/* View: CBO_PTOVTA_FDP01 */
CREATE OR ALTER VIEW CBO_PTOVTA_FDP01(
    ID_SOCSYST10,
    SOCSYST10_CODIGO,
    SOCSYST10_DESCRIPCION)
AS
select
CBO_SOCSYST10_FDP01.id_socsyst10,
CBO_SOCSYST10_FDP01.socsyst10_codigo,
iif(CBO_SOCSYST10_FDP01.socsyst10_codigo = '99', '(99) Ventas a Crédito', CBO_SOCSYST10_FDP01.socsyst10_descripcion)
from CBO_SOCSYST10_FDP01
where not (CBO_SOCSYST10_FDP01.socsyst10_codigo >= '12' and  CBO_SOCSYST10_FDP01.socsyst10_codigo <= '27')
;



/* View: CBO_SICEGRE01 */
CREATE OR ALTER VIEW CBO_SICEGRE01(
    RELA_SICEGRE01,
    ID_SOCUSUA30,
    RELA_SOCMAIN01,
    ENTIDAD)
AS
SELECT
sicegre01_cab_proveedores.id_sicegre01,
sicegre01_cab_proveedores.rela_socusua30,
sicegre01_cab_proveedores.rela_socmain01,

(SELECT cbo_socusua30.entidad
 FROM cbo_socusua30(sicegre01_cab_proveedores.rela_socusua30)
)
FROM sicegre01_cab_proveedores
;



/* View: CBO_SICEGRE01_ID */
CREATE OR ALTER VIEW CBO_SICEGRE01_ID(
    ID_SICEGRE01,
