/* View: CBO_SICINGR01_SICINGR70 */
CREATE OR ALTER VIEW CBO_SICINGR01_SICINGR70(
    ID_SICINGR01,
    RELA_SOCUSUA30,
    RELA_SOCMAIN01,
    ENTIDAD,
    RFC,
    TIPO,
    FOLIO)
AS
SELECT
sicingr01_cab_clientes.id_sicingr01,
sicingr01_cab_clientes.rela_socusua30,
sicingr01_cab_clientes.rela_socmain01,

(SELECT cbo_socusua30.entidad
 FROM cbo_socusua30(sicingr01_cab_clientes.rela_socusua30)
),

(SELECT cbo_socusua30.rfc
 FROM cbo_socusua30(sicingr01_cab_clientes.rela_socusua30)
),

(SELECT cbo_socusua30.tipo
 FROM cbo_socusua30(sicingr01_cab_clientes.rela_socusua30)
),

(SELECT first 1 sicingr70_cab_facturacion.sicingr70_docnro
 FROM sicingr70_cab_facturacion
 WHERE sicingr70_cab_facturacion.rela_sicingr01 = sicingr01_cab_clientes.id_sicingr01
 ORDER BY sicingr70_cab_facturacion.sicingr70_docnro DESC
)

FROM sicingr01_cab_clientes
;



