    POLIZA,
    RELA_SOCUSUA30)
AS
select
SICINGR51_CAB_BANCOS.rela_sicingr01,
SICINGR51_CAB_BANCOS.rela_sicegre01,
SICINGR51_CAB_BANCOS.rela_socmain01,
SICINGR51_CAB_BANCOS.id_sicingr51,
SICINGR51_CAB_BANCOS.sicingr51_importe,
SICINGR51_CAB_BANCOS.sicingr51_fecha,
SICINGR51_CAB_BANCOS.sicingr51_referencia,
socsyst10_det_entradas.socsyst10_descripcion,
socsyst10_det_entradas.socsyst10_valor01,
socmain05_det_bancos.socmain05_cuenta,
( select siccont10_cab_polizas.siccont10_docnro
  from sicingr50_det_ctacte
  inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
  where sicingr50_det_ctacte.rela_sicingr51 = SICINGR51_CAB_BANCOS.id_sicingr51
),
( select sicegre01_cab_proveedores.rela_socusua30
  from sicegre01_cab_proveedores
  where sicegre01_cab_proveedores.id_sicegre01 = SICINGR51_CAB_BANCOS.rela_sicegre01
)
from SICINGR51_CAB_BANCOS
inner join socmain05_det_bancos on (socmain05_det_bancos.id_socmain05 = SICINGR51_CAB_BANCOS.rela_socmain05)
inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ban01)
where SICINGR51_CAB_BANCOS.rela_sicingr01 is not null
and SICINGR51_CAB_BANCOS.rela_sicegre01 is not null
and not exists ( select first 1 sicpago50_cab_factoraje.id_sicpago50
                 from sicpago50_cab_factoraje
                 where sicpago50_cab_factoraje.rela_sicingr51 = SICINGR51_CAB_BANCOS.id_sicingr51
                )
;



/* View: CBO_SICINGR51_SICPAGO70_VIEW */
CREATE OR ALTER VIEW CBO_SICINGR51_SICPAGO70_VIEW(
    RELA_SICINGR01,
    RELA_SICEGRE01,
