;



/* View: CBO_SOCSYST10_CTM01 */
CREATE OR ALTER VIEW CBO_SOCSYST10_CTM01(
    ID_SOCSYST10,
    SOCSYST10_CODIGO,
    SOCSYST10_DESCRIPCION)
AS
SELECT
    SOCSYST10_DET_REMOTO.ID_SOCSYST10,
    SOCSYST10_DET_REMOTO.SOCSYST10_CODIGO,
    SOCSYST10_DET_REMOTO.SOCSYST10_DESCRIPCION
FROM SOCSYST10_DET_REMOTO
INNER JOIN SOCSYST09_CAB_ENTRADAS ON (SOCSYST10_DET_REMOTO.RELA_SOCSYST09 = SOCSYST09_CAB_ENTRADAS.ID_SOCSYST09)
