;



/* View: CBO_SICINGR73_SICXMLS41_WEB */
CREATE OR ALTER VIEW CBO_SICINGR73_SICXMLS41_WEB(
    RELA_SICINGR01,
    ID_SICXMLS41,
    SICINGR74_UUID,
    SICINGR74_UUID_IMPORTE,
    SICINGR74_UUID_FECHA,
    SICINGR70_DOCNRO,
    TIPOCOMPROBANTE,
    MONEDA)
AS
SELECT
sicingr70_cab_facturacion.rela_sicingr01,
sicxmls41_det_migracion.id_sicxmls41,
sicingr74_dep_cfdis.sicingr74_uuid,
sicingr74_dep_cfdis.sicingr74_uuid_importe,
sicingr74_dep_cfdis.sicingr74_uuid_fecha,
sicingr70_cab_facturacion.sicingr70_docnro,
ctp01.socsyst10_descripcion,
ctm01.socsyst10_descripcion
FROM sicingr70_cab_facturacion
INNER JOIN sicingr74_dep_cfdis ON (sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
INNER JOIN cbo_socsyst10_tcp01 ctp01 ON  ( ctp01.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01 )
INNER JOIN cbo_socsyst10_ctm01 ctm01 ON ( ctm01.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01 )
inner join sicxmls41_det_migracion on (sicxmls41_det_migracion.id_sicxmls41 = sicingr74_dep_cfdis.rela_sicxmls41)
;



/* View: CBO_SICINGR90_SICXMLS02 */
CREATE OR ALTER VIEW CBO_SICINGR90_SICXMLS02(
    RELA_SICXMLS01,
    RELA_SOCMAIN01,
    ID_SICXMLS02,
    SICCONT02_CODIGO_EXT,
    SICCONT02_DESCRIPCION,
    SICCONT02_CODAGRUP,
    SOCSYST10_DESCRIPCION,
    SICXMLS02_IMPUESTO,
    TIPO,
    TASA)
AS
select
sicxmls01_cab_parametros.id_sicxmls01,
sicxmls01_cab_parametros.rela_socmain01,
sicxmls02_det_impuestos.id_sicxmls02,
siccont02_arb_planctas.siccont02_codigo_ext,
siccont02_arb_planctas.siccont02_descripcion,
siccont02_arb_planctas.siccont02_codagrup,
socsyst10_det_entradas.socsyst10_descripcion,
sicxmls02_det_impuestos.sicxmls02_impuesto,
iif(sicxmls02_det_impuestos.sicxmls02_retenido = 1, 'Retenido', 'Trasladado'),
sicxmls02_det_impuestos.sicxmls02_tasa
from sicxmls01_cab_parametros
inner join sicxmls02_det_impuestos on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls02_det_impuestos.rela_sicxmls01 )
inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = sicxmls02_det_impuestos.rela_siccont02_ctracta )
inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicxmls02_det_impuestos.rela_socsyst10_tct01 )
where sicxmls02_det_impuestos.rela_siccont02 is not null
  and sicxmls02_det_impuestos.rela_siccont02_ctracta is not null
  and sicxmls02_det_impuestos.sicxmls02_tipo = 'I'
;



/* View: CBO_SICINGR95 */
CREATE OR ALTER VIEW CBO_SICINGR95(
    RELA_SOCMAIN01,
    ID_SICINGR95,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION,
    SICINGR95_PREDIAL,
    SICINGR95_IMPORTE,
    UNIDAD_MEDIDA,
    SAT_SERVPROD,
    IVA,
    SICINGR98_IMPORTE,
    SICINGR95_FRACCION,
    SAT_CODE)
AS
SELECT
sicxmls01_cab_parametros.rela_socmain01,
sicingr95_cab_conceptos.id_sicingr95,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion,
sicingr95_cab_conceptos.sicingr95_predial,
sicingr95_cab_conceptos.sicingr95_importe,
'(' || cum01.socsyst10_codigo || ') ' || cum01.socsyst10_descripcion,
'(' || cpo01.socsyst10_codigo || ') ' || cpo01.socsyst10_descripcion,
iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Exento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'IVA 0%', 'IVA')),
( select
  sum(sicingr98_det_importes.sicingr98_importe) / count(sicingr98_det_importes.id_sicingr98)
  from sicingr98_det_importes
  inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01 )
  where sicingr98_det_importes.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95
  and socsyst10_det_entradas.socsyst10_codigo = 'CONCEP-XMARGEN'
),
sicingr95_cab_conceptos.sicingr95_fraccion,
cpo01.socsyst10_codigo
from sicingr95_cab_conceptos
inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
;



/* View: CBO_SICINGR95_AUTOMOTORES */
CREATE OR ALTER VIEW CBO_SICINGR95_AUTOMOTORES(
    RELA_SOCMAIN01,
    ID_SICINGR95,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION,
    SICINGR95_PREDIAL,
    SICINGR95_IMPORTE,
    UNIDAD_MEDIDA,
    SAT_SERVPROD,
    IVA)
AS
SELECT
sicxmls01_cab_parametros.rela_socmain01,
sicingr95_cab_conceptos.id_sicingr95,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion,
sicingr95_cab_conceptos.sicingr95_predial,
sicingr95_cab_conceptos.sicingr95_importe,
'(' || cum01.socsyst10_codigo || ') ' || cum01.socsyst10_descripcion,
'(' || cpo01.socsyst10_codigo || ') ' || cpo01.socsyst10_descripcion,
iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Exento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'IVA 0%', 'IVA'))
from sicingr95_cab_conceptos
inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
where exists ( select first 1 sicingr97_det_clasificacion.id_sicingr97
               from sicingr97_det_clasificacion
               inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
               where sicingr97_det_clasificacion.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95
               and socsyst10_det_entradas.socsyst10_codigo = 'AUTO'
              )
;



/* View: QRY_SICXMLS42_MAX_IMPORTE */
CREATE OR ALTER VIEW QRY_SICXMLS42_MAX_IMPORTE(
    RELA_SICXMLS04,
    ID_SICXMLS42,
    IMPORTE)
AS
select
sicxmls42_det_conceptos.rela_sicxmls04,
max(sicxmls42_det_conceptos.id_sicxmls42),
(select importe.sicxmls42_importe
 from sicxmls42_det_conceptos importe
 where importe.id_sicxmls42 = max(sicxmls42_det_conceptos.id_sicxmls42)
)
from sicxmls42_det_conceptos
group by sicxmls42_det_conceptos.rela_sicxmls04
;



/* View: CBO_SICINGR95_SICXMLS04 */
CREATE OR ALTER VIEW CBO_SICINGR95_SICXMLS04(
    RELA_SICXMLS01,
    RELA_SOCMAIN01,
    ID_SICXMLS04,
    SICCONT02_CODIGO_EXT,
    SICCONT02_DESCRIPCION,
    SICCONT02_CODAGRUP,
    SOCSYST10_DESCRIPCION,
    SICXMLS04_CONCEPTO,
    TIPO,
    DEDUCIBLE,
    IMPORTE,
    ASIGNADO)
AS
select
sicxmls01_cab_parametros.id_sicxmls01,
sicxmls01_cab_parametros.rela_socmain01,
sicxmls04_det_conceptos.id_sicxmls04,
siccont02_arb_planctas.siccont02_codigo_ext,
siccont02_arb_planctas.siccont02_descripcion,
siccont02_arb_planctas.siccont02_codagrup,
socsyst10_det_entradas.socsyst10_descripcion,
sicxmls04_det_conceptos.sicxmls04_concepto,
iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Excento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'Iva 0%', 'Iva')),
iif(sicxmls04_det_conceptos.sicxmls04_deducible = 0, 'No', 'Si'),
( select QRY_SICXMLS42_MAX_IMPORTE.importe
  from QRY_SICXMLS42_MAX_IMPORTE
  where QRY_SICXMLS42_MAX_IMPORTE.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04
),
iif( ( select sicingr95_cab_conceptos.id_sicingr95
       from sicingr95_cab_conceptos
       where sicingr95_cab_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01
       and sicingr95_cab_conceptos.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04 ) is null, 'No', 'Si')

from sicxmls01_cab_parametros
inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01 )
inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02 )
inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicxmls04_det_conceptos.rela_socsyst10_tct01 )
where sicxmls04_det_conceptos.rela_siccont02 is not null
  and (sicxmls04_det_conceptos.sicxmls04_tipo = 'I'
  and socsyst10_det_entradas.socsyst10_codigo like 'CLIENTE%')
  or (sicxmls04_det_conceptos.sicxmls04_tipo = 'E'
  and socsyst10_det_entradas.socsyst10_codigo like 'PROVE%')

order by siccont02_arb_planctas.siccont02_codigo_ext
;



/* View: CBO_SICINGR95_SINKIT */
CREATE OR ALTER VIEW CBO_SICINGR95_SINKIT(
    RELA_SOCMAIN01,
    ID_SICINGR95,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION)
AS
SELECT
sicxmls01_cab_parametros.rela_socmain01,
sicingr95_cab_conceptos.id_sicingr95,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion
from sicingr95_cab_conceptos
inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
where not exists(
    select first 1 sicingr99_det_kits.id_sicingr99
    from sicingr99_det_kits
    where sicingr99_det_kits.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95
)
ORDER BY sicingr95_cab_conceptos.sicingr95_descripcion
;



/* View: CBO_SICNOMI01 */
CREATE OR ALTER VIEW CBO_SICNOMI01(
    RELA_SICNOMI01,
    ID_SOCUSUA30,
    RELA_SOCMAIN01,
    ENTIDAD)
AS
SELECT
sicnomi01_cab_empleados.id_sicnomi01,
sicnomi01_cab_empleados.rela_socusua30,
sicnomi01_cab_empleados.rela_socmain01,

(SELECT cbo_socusua30.entidad
 FROM cbo_socusua30(sicnomi01_cab_empleados.rela_socusua30)
)
FROM sicnomi01_cab_empleados
;



/* View: CBO_SICNOMI01_CURP */
CREATE OR ALTER VIEW CBO_SICNOMI01_CURP(
    ID_SICNOMI01,
    RELA_SOCUSUA30,
    RELA_SOCMAIN01,
    ENTIDAD,
    CURP,
    RFC,
    MAX_FECHA)
AS
SELECT
sicnomi01_cab_empleados.id_sicnomi01,
sicnomi01_cab_empleados.rela_socusua30,
sicnomi01_cab_empleados.rela_socmain01,

(SELECT cbo_socusua30.entidad
 FROM cbo_socusua30(sicnomi01_cab_empleados.rela_socusua30)
),

(select first 1 socusua32_det_documentos.socusua32_documento
 from socusua32_det_documentos
 inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
 where socusua32_det_documentos.rela_socusua30 = sicnomi01_cab_empleados.rela_socusua30
 and socusua32_det_documentos.socusua32_principal = 1
 and socsyst10_det_entradas.socsyst10_codigo = 'CURP'),

(select first 1socusua32_det_documentos.socusua32_documento
 from socusua32_det_documentos
 inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
 where socusua32_det_documentos.rela_socusua30 = sicnomi01_cab_empleados.rela_socusua30
 and socusua32_det_documentos.socusua32_principal = 1
 and socsyst10_det_entradas.socsyst10_codigo = 'RFC'),

(select max(sicnomi70_cab_nomina.sicnomi70_fecha)
 from sicnomi70_cab_nomina
 where sicnomi70_cab_nomina.rela_socmain01 = sicnomi01_cab_empleados.rela_socmain01
 and sicnomi70_cab_nomina.rela_sicnomi01 = sicnomi01_cab_empleados.id_sicnomi01
)

FROM sicnomi01_cab_empleados
;



/* View: SMX$DB_TABLASVIRTUALES */
CREATE OR ALTER VIEW SMX$DB_TABLASVIRTUALES(
    ID_SOCSYST09,
    ID_SOCSYST10,
    SOCSYST09_CODIGO,
    SOCSYST09_DESCIPCION,
    SOCSYST10_CODIGO,
    SOCSYST10_DESCRIPCION,
    SOCSYST10_GRUPO,
    SOCSYST10_VALOR01,
    SOCSYST10_HASHTAG_1)
AS
select
socsyst09_cab_entradas.id_socsyst09,
socsyst10_det_entradas.id_socsyst10,
socsyst09_cab_entradas.socsyst09_codigo,
socsyst09_cab_entradas.socsyst09_descipcion,
socsyst10_det_entradas.socsyst10_codigo,
socsyst10_det_entradas.socsyst10_descripcion,
socsyst10_det_entradas.socsyst10_grupo,
socsyst10_det_entradas.socsyst10_valor01,
socsyst10_det_entradas.socsyst10_hashtag_1
