/* View: CBO_SICNOMI01_ID */
CREATE OR ALTER VIEW CBO_SICNOMI01_ID(
    ID_SICNOMI01,
    RELA_SOCUSUA30,
    RELA_SOCMAIN01,
    ENTIDAD,
    RFC,
    TIPO,
    CURP,
    SICNOMI01_FAPL)
AS
SELECT
sicnomi01_cab_empleados.id_sicnomi01,
sicnomi01_cab_empleados.rela_socusua30,
sicnomi01_cab_empleados.rela_socmain01,

(SELECT cbo_socusua30.entidad
 FROM cbo_socusua30(sicnomi01_cab_empleados.rela_socusua30)
),


(SELECT cbo_socusua30.rfc
 FROM cbo_socusua30(sicnomi01_cab_empleados.rela_socusua30)
),

(SELECT cbo_socusua30.tipo
 FROM cbo_socusua30(sicnomi01_cab_empleados.rela_socusua30)
),
(
 select first 1 socusua32_det_documentos.socusua32_documento
 FROM socusua32_det_documentos
 INNER JOIN cbo_socsyst10_td001 ON (socusua32_det_documentos.rela_socsyst10_td001 = cbo_socsyst10_td001.id_socsyst10)
 WHERE socusua32_det_documentos.rela_socusua30 = sicnomi01_cab_empleados.rela_socusua30
 AND cbo_socsyst10_td001.socsyst10_codigo = 'CURP'
 order by socusua32_det_documentos.id_socusua32 desc
),
sicnomi01_cab_empleados.sicnomi01_fapl

FROM sicnomi01_cab_empleados
;
;



/* View: CBO_SICNOMI01_SOCUSUA01 */
