/* View: CBO_SOCMAIN01_ALL */
CREATE OR ALTER VIEW CBO_SOCMAIN01_ALL(
    ID_SOCMAIN01,
    SOCMAIN01_NOMCOMERCIAL,
    SOCMAIN01_PROPIETARIA,
    SOCMAIN01_SATUSER,
    SOCMAIN01_SATPASS,
    RFC,
    SOCMAIN01_TEST,
    REGIMEN_FISCAL)
AS
Select
socmain01_cab_empresas.id_socmain01,
socmain01_cab_empresas.socmain01_nomcomercial,
socmain01_cab_empresas.socmain01_propietaria,
socmain01_cab_empresas.socmain01_satuser,
socmain01_cab_empresas.socmain01_satpass,
(
    SELECT FIRST 1 socusua32_det_documentos.socusua32_documento
    FROM socusua30_cab_entidades
    INNER JOIN socusua32_det_documentos ON (socusua32_det_documentos.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
    INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
    WHERE socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30
    AND socsyst10_det_entradas.socsyst10_codigo = 'RFC'
),
socmain01_cab_empresas.socmain01_test,
cbo_socsyst10_sat01.socsyst10_codigo
from socmain01_cab_empresas
inner join cbo_socsyst10_sat01 on (cbo_socsyst10_sat01.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01)
;



/* View: CBO_SOCMAIN01 */
CREATE OR ALTER VIEW CBO_SOCMAIN01(
    RELA_SICXMLS01,
    ID_SOCMAIN01,
    SOCMAIN01_NOMCOMERCIAL,
    SOCMAIN01_SATUSER,
    SOCMAIN01_SATPASS,
    RFC,
    SOCMAIN01_TEST,
    REGIMEN_FISCAL)
AS
Select
sicxmls01_cab_parametros.id_sicxmls01,
CBO_SOCMAIN01_ALL.id_socmain01,
CBO_SOCMAIN01_ALL.socmain01_nomcomercial,
CBO_SOCMAIN01_ALL.socmain01_satuser,
CBO_SOCMAIN01_ALL.socmain01_satpass,
CBO_SOCMAIN01_ALL.rfc,
CBO_SOCMAIN01_ALL.socmain01_test,
CBO_SOCMAIN01_ALL.regimen_fiscal
from CBO_SOCMAIN01_ALL
inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.rela_socmain01 = CBO_SOCMAIN01_ALL.id_socmain01)
where CBO_SOCMAIN01_ALL.rfc is not null and trim(CBO_SOCMAIN01_ALL.rfc) <> ''
;



/* View: CBO_SOCMAIN01_CFDI */
CREATE OR ALTER VIEW CBO_SOCMAIN01_CFDI(
    ID_SOCMAIN01,
    SOCMAIN01_NOMCOMERCIAL,
    SOCMAIN01_SATUSER,
    SOCMAIN01_SATPASS,
    RFC,
    CODPOSTAL)
AS
Select
CBO_SOCMAIN01_ALL.id_socmain01,
CBO_SOCMAIN01_ALL.socmain01_nomcomercial,
CBO_SOCMAIN01_ALL.socmain01_satuser,
CBO_SOCMAIN01_ALL.socmain01_satpass,
CBO_SOCMAIN01_ALL.rfc,
( SELECT FIRST 1
  socusua36_det_domicilios.socusua36_codpostal
  FROM socusua36_det_domicilios
  INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
  INNER JOIN socusua30_cab_entidades ON (  socusua30_cab_entidades.id_socusua30 = socusua36_det_domicilios.rela_socusua30 )
  INNER JOIN socmain01_cab_empresas ON ( socmain01_cab_empresas.rela_socusua30 = socusua30_cab_entidades.id_socusua30 )
  WHERE socmain01_cab_empresas.id_socmain01 = CBO_SOCMAIN01_ALL.id_socmain01
  AND socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
)
from CBO_SOCMAIN01_ALL
where (
           (CBO_SOCMAIN01_ALL.rfc is not null and trim(CBO_SOCMAIN01_ALL.rfc) <> '')
    and    (CBO_SOCMAIN01_ALL.socmain01_satuser is not null and trim(CBO_SOCMAIN01_ALL.socmain01_satuser) <> '')
    and    (CBO_SOCMAIN01_ALL.socmain01_satpass is not null and trim(CBO_SOCMAIN01_ALL.socmain01_satpass) <> '')
)
;



/* View: CBO_SOCMAIN01_CTLCTAS */
CREATE OR ALTER VIEW CBO_SOCMAIN01_CTLCTAS(
    ID_SOCMAIN01,
    SOCMAIN01_NOMCOMERCIAL,
    RFC)
AS
Select
CBO_SOCMAIN01_ALL.id_socmain01,
CBO_SOCMAIN01_ALL.socmain01_nomcomercial,
CBO_SOCMAIN01_ALL.rfc
from CBO_SOCMAIN01_ALL
where CBO_SOCMAIN01_ALL.rfc is not null
and trim(CBO_SOCMAIN01_ALL.rfc) <> ''
and CBO_SOCMAIN01_ALL.socmain01_propietaria = 1
and exists ( select siccont01_cab_planctas.id_siccont01
             from siccont01_cab_planctas
             where siccont01_cab_planctas.rela_socmain01 = CBO_SOCMAIN01_ALL.id_socmain01
            )
;



