    RELA_SOCMAIN01,
    RELA_PYMVENT10,
    ID_SOCSYST10,
    SOCSYST10_CODIGO,
    SOCSYST10_DESCRIPCION,
    SOCSYST10_GRUPO,
    PYMVENT10_PORCENTAJE)
AS
select
pymvent10_cab_listaprecios.rela_socmain01,
pymvent10_cab_listaprecios.id_pymvent10,
smx$db_tablasvirtuales.id_socsyst10,
smx$db_tablasvirtuales.socsyst10_codigo,
trim(smx$db_tablasvirtuales.socsyst10_descripcion) || ' ' || cast(pymvent10_cab_listaprecios.pymvent10_porcentaje as numeric(8,2)) || '%',
smx$db_tablasvirtuales.socsyst10_grupo,
pymvent10_cab_listaprecios.pymvent10_porcentaje
from smx$db_tablasvirtuales
inner join pymvent10_cab_listaprecios on (pymvent10_cab_listaprecios.rela_socsyst10_lpr01 = smx$db_tablasvirtuales.id_socsyst10)
where smx$db_tablasvirtuales.socsyst09_codigo = 'LPR01'
and (pymvent10_cab_listaprecios.pymvent10_inactivo is null or pymvent10_cab_listaprecios.pymvent10_inactivo = 0)
;



