/* View: CBO_SOCSYST12 */
CREATE OR ALTER VIEW CBO_SOCSYST12(
    RELA_SOCSYST10,
    SOCSYST10_CODIGO,
    RELA_SOCSYST10_CDP01,
    ID_SOCSYST12,
    SOCSYST12_CODIGO,
    SOCSYST12_DESCRIPCION,
    SOCSYST12_CODAGR,
    SOCSYST12_HASHTAG_1,
    SOCSYST12_HASHTAG_2)
AS
SELECT
socsyst10_det_entradas.id_socsyst10,
socsyst10_det_entradas.socsyst10_codigo,
socsyst12_det_cla.rela_socsyst10,
socsyst12_det_cla.id_socsyst12,
socsyst12_det_cla.socsyst12_codigo,
socsyst12_det_cla.socsyst12_descripcion,
socsyst12_det_cla.socsyst12_codagr,
socsyst12_det_cla.socsyst12_hashtag_1,
socsyst12_det_cla.socsyst12_hashtag_2
FROM socsyst12_det_cla
inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socsyst12_det_cla.rela_socsyst10 )
order by socsyst12_det_cla.rela_socsyst10, socsyst12_det_cla.socsyst12_codigo
;



/* View: CBO_SOCUSUA02 */
CREATE OR ALTER VIEW CBO_SOCUSUA02(
    RELA_SOCMAIN21,
    RELA_SOCSYST10_CA001,
    ID_SOCUSUA02,
    SOCMAIN21_DESCRIPCION,
    SOCSYST10_DESCRIPCION)
AS
select distinct
SOCUSUA02_DET_ORGANIZACION.rela_socmain21,
SOCUSUA02_DET_ORGANIZACION.rela_socsyst10_ca001,
SOCUSUA02_DET_ORGANIZACION.id_socusua02,
socmain21_arb_organizacion.socmain21_descripcion,
socsyst10_det_entradas.socsyst10_descripcion
from SOCUSUA02_DET_ORGANIZACION
INNER join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = SOCUSUA02_DET_ORGANIZACION.rela_socmain21)
INNER JOIN socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SOCUSUA02_DET_ORGANIZACION.rela_socsyst10_ca001)
order by ID_SOCUSUA02
;



/* View: CBO_SOCUSUA30_ALL */
CREATE OR ALTER VIEW CBO_SOCUSUA30_ALL(
    ID_SOCUSUA30,
    TIPO,
    ENTIDAD)
AS
select
    socusua30_cab_entidades.id_socusua30,
    socsyst10_det_entradas.socsyst10_codigo,
    CAST(COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_pat), '') || ' ' ||
    COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_mat), '') || ', ' ||
    COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc), '') AS VARCHAR(1200))
    FROM socusua30_cab_entidades
    INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)
    where socsyst10_det_entradas.socsyst10_codigo = 'FISICO'

    
    UNION ALL
    
    select
    socusua30_cab_entidades.id_socusua30,
    socsyst10_det_entradas.socsyst10_codigo,
    CAST(COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc), '') AS VARCHAR(1200))
    FROM socusua30_cab_entidades
    INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)
    where socsyst10_det_entradas.socsyst10_codigo = 'MORAL'
;



/* View: CBO_SOCUSUA30_PFISICAS */
CREATE OR ALTER VIEW CBO_SOCUSUA30_PFISICAS(
    ID_SOCUSUA30,
    SOCUSUA30_APELLIDO_PAT,
    SOCUSUA30_APELLIDO_MAT,
    SOCUSUA30_NOMBRE_RAZSOC,
    SOCUSUA30_FNAC_CONST,
    SOCUSUA30_FAPL,
    BUSQUEDA)
AS
SELECT
SOCUSUA30_CAB_ENTIDADES.id_socusua30,
COALESCE(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_pat, ''),
COALESCE(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_mat, ''),
COALESCE(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc, ''),
SOCUSUA30_CAB_ENTIDADES.socusua30_fnac_const,
SOCUSUA30_CAB_ENTIDADES.socusua30_fapl,
COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_pat), '') || ' ' ||
COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_mat), '') || ', ' ||
COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc), '')
FROM SOCUSUA30_CAB_ENTIDADES
inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SOCUSUA30_CAB_ENTIDADES.rela_socsyst10)
WHERE socsyst10_det_entradas.socsyst10_codigo = 'FISICO'
;



/* View: CBO_SOCUSUA30_PFISICAS_EMP */
CREATE OR ALTER VIEW CBO_SOCUSUA30_PFISICAS_EMP(
    ID_SOCUSUA30,
    SOCUSUA30_APELLIDO_PAT,
    SOCUSUA30_APELLIDO_MAT,
    SOCUSUA30_NOMBRE_RAZSOC,
    SOCUSUA30_FNAC_CONST,
    SOCUSUA30_FAPL,
    BUSQUEDA)
AS
SELECT
SOCUSUA30_CAB_ENTIDADES.id_socusua30,
COALESCE(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_pat, ''),
COALESCE(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_mat, ''),
COALESCE(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc, ''),
SOCUSUA30_CAB_ENTIDADES.socusua30_fnac_const,
SOCUSUA30_CAB_ENTIDADES.socusua30_fapl,
COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_pat), '') || ' ' ||
COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_mat), '') || ', ' ||
COALESCE(TRIM(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc), '')
FROM SOCUSUA30_CAB_ENTIDADES
inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SOCUSUA30_CAB_ENTIDADES.rela_socsyst10)
WHERE socsyst10_det_entradas.socsyst10_codigo = 'FISICO'
AND   EXISTS (SELECT FIRST 1 socusua32_det_documentos.id_socusua32
              FROM socusua32_det_documentos
              WHERE socusua32_det_documentos.rela_socusua30 = SOCUSUA30_CAB_ENTIDADES.id_socusua30)
;



