BAN.socsyst10_descripcion,
MON.socsyst10_descripcion,
sicingr02_det_bancos.rela_sicingr01,
SICINGR02_DET_BANCOS.rela_socsyst10_ban01,
SICINGR02_DET_BANCOS.rela_socsyst10_ctm01,
SICINGR02_DET_BANCOS.id_SICINGR02,
SICINGR02_DET_BANCOS.SICINGR02_cuenta,
SICINGR02_DET_BANCOS.SICINGR02_fapl,
trim(BAN.socsyst10_descripcion) || ' ' || trim(MON.socsyst10_descripcion) || ' Cuenta : ' || trim(SICINGR02_cuenta),
RELA_SOCSYST10_BAN01 || RELA_SOCSYST10_CTM01 || trim(SICINGR02_CUENTA)

from SICINGR02_DET_BANCOS

inner join socsyst10_det_entradas BAN ON ( BAN.id_socsyst10 = SICINGR02_DET_BANCOS.rela_socsyst10_ban01)
inner join socsyst10_det_remoto MON ON ( MON.id_socsyst10 = SICINGR02_DET_BANCOS.rela_socsyst10_ctm01)
;



