/* View: GRD_ADUCTAG02 */
CREATE OR ALTER VIEW GRD_ADUCTAG02(
    RELA_SICINGR85,
    RELA_SOCMAIN05,
    RELA_SICINGR02,
    RELA_SOCSYST10_MDP01,
    ID_ADUCTAG02,
    ADUCTAG02_REFERENCIA,
    ADUCTAG02_IMPORTE,
    ADUCTAG02_FECHA,
    ADUCTAG02_COTIZA,
    ADUCTAG02_FAPL,
    BANCO,
    MONEDA,
    CUENTA,
    BANCO_CLIENTE,
    MONEDA_CLIENTE,
    CUENTA_CLIENTE,
    MODODEPAGO)
AS
select 
    aductag02_det_anticipos.rela_sicingr85,
    aductag02_det_anticipos.rela_socmain05,
    aductag02_det_anticipos.rela_sicingr02,
    aductag02_det_anticipos.rela_socsyst10_mdp01,
    aductag02_det_anticipos.id_aductag02,
    aductag02_det_anticipos.aductag02_referencia,
    aductag02_det_anticipos.aductag02_importe,
    aductag02_det_anticipos.aductag02_fecha,
    aductag02_det_anticipos.aductag02_cotiza,
    aductag02_det_anticipos.aductag02_fapl,
    grd_socmain05.banco,
    grd_socmain05.moneda,
    grd_socmain05.socmain05_cuenta,
    grd_sicingr02.banco,
    grd_sicingr02.moneda,
    grd_sicingr02.sicingr02_cuenta,
    cbo_socsyst10_mdp01.socsyst10_descripcion
from cbo_socsyst10_mdp01
   inner join aductag02_det_anticipos on (cbo_socsyst10_mdp01.id_socsyst10 = aductag02_det_anticipos.rela_socsyst10_mdp01)
   inner join grd_socmain05 on (aductag02_det_anticipos.rela_socmain05 = grd_socmain05.id_socmain05)
   inner join grd_sicingr02 on (aductag02_det_anticipos.rela_sicingr02 = grd_sicingr02.id_sicingr02)
;
;



