/* View: GRD_PYMALMA02_VIEW */
CREATE OR ALTER VIEW GRD_PYMALMA02_VIEW(
    RELA_SOCMAIN01,
    RELA_SOCMAIN21,
    RELA_PYMALMA01,
    RELA_PYMALMA01_TRANSF,
    RELA_SICINGR95,
    RELA_SOCSYST10_STK01,
    RELA_SICEGRE81,
    ID_PYMALMA02,
    PYMALMA02_CANTIDAD,
    PYMALMA02_FAPL,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION,
    SOCSYST10_DESCRIPCION,
    SALDO,
    TRANSFERENCIA,
    PYMALMA20_MODELO,
    PYMALMA20_TALLA,
    PYMALMA20_COLOR,
    PYMALMA20_LOTE_DESDE,
    PYMALMA20_LOTE_HASTA,
    PYMALMA20_VENCIMIENTO,
    PYMALMA20_SERIE_DESDE,
    PYMALMA20_SERIE_HASTA,
    BUSCA)
AS
select
pymalma01_cab_stock.rela_socmain01,
pymalma01_cab_stock.rela_socmain21,
pymalma02_det_stock.rela_pymalma01,
pymalma02_det_stock.rela_pymalma01_transf,
pymalma02_det_stock.rela_sicingr95,
pymalma02_det_stock.rela_socsyst10_stk01,
null,
pymalma02_det_stock.id_pymalma02,
pymalma02_det_stock.pymalma02_cantidad,
pymalma02_det_stock.pymalma02_fapl,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion,
socsyst10_det_entradas.socsyst10_descripcion,
cast(0.00 as double precision),
cast('' as varchar(400)),
pymalma20_dep_mtclvs.pymalma20_modelo,
pymalma20_dep_mtclvs.pymalma20_talla,
pymalma20_dep_mtclvs.pymalma20_color,
pymalma20_dep_mtclvs.pymalma20_lote_desde,
pymalma20_dep_mtclvs.pymalma20_lote_hasta,
pymalma20_dep_mtclvs.pymalma20_vencimiento,
pymalma20_dep_mtclvs.pymalma20_serie_desde,
pymalma20_dep_mtclvs.pymalma20_serie_hasta,
(sicingr95_codigo  || iif(pymalma20_modelo is null, '', pymalma20_modelo) ||
iif(pymalma20_talla is null, '', pymalma20_talla) || iif(pymalma20_color is null, '', pymalma20_color) ||
iif(pymalma20_lote_desde is null, '', pymalma20_lote_desde) || iif(pymalma20_lote_hasta is null, '', pymalma20_lote_hasta) ||
iif(pymalma20_vencimiento is null, '', cast(pymalma20_vencimiento as varchar (10))) ||
iif(pymalma20_serie_desde is null, '', pymalma20_serie_desde) || iif(pymalma20_serie_hasta is null, '', pymalma20_serie_hasta))
FROM pymalma02_det_stock
inner join pymalma01_cab_stock on (pymalma01_cab_stock.id_pymalma01 = pymalma02_det_stock.rela_pymalma01)
inner join sicingr95_cab_conceptos on (sicingr95_cab_conceptos.id_sicingr95 = pymalma02_det_stock.rela_sicingr95)
inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = pymalma02_det_stock.rela_socsyst10_stk01)
inner join pymalma20_dep_mtclvs on (pymalma20_dep_mtclvs.rela_pymalma02 = pymalma02_det_stock.id_pymalma02)
;



