/* View: GRD_PYMVENT61 */
CREATE OR ALTER VIEW GRD_PYMVENT61(
    SOCSYST10_CODIGO,
    SOCSYST10_DESCRIPCION,
    RELA_PYMVENT60,
    RELA_SOCSYST10_FDP01,
    ID_PYMVENT61,
    PYMVENT61_REFERENCIA,
    PYMVENT61_COMPROBANTE,
    PYMVENT61_VALOR,
    PYMVENT61_FAPL,
    ES_FACTURADO,
    PYMVENT62_CANCELADO)
AS
select
socsyst10_det_remoto.socsyst10_codigo,
'(' || socsyst10_det_remoto.socsyst10_codigo || ') ' || socsyst10_det_remoto.socsyst10_descripcion,
pymvent61_det_cobro.rela_pymvent60,
pymvent61_det_cobro.rela_socsyst10_fdp01,
pymvent61_det_cobro.id_pymvent61,
pymvent61_det_cobro.pymvent61_referencia,
pymvent61_det_cobro.pymvent61_comprobante,
pymvent61_det_cobro.pymvent61_valor,
pymvent61_det_cobro.pymvent61_fapl,
( select pymvent62_dep_facturacion.id_pymvent62
  from pymvent62_dep_facturacion
  where pymvent62_dep_facturacion.rela_pymvent60 = pymvent61_det_cobro.rela_pymvent60
  and exists (select sicingr74_dep_cfdis.id_sicingr74
              from sicingr74_dep_cfdis
              where sicingr74_dep_cfdis.rela_sicingr70 = pymvent62_dep_facturacion.rela_sicingr70)
),

   (
     (select PYMVENT62_DEP_FACTURACION.pymvent62_cancelado
     from PYMVENT62_DEP_FACTURACION
     where PYMVENT62_DEP_FACTURACION.rela_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
   )

from pymvent61_det_cobro
inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01 )
order by socsyst10_det_remoto.socsyst10_codigo
;



/* View: GRD_PYMVENT81_CON_CLIENTE */
CREATE OR ALTER VIEW GRD_PYMVENT81_CON_CLIENTE(
    MARCA,
    RELA_SOCMAIN01,
    RELA_SOCMAIN21,
    ENTIDAD,
    ID_PYMVENT70,
    PYMVENT70_DOCNRO,
    PYMVENT70_FECHA,
    PYMVENT70_HORA,
    PYMVENT70_NETO)
AS
select
1,
pymvent70_cab_ticket.rela_socmain01,
pymvent70_cab_ticket.rela_socmain21,
cbo_sicingr01_id.entidad,
pymvent70_cab_ticket.id_pymvent70,
pymvent70_cab_ticket.pymvent70_docnro,
cast(pymvent70_cab_ticket.pymvent70_fecha as date),
cast(extract(hour from pymvent70_cab_ticket.pymvent70_fecha) || ':' || extract(minute from pymvent70_cab_ticket.pymvent70_fecha) as time),
pymvent70_cab_ticket.pymvent70_neto
from pymvent70_cab_ticket
inner join cbo_sicingr01_id on ( cbo_sicingr01_id.id_sicingr01 = pymvent70_cab_ticket.rela_sicingr01 )
where exists ( select first 1 pymvent51_det_ventas.id_pymvent51
               from pymvent51_det_ventas
               where pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70
               and pymvent51_det_ventas.pymvent51_fvencido is null
               and pymvent51_det_ventas.pymvent51_fcerrado is not null
               and pymvent51_det_ventas.pymvent51_cancelado = 0
              )
and not exists ( select first 1 pymvent81_det_factglobal.id_pymvent81
                 from pymvent81_det_factglobal
                 where pymvent81_det_factglobal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70
                )
and not exists ( select first 1 sicingr74_dep_cfdis.id_sicingr74
                from sicingr74_dep_cfdis
                inner join sicingr70_cab_facturacion on (sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
                inner join pymvent62_dep_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = pymvent62_dep_facturacion.rela_sicingr70)
                where pymvent62_dep_facturacion.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70
                )
;



