/* View: GRD_PYMVENT81_SIN_CLIENTE */
CREATE OR ALTER VIEW GRD_PYMVENT81_SIN_CLIENTE(
    MARCA,
    RELA_SOCMAIN01,
    RELA_SOCMAIN21,
    ID_PYMVENT70,
    PYMVENT70_DOCNRO,
    PYMVENT70_FECHA,
