1,
pymvent70_cab_ticket.rela_socmain01,
pymvent70_cab_ticket.rela_socmain21,
pymvent70_cab_ticket.id_pymvent70,
pymvent70_cab_ticket.pymvent70_docnro,
cast(pymvent70_cab_ticket.pymvent70_fecha as date),
cast(extract(hour from pymvent70_cab_ticket.pymvent70_fecha) || ':' || extract(minute from pymvent70_cab_ticket.pymvent70_fecha) as time),
pymvent70_cab_ticket.pymvent70_neto
from pymvent70_cab_ticket
where pymvent70_cab_ticket.rela_sicingr01 is null
and exists ( select first 1 pymvent51_det_ventas.id_pymvent51
               from pymvent51_det_ventas
               where pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70
               and pymvent51_det_ventas.pymvent51_fvencido is null
               and pymvent51_det_ventas.pymvent51_fcerrado is not null
               and pymvent51_det_ventas.pymvent51_cancelado = 0
              )
and not exists ( select first 1 pymvent81_det_factglobal.id_pymvent81
                 from pymvent81_det_factglobal
                 where pymvent81_det_factglobal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70
                )
and not exists ( select first 1 sicingr74_dep_cfdis.id_sicingr74
                from sicingr74_dep_cfdis
                inner join sicingr70_cab_facturacion on (sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
                inner join pymvent62_dep_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = pymvent62_dep_facturacion.rela_sicingr70)
                where pymvent62_dep_facturacion.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70
                )
;



/* View: GRD_PYMVENT81_SIN_CLIENTE_ADD */
CREATE OR ALTER VIEW GRD_PYMVENT81_SIN_CLIENTE_ADD(
    MARCA,
    RELA_PYMVENT80,
    ID_PYMVENT70,
    PYMVENT70_DOCNRO,
    PYMVENT70_FECHA,
    PYMVENT70_HORA,
    PYMVENT70_NETO)
AS
select
1,
pymvent81_det_factglobal.rela_pymvent80,
pymvent70_cab_ticket.id_pymvent70,
pymvent70_cab_ticket.pymvent70_docnro,
cast(pymvent70_cab_ticket.pymvent70_fecha as date),
cast(extract(hour from pymvent70_cab_ticket.pymvent70_fecha) || ':' || extract(minute from pymvent70_cab_ticket.pymvent70_fecha) as time),
pymvent70_cab_ticket.pymvent70_neto
from pymvent81_det_factglobal
   inner join pymvent70_cab_ticket on (pymvent81_det_factglobal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
where pymvent70_cab_ticket.rela_sicingr01 is null
;



