/* View: GRD_SICCONT50 */
CREATE OR ALTER VIEW GRD_SICCONT50(
    VE,
    SICCONT10_DOCNRO,
    RELA_SOCMAIN05,
    RELA_SOCMAIN01,
    RELA_SOCMAIN21,
    RELA_SOCUSUA01,
    RELA_SICCONT10_POLIZA,
    ID_SICCONT50,
    SICCONT50_ANO,
    SICCONT50_MES,
    SICCONT50_SALDO_INICIAL,
    SICCONT50_SALDO_SISTEMA,
    SICCONT50_SALDO_BANCO,
    SICCONT50_SALDO_AJUSTE,
    SICCONT50_FAPL)
AS
select
grd_socmain05.ve,
siccont10_cab_polizas.siccont10_docnro,
SICCONT50_CAB_BANCOS.rela_socmain05,
SICCONT50_CAB_BANCOS.rela_socmain01,
