from SICCONT50_CAB_BANCOS
inner join grd_socmain05 on ( grd_socmain05.id_socmain05 = SICCONT50_CAB_BANCOS.rela_socmain05 )
inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = SICCONT50_CAB_BANCOS.rela_siccont10_poliza )

union all

select
grd_socmain05.ve,
cast('S/AJUSTE' as varchar(50)),
SICCONT50_CAB_BANCOS.rela_socmain05,
SICCONT50_CAB_BANCOS.rela_socmain01,
SICCONT50_CAB_BANCOS.rela_socmain21,
SICCONT50_CAB_BANCOS.rela_socusua01,
SICCONT50_CAB_BANCOS.rela_siccont10_poliza,
