SICCONT50_CAB_BANCOS.siccont50_mes,
SICCONT50_CAB_BANCOS.siccont50_saldo_inicial,
SICCONT50_CAB_BANCOS.siccont50_saldo_sistema,
SICCONT50_CAB_BANCOS.siccont50_saldo_banco,
SICCONT50_CAB_BANCOS.siccont50_saldo_ajuste,
CAST( (SICCONT50_CAB_BANCOS.siccont50_mes || '-01-' || SICCONT50_CAB_BANCOS.siccont50_ano) AS DATE)
from SICCONT50_CAB_BANCOS
inner join grd_socmain05 on ( grd_socmain05.id_socmain05 = SICCONT50_CAB_BANCOS.rela_socmain05 )
where SICCONT50_CAB_BANCOS.rela_siccont10_poliza is null
;



/* View: GRD_SICEGRE01 */
CREATE OR ALTER VIEW GRD_SICEGRE01(
    RELA_SOCMAIN01,
    RELA_SOCUSUA30,
    RELA_SOCSYST10_SAT01,
    ID_SICEGRE01,
    SICEGRE01_DIASCREDITO,
    SICEGRE01_FAPL,
    ENTIDAD,
    RFC,
    CURP,
    RELA_SOCMAIN80)
AS
select
sicegre01_cab_proveedores.rela_socmain01,
sicegre01_cab_proveedores.rela_socusua30,
sicegre01_cab_proveedores.rela_socsyst10_sat01,
sicegre01_cab_proveedores.id_sicegre01,
sicegre01_cab_proveedores.sicegre01_diascredito,
sicegre01_cab_proveedores.sicegre01_fapl,
(select cbo_socusua30.entidad
 from cbo_socusua30( sicegre01_cab_proveedores.rela_socusua30 )
),
(select cbo_socusua30.rfc
 from cbo_socusua30( sicegre01_cab_proveedores.rela_socusua30 )
),
(select cbo_socusua30.curp
 from cbo_socusua30( sicegre01_cab_proveedores.rela_socusua30 )
),
(select socusua36_det_domicilios.rela_socmain80
 from socusua36_det_domicilios
 inner join cbo_socsyst10_TDD01 on (cbo_socsyst10_TDD01.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
 where socusua36_det_domicilios.rela_socusua30 = sicegre01_cab_proveedores.rela_socusua30
 and cbo_socsyst10_TDD01.socsyst10_codigo = 'PARTICULAR'
)
from sicegre01_cab_proveedores
;



/* View: GRD_SICEGRE02 */
CREATE OR ALTER VIEW GRD_SICEGRE02(
    BANCO,
    MONEDA,
    RELA_SICEGRE01,
    RELA_SOCSYST10_BAN01,
    RELA_SOCSYST10_CTM01,
    ID_SICEGRE02,
    SICEGRE02_CUENTA,
    SICEGRE02_FAPL,
    VE,
    BUSQUEDA)
AS
select
BAN.socsyst10_descripcion,
MON.socsyst10_descripcion,
SICEGRE02_DET_BANCOS.rela_sicegre01,
SICEGRE02_DET_BANCOS.rela_socsyst10_ban01,
SICEGRE02_DET_BANCOS.rela_socsyst10_ctm01,
SICEGRE02_DET_BANCOS.id_sicegre02,
SICEGRE02_DET_BANCOS.sicegre02_cuenta,
SICEGRE02_DET_BANCOS.sicegre02_fapl,
trim(BAN.socsyst10_descripcion) || ' ' || trim(MON.socsyst10_descripcion) || ' Cuenta : ' || trim(sicegre02_cuenta),
RELA_SOCSYST10_BAN01 || RELA_SOCSYST10_CTM01 || trim(sicegre02_CUENTA)

from SICEGRE02_DET_BANCOS

inner join socsyst10_det_entradas BAN ON ( BAN.id_socsyst10 = SICEGRE02_DET_BANCOS.rela_socsyst10_ban01)
inner join socsyst10_det_remoto MON ON ( MON.id_socsyst10 = SICEGRE02_DET_BANCOS.rela_socsyst10_ctm01)
;



