/* View: GRD_SICINGR51_WEB */
CREATE OR ALTER VIEW GRD_SICINGR51_WEB(
    RELA_SOCMAIN01,
    RELA_SICPAGO70,
    ID_SICINGR51,
    CLIENTE,
    RFC,
    UUID,
    SICPAGO70_DOCNRO,
    SICPAGO70_STATUS,
    SICINGR51_IMPORTE,
    SICINGR51_FECHA,
    UUID_CANCELADO)
AS
select 
    sicingr51_cab_bancos.rela_socmain01,
    sicpago70_cab_pago.id_sicpago70,
    sicingr51_cab_bancos.id_sicingr51,
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc,
    CAST(
          (
           SELECT SICPAGO74_DEP_CFDIS.sicpago74_uuid
           FROM SICPAGO74_DEP_CFDIS
           WHERE SICPAGO74_DEP_CFDIS.rela_sicpago70 = sicpago70_cab_pago.id_sicpago70
          )
        AS VARCHAR(50)),
