/* View: GRD_SICINGR70_NOTASCREDITO */
CREATE OR ALTER VIEW GRD_SICINGR70_NOTASCREDITO(
    ID_SICINGR70,
    SICINGR70_DOCNRO,
    SICINGR70_FECHA,
    CREDITO,
    FOLIO,
    FACTURA,
    SALDO,
    SICINGR70_FAPL)
AS
select
max(sicingr70_cab_facturacion.id_sicingr70),
sicingr70_cab_facturacion.sicingr70_docnro,
sicingr70_cab_facturacion.sicingr70_fecha,
sicingr70_cab_facturacion.sicingr70_neto as credito,
max(sicxmls41_det_migracion.sicxmls41_folio) as folio,
sum(sicxmls41_det_migracion.sicxmls41_uuid_importe) as factura,
(sum(sicxmls41_det_migracion.sicxmls41_uuid_importe) - sicingr70_cab_facturacion.sicingr70_neto) as saldo,
max(sicingr70_cab_facturacion.sicingr70_fapl)
from sicingr70_cab_facturacion
inner join cbo_socsyst10_tcp01 on (cbo_socsyst10_tcp01.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01)
inner join sicingr73_det_relacionados on (sicingr70_cab_facturacion.id_sicingr70 = sicingr73_det_relacionados.rela_sicingr70)
inner join cbo_socsyst10_tre01 on (cbo_socsyst10_tre01.id_socsyst10 = sicingr73_det_relacionados.rela_socsyst10_tre01)
inner join sicxmls41_det_migracion on (sicxmls41_det_migracion.id_sicxmls41 = sicingr73_det_relacionados.rela_sicxmls41)
where cbo_socsyst10_tcp01.socsyst10_codigo = 'E'
and cbo_socsyst10_tre01.socsyst10_codigo = '01'
group by sicingr70_cab_facturacion.sicingr70_docnro,
         sicingr70_cab_facturacion.sicingr70_fecha,
         sicingr70_cab_facturacion.sicingr70_neto
;



