/* View: GRD_SICINGR71 */
CREATE OR ALTER VIEW GRD_SICINGR71(
    RELA_SICINGR70,
    RELA_SICINGR95,
    ID_SICINGR71,
    SICINGR71_CODIGO,
    SICINGR71_CONCEPTO,
    SICINGR71_CANTIDAD,
    SICINGR71_IMPORTE_UNIDAD,
    SICINGR71_IMPORTE_SUBTOTAL,
    SICINGR71_IMPORTE_DESCUENTO,
    SICINGR71_IMPORTE_IMPUESTOS,
    SICINGR71_IMPORTE_TOTAL,
    SICINGR71_IMPORTE_NETO,
    SICINGR71_IMPORTE_RETENIDO,
    SICINGR71_IMPORTE_TRASLADO,
    SICINGR71_IMPORTE_LOCALES,
    SICINGR71_FAPL,
    UNIDAD_MEDIDA,
    SAT_SERVPROD,
    IVA,
    SICINGR71_FACTGLOBAL,
    SICINGR71_IMPORTE_COSTO,
    SICINGR95_FRACCION)
AS
select
SICINGR71_DET_FACTURACION.rela_sicingr70,
SICINGR71_DET_FACTURACION.rela_sicingr95,
SICINGR71_DET_FACTURACION.id_sicingr71,
SICINGR71_DET_FACTURACION.sicingr71_codigo,
SICINGR71_DET_FACTURACION.sicingr71_concepto,
SICINGR71_DET_FACTURACION.sicingr71_cantidad,
SICINGR71_DET_FACTURACION.sicingr71_importe_unidad,
SICINGR71_DET_FACTURACION.sicingr71_importe_subtotal,
SICINGR71_DET_FACTURACION.sicingr71_importe_descuento,
SICINGR71_DET_FACTURACION.sicingr71_importe_impuestos,
SICINGR71_DET_FACTURACION.sicingr71_importe_total,
SICINGR71_DET_FACTURACION.sicingr71_importe_neto,
SICINGR71_DET_FACTURACION.sicingr71_importe_retenido,
SICINGR71_DET_FACTURACION.sicingr71_importe_traslado,
SICINGR71_DET_FACTURACION.sicingr71_importe_locales,
SICINGR71_DET_FACTURACION.sicingr71_fapl,
'(' || cum01.socsyst10_codigo || ') ' || cum01.socsyst10_descripcion,
'(' || cpo01.socsyst10_codigo || ') ' || cpo01.socsyst10_descripcion,
iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Exento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'IVA 0%', 'IVA')),
SICINGR71_DET_FACTURACION.sicingr71_factglobal,
SICINGR71_DET_FACTURACION.sicingr71_importe_costo,
sicingr95_cab_conceptos.sicingr95_fraccion
from SICINGR71_DET_FACTURACION
inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = SICINGR71_DET_FACTURACION.rela_sicingr95 )
inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
;



