    RELA_SICINGR70,
    ID_SICXMLS02,
    SICINGR72_TIPOZONA,
    TIPO,
    SICINGR72_IMPUESTO,
    SICINGR72_IMPORTE,
    BUSQUEDA)
AS
select 
sicingr71_det_facturacion.rela_sicingr70,
sicingr72_det_impuestos.rela_sicxmls02,
sicingr72_det_impuestos.sicingr72_tipozona,
iif( sicxmls02_det_impuestos.sicxmls02_retenido = 0, 'Trasladado', 'Retención'),
sicingr72_det_impuestos.sicingr72_impuesto,
sum(sicingr72_det_impuestos.sicingr72_importe),
trim(sicingr72_det_impuestos.sicingr72_tipozona) || trim(cast(sicingr72_det_impuestos.rela_sicxmls02 as varchar(20)))
from sicxmls02_det_impuestos
   inner join sicingr72_det_impuestos on (sicxmls02_det_impuestos.id_sicxmls02 = sicingr72_det_impuestos.rela_sicxmls02)
   inner join sicingr71_det_facturacion on (sicingr72_det_impuestos.rela_sicingr71 = sicingr71_det_facturacion.id_sicingr71)
group by
sicingr71_det_facturacion.rela_sicingr70,
sicingr72_det_impuestos.rela_sicxmls02,
sicingr72_det_impuestos.sicingr72_tipozona,
sicxmls02_det_impuestos.sicxmls02_retenido,
sicingr72_det_impuestos.sicingr72_impuesto
;



/* View: GRD_SICINGR73 */
CREATE OR ALTER VIEW GRD_SICINGR73(
    RELA_SICINGR70,
    RELA_SOCSYST10_TRE01,
    RELA_SICXMLS41,
    RELA_SICINGR77,
    ID_SICINGR73,
    SICINGR73_FAPL,
    UUID,
    UUID_IMPORTE,
    UUID_FECHA,
    FOLIO,
    ORIGEN,
    CODIGO_TIPO,
    DESCRIPCION_TIPO)
AS
SELECT
sicingr73_det_relacionados.rela_sicingr70,
sicingr73_det_relacionados.rela_socsyst10_tre01,
sicingr73_det_relacionados.rela_sicxmls41,
sicingr73_det_relacionados.rela_sicingr77,
sicingr73_det_relacionados.id_sicingr73,
sicingr73_det_relacionados.sicingr73_fapl,
sicxmls41_det_migracion.sicxmls41_uuid,
sicxmls41_det_migracion.sicxmls41_uuid_importe,
cast(sicxmls41_det_migracion.sicxmls41_uuid_fecha as date),
sicxmls41_det_migracion.sicxmls41_folio,
cast('DropZone' as varchar(20)),
socsyst10_det_remoto.socsyst10_codigo,
socsyst10_det_remoto.socsyst10_descripcion

FROM sicingr73_det_relacionados
INNER JOIN socsyst10_det_remoto ON (socsyst10_det_remoto.id_socsyst10 = sicingr73_det_relacionados.rela_socsyst10_tre01)
inner join sicxmls41_det_migracion on (sicxmls41_det_migracion.id_sicxmls41 = sicingr73_det_relacionados.rela_sicxmls41)
INNER JOIN siccont10_cab_polizas ON ( siccont10_cab_polizas.id_siccont10 = sicxmls41_det_migracion.rela_siccont10 )
INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )

union all

select 
sicingr73_det_relacionados.rela_sicingr70,
sicingr73_det_relacionados.rela_socsyst10_tre01,
sicingr73_det_relacionados.rela_sicxmls41,
sicingr73_det_relacionados.rela_sicingr77,
sicingr73_det_relacionados.id_sicingr73,
sicingr73_det_relacionados.sicingr73_fapl,
sicingr77_det_cfdiscancelados.sicingr77_uuid,
sicingr77_det_cfdiscancelados.sicingr77_uuid_importe,
cast(sicingr77_det_cfdiscancelados.sicingr77_uuid_fecha as date),
sicingr77_det_cfdiscancelados.sicingr77_folio,
cast('Cancelado' as varchar(20)),
socsyst10_det_remoto.socsyst10_codigo,
socsyst10_det_remoto.socsyst10_descripcion

from sicingr73_det_relacionados
   INNER JOIN socsyst10_det_remoto ON (socsyst10_det_remoto.id_socsyst10 = sicingr73_det_relacionados.rela_socsyst10_tre01)
   inner join sicingr77_det_cfdiscancelados on (sicingr73_det_relacionados.rela_sicingr77 = sicingr77_det_cfdiscancelados.id_sicingr77)
   inner join sicingr70_cab_facturacion on (sicingr77_det_cfdiscancelados.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
;



/* View: GRD_SICINGR84 */
CREATE OR ALTER VIEW GRD_SICINGR84(
    RELA_SOCMAIN01,
    RELA_SICINGR95,
    ID_SICINGR84,
    SICINGR84_PROCESA,
