;



/* View: GRD_SICINGR88_SALDEVO */
CREATE OR ALTER VIEW GRD_SICINGR88_SALDEVO(
    RELA_SOCMAIN01,
    ID_SICINGR01,
    ENTIDAD,
    SALDO)
AS
select 
sicingr70_cab_facturacion.rela_socmain01,
cbo_sicingr01_id.id_sicingr01,
cbo_sicingr01_id.entidad,
sum(sicingr88_det_gastos3ros.sicingr88_importe_sal) * -1
from sicingr70_cab_facturacion
   inner join sicingr88_det_gastos3ros on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
   inner join cbo_sicingr01_id on (sicingr70_cab_facturacion.rela_sicingr01 = cbo_sicingr01_id.id_sicingr01)
group by sicingr70_cab_facturacion.rela_socmain01,
         cbo_sicingr01_id.id_sicingr01,
         cbo_sicingr01_id.entidad
having sum(sicingr88_det_gastos3ros.sicingr88_importe_sal) < 0
;



/* View: GRD_SICINGR90 */
CREATE OR ALTER VIEW GRD_SICINGR90(
    RELA_SOCMAIN01,
    RELA_SICXMLS01,
    RELA_SICXMLS02,
    RELA_SOCSYST10_MCI01,
    RELA_SOCSYST10_IMP02,
    ID_SICINGR90,
    SICINGR90_TIPOZONA,
    ZONA,
    SICINGR90_DESCRIPCION,
    TIPO,
    SICINGR90_TASA,
    SICINGR90_MODO,
    SICINGR90_FAPL,
    SICCONT02_CODIGO_EXT,
    SICCONT02_DESCRIPCION,
    SICCONT02_CODAGRUP)
AS
select
sicxmls01_cab_parametros.rela_socmain01,
sicingr90_cab_impuestos.rela_sicxmls01,
sicingr90_cab_impuestos.rela_sicxmls02,
sicingr90_cab_impuestos.rela_socsyst10_mci01,
sicingr90_cab_impuestos.rela_socsyst10_imp02,
sicingr90_cab_impuestos.id_sicingr90,
sicingr90_cab_impuestos.sicingr90_tipozona,
iif(sicingr90_cab_impuestos.sicingr90_tipozona = 'F', 'Federal',
iif(sicingr90_cab_impuestos.sicingr90_tipozona = 'E', 'Estatal', 'Muncipal')),
socsyst10_det_remoto.socsyst10_descripcion,
iif(sicxmls02_det_impuestos.sicxmls02_retenido = 1, 'Retenido', 'Trasladado'),
sicingr90_cab_impuestos.sicingr90_tasa,
sicingr90_cab_impuestos.sicingr90_modo,
sicingr90_cab_impuestos.sicingr90_fapl,
