/* View: GRD_SICINGR95_ERPINGE01 */
CREATE OR ALTER VIEW GRD_SICINGR95_ERPINGE01(
    RELA_SOCMAIN01,
    RELA_SICXMLS01,
    RELA_SOCSYST10_CUM01,
    RELA_SOCSYST10_CPO01,
    ID_SICINGR95,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION,
    SICINGR95_IMPORTE,
    UNIDAD_MEDIDA,
    CATEGORIA_SAT,
    TIPO)
AS
select
sicxmls01_cab_parametros.rela_socmain01,
sicingr95_cab_conceptos.rela_sicxmls01,
sicingr95_cab_conceptos.rela_socsyst10_cum01,
sicingr95_cab_conceptos.rela_socsyst10_cpo01,
sicingr95_cab_conceptos.id_sicingr95,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion,
sicingr95_cab_conceptos.sicingr95_importe,
cum01.socsyst10_descripcion,
cpo01.socsyst10_descripcion,
( SELECT prd_sicingr95_tipo.descripcion
  from prd_sicingr95_tipo(sicingr95_cab_conceptos.sicingr95_tipo)
)

from sicingr95_cab_conceptos
inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
where (sicingr95_cab_conceptos.sicingr95_tipo = 1 or sicingr95_cab_conceptos.sicingr95_tipo = 4)
and sicingr95_cab_conceptos.sicingr95_inactivo = 0
order by sicingr95_cab_conceptos.sicingr95_codigo
;



/* View: GRD_SICINGR95_ERPINGE02 */
CREATE OR ALTER VIEW GRD_SICINGR95_ERPINGE02(
    RELA_SOCMAIN01,
    RELA_SICXMLS01,
    RELA_SOCSYST10_CUM01,
    RELA_SOCSYST10_CPO01,
    ID_SICINGR95,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION,
    SICINGR95_IMPORTE,
    UNIDAD_MEDIDA,
    CATEGORIA_SAT,
    TIPO,
    SICINGR95_TIPO)
AS
select
sicxmls01_cab_parametros.rela_socmain01,
sicingr95_cab_conceptos.rela_sicxmls01,
sicingr95_cab_conceptos.rela_socsyst10_cum01,
sicingr95_cab_conceptos.rela_socsyst10_cpo01,
sicingr95_cab_conceptos.id_sicingr95,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion,
sicingr95_cab_conceptos.sicingr95_importe,
cum01.socsyst10_descripcion,
cpo01.socsyst10_descripcion,
(select prd_sicingr95_tipo.descripcion
 from prd_sicingr95_tipo(sicingr95_cab_conceptos.sicingr95_tipo)),
sicingr95_cab_conceptos.sicingr95_tipo
from sicingr95_cab_conceptos
inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
where sicingr95_cab_conceptos.sicingr95_tipo >= 2
and sicingr95_cab_conceptos.sicingr95_inactivo = 0
order by sicingr95_cab_conceptos.sicingr95_codigo
;



/* View: GRD_SICINGR95_FAMILIA */
CREATE OR ALTER VIEW GRD_SICINGR95_FAMILIA(
    RELA_SICINGR95,
    ID_SOCSYST12,
    SOCSYST12_DESCRIPCION,
    SOCSYST12_FAPL)
AS
SELECT
    sicingr97_det_clasificacion.rela_sicingr95,
    socsyst12_det_cla.id_socsyst12,
    socsyst12_det_cla.socsyst12_descripcion,
    socsyst12_det_cla.socsyst12_fapl
FROM sicingr97_det_clasificacion
INNER JOIN socsyst10_det_entradas
    ON socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01
INNER JOIN socsyst12_det_cla
    ON socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12
where socsyst10_det_entradas.socsyst10_codigo = 'FAMILIA'
;
;



/* View: GRD_SICINGR95_SICXMLS04 */
CREATE OR ALTER VIEW GRD_SICINGR95_SICXMLS04(
    MARCA,
    RELA_SICXMLS01,
    RELA_SOCMAIN01,
    ID_SICXMLS04,
    SICCONT02_CODIGO_EXT,
    SICCONT02_DESCRIPCION,
    SICCONT02_CODAGRUP,
    SOCSYST10_DESCRIPCION,
    SICXMLS04_CONCEPTO,
    TIPO,
    IMPORTE)
AS
select
0,
sicxmls01_cab_parametros.id_sicxmls01,
sicxmls01_cab_parametros.rela_socmain01,
sicxmls04_det_conceptos.id_sicxmls04,
siccont02_arb_planctas.siccont02_codigo_ext,
siccont02_arb_planctas.siccont02_descripcion,
siccont02_arb_planctas.siccont02_codagrup,
socsyst10_det_entradas.socsyst10_descripcion,
sicxmls04_det_conceptos.sicxmls04_concepto,
iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Excento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'Iva 0%', 'Iva')),
( select QRY_SICXMLS42_MAX_IMPORTE.importe
  from QRY_SICXMLS42_MAX_IMPORTE
  where QRY_SICXMLS42_MAX_IMPORTE.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04
)

from sicxmls01_cab_parametros
inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01 )
inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02 )
inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicxmls04_det_conceptos.rela_socsyst10_tct01 )
where sicxmls04_det_conceptos.rela_siccont02 is not null
  and sicxmls04_det_conceptos.sicxmls04_tipo = 'I'
  and socsyst10_det_entradas.socsyst10_codigo like 'CLIENTE%'
  and not exists ( select sicingr95_cab_conceptos.id_sicingr95
                   from sicingr95_cab_conceptos
                   where sicingr95_cab_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01
                   and sicingr95_cab_conceptos.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04 )
;



/* View: GRD_SICINGR95_WEB */
CREATE OR ALTER VIEW GRD_SICINGR95_WEB(
    RELA_SOCMAIN01,
    RELA_PYMALMA01,
    ID_SICINGR95,
    SICINGR95_CODIGO,
    SICINGR95_DESCRIPCION,
    CPO01_DESCRIPCION,
    CUM01_DESCRIPCION,
    SICINGR95_INACTIVO,
    SICINGR95_IMPORTE,
    UNIDAD_MEDIDA,
    SAT_SERVPROD,
    SICINGR95_STOCK,
    SICINGR95_FAPL)
AS
SELECT
sicxmls01_cab_parametros.rela_socmain01,
sicingr95_cab_conceptos.rela_pymalma01,
sicingr95_cab_conceptos.id_sicingr95,
sicingr95_cab_conceptos.sicingr95_codigo,
sicingr95_cab_conceptos.sicingr95_descripcion,
cpo01.socsyst10_descripcion,
cum01.socsyst10_descripcion,
sicingr95_cab_conceptos.sicingr95_inactivo,
sicingr95_cab_conceptos.sicingr95_importe,
'(' || cum01.socsyst10_codigo || ') ' || cum01.socsyst10_descripcion,
'(' || cpo01.socsyst10_codigo || ') ' || cpo01.socsyst10_descripcion,
( select COALESCE(SUM(pymalma02_det_stock.pymalma02_cantidad), 0)
  from PYMALMA02_DET_STOCK
  inner join PYMALMA01_CAB_STOCK on (
    PYMALMA01_CAB_STOCK.ID_PYMALMA01 = PYMALMA02_DET_STOCK.RELA_PYMALMA01
  )
  where PYMALMA01_CAB_STOCK.RELA_SOCMAIN01 = sicxmls01_cab_parametros.RELA_SOCMAIN01
  and PYMALMA02_DET_STOCK.RELA_SICINGR95 = sicingr95_cab_conceptos.ID_SICINGR95
),
sicingr95_cab_conceptos.sicingr95_fapl
FROM sicingr95_cab_conceptos
inner join sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01)
inner join SOCSYST10_DET_REMOTO cpo01 on (cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01)
inner join SOCSYST10_DET_REMOTO cum01 on (cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01)
order by sicingr95_cab_conceptos.sicingr95_descripcion
;



