/* View: GRD_SICNOMI02 */
CREATE OR ALTER VIEW GRD_SICNOMI02(
    BANCO,
    MONEDA,
    RELA_SICNOMI01,
    RELA_SOCSYST10_BAN01,
    RELA_SOCSYST10_CTM01,
    ID_SICNOMI02,
    SICNOMI02_CUENTA,
    SICNOMI02_FAPL,
    VE,
    BUSQUEDA)
AS
select
BAN.socsyst10_descripcion,
MON.socsyst10_descripcion,
SICNOMI02_DET_BANCOS.rela_SICNOMI01,
SICNOMI02_DET_BANCOS.rela_socsyst10_ban01,
SICNOMI02_DET_BANCOS.RELA_SOCSYST10_CTM01,
SICNOMI02_DET_BANCOS.id_SICNOMI02,
SICNOMI02_DET_BANCOS.SICNOMI02_cuenta,
SICNOMI02_DET_BANCOS.SICNOMI02_fapl,
trim(BAN.socsyst10_descripcion) || ' ' || trim(MON.socsyst10_descripcion) || ' Cuenta : ' || trim(SICNOMI02_cuenta),
RELA_SOCSYST10_BAN01 || RELA_SOCSYST10_CTM01 || trim(SICNOMI02_CUENTA)

from SICNOMI02_DET_BANCOS

inner join socsyst10_det_entradas BAN ON ( BAN.id_socsyst10 = SICNOMI02_DET_BANCOS.rela_socsyst10_ban01)
inner join socsyst10_det_remoto MON ON ( MON.id_socsyst10 = SICNOMI02_DET_BANCOS.rela_socsyst10_ctm01)
;



