    TOT_PERCEPCIONES,
    TOT_DEDUCCIONES,
    RELA_SICCONT10,
    UUID,
    UUID_SMX,
    UUID_SMX_QRCODE,
    UUID_IMPORTE,
    UUID_CANCELADO,
    RFC_EMPLEADO,
    CURP,
    EMPLEADO)
AS
SELECT
sicnomi70_cab_nomina.rela_socmain01,
sicnomi70_cab_nomina.rela_socmain21,
sicnomi70_cab_nomina.rela_socusua01,
sicnomi70_cab_nomina.rela_sicnomi01,
sicnomi70_cab_nomina.id_sicnomi70,

iif(
(select first 1 sicnomi73_det_xperiodo.id_sicnomi73
 from sicnomi73_det_xperiodo
 where sicnomi73_det_xperiodo.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
) is null, 'MANUAL', 'PERIODO'),

sicnomi70_cab_nomina.sicnomi70_docnro,
sicnomi70_cab_nomina.sicnomi70_tiponomina,
sicnomi70_cab_nomina.sicnomi70_fecha,
sicnomi70_cab_nomina.sicnomi70_fini,
sicnomi70_cab_nomina.sicnomi70_ffin,
sicnomi70_cab_nomina.sicnomi70_dias,
sicnomi70_cab_nomina.sicnomi70_fapl,
sicnomi70_cab_nomina.sicnomi70_status,

(   select sum( sicnomi71_det_nomina.sicnomi71_importe )
    from sicnomi71_det_nomina
    INNER JOIN sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05)
    where sicnomi71_det_nomina.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo <> 'D' AND sicxmls05_det_nomina.sicxmls05_tipo <> 'I')
),

(   select sum( sicnomi71_det_nomina.sicnomi71_importe )
    from sicnomi71_det_nomina
    INNER JOIN sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05)
    where sicnomi71_det_nomina.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' or sicxmls05_det_nomina.sicxmls05_tipo = 'I')
),

(   select siccont10_cab_polizas.id_siccont10
    from sicnomi74_dep_cfdis
    inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicnomi74_dep_cfdis.rela_sicxmls41 )
    inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicxmls41_det_migracion.rela_siccont10 )
    where sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70

),

(   select sicnomi74_dep_cfdis.sicnomi74_uuid
    from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
),

(   select sicnomi74_dep_cfdis.sicnomi74_uuid_smx
    from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
),

(   select sicnomi74_dep_cfdis.sicnomi74_uuid_smx_qrcode
    from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
),
(   select sicnomi74_dep_cfdis.sicnomi74_uuid_importe
    from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
),
(
    select first 1 sicnomi77_det_cfdiscancelados.sicnomi77_uuid
    from sicnomi77_det_cfdiscancelados
    where sicnomi77_det_cfdiscancelados.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70
    order by sicnomi77_det_cfdiscancelados.id_sicnomi77 desc
),
(   select cbo_sicnomi01_id.rfc
    from cbo_sicnomi01_id
    where cbo_sicnomi01_id.id_sicnomi01 = sicnomi70_cab_nomina.rela_sicnomi01
),
(
    select first 1 socusua32_det_documentos.socusua32_documento
    from cbo_sicnomi01_id
    inner join socusua32_det_documentos on (socusua32_det_documentos.rela_socusua30 = cbo_sicnomi01_id.rela_socusua30)
    INNER JOIN cbo_socsyst10_td001 ON (socusua32_det_documentos.rela_socsyst10_td001 = cbo_socsyst10_td001.id_socsyst10)
    where cbo_sicnomi01_id.id_sicnomi01 = sicnomi70_cab_nomina.rela_sicnomi01
    AND cbo_socsyst10_td001.socsyst10_codigo = 'CURP'
    order by socusua32_det_documentos.id_socusua32 desc
),
cbo_sicnomi01_ID.entidad
FROM sicnomi70_cab_nomina
INNER JOIN cbo_sicnomi01_ID ON (sicnomi70_cab_nomina.rela_sicnomi01 = cbo_sicnomi01_ID.id_sicnomi01)
order by sicnomi70_cab_nomina.SICNOMI70_DOCNRO desc
;



