/* View: GRD_SICPAGO50 */
CREATE OR ALTER VIEW GRD_SICPAGO50(
    RELA_SOCMAIN01,
    RELA_SICINGR01,
    RELA_SICEGRE01,
    RELA_SICXMLS41_COMI,
    RELA_SICINGR51,
    ID_SICPAGO50,
    SICPAGO50_CUENTA,
    SICPAGO50_IMPORTE,
    SICPAGO50_COMISION,
    SICPAGO50_FECHA,
    SICPAGO50_FAPL,
    CLIENTE,
    CLIENTE_RFC,
    PROVEEDOR,
    PROVEEDOR_RFC,
    SICPAGO74_UUID)
AS
select
sicingr51_cab_bancos.rela_socmain01,
SICPAGO50_CAB_FACTORAJE.rela_sicingr01,
SICPAGO50_CAB_FACTORAJE.rela_sicegre01,
SICPAGO50_CAB_FACTORAJE.rela_sicxmls41_comi,
SICPAGO50_CAB_FACTORAJE.rela_sicingr51,
SICPAGO50_CAB_FACTORAJE.id_sicpago50,
SICPAGO50_CAB_FACTORAJE.sicpago50_cuenta,
SICPAGO50_CAB_FACTORAJE.sicpago50_importe,
SICPAGO50_CAB_FACTORAJE.sicpago50_comision,
SICPAGO50_CAB_FACTORAJE.sicpago50_fecha,
SICPAGO50_CAB_FACTORAJE.sicpago50_fapl,
cbo_sicingr01_id.entidad,
cbo_sicingr01_id.rfc,
cbo_sicegre01_id.entidad,
cbo_sicegre01_id.rfc,
( select sicpago74_dep_cfdis.sicpago74_uuid
  from sicpago70_cab_pago
  inner join sicpago74_dep_cfdis on (sicpago74_dep_cfdis.rela_sicpago70 = sicpago70_cab_pago.id_sicpago70)
  where sicpago70_cab_pago.rela_sicingr51 = SICPAGO50_CAB_FACTORAJE.rela_sicingr51
)
from SICPAGO50_CAB_FACTORAJE
inner join sicingr51_cab_bancos on (sicingr51_cab_bancos.id_sicingr51 = SICPAGO50_CAB_FACTORAJE.rela_sicingr51)
inner join cbo_sicingr01_id on (cbo_sicingr01_id.id_sicingr01 = SICPAGO50_CAB_FACTORAJE.rela_sicingr01)
inner join cbo_sicegre01_id on (cbo_sicegre01_id.id_sicegre01 = SICPAGO50_CAB_FACTORAJE.rela_sicegre01)
;



