/* View: GRD_SICXMLS02_CON */
CREATE OR ALTER VIEW GRD_SICXMLS02_CON(
    SOCSYST10_DESCRIPCION,
    CUENTA,
    CUENTA_TRASLADO,
    RELA_SICXMLS01,
    RELA_SOCSYST10_TCT01,
    RELA_SICCONT02,
    RELA_SICCONT02_CTRACTA,
    ID_SICXMLS02,
    SICXMLS02_IMPUESTO,
    SICXMLS02_TIPO,
    TIPO,
    SICXMLS02_RETENIDO,
    RETENIDO,
    SICXMLS02_TASA,
    SICXMLS02_FAPL,
    BUSQUEDA)
AS
SELECT
socsyst10_det_entradas.socsyst10_descripcion,
trim(siccont02_arb_planctas.siccont02_codigo_ext) || ' - ' ||
trim(siccont02_arb_planctas.siccont02_descripcion),
trim(TRASL.siccont02_codigo_ext) || ' - ' ||
trim(TRASL.siccont02_descripcion),
sicxmls02_det_impuestos.rela_sicxmls01,
sicxmls02_det_impuestos.rela_socsyst10_tct01,
sicxmls02_det_impuestos.rela_siccont02,
sicxmls02_det_impuestos.rela_siccont02_ctracta,
sicxmls02_det_impuestos.id_sicxmls02,
sicxmls02_det_impuestos.sicxmls02_impuesto,
sicxmls02_det_impuestos.sicxmls02_tipo,
iif(sicxmls02_det_impuestos.sicxmls02_tipo = 'E', 'Egreso', 'Ingreso'),
sicxmls02_det_impuestos.sicxmls02_retenido,
iif(sicxmls02_det_impuestos.sicxmls02_retenido = 0, 'No', 'Si'),
sicxmls02_det_impuestos.sicxmls02_tasa,
sicxmls02_det_impuestos.sicxmls02_fapl,
sicxmls02_det_impuestos.rela_socsyst10_tct01 ||
upper(trim(sicxmls02_det_impuestos.sicxmls02_impuesto)) ||
cast(sicxmls02_det_impuestos.sicxmls02_tasa as numeric(15,4)) ||
sicxmls02_det_impuestos.sicxmls02_retenido
FROM sicxmls02_det_impuestos
INNER JOIN socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls02_det_impuestos.rela_socsyst10_tct01)
INNER JOIN siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = sicxmls02_det_impuestos.rela_siccont02)
INNER JOIN siccont02_arb_planctas TRASL on (TRASL.id_siccont02 = sicxmls02_det_impuestos.rela_siccont02_ctracta)
;



/* View: GRD_SICXMLS02_SIN */
