from grd_sicxmls02_sin
;



/* View: GRD_SICXMLS04_CON */
CREATE OR ALTER VIEW GRD_SICXMLS04_CON(
    MARCA,
    SOCSYST10_DESCRIPCION,
    CUENTA,
    RELA_SICXMLS01,
    RELA_SOCSYST10_TCT01,
    RELA_SICCONT02,
    ID_SICXMLS04,
    SICXMLS04_TIPO,
    TIPO,
    SICXMLS04_EXCENTO,
    EXCENTO,
    SICXMLS04_DEDUCIBLE,
    DEDUCIBLE,
    UNIDAD,
    CLAVEPRODUCTO,
    CODIGO_CONCEPTO,
    SICXMLS04_CONCEPTO,
    SICXMLS04_FAPL,
    BUSQUEDA)
AS
SELECT
0,
socsyst10_det_entradas.socsyst10_descripcion,
trim(siccont02_arb_planctas.siccont02_codigo_ext) || ' - ' ||
trim(siccont02_arb_planctas.siccont02_descripcion),
sicxmls04_det_conceptos.rela_sicxmls01,
sicxmls04_det_conceptos.RELA_SOCSYST10_TCT01,
sicxmls04_det_conceptos.rela_siccont02,
sicxmls04_det_conceptos.id_sicxmls04,
sicxmls04_det_conceptos.sicxmls04_tipo,
iif(sicxmls04_det_conceptos.SICXMLS04_TIPO = 'E', 'Egreso', 'Ingreso'),
sicxmls04_det_conceptos.SICXMLS04_EXCENTO,
iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Exento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'IVA 0%', 'IVA')),
sicxmls04_det_conceptos.sicxmls04_deducible,
iif(sicxmls04_det_conceptos.sicxmls04_deducible = 0, 'No', 'Si'),
sicxmls04_det_conceptos.sicxmls04_unidad,
sicxmls04_det_conceptos.sicxmls04_claveprodserv,
(select first 1 sicxmls42_det_conceptos.sicxmls42_noidentificacion
 from sicxmls42_det_conceptos
 where sicxmls42_det_conceptos.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04
),
sicxmls04_det_conceptos.SICXMLS04_CONCEPTO,
sicxmls04_det_conceptos.sicxmls04_fapl,
sicxmls04_det_conceptos.RELA_SOCSYST10_TCT01 || TRIM(sicxmls04_det_conceptos.SICXMLS04_CONCEPTO)
FROM sicxmls04_det_conceptos
INNER JOIN socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls04_det_conceptos.RELA_SOCSYST10_TCT01)
INNER JOIN siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02)
;



