sicxmls04_det_conceptos.sicxmls04_claveprodserv,
socsyst10_det_entradas.socsyst10_codigo
FROM sicxmls42_det_conceptos
inner join sicxmls04_det_conceptos on (sicxmls04_det_conceptos.id_sicxmls04 = sicxmls42_det_conceptos.rela_sicxmls04)
inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls04_det_conceptos.rela_socsyst10_tct01)
inner join sicxmls41_det_migracion on (sicxmls41_det_migracion.id_sicxmls41 = sicxmls42_det_conceptos.rela_sicxmls41)
where sicxmls04_det_conceptos.rela_siccont02 is null
and sicxmls41_det_migracion.rela_siccont10 is null
;



