    SICXMLS05_GRAVADO,
    GRAVADO,
    SICXMLS05_CONCEPTO,
    SICXMLS05_FAPL,
    SICXMLS05_TIPOSAT,
    BUSQUEDA)
AS
select
SICXMLS05_DET_NOMINA.id_sicxmls05,
trim(siccont02_arb_planctas.siccont02_codigo_ext) || ' - ' ||
trim(siccont02_arb_planctas.siccont02_descripcion),
SICXMLS05_DET_NOMINA.rela_sicxmls01,
SICXMLS05_DET_NOMINA.rela_siccont02,
SICXMLS05_DET_NOMINA.sicxmls05_tipo,
iif(SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'P', 'Percepción',
iif(SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'D', 'Deducción',
iif(SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'O', 'Otros Pagos',
iif(SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'I', 'Incapacidad', 'Horas Extra')))),
SICXMLS05_DET_NOMINA.sicxmls05_gravado,
iif(SICXMLS05_DET_NOMINA.sicxmls05_gravado = 0, 'No', 'Si'),
SICXMLS05_DET_NOMINA.sicxmls05_concepto,
SICXMLS05_DET_NOMINA.sicxmls05_fapl,
SICXMLS05_DET_NOMINA.sicxmls05_tiposat,
SICXMLS05_DET_NOMINA.sicxmls05_tipo ||
iif(SICXMLS05_DET_NOMINA.sicxmls05_tiposat is null,'',SICXMLS05_DET_NOMINA.sicxmls05_tiposat) ||
SICXMLS05_DET_NOMINA.sicxmls05_gravado ||
SICXMLS05_DET_NOMINA.sicxmls05_concepto
from SICXMLS05_DET_NOMINA
INNER JOIN siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = SICXMLS05_DET_NOMINA.rela_siccont02)
INNER JOIN siccont02_arb_planctas TRASL on (TRASL.id_siccont02 = SICXMLS05_DET_NOMINA.rela_siccont02_ctracta)
;



