/* View: GRD_SICXMLS41_SICPAGO70 */
CREATE OR ALTER VIEW GRD_SICXMLS41_SICPAGO70(
    RELA_SOCUSUA30,
    ID_SICXMLS41,
    SICXMLS41_FOLIO,
    SICXMLS41_UUID,
    SICXMLS41_UUID_IMPORTE,
    SICXMLS41_UUID_FECHA)
AS
SELECT
sicxmls41_det_migracion.rela_socusua30,
sicxmls41_det_migracion.id_sicxmls41,
sicxmls41_det_migracion.sicxmls41_folio,
sicxmls41_det_migracion.sicxmls41_uuid,
sicxmls41_det_migracion.sicxmls41_uuid_importe,
sicxmls41_det_migracion.sicxmls41_uuid_fecha

FROM sicxmls41_det_migracion
INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01)
WHERE socsyst10_det_entradas.socsyst10_codigo = 'PROVE'
AND sicxmls41_det_migracion.sicxmls41_metododepago = 'PUE'
AND sicxmls41_det_migracion.sicxmls41_formapago = '17'
AND NOT EXISTS ( SELECT FIRST 1 sicpago50_cab_factoraje.id_sicpago50
                 FROM sicpago50_cab_factoraje
                 WHERE sicpago50_cab_factoraje.rela_sicxmls41_comi = sicxmls41_det_migracion.id_sicxmls41
                )
;



