sicxmls41_det_migracion.sicxmls41_uuid,
sicxmls41_det_migracion.sicxmls41_uuid_importe,
sicxmls41_det_migracion.sicxmls41_uuid_fecha

FROM sicxmls41_det_migracion
INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01)
WHERE socsyst10_det_entradas.socsyst10_codigo = 'PROVE'
AND sicxmls41_det_migracion.sicxmls41_metododepago = 'PUE'
AND sicxmls41_det_migracion.sicxmls41_formapago = '17'
;



