SICXMLS44_DET_ERRORES.rela_socsyst10_tct01,
SICXMLS44_DET_ERRORES.id_sicxmls44,
SICXMLS44_DET_ERRORES.sicxmls44_uuid,
SICXMLS44_DET_ERRORES.sicxmls44_path,
SICXMLS44_DET_ERRORES.sicxmls44_error,
SICXMLS44_DET_ERRORES.sicxmls44_fapl
from SICXMLS44_DET_ERRORES
inner join socsyst10_det_entradas xml01 ON (xml01.id_socsyst10 = SICXMLS44_DET_ERRORES.rela_socsyst10_xml01)
inner join socsyst10_det_entradas tct01 ON (tct01.id_socsyst10 = SICXMLS44_DET_ERRORES.rela_socsyst10_tct01)
;



/* View: GRD_SOCMAIN01 */
CREATE OR ALTER VIEW GRD_SOCMAIN01(
    SOCUSUA30_NOMBRE_RAZSOC,
    SOCSYST10_DESCRIPCION,
    RELA_SOCUSUA30,
    RELA_SOCSYST10_TS001,
    RELA_SOCSYST10_SAT01,
    ID_SOCMAIN01,
    SOCMAIN01_PROPIETARIA,
    PROPIETARIA,
    SOCMAIN01_NOMCOMERCIAL,
    SOCMAIN01_FAPL,
    RFC,
    TIPO_ENTIDAD,
    SOCMAIN01_NOCERTIFICADO,
    SOCMAIN01_PAC,
    SOCMAIN01_SATUSER,
    SOCMAIN01_SATPASS,
    SOCMAIN01_CFDIUSER,
    SOCMAIN01_CFDIPASS,
    SOCMAIN01_PACUSER,
    SOCMAIN01_PACPASS,
    SOCMAIN01_UUID_SMX_KEY,
    SOCMAIN01_UUID_SMX_CER,
    SOCMAIN01_AVISOFOLIOS)
AS
select
socusua30_cab_entidades.socusua30_nombre_razsoc,
socsyst10_det_entradas.socsyst10_descripcion,
socmain01_cab_empresas.rela_socusua30,
socmain01_cab_empresas.rela_socsyst10_ts001,
socmain01_cab_empresas.rela_socsyst10_sat01,
socmain01_cab_empresas.id_socmain01,
socmain01_cab_empresas.socmain01_propietaria,
iif(socmain01_cab_empresas.socmain01_propietaria = 0, 'No', 'Si'),
socmain01_cab_empresas.socmain01_nomcomercial,
socmain01_cab_empresas.socmain01_fapl,
(
    SELECT FIRST 1 socusua32_det_documentos.socusua32_documento
    FROM socusua30_cab_entidades
    INNER JOIN socusua32_det_documentos ON (socusua32_det_documentos.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
    INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
    WHERE socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30
    AND socsyst10_det_entradas.socsyst10_codigo = 'RFC'
),
TIPOENTI.socsyst10_codigo,
socmain01_cab_empresas.socmain01_nocertificado,
socmain01_cab_empresas.socmain01_pac,
socmain01_cab_empresas.socmain01_satuser,
socmain01_cab_empresas.socmain01_satpass,
socmain01_cab_empresas.socmain01_cfdiuser,
socmain01_cab_empresas.socmain01_cfdipass,
socmain01_cab_empresas.socmain01_pacuser,
socmain01_cab_empresas.socmain01_pacpass,
socmain01_cab_empresas.socmain01_uuid_smx_key,
socmain01_cab_empresas.socmain01_uuid_smx_cer,
socmain01_cab_empresas.socmain01_avisofolios
from socmain01_cab_empresas
inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30)
inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_ts001)
inner join socsyst10_det_entradas TIPOENTI on (TIPOENTI.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)
;



/* View: GRD_SOCMAIN02 */
CREATE OR ALTER VIEW GRD_SOCMAIN02(
    SOCSYST10_CODIGO,
    SOCSYST10_DESCRIPCION,
    RELA_SOCMAIN01,
    RELA_SOCSYST10_TDL01,
    RELA_SYSJSON02,
    ID_SOCMAIN02,
    SOCMAIN02_FAPL,
    BUSQUEDA,
    SYSJSON02_UUID)
AS
select
socsyst10_det_entradas.socsyst10_codigo,
socsyst10_det_entradas.socsyst10_descripcion,
socmain02_det_logos.rela_socmain01,
socmain02_det_logos.rela_socsyst10_tdl01,
socmain02_det_logos.rela_sysjson02,
socmain02_det_logos.id_socmain02,
socmain02_det_logos.socmain02_fapl,
socmain02_det_logos.rela_socsyst10_tdl01,
(select sysjson02_tbl_files.sysjson02_uuid
 from sysjson02_tbl_files
 where sysjson02_tbl_files.id_sysjson02 = socmain02_det_logos.rela_sysjson02
)
FROM socmain02_det_logos
INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = socmain02_det_logos.rela_socsyst10_tdl01 )
;



/* View: GRD_SOCMAIN05_CTA */
CREATE OR ALTER VIEW GRD_SOCMAIN05_CTA(
    BANCO,
    MONEDA,
    RELA_SICCONT02,
    RELA_SOCMAIN01,
    RELA_SOCSYST10_BAN01,
    RELA_SOCSYST10_CTM01,
    ID_SOCMAIN05,
    SOCMAIN05_CUENTA,
    SOCMAIN05_FAPL,
    VE,
    BUSQUEDA)
AS
SELECT
BAN.socsyst10_descripcion,
MON.socsyst10_descripcion,
SOCMAIN05_DET_BANCOS.rela_siccont02,
SOCMAIN05_DET_BANCOS.RELA_SOCMAIN01,
SOCMAIN05_DET_BANCOS.RELA_SOCSYST10_BAN01,
SOCMAIN05_DET_BANCOS.RELA_SOCSYST10_CTM01,
SOCMAIN05_DET_BANCOS.ID_SOCMAIN05,
SOCMAIN05_DET_BANCOS.SOCMAIN05_CUENTA,
SOCMAIN05_DET_BANCOS.SOCMAIN05_FAPL,
trim(BAN.socsyst10_descripcion) || ' ' || trim(MON.socsyst10_descripcion) || ' Cuenta : ' || trim(SOCMAIN05_CUENTA),
RELA_SOCSYST10_BAN01 || RELA_SOCSYST10_CTM01 || trim(SOCMAIN05_CUENTA)

from SOCMAIN05_DET_BANCOS

INNER JOIN socsyst10_det_entradas BAN ON (BAN.id_socsyst10 = SOCMAIN05_DET_BANCOS.RELA_SOCSYST10_BAN01)
INNER JOIN socsyst10_det_remoto MON ON (MON.id_socsyst10 = SOCMAIN05_DET_BANCOS.rela_socsyst10_ctm01)
;



