/* View: GRD_SOCSYST21 */
CREATE OR ALTER VIEW GRD_SOCSYST21(
    SOCMAIN01_NOMCOMERCIAL,
    SOCMAIN21_DESCRIPCION,
    SOCSYST10_DESCRIPCION,
    RELA_SOCMAIN01,
    RELA_SOCMAIN20,
    RELA_SOCMAIN21,
    RELA_SOCSYST10_CO001,
    ID_SOCSYST21,
    SOCSYST21_PREFIJO,
    SOCSYST21_SUBFIJO,
    SOCSYST21_LONGITUD,
    SOCSYST21_CONTADOR,
    SOCSYST21_FAPL,
    BUSQUEDA)
AS
select
    socmain01_cab_empresas.socmain01_nomcomercial,
    socmain21_arb_organizacion.socmain21_descripcion,
    socsyst10_det_entradas.socsyst10_descripcion,
    SOCSYST21_CAB_CONTAORGA.rela_socmain01,
    SOCSYST21_CAB_CONTAORGA.rela_socmain20,
    SOCSYST21_CAB_CONTAORGA.rela_socmain21,
    SOCSYST21_CAB_CONTAORGA.rela_socsyst10_co001,
    SOCSYST21_CAB_CONTAORGA.id_socsyst21,
    SOCSYST21_CAB_CONTAORGA.socsyst21_prefijo,
    SOCSYST21_CAB_CONTAORGA.socsyst21_subfijo,
    SOCSYST21_CAB_CONTAORGA.socsyst21_longitud,
    SOCSYST21_CAB_CONTAORGA.socsyst21_contador,
    SOCSYST21_CAB_CONTAORGA.socsyst21_fapl,
    (
    SOCSYST21_CAB_CONTAORGA.rela_socsyst10_co001 ||
    SOCSYST21_CAB_CONTAORGA.rela_socmain21
    )



from SOCSYST21_CAB_CONTAORGA
inner join socsyst10_det_entradas on (SOCSYST21_CAB_CONTAORGA.rela_socsyst10_co001 = socsyst10_det_entradas.id_socsyst10)
inner join socmain21_arb_organizacion on (SOCSYST21_CAB_CONTAORGA.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = SOCSYST21_CAB_CONTAORGA.rela_socmain01)
;



