/* View: GRD_SYSUSER11 */
CREATE OR ALTER VIEW GRD_SYSUSER11(
    ID_SYSUSER11,
    RELA_SYSJSON02,
    RELA_SYSUSER10,
    SYSUSER11_RELACION,
    SYSUSER11_ACEPTADO,
    SYSUSER10_NOMBRES,
    SYSUSER10_APELLIDOS,
    SYSUSER10_TELEFONO,
    SYSUSER10_CORREO,
    SYSUSER10_GEOLOC_ULT,
    SYSJSON02_UUID,
    SYSUSER11_FAPL)
AS
select
sysuser11_det_contactos.id_sysuser11,
sysuser10_cab_movil.rela_sysjson02,
sysuser11_det_contactos.rela_sysuser10,
sysuser11_det_contactos.sysuser11_relacion,
sysuser11_det_contactos.sysuser11_aceptado,
sysuser10_cab_movil.sysuser10_nombres,
sysuser10_cab_movil.sysuser10_apellidos,
sysuser10_cab_movil.sysuser10_telefono,
sysuser10_cab_movil.sysuser10_correo,
sysuser10_cab_movil.sysuser10_geoloc_ult,
(select sysjson02_tbl_files.sysjson02_uuid
 from sysjson02_tbl_files
 where sysjson02_tbl_files.id_sysjson02 = sysuser10_cab_movil.rela_sysjson02
),
sysuser11_det_contactos.sysuser11_fapl
from sysuser11_det_contactos
inner join sysuser10_cab_movil on (sysuser10_cab_movil.id_sysuser10 = sysuser11_det_contactos.rela_sysuser10_invitado)
ORDER BY sysuser10_cab_movil.sysuser10_apellidos
;



/* View: GRD_SYSUSER20 */
CREATE OR ALTER VIEW GRD_SYSUSER20(
    RELA_SYSUSER10,
    RELA_SOCSYST10_VM001,
    ID_SYSUSER20,
    SYSUSER20_FOLIO,
    SYSUSER20_PANICO,
    TIPO,
    SYSUSER20_TITULO,
    SYSUSER20_GEOLOCACION,
    SYSUSER20_FAPL,
    FAPL_FORMAT,
    SYSUSER10_NOMBRES,
    SYSUSER10_APELLIDOS,
    SYSUSER10_TELEFONO,
    SYSUSER10_CORREO,
    SYSUSER10_CORREO_01,
    EDAD,
    CANT_FOTOS,
    CANT_MSJ_NOLEIDOS,
    ESTADO_CODE,
    ESTADO)
AS
select 
sysuser20_det_alertas.rela_sysuser10,
sysuser20_det_alertas.rela_socsyst10_vm001,
sysuser20_det_alertas.id_sysuser20,
sysuser20_det_alertas.sysuser20_folio,
sysuser20_det_alertas.sysuser20_panico,
CAST(IIF(sysuser20_det_alertas.sysuser20_panico = 1, 'Pánico', 'Denuncia') AS VARCHAR(50)),
sysuser20_det_alertas.sysuser20_titulo,
sysuser20_det_alertas.sysuser20_geolocacion,
sysuser20_det_alertas.sysuser20_fapl,
SUBSTRING(CAST(sysuser20_fapl AS VARCHAR(25)) FROM 1 FOR POSITION('.' IN CAST(sysuser20_fapl AS VARCHAR(25))) - 1),
sysuser10_cab_movil.sysuser10_nombres,
sysuser10_cab_movil.sysuser10_apellidos,
sysuser10_cab_movil.sysuser10_telefono,
sysuser10_cab_movil.sysuser10_correo,
sysuser10_cab_movil.sysuser10_correo_01,
CAST(
    DATEDIFF(YEAR, sysuser10_fecha, CURRENT_DATE) -
    CASE 
      WHEN EXTRACT(MONTH FROM CURRENT_DATE) < EXTRACT(MONTH FROM sysuser10_fecha) 
           OR (EXTRACT(MONTH FROM CURRENT_DATE) = EXTRACT(MONTH FROM sysuser10_fecha) 
               AND EXTRACT(DAY FROM CURRENT_DATE) < EXTRACT(DAY FROM sysuser10_fecha)) 
      THEN 1 ELSE 0 
    END 
  AS INTEGER),
(
  select count(*)
  from sysuser22_det_imagenes
  where sysuser22_det_imagenes.rela_sysuser20 = sysuser20_det_alertas.id_sysuser20
),
(
  select count(*)
  from sysuser21_det_mensajes
  where sysuser21_det_mensajes.rela_sysuser20 = sysuser20_det_alertas.id_sysuser20
),
cbo_socsyst10_vmo01.socsyst10_codigo,
cbo_socsyst10_vmo01.socsyst10_descripcion
from sysuser20_det_alertas
   inner join sysuser10_cab_movil on (sysuser20_det_alertas.rela_sysuser10 = sysuser10_cab_movil.id_sysuser10)
   inner join cbo_socsyst10_vmo01 on (sysuser20_det_alertas.RELA_SOCSYST10_VM001 = cbo_socsyst10_vmo01.id_socsyst10)
ORDER BY sysuser20_det_alertas.id_sysuser20 DESC
;



