/* View: GRD_TMP_SICINGR70 */
CREATE OR ALTER VIEW GRD_TMP_SICINGR70(
    USUARIO,
    RELA_SICINGR01,
    SUBTOTAL,
    DESCUENTO,
    IVA,
    OTROS,
    RETIVA,
    RETISR,
    TOTAL)
AS
SELECT
    TMP_SICINGR70_FACTURAS.USUARIO,
    TMP_SICINGR70_FACTURAS.RELA_SICINGR01,
    SUM(TMP_SICINGR70_FACTURAS.SUBTOTAL),
    SUM(TMP_SICINGR70_FACTURAS.DESCUENTO),
    SUM(TMP_SICINGR70_FACTURAS.IVA),
    SUM(TMP_SICINGR70_FACTURAS.OTROS),
    SUM(TMP_SICINGR70_FACTURAS.RETIVA),
    SUM(TMP_SICINGR70_FACTURAS.RETISR),
    SUM(TMP_SICINGR70_FACTURAS.TOTAL)
FROM TMP_SICINGR70_FACTURAS
GROUP BY
    TMP_SICINGR70_FACTURAS.USUARIO,
    TMP_SICINGR70_FACTURAS.RELA_SICINGR01
;



/* View: QRY_SICCONT11_AUXILIAR */
CREATE OR ALTER VIEW QRY_SICCONT11_AUXILIAR(
    RELA_SOCMAIN01,
    ID_SICCONT02,
    SICCONT02_TIPO,
    SALDO,
    SUMA_DEBE,
    SUMA_HABER,
    SICCONT10_FCTA,
    MOVIMIENTOS)
AS
select
siccont10_cab_polizas.rela_socmain01,
siccont11_det_polizas.rela_siccont02,
siccont02_arb_planctas.siccont02_tipo,
iif(siccont02_arb_planctas.siccont02_tipo = 'D',
    sum(siccont11_det_polizas.siccont11_debe) - sum(siccont11_det_polizas.siccont11_haber),
    sum(siccont11_det_polizas.siccont11_haber) - sum(siccont11_det_polizas.siccont11_debe)),
sum(siccont11_det_polizas.siccont11_debe),
sum(siccont11_det_polizas.siccont11_haber),
siccont10_cab_polizas.siccont10_fcta,
count(siccont11_det_polizas.rela_siccont02)
from siccont11_det_polizas
inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10)
inner join siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02)
group by
siccont10_cab_polizas.rela_socmain01,
siccont11_det_polizas.rela_siccont02,
siccont02_arb_planctas.siccont02_tipo,
siccont10_cab_polizas.siccont10_fcta
;



/* View: QRY_SICCONT11_BALANZA */
CREATE OR ALTER VIEW QRY_SICCONT11_BALANZA(
    RELA_SOCMAIN01,
    RELA_SICCONT02,
    SICCONT02_TIPO,
    SICCONT02_CODIGO,
    SICCONT02_CODIGO_EXT,
    SUMA_DEBE,
    SUMA_HABER,
    SICCONT11_ANO,
    SICCONT11_MES)
AS
SELECT
siccont10_cab_polizas.rela_socmain01,
SICCONT11_DET_POLIZAS.rela_siccont02,
siccont02_arb_planctas.siccont02_tipo,
trim(siccont02_arb_planctas.siccont02_codigo),
trim(siccont02_arb_planctas.siccont02_codigo_ext),
sum(SICCONT11_DET_POLIZAS.siccont11_debe),
sum(SICCONT11_DET_POLIZAS.siccont11_haber),
SICCONT11_DET_POLIZAS.siccont11_ano,
SICCONT11_DET_POLIZAS.siccont11_mes
FROM SICCONT11_DET_POLIZAS
INNER JOIN siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = SICCONT11_DET_POLIZAS.rela_siccont10)
INNER JOIN siccont02_arb_planctas ON (siccont02_arb_planctas.id_siccont02 = SICCONT11_DET_POLIZAS.rela_siccont02)
GROUP BY
siccont10_cab_polizas.rela_socmain01,
SICCONT11_DET_POLIZAS.rela_siccont02,
siccont02_arb_planctas.siccont02_tipo,
trim(siccont02_arb_planctas.siccont02_codigo),
trim(siccont02_arb_planctas.siccont02_codigo_ext),
SICCONT11_DET_POLIZAS.siccont11_ano,
SICCONT11_DET_POLIZAS.siccont11_mes
;



/* View: QRY_SICCONT11_BALANZA_FISCAL */
CREATE OR ALTER VIEW QRY_SICCONT11_BALANZA_FISCAL(
    USUARIO,
    ID_SICCONT02,
    SICCONT02_TIPO,
    SICCONT02_CODIGO_EXT,
    SICCONT02_CODAGRUP,
    SUMA_DEBE,
    SUMA_HABER)
AS
SELECT
tmp_siccont11_balanza_fiscal.usuario,
tmp_siccont11_balanza_fiscal.id_siccont02,
tmp_siccont11_balanza_fiscal.siccont02_tipo,
tmp_siccont11_balanza_fiscal.siccont02_codigo_ext,
tmp_siccont11_balanza_fiscal.siccont02_codagrup,
sum(tmp_siccont11_balanza_fiscal.suma_debe),
sum(tmp_siccont11_balanza_fiscal.suma_haber)
from tmp_siccont11_balanza_fiscal
where (tmp_siccont11_balanza_fiscal.suma_debe + tmp_siccont11_balanza_fiscal.suma_haber) <> 0
GROUP BY
tmp_siccont11_balanza_fiscal.usuario,
tmp_siccont11_balanza_fiscal.id_siccont02,
tmp_siccont11_balanza_fiscal.siccont02_tipo,
tmp_siccont11_balanza_fiscal.siccont02_codigo_ext,
tmp_siccont11_balanza_fiscal.siccont02_codagrup
;



/* View: QRY_SICCONT11_DIFERENCIAS */
CREATE OR ALTER VIEW QRY_SICCONT11_DIFERENCIAS(
    SICCONT10_DOCNRO,
    SICCONT10_TIPO_ENTIDAD,
    SICXMLS41_UUID,
    SICXMLS41_UUID_SMX,
    SICXMLS41_UUID_FECHA,
    SICXMLS41_UUID_IMPORTE,
    SUMA_DEBE,
    SUMA_HABER,
    DIFERENCIA)
AS
select
siccont10_cab_polizas.siccont10_docnro,
siccont10_cab_polizas.siccont10_tipo_entidad,
sicxmls41_det_migracion.sicxmls41_uuid,
sicxmls41_det_migracion.sicxmls41_uuid_smx,
sicxmls41_det_migracion.sicxmls41_uuid_fecha,
sicxmls41_det_migracion.sicxmls41_uuid_importe,
sum(siccont11_det_polizas.siccont11_debe),
sum(siccont11_det_polizas.siccont11_haber),
(sum(siccont11_det_polizas.siccont11_debe) - sum(siccont11_det_polizas.siccont11_haber))
from siccont10_cab_polizas
inner join siccont11_det_polizas on ( siccont10_cab_polizas.id_siccont10 =  siccont11_det_polizas.rela_siccont10)
inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
group by
siccont10_cab_polizas.siccont10_docnro,
siccont10_cab_polizas.siccont10_tipo_entidad,
sicxmls41_det_migracion.sicxmls41_uuid,
sicxmls41_det_migracion.sicxmls41_uuid_smx,
sicxmls41_det_migracion.sicxmls41_uuid_fecha,
sicxmls41_det_migracion.sicxmls41_uuid_importe
having
cast(sum(siccont11_det_polizas.siccont11_debe) as numeric(15,4)) <>
cast(sum(siccont11_det_polizas.siccont11_haber) as numeric(15,4))
;



/* View: QRY_SICCONT11_SALDOS */
CREATE OR ALTER VIEW QRY_SICCONT11_SALDOS(
    RELA_SOCMAIN01,
    ID_SICCONT02,
    SALDO,
    SICCONT10_FCTA)
AS
select
siccont10_cab_polizas.rela_socmain01,
siccont11_det_polizas.rela_siccont02,
iif(siccont02_arb_planctas.siccont02_tipo = 'D',
    siccont11_det_polizas.siccont11_debe - siccont11_det_polizas.siccont11_haber,
    siccont11_det_polizas.siccont11_haber - siccont11_det_polizas.siccont11_debe),
siccont10_cab_polizas.siccont10_fcta

from siccont11_det_polizas
inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10)
inner join siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02)
;



