sicegre50_det_ctacte.sicegre50_importe,
sicegre50_det_ctacte.sicegre50_fapl,
siccont10_cab_polizas.siccont10_cotiza,
sicegre50_det_ctacte.sicegre50_importe * siccont10_cab_polizas.siccont10_cotiza,
socsyst10_det_remoto.socsyst10_codigo,
socsyst10_det_remoto.socsyst10_descripcion,
sicegre01_cab_proveedores.sicegre01_diascredito,
sicegre01_cab_proveedores.sicegre01_credito,
sicegre01_cab_proveedores.sicegre01_factoraje
from sicegre50_det_ctacte
inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10 )
inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctm01 )
inner join sicegre01_cab_proveedores on ( sicegre01_cab_proveedores.id_sicegre01 = sicegre50_det_ctacte.rela_sicegre01 )
;



/* View: QRY_SICINGR50 */
CREATE OR ALTER VIEW QRY_SICINGR50(
    RELA_SICINGR01,
    RELA_SOCUSUA30,
    RELA_SOCMAIN01,
    RELA_SICCONT10,
    RELA_SICINGR51,
    RELA_SOCSYST10_CTM01,
    ID_SICINGR50,
    SICINGR50_IMPORTE,
    SICINGR50_FAPL,
    SICCONT10_COTIZA,
    SICINGR50_IMPORTE_PESOS,
    MONEDA_CODIGO,
    MONEDA_DESCRIPCION,
    SICINGR01_DIASCREDITO,
    SICINGR01_CREDITO,
    SICINGR50_IMPORTE_NO_PESOS)
AS
select
sicingr50_det_ctacte.rela_sicingr01,
sicingr01_cab_clientes.rela_socusua30,
sicingr50_det_ctacte.rela_socmain01,
sicingr50_det_ctacte.rela_siccont10,
sicingr50_det_ctacte.rela_sicingr51,
siccont10_cab_polizas.rela_socsyst10_ctm01,
sicingr50_det_ctacte.id_sicingr50,
sicingr50_det_ctacte.sicingr50_importe,
sicingr50_det_ctacte.sicingr50_fapl,
siccont10_cab_polizas.siccont10_cotiza,
sicingr50_det_ctacte.sicingr50_importe * siccont10_cab_polizas.siccont10_cotiza,
socsyst10_det_remoto.socsyst10_codigo,
socsyst10_det_remoto.socsyst10_descripcion,
sicingr01_cab_clientes.sicingr01_diascredito,
sicingr01_cab_clientes.sicingr01_credito,
iif(siccont10_cab_polizas.siccont10_cotiza = 1,
    0.00,
    sicingr50_det_ctacte.sicingr50_importe * siccont10_cab_polizas.siccont10_cotiza)
from sicingr50_det_ctacte
inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctm01 )
inner join sicingr01_cab_clientes on ( sicingr01_cab_clientes.id_sicingr01 = sicingr50_det_ctacte.rela_sicingr01 )
;



/* View: QRY_SICINGR52_ANTICIPOS_NO_AA */
CREATE OR ALTER VIEW QRY_SICINGR52_ANTICIPOS_NO_AA(
    RELA_SICINGR01,
    CONCEPTO,
    IMPORTE)
AS
select
sicingr51_cab_bancos.rela_sicingr01,
'Anticipos',
sum(sicingr51_cab_bancos.sicingr51_importe)
from sicingr51_cab_bancos
inner join sicingr54_dep_anticipos on ( sicingr54_dep_anticipos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51 )
and sicingr51_cab_bancos.sicingr51_anticipo = 1
and not exists ( select first 1 sicingr53_det_refanticipos.id_sicingr53
                   from sicingr53_det_refanticipos
                   where sicingr53_det_refanticipos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51
                  )
group by sicingr51_cab_bancos.rela_sicingr01

union all

select
sicingr51_cab_bancos.rela_sicingr01,
'Aplicacion',
sum(sicingr52_det_bancos.sicingr52_importe)
from sicingr51_cab_bancos
inner join sicingr50_det_ctacte on ( sicingr51_cab_bancos.id_sicingr51 = sicingr50_det_ctacte.rela_sicingr51 )
inner join sicingr52_det_bancos on ( sicingr52_det_bancos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51 )
where sicingr51_cab_bancos.sicingr51_anticipo = 0
and sicingr52_det_bancos.sicingr52_importe < 0
and exists ( select first 1 sicingr50_det_ctacte.rela_siccont10
             from sicingr50_det_ctacte
             where sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50
             and exists ( select first 1 sicingr54_dep_anticipos.id_sicingr54
                          from sicingr54_dep_anticipos
                          where sicingr54_dep_anticipos.rela_siccont10 = sicingr50_det_ctacte.rela_siccont10
                         )
            )
and exists ( select first 1 sicingr50_det_ctacte.rela_siccont10
             from sicingr50_det_ctacte
             where sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50
             and exists ( select first 1 sicingr54_dep_anticipos.id_sicingr54
                          from sicingr54_dep_anticipos
                          where sicingr54_dep_anticipos.rela_siccont10 = sicingr50_det_ctacte.rela_siccont10
                          and not exists ( select first 1 sicingr53_det_refanticipos.id_sicingr53
                                           from sicingr53_det_refanticipos
                                           where sicingr53_det_refanticipos.rela_sicingr51 = sicingr54_dep_anticipos.rela_sicingr51
                             )
                         )
            )
group by sicingr51_cab_bancos.rela_sicingr01
;



/* View: QRY_SICINGR52_SALDOS */
CREATE OR ALTER VIEW QRY_SICINGR52_SALDOS(
    RELA_SICINGR50,
    IMPORTE_BANCOS,
    IMPORTE_FACTURA,
    ID_SICCONT10)
AS
select
  sicingr52_det_bancos.rela_sicingr50,
  sum(sicingr52_det_bancos.sicingr52_importe),
  sicingr50_det_ctacte.sicingr50_importe,
  sicingr50_det_ctacte.rela_siccont10
  from sicingr52_det_bancos
  inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
  group by
  sicingr52_det_bancos.rela_sicingr50,
  sicingr50_det_ctacte.sicingr50_importe,
  sicingr50_det_ctacte.rela_siccont10
;



/* View: QRY_SICINGR52_SICINGR70 */
CREATE OR ALTER VIEW QRY_SICINGR52_SICINGR70(
    RELA_SICCONT10,
    RELA_SICXMLS41,
    RELA_SICINGR01,
    ID_SICINGR70,
    IMPORTE_BANCOS,
    IMPORTE_PAGADO,
    IMPORTE_FACTURA,
    IMPORTE_CTAGASTO,
    IMPORTE_ANTICIPOS_AA,
    IMPORTE_ANTICIPOS)
AS
SELECT
QRY_SICINGR52_SALDOS.id_siccont10,
sicxmls41_det_migracion.id_sicxmls41,
sicingr70_cab_facturacion.rela_sicingr01,
sicingr74_dep_cfdis.rela_sicingr70,
QRY_SICINGR52_SALDOS.importe_bancos,

(select
    sum(sicingr52_det_bancos.sicingr52_importe)
    from sicingr52_det_bancos
    where exists ( select first 1 sicpago70_cab_pago.id_sicpago70
             from sicpago70_cab_pago
             where sicpago70_cab_pago.rela_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
    and sicingr52_det_bancos.rela_sicingr50 = QRY_SICINGR52_SALDOS.rela_sicingr50
    group by sicingr52_det_bancos.rela_sicingr50
),

QRY_SICINGR52_SALDOS.importe_factura,

(select
    sum(sicingr86_det_gastos3ros.sicingr86_importe)
    from sicingr88_det_gastos3ros
    inner join sicingr85_cab_gastos3ros on ( sicingr85_cab_gastos3ros.id_sicingr85 =  sicingr88_det_gastos3ros.rela_sicingr85 )
    inner join sicingr86_det_gastos3ros on ( sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85 )
    where sicingr88_det_gastos3ros.rela_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70
),

(select
    sum(SICINGR53_DET_REFANTICIPOS.sicingr53_importe)
    from SICINGR53_DET_REFANTICIPOS
    inner join sicingr85_cab_gastos3ros on ( sicingr85_cab_gastos3ros.id_sicingr85 = SICINGR53_DET_REFANTICIPOS.rela_sicingr85 )
    inner join sicingr88_det_gastos3ros on ( sicingr88_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85 )
    where sicingr88_det_gastos3ros.rela_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70
),

(select
    sum(SICINGR51_CAB_BANCOS.sicingr51_importe)
    from SICINGR51_CAB_BANCOS
    inner join sicingr54_dep_anticipos on ( sicingr54_dep_anticipos.rela_sicingr51 = SICINGR51_CAB_BANCOS.id_sicingr51 )
    where SICINGR51_CAB_BANCOS.rela_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01
    and SICINGR51_CAB_BANCOS.sicingr51_anticipo = 1
    and not exists ( select first 1 sicingr53_det_refanticipos.id_sicingr53
                     from sicingr53_det_refanticipos
                     where sicingr53_det_refanticipos.rela_sicingr51 = SICINGR51_CAB_BANCOS.id_sicingr51
                    )
)

FROM QRY_SICINGR52_SALDOS
INNER JOIN sicxmls41_det_migracion ON (sicxmls41_det_migracion.rela_siccont10 = QRY_SICINGR52_SALDOS.id_siccont10 )
INNER JOIN sicingr74_dep_cfdis ON ( sicingr74_dep_cfdis.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
;



