    RELA_SOCMAIN01,
    SOCSYST06_NIVEL,
    SOCSYST06_DESCRIPCION,
    ID_SICCONT02,
    SICCONT02_CODIGO_EXT,
    SICCONT02_DESCRIPCION,
    SICCONT02_TIPO,
    SICCONT02_CODAGRUP,
    SUBCTADE)
AS
SELECT
siccont01_cab_planctas.rela_socmain01,
socsyst06_det_niveles.socsyst06_nivel,
socsyst06_det_niveles.socsyst06_descripcion,
siccont02_arb_planctas.id_siccont02,
