/* View: ZZZ$_USUARIOS */
CREATE OR ALTER VIEW ZZZ$_USUARIOS(
    SOCUSUA01_USUARIO,
    ENTIDAD,
    SOCUSUA11_DESCRIPCION,
    SOCUSUA12_BTO_ALTA,
    SOCUSUA12_BTO_BAJA,
    SOCUSUA12_BTO_MODI,
    SOCUSUA12_BTO_REPO,
    SOCUSUA12_BTO_CONS,
    SOCUSUA12_BTO_INFO)
AS
select 
    socusua01_cab_usuarios.socusua01_usuario,
    cbo_socusua30_all.entidad,
    socusua11_arb_menu.socusua11_descripcion,
    iif(socusua12_dep_funciones.socusua12_bto_alta = 1, 'Si', 'No'),
    iif(socusua12_dep_funciones.socusua12_bto_baja = 1, 'Si', 'No'),
    iif(socusua12_dep_funciones.socusua12_bto_modi = 1, 'Si', 'No'),
    iif(socusua12_dep_funciones.socusua12_bto_repo = 1, 'Si', 'No'),
    iif(socusua12_dep_funciones.socusua12_bto_cons = 1, 'Si', 'No'),
    iif(socusua12_dep_funciones.socusua12_bto_info = 1, 'Si', 'No')
from socusua12_dep_funciones
   inner join socusua11_arb_menu on (socusua12_dep_funciones.rela_socusua11 = socusua11_arb_menu.id_socusua11)
   inner join socusua10_cab_menu on (socusua11_arb_menu.rela_socusua10 = socusua10_cab_menu.id_socusua10)
   inner join socusua15_det_perfiles on (socusua10_cab_menu.id_socusua10 = socusua15_det_perfiles.rela_socusua10)
   inner join socmain21_arb_organizacion on (socusua15_det_perfiles.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
   inner join socusua02_det_organizacion on (socmain21_arb_organizacion.id_socmain21 = socusua02_det_organizacion.rela_socmain21)
   inner join socusua01_cab_usuarios on (socusua02_det_organizacion.rela_socusua01 = socusua01_cab_usuarios.id_socusua01)
   inner join cbo_socusua30_all on (socusua01_cab_usuarios.rela_socusua30 = cbo_socusua30_all.id_socusua30)
where socusua01_cab_usuarios.socusua01_usuario != 'ADMIN' and socusua01_cab_usuarios.socusua01_usuario != 'RAUL'
order by socusua01_usuario, socusua11_arb_menu.socusua11_descripcion
;




