/* Trigger: TID_ADUCTAG01 */
CREATE OR ALTER TRIGGER TID_ADUCTAG01 FOR ADUCTAG01_CAB_CTAGASTOS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_ADUCTAG01 = GEN_ID(SID_ADUCTAG01,1); 
        cTipo = 'A'; 
        nID = NEW.ID_ADUCTAG01; 

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ctm01, 'CTM01')
        into new.rela_socsyst10_ctm01;
    END
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_ADUCTAG01; 

        if ((old.rela_socsyst10_ctm01 <> new.rela_socsyst10_ctm01) or (old.rela_socsyst10_ctm01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ctm01, 'CTM01')
            into new.rela_socsyst10_ctm01;
        end
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_ADUCTAG01; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'ADUCTAG01',
            :nID; 
END
^


