/* Trigger: TID_PYMALMA03 */
CREATE OR ALTER TRIGGER TID_PYMALMA03 FOR PYMALMA03_DEP_REFERENCIA
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT;
declare variable pymalma02_cantidad double precision;
declare variable id_socsyst10_cancela bigint;
declare variable rela_pymalma01 bigint;
declare variable rela_pymalma01_transf bigint;
declare variable rela_sicingr95 bigint;


BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_PYMALMA03 = GEN_ID(SID_PYMALMA03,1); 
        cTipo = 'A'; 
        nID = NEW.ID_PYMALMA03; 
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_PYMALMA03; 
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_PYMALMA03; 

        select CBO_SOCSYST10_STK01.id_socsyst10
        from CBO_SOCSYST10_STK01
        where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK-AUTO-CANCELA'
        into :id_socsyst10_cancela;

        select
        pymalma02_det_stock.rela_pymalma01,
        pymalma02_det_stock.rela_pymalma01_transf,
        pymalma02_det_stock.rela_sicingr95,
        pymalma02_det_stock.pymalma02_cantidad
        from pymalma02_det_stock
        where pymalma02_det_stock.id_pymalma02 = old.rela_pymalma02
        into :rela_pymalma01,
             :rela_pymalma01_transf,
             :rela_sicingr95,
             :pymalma02_cantidad;

        pymalma02_cantidad = pymalma02_cantidad * (-1);

        insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                         pymalma02_det_stock.rela_pymalma01_transf,
                                         pymalma02_det_stock.rela_socsyst10_stk01,
                                         pymalma02_det_stock.rela_sicingr95,
                                         pymalma02_det_stock.pymalma02_cantidad )
        values( :rela_pymalma01,
                :rela_pymalma01_transf,
                :id_socsyst10_cancela,
                :rela_sicingr95,
                :pymalma02_cantidad );


    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'PYMALMA03',
            :nID; 
END
^


