/* Trigger: TID_PYMVENT50 */
CREATE OR ALTER TRIGGER TID_PYMVENT50 FOR PYMVENT50_CAB_APERTURA
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
declare variable codigo VARCHAR(50);
declare variable totales DOUBLE precision;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_PYMVENT50 = GEN_ID(SID_PYMVENT50,1); 
        cTipo = 'A'; 
        nID = NEW.ID_PYMVENT50; 

        Select smx$soc_contadores.nrodoc
        from smx$soc_contadores(new.rela_socmain01, new.rela_socmain21, :nid, 'PYMVENT50')
        into new.pymvent50_docnro;
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_PYMVENT50; 

        if (new.pymvent50_fcierre is not null) then
        begin
            for select
            rep_pymvent50_cobros.socsyst10_codigo,
            rep_pymvent50_cobros.totales
            from rep_pymvent50_cobros(:nID)
            where rep_pymvent50_cobros.socsyst10_codigo = 'Z1'
            or rep_pymvent50_cobros.socsyst10_codigo = 'Z3'
            into :codigo,
                 :totales
            do
            begin
                if (codigo = 'Z1') then
                    new.pymvent50_importe_venta = totales;
                else if (codigo = 'Z3') then
                    new.pymvent50_importe_efectivo = totales;
            end
        end
    END
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_PYMVENT50; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'PYMVENT50',
            :nID; 
END
^


/* Trigger: TID_PYMVENT51 */
CREATE OR ALTER TRIGGER TID_PYMVENT51 FOR PYMVENT51_DET_VENTAS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 

DECLARE VARIABLE rela_socmain01 BIGINT;
DECLARE VARIABLE id_pymalma01 BIGINT;
DECLARE VARIABLE id_pymalma01_apartado BIGINT;

DECLARE VARIABLE id_socsyst10_stk_mas BIGINT;
DECLARE VARIABLE id_socsyst10_stk_menos BIGINT;

DECLARE VARIABLE id_pymvent71 BIGINT;
DECLARE VARIABLE id_sicingr95 BIGINT;
DECLARE VARIABLE id_pymalma02 BIGINT;
DECLARE VARIABLE id_pymalma02_apartado BIGINT;
DECLARE VARIABLE rela_socmain21 BIGINT;

DECLARE VARIABLE oldDiasApartados INTEGER;

DECLARE VARIABLE pymvent71_cantidad DOUBLE precision;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_PYMVENT51 = GEN_ID(SID_PYMVENT51,1); 
        cTipo = 'A'; 
        nID = NEW.ID_PYMVENT51; 
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_PYMVENT51; 
        oldDiasApartados = old.pymvent51_diasapartado;

        if (oldDiasApartados is null) then
            oldDiasApartados = 0;

        if (oldDiasApartados = 0 and new.pymvent51_diasapartado <> 0) then
        begin
            select
            pymvent70_cab_ticket.rela_socmain01,
            pymvent70_cab_ticket.rela_socmain21
            from pymvent70_cab_ticket
            where pymvent70_cab_ticket.id_pymvent70 = old.rela_pymvent70
            into :rela_socmain01,
                 :rela_socmain21;

            select
            pymalma01_cab_stock.id_pymalma01
            from pymalma01_cab_stock
            where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
            and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
            into :id_pymalma01;

            select
            pymalma01_cab_stock.id_pymalma01
            from pymalma01_cab_stock
            where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
            and pymalma01_cab_stock.rela_socmain21 = new.rela_socmain21_apartados
            into :id_pymalma01_apartado;

            if (id_pymalma01_apartado is null) then
            begin
                insert into pymalma01_cab_stock( pymalma01_cab_stock.rela_socmain01,
                                                 pymalma01_cab_stock.rela_socmain21,
                                                 pymalma01_cab_stock.rela_socusua01 )
                values( :rela_socmain01,
                        new.rela_socmain21_apartados,
                        new.rela_socusua01_vend );

                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA01'
                INTO :id_pymalma01_apartado;
            end

            select CBO_SOCSYST10_STK01.id_socsyst10
            from CBO_SOCSYST10_STK01
            where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK_AUTO-APARTADO-MAS'
            into :id_socsyst10_stk_mas;

            select CBO_SOCSYST10_STK01.id_socsyst10
            from CBO_SOCSYST10_STK01
            where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK_AUTO-APARTADO-MENOS'
            into :id_socsyst10_stk_menos;

            for select
            pymvent71_det_ticket.id_pymvent71,
            pymvent71_det_ticket.rela_sicingr95,
            pymvent71_det_ticket.pymvent71_cantidad
            from pymvent71_det_ticket
            where pymvent71_det_ticket.rela_pymvent70 = old.rela_pymvent70
            into :id_pymvent71,
                 :id_sicingr95,
                 :pymvent71_cantidad
            do
            begin
                insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                                 pymalma02_det_stock.rela_sicingr95,
                                                 pymalma02_det_stock.rela_socsyst10_stk01,
                                                 pymalma02_det_stock.pymalma02_cantidad )
                values( :id_pymalma01,
                        :id_sicingr95,
                        :id_socsyst10_stk_menos,
                        :pymvent71_cantidad * (-1) );
        
                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
                INTO :id_pymalma02;

                /* ========================================================================================================================================== */

                insert into pymalma03_dep_referencia( pymalma03_dep_referencia.rela_pymalma02,
                                                          pymalma03_dep_referencia.rela_pymvent71 )
                values( :id_pymalma02,
                            :id_pymvent71 );
        
                /* ========================================================================================================================================== */
  
                execute procedure PRD_PYMALMA04_INSERT :id_pymalma01, :id_pymalma02,  :id_sicingr95;

                /* ========================================================================================================================================== */

                insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                                     pymalma02_det_stock.rela_sicingr95,
                                                     pymalma02_det_stock.rela_socsyst10_stk01,
                                                     pymalma02_det_stock.pymalma02_cantidad )
                values( :id_pymalma01_apartado,
                            :id_sicingr95,
                            :id_socsyst10_stk_mas,
                            :pymvent71_cantidad );
        
                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
                INTO :id_pymalma02_apartado;

                /* ========================================================================================================================================== */

                insert into pymalma03_dep_referencia( pymalma03_dep_referencia.rela_pymalma02,
                                                          pymalma03_dep_referencia.rela_pymvent71 )
                values( :id_pymalma02_apartado,
                            :id_pymvent71 );
        
                /* ========================================================================================================================================== */

                execute procedure PRD_PYMALMA04_INSERT :id_pymalma01_apartado, :id_pymalma02_apartado,  :id_sicingr95;

                /* ========================================================================================================================================== */
            end

        end
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_PYMVENT51; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'PYMVENT51',
            :nID; 
END
^


