/* Trigger: TID_PYMVENT55 */
CREATE OR ALTER TRIGGER TID_PYMVENT55 FOR PYMVENT55_MOV_MOVENTSAL
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
DECLARE VARIABLE id_pymvent55 BIGINT;
declare variable pymvent70_neto double precision;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_PYMVENT55 = GEN_ID(SID_PYMVENT55,1); 
        cTipo = 'A'; 
        nID = NEW.ID_PYMVENT55;

        if (NEW.rela_pymvent70 IS NOT NULL AND NEW.pymvent55_entsal IS NOT NULL) then
        BEGIN
            id_pymvent55 = NULL;

            select first 1 pymvent55_mov_moventsal.id_pymvent55
            from pymvent55_mov_moventsal
            where pymvent55_mov_moventsal.rela_pymvent70 = new.rela_pymvent70
            and pymvent55_mov_moventsal.pymvent55_importe < 0
            into :id_pymvent55;

            if (id_pymvent55 IS NULL) then
            BEGIN
                select pymvent70_cab_ticket.pymvent70_neto
                from pymvent70_cab_ticket
                where pymvent70_cab_ticket.id_pymvent70 = new.rela_pymvent70
                into :pymvent70_neto;

                insert into pymvent55_mov_moventsal( pymvent55_mov_moventsal.rela_pymvent50,
                                                     pymvent55_mov_moventsal.rela_socusua30,
                                                     pymvent55_mov_moventsal.rela_pymvent70,
                                                     pymvent55_mov_moventsal.pymvent55_importe,
                                                     pymvent55_mov_moventsal.pymvent55_pagoticket,
                                                     pymvent55_mov_moventsal.pymvent55_notas )
                values( new.rela_pymvent50,
                        new.rela_socusua30,
                        new.rela_pymvent70,
                        :pymvent70_neto * (-1),
                        new.pymvent55_pagoticket,
                        new.pymvent55_notas );
            END
        END
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_PYMVENT55; 
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_PYMVENT55; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'PYMVENT55',
            :nID; 
END
^


