/* Trigger: TID_PYMVENT60_FCIERRE */
CREATE OR ALTER TRIGGER TID_PYMVENT60_FCIERRE FOR PYMVENT60_CAB_COBRO
ACTIVE AFTER INSERT POSITION 0
AS
declare variable rela_socmain01 bigint;
declare variable rela_socmain21 bigint;
declare variable id_pymalma01 bigint;
declare variable id_pymalma02 bigint;
declare variable id_socsyst10_stk bigint;
declare variable rela_pymvent70 bigint;
declare variable id_pymvent71 bigint;
declare variable id_sicingr95 bigint;
declare variable pymvent71_cantidad double precision;
declare variable pymvent51_diasapartado integer;
declare variable rela_socmain21_apartados bigint;

begin
    update pymvent51_det_ventas set pymvent51_det_ventas.pymvent51_fcerrado = current_timestamp
    where pymvent51_det_ventas.id_pymvent51 = new.rela_pymvent51;

    /* ========================================================================================================================================== */
    /* ========================================================================================================================================== */

    select
    pymvent50_cab_apertura.rela_socmain01,
    pymvent50_cab_apertura.rela_socmain21,
    pymvent51_det_ventas.rela_pymvent70,
    pymvent51_det_ventas.pymvent51_diasapartado
    from pymvent51_det_ventas
    inner join pymvent50_cab_apertura on (pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50)
    where pymvent51_det_ventas.id_pymvent51 = new.rela_pymvent51
    into :rela_socmain01,
         :rela_socmain21,
         :rela_pymvent70,
         :pymvent51_diasapartado;

    /* ========================================================================================================================================== */

    id_pymalma01 = null;

    if (pymvent51_diasapartado = 0) then
    begin
        select
        pymalma01_cab_stock.id_pymalma01
        from pymalma01_cab_stock
        where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
        and pymalma01_cab_stock.rela_socmain21 = : rela_socmain21
        into :id_pymalma01;
    end
    else
    begin
        select
        pymvent51_det_ventas.rela_socmain21_apartados
        from pymvent51_det_ventas
        where pymvent51_det_ventas.id_pymvent51 = new.rela_pymvent51
        into :rela_socmain21_apartados;

        select
        pymalma01_cab_stock.id_pymalma01
        from pymalma01_cab_stock
        where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
        and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21_apartados
        into :id_pymalma01;
    end

    /* ========================================================================================================================================== */

    if (id_pymalma01 is not null) then
    begin
        if (pymvent51_diasapartado = 0) then
            select
            CBO_SOCSYST10_STK01.id_socsyst10
            from CBO_SOCSYST10_STK01
            where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK-PTOVTA-DESCUENTO'
            into :id_socsyst10_stk;
        else
            select
            CBO_SOCSYST10_STK01.id_socsyst10
            from CBO_SOCSYST10_STK01
            where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK_AUTO-APARTADO-MENOS'
            into :id_socsyst10_stk;

        /* ========================================================================================================================================== */
    
        for select
        pymvent71_det_ticket.id_pymvent71,
        pymvent71_det_ticket.rela_sicingr95,
        pymvent71_det_ticket.pymvent71_cantidad
        from pymvent71_det_ticket
        where pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
        and pymvent71_det_ticket.pymvent71_cancelado = 0
        into :id_pymvent71,
             :id_sicingr95,
             :pymvent71_cantidad
        do
        begin
            insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                             pymalma02_det_stock.rela_sicingr95,
                                             pymalma02_det_stock.rela_socsyst10_stk01,
                                             pymalma02_det_stock.pymalma02_cantidad )
            values( :id_pymalma01,
                    :id_sicingr95,
                    :id_socsyst10_stk,
                    :pymvent71_cantidad * (-1) );
    
            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
            INTO :id_pymalma02;
    
            /* ========================================================================================================================================== */
    
            insert into pymalma03_dep_referencia( pymalma03_dep_referencia.rela_pymalma02,
                                                  pymalma03_dep_referencia.rela_pymvent71 )
            values( :id_pymalma02,
                    :id_pymvent71 );

            update pymvent16_det_xreglas_p
            set pymvent16_det_xreglas_p.pymvent16_stock_cont = (pymvent16_det_xreglas_p.pymvent16_stock + :pymvent71_cantidad)
            where pymvent16_det_xreglas_p.rela_sicingr95 = :id_sicingr95;

    
            /* ========================================================================================================================================== */
    
            execute procedure PRD_PYMALMA04_INSERT :id_pymalma01, :id_pymalma02,  :id_sicingr95;
    
        end
    end
end
^


