/* Trigger: TID_PYMVENT61_MONEDERO */
CREATE OR ALTER TRIGGER TID_PYMVENT61_MONEDERO FOR PYMVENT61_DET_COBRO
ACTIVE AFTER INSERT POSITION 0
AS

declare variable codigo varchar(50);
declare variable rela_sicingr01 bigint;
declare variable rela_pymvent50 bigint;
declare variable rela_pymvent70 bigint;
declare variable rela_socusua30 bigint;

begin
    select cbo_socsyst10_fdp01.socsyst10_codigo
    from cbo_socsyst10_fdp01
    where cbo_socsyst10_fdp01.id_socsyst10 = new.rela_socsyst10_fdp01
    into :codigo;

    if (codigo = '05' or codigo = '99') then
    begin
        select
        pymvent70_cab_ticket.rela_sicingr01,
        pymvent51_det_ventas.rela_pymvent50,
        pymvent70_cab_ticket.id_pymvent70
        from pymvent60_cab_cobro
        inner join pymvent51_det_ventas on ( pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51 )
        inner join pymvent70_cab_ticket on ( pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70 )
        where pymvent60_cab_cobro.id_pymvent60 = new.rela_pymvent60
        into :rela_sicingr01,
             :rela_pymvent50,
             :rela_pymvent70;

        select sicingr01_cab_clientes.rela_socusua30
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
        into :rela_socusua30;
    end

    if (codigo = '05' and rela_socusua30 is not null) then
    begin
