/* Trigger: TID_PYMVENT62 */
CREATE OR ALTER TRIGGER TID_PYMVENT62 FOR PYMVENT62_DEP_FACTURACION
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
declare variable rela_sicingr01 BIGINT;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_PYMVENT62 = GEN_ID(SID_PYMVENT62,1); 
        cTipo = 'A'; 
        nID = NEW.ID_PYMVENT62; 

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_met01, 'MET01')
        into new.rela_socsyst10_met01;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ucf01, 'UCF01')
        into new.rela_socsyst10_ucf01;
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_PYMVENT62; 

        if ((old.rela_socsyst10_met01 <> new.rela_socsyst10_met01) or (old.rela_socsyst10_met01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_met01, 'MET01')
            into new.rela_socsyst10_met01;
        end

        if ((old.rela_socsyst10_ucf01 <> new.rela_socsyst10_ucf01) or (old.rela_socsyst10_ucf01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ucf01, 'UCF01')
            into new.rela_socsyst10_ucf01;
        end

        if (old.rela_sicingr70 is not null and (old.pymvent62_cancelado = 1 and new.pymvent62_cancelado = 0)) then
        begin
            select pymvent70_cab_ticket.rela_sicingr01
            from pymvent70_cab_ticket
            where pymvent70_cab_ticket.id_pymvent70 = new.rela_pymvent70
            into :rela_sicingr01;

            update sicingr70_cab_facturacion set sicingr70_cab_facturacion.rela_sicingr01 = :rela_sicingr01
            where sicingr70_cab_facturacion.id_sicingr70 = old.rela_sicingr70;
        end
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_PYMVENT62; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'PYMVENT62',
            :nID; 
END
^


