/* Trigger: TID_SICCONT02 */
CREATE OR ALTER TRIGGER TID_SICCONT02 FOR SICCONT02_ARB_PLANCTAS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT;
declare variable rela_old bigint;
declare variable rela_new bigint;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICCONT02 = GEN_ID(SID_SICCONT02,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICCONT02; 

        execute procedure smx$soc_arboles new.rela_siccont01,
                                              'SICCONT02',
                                              new.rela_siccont02
        returning_values new.rela_socsyst06,
                         new.siccont02_codigo;
    END
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICCONT02; 
        rela_old = old.rela_siccont02;
        rela_new = new.rela_siccont02;

        if (rela_old is null) then
            rela_old = 0;

        if (rela_new is null) then
            rela_new = 0;

        if (rela_old <> rela_new) then
            execute procedure smx$soc_arboles new.rela_siccont01,
                                              'SICCONT02',
                                              new.rela_siccont02
            returning_values new.rela_socsyst06,
                             new.siccont02_codigo;

    END
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICCONT02; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICCONT02',
            :nID; 
END
^


