/* Trigger: TID_SICCONT10_DELETE */
CREATE OR ALTER TRIGGER TID_SICCONT10_DELETE FOR SICCONT10_CAB_POLIZAS
ACTIVE AFTER DELETE POSITION 0
AS
declare variable rela_sicegre51 BIGINT;
declare variable rela_sicingr51 BIGINT;
declare variable rela_sicnomi51 BIGINT;
declare variable socsyst10_codigo varchar(50);
declare variable id_sicingr50 BIGINT;
declare variable sicingr52_importe DOUBLE precision;

begin
    delete from sicxmls41_det_migracion
    where sicxmls41_det_migracion.rela_siccont10 = old.id_siccont10;

    rela_sicegre51 = NULL;

    /* -------------------------------------------------------------------------------- */
    /* -------------------------------------------------------------------------------- */

    select  FIRST 1 SICEGRE50_DET_CTACTE.rela_sicegre51
    from SICEGRE50_DET_CTACTE
    where SICEGRE50_DET_CTACTE.rela_siccont10 = old.id_siccont10
    into :rela_sicegre51;

    if (rela_sicegre51 IS NOT NULL) then
    begin
        delete from sicegre51_cab_bancos
        where sicegre51_cab_bancos.id_sicegre51 = :rela_sicegre51;
    end

    /* -------------------------------------------------------------------------------- */
    /* -------------------------------------------------------------------------------- */

    select  FIRST 1
    SICINGR50_DET_CTACTE.id_sicingr50,
    SICINGR50_DET_CTACTE.rela_sicingr51
    from SICINGR50_DET_CTACTE
    where SICINGR50_DET_CTACTE.rela_siccont10 = old.id_siccont10
    into :id_sicingr50,
         :rela_sicingr51;

    if (rela_sicingr51 IS NOT NULL) then
    begin
        delete from sicingr51_cab_bancos
        where sicingr51_cab_bancos.id_sicingr51 = :rela_sicingr51;
    end

    /* -------------------------------------------------------------------------------- */
    /* -------------------------------------------------------------------------------- */

    select  FIRST 1 SICNOMI50_DET_CTACTE.rela_sicnomi51
    from SICNOMI50_DET_CTACTE
    where SICNOMI50_DET_CTACTE.rela_siccont10 = old.id_siccont10
    into :rela_sicnomi51;

    if (rela_sicnomi51 IS NOT NULL) then
    begin
        delete from sicnomi51_cab_bancos
        where sicnomi51_cab_bancos.id_sicnomi51 = :rela_sicnomi51;
    end

    /* -------------------------------------------------------------------------------- */
    /* -------------------------------------------------------------------------------- */

    select socsyst10_det_entradas.socsyst10_codigo
    from socsyst10_det_entradas
    where socsyst10_det_entradas.id_socsyst10 = old.rela_socsyst10_ctp01
    into :socsyst10_codigo;

    if (socsyst10_codigo = 'DROPZONE-ANTI-CLIENTE') then
    begin
        select sicingr54_dep_anticipos.rela_sicingr51
        from sicingr54_dep_anticipos
        where sicingr54_dep_anticipos.rela_siccont10 = old.id_siccont10
        into :rela_sicingr51;

        delete from sicingr51_cab_bancos where sicingr51_cab_bancos.id_sicingr51 = :rela_sicingr51;
    end
    else if (socsyst10_codigo = 'BANCOS-GASTOS3ROS') then
    begin
        select first 1
        sicingr52_det_bancos.rela_sicingr51,
        sicingr52_det_bancos.sicingr52_importe
        from sicingr52_det_bancos
        where sicingr52_det_bancos.rela_sicingr50 = :id_sicingr50
        into :rela_sicingr51,
             :sicingr52_importe;

         delete from sicingr52_det_bancos where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
            and cast(sicingr52_det_bancos.sicingr52_importe as numeric(15,3)) =
                cast(:sicingr52_importe * (-1) as numeric(15,3));
    end
end
^


/* Trigger: TID_SICCONT10_UPDATE */
CREATE OR ALTER TRIGGER TID_SICCONT10_UPDATE FOR SICCONT10_CAB_POLIZAS
ACTIVE AFTER INSERT OR UPDATE POSITION 0
AS
begin
    UPDATE siccont11_det_polizas
    SET siccont11_det_polizas.siccont11_ano = extract(year from new.siccont10_fcta),
        siccont11_det_polizas.siccont11_mes = extract(month from new.siccont10_fcta)
    where siccont11_det_polizas.rela_siccont10 = new.id_siccont10;
end
^


/* Trigger: TID_SICCONT11 */
CREATE OR ALTER TRIGGER TID_SICCONT11 FOR SICCONT11_DET_POLIZAS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
declare variable fcta DATE;
declare variable siccont10_cotiza double precision;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICCONT11 = GEN_ID(SID_SICCONT11,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICCONT11; 
    END
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICCONT11; 
        END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICCONT11; 
    END 

    IF (INSERTING or UPDATING ) THEN
    begin
        if (new.siccont11_nocotiza is null) then
            new.siccont11_nocotiza = 0;

        select
        siccont10_cab_polizas.siccont10_fcta,
        siccont10_cab_polizas.siccont10_cotiza
        from siccont10_cab_polizas
        where siccont10_cab_polizas.id_siccont10 = new.rela_siccont10
        INTO :fcta,
             :siccont10_cotiza;
    
        NEW.siccont11_ano = EXTRACT(YEAR FROM :fcta);
        NEW.siccont11_mes = EXTRACT(month FROM :fcta);

        if (new.siccont11_nocotiza = 0) then
        begin
            if (new.siccont11_debe <> 0) then
                new.siccont11_debe = new.siccont11_debe * :siccont10_cotiza;
        
            if (new.siccont11_haber <> 0) then
                new.siccont11_haber = new.siccont11_haber * :siccont10_cotiza;
        end

        /* ------------------------------------------------------------------ */

        if (new.siccont11_debe < 0) then
        begin
            new.siccont11_haber = new.siccont11_debe * (-1);
            new.siccont11_debe = 0;
        end
        else if (new.siccont11_haber < 0) then
        begin
            new.siccont11_debe = new.siccont11_haber * (-1);
            new.siccont11_haber = 0;
        end
    end

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICCONT11',
            :nID; 
END
^


