/* Trigger: TID_SICINGR70 */
CREATE OR ALTER TRIGGER TID_SICINGR70 FOR SICINGR70_CAB_FACTURACION
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
DECLARE VARIABLE SOCSYST10_CODIGO_borra varchar(50);

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICINGR70 = GEN_ID(SID_SICINGR70,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICINGR70; 

        /* -------------------------------------------------------------------------------------------------------------- */

        Select smx$soc_contadores.nrodoc, smx$soc_contadores.serie
        from smx$soc_contadores(new.rela_socmain01, new.rela_socmain21, :nid, 'SICINGR70')
        into new.sicingr70_docnro, new.sicingr70_serie;

        /* -------------------------------------------------------------------------------------------------------------- */

        new.sicingr70_status = 'Pendiente por Timbrar';

        /* -------------------------------------------------------------------------------------------------------------- */
        /* -------------------------------------------------------------------------------------------------------------- */

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ctm01, 'CTM01')
        into new.rela_socsyst10_ctm01;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_fdp01, 'FDP01')
        into new.rela_socsyst10_fdp01;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_tcp01, 'TCP01')
        into new.rela_socsyst10_tcp01;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_met01, 'MET01')
        into new.rela_socsyst10_met01;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ucf01, 'UCF01')
        into new.rela_socsyst10_ucf01;
    END
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICINGR70;

         /* -------------------------------------------------------------------------------------------------------------- */

         if (old.rela_socsyst10 <> new.rela_socsyst10) then
         begin
            select CBO_SOCSYST10_FFS01.SOCSYST10_CODIGO
            from CBO_SOCSYST10_FFS01
            where CBO_SOCSYST10_FFS01.ID_SOCSYST10 = old.rela_socsyst10
            into :SOCSYST10_CODIGO_borra;

            if (socsyst10_codigo_borra = 'SICINGR70-CPORTE') then
                delete from sicingr81_cab_transporte where sicingr81_cab_transporte.rela_sicingr70 = :nID;

            else if (socsyst10_codigo_borra = 'SICINGR70-GASTOS3ROS') then
                delete from sicingr88_det_gastos3ros where sicingr88_det_gastos3ros.rela_sicingr70 = :nID;

         end

        /* -------------------------------------------------------------------------------------------------------------- */

        if (new.sicingr70_status = 'En proceso de Timbrar') then
        begin
            insert into SICINGR80_MOV_PROCESOS( SICINGR80_MOV_PROCESOS.rela_sicingr70,
                                                SICINGR80_MOV_PROCESOS.sicingr80_flag,
                                                SICINGR80_MOV_PROCESOS.sicingr80_usuario)
            values(old.id_sicingr70, 0, current_user);
        end
        else if (new.sicingr70_status <> 'ERROR. Se Cancela Proceso Masivo de Timbrado') then
        begin
            update sicingr80_mov_procesos set sicingr80_mov_procesos.sicingr80_flag = 1
            where sicingr80_mov_procesos.rela_sicingr70 = old.id_sicingr70;

            delete from sicingr80_mov_procesos where sicingr80_mov_procesos.rela_sicingr70 = old.id_sicingr70;
        end

        /* -------------------------------------------------------------------------------------------------------------- */
        /* -------------------------------------------------------------------------------------------------------------- */

        if ((old.rela_socsyst10_ctm01 <> new.rela_socsyst10_ctm01) or (old.rela_socsyst10_ctm01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ctm01, 'CTM01')
            into new.rela_socsyst10_ctm01;
        end

        if ((old.rela_socsyst10_fdp01 <> new.rela_socsyst10_fdp01) or (old.rela_socsyst10_fdp01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_fdp01, 'FDP01')
            into new.rela_socsyst10_fdp01;
        end

        if ((old.rela_socsyst10_tcp01 <> new.rela_socsyst10_tcp01) or (old.rela_socsyst10_tcp01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_tcp01, 'TCP01')
            into new.rela_socsyst10_tcp01;
        end

        if ((old.rela_socsyst10_met01 <> new.rela_socsyst10_met01) or (old.rela_socsyst10_met01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_met01, 'MET01')
            into new.rela_socsyst10_met01;
        end

        if ((old.rela_socsyst10_ucf01 <> new.rela_socsyst10_ucf01) or (old.rela_socsyst10_ucf01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ucf01, 'UCF01')
            into new.rela_socsyst10_ucf01;
        end
    END
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICINGR70; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICINGR70',
            :nID; 
END
^


