/* Trigger: TID_SICINGR72_DELETE */
CREATE OR ALTER TRIGGER TID_SICINGR72_DELETE FOR SICINGR75_DET_IMPUESTOS_WEB
ACTIVE AFTER DELETE POSITION 0
AS

DECLARE VARIABLE rela_sicingr72 BIGINT;
DECLARE VARIABLE update_si integer;

begin
    select count(SOCSYST01_CAB_FUNCIONES.id_socsyst01)
    from SOCSYST01_CAB_FUNCIONES
    where SOCSYST01_CAB_FUNCIONES.socsyst01_codigo = 'SOCSYST09'
    and SOCSYST01_CAB_FUNCIONES.socsyst01_activo = 1
    into :update_si;

    if (update_si = 1) then
    EXECUTE PROCEDURE prd_sicingr75_sicingr72
        'B',
        old.rela_sicingr71,
        old.rela_sicingr72,
        -1,
        0.0,
        '',
        0.0
    RETURNING_VALUES :rela_sicingr72;
end
^


