/* Trigger: TID_SICINGR75 */
CREATE OR ALTER TRIGGER TID_SICINGR75 FOR SICINGR75_DET_IMPUESTOS_WEB
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 
DECLARE VARIABLE rela_sicingr72 BIGINT;
DECLARE VARIABLE update_si integer;

BEGIN 
    select count(SOCSYST01_CAB_FUNCIONES.id_socsyst01)
    from SOCSYST01_CAB_FUNCIONES
    where SOCSYST01_CAB_FUNCIONES.socsyst01_codigo = 'SOCSYST09'
    and SOCSYST01_CAB_FUNCIONES.socsyst01_activo = 1
    into :update_si;

    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICINGR75 = GEN_ID(SID_SICINGR75,1);
        cTipo = 'A'; 
        nID = NEW.ID_SICINGR75; 

        if (update_si = 1) then
        EXECUTE PROCEDURE prd_sicingr75_sicingr72
            cTipo,
            new.rela_sicingr71,
            -1,
            new.rela_socsyst10_sat10,
            new.sicingr75_porcentaje,
            new.sicingr75_implocal,
            new.sicingr75_total
        RETURNING_VALUES new.rela_sicingr72;

    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICINGR75; 

        if (update_si = 1) then
        EXECUTE PROCEDURE prd_sicingr75_sicingr72
            cTipo,
            old.rela_sicingr71,
            old.rela_sicingr72,
            new.rela_socsyst10_sat10,
            new.sicingr75_porcentaje,
            new.sicingr75_implocal,
            new.sicingr75_total
        RETURNING_VALUES :rela_sicingr72;
    END
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICINGR75; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICINGR75',
            :nID; 
END
^


