/* Trigger: TID_SICINGR77_RELACIONCFDI */
CREATE OR ALTER TRIGGER TID_SICINGR77_RELACIONCFDI FOR SICINGR77_DET_CFDISCANCELADOS
ACTIVE AFTER INSERT POSITION 0
AS

declare variable id_socsyst10_tre01 bigint;
declare variable id_sicingr73 bigint;

begin
    update PYMVENT62_DEP_FACTURACION set PYMVENT62_DEP_FACTURACION.pymvent62_cancelado = 1
    where PYMVENT62_DEP_FACTURACION.rela_sicingr70 = new.rela_sicingr70;

    select
    cbo_socsyst10_tre01.id_socsyst10
    from cbo_socsyst10_tre01
    where cbo_socsyst10_tre01.socsyst10_codigo = '04'
    into :id_socsyst10_tre01;

    id_sicingr73 = null;

    select
    sicingr73_det_relacionados.id_sicingr73
    from sicingr73_det_relacionados
    where sicingr73_det_relacionados.rela_sicingr70 = new.rela_sicingr70
    and sicingr73_det_relacionados.rela_socsyst10_tre01 = :id_socsyst10_tre01
    into :id_sicingr73;

    if (id_sicingr73 is null) then
        insert into sicingr73_det_relacionados(sicingr73_det_relacionados.rela_sicingr70,
                                               sicingr73_det_relacionados.rela_socsyst10_tre01,
                                               sicingr73_det_relacionados.rela_sicingr77 )
        values(new.rela_sicingr70,
               :id_socsyst10_tre01,
               new.id_sicingr77);
    else
        update sicingr73_det_relacionados set sicingr73_det_relacionados.rela_sicingr77 = new.id_sicingr77
        where sicingr73_det_relacionados.id_sicingr73 = :id_sicingr73;
end
^


