/* Trigger: TID_SICINGR95 */
CREATE OR ALTER TRIGGER TID_SICINGR95 FOR SICINGR95_CAB_CONCEPTOS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT;
DECLARE VARIABLE rela_socmain01 BIGINT;

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICINGR95 = GEN_ID(SID_SICINGR95,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICINGR95; 

        if (new.sicingr95_codigo = 'SMXAUTO') then
            new.sicingr95_codigo = 'SMXAUTO' || nID;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_cum01, 'CUM01')
        into new.rela_socsyst10_cum01;

        select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
        from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_cpo01, 'CPO01')
        into new.rela_socsyst10_cpo01;

        if (new.rela_socsyst10_ctm01 is not null) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ctm01, 'CTM01')
            into new.rela_socsyst10_ctm01;
        end

        if (new.rela_pymalma01 is null) then
        begin
            select sicxmls01_cab_parametros.rela_socmain01
            from sicxmls01_cab_parametros
            where sicxmls01_cab_parametros.id_sicxmls01 = new.rela_sicxmls01
            into :rela_socmain01;

            select max(PYMALMA01_CAB_STOCK.id_pymalma01)
            from PYMALMA01_CAB_STOCK
            where PYMALMA01_CAB_STOCK.rela_socmain01 = :rela_socmain01
            into new.rela_pymalma01;
        end
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICINGR95; 

        if ((old.rela_socsyst10_cum01 <> new.rela_socsyst10_cum01) or (old.rela_socsyst10_cum01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_cum01, 'CUM01')
            into new.rela_socsyst10_cum01;
        end

        if ((old.rela_socsyst10_cpo01 <> new.rela_socsyst10_cpo01) or (old.rela_socsyst10_cpo01 is null)) then
        begin
            select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
            from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_cpo01, 'CPO01')
            into new.rela_socsyst10_cpo01;
        end

        if (new.rela_socsyst10_ctm01 is not null) then
        begin
            if ((old.rela_socsyst10_ctm01 <> new.rela_socsyst10_ctm01) or (old.rela_socsyst10_ctm01 is null)) then
            begin
                select SMX$SOC_SOCSYST10_UPDATE_REMOTO.id_socsyst10_reto
                from SMX$SOC_SOCSYST10_UPDATE_REMOTO(new.rela_socsyst10_ctm01, 'CTM01')
                into new.rela_socsyst10_ctm01;
            end
        end
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICINGR95; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICINGR95',
            :nID; 
END
^


/* Trigger: TID_SICINGR95_SICINGR98 */
CREATE OR ALTER TRIGGER TID_SICINGR95_SICINGR98 FOR SICINGR95_CAB_CONCEPTOS
ACTIVE AFTER UPDATE POSITION 0
AS
declare variable id_socsyst10_stk01_neteo bigint;
declare variable id_socsyst10_stk01_nuevo bigint;
declare variable total_stock double precision;
declare variable actual_stock double precision;
declare variable rela_socmain01 bigint;
declare variable id_socsyst10_mli01 bigint;

begin
    select CBO_SOCSYST10_MLI01.id_socsyst10
    from CBO_SOCSYST10_MLI01
    where CBO_SOCSYST10_MLI01.socsyst10_codigo = 'CONCEP-REF'
    into :id_socsyst10_mli01;

    update sicingr98_det_importes set sicingr98_det_importes.sicingr98_importe = new.sicingr95_importe
    where sicingr98_det_importes.rela_sicingr95 = new.id_sicingr95
    and sicingr98_det_importes.rela_socsyst10_mli01 = :id_socsyst10_mli01;

    if (coalesce(old.sicingr95_stock, 0) = coalesce(new.sicingr95_stock, 0)) then
    exit;

    select sicxmls01_cab_parametros.rela_socmain01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.id_sicxmls01 = new.rela_sicxmls01
    into :rela_socmain01;

    Select GRD_PYMALMA01_WEB.stock
    from GRD_PYMALMA01_WEB(:rela_socmain01, new.id_sicingr95)
    where GRD_PYMALMA01_WEB.id_pymalma01 = new.rela_pymalma01
    into :actual_stock;

    if (new.sicingr95_stock = actual_stock) then
    begin
        exit;
    end

    select CBO_SOCSYST10_STK01.id_socsyst10
    from CBO_SOCSYST10_STK01
    where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK-AUTO-NETEO-SICINGR95'
    into :id_socsyst10_stk01_neteo;

    select CBO_SOCSYST10_STK01.id_socsyst10
    from CBO_SOCSYST10_STK01
    where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK-AUTO-NUEVO-SICINGR95'
    into :id_socsyst10_stk01_nuevo;

    select coalesce(sum(pymalma02_det_stock.pymalma02_cantidad), 0)
    from pymalma02_det_stock
    where pymalma02_det_stock.rela_pymalma01 = new.rela_pymalma01
    and pymalma02_det_stock.rela_sicingr95 = new.id_sicingr95
    into :total_stock;

    if (coalesce(new.sicingr95_stock, 0) = 0) then
    begin
        if (total_stock != 0) then
        begin
            insert into pymalma02_det_stock (
                    rela_pymalma01,
                    rela_sicingr95,
                    rela_socsyst10_stk01,
                    pymalma02_cantidad)
            values (
                    new.rela_pymalma01,
                    new.id_sicingr95,
                    :id_socsyst10_stk01_neteo,
                    :total_stock * (-1));
        end
    end
    else
    begin
        if (total_stock != 0) then
        begin
            insert into pymalma02_det_stock (
                        rela_pymalma01,
                        rela_sicingr95,
                        rela_socsyst10_stk01,
                        pymalma02_cantidad)
            values (
                        new.rela_pymalma01,
                        new.id_sicingr95,
                        :id_socsyst10_stk01_neteo,
                        :total_stock * (-1));
        end
        
        insert into pymalma02_det_stock (
                    rela_pymalma01,
                    rela_sicingr95,
                    rela_socsyst10_stk01,
                    pymalma02_cantidad)
        values (
                    new.rela_pymalma01,
                    new.id_sicingr95,
                    :id_socsyst10_stk01_nuevo,
                    new.sicingr95_stock);
    end
end
^


