/* Trigger: TID_SICNOMI70 */
CREATE OR ALTER TRIGGER TID_SICNOMI70 FOR SICNOMI70_CAB_NOMINA
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICNOMI70 = GEN_ID(SID_SICNOMI70,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICNOMI70; 

        Select smx$soc_contadores.nrodoc, smx$soc_contadores.serie
        from smx$soc_contadores(new.rela_socmain01, new.rela_socmain21, :nid, 'SICNOMI70')
        into new.sicnomi70_docnro, new.sicnomi70_serie;

        new.sicnomi70_status = 'Pendiente por Timbrar';
    END 
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICNOMI70; 

        if (new.sicnomi70_status = 'En proceso de Timbrar') then
        begin
            insert into SICNOMI80_MOV_PROCESOS( SICNOMI80_MOV_PROCESOS.rela_sicnomi70,
                                                SICNOMI80_MOV_PROCESOS.sicnomi80_flag,
                                                SICNOMI80_MOV_PROCESOS.sicnomi80_usuario)
            values(old.id_sicnomi70, 0, current_user);
        end
        else if (new.sicnomi70_status <> 'ERROR. Se Cancela Proceso Masivo de Timbrado') then
        begin
            update sicnomi80_mov_procesos set sicnomi80_mov_procesos.sicnomi80_flag = 1
            where sicnomi80_mov_procesos.rela_sicnomi70 = old.id_sicnomi70;

            delete from sicnomi80_mov_procesos where sicnomi80_mov_procesos.rela_sicnomi70 = old.id_sicnomi70;
        end

    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICNOMI70; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICNOMI70',
            :nID; 
END
^


/* Trigger: TID_SICNOMI71 */
CREATE OR ALTER TRIGGER TID_SICNOMI71 FOR SICNOMI71_DET_NOMINA
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICNOMI71 = GEN_ID(SID_SICNOMI71,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICNOMI71; 

        select sicxmls05_det_nomina.sicxmls05_tipo
        from sicxmls05_det_nomina
        where sicxmls05_det_nomina.id_sicxmls05 = new.rela_sicxmls05
