/* Trigger: TID_SICPAGO70 */
CREATE OR ALTER TRIGGER TID_SICPAGO70 FOR SICPAGO70_CAB_PAGO
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID BIGINT; 

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SICPAGO70 = GEN_ID(SID_SICPAGO70,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SICPAGO70; 

        Select smx$soc_contadores.nrodoc, smx$soc_contadores.serie
        from smx$soc_contadores(new.rela_socmain01, new.rela_socmain21, :nid, 'SICPAGO70')
        into new.sicpago70_docnro, new.sicpago70_serie;

        new.sicpago70_status = 'Pendiente por Timbrar';
    END
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SICPAGO70; 

         if (new.sicpago70_status = 'En proceso de Timbrar') then
        begin
            insert into SICPAGO80_MOV_PROCESOS( SICPAGO80_MOV_PROCESOS.rela_sicpago70,
                                                SICPAGO80_MOV_PROCESOS.sicpago80_flag,
                                                SICPAGO80_MOV_PROCESOS.sicpago80_usuario)
            values(old.id_sicpago70, 0, current_user);
        end
        else if (new.sicpago70_status <> 'ERROR. Se Cancela Proceso Masivo de Timbrado') then
        begin
            update sicpago80_mov_procesos set sicpago80_mov_procesos.sicpago80_flag = 1
            where sicpago80_mov_procesos.rela_sicpago70 = old.id_sicpago70;

            delete from sicpago80_mov_procesos where sicpago80_mov_procesos.rela_sicpago70 = old.id_sicpago70;
        end
    END 
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SICPAGO70; 
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SICPAGO70',
            :nID; 
END
^


