/* Trigger: TID_SOCMAIN21 */
CREATE OR ALTER TRIGGER TID_SOCMAIN21 FOR SOCMAIN21_ARB_ORGANIZACION
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID bigint;
declare variable rela_old bigint;
declare variable rela_new bigint;

BEGIN 
    IF (INSERTING) THEN
    BEGIN 
        NEW.ID_SOCMAIN21 = GEN_ID(SID_SOCMAIN21,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SOCMAIN21; 

        if (new.rela_socmain80 is not null) then
        begin
            select smx$soc_socmain80_update_remoto.id_socmain80_reto
            from smx$soc_socmain80_update_remoto(new.rela_socmain80)
            into new.rela_socmain80;
        end

        execute procedure smx$soc_arboles new.rela_socmain20,
                                          'SOCMAIN21',
                                          new.rela_socmain21
        returning_values new.rela_socsyst06,
                         new.socmain21_codigo;
    END
    ELSE IF (UPDATING) THEN 
    BEGIN
        cTipo = 'M'; 
        nID = OLD.ID_SOCMAIN21; 

        if (new.rela_socmain80 is not null) then
        begin
            if ((old.rela_socmain80 <> new.rela_socmain80) or (old.rela_socmain80 is null)) then
            begin
                select smx$soc_socmain80_update_remoto.id_socmain80_reto
                from smx$soc_socmain80_update_remoto(new.rela_socmain80)
                into new.rela_socmain80;
            end
        end

        rela_old = old.rela_socmain21;
        rela_new = new.rela_socmain21;

        if (rela_old is null) then
            rela_old = 0;

        if (rela_new is null) then
            rela_new = 0;

        if (rela_old <> rela_new) then
            execute procedure smx$soc_arboles new.rela_socmain20,
                                              'SOCMAIN21',
                                              new.rela_socmain21
            returning_values new.rela_socsyst06,
                             new.socmain21_codigo;

    END
    ELSE
    BEGIN
        cTipo = 'B'; 
        nID = OLD.ID_SOCMAIN21; 
    END

    EXECUTE PROCEDURE smx$db_util_logs 
                      CURRENT_USER,
                      :cTipo,
                      'SOCMAIN21',
                      :nID; 
END
^


