/* Trigger: TID_SOCUSUA01 */
CREATE OR ALTER TRIGGER TID_SOCUSUA01 FOR SOCUSUA01_CAB_USUARIOS
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID INTEGER; 
DECLARE VARIABLE status_seguridad varchar(50);

BEGIN 
    IF (INSERTING) THEN 
    BEGIN 
        NEW.ID_SOCUSUA01 = GEN_ID(SID_SOCUSUA01,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SOCUSUA01; 

        if (new.socusua01_acceso = 1) then
            execute procedure smx$soc_seguridad 'ALTA', new.socusua01_usuario, new.socusua01_clave
            returning_values status_seguridad;
    END
    ELSE IF (UPDATING) THEN 
    BEGIN 
        cTipo = 'M'; 
        nID = OLD.ID_SOCUSUA01; 

        if (old.socusua01_acceso = 0 and new.socusua01_acceso = 1) then
            execute procedure smx$soc_seguridad 'ALTA', new.socusua01_usuario, new.socusua01_clave
            returning_values status_seguridad;

        else if (old.socusua01_acceso = 1 and new.socusua01_acceso = 0) then
            execute procedure smx$soc_seguridad 'BAJA', old.socusua01_usuario, old.socusua01_clave
            returning_values status_seguridad;

        if (old.socusua01_clave <> new.socusua01_clave and old.socusua01_acceso = 1) then
            execute procedure smx$soc_seguridad 'MODI', new.socusua01_usuario, new.socusua01_clave
            returning_values status_seguridad;
    END
    ELSE 
    BEGIN 
        cTipo = 'B'; 
        nID = OLD.ID_SOCUSUA01; 
        
        execute procedure smx$soc_seguridad 'BAJA', old.socusua01_usuario, old.socusua01_clave
        returning_values status_seguridad;
    END 

    EXECUTE PROCEDURE smx$db_util_logs 
            CURRENT_USER, 
            :cTipo, 
            'SOCUSUA01',
            :nID; 
END
^


/* Trigger: TID_SOCUSUA01_INSERT */
CREATE OR ALTER TRIGGER TID_SOCUSUA01_INSERT FOR SOCUSUA01_CAB_USUARIOS
ACTIVE AFTER INSERT POSITION 0
AS

DECLARE VARIABLE rela_socsyst10_ca001 bigint;
DECLARE VARIABLE id_socmain01 bigint;
DECLARE VARIABLE id_socmain20 bigint;
DECLARE VARIABLE id_socmain21 bigint;

begin
    if (position('WEB_' in new.socusua02_codigo) != 0) then
    BEGIN
        select max(cbo_socsyst10_ca001.id_socsyst10)
        from cbo_socsyst10_ca001
        into :rela_socsyst10_ca001;

        select socmain01_cab_empresas.id_socmain01
        from socmain01_cab_empresas
        where socmain01_cab_empresas.rela_socusua30 = new.rela_socusua30
        into :id_socmain01;

        select SOCMAIN20_CAB_ORGANIZACION.id_socmain20
        from SOCMAIN20_CAB_ORGANIZACION
        where SOCMAIN20_CAB_ORGANIZACION.rela_socmain01 = :id_socmain01
        into :id_socmain20;

        select socmain21_arb_organizacion.id_socmain21
        from socmain21_arb_organizacion
        where socmain21_arb_organizacion.rela_socmain20 = :id_socmain20
        into :id_socmain21;

        insert into SOCUSUA02_DET_ORGANIZACION(SOCUSUA02_DET_ORGANIZACION.rela_socusua01,
                                               SOCUSUA02_DET_ORGANIZACION.rela_socmain01,
                                               SOCUSUA02_DET_ORGANIZACION.rela_socmain20,
                                               SOCUSUA02_DET_ORGANIZACION.rela_socmain21,
                                               SOCUSUA02_DET_ORGANIZACION.rela_socsyst10_ca001)
        values(new.id_socusua01,
               :id_socmain01,
               :id_socmain20,
               :id_socmain21,
               :rela_socsyst10_ca001);

        insert into socusua04_det_empresas(socusua04_det_empresas.rela_socusua01,
                                           socusua04_det_empresas.rela_socmain01)
        values(new.id_socusua01,
               :id_socmain01);
    END
end
^


