/* Trigger: TID_SOCUSUA11 */
CREATE OR ALTER TRIGGER TID_SOCUSUA11 FOR SOCUSUA11_ARB_MENU
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID INTEGER; 
declare variable rela_old bigint;
declare variable rela_new bigint;

BEGIN 
    IF (INSERTING) THEN
    BEGIN
        NEW.ID_SOCUSUA11 = GEN_ID(SID_SOCUSUA11,1); 
        cTipo = 'A'; 
        nID = NEW.ID_SOCUSUA11;

        execute procedure smx$soc_arboles new.rela_socusua10,
                                              'SOCUSUA11',
                                              new.rela_socusua11
        returning_values new.rela_socsyst06,
                         new.socusua11_codigo;
    END
    ELSE IF (UPDATING) THEN
    BEGIN
        cTipo = 'M'; 
        nID = OLD.ID_SOCUSUA11; 
        rela_old = old.rela_socusua11;
        rela_new = new.rela_socusua11;

        if (rela_old is null) then
            rela_old = 0;

        if (rela_new is null) then
            rela_new = 0;

        if (rela_old <> rela_new) then
            execute procedure smx$soc_arboles new.rela_socusua10,
                                              'SOCUSUA11',
                                              new.rela_socusua11
            returning_values new.rela_socsyst06,
                             new.socusua11_codigo;
    END
    ELSE
    BEGIN
        cTipo = 'B'; 
        nID = OLD.ID_SOCUSUA11; 
    END
    
    EXECUTE PROCEDURE smx$db_util_logs
          CURRENT_USER, 
          :cTipo, 
          'SOCUSUA11',
          :nID; 
END
^


