/* Trigger: TID_TMPCONT11 */
CREATE OR ALTER TRIGGER TID_TMPCONT11 FOR TMP_SICCONT11_BALANZA
ACTIVE BEFORE INSERT POSITION 0
as

declare variable ano_c varchar(4);
declare variable mes_c varchar(2);

begin
    new.id_tmpcont11 = gen_id(sid_tmpcont11,1);

    ano_c = cast(new.siccont11_ano as varchar(4));
    mes_c = cast(new.siccont11_mes as varchar(2));

    if (char_length(mes_c) = 1) then
        mes_c = '0' || mes_c;

    new.anomes = cast(ano_c || mes_c as integer);
end
