/* Trigger: TID_TMPXMLS41 */
CREATE OR ALTER TRIGGER TID_TMPXMLS41 FOR TMPXMLS41_TBL_UUIDS_RECIBIDOS
ACTIVE BEFORE INSERT POSITION 0
AS
declare variable id_sicxmls41 bigint;
declare variable id_sicxmls77 bigint;
begin
    id_sicxmls41 = null;
    NEW.id_tmpxmls41 = GEN_ID(SID_TMPXMLS41,1);

    EXECUTE PROCEDURE smx$db_util_logs 
                      CURRENT_USER, 
                      'A',
                      'TMPXMLS41',
                      NEW.id_tmpxmls41;

    select first 1
    sicxmls41_det_migracion.id_sicxmls41
    from sicxmls41_det_migracion
    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01)
    where sicxmls40_cab_migracion.rela_socmain01 = new.tmpxmls41_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'PROVE'
    and upper(sicxmls41_det_migracion.sicxmls41_uuid) = upper(new.tmpxmls41_uuid)
    into :id_sicxmls41;

    if (id_sicxmls41 is not null) then
    begin
        id_sicxmls77 = null;

        select
        sicxmls77_cab_porcancelar.id_sicxmls77
        from sicxmls77_cab_porcancelar
        where sicxmls77_cab_porcancelar.rela_socmain01 = new.tmpxmls41_socmain01
        and sicxmls77_cab_porcancelar.rela_sicxmls41 = :id_sicxmls41
        into :id_sicxmls77;

        if (id_sicxmls77 is null) then
            insert into sicxmls77_cab_porcancelar(sicxmls77_cab_porcancelar.rela_socmain01,
                                                  sicxmls77_cab_porcancelar.rela_sicxmls41,
                                                  sicxmls77_cab_porcancelar.sicxmls77_status)
            values(new.tmpxmls41_socmain01,
                   :id_sicxmls41,
                   new.tmpxmls41_status);
        else
            update sicxmls77_cab_porcancelar set sicxmls77_cab_porcancelar.sicxmls77_status = new.tmpxmls41_status
            where sicxmls77_cab_porcancelar.id_sicxmls77 = :id_sicxmls77;
    end
end
^


/* Trigger: TMPINGR95_TBL_REPLICACION_BIUD0 */
CREATE OR ALTER TRIGGER TMPINGR95_TBL_REPLICACION_BIUD0 FOR TMPINGR95_TBL_REPLICACION
ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0
AS 

DECLARE VARIABLE cTipo CHAR(1); 
DECLARE VARIABLE nID INTEGER; 

BEGIN 
  IF (INSERTING) THEN 
  BEGIN 
    NEW.id_tmpingr95 = GEN_ID(SID_TMPINGR95,1);
    cTipo = 'A'; 
    nID = NEW.id_tmpingr95;
  END 
  ELSE IF (UPDATING) THEN 
  BEGIN 
    cTipo = 'M'; 
    nID = OLD.id_tmpingr95;
    END 
  ELSE 
  BEGIN 
    cTipo = 'B'; 
    nID = OLD.id_tmpingr95;
  END 

  EXECUTE PROCEDURE smx$db_util_logs 
      CURRENT_USER, 
      :cTipo, 
      'TMPINGR95',
      :nID; 
END
^


