CREATE OR ALTER PROCEDURE ARB_SICCONT02 (
    RELA_SICCONT01X BIGINT)
RETURNS (
    RELA_SICCONT01 BIGINT,
    RELA_SOCSYST06 BIGINT,
    RELA_SICCONT02 BIGINT,
    SOCSYST06_NIVEL INTEGER,
    ID_SICCONT02 BIGINT,
    SICCONT02_CODIGO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_FAPL TIMESTAMP,
    MAXIMO_NIVEL INTEGER,
    MAXIMO_CODIGO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO CHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ENTRA integer;
declare variable RELA_SOCSYST05 bigint;
begin
    entra = 0;
    for Select
    siccont02_arb_planctas.rela_siccont01,
    siccont02_arb_planctas.rela_socsyst06,
    siccont02_arb_planctas.rela_siccont02,
    socsyst06_det_niveles.socsyst06_nivel,
    siccont02_arb_planctas.id_siccont02,
    siccont02_arb_planctas.siccont02_codigo,
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    siccont02_arb_planctas.siccont02_fapl,
    siccont02_arb_planctas.siccont02_tipo,
    siccont02_arb_planctas.siccont02_codagrup
    from siccont02_arb_planctas
    inner join socsyst06_det_niveles on (socsyst06_det_niveles.id_socsyst06 = siccont02_arb_planctas.rela_socsyst06)
    where siccont02_arb_planctas.rela_siccont01 = :RELA_SICCONT01X
    order by siccont02_arb_planctas.siccont02_codigo_ext
    into :rela_SICCONT01,
         :rela_socsyst06,
         :rela_siccont02,
         :socsyst06_nivel,
         :id_siccont02,
         :siccont02_codigo,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_fapl,
         :siccont02_tipo,
         :siccont02_codagrup
    do
    begin
        if (entra = 0) then
        begin
            entra = 1;
            select first 1 socsyst06_det_niveles.rela_socsyst05
            from socsyst06_det_niveles
            where socsyst06_det_niveles.id_socsyst06 = :rela_socsyst06
            into :rela_socsyst05;

            select max(socsyst06_det_niveles.socsyst06_nivel)
            from socsyst06_det_niveles
            where socsyst06_det_niveles.rela_socsyst05 = :rela_socsyst05
            into :MAXIMO_NIVEL;
        end

        maximo_codigo = '';
        if (rela_siccont02 is null) then
        begin
            select max(siccont02_arb_planctas.siccont02_codigo)
            from siccont02_arb_planctas
            where siccont02_arb_planctas.rela_siccont01 = :RELA_SICCONT01x
            and siccont02_arb_planctas.rela_siccont02 is null
            into :maximo_codigo;
        end
        else
        begin
            select max(siccont02_arb_planctas.siccont02_codigo)
            from siccont02_arb_planctas
            where siccont02_arb_planctas.rela_siccont02 = :rela_siccont02
            into :maximo_codigo;
        end
        suspend;
    end
end^


