CREATE OR ALTER PROCEDURE CBO_INTAUTO01 (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    RELA_INTAUTO01 BIGINT,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_NETO DOUBLE PRECISION,
    MECANICO VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    for select
    intauto01_cab_servicios.rela_pymvent70,
    intauto01_cab_servicios.rela_socusua30,
    intauto01_cab_servicios.id_intauto01,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_neto
    from pymvent70_cab_ticket
    inner join intauto01_cab_servicios on (pymvent70_cab_ticket.id_pymvent70 = intauto01_cab_servicios.rela_pymvent70)
    where pymvent70_cab_ticket.rela_socmain01 = :rela_socmain01
    into :id_pymvent70,
         :rela_socusua30,
         :rela_intauto01,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto
    do
    begin
        select
        cbo_socusua30.entidad
        from cbo_socusua30(:rela_socusua30)
        into :mecanico;

        ve = trim(pymvent70_docnro) || ' - ' || trim(mecanico);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_PYMALMA20 (
    P_ID_SICINGRE95 BIGINT,
    P_RELA_SOCMAIN01 BIGINT,
    P_RELA_SOCMAIN21 BIGINT,
    TIPO INTEGER)
RETURNS (
    ID_TMPINGR95 BIGINT,
    RELA_SICINGR95 BIGINT,
    PYMALMA20_LOTE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_VENCIMIENTO DATE,
    PYMALMA20_SERIE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_SERIE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_MODELO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_TALLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_COLOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    "SUM" DOUBLE PRECISION)
AS
declare variable STR_CAMPOS varchar(1000);
declare variable STR_WHERE varchar(1000);
declare variable STR_QUERY varchar(1000);
BEGIN
    id_tmpingr95 = 0;
    --Dependiendo del tipo de combo, seleccionamos los campos
  if (tipo = 0) then
  begin
    str_campos = 'pymalma20_dep_mtclvs.pymalma20_lote_desde, pymalma20_dep_mtclvs.pymalma20_lote_hasta,
      pymalma20_dep_mtclvs.pymalma20_vencimiento, null, null, null, null,null,';

    str_where =  ' and pymalma20_dep_mtclvs.pymalma20_lote_desde is not null and pymalma20_dep_mtclvs.pymalma20_vencimiento is not null
        group by pymalma20_dep_mtclvs.pymalma20_lote_desde, pymalma20_dep_mtclvs.pymalma20_lote_hasta, pymalma20_dep_mtclvs.pymalma20_vencimiento';
  end
  /*$$IBEC$$ else if (tipo = 1) then
  begin
      str_campos = 'null, null, pymalma20_dep_mtclvs.pymalma20_vencimiento, null,null,null,null,null,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_vencimiento is not null
         group by pymalma20_dep_mtclvs.pymalma20_vencimiento';
  end $$IBEC$$*/
  else if (tipo = 2) then
  begin
      str_campos = 'null, null, null, pymalma20_dep_mtclvs.pymalma20_serie_desde,
            pymalma20_dep_mtclvs.pymalma20_serie_hasta, null, null, null,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_serie_desde is not null
      group by pymalma20_dep_mtclvs.pymalma20_serie_desde, pymalma20_dep_mtclvs.pymalma20_serie_hasta';
  end
  else if (tipo = 3) then
  begin
      str_campos = 'null, null, null, null, null,
            pymalma20_dep_mtclvs.pymalma20_modelo, null, null,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_modelo is not null
        group by pymalma20_dep_mtclvs.pymalma20_modelo';
  end
  else if (tipo = 4) then
  begin
      str_campos = 'null, null, null, null, null, null,
            pymalma20_dep_mtclvs.pymalma20_talla, null, ';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_talla is not null
        group by pymalma20_dep_mtclvs.pymalma20_talla';
  end
  else if (tipo = 5) then
  begin
      str_campos = 'null, null, null, null, null, null,null,
            pymalma20_dep_mtclvs.pymalma20_color, ';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_color is not null
        group by pymalma20_dep_mtclvs.pymalma20_color';
  end  /*$$IBEC$$ else if (tipo = 6) then
  begin
      str_campos = 'pymalma20_dep_mtclvs.pymalma20_lote_desde, pymalma20_dep_mtclvs.pymalma20_lote_hasta,
      pymalma20_dep_mtclvs.pymalma20_vencimiento, null, null, null, null,null,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_lote_desde is not null and pymalma20_dep_mtclvs.pymalma20_vencimiento is not null
        group by pymalma20_dep_mtclvs.pymalma20_lote_desde, pymalma20_dep_mtclvs.pymalma20_lote_hasta, pymalma20_dep_mtclvs.pymalma20_vencimiento';
  end $$IBEC$$*/

  str_query = 'select ' || str_campos ||
               ' sum(pymalma02_det_stock.pymalma02_cantidad)
            from pymalma20_dep_mtclvs
            inner join pymalma02_det_stock on (pymalma20_dep_mtclvs.rela_pymalma02 = pymalma02_det_stock.id_pymalma02)
            inner join pymalma01_cab_stock on (pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01)
            where  pymalma02_det_stock.rela_sicingr95 = ' || :p_id_sicingre95 || ' and
            pymalma01_cab_stock.rela_socmain01 = '|| :p_rela_socmain01 ||
            ' and  pymalma01_cab_stock.rela_socmain21 = ' || :p_rela_socmain21 || str_where;


  FOR EXECUTE STATEMENT :str_query
    INTO :PYMALMA20_LOTE_DESDE,
         :PYMALMA20_LOTE_HASTA,
         :pymalma20_vencimiento,
         :pymalma20_serie_desde,
         :pymalma20_serie_hasta,
         :pymalma20_modelo,
         :pymalma20_talla,
         :pymalma20_color,
         :"SUM"
  DO
  BEGIN
    rela_sicingr95 = p_id_sicingre95;
    id_tmpingr95 = id_tmpingr95 + 1;
    SUSPEND;
  END
END^


CREATE OR ALTER PROCEDURE CBO_PYMALMA20_MTC (
    P_ID_SICINGRE95 BIGINT,
    P_RELA_SOCMAIN01 BIGINT,
    P_RELA_SOCMAIN21 BIGINT,
    TIPO INTEGER)
RETURNS (
    ID_TMPINGR95 BIGINT,
    RELA_SICINGR95 BIGINT,
    PYMALMA20_MODELO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_TALLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_COLOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    "SUM" DOUBLE PRECISION)
AS
declare variable STR_CAMPOS varchar(1000);
declare variable STR_WHERE varchar(1000);
declare variable STR_QUERY varchar(1000);
BEGIN
    id_tmpingr95 = 0;
    --Dependiendo del tipo de combo, seleccionamos los campos
  if (tipo = 0) then
  begin
     str_campos = 'pymalma20_dep_mtclvs.pymalma20_modelo, pymalma20_dep_mtclvs.pymalma20_talla, null,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_modelo is not null and pymalma20_dep_mtclvs.pymalma20_talla is not null
        group by pymalma20_dep_mtclvs.pymalma20_modelo, pymalma20_dep_mtclvs.pymalma20_talla';
  end
  else if (tipo = 1) then
  begin
      str_campos = 'pymalma20_dep_mtclvs.pymalma20_modelo, null, pymalma20_dep_mtclvs.pymalma20_color,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_modelo is not null and pymalma20_dep_mtclvs.pymalma20_color is not null
        group by pymalma20_dep_mtclvs.pymalma20_modelo, pymalma20_dep_mtclvs.pymalma20_color';
  end
  else if (tipo = 2) then
  begin
      str_campos = 'null, pymalma20_dep_mtclvs.pymalma20_talla, pymalma20_dep_mtclvs.pymalma20_color,';

      str_where =  ' and pymalma20_dep_mtclvs.pymalma20_talla is not null and pymalma20_dep_mtclvs.pymalma20_color is not null
        group by pymalma20_dep_mtclvs.pymalma20_talla, pymalma20_dep_mtclvs.pymalma20_color';
  end
  else if (tipo = 3) then
  begin
      str_campos = 'pymalma20_dep_mtclvs.pymalma20_modelo, pymalma20_dep_mtclvs.pymalma20_talla, pymalma20_dep_mtclvs.pymalma20_color,';

      str_where =  'and pymalma20_dep_mtclvs.pymalma20_modelo is not null and pymalma20_dep_mtclvs.pymalma20_talla is not null and pymalma20_dep_mtclvs.pymalma20_color is not null
        group by pymalma20_dep_mtclvs.pymalma20_modelo, pymalma20_dep_mtclvs.pymalma20_talla, pymalma20_dep_mtclvs.pymalma20_color';
  end


  str_query = 'select ' || str_campos ||
               ' sum(pymalma02_det_stock.pymalma02_cantidad)
            from pymalma20_dep_mtclvs
            inner join pymalma02_det_stock on (pymalma20_dep_mtclvs.rela_pymalma02 = pymalma02_det_stock.id_pymalma02)
            inner join pymalma01_cab_stock on (pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01)
            where  pymalma02_det_stock.rela_sicingr95 = ' || :p_id_sicingre95 || ' and
            pymalma01_cab_stock.rela_socmain01 = '|| :p_rela_socmain01 ||
            ' and  pymalma01_cab_stock.rela_socmain21 = ' || :p_rela_socmain21 || str_where;


  FOR EXECUTE STATEMENT :str_query
    INTO :pymalma20_modelo,
         :pymalma20_talla,
         :pymalma20_color,
         :"SUM"
  DO
  BEGIN
    rela_sicingr95 = p_id_sicingre95;
    id_tmpingr95 = id_tmpingr95 + 1;
    SUSPEND;
  END
END^


