CREATE OR ALTER PROCEDURE CBO_PYMVENT70_ACREDITO (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT)
RETURNS (
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT70_FECHA DATE,
    ABONO DOUBLE PRECISION,
    SALDO NUMERIC(15,2),
    STATUS VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_CODE INTEGER)
AS
declare variable ID_PYMVENT51 bigint;
declare variable EXISTE bigint;
declare variable MODO varchar(1);
begin
    for

    select
    'A',
    pymvent51_det_ventas.id_pymvent51,
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_neto,
    pymvent70_cab_ticket.pymvent70_fecha
    from pymvent70_cab_ticket
    inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    inner join pymvent50_cab_apertura on (pymvent51_det_ventas.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
    where pymvent50_cab_apertura.rela_socmain01 = :rela_socmain01
    and pymvent70_cab_ticket.rela_socmain01 = :rela_socmain01
    and pymvent70_cab_ticket.rela_sicingr01 = :rela_sicingr01
    and pymvent51_det_ventas.pymvent51_diasapartado <> 0
    and pymvent51_det_ventas.pymvent51_fcerrado is null
    and not exists ( select first 1 pymvent60_cab_cobro.id_pymvent60
                     from pymvent60_cab_cobro
                     where pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51
                    )

    UNION ALL

    select
    'O',
    pymvent51_det_ventas.id_pymvent51,
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_neto,
    pymvent70_cab_ticket.pymvent70_fecha
    from pymvent60_cab_cobro
    inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
    inner join pymvent50_cab_apertura on (pymvent51_det_ventas.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
    inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    where pymvent50_cab_apertura.rela_socmain01 = :rela_socmain01
    and pymvent70_cab_ticket.rela_socmain01 = :rela_socmain01
    and pymvent70_cab_ticket.rela_sicingr01 = :rela_sicingr01
    into :modo,
         :id_pymvent51,
         :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_neto,
         :pymvent70_fecha
    do
    begin
        existe = null;
        abono = null;
        saldo = null;

        if (modo = 'O') then
        begin
            select first 1 pymvent60_cab_cobro.id_pymvent60
            from pymvent60_cab_cobro
            inner join pymvent61_det_cobro on (pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
            inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01)
            where pymvent60_cab_cobro.rela_pymvent51 = :id_pymvent51
            and socsyst10_det_remoto.socsyst10_codigo = '99'
            into :existe;

            if (existe is not null) then
            begin
                select
                sum(pymvent55_mov_moventsal.pymvent55_importe)
                from pymvent55_mov_moventsal
                where pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70
                and pymvent55_mov_moventsal.pymvent55_pagoticket = 3
                and pymvent55_mov_moventsal.pymvent55_importe > 0
                into :abono;

                if (abono is null) then abono = 0;

                saldo = pymvent70_neto - abono;

                 --HV: Se agregó para considerar las devoluciones
                select
                sum(pymvent55_mov_moventsal.pymvent55_importe)*(-1)
                from pymvent55_mov_moventsal
                where pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70
                and pymvent55_mov_moventsal.pymvent55_pagoticket = 6
                --and pymvent55_mov_moventsal.pymvent55_importe < 0
                into :abono;

                if (abono is null) then abono = 0;

                saldo = saldo - abono;

                if (saldo <> 0) then
                begin
                    status = 'Venta a Crédito';
                    status_code = 3;
                    suspend;
                end
            end
        end
        else if (modo = 'A') then
        begin
            select
            sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent55_mov_moventsal
            where pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70
            and pymvent55_mov_moventsal.pymvent55_pagoticket = 5
            and pymvent55_mov_moventsal.pymvent55_importe > 0
            into :abono;

            if (abono is null) then abono = 0;

            saldo = pymvent70_neto - abono;

            if (saldo <> 0) then
            begin
                status = 'Apartado';
                status_code = 5;
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICCONT02 (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    ID_SICCONT02 BIGINT,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICCONT01 bigint;
begin
    SELECT siccont01_cab_planctas.id_siccont01
    FROM siccont01_cab_planctas
    WHERE siccont01_cab_planctas.rela_socmain01 = :RELA_SOCMAIN01
    INTO :id_siccont01;


    for SELECT
    siccont02_arb_planctas.id_siccont02,
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    siccont02_arb_planctas.siccont02_tipo,
    siccont02_arb_planctas.siccont02_codagrup
    FROM siccont02_arb_planctas
    WHERE siccont02_arb_planctas.rela_siccont01 = :id_siccont01
    and not EXISTS (SELECT siccont02_arb_planctas.id_siccont02
                      FROM siccont02_arb_planctas siccont02
                      WHERE siccont02.rela_siccont02 = siccont02_arb_planctas.id_siccont02)
    ORDER BY siccont02_arb_planctas.siccont02_codigo_ext
    into :id_siccont02,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_tipo,
         :siccont02_codagrup
    do
    begin
        CUENTA = trim(siccont02_codigo_ext) || ' - ' || trim(siccont02_descripcion);
        suspend;
    end
end^


