CREATE OR ALTER PROCEDURE CBO_SICINGR01_ENT_SAL (
    P_SOCMAIN01 BIGINT)
RETURNS (
    ID_SICINGR01 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_PARTICULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_CELULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_LABORAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BUSQUEDA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCUSUA31_LADA varchar(50);
declare variable SOCUSUA31_NRO varchar(50);
declare variable TELEFONO varchar(50);
begin
    /* Obtenemos los clientes de la empresa que hayan realizado alguna compra con
    forma de pago 99 (credito)*/
    for select distinct pymvent70_cab_ticket.rela_sicingr01
    from sicingr01_cab_clientes
       inner join pymvent70_cab_ticket on (sicingr01_cab_clientes.id_sicingr01 = pymvent70_cab_ticket.rela_sicingr01)
       inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
       inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
       inner join pymvent61_det_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
    where sicingr01_cab_clientes.rela_socmain01 = :P_SOCMAIN01  and pymvent61_det_cobro.rela_socsyst10_fdp01 = 54661
    INTO :id_sicingr01
    do
    begin
        /* Inicializamos las variables */
        entidad = null;
        tipo = null;
        rfc = null;

        SELECT
        CBO_SICINGR01_ID.entidad,
        CBO_SICINGR01_ID.tipo,
        CBO_SICINGR01_ID.rfc
        FROM CBO_SICINGR01_ID
        where CBO_SICINGR01_ID.id_sicingr01 = :id_sicingr01
        into :entidad,
             :tipo,
             :rfc;

        if (rfc is null) then
            rfc = '';

        for select
        socsyst10_det_entradas.socsyst10_codigo,
        socusua31_det_telefonos.socusua31_lada,
        socusua31_det_telefonos.socusua31_nro
        from socusua31_det_telefonos
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua31_det_telefonos.rela_socsyst10_tt001 )
        where socusua31_det_telefonos.rela_socusua30 = :id_sicingr01
        into :socsyst10_codigo,
             :socusua31_lada,
             :socusua31_nro
        do
        begin
            /* Inicializamos las variables */
            telefono = null;
            tel_celular = null;
            tel_particular = null;
            tel_laboral = null;
            busqueda = null;

            telefono = '(' || :socusua31_lada || ') ' || :socusua31_nro;

            if (socsyst10_codigo = 'TELCEL') then
                tel_celular = telefono;
            else if (socsyst10_codigo = 'TELPAR') then
                tel_particular = telefono;
            else if (socsyst10_codigo = 'TELLAB') then
                tel_laboral = telefono;
        end

        if (tel_celular is null) then tel_celular = '';
        if (tel_particular is null) then tel_particular = '';
        if (tel_laboral is null) then tel_laboral = '';

        busqueda = :entidad || :rfc || tel_celular || tel_particular || tel_laboral;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR01_PYMVENT70 (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    ID_SICINGR01 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_PARTICULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_CELULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_LABORAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BUSQUEDA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCUSUA31_LADA varchar(50);
declare variable SOCUSUA31_NRO varchar(50);
declare variable TELEFONO varchar(50);
begin
    FOR SELECT
    sicingr01_cab_clientes.id_sicingr01,
    sicingr01_cab_clientes.rela_socusua30
    FROM sicingr01_cab_clientes
    WHERE sicingr01_cab_clientes.rela_socmain01 = :rela_socmain01
    INTO :id_sicingr01,
         :rela_socusua30
    do
    begin
        SELECT
        cbo_socusua30.entidad,
        cbo_socusua30.tipo,
        cbo_socusua30.rfc
        FROM cbo_socusua30(:rela_socusua30)
        into :entidad,
             :tipo,
             :rfc;

        if (rfc is null) then
            rfc = '';

        for select
        socsyst10_det_entradas.socsyst10_codigo,
        socusua31_det_telefonos.socusua31_lada,
        socusua31_det_telefonos.socusua31_nro
        from socusua31_det_telefonos
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua31_det_telefonos.rela_socsyst10_tt001 )
        where socusua31_det_telefonos.rela_socusua30 = :rela_socusua30
        into :socsyst10_codigo,
             :socusua31_lada,
             :socusua31_nro
        do
        begin
            telefono = '(' || :socusua31_lada || ') ' || :socusua31_nro;

            if (socsyst10_codigo = 'TELCEL') then
                tel_celular = telefono;
            else if (socsyst10_codigo = 'TELPAR') then
                tel_particular = telefono;
            else if (socsyst10_codigo = 'TELLAB') then
                tel_laboral = telefono;
        end

        if (tel_celular is null) then tel_celular = '';
        if (tel_particular is null) then tel_particular = '';
        if (tel_laboral is null) then tel_laboral = '';

        busqueda = :entidad || :rfc || tel_celular || tel_particular || tel_laboral;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR01_WEB
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    ID_SICINGR01 BIGINT,
    ENTIDAD VARCHAR(500) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGIMEN_FISCAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    for SELECT
    cbo_sicingr01_id.rela_socmain01,
    cbo_sicingr01_id.rela_socusua30,
    cbo_sicingr01_id.id_sicingr01,
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc,
    cbo_sicingr01_id.tipo
    FROM cbo_sicingr01_id
    order by cbo_sicingr01_id.entidad
    INTO :rela_socmain01,
         :rela_socusua30,
         :id_sicingr01,
         :entidad,
         :rfc,
         :tipo
    DO
    BEGIN
        regimen_fiscal = null;

        select cbo_socsyst10_sat01.socsyst10_codigo
        from sicingr01_cab_clientes
        inner join cbo_socsyst10_sat01 on (cbo_socsyst10_sat01.id_socsyst10 = sicingr01_cab_clientes.rela_socsyst10_sat01)
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        into :regimen_fiscal;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR70_SICINGR55 (
    RELA_SICINGR01 BIGINT)
RETURNS (
    ID_SICINGR70 BIGINT,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE,
    SICINGR70_NETO DOUBLE PRECISION,
    SICINGR70_PAGADO DOUBLE PRECISION,
    SICINGR70_SALDO DOUBLE PRECISION,
    SICINGR70_NOTACREDITO DOUBLE PRECISION)
AS
begin
    delete from tmp_sicingr70_notascredito
    where tmp_sicingr70_notascredito.usuario = current_user;

    insert into tmp_sicingr70_notascredito
    select
    current_user,
    grd_sicingr70_notascredito.id_sicingr70,
    grd_sicingr70_notascredito.sicingr70_docnro,
    grd_sicingr70_notascredito.sicingr70_fecha,
    grd_sicingr70_notascredito.credito,
    grd_sicingr70_notascredito.folio,
    grd_sicingr70_notascredito.factura,
    grd_sicingr70_notascredito.saldo,
    grd_sicingr70_notascredito.sicingr70_fapl
    from grd_sicingr70_notascredito;

    for select
    sicingr70_cab_facturacion.id_sicingr70,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_fecha,
    sicingr70_cab_facturacion.sicingr70_neto
    from sicingr70_cab_facturacion
    where sicingr70_cab_facturacion.rela_sicingr01 = :rela_sicingr01
    order by sicingr70_cab_facturacion.sicingr70_docnro desc
    into :id_sicingr70,
         :sicingr70_docnro,
         :sicingr70_fecha,
         :sicingr70_neto
    do
    begin
        select sum(sicingr55_det_facturas.sicingr55_importe)
        from sicingr55_det_facturas
        where sicingr55_det_facturas.rela_sicingr70 = :id_sicingr70
        into :sicingr70_pagado;
    
        sicingr70_pagado = iif(sicingr70_pagado is null, 0.0, sicingr70_pagado);
        sicingr70_saldo = sicingr70_neto - sicingr70_pagado;

        sicingr70_notacredito = null;

        select coalesce(sum(tmp_sicingr70_notascredito.credito), 0)
        from tmp_sicingr70_notascredito
        where tmp_sicingr70_notascredito.usuario = current_user
        and tmp_sicingr70_notascredito.folio = :sicingr70_docnro
        into :sicingr70_notacredito;

        sicingr70_notacredito = iif(sicingr70_notacredito is null,  0, sicingr70_notacredito);

        sicingr70_saldo = sicingr70_saldo - :sicingr70_notacredito;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR85 (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01 BIGINT,
    ID_SICINGR70 BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICINGR85 BIGINT,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR85_IMPGASTOS DOUBLE PRECISION,
    SICINGR85_FCERRADO TIMESTAMP,
    SICINGR85_FAPL TIMESTAMP,
    SOCUSUA01_USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ANTICIPOS DOUBLE PRECISION,
    VE VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICINGR88 bigint;
declare variable ANTICIPOS_USO double precision;
begin
    id_sicingr88  = null;

    if (id_sicingr70 is not null and id_sicingr70 > 0) then
        select sicingr88_det_gastos3ros.id_sicingr88
        from sicingr88_det_gastos3ros
        where sicingr88_det_gastos3ros.rela_sicingr70 = :id_sicingr70
        into :id_sicingr88;


    if (id_sicingr88 is not null) then
    begin
        for select
        socusua01_cab_usuarios.socusua01_usuario,
        sicingr85_cab_gastos3ros.rela_socmain01,
        sicingr85_cab_gastos3ros.rela_socmain21,
        sicingr85_cab_gastos3ros.rela_socusua01,
        sicingr85_cab_gastos3ros.rela_sicingr01,
        ( select aductag01_cab_ctagastos.rela_socsyst10_ctm01
          from aductag01_cab_ctagastos
          where aductag01_cab_ctagastos.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
        sicingr85_cab_gastos3ros.id_sicingr85,
        sicingr85_cab_gastos3ros.sicingr85_referencia,
        ( select sum(sicingr86_det_gastos3ros.sicingr86_importe)
          from sicingr86_det_gastos3ros
          where sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
        sicingr85_cab_gastos3ros.sicingr85_fcerrado,
        sicingr85_cab_gastos3ros.sicingr85_fapl
        from sicingr85_cab_gastos3ros
        inner join socusua01_cab_usuarios on ( socusua01_cab_usuarios.id_socusua01 = sicingr85_cab_gastos3ros.rela_socusua01 )
        inner join sicingr88_det_gastos3ros on ( sicingr88_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85 )
        where sicingr88_det_gastos3ros.id_sicingr88 = :id_sicingr88
        into :socusua01_usuario,
             :rela_socmain01,
             :rela_socmain21,
             :rela_socusua01,
             :rela_sicingr01,
             :rela_socsyst10_ctm01,
             :id_sicingr85,
             :sicingr85_referencia,
             :sicingr85_impgastos,
             :sicingr85_fcerrado,
             :sicingr85_fapl
        do
        begin
            select sum(sicingr86_det_gastos3ros.sicingr86_importe)
            from sicingr86_det_gastos3ros
            where sicingr86_det_gastos3ros.rela_sicingr85 = :id_sicingr85
            into :sicingr85_impgastos;

            if (sicingr85_impgastos is null) then
                sicingr85_impgastos = 0;
    
            ve = '(' || cast(id_sicingr85 as varchar(10)) ||
                 ') ' || cast(cast(sicingr85_fapl as date) as varchar(50)) ||
                 ' : ' || socusua01_usuario || ' (' || :sicingr85_referencia || ')';

            select
            sum(sicingr53_det_refanticipos.sicingr53_importe)
            from sicingr53_det_refanticipos
            where sicingr53_det_refanticipos.rela_sicingr85 = :id_sicingr85
            into :anticipos;

            select sum(SICINGR88_DET_GASTOS3ROS.sicingr88_importe_cta)
            from SICINGR88_DET_GASTOS3ROS
            where SICINGR88_DET_GASTOS3ROS.rela_sicingr85 = :id_sicingr85
            into :anticipos_uso;

            if (anticipos is null) then
                anticipos = 0;

            if (anticipos_uso is null) then
                anticipos_uso = 0;

            anticipos = anticipos - anticipos_uso;

            suspend;
        end    
    end
    else
    begin
        for select
        socusua01_cab_usuarios.socusua01_usuario,
        sicingr85_cab_gastos3ros.rela_socmain01,
        sicingr85_cab_gastos3ros.rela_socmain21,
        sicingr85_cab_gastos3ros.rela_socusua01,
        sicingr85_cab_gastos3ros.rela_sicingr01,
        ( select aductag01_cab_ctagastos.rela_socsyst10_ctm01
          from aductag01_cab_ctagastos
          where aductag01_cab_ctagastos.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
        sicingr85_cab_gastos3ros.id_sicingr85,
        sicingr85_cab_gastos3ros.sicingr85_referencia,
        ( select sum(sicingr86_det_gastos3ros.sicingr86_importe)
          from sicingr86_det_gastos3ros
          where sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
        sicingr85_cab_gastos3ros.sicingr85_fcerrado,
        sicingr85_cab_gastos3ros.sicingr85_fapl
        from sicingr85_cab_gastos3ros
        inner join socusua01_cab_usuarios on ( socusua01_cab_usuarios.id_socusua01 = sicingr85_cab_gastos3ros.rela_socusua01 )
        where sicingr85_cab_gastos3ros.rela_socmain01 = :id_socmain01
        and sicingr85_cab_gastos3ros.rela_sicingr01 = :id_sicingr01
        and iif(sicingr85_cab_gastos3ros.sicingr85_fcerrado is null, 0, 1) = 1
        and not exists ( select sicingr88_det_gastos3ros.id_sicingr88
                         from sicingr88_det_gastos3ros
                         where sicingr88_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
                       )
        into :socusua01_usuario,
             :rela_socmain01,
             :rela_socmain21,
             :rela_socusua01,
             :rela_sicingr01,
             :rela_socsyst10_ctm01,
             :id_sicingr85,
             :sicingr85_referencia,
             :sicingr85_impgastos,
             :sicingr85_fcerrado,
             :sicingr85_fapl
        do
        begin
            select sum(sicingr86_det_gastos3ros.sicingr86_importe)
            from sicingr86_det_gastos3ros
            where sicingr86_det_gastos3ros.rela_sicingr85 = :id_sicingr85
            into :sicingr85_impgastos;

            if (sicingr85_impgastos is null) then
                sicingr85_impgastos = 0;
    
            ve = '(' || cast(id_sicingr85 as varchar(10)) ||
                 ') ' || cast(cast(sicingr85_fapl as date) as varchar(50)) ||
                 ' : ' || socusua01_usuario || ' (' || :sicingr85_referencia || ')';
    
            id_sicingr88 = null;

            select sicingr88_det_gastos3ros.id_sicingr88
            from sicingr88_det_gastos3ros
            inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70 )
            inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
            where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
            into :id_sicingr88;

            if (id_sicingr88 is null) then
            begin
                select
                sum(sicingr53_det_refanticipos.sicingr53_importe)
                from sicingr53_det_refanticipos
                where sicingr53_det_refanticipos.rela_sicingr85 = :id_sicingr85
                into :anticipos;
    
                select sum(SICINGR88_DET_GASTOS3ROS.sicingr88_importe_cta)
                from SICINGR88_DET_GASTOS3ROS
                where SICINGR88_DET_GASTOS3ROS.rela_sicingr85 = :id_sicingr85
                into :anticipos_uso;

                if (anticipos is null) then
                    anticipos = 0;

                if (anticipos_uso is null) then
                    anticipos_uso = 0;

                anticipos = anticipos - anticipos_uso;

                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR85_ANTICIPOS (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01 BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICINGR85 BIGINT,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR85_IMPGASTOS DOUBLE PRECISION,
    SICINGR85_IMPANTICIPOS DOUBLE PRECISION,
    SICINGR85_FAPL TIMESTAMP)
AS
begin
    for select
    sicingr85_cab_gastos3ros.rela_socmain01,
    sicingr85_cab_gastos3ros.rela_socmain21,
    sicingr85_cab_gastos3ros.rela_socusua01,
    sicingr85_cab_gastos3ros.rela_sicingr01,
    ( select aductag01_cab_ctagastos.rela_socsyst10_ctm01
      from aductag01_cab_ctagastos
      where aductag01_cab_ctagastos.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
    ),
    sicingr85_cab_gastos3ros.id_sicingr85,
    sicingr85_cab_gastos3ros.sicingr85_referencia,
    ( select sum(sicingr86_det_gastos3ros.sicingr86_importe)
          from sicingr86_det_gastos3ros
          where sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
    sicingr85_cab_gastos3ros.sicingr85_fapl
    from sicingr85_cab_gastos3ros
    where sicingr85_cab_gastos3ros.rela_socmain01 = :id_socmain01
    and sicingr85_cab_gastos3ros.rela_sicingr01 = :id_sicingr01
    and not exists (select sicingr88_det_gastos3ros.id_sicingr88
                    from sicingr88_det_gastos3ros
                    where sicingr88_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
                   )
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :rela_sicingr01,
         :rela_socsyst10_ctm01,
         :id_sicingr85,
         :sicingr85_referencia,
         :sicingr85_impgastos,
         :sicingr85_fapl
    do
    begin
        select sum(sicingr53_det_refanticipos.sicingr53_importe)
        from sicingr53_det_refanticipos
        where sicingr53_det_refanticipos.rela_sicingr85 = :id_sicingr85
        into :sicingr85_impanticipos;

        if (sicingr85_impgastos is null) then
            sicingr85_impgastos = 0;

        if (sicingr85_impanticipos is null) then
            sicingr85_impanticipos = 0;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR85_WEB (
    ID_SICINGR01 BIGINT)
RETURNS (
    ID_SICINGR85 BIGINT,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR85_FCERRADO TIMESTAMP,
    TOT_ANTICIPOS DOUBLE PRECISION,
    TOT_FACTURAS_3ROS DOUBLE PRECISION,
    TOT_GASTOS DOUBLE PRECISION,
    TOT_FACTURADO DOUBLE PRECISION,
    TOT_TIMBRADO DOUBLE PRECISION,
    SICINGR85_FAPL TIMESTAMP)
AS
begin
    for select
    sicingr85_cab_gastos3ros.id_sicingr85,
    sicingr85_cab_gastos3ros.sicingr85_referencia,
    sicingr85_cab_gastos3ros.sicingr85_fcerrado,
    sicingr85_cab_gastos3ros.sicingr85_fapl
    from sicingr85_cab_gastos3ros
    where sicingr85_cab_gastos3ros.rela_sicingr01 = :id_sicingr01
    and sicingr85_cab_gastos3ros.sicingr85_fcerrado is null
    ORDER BY sicingr85_fapl DESC
    into :id_sicingr85,
         :sicingr85_referencia,
         :sicingr85_fcerrado,
         :sicingr85_fapl
    do
    begin
        select sum(aductag02_det_anticipos.aductag02_importe)
        from aductag02_det_anticipos
        where aductag02_det_anticipos.rela_sicingr85 = :id_sicingr85
        into :tot_anticipos;

        tot_anticipos = iif(tot_anticipos is null, 0.0, tot_anticipos);

        select sum(adufact01_cab_facturas.adufact01_importe)
        from adufact01_cab_facturas
        where adufact01_cab_facturas.rela_sicingr85 = :id_sicingr85
        into :tot_facturas_3ros;

        tot_facturas_3ros = iif(tot_facturas_3ros is null, 0.0, tot_facturas_3ros);

        select sum(sicingr86_det_gastos3ros.sicingr86_importe)
        from sicingr86_det_gastos3ros
        where sicingr86_det_gastos3ros.rela_sicingr85 = :id_sicingr85
        into :tot_gastos;

        tot_gastos = iif(tot_gastos is null, 0.0, tot_gastos);

        select sum(sicingr70_cab_facturacion.sicingr70_neto)
        from sicingr88_det_gastos3ros
        inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
        where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
        into :tot_facturado;

        tot_facturado = iif(tot_facturado is null, 0.0, tot_facturado);

        select sum(sicingr70_cab_facturacion.sicingr70_neto)
        from sicingr88_det_gastos3ros
        inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
        inner join sicingr74_dep_cfdis on (sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
        where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
        into :tot_timbrado;

        tot_timbrado = iif(tot_timbrado is null, 0.0, tot_timbrado);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR95_SICXMLS04_FIND (
    ID_SOCMAIN01 BIGINT,
    BUSCARTXT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICXMLS04 BIGINT)
RETURNS (
    RELA_SICXMLS01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    ID_SICXMLS04 BIGINT,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS04_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DEDUCIBLE VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    ASIGNADO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SQLSTR varchar(2000);
begin
    if ( (id_socmain01 is not null and id_socmain01 > 0) or (rela_sicxmls04 is not null and rela_sicxmls04 > 0) ) then
    begin
        BUSCARTXT = TRIM(UPPER(BUSCARTXT));
    
        if (rela_sicxmls04 is null or rela_sicxmls04 <= 0) then
            sqlstr = 'SELECT
                     CBO_SICINGR95_SICXMLS04.rela_sicxmls01,
                     CBO_SICINGR95_SICXMLS04.rela_socmain01,
                     CBO_SICINGR95_SICXMLS04.id_sicxmls04,
                     CBO_SICINGR95_SICXMLS04.siccont02_codigo_ext,
                     CBO_SICINGR95_SICXMLS04.siccont02_descripcion,
                     CBO_SICINGR95_SICXMLS04.siccont02_codagrup,
                     CBO_SICINGR95_SICXMLS04.socsyst10_descripcion,
                     CBO_SICINGR95_SICXMLS04.sicxmls04_concepto,
                     CBO_SICINGR95_SICXMLS04.tipo,
                     CBO_SICINGR95_SICXMLS04.deducible,
                     CBO_SICINGR95_SICXMLS04.importe,
                     CBO_SICINGR95_SICXMLS04.asignado
                     FROM CBO_SICINGR95_SICXMLS04
                     WHERE CBO_SICINGR95_SICXMLS04.rela_socmain01 = ' || :id_socmain01 ||
                     'AND ( TRIM(UPPER( CBO_SICINGR95_SICXMLS04.siccont02_codigo_ext)) ||
                            TRIM(UPPER( CBO_SICINGR95_SICXMLS04.siccont02_descripcion)) ||
                            TRIM(UPPER( CBO_SICINGR95_SICXMLS04.siccont02_codagrup)) ||
                            TRIM(UPPER( CBO_SICINGR95_SICXMLS04.socsyst10_descripcion)) ||
                            TRIM(UPPER( CBO_SICINGR95_SICXMLS04.sicxmls04_concepto)) ) LIKE ''%' ||:buscartxt || '%''';
        else
            sqlstr = 'SELECT
                     CBO_SICINGR95_SICXMLS04.rela_sicxmls01,
                     CBO_SICINGR95_SICXMLS04.rela_socmain01,
                     CBO_SICINGR95_SICXMLS04.id_sicxmls04,
                     CBO_SICINGR95_SICXMLS04.siccont02_codigo_ext,
                     CBO_SICINGR95_SICXMLS04.siccont02_descripcion,
                     CBO_SICINGR95_SICXMLS04.siccont02_codagrup,
                     CBO_SICINGR95_SICXMLS04.socsyst10_descripcion,
                     CBO_SICINGR95_SICXMLS04.sicxmls04_concepto,
                     CBO_SICINGR95_SICXMLS04.tipo,
                     CBO_SICINGR95_SICXMLS04.deducible,
                     CBO_SICINGR95_SICXMLS04.importe,
                     CBO_SICINGR95_SICXMLS04.asignado
                     FROM CBO_SICINGR95_SICXMLS04
                     WHERE CBO_SICINGR95_SICXMLS04.id_sicxmls04 = ' || :rela_sicxmls04;
    
        for execute statement :sqlstr
        into  :rela_sicxmls01,
              :rela_socmain01,
              :id_sicxmls04,
              :siccont02_codigo_ext,
              :siccont02_descripcion,
              :siccont02_codagrup,
              :socsyst10_descripcion,
              :sicxmls04_concepto,
              :tipo,
              :deducible,
              :importe,
              :asignado
        do
        begin
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICINGR95_WEB (
    ID_EMPRESA BIGINT,
    ID_POSITION BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    ID_SICINGR95 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD_MEDIDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SAT_SERVPROD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SAT_CODE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (id_position > 0) then
    begin
        SELECT
        CBO_SICINGR95.rela_socmain01,
        CBO_SICINGR95.id_sicingr95,
        CBO_SICINGR95.sicingr95_codigo,
        CBO_SICINGR95.sicingr95_descripcion,
        CBO_SICINGR95.unidad_medida,
        CBO_SICINGR95.sat_servprod,
        CBO_SICINGR95.sat_code
        FROM CBO_SICINGR95
        where CBO_SICINGR95.id_sicingr95 = :id_position
        INTO :rela_socmain01,
             :id_sicingr95,
             :sicingr95_codigo,
             :sicingr95_descripcion,
             :unidad_medida,
             :sat_servprod,
             :sat_code;
    
        suspend;
    end
    
    for select
    CBO_SICINGR95.rela_socmain01,
    CBO_SICINGR95.id_sicingr95,
    CBO_SICINGR95.sicingr95_codigo,
    CBO_SICINGR95.sicingr95_descripcion,
    CBO_SICINGR95.unidad_medida,
    CBO_SICINGR95.sat_servprod,
    CBO_SICINGR95.sat_code
    FROM CBO_SICINGR95
    where CBO_SICINGR95.RELA_SOCMAIN01 = :ID_EMPRESA
    and CBO_SICINGR95.id_sicingr95 != :id_position
    order by sicingr95_descripcion
    INTO :rela_socmain01,
         :id_sicingr95,
         :sicingr95_codigo,
         :sicingr95_descripcion,
         :unidad_medida,
         :sat_servprod,
         :sat_code
     DO
     BEGIN
        
        suspend;
     END
end^


CREATE OR ALTER PROCEDURE CBO_SICNOMI01_ABM (
    ID_SOCMAIN01 BIGINT,
    ID_SICNOMI01 BIGINT)
RETURNS (
    ID_SOCUSUA30 BIGINT,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (id_sicnomi01 is not null) then
    begin
        select sicnomi01_cab_empleados.rela_socusua30
        from sicnomi01_cab_empleados
        where sicnomi01_cab_empleados.id_sicnomi01 = :id_sicnomi01
        into :id_socusua30;

        select
        cbo_socusua30.id_socusua30,
        cbo_socusua30.entidad,
        cbo_socusua30.tipo,
        cbo_socusua30.rfc,
        cbo_socusua30.curp
        from cbo_socusua30(:id_socusua30)
        into :id_socusua30,
             :entidad,
             :tipo,
             :rfc,
             :curp;
        suspend;
    end

    for select
    cbo_socusua30.id_socusua30,
    cbo_socusua30.entidad,
    cbo_socusua30.tipo,
    cbo_socusua30.rfc,
    cbo_socusua30.curp
    from cbo_socusua30(null)
    where not exists (  select first 1 sicnomi01_cab_empleados.id_sicnomi01
                        from sicnomi01_cab_empleados
                        where sicnomi01_cab_empleados.rela_socmain01 = :id_socmain01
