    into :id_socusua30,
         :entidad,
         :tipo,
         :rfc,
         :curp
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SICNOMI60_PERIODOS (
    RELA_SICMAIN01 BIGINT,
    ID_SICNOMI60 BIGINT)
RETURNS (
    ID INTEGER,
    FECHA DATE)
AS
declare variable ID_SICNOMI50 bigint;
begin
    ID = 0;

    if (ID_SICNOMI60 < 0) then
    begin
        for Select distinct
        sicxmls41_det_migracion.sicxmls41_fecha_pago
        from sicxmls41_det_migracion
        inner join sicxmls40_cab_migracion on ( sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40 )
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01 )
        where sicxmls40_cab_migracion.rela_socmain01 = :rela_sicmain01
        and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA'
        order by sicxmls41_fecha_pago
        into :fecha
        do
        begin
            id_sicnomi50 = null;
            Select first 1 GRD_SICNOMI50_XPERIODOS.id_sicnomi50
            from GRD_SICNOMI50_XPERIODOS(:rela_sicmain01, :fecha)
            into :id_sicnomi50;

            if (id_sicnomi50 is not null) then
            begin
                ID = ID + 1;
                suspend;
            end

        end
    end
    else
    begin
        SELECT sicnomi60_cab_xperiodo.sicnomi60_fperiodo
        FROM sicnomi60_cab_xperiodo
        WHERE sicnomi60_cab_xperiodo.id_sicnomi60 = :id_sicnomi60
        INTO :fecha;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCMAIN01_STOCK (
    COD_PRODUCTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCMAIN01 BIGINT,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICINGR95 BIGINT)
AS
begin
    cod_producto = TRIM(UPPER(cod_producto));

    for Select
    socmain01_cab_empresas.id_socmain01,
    socmain01_cab_empresas.socmain01_nomcomercial
    from socmain01_cab_empresas
    WHERE EXISTS( SELECT FIRST 1 pymalma01_cab_stock.id_pymalma01
                FROM pymalma01_cab_stock
                WHERE pymalma01_cab_stock.rela_socmain01 = socmain01_cab_empresas.id_socmain01
               )
    into :id_socmain01,
         :socmain01_nomcomercial
    do
    begin
        if (cod_producto = '19640924') then
        begin
            suspend;
        end
        else
        begin
            rela_sicingr95 = NULL;
    
            select FIRST 1 sicingr95_cab_conceptos.id_sicingr95
            from sicingr95_cab_conceptos
            inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
            where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
            and upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)) = :COD_PRODUCTO
