        end
    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCMAIN01_WEB (
    RELA_SOCUSUA01 BIGINT)
RETURNS (
    RELA_SICXMLS01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    RELA_SOCMAIN20 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    ID_SOCMAIN01 BIGINT,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_TEST INTEGER,
    REGIMEN_FISCAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_FOLIOS INTEGER,
    IS_RESELLER INTEGER,
    SOCMAIN01_FAPL TIMESTAMP)
AS
declare variable EMPRESAS_USUARIO integer;
begin
    SELECT count(SOCUSUA04_DET_EMPRESAS.id_socusua04)
    FROM SOCUSUA04_DET_EMPRESAS
    WHERE SOCUSUA04_DET_EMPRESAS.rela_socusua01 = :rela_socusua01
    into :empresas_usuario;

    if (empresas_usuario = 0) then
    begin
        for select
        cbo_socmain01.rela_sicxmls01,
        cbo_socmain01.id_socmain01,
        cbo_socmain01.socmain01_nomcomercial,
        cbo_socmain01.rfc,
        cbo_socmain01.socmain01_test,
        cbo_socmain01.regimen_fiscal
        from cbo_socmain01
        into :rela_sicxmls01,
             :id_socmain01,
             :socmain01_nomcomercial,
             :rfc,
             :socmain01_test,
             :regimen_fiscal
        do
        begin
            SELECT
            SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_comprados) -
            SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_consumidos)
            FROM SOCMAIN11_MOV_FOLIOS
            INNER JOIN socmain10_det_contadores ON (socmain10_det_contadores.id_socmain10 = SOCMAIN11_MOV_FOLIOS.rela_socmain10)
            WHERE socmain10_det_contadores.rela_socmain01 = :id_socmain01
            INTO :saldo_folios;

            saldo_folios = iif(saldo_folios is null, 0, saldo_folios);

            select
            socmain01_cab_empresas.rela_socusua30,
            socmain01_cab_empresas.socmain01_propietaria,
            socmain01_cab_empresas.socmain01_fapl
            from socmain01_cab_empresas
            where socmain01_cab_empresas.id_socmain01 = :id_socmain01
            into :rela_socusua30,
                 :is_reseller,
                 :socmain01_fapl;

            SELECT
            SOCMAIN20_CAB_ORGANIZACION.id_socmain20
            FROM SOCMAIN20_CAB_ORGANIZACION
            WHERE SOCMAIN20_CAB_ORGANIZACION.rela_socmain01 = :id_socmain01
            INTO :rela_socmain20;

            select min(socmain21_arb_organizacion.id_socmain21)
            from socmain21_arb_organizacion
            WHERE socmain21_arb_organizacion.rela_socmain20 = :rela_socmain20
            into :rela_socmain21;

            suspend;
        end
    end
    else
    begin
       for select
        cbo_socmain01.rela_sicxmls01,
        cbo_socmain01.id_socmain01,
        cbo_socmain01.socmain01_nomcomercial,
        cbo_socmain01.rfc,
        cbo_socmain01.socmain01_test,
        cbo_socmain01.regimen_fiscal
        from cbo_socmain01
        inner join socusua04_det_empresas on (socusua04_det_empresas.rela_socmain01 = cbo_socmain01.id_socmain01)
        where socusua04_det_empresas.rela_socusua01 = :rela_socusua01
        into :rela_sicxmls01,
             :id_socmain01,
             :socmain01_nomcomercial,
             :rfc,
             :socmain01_test,
             :regimen_fiscal
        do
        begin
            SELECT
            SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_comprados) -
            SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_consumidos)
            FROM SOCMAIN11_MOV_FOLIOS
            INNER JOIN socmain10_det_contadores ON (socmain10_det_contadores.id_socmain10 = SOCMAIN11_MOV_FOLIOS.rela_socmain10)
            WHERE socmain10_det_contadores.rela_socmain01 = :id_socmain01
            INTO :saldo_folios;

            saldo_folios = iif(saldo_folios is null, 0, saldo_folios);

            select
            socmain01_cab_empresas.rela_socusua30,
            socmain01_cab_empresas.socmain01_propietaria,
            socmain01_cab_empresas.socmain01_fapl
            from socmain01_cab_empresas
            where socmain01_cab_empresas.id_socmain01 = :id_socmain01
            into :rela_socusua30,
                 :is_reseller,
                 :socmain01_fapl;


            SELECT
            SOCMAIN20_CAB_ORGANIZACION.id_socmain20
            FROM SOCMAIN20_CAB_ORGANIZACION
            WHERE SOCMAIN20_CAB_ORGANIZACION.rela_socmain01 = :id_socmain01
            INTO :rela_socmain20;

            select min(socmain21_arb_organizacion.id_socmain21)
            from socmain21_arb_organizacion
            WHERE socmain21_arb_organizacion.rela_socmain20 = :rela_socmain20
            into :rela_socmain21;

            suspend;
        end 
    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCMAIN21_WEB (
    REL_SOCMAIN01 BIGINT)
RETURNS (
    ID_SOCMAIN21 BIGINT,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_FAPL TIMESTAMP)
AS
declare variable ID_SOCMAIN20 bigint;
begin
    SELECT socmain20_cab_organizacion.id_socmain20
    FROM socmain20_cab_organizacion
    WHERE socmain20_cab_organizacion.rela_socmain01 = :rel_socmain01
    INTO :id_socmain20;

    for select
    socmain21_arb_organizacion.id_socmain21,
    socmain21_arb_organizacion.socmain21_descripcion,
    socmain21_arb_organizacion.socmain21_fapl
    from socmain21_arb_organizacion
    where socmain21_arb_organizacion.rela_socmain20 = :id_socmain20
    and not exists (select first 1 socmain21_arb_organizacion.id_socmain21
         from socmain21_arb_organizacion arb
         where arb.rela_socmain21 = socmain21_arb_organizacion.id_socmain21
    )
    order by socmain21_arb_organizacion.socmain21_descripcion
    into :id_socmain21,
         :socmain21_descripcion,
         :socmain21_fapl
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCMAIN80 (
    COD_POSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCMAIN80 BIGINT,
    SOCMAIN80_D_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CODIGO INTEGER,
    SOCMAIN80_D_ASENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_TIPO_ASENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CIUDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_MNPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DAR_ALTA INTEGER)
AS
declare variable SOCMAIN80 varchar(400);
declare variable IS_ENTRO integer;
declare variable POS integer;
declare variable COD_POSTAL_FIND varchar(50);
begin
    cod_postal = trim(cod_postal);

    if (CHAR_LENGTH(cod_postal) <> 0) then
    begin
        cod_postal = LPAD(cod_postal, 5 , '0');
    end

    IS_ENTRO = 0;
    DAR_ALTA = 0;
    SOCMAIN80 = 'SELECT * FROM C_CODIGOPOSTAL WHERE SOCMAIN80_D_CODIGO = ''' || :COD_POSTAL || '''';

    for execute statement :SOCMAIN80
    on external 'SMXSEG'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :ID_SOCMAIN80,
         :socmain80_d_pais,
         :SOCMAIN80_D_CODIGO,
         :SOCMAIN80_D_ASENTA,
         :SOCMAIN80_D_TIPO_ASENTA,
         :SOCMAIN80_D_CIUDAD,
         :SOCMAIN80_D_MNPIO,
         :SOCMAIN80_D_ESTADO,
         :SOCMAIN80_D_CP
    do
    BEGIN
        IS_ENTRO = 1;
        suspend;
    end

    if (IS_ENTRO = 0) then
    begin
        SOCMAIN80 = 'SELECT * FROM C_CODIGOPOSTAL WHERE SOCMAIN80_D_CP = ''' || :COD_POSTAL || '''';
    
        for execute statement :SOCMAIN80
        on external 'SMXSEG'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :ID_SOCMAIN80,
             :socmain80_d_pais,
             :SOCMAIN80_D_CODIGO,
             :SOCMAIN80_D_ASENTA,
             :SOCMAIN80_D_TIPO_ASENTA,
             :SOCMAIN80_D_CIUDAD,
             :SOCMAIN80_D_MNPIO,
             :SOCMAIN80_D_ESTADO,
             :SOCMAIN80_D_CP
        do
        BEGIN
            IS_ENTRO = 1;
            suspend;
        end
    end

    if (is_entro = 0) then
    begin
        pos = 4;
        while (pos <> 0) do
        begin
            cod_postal_find = SUBSTRING(cod_postal FROM 1 FOR pos);

            SOCMAIN80 = 'SELECT first 1 * FROM C_CODIGOPOSTAL WHERE SOCMAIN80_D_CP like ''' || :cod_postal_find || '%''';
    
            for execute statement :SOCMAIN80
            on external 'SMXSEG'
            AS
            USER 'SYSDBA' PASSWORD 'masterkey'
            into :ID_SOCMAIN80,
                 :socmain80_d_pais,
                 :SOCMAIN80_D_CODIGO,
                 :SOCMAIN80_D_ASENTA,
                 :SOCMAIN80_D_TIPO_ASENTA,
                 :SOCMAIN80_D_CIUDAD,
                 :SOCMAIN80_D_MNPIO,
                 :SOCMAIN80_D_ESTADO,
                 :SOCMAIN80_D_CP
            do
            BEGIN
                IS_ENTRO = 1;
                dar_alta = 1;
                suspend;
            end

            if (is_entro = 1) then
                break;

            pos = pos - 1;
        end

    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCMAIN80_SAT (
    COD_POSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCMAIN80 BIGINT,
    SOCMAIN80_D_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
