    SOCMAIN80_D_MNPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DAR_ALTA INTEGER,
    SAT_ESTADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SAT_MUNICIPIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SAT_LOCALIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCMAIN80 varchar(400);
