    DAR_ALTA = 0;
    SOCMAIN80 = 'SELECT * FROM C_CODIGOPOSTAL_SAT WHERE SOCMAIN80_D_CODIGO = ''' || :COD_POSTAL || '''';

    for execute statement :SOCMAIN80
    on external 'SMXSEG'
    AS
