    into :ID_SOCMAIN80,
         :socmain80_d_pais,
         :SOCMAIN80_D_CODIGO,
         :SOCMAIN80_D_ASENTA,
         :SOCMAIN80_D_TIPO_ASENTA,
         :SOCMAIN80_D_CIUDAD,
