         :SAT_ESTADO,
         :SAT_MUNICIPIO,
         :SAT_LOCALIDAD
    do
    BEGIN
        IS_ENTRO = 1;
        suspend;
    end

    if (IS_ENTRO = 0) then
    begin
        SOCMAIN80 = 'SELECT * FROM C_CODIGOPOSTAL_SAT WHERE SOCMAIN80_D_CP = ''' || :COD_POSTAL || '''';
    
        for execute statement :SOCMAIN80
        on external 'SMXSEG'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :ID_SOCMAIN80,
             :socmain80_d_pais,
             :SOCMAIN80_D_CODIGO,
             :SOCMAIN80_D_ASENTA,
             :SOCMAIN80_D_TIPO_ASENTA,
             :SOCMAIN80_D_CIUDAD,
             :SOCMAIN80_D_MNPIO,
             :SOCMAIN80_D_ESTADO,
             :SOCMAIN80_D_CP,
             :SAT_ESTADO,
             :SAT_MUNICIPIO,
             :SAT_LOCALIDAD
        do
        BEGIN
            IS_ENTRO = 1;
            suspend;
        end
    end

    if (is_entro = 0) then
    begin
        pos = 4;
        while (pos <> 0) do
        begin
            cod_postal_find = SUBSTRING(cod_postal FROM 1 FOR pos);

            SOCMAIN80 = 'SELECT first 1 * FROM C_CODIGOPOSTAL_SAT WHERE SOCMAIN80_D_CP like ''' || :cod_postal_find || '%''';
    
            for execute statement :SOCMAIN80
            on external 'SMXSEG'
            AS
            USER 'SYSDBA' PASSWORD 'masterkey'
            into :ID_SOCMAIN80,
                 :socmain80_d_pais,
                 :SOCMAIN80_D_CODIGO,
                 :SOCMAIN80_D_ASENTA,
                 :SOCMAIN80_D_TIPO_ASENTA,
                 :SOCMAIN80_D_CIUDAD,
                 :SOCMAIN80_D_MNPIO,
                 :SOCMAIN80_D_ESTADO,
                 :SOCMAIN80_D_CP,
                 :SAT_ESTADO,
                 :SAT_MUNICIPIO,
                 :SAT_LOCALIDAD
            do
            BEGIN
                IS_ENTRO = 1;
                dar_alta = 1;
                suspend;
            end

            if (is_entro = 1) then
                break;

            pos = pos - 1;
        end

    end
end^


