    SOCMAIN80_D_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CODIGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
