CREATE OR ALTER PROCEDURE CBO_SOCSYST10_BAN01_WEB (
    RELA_SICINGR01 BIGINT)
RETURNS (
    ID_SOCSYST10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_GRUPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    for select
    CBO_SOCSYST10_BAN01.id_socsyst10,
    CBO_SOCSYST10_BAN01.socsyst10_codigo,
    CBO_SOCSYST10_BAN01.socsyst10_descripcion,
    CBO_SOCSYST10_BAN01.socsyst10_grupo,
    CBO_SOCSYST10_BAN01.rfc
    from CBO_SOCSYST10_BAN01
    order by CBO_SOCSYST10_BAN01.socsyst10_descripcion
    into :id_socsyst10,
         :socsyst10_codigo,
         :socsyst10_descripcion,
         :socsyst10_grupo,
         :rfc
    do
    begin
        cuenta = 'Sin asignar';
        moneda = 'Moneda: Sin asignar';

        select first 1
        sicingr02_det_bancos.sicingr02_cuenta,
        MON.socsyst10_descripcion
        from sicingr02_det_bancos
        INNER JOIN socsyst10_det_remoto MON ON (MON.id_socsyst10 = sicingr02_det_bancos.rela_socsyst10_ctm01)
        where sicingr02_det_bancos.rela_sicingr01 = :rela_sicingr01
        and sicingr02_det_bancos.rela_socsyst10_ban01 = :id_socsyst10
        order by sicingr02_det_bancos.id_sicingr02 desc
        INTO :cuenta,
             :moneda;

        ve = trim(:socsyst10_descripcion) || ' ' || trim(:moneda) || ' Cuenta : ' || trim(:cuenta);
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCSYST10_CO001_FILTRO (
    ID_SOCMAIN01 BIGINT,
    MODO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCSYST10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_GRUPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable NO_INCLUIR integer;
declare variable SOCMAIN10_MODO integer;
begin
    for SELECT
    cbo_socsyst10_co001.id_socsyst10,
    cbo_socsyst10_co001.socsyst10_codigo,
    cbo_socsyst10_co001.socsyst10_descripcion,
    cbo_socsyst10_co001.socsyst10_grupo
    from cbo_socsyst10_co001
    into :id_socsyst10,
         :socsyst10_codigo,
         :socsyst10_descripcion,
         :socsyst10_grupo
    do
    begin
        NO_INCLUIR = 0;

        if (modo = 'E') then
        BEGIN
            socmain10_modo = null;

            select SOCMAIN10_DET_CONTADORES.id_socmain10
            from SOCMAIN10_DET_CONTADORES
            where SOCMAIN10_DET_CONTADORES.rela_socmain01 = :id_socmain01
            and SOCMAIN10_DET_CONTADORES.rela_socsyst10_co001 = :id_socsyst10
            and SOCMAIN10_DET_CONTADORES.socmain10_modo = 0
            into :socmain10_modo;

            if (socmain10_modo is null) then
                NO_INCLUIR = 1;
        END
        ELSE
        BEGIN
            socmain10_modo = null;

            select SOCMAIN10_DET_CONTADORES.id_socmain10
            from SOCMAIN10_DET_CONTADORES
            where SOCMAIN10_DET_CONTADORES.rela_socmain01 = :id_socmain01
            and SOCMAIN10_DET_CONTADORES.rela_socsyst10_co001 = :id_socsyst10
            and SOCMAIN10_DET_CONTADORES.socmain10_modo = 1
            into :socmain10_modo;

            if (socmain10_modo is null) then
                NO_INCLUIR = 1;
        END

        if (NO_INCLUIR = 0) then
            suspend;
    end
end^


