CREATE OR ALTER PROCEDURE CBO_SOCSYST10_CPO01_FILTRO (
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SOCSYST10X BIGINT)
RETURNS (
    RELA_SOCSYST10 BIGINT,
    ID_SOCSYST10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(500) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10 varchar(400);
begin
    if (ID_SOCSYST10X IS NOT NULL) then
    BEGIN
        SOCSYST10 = 'SELECT SOCSYST10_CODIGO FROM C_CLAVEPRODSERV where ' ||
                    'ID_SOCSYST10 = ' || :id_socsyst10x;

        execute statement :SOCSYST10
        on external 'SMXSEG'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :SOCSYST10_CODIGO;

        codigo = SUBSTRING(:SOCSYST10_CODIGO FROM 1 FOR 4);

        select cbo_socsyst10_cpo01_root.id_socsyst10
        from cbo_socsyst10_cpo01_root
        where cbo_socsyst10_cpo01_root.socsyst10_codigo = :codigo
        into :rela_socsyst10;
    END

    if (codigo is null) then
        codigo = '01010101';

    SOCSYST10 = 'SELECT ID_SOCSYST10, SOCSYST10_CODIGO, VE FROM C_CLAVEPRODSERV ' ||
                'where c_claveprodserv.socsyst10_codigo like ''' || :codigo || '%''';

    for execute statement :SOCSYST10
    on external 'SMXSEG'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :ID_SOCSYST10,
         :SOCSYST10_CODIGO,
         :SOCSYST10_DESCRIPCION
    do
    BEGIN
        suspend;
    end
end^


