CREATE OR ALTER PROCEDURE CBO_SOCSYST10_CTM01_COTIZA
RETURNS (
    ID_SOCSYST10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_COTIZA DOUBLE PRECISION)
AS
begin
    for select
    cbo_socsyst10_ctm01.id_socsyst10,
    cbo_socsyst10_ctm01.socsyst10_codigo,
    cbo_socsyst10_ctm01.socsyst10_descripcion
    from cbo_socsyst10_ctm01
    into :id_socsyst10,
         :socsyst10_codigo,
         :socsyst10_descripcion
    DO
    BEGIN
        socsyst10_cotiza = 1.0;

        if (socsyst10_codigo <> 'MXN') then
        BEGIN
            socsyst10_cotiza = null;

            SELECT first 1
            SICINGR70_CAB_FACTURACION.sicingr70_cambio
            FROM SICINGR70_CAB_FACTURACION
            inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = SICINGR70_CAB_FACTURACION.rela_socsyst10_ctm01 )
            WHERE trim(upper(socsyst10_det_remoto.socsyst10_codigo)) = trim(upper(:socsyst10_codigo))
            and SICINGR70_CAB_FACTURACION.sicingr70_cambio <> 0
            order by SICINGR70_CAB_FACTURACION.id_sicingr70 desc
            INTO :socsyst10_cotiza;

            if (socsyst10_cotiza is null) then
            begin
                SELECT first 1
                pymvent52_det_cotizacion.pymvent52_cotiza
                from pymvent52_det_cotizacion
                where pymvent52_det_cotizacion.rela_socsyst10_ctm01 = :id_socsyst10
                order by pymvent52_det_cotizacion.id_pymvent52 desc
                into :socsyst10_cotiza;
            end

            if (socsyst10_cotiza is null) then
                socsyst10_cotiza = 0.00;
        END

        if (socsyst10_cotiza <> 0.00) then
            suspend;
    END
end^


