CREATE OR ALTER PROCEDURE CBO_SOCUSUA01 (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    ID_SOCUSUA01 BIGINT,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
declare variable FIND_PARAM bigint;
declare variable SQL_C varchar(1000);
begin
    sql_c = 'select
            socsyst10_det_entradas.socsyst10_codigo,
            socusua30_cab_entidades.socusua30_apellido_pat,
            socusua30_cab_entidades.socusua30_apellido_mat,
            socusua30_cab_entidades.socusua30_nombre_razsoc,
            SOCUSUA01_CAB_USUARIOS.rela_socusua30,
            SOCUSUA01_CAB_USUARIOS.id_socusua01,
            SOCUSUA01_CAB_USUARIOS.socusua01_usuario,
            SOCUSUA01_CAB_USUARIOS.socusua01_clave
            from SOCUSUA01_CAB_USUARIOS
            inner join socusua30_cab_entidades on (SOCUSUA01_CAB_USUARIOS.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)';

    if (RELA_SOCUSUA01 is not null and RELA_SOCUSUA01 > 0) then
        sql_c = sql_c || ' where SOCUSUA01_CAB_USUARIOS.id_socusua01 = ' || :rela_socusua01;

    for execute statement :sql_c
    into :TIPO,
         :SOCUSUA30_APELLIDO_PAT,
         :SOCUSUA30_APELLIDO_MAT,
         :SOCUSUA30_NOMBRE_RAZSOC,
         :RELA_SOCUSUA30,
         :ID_SOCUSUA01,
         :USUARIO,
         :CLAVE

    do
    begin
        if (TIPO = 'FISICO') then
            entidad = socusua30_apellido_pat || ' ' || socusua30_apellido_mat || ', ' || SOCUSUA30_NOMBRE_RAZSOC;
        else
            entidad = SOCUSUA30_NOMBRE_RAZSOC;

        suspend;
    end
end^


