        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CBO_SOCUSUA30 (
    RELA_SOCUSUA30 BIGINT)
RETURNS (
    ID_SOCUSUA30 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
declare variable SOCUSUA30_EXTRANJERO integer;
begin
    if (RELA_SOCUSUA30 IS NULL) then
    BEGIN
        FOR SELECT
        cbo_socusua30_pfisicas.id_socusua30,
        cbo_socusua30_pfisicas.socusua30_apellido_pat,
        cbo_socusua30_pfisicas.socusua30_apellido_mat,
        cbo_socusua30_pfisicas.socusua30_nombre_razsoc
        FROM cbo_socusua30_pfisicas
        into :id_socusua30,
             :socusua30_apellido_pat,
             :socusua30_apellido_mat,
             :socusua30_nombre_razsoc
        do
        begin
            tipo = 'F';
            CURP = null;
            rfc = null;

            ENTIDAD = trim(socusua30_nombre_razsoc) || ' ' ||
                      trim(socusua30_apellido_pat) || ' ' ||
                      trim(socusua30_apellido_mat);

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
            INTO :RFC;

            if (rfc is null or trim(rfc) = '' or trim(rfc) = 'null') then
            BEGIN
                select socusua30_cab_entidades.socusua30_extranjero
                from socusua30_cab_entidades
                where socusua30_cab_entidades.id_socusua30 = :id_socusua30
                into :socusua30_extranjero;

                if (socusua30_extranjero = 1) then
                    rfc = 'XEXX010101000';
                else
                    rfc = 'XAXX010101000';
            END

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'CURP'
            INTO :CURP;

            suspend;
        end

        FOR SELECT
        cbo_socusua30_pmorales.id_socusua30,
        cbo_socusua30_pmorales.socusua30_nombre_razsoc
        FROM cbo_socusua30_pmorales
        into :id_socusua30,
             :socusua30_nombre_razsoc
        do
        begin
            tipo = 'M';
            CURP = null;
            RFC = null;
            ENTIDAD = socusua30_nombre_razsoc;

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
            INTO :RFC;

            if (rfc is null or trim(rfc) = '' or trim(rfc) = 'null') then
            BEGIN
                select socusua30_cab_entidades.socusua30_extranjero
                from socusua30_cab_entidades
                where socusua30_cab_entidades.id_socusua30 = :id_socusua30
                into :socusua30_extranjero;

                if (socusua30_extranjero = 1) then
                    rfc = 'XEXX010101000';
                else
                BEGIN
                    rfc = 'XAXX010101000';
                END
            END

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'CURP'
            INTO :CURP;

            suspend;
        end
    END
    ELSE
    BEGIN
        FOR SELECT
        cbo_socusua30_pfisicas.id_socusua30,
        cbo_socusua30_pfisicas.socusua30_apellido_pat,
        cbo_socusua30_pfisicas.socusua30_apellido_mat,
        cbo_socusua30_pfisicas.socusua30_nombre_razsoc
        FROM cbo_socusua30_pfisicas
        WHERE cbo_socusua30_pfisicas.id_socusua30 = :rela_socusua30
        into :id_socusua30,
             :socusua30_apellido_pat,
             :socusua30_apellido_mat,
             :socusua30_nombre_razsoc
        do
        begin
            tipo = 'F';
            CURP = null;
            RFC = null;
            ENTIDAD = trim(socusua30_nombre_razsoc) || ' ' ||
                      trim(socusua30_apellido_pat) || ' ' ||
                      trim(socusua30_apellido_mat);

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
            INTO :RFC;

            if (rfc is null or trim(rfc) = '' or trim(rfc) = 'null') then
            BEGIN
                select socusua30_cab_entidades.socusua30_extranjero
                from socusua30_cab_entidades
                where socusua30_cab_entidades.id_socusua30 = :id_socusua30
                into :socusua30_extranjero;

                if (socusua30_extranjero = 1) then
                    rfc = 'XEXX010101000';
                else
                    rfc = 'XAXX010101000';
            END

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'CURP'
            INTO :CURP;

            suspend;
        end

        FOR SELECT
        cbo_socusua30_pmorales.id_socusua30,
        cbo_socusua30_pmorales.socusua30_nombre_razsoc
        FROM cbo_socusua30_pmorales
        WHERE cbo_socusua30_pmorales.id_socusua30 = :rela_socusua30
        into :id_socusua30,
             :socusua30_nombre_razsoc
        do
        begin
            tipo = 'M';
            CURP = null;
            RFC = null;
            ENTIDAD = socusua30_nombre_razsoc;

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
            INTO :RFC;

            if (rfc is null or trim(rfc) = '' or trim(rfc) = 'null') then
            BEGIN
                select socusua30_cab_entidades.socusua30_extranjero
                from socusua30_cab_entidades
                where socusua30_cab_entidades.id_socusua30 = :id_socusua30
                into :socusua30_extranjero;

                if (socusua30_extranjero = 1) then
                    rfc = 'XEXX010101000';
                else
                    rfc = 'XAXX010101000';
            END

            select socusua32_det_documentos.socusua32_documento
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :id_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'CURP'
            INTO :CURP;

            suspend;
        end
    END
end^


