CREATE OR ALTER PROCEDURE CBO_SOCUSUA30_CTRANS (
    RELA_SICINGR01 BIGINT,
    TIPO_ENTIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCUSUA30 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    tipo_entidad = TRIM(UPPER(tipo_entidad));

    FOR SELECT
    CBO_SOCUSUA30.id_socusua30,
    CBO_SOCUSUA30.tipo,
    CBO_SOCUSUA30.entidad,
    CBO_SOCUSUA30.rfc,
    CBO_SOCUSUA30.curp
    FROM CBO_SOCUSUA30( NULL )
    INNER JOIN sicingr03_det_entidades ON ( sicingr03_det_entidades.rela_socusua30 = CBO_SOCUSUA30.id_socusua30 )
    INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = sicingr03_det_entidades.rela_socsyst10_tec01 )
    WHERE sicingr03_det_entidades.rela_sicingr01 = :rela_sicingr01
    and socsyst10_det_entradas.socsyst10_codigo = :tipo_entidad
    INTO :id_socusua30,
         :tipo,
         :entidad,
         :rfc,
         :curp
    DO
    BEGIN
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE CBO_SOCUSUA30_SICXMLS41 (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    ID_SOCUSUA30 BIGINT,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COUNT_XMLS_CLIENTE INTEGER,
    COUNT_XMLS_CLIENTEX INTEGER,
    COUNT_XMLS_PROVE INTEGER,
    COUNT_XMLS_PROVEX INTEGER,
    COUNT_XMLS_NOMINA INTEGER,
    COUNT_XMLS_CREADITOAFAVOR INTEGER,
    COUNT_XMLS_CREADITOAFAVORX INTEGER,
    COUNT_XMLS_CREDITOENCONTRA INTEGER,
    COUNT_XMLS_CREDITOENCONTRAX INTEGER)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
declare variable CODIGO varchar(50);
declare variable COUNT_XMLS integer;
declare variable TOTAL_COUNT integer;
declare variable ID_SICXMLS01 bigint;
begin
    delete from tmp_socusua30_sicxmls41
    where tmp_socusua30_sicxmls41.usuario = current_user;

    SELECT sicxmls01_cab_parametros.id_sicxmls01
    FROM sicxmls01_cab_parametros
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    insert into tmp_socusua30_sicxmls41(
    tmp_socusua30_sicxmls41.usuario,
    tmp_socusua30_sicxmls41.id_sicxmls04,
    tmp_socusua30_sicxmls41.rela_socusua30,
    tmp_socusua30_sicxmls41.socsyst10_codigo)
    select
    current_user,
    grd_sicxmls04_sinpara_xprove.id_sicxmls04,
    grd_sicxmls04_sinpara_xprove.rela_socusua30,
    grd_sicxmls04_sinpara_xprove.socsyst10_codigo
    from grd_sicxmls04_sinpara_xprove
    where grd_sicxmls04_sinpara_xprove.rela_sicxmls01 = :id_sicxmls01;

    FOR SELECT
    socsyst10_det_entradas.socsyst10_codigo,
    socusua30_cab_entidades.id_socusua30,
    socusua30_cab_entidades.socusua30_apellido_pat,
    socusua30_cab_entidades.socusua30_apellido_mat,
    socusua30_cab_entidades.socusua30_nombre_razsoc
    FROM socusua30_cab_entidades
    INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)
    WHERE EXISTS (
                    SELECT FIRST 1 sicxmls41_det_migracion.id_sicxmls41
                    FROM sicxmls41_det_migracion
                    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
                    WHERE sicxmls40_cab_migracion.rela_socmain01 = :rela_socmain01
                    and sicxmls41_det_migracion.rela_socusua30 = socusua30_cab_entidades.id_socusua30
                    AND sicxmls41_det_migracion.rela_siccont10 IS NULL
                 )
    INTO :socsyst10_codigo,
         :id_socusua30,
         :socusua30_apellido_pat,
         :socusua30_apellido_mat,
         :socusua30_nombre_razsoc
    DO
    BEGIN
        if (socsyst10_codigo = 'FISICO') then
        begin
            tipo = 'M';
            entidad = trim(socusua30_apellido_pat) || ' ' ||
                      trim(socusua30_apellido_mat) || ', ' ||
                      trim(socusua30_nombre_razsoc);
        end
        else if (socsyst10_codigo = 'MORAL') then
        begin
            tipo = 'F';
            entidad = trim(socusua30_nombre_razsoc);
        end

        count_xmls_cliente = 0;
        count_xmls_clientex = 0;
        count_xmls_prove = 0;
        count_xmls_provex = 0;
        count_xmls_nomina = 0;
        count_xmls_creaditoafavor = 0;
        count_xmls_creaditoafavorx = 0;
        count_xmls_creditoencontra = 0;
        count_xmls_creditoencontrax = 0;

        for select
        tmp_socusua30_sicxmls41.socsyst10_codigo,
        count(tmp_socusua30_sicxmls41.id_sicxmls04)
        from tmp_socusua30_sicxmls41
        where tmp_socusua30_sicxmls41.usuario = current_user
        and tmp_socusua30_sicxmls41.rela_socusua30 = :id_socusua30
        group by tmp_socusua30_sicxmls41.socsyst10_codigo
        into :codigo,
             :count_xmls
        do
        begin
            if (codigo = 'PROVE') then
                count_xmls_prove = :count_xmls;
            else if (codigo = 'PROVEX') then
                count_xmls_provex = :count_xmls;
            else if (codigo = 'CLIENTE') then
                count_xmls_cliente = :count_xmls;
            else if (codigo = 'CLIENTEX') then
                count_xmls_clientex = :count_xmls;
            else if (codigo = 'NOMINA') then
                count_xmls_nomina = :count_xmls;
            else if (codigo = 'CREADITOAFAVOR') then
                count_xmls_creaditoafavor = :count_xmls;
            else if (codigo = 'CREADITOAFAVORX') then
                count_xmls_creaditoafavorx = :count_xmls;
            else if (codigo = 'CREDITOENCONTRA') then
                count_xmls_creditoencontra = :count_xmls;
            else if (codigo = 'CREDITOENCONTRAX') then
                count_xmls_creditoencontrax = :count_xmls;

        end

        total_count = count_xmls_prove +
                      count_xmls_provex +
                      count_xmls_cliente +
                      count_xmls_clientex +
                      count_xmls_nomina +
                      count_xmls_creaditoafavor +
                      count_xmls_creaditoafavorx +
                      count_xmls_creditoencontra +
                      count_xmls_creditoencontrax;
        if (total_count <> 0) then
            suspend;
    END
end^


CREATE OR ALTER PROCEDURE CBO_SOCUSUA30_VIEW (
    ID_SOCMAIN01 BIGINT,
    BUSCAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODALIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SICINGR01 BIGINT,
    ID_SOCUSUA30 INTEGER,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable EXISTE bigint;
begin
    buscar = upper(buscar);

    if (modalidad = 'A') then
    BEGIN
        for select
        CBO_SOCUSUA30_ALL.id_socusua30,
        CBO_SOCUSUA30_ALL.tipo,
        CBO_SOCUSUA30_ALL.entidad
        from CBO_SOCUSUA30_ALL
        where upper(CBO_SOCUSUA30_ALL.entidad)  like '%' || :buscar || '%'
        into :id_socusua30,
             :tipo,
             :entidad
        do
        begin
            existe = null;
            rela_sicingr01 = null;
    
            select first 1
            sicingr01_cab_clientes.id_sicingr01
            from sicingr01_cab_clientes
            where sicingr01_cab_clientes.rela_socusua30 = :id_socusua30
            and sicingr01_cab_clientes.rela_socmain01 = :id_socmain01
            into :existe;
    
            if (existe is not null) then
            begin
                origen = 'Cliente';
                rela_sicingr01 = existe;
                suspend;
            end
            else
            begin
                existe = null;
        
                select first 1
                sicegre01_cab_proveedores.id_sicegre01
                from sicegre01_cab_proveedores
                where sicegre01_cab_proveedores.rela_socusua30 = :id_socusua30
                and sicegre01_cab_proveedores.rela_socmain01 = :id_socmain01
                into :existe;    
    
                if (existe is not null) then
                begin
                    origen = 'Proveedor';
                    suspend;
                end
                else
                begin
                    existe = null;
            
                    select first 1
                    sicnomi01_cab_empleados.id_sicnomi01
                    from sicnomi01_cab_empleados
                    where sicnomi01_cab_empleados.rela_socusua30 = :id_socusua30
                    and sicnomi01_cab_empleados.rela_socmain01 = :id_socmain01
                    into :existe;    
    
                    if (existe is not null) then
                    begin
                        origen = 'Empleado';
                        suspend;
                    end
                    else
                    begin
                        existe = null;
    
                        select first 1
                        socusua01_cab_usuarios.id_socusua01
                        from socusua01_cab_usuarios
                        inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = socusua01_cab_usuarios.rela_socusua30)
                        where socusua01_cab_usuarios.rela_socusua30 = :id_socusua30
                        and exists ( select socusua02_det_organizacion.id_socusua02
                                       from socusua02_det_organizacion
                                       where socusua02_det_organizacion.rela_socmain01 = :id_socmain01
                                        and socusua02_det_organizacion.rela_socusua01 = socusua01_cab_usuarios.id_socusua01
                                     )
                        into :existe;
    
                        if (existe is not null) then
                        begin
                            origen = 'Usuario';
                            suspend;    
                        end
                    end
                end
            end
    end
    END
    else if (modalidad = 'E') then
    BEGIN
        FOR select
        CBO_SOCUSUA01_ALL.rela_socusua30,
        CBO_SOCUSUA01_ALL.tipo,
        CBO_SOCUSUA01_ALL.entidad
        from CBO_SOCUSUA01_ALL(:id_socmain01)
        where upper(CBO_SOCUSUA01_ALL.entidad)  like '%' || :buscar || '%'
        into :id_socusua30,
             :tipo,
             :entidad
        do
        begin
            origen = 'Usuario';
            suspend;
        end
    END

end^


CREATE OR ALTER PROCEDURE CFDI_ADDENDA_MABE (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_FACADDE01 INTEGER,
    FACADDE01_CODPROVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACADDE01_PLANTAENTREGA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACADDE01_ENTREGA_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACADDE01_ENTREGA_CP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACADDE01_ENTREGA_NOEXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACADDE01_ENTREGA_NOINT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    select
    facadde01_cab_mabe.id_facadde01,
    facadde01_cab_mabe.facadde01_codprove,
    facadde01_cab_mabe.facadde01_plantaentrega,
    facadde01_cab_mabe.facadde01_entrega_calle,
    facadde01_cab_mabe.facadde01_entrega_cp,
    facadde01_cab_mabe.facadde01_entrega_noext,
    facadde01_cab_mabe.facadde01_entrega_noint
    from facadde01_cab_mabe
    where facadde01_cab_mabe.rela_sicingr70 = :rela_sicingr70
    into :id_facadde01,
         :facadde01_codprove,
         :facadde01_plantaentrega,
         :facadde01_entrega_calle,
         :facadde01_entrega_cp,
         :facadde01_entrega_noext,
         :facadde01_entrega_noint;

    if (facadde01_entrega_calle is not null and trim(facadde01_entrega_calle) = '') then
        facadde01_entrega_calle = null;

    if (facadde01_entrega_cp is not null and trim(facadde01_entrega_cp) = '') then
        facadde01_entrega_cp = null;

    if (facadde01_entrega_noext is not null and trim(facadde01_entrega_noext) = '') then
        facadde01_entrega_noext = null;

    if (facadde01_entrega_noint is not null and trim(facadde01_entrega_noint) = '') then
        facadde01_entrega_noint = null;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_CANCELA (
    RELA_SICINGR70 BIGINT,
    ES_CANCELABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_CANCELABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICINGR70 BIGINT)
AS
declare variable SERIE varchar(50);
declare variable DOCNRO varchar(50);
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SICXMLS41 bigint;
declare variable RELA_SICCONT10 bigint;
declare variable ID_SICINGR50 bigint;
declare variable FOLIO_CANCELADO varchar(50);
declare variable FOLIOS_CANCELADOS varchar(1000);
declare variable SICINGR74_SELLO varchar(8000);
begin
    select
    sicingr70_cab_facturacion.rela_socmain01,
    sicingr70_cab_facturacion.rela_socmain21,
    sicingr70_cab_facturacion.sicingr70_serie,
    sicingr70_cab_facturacion.sicingr70_docnro
    from sicingr70_cab_facturacion where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :rela_socmain01,
         :rela_socmain21,
         :serie,
         :docnro;

    serie = iif (serie is null, '', serie);

    SELECT
    sicxmls41_det_migracion.rela_siccont10,
    sicingr74_dep_cfdis.rela_sicxmls41,
    sicingr74_dep_cfdis.SICINGR74_SELLO
    FROM sicingr74_dep_cfdis
    inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicingr74_dep_cfdis.rela_sicxmls41 )
    WHERE sicingr74_dep_cfdis.rela_sicingr70 = :rela_sicingr70
    into :rela_siccont10,
         :rela_sicxmls41,
         :sicingr74_sello;

    sicingr74_sello = substring(sicingr74_sello from CHAR_LENGTH (sicingr74_sello) - 7 for CHAR_LENGTH (sicingr74_sello));

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    insert into sicingr77_det_cfdiscancelados( sicingr77_det_cfdiscancelados.rela_sicingr70,
                                               sicingr77_det_cfdiscancelados.sicingr77_uuid,
                                               sicingr77_det_cfdiscancelados.sicingr77_uuid_fecha,
                                               sicingr77_det_cfdiscancelados.sicingr77_fcancelado,
                                               sicingr77_det_cfdiscancelados.sicingr77_folio,
                                               sicingr77_det_cfdiscancelados.sicingr77_serie,
                                               sicingr77_det_cfdiscancelados.sicingr77_uuid_importe,
                                               sicingr77_det_cfdiscancelados.sicingr77_uuid_smx,
                                               sicingr77_det_cfdiscancelados.sicingr77_cancelable,
                                               sicingr77_det_cfdiscancelados.sicingr77_status,
                                               sicingr77_det_cfdiscancelados.sicingr77_ult8_sello)
    select
    sicingr74_dep_cfdis.rela_sicingr70,
    sicingr74_dep_cfdis.sicingr74_uuid,
    sicingr74_dep_cfdis.sicingr74_uuid_fecha,
    current_timestamp,
    :docnro,
    :serie,
    sicingr74_dep_cfdis.sicingr74_uuid_importe,
    sicingr74_dep_cfdis.sicingr74_uuid_smx,
    :es_cancelable,
    :status_cancelable,
    :sicingr74_sello
    from sicingr74_dep_cfdis
    where sicingr74_dep_cfdis.rela_sicingr70 = :rela_sicingr70;

    delete from sicingr74_dep_cfdis
    where sicingr74_dep_cfdis.rela_sicingr70 = :rela_sicingr70;

    id_sicingr70 = :rela_sicingr70;

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    if (rela_siccont10 is null) then
        delete from sicxmls41_det_migracion where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41;
    else
    BEGIN
        select sicingr50_det_ctacte.id_sicingr50
        from sicingr50_det_ctacte
        where sicingr50_det_ctacte.rela_siccont10 = :rela_siccont10
        into :id_sicingr50;

        delete from sicingr61_det_depositos where sicingr61_det_depositos.rela_sicingr50 = :id_sicingr50;
        delete from siccont10_cab_polizas where siccont10_cab_polizas.id_siccont10 = :rela_siccont10;
    END

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    folios_cancelados = '';

    for select sicingr77_det_cfdiscancelados.sicingr77_folio
    from sicingr77_det_cfdiscancelados
    where sicingr77_det_cfdiscancelados.rela_sicingr70 = :rela_sicingr70
    into :folio_cancelado
    do
    begin
        folios_cancelados = folios_cancelados || ' ' || folio_cancelado;
    end

    folios_cancelados = 'Timbrado Cancelado. Folios Cancelados (' || trim(:folios_cancelados) || ')';

    Select smx$soc_contadores.nrodoc, smx$soc_contadores.serie
    from smx$soc_contadores(:rela_socmain01, :rela_socmain21, :rela_sicingr70, 'SICINGR70')
    into :docnro, :serie;

    update sicingr70_cab_facturacion set sicingr70_cab_facturacion.sicingr70_serie = :serie,
                                         sicingr70_cab_facturacion.sicingr70_docnro = :docnro,
                                         sicingr70_cab_facturacion.sicingr70_status = :folios_cancelados
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70;

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    execute procedure PRD_SICINGR88_CREAPOLIZAS :rela_sicingr70, 'D';

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_CFDIS_RELACIONADOS (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR73 BIGINT,
    TIPO_RELACION VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_RELACION VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICXMLS41 bigint;
declare variable RELA_SICINGR77 bigint;
begin
    FOR SELECT
    sicingr73_det_relacionados.id_sicingr73,
    sicingr73_det_relacionados.rela_sicxmls41,
    sicingr73_det_relacionados.rela_sicingr77,
    socsyst10_det_remoto.socsyst10_codigo
    FROM sicingr73_det_relacionados
    INNER JOIN socsyst10_det_remoto ON ( socsyst10_det_remoto.id_socsyst10 = sicingr73_det_relacionados.rela_socsyst10_tre01 )
    WHERE sicingr73_det_relacionados.rela_sicingr70 = :rela_sicingr70
    INTO :id_sicingr73,
         :rela_sicxmls41,
         :rela_sicingr77,
         :tipo_relacion
    do
    begin
        if (rela_sicxmls41 is not null) then
            select sicxmls41_det_migracion.sicxmls41_uuid
            from sicxmls41_det_migracion
            where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
            into :uuid_relacion;

        else if (rela_sicingr77 is not null) then
            select sicingr77_det_cfdiscancelados.sicingr77_uuid
            from sicingr77_det_cfdiscancelados
            where sicingr77_det_cfdiscancelados.id_sicingr77 = :rela_sicingr77
            into :uuid_relacion;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_CODIGO_QR (
    MODALIDAD INTEGER,
    ID BIGINT,
    NEW_UUID_QR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_CFDI BIGINT,
    RFC_EMISOR VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_RECEPTOR VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL DOUBLE PRECISION,
    SELLO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable SELLO_LARGO varchar(8000);
begin
    id_cfdi = 1;

    if (modalidad = 1) then
    begin
        NEW_UUID_QR = upper(NEW_UUID_QR);

        select first 1 sicingr74_dep_cfdis.sicingr74_sello
        from sicingr74_dep_cfdis
        where sicingr74_dep_cfdis.sicingr74_uuid = :NEW_UUID_QR
        into :sello;

        if (sello  is null) then
        begin
            select first 1 sicnomi74_dep_cfdis.sicnomi74_sello
            from sicnomi74_dep_cfdis
            where sicnomi74_dep_cfdis.sicnomi74_uuid = :NEW_UUID_QR
            into :sello;
        end

        if (sello  is null) then
        begin
            select first 1 sicpago74_dep_cfdis.sicpago74_sello
            from sicpago74_dep_cfdis
            where sicpago74_dep_cfdis.sicpago74_uuid = :NEW_UUID_QR
            into :sello;
        end

        if (sello is not null) then
        begin
            rfc_emisor = '';
            rfc_receptor = '';
            total = 0;
            sello = substring(sello from CHAR_LENGTH (sello) - 7 for CHAR_LENGTH (sello));

            suspend;
        end
    end
    else if (new_uuid_qr is null) then
    begin
        /* MODALIDAD_CFDI_GRAL */
        if (modalidad = 0) then
        begin
            select
            CFDI_COMPROBANTE.total,
            CFDI_COMPROBANTE.rfc
            from CFDI_COMPROBANTE(:id)
            into :total,
                 :rfc_receptor;
    
            select
            sicingr70_cab_facturacion.rela_socmain01,
            sicingr74_dep_cfdis.sicingr74_sello
            from sicingr70_cab_facturacion
            inner join sicingr74_dep_cfdis on (sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
            where sicingr70_cab_facturacion.id_sicingr70 = :id
            into :rela_socmain01,
                 :sello_largo;

            if (rela_socmain01 is null) then
            begin
                select first 1
                sicingr70_cab_facturacion.rela_socmain01,
                sicingr77_det_cfdiscancelados.sicingr77_ult8_sello
                from sicingr70_cab_facturacion
                inner join sicingr77_det_cfdiscancelados on (sicingr77_det_cfdiscancelados.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
                where sicingr70_cab_facturacion.id_sicingr70 = :id
                order by sicingr77_det_cfdiscancelados.id_sicingr77 desc
                into :rela_socmain01,
                     :sello_largo;
            end
        end
        /* MODALIDAD_CFDI_NOMINA */
        else if (modalidad = 2) then
        begin
            select
            cfdi_comprobante_nomina.total,
            cfdi_comprobante_nomina.rfc
            from cfdi_comprobante_nomina(:id)
            into :total,
                 :rfc_receptor;
    
            select
            sicnomi70_cab_nomina.rela_socmain01,
            sicnomi74_dep_cfdis.sicnomi74_sello
            from sicnomi70_cab_nomina
            inner join sicnomi74_dep_cfdis on (sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70)
            where sicnomi70_cab_nomina.id_sicnomi70 = :id
            into :rela_socmain01,
                 :sello_largo;
        end
        /* MODALIDAD_CFDI_PAGO */
        else if (modalidad = 3) then
        begin
            select
            cfdi_comprobante_pago.total,
            cfdi_comprobante_pago.rfc
            from cfdi_comprobante_pago(:id)
            into :total,
                 :rfc_receptor;
    
            select
            sicpago70_cab_pago.rela_socmain01,
            sicpago74_dep_cfdis.sicpago74_sello
            from sicpago70_cab_pago
            inner join sicpago74_dep_cfdis on (sicpago74_dep_cfdis.rela_sicpago70 = sicpago70_cab_pago.id_sicpago70)
            where sicpago70_cab_pago.id_sicpago70 = :id
            into :rela_socmain01,
                 :sello_largo;

            if (rela_socmain01 is null) then
            begin
                select first 1
                sicpago70_cab_pago.rela_socmain01,
                'sin sello'
                from sicpago70_cab_pago
                where sicpago70_cab_pago.id_sicpago70 = :id
                into :rela_socmain01,
                     :sello_largo;
            end
        end


        select
        cfdi_empresa.rfc
        from cfdi_empresa(:rela_socmain01)
        into :rfc_emisor;

        if (CHAR_LENGTH (sello_largo) > 8) then
            sello = substring(sello_largo from CHAR_LENGTH (sello_largo) - 7 for CHAR_LENGTH (sello_largo));
        else
            sello = sello_largo;

    end
    else if (new_uuid_qr is not null) then
    begin
        /* MODALIDAD_CFDI_GRAL */
        if (modalidad = 0) then
        begin
            UPDATE SICINGR74_DEP_CFDIS SET SICINGR74_DEP_CFDIS.sicingr74_uuid_smx_qrcode = :new_uuid_qr
            WHERE SICINGR74_DEP_CFDIS.rela_sicingr70 = :id;
        end
        /* MODALIDAD_CFDI_NOMINA */
        else if (modalidad = 2) then
        begin
            UPDATE SICNOMI74_DEP_CFDIS SET SICNOMI74_DEP_CFDIS.sicnomi74_uuid_smx_qrcode = :new_uuid_qr
            WHERE SICNOMI74_DEP_CFDIS.rela_sicnomi70 = :id;
        end
        /* MODALIDAD_CFDI_PAGO */
        else if (modalidad = 3) then
        begin
            UPDATE SICPAGO74_DEP_CFDIS SET SICPAGO74_DEP_CFDIS.sicpago74_uuid_smx_qrcode = :new_uuid_qr
            WHERE SICPAGO74_DEP_CFDIS.rela_sicpago70 = :id;
        end

        rfc_emisor = null;
        rfc_receptor = null;
        total = null;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_COMPLE_COMERE_CAB (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_FACCOMP01 BIGINT,
    CINCOTERM VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOTAS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMBIO DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    E_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    E_NRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    E_CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    E_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    E_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_NRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IDTRIB VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30_EMISOR bigint;
declare variable RELA_SOCUSUA30_RECEPTOR bigint;
begin
    select
    socmain01_cab_empresas.rela_socusua30,
    sicingr01_cab_clientes.rela_socusua30,
    FACCOMP01_CAB_COMERE.id_faccomp01,
    socsyst10_det_remoto.socsyst10_codigo,
    FACCOMP01_CAB_COMERE.faccomp01_notas,
    FACCOMP01_CAB_COMERE.faccomp01_cambiousd,
    sicingr70_cab_facturacion.sicingr70_neto
    from FACCOMP01_CAB_COMERE
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = FACCOMP01_CAB_COMERE.rela_sicingr70)
    inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = FACCOMP01_CAB_COMERE.rela_socsyst10_tic01)
    inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.id_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01)
    inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = sicingr70_cab_facturacion.rela_socmain01)
    where FACCOMP01_CAB_COMERE.rela_sicingr70 = :rela_sicingr70
    into :rela_socusua30_emisor,
         :rela_socusua30_receptor,
         :id_faccomp01,
         :CINCOTERM,
         :NOTAS,
         :CAMBIO,
         :TOTAL;

    select socusua32_det_documentos.socusua32_documento
    from socusua32_det_documentos
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001 )
    where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_emisor
    and socsyst10_det_entradas.socsyst10_codigo = 'CURP'
    into :curp;

    select socusua32_det_documentos.socusua32_documento
    from socusua32_det_documentos
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001 )
    where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_receptor
    and socsyst10_det_entradas.socsyst10_codigo = 'IDTRIB'
    into :idtrib;

    select first 1
    socusua36_det_domicilios.socusua36_codpostal,
    socusua36_det_domicilios.socusua36_calle,
    socusua36_det_domicilios.socusua36_nro,
    socmain80_cab_codpostales.socmain80_d_estado,
    iif(socmain80_cab_codpostales.socmain80_d_pais is null, 'MEX', socmain80_cab_codpostales.socmain80_d_pais)
    from socusua36_det_domicilios
    inner join socmain80_cab_codpostales on (socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80)
    where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_emisor
    order by socusua36_det_domicilios.id_socusua36 desc
    into :e_codpostal,
         :e_calle,
         :e_nro,
         :e_estado,
         :e_pais;

    --e_estado = 'MIC';

    select first 1
    socusua36_det_domicilios.socusua36_codpostal,
    socusua36_det_domicilios.socusua36_calle,
    socusua36_det_domicilios.socusua36_nro,
    socmain80_cab_codpostales.socmain80_d_estado,
    iif(socmain80_cab_codpostales.socmain80_d_pais is null, 'MEX', socmain80_cab_codpostales.socmain80_d_pais)
    from socusua36_det_domicilios
    inner join socmain80_cab_codpostales on (socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80)
    where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_receptor
    order by socusua36_det_domicilios.id_socusua36 desc
    into :r_codpostal,
         :r_calle,
         :r_nro,
         :r_estado,
         :r_pais;

    --r_estado = 'FL';

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_COMPLE_COMERE_DET (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR71 BIGINT,
    SICINGR71_CANTIDAD DOUBLE PRECISION,
    SICINGR71_FRACCION VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_IMPORTE_NETO DOUBLE PRECISION,
    SICINGR71_IMPORTE_UNIDAD DOUBLE PRECISION)
AS
begin
    FOR
    SELECT
    max(sicingr71_det_facturacion.id_sicingr71),
    sicingr71_det_facturacion.sicingr71_codigo,
    sicingr71_det_facturacion.sicingr71_fraccion,
    sum(sicingr71_det_facturacion.sicingr71_cantidad),
    sum(sicingr71_det_facturacion.sicingr71_importe_unidad),
    sum(sicingr71_det_facturacion.sicingr71_importe_neto)
    FROM sicingr71_det_facturacion
    WHERE sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    group by sicingr71_det_facturacion.sicingr71_codigo,
             sicingr71_det_facturacion.sicingr71_fraccion
    into :id_sicingr71,
         :sicingr71_codigo,
         :sicingr71_fraccion,
         :sicingr71_cantidad,
         :sicingr71_importe_unidad,
         :sicingr71_importe_neto
    DO
    BEGIN
        unidad = '01';
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE CFDI_COMPLE_CPORTE_CAB (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR81 BIGINT,
    SICINGR81_DIST_REC INTEGER,
    LICENCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_EMPRESA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PERMISO_SCT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PLACAS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ANO INTEGER,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OPERADOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ASEGURADORA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_CAMION VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DES_ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DES_DESTINO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_DESTINO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOST_ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIRECCION_ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOST_DESTINO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIRECCION_DESTINO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO_ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MUNICIPIO_ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LOCALIDAD_ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO_DESTINO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MUNICIPIO_DESTINO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LOCALIDAD_DESTINO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_SALIDA TIMESTAMP,
    FECHA_LLEGADA TIMESTAMP,
    CANT_PRODUCTOS INTEGER,
    PESO_BRUTO DOUBLE PRECISION,
    SICINGR81_DOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IDTRIB_ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IDTRIB_DESTINO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_PESO DOUBLE PRECISION)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SOCSYST10_POR02 bigint;
declare variable RELA_SOCSYST10_POR05 bigint;
declare variable RELA_SOCUSUA30_ORIGEN bigint;
declare variable RELA_SOCUSUA30_DESTINO bigint;
declare variable RELA_SOCMAIN80_ORIGEN bigint;
declare variable RELA_SOCMAIN80_DESTINO bigint;
declare variable ID_SOCSYST10_IDTRIB bigint;
begin
    select
    sicingr70_cab_facturacion.rela_socmain01
    from sicingr70_cab_facturacion
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :rela_socmain01;

    select
    cbo_socmain01.rfc
    from cbo_socmain01
    where cbo_socmain01.id_socmain01 = :rela_socmain01
    into :rfc_empresa;

    select
    socmain01_cab_empresas.rela_socusua30
    from socmain01_cab_empresas
    where socmain01_cab_empresas.id_socmain01 = :rela_socmain01
    into :rela_socusua30;

    select
    CBO_SOCSYST10_TD001.id_socsyst10
    from CBO_SOCSYST10_TD001
    where CBO_SOCSYST10_TD001.socsyst10_codigo = 'IDTRIB'
    into :id_socsyst10_idTrib;

    select
    sicingr81_cab_transporte.rela_socsyst10_por02,
    sicingr81_cab_transporte.rela_socsyst10_por05,
    sicingr81_cab_transporte.rela_socusua30_origen,
    sicingr81_cab_transporte.rela_socusua30_destino,
    sicingr81_cab_transporte.id_sicingr81,
    sicingr81_cab_transporte.sicingr81_dist_rec,
    sicingr81_cab_transporte.sicingr81_documento,
    sicingr81_cab_transporte.sicingr81_placas,
    sicingr81_cab_transporte.sicingr81_camion_ano,
    sicingr81_cab_transporte.sicingr81_poliza,
    sicingr81_cab_transporte.sicingr81_camion_tipo,
    sicingr81_cab_transporte.sicingr81_fdesalida,
    sicingr81_cab_transporte.sicingr81_fdeentrega,
    sicingr81_cab_transporte.sicingr81_permsct,
    sicingr81_cab_transporte.sicingr81_licencia,
    sicingr81_cab_transporte.sicingr81_peso
    from sicingr81_cab_transporte
    where sicingr81_cab_transporte.rela_sicingr70 = :rela_sicingr70
    into :rela_socsyst10_por02,
         :rela_socsyst10_por05,
         :rela_socusua30_origen,
         :rela_socusua30_destino,
         :id_sicingr81,
         :sicingr81_dist_rec,
         :sicingr81_documento,
         :placas,
         :ano,
         :poliza,
         :tipo_camion,
         :fecha_salida,
         :fecha_llegada,
         :permiso_sct,
         :licencia,
         :sicingr81_peso;

    select
    cbo_socsyst10_por05.socsyst10_descripcion
    from cbo_socsyst10_por05
    where cbo_socsyst10_por05.id_socsyst10 = :rela_socsyst10_por05
    into :aseguradora;

    select
    cbo_socsyst10_por02.socsyst10_descripcion
    from cbo_socsyst10_por02
    where cbo_socsyst10_por02.id_socsyst10 = :rela_socsyst10_por02
    into :operador;

    select
    CBO_SOCUSUA30.entidad,
    CBO_SOCUSUA30.rfc
    from CBO_SOCUSUA30(:rela_socusua30_origen)
    into :des_origen,
         :rfc_origen;

    select
    CBO_SOCUSUA30.entidad,
    CBO_SOCUSUA30.rfc
    from CBO_SOCUSUA30(:rela_socusua30_destino)
    into :des_destino,
         :rfc_destino;

    select first 1 socusua32_det_documentos.socusua32_documento
    from socusua32_det_documentos
    where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_origen
    and socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_idtrib
    into :idtrib_origen;

    select first 1 socusua32_det_documentos.socusua32_documento
    from socusua32_det_documentos
    where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_destino
    and socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_idtrib
    into :idtrib_destino;

    select first 1
    socusua36_det_domicilios.rela_socmain80,
    socusua36_det_domicilios.socusua36_codpostal,
    socusua36_det_domicilios.socusua36_calle || ' ' || socusua36_det_domicilios.socusua36_nro
    from socusua36_det_domicilios
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
    where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_origen
    and (socsyst10_det_entradas.socsyst10_codigo = 'CPORTE')
    order by socsyst10_det_entradas.socsyst10_codigo asc
    into :rela_socmain80_origen,
         :codpost_origen,
         :direccion_origen;

    select first 1
    socusua36_det_domicilios.rela_socmain80,
    socusua36_det_domicilios.socusua36_codpostal,
    socusua36_det_domicilios.socusua36_calle || ' ' || socusua36_det_domicilios.socusua36_nro
    from socusua36_det_domicilios
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
    where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_destino
    and (socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR' or socsyst10_det_entradas.socsyst10_codigo = 'CPORTE')
    order by socsyst10_det_entradas.socsyst10_codigo asc
    into :rela_socmain80_destino,
         :codpost_destino,
         :direccion_destino;

    if (CHAR_LENGTH (codpost_origen) < 5) then
        codpost_origen = '0' || codpost_origen;

    if (CHAR_LENGTH (codpost_destino) < 5) then
        codpost_destino = '0' || codpost_destino;

    if (rela_socmain80_origen is not null) then
        select
        CBO_SOCMAIN80_SAT.sat_estado,
        CBO_SOCMAIN80_SAT.sat_municipio,
        CBO_SOCMAIN80_SAT.sat_localidad
        from CBO_SOCMAIN80_SAT(:codpost_origen)
        where CBO_SOCMAIN80_SAT.id_socmain80 = :rela_socmain80_origen
        into :estado_origen,
             :municipio_origen,
             :localidad_origen;

    if (rela_socmain80_destino is not null) then
        select
        CBO_SOCMAIN80_SAT.sat_estado,
        CBO_SOCMAIN80_SAT.sat_municipio,
        CBO_SOCMAIN80_SAT.sat_localidad
        from CBO_SOCMAIN80_SAT(:codpost_destino)
        where CBO_SOCMAIN80_SAT.id_socmain80 = :rela_socmain80_destino
        into :estado_destino,
             :municipio_destino,
             :localidad_destino;

    select
    count(sicingr82_det_transporte.id_sicingr82),
    sum(sicingr82_det_transporte.sicingr82_peso)
    from sicingr82_det_transporte
    where sicingr82_det_transporte.rela_sicingr81  = :id_sicingr81
    into :cant_productos,
         :peso_bruto;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_COMPLE_CPORTE_DET (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR82 BIGINT,
    SICINGR82_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR82_CANTIDAD DOUBLE PRECISION,
    SICINGR82_VALOR DOUBLE PRECISION,
    SICINGR82_PESO DOUBLE PRECISION,
    SICINGR82_PELIGROSO INTEGER,
    UNIDAD_CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD_DESCRI VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COD_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICINGR81 bigint;
declare variable RELA_SOCSYST10_CUM01 bigint;
declare variable RELA_SOCSYST10_CPO01 bigint;
begin
    select
    sicingr81_cab_transporte.id_sicingr81
    from sicingr81_cab_transporte
    where sicingr81_cab_transporte.rela_sicingr70 = :rela_sicingr70
    into :id_sicingr81;

    for select
    sicingr82_det_transporte.rela_socsyst10_cum01,
    sicingr82_det_transporte.rela_socsyst10_cpo01,
    sicingr82_det_transporte.id_sicingr82,
    sicingr82_det_transporte.sicingr82_concepto,
    sicingr82_det_transporte.sicingr82_cantidad,
    sicingr82_det_transporte.sicingr82_valor,
    sicingr82_det_transporte.sicingr82_peso,
    sicingr82_det_transporte.sicingr82_peligroso
    from sicingr82_det_transporte
    where sicingr82_det_transporte.rela_sicingr81 = :id_sicingr81
    into :rela_socsyst10_cum01,
         :rela_socsyst10_cpo01,
         :id_sicingr82,
         :sicingr82_concepto,
         :sicingr82_cantidad,
         :sicingr82_valor,
         :sicingr82_peso,
         :sicingr82_peligroso
    do
    begin
        select
        cbo_socsyst10_cum01.socsyst10_codigo,
        cbo_socsyst10_cum01.socsyst10_descripcion
        from cbo_socsyst10_cum01
        where cbo_socsyst10_cum01.id_socsyst10 = :rela_socsyst10_cum01
        into :unidad_clave,
             :unidad_descri;


        unidad_descri = trim(SUBSTRING(unidad_descri FROM (
                                                            POSITION(')' in :unidad_descri)+1
                                                            )
                             )
                        );

        if (CHAR_LENGTH(unidad_descri) > 20) then
            unidad_descri = SUBSTRING(unidad_descri FROM 1 FOR 20);

        select
        cbo_socsyst10_cpo01.socsyst10_codigo
        from cbo_socsyst10_cpo01
        where cbo_socsyst10_cpo01.id_socsyst10 = :rela_socsyst10_cpo01
        into :cod_sat;

        suspend;
    end
end^


