CREATE OR ALTER PROCEDURE CFDI_COMPROBANTE (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR70 BIGINT,
    FECHA TIMESTAMP,
    TOTAL DOUBLE PRECISION,
    SUBTOTAL DOUBLE PRECISION,
    DESCUENTO DOUBLE PRECISION,
    SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FORMADEPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODODEPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPODECOMPROBANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USO_CFDI VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMBIO DOUBLE PRECISION,
    TOTAL_SINIMPUESTOS DOUBLE PRECISION,
    CON_CFDIS_RELACIONADOS INTEGER,
    CONDPAGOS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ES_ADDENDA INTEGER,
    ADDENDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ES_COMPLEMENTO INTEGER,
    COMPLEMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LUGAR_EXPEDICION INTEGER,
    REGIMEN_FISCAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REG_FISCAL_EMISOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable SOCSYST10_GRUPO varchar(50);
declare variable SOCSYST10_VALOR01 varchar(50);
declare variable RELA_SOCSYST10_SAT01 bigint;
declare variable RELA_SOCSYST10_SAT01_EMI bigint;
begin
    fecha = current_timestamp;
    con_cfdis_relacionados = 0;

    select
    socmain21_arb_organizacion.socmain21_codpostal,
    sicingr01_cab_clientes.rela_socusua30,
    sicingr70_cab_facturacion.id_sicingr70,
    sicingr70_cab_facturacion.sicingr70_serie,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_subtotal,
    sicingr70_cab_facturacion.sicingr70_descuento,
    sicingr70_cab_facturacion.sicingr70_total,
    sicingr70_cab_facturacion.sicingr70_neto,
    sicingr70_cab_facturacion.sicingr70_cambio,
    sicingr70_cab_facturacion.sicingr70_condpagos,
    moneda.socsyst10_codigo,
    fopago.socsyst10_codigo,
    tcompr.socsyst10_codigo,
    mdpago.socsyst10_codigo,
    uscfdi.socsyst10_codigo,
    addenda.socsyst10_grupo,
    addenda.socsyst10_valor01,
    sicingr01_cab_clientes.rela_socsyst10_sat01,
    sicingr70_cab_facturacion.rela_socsyst10_sat01
    from sicingr70_cab_facturacion
    inner join sicingr01_cab_clientes on ( sicingr01_cab_clientes.id_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01 )
    inner join socmain21_arb_organizacion on ( socmain21_arb_organizacion.id_socmain21 = sicingr70_cab_facturacion.rela_socmain21 )
    inner join socsyst10_det_entradas addenda on (addenda.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10 )
    inner join socsyst10_det_remoto moneda on ( moneda.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01 )
    inner join socsyst10_det_remoto fopago on ( fopago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_fdp01 )
    inner join socsyst10_det_remoto tcompr on ( tcompr.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01 )
    inner join socsyst10_det_remoto mdpago on ( mdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
    inner join socsyst10_det_remoto uscfdi on ( uscfdi.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ucf01 )
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :lugar_expedicion,
         :rela_socusua30,
         :id_sicingr70,
         :serie,
         :folio,
         :subtotal,
         :descuento,
         :total_sinimpuestos,
         :total,
         :cambio,
         :condpagos,
         :moneda,
         :formadepago,
         :tipodecomprobante,
         :metododepago,
         :uso_cfdi,
         :socsyst10_grupo,
         :socsyst10_valor01,
         :rela_socsyst10_sat01,
         :rela_socsyst10_sat01_emi;

    if (serie is not null and trim(serie) = '') then
        serie = null;

    if (folio is not null and trim(folio) = '') then
        folio = null;

    if (rela_socsyst10_sat01 is not null) then
        select cbo_socsyst10_sat01.socsyst10_codigo
        from cbo_socsyst10_sat01
        where cbo_socsyst10_sat01.id_socsyst10 = :rela_socsyst10_sat01
        into :REGIMEN_FISCAL;

    SELECT
    CBO_SOCUSUA30.entidad,
    CBO_SOCUSUA30.rfc
    FROM CBO_SOCUSUA30(:rela_socusua30)
    INTO :NOMBRE,
         :RFC;

    SELECT
    socusua36_det_domicilios.socusua36_codpostal
    FROM socusua36_det_domicilios
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
    inner JOIN socmain80_cab_codpostales ON ( socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80 )
    WHERE socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
    and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
    INTO :codpostal;

    if(CHAR_LENGTH (codpostal) = 4) then
        codpostal = '0' || codpostal;

    con_cfdis_relacionados = null;

    select first 1
    sicingr73_det_relacionados.id_sicingr73
    from sicingr73_det_relacionados
    where sicingr73_det_relacionados.rela_sicingr70 = :id_sicingr70
    into :con_cfdis_relacionados;

    if (con_cfdis_relacionados is null) then
        con_cfdis_relacionados = 0;
    else
        con_cfdis_relacionados = 1;

     es_addenda = 0;
     addenda = null;
     es_complemento = 0;
     complemento = null;

    if (socsyst10_grupo is not null and socsyst10_grupo = 'ADDENDA') then
    BEGIN
        es_addenda = 1;
        addenda = socsyst10_valor01;
    END
    else if (socsyst10_grupo is not null and socsyst10_grupo = 'COMPLEMENTO') then
    BEGIN
        es_complemento = 1;
        complemento = socsyst10_valor01;
    END

    if (rela_socsyst10_sat01_emi is not null) then
        SELECT cbo_socsyst10_sat01.socsyst10_codigo
        FROM cbo_socsyst10_sat01
        WHERE cbo_socsyst10_sat01.id_socsyst10 = :rela_socsyst10_sat01_emi
        INTO :reg_fiscal_emisor;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_COMPROBANTE_NOMINA (
    RELA_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI70 BIGINT,
    FECHA TIMESTAMP,
    TOTAL DOUBLE PRECISION,
    SUBTOTAL DOUBLE PRECISION,
    DESCUENTO DOUBLE PRECISION,
    SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FORMADEPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODODEPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPODECOMPROBANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USO_CFDI VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMBIO DOUBLE PRECISION,
    LUGAR_EXPEDICION INTEGER)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable TOTPERCEPCIONES double precision;
declare variable TOTOTROSPAGOS double precision;
declare variable TOTDEDUCCIONES double precision;
declare variable TOTSEPARAINDEM double precision;
begin
    fecha = current_timestamp;
    id_sicnomi70 = :rela_sicnomi70;

    select
    iif(CFDI_NOMINA.totpercepciones is null, 0.00, CFDI_NOMINA.totpercepciones),
    iif(CFDI_NOMINA.tototrospagos is null, 0.00, CFDI_NOMINA.tototrospagos),
    iif(CFDI_NOMINA.totdeducciones is null, 0.00, CFDI_NOMINA.totdeducciones),
    iif(CFDI_NOMINA.totseparaindem is null, 0.00, CFDI_NOMINA.totseparaindem)
    from CFDI_NOMINA(:id_sicnomi70)
    into :totpercepciones,
         :tototrospagos,
         :totdeducciones,
         :totseparaindem;

    subtotal = (totpercepciones + tototrospagos);
    descuento = totdeducciones;
    total = (subtotal - descuento);

    tipodecomprobante = 'N';
    formadepago = '99';
    metodoDePago = 'PUE';
    uso_cfdi = 'P01';
    cambio = 1.00;

    select
    socmain21_arb_organizacion.socmain21_codpostal,
    sicnomi01_cab_empleados.rela_socusua30,
    sicnomi70_cab_nomina.sicnomi70_serie,
    sicnomi70_cab_nomina.sicnomi70_docnro
    from sicnomi70_cab_nomina
    inner join sicnomi01_cab_empleados on  ( sicnomi01_cab_empleados.id_sicnomi01 = sicnomi70_cab_nomina.rela_sicnomi01 )
    inner join socmain21_arb_organizacion on ( socmain21_arb_organizacion.id_socmain21 = sicnomi70_cab_nomina.rela_socmain21 )
    where sicnomi70_cab_nomina.id_sicnomi70 = :id_sicnomi70
    into :lugar_expedicion,
         :rela_socusua30,
         :serie,
         :folio;

    if (serie is not null and trim(serie) = '') then
        serie = null;

    if (folio is not null and trim(folio) = '') then
        folio = null;

    select socusua32_det_documentos.socusua32_documento
    from socusua32_det_documentos
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001 )
    where socusua32_det_documentos.rela_socusua30 = :rela_socusua30
    AND socsyst10_det_entradas.socsyst10_codigo = 'RFC'
    INTO :RFC;

    SELECT
    CBO_SOCUSUA30_PFISICAS.busqueda
    FROM CBO_SOCUSUA30_PFISICAS
    WHERE CBO_SOCUSUA30_PFISICAS.id_socusua30 = :rela_socusua30
    INTO :NOMBRE;

    SELECT
    socmain80_cab_codpostales.socmain80_d_codigo
    FROM socusua36_det_domicilios
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
    inner JOIN socmain80_cab_codpostales ON ( socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80 )
    WHERE socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
    and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
    INTO :codpostal;

    moneda = 'MXN';

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_COMPROBANTE_PAGO (
    RELA_SICPAGO70 BIGINT)
RETURNS (
    ID_SICPAGO70 BIGINT,
    FECHA TIMESTAMP,
    TOTAL DOUBLE PRECISION,
    SUBTOTAL DOUBLE PRECISION,
    DESCUENTO DOUBLE PRECISION,
    SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FORMADEPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODODEPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPODECOMPROBANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMBIO DOUBLE PRECISION,
    MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CON_CFDIS_RELACIONADOS INTEGER,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USO_CFDI VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LUGAR_EXPEDICION INTEGER,
    CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGIMEN_FISCAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCUSUA30 bigint;
begin
    id_sicpago70 = :rela_sicpago70;

    select
    socmain21_arb_organizacion.socmain21_codpostal,
    sicingr51_cab_bancos.rela_sicingr01,
    sicpago70_cab_pago.sicpago70_serie,
    sicpago70_cab_pago.sicpago70_docnro
    from sicpago70_cab_pago
    inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51 )
    inner join socmain21_arb_organizacion on ( socmain21_arb_organizacion.id_socmain21 = sicpago70_cab_pago.rela_socmain21 )
    where sicpago70_cab_pago.id_sicpago70 = :rela_sicpago70
    into :lugar_expedicion,
         :rela_sicingr01,
         :serie,
         :folio;

    moneda = 'XXX';
    fecha = current_timestamp;
    formadepago = null;
    metododepago = null;
    con_cfdis_relacionados = 0;
    cambio = 0;
    tipodecomprobante = 'P';
    uso_cfdi = 'CP01';
    total = 0;
    subtotal = 0;
    descuento = 0;

    select
    cbo_sicingr01_id.rela_socusua30,
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc
    from cbo_sicingr01_id
    where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
    into :rela_socusua30,
         :nombre,
         :rfc;

    SELECT
    socmain80_cab_codpostales.socmain80_d_codigo
    FROM socusua36_det_domicilios
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
    inner JOIN socmain80_cab_codpostales ON ( socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80 )
    WHERE socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
    and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
    INTO :codpostal;

    if(CHAR_LENGTH (codpostal) = 4) then
        codpostal = '0' || codpostal;

    select socsyst10_det_entradas.socsyst10_codigo
    from sicingr01_cab_clientes
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr01_cab_clientes.rela_socsyst10_sat01 )
    where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
    into :regimen_fiscal;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_CONCEPTOS (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR71 BIGINT,
    CANTIDAD DOUBLE PRECISION,
    DESCRIPCION VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOIDENTIFICACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    VALORUNITARIO DOUBLE PRECISION,
    CLAVEPRODSERV VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVEUNIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DESCUENTO DOUBLE PRECISION,
    TRASLADOS DOUBLE PRECISION,
    RETENIDOS DOUBLE PRECISION,
    SICINGR71_PREDIAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INFO_ADUANA BIGINT)
AS
begin
    for select
    sicingr71_det_facturacion.id_sicingr71,
    sicingr71_det_facturacion.sicingr71_codigo,
    sicingr71_det_facturacion.sicingr71_concepto,
    sicingr71_det_facturacion.sicingr71_cantidad,
    sicingr71_det_facturacion.sicingr71_importe_unidad,
    sicingr71_det_facturacion.sicingr71_importe_subtotal,
    COD_MEDIDA.socsyst10_codigo,
    COD_MEDIDA.socsyst10_descripcion,
    COD_SERVPRD.socsyst10_codigo,
    sicingr71_det_facturacion.sicingr71_importe_descuento,
    sicingr71_det_facturacion.sicingr71_importe_retenido,
    sicingr71_det_facturacion.sicingr71_importe_traslado,
    sicingr71_det_facturacion.sicingr71_predial
    from sicingr71_det_facturacion
    inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = sicingr71_det_facturacion.rela_sicingr95 )
    inner join socsyst10_det_remoto COD_SERVPRD ON ( COD_SERVPRD.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
    inner join socsyst10_det_remoto COD_MEDIDA ON ( COD_MEDIDA.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    into :id_sicingr71,
         :noidentificacion,
         :descripcion,
         :cantidad,
         :valorunitario,
         :importe,
         :claveunidad,
         :unidad,
         :claveprodserv,
         :descuento,
         :retenidos,
         :traslados,
         :sicingr71_predial
   DO
   BEGIN
        info_aduana = 0;

        select first 1 sicingr78_det_infoaduanera.id_sicingr78
        from sicingr78_det_infoaduanera
        where sicingr78_det_infoaduanera.rela_sicingr71 = :id_sicingr71
        into :info_aduana;

        suspend;
   END
end^


CREATE OR ALTER PROCEDURE CFDI_CONCEPTOS_NOMINA (
    RELA_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI70 BIGINT,
    CANTIDAD DOUBLE PRECISION,
    DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOIDENTIFICACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    VALORUNITARIO DOUBLE PRECISION,
    CLAVEPRODSERV VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVEUNIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DESCUENTO DOUBLE PRECISION,
    INFO_ADUANA BIGINT)
AS
begin
  id_sicnomi70 = :rela_sicnomi70;
  cantidad = 1;
  unidad = 'ACT';
  claveunidad = 'ACT';
  descripcion = 'Pago de nómina';

  select cfdi_comprobante_nomina.subtotal
  from cfdi_comprobante_nomina(:id_sicnomi70)
  into :valorunitario;

  importe = :valorunitario;
  noidentificacion = null;
  claveprodserv = '84111505';

  select CFDI_COMPROBANTE_NOMINA.descuento
  from CFDI_COMPROBANTE_NOMINA(:rela_sicnomi70)
  into :descuento;

  info_aduana = 0;

  suspend;
end^


