CREATE OR ALTER PROCEDURE CFDI_CONCEPTOS_RETENIDOS (
    RELA_SICINGR71 BIGINT)
RETURNS (
    ID_SICINGR72 BIGINT,
    IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    BASE DOUBLE PRECISION,
    TASAOCUOTA NUMERIC(15,6),
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable N_TASAOCUOTA double precision;
begin
    FOR SELECT
    sicingr72_det_impuestos.id_sicingr72,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_importe,
    sicingr72_det_impuestos.sicingr72_base,
    sicingr72_det_impuestos.sicingr72_tasaocuota / 100,
    sicingr72_det_impuestos.sicingr72_factor
    FROM sicingr72_det_impuestos
    where sicingr72_det_impuestos.rela_sicingr71 = :rela_sicingr71
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipozona)) = 'FEDERAL'
    and  upper(trim(sicingr72_det_impuestos.sicingr72_tipo)) = 'RETENIDO'
    into :id_sicingr72,
         :impuesto,
         :importe,
         :base,
         :n_tasaocuota,
         :factor
    do
    begin
        importe = importe * -1;
        tasaocuota = cast(n_tasaocuota as numeric(15, 6));
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_CONCEPTOS_TRASLADOS (
    RELA_SICINGR71 BIGINT)
RETURNS (
    ID_SICINGR72 BIGINT,
    IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    BASE DOUBLE PRECISION,
    TASAOCUOTA NUMERIC(15,6),
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable N_TASAOCUOTA double precision;
begin
    FOR SELECT
    sicingr72_det_impuestos.id_sicingr72,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_importe,
    sicingr72_det_impuestos.sicingr72_base,
    sicingr72_det_impuestos.sicingr72_tasaocuota / 100,
    sicingr72_det_impuestos.sicingr72_factor
    FROM sicingr72_det_impuestos
    where sicingr72_det_impuestos.rela_sicingr71 = :rela_sicingr71
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipozona)) = 'FEDERAL'
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipo)) = 'TRASLADADO'
    into :id_sicingr72,
         :impuesto,
         :importe,
         :base,
         :n_tasaocuota,
         :factor
    do
    begin
      tasaocuota = cast(n_tasaocuota as numeric(15, 6));
      suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_EMPRESA (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    ID_SOCMAIN01 BIGINT,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_NOCERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_PAC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_SATPCSD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_PACUSER VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_PACPASS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_UUID_SMX_KEY VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_UUID_SMX_CER VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGISTROPATRONAL VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOEXTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOINTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_LOCALIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_MUNICIPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_PAIS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_ENTIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_PACAPIKEY VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    id_socmain01 = :rela_socmain01;

    SELECT
    SOCMAIN01_CAB_EMPRESAS.rela_socusua30,
    SOCMAIN01_CAB_EMPRESAS.id_socmain01,
    SOCMAIN01_CAB_EMPRESAS.socmain01_nomcomercial,
    SOCMAIN01_CAB_EMPRESAS.socmain01_nocertificado,
    SOCMAIN01_CAB_EMPRESAS.socmain01_pac,
    SOCMAIN01_CAB_EMPRESAS.socmain01_satpcsd,
    SOCMAIN01_CAB_EMPRESAS.socmain01_pacuser,
    SOCMAIN01_CAB_EMPRESAS.socmain01_pacpass,
    SOCMAIN01_CAB_EMPRESAS.socmain01_uuid_smx_key,
    SOCMAIN01_CAB_EMPRESAS.socmain01_uuid_smx_cer ,
    SOCMAIN01_CAB_EMPRESAS.socmain01_pacapikey
    FROM SOCMAIN01_CAB_EMPRESAS
    WHERE SOCMAIN01_CAB_EMPRESAS.id_socmain01 = :id_socmain01
    into :rela_socusua30,
         :id_socmain01,
         :socmain01_nomcomercial,
         :socmain01_nocertificado,
         :socmain01_pac,
         :socmain01_satpcsd,
         :socmain01_pacuser,
         :socmain01_pacpass,
         :socmain01_uuid_smx_key,
         :socmain01_uuid_smx_cer,
         :socmain01_pacapikey;

    Select
    CBO_SOCUSUA30.tipo,
    CBO_SOCUSUA30.entidad,
    CBO_SOCUSUA30.rfc,
    CBO_SOCUSUA30.curp
    FROM CBO_SOCUSUA30(:rela_socusua30)
    into :tipo_entidad,
         :razsocial,
         :rfc,
         :curp;

    SELECT
    socusua32_det_documentos.socusua32_documento
    FROM socusua32_det_documentos
    INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001 )
    WHERE socusua32_det_documentos.rela_socusua30 = :rela_socusua30
    AND socsyst10_det_entradas.socsyst10_codigo = 'REGISTROPATRONAL'
    INTO :REGISTROPATRONAL;

    SELECT
    socmain80_cab_codpostales.socmain80_d_codigo,
    socusua36_det_domicilios.socusua36_calle,
    socusua36_det_domicilios.socusua36_nro,
    socusua36_det_domicilios.socusua36_nrointerior,
    socusua36_det_domicilios.socusua36_colonia,
    socusua36_det_domicilios.socusua36_ciudad,
    socmain80_cab_codpostales.socmain80_d_mnpio,
    socmain80_cab_codpostales.socmain80_d_estado,
    socusua36_det_domicilios.socusua36_referencia
    FROM socusua36_det_domicilios
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
    inner JOIN socmain80_cab_codpostales ON ( socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80 )
    WHERE socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
    and socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
    INTO :domf_codpostal,
         :domf_calle,
         :domf_noexterior,
         :domf_nointerior,
         :domf_colonia,
         :domf_localidad,
         :domf_municipio,
         :domf_estado,
         :domf_referencia;

    domf_pais = 'México';

    if (domf_codpostal is not null and trim(domf_codpostal) = '') then
        domf_codpostal = null;

    if (domf_calle is not null and trim(domf_calle) = '') then
        domf_calle = null;

    if (domf_noexterior is not null and trim(domf_noexterior) = '') then
        domf_noexterior = null;

    if (domf_nointerior is not null and trim(domf_nointerior) = '') then
        domf_nointerior = null;

    if (domf_colonia is not null and trim(domf_colonia) = '') then
        domf_colonia = null;

    if (domf_localidad is not null and trim(domf_localidad) = '') then
        domf_localidad = null;

    if (domf_municipio is not null and trim(domf_municipio) = '') then
        domf_municipio = null;

    if (domf_estado is not null and trim(domf_estado) = '') then
        domf_estado = null;

    if (domf_referencia is not null and trim(domf_referencia) = '') then
        domf_referencia = null;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_EMPRESA_REGFISCAL (
    ID_SOCMAIN01X BIGINT)
RETURNS (
    RELA_SOCSYST10_SAT01 BIGINT,
