CREATE OR ALTER PROCEDURE CFDI_FIND_UUID (
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICXMLS41 BIGINT,
    RFC_EMISOR VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_RECEPTOR VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL DOUBLE PRECISION,
    SELLO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICXMLS40 bigint;
declare variable SELLO_LARGO varchar(8000);
begin
    select first 1
    sicxmls41_det_migracion.rela_sicxmls40,
    sicxmls41_det_migracion.id_sicxmls41,
    sicxmls41_det_migracion.sicxmls41_rfc,
    sicxmls41_det_migracion.sicxmls41_uuid_importe
    from sicxmls41_det_migracion
    where upper(sicxmls41_det_migracion.sicxmls41_uuid) = upper(:uuid)
    into :rela_sicxmls40,
         :id_sicxmls41,
         :rfc_receptor,
         :total;

    select first 1 cbo_socmain01_all.rfc
    from sicxmls40_cab_migracion
    inner join cbo_socmain01_all on (cbo_socmain01_all.id_socmain01 = sicxmls40_cab_migracion.rela_socmain01)
    where sicxmls40_cab_migracion.id_sicxmls40 = :rela_sicxmls40
    into :rfc_emisor;

    select sicingr74_dep_cfdis.sicingr74_sello
    from sicingr74_dep_cfdis
    where sicingr74_dep_cfdis.rela_sicxmls41 = :id_sicxmls41
    into :sello_largo;

    if (sello_largo is not null and CHAR_LENGTH(sello_largo) > 15) then
    begin
        sello = substring(sello_largo from CHAR_LENGTH (sello_largo) - 8 for CHAR_LENGTH (sello_largo));
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_IMPUESTOS (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR70 BIGINT,
    TOTTRASLADOS DOUBLE PRECISION,
    TOTRETENIDOS DOUBLE PRECISION,
    TASA DOUBLE PRECISION)
AS
begin
    select
    sicingr70_cab_facturacion.id_sicingr70,
    sicingr70_cab_facturacion.sicingr70_totimp_retenidos,
    sicingr70_cab_facturacion.sicingr70_totimp_traslados
    from sicingr70_cab_facturacion
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :id_sicingr70,
         :totretenidos,
         :tottraslados;

    select first 1 sicingr72_det_impuestos.sicingr72_tasaocuota
    from sicingr71_det_facturacion
    inner join sicingr72_det_impuestos on (sicingr72_det_impuestos.rela_sicingr71 = sicingr71_det_facturacion.id_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    and sicingr72_det_impuestos.sicingr72_impuesto = 'IVA'
    into :tasa;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_IMPUESTOS_LOCALES (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR70 BIGINT,
    TOTTRASLADOS DOUBLE PRECISION,
    TOTRETENIDOS DOUBLE PRECISION)
AS
begin
    id_sicingr70 = :rela_sicingr70;

    select sum(sicingr72_det_impuestos.sicingr72_importe * -1)
    from sicingr71_det_facturacion
    inner join sicingr72_det_impuestos on (sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipozona)) <> 'FEDERAL'
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipo)) = 'RETENIDO'
    into :totretenidos;

    select sum(sicingr72_det_impuestos.sicingr72_importe)
    from sicingr71_det_facturacion
    inner join sicingr72_det_impuestos on (sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipozona)) <> 'FEDERAL'
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipo)) = 'TRASLADADO'
    into :tottraslados;

    if (totretenidos is null) then
        totretenidos = 0;

    if (tottraslados is null) then
        tottraslados = 0;

    if ((totretenidos + tottraslados) <> 0) then
        suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_NOMINA (
    RELA_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI70 BIGINT,
    TIPONOMINA VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHAPAGO DATE,
    FECHAINIPAGO DATE,
    FECHAFINPAGO DATE,
    NUMDIASPAGADOS DOUBLE PRECISION,
    TOTDEDUCCIONES DOUBLE PRECISION,
    TOTPERCEPCIONES DOUBLE PRECISION,
    TOTOTROSPAGOS DOUBLE PRECISION,
    TOTPERCEPEXENTO DOUBLE PRECISION,
    TOTPERCEPGRAVADO DOUBLE PRECISION,
    TOTSUELDO DOUBLE PRECISION,
    TOTIMPRETENIDO DOUBLE PRECISION,
    TOTOTRASDEDUCCIONES DOUBLE PRECISION,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NUMSEGURO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHAINILABORAL DATE,
    ANTIGUEDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPOCONTRATO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SINDICALIZADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPOJORNADA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPOREGIMEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NUMEMPLEADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DEPARTAMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RIESGOPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PERIODOPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTABANCO BIGINT,
    CLAVEENTFED VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CON_SUBCONTRA VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALARIODIARIOINTEGRADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALARIOBASECOTAPOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTSEPARAINDEM DOUBLE PRECISION,
    ANOS_SERVICIOS INTEGER)
AS
declare variable RELA_SICNOMI01 bigint;
declare variable CODIGO varchar(50);
declare variable VALOR varchar(400);
declare variable ID_SICNOMI76 bigint;
declare variable ANOS_INI date;
declare variable ANOS_FIN date;
begin
    id_sicnomi70 = :rela_sicnomi70;

    SELECT
    sicnomi70_cab_nomina.rela_sicnomi01,
    sicnomi70_cab_nomina.sicnomi70_tiponomina,
    sicnomi70_cab_nomina.sicnomi70_fecha,
    sicnomi70_cab_nomina.sicnomi70_fini,
    sicnomi70_cab_nomina.sicnomi70_ffin,
    sicnomi70_cab_nomina.sicnomi70_dias
    FROM sicnomi70_cab_nomina
    WHERE sicnomi70_cab_nomina.id_sicnomi70 = :id_sicnomi70
    into :rela_sicnomi01,
         :tiponomina,
         :fechapago,
         :fechainipago,
         :fechafinpago,
         :numdiaspagados;

    select first 1 sicnomi76_det_subcontratado.id_sicnomi76
    from sicnomi76_det_subcontratado
    where sicnomi76_det_subcontratado.rela_sicnomi70 = :id_sicnomi70
    into :id_sicnomi76;

    if (id_sicnomi76 is null) then
        con_subcontra = 'N';
    ELSE
        con_subcontra = 'S';

    /* ================================================================================================================ */
    /* ================================================================================================================ */

    SELECT SUM(CFDI_NOMINA_DEDUCCIONES.importe)
    FROM CFDI_NOMINA_DEDUCCIONES(:id_sicnomi70)
    into :totdeducciones;

    SELECT SUM(CFDI_NOMINA_DEDUCCIONES.importe)
    FROM CFDI_NOMINA_DEDUCCIONES(:id_sicnomi70)
    WHERE CFDI_NOMINA_DEDUCCIONES.tipo <> '002'
    into :tototrasdeducciones;

    SELECT SUM(CFDI_NOMINA_DEDUCCIONES.importe)
    FROM CFDI_NOMINA_DEDUCCIONES(:id_sicnomi70)
    WHERE CFDI_NOMINA_DEDUCCIONES.tipo = '002'
    into :totimpretenido;

    /* ================================================================================================================ */
    /* ================================================================================================================ */

    SELECT SUM(CFDI_NOMINA_PERCEPCIONES.importe_exento) + SUM(CFDI_NOMINA_PERCEPCIONES.importe_gravado)
    FROM CFDI_NOMINA_PERCEPCIONES(:id_sicnomi70)
    into :totpercepciones;

    SELECT SUM(CFDI_NOMINA_PERCEPCIONES.importe_gravado)
    FROM CFDI_NOMINA_PERCEPCIONES(:id_sicnomi70)
    into :totpercepgravado;

    SELECT SUM(CFDI_NOMINA_PERCEPCIONES.importe_exento)
    FROM CFDI_NOMINA_PERCEPCIONES(:id_sicnomi70)
    into :totpercepexento;

    SELECT SUM(cfdi_nomina_otrospagos.importe)
    FROM cfdi_nomina_otrospagos(:id_sicnomi70)
    into :tototrospagos;

    totsueldo = :totpercepciones;

    /* ================================================================================================================ */
    /* ================================================================================================================ */

    SELECT SUM(CFDI_NOMINA_PERCEPCIONES.importe_gravado)
    FROM CFDI_NOMINA_PERCEPCIONES(:id_sicnomi70)
    where (CFDI_NOMINA_PERCEPCIONES.tipo = '022' or
           CFDI_NOMINA_PERCEPCIONES.tipo = '023' or
           CFDI_NOMINA_PERCEPCIONES.tipo = '025')
    into :totseparaindem;

    if (totseparaindem is not null) then
    begin
       totsueldo = totsueldo - totseparaindem;
    end

    /* ================================================================================================================ */
    /* ================================================================================================================ */

    select cbo_sicnomi01_curp.curp
    from cbo_sicnomi01_curp
    where cbo_sicnomi01_curp.id_sicnomi01 = :rela_sicnomi01
    into :curp;

    select
    socsyst10_det_entradas.socsyst10_grupo,
    CAST(sicnomi02_det_bancos.sicnomi02_cuenta AS BIGINT)
    from sicnomi02_det_bancos
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicnomi02_det_bancos.rela_socsyst10_ban01 )
    where sicnomi02_det_bancos.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA'
    INTO :banco,
         :cuentabanco;

    for select
    socsyst10_det_entradas.socsyst10_codigo,
    SICNOMI05_DET_NOMINA.sicnomi05_valor
    from SICNOMI05_DET_NOMINA
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = SICNOMI05_DET_NOMINA.rela_socsyst10_cno01 )
    where  SICNOMI05_DET_NOMINA.rela_sicnomi01 = :rela_sicnomi01
    into :codigo,
         :valor
    do
    begin
        if (valor is not null and trim(valor) = '') then
            valor = null;

        if (codigo = 'NUMEMPLEADO') then
            numempleado = :valor;

        if (codigo = 'NUMSEGURIDADSOCIAL') then
            numseguro = :valor;

        if (codigo = 'FECHAINICIORELLABORAL') then
        begin
            fechainilaboral = :valor;
            anos_ini = cast(:fechainilaboral as date);
            anos_fin = :fechafinpago;
            anos_servicios = DATEDIFF(year, anos_ini, anos_fin);
        end

        if (codigo = 'ANTIGUEDAD') then
            antiguedad = :valor;

        if (codigo = 'TIPOCONTRATO') then
            tipocontrato = :valor;

        if (codigo = 'SINDICALIZADO') then
            sindicalizado = :valor;

        if (codigo = 'TIPOJORNADA') then
            tipojornada = :valor;

        if (codigo = 'TIPOREGIMEN') then
            tiporegimen = :valor;

        if (codigo = 'DEPARTAMENTO') then
            departamento = :valor;

        if (codigo = 'PUESTO') then
            puesto = :valor;

        if (codigo = 'RIESGOPUESTO') then
            riesgopuesto = :valor;

        if (codigo = 'PERIODICIDADPAGO') then
            periodopago = :valor;

        if (codigo = 'CLAVEENTFED') then
            claveentfed = :valor;

        if (codigo = 'SALARIODIARIOINTEGRADO') then
            salariodiariointegrado = :valor;

        if (codigo = 'SALARIOBASECOTAPOR') then
            salariobasecotapor = :valor;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_NOMINA_CANCELA (
    RELA_SICNOMI70 BIGINT,
    ES_CANCELABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_CANCELABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICNOMI70 BIGINT)
AS
declare variable SERIE varchar(50);
declare variable DOCNRO varchar(50);
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SICXMLS41 bigint;
declare variable RELA_SICCONT10 bigint;
declare variable ID_SICNOMI50 bigint;
declare variable FOLIO_CANCELADO varchar(50);
declare variable FOLIOS_CANCELADOS varchar(1000);
begin
    select
    sicnomi70_cab_nomina.rela_socmain01,
    sicnomi70_cab_nomina.rela_socmain21,
    sicnomi70_cab_nomina.sicnomi70_serie,
    sicnomi70_cab_nomina.sicnomi70_docnro
    from sicnomi70_cab_nomina where sicnomi70_cab_nomina.id_sicnomi70 = :rela_sicnomi70
    into :rela_socmain01,
         :rela_socmain21,
         :serie,
         :docnro;

    SELECT
    sicxmls41_det_migracion.rela_siccont10,
    sicnomi74_dep_cfdis.rela_sicxmls41
    FROM sicnomi74_dep_cfdis
    inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicnomi74_dep_cfdis.rela_sicxmls41 )
    WHERE sicnomi74_dep_cfdis.rela_sicnomi70 = :rela_sicnomi70
    into :rela_siccont10,
         :rela_sicxmls41;

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    insert into sicnomi77_det_cfdiscancelados( sicnomi77_det_cfdiscancelados.rela_sicnomi70,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_uuid,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_uuid_fecha,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_fcancelado,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_folio,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_serie,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_uuid_importe,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_uuid_smx,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_cancelable,
                                               sicnomi77_det_cfdiscancelados.sicnomi77_status)
    select
    sicnomi74_dep_cfdis.rela_sicnomi70,
    sicnomi74_dep_cfdis.sicnomi74_uuid,
    sicnomi74_dep_cfdis.sicnomi74_uuid_fecha,
    current_timestamp,
    :docnro,
    :serie,
    sicnomi74_dep_cfdis.sicnomi74_uuid_importe,
    sicnomi74_dep_cfdis.sicnomi74_uuid_smx,
    :es_cancelable,
    :status_cancelable
    from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = :rela_sicnomi70;

    delete from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = :rela_sicnomi70;
    ID_SICNOMI70 = :rela_sicnomi70;

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    if (rela_siccont10 is null) then
        delete from sicxmls41_det_migracion where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41;
    else
    BEGIN
        select sicnomi50_det_ctacte.id_sicnomi50
        from sicnomi50_det_ctacte
        where sicnomi50_det_ctacte.rela_siccont10 = :rela_siccont10
        into :id_sicnomi50;

        delete from sicnomi61_det_xperiodo where sicnomi61_det_xperiodo.rela_sicnomi50 = :id_sicnomi50;
        delete from siccont10_cab_polizas where siccont10_cab_polizas.id_siccont10 = :rela_siccont10;
    END
    /* ======================================================================================================== */
    /* ======================================================================================================== */

    folios_cancelados = '';

    for select sicnomi77_det_cfdiscancelados.sicnomi77_folio
    from sicnomi77_det_cfdiscancelados
    where sicnomi77_det_cfdiscancelados.rela_sicnomi70 = :rela_sicnomi70
    into :folio_cancelado
    do
    begin
        folios_cancelados = folios_cancelados || ' ' || folio_cancelado;
    end

    folios_cancelados = 'Timbrado Cancelado. Folios Cancelados (' || trim(:folios_cancelados) || ')';

    Select smx$soc_contadores.nrodoc, smx$soc_contadores.serie
    from smx$soc_contadores(:rela_socmain01, :rela_socmain21, :rela_sicnomi70, 'SICNOMI70')
    into :docnro, :serie;

    update sicnomi70_cab_nomina set sicnomi70_cab_nomina.sicnomi70_serie = :serie,
                                    sicnomi70_cab_nomina.sicnomi70_docnro = :docnro,
                                    sicnomi70_cab_nomina.sicnomi70_status = :folios_cancelados
    where sicnomi70_cab_nomina.id_sicnomi70 = :rela_sicnomi70;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_NOMINA_DEDUCCIONES (
    ID_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI71 BIGINT,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION)
AS
begin
    for select
    sicnomi71_det_nomina.id_sicnomi71,
    siccont02_arb_planctas.siccont02_codigo_ext,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicxmls05_det_nomina.sicxmls05_concepto,
    sicnomi71_det_nomina.sicnomi71_importe
    from sicnomi71_det_nomina
    INNER JOIN sicxmls05_det_nomina ON ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05 )
    INNER JOIN siccont02_arb_planctas ON ( siccont02_arb_planctas.id_siccont02 = sicxmls05_det_nomina.rela_siccont02 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' or sicxmls05_det_nomina.sicxmls05_tipo = 'I')
    into :id_sicnomi71,
         :clave,
         :tipo,
         :concepto,
         :importe
    do
    begin
        concepto = replace (concepto,  '.', '');
        concepto = replace (concepto,  '(', '');
        concepto = replace (concepto,  ')', '');
        suspend;
    end
end^


