CREATE OR ALTER PROCEDURE CFDI_NOMINA_PERCEPCIONES (
    ID_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI71 BIGINT,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_EXENTO DOUBLE PRECISION,
    IMPORTE_GRAVADO DOUBLE PRECISION,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CON_HORASEXTRAS VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable IMPORTE double precision;
declare variable GRAVADO integer;
declare variable ID_SICNOMI75 bigint;
begin
    for select
    sicnomi71_det_nomina.id_sicnomi71,
    siccont02_arb_planctas.siccont02_codigo_ext,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicxmls05_det_nomina.sicxmls05_concepto,
    sicnomi71_det_nomina.sicnomi71_importe,
    sicxmls05_det_nomina.sicxmls05_gravado
    from sicnomi71_det_nomina
    INNER JOIN sicxmls05_det_nomina ON ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05 )
    INNER JOIN siccont02_arb_planctas ON ( siccont02_arb_planctas.id_siccont02 = sicxmls05_det_nomina.rela_siccont02 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'P' OR sicxmls05_det_nomina.sicxmls05_tipo = 'H')
    into :id_sicnomi71,
         :clave,
         :tipo,
         :concepto,
         :importe,
         :gravado
    do
    begin
        id_sicnomi75 = NULL;
        importe_gravado = 0;
        importe_exento = 0;

        if (gravado = 1) then
            importe_gravado = :importe;
        else
            importe_exento = :importe;

        select first 1 sicnomi75_det_horasextra.id_sicnomi75
        from sicnomi75_det_horasextra
        where sicnomi75_det_horasextra.rela_sicnomi71 = :id_sicnomi71
        into :id_sicnomi75;

        if (id_sicnomi75 is null) then
            con_horasextras = 'N';
        else
            con_horasextras = 'S';

        concepto = replace (concepto,  '.', '');
        concepto = replace (concepto,  '(', '');
        concepto = replace (concepto,  ')', '');
        suspend;
    end
end^


