CREATE OR ALTER PROCEDURE CFDI_PAGO (
    RELA_SICPAGO70 BIGINT)
RETURNS (
    ID_SICINGR51 BIGINT,
    FECHA TIMESTAMP,
    MONTO DOUBLE PRECISION,
    MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    CUENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FORMAPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ISCTAORD INTEGER,
    RELA_SICPAGO50 BIGINT)
AS
declare variable FECHA_TMP date;
begin
    select
    sicingr51_cab_bancos.id_sicingr51,
    sicingr51_cab_bancos.sicingr51_fecha,
    sicingr51_cab_bancos.sicingr51_importe,
    MONEDA.socsyst10_codigo,
    BANCO.socsyst10_valor01,
    PAGO.socsyst10_grupo,
    sicingr51_cab_bancos.sicingr51_referencia,
    sicingr51_cab_bancos.sicingr51_cotiza,
    sicingr51_cab_bancos.sicingr51_cuenta,
    sicingr51_cab_bancos.sicingr51_ctaord
    from sicpago70_cab_pago
    inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51 )
    inner join socsyst10_det_entradas BANCO on ( BANCO.id_socsyst10 = sicingr51_cab_bancos.rela_socsyst10_ban01 )
    inner join socsyst10_det_remoto MONEDA on ( MONEDA.id_socsyst10 = sicingr51_cab_bancos.rela_socsyst10_ctm01 )
    inner join socsyst10_det_entradas PAGO on ( PAGO.id_socsyst10 = sicingr51_cab_bancos.rela_socsyst10_mdp01 )
    where sicpago70_cab_pago.id_sicpago70 = :rela_sicpago70
    into :id_sicingr51,
         :fecha_tmp,
         :monto,
         :moneda,
         :rfc,
         :formapago,
         :referencia,
         :cotiza,
         :cuenta,
         :isctaord;

    rela_sicpago50 = null;

    select sicpago50_cab_factoraje.id_sicpago50
    from sicpago50_cab_factoraje
    where sicpago50_cab_factoraje.rela_sicingr51 = :id_sicingr51
    into :rela_sicpago50;

    fecha = cast( fecha_tmp || ' 12:00:00' as timestamp );

    if (char_length(referencia) > 100) then
        referencia = substring(referencia from 1 for 100);

    if (moneda <> 'MXN') then
    BEGIN
        SELECT sum(cfdi_pago_detalles.imppagado)
        FROM cfdi_pago_detalles(:id_sicingr51)
        INTO :monto;
    END
    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_CANCELA (
    RELA_SICPAGO70 BIGINT,
    ES_CANCELABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_CANCELABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICPAGO70 BIGINT)
AS
declare variable SERIE varchar(50);
declare variable DOCNRO varchar(50);
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable FOLIO_CANCELADO varchar(50);
declare variable FOLIOS_CANCELADOS varchar(1000);
begin
    select
    sicpago70_cab_pago.rela_socmain01,
    sicpago70_cab_pago.rela_socmain21,
    sicpago70_cab_pago.sicpago70_serie,
    sicpago70_cab_pago.sicpago70_docnro
    from sicpago70_cab_pago where sicpago70_cab_pago.id_sicpago70 = :rela_sicpago70
    into :rela_socmain01,
         :rela_socmain21,
         :serie,
         :docnro;

    /* ======================================================================================================== */
    /* ======================================================================================================== */

    insert into sicpago77_det_cfdiscancelados( sicpago77_det_cfdiscancelados.rela_sicpago70,
                                               sicpago77_det_cfdiscancelados.sicpago77_uuid,
                                               sicpago77_det_cfdiscancelados.sicpago77_uuid_fecha,
                                               sicpago77_det_cfdiscancelados.sicpago77_fcancelado,
                                               sicpago77_det_cfdiscancelados.sicpago77_folio,
                                               sicpago77_det_cfdiscancelados.sicpago77_serie,
                                               sicpago77_det_cfdiscancelados.sicpago77_uuid_importe,
                                               sicpago77_det_cfdiscancelados.sicpago77_uuid_smx,
                                               sicpago77_det_cfdiscancelados.sicpago77_cancelable,
                                               sicpago77_det_cfdiscancelados.sicpago77_status)
    select
    sicpago74_dep_cfdis.rela_sicpago70,
    sicpago74_dep_cfdis.sicpago74_uuid,
    sicpago74_dep_cfdis.sicpago74_uuid_fecha,
    current_timestamp,
    :docnro,
    iif(:serie is null, '', :serie),
    sicpago74_dep_cfdis.sicpago74_uuid_importe,
    sicpago74_dep_cfdis.sicpago74_uuid_smx,
    :es_cancelable,
    :status_cancelable
    from sicpago74_dep_cfdis
    where sicpago74_dep_cfdis.rela_sicpago70 = :rela_sicpago70;

    delete from sicpago74_dep_cfdis
    where sicpago74_dep_cfdis.rela_sicpago70 = :rela_sicpago70;

    id_sicpago70 = :rela_sicpago70;

    /* ======================================================================================================== */
    /* ======================================================================================================== */
    folios_cancelados = '';

    for select sicpago77_det_cfdiscancelados.sicpago77_folio
    from sicpago77_det_cfdiscancelados
    where sicpago77_det_cfdiscancelados.rela_sicpago70 = :rela_sicpago70
    into :folio_cancelado
    do
    begin
        folios_cancelados = folios_cancelados || ' ' || folio_cancelado;
    end

    folios_cancelados = 'Timbrado Cancelado. Folios Cancelados (' || trim(:folios_cancelados) || ')';

    Select smx$soc_contadores.nrodoc, smx$soc_contadores.serie
    from smx$soc_contadores(:rela_socmain01, :rela_socmain21, :rela_sicpago70, 'sicpago70')
    into :docnro, :serie;

    update sicpago70_cab_pago set sicpago70_cab_pago.sicpago70_serie = :serie,
                                  sicpago70_cab_pago.sicpago70_docnro = :docnro,
                                  sicpago70_cab_pago.sicpago70_status = :folios_cancelados
    where sicpago70_cab_pago.id_sicpago70 = :rela_sicpago70;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_DETALLES (
    RELA_SICINGR51 BIGINT)
RETURNS (
    RELA_SICXMLS41 BIGINT,
    RELA_SICCONT10 BIGINT,
    ID_SICINGR52 BIGINT,
    NUMPARCIALIDAD INTEGER,
    IMPSALDOINSOLUTO DOUBLE PRECISION,
    IMPPAGADO DOUBLE PRECISION,
    IMPSALDOANT DOUBLE PRECISION,
    TIPOCAMBIODR DOUBLE PRECISION,
    METODODEPAGODR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDADR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IDDOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTTRASLADOS DOUBLE PRECISION,
    TOTRETENIDOS DOUBLE PRECISION,
    IMPORTE_XML DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPUESTO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPUESTO_TASA DOUBLE PRECISION,
    IMPUESTO_FACTOR VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPUESTO_BASE DOUBLE PRECISION,
    PORCENTAJE DOUBLE PRECISION)
AS
declare variable RELA_SICINGR50 bigint;
declare variable SUMAPAGOS double precision;
declare variable RELA_SICINGR70 bigint;
declare variable SICXMLS41_ORIGEN varchar(1);
begin
    for select
    SICINGR52_DET_BANCOS.id_sicingr52,
    SICINGR52_DET_BANCOS.rela_sicingr50,
    SICINGR52_DET_BANCOS.sicingr52_importe,
    sicingr50_det_ctacte.sicingr50_importe,
    sicingr50_det_ctacte.rela_siccont10
    from SICINGR52_DET_BANCOS
    inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = SICINGR52_DET_BANCOS.rela_sicingr50 )
    WHERE SICINGR52_DET_BANCOS.rela_sicingr51 = :rela_sicingr51
    INTO :id_sicingr52,
         :rela_sicingr50,
         :imppagado,
         :importe_xml,
         :rela_siccont10
    do
    begin
        numparcialidad = 0;
        impsaldoant = importe_xml;
        impsaldoinsoluto = 0;

        select
        sicxmls41_det_migracion.id_sicxmls41,
        sicxmls41_det_migracion.sicxmls41_uuid,
        sicxmls41_det_migracion.sicxmls41_moneda,
        sicxmls41_det_migracion.sicxmls41_cambio,
        sicxmls41_det_migracion.sicxmls41_origen,
        sicxmls41_det_migracion.sicxmls41_folio
        from sicxmls41_det_migracion
        where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
        into :rela_sicxmls41,
             :iddocumento,
             :monedadr,
             :tipocambiodr,
             :sicxmls41_origen,
             :folio;

        if (monedadr = 'MXN') then
            tipocambiodr = 0;

        if (sicxmls41_origen = 'F') then
        BEGIN
            select
            sicingr74_dep_cfdis.RELA_SICINGR70,
            socsyst10_det_remoto.socsyst10_codigo
            from sicingr74_dep_cfdis
            inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
            inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
            where sicingr74_dep_cfdis.rela_sicxmls41 = :rela_sicxmls41
            into :rela_sicingr70,
                 :metododepagodr;
        END
        ELSE
        BEGIN
            select sicxmls41_det_migracion.sicxmls41_metododepago
            from sicxmls41_det_migracion
            where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
            into :metododepagodr;
        END

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (imppagado <> importe_xml) then
        begin
            select
            count(SICINGR52_DET_BANCOS.id_sicingr52),
            sum(SICINGR52_DET_BANCOS.sicingr52_importe)
            from SICINGR52_DET_BANCOS
            where SICINGR52_DET_BANCOS.rela_sicingr50 = :rela_sicingr50
            and SICINGR52_DET_BANCOS.id_sicingr52 < :id_sicingr52
            into :numparcialidad,
                 :sumapagos;

            numparcialidad = numparcialidad + 1;

            if (sumapagos is null) then
                sumapagos = 0;

            impsaldoinsoluto = importe_xml - (imppagado + sumapagos);

            if (sumapagos = 0) then
                impsaldoant = importe_xml;
            else
                impsaldoant = importe_xml - sumapagos;
        end

        porcentaje = imppagado / importe_xml * 100;

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (sicxmls41_origen = 'F') then
        BEGIN
            select
            CFDI_IMPUESTOS.TOTTRASLADOS,
            CFDI_IMPUESTOS.TOTRETENIDOS,
            CFDI_IMPUESTOS.tasa
            from CFDI_IMPUESTOS(:rela_sicingr70)
            into :TOTTRASLADOS,
                 :TOTRETENIDOS,
                 :IMPUESTO_TASA;
        END
        ELSE
        BEGIN
            select
            max(sicxmls43_det_impuestos.sicxmls43_tasa),
            sum(sicxmls43_det_impuestos.sicxmls43_importe)
            from sicxmls43_det_impuestos
            where sicxmls43_det_impuestos.rela_sicxmls41 = :rela_sicxmls41
            and sicxmls43_det_impuestos.sicxmls43_retenido = 0
            into :IMPUESTO_TASA,
                 :TOTTRASLADOS;

            select
            max(sicxmls43_det_impuestos.sicxmls43_tasa),
            sum(sicxmls43_det_impuestos.sicxmls43_importe)
            from sicxmls43_det_impuestos
            where sicxmls43_det_impuestos.rela_sicxmls41 = :rela_sicxmls41
            and sicxmls43_det_impuestos.sicxmls43_retenido = 1
            into :IMPUESTO_TASA,
                 :TOTRETENIDOS;
        END

        TOTTRASLADOS = TOTTRASLADOS * porcentaje / 100;
        TOTRETENIDOS = TOTRETENIDOS * porcentaje / 100;

        if (metododepagodr = 'PPD' and numparcialidad = 0) then
            numparcialidad = 1;

        IMPUESTO = '002';
        IMPUESTO_FACTOR = 'Tasa';

        IMPUESTO_TASA = IMPUESTO_TASA / 100;
        TOTTRASLADOS = IMPPAGADO - (IMPPAGADO / (IMPUESTO_TASA + 1));
        IMPUESTO_BASE = IMPPAGADO - TOTTRASLADOS;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_DETALLES_WEB (
    RELA_SICINGR51 BIGINT)
RETURNS (
    RELA_SICINGR70 BIGINT,
    ID_SICINGR52 BIGINT,
    NUMPARCIALIDAD INTEGER,
    IMPSALDOINSOLUTO DOUBLE PRECISION,
    IMPPAGADO DOUBLE PRECISION,
    IMPSALDOANT DOUBLE PRECISION,
    TIPOCAMBIODR DOUBLE PRECISION,
    METODODEPAGODR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDADR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IDDOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTTRASLADOS DOUBLE PRECISION,
    TOTRETENIDOS DOUBLE PRECISION,
    IMPORTE_XML DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PORCENTAJE DOUBLE PRECISION,
    BASE_PAGADO DOUBLE PRECISION)
AS
declare variable SUMAPAGOS double precision;
declare variable SICXMLS41_ORIGEN varchar(1);
begin
    for select
    sicingr55_det_facturas.rela_sicingr70,
    sicingr55_det_facturas.id_sicingr55,
    sicingr55_det_facturas.sicingr55_importe,
    sicingr70_cab_facturacion.sicingr70_neto,
    sicingr74_dep_cfdis.sicingr74_uuid,
    cbo_socsyst10_ctm01.socsyst10_codigo,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_cambio,
    cbo_socsyst10_tcp01.socsyst10_codigo,
    cbo_socsyst10_met01.socsyst10_codigo
    from sicingr55_det_facturas
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr55_det_facturas.rela_sicingr70)
    inner join sicingr74_dep_cfdis on (sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70)
    inner join cbo_socsyst10_ctm01 on (cbo_socsyst10_ctm01.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01)
    inner join cbo_socsyst10_tcp01 on (cbo_socsyst10_tcp01.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01)
    inner join cbo_socsyst10_met01 on (cbo_socsyst10_met01.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01)
    WHERE sicingr55_det_facturas.rela_sicingr51 = :rela_sicingr51
    INTO :rela_sicingr70,
         :id_sicingr52,
         :imppagado,
         :importe_xml,
         :iddocumento,
         :monedadr,
         :folio,
         :tipocambiodr,
         :sicxmls41_origen,
         :metododepagodr
    do
    begin
        numparcialidad = 0;
        impsaldoant = importe_xml;
        impsaldoinsoluto = 0;

        if (monedadr = 'MXN') then
            tipocambiodr = 0;

        if (sicxmls41_origen = 'I') then
            sicxmls41_origen = 'F';

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (imppagado <> importe_xml) then
        begin
            select
            count(sicingr55_det_facturas.id_sicingr55),
            sum(sicingr55_det_facturas.sicingr55_importe)
            from sicingr55_det_facturas
            where sicingr55_det_facturas.rela_sicingr70 = :rela_sicingr70
            and sicingr55_det_facturas.rela_sicingr51 != :rela_sicingr51
            into :numparcialidad,
                 :sumapagos;

            numparcialidad = numparcialidad + 1;

            if (sumapagos is null) then
                sumapagos = 0;

            impsaldoinsoluto = importe_xml - (imppagado + sumapagos);

            if (sumapagos = 0) then
                impsaldoant = importe_xml;
            else
                impsaldoant = importe_xml - sumapagos;
        end

        porcentaje = imppagado / importe_xml;

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        select sum(sicingr71_det_facturacion.sicingr71_importe_total)
        from sicingr71_det_facturacion
        where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
        into :base_pagado;

        base_pagado = base_pagado * porcentaje;

        select
        sum(sicingr75_det_impuestos_web.sicingr75_total)
        from sicingr75_det_impuestos_web
        inner join sicingr71_det_facturacion on (sicingr71_det_facturacion.id_sicingr71 = sicingr75_det_impuestos_web.rela_sicingr71)
        inner join cbo_socsyst10_sat10 on (cbo_socsyst10_sat10.id_socsyst10 = sicingr75_det_impuestos_web.rela_socsyst10_sat10)
        where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
        and cbo_socsyst10_sat10.socsyst10_valor01 = 'T'
        INTO :TOTTRASLADOS;

        TOTTRASLADOS = IIF(TOTTRASLADOS IS NULL, 0.0, TOTTRASLADOS);

        select sum(sicingr75_det_impuestos_web.sicingr75_total)*-1
        from sicingr75_det_impuestos_web
        inner join sicingr71_det_facturacion on (sicingr71_det_facturacion.id_sicingr71 = sicingr75_det_impuestos_web.rela_sicingr71)
        inner join cbo_socsyst10_sat10 on (cbo_socsyst10_sat10.id_socsyst10 = sicingr75_det_impuestos_web.rela_socsyst10_sat10)
        where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
        and cbo_socsyst10_sat10.socsyst10_valor01 = 'R'
        INTO :TOTRETENIDOS;

        TOTRETENIDOS = IIF(TOTRETENIDOS IS NULL, 0.0, TOTRETENIDOS);

        if (numparcialidad = 0) then
            numparcialidad = 1;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_FACTORAJE (
    ID_SICPAGO50X BIGINT)
RETURNS (
    ID_SICPAGO50 BIGINT,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_FORMAPAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID_FECHA DATE,
    SICXMLS41_ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICXMLS41_COMI bigint;
begin
    select
    sicpago50_cab_factoraje.rela_sicxmls41_comi,
    sicpago50_cab_factoraje.id_sicpago50
    from sicpago50_cab_factoraje
    where sicpago50_cab_factoraje.id_sicpago50 = :id_sicpago50x
    into :rela_sicxmls41_comi,
         :id_sicpago50;
    
    select
    sicxmls41_det_migracion.sicxmls41_uuid_importe,
    sicxmls41_det_migracion.sicxmls41_formapago,
    sicxmls41_det_migracion.sicxmls41_moneda,
    sicxmls41_det_migracion.sicxmls41_uuid_fecha,
    sicxmls41_det_migracion.sicxmls41_entidad,
    sicxmls41_det_migracion.sicxmls41_rfc
    from sicxmls41_det_migracion
    where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41_comi
    into :sicxmls41_uuid_importe,
         :sicxmls41_formapago,
         :sicxmls41_moneda,
         :sicxmls41_uuid_fecha,
         :sicxmls41_entidad,
         :sicxmls41_rfc;

    suspend;
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_FACTORAJE_DET (
    ID_SICPAGO50X BIGINT)
RETURNS (
    IDDOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDADR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODODEPAGODR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICPAGO50_COMISION DOUBLE PRECISION,
    IMPSALDOANT_FAC DOUBLE PRECISION,
    IMPSALDOANT_COM DOUBLE PRECISION,
    IMPPAGADO_FAC DOUBLE PRECISION,
    IMPPAGADO_COM DOUBLE PRECISION,
    IMPSALDOINSOLUTO_FAC DOUBLE PRECISION)
AS
declare variable RELA_SICINGR51 bigint;
declare variable SICXMLS41_UUID_IMPORTE double precision;
begin
    select
    sicpago50_cab_factoraje.sicpago50_comision,
    sicpago50_cab_factoraje.rela_sicingr51
    from sicpago50_cab_factoraje
    where sicpago50_cab_factoraje.id_sicpago50 = :id_sicpago50x
    into :sicpago50_comision,
         :rela_sicingr51;

    for select
    GRD_SICINGR52_SICPAGO70.sicxmls41_uuid,
    GRD_SICINGR52_SICPAGO70.sicxmls41_folio,
    GRD_SICINGR52_SICPAGO70.sicxmls41_metododepago,
    GRD_SICINGR52_SICPAGO70.sicxmls41_moneda,
    GRD_SICINGR52_SICPAGO70.sicxmls41_uuid_importe
    from GRD_SICINGR52_SICPAGO70
    where GRD_SICINGR52_SICPAGO70.rela_sicingr51 = :rela_sicingr51
    into :iddocumento,
         :folio,
         :metododepagodr,
         :monedadr,
         :sicxmls41_uuid_importe
    do
    begin
        impsaldoant_fac = sicxmls41_uuid_importe;
        impsaldoinsoluto_fac = impsaldoant_fac * sicpago50_comision / 100;
        imppagado_fac = impsaldoant_fac - impsaldoinsoluto_fac;

        imppagado_com = impsaldoinsoluto_fac;
        impsaldoant_com = impsaldoinsoluto_fac;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_IMPUESTOS (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR72 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TASAOCUOTA DOUBLE PRECISION,
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BASE DOUBLE PRECISION)
AS
begin
    for select
    max(sicingr72_det_impuestos.id_sicingr72),
    SUBSTRING(sicingr72_det_impuestos.sicingr72_tipo FROM 1 FOR 1),
    sum(sicingr72_det_impuestos.sicingr72_importe),
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_tasaocuota,
    sicingr72_det_impuestos.sicingr72_factor,
    sum(sicingr72_det_impuestos.sicingr72_base)
    from sicingr71_det_facturacion
    inner join sicingr72_det_impuestos on (sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    and (sicingr72_det_impuestos.sicingr72_impuesto = 'IVA' OR
         sicingr72_det_impuestos.sicingr72_impuesto = 'ISR' OR
         sicingr72_det_impuestos.sicingr72_impuesto = 'IEPS')
    group by SUBSTRING(sicingr72_det_impuestos.sicingr72_tipo FROM 1 FOR 1),
          sicingr72_det_impuestos.sicingr72_impuesto,
          sicingr72_det_impuestos.sicingr72_tasaocuota,
          sicingr72_det_impuestos.sicingr72_factor
    into :id_sicingr72,
         :tipo,
         :importe,
         :impuesto,
         :tasaocuota,
         :factor,
         :base
    do
    begin
        tasaocuota = tasaocuota / 100;

        if (importe < 0) then
            importe = importe * -1;

        if (impuesto = 'IVA') then
            impuesto = '002';

        else if (impuesto = 'ISR') then
            impuesto = '001';

        else if (impuesto = 'IEPS') then
            impuesto = '003';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_IMPUESTOS_VIEW (
    RELA_SICINGR51 BIGINT)
RETURNS (
    ID_SICINGR72 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TASAOCUOTA DOUBLE PRECISION,
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICINGR70 bigint;
declare variable PORCENTAJE double precision;
declare variable ID_SICXMLS41 bigint;
declare variable RELA_SICCONT10 bigint;
declare variable ID_SICINGR71 bigint;
declare variable IMPPAGADO double precision;
declare variable IMPORTE_XML double precision;
declare variable TASAOCUOTA_C varchar(10);
begin
    for select
    SICINGR52_DET_BANCOS.sicingr52_importe,
    sicingr50_det_ctacte.sicingr50_importe,
    sicingr50_det_ctacte.rela_siccont10
    from SICINGR52_DET_BANCOS
    inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = SICINGR52_DET_BANCOS.rela_sicingr50 )
    WHERE SICINGR52_DET_BANCOS.rela_sicingr51 = :rela_sicingr51
    INTO :imppagado,
         :importe_xml,
         :rela_siccont10
    do
    begin
    select
        sicxmls41_det_migracion.id_sicxmls41
        from sicxmls41_det_migracion
        where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
        into :id_sicxmls41;

        select
        sicingr74_dep_cfdis.RELA_SICINGR70
        from sicingr74_dep_cfdis
        inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
        inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
        where sicingr74_dep_cfdis.rela_sicxmls41 = :id_sicxmls41
        into :rela_sicingr70;

        porcentaje = imppagado / importe_xml * 100;

        for select
        sicingr71_det_facturacion.id_sicingr71
        from sicingr71_det_facturacion
        where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
        into :id_sicingr71
        do
        begin
            for select
            cfdi_conceptos_traslados.id_sicingr72,
            cfdi_conceptos_traslados.importe,
            cfdi_conceptos_traslados.impuesto,
            cfdi_conceptos_traslados.tasaocuota,
            cfdi_conceptos_traslados.factor
            from cfdi_conceptos_traslados(:id_sicingr71)
            into :id_sicingr72,
                 :importe,
                 :impuesto,
                 :tasaocuota_c,
                 :factor
            do
            begin
                tipo = 'T';
                importe = importe * porcentaje / 100;
                tasaocuota = cast(tasaocuota_c as double precision);
                suspend;
            end

            for select
            cfdi_conceptos_retenidos.id_sicingr72,
            cfdi_conceptos_retenidos.importe,
            cfdi_conceptos_retenidos.impuesto,
            cfdi_conceptos_retenidos.tasaocuota,
            cfdi_conceptos_retenidos.factor
            from cfdi_conceptos_retenidos(:id_sicingr71)
            into id_sicingr72,
                 :importe,
                 :impuesto,
                 :tasaocuota_c,
                 :factor
            do
            begin
                tipo = 'R';
                importe = importe * porcentaje / 100;
                tasaocuota = cast(tasaocuota_c as double precision);
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE CFDI_PAGO_IMPUESTOS_WEB (
    RELA_SICINGR70 BIGINT,
    BASE_PAGADO DOUBLE PRECISION)
RETURNS (
    ID_SICINGR72 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TASAOCUOTA DOUBLE PRECISION,
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BASE DOUBLE PRECISION)
AS
declare variable PROPORCION double precision;
begin
    for select
    max(sicingr72_det_impuestos.id_sicingr72),
    SUBSTRING(sicingr72_det_impuestos.sicingr72_tipo FROM 1 FOR 1),
    sum(sicingr72_det_impuestos.sicingr72_importe),
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_tasaocuota,
    sicingr72_det_impuestos.sicingr72_factor,
    sum(sicingr72_det_impuestos.sicingr72_base)
    from sicingr71_det_facturacion
    inner join sicingr72_det_impuestos on (sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    and (sicingr72_det_impuestos.sicingr72_impuesto = 'IVA' OR
         sicingr72_det_impuestos.sicingr72_impuesto = 'ISR' OR
         sicingr72_det_impuestos.sicingr72_impuesto = 'IEPS')
    group by SUBSTRING(sicingr72_det_impuestos.sicingr72_tipo FROM 1 FOR 1),
          sicingr72_det_impuestos.sicingr72_impuesto,
          sicingr72_det_impuestos.sicingr72_tasaocuota,
          sicingr72_det_impuestos.sicingr72_factor
    into :id_sicingr72,
         :tipo,
         :importe,
         :impuesto,
         :tasaocuota,
         :factor,
         :base
    do
    begin
        tasaocuota = tasaocuota / 100;
        proporcion = base_pagado / base;
        base = base * proporcion;
        importe = base * tasaocuota;

        if (importe < 0) then
            importe = importe * -1;

        if (impuesto = 'IVA') then
            impuesto = '002';

        else if (impuesto = 'ISR') then
            impuesto = '001';

        else if (impuesto = 'IEPS') then
            impuesto = '003';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE CFDI_PROCESO_CANCELA_GRAL (
    ID_SICINGR70 BIGINT)
RETURNS (
    MENSAJE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICINGR70FIND bigint;
declare variable ID_SICINGR74 bigint;
begin
    mensaje = 'No se Encontro la Factura';
    id_sicingr70find = null;

    Select sicingr70_cab_facturacion.id_sicingr70
    from sicingr70_cab_facturacion
    where sicingr70_cab_facturacion.id_sicingr70 = :id_sicingr70
    into :id_sicingr70find;

    if (id_sicingr70find is not null) then
    begin
        mensaje = 'Factura Encontrada';
        select sicingr74_dep_cfdis.id_sicingr74
        from sicingr74_dep_cfdis
        where sicingr74_dep_cfdis.rela_sicingr70 = :id_sicingr70find
        into :id_sicingr74;

        if (id_sicingr74 is not null) then
        begin
            mensaje = 'Factura Encontrada y timbrada';
            update sicingr70_cab_facturacion set sicingr70_cab_facturacion.sicingr70_status = 'ERROR. Se Intento ReTimbrar. Se Cancela Proceso'
            where sicingr70_cab_facturacion.id_sicingr70 = :id_sicingr70find;
        end
        else
        begin
            mensaje = 'Factura Encontrada y Sin timbrada';
            update sicingr70_cab_facturacion set sicingr70_cab_facturacion.sicingr70_status = 'ERROR. Se Cancela Proceso Masivo de Timbrado'
            where sicingr70_cab_facturacion.id_sicingr70 = :id_sicingr70find;
        end
    end

    suspend;
end^


