CREATE OR ALTER PROCEDURE CFDI_RETENCIONES (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR72 BIGINT,
    IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION)
AS
begin
    FOR select
    max(sicingr72_det_impuestos.id_sicingr72),
    sicingr72_det_impuestos.sicingr72_impuesto,
    sum(sicingr72_det_impuestos.sicingr72_importe * (-1))
    from sicingr70_cab_facturacion
    inner join sicingr71_det_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr71_det_facturacion.rela_sicingr70)
    inner join sicingr72_det_impuestos on (sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71)
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    and upper(trim(sicingr72_det_impuestos.sicingr72_tipozona)) = 'FEDERAL'
    and  upper(trim(sicingr72_det_impuestos.sicingr72_tipo)) = 'RETENIDO'
    group by sicingr72_det_impuestos.sicingr72_impuesto
    into :id_sicingr72,
         :impuesto,
         :importe
    do
    begin
        suspend;
    end
end^


