CREATE OR ALTER PROCEDURE GRD_PYMALMA01_DESTINO_WEB (
    P_RELA_SOCMAIN01 BIGINT,
    P_RELA_SICINGR95 BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    ID_PYMALMA01 BIGINT,
    PYMALMA01_FAPL TIMESTAMP,
    SOCMAIN21_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STOCK DOUBLE PRECISION)
AS
declare variable V_SICINGR95_CODIGO varchar(50);
declare variable V_ID_SICXMLS01 bigint;
BEGIN
    v_id_sicxmls01 = null;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :p_rela_socmain01
    into :v_id_sicxmls01;

    if (v_id_sicxmls01 is null) then
    begin
        EXIT;
    end

    select
    sicingr95_cab_conceptos.sicingr95_codigo
    from sicingr95_cab_conceptos
    where sicingr95_cab_conceptos.id_sicingr95 = :p_rela_sicingr95
    into :v_sicingr95_codigo;

    if (v_sicingr95_codigo is null) then
    begin
        EXIT;
    end

    p_rela_sicingr95 = null;

    select sicingr95_cab_conceptos.id_sicingr95
    from sicingr95_cab_conceptos
    where sicingr95_cab_conceptos.rela_sicxmls01 = :v_id_sicxmls01
    and sicingr95_cab_conceptos.sicingr95_codigo = :v_sicingr95_codigo
    into :p_rela_sicingr95;

    if (p_rela_sicingr95 is null) then
    begin
        EXIT;
    end

    FOR SELECT
        GRD_PYMALMA01.RELA_SOCMAIN01,
        GRD_PYMALMA01.RELA_SOCMAIN21,
        GRD_PYMALMA01.RELA_SOCUSUA01,
        GRD_PYMALMA01.ID_PYMALMA01,
        GRD_PYMALMA01.PYMALMA01_FAPL,
        GRD_PYMALMA01.SOCMAIN21_CODIGO,
        GRD_PYMALMA01.SOCMAIN21_DESCRIPCION,
        GRD_PYMALMA01.SOCMAIN01_NOMCOMERCIAL,
        COALESCE((
            SELECT SUM(PYMALMA02_DET_STOCK.PYMALMA02_CANTIDAD)
            FROM PYMALMA02_DET_STOCK
            WHERE PYMALMA02_DET_STOCK.RELA_PYMALMA01 = GRD_PYMALMA01.ID_PYMALMA01
            AND PYMALMA02_DET_STOCK.RELA_SICINGR95 = :P_RELA_SICINGR95
        ), 0)
    FROM GRD_PYMALMA01
    WHERE GRD_PYMALMA01.RELA_SOCMAIN01 = :P_RELA_SOCMAIN01
    and EXISTS (select sicingr95_cab_conceptos.id_sicingr95
                from sicingr95_cab_conceptos
                where sicingr95_cab_conceptos.id_sicingr95 = :p_rela_sicingr95)
    ORDER BY GRD_PYMALMA01.SOCMAIN21_DESCRIPCION
    INTO :RELA_SOCMAIN01,
         :RELA_SOCMAIN21,
         :RELA_SOCUSUA01,
         :ID_PYMALMA01,
         :PYMALMA01_FAPL,
         :SOCMAIN21_CODIGO,
         :SOCMAIN21_DESCRIPCION,
         :SOCMAIN01_NOMCOMERCIAL,
         :STOCK
    DO
    BEGIN
        SUSPEND;
    END
END^


