            WHERE PYMALMA02_DET_STOCK.RELA_PYMALMA01 = GRD_PYMALMA01.ID_PYMALMA01
            AND PYMALMA02_DET_STOCK.RELA_SICINGR95 = :P_RELA_SICINGR95
