    FROM GRD_PYMALMA01
    WHERE GRD_PYMALMA01.RELA_SOCMAIN01 = :P_RELA_SOCMAIN01
    ORDER BY GRD_PYMALMA01.SOCMAIN21_DESCRIPCION
    INTO :RELA_SOCMAIN01,
         :RELA_SOCMAIN21,
         :RELA_SOCUSUA01,
         :ID_PYMALMA01,
