CREATE OR ALTER PROCEDURE GRD_PYMALMA02 (
    RELA_PYMALMA01 BIGINT,
    RELA_SICINGR95 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SOCSYST10_STK01 BIGINT,
    ID_PYMALMA02 BIGINT,
    PYMALMA02_CANTIDAD DOUBLE PRECISION,
    PYMALMA02_FAPL TIMESTAMP,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_PYMALMA01_TRANSF bigint;
begin
    for select
    pymalma02_det_stock.rela_pymalma01_transf,
    pymalma02_det_stock.rela_socsyst10_stk01,
    pymalma02_det_stock.id_pymalma02,
    pymalma02_det_stock.pymalma02_cantidad,
    pymalma02_det_stock.pymalma02_fapl,
    socsyst10_det_entradas.socsyst10_descripcion
    from sicingr95_cab_conceptos
       inner join pymalma02_det_stock on (sicingr95_cab_conceptos.id_sicingr95 = pymalma02_det_stock.rela_sicingr95)
       inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = pymalma02_det_stock.rela_socsyst10_stk01)
    where pymalma02_det_stock.rela_pymalma01 = :rela_pymalma01 and pymalma02_det_stock.rela_sicingr95 = :rela_sicingr95
    and cast(pymalma02_det_stock.pymalma02_fapl as date) between :fecha_desde and :fecha_hasta
    order by pymalma02_det_stock.pymalma02_fapl desc
    into :rela_pymalma01_transf,
         :rela_socsyst10_stk01,
         :id_pymalma02,
         :pymalma02_cantidad,
         :pymalma02_fapl,
         :socsyst10_descripcion
    do
    begin
        socmain21_descripcion = null;
        empresa = null;

        if (rela_pymalma01_transf IS NOT NULL) then
            select
            socmain21_arb_organizacion.socmain21_descripcion,
            socmain01_cab_empresas.socmain01_nomcomercial
            from pymalma01_cab_stock
            inner join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = pymalma01_cab_stock.rela_socmain21)
            inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = pymalma01_cab_stock.rela_socmain01)
            where pymalma01_cab_stock.id_pymalma01 = :rela_pymalma01_transf
            into :socmain21_descripcion,
                 :empresa;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMALMA11_SICEGRE81 (
    P_RELA_PYMALMA10 BIGINT)
RETURNS (
    ID_PYMALMA11 BIGINT,
    PYMALMA11_CANTIDAD_SOL DOUBLE PRECISION,
    PYMALMA11_CANTIDAD_REC DOUBLE PRECISION,
    SICEGRE81_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE81_CODIGO_PROVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE81_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE81_CONCEPTO_PROVE VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE81_IMPORTE DOUBLE PRECISION)
AS
begin
  FOR SELECT pymalma11_det_productos.id_pymalma11,
             pymalma11_det_productos.pymalma11_cantidad_sol,
             pymalma11_det_productos.pymalma11_cantidad_rec,
             sicegre81_det_productos.sicegre81_codigo,
             sicegre81_det_productos.sicegre81_codigo_prove,
             sicegre81_det_productos.sicegre81_concepto,
             sicegre81_det_productos.sicegre81_concepto_prove,
             sicegre81_det_productos.sicegre81_importe
      FROM pymalma11_det_productos
      INNER JOIN sicegre81_det_productos ON (pymalma11_det_productos.rela_sicegre81 = sicegre81_det_productos.id_sicegre81)
      WHERE pymalma11_det_productos.rela_pymalma10 = :p_rela_pymalma10
      INTO  id_pymalma11,
            pymalma11_cantidad_sol,
