  DO BEGIN
      suspend;
  END
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT01 (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X BIGINT)
RETURNS (
    RELA_SOCMAIN01 INTEGER,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCMAIN21_APARTADO BIGINT,
    RELA_SOCUSUA01_SUPE BIGINT,
    RELA_SOCUSUA01_CAJE BIGINT,
    RELA_SOCSYST10_PVC01 BIGINT,
    ID_PYMVENT01 BIGINT,
    PYMVENT01_FAPL TIMESTAMP,
    PYMVENT01_PATHWORK VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SUPERVISOR VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SUPERVISOR_PASS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJERO VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJERO_PASS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJA_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPRESION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPRESION_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT01_ANCHOTICKET DOUBLE PRECISION,
    PYMVENT01_CONLOGO INTEGER,
    PYMVENT01_CONCODIGO INTEGER,
    PYMVENT01_TEST INTEGER,
    PYMVENT01_COPIASTICKET INTEGER,
    PYMVENT01_FULLSCREEN INTEGER,
    PYMVENT01_REPTICKET INTEGER,
    PYMVENT01_REPPRESU INTEGER,
    PYMVENT01_REPAPART INTEGER,
    PYMVENT01_FACTURA INTEGER,
    PYMVENT01_REGLAS INTEGER,
    PYMVENT01_VALSTK INTEGER,
    PYMVENT01_EDITAIMP INTEGER,
    PYMVENT01_MENSAJE_TOP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT01_MENSAJE_DOWN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT01_REGLAS_NEGO INTEGER)
AS
begin
    FOR SELECT
    PYMVENT01_CAB_CAJAS.rela_socmain01,
    PYMVENT01_CAB_CAJAS.rela_socmain21,
    PYMVENT01_CAB_CAJAS.rela_socmain21_apartado,
    PYMVENT01_CAB_CAJAS.rela_socusua01_supe,
    PYMVENT01_CAB_CAJAS.rela_socusua01_caje,
    PYMVENT01_CAB_CAJAS.rela_socsyst10_pvc01,
    PYMVENT01_CAB_CAJAS.id_pymvent01,
    PYMVENT01_CAB_CAJAS.pymvent01_fapl,
    PYMVENT01_CAB_CAJAS.pymvent01_pathwork,
    PYMVENT01_CAB_CAJAS.pymvent01_anchoticket,
    PYMVENT01_CAB_CAJAS.pymvent01_conlogo,
    PYMVENT01_CAB_CAJAS.pymvent01_concodigo,
    PYMVENT01_CAB_CAJAS.pymvent01_test,
    PYMVENT01_CAB_CAJAS.pymvent01_copiasticket,
    PYMVENT01_CAB_CAJAS.pymvent01_fullscreen,
    PYMVENT01_CAB_CAJAS.pymvent01_repticket,
    PYMVENT01_CAB_CAJAS.pymvent01_reppresu,
    PYMVENT01_CAB_CAJAS.pymvent01_repapart,
    PYMVENT01_CAB_CAJAS.pymvent01_factura,
    PYMVENT01_CAB_CAJAS.pymvent01_reglas,
    PYMVENT01_CAB_CAJAS.pymvent01_valstk,
    PYMVENT01_CAB_CAJAS.pymvent01_editaimp,
    PYMVENT01_CAB_CAJAS.pymvent01_mensaje_top,
    PYMVENT01_CAB_CAJAS.pymvent01_mensaje_down,
    PYMVENT01_CAB_CAJAS.pymvent01_reglas_nego,
    pvc01.socsyst10_codigo,
    pvc01.socsyst10_descripcion,
    pvi01.socsyst10_descripcion,
    pvi01.socsyst10_codigo
    FROM PYMVENT01_CAB_CAJAS
    inner join socsyst10_det_entradas pvc01 on ( pvc01.id_socsyst10 = PYMVENT01_CAB_CAJAS.rela_socsyst10_pvc01 )
    inner join socsyst10_det_entradas pvi01 on ( pvi01.id_socsyst10 = PYMVENT01_CAB_CAJAS.rela_socsyst10_pvi01 )
    where PYMVENT01_CAB_CAJAS.rela_socmain01 = :rela_socmain01x
    and PYMVENT01_CAB_CAJAS.rela_socmain21 = :rela_socmain21x
    INTO :rela_socmain01,
         :rela_socmain21,
         :rela_socmain21_apartado,
         :rela_socusua01_supe,
         :rela_socusua01_caje,
         :rela_socsyst10_pvc01,
         :id_pymvent01,
         :pymvent01_fapl,
         :pymvent01_pathwork,
         :pymvent01_anchoticket,
         :pymvent01_conlogo,
         :pymvent01_concodigo,
         :pymvent01_test,
         :pymvent01_copiasticket,
         :pymvent01_fullscreen,
         :pymvent01_repticket,
         :pymvent01_reppresu,
         :pymvent01_repapart,
         :pymvent01_factura,
         :pymvent01_reglas,
         :pymvent01_valstk,
         :pymvent01_editaimp,
         :pymvent01_mensaje_top,
         :pymvent01_mensaje_down, 
         :pymvent01_reglas_nego,
         :caja_codigo,
         :caja,
         :impresion,
         :impresion_codigo
    DO
    BEGIN
        select
        cbo_socusua01.entidad,
        cbo_socusua01.clave
        from cbo_socusua01(:rela_socmain01, :rela_socmain21, :rela_socusua01_supe)
        into :supervisor,
             :supervisor_pass;

        select
        cbo_socusua01.entidad,
        cbo_socusua01.clave
        from cbo_socusua01(:rela_socmain01, :rela_socmain21, :rela_socusua01_caje)
        into :cajero,
             :cajero_pass;

        SUSPEND;
    END
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT15 (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SOCMAIN21 BIGINT,
    RELA_SICINGR95 BIGINT,
    ID_PYMVENT15 BIGINT,
    PYMVENT15_REGLA INTEGER,
    PYMVENT15_PORCENTAJE DOUBLE PRECISION,
    PYMVENT15_VOL_STOCK DOUBLE PRECISION,
    PYMVENT15_VOL_VENTA DOUBLE PRECISION,
    PYMVENT15_STOCKCERO INTEGER,
    PYMVENT15_FVTO DATE,
    PYMVENT15_SEMANA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT15_PUNTOS DOUBLE PRECISION,
    PYMVENT15_FAPL TIMESTAMP,
    PYMVENT15_REGALO DOUBLE PRECISION,
    PYMVENT15_REGALO_MIN DOUBLE PRECISION,
    SUCURSAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGALO_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGALO_PRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DESCRIPCION VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    id_pymvent15 = -1;
    descripcion = 'Nueva Regla de Negocio';

    suspend;

    FOR SELECT
    pymvent15_cab_xreglas.rela_socmain21,
    pymvent15_cab_xreglas.rela_sicingr95,
    pymvent15_cab_xreglas.id_pymvent15,
    pymvent15_cab_xreglas.pymvent15_regla,
    pymvent15_cab_xreglas.pymvent15_porcentaje,
    pymvent15_cab_xreglas.pymvent15_vol_stock,
    pymvent15_cab_xreglas.pymvent15_vol_venta,
    pymvent15_cab_xreglas.pymvent15_stockcero,
    pymvent15_cab_xreglas.pymvent15_fvto,
    pymvent15_cab_xreglas.pymvent15_semana,
    pymvent15_cab_xreglas.pymvent15_puntos,
    pymvent15_cab_xreglas.pymvent15_fapl,
    pymvent15_cab_xreglas.pymvent15_regalo,
    pymvent15_cab_xreglas.pymvent15_regalo_min
    FROM pymvent15_cab_xreglas
    WHERE pymvent15_cab_xreglas.rela_socmain01 = :rela_socmain01
    INTO :rela_socmain21,
         :rela_sicingr95,
         :id_pymvent15,
         :pymvent15_regla,
         :pymvent15_porcentaje,
         :pymvent15_vol_stock,
         :pymvent15_vol_venta,
         :pymvent15_stockcero,
         :pymvent15_fvto,
         :pymvent15_semana,
         :pymvent15_puntos,
         :pymvent15_fapl,
         :pymvent15_regalo,
         :pymvent15_regalo_min
    DO
    BEGIN
        descripcion = '';

        if (rela_socmain21 is not null) then
        begin
            select socmain21_arb_organizacion.socmain21_descripcion
            from socmain21_arb_organizacion
            where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
            into :sucursal;

            descripcion = 'Regla por Sucursal : ' || :sucursal;
        end

        if (rela_sicingr95 is not null) then
        begin
            select
            sicingr95_cab_conceptos.sicingr95_codigo,
            sicingr95_cab_conceptos.sicingr95_descripcion
            from sicingr95_cab_conceptos
            where sicingr95_cab_conceptos.id_sicingr95 = :rela_sicingr95
            into :regalo_codigo,
                 :regalo_producto;

            descripcion = descripcion || ' Producto de Regalo : ' || :regalo_producto;
        end

        if (rela_sicingr95 is null) then
        begin
            if (pymvent15_regla = 0) then
                descripcion = descripcion || ' Por Porcentaje ' || cast(pymvent15_porcentaje as numeric(12,2)) || ' %';
            else
                descripcion = descripcion || ' Lleva ' || cast(pymvent15_vol_stock as numeric(12,2)) ||
                                             ' Paga ' || cast(pymvent15_vol_venta as numeric(12,2));
        end

        if (PYMVENT15_STOCKCERO = 0) then
            descripcion = descripcion || ' Stock sin Límite';
        else
            descripcion = descripcion || ' Stock Con Límite';

        descripcion = trim(descripcion);
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT16 (
    RELA_PYMVENT15X BIGINT)
RETURNS (
    RELA_PYMVENT15 BIGINT,
    RELA_SICINGR95 BIGINT,
    ID_PYMVENT16 BIGINT,
    PYMVENT16_STOCK DOUBLE PRECISION,
    PYMVENT16_STOCK_CONT DOUBLE PRECISION,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT16_IMPORTE_COSTO DOUBLE PRECISION,
    PYMVENT16_IMPORTE_VENTA DOUBLE PRECISION,
    PYMVENT16_FAPL TIMESTAMP)
AS
begin
    FOR SELECT
    pymvent16_det_xreglas_p.rela_pymvent15,
    pymvent16_det_xreglas_p.rela_sicingr95,
    pymvent16_det_xreglas_p.id_pymvent16,
    pymvent16_det_xreglas_p.pymvent16_stock,
    pymvent16_det_xreglas_p.pymvent16_stock_cont,
    sicingr95_cab_conceptos.sicingr95_codigo,
    sicingr95_cab_conceptos.sicingr95_descripcion,
    pymvent16_det_xreglas_p.pymvent16_importe_costo,
    pymvent16_det_xreglas_p.pymvent16_importe_venta,
    pymvent16_det_xreglas_p.pymvent16_fapl
    FROM pymvent16_det_xreglas_p
    INNER JOIN sicingr95_cab_conceptos ON ( sicingr95_cab_conceptos.id_sicingr95 = pymvent16_det_xreglas_p.rela_sicingr95 )
    WHERE pymvent16_det_xreglas_p.rela_pymvent15 = :rela_pymvent15x
    INTO :rela_pymvent15,
         :rela_sicingr95,
         :id_pymvent16,
