         :pymvent16_stock_cont,
         :sicingr95_codigo,
         :sicingr95_descripcion,
         :pymvent16_importe_costo,
         :pymvent16_importe_venta,
         :pymvent16_fapl
    DO
    BEGIN
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT50 (
    ID_PYMVENT01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SOCUSUA01_SUPER BIGINT,
    RELA_PYMVENT01 BIGINT,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT50_IMPORTE_APERTURA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_VENTA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_EFECTIVO DOUBLE PRECISION,
    PYMVENT50_FAPERTURA TIMESTAMP,
    PYMVENT50_FCIERRE TIMESTAMP,
    PYMVENT50_FAPL TIMESTAMP,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SUPERVISOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJERO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SQL_C varchar(5000);
declare variable CODIGO varchar(50);
declare variable TOTALES double precision;
begin
    sql_c = 'select super.id_socusua01, ' ||
            'PYMVENT50_CAB_APERTURA.rela_pymvent01, ' ||
            'PYMVENT50_CAB_APERTURA.id_pymvent50, ' ||
            'PYMVENT50_CAB_APERTURA.PYMVENT50_DOCNRO, ' ||
            'PYMVENT50_CAB_APERTURA.pymvent50_importe_apertura, ' ||
            'PYMVENT50_CAB_APERTURA.pymvent50_importe_venta, ' ||
            'PYMVENT50_CAB_APERTURA.pymvent50_importe_efectivo, ' ||
            'PYMVENT50_CAB_APERTURA.pymvent50_fapertura, ' ||
            'PYMVENT50_CAB_APERTURA.pymvent50_fcierre, ' ||
            'PYMVENT50_CAB_APERTURA.pymvent50_fapl, ' ||
            'socsyst10_det_entradas.socsyst10_codigo, ' ||
            'socsyst10_det_entradas.socsyst10_descripcion, ' ||
            'super.socusua01_usuario, ' ||
            'cajero.socusua01_usuario ' ||
            'FROM PYMVENT50_CAB_APERTURA ' ||
            'inner join pymvent01_cab_cajas on ( pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01 ) ' ||
            'inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = pymvent01_cab_cajas.rela_socsyst10_pvc01 ) ' ||
            'inner join socusua01_cab_usuarios super on (super.id_socusua01 = pymvent01_cab_cajas.rela_socusua01_supe ) ' ||
            'inner join socusua01_cab_usuarios cajero on (cajero.id_socusua01 = pymvent01_cab_cajas.rela_socusua01_caje ) ' ||
            'where pymvent01_cab_cajas.id_pymvent01 = ' || :id_pymvent01;

    if (fecha_desde is not null and fecha_desde is not null) then
    begin
        sql_c = sql_c || ' and cast(PYMVENT50_CAB_APERTURA.pymvent50_fcierre as date) between ''' ||
                :fecha_desde || ''' and ''' || :fecha_hasta || '''';

    end
    else
    begin
        sql_c = sql_c || ' and PYMVENT50_CAB_APERTURA.pymvent50_fcierre is null';
    end

    for execute statement :sql_c
    into :rela_socusua01_super,
         :rela_pymvent01,
         :id_pymvent50,
         :PYMVENT50_DOCNRO,
         :pymvent50_importe_apertura,
         :pymvent50_importe_venta,
         :pymvent50_importe_efectivo,
         :pymvent50_fapertura,
         :pymvent50_fcierre,
         :pymvent50_fapl,
         :socsyst10_codigo,
         :socsyst10_descripcion,
         :supervisor,
         :cajero
    do
    begin
        for select
        rep_pymvent50_cobros.socsyst10_codigo,
        rep_pymvent50_cobros.totales
        from rep_pymvent50_cobros(:id_pymvent50)
        where rep_pymvent50_cobros.socsyst10_codigo = 'Z1'
        or rep_pymvent50_cobros.socsyst10_codigo = 'Z3'
        into :codigo,
             :totales
        do
        begin
            if (codigo = 'Z1') then
                pymvent50_importe_venta = totales;
            else if (codigo = 'Z3') then
                pymvent50_importe_efectivo = totales;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT51_PENDIENTES (
    RELA_SOCUSUA01_CAJERO BIGINT,
    RELA_PYMVENT50X BIGINT,
    RELA_PYMVENT01 BIGINT)
RETURNS (
    RELA_SOCUSUA01_VEND BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_PYMVENT70 BIGINT,
    ID_PYMVENT51 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_NETO DOUBLE PRECISION,
    VENDEDOR VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_FVENCIDO TIMESTAMP,
    RELA_PYMVENT50 BIGINT,
    RELA_SOCMAIN21_APARTADOS BIGINT,
    PYMVENT51_DIASAPARTADO INTEGER,
    RELA_SOCUSUA30 BIGINT,
    SALDO_APARTADO DOUBLE PRECISION)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
begin
    FOR SELECT
    pymvent01_cab_cajas.rela_socmain01,
    pymvent01_cab_cajas.rela_socmain21,
    pymvent51_det_ventas.rela_socusua01_vend,
    pymvent51_det_ventas.rela_pymvent70,
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent51_det_ventas.id_pymvent51,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_neto,
    pymvent51_det_ventas.pymvent51_fvencido,
    pymvent51_det_ventas.rela_pymvent50,
    pymvent51_det_ventas.rela_socmain21_apartados,
    pymvent51_det_ventas.pymvent51_diasapartado
    FROM pymvent51_det_ventas
    inner join pymvent50_cab_apertura on ( pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50 )
    inner join pymvent01_cab_cajas on ( pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01 )
    inner join pymvent70_cab_ticket on ( pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70 )
    where pymvent50_cab_apertura.rela_pymvent01 = :rela_pymvent01
    and pymvent51_det_ventas.rela_pymvent50 = :rela_pymvent50x
    and pymvent01_cab_cajas.rela_socusua01_caje = :rela_socusua01_cajero
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent51_det_ventas.pymvent51_cancelado <> 9
    and not exists ( select first 1 PYMVENT60_CAB_COBRO.id_pymvent60
                     from PYMVENT60_CAB_COBRO
                     where PYMVENT60_CAB_COBRO.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51
                    )
    and not exists ( select first 1 PYMVENT74_DEP_PYMVENT70_CANC.id_pymvent74
                     from PYMVENT74_DEP_PYMVENT70_CANC
                     where PYMVENT74_DEP_PYMVENT70_CANC.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70 )
    and not exists ( select first 1 pymvent57_det_presupuesto.id_pymvent57
                     from pymvent57_det_presupuesto
                     where pymvent57_det_presupuesto.rela_pymvent70_presu = pymvent51_det_ventas.rela_pymvent70 )

    union all

    SELECT
    pymvent01_cab_cajas.rela_socmain01,
    pymvent01_cab_cajas.rela_socmain21,
    pymvent51_det_ventas.rela_socusua01_vend,
    pymvent51_det_ventas.rela_pymvent70,
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent51_det_ventas.id_pymvent51,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_neto,
    pymvent51_det_ventas.pymvent51_fvencido,
    pymvent51_det_ventas.rela_pymvent50,
    pymvent51_det_ventas.rela_socmain21_apartados,
    pymvent51_det_ventas.pymvent51_diasapartado
    FROM pymvent51_det_ventas
    inner join pymvent50_cab_apertura on ( pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50 )
    inner join pymvent01_cab_cajas on ( pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01 )
    inner join pymvent70_cab_ticket on ( pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70 )
    where pymvent50_cab_apertura.rela_pymvent01 = :rela_pymvent01
    and (pymvent51_det_ventas.pymvent51_fvencido is not null or pymvent51_det_ventas.pymvent51_diasapartado <> 0)
    and pymvent51_det_ventas.pymvent51_cancelado <> 9
    and not exists ( select first 1 PYMVENT60_CAB_COBRO.id_pymvent60
                     from PYMVENT60_CAB_COBRO
                     where PYMVENT60_CAB_COBRO.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51
                    )
    and not exists ( select first 1 PYMVENT74_DEP_PYMVENT70_CANC.id_pymvent74
                     from PYMVENT74_DEP_PYMVENT70_CANC
                     where PYMVENT74_DEP_PYMVENT70_CANC.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70 )
    and not exists ( select first 1 pymvent57_det_presupuesto.id_pymvent57
                     from pymvent57_det_presupuesto
                     where pymvent57_det_presupuesto.rela_pymvent70_presu = pymvent51_det_ventas.rela_pymvent70 )
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01_vend,
         :rela_pymvent70,
         :rela_sicingr01,
         :id_pymvent51,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto,
         :pymvent51_fvencido,
         :rela_pymvent50,
         :rela_socmain21_apartados,
         :pymvent51_diasapartado

    do
    begin
         select CBO_SOCUSUA01.entidad
         from CBO_SOCUSUA01(:rela_socmain01, :rela_socmain21, :rela_socusua01_vend)
         into :vendedor;

         if (rela_sicingr01 is null) then
         begin
            cliente = 'Venta Consumidor Final';
         end
         else
         begin
            select
            cbo_sicingr01_id.entidad,
            cbo_sicingr01_id.rela_socusua30
            from cbo_sicingr01_id
            where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
            into :cliente,
                 :rela_socusua30;
         end

         saldo_apartado = null;

         if (pymvent51_diasapartado <> 0) then
            Select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent55_mov_moventsal
            where pymvent55_mov_moventsal.rela_pymvent70 = :rela_pymvent70
            into :saldo_apartado;

         if (saldo_apartado is null) then
            saldo_apartado = 0.00;
         else
            saldo_apartado = saldo_apartado * (-1);

         if (pymvent51_diasapartado <> 99) then
            suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT55 (
    ID_SICINGR01 BIGINT,
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_PYMVENT55 BIGINT,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT55_IMPORTE DOUBLE PRECISION,
    PYMVENT55_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TICKET_NRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TICKET_FECHA TIMESTAMP,
    TICKET_IMPORTE DOUBLE PRECISION,
    PYMVENT55_FAPL TIMESTAMP,
    PYMVENT50_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT50_FAPERTURA TIMESTAMP,
    RELA_SOCUSUA30 BIGINT,
    ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN_CODIGO INTEGER)
AS
declare variable RELA_PYMVENT70 bigint;
declare variable C_SQL varchar(4000);
declare variable SALDOMONEDERO double precision;
declare variable PYMVENT55_PAGOTICKET integer;
declare variable RELA_PYMVENT56 bigint;
begin
    if (ID_PYMVENT50 IS NOT NULL) then
    BEGIN
        c_sql = 'SELECT
                pymvent55_mov_moventsal.rela_socusua30,
                pymvent55_mov_moventsal.id_pymvent55,
                CBO_SOCUSUA30_ALL.entidad,
                pymvent55_mov_moventsal.rela_pymvent70,
                pymvent55_mov_moventsal.pymvent55_importe,
                pymvent55_mov_moventsal.pymvent55_notas,
                pymvent55_mov_moventsal.pymvent55_fapl,
                pymvent50_cab_apertura.pymvent50_docnro,
                pymvent50_cab_apertura.pymvent50_fapertura,
                pymvent55_mov_moventsal.pymvent55_pagoticket
                FROM pymvent55_mov_moventsal
                INNER JOIN CBO_SOCUSUA30_ALL ON (CBO_SOCUSUA30_ALL.id_socusua30 = pymvent55_mov_moventsal.rela_socusua30)
                inner join pymvent50_cab_apertura on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
                WHERE pymvent55_mov_moventsal.rela_pymvent50 = ' || :id_pymvent50;
    END
    ELSE
    BEGIN
        select sicingr01_cab_clientes.rela_socusua30
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        into :rela_socusua30;

        c_sql = 'SELECT
                pymvent55_mov_moventsal.rela_socusua30,
                pymvent55_mov_moventsal.id_pymvent55,
                CBO_SOCUSUA30_ALL.entidad,
                pymvent55_mov_moventsal.rela_pymvent70,
                pymvent55_mov_moventsal.pymvent55_importe,
                pymvent55_mov_moventsal.pymvent55_notas,
                pymvent55_mov_moventsal.pymvent55_fapl,
                pymvent50_cab_apertura.pymvent50_docnro,
                pymvent50_cab_apertura.pymvent50_fapertura,
                pymvent55_mov_moventsal.pymvent55_pagoticket
                FROM pymvent55_mov_moventsal
                INNER JOIN CBO_SOCUSUA30_ALL ON (CBO_SOCUSUA30_ALL.id_socusua30 = pymvent55_mov_moventsal.rela_socusua30)
                inner join pymvent50_cab_apertura on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
                WHERE pymvent55_mov_moventsal.rela_pymvent70 is not null and
                 pymvent55_mov_moventsal.rela_socusua30 = ' || :rela_socusua30;
    END

    for execute statement :c_sql
    INTO :rela_socusua30,
         :id_pymvent55,
         :entidad,
         :rela_pymvent70,
         :pymvent55_importe,
         :pymvent55_notas,
         :pymvent55_fapl,
         :pymvent50_docnro,
         :pymvent50_fapertura,
         :pymvent55_pagoticket
    do
    begin
        ticket_nro = null;
        ticket_fecha = null;
        ticket_importe = null;

        if (rela_pymvent70 is not null) then
        begin
            select
            pymvent70_cab_ticket.pymvent70_docnro,
            pymvent70_cab_ticket.pymvent70_fecha,
            pymvent70_cab_ticket.pymvent70_neto
            from pymvent70_cab_ticket
            where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
            into :ticket_nro,
                 :ticket_fecha,
                 :ticket_importe;

        end

        /* --------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------- */

        origen = null;
        origen_codigo = pymvent55_pagoticket;

        if (pymvent55_pagoticket = 0) then
        begin
            if (pymvent55_importe > 0) then
                origen = 'Entrada Efectivo';
            else
                origen = 'Salida Efectivo';
            SUSPEND;
        end
        else if (pymvent55_pagoticket = 3) then
        begin
            if (pymvent55_importe > 0) then
                origen = 'Paga Crédito';
            else
                origen = 'Ingreso de Crédito';
            SUSPEND;
        end
       /*$$IBEC$$  else if (pymvent55_pagoticket = 4) then
        begin
            if (rela_pymvent70 is not null and pymvent55_importe > 0) then
            begin
                --Para descartar los pagos con monedero que no son a credito o apartados
                select
                    pymvent56_det_cobro.id_pymvent56
                from pymvent56_det_cobro
                  -- inner join socsyst10_det_remoto on (pymvent56_det_cobro.rela_socsyst10_fdp01 = socsyst10_det_remoto.id_socsyst10)
                where pymvent56_det_cobro.rela_pymvent55 = :id_pymvent55
                into :rela_pymvent56;

                if (:rela_pymvent56 is not null) then
                begin
                    origen = 'Pago con Monedero Electrónico ';
                    SUSPEND;
                end
            end
             $$IBEC$$*//*$$IBEC$$ else if (rela_pymvent70 is not null and pymvent55_importe <= 0) then
                BEGIN
                origen = 'Ingreso Monedero Electrónico por Cancelación';
                pymvent55_importe = (-1)*pymvent55_importe;   --HV 06/05/2019
                END
            else begin
                origen = 'Salida Efectivo por Monedero Electrónico';
                pymvent55_importe = (-1)*pymvent55_importe;   --HV 07/05/2019
            end $$IBEC$$*//*$$IBEC$$ 

        end $$IBEC$$*/
        else if (pymvent55_pagoticket = 5) then
        begin
            if (pymvent55_importe < 0) then
                origen = 'Entrada Apartado';
            else
                origen = 'Anticipo de Apartado';
             SUSPEND;
        end
        else if (pymvent55_pagoticket = 6) then  --HV 08/05/2019
            begin
                origen = 'Diminución por Cancelación';
                pymvent55_importe = (-1)*pymvent55_importe;
            SUSPEND;
            end


       -- suspend;

    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT55_MONEDERO (
    ID_SICINGR01 BIGINT)
RETURNS (
    ID_PYMVENT55 BIGINT,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT55_IMPORTE DOUBLE PRECISION,
    PYMVENT55_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT55_FAPL TIMESTAMP,
    RELA_SOCUSUA30 BIGINT,
    ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT55_PAGOTICKET INTEGER)
AS
declare variable RELA_PYMVENT70 bigint;
begin

  select sicingr01_cab_clientes.rela_socusua30
    from sicingr01_cab_clientes
    where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
    into :rela_socusua30;

   for SELECT
        pymvent55_mov_moventsal.rela_socusua30,
        pymvent55_mov_moventsal.id_pymvent55,
        CBO_SOCUSUA30_ALL.entidad,
        pymvent55_mov_moventsal.rela_pymvent70,
        pymvent55_mov_moventsal.pymvent55_importe,
        pymvent55_mov_moventsal.pymvent55_notas,
        pymvent55_mov_moventsal.pymvent55_fapl,
        pymvent55_mov_moventsal.pymvent55_pagoticket
        FROM pymvent55_mov_moventsal
        INNER JOIN CBO_SOCUSUA30_ALL ON (CBO_SOCUSUA30_ALL.id_socusua30 = pymvent55_mov_moventsal.rela_socusua30)
        WHERE (pymvent55_mov_moventsal.pymvent55_pagoticket = 4 or
        (pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and pymvent55_mov_moventsal.pymvent55_importe > 0))
            and pymvent55_mov_moventsal.rela_socusua30 = :rela_socusua30
        order by   pymvent55_mov_moventsal.pymvent55_fapl
    INTO :rela_socusua30,
         :id_pymvent55,
         :entidad,
         :rela_pymvent70,
         :pymvent55_importe,
         :pymvent55_notas,
         :pymvent55_fapl,
         :pymvent55_pagoticket
    do
    begin
        origen = null;
        if (rela_pymvent70 is not null and pymvent55_importe > 0) then
        Begin
            if (pymvent55_pagoticket = 3) then
            begin
                select
                    sum(pymvent56_det_cobro.pymvent56_valor)
                from pymvent56_det_cobro
                   inner join socsyst10_det_remoto on (pymvent56_det_cobro.rela_socsyst10_fdp01 = socsyst10_det_remoto.id_socsyst10)
                where socsyst10_det_remoto.socsyst10_codigo = '05' and
                    pymvent56_det_cobro.rela_pymvent55 = :id_pymvent55
                into :pymvent55_importe;
            end
            if (pymvent55_importe is not null) then
            begin
                origen = 'Pago con Monedero Electrónico ';
                suspend;
            end
        end
        else if (rela_pymvent70 is not null and pymvent55_importe <= 0) then
            begin
                origen = 'Ingreso Monedero Electrónico por Cancelación';
                suspend;
            end
            else if (rela_pymvent70 is null and pymvent55_importe > 0) then
                begin
                    origen = 'Salida Efectivo por Monedero Electrónico';
                    suspend;
                end

    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT71_XCANCELAR (
    ID_PYMVENT70 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_PYMVENT71 BIGINT,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_NETO DOUBLE PRECISION,
    CANTIDAD_CANCELADA DOUBLE PRECISION,
    IMPORTE_CANCELADO DOUBLE PRECISION,
    NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SUMA_CANTIDAD double precision;
declare variable SUMA_IMPORTE double precision;
begin
    for select
    0,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_neto
    from pymvent71_det_ticket
    where pymvent71_det_ticket.rela_pymvent70 = :id_pymvent70
    and pymvent71_det_ticket.pymvent71_cancelado = 0
    into :marca,
         :id_pymvent71,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_cantidad,
         :pymvent71_importe_unidad,
         :pymvent71_importe_neto
    do
    begin
        cantidad_cancelada = 0.00;
        importe_cancelado = 0.00;
        pymvent71_importe_unidad = pymvent71_importe_neto / pymvent71_cantidad;
        notas = '';

        select
        sum(pymvent73_mov_cancelados.pymvent73_cantidad),
        sum(pymvent73_mov_cancelados.pymvent73_importe)
        from pymvent73_mov_cancelados
        where pymvent73_mov_cancelados.rela_pymvent71 = :id_pymvent71
        into :suma_cantidad,
             :suma_importe;

        if (suma_cantidad is null) then
            suma_cantidad = 0;

        if (suma_importe is null) then
            suma_importe = 0;

        pymvent71_cantidad = pymvent71_cantidad - suma_cantidad;

        if (pymvent71_cantidad <> 0) then
        begin
            pymvent71_importe_neto = pymvent71_importe_neto - :suma_importe;
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT71_XRECUPERADO (
    RELA_PYMVENT70X BIGINT)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    RELA_SICINGR95 BIGINT,
    ID_PYMVENT71 BIGINT,
    PYMVENT71_ORDEN INTEGER,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_IMPUESTOS DOUBLE PRECISION,
    PYMVENT71_IMPORTE_NETO DOUBLE PRECISION,
    CANT_CANCELADA DOUBLE PRECISION,
    RELA_PYMVENT81 BIGINT)
AS
begin
    rela_pymvent81 = null;

    select pymvent81_det_factglobal.id_pymvent81
    from pymvent81_det_factglobal
    where pymvent81_det_factglobal.rela_pymvent70 = :rela_pymvent70x
    into :rela_pymvent81;

    if (rela_pymvent81 is null) then
        rela_pymvent81 = 0;

    for select
    PYMVENT71_DET_TICKET.rela_pymvent70,
    PYMVENT71_DET_TICKET.rela_sicingr95,
    PYMVENT71_DET_TICKET.id_pymvent71,
    PYMVENT71_DET_TICKET.pymvent71_orden,
    PYMVENT71_DET_TICKET.pymvent71_codigo,
    PYMVENT71_DET_TICKET.pymvent71_concepto,
    PYMVENT71_DET_TICKET.pymvent71_cantidad,
    PYMVENT71_DET_TICKET.pymvent71_importe_unidad,
    PYMVENT71_DET_TICKET.pymvent71_importe_subtotal,
    PYMVENT71_DET_TICKET.pymvent71_importe_descuento,
    PYMVENT71_DET_TICKET.pymvent71_importe_impuestos,
    PYMVENT71_DET_TICKET.pymvent71_importe_neto
    from PYMVENT71_DET_TICKET
    where PYMVENT71_DET_TICKET.RELA_PYMVENT70 = :rela_pymvent70x and PYMVENT71_CANCELADO = 0
    into :rela_pymvent70,
         :rela_sicingr95,
         :id_pymvent71,
         :pymvent71_orden,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_cantidad,
         :pymvent71_importe_unidad,
         :pymvent71_importe_subtotal,
         :pymvent71_importe_descuento,
         :pymvent71_importe_impuestos,
         :pymvent71_importe_neto
    do
    begin
        select
        sum(pymvent73_mov_cancelados.pymvent73_cantidad)
        from pymvent73_mov_cancelados
        where pymvent73_mov_cancelados.rela_pymvent71 = :id_pymvent71
        into :cant_cancelada;

        if (cant_cancelada is null) then
            cant_cancelada = 0;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_PYMVENT73 (
    RELA_PYMVENT70_INPUT BIGINT)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    RELA_SICINGR95 BIGINT,
    ID_PYMVENT71 BIGINT,
    PYMVENT71_ORDEN INTEGER,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_IMPUESTOS DOUBLE PRECISION,
    PYMVENT71_IMPORTE_NETO DOUBLE PRECISION,
    CANT_CANCELADA DOUBLE PRECISION)
AS
declare variable PORC double precision;
begin
   --Se copió buena parte de GRD_PYMVENT71_XRECUPERADO
    FOR select
        PYMVENT71_DET_TICKET.rela_pymvent70,
        PYMVENT71_DET_TICKET.rela_sicingr95,
        PYMVENT71_DET_TICKET.id_pymvent71,
        PYMVENT71_DET_TICKET.pymvent71_orden,
        PYMVENT71_DET_TICKET.pymvent71_codigo,
        PYMVENT71_DET_TICKET.pymvent71_concepto,
        sum(pymvent73_mov_cancelados.pymvent73_cantidad),
        PYMVENT71_DET_TICKET.pymvent71_cantidad,
        PYMVENT71_DET_TICKET.pymvent71_importe_unidad,
        PYMVENT71_DET_TICKET.pymvent71_importe_subtotal,
        PYMVENT71_DET_TICKET.pymvent71_importe_descuento,
        PYMVENT71_DET_TICKET.pymvent71_importe_impuestos,
        PYMVENT71_DET_TICKET.pymvent71_importe_neto
    from pymvent71_det_ticket
       inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
       inner join pymvent73_mov_cancelados on (pymvent73_mov_cancelados.rela_pymvent71 = pymvent71_det_ticket.id_pymvent71)
    where pymvent71_det_ticket.rela_pymvent70 = :RELA_PYMVENT70_INPUT
    GROUP BY  PYMVENT71_DET_TICKET.rela_pymvent70,
        PYMVENT71_DET_TICKET.rela_sicingr95,
        PYMVENT71_DET_TICKET.id_pymvent71,
        PYMVENT71_DET_TICKET.pymvent71_orden,
        PYMVENT71_DET_TICKET.pymvent71_codigo,
        PYMVENT71_DET_TICKET.pymvent71_concepto,
        pymvent73_mov_cancelados.pymvent73_cantidad,
        PYMVENT71_DET_TICKET.pymvent71_cantidad,
        PYMVENT71_DET_TICKET.pymvent71_importe_unidad,
        PYMVENT71_DET_TICKET.pymvent71_importe_subtotal,
        PYMVENT71_DET_TICKET.pymvent71_importe_descuento,
        PYMVENT71_DET_TICKET.pymvent71_importe_impuestos,
        PYMVENT71_DET_TICKET.pymvent71_importe_neto
    into :rela_pymvent70,
         :rela_sicingr95,
         :id_pymvent71,
         :pymvent71_orden,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :cant_cancelada,
         :pymvent71_cantidad,
         :pymvent71_importe_unidad,
         :pymvent71_importe_subtotal,
         :pymvent71_importe_descuento,
         :pymvent71_importe_impuestos,
         :pymvent71_importe_neto
    do
    begin
       porc =  cant_cancelada / pymvent71_cantidad;
      pymvent71_cantidad = cant_cancelada;   -- Se deja este nombre para que funcione en Java igual que con GRD_PYMVENT71_XRECUPERADO
      pymvent71_importe_subtotal = pymvent71_importe_subtotal * porc;
      pymvent71_importe_descuento =  pymvent71_importe_descuento * porc;
      pymvent71_importe_impuestos = pymvent71_importe_impuestos * porc;
      pymvent71_importe_neto = pymvent71_importe_neto  * porc;
      suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICCONT10_ERRORES (
    RELA_SOCMAIN01X BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCSYST10_CTP01 BIGINT,
    RELA_SOCSYST10_CTP02 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    ID_SICCONT10 BIGINT,
    SICCONT10_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT10_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_COTIZA DOUBLE PRECISION,
    SICCONT10_FAPL TIMESTAMP,
    ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_CTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    IMPORTE_ORIGINAL DOUBLE PRECISION,
    SICCONT10_ERROR_AJUSTE VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    AJUSTE DOUBLE PRECISION,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN_AUTOMATICO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ORIGEN_CODIGO varchar(50);
begin
    FOR SELECT
    SMX$SICCONT11_CORRECCION.id_siccont10
    FROM SMX$SICCONT11_CORRECCION(:rela_socmain01x)
    where SMX$SICCONT11_CORRECCION.status = 'Correccion a Mano'
    into :id_siccont10
    do
    begin
        FOR SELECT
        SICCONT10_CAB_POLIZAS.rela_socmain01,
        SICCONT10_CAB_POLIZAS.rela_socmain21,
        SICCONT10_CAB_POLIZAS.rela_socusua01,
        SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
        SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
        SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
        SICCONT10_CAB_POLIZAS.rela_socusua30,
        SICCONT10_CAB_POLIZAS.id_siccont10,
        SICCONT10_CAB_POLIZAS.siccont10_uuid_smx,
        SICCONT10_CAB_POLIZAS.siccont10_uuid_sat,
        SICCONT10_CAB_POLIZAS.siccont10_descripcion,
        SICCONT10_CAB_POLIZAS.siccont10_docnro,
        SICCONT10_CAB_POLIZAS.siccont10_fcta,
        SICCONT10_CAB_POLIZAS.siccont10_notas,
        SICCONT10_CAB_POLIZAS.siccont10_cotiza,
        SICCONT10_CAB_POLIZAS.siccont10_fapl,
        SICCONT10_CAB_POLIZAS.siccont10_error_ajuste,
        CTP01.socsyst10_codigo,
        CTP02.socsyst10_descripcion,
        CTM01.socsyst10_descripcion,
        ( SELECT SUM(siccont11_det_polizas.siccont11_debe)
        FROM siccont11_det_polizas
        WHERE siccont11_det_polizas.rela_siccont10 = SICCONT10_CAB_POLIZAS.id_siccont10
        ),
        CTP01.socsyst10_codigo,
        SICCONT10_CAB_POLIZAS.siccont10_origen
        from SICCONT10_CAB_POLIZAS
        inner join socsyst10_det_entradas CTP01 ON (CTP01.id_socsyst10 = SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01)
        inner join socsyst10_det_entradas CTP02 ON (CTP02.id_socsyst10 = SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02)
        inner join socsyst10_det_remoto CTM01 ON (CTM01.id_socsyst10 = SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01)
        where SICCONT10_CAB_POLIZAS.id_siccont10 = :id_siccont10
        into :rela_socmain01,
             :rela_socmain21,
             :rela_socusua01,
             :rela_socsyst10_ctp01,
             :rela_socsyst10_ctp02,
             :rela_socsyst10_ctm01,
             :rela_socusua30,
             :id_siccont10,
             :siccont10_uuid_smx,
             :siccont10_uuid_sat,
             :siccont10_descripcion,
             :siccont10_docnro,
             :siccont10_fcta,
             :siccont10_notas,
             :siccont10_cotiza,
             :siccont10_fapl,
             :siccont10_error_ajuste,
             :origen,
             :tipo_cta,
             :moneda,
             :importe,
             :origen_codigo,
             :origen_automatico
        do
        begin
            if ((origen_codigo = 'DROPZONE') or
                (origen_codigo = 'MANUAL') or
                (origen_codigo = 'DROPZONE-ANTI') or
                (origen_codigo = 'DROPZONE-ANTI-CLIENTE') or
                (origen_codigo = 'DROPZONE-ANTI-NOMI')  ) then
            begin
                importe_original = :importe;
            end
            else if (origen_codigo = 'DROPZONE-BANCOS') then
            begin
                select sicegre51_cab_bancos.sicegre51_importe
                from sicegre51_cab_bancos
                inner join sicegre50_det_ctacte on (sicegre51_cab_bancos.id_sicegre51 = sicegre50_det_ctacte.rela_sicegre51)
                where sicegre50_det_ctacte.rela_siccont10 = :id_siccont10
                into :importe_original;
            end
            else if (origen_codigo = 'DROPZONE-BANCOS-CLIENTE') then
            begin
                select sicingr51_cab_bancos.sicingr51_importe
                from sicingr51_cab_bancos
                inner join sicingr50_det_ctacte on (sicingr51_cab_bancos.id_sicingr51 = sicingr50_det_ctacte.rela_sicingr51)
                where sicingr50_det_ctacte.rela_siccont10 = :id_siccont10
                into :importe_original;
            end
            else if (origen_codigo = 'DROPZONE-REEMBOLSO') then
            begin
                importe_original = null;
    
                select sicegre50_det_ctacte.sicegre50_importe * -1
                from sicegre50_det_ctacte
                where sicegre50_det_ctacte.rela_siccont10 = :id_siccont10
                into :importe_original;
    
                if (importe_original is null) then
                   importe_original = :importe; 
    
            end
            else if (origen_codigo = 'DROPZONE-DEPOSITOS') then
            begin
                importe_original = null;
    
                select sicingr50_det_ctacte.sicingr50_importe * -1
                from sicingr50_det_ctacte
                where sicingr50_det_ctacte.rela_siccont10 = :id_siccont10
                into :importe_original;
    
                if (importe_original is null) then
                   importe_original = :importe; 
    
            end
            else if (origen_codigo = 'DROPZONE-BANCOS-NOMI') then
            begin
                select sicnomi51_cab_bancos.sicnomi51_importe
                from sicnomi51_cab_bancos
                inner join sicnomi50_det_ctacte on (sicnomi51_cab_bancos.id_sicnomi51 = sicnomi50_det_ctacte.rela_sicnomi51)
                where sicnomi50_det_ctacte.rela_siccont10 = :id_siccont10
                into :importe_original;
            end
            else if (origen_codigo = 'DROPZONE-PERIODO-NOMI') then
            begin
                importe_original = null;
    
                select sicnomi50_det_ctacte.sicnomi50_importe * -1
                from sicnomi50_det_ctacte
                where sicnomi50_det_ctacte.rela_siccont10 = :id_siccont10
                into :importe_original;
    
                if (importe_original is null) then
                   importe_original = :importe; 
            end
    
            ajuste = null;
    
            select sum(siccont11_det_polizas.siccont11_debe + siccont11_det_polizas.siccont11_haber)
            from socsyst10_det_entradas
            inner join sicxmls03_det_cuentas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
            inner join siccont02_arb_planctas on (sicxmls03_det_cuentas.rela_siccont02 = siccont02_arb_planctas.id_siccont02)
            inner join siccont11_det_polizas on (siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02)
            where siccont11_det_polizas.rela_siccont10 = :id_siccont10
            and socsyst10_det_entradas.socsyst10_codigo like '%AJUSTE%'
            into :ajuste;
    
            if (ajuste is null) then
                ajuste = 0;
    
            ENTIDAD = NULL;
            RFC = NULL;
    
            if (:rela_socusua30 IS NOT NULL) then
                SELECT
                cbo_socusua30.entidad,
                cbo_socusua30.rfc
                from cbo_socusua30(:rela_socusua30)
                into :entidad,
                     :rfc;
    
            SICCONT10_ERROR_AJUSTE = 'E';

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICCONT10_FILTRO (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X BIGINT,
    RELA_SOCSYST10_CTP01X BIGINT,
    FECHA_DESDEX DATE,
    FECHA_HASTAX DATE)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCSYST10_CTP01 BIGINT,
    RELA_SOCSYST10_CTP02 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    ID_SICCONT10 BIGINT,
    SICCONT10_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT10_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_COTIZA DOUBLE PRECISION,
    SICCONT10_FAPL TIMESTAMP,
    ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_CTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    IMPORTE_ORIGINAL DOUBLE PRECISION,
    SICCONT10_ERROR_AJUSTE VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    AJUSTE DOUBLE PRECISION,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN_AUTOMATICO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CONCILIADO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ORIGEN_CODIGO varchar(50);
declare variable ID_SICCONT51 bigint;
declare variable SICXMLS41_FORMAPAGO varchar(400);
declare variable SICXMLS41_METODODEPAGO varchar(400);
declare variable ID_BANCOS bigint;
begin
    FOR SELECT
    SICCONT10_CAB_POLIZAS.rela_socmain01,
    SICCONT10_CAB_POLIZAS.rela_socmain21,
    SICCONT10_CAB_POLIZAS.rela_socusua01,
    SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
    SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
    SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
    SICCONT10_CAB_POLIZAS.rela_socusua30,
    SICCONT10_CAB_POLIZAS.id_siccont10,
    SICCONT10_CAB_POLIZAS.siccont10_uuid_smx,
    SICCONT10_CAB_POLIZAS.siccont10_uuid_sat,
    SICCONT10_CAB_POLIZAS.siccont10_descripcion,
    SICCONT10_CAB_POLIZAS.siccont10_docnro,
    SICCONT10_CAB_POLIZAS.siccont10_fcta,
    SICCONT10_CAB_POLIZAS.siccont10_notas,
    SICCONT10_CAB_POLIZAS.siccont10_cotiza,
    SICCONT10_CAB_POLIZAS.siccont10_fapl,
    SICCONT10_CAB_POLIZAS.siccont10_error_ajuste,
    CTP01.socsyst10_codigo,
    CTP02.socsyst10_descripcion,
    CTM01.socsyst10_descripcion,
    ( SELECT SUM(siccont11_det_polizas.siccont11_debe)
    FROM siccont11_det_polizas
    WHERE siccont11_det_polizas.rela_siccont10 = SICCONT10_CAB_POLIZAS.id_siccont10
    ),
    CTP01.socsyst10_codigo,
    SICCONT10_CAB_POLIZAS.siccont10_origen
    from SICCONT10_CAB_POLIZAS
    inner join socsyst10_det_entradas CTP01 ON (CTP01.id_socsyst10 = SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01)
    inner join socsyst10_det_entradas CTP02 ON (CTP02.id_socsyst10 = SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02)
    inner join socsyst10_det_remoto CTM01 ON (CTM01.id_socsyst10 = SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01)
    where SICCONT10_CAB_POLIZAS.rela_socmain01 = :rela_socmain01x
    and SICCONT10_CAB_POLIZAS.rela_socmain21 = :rela_socmain21x
    and SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01 = :rela_socsyst10_ctp01x
    and SICCONT10_CAB_POLIZAS.siccont10_fcta between :fecha_desdex and :fecha_hastax
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :rela_socsyst10_ctp01,
         :rela_socsyst10_ctp02,
         :rela_socsyst10_ctm01,
         :rela_socusua30,
         :id_siccont10,
         :siccont10_uuid_smx,
         :siccont10_uuid_sat,
         :siccont10_descripcion,
         :siccont10_docnro,
         :siccont10_fcta,
         :siccont10_notas,
         :siccont10_cotiza,
         :siccont10_fapl,
         :siccont10_error_ajuste,
         :origen,
         :tipo_cta,
         :moneda,
         :importe,
         :origen_codigo,
         :origen_automatico
    do
    begin
        if ((origen_codigo = 'DROPZONE') or
            (origen_codigo = 'MANUAL') or
            (origen_codigo = 'DROPZONE-ANTI') or
            (origen_codigo = 'DROPZONE-ANTI-CLIENTE') or
            (origen_codigo = 'DROPZONE-ANTI-NOMI')  ) then
        begin
            importe_original = :importe;
        end
        else if (origen_codigo = 'DROPZONE-BANCOS') then
        begin
            select sicegre51_cab_bancos.sicegre51_importe
            from sicegre51_cab_bancos
            inner join sicegre50_det_ctacte on (sicegre51_cab_bancos.id_sicegre51 = sicegre50_det_ctacte.rela_sicegre51)
            where sicegre50_det_ctacte.rela_siccont10 = :id_siccont10
            into :importe_original;
        end
        else if (origen_codigo = 'DROPZONE-BANCOS-CLIENTE') then
        begin
            select sicingr51_cab_bancos.sicingr51_importe
            from sicingr51_cab_bancos
            inner join sicingr50_det_ctacte on (sicingr51_cab_bancos.id_sicingr51 = sicingr50_det_ctacte.rela_sicingr51)
            where sicingr50_det_ctacte.rela_siccont10 = :id_siccont10
            into :importe_original;
        end
        else if (origen_codigo = 'DROPZONE-REEMBOLSO') then
        begin
            importe_original = null;

            select sicegre50_det_ctacte.sicegre50_importe * -1
            from sicegre50_det_ctacte
            where sicegre50_det_ctacte.rela_siccont10 = :id_siccont10
            into :importe_original;

            if (importe_original is null) then
               importe_original = :importe; 

        end
        else if (origen_codigo = 'DROPZONE-DEPOSITOS') then
        begin
            importe_original = null;

            select sicingr50_det_ctacte.sicingr50_importe * -1
            from sicingr50_det_ctacte
            where sicingr50_det_ctacte.rela_siccont10 = :id_siccont10
            into :importe_original;

            if (importe_original is null) then
               importe_original = :importe; 

        end
        else if (origen_codigo = 'DROPZONE-BANCOS-NOMI') then
        begin
            select sicnomi51_cab_bancos.sicnomi51_importe
            from sicnomi51_cab_bancos
            inner join sicnomi50_det_ctacte on (sicnomi51_cab_bancos.id_sicnomi51 = sicnomi50_det_ctacte.rela_sicnomi51)
            where sicnomi50_det_ctacte.rela_siccont10 = :id_siccont10
            into :importe_original;
        end
        else if (origen_codigo = 'DROPZONE-PERIODO-NOMI') then
        begin
            importe_original = null;

            select sicnomi50_det_ctacte.sicnomi50_importe * -1
            from sicnomi50_det_ctacte
            where sicnomi50_det_ctacte.rela_siccont10 = :id_siccont10
            into :importe_original;

            if (importe_original is null) then
               importe_original = :importe; 
        end

        ajuste = null;

        select sum(siccont11_det_polizas.siccont11_debe + siccont11_det_polizas.siccont11_haber)
        from socsyst10_det_entradas
        inner join sicxmls03_det_cuentas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        inner join siccont02_arb_planctas on (sicxmls03_det_cuentas.rela_siccont02 = siccont02_arb_planctas.id_siccont02)
        inner join siccont11_det_polizas on (siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02)
        where siccont11_det_polizas.rela_siccont10 = :id_siccont10
        and socsyst10_det_entradas.socsyst10_codigo like '%AJUSTE%'
        into :ajuste;

        if (ajuste is null) then
            ajuste = 0;

        ENTIDAD = NULL;
        RFC = NULL;
        id_siccont51 = NULL;

        if (:rela_socusua30 IS NOT NULL) then
            SELECT
            cbo_socusua30.entidad,
            cbo_socusua30.rfc
            from cbo_socusua30(:rela_socusua30)
            into :entidad,
                 :rfc;

        if (siccont10_docnro = '000571') then
              siccont10_docnro = '000571';

        --HV
        select SICCONT51_DET_BANCOS.id_siccont51
        from SICCONT51_DET_BANCOS
        where SICCONT51_DET_BANCOS.rela_siccont10 = :id_siccont10
        into :id_siccont51;

        if (:id_siccont51 IS NOT NULL) then
             conciliado = 'Si';
        else
        BEGIN
            id_bancos = null;
            conciliado = 'No';

            select first 1 VW_CTACTES_SICCONT10.id_ctactes
            from VW_CTACTES_SICCONT10
            where VW_CTACTES_SICCONT10.rela_siccont10 = :id_siccont10
            into :id_bancos;

            if (id_bancos is not null) then
                conciliado = 'Si';
        END

        CRP = '';

        select sicxmls41_det_migracion.sicxmls41_formapago,
        sicxmls41_det_migracion.sicxmls41_metododepago
        from sicxmls41_det_migracion
        inner join siccont10_cab_polizas on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
        where siccont10_cab_polizas.id_siccont10 =  :id_siccont10
        into :sicxmls41_formapago,
             :sicxmls41_metododepago;

        if (origen_codigo = 'DROPZONE')  then
        begin
            if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
                CRP = 'Si';
            else
                CRP = 'No';
        end
        -- Hasta aqui
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE50 (
    ID_SOCMAIN01 BIGINT,
    ID_SICEGRE01 BIGINT)
RETURNS (
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICEGRE01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    SICEGRE50_IMPORTE DOUBLE PRECISION,
    ULT_FECHA DATE,
    SICEGRE01_DIASCREDITO INTEGER,
    SICEGRE01_CREDITO DOUBLE PRECISION,
    RELA_SOCMAIN05 BIGINT,
    RELA_SOCSYST10_BAN01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICEGRE51 BIGINT,
    SICEGRE51_CUENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE51_FECHA DATE,
    SICEGRE51_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE51_FAPL TIMESTAMP,
    IMPORTE_OTRASMONEDAS DOUBLE PRECISION,
    COTIZA_PROMEDIO DOUBLE PRECISION)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable CUENTA_COTIZA integer;
declare variable SUMA_COTIZA double precision;
declare variable IMPORTE_OTRASMONEDAS_PAGADAS double precision;
declare variable CONTADOR_ID bigint;
declare variable SQL_C varchar(1500);
declare variable COUNT_ENTIDAD integer;
begin
    CONTADOR_ID = 100000;

    select count(sicegre01_cab_proveedores.id_sicegre01)
    from sicegre01_cab_proveedores
    where sicegre01_cab_proveedores.rela_socmain01 = :id_socmain01
    into :count_entidad;

    if (count_entidad < 100) then
        id_sicegre01 = null;

    if (id_sicegre01 is not null and id_sicegre01 > 0) then
    begin
        sql_c = 'Select
                sicegre01_cab_proveedores.rela_socusua30,
                sicegre01_cab_proveedores.sicegre01_diascredito,
                sicegre01_cab_proveedores.sicegre01_credito,
                SICEGRE50_DET_CTACTE.rela_sicegre01,
                SICEGRE50_DET_CTACTE.rela_socmain01,
                sum(SICEGRE50_DET_CTACTE.sicegre50_importe),
                max(SICEGRE50_DET_CTACTE.sicegre50_fapl)
                from SICEGRE50_DET_CTACTE
                inner join sicegre01_cab_proveedores on (sicegre01_cab_proveedores.id_sicegre01 = SICEGRE50_DET_CTACTE.rela_sicegre01)
                where SICEGRE50_DET_CTACTE.rela_socmain01 = ' || :id_socmain01 ||
                ' and sicegre01_cab_proveedores.id_sicegre01 = ' || :id_sicegre01 ||
                ' and SICEGRE50_DET_CTACTE.rela_sicegre01 = ' || :id_sicegre01 ||
                ' group by
                sicegre01_cab_proveedores.rela_socusua30,
                sicegre01_cab_proveedores.sicegre01_diascredito,
                sicegre01_cab_proveedores.sicegre01_credito,
                SICEGRE50_DET_CTACTE.rela_sicegre01,
                SICEGRE50_DET_CTACTE.rela_socmain01';
    end
    else
    begin
        sql_c = 'Select
                sicegre01_cab_proveedores.rela_socusua30,
                sicegre01_cab_proveedores.sicegre01_diascredito,
                sicegre01_cab_proveedores.sicegre01_credito,
                SICEGRE50_DET_CTACTE.rela_sicegre01,
                SICEGRE50_DET_CTACTE.rela_socmain01,
                sum(SICEGRE50_DET_CTACTE.sicegre50_importe),
                max(SICEGRE50_DET_CTACTE.sicegre50_fapl)
                from SICEGRE50_DET_CTACTE
                inner join sicegre01_cab_proveedores on (sicegre01_cab_proveedores.id_sicegre01 = SICEGRE50_DET_CTACTE.rela_sicegre01)
                where SICEGRE50_DET_CTACTE.rela_socmain01 = ' || :id_socmain01 ||
                ' group by
                sicegre01_cab_proveedores.rela_socusua30,
                sicegre01_cab_proveedores.sicegre01_diascredito,
                sicegre01_cab_proveedores.sicegre01_credito,
                SICEGRE50_DET_CTACTE.rela_sicegre01,
                SICEGRE50_DET_CTACTE.rela_socmain01';
    end

    for execute statement :sql_c
    into :rela_socusua30,
         :sicegre01_diascredito,
         :sicegre01_credito,
         :rela_sicegre01,
         :rela_socmain01,
         :sicegre50_importe,
         :ult_fecha
    do
    begin
        select
        cbo_socusua30.tipo,
        cbo_socusua30.entidad,
        cbo_socusua30.rfc
        from cbo_socusua30(:rela_socusua30)
        into :tipo,
             :entidad,
             :rfc;

        /* --------------------------------------------------------------- */
        /* ----- aqui tomo sumas que vengan desde otras monedas ---------- */
        /* --------------------------------------------------------------- */

        importe_otrasmonedas = null;

        /* aquí recupero los pagos con cambio diferente de 1 para restrlo al total de xml con cmbio diferente de 1 */
        select
        sum(sicegre52_det_bancos.sicegre52_importe)
        from sicxmls41_det_migracion
        inner join siccont10_cab_polizas on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
        inner join sicegre50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
        inner join sicegre52_det_bancos on (sicegre50_det_ctacte.id_sicegre50 = sicegre52_det_bancos.rela_sicegre50)
        where siccont10_cab_polizas.rela_socusua30 = :rela_socusua30
        and sicxmls41_det_migracion.sicxmls41_cambio <> 1
        into :importe_otrasmonedas_pagadas;

        if (importe_otrasmonedas_pagadas is null) then
            importe_otrasmonedas_pagadas = 0;

        /* --------------------------------------------------------------- */

        select
        count(sicxmls41_det_migracion.id_sicxmls41),
        sum(siccont10_cab_polizas.siccont10_cotiza),
        sum(sicxmls41_det_migracion.sicxmls41_uuid_importe)
        from siccont10_cab_polizas
        inner join sicegre50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
        inner join sicxmls41_det_migracion on (siccont10_cab_polizas.id_siccont10 = sicxmls41_det_migracion.rela_siccont10)
        where siccont10_cab_polizas.rela_socusua30 = :rela_socusua30
        and siccont10_cab_polizas.siccont10_cotiza <> 1
        into :cuenta_cotiza,
             :suma_cotiza,
             :importe_otrasmonedas;

        if (importe_otrasmonedas is null) then
        begin
            importe_otrasmonedas = 0;
            cotiza_promedio = 1;
        end
        else
        begin
            cotiza_promedio = suma_cotiza / cuenta_cotiza;
            importe_otrasmonedas = importe_otrasmonedas * cotiza_promedio;
            importe_otrasmonedas = importe_otrasmonedas - :importe_otrasmonedas_pagadas;
        end

        /* --------------------------------------------------------------- */
        /* --------------------------------------------------------------- */
        /* --------------------------------------------------------------- */

        id_sicegre51 = null;

        select max(sicegre51_cab_bancos.id_sicegre51)
        from sicegre51_cab_bancos
        where sicegre51_cab_bancos.rela_sicegre01 = :rela_sicegre01
        into :id_sicegre51;

        if (id_sicegre51 is null) then
        begin
            contador_id = contador_id + 1;
            id_sicegre51 = :contador_id;
        end

        suspend;
    end

end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE50_DET (
    ID_SOCMAIN01 BIGINT,
    ID_SICEGRE01 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICCONT10 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SICEGRE01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SICEGRE51 BIGINT,
    ID_SICEGRE50 BIGINT,
    SICEGRE50_IMPORTE DOUBLE PRECISION,
    SICEGRE50_FAPL TIMESTAMP,
    IMPORTE_XPAGAR DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCSYST10_CTM01 BIGINT)
AS
declare variable SUMA_SALDO double precision;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICXMLS41 bigint;
begin
    for select
    socsyst10_det_entradas.socsyst10_codigo,
    siccont10_cab_polizas.id_siccont10,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_fcta,
    SICEGRE50_DET_CTACTE.rela_sicegre01,
    SICEGRE50_DET_CTACTE.rela_socmain01,
    SICEGRE50_DET_CTACTE.rela_siccont10,
    SICEGRE50_DET_CTACTE.rela_sicegre51,
    SICEGRE50_DET_CTACTE.id_sicegre50,
    SICEGRE50_DET_CTACTE.sicegre50_importe,
    SICEGRE50_DET_CTACTE.sicegre50_fapl,
    siccont10_cab_polizas.siccont10_cotiza,
    moneda.socsyst10_descripcion,
    siccont10_cab_polizas.rela_socsyst10_ctm01
    FROM SICEGRE50_DET_CTACTE
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = SICEGRE50_DET_CTACTE.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    inner join socsyst10_det_remoto moneda on (moneda.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctm01)
    where SICEGRE50_DET_CTACTE.rela_socmain01 = :id_socmain01
    and SICEGRE50_DET_CTACTE.rela_sicegre01 = :id_sicegre01
    and not exists (select first 1 SICEGRE50_DET_CTACTE.id_sicegre50
                    from sicegre61_det_rendicion
                    where sicegre61_det_rendicion.rela_sicegre50 = SICEGRE50_DET_CTACTE.id_sicegre50)

    into :socsyst10_codigo,
         :id_siccont10,
         :SICCONT10_DOCNRO,
         :SICCONT10_UUID_SAT,
         :SICCONT10_FCTA,
         :RELA_SICEGRE01,
         :RELA_SOCMAIN01,
         :RELA_SICCONT10,
         :RELA_SICEGRE51,
         :ID_SICEGRE50,
         :SICEGRE50_IMPORTE,
         :SICEGRE50_FAPL,
         :cotiza,
         :moneda,
         :rela_socsyst10_ctm01
    do
    begin
        marca = 0;
        importe_xpagar = 0.0;
        suma_saldo = 0.0;
        sicxmls41_folio = null;
        id_sicxmls41 = null;

        select sum(sicegre52_det_bancos.sicegre52_importe)
        from sicegre52_det_bancos
        where sicegre52_det_bancos.rela_sicegre50 = :ID_SICEGRE50
        into :suma_saldo;

        if (suma_saldo is null) then
            suma_saldo = 0;

        sicegre50_importe = sicegre50_importe - suma_saldo;

        if (cast(sicegre50_importe as numeric(18,4)) <> 0 and SICCONT10_UUID_SAT is not null) then
        begin
            select
            sicxmls41_det_migracion.id_sicxmls41,
            sicxmls41_det_migracion.sicxmls41_folio,
              sicxmls41_det_migracion.sicxmls41_formapago,
            sicxmls41_det_migracion.sicxmls41_metododepago
            from sicxmls41_det_migracion
            where sicxmls41_det_migracion.rela_siccont10 = :RELA_SICCONT10
            into :id_sicxmls41,
                 :sicxmls41_folio,
                 :sicxmls41_formapago,
                 :sicxmls41_metododepago;

            if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
                CRP = 'Si';
            else
                CRP = 'No';

            if (id_sicxmls41 is not null) then
            begin
                suspend;
            end
        end
        else if (cast(sicegre50_importe as numeric(18,4)) <> 0) then
        begin
            if (socsyst10_codigo = 'DROPZONE-ANTI') then
            begin
                SICXMLS41_FOLIO = :siccont10_docnro;
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE50_MOV (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICEGRE01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SICCONT10 BIGINT,
    RELA_SICEGRE51 BIGINT,
    ID_SICEGRE50 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EJECUTADO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_REF VARCHAR(5000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS_REF INTEGER,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    FECHA DATE,
    UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICEGRE61FIND bigint;
declare variable REFERENCIA_POLIZA varchar(50);
declare variable RELA_SICEGRE51_CREDITO bigint;
declare variable FECHA_REF date;
begin
    FOR select
    socsyst10_det_entradas.socsyst10_codigo,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_fcta,
    SICEGRE50_DET_CTACTE.rela_siccont10,
    SICEGRE50_DET_CTACTE.rela_sicegre51,
    SICEGRE50_DET_CTACTE.id_sicegre50,
    SICEGRE50_DET_CTACTE.sicegre50_importe,
    siccont10_cab_polizas.siccont10_cotiza,
    moneda.socsyst10_descripcion
    FROM SICEGRE50_DET_CTACTE
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = SICEGRE50_DET_CTACTE.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    inner join socsyst10_det_remoto moneda on (moneda.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctm01)
    where SICEGRE50_DET_CTACTE.rela_socmain01 = :rela_socmain01
    and SICEGRE50_DET_CTACTE.rela_sicegre01 = :rela_sicegre01
    and siccont10_cab_polizas.siccont10_fcta between :fecha_desde and :fecha_hasta
    order  by siccont10_cab_polizas.siccont10_fcta
    INTO :SOCSYST10_CODIGO,
         :POLIZA,
         :UUID_SAT,
         :FECHA,
         :RELA_SICCONT10,
         :rela_sicegre51,
         :id_sicegre50,
         :importe_xml,
         :cotiza,
         :moneda
    DO
    BEGIN
        folio = null;
        sicxmls41_metododepago = '';
        sicxmls41_formapago = '';
        CRP = '';
        siccont10_docnro_ref = null;
        dias_ref = 0;

        select SICXMLS41_DET_MIGRACION.sicxmls41_folio,
             SICXMLS41_DET_MIGRACION.sicxmls41_metododepago,
             SICXMLS41_DET_MIGRACION.sicxmls41_formapago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
        :sicxmls41_metododepago,
        :sicxmls41_formapago;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
         else
           CRP = 'No';

        select
        sum(sicegre52_det_bancos.sicegre52_importe)
        from sicegre52_det_bancos
        where sicegre52_det_bancos.rela_sicegre50 = :ID_SICEGRE50
        into :importe_banco;

        if (importe_banco is null) then
            importe_banco = 0;

        importe_saldo = importe_xml - importe_banco;
        importe_saldo = cast(importe_saldo as numeric(18,4));

        ejecutado = 0;

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */

        if (SOCSYST10_CODIGO = 'DROPZONE') then
        begin
            if (importe_xml > 0) then
                STATUS = 'Factura Recibida';
            else
                STATUS = 'Crédito a Favor';

            importe_xml = iif(importe_xml is null, 0.00, importe_xml);
            if (importe_xml <> 0) then
                ejecutado = (importe_banco / importe_xml * 100);

            if (ejecutado = 0) then
            begin
                ejecutado = 0.0;
                id_sicegre61find = null;

                select first 1
                sicegre61_det_rendicion.id_sicegre61,
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta
                from sicegre61_det_rendicion
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre61_det_rendicion.rela_siccont10 )
                where sicegre61_det_rendicion.rela_sicegre50 = :id_sicegre50
                into :id_sicegre61find,
                     :siccont10_docnro_ref,
                     :fecha_ref;

                if (id_sicegre61find is not null) then
                BEGIN
                   ejecutado = 100;
                   importe_banco = :importe_xml;
                   importe_saldo = 0;
                   dias_ref = datediff(DAY FROM :fecha TO :fecha_ref);
                END
            end
            else
            if (STATUS = 'Factura Recibida') then
            begin
                for select
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta
                from sicegre52_det_bancos
                inner join sicegre51_cab_bancos on ( sicegre51_cab_bancos.id_sicegre51 = sicegre52_det_bancos.rela_sicegre51 )
                inner join sicegre50_det_ctacte on ( sicegre51_cab_bancos.id_sicegre51 = sicegre50_det_ctacte.rela_sicegre51 )
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10 )
                where sicegre52_det_bancos.rela_sicegre50 = :ID_SICEGRE50
                order by siccont10_cab_polizas.siccont10_docnro
                into :referencia_poliza,
                     :fecha_ref
                do
                begin
                    siccont10_docnro_ref = iif(siccont10_docnro_ref is null, '', siccont10_docnro_ref);
                    siccont10_docnro_ref = siccont10_docnro_ref || trim(referencia_poliza) || '/';
                end

                if ( siccont10_docnro_ref is not null ) then
                begin
                    siccont10_docnro_ref = SUBSTRING (siccont10_docnro_ref FROM 1 FOR CHAR_LENGTH (siccont10_docnro_ref) - 1);
                    dias_ref = datediff(DAY FROM :fecha TO :fecha_ref);
                end
            end
            else
            begin
                select first 1 sicegre52_det_bancos.rela_sicegre51
                from sicegre52_det_bancos
                where sicegre52_det_bancos.rela_sicegre50 = :ID_SICEGRE50
                into :rela_sicegre51_credito;

                Select
                max(siccont10_cab_polizas.siccont10_docnro),
                max(siccont10_cab_polizas.siccont10_fcta)
                from sicegre52_det_bancos
                inner join sicegre50_det_ctacte on ( sicegre50_det_ctacte.id_sicegre50 = sicegre52_det_bancos.rela_sicegre50 )
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10 )
                where sicegre52_det_bancos.rela_sicegre51 = :rela_sicegre51_credito
                and sicegre52_det_bancos.sicegre52_importe > 0
                into :siccont10_docnro_ref,
                     :fecha_ref;

                dias_ref = datediff(DAY FROM :fecha TO :fecha_ref);
            end
        end

        else
        BEGIN
            CRP = '';
            if (SOCSYST10_CODIGO = 'DROPZONE-ANTI') then
            begin
                STATUS = 'Anticipo';
            end
    
            else if (SOCSYST10_CODIGO = 'DROPZONE-BANCOS') then
            begin
                STATUS = 'Pago';
                ejecutado = 100;
                importe_saldo = 0;
                importe_banco = importe_xml;
            end
    
            else if (SOCSYST10_CODIGO = 'DROPZONE-REEMBOLSO') then
            begin
                STATUS = 'Reembolso por Rendición';
                ejecutado = 100;
                importe_saldo = 0;
                importe_banco = importe_xml;
            end
            else
            begin
                STATUS = :SOCSYST10_CODIGO;
            end
        END

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */

        if (ejecutado <> 0) then
        begin
            select
            BAN01.socsyst10_descripcion,
            CTM01.socsyst10_descripcion,
            sicegre51_cab_bancos.sicegre51_cuenta
            from sicegre51_cab_bancos
            inner join socmain05_det_bancos on ( socmain05_det_bancos.id_socmain05 = sicegre51_cab_bancos.rela_socmain05 )
            inner join socsyst10_det_entradas BAN01 ON (BAN01.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ban01 )
            inner join socsyst10_det_remoto CTM01 ON (CTM01.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ctm01 )
            where sicegre51_cab_bancos.id_sicegre51 = :RELA_SICEGRE51
            INTO :banco_emp,
                 :moneda_emp,
                 :cuenta_emp;

            if (banco_emp is null) then
                banco_emp = 'N/A';

            if (moneda_emp is null) then
                moneda_emp = 'N/A';

            if (cuenta_emp is null) then
                cuenta_emp = 'N/A';

        end

        suspend;
    end

end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE50_MOV_DET (
    RELA_SICEGRE51 BIGINT,
    RELA_SICEGRE50 BIGINT)
RETURNS (
    ID_SICEGRE52 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICCONT10 BIGINT,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    /*
        el rela_sicegre51 lo utilizo para buscar en los pagados a cuales xml he pagado
        el rela_sicegre50 lo utilizo para buscar en los xmls ya ejecutados con que movimientos de banco los pague
    */

    if (rela_sicegre51 is not null) then
    begin
        for select
        sicegre52_det_bancos.id_sicegre52,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont10_cab_polizas.siccont10_uuid_sat,
        sicegre50_det_ctacte.sicegre50_importe,
        SICEGRE50_DET_CTACTE.rela_siccont10,
        sicegre52_det_bancos.sicegre52_importe
        from sicegre52_det_bancos
        inner join sicegre50_det_ctacte on (sicegre52_det_bancos.rela_sicegre50 = sicegre50_det_ctacte.id_sicegre50)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
        where sicegre52_det_bancos.rela_sicegre51 = :rela_sicegre51
        order by siccont10_cab_polizas.siccont10_fcta
        into :id_sicegre52,
             :siccont10_docnro,
             :siccont10_fcta,
             :siccont10_uuid_sat,
             :rela_siccont10,
             :importe_xml,
             :importe_pago
        do
        begin

            folio = null;

            select SICXMLS41_DET_MIGRACION.sicxmls41_folio
            from SICXMLS41_DET_MIGRACION
            where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
            into :folio;

            if (importe_xml < 0) then
            begin
                status = 'Crédito a Favor';
                if (siccont10_uuid_sat is null or trim(siccont10_uuid_sat) = '' ) then
                    STATUS = 'Anticipo';
            end
            else
                status = 'Factura Recibida';

            saldo = :importe_xml - :importe_pago;
            suspend;
        end
    end

    if (rela_sicegre50 is not null) then
    begin
        importe_xml = 0;
        saldo = 0;

        for select
        sicegre52_det_bancos.rela_sicegre51,
        sicegre52_det_bancos.id_sicegre52,
        sicegre52_det_bancos.sicegre52_importe
        from sicegre52_det_bancos
        where sicegre52_det_bancos.rela_sicegre50 = :rela_sicegre50
        into :rela_sicegre51,
             :id_sicegre52,
             :importe_pago
        do
        begin
            select
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta,
            siccont10_cab_polizas.siccont10_uuid_sat
            from sicegre50_det_ctacte
            inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
            where sicegre50_det_ctacte.rela_sicegre51 = :rela_sicegre51
            into :siccont10_docnro,
                 :siccont10_fcta,
                 :siccont10_uuid_sat;

            if (siccont10_docnro is null) then
            begin
                STATUS = 'Crédito a Favor';

                select
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta,
                siccont10_cab_polizas.siccont10_uuid_sat
                from sicegre50_det_ctacte
                inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
                where sicegre50_det_ctacte.id_sicegre50 = :rela_sicegre50
                into :siccont10_docnro,
                     :siccont10_fcta,
                     :siccont10_uuid_sat;

            end
            else
            begin
               STATUS = 'Pago';
            end

            suspend;
        end     
    end


end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE50_RENDICION (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICEGRE50 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_REND VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICEGRE50_IMPORTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XPAGAR DOUBLE PRECISION,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICCONT10 bigint;
begin
    for select
    sicegre50_det_ctacte.rela_siccont10,
    sicegre50_det_ctacte.id_sicegre50,
    cbo_sicegre01.entidad,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicegre50_det_ctacte.sicegre50_importe,
    siccont10_cab_polizas.siccont10_uuid_sat
    from sicegre50_det_ctacte
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
    inner join sicegre01_cab_proveedores on (sicegre01_cab_proveedores.id_sicegre01 = sicegre50_det_ctacte.rela_sicegre01)
    inner join cbo_sicegre01 on (cbo_sicegre01.id_socusua30 = sicegre01_cab_proveedores.rela_socusua30)
    where sicegre50_det_ctacte.rela_socmain01 = :rela_socmain01
    and siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
    and cbo_sicegre01.rela_socmain01 = :rela_socmain01
    and siccont10_cab_polizas.siccont10_uuid_sat is not null
    and sicegre50_det_ctacte.sicegre50_importe > 0
    and siccont10_cab_polizas.siccont10_cotiza = 1

    and not exists (select first 1 sicegre52_det_bancos.id_sicegre52
                    from sicegre52_det_bancos
                    where sicegre52_det_bancos.rela_sicegre50 = sicegre50_det_ctacte.id_sicegre50
                    )
    and not exists (select first 1 sicegre61_det_rendicion.id_sicegre61
                    from sicegre61_det_rendicion
                    where sicegre61_det_rendicion.rela_sicegre50 = sicegre50_det_ctacte.id_sicegre50
                    )
    into :rela_siccont10,
         :id_sicegre50,
         :entidad,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicegre50_importe,
         :SICCONT10_UUID_SAT
    do
    begin
        marca = 0;
        IMPORTE_XPAGAR = 0.0;
        CRP = '';

        select
        SICXMLS41_DET_MIGRACION.sicxmls41_folio,
        SICXMLS41_DET_MIGRACION.sicxmls41_metododepago,
        SICXMLS41_DET_MIGRACION.sicxmls41_formapago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
             :sicxmls41_metododepago,
             :sicxmls41_formapago;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
         else
           CRP = 'No';

        select first 1 siccont11_det_polizas.siccont11_referencia
        from siccont11_det_polizas
        inner join siccont12_mov_dropzone on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
        and siccont12_mov_dropzone.rela_sicxmls04 is not null
        into :siccont11_referencia;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE50_RENDICION_VIEW (
    RELA_SICEGRE60 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICEGRE50 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_REND VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICEGRE50_IMPORTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XPAGAR DOUBLE PRECISION,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICCONT10 bigint;
begin
    for select
    sicegre50_det_ctacte.rela_siccont10,
    sicegre50_det_ctacte.id_sicegre50,
    cbo_sicegre01.entidad,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicegre50_det_ctacte.sicegre50_importe,
    siccont10_cab_polizas.siccont10_uuid_sat,
    REND.siccont10_docnro
    from sicegre01_cab_proveedores
    inner join sicegre50_det_ctacte on (sicegre01_cab_proveedores.id_sicegre01 = sicegre50_det_ctacte.rela_sicegre01)
    inner join sicegre61_det_rendicion on (sicegre50_det_ctacte.id_sicegre50 = sicegre61_det_rendicion.rela_sicegre50)
    inner join sicegre60_cab_rendicion on (sicegre61_det_rendicion.rela_sicegre60 = sicegre60_cab_rendicion.id_sicegre60)
    inner join siccont10_cab_polizas rend on (sicegre61_det_rendicion.rela_siccont10 = rend.id_siccont10)
    inner join siccont10_cab_polizas on (sicegre50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
    inner join cbo_sicegre01 on (sicegre01_cab_proveedores.id_sicegre01 = cbo_sicegre01.rela_sicegre01)
    where sicegre60_cab_rendicion.id_sicegre60 = :RELA_SICEGRE60
    into :rela_siccont10,
         :id_sicegre50,
         :entidad,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicegre50_importe,
         :SICCONT10_UUID_SAT,
         :siccont10_docnro_rend
    do
    begin
        marca = 1;
        IMPORTE_XPAGAR = sicegre50_importe;
        CRP = '';

        select
        SICXMLS41_DET_MIGRACION.sicxmls41_folio,
        SICXMLS41_DET_MIGRACION.sicxmls41_metododepago,
        SICXMLS41_DET_MIGRACION.sicxmls41_formapago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
             :sicxmls41_metododepago,
             :sicxmls41_formapago;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
         else
           CRP = 'No';

        select first 1 siccont11_det_polizas.siccont11_referencia
        from siccont11_det_polizas
        inner join siccont12_mov_dropzone on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
        and siccont12_mov_dropzone.rela_sicxmls04 is not null
        into :siccont11_referencia;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE60 (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    EMPLEADO VARCHAR(1210) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_AJUSTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICNOMI01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    ID_SICEGRE60 BIGINT,
    SICEGRE60_IMPORTE DOUBLE PRECISION,
    SICEGRE60_FAPL TIMESTAMP,
    IMPORTE_RENDICION DOUBLE PRECISION,
    SICEGRE60_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    AJUSTE DOUBLE PRECISION,
    BANCO_CUENTA VARCHAR(1250) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICCONT10_AJUSTE bigint;
begin
    FOR select
    trim(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_pat) || ' ' ||
    trim(SOCUSUA30_CAB_ENTIDADES.socusua30_apellido_mat) || ', ' ||
    trim(SOCUSUA30_CAB_ENTIDADES.socusua30_nombre_razsoc),
    SICCONT10_CAB_POLIZAS.siccont10_docnro,
    SICCONT10_CAB_POLIZAS.siccont10_fcta,
    SICEGRE60_CAB_RENDICION.rela_socmain01,
    SICEGRE60_CAB_RENDICION.rela_socmain21,
    SICEGRE60_CAB_RENDICION.rela_socusua01,
    SICEGRE60_CAB_RENDICION.rela_sicnomi01,
    SICEGRE60_CAB_RENDICION.rela_siccont10,
    SICEGRE60_CAB_RENDICION.rela_siccont10_ajuste,
    SICEGRE60_CAB_RENDICION.rela_socmain05,
    SICEGRE60_CAB_RENDICION.id_sicegre60,
    SICEGRE60_CAB_RENDICION.sicegre60_importe,
    SICEGRE60_CAB_RENDICION.sicegre60_descripcion,
    SICEGRE60_CAB_RENDICION.sicegre60_fapl,
    (SELECT sum(sicegre50_det_ctacte.sicegre50_importe)
     FROM sicegre61_det_rendicion
     INNER join sicegre50_det_ctacte ON (sicegre50_det_ctacte.id_sicegre50 = sicegre61_det_rendicion.rela_sicegre50)
     WHERE sicegre61_det_rendicion.rela_sicegre60 = SICEGRE60_CAB_RENDICION.id_sicegre60
    )
    from SICEGRE60_CAB_RENDICION
    INNER JOIN SICCONT10_CAB_POLIZAS ON (SICCONT10_CAB_POLIZAS.ID_SICCONT10 = SICEGRE60_CAB_RENDICION.rela_siccont10)
    INNER JOIN SICNOMI01_CAB_EMPLEADOS ON (SICNOMI01_CAB_EMPLEADOS.ID_SICNOMI01 = SICEGRE60_CAB_RENDICION.rela_sicnomi01)
    INNER JOIN SOCUSUA30_CAB_ENTIDADES ON (SOCUSUA30_CAB_ENTIDADES.ID_SOCUSUA30 = SICNOMI01_CAB_EMPLEADOS.rela_socusua30)
    WHERE SICEGRE60_CAB_RENDICION.rela_socmain01 = :rela_socmain01x
    and SICEGRE60_CAB_RENDICION.rela_socmain21 = :RELA_SOCMAIN21X
    AND  SICCONT10_CAB_POLIZAS.siccont10_fcta between :fecha_desde and :fecha_hasta
    INTO :EMPLEADO,
         :SICCONT10_DOCNRO,
         :SICCONT10_FCTA,
         :RELA_SOCMAIN01,
         :RELA_SOCMAIN21,
         :RELA_SOCUSUA01,
         :RELA_SICNOMI01,
         :RELA_SICCONT10,
         :rela_siccont10_ajuste,
         :rela_socmain05,
         :ID_SICEGRE60,
         :SICEGRE60_IMPORTE,
         :sicegre60_descripcion,
         :SICEGRE60_FAPL,
         :IMPORTE_RENDICION
    DO
    BEGIN
        AJUSTE = SICEGRE60_IMPORTE - IMPORTE_RENDICION;
        Select GRD_SOCMAIN05.ve
        from GRD_SOCMAIN05
        WHERE GRD_SOCMAIN05.id_socmain05 = :rela_socmain05
        into :banco_cuenta;

        if (rela_siccont10_ajuste is not null) then
            select siccont10_cab_polizas.siccont10_docnro
            from siccont10_cab_polizas
            where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_ajuste
            into :siccont10_docnro_ajuste;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICEGRE80 (
    P_RELA_SOCMAIN01 BIGINT,
    P_RELA_SOCMAIN21 BIGINT,
    P_RELA_SICEGRE01 BIGINT,
    P_FECHA_DESDE DATE,
    P_FECHA_HASTA DATE,
    P_CERRADO INTEGER)
RETURNS (
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICEGRE01 BIGINT,
    ID_SICEGRE80 BIGINT,
    PROVEEDOR VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE80_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICEGRE80_FECHA DATE,
    SICEGRE80_FECHA_ENTREGA DATE,
    SICEGRE80_FECHA_CIERRE DATE,
    SICEGRE80_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable STR_SQL varchar(4000);
begin
    
    str_sql = 'select
        sicegre80_cab_ordcompra.rela_socusua01,
        sicegre80_cab_ordcompra.rela_socmain01,
        sicegre80_cab_ordcompra.rela_socmain21,
        sicegre80_cab_ordcompra.rela_sicegre01,
        sicegre80_cab_ordcompra.id_sicegre80,
        sicegre80_cab_ordcompra.sicegre80_docnro,
        sicegre80_cab_ordcompra.sicegre80_fecha,
        sicegre80_cab_ordcompra.sicegre80_fecha_entrega,
        sicegre80_cab_ordcompra.sicegre80_fecha_cierre,
        sicegre80_cab_ordcompra.sicegre80_notas
    from sicegre80_cab_ordcompra
    where sicegre80_cab_ordcompra.rela_socmain01 = ' || :p_rela_socmain01 ||
    ' and sicegre80_cab_ordcompra.rela_socmain21 = ' || :p_rela_socmain21;

    if (p_rela_sicegre01 != -1 ) then
    begin
        str_sql = str_sql || ' and sicegre80_cab_ordcompra.rela_sicegre01 = ' || p_rela_sicegre01;
    end

    if (p_fecha_desde is not null ) then
    begin
        str_sql = str_sql || ' and cast(sicegre80_cab_ordcompra.sicegre80_fecha as date) between ''' || p_fecha_desde || ''' AND ''' || p_fecha_hasta || '''';
    end

    if (p_cerrado = 1 ) then     --No se quieren Ordenes ya cerradas
    begin
        str_sql = str_sql || ' and (cast(sicegre80_cab_ordcompra.sicegre80_fecha_cierre as date) > ''' || cast(current_timestamp as date) || ''''
                            || ' or sicegre80_cab_ordcompra.sicegre80_fecha_cierre is null )';
    end

    for execute statement :str_sql
    into :rela_socusua01,
        :rela_socmain01,
        :rela_socmain21,
        :rela_sicegre01,
        :id_sicegre80,
        :sicegre80_docnro,
        :sicegre80_fecha,
        :sicegre80_fecha_entrega,
        :sicegre80_fecha_cierre,
        :sicegre80_notas
  do begin

      select cbo_sicegre01.entidad from cbo_sicegre01
      where cbo_sicegre01.rela_sicegre01 = :rela_sicegre01
      into :PROVEEDOR;
      suspend;
  end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR01_PYMVENT70 (
    RELA_SOCMAIN01 BIGINT,
    BUSCAR VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    ID_SICINGR01 BIGINT,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_PARTICULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_CELULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_LABORAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    buscar = upper(trim(buscar));

    FOR SELECT
    CBO_SICINGR01_PYMVENT70.rela_socusua30,
    CBO_SICINGR01_PYMVENT70.id_sicingr01,
    CBO_SICINGR01_PYMVENT70.entidad,
    CBO_SICINGR01_PYMVENT70.rfc,
    CBO_SICINGR01_PYMVENT70.tipo,
    CBO_SICINGR01_PYMVENT70.tel_particular,
    CBO_SICINGR01_PYMVENT70.tel_celular,
    CBO_SICINGR01_PYMVENT70.tel_laboral
    FROM CBO_SICINGR01_PYMVENT70(:rela_socmain01)
    where CBO_SICINGR01_PYMVENT70.busqueda like ('%' || :buscar || '%')
    INTO :rela_socusua30,
         :id_sicingr01,
         :entidad,
         :rfc,
         :tipo,
         :tel_particular,
         :tel_celular,
         :tel_laboral
    do
    begin
        if (rfc is null or trim(rfc) = '' or rfc = 'null' ) then
            rfc = 'XAXX010101000';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50 (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01 BIGINT)
RETURNS (
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCUSUA30 BIGINT,
    SICINGR01_DIASCREDITO INTEGER,
    SICINGR01_CREDITO DOUBLE PRECISION,
    RELA_SICINGR01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    SICINGR50_IMPORTE DOUBLE PRECISION,
    SICINGR50_IMPORTE_PESOS DOUBLE PRECISION,
    SICINGR50_IMPORTE_NO_PESOS DOUBLE PRECISION,
    ULT_FECHA DATE,
    ID_SICINGR51 BIGINT,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CONTADOR_ID bigint;
declare variable SQL_C varchar(1500);
declare variable COUNT_ENTIDAD integer;
begin
    CONTADOR_ID = 100000;

    select count(sicingr01_cab_clientes.id_sicingr01)
    from sicingr01_cab_clientes
    where sicingr01_cab_clientes.rela_socmain01 = :id_socmain01
    into :count_entidad;

    if (count_entidad < 100) then
        id_sicingr01 = null;

    if (id_sicingr01 is not null and id_sicingr01 > 0) then
    begin
        sql_c = 'Select
                qry_sicingr50.rela_socusua30,
                qry_sicingr50.sicingr01_diascredito,
                qry_sicingr50.sicingr01_credito,
                qry_sicingr50.rela_sicingr01,
                qry_sicingr50.rela_socmain01,
                sum(qry_sicingr50.SICINGR50_importe),
                sum(qry_sicingr50.SICINGR50_importe_pesos),
                sum(qry_sicingr50.SICINGR50_importe_no_pesos),
                max(qry_sicingr50.SICINGR50_fapl)
                from qry_sicingr50
                where qry_sicingr50.rela_socmain01 = ' || :id_socmain01 ||
                ' and qry_sicingr50.rela_sicingr01 = ' || :id_sicingr01 ||
                ' and qry_sicingr50.rela_sicingr01 = ' || :id_sicingr01 ||
                ' group by
                qry_sicingr50.rela_socusua30,
                qry_sicingr50.sicingr01_diascredito,
                qry_sicingr50.sicingr01_credito,
                qry_sicingr50.rela_sicingr01,
                qry_sicingr50.rela_socmain01';
    end
    else
    begin
        sql_c = 'Select
                qry_sicingr50.rela_socusua30,
                qry_sicingr50.sicingr01_diascredito,
                qry_sicingr50.sicingr01_credito,
                qry_sicingr50.rela_sicingr01,
                qry_sicingr50.rela_socmain01,
                sum(qry_sicingr50.SICINGR50_importe),
                sum(qry_sicingr50.SICINGR50_importe_pesos),
                sum(qry_sicingr50.SICINGR50_importe_no_pesos),
                max(qry_sicingr50.SICINGR50_fapl)
                from qry_sicingr50
                where qry_sicingr50.rela_socmain01 = ' || :id_socmain01 ||
                ' group by
                qry_sicingr50.rela_socusua30,
                qry_sicingr50.sicingr01_diascredito,
                qry_sicingr50.sicingr01_credito,
                qry_sicingr50.rela_sicingr01,
                qry_sicingr50.rela_socmain01';
    end

    for execute statement :sql_c
    into :rela_socusua30,
         :sicingr01_diascredito,
         :sicingr01_credito,
         :rela_sicingr01,
         :rela_socmain01,
         :SICINGR50_importe,
         :SICINGR50_importe_pesos,
         :SICINGR50_importe_no_pesos,
         :ult_fecha
    do
    begin
        select
        cbo_socusua30.tipo,
        cbo_socusua30.entidad,
        cbo_socusua30.rfc
        from cbo_socusua30(:rela_socusua30)
        into :tipo,
             :entidad_cliente,
             :rfc;

        /* --------------------------------------------------------------- */
        /* --------------------------------------------------------------- */
        /* --------------------------------------------------------------- */

        id_sicingr51 = null;

        select max(sicingr51_cab_bancos.id_sicingr51)
        from sicingr51_cab_bancos
        where sicingr51_cab_bancos.rela_sicingr01 = :rela_sicingr01
        into :id_sicingr51;

        if (id_sicingr51 is null) then
        begin
            contador_id = contador_id + 1;
            id_sicingr51 = :contador_id;
        end

        suspend;
    end

end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_DEPOSITOS (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICINGR50 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_DEPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICINGR50_IMPORTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XCOBRAR DOUBLE PRECISION,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICCONT10 bigint;
begin
    for select
    sicingr50_det_ctacte.rela_siccont10,
    sicingr50_det_ctacte.id_sicingr50,
    cbo_sicingr01.entidad,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicingr50_det_ctacte.sicingr50_importe,
    siccont10_cab_polizas.siccont10_uuid_sat
    from sicingr50_det_ctacte
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
    inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.id_sicingr01 = sicingr50_det_ctacte.rela_sicingr01)
    inner join cbo_sicingr01 on (cbo_sicingr01.id_socusua30 = sicingr01_cab_clientes.rela_socusua30)
    where sicingr50_det_ctacte.rela_socmain01 = :rela_socmain01
    and siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
    and cbo_sicingr01.rela_socmain01 = :rela_socmain01
    and siccont10_cab_polizas.siccont10_uuid_sat is not null
    and sicingr50_det_ctacte.sicingr50_importe > 0
    and siccont10_cab_polizas.siccont10_cotiza = 1

    and not exists (select first 1 sicingr52_det_bancos.id_sicingr52
                    from sicingr52_det_bancos
                    where sicingr52_det_bancos.rela_sicingr50 = sicingr50_det_ctacte.id_sicingr50
                    )
    and not exists (select first 1 sicingr61_det_depositos.id_sicingr61
                    from sicingr61_det_depositos
                    where sicingr61_det_depositos.rela_sicingr50 = sicingr50_det_ctacte.id_sicingr50
                    )
    into :rela_siccont10,
         :id_sicingr50,
         :entidad,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicingr50_importe,
         :SICCONT10_UUID_SAT
    do
    begin
        marca = 0;
        IMPORTE_XCOBRAR = 0.0;
        CRP = '';

        select
        SICXMLS41_DET_MIGRACION.sicxmls41_folio,
        SICXMLS41_DET_MIGRACION.sicxmls41_metododepago,
        SICXMLS41_DET_MIGRACION.sicxmls41_formapago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
             :sicxmls41_metododepago,
             :sicxmls41_formapago;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
         else
           CRP = 'No';

        select first 1 siccont11_det_polizas.siccont11_referencia
        from siccont11_det_polizas
        inner join siccont12_mov_dropzone on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
        and siccont12_mov_dropzone.rela_sicxmls04 is not null
        into :siccont11_referencia;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_DEPOSITOS_VIEW (
    RELA_SICINGR60 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICINGR50 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_DEPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICINGR50_IMPORTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XCOBRAR DOUBLE PRECISION,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICCONT10 bigint;
begin
    for select
    sicingr50_det_ctacte.rela_siccont10,
    sicingr50_det_ctacte.id_sicingr50,
    cbo_sicingr01.entidad,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicingr50_det_ctacte.sicingr50_importe,
    siccont10_cab_polizas.siccont10_uuid_sat,
    DEPO.siccont10_docnro
    from sicingr60_cab_depositos
    inner join sicingr61_det_depositos on (sicingr60_cab_depositos.id_SICINGR60 = sicingr61_det_depositos.rela_SICINGR60)
    inner join siccont10_cab_polizas DEPO ON (DEPO.id_siccont10 = sicingr61_det_depositos.rela_siccont10)
    inner join sicingr50_det_ctacte on (sicingr50_det_ctacte.id_sicingr50 = sicingr61_det_depositos.rela_sicingr50)
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
    inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.id_sicingr01 = sicingr50_det_ctacte.rela_sicingr01)
    inner join cbo_sicingr01 on (cbo_sicingr01.rela_sicingr01 = sicingr01_cab_clientes.id_sicingr01)
    where sicingr60_cab_depositos.id_SICINGR60 = :RELA_SICINGR60
    into :rela_siccont10,
         :id_sicingr50,
         :entidad,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicingr50_importe,
         :SICCONT10_UUID_SAT,
         :siccont10_docnro_depo
    do
    begin
        marca = 1;
        IMPORTE_XCOBRAR = sicingr50_importe;
        CRP = '';

        select
             SICXMLS41_DET_MIGRACION.sicxmls41_folio,
             SICXMLS41_DET_MIGRACION.sicxmls41_metododepago,
             SICXMLS41_DET_MIGRACION.sicxmls41_formapago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
            :sicxmls41_metododepago,
        :sicxmls41_formapago;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
         else
           CRP = 'No';

        select first 1 siccont11_det_polizas.siccont11_referencia
        from siccont11_det_polizas
        inner join siccont12_mov_dropzone on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
        and siccont12_mov_dropzone.rela_sicxmls04 is not null
        into :siccont11_referencia;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_DET (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01 BIGINT,
    VERSION_XML VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MARCA INTEGER,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SICINGR01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SICINGR51 BIGINT,
    ID_SICINGR50 BIGINT,
    SICINGR50_IMPORTE DOUBLE PRECISION,
    SICINGR50_FAPL TIMESTAMP,
    IMPORTE_XCOBRAR DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCSYST10_CTM01 BIGINT)
AS
declare variable SUMA_SALDO double precision;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICXMLS41 bigint;
declare variable SICXMLS41_VERSION varchar(50);
begin
    for select
    socsyst10_det_entradas.socsyst10_codigo,
    socsyst10_det_entradas.socsyst10_descripcion,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_fcta,
    qry_sicingr50.rela_sicingr01,
    qry_sicingr50.rela_socmain01,
    qry_sicingr50.rela_siccont10,
    qry_sicingr50.rela_SICINGR51,
    qry_sicingr50.id_SICINGR50,
    qry_sicingr50.SICINGR50_importe,
    qry_sicingr50.SICINGR50_fapl,
    qry_sicingr50.siccont10_cotiza,
    qry_sicingr50.moneda_descripcion,
    qry_sicingr50.rela_socsyst10_ctm01
    FROM qry_sicingr50
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = qry_sicingr50.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    where qry_sicingr50.rela_socmain01 = :id_socmain01
    and qry_sicingr50.rela_sicingr01 = :id_sicingr01
    and not exists (select first 1 sicingr61_det_depositos.id_sicingr61
                    from sicingr61_det_depositos
                    where sicingr61_det_depositos.rela_sicingr50 = qry_sicingr50.id_sicingr50)
    into :socsyst10_codigo,
         :socsyst10_descripcion,
         :SICCONT10_DOCNRO,
         :SICCONT10_UUID_SAT,
         :SICCONT10_FCTA,
         :RELA_SICingr01,
         :RELA_SOCMAIN01,
         :RELA_SICCONT10,
         :RELA_SICINGR51,
         :ID_SICINGR50,
         :SICINGR50_IMPORTE,
         :SICINGR50_FAPL,
         :cotiza,
         :moneda,
         :rela_socsyst10_ctm01
    do
    begin
        if (rela_siccont10 = 9465) then
        rela_siccont10 = 9465;

        marca = 0;
        importe_xcobrar = 0.0;
        suma_saldo = 0.0;
        sicxmls41_folio = null;
        id_sicxmls41 = null;

        select sum(sicingr52_det_bancos.sicingr52_importe)
        from sicingr52_det_bancos
        where sicingr52_det_bancos.rela_SICINGR50 = :ID_SICINGR50
        into :suma_saldo;

        if (suma_saldo is null) then
            suma_saldo = 0;

        SICINGR50_importe = SICINGR50_importe - suma_saldo;

        if (cast(SICINGR50_importe as numeric(18,4)) <> 0 and SICCONT10_UUID_SAT is not null and TRIM(SICCONT10_UUID_SAT) <> '') then
        begin
            select
            sicxmls41_det_migracion.id_sicxmls41,
            sicxmls41_det_migracion.sicxmls41_folio,
            sicxmls41_det_migracion.sicxmls41_version,
            sicxmls41_det_migracion.sicxmls41_metododepago,
            sicxmls41_det_migracion.sicxmls41_formapago
            from sicxmls41_det_migracion
            where sicxmls41_det_migracion.rela_siccont10 = :RELA_SICCONT10
            into :id_sicxmls41,
                 :sicxmls41_folio,
                 :sicxmls41_version,
                 :sicxmls41_metododepago,
                 :sicxmls41_formapago;

            if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
                CRP = 'Si';
            else
                CRP = 'No';

            if (id_sicxmls41 is not null) then
            begin
                if (sicxmls41_version is null) then
                    sicxmls41_version = '3.2';

                if (sicxmls41_version = version_xml ) then
                    suspend;
            end
        end
        else if (cast(SICINGR50_importe as numeric(18,4)) <> 0) then
        begin
            if (socsyst10_codigo = 'DROPZONE-ANTI-CLIENTE') then
            begin
                SICXMLS41_FOLIO = :siccont10_docnro;
                suspend;
            end
            else  if (socsyst10_codigo = 'BANCOS-GASTOS3ROS') then
            begin
                SICXMLS41_FOLIO = :siccont10_docnro;
                suspend;
            end

        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_MOV (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SICCONT10 BIGINT,
    RELA_SICINGR51 BIGINT,
    ID_SICINGR50 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EJECUTADO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_REF VARCHAR(5000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS_REF INTEGER,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    FECHA DATE,
    UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCSYST10_CTM01 BIGINT,
    BANCO_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICXMLS41 bigint;
declare variable ID_SICINGR61FIND bigint;
declare variable REFERENCIA_POLIZA varchar(50);
declare variable RELA_SICINGR51_CREDITO bigint;
declare variable FECHA_REF date;
begin
    FOR select
    socsyst10_det_entradas.socsyst10_codigo,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_fcta,
    qry_sicingr50.rela_siccont10,
    qry_sicingr50.rela_SICINGR51,
    qry_sicingr50.id_SICINGR50,
    qry_sicingr50.SICINGR50_importe,
    siccont10_cab_polizas.siccont10_cotiza,
    qry_sicingr50.moneda_descripcion,
    qry_sicingr50.moneda_codigo,
    qry_sicingr50.rela_socsyst10_ctm01
    FROM qry_sicingr50
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = qry_sicingr50.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    where qry_sicingr50.rela_socmain01 = :rela_socmain01
    and qry_sicingr50.rela_SICINGR01 = :rela_SICINGR01
    and siccont10_cab_polizas.siccont10_fcta between :fecha_desde and :fecha_hasta
    order  by siccont10_cab_polizas.siccont10_fcta
    INTO :SOCSYST10_CODIGO,
         :POLIZA,
         :UUID_SAT,
         :FECHA,
         :RELA_SICCONT10,
         :rela_SICINGR51,
         :id_SICINGR50,
         :importe_xml,
         :cotiza,
         :moneda,
         :moneda_codigo,
         :rela_socsyst10_ctm01
    DO
    BEGIN
        folio = null;
        id_sicxmls41 = null;
        siccont10_docnro_ref = null;
        fecha_ref = null;
        dias_ref = 0;
        cotiza = iif(cotiza is null or cotiza = 0, 1, :cotiza);

        select
        SICXMLS41_DET_MIGRACION.sicxmls41_folio,
        SICXMLS41_DET_MIGRACION.id_sicxmls41,
        SICXMLS41_DET_MIGRACION.sicxmls41_metododepago,
        SICXMLS41_DET_MIGRACION.sicxmls41_formapago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
             :id_sicxmls41,
             sicxmls41_metododepago,
             sicxmls41_formapago;

        CRP = '';

        select sum(SICINGR52_det_bancos.SICINGR52_importe)
        from SICINGR52_det_bancos
        where SICINGR52_det_bancos.rela_SICINGR50 = :ID_SICINGR50
        into :importe_banco;

        if (importe_banco is null) then
            importe_banco = 0.00;

        importe_saldo = importe_xml - importe_banco;
        importe_saldo = cast(importe_saldo as numeric(18,4));

        ejecutado = 0;

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */

        if (SOCSYST10_CODIGO = 'DROPZONE' and id_sicxmls41 is not null) then
        begin
             if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
                CRP = 'Si';
            else
                CRP = 'No';

            if (importe_xml > 0) then
                STATUS = 'Factura Emitida';
            else
                STATUS = 'Crédito en Contra';

            importe_xml = iif(importe_xml is null, 0.00, importe_xml);
            if (importe_xml <> 0) then
                ejecutado = (importe_banco / importe_xml * 100);

            if (ejecutado = 0) then
            begin
                ejecutado = 0.0;
                id_sicingr61find = null;

                select first 1
                SICINGR61_DET_DEPOSITOS.id_sicingr61,
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta
                from SICINGR61_DET_DEPOSITOS
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = SICINGR61_DET_DEPOSITOS.rela_siccont10 )
                where SICINGR61_DET_DEPOSITOS.rela_sicingr50 = :id_sicingr50
                into :id_sicingr61find,
                     :siccont10_docnro_ref,
                     :fecha_ref;

                if (id_sicingr61find is not null) then
                BEGIN
                   ejecutado = 100;
                   importe_banco = :importe_xml;
                   importe_saldo = 0;
                   dias_ref = datediff(DAY FROM :fecha TO :fecha_ref);
                END
            end
            else
            if (STATUS = 'Factura Emitida') then
            begin
                for select
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta
                from sicingr52_det_bancos
                inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
                inner join sicingr50_det_ctacte on ( sicingr51_cab_bancos.id_sicingr51 = sicingr50_det_ctacte.rela_sicingr51 )
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
                where sicingr52_det_bancos.rela_sicingr50 = :ID_SICINGR50
                order by siccont10_cab_polizas.siccont10_docnro
                into :referencia_poliza,
                     :fecha_ref
                do
                begin
                    siccont10_docnro_ref = iif(siccont10_docnro_ref is null, '', siccont10_docnro_ref);
                    siccont10_docnro_ref = siccont10_docnro_ref || trim(referencia_poliza) || ' ';
                end

                if ( siccont10_docnro_ref is not null ) then
                begin
                    siccont10_docnro_ref = trim(siccont10_docnro_ref);
                    dias_ref = datediff(DAY FROM :fecha TO :fecha_ref);
                end
            end
            else
            begin
                select first 1 sicingr52_det_bancos.rela_sicingr51
                from sicingr52_det_bancos
                where sicingr52_det_bancos.rela_sicingr50 = :ID_SICINGR50
                into :rela_sicingr51_credito;

                Select
                max(siccont10_cab_polizas.siccont10_docnro),
                max(siccont10_cab_polizas.siccont10_fcta)
                from sicingr52_det_bancos
                inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
                where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51_credito
                and sicingr52_det_bancos.sicingr52_importe > 0
                into :siccont10_docnro_ref,
                     :fecha_ref;

                dias_ref = datediff(DAY FROM :fecha TO :fecha_ref);
            end

        end

        else if (SOCSYST10_CODIGO = 'DROPZONE-ANTI-CLIENTE') then
        begin
            STATUS = 'Anticipo';
        end

        else if (SOCSYST10_CODIGO = 'DROPZONE-BANCOS-CLIENTE') then
        begin
            STATUS = 'Cobro';
            ejecutado = 100;
            importe_saldo = 0;
            importe_banco = importe_xml;
        end

        else if (SOCSYST10_CODIGO = 'DROPZONE-DEPOSITOS') then
        begin
            STATUS = 'Depositos Globales';
            ejecutado = 100;
            importe_saldo = 0;
            importe_banco = importe_xml;
        end

        else if (SOCSYST10_CODIGO = 'BANCOS-GASTOS3ROS') then
        begin
            STATUS = 'Gastos por Cuenta del Cliente';
            ejecutado = 100;
            importe_saldo = 0;
            importe_banco = importe_xml;
        end
        else
        begin
            STATUS = :SOCSYST10_CODIGO;
        end

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */

        if (ejecutado <> 0) then
        begin
            select
            BAN01.socsyst10_descripcion,
            CTM01.socsyst10_descripcion,
            sicingr51_cab_bancos.sicingr51_cuenta
            from sicingr51_cab_bancos
            inner join socmain05_det_bancos on ( socmain05_det_bancos.id_socmain05 = sicingr51_cab_bancos.rela_socmain05 )
            inner join socsyst10_det_entradas BAN01 ON (BAN01.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ban01 )
            inner join socsyst10_det_remoto CTM01 ON (CTM01.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ctm01 )
            where sicingr51_cab_bancos.id_sicingr51 = :RELA_SICINGR51
            INTO :banco_emp,
                 :moneda_emp,
                 :cuenta_emp;

            if (banco_emp is null) then
                banco_emp = 'N/A';

            if (moneda_emp is null) then
                moneda_emp = 'N/A';

            if (cuenta_emp is null) then
                cuenta_emp = 'N/A';
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_MOV_DET (
    RELA_SICINGR51 BIGINT,
    RELA_SICINGR50 BIGINT,
    GASTOS_X_CLIENTE INTEGER)
RETURNS (
    RELA_SICCONT10 BIGINT,
    ID_SICINGR52 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICINGR50X bigint;
declare variable ID_SICINGR52_GTOSXCLIENTE bigint;
declare variable SICCONT10_DOCNROGC varchar(50);
declare variable SICCONT10_FCTAGC date;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SICCONT10_COTIZA double precision;
begin
    /*
        el rela_sicingr51 lo utilizo para buscar en los cobros a cuales xml he cobrado
        el rela_sicingr50 lo utilizo para buscar en los xmls ya ejecutados con que movimientos de banco los cobre
    */

    if (rela_sicingr51 is not null) then
    begin
        for select
        sicingr52_det_bancos.rela_sicingr50,
        max(sicingr52_det_bancos.id_sicingr52),
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont10_cab_polizas.siccont10_uuid_sat,
        sicingr50_det_ctacte.rela_siccont10,  --HV
        sicingr50_det_ctacte.sicingr50_importe,
        socsyst10_det_entradas.socsyst10_codigo
        from sicingr52_det_bancos
        inner join sicingr50_det_ctacte on (sicingr52_det_bancos.rela_sicingr50 = sicingr50_det_ctacte.id_sicingr50)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
        where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
        group by
        sicingr52_det_bancos.rela_sicingr50,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont10_cab_polizas.siccont10_uuid_sat,
        sicingr50_det_ctacte.rela_siccont10,  --HV
        sicingr50_det_ctacte.sicingr50_importe,
        socsyst10_det_entradas.socsyst10_codigo
        order by
        siccont10_cab_polizas.siccont10_fcta
        into :rela_sicingr50x,
             :id_sicingr52,
             :siccont10_docnro,
             :siccont10_fcta,
             :siccont10_uuid_sat,
             :rela_siccont10,  --HV
             :importe_xml,
             :socsyst10_codigo
        do
        begin
            folio = null;   --HV

            select SICXMLS41_DET_MIGRACION.sicxmls41_folio
            from SICXMLS41_DET_MIGRACION
            where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
            into :folio;
            --Hasta aqui

            select sum(sicingr52_det_bancos.sicingr52_importe)
            from sicingr52_det_bancos
            where sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50x
            into :importe_pago;

            if (importe_xml < 0) then
            begin
                status = 'Crédito en Contra';
                if (siccont10_uuid_sat is null or trim(siccont10_uuid_sat) = '' ) then
                begin
                    STATUS = 'Anticipo';

                    if (socsyst10_codigo = 'BANCOS-GASTOS3ROS') then
                        STATUS = 'Gastos por Cuenta del Cliente';
                end
            end
            else
            begin
                status = 'Factura Emitida';
            end

            saldo = :importe_xml - :importe_pago;
            suspend;
        end
    end
    else if (rela_sicingr51 is null and gastos_x_cliente = 1) then
    begin
        select first 1
        sicingr52_det_bancos.rela_sicingr51,
        sicingr52_det_bancos.sicingr52_importe * (-1)
        from sicingr52_det_bancos
        where sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
        into :rela_sicingr51,
             :importe_pago;

        select first 1
        siccont10_cab_polizas.id_siccont10,
        sicingr52_det_bancos.id_sicingr52,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont10_cab_polizas.siccont10_uuid_sat,
        siccont10_cab_polizas.siccont10_cotiza
        from sicingr52_det_bancos
        inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
        where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
        and sicingr52_det_bancos.sicingr52_importe = :importe_pago
        into :rela_siccont10,
             :id_sicingr52,
             :siccont10_docnro,
             :siccont10_fcta,
             :siccont10_uuid_sat,
             :siccont10_cotiza;

        siccont10_cotiza = iif(siccont10_cotiza = 0 or siccont10_cotiza is null, 1, siccont10_cotiza);
        status = 'Factura Emitida';

        select sum(siccont11_det_polizas.siccont11_debe)
        from siccont11_det_polizas
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
        into :importe_xml;

        importe_xml = :importe_xml / :siccont10_cotiza;
        importe_pago = :importe_xml;

        suspend;
    end
    else if (rela_sicingr51 is null and gastos_x_cliente = 0) then
    begin
        importe_xml = 0;
        saldo = 0;

        for select
        sicingr52_det_bancos.rela_sicingr51,
        sicingr52_det_bancos.id_sicingr52,
        sicingr52_det_bancos.sicingr52_importe
        from sicingr52_det_bancos
        where sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
        into :rela_sicingr51,
             :id_sicingr52,
             :importe_pago
        do
        begin
            select
            siccont10_cab_polizas.id_siccont10,
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta,
            siccont10_cab_polizas.siccont10_uuid_sat
            from sicingr50_det_ctacte
            inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
            where sicingr50_det_ctacte.rela_sicingr51 = :rela_sicingr51
            into :rela_siccont10,
                 :siccont10_docnro,
                 :siccont10_fcta,
                 :siccont10_uuid_sat;

            if (siccont10_docnro is null) then
            begin
                STATUS = 'Crédito en Contra';

                select
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta,
                siccont10_cab_polizas.siccont10_uuid_sat
                from sicingr50_det_ctacte
                inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
                where sicingr50_det_ctacte.id_sicingr50 = :rela_sicingr50
                into :siccont10_docnro,
                     :siccont10_fcta,
                     :siccont10_uuid_sat;

            end
            else
            begin
               STATUS = 'Cobro';
               id_sicingr52_gtosXCliente = null;
    
                select first 1
                sicingr52_det_bancos.id_sicingr52,
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta
                from sicingr52_det_bancos
                inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
                inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
                where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
                and socsyst10_det_entradas.socsyst10_codigo = 'BANCOS-GASTOS3ROS'
                and sicingr52_det_bancos.sicingr52_importe = :importe_pago * (-1)
                into :id_sicingr52_gtosXCliente,
                     :siccont10_docnroGC,
                     :siccont10_fctaGC;
    
                if (id_sicingr52_gtosXCliente is not null) then
                begin
                    STATUS = 'Gastos por Cuenta del Cliente';
                    siccont10_docnro =siccont10_docnroGC;
                    siccont10_fcta = siccont10_fctaGC;
                    siccont10_uuid_sat = '';
                end
            end

            suspend;
        end     
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_MOV_FACT (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT)
RETURNS (
    RELA_SICCONT10 BIGINT,
    ID_SICINGR50 BIGINT,
    EJECUTADO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    IMPORTE_ANTICIPOS DOUBLE PRECISION,
    IMPORTE_ANTICIPOS_NOAPLICADO DOUBLE PRECISION,
    IMPORTE_PAGO_CLIENTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE,
    COTIZA DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICINGR85 bigint;
declare variable IMPORTE_ANTICIPOS_APLICADO double precision;
begin
    id_sicingr85 = null;

    select first 1 SICINGR85_CAB_GASTOS3ROS.id_sicingr85
    from SICINGR85_CAB_GASTOS3ROS
    where SICINGR85_CAB_GASTOS3ROS.rela_socmain01 = :rela_socmain01
    and SICINGR85_CAB_GASTOS3ROS.rela_sicingr01 = :rela_sicingr01
    into :id_sicingr85;

    if (id_sicingr85 is not null) then
    begin
        FOR SELECT
        GRD_SICINGR50_MOV.id_sicingr50,
        GRD_SICINGR50_MOV.rela_siccont10,
        GRD_SICINGR50_MOV.ejecutado,
        GRD_SICINGR50_MOV.poliza,
        GRD_SICINGR50_MOV.importe_xml,
        GRD_SICINGR50_MOV.importe_banco,
        GRD_SICINGR50_MOV.importe_saldo,
        GRD_SICINGR50_MOV.folio,
        GRD_SICINGR50_MOV.fecha,
        GRD_SICINGR50_MOV.cotiza,
        GRD_SICINGR50_MOV.moneda
        FROM GRD_SICINGR50_MOV(:rela_socmain01, :rela_sicingr01, '01/01/01', '12/31/2030')
        WHERE GRD_SICINGR50_MOV.STATUS = 'Factura Emitida'
        order by GRD_SICINGR50_MOV.folio
        INTO :id_sicingr50,
             :rela_siccont10,
             :ejecutado,
             :poliza,
             :importe_xml,
             :importe_banco,
             :importe_saldo,
             :folio,
             :fecha,
             :cotiza,
             :moneda
        do
        BEGIN
            IMPORTE_ANTICIPOS = null;
            IMPORTE_PAGO_CLIENTE = null;
            importe_anticipos_aplicado = null;
            importe_anticipos_noaplicado = null;

            Select SUM(GRD_SICINGR70_SICINGR88.sicingr53_importe)
            from GRD_SICINGR70_SICINGR88( :rela_siccont10 )
            INTO :IMPORTE_ANTICIPOS;
    
            if (IMPORTE_ANTICIPOS is null) then
                IMPORTE_ANTICIPOS = 0.00;
    
            SELECT SUM(GRD_SICINGR50_MOV_DET.importe_pago)
            FROM GRD_SICINGR50_MOV_DET(null,:id_sicingr50, 0)
            WHERE GRD_SICINGR50_MOV_DET.status = 'Gastos por Cuenta del Cliente'
            INTO :IMPORTE_PAGO_CLIENTE;
    
            if (importe_pago_cliente is null) then
                importe_pago_cliente = 0;


            if (ejecutado = 0 and importe_pago_cliente = 0 and importe_anticipos <> 0) then
                importe_pago_cliente = importe_xml - importe_anticipos;
    
            select sum(PRD_SICINGR50_ANTICIPOS.sicingr52_importe)
            from PRD_SICINGR50_ANTICIPOS(:id_sicingr50)
            into :importe_anticipos_aplicado;

            if (importe_anticipos_aplicado is null) then
                importe_anticipos_aplicado = 0;

            if (importe_anticipos_aplicado <> 0) then
                importe_anticipos_noaplicado = :importe_anticipos - :importe_anticipos_aplicado;
            else
                importe_anticipos_noaplicado = 0;

            suspend;
        END
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR50_SICINGR70 (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCUSUA30 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    SICINGR50_IMPORTE DOUBLE PRECISION,
    ULT_FECHA DATE,
    RELA_SOCMAIN05 BIGINT,
    RELA_SOCSYST10_BAN01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICINGR51 BIGINT,
    SICINGR51_CUENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR51_FECHA DATE,
    SICINGR51_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR51_FAPL TIMESTAMP,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_OTRASMONEDAS DOUBLE PRECISION,
    COTIZA_PROMEDIO DOUBLE PRECISION)
AS
declare variable CUENTA_COTIZA integer;
declare variable SUMA_COTIZA double precision;
declare variable IMPORTE_OTRASMONEDAS_PAGADAS double precision;
declare variable CONTADOR_ID bigint;
begin
    CONTADOR_ID = 100000;

    for Select
    sicingr01_cab_clientes.rela_socusua30,
    sicingr01_cab_clientes.id_sicingr01,
    sicingr01_cab_clientes.rela_socmain01,
    sum(SICINGR50_DET_CTACTE.SICINGR50_importe),
    max(SICINGR50_DET_CTACTE.SICINGR50_fapl)
    from sicingr01_cab_clientes
    left outer join sicingr50_det_ctacte on (sicingr01_cab_clientes.id_sicingr01 = sicingr50_det_ctacte.rela_sicingr01)
    where sicingr01_cab_clientes.rela_socmain01 = :id_socmain01
    group by
    sicingr01_cab_clientes.rela_socusua30,
    sicingr01_cab_clientes.id_sicingr01,
    sicingr01_cab_clientes.rela_socmain01
    into :rela_socusua30,
         :rela_sicingr01,
         :rela_socmain01,
         :SICINGR50_importe,
         :ult_fecha
    do
    begin
        if (SICINGR50_importe is null) then
            SICINGR50_importe = 0.00;

        select
        cbo_socusua30.tipo,
        cbo_socusua30.entidad,
        cbo_socusua30.rfc
        from cbo_socusua30(:rela_socusua30)
        into :tipo,
             :entidad,
             :rfc;

        /* --------------------------------------------------------------- */
        /* ----- aqui tomo sumas que vengan desde otras monedas ---------- */
        /* --------------------------------------------------------------- */

        importe_otrasmonedas = null;

        /* aquí recupero los pagos con cambio diferente de 1 para restrlo al total de xml con cmbio diferente de 1 */

        select
        sum(sicingr52_det_bancos.sicingr52_importe)
        from sicxmls41_det_migracion
        inner join siccont10_cab_polizas on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
        inner join sicingr50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
        inner join sicingr52_det_bancos on (sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50)
        where siccont10_cab_polizas.rela_socmain01 = :id_socmain01
        and siccont10_cab_polizas.rela_socusua30 = :rela_socusua30
        and sicxmls41_det_migracion.sicxmls41_cambio <> 1
        into :importe_otrasmonedas_pagadas;

        if (importe_otrasmonedas_pagadas is null) then
            importe_otrasmonedas_pagadas = 0;

        /* --------------------------------------------------------------- */

        select
        count(sicxmls41_det_migracion.id_sicxmls41),
        sum(siccont10_cab_polizas.siccont10_cotiza),
        sum(sicxmls41_det_migracion.sicxmls41_uuid_importe)
        from siccont10_cab_polizas
        inner join sicingr50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
        inner join sicxmls41_det_migracion on (siccont10_cab_polizas.id_siccont10 = sicxmls41_det_migracion.rela_siccont10)
        where siccont10_cab_polizas.rela_socusua30 = :rela_socusua30
        and siccont10_cab_polizas.siccont10_cotiza <> 1
        into :cuenta_cotiza,
             :suma_cotiza,
             :importe_otrasmonedas;

        if (importe_otrasmonedas is null) then
        begin
            importe_otrasmonedas = 0;
            cotiza_promedio = 1;
        end
        else
        begin
            cotiza_promedio = suma_cotiza / cuenta_cotiza;
            importe_otrasmonedas = importe_otrasmonedas * cotiza_promedio;
            importe_otrasmonedas = importe_otrasmonedas - :importe_otrasmonedas_pagadas;
        end

        /* --------------------------------------------------------------- */
        /* --------------------------------------------------------------- */
        /* --------------------------------------------------------------- */

        id_sicingr51 = null;

        select max(sicingr51_cab_bancos.id_sicingr51)
        from sicingr51_cab_bancos
        where sicingr51_cab_bancos.rela_sicingr01 = :rela_sicingr01
        into :id_sicingr51;

        if (id_sicingr51 is null) then
        begin
            contador_id = contador_id + 1;
            id_sicingr51 = :contador_id;
        end

         suspend;
    end

end^


CREATE OR ALTER PROCEDURE GRD_SICINGR51_PAGOS (
    ID_SOCMAIN01 BIGINT,
    CODIGO INTEGER)
RETURNS (
    MARCA INTEGER,
    FACTORAJE VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICINGR01 BIGINT,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICPAGO70 BIGINT,
    BANCO_CLIENTE_COD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_CLIENTE_DES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_CLIENTE_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_CLIENTE_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_CLIENTE_CTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_CLIENTE_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_CLIENTE_DES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_CLIENTE_COTIZA DOUBLE PRECISION,
    METPAGO_CLIENTE_COD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METPAGO_CLIENTE_DES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METPAGO_CLIENTE_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR51_IMPORTE DOUBLE PRECISION,
    SICINGR51_FECHA DATE,
    SICINGR51_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMPRESA_COD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMPRESA_DES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMPRESA_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMPRESA_CTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_EMPRESA_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_EMPRESA_DES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_SMX_QRCODE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICPAGO70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICPAGO70_STATUS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_CANCELADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_FACTORAJE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE)
AS
declare variable RELA_SICCONT10 bigint;
declare variable RELA_SICINGR51 bigint;
declare variable RELA_SICEGRE01_FACTORAJE bigint;
begin
    marca = 0;

    for select
    sicingr51_cab_bancos.id_sicingr51,
    sicingr51_cab_bancos.rela_sicingr01,
    BANCO.socsyst10_codigo,
    BANCO.socsyst10_descripcion,
    BANCO.socsyst10_grupo,
    BANCO.socsyst10_valor01,
    sicingr51_cab_bancos.sicingr51_cuenta,
    MONEDA.socsyst10_codigo,
    MONEDA.socsyst10_descripcion,
    sicingr51_cab_bancos.sicingr51_cotiza,
    MET_PAGO.socsyst10_codigo,
    MET_PAGO.socsyst10_descripcion,
    MET_PAGO.socsyst10_grupo,
    BANCO_EMP.socsyst10_codigo,
    BANCO_EMP.socsyst10_descripcion,
    BANCO_EMP.socsyst10_grupo,
    BANCO_EMP.socsyst10_valor01,
    socmain05_det_bancos.socmain05_cuenta,
    MONEDA_EMP.socsyst10_codigo,
    MONEDA_EMP.socsyst10_descripcion,
    sicingr51_cab_bancos.sicingr51_importe,
    sicingr51_cab_bancos.sicingr51_fecha,
    sicingr51_cab_bancos.sicingr51_referencia,
    sicpago70_cab_pago.id_sicpago70,
    sicpago70_cab_pago.sicpago70_docnro,
    sicpago70_cab_pago.sicpago70_status
    from sicingr51_cab_bancos
    inner join socmain05_det_bancos on ( socmain05_det_bancos.id_socmain05 = sicingr51_cab_bancos.rela_socmain05 )
    inner join socsyst10_det_entradas BANCO on ( BANCO.id_socsyst10 = sicingr51_cab_bancos.rela_socsyst10_ban01 )
    inner join socsyst10_det_remoto MONEDA on ( MONEDA.id_socsyst10 = sicingr51_cab_bancos.rela_socsyst10_ctm01 )
    inner join socsyst10_det_entradas MET_PAGO on ( MET_PAGO.id_socsyst10 = sicingr51_cab_bancos.rela_socsyst10_mdp01 )
    inner join socsyst10_det_entradas BANCO_EMP on ( BANCO_EMP.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ban01 )
    inner join socsyst10_det_remoto MONEDA_EMP on ( MONEDA_EMP.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ctm01 )
    inner join sicpago70_cab_pago on ( sicpago70_cab_pago.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51 )
    where sicingr51_cab_bancos.rela_socmain01 = :id_socmain01
    and sicingr51_cab_bancos.sicingr51_anticipo = 0
    into :rela_sicingr51,
         :rela_sicingr01,
         :banco_cliente_cod,
         :banco_cliente_des,
         :banco_cliente_sat,
         :banco_cliente_rfc,
         :banco_cliente_cta,
         :moneda_cliente_sat,
         :moneda_cliente_des,
         :moneda_cliente_cotiza,
         :metpago_cliente_cod,
         :metpago_cliente_des,
         :metpago_cliente_sat,
         :banco_empresa_cod,
         :banco_empresa_des,
         :banco_empresa_sat,
         :banco_empresa_rfc,
         :banco_empresa_cta,
         :moneda_empresa_sat,
         :moneda_empresa_des,
         :sicingr51_importe,
         :sicingr51_fecha,
         :sicingr51_referencia,
         :id_sicpago70,
         :sicpago70_docnro,
         :sicpago70_status
    do
    begin
        rela_siccont10 = null;
        uuid = null;
        uuid_smx = null;
        uuid_smx_qrcode = null;

        select
        cbo_sicingr01_id.entidad,
        cbo_sicingr01_id.rfc
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :cliente,
             :cliente_rfc;

        select
        sicpago74_dep_cfdis.sicpago74_uuid,
        sicpago74_dep_cfdis.sicpago74_uuid_smx,
        sicpago74_dep_cfdis.sicpago74_uuid_smx_qrcode
        from sicpago74_dep_cfdis
        where sicpago74_dep_cfdis.rela_sicpago70 = :id_sicpago70
        into :uuid,
             :uuid_smx,
             :uuid_smx_qrcode;

        if (sicpago70_status = 'En proceso de Timbrar' and uuid is not null) then
        begin
            sicpago70_status = 'Timbrado Individualmente';
            update sicpago70_cab_pago set sicpago70_cab_pago.sicpago70_status = 'Timbrado Individualmente'
            where sicpago70_cab_pago.id_sicpago70 = :id_sicpago70;
        end

        UUID_CANCELADO = NULL;

        SELECT FIRST 1 sicpago77_det_cfdiscancelados.sicpago77_uuid
        FROM sicpago77_det_cfdiscancelados
        WHERE sicpago77_det_cfdiscancelados.rela_sicpago70 = :id_sicpago70
        ORDER BY sicpago77_det_cfdiscancelados.id_sicpago77 DESC
        INTO :UUID_CANCELADO;

        rela_siccont10 = null;
        siccont10_docnro = null;
        siccont10_fcta = null;

        select first 1
        siccont10_cab_polizas.id_siccont10
        from sicingr52_det_bancos
        inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
        where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
        and exists (select first 1 sicxmls41_det_migracion.id_sicxmls41
                    from sicxmls41_det_migracion
                    where sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10
                    and trim(sicxmls41_det_migracion.sicxmls41_formapago) = '99' )
        into :rela_siccont10;

        select
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta
        from sicingr50_det_ctacte
        inner join sicingr51_cab_bancos on (sicingr51_cab_bancos.id_sicingr51 = sicingr50_det_ctacte.rela_sicingr51)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
        where sicingr50_det_ctacte.rela_sicingr51 = :rela_sicingr51
        into :siccont10_docnro,
             :siccont10_fcta;

        rela_sicegre01_factoraje = null;

        select sicpago50_cab_factoraje.rela_sicegre01
        from sicpago50_cab_factoraje
        where sicpago50_cab_factoraje.rela_sicingr51 = :rela_sicingr51
        into :rela_sicegre01_factoraje;

        if (rela_sicegre01_factoraje is not null) then
        begin
            factoraje = 'Si';
            select cbo_sicegre01_id.rfc
            from cbo_sicegre01_id
            where cbo_sicegre01_id.id_sicegre01 = :rela_sicegre01_factoraje
            into :rfc_factoraje;

            if (codigo = 0 and uuid is null) then
                suspend;
            else if (codigo = 1 and uuid is not null) then
                suspend;
        end
        else if (rela_siccont10 is not null) then
        begin
            factoraje = 'No';

            if (codigo = 0 and uuid is null) then
                suspend;
            else if (codigo = 1 and uuid is not null) then
                suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR55 (
    RELA_SICINGR51 BIGINT)
RETURNS (
    RELA_SICINGR70 BIGINT,
    ID_SICINGR55 BIGINT,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE,
    SICINGR70_NETO DOUBLE PRECISION,
    SICINGR70_PAGADO DOUBLE PRECISION,
    SICINGR70_SALDO DOUBLE PRECISION,
    SICINGR55_IMPORTE DOUBLE PRECISION,
    SICINGR70_NOTACREDITO DOUBLE PRECISION)
AS
declare variable CREDITO double precision;
begin
    delete from tmp_sicingr70_notascredito
    where tmp_sicingr70_notascredito.usuario = current_user;

    insert into tmp_sicingr70_notascredito
    select
    current_user,
    grd_sicingr70_notascredito.id_sicingr70,
    grd_sicingr70_notascredito.sicingr70_docnro,
    grd_sicingr70_notascredito.sicingr70_fecha,
    grd_sicingr70_notascredito.credito,
    grd_sicingr70_notascredito.folio,
    grd_sicingr70_notascredito.factura,
    grd_sicingr70_notascredito.saldo,
    grd_sicingr70_notascredito.sicingr70_fapl
    from grd_sicingr70_notascredito;


    for select
    sicingr55_det_facturas.rela_sicingr70,
    sicingr55_det_facturas.id_sicingr55,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_fecha,
    sicingr70_cab_facturacion.sicingr70_neto,
    sicingr55_det_facturas.sicingr55_importe
    from sicingr55_det_facturas
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr55_det_facturas.rela_sicingr70)
    where sicingr55_det_facturas.rela_sicingr51 = :rela_sicingr51
    order by sicingr70_cab_facturacion.sicingr70_docnro desc
    into :rela_sicingr70,
         :id_sicingr55,
         :sicingr70_docnro,
         :sicingr70_fecha,
         :sicingr70_neto,
         :sicingr55_importe
    do
    begin
        select sum(sicingr55_det_facturas.sicingr55_importe)
        from sicingr55_det_facturas
        where sicingr55_det_facturas.rela_sicingr70 = :rela_sicingr70
        into :sicingr70_pagado;

        sicingr70_saldo = sicingr70_neto - sicingr70_pagado;

        select coalesce(tmp_sicingr70_notascredito.credito, 0)
        from tmp_sicingr70_notascredito
        where tmp_sicingr70_notascredito.usuario = current_user
        and tmp_sicingr70_notascredito.folio = sicingr70_docnro
        into :credito;

        sicingr70_saldo = sicingr70_saldo - credito;

        select coalesce(sum(tmp_sicingr70_notascredito.credito), 0)
        from tmp_sicingr70_notascredito
        where tmp_sicingr70_notascredito.usuario = current_user
        and tmp_sicingr70_notascredito.folio = :sicingr70_docnro
        into :sicingr70_notacredito;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR60 (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    ID_SICINGR60 BIGINT,
    SICINGR60_IMPORTE DOUBLE PRECISION,
    SICINGR60_FAPL TIMESTAMP,
    IMPORTE_TOTAL DOUBLE PRECISION,
    SICINGR60_AJUSTE DOUBLE PRECISION,
    BANCO_CUENTA VARCHAR(1250) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    FOR select
    SICCONT10_CAB_POLIZAS.siccont10_docnro,
    SICCONT10_CAB_POLIZAS.siccont10_fcta,
    SICINGR60_CAB_DEPOSITOS.rela_socmain01,
    SICINGR60_CAB_DEPOSITOS.rela_socmain21,
    SICINGR60_CAB_DEPOSITOS.rela_socusua01,
    SICINGR60_CAB_DEPOSITOS.rela_siccont10,
    SICINGR60_CAB_DEPOSITOS.rela_socmain05,
    SICINGR60_CAB_DEPOSITOS.id_SICINGR60,
    SICINGR60_CAB_DEPOSITOS.SICINGR60_importe,
    SICINGR60_CAB_DEPOSITOS.sicingr60_ajuste,
    SICINGR60_CAB_DEPOSITOS.SICINGR60_fapl,
    (SELECT sum(sicingr50_det_ctacte.sicingr50_importe)
     FROM sicingr61_det_DEPOSITOS
     INNER join sicingr50_det_ctacte ON (sicingr50_det_ctacte.id_sicingr50 = sicingr61_det_DEPOSITOS.rela_sicingr50)
     WHERE sicingr61_det_DEPOSITOS.rela_SICINGR60 = SICINGR60_CAB_DEPOSITOS.id_SICINGR60
    )
    from SICINGR60_CAB_DEPOSITOS
    INNER JOIN SICCONT10_CAB_POLIZAS ON (SICCONT10_CAB_POLIZAS.ID_SICCONT10 = SICINGR60_CAB_DEPOSITOS.rela_siccont10)
    WHERE SICINGR60_CAB_DEPOSITOS.rela_socmain01 = :rela_socmain01x
    and SICINGR60_CAB_DEPOSITOS.rela_socmain21 = :RELA_SOCMAIN21X
    AND  SICCONT10_CAB_POLIZAS.siccont10_fcta between :fecha_desde and :fecha_hasta
    INTO :SICCONT10_DOCNRO,
         :SICCONT10_FCTA,
         :RELA_SOCMAIN01,
         :RELA_SOCMAIN21,
         :RELA_SOCUSUA01,
         :RELA_SICCONT10,
         :rela_socmain05,
         :ID_SICINGR60,
         :SICINGR60_IMPORTE,
         :sicingr60_ajuste,
         :SICINGR60_FAPL,
         :IMPORTE_TOTAL

    DO
    BEGIN
        Select GRD_SOCMAIN05.ve
        from GRD_SOCMAIN05
        WHERE GRD_SOCMAIN05.id_socmain05 = :rela_socmain05
        into :banco_cuenta;

        IMPORTE_TOTAL = IMPORTE_TOTAL + sicingr60_ajuste;
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR70_CFDIS_FILT (
    ID_SOCMAIN01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE,
    FILTRO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MARCA INTEGER,
    NOVEDAD VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR70 BIGINT,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE,
    SICINGR74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_SMX_QRCODE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_UUID DOUBLE PRECISION,
    SICINGR70_SUBTOTAL DOUBLE PRECISION,
    SICINGR70_DESCUENTO DOUBLE PRECISION,
    SICINGR70_TOTAL DOUBLE PRECISION,
    SICINGR70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    SICINGR70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    SICINGR70_TOTIMP_LOCALES DOUBLE PRECISION,
    SICINGR70_NETO DOUBLE PRECISION,
    MONEDA VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USOCFDI VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FORMAPAGO VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODOPAGO VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPOCOMPROBANTE VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    filtro = upper(:filtro);

    FOR SELECT
    sicingr70_cab_facturacion.id_sicingr70,
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_fecha,
    sicingr70_cab_facturacion.sicingr70_status,
    sicingr74_dep_cfdis.sicingr74_uuid,
    sicingr74_dep_cfdis.sicingr74_uuid_smx,
    sicingr74_dep_cfdis.sicingr74_uuid_smx_qrcode,
    sicingr74_dep_cfdis.sicingr74_uuid_importe,
    sicingr70_cab_facturacion.sicingr70_subtotal,
    sicingr70_cab_facturacion.sicingr70_descuento,
    sicingr70_cab_facturacion.sicingr70_total,
    sicingr70_cab_facturacion.sicingr70_totimp_traslados,
    sicingr70_cab_facturacion.sicingr70_totimp_retenidos,
    sicingr70_cab_facturacion.sicingr70_totimp_locales,
    sicingr70_cab_facturacion.sicingr70_neto,
    moneda.socsyst10_descripcion,
    uscfdi.socsyst10_descripcion,
    fdpago.socsyst10_descripcion,
    mdpago.socsyst10_descripcion,
    tcompr.socsyst10_descripcion
    FROM sicingr70_cab_facturacion
    inner join socsyst10_det_remoto tcompr on ( tcompr.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01 )
    inner join socsyst10_det_remoto moneda on ( moneda.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01 )
    inner join socsyst10_det_remoto fdpago on ( fdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_fdp01 )
    inner join socsyst10_det_remoto mdpago on ( mdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
    inner join socsyst10_det_remoto uscfdi on ( uscfdi.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ucf01 )
    inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
    inner join cbo_sicingr01_id on ( cbo_sicingr01_id.id_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01 )
    where sicingr70_cab_facturacion.rela_socmain01 = :id_socmain01
    and cbo_sicingr01_id.rela_socmain01 = :id_socmain01
    and sicingr70_cab_facturacion.sicingr70_fecha between :fecha_desde and :fecha_hasta
    and upper(cbo_sicingr01_id.entidad || iif(sicingr70_cab_facturacion.sicingr70_status is null, '', sicingr70_cab_facturacion.sicingr70_status))  like '%' || :filtro || '%'
    into :id_sicingr70,
         :entidad,
         :rfc,
         :sicingr70_docnro,
         :sicingr70_fecha,
         :novedad,
         :sicingr74_uuid,
         :sicingr74_uuid_smx,
         :sicingr74_uuid_smx_qrcode,
         :importe_uuid,
         :sicingr70_subtotal,
         :sicingr70_descuento,
         :sicingr70_total,
         :sicingr70_totimp_traslados,
         :sicingr70_totimp_retenidos,
         :sicingr70_totimp_locales,
         :sicingr70_neto,
         :moneda,
         :usocfdi,
         :formapago,
         :metodopago,
         :tipocomprobante
    do
    begin
        marca = 1;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR70_CFDIS_PEND (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICINGR70 BIGINT,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE,
    NOVEDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_SUBTOTAL DOUBLE PRECISION,
    SICINGR70_DESCUENTO DOUBLE PRECISION,
    SICINGR70_TOTAL DOUBLE PRECISION,
    SICINGR70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    SICINGR70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    SICINGR70_TOTIMP_LOCALES DOUBLE PRECISION,
    SICINGR70_NETO DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USOCFDI VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODOPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPOCOMPROBANTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    FOR SELECT
    1,
    sicingr70_cab_facturacion.id_sicingr70,
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_fecha,
    sicingr70_cab_facturacion.sicingr70_status,
    sicingr70_cab_facturacion.sicingr70_subtotal,
    sicingr70_cab_facturacion.sicingr70_descuento,
    sicingr70_cab_facturacion.sicingr70_total,
    sicingr70_cab_facturacion.sicingr70_totimp_traslados,
    sicingr70_cab_facturacion.sicingr70_totimp_retenidos,
    sicingr70_cab_facturacion.sicingr70_totimp_locales,
    sicingr70_cab_facturacion.sicingr70_neto,
    moneda.socsyst10_descripcion,
    uscfdi.socsyst10_descripcion,
    fdpago.socsyst10_descripcion,
    mdpago.socsyst10_descripcion,
    tcompr.socsyst10_descripcion
    FROM sicingr70_cab_facturacion
    inner join socsyst10_det_remoto tcompr on ( tcompr.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01 )
    inner join socsyst10_det_remoto moneda on ( moneda.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01 )
    inner join socsyst10_det_remoto fdpago on ( fdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_fdp01 )
    inner join socsyst10_det_remoto mdpago on ( mdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
    inner join socsyst10_det_remoto uscfdi on ( uscfdi.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ucf01 )
    inner join cbo_sicingr01_id on ( cbo_sicingr01_id.id_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01 )
    where sicingr70_cab_facturacion.rela_socmain01 = :id_socmain01
    AND NOT EXISTS (select sicingr74_dep_cfdis.id_sicingr74
                    from sicingr74_dep_cfdis
                    where sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
    into :marca,
         :id_sicingr70,
         :entidad,
         :rfc,
         :sicingr70_docnro,
         :sicingr70_fecha,
         :novedad,
         :sicingr70_subtotal,
         :sicingr70_descuento,
         :sicingr70_total,
         :sicingr70_totimp_traslados,
         :sicingr70_totimp_retenidos,
         :sicingr70_totimp_locales,
         :sicingr70_neto,
         :moneda,
         :usocfdi,
         :formapago,
         :metodopago,
         :tipocomprobante
   DO
    BEGIN
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR70_SICINGR55 (
    RELA_SICINGR01 BIGINT,
    RELA_SICINGR51 BIGINT)
RETURNS (
    RELA_SICINGR70 BIGINT,
    ID_SICINGR55 BIGINT,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE,
    SICINGR70_NETO DOUBLE PRECISION,
    SICINGR70_PAGADO DOUBLE PRECISION,
    SICINGR70_SALDO DOUBLE PRECISION,
    SICINGR55_IMPORTE DOUBLE PRECISION)
AS
begin
    id_sicingr55 = 0;
    sicingr55_importe = 0.0;

    if (rela_sicingr51 <= 0) then
    begin
        for select
        sicingr70_cab_facturacion.id_sicingr70,
        sicingr70_cab_facturacion.sicingr70_docnro,
        sicingr70_cab_facturacion.sicingr70_fecha,
        sicingr70_cab_facturacion.sicingr70_neto
        from sicingr70_cab_facturacion
        where sicingr70_cab_facturacion.rela_sicingr01 = :rela_sicingr01
        order by sicingr70_cab_facturacion.sicingr70_docnro desc
        into :rela_sicingr70,
             :sicingr70_docnro,
             :sicingr70_fecha,
             :sicingr70_neto
        do
        begin
            select sum(sicingr55_det_facturas.sicingr55_importe)
            from sicingr55_det_facturas
            where sicingr55_det_facturas.rela_sicingr70 = :rela_sicingr70
            into :sicingr70_pagado;
    
            sicingr70_pagado = iif(sicingr70_pagado is null, 0.0, sicingr70_pagado);
            sicingr70_saldo = sicingr70_neto - sicingr70_pagado;

            if (sicingr70_saldo > 0) then
            begin
                id_sicingr55 = id_sicingr55 + (-1);
                suspend;
            end
        end
    end
    else
    begin
        for select
        sicingr55_det_facturas.rela_sicingr70,
        sicingr55_det_facturas.id_sicingr55,
        sicingr70_cab_facturacion.sicingr70_docnro,
        sicingr70_cab_facturacion.sicingr70_fecha,
        sicingr70_cab_facturacion.sicingr70_neto,
        sicingr55_det_facturas.sicingr55_importe
        from sicingr55_det_facturas
        inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr55_det_facturas.rela_sicingr70)
        where sicingr55_det_facturas.rela_sicingr51 = :rela_sicingr51
        order by sicingr70_cab_facturacion.sicingr70_docnro desc
        into :rela_sicingr70,
             :id_sicingr55,
             :sicingr70_docnro,
             :sicingr70_fecha,
             :sicingr70_neto,
             :sicingr55_importe
        do
        begin
            select sum(sicingr55_det_facturas.sicingr55_importe)
            from sicingr55_det_facturas
            where sicingr55_det_facturas.rela_sicingr70 = :rela_sicingr70
            into :sicingr70_pagado;

            sicingr70_saldo = sicingr70_neto - sicingr70_pagado;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR70_SICINGR88 (
    RELA_SICCONT10 BIGINT)
RETURNS (
    RELA_SICINGR85 BIGINT,
    RELA_SICINGR70 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    ID_SICCONT10_ANTICIPO BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICINGR53_IMPORTE DOUBLE PRECISION)
AS
begin
    rela_sicingr70 = null;

    select
    sicingr70_cab_facturacion.id_sicingr70
    from sicingr88_det_gastos3ros
    inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70 )
    inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
    inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicingr74_dep_cfdis.rela_sicxmls41 )
    where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
    into :rela_sicingr70;

    if (rela_sicingr70 is not null) then
    begin
        rela_sicingr85 = null;

        select
        sicingr88_det_gastos3ros.rela_sicingr85,
        sicingr88_det_gastos3ros.rela_socmain05
        from sicingr88_det_gastos3ros
        where sicingr88_det_gastos3ros.rela_sicingr70 = :rela_sicingr70
        into :rela_sicingr85,
             :rela_socmain05;

        if (rela_sicingr85 is not null) then
        begin
            for select
            sicingr54_dep_anticipos.rela_siccont10,
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta,
            SICINGR53_DET_REFANTICIPOS.sicingr53_importe
            from SICINGR53_DET_REFANTICIPOS
            inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = SICINGR53_DET_REFANTICIPOS.rela_sicingr51 )
            inner join sicingr54_dep_anticipos on ( sicingr54_dep_anticipos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51 )
            inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr54_dep_anticipos.rela_siccont10 )
            where SICINGR53_DET_REFANTICIPOS.rela_sicingr85 = :rela_sicingr85
            into :id_siccont10_anticipo,
                 :siccont10_docnro,
                 :siccont10_fcta,
                 :sicingr53_importe
            do
            begin
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR72_X_CONCEPTO (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR95 BIGINT)
RETURNS (
    RELA_SICINGR95 BIGINT,
    RELA_SICINGR90 BIGINT,
    RELA_SICXMLS02 BIGINT,
    ID_SICINGR96 BIGINT,
    SICINGR96_FAPL TIMESTAMP,
    ZONA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPUESTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR90_TASA DOUBLE PRECISION,
    IMPORTE_CALCULO DOUBLE PRECISION,
    IMPORTE_BASE DOUBLE PRECISION,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IVA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODALIDAD_CALCULO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable IVA_FLAG integer;
declare variable RELA_SOCSYST10_MCI01 bigint;
begin
    for select
    grd_sicingr90.rela_socsyst10_mci01,
    grd_sicingr90.rela_sicxmls02,
    grd_sicingr90.id_sicingr90,
    grd_sicingr90.zona,
    grd_sicingr90.sicingr90_descripcion,
    grd_sicingr90.tipo,
    grd_sicingr90.sicingr90_tasa,
    grd_sicingr90.siccont02_codigo_ext,
    grd_sicingr90.siccont02_descripcion,
    grd_sicingr90.sicingr90_modo
    from grd_sicingr90
    where grd_sicingr90.rela_socmain01 = :id_socmain01
    into :rela_socsyst10_mci01,
         :rela_sicxmls02,
         :rela_sicingr90,
         :zona,
         :impuesto,
         :tipo,
         :sicingr90_tasa,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :factor
    do
    begin
        importe_calculo = 0.00;
        importe_base = 0.00;
        id_sicingr96 = null;

        select
        sicingr96_det_impuestos.id_sicingr96,
        sicingr96_det_impuestos.sicingr96_fapl,
        sicxmls04_det_conceptos.sicxmls04_excento
        from sicingr96_det_impuestos
        inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = sicingr96_det_impuestos.rela_sicingr95 )
        inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
        where sicingr96_det_impuestos.rela_sicingr90 = :rela_sicingr90
        and sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
        into :id_sicingr96,
             :sicingr96_fapl,
             :iva_flag;

        if (id_sicingr96 is not null) then
        begin
            rela_sicingr95 = :id_sicingr95;

            if (iva_flag = 0) then
                iva = 'Exento';
            else if (iva_flag = 1) then
                iva = 'IVA 0%';
            else
                iva = 'IVA';

            select socsyst10_det_entradas.socsyst10_codigo
            from socsyst10_det_entradas
            where socsyst10_det_entradas.id_socsyst10 = :rela_socsyst10_mci01
            into :modalidad_calculo;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR82 (
    RELA_SICINGR81X BIGINT)
RETURNS (
    RELA_SICINGR81 BIGINT,
    RELA_SOCSYST10_CUM01 BIGINT,
    RELA_SOCSYST10_CPO01 BIGINT,
    ID_SICINGR82 BIGINT,
    SICINGR82_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR82_CANTIDAD DOUBLE PRECISION,
    SOCSYST10_CODIGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR82_FAPL TIMESTAMP)
AS
begin
    for select
    SICINGR82_DET_TRANSPORTE.rela_sicingr81,
    SICINGR82_DET_TRANSPORTE.rela_socsyst10_cum01,
    SICINGR82_DET_TRANSPORTE.rela_socsyst10_cpo01,
    SICINGR82_DET_TRANSPORTE.id_sicingr82,
    SICINGR82_DET_TRANSPORTE.sicingr82_concepto,
    SICINGR82_DET_TRANSPORTE.sicingr82_cantidad,
    SICINGR82_DET_TRANSPORTE.sicingr82_fapl
    from SICINGR82_DET_TRANSPORTE
    WHERE SICINGR82_DET_TRANSPORTE.rela_sicingr81 = :rela_sicingr81x
    into :RELA_SICINGR81,
         :rela_socsyst10_cum01,
         :rela_socsyst10_cpo01,
         :ID_SICINGR82,
         :SICINGR82_CONCEPTO,
         :SICINGR82_CANTIDAD,
         :SICINGR82_FAPL
    do
    begin
        if (rela_socsyst10_cpo01 is not null) then
        begin
            select cbo_socsyst10_cpo01.socsyst10_codigo
            from cbo_socsyst10_cpo01
            where cbo_socsyst10_cpo01.id_socsyst10 = :rela_socsyst10_cpo01
            into :socsyst10_codigo;

            select cbo_socsyst10_cum01.socsyst10_descripcion
            from cbo_socsyst10_cum01
            where cbo_socsyst10_cum01.id_socsyst10 = :rela_socsyst10_cum01
            into :socsyst10_descripcion;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR85 (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICINGR01 BIGINT,
    ID_SICINGR85 BIGINT,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR85_IMPGASTOS DOUBLE PRECISION,
    SICINGR85_IMPANTICIPOS INTEGER,
    SICINGR85_FCERRADO TIMESTAMP,
    SICINGR85_FAPL TIMESTAMP,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE)
AS
begin
    for select
    sicingr85_cab_gastos3ros.rela_socmain01,
    sicingr85_cab_gastos3ros.rela_socmain21,
    sicingr85_cab_gastos3ros.rela_socusua01,
    sicingr85_cab_gastos3ros.rela_sicingr01,
    sicingr85_cab_gastos3ros.id_sicingr85,
    sicingr85_cab_gastos3ros.sicingr85_referencia,
    ( select sum(sicingr86_det_gastos3ros.sicingr86_importe)
          from sicingr86_det_gastos3ros
          where sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
    ( select sum(sicingr53_det_refanticipos.sicingr53_importe)
          from sicingr53_det_refanticipos
          where sicingr53_det_refanticipos.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85
        ),
    sicingr85_cab_gastos3ros.sicingr85_fcerrado,
    sicingr85_cab_gastos3ros.sicingr85_fapl
    from sicingr85_cab_gastos3ros
    where sicingr85_cab_gastos3ros.rela_socmain01 = :id_socmain01
    and sicingr85_cab_gastos3ros.rela_sicingr01 = :id_sicingr01
    and cast(sicingr85_cab_gastos3ros.sicingr85_fapl as date) between :fecha_desde and :fecha_hasta
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :rela_sicingr01,
         :id_sicingr85,
         :sicingr85_referencia,
         :sicingr85_impgastos,
         :sicingr85_impanticipos,
         :sicingr85_fcerrado,
         :sicingr85_fapl
    do
    begin
        siccont10_docnro = null;
        siccont10_fcta = null;
        sicingr70_docnro = null;
        sicingr70_fecha = null;

        if (sicingr85_impgastos is null) then
            sicingr85_impgastos = 0;

        if (sicingr85_impanticipos is null) then
            sicingr85_impanticipos = 0;

        select
        sicingr70_cab_facturacion.sicingr70_docnro,
        sicingr70_cab_facturacion.sicingr70_fecha
        from sicingr88_det_gastos3ros
        inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70 )
        where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
        into :sicingr70_docnro,
             :sicingr70_fecha;

        select
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta
        from sicingr88_det_gastos3ros
        inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70 )
        inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
        inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicingr74_dep_cfdis.rela_sicxmls41 )
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicxmls41_det_migracion.rela_siccont10 )
        where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
        into :siccont10_docnro,
             :siccont10_fcta;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95 (
    RELA_SOCMAIN01X BIGINT,
    BUSCARTXT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    SAT_DESCRIPCION VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICXMLS01 BIGINT,
    RELA_SICXMLS04 BIGINT,
    ID_SICINGR95 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_IMPORTE DOUBLE PRECISION,
    SICINGR95_FAPL TIMESTAMP,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DEDUCIBLE VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INACTIVO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SICINGR95_INACTIVO integer;
begin
    buscartxt = upper(buscartxt);

    for select
    '(' || socsyst10_det_remoto.socsyst10_codigo || ') ' || socsyst10_det_remoto.socsyst10_descripcion,
    sicxmls01_cab_parametros.rela_socmain01,
    sicingr95_cab_conceptos.rela_sicxmls01,
    sicingr95_cab_conceptos.rela_sicxmls04,
    sicingr95_cab_conceptos.id_sicingr95,
    sicingr95_cab_conceptos.sicingr95_codigo,
    sicingr95_cab_conceptos.sicingr95_descripcion,
    sicingr95_cab_conceptos.sicingr95_importe,
    sicingr95_cab_conceptos.sicingr95_fapl,
    sicingr95_cab_conceptos.sicingr95_inactivo,
    iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 0, 'Excento', iif(sicxmls04_det_conceptos.SICXMLS04_EXCENTO = 1, 'Iva 0%', 'Iva')),
    iif(sicxmls04_det_conceptos.sicxmls04_deducible = 0, 'No', 'Si'),
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    siccont02_arb_planctas.siccont02_codagrup
    from sicingr95_cab_conceptos
    inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
    inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02 )
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01x
    and upper(socsyst10_det_remoto.socsyst10_codigo || socsyst10_det_remoto.socsyst10_descripcion ||
         sicingr95_cab_conceptos.sicingr95_codigo || sicingr95_cab_conceptos.sicingr95_descripcion
         ) like '%' || :buscartxt || '%'
    into :SAT_DESCRIPCION,
         :RELA_SOCMAIN01,
         :RELA_SICXMLS01,
         :RELA_SICXMLS04,
         :ID_SICINGR95,
         :SICINGR95_CODIGO,
         :SICINGR95_DESCRIPCION,
         :SICINGR95_IMPORTE,
         :SICINGR95_FAPL,
         :sicingr95_inactivo,
         :TIPO,
         :DEDUCIBLE,
         :SICCONT02_CODIGO_EXT,
         :SICCONT02_DESCRIPCION,
         :SICCONT02_CODAGRUP
    do
    begin
        if (sicingr95_inactivo is null or sicingr95_inactivo = 0) then
            inactivo = 'No';
        else
            inactivo = 'Si';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95_INFO (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    BUSCAR VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCSYST12 BIGINT,
    RELA_SOCSYST10_CDP01 BIGINT,
    SOLO_SUCURSAL INTEGER,
    SOLO_SINREGLAS INTEGER,
    TIPO_PRODUCTO INTEGER)
RETURNS (
    MARCA INTEGER,
    ID_SICINGR95 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_IMPORTE DOUBLE PRECISION,
    PYMALMA02_CANTIDAD DOUBLE PRECISION,
    PYMALMA02_CANTIDAD_GRAL DOUBLE PRECISION,
    SICINGR95_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_COSTO DOUBLE PRECISION)
AS
declare variable ID_SICINGR97 bigint;
declare variable EXISTE_EN_SUCURSAL integer;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable IMPORTE_PRODUCTO double precision;
declare variable SQL_SELECT varchar(8000);
begin
    marca = 1;
    buscar = iif(buscar is null, '', buscar);
    buscar = upper(trim(buscar));

    if (solo_sinreglas = 0) then
    begin
        sql_select = 'SELECT
                     sicingr95_cab_conceptos.rela_socsyst10_ctm01,
                     sicingr95_cab_conceptos.id_sicingr95,
                     sicingr95_cab_conceptos.sicingr95_codigo,
                     sicingr95_cab_conceptos.sicingr95_descripcion,
                     sicingr95_cab_conceptos.sicingr95_notas
                     FROM sicingr95_cab_conceptos
                     INNER JOIN sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 ) ' ||
                     'where sicxmls01_cab_parametros.rela_socmain01 = ' || :rela_socmain01 ||
                     ' and iif(sicingr95_cab_conceptos.sicingr95_tipo is null, 0, sicingr95_cab_conceptos.sicingr95_tipo) = ' || :tipo_producto ||
                     ' and (upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)) like ''' || :buscar || '%''' ||
                     ' or  upper(trim(sicingr95_cab_conceptos.sicingr95_descripcion)) like ''' || :buscar || '%'')';
    end
    else
    begin
        sql_select = 'SELECT
                     sicingr95_cab_conceptos.rela_socsyst10_ctm01,
                     sicingr95_cab_conceptos.id_sicingr95,
                     sicingr95_cab_conceptos.sicingr95_codigo,
                     sicingr95_cab_conceptos.sicingr95_descripcion,
                     sicingr95_cab_conceptos.sicingr95_notas
                     FROM sicingr95_cab_conceptos
                     INNER JOIN sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 ) ' ||
                     'where sicxmls01_cab_parametros.rela_socmain01 = ' || :rela_socmain01 ||
                     ' and iif(sicingr95_cab_conceptos.sicingr95_tipo is null, 0, sicingr95_cab_conceptos.sicingr95_tipo) = ' || :tipo_producto ||
                     ' and not exists (select first 1 sicingr95_cab_conceptos.id_sicingr95' ||
                     ' from pymvent16_det_xreglas_p where pymvent16_det_xreglas_p.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95)' ||
                     ' and (upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)) like ''' || :buscar || '%''' ||
                     ' or  upper(trim(sicingr95_cab_conceptos.sicingr95_descripcion)) like ''' || :buscar || '%'')';
    end

    FOR EXECUTE STATEMENT :sql_select
    /*SELECT
    sicingr95_cab_conceptos.rela_socsyst10_ctm01,
    sicingr95_cab_conceptos.id_sicingr95,
    sicingr95_cab_conceptos.sicingr95_codigo,
    sicingr95_cab_conceptos.sicingr95_descripcion,
    sicingr95_cab_conceptos.sicingr95_notas
    FROM sicingr95_cab_conceptos
    INNER JOIN sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and (upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)) like :buscar || '%'
    or  upper(trim(sicingr95_cab_conceptos.sicingr95_descripcion)) like :buscar || '%') */
    into :rela_socsyst10_ctm01,
         :id_sicingr95,
         :sicingr95_codigo,
         :sicingr95_descripcion,
         :sicingr95_notas
    do
    begin
        moneda = 'MXN';

        if (rela_socsyst10_ctm01 is not null) then
            select cbo_socsyst10_ctm01.socsyst10_codigo
            from cbo_socsyst10_ctm01
            where cbo_socsyst10_ctm01.id_socsyst10 = :rela_socsyst10_ctm01
            into :moneda;

        select
        PRD_SICINGR95_IMPUESTOS_CALCULO.importe_neto,
        PRD_SICINGR95_IMPUESTOS_CALCULO.importe_producto
        from PRD_SICINGR95_IMPUESTOS_CALCULO(:id_sicingr95, null)
        into :sicingr95_importe,
             :importe_producto;

        existe_en_sucursal = 0;
        pymalma02_cantidad = 0.00;
        pymalma02_cantidad_gral = 0.00;

        if (rela_socmain21 is not null and rela_socmain21 > 0) then
        begin
            pymalma02_cantidad = null;
            pymalma02_cantidad_gral = null;

            select sum(pymalma02_det_stock.pymalma02_cantidad)
            from pymalma01_cab_stock
            inner join pymalma02_det_stock on ( pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01 )
            where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
            and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
            and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
            into :pymalma02_cantidad;

            if (pymalma02_cantidad is null) then
                pymalma02_cantidad = 0.00;
            else
                existe_en_sucursal = 1;

            select sum(pymalma02_det_stock.pymalma02_cantidad)
            from pymalma01_cab_stock
            inner join pymalma02_det_stock on ( pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01 )
            where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
            and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
            into :pymalma02_cantidad_gral;

            if (pymalma02_cantidad_gral is null) then
                pymalma02_cantidad_gral = 0.00;
        end

        importe_costo = null;

        select
        sum(sicingr98_det_importes.sicingr98_importe) / count(sicingr98_det_importes.id_sicingr98)
        from sicingr98_det_importes
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01 )
        where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'CONCEP-XMARGEN'
        into :importe_costo;

        if (importe_costo is null) then
            importe_costo = :importe_producto;

        /* ------------------------------------------------------------------------------------------------------------ */

        if (RELA_SOCSYST12 is null) then
        begin
            if (solo_sucursal = 0) then
               suspend;
            else if (existe_en_sucursal = 1) then
               suspend;
        end
        else
        begin
            id_sicingr97 = null;

            select first 1 sicingr97_det_clasificacion.id_sicingr97
            from sicingr97_det_clasificacion
            where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
            and sicingr97_det_clasificacion.rela_socsyst12 = :rela_socsyst12
            and sicingr97_det_clasificacion.rela_socsyst10_cdp01 = :rela_socsyst10_cdp01
            into :id_sicingr97;

            if (id_sicingr97 is not null) then
               suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95_INFO_CLASS (
    ID_SICINGR95 BIGINT)
RETURNS (
    RELA_SOCSYST12 BIGINT,
    RELA_SOCSYST10_CDP01 BIGINT,
    ID_SICINGR97 BIGINT,
    CLASIFICACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    for select
    sicingr97_det_clasificacion.rela_socsyst12,
    sicingr97_det_clasificacion.rela_socsyst10_cdp01,
    sicingr97_det_clasificacion.id_sicingr97,
    socsyst10_det_entradas.socsyst10_descripcion,
    socsyst12_det_cla.socsyst12_descripcion
    from sicingr97_det_clasificacion
    inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
    where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
    into :rela_socsyst12,
         :rela_socsyst10_cdp01,
         :id_sicingr97,
         :clasificacion,
         :valor
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95_INFO_INVEN (
    RELA_SOCMAIN01 BIGINT,
    ID_SICINGR95 BIGINT)
RETURNS (
    ID_SOCMAIN21 BIGINT,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA02_CANTIDAD DOUBLE PRECISION)
AS
begin
    for select
    pymalma01_cab_stock.rela_socmain21,
    socmain21_arb_organizacion.socmain21_descripcion,
    sum(pymalma02_det_stock.pymalma02_cantidad)
    from pymalma01_cab_stock
    inner join socmain21_arb_organizacion on ( socmain21_arb_organizacion.id_socmain21 = pymalma01_cab_stock.rela_socmain21 )
    inner join pymalma02_det_stock on ( pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01 )
    where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
    and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
    group by pymalma01_cab_stock.rela_socmain21,
             socmain21_arb_organizacion.socmain21_descripcion
    into :id_socmain21,
         :socmain21_descripcion,
         :pymalma02_cantidad
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95_INFO_INVEN_MTCLVS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR95 BIGINT,
    RELA_SOCMAIN21 BIGINT)
RETURNS (
    ID_PYMALMA20 BIGINT,
    PYMALMA20_MODELO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_TALLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_COLOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_VENCIMIENTO DATE,
    PYMALMA20_SERIE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_SERIE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA02_CANTIDAD DOUBLE PRECISION)
AS
begin
    for select
    max(pymalma20_dep_mtclvs.id_pymalma20),
    pymalma20_dep_mtclvs.pymalma20_modelo,
    pymalma20_dep_mtclvs.pymalma20_talla,
    pymalma20_dep_mtclvs.pymalma20_color,
    pymalma20_dep_mtclvs.pymalma20_lote_desde,
    pymalma20_dep_mtclvs.pymalma20_lote_hasta,
    pymalma20_dep_mtclvs.pymalma20_vencimiento,
    pymalma20_dep_mtclvs.pymalma20_serie_desde,
    pymalma20_dep_mtclvs.pymalma20_serie_hasta,
    sum(pymalma02_det_stock.pymalma02_cantidad)
    from pymalma01_cab_stock
    inner join pymalma02_det_stock on ( pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01 )
    inner join pymalma20_dep_mtclvs on ( pymalma20_dep_mtclvs.rela_pymalma02 = pymalma02_det_stock.id_pymalma02 )
    where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
    and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
    and pymalma02_det_stock.rela_sicingr95 = :rela_sicingr95
    group by
    pymalma20_dep_mtclvs.pymalma20_modelo,
    pymalma20_dep_mtclvs.pymalma20_talla,
    pymalma20_dep_mtclvs.pymalma20_color,
    pymalma20_dep_mtclvs.pymalma20_lote_desde,
    pymalma20_dep_mtclvs.pymalma20_lote_hasta,
    pymalma20_dep_mtclvs.pymalma20_vencimiento,
    pymalma20_dep_mtclvs.pymalma20_serie_desde,
    pymalma20_dep_mtclvs.pymalma20_serie_hasta
    into :id_pymalma20,
         :pymalma20_modelo,
         :pymalma20_talla,
         :pymalma20_color,
         :pymalma20_lote_desde,
         :pymalma20_lote_hasta,
         :pymalma20_vencimiento,
         :pymalma20_serie_desde,
         :pymalma20_serie_hasta,
         :pymalma02_cantidad
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95_INFO_LPREC (
    ID_SICINGR95 BIGINT)
RETURNS (
    ID_PYMVENT11 BIGINT,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT10_PORCENTAJE DOUBLE PRECISION,
    PYMVENT11_IMPORTE DOUBLE PRECISION)
AS
begin
    for select
    pymvent11_det_xproductos.id_pymvent11,
    socsyst10_det_entradas.socsyst10_descripcion,
    PYMVENT10_CAB_LISTAPRECIOS.pymvent10_porcentaje,
    pymvent11_det_xproductos.pymvent11_importe
    from PYMVENT10_CAB_LISTAPRECIOS
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = PYMVENT10_CAB_LISTAPRECIOS.rela_socsyst10_lpr01 )
    inner join pymvent11_det_xproductos on ( pymvent11_det_xproductos.rela_pymvent10 = PYMVENT10_CAB_LISTAPRECIOS.id_pymvent10 )
    where pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95
    into :id_pymvent11,
         :socsyst10_descripcion,
         :pymvent10_porcentaje,
         :pymvent11_importe
    do
    begin
        select PRD_SICINGR95_IMPUESTOS_CALCULO.importe_neto
        from PRD_SICINGR95_IMPUESTOS_CALCULO(:id_sicingr95, :pymvent11_importe)
        into :pymvent11_importe;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR95_INFO_OTROS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    MODO INTEGER,
    SOLO_SINREGLAS INTEGER)
RETURNS (
    MARCA INTEGER,
    ID_SICINGR95 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_IMPORTE DOUBLE PRECISION,
    PYMALMA02_CANTIDAD DOUBLE PRECISION,
    PYMALMA02_CANTIDAD_GRAL DOUBLE PRECISION,
    SICINGR95_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_COSTO DOUBLE PRECISION)
AS
declare variable EXISTE bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable IMPORTE_PRODUCTO double precision;
begin
    /*
        modo :
                0, Sin Inventario
                1, Con Inventario 0
                2, Con Inventario Menos de 0
                3, Con Inventario Mayor a 0
                4, Sin Clasificacion
                5, Sin Lista de Precios
                6, Productos Moneda Extranjera
    
    */

    /* 0, Sin Inventario */

    marca = 1;

    if (modo = 0) then
    begin
        for SELECT
        sicingr95_cab_conceptos.rela_socsyst10_ctm01,
        sicingr95_cab_conceptos.id_sicingr95,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion,
        sicingr95_cab_conceptos.sicingr95_notas
        FROM sicingr95_cab_conceptos
        INNER JOIN sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
