CREATE OR ALTER PROCEDURE GRD_SICINGR95_XCLASS (
    MODALIDAD INTEGER,
    RELA_SOCSYST10_CDP01 BIGINT,
    RELA_SOCSYST12 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICINGR95 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_IMPORTE DOUBLE PRECISION)
AS
begin
    /*
        MODALIDAD
            0 = ALTA
            1 = MODIFICACION O BAJA
    */

    if (modalidad = 0) then
    begin
        for select
        1,
        sicingr95_cab_conceptos.id_sicingr95,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion,
        sicingr95_cab_conceptos.sicingr95_importe
        from sicingr95_cab_conceptos
        inner join sicingr97_det_clasificacion on ( sicingr97_det_clasificacion.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95 )
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
        inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
        where sicingr97_det_clasificacion.rela_socsyst10_cdp01 = :rela_socsyst10_cdp01
        and sicingr97_det_clasificacion.rela_socsyst12 = :rela_socsyst12
        and not exists ( select first 1 pymvent16_det_xreglas_p.id_pymvent16
                         from pymvent16_det_xreglas_p
                         where pymvent16_det_xreglas_p.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95
                        )
        order by sicingr95_cab_conceptos.sicingr95_descripcion
        into :marca,
             :id_sicingr95,
             :sicingr95_codigo,
             :sicingr95_descripcion,
             :sicingr95_importe
        do
        begin
            suspend;
        end    
    end
    else
    begin
        for select
        1,
        sicingr95_cab_conceptos.id_sicingr95,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion,
        sicingr95_cab_conceptos.sicingr95_importe
        from sicingr95_cab_conceptos
        inner join sicingr97_det_clasificacion on ( sicingr97_det_clasificacion.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95 )
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
        inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
        inner join pymvent16_det_xreglas_p on ( sicingr95_cab_conceptos.id_sicingr95 = pymvent16_det_xreglas_p.rela_sicingr95 )
        where sicingr97_det_clasificacion.rela_socsyst10_cdp01 = :rela_socsyst10_cdp01
        and sicingr97_det_clasificacion.rela_socsyst12 = :rela_socsyst12
        order by sicingr95_cab_conceptos.sicingr95_descripcion
        into :marca,
             :id_sicingr95,
             :sicingr95_codigo,
             :sicingr95_descripcion,
             :sicingr95_importe
        do
        begin
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICINGR96_CHECK (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR95 BIGINT)
RETURNS (
    MARCA INTEGER,
    RELA_SICINGR95 BIGINT,
    RELA_SICINGR90 BIGINT,
    ID_SICINGR96 BIGINT,
    SICINGR96_FAPL TIMESTAMP,
    ZONA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR90_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR90_TASA DOUBLE PRECISION,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CONTADOR_ID bigint;
begin
    contador_id = 0;

    for select
    grd_sicingr90.id_sicingr90,
    grd_sicingr90.zona,
    grd_sicingr90.sicingr90_descripcion,
    grd_sicingr90.tipo,
    grd_sicingr90.sicingr90_tasa,
    grd_sicingr90.siccont02_codigo_ext,
    grd_sicingr90.siccont02_descripcion,
    grd_sicingr90.siccont02_codagrup,
    grd_sicingr90.sicingr90_modo
    from grd_sicingr90
    where grd_sicingr90.rela_socmain01 = :id_socmain01
    into :rela_sicingr90,
         :zona,
         :sicingr90_descripcion,
         :tipo,
         :sicingr90_tasa,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_codagrup,
         :modo
    do
    begin
        marca = 0;
        id_sicingr96 = null;

        if (id_sicingr95 is not null and id_sicingr95 = -1) then
        begin
            contador_id = contador_id - 1;
            id_sicingr96 = contador_id;
        end
        else
        begin
            select
            sicingr96_det_impuestos.id_sicingr96,
            sicingr96_det_impuestos.sicingr96_fapl
            from sicingr96_det_impuestos
            where sicingr96_det_impuestos.rela_sicingr90 = :rela_sicingr90
            and sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
            into :id_sicingr96,
                 :sicingr96_fapl;
    
            if (id_sicingr96 is not null) then
            begin
                marca = 1;
                rela_sicingr95 = :id_sicingr95;
            end
            else
            begin
                contador_id = contador_id - 1;
                id_sicingr96 = contador_id;
            end
        end


        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI05_ABM (
    ID_SICNOMI01 BIGINT)
RETURNS (
    RELA_SOCSYST10_CNO01 BIGINT,
    RELA_SICNOMI01 BIGINT,
    ID_SICNOMI05 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI05_VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_GRUPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI05_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_CONTA integer;
begin
    id_conta = 0;
    rela_sicnomi01 = id_sicnomi01;

    FOR SELECT
    CBO_SOCSYST10_CNO01.id_socsyst10,
    CBO_SOCSYST10_CNO01.socsyst10_codigo,
    CBO_SOCSYST10_CNO01.socsyst10_descripcion,
    CBO_SOCSYST10_CNO01.socsyst10_grupo
    FROM CBO_SOCSYST10_CNO01
    INTO :rela_socsyst10_cno01,
         :socsyst10_codigo,
         :socsyst10_descripcion,
         :socsyst10_grupo
    do
    begin
        id_sicnomi05 = null;

        select
        sicnomi05_det_nomina.id_sicnomi05,
        sicnomi05_det_nomina.sicnomi05_valor,
        sicnomi05_det_nomina.sicnomi05_descripcion
        from sicnomi05_det_nomina
        where sicnomi05_det_nomina.rela_sicnomi01 = :id_sicnomi01
        and sicnomi05_det_nomina.rela_socsyst10_cno01 = :rela_socsyst10_cno01
        into :id_sicnomi05,
             :sicnomi05_valor,
             :sicnomi05_descripcion;

        if (id_sicnomi05 is null) then
        begin
            id_conta = id_conta - 1;
            id_sicnomi05 = id_conta;
        end
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI50 (
    ID_SOCMAIN01 BIGINT,
    ID_SICNOMI01 BIGINT)
RETURNS (
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICNOMI01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    SICNOMI50_IMPORTE DOUBLE PRECISION,
    ULT_FECHA DATE,
    RELA_SOCMAIN05 BIGINT,
    RELA_SOCSYST10_BAN01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICNOMI51 BIGINT,
    SICNOMI51_CUENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI51_FECHA DATE,
    SICNOMI51_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI51_FAPL TIMESTAMP,
    SICXMLS41_FECHA_PAGO DATE,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable CONTADOR_ID bigint;
declare variable SQL_C varchar(1000);
declare variable COUNT_ENTIDAD integer;
begin
    CONTADOR_ID = 100000;

    select count(sicnomi01_cab_empleados.id_sicnomi01)
    from sicnomi01_cab_empleados
    where sicnomi01_cab_empleados.rela_socmain01 = :id_socmain01
    into :count_entidad;

    if (count_entidad < 100) then
        id_sicnomi01 = null;

    if (id_sicnomi01 is not null and id_sicnomi01 > 0) then
    begin
        sql_c = 'Select
                sicnomi01_cab_empleados.rela_socusua30,
                SICNOMI50_DET_CTACTE.rela_SICNOMI01,
                SICNOMI50_DET_CTACTE.rela_socmain01,
                sum(SICNOMI50_DET_CTACTE.SICNOMI50_importe),
                max(SICNOMI50_DET_CTACTE.SICNOMI50_fapl)
                from SICNOMI50_DET_CTACTE
                inner join sicnomi01_cab_empleados on (sicnomi01_cab_empleados.id_sicnomi01 = SICNOMI50_DET_CTACTE.rela_SICNOMI01)
                where SICNOMI50_DET_CTACTE.rela_socmain01 = ' || :id_socmain01 ||
                ' and sicnomi01_cab_empleados.id_sicnomi01 = ' || id_sicnomi01 ||
                ' and SICNOMI50_DET_CTACTE.rela_SICNOMI01 = ' || :id_sicnomi01 ||
                ' group by
                sicnomi01_cab_empleados.rela_socusua30,
                SICNOMI50_DET_CTACTE.rela_SICNOMI01,
                SICNOMI50_DET_CTACTE.rela_socmain01';
    end
    else
    begin
        sql_c = 'Select
                sicnomi01_cab_empleados.rela_socusua30,
                SICNOMI50_DET_CTACTE.rela_SICNOMI01,
                SICNOMI50_DET_CTACTE.rela_socmain01,
                sum(SICNOMI50_DET_CTACTE.SICNOMI50_importe),
                max(SICNOMI50_DET_CTACTE.SICNOMI50_fapl)
                from SICNOMI50_DET_CTACTE
                inner join sicnomi01_cab_empleados on (sicnomi01_cab_empleados.id_sicnomi01 = SICNOMI50_DET_CTACTE.rela_SICNOMI01)
                where SICNOMI50_DET_CTACTE.rela_socmain01 = ' || :id_socmain01 ||
                ' group by
                sicnomi01_cab_empleados.rela_socusua30,
                SICNOMI50_DET_CTACTE.rela_SICNOMI01,
                SICNOMI50_DET_CTACTE.rela_socmain01';
    end

    for execute statement :sql_c
    into :rela_socusua30,
         :rela_SICNOMI01,
         :rela_socmain01,
         :SICNOMI50_importe,
         :ult_fecha
    do
    begin
        select
        cbo_socusua30.tipo,
        cbo_socusua30.entidad,
        cbo_socusua30.rfc,
        cbo_socusua30.curp
        from cbo_socusua30(:rela_socusua30)
        into :tipo,
             :entidad,
             :rfc,
             :curp;

        select max(sicxmls41_det_migracion.sicxmls41_fecha_pago)
        from sicxmls41_det_migracion
        where sicxmls41_det_migracion.rela_socusua30 = :rela_socusua30
        into :sicxmls41_fecha_pago;

        id_sicnomi51 = null;

        select max(sicnomi51_cab_bancos.id_sicnomi51)
        from sicnomi51_cab_bancos
        where sicnomi51_cab_bancos.rela_sicnomi01 = :rela_sicnomi01
        into :id_sicnomi51;

        if (id_sicnomi51 is null) then
        begin
            contador_id = contador_id + 1;
            id_sicnomi51 = :contador_id;
        end

         suspend;
    end

end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI50_DET (
    ID_SOCMAIN01 BIGINT,
    ID_SICNOMI01 BIGINT)
RETURNS (
    MARCA INTEGER,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SICNOMI01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SICNOMI51 BIGINT,
    ID_SICNOMI50 BIGINT,
    SICNOMI50_IMPORTE DOUBLE PRECISION,
    SICNOMI50_FAPL TIMESTAMP,
    IMPORTE_XPAGAR DOUBLE PRECISION,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SUMA_SALDO double precision;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICXMLS41 bigint;
begin
    for select
    socsyst10_det_entradas.socsyst10_codigo,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_fcta,
    SICNOMI50_DET_CTACTE.rela_SICNOMI01,
    SICNOMI50_DET_CTACTE.rela_socmain01,
    SICNOMI50_DET_CTACTE.rela_siccont10,
    SICNOMI50_DET_CTACTE.rela_SICNOMI51,
    SICNOMI50_DET_CTACTE.id_SICNOMI50,
    SICNOMI50_DET_CTACTE.SICNOMI50_importe,
    SICNOMI50_DET_CTACTE.SICNOMI50_fapl
    FROM SICNOMI50_DET_CTACTE
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = SICNOMI50_DET_CTACTE.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    where SICNOMI50_DET_CTACTE.rela_socmain01 = :id_socmain01
    and SICNOMI50_DET_CTACTE.rela_SICNOMI01 = :id_SICNOMI01
    and not exists (select first 1 SICNOMI50_DET_CTACTE.id_SICNOMI50
                    from sicnomi61_det_xperiodo
                    where sicnomi61_det_xperiodo.rela_SICNOMI50 = SICNOMI50_DET_CTACTE.id_SICNOMI50)

    into :socsyst10_codigo,
         :SICCONT10_DOCNRO,
         :SICCONT10_UUID_SAT,
         :SICCONT10_FCTA,
         :RELA_SICNOMI01,
         :RELA_SOCMAIN01,
         :RELA_SICCONT10,
         :RELA_SICNOMI51,
         :ID_SICNOMI50,
         :SICNOMI50_IMPORTE,
         :SICNOMI50_FAPL
    do
    begin
        marca = 0;
        importe_xpagar = 0.0;
        suma_saldo = 0.0;
        sicxmls41_folio = null;
        id_sicxmls41 = null;

        select sum(SICNOMI52_det_bancos.SICNOMI52_importe)
        from SICNOMI52_det_bancos
        where SICNOMI52_det_bancos.rela_SICNOMI50 = :ID_SICNOMI50
        into :suma_saldo;

        if (suma_saldo is null) then
            suma_saldo = 0;

        SICNOMI50_importe = SICNOMI50_importe - suma_saldo;

        if (cast(SICNOMI50_importe as numeric(18,4)) <> 0 and SICCONT10_UUID_SAT is not null) then
        begin
            select sicxmls41_det_migracion.id_sicxmls41,
            sicxmls41_det_migracion.sicxmls41_folio,
            sicxmls41_det_migracion.sicxmls41_metododepago,
            sicxmls41_det_migracion.sicxmls41_formapago
            from sicxmls41_det_migracion
            where sicxmls41_det_migracion.rela_siccont10 = :RELA_SICCONT10
            into :id_sicxmls41,
                 :sicxmls41_folio,
                 :sicxmls41_metododepago,
                 :sicxmls41_formapago;

            if (id_sicxmls41 is not null) then
            begin
                suspend;
            end
        end
        else if (cast(SICNOMI50_importe as numeric(18,4)) <> 0) then
        begin
            if (socsyst10_codigo = 'DROPZONE-ANTI-NOMI') then
            begin
                SICXMLS41_FOLIO = :siccont10_docnro;
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI50_MOV (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICNOMI01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SICCONT10 BIGINT,
    RELA_SICNOMI51 BIGINT,
    ID_SICNOMI50 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EJECUTADO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    FECHA DATE,
    UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BANCO_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA_EMP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICNOMI61FIND bigint;
begin
    FOR select
    socsyst10_det_entradas.socsyst10_codigo,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_fcta,
    SICNOMI50_DET_CTACTE.rela_siccont10,
    SICNOMI50_DET_CTACTE.rela_SICNOMI51,
    SICNOMI50_DET_CTACTE.id_SICNOMI50,
    SICNOMI50_DET_CTACTE.SICNOMI50_importe
    FROM SICNOMI50_DET_CTACTE
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = SICNOMI50_DET_CTACTE.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    where SICNOMI50_DET_CTACTE.rela_socmain01 = :rela_socmain01
    and SICNOMI50_DET_CTACTE.rela_SICNOMI01 = :rela_SICNOMI01
     and siccont10_cab_polizas.siccont10_fcta between :fecha_desde and :fecha_hasta
    order  by siccont10_cab_polizas.siccont10_fcta
    INTO :SOCSYST10_CODIGO,
         :POLIZA,
         :UUID_SAT,
         :FECHA,
         :RELA_SICCONT10,
         :rela_SICNOMI51,
         :id_SICNOMI50,
         :importe_xml
    DO
    BEGIN
        folio = null;

        select SICXMLS41_DET_MIGRACION.sicxmls41_folio
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio;

        select sum(SICNOMI52_det_bancos.SICNOMI52_importe)
        from SICNOMI52_det_bancos
        where SICNOMI52_det_bancos.rela_SICNOMI50 = :ID_SICNOMI50
        into :importe_banco;

        if (importe_banco is null) then
            importe_banco = 0;

        importe_saldo = importe_xml - importe_banco;
        importe_saldo = cast(importe_saldo as numeric(18,4));

        ejecutado = 0;

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */

        if (SOCSYST10_CODIGO = 'DROPZONE') then
        begin
            if (importe_xml > 0) then
                STATUS = 'Nómina Emitida';
            else
                STATUS = 'Crédito a Favor';

            ejecutado = (importe_banco / importe_xml * 100);

            if (ejecutado = 0) then
            begin
                ejecutado = 0.0;
                id_SICNOMI61find = null;

                select first 1 sicnomi61_det_xperiodo.id_SICNOMI61
                from sicnomi61_det_xperiodo
                where sicnomi61_det_xperiodo.rela_SICNOMI50 = :id_SICNOMI50
                into :id_SICNOMI61find;

                if (id_SICNOMI61find is not null) then
                   ejecutado = 100;

            end
        end

        else if (SOCSYST10_CODIGO = 'DROPZONE-ANTI-NOMI') then
        begin
            STATUS = 'Anticipo';
        end

        else if (SOCSYST10_CODIGO = 'DROPZONE-BANCOS-NOMI') then
        begin
            STATUS = 'Pago';
            ejecutado = 100;
            importe_saldo = 0;
            importe_banco = importe_xml;
        end

        else if (SOCSYST10_CODIGO = 'DROPZONE-PERIODO-NOMI') then
        begin
            STATUS = 'Nómina generada por Período';
            ejecutado = 100;
            importe_saldo = 0;
            importe_banco = importe_xml;
        end
        else
        begin
            STATUS = :SOCSYST10_CODIGO;
        end

        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------ */

        if (ejecutado <> 0) then
        begin
            select
            BAN01.socsyst10_descripcion,
            CTM01.socsyst10_descripcion,
            sicnomi51_cab_bancos.sicnomi51_cuenta
            from sicnomi51_cab_bancos
            inner join socmain05_det_bancos on ( socmain05_det_bancos.id_socmain05 = sicnomi51_cab_bancos.rela_socmain05 )
            inner join socsyst10_det_entradas BAN01 ON (BAN01.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ban01 )
            inner join socsyst10_det_remoto CTM01 ON (CTM01.id_socsyst10 = socmain05_det_bancos.rela_socsyst10_ctm01 )
            where sicnomi51_cab_bancos.id_sicnomi51 = :RELA_SICNOMI51
            INTO :banco_emp,
                 :moneda_emp,
                 :cuenta_emp;

            if (banco_emp is null) then
                banco_emp = 'N/A';

            if (moneda_emp is null) then
                moneda_emp = 'N/A';

            if (cuenta_emp is null) then
                cuenta_emp = 'N/A';
        end

        suspend;
    end

end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI50_MOV_DET (
    RELA_SICNOMI51 BIGINT,
    RELA_SICNOMI50 BIGINT)
RETURNS (
    ID_SICNOMI52 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION)
AS
begin
    /*
        el rela_sicnomi51 lo utilizo para buscar en los pagados a cuales xml he pagado
        el rela_sicnomi50 lo utilizo para buscar en los xmls ya ejecutados con que movimientos de banco los pague
    */

    if (rela_sicnomi51 is not null) then
    begin
        for select
        sicnomi52_det_bancos.id_sicnomi52,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont10_cab_polizas.siccont10_uuid_sat,
        sicnomi50_det_ctacte.sicnomi50_importe,
        sicnomi52_det_bancos.sicnomi52_importe
        from sicnomi52_det_bancos
        inner join sicnomi50_det_ctacte on (sicnomi52_det_bancos.rela_sicnomi50 = sicnomi50_det_ctacte.id_sicnomi50)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi50_det_ctacte.rela_siccont10)
        where sicnomi52_det_bancos.rela_sicnomi51 = :rela_sicnomi51
        order by siccont10_cab_polizas.siccont10_fcta
        into :id_sicnomi52,
             :siccont10_docnro,
             :siccont10_fcta,
             :siccont10_uuid_sat,
             :importe_xml,
             :importe_pago
        do
        begin
            if (importe_xml < 0) then
            begin
                status = 'Crédito a Favor';
                if (siccont10_uuid_sat is null or trim(siccont10_uuid_sat) = '' ) then
                    STATUS = 'Anticipo';
            end
            else
                status = 'Nomina Recibida';

            saldo = :importe_xml - :importe_pago;
            suspend;
        end
    end

    if (rela_sicnomi50 is not null) then
    begin
        importe_xml = 0;
        saldo = 0;

        for select
        sicnomi52_det_bancos.rela_sicnomi51,
        sicnomi52_det_bancos.id_sicnomi52,
        sicnomi52_det_bancos.sicnomi52_importe
        from sicnomi52_det_bancos
        where sicnomi52_det_bancos.rela_sicnomi50 = :rela_sicnomi50
        into :rela_sicnomi51,
             :id_sicnomi52,
             :importe_pago
        do
        begin
            select
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta,
            siccont10_cab_polizas.siccont10_uuid_sat
            from sicnomi50_det_ctacte
            inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi50_det_ctacte.rela_siccont10)
            where sicnomi50_det_ctacte.rela_sicnomi51 = :rela_sicnomi51
            into :siccont10_docnro,
                 :siccont10_fcta,
                 :siccont10_uuid_sat;

            if (siccont10_docnro is null) then
            begin
                STATUS = 'Crédito a Favor';

                select
                siccont10_cab_polizas.siccont10_docnro,
                siccont10_cab_polizas.siccont10_fcta,
                siccont10_cab_polizas.siccont10_uuid_sat
                from sicnomi50_det_ctacte
                inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi50_det_ctacte.rela_siccont10)
                where sicnomi50_det_ctacte.id_sicnomi50 = :rela_sicnomi50
                into :siccont10_docnro,
                     :siccont10_fcta,
                     :siccont10_uuid_sat;

            end
            else
            begin
               STATUS = 'Pago';
            end

            suspend;
        end     
    end


end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI50_XPERIODOS (
    RELA_SOCMAIN01 BIGINT,
    FECHA_PAGO DATE)
RETURNS (
    MARCA INTEGER,
    ID_SICNOMI50 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_NOMI VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICNOMI50_IMPORTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XPAGAR DOUBLE PRECISION)
AS
declare variable RELA_SICCONT10 bigint;
declare variable SUMA_BANCOS double precision;
begin
    for select
    sicnomi50_det_ctacte.rela_siccont10,
    sicnomi50_det_ctacte.id_sicnomi50,
    cbo_sicnomi01.entidad,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicnomi50_det_ctacte.sicnomi50_importe,
    siccont10_cab_polizas.siccont10_uuid_sat,
    sicxmls41_det_migracion.sicxmls41_folio,
    sicxmls41_det_migracion.sicxmls41_metododepago
    from sicnomi50_det_ctacte
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi50_det_ctacte.rela_siccont10)
    inner join sicnomi01_cab_empleados on (sicnomi01_cab_empleados.id_sicnomi01 = sicnomi50_det_ctacte.rela_sicnomi01)
    inner join cbo_sicnomi01 on (cbo_sicnomi01.id_socusua30 = sicnomi01_cab_empleados.rela_socusua30)
    inner join sicxmls41_det_migracion on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
    where sicnomi50_det_ctacte.rela_socmain01 = :rela_socmain01
    and siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
    and cbo_sicnomi01.rela_socmain01 = :rela_socmain01
    and siccont10_cab_polizas.siccont10_uuid_sat is not null
    and sicnomi50_det_ctacte.sicnomi50_importe > 0
    and sicxmls41_det_migracion.sicxmls41_fecha_pago = :fecha_pago
    and not exists (select first 1 sicnomi61_det_xperiodo.id_sicnomi61
                    from sicnomi61_det_xperiodo
                    where sicnomi61_det_xperiodo.rela_sicnomi50 = sicnomi50_det_ctacte.id_sicnomi50
                    )
    into :rela_siccont10,
         :id_sicnomi50,
         :entidad,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicnomi50_importe,
         :SICCONT10_UUID_SAT,
         :folio,
         :sicxmls41_metododepago
    do
    begin
        suma_bancos = null;

        select sum(sicnomi52_det_bancos.sicnomi52_importe)
        from sicnomi52_det_bancos
        where sicnomi52_det_bancos.rela_sicnomi50 = :id_sicnomi50
        into :suma_bancos;

        if (suma_bancos is null) then
            suma_bancos = 0;

        sicnomi50_importe = sicnomi50_importe - :suma_bancos;

        if (sicnomi50_importe <> 0) then
        begin
            select first 1 siccont11_det_polizas.siccont11_referencia
            from siccont11_det_polizas
            inner join siccont12_mov_dropzone on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
            where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
            and siccont12_mov_dropzone.rela_sicxmls05 is not null
            into :siccont11_referencia;

            marca = 1;
            IMPORTE_XPAGAR = sicnomi50_importe;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI50_XPERIODOS_VIEW (
    RELA_SICNOMI60 BIGINT)
RETURNS (
    MARCA INTEGER,
    ID_SICNOMI50 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO_NOMI VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICNOMI50_IMPORTE DOUBLE PRECISION,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XPAGAR DOUBLE PRECISION)
AS
declare variable RELA_SICCONT10 bigint;
begin
    for select
    sicnomi50_det_ctacte.rela_siccont10,
    sicnomi50_det_ctacte.id_sicnomi50,
    cbo_sicnomi01.entidad,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicnomi50_det_ctacte.sicnomi50_importe,
    siccont10_cab_polizas.siccont10_uuid_sat,
    NOMI.siccont10_docnro
    from sicnomi60_cab_xperiodo
    inner join sicnomi61_det_xperiodo on (sicnomi60_cab_xperiodo.id_sicnomi60 = sicnomi61_det_xperiodo.rela_sicnomi60)
    inner join siccont10_cab_polizas NOMI ON (NOMI.id_siccont10 = sicnomi61_det_xperiodo.rela_siccont10)
    inner join sicnomi50_det_ctacte on (sicnomi50_det_ctacte.id_sicnomi50 = sicnomi61_det_xperiodo.rela_sicnomi50)
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi50_det_ctacte.rela_siccont10)
    inner join sicnomi01_cab_empleados on (sicnomi01_cab_empleados.id_sicnomi01 = sicnomi50_det_ctacte.rela_sicnomi01)
    inner join cbo_sicnomi01 on (cbo_sicnomi01.id_socusua30 = sicnomi01_cab_empleados.rela_socusua30)
    where sicnomi60_cab_xperiodo.id_sicnomi60 = :RELA_sicnomi60
    into :rela_siccont10,
         :id_sicnomi50,
         :entidad,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicnomi50_importe,
         :SICCONT10_UUID_SAT,
         :siccont10_docnro_nomi
    do
    begin
        marca = 1;
        IMPORTE_XPAGAR = sicnomi50_importe;

        select
        SICXMLS41_DET_MIGRACION.sicxmls41_folio,
        SICXMLS41_DET_MIGRACION.sicxmls41_metododepago
        from SICXMLS41_DET_MIGRACION
        where SICXMLS41_DET_MIGRACION.rela_siccont10 = :RELA_SICCONT10
        into :folio,
             :sicxmls41_metododepago;

        select first 1 siccont11_det_polizas.siccont11_referencia
        from siccont11_det_polizas
        inner join siccont12_mov_dropzone on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
        and siccont12_mov_dropzone.rela_sicxmls05 is not null
        into :siccont11_referencia;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI60 (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X BIGINT)
RETURNS (
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    ID_SICNOMI60 BIGINT,
    SICNOMI60_IMPORTE DOUBLE PRECISION,
    SICNOMI60_FAPL TIMESTAMP,
    IMPORTE_TOTAL DOUBLE PRECISION,
    SICNOMI60_AJUSTE DOUBLE PRECISION,
    BANCO_CUENTA VARCHAR(1250) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    FOR select
    SICCONT10_CAB_POLIZAS.siccont10_docnro,
    SICCONT10_CAB_POLIZAS.siccont10_fcta,
    SICNOMI60_CAB_XPERIODO.rela_socmain01,
    SICNOMI60_CAB_XPERIODO.rela_socmain21,
    SICNOMI60_CAB_XPERIODO.rela_socusua01,
    SICNOMI60_CAB_XPERIODO.rela_siccont10,
    SICNOMI60_CAB_XPERIODO.rela_socmain05,
    SICNOMI60_CAB_XPERIODO.id_SICNOMI60,
    SICNOMI60_CAB_XPERIODO.SICNOMI60_importe,
    SICNOMI60_CAB_XPERIODO.SICNOMI60_ajuste,
    SICNOMI60_CAB_XPERIODO.SICNOMI60_fapl,
    (SELECT sum(sicnomi50_det_ctacte.sicnomi50_importe)
     FROM sicnomi61_det_xperiodo
     INNER join sicnomi50_det_ctacte ON (sicnomi50_det_ctacte.id_sicnomi50 = sicnomi61_det_xperiodo.rela_sicnomi50)
     WHERE sicnomi61_det_xperiodo.rela_SICNOMI60 = SICNOMI60_CAB_XPERIODO.id_SICNOMI60
    )
    from SICNOMI60_CAB_XPERIODO
    INNER JOIN SICCONT10_CAB_POLIZAS ON (SICCONT10_CAB_POLIZAS.ID_SICCONT10 = SICNOMI60_CAB_XPERIODO.rela_siccont10)
    WHERE SICNOMI60_CAB_XPERIODO.rela_socmain01 = :rela_socmain01x
    and SICNOMI60_CAB_XPERIODO.rela_socmain21 = :RELA_SOCMAIN21X
    INTO :SICCONT10_DOCNRO,
         :SICCONT10_FCTA,
         :RELA_SOCMAIN01,
         :RELA_SOCMAIN21,
         :RELA_SOCUSUA01,
         :RELA_SICCONT10,
         :rela_socmain05,
         :ID_SICNOMI60,
         :SICNOMI60_IMPORTE,
         :SICNOMI60_ajuste,
         :SICNOMI60_FAPL,
         :IMPORTE_TOTAL

    DO
    BEGIN
        Select GRD_SOCMAIN05.ve
        from GRD_SOCMAIN05
        WHERE GRD_SOCMAIN05.id_socmain05 = :rela_socmain05
        into :banco_cuenta;

        IMPORTE_TOTAL = IMPORTE_TOTAL + SICNOMI60_ajuste;
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI70_CFDIS_FILT (
    ID_SOCMAIN01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE,
    FILTRO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MARCA INTEGER,
    NOVEDAD VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICNOMI70 BIGINT,
    SICNOMI70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI70_TIPONOMINA VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI70_FECHA DATE,
    SICNOMI70_FINI DATE,
    SICNOMI70_FFIN DATE,
    SICNOMI70_DIAS INTEGER,
    TOT_PERCEPCIONES DOUBLE PRECISION,
    TOT_DEDUCCIONES DOUBLE PRECISION,
    TOT_SUELDO DOUBLE PRECISION,
    SICNOMI74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID_SMX_QRCODE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICNOMI73 bigint;
begin
    filtro = upper(:filtro);

    FOR SELECT
    sicnomi70_cab_nomina.id_sicnomi70,
    cbo_sicnomi01_curp.entidad,
    cbo_sicnomi01_curp.curp,
    cbo_sicnomi01_curp.rfc,
    sicnomi70_cab_nomina.sicnomi70_docnro,
    sicnomi70_cab_nomina.sicnomi70_fecha,
    sicnomi70_cab_nomina.sicnomi70_status,
    sicnomi70_cab_nomina.sicnomi70_tiponomina,
    sicnomi70_cab_nomina.sicnomi70_fini,
    sicnomi70_cab_nomina.sicnomi70_ffin,
    sicnomi70_cab_nomina.sicnomi70_dias,
    sicnomi74_dep_cfdis.sicnomi74_uuid,
    sicnomi74_dep_cfdis.sicnomi74_uuid_smx,
    sicnomi74_dep_cfdis.sicnomi74_uuid_smx_qrcode,
    sicnomi74_dep_cfdis.sicnomi74_uuid_importe
    FROM sicnomi70_cab_nomina
    inner join sicnomi74_dep_cfdis on ( sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70 )
    inner join cbo_sicnomi01_curp on ( cbo_sicnomi01_curp.id_sicnomi01 = sicnomi70_cab_nomina.rela_sicnomi01 )
    where sicnomi70_cab_nomina.rela_socmain01 = :id_socmain01
    and cbo_sicnomi01_curp.rela_socmain01 = :id_socmain01
    and sicnomi70_cab_nomina.sicnomi70_fecha between :fecha_desde and :fecha_hasta
    and upper(cbo_sicnomi01_curp.entidad || iif(sicnomi70_cab_nomina.sicnomi70_status is null, '', sicnomi70_cab_nomina.sicnomi70_status))  like '%' || :filtro || '%'
    into :id_sicnomi70,
         :entidad,
         :curp,
         :rfc,
         :sicnomi70_docnro,
         :sicnomi70_fecha,
         :novedad,
         :sicnomi70_tiponomina,
         :sicnomi70_fini,
         :sicnomi70_ffin,
         :sicnomi70_dias,
         :sicnomi74_uuid,
         :sicnomi74_uuid_smx,
         :sicnomi74_uuid_smx_qrcode,
         :tot_sueldo
    do
    begin
        marca = 1;

        id_sicnomi73 = null;
        origen = 'MANUAL';

        select first 1 sicnomi73_det_xperiodo.id_sicnomi73
        from sicnomi73_det_xperiodo
        where sicnomi73_det_xperiodo.rela_sicnomi70 = :id_sicnomi70
        into :id_sicnomi73;

        if (id_sicnomi73 is not null) then
           origen = 'PERIODO';

        select sum( sicnomi71_det_nomina.sicnomi71_importe )
        from sicnomi71_det_nomina
        INNER JOIN sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05)
        where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
        and (sicxmls05_det_nomina.sicxmls05_tipo <> 'D' AND sicxmls05_det_nomina.sicxmls05_tipo <> 'I')
        into tot_percepciones;

        select iif(sum( sicnomi71_det_nomina.sicnomi71_importe ) is null, 0.00, sum( sicnomi71_det_nomina.sicnomi71_importe ))
        from sicnomi71_det_nomina
        INNER JOIN sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05)
        where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
        and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' AND sicxmls05_det_nomina.sicxmls05_tipo = 'I')
        into tot_deducciones;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI70_CFDIS_PEND (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    MARCA INTEGER,
    NOVEDAD VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICNOMI70 BIGINT,
    SICNOMI70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI70_TIPONOMINA VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI70_FECHA DATE,
    SICNOMI70_FINI DATE,
    SICNOMI70_FFIN DATE,
    SICNOMI70_DIAS INTEGER,
    TOT_PERCEPCIONES DOUBLE PRECISION,
    TOT_DEDUCCIONES DOUBLE PRECISION,
    TOT_SUELDO DOUBLE PRECISION)
AS
declare variable ID_SICNOMI73 integer;
begin
    FOR SELECT
    1,
    sicnomi70_cab_nomina.sicnomi70_status,
    cbo_sicnomi01_curp.entidad,
    cbo_sicnomi01_curp.curp,
    cbo_sicnomi01_curp.rfc,
    sicnomi70_cab_nomina.id_sicnomi70,
    sicnomi70_cab_nomina.sicnomi70_docnro,
    sicnomi70_cab_nomina.sicnomi70_tiponomina,
    sicnomi70_cab_nomina.sicnomi70_fecha,
    sicnomi70_cab_nomina.sicnomi70_fini,
    sicnomi70_cab_nomina.sicnomi70_ffin,
    sicnomi70_cab_nomina.sicnomi70_dias
    FROM sicnomi70_cab_nomina
    inner join cbo_sicnomi01_curp on (cbo_sicnomi01_curp.id_sicnomi01 = sicnomi70_cab_nomina.rela_sicnomi01 )
    WHERE sicnomi70_cab_nomina.rela_socmain01 = :id_socmain01
    AND NOT EXISTS (select sicnomi74_dep_cfdis.id_sicnomi74
                      from sicnomi74_dep_cfdis
                      where sicnomi74_dep_cfdis.rela_sicnomi70 = sicnomi70_cab_nomina.id_sicnomi70)
    INTO :marca,
         :novedad,
         :entidad,
         :curp,
         :rfc,
         :id_sicnomi70,
         :sicnomi70_docnro,
         :sicnomi70_tiponomina,
         :sicnomi70_fecha,
         :sicnomi70_fini,
         :sicnomi70_ffin,
         :sicnomi70_dias
    DO
    BEGIN
        id_sicnomi73 = null;
        origen = 'MANUAL';

        select first 1 sicnomi73_det_xperiodo.id_sicnomi73
        from sicnomi73_det_xperiodo
        where sicnomi73_det_xperiodo.rela_sicnomi70 = :id_sicnomi70
        into :id_sicnomi73;

        if (id_sicnomi73 is not null) then
           origen = 'PERIODO';

        select sum( sicnomi71_det_nomina.sicnomi71_importe )
        from sicnomi71_det_nomina
        INNER JOIN sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05)
        where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
        and (sicxmls05_det_nomina.sicxmls05_tipo <> 'D' AND sicxmls05_det_nomina.sicxmls05_tipo <> 'I')
        into tot_percepciones;

        select iif(sum( sicnomi71_det_nomina.sicnomi71_importe ) is null, 0.00, sum( sicnomi71_det_nomina.sicnomi71_importe ))
        from sicnomi71_det_nomina
        INNER JOIN sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05)
        where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
        and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' AND sicxmls05_det_nomina.sicxmls05_tipo = 'I')
        into tot_deducciones;

        tot_sueldo = tot_percepciones - tot_deducciones;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI71_DEDUCCIONES (
    ID_SOCMAIN01 VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICNOMI01 VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SICNOMI70 BIGINT,
    RELA_SICXMLS05 BIGINT,
    ID_SICNOMI71 BIGINT,
    SICXMLS05_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    GRAVADO VARCHAR(2) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_IMPORTE DOUBLE PRECISION,
    SICNOMI71_FAPL TIMESTAMP,
    SICXMLS05_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS05_TIPOSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_CANTIDAD DOUBLE PRECISION,
    SICNOMI71_CLAVEOTROS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_SUBSIDIO DOUBLE PRECISION,
    SICNOMI71_ANO INTEGER,
    SICNOMI71_REMANENTE DOUBLE PRECISION,
    SICNOMI71_SALDOFAVOR DOUBLE PRECISION)
AS
declare variable FECHA_MAX date;
declare variable SICXMLS05_GRAVADO integer;
begin
    select
    max(sicnomi70_cab_nomina.sicnomi70_fecha)
    from sicnomi70_cab_nomina
    WHERE sicnomi70_cab_nomina.rela_socmain01 = :id_socmain01
    and sicnomi70_cab_nomina.rela_sicnomi01 = :id_sicnomi01
    into :fecha_max;

    select
    max(sicnomi70_cab_nomina.id_sicnomi70)
    from sicnomi70_cab_nomina
    WHERE sicnomi70_cab_nomina.rela_socmain01 = :id_socmain01
    and sicnomi70_cab_nomina.rela_sicnomi01 = :id_sicnomi01
    and sicnomi70_cab_nomina.sicnomi70_fecha = :fecha_max
    into :rela_sicnomi70;

    if (rela_sicnomi70 is null) then
    begin
        ID_SICNOMI71 = 0;
        rela_sicnomi70 = -1;

        for select
        sicxmls05_det_nomina.id_sicxmls05,
        sicxmls05_det_nomina.sicxmls05_concepto,
        sicxmls05_det_nomina.sicxmls05_gravado,
        sicxmls05_det_nomina.sicxmls05_tipo,
        sicxmls05_det_nomina.sicxmls05_tiposat
        from sicxmls05_det_nomina
        inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
        where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
        and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' OR sicxmls05_det_nomina.sicxmls05_tipo = 'I')
        into :rela_sicxmls05,
             :sicxmls05_concepto,
             :sicxmls05_gravado,
             :sicxmls05_tipo,
             :sicxmls05_tiposat
        do
        begin
            ID_SICNOMI71 = ID_SICNOMI71 - 1;
            sicnomi71_cantidad = cast( 0.00 as double precision );
            sicnomi71_claveotros = cast( null as varchar(400) );
            sicnomi71_subsidio = cast( 0.00 as double precision );
            sicnomi71_ano = cast( 0 as integer );
            sicnomi71_remanente = cast( 0.00 as double precision );
            sicnomi71_saldofavor = cast( 0.00 as double precision );

            select
            prd_sicnomi71_importes.gravado,
            prd_sicnomi71_importes.importe
            from prd_sicnomi71_importes(:sicxmls05_gravado, :id_socmain01, :id_sicnomi01, :rela_sicxmls05)
            into :gravado,
                 :sicnomi71_importe;

            SICNOMI71_FAPL = current_timestamp;
            suspend;
        end

    end
    else
    begin
        ID_SICNOMI71 = 0;

        for select
        sicxmls05_det_nomina.id_sicxmls05,
        sicxmls05_det_nomina.sicxmls05_concepto,
        sicnomi71_det_nomina.sicnomi71_importe,
        sicxmls05_det_nomina.sicxmls05_gravado,
        sicxmls05_det_nomina.sicxmls05_tipo,
        sicxmls05_det_nomina.sicxmls05_tiposat,
        sicnomi71_det_nomina.sicnomi71_cantidad,
        sicnomi71_det_nomina.sicnomi71_claveotros,
        sicnomi71_det_nomina.sicnomi71_subsidio,
        sicnomi71_det_nomina.sicnomi71_ano,
        sicnomi71_det_nomina.sicnomi71_remanente,
        sicnomi71_det_nomina.sicnomi71_saldofavor
        from sicnomi71_det_nomina
        right outer join sicxmls05_det_nomina on (sicnomi71_det_nomina.rela_sicxmls05 = sicxmls05_det_nomina.id_sicxmls05)
        inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
        where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
        and sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
        and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' OR sicxmls05_det_nomina.sicxmls05_tipo = 'I')

        union all

        select
        sicxmls05_det_nomina.id_sicxmls05,
        sicxmls05_det_nomina.sicxmls05_concepto,
        0.00,
        sicxmls05_det_nomina.sicxmls05_gravado,
        sicxmls05_det_nomina.sicxmls05_tipo,
        sicxmls05_det_nomina.sicxmls05_tiposat,
        cast( 0.00 as double precision ),
        cast( null as varchar(400) ),
        cast( 0.00 as double precision ),
        cast( 0 as integer ),
        cast( 0.00 as double precision ),
        cast( 0.00 as double precision )
        from sicxmls05_det_nomina
        inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
        where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
        and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' OR sicxmls05_det_nomina.sicxmls05_tipo = 'I')
        and not exists (select first 1 sicnomi71_det_nomina.id_sicnomi71
                        from sicnomi71_det_nomina
                        where sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
                        and sicnomi71_det_nomina.rela_sicxmls05 = sicxmls05_det_nomina.id_sicxmls05)

        into :rela_sicxmls05,
             :sicxmls05_concepto,
             :sicnomi71_importe,
             :sicxmls05_gravado,
             :sicxmls05_tipo,
             :sicxmls05_tiposat,
             :sicnomi71_cantidad,
             :sicnomi71_claveotros,
             :sicnomi71_subsidio,
             :sicnomi71_ano,
             :sicnomi71_remanente,
             :sicnomi71_saldofavor
        do
        begin
            if (sicxmls05_gravado = 0) then
                gravado = 'No';
            else
                gravado = 'Si';

            ID_SICNOMI71 = ID_SICNOMI71 - 1;
            SICNOMI71_FAPL = current_timestamp;

            if (sicnomi71_importe is null) then
                sicnomi71_importe = 0.00;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI71_DEDUCCIONES_MOD (
    ID_SICNOMI70 BIGINT)
RETURNS (
    RELA_SICNOMI70 BIGINT,
    RELA_SICXMLS05 BIGINT,
    ID_SICNOMI71 BIGINT,
    SICXMLS05_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    GRAVADO VARCHAR(2) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_IMPORTE DOUBLE PRECISION,
    SICNOMI71_FAPL TIMESTAMP,
    SICXMLS05_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS05_TIPOSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_CANTIDAD DOUBLE PRECISION,
    SICNOMI71_CLAVEOTROS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_SUBSIDIO DOUBLE PRECISION,
    SICNOMI71_ANO INTEGER,
    SICNOMI71_REMANENTE DOUBLE PRECISION,
    SICNOMI71_SALDOFAVOR DOUBLE PRECISION)
AS
declare variable ID_SOCMAIN01 bigint;
declare variable IDTMP bigint;
begin
    idtmp = 0;

    select
    sicnomi70_cab_nomina.rela_socmain01
    from sicnomi70_cab_nomina
    where sicnomi70_cab_nomina.id_sicnomi70 = :id_sicnomi70
    into :id_socmain01;

    for select
    sicxmls05_det_nomina.id_sicxmls05,
    sicnomi71_det_nomina.id_sicnomi71,
    sicxmls05_det_nomina.sicxmls05_concepto,
    iif(sicxmls05_det_nomina.sicxmls05_gravado = 0, 'No', 'Si'),
    sicnomi71_det_nomina.sicnomi71_importe,
    sicnomi71_det_nomina.sicnomi71_fapl,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicnomi71_det_nomina.sicnomi71_cantidad,
    sicnomi71_det_nomina.sicnomi71_claveotros,
    sicnomi71_det_nomina.sicnomi71_subsidio,
    sicnomi71_det_nomina.sicnomi71_ano,
    sicnomi71_det_nomina.sicnomi71_remanente,
    sicnomi71_det_nomina.sicnomi71_saldofavor
    from sicxmls05_det_nomina
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
    inner join sicnomi71_det_nomina on ( sicnomi71_det_nomina.rela_sicxmls05 = sicxmls05_det_nomina.id_sicxmls05 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' or sicxmls05_det_nomina.sicxmls05_tipo = 'I')

    union all

    select
    sicxmls05_det_nomina.id_sicxmls05,
    -1964,
    sicxmls05_det_nomina.sicxmls05_concepto,
    iif(sicxmls05_det_nomina.sicxmls05_gravado = 0, 'No', 'Si'),
    0.00,
    current_timestamp,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    cast( 0.00 as double precision ),
    cast( null as varchar(400) ),
    cast( 0.00 as double precision ),
    cast( 0 as integer ),
    cast( 0.00 as double precision ),
    cast( 0.00 as double precision )

    from sicxmls05_det_nomina
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' or sicxmls05_det_nomina.sicxmls05_tipo = 'I')
    and not exists ( select first 1 sicnomi71_det_nomina.id_sicnomi71
                     from sicnomi71_det_nomina
                     where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
                     and sicnomi71_det_nomina.rela_sicxmls05 = sicxmls05_det_nomina.id_sicxmls05
                    )

    into :rela_sicxmls05,
         :id_sicnomi71,
         :sicxmls05_concepto,
         :gravado,
         :sicnomi71_importe,
         :sicnomi71_fapl,
         :sicxmls05_tipo,
         :sicxmls05_tiposat,
         :sicnomi71_cantidad,
         :sicnomi71_claveotros,
         :sicnomi71_subsidio,
         :sicnomi71_ano,
         :sicnomi71_remanente,
         :sicnomi71_saldofavor
    do
    begin
        if (id_sicnomi71 = -1964) then
        begin
            idtmp = idtmp - 1;
            ID_SICNOMI71 = idtmp;
        end

        RELA_SICNOMI70 = :id_sicnomi70;

        suspend;
    end
end^


