    SICXMLS05_TIPOSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_CANTIDAD DOUBLE PRECISION,
    SICNOMI71_CLAVEOTROS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_SUBSIDIO DOUBLE PRECISION,
    SICNOMI71_ANO INTEGER,
    SICNOMI71_REMANENTE DOUBLE PRECISION,
    SICNOMI71_SALDOFAVOR DOUBLE PRECISION)
AS
declare variable ID_SOCMAIN01 bigint;
declare variable IDTMP bigint;
begin
    idtmp = 0;

    select
    sicnomi70_cab_nomina.rela_socmain01
    from sicnomi70_cab_nomina
    where sicnomi70_cab_nomina.id_sicnomi70 = :id_sicnomi70
    into :id_socmain01;

    for select
    sicxmls05_det_nomina.id_sicxmls05,
    sicnomi71_det_nomina.id_sicnomi71,
    sicxmls05_det_nomina.sicxmls05_concepto,
    iif(sicxmls05_det_nomina.sicxmls05_gravado = 0, 'No', 'Si'),
    sicnomi71_det_nomina.sicnomi71_importe,
    sicnomi71_det_nomina.sicnomi71_fapl,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicnomi71_det_nomina.sicnomi71_cantidad,
    sicnomi71_det_nomina.sicnomi71_claveotros,
    sicnomi71_det_nomina.sicnomi71_subsidio,
    sicnomi71_det_nomina.sicnomi71_ano,
    sicnomi71_det_nomina.sicnomi71_remanente,
    sicnomi71_det_nomina.sicnomi71_saldofavor
    from sicxmls05_det_nomina
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
    inner join sicnomi71_det_nomina on ( sicnomi71_det_nomina.rela_sicxmls05 = sicxmls05_det_nomina.id_sicxmls05 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo <> 'D' AND sicxmls05_det_nomina.sicxmls05_tipo <> 'I')

    union all

    select
    sicxmls05_det_nomina.id_sicxmls05,
    -1964,
    sicxmls05_det_nomina.sicxmls05_concepto,
    iif(sicxmls05_det_nomina.sicxmls05_gravado = 0, 'No', 'Si'),
    0.00,
    current_timestamp,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    cast( 0.00 as double precision ),
    cast( null as varchar(400) ),
    cast( 0.00 as double precision ),
    cast( 0 as integer ),
    cast( 0.00 as double precision ),
    cast( 0.00 as double precision )
    from sicxmls05_det_nomina
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01 )
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and (sicxmls05_det_nomina.sicxmls05_tipo <> 'D' AND sicxmls05_det_nomina.sicxmls05_tipo <> 'I')
    and not exists ( select first 1 sicnomi71_det_nomina.id_sicnomi71
                     from sicnomi71_det_nomina
                     where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
                     and sicnomi71_det_nomina.rela_sicxmls05 = sicxmls05_det_nomina.id_sicxmls05
                    )

    into :rela_sicxmls05,
         :id_sicnomi71,
         :sicxmls05_concepto,
         :gravado,
         :sicnomi71_importe,
         :sicnomi71_fapl,
         :sicxmls05_tipo,
         :sicxmls05_tiposat,
         :sicnomi71_cantidad,
         :sicnomi71_claveotros,
         :sicnomi71_subsidio,
         :sicnomi71_ano,
         :sicnomi71_remanente,
         :sicnomi71_saldofavor
    do
    begin
        if (id_sicnomi71 = -1964) then
        begin
            idtmp = idtmp - 1;
            ID_SICNOMI71 = idtmp;
        end

        RELA_SICNOMI70 = :id_sicnomi70;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI73 (
    ID_SOCMAIN01 BIGINT,
    ID_SICNOMI72 INTEGER)
RETURNS (
    MARCA INTEGER,
    RELA_SICNOMI72 BIGINT,
    RELA_SICNOMI01 BIGINT,
    RELA_SICNOMI70 BIGINT,
    ID_SICNOMI73 BIGINT,
    SICNOMI73_FAPL TIMESTAMP,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI73_ANTIGUEDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_INILABORAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PERIODO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOT_PERCEPCIONES DOUBLE PRECISION,
    TOT_DEDUCCIONES DOUBLE PRECISION,
    TOT_SUELDO DOUBLE PRECISION)
AS
declare variable SICNOMI73_CON integer;
begin
    SICNOMI73_CON = 0;
    sicnomi73_antiguedad = '';

    FOR SELECT
    CBO_SICNOMI01_CURP.id_sicnomi01,
    CBO_SICNOMI01_CURP.entidad,
    CBO_SICNOMI01_CURP.curp,
    CBO_SICNOMI01_CURP.rfc
    FROM CBO_SICNOMI01_CURP
    WHERE CBO_SICNOMI01_CURP.rela_socmain01 = :id_socmain01
    and (
            exists (select first 1 sicxmls41_det_migracion.id_sicxmls41
                    from sicxmls41_det_migracion
                    inner join sicxmls40_cab_migracion on ( sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40 )
                    where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
                    and sicxmls41_det_migracion.rela_socusua30 = CBO_SICNOMI01_CURP.rela_socusua30)
            or exists (Select first 1 sicnomi70_cab_nomina.id_sicnomi70
                       from sicnomi70_cab_nomina
                       where sicnomi70_cab_nomina.rela_socmain01 = :id_socmain01
                       and sicnomi70_cab_nomina.rela_sicnomi01 = CBO_SICNOMI01_CURP.id_sicnomi01)
    )

    INTO :RELA_SICNOMI01,
         :ENTIDAD,
         :CURP,
         :RFC
    DO
    BEGIN
        if (ID_SICNOMI72 < 0) then
        BEGIN
            SICNOMI73_CON = SICNOMI73_CON - 1;
            marca = 1;
            ID_SICNOMI73 = SICNOMI73_CON;
            rela_sicnomi70 = -1;
            rela_sicnomi72 = :id_sicnomi72;
            sicnomi73_fapl = current_timestamp;
        END

        select sicnomi05_det_nomina.sicnomi05_valor
        from sicnomi05_det_nomina
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01 )
        where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
        and socsyst10_det_entradas.socsyst10_codigo = 'FECHAINICIORELLABORAL'
        into :FECHA_INILABORAL;

        select sicnomi05_det_nomina.sicnomi05_valor
        from sicnomi05_det_nomina
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01 )
        where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
        and socsyst10_det_entradas.socsyst10_codigo = 'PERIODICIDADPAGO'
        into :PERIODO;

        SELECT
        SUM(GRD_SICNOMI71_PERCEPCIONES.sicnomi71_importe)
        FROM GRD_SICNOMI71_PERCEPCIONES(:id_socmain01, :rela_sicnomi01)
        INTO :tot_percepciones;

        SELECT
        SUM(GRD_SICNOMI71_DEDUCCIONES.sicnomi71_importe)
        FROM GRD_SICNOMI71_DEDUCCIONES(:id_socmain01, :rela_sicnomi01)
        INTO :tot_deducciones;

        tot_sueldo = tot_percepciones - tot_deducciones;

        SUSPEND ;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICNOMI73_MOD (
    RELA_SICNOMI72X BIGINT)
RETURNS (
    MARCA INTEGER,
    RELA_SICNOMI72 BIGINT,
    RELA_SICNOMI01 BIGINT,
    RELA_SICNOMI70 BIGINT,
    ID_SICNOMI73 BIGINT,
    SICNOMI73_FAPL TIMESTAMP,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOT_PERCEPCIONES DOUBLE PRECISION,
    TOT_DEDUCCIONES DOUBLE PRECISION,
    TOT_SUELDO DOUBLE PRECISION)
AS
begin
    FOR SELECT
    1,
    sicnomi73_det_xperiodo.rela_sicnomi72,
    sicnomi73_det_xperiodo.rela_sicnomi01,
    sicnomi73_det_xperiodo.rela_sicnomi70,
    sicnomi73_det_xperiodo.id_sicnomi73,
    sicnomi73_det_xperiodo.sicnomi73_fapl,
    cbo_sicnomi01_curp.entidad,
    cbo_sicnomi01_curp.curp,
    cbo_sicnomi01_curp.rfc
    FROM sicnomi73_det_xperiodo
    inner join cbo_sicnomi01_curp on ( sicnomi73_det_xperiodo.rela_sicnomi01 = cbo_sicnomi01_curp.id_sicnomi01 )
    WHERE sicnomi73_det_xperiodo.rela_sicnomi72 = :rela_sicnomi72x
    INTO :marca,
         :rela_sicnomi72,
         :rela_sicnomi01,
         :rela_sicnomi70,
         :id_sicnomi73,
         :sicnomi73_fapl,
         :entidad,
         :curp,
         :rfc
    do
    begin
        select
        sum(sicnomi71_det_nomina.sicnomi71_importe)
        from sicnomi71_det_nomina
        where sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
        and sicnomi71_det_nomina.sicnomi71_tipo <> 'D'
        and sicnomi71_det_nomina.sicnomi71_tipo <> 'I'
        into :tot_percepciones;

        select
        sum(sicnomi71_det_nomina.sicnomi71_importe)
        from sicnomi71_det_nomina
        where sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
        and (sicnomi71_det_nomina.sicnomi71_tipo ='D'
        or sicnomi71_det_nomina.sicnomi71_tipo = 'I')
        into :tot_deducciones;

        tot_sueldo = tot_percepciones - tot_deducciones;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS03 (
    RELA_SICXMLS01X BIGINT)
RETURNS (
    RELA_SICXMLS01 INTEGER,
    RELA_SOCSYST10_TCT01 INTEGER,
    RELA_SICCONT02 INTEGER,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICXMLS03 BIGINT,
    SICXMLS03_FAPL TIMESTAMP,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COLOR INTEGER)
AS
declare variable IDFALSO bigint;
declare variable ID_SOCSYST10 bigint;
declare variable SICCONT02_CODIGO_EXT varchar(50);
declare variable SICCONT02_DESCRIPCION varchar(400);
declare variable CONTA_00 integer;
declare variable CONTA_01 integer;
declare variable CONTA_02 integer;
declare variable CONTA_03 integer;
declare variable CONTA_04 integer;
declare variable CONTA_05 integer;
declare variable CONTA_06 integer;
declare variable CONTA_07 integer;
begin
    idfalso = 0;

    conta_00 = 0;
    conta_01 = 0;
    conta_02 = 0;
    conta_03 = 0;
    conta_04 = 0;
    conta_05 = 0;
    conta_06 = 0;
    conta_07 = 0;

    for select
    cbo_socsyst10_tct01_ctas.id_socsyst10,
    cbo_socsyst10_tct01_ctas.socsyst10_descripcion,
    cbo_socsyst10_tct01_ctas.socsyst10_codigo
    from cbo_socsyst10_tct01_ctas
    order by cbo_socsyst10_tct01_ctas.socsyst10_codigo
    into :id_socsyst10,
         :socsyst10_descripcion,
         :socsyst10_codigo
    do
    begin
        id_sicxmls03 = null;

        select
        sicxmls03_det_cuentas.rela_sicxmls01,
        sicxmls03_det_cuentas.rela_socsyst10_tct01,
        sicxmls03_det_cuentas.rela_siccont02,
        sicxmls03_det_cuentas.id_sicxmls03,
        sicxmls03_det_cuentas.sicxmls03_fapl,
        siccont02_arb_planctas.siccont02_codigo_ext,
        siccont02_arb_planctas.siccont02_descripcion
        from sicxmls03_det_cuentas
        inner join siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = sicxmls03_det_cuentas.rela_siccont02)
        where sicxmls03_det_cuentas.rela_sicxmls01 = :rela_sicxmls01x
        and sicxmls03_det_cuentas.rela_socsyst10_tct01 = :id_socsyst10
        into :rela_sicxmls01,
             :rela_socsyst10_tct01,
             :rela_siccont02,
             :id_sicxmls03,
             :sicxmls03_fapl,
             :siccont02_codigo_ext,
             :siccont02_descripcion;

        if (id_sicxmls03 is null) then
        begin
            idfalso = idfalso - 1;
            rela_siccont02 = null;
            rela_sicxmls01 = :rela_sicxmls01x;
            rela_socsyst10_tct01 = :id_socsyst10;
            id_sicxmls03 = :idfalso;
            sicxmls03_fapl = current_timestamp;
            CUENTA = NULL;
        end
        ELSE
            CUENTA = trim(siccont02_codigo_ext) || ' - ' || trim(siccont02_descripcion);

        if (socsyst10_codigo like 'AJUSTE%' or socsyst10_codigo like 'TRASPASO') then
        begin
            conta_00 = conta_00 + 1;
            socsyst10_descripcion = '0.' || conta_00 || '.- ' || socsyst10_descripcion;
                
            color = 0;
        end
        else if (socsyst10_codigo like 'CIERRE%') then
        begin
            conta_01 = conta_01 + 1;
            socsyst10_descripcion = '1.' || conta_01 || '.- ' || socsyst10_descripcion;

            color = 1;
        end
        else if (socsyst10_codigo like 'CLIENTE%') then
        begin
            conta_02 = conta_02 + 1;
            socsyst10_descripcion = '2.' || conta_02 || '.- ' || socsyst10_descripcion;
            color = 2;
        end
        else if (socsyst10_codigo like 'COTIZA%') then
        begin
            conta_03 = conta_03 + 1;
            socsyst10_descripcion = '3.' || conta_03 || '.- ' || socsyst10_descripcion;

            color = 3;
        end
        else if (socsyst10_codigo like 'CRE%') then
        begin
            conta_04 = conta_04 + 1;
            socsyst10_descripcion = '4.' || conta_04 || '.- ' || socsyst10_descripcion;

            color = 4;
        end
        else if (socsyst10_codigo like 'DESC%') then
        begin
            conta_05 = conta_05 + 1;
            socsyst10_descripcion = '5.' || conta_05 || '.- ' || socsyst10_descripcion;

            color = 5;
        end
        else if (socsyst10_codigo like 'NOMINA%') then
        begin
            conta_06 = conta_06 + 1;
            socsyst10_descripcion = '6.' || conta_06 || '.- ' || socsyst10_descripcion;

            color = 6;
        end
        else if (socsyst10_codigo like 'PROVE%') then
        begin
            conta_07 = conta_07 + 1;
            socsyst10_descripcion = '7.' || conta_07 || '.- ' || socsyst10_descripcion;

            color = 7;
        end

        suspend;
    end


end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS04_CON_MIGRA (
    RELA_SICXMLS01X BIGINT,
    MODALIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MARCA INTEGER,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICXMLS01 BIGINT,
    RELA_SOCSYST10_TCT01 BIGINT,
    RELA_SICCONT02 BIGINT,
    ID_SICXMLS04 BIGINT,
    SICXMLS04_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS04_EXCENTO INTEGER,
    EXCENTO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS04_DEDUCIBLE INTEGER,
    DEDUCIBLE VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVEPRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODIGO_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS04_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS04_FAPL TIMESTAMP,
    BUSQUEDA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    /*
        MODALIDAD  = 0 CLIENTE
        MODALIDAD  = 1 PROVEEDOR
    */
    FOR SELECT
    GRD_SICXMLS04_CON.MARCA,
    GRD_SICXMLS04_CON.SOCSYST10_DESCRIPCION,
    GRD_SICXMLS04_CON.CUENTA,
    GRD_SICXMLS04_CON.RELA_SICXMLS01,
    GRD_SICXMLS04_CON.RELA_SOCSYST10_TCT01,
    GRD_SICXMLS04_CON.RELA_SICCONT02,
    GRD_SICXMLS04_CON.ID_SICXMLS04,
    GRD_SICXMLS04_CON.SICXMLS04_TIPO,
    GRD_SICXMLS04_CON.TIPO,
    GRD_SICXMLS04_CON.SICXMLS04_EXCENTO,
    GRD_SICXMLS04_CON.EXCENTO,
    GRD_SICXMLS04_CON.SICXMLS04_DEDUCIBLE,
    GRD_SICXMLS04_CON.DEDUCIBLE,
    GRD_SICXMLS04_CON.UNIDAD,
    GRD_SICXMLS04_CON.CLAVEPRODUCTO,
    GRD_SICXMLS04_CON.CODIGO_CONCEPTO,
    GRD_SICXMLS04_CON.SICXMLS04_CONCEPTO,
    GRD_SICXMLS04_CON.SICXMLS04_FAPL,
    GRD_SICXMLS04_CON.BUSQUEDA
    FROM GRD_SICXMLS04_CON where RELA_SICXMLS01 = :rela_sicxmls01x
    and TRIM(UPPER(SOCSYST10_DESCRIPCION)) LIKE :modalidad
    and not exists ( select first 1 sicingr95_cab_conceptos.id_sicingr95
                     from sicingr95_cab_conceptos
                     where sicingr95_cab_conceptos.rela_sicxmls04 = GRD_SICXMLS04_CON.ID_SICXMLS04
                   )
    into :MARCA,
         :SOCSYST10_DESCRIPCION,
         :CUENTA,
         :RELA_SICXMLS01,
         :RELA_SOCSYST10_TCT01,
         :RELA_SICCONT02,
         :ID_SICXMLS04,
         :SICXMLS04_TIPO,
         :TIPO,
         :SICXMLS04_EXCENTO,
         :EXCENTO,
         :SICXMLS04_DEDUCIBLE,
         :DEDUCIBLE,
         :UNIDAD,
         :CLAVEPRODUCTO,
         :CODIGO_CONCEPTO,
         :SICXMLS04_CONCEPTO,
         :SICXMLS04_FAPL,
         :BUSQUEDA

    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS40 (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X BIGINT,
    FECHA_DESDEX DATE,
    FECHA_HASTAX DATE)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    ID_SICXMLS40 BIGINT,
    SICXMLS40_FECHA_PROCESO DATE,
    SICXMLS40_FAPL TIMESTAMP,
    CANT_PROVE INTEGER,
    SUMA_PROVE DOUBLE PRECISION,
    CANT_CLIENTE INTEGER,
    SUMA_CLIENTE DOUBLE PRECISION,
    CANT_NOMINA INTEGER,
    SUMA_NOMINA DOUBLE PRECISION,
    TOTAL_CFDIS DOUBLE PRECISION,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODALIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
AS
declare variable ORIGEN_AUTOMATICO varchar(1);
begin
    FOR SELECT
    sicxmls40_cab_migracion.rela_socmain01,
    sicxmls40_cab_migracion.rela_socmain21,
    sicxmls40_cab_migracion.rela_socusua01,
    sicxmls40_cab_migracion.id_sicxmls40,
    sicxmls40_cab_migracion.sicxmls40_fapl,
    sicxmls40_cab_migracion.sicxmls40_fecha_proceso
    FROM sicxmls40_cab_migracion
    WHERE sicxmls40_cab_migracion.rela_socmain01 = :rela_socmain01x
    AND sicxmls40_cab_migracioN.rela_socmain21 = :rela_socmain21x
    AND sicxmls40_cab_migracion.sicxmls40_fecha_proceso between :fecha_desdex and :fecha_hastax
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :id_sicxmls40,
         :sicxmls40_fapl,
         :sicxmls40_fecha_proceso
    do
    begin
        modalidad = '';

        select
        min(sicxmls41_det_migracion.sicxmls41_origen),
        sum(sicxmls41_det_migracion.sicxmls41_uuid_importe),
        count(sicxmls41_det_migracion.id_sicxmls41)
        from sicxmls41_det_migracion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01)
        where sicxmls41_det_migracion.rela_sicxmls40 = :id_sicxmls40
        and socsyst10_det_entradas.socsyst10_codigo = 'PROVE'
        into :origen_automatico,
             :suma_prove,
             :cant_prove;

        if (suma_prove is null) then
            suma_prove = 0;
        else
            modalidad = 'PRO';

        select
        min(sicxmls41_det_migracion.sicxmls41_origen),
        sum(sicxmls41_det_migracion.sicxmls41_uuid_importe),
        count(sicxmls41_det_migracion.id_sicxmls41)
        from sicxmls41_det_migracion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01)
        where sicxmls41_det_migracion.rela_sicxmls40 = :id_sicxmls40
        and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE'
        into :origen_automatico,
             :suma_cliente,
             :cant_cliente;

        if (suma_cliente is null) then
            suma_cliente = 0;
        else
            modalidad = modalidad || '-CLI';

        select
        min(sicxmls41_det_migracion.sicxmls41_origen),
        sum(sicxmls41_det_migracion.sicxmls41_uuid_importe),
        count(sicxmls41_det_migracion.id_sicxmls41)
        from sicxmls41_det_migracion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01)
        where sicxmls41_det_migracion.rela_sicxmls40 = :id_sicxmls40
        and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA'
        into :origen_automatico,
             :suma_nomina,
             :cant_nomina;

        if (suma_nomina is null) then
            suma_nomina = 0;
        else
            modalidad = modalidad || '-NOM';

        total_cfdis = suma_cliente - (suma_prove + suma_nomina);

        FECHA_DESDE = null;
        FECHA_HASTA = null;
        status = 'MANUAL';

        select
        sicxmls51_mov_descargasat.sicxmls51_fini,
        sicxmls51_mov_descargasat.sicxmls51_ffin,
        sicxmls51_mov_descargasat.sicxmls51_modalidad
        from sicxmls50_det_descargasat
        inner join sicxmls51_mov_descargasat on (sicxmls51_mov_descargasat.id_sicxmls51 = sicxmls50_det_descargasat.rela_sicxmls51)
        where sicxmls50_det_descargasat.rela_sicxmls40 = :id_sicxmls40
        into :fecha_desde,
             :fecha_hasta,
             :modalidad;

        if (fecha_desde is not null) then
            status = 'AUTOMATICO';
        else 
        begin
             if (origen_automatico is not null and origen_automatico = 'N') then
                modalidad = 'SYS-NOMI';
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS41 (
    ID_SOCMAIN01 BIGINT,
    MODALIDAD INTEGER,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    MARCA INTEGER,
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_XML VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICXMLS41 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICXMLS41_ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_UUID_FECHA DATE,
    SICXMLS41_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_TIPOCOMPROBANTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_CAMBIO DOUBLE PRECISION,
    SICXMLS41_SUBTOTAL DOUBLE PRECISION,
    SICXMLS41_DESCUENTO DOUBLE PRECISION,
    EXTRANJERO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_DIFERENCIA DOUBLE PRECISION,
    SICXMLS41_FECHA_PAGO DATE,
    SICXMLS41_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_ORIGEN VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_CFDI VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SICXMLS41_EXTRANJERO integer;
declare variable RELA_SICCONT10 bigint;
declare variable FILTRO varchar(50);
declare variable TIPO_XML_CREDITO varchar(50);
declare variable STR_SQL varchar(8000);
begin
    STATUS_CFDI = NULL;

    if (modalidad = 0) then
        filtro = 'CLIENTE';
    else if (modalidad = 1) then
        filtro = 'PROVE';
    else if (modalidad = 2) then
        filtro = 'NOMINA';


    str_sql =  'select
                0,
                tct01.socsyst10_codigo,
                xml01.socsyst10_codigo,
                sicxmls41_det_migracion.rela_siccont10,
                sicxmls41_det_migracion.id_sicxmls41,
                sicxmls41_det_migracion.sicxmls41_entidad,
                sicxmls41_det_migracion.sicxmls41_rfc,
                sicxmls41_det_migracion.sicxmls41_folio,
                sicxmls41_det_migracion.sicxmls41_uuid,
                sicxmls41_det_migracion.sicxmls41_uuid_importe,
                sicxmls41_det_migracion.sicxmls41_uuid_fecha,
                sicxmls41_det_migracion.sicxmls41_uuid_smx,
                sicxmls41_det_migracion.sicxmls41_tipocomprobante,
                sicxmls41_det_migracion.sicxmls41_metododepago,
                sicxmls41_det_migracion.sicxmls41_formapago,
                sicxmls41_det_migracion.sicxmls41_moneda,
                sicxmls41_det_migracion.sicxmls41_cambio,
                sicxmls41_det_migracion.sicxmls41_subtotal,
                sicxmls41_det_migracion.sicxmls41_descuento,
                sicxmls41_det_migracion.sicxmls41_extranjero,
                sicxmls41_det_migracion.sicxmls41_diferencia,
                sicxmls41_det_migracion.sicxmls41_fecha_pago,
                sicxmls41_det_migracion.sicxmls41_curp,
                sicxmls41_det_migracion.sicxmls41_origen
                FROM sicxmls40_cab_migracion
                INNER JOIN sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
                inner join socsyst10_det_entradas tct01 on ( tct01.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01 )
                inner join socsyst10_det_entradas xml01 on ( xml01.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01 )
                WHERE sicxmls40_cab_migracion.rela_socmain01 = ' || :id_socmain01 ||
                iif(modalidad >= 0 and modalidad <=2, ' and xml01.socsyst10_codigo = ''' || :filtro || '''', '') ||
                ' and sicxmls41_det_migracion.sicxmls41_uuid_fecha between ''' || :fecha_desde || ''' and ''' || :fecha_hasta || '''';

    for execute statement :str_sql
    INTO :marca,
         :tipo_xml_credito,
         :origen,
         :rela_siccont10,
         :id_sicxmls41,
         :sicxmls41_entidad,
         :sicxmls41_rfc,
         :sicxmls41_folio,
         :sicxmls41_uuid,
         :sicxmls41_uuid_importe,
         :sicxmls41_uuid_fecha,
         :sicxmls41_uuid_smx,
         :sicxmls41_tipocomprobante,
         :sicxmls41_metododepago,
         :sicxmls41_formapago,
         :sicxmls41_moneda,
         :sicxmls41_cambio,
         :sicxmls41_subtotal,
         :sicxmls41_descuento,
         :sicxmls41_extranjero,
         :sicxmls41_diferencia,
         :sicxmls41_fecha_pago,
         :sicxmls41_curp,
         :sicxmls41_origen
    DO
    BEGIN
        siccont10_docnro = 'Pendiente';
        siccont10_fcta = null;
        tipo_xml = 'No';

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
        else
           CRP = 'No';


        if ( POSITION('CREDITO' IN upper(tipo_xml_credito)) <> 0 ) then
            tipo_xml = 'Si';

        if (sicxmls41_extranjero = 0) then
            extranjero = 'No';
        else
            extranjero = 'SI';

        if (rela_siccont10 IS NOT NULL) then
        begin
            Select
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta
            from siccont10_cab_polizas
            where siccont10_cab_polizas.id_siccont10 = :rela_siccont10
            into :siccont10_docnro,
                 :siccont10_fcta;
        end

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS41_IMPUESTOS (
    ID_SOCMAIN01 BIGINT,
    MODALIDAD INTEGER,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    MARCA INTEGER,
    RELA_SOCUSUA30 BIGINT,
    ID_SICXMLS41 BIGINT,
    SICCONT10_DOCNRO INTEGER,
    SICCONT10_FCTA DATE,
    SICXMLS41_ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_TIPOCOMPROBANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_UUID_FECHA DATE,
    SICXMLS41_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_PAGO_O_COBRO DOUBLE PRECISION,
    BASE_IMPONIBLE DOUBLE PRECISION,
    BASE_IMPONIBLE8 DOUBLE PRECISION,
    BASE_CERO_EXCE DOUBLE PRECISION,
    IVA_TRAS DOUBLE PRECISION,
    IVA_TRAS8 DOUBLE PRECISION,
    IVA_RETE DOUBLE PRECISION,
    IVA_RETE8 DOUBLE PRECISION,
    IVA_EXENTO DOUBLE PRECISION,
    IVA_CERO DOUBLE PRECISION,
    IEPS_TRAS DOUBLE PRECISION,
    IEPS_RETE DOUBLE PRECISION,
    ISR_RETE DOUBLE PRECISION,
    IMPORTE_NODEDUC DOUBLE PRECISION,
    STATUS_CFDI VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable FILTRO varchar(50);
declare variable FILTROX varchar(50);
begin
    STATUS_CFDI = NULL;

    if (modalidad = 4) then
    BEGIN
        filtro = 'CLIENTE';
        filtrox = 'CLIENTEX';
    END
    else if (modalidad = 5) then
    BEGIN
        filtro = 'PROVE';
        filtrox = 'PROVEX';
    END
    else if (modalidad = 6) then
    BEGIN
        filtro = 'NOMINA';
        filtrox = 'NOMINA';
    END

    for select
    0,
    sicxmls41_det_migracion.rela_socusua30,
    sicxmls41_det_migracion.id_sicxmls41,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sicxmls41_det_migracion.sicxmls41_tipocomprobante,
    sicxmls41_det_migracion.sicxmls41_entidad,
    sicxmls41_det_migracion.sicxmls41_rfc,
    sicxmls41_det_migracion.sicxmls41_folio,
    sicxmls41_det_migracion.sicxmls41_uuid,
    sicxmls41_det_migracion.sicxmls41_metododepago,
    sicxmls41_det_migracion.sicxmls41_formapago,
    sicxmls41_det_migracion.sicxmls41_uuid_importe,
    sicxmls41_det_migracion.sicxmls41_uuid_fecha,
    sicxmls41_det_migracion.sicxmls41_uuid_smx
    FROM sicxmls40_cab_migracion
    INNER JOIN sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
    inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicxmls41_det_migracion.rela_siccont10 )
    inner join socsyst10_det_entradas tct01 on ( tct01.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01 )
    inner join socsyst10_det_entradas xml01 on ( xml01.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01 )
    WHERE sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
    and (tct01.socsyst10_codigo = :filtro or tct01.socsyst10_codigo = :filtrox)
    INTO :marca,
         :rela_socusua30,
         :id_sicxmls41,
         :siccont10_docnro,
         :siccont10_fcta,
         :sicxmls41_tipocomprobante,
         :sicxmls41_entidad,
         :sicxmls41_rfc,
         :sicxmls41_folio,
         :sicxmls41_uuid,
         :sicxmls41_metododepago,
         :sicxmls41_formapago,
         :sicxmls41_uuid_importe,
         :sicxmls41_uuid_fecha,
         :sicxmls41_uuid_smx
    DO
    BEGIN
        importe_pago_o_cobro = null;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
        else
           CRP = 'No';

        if (modalidad = 4) then
            SELECT rep_sicingr50_sum.importe_pago
            FROM rep_sicingr50_sum(:id_sicxmls41, :fecha_desde, :fecha_hasta)
            into :importe_pago_o_cobro;
        else  if (modalidad = 5) then
        BEGIN
            SELECT rep_sicegre50_sum.importe_pago
            FROM rep_sicegre50_sum(:id_sicxmls41, :fecha_desde, :fecha_hasta)
            into :importe_pago_o_cobro;
        END
        else
        begin
           importe_pago_o_cobro =  sicxmls41_uuid_importe;
           CRP = '';
        end

        importe_pago_o_cobro = iif(importe_pago_o_cobro is null, 0, :importe_pago_o_cobro);

        if (importe_pago_o_cobro <> 0) then
        begin
            SELECT
            grd_sicxmls41_impuestos_det.iva_tras,
            grd_sicxmls41_impuestos_det.iva_tras8,
            grd_sicxmls41_impuestos_det.iva_rete,
            grd_sicxmls41_impuestos_det.iva_rete8,
            grd_sicxmls41_impuestos_det.iva_exento,
            grd_sicxmls41_impuestos_det.iva_cero,
            grd_sicxmls41_impuestos_det.ieps_tras,
            grd_sicxmls41_impuestos_det.ieps_rete,
            grd_sicxmls41_impuestos_det.isr_rete,
            grd_sicxmls41_impuestos_det.importe_nodeduc,
            grd_sicxmls41_impuestos_det.base_imponible,
            grd_sicxmls41_impuestos_det.base_imponible8,
            grd_sicxmls41_impuestos_det.base_cero_exce
            FROM grd_sicxmls41_impuestos_det( :id_sicxmls41,
                                              :sicxmls41_uuid_importe,
                                              :importe_pago_o_cobro )
            into :iva_tras,
                 :iva_tras8,
                 :iva_rete,
                 :iva_rete8,
                 :iva_exento,
                 :iva_cero,
                 :ieps_tras,
                 :ieps_rete,
                 :isr_rete,
                 :importe_nodeduc,
                 :base_imponible,
                 :base_imponible8,
                 :base_cero_exce;

            suspend;
        end
    END
end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS41_IMPUESTOS_DET (
    ID_SICXMLS41 BIGINT,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_PAGO_O_COBRO DOUBLE PRECISION)
RETURNS (
    IVA_TRAS DOUBLE PRECISION,
    IVA_RETE DOUBLE PRECISION,
    IVA_TRAS8 DOUBLE PRECISION,
    IVA_RETE8 DOUBLE PRECISION,
    IEPS_TRAS DOUBLE PRECISION,
    IEPS_RETE DOUBLE PRECISION,
    ISR_RETE DOUBLE PRECISION,
    IMPORTE_NODEDUC DOUBLE PRECISION,
    BASE_IMPONIBLE DOUBLE PRECISION,
    BASE_IMPONIBLE8 DOUBLE PRECISION,
    BASE_CERO_EXCE DOUBLE PRECISION,
    IVA_EXENTO DOUBLE PRECISION,
    IVA_CERO DOUBLE PRECISION)
AS
declare variable PORCENTAJE double precision;
begin
    importe_pago_o_cobro = iif(importe_pago_o_cobro is null, 0, :importe_pago_o_cobro);

    porcentaje = importe_pago_o_cobro / importe_xml * 100;

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'IVA' or sicxmls43_det_impuestos.sicxmls43_impuesto = '002')
    and (sicxmls43_det_impuestos.sicxmls43_tasa = 16 or sicxmls43_det_impuestos.sicxmls43_tasa = 0.16)
    and sicxmls43_det_impuestos.sicxmls43_retenido = 0
    into :iva_tras;

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'IVA' or sicxmls43_det_impuestos.sicxmls43_impuesto = '002')
    and (sicxmls43_det_impuestos.sicxmls43_tasa = 8 or sicxmls43_det_impuestos.sicxmls43_tasa = 0.08)
    and sicxmls43_det_impuestos.sicxmls43_retenido = 0
    into :iva_tras8;

    /* ------------------------------------------------------------------------------------------------------------------ */

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'IVA' or sicxmls43_det_impuestos.sicxmls43_impuesto = '002')
    and (sicxmls43_det_impuestos.sicxmls43_tasa = 16 or sicxmls43_det_impuestos.sicxmls43_tasa = 0.16)
    and sicxmls43_det_impuestos.sicxmls43_retenido = 1
    into :iva_rete;

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'IVA' or sicxmls43_det_impuestos.sicxmls43_impuesto = '002')
    and (sicxmls43_det_impuestos.sicxmls43_tasa = 8 or sicxmls43_det_impuestos.sicxmls43_tasa = 0.08)
    and sicxmls43_det_impuestos.sicxmls43_retenido = 1
    into :iva_rete8;

    /* ------------------------------------------------------------------------------------------------------------------ */

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'IEPS' or sicxmls43_det_impuestos.sicxmls43_impuesto = '003')
    and sicxmls43_det_impuestos.sicxmls43_retenido = 0
    into :ieps_tras;

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'IEPS' or sicxmls43_det_impuestos.sicxmls43_impuesto = '003')
    and sicxmls43_det_impuestos.sicxmls43_retenido = 1
    into :ieps_rete;

    select sum(sicxmls43_det_impuestos.sicxmls43_importe)
    from sicxmls43_det_impuestos
    where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
    and (sicxmls43_det_impuestos.sicxmls43_impuesto = 'ISR' or sicxmls43_det_impuestos.sicxmls43_impuesto = '001')
    and sicxmls43_det_impuestos.sicxmls43_retenido = 1
    into :isr_rete;

    select sum(sicxmls42_det_conceptos.sicxmls42_importe)
    from sicxmls42_det_conceptos
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicxmls42_det_conceptos.rela_sicxmls04 )
    where sicxmls42_det_conceptos.rela_sicxmls41 = :id_sicxmls41
    and sicxmls04_det_conceptos.sicxmls04_deducible = 0
    into :importe_nodeduc;

    /* ------------------------------------------------------------------------------------------------------------------ */

    select sum(sicxmls42_det_conceptos.sicxmls42_importe)
    from sicxmls42_det_conceptos
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicxmls42_det_conceptos.rela_sicxmls04 )
    where sicxmls42_det_conceptos.rela_sicxmls41 = :id_sicxmls41
    and sicxmls04_det_conceptos.sicxmls04_deducible = 1
    and sicxmls04_det_conceptos.sicxmls04_excento = 0
    into :iva_exento;

    /* ------------------------------------------------------------------------------------------------------------------ */

    select sum(sicxmls42_det_conceptos.sicxmls42_importe)
    from sicxmls42_det_conceptos
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicxmls42_det_conceptos.rela_sicxmls04 )
    where sicxmls42_det_conceptos.rela_sicxmls41 = :id_sicxmls41
    and sicxmls04_det_conceptos.sicxmls04_deducible = 1
    and sicxmls04_det_conceptos.sicxmls04_excento = 1
    into :iva_cero;

    /* ------------------------------------------------------------------------------------------------------------------ */

    iva_tras = iif(:iva_tras is null or :iva_tras = 0, 0, :iva_tras * :porcentaje / 100);
    iva_tras8 = iif(:iva_tras8 is null or :iva_tras8 = 0, 0, :iva_tras8 * :porcentaje / 100);
    iva_rete = iif(:iva_rete is null or :iva_rete = 0, 0, :iva_rete * :porcentaje / 100);
    iva_rete8 = iif(:iva_rete8 is null or :iva_rete8 = 0, 0, :iva_rete8 * :porcentaje / 100);
    iva_exento = iif(:iva_exento is null or :iva_exento = 0, 0, :iva_exento * :porcentaje / 100);
    iva_cero = iif(:iva_cero is null or :iva_cero = 0, 0, :iva_cero * :porcentaje / 100);
    ieps_tras = iif(:ieps_tras is null or :ieps_tras = 0, 0, :ieps_tras * :porcentaje / 100);
    ieps_rete = iif(:ieps_rete is null or :ieps_rete = 0, 0, :ieps_rete * :porcentaje / 100);
    isr_rete = iif(:isr_rete is null or :isr_rete = 0, 0, :isr_rete * :porcentaje / 100);
    importe_nodeduc = iif(:importe_nodeduc is null or :importe_nodeduc = 0, 0, :importe_nodeduc * :porcentaje / 100);

    base_imponible = 0;

    if (iva_tras <> 0) then
    begin
        base_imponible = iva_tras / 16 * 100;
    end

    if (iva_tras8 <> 0) then
    begin
        base_imponible8 = iva_tras8 / 8 * 100;
    end

    base_imponible8 = iif(:base_imponible8 is null or :base_imponible8 = 0, 0, :base_imponible8 * :porcentaje / 100);
    base_cero_exce = iva_exento + iva_cero;

    suspend;
end^


CREATE OR ALTER PROCEDURE GRD_SICXMLS77 (
    RELA_SOCMAIN01 BIGINT,
    MODALIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MARCA INTEGER,
    ID_SICXMLS77 BIGINT,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_FECHA TIMESTAMP,
    UUID_IMPORTE DOUBLE PRECISION,
    UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FCANCELADO TIMESTAMP)
AS
declare variable RELA_PERSONA bigint;
begin
    modalidad = upper(modalidad);
    id_sicxmls77 = 0;
    marca = 0;

    if (modalidad = 'E') then
    BEGIN
        for select
        sicingr70_cab_facturacion.rela_sicingr01,
        sicingr77_det_cfdiscancelados.sicingr77_folio,
        sicingr77_det_cfdiscancelados.sicingr77_uuid,
        sicingr77_det_cfdiscancelados.sicingr77_uuid_fecha,
        sicingr77_det_cfdiscancelados.sicingr77_uuid_importe,
        sicingr77_det_cfdiscancelados.sicingr77_uuid_smx,
        sicingr77_det_cfdiscancelados.sicingr77_status,
        sicingr77_det_cfdiscancelados.sicingr77_fcancelado
        from sicingr77_det_cfdiscancelados
        inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr77_det_cfdiscancelados.rela_sicingr70)
        where sicingr70_cab_facturacion.rela_socmain01 = :rela_socmain01
        and sicingr77_det_cfdiscancelados.sicingr77_conaceptacion = 1
        into :rela_persona,
             :folio,
             :uuid,
             :uuid_fecha,
             :uuid_importe,
             :uuid_smx,
             :status,
             :fcancelado
        do
        begin
            id_sicxmls77 = id_sicxmls77 + 1;
            tipo = 'Facturación';
            select
            cbo_sicingr01_id.entidad,
            cbo_sicingr01_id.rfc
            from cbo_sicingr01_id
            where cbo_sicingr01_id.id_sicingr01 = :rela_persona
            into :entidad,
                 :entidad_rfc;

            suspend;
        end

        /* ------------------------------------------------------------------------------------------------------------------- */
        /* ------------------------------------------------------------------------------------------------------------------- */

        for select
        sicingr51_cab_bancos.rela_sicingr01,
        sicpago77_det_cfdiscancelados.sicpago77_folio,
        sicpago77_det_cfdiscancelados.sicpago77_uuid,
        sicpago77_det_cfdiscancelados.sicpago77_uuid_fecha,
        sicpago77_det_cfdiscancelados.sicpago77_uuid_importe,
        sicpago77_det_cfdiscancelados.sicpago77_uuid_smx,
        sicpago77_det_cfdiscancelados.sicpago77_status,
        sicpago77_det_cfdiscancelados.sicpago77_fcancelado
        from sicpago77_det_cfdiscancelados
        inner join sicpago70_cab_pago on (sicpago70_cab_pago.id_sicpago70 = sicpago77_det_cfdiscancelados.rela_sicpago70)
        inner join sicingr51_cab_bancos on (sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51)
        where sicpago70_cab_pago.rela_socmain01 = :rela_socmain01
        and sicpago77_det_cfdiscancelados.sicpago77_conaceptacion = 1
        into :rela_persona,
             :folio,
             :uuid,
             :uuid_fecha,
             :uuid_importe,
             :uuid_smx,
             :status,
             :fcancelado
        do
        begin
            id_sicxmls77 = id_sicxmls77 + 1;
            tipo = 'Pago';
            select
            cbo_sicingr01_id.entidad,
            cbo_sicingr01_id.rfc
            from cbo_sicingr01_id
            where cbo_sicingr01_id.id_sicingr01 = :rela_persona
            into :entidad,
                 :entidad_rfc;

            suspend;
        end

        /* ------------------------------------------------------------------------------------------------------------------- */
        /* ------------------------------------------------------------------------------------------------------------------- */

        for select
        sicnomi70_cab_nomina.rela_sicnomi01,
        sicnomi77_det_cfdiscancelados.sicnomi77_folio,
        sicnomi77_det_cfdiscancelados.sicnomi77_uuid,
        sicnomi77_det_cfdiscancelados.sicnomi77_uuid_fecha,
        sicnomi77_det_cfdiscancelados.sicnomi77_uuid_importe,
        sicnomi77_det_cfdiscancelados.sicnomi77_uuid_smx,
        sicnomi77_det_cfdiscancelados.sicnomi77_status,
        sicnomi77_det_cfdiscancelados.sicnomi77_fcancelado
        from sicnomi77_det_cfdiscancelados
        inner join sicnomi70_cab_nomina on (sicnomi70_cab_nomina.id_sicnomi70 = sicnomi77_det_cfdiscancelados.rela_sicnomi70)
        where sicnomi70_cab_nomina.rela_socmain01 = :rela_socmain01
        and sicnomi77_det_cfdiscancelados.sicnomi77_conaceptacion = 1
        into :rela_persona,
             :folio,
             :uuid,
             :uuid_fecha,
             :uuid_importe,
             :uuid_smx,
             :status,
             :fcancelado
        do
        begin
            id_sicxmls77 = id_sicxmls77 + 1;
            tipo = 'Nómina';
            select
            cbo_sicnomi01_id.entidad,
            cbo_sicnomi01_id.rfc
            from cbo_sicnomi01_id
            where cbo_sicnomi01_id.id_sicnomi01 = :rela_persona
            into :entidad,
                 :entidad_rfc;

            suspend;
        end
    END
    ELSE if (modalidad = 'R') then
    BEGIN
        for select
        sicxmls41_det_migracion.sicxmls41_entidad,
        sicxmls41_det_migracion.sicxmls41_rfc,
        sicxmls41_det_migracion.sicxmls41_folio,
        sicxmls41_det_migracion.sicxmls41_uuid,
        sicxmls41_det_migracion.sicxmls41_uuid_importe,
        sicxmls41_det_migracion.sicxmls41_uuid_fecha,
        sicxmls41_det_migracion.sicxmls41_uuid_smx,
        sicxmls77_cab_porcancelar.sicxmls77_status,
        sicxmls77_cab_porcancelar.sicxmls77_fapl
        from sicxmls77_cab_porcancelar
        inner join sicxmls41_det_migracion on (sicxmls41_det_migracion.id_sicxmls41 = sicxmls77_cab_porcancelar.rela_sicxmls41)
        where sicxmls77_cab_porcancelar.rela_socmain01 = :rela_socmain01
        into :entidad,
             :entidad_rfc,
             :folio,
             :uuid,
             :uuid_importe,
             :uuid_fecha,
             :uuid_smx,
             :status,
             :fcancelado
        do
        begin
            id_sicxmls77 = id_sicxmls77 + 1;
            tipo = 'Proveedor';
            suspend;
        end
    END
end^


CREATE OR ALTER PROCEDURE GRD_SOCJARS20_FOLIOS
RETURNS (
    ID_FOLIOS INTEGER,
    INSTANCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
