    CONSUMIDOS INTEGER,
    SALDO INTEGER,
    PAC VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ULT_FECHA DATE,
    FECHA_FOLIOS DATE)
AS
declare variable SOCSYST10 varchar(400);
begin
    ID_FOLIOS = 0;
    SOCSYST10 = 'SELECT * FROM SMX$SOC_FOLIOS';

    for execute statement :SOCSYST10
    on external 'SMXSEG'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :INSTANCIA,
         :RFC,
         :EMPRESA,
         :EMPRESA_FECHA,
         :COMPRADOS,
         :CONSUMIDOS,
         :SALDO,
