        suspend;
    end
end^


CREATE OR ALTER PROCEDURE GRD_SOCJARS20_SICINGR70_COLORES (
    ICOLOR INTEGER)
RETURNS (
    COLOR_DES VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (icolor = 1) then
        color_des = 'Vencidos';
    else if (icolor = 2) then
        color_des = 'Por Vencer';
    else if (icolor = 4) then
        color_des = 'Bancos';
    else if (icolor = 8) then
        color_des = 'Nuevos';
    else if (icolor = 9) then
        color_des = 'Oportunos';

    suspend;
end^


