    SOCSYST13_REPORTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_FXML VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_ACTIVO INTEGER,
    SOCSYST13_FAPL TIMESTAMP,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ACTIVO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    FOR select
    socsyst01_cab_funciones.socsyst01_descripcion,
    SOCSYST13_CAB_REPORTES.rela_socsyst01,
    SOCSYST13_CAB_REPORTES.id_socsyst13,
    SOCSYST13_CAB_REPORTES.socsyst13_codigo,
    SOCSYST13_CAB_REPORTES.socsyst13_descripcion,
    SOCSYST13_CAB_REPORTES.socsyst13_reporte,
    SOCSYST13_CAB_REPORTES.socsyst13_fxml,
    SOCSYST13_CAB_REPORTES.socsyst13_tipo,
    SOCSYST13_CAB_REPORTES.socsyst13_activo,
    SOCSYST13_CAB_REPORTES.socsyst13_fapl
    from SOCSYST13_CAB_REPORTES
    inner join socsyst01_cab_funciones on (socsyst01_cab_funciones.id_socsyst01 = SOCSYST13_CAB_REPORTES.rela_socsyst01)
    into :socsyst01_descripcion,
         :rela_socsyst01,
         :id_socsyst13,
         :socsyst13_codigo,
         :socsyst13_descripcion,
         :socsyst13_reporte,
         :socsyst13_fxml,
         :socsyst13_tipo,
         :socsyst13_activo,
         :socsyst13_fapl
    do
    begin
        if (socsyst13_tipo = 'L') then
            tipo = 'Local';
        else if (socsyst13_tipo = 'R') then
            tipo = 'Remoto';

        if (SOCSYST13_ACTIVO = 0) then
            activo = 'No';
        else if (SOCSYST13_ACTIVO = 1) then
            activo = 'Si';

        suspend;
    end
end^


