CREATE OR ALTER PROCEDURE GRD_SYSUSER21 (
    RELA_SYSUSER20 BIGINT,
    EMISOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SYSUSER21 BIGINT,
    SYSUSER21_EMISOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER21_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER21_RESUMEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER21_MENSAJE VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SYSUSER21_LEIDO INTEGER,
    SYSUSER21_FAPL TIMESTAMP)
AS
begin
    update sysuser21_det_mensajes set sysuser21_det_mensajes.sysuser21_leido = 1
    where sysuser21_det_mensajes.rela_sysuser20 = :rela_sysuser20
    and sysuser21_det_mensajes.sysuser21_emisor = iif(:emisor = 'Entidad', 'Ciudadano', 'Entidad')
    and sysuser21_det_mensajes.sysuser21_leido = 0;


    for select
    sysuser21_det_mensajes.id_sysuser21,
    sysuser21_det_mensajes.sysuser21_emisor,
    sysuser21_det_mensajes.sysuser21_folio,
    sysuser21_det_mensajes.sysuser21_resumen,
    sysuser21_det_mensajes.sysuser21_mensaje,
    sysuser21_det_mensajes.sysuser21_leido,
    sysuser21_det_mensajes.sysuser21_fapl
    from sysuser21_det_mensajes
    where sysuser21_det_mensajes.rela_sysuser20 = :rela_sysuser20
    order by SYSUSER21_FAPL desc
    into :id_sysuser21,
         :sysuser21_emisor,
         :sysuser21_folio,
         :sysuser21_resumen,
         :sysuser21_mensaje,
         :sysuser21_leido,
         :sysuser21_fapl
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_CFDI_MAIL_WEB (
    ID_TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID BIGINT)
RETURNS (
    ID_MAIL BIGINT,
    MAIL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
begin
    if (id_tipo = 'I' or id_tipo = 'P') then
    begin
        select
        sicingr01_cab_clientes.rela_socusua30,
        sicingr01_cab_clientes.sicingr01_mail
        from sicingr70_cab_facturacion
        inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.id_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01)
        where sicingr70_cab_facturacion.id_sicingr70 = :id
        into :rela_socusua30, :mail;
    end
    else if (id_tipo = 'N') then
    begin
        select
        sicnomi01_cab_empleados.rela_socusua30,
        sicnomi01_cab_empleados.sicnomi01_mail
        from sicnomi70_cab_nomina
        inner join sicnomi01_cab_empleados on (sicnomi01_cab_empleados.id_sicnomi01 = sicnomi70_cab_nomina.rela_sicnomi01)
        where sicnomi70_cab_nomina.id_sicnomi70 = :id
        into :rela_socusua30, :mail;
    end

    select cbo_socusua30_all.entidad
    from cbo_socusua30_all
    where cbo_socusua30_all.id_socusua30 = :rela_socusua30
    into :cliente;

    ID_MAIL = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_CFDI_UUID_WEB (
    MODALIDAD VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID BIGINT)
RETURNS (
    ID_UUID BIGINT,
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (modalidad = 'I') then
    begin
        select sicingr74_dep_cfdis.sicingr74_uuid
        from sicingr74_dep_cfdis
        where sicingr74_dep_cfdis.rela_sicingr70 = :id
        into :uuid;

        if (uuid is null) then
            select first 1 sicingr77_det_cfdiscancelados.sicingr77_uuid
            from sicingr77_det_cfdiscancelados
            where sicingr77_det_cfdiscancelados.rela_sicingr70 = :id
            order by sicingr77_det_cfdiscancelados.id_sicingr77 desc
            into :uuid;
    end
    else if (modalidad = 'P') then
    begin
        select sicpago74_dep_cfdis.sicpago74_uuid
        from sicpago74_dep_cfdis
        where sicpago74_dep_cfdis.rela_sicpago70 = :id
        into :uuid;

        if (uuid is null) then
            select first 1 sicpago77_det_cfdiscancelados.sicpago77_uuid
            from sicpago77_det_cfdiscancelados
            where sicpago77_det_cfdiscancelados.rela_sicpago70 = :id
            order by sicpago77_det_cfdiscancelados.id_sicpago77 desc
            into :uuid;
    end
    else if (modalidad = 'N') then
    begin
        select sicnomi74_dep_cfdis.sicnomi74_uuid
        from sicnomi74_dep_cfdis
        where sicnomi74_dep_cfdis.rela_sicnomi70 = :id
        into :uuid;

        if (uuid is null) then
            select first 1 sicnomi77_det_cfdiscancelados.sicnomi77_uuid
            from sicnomi77_det_cfdiscancelados
            where sicnomi77_det_cfdiscancelados.rela_sicnomi70 = :id
            order by sicnomi77_det_cfdiscancelados.id_sicnomi77 desc
            into :uuid;
    end

    id_uuid = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_LOGON_WEB (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCUSUA01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN20 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    USUARIO_NOMBRES VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PERFIL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable RFC varchar(20);
declare variable EMPRESA varchar(1200);
declare variable INSTANCIA varchar(50);
declare variable ID_PYMALMA01 bigint;
declare variable ID_SOCSYST10_STK01 bigint;
declare variable RELA_USUARIO_OK bigint;
declare variable ID_SOCSYST09 bigint;
begin
    Select first 1 distinct
    socusua01_cab_usuarios.rela_socusua30,
    socusua01_cab_usuarios.id_socusua01,
    socusua02_det_organizacion.rela_socmain01,
    socusua02_det_organizacion.rela_socmain20,
    socusua02_det_organizacion.rela_socmain21,
    cbo_socsyst10_ca001.socsyst10_codigo
    from socusua01_cab_usuarios
    inner join socusua02_det_organizacion on (socusua01_cab_usuarios.id_socusua01 = socusua02_det_organizacion.rela_socusua01)
    inner join cbo_socsyst10_ca001 on (cbo_socsyst10_ca001.id_socsyst10 = socusua02_det_organizacion.rela_socsyst10_ca001)
    where socusua01_usuario = :usuario
    and socusua01_clave = :clave
    into :rela_socusua30,
         :id_socusua01,
         :rela_socmain01,
         :rela_socmain20,
         :rela_socmain21,
         :perfil;

    if (id_socusua01 is not null) then
    BEGIN
        select cbo_socusua30_all.entidad
        from cbo_socusua30_all
        where cbo_socusua30_all.id_socusua30 = :rela_socusua30
        into :usuario_nombres;

        select socsyst50_cab_config.socsyst50_instancia
        from socsyst50_cab_config
        into :instancia;

        select
        cbo_socmain01.socmain01_nomcomercial,
        cbo_socmain01.rfc
        from cbo_socmain01
        where cbo_socmain01.id_socmain01 = :rela_socmain01
        into :empresa,
             :rfc;

        EXECUTE PROCEDURE SMX$SOC_EMPRESAS_SEG
                          :instancia,
                          :empresa,
                          :rfc,
                          :usuario,
                          1;

        EXECUTE PROCEDURE SMX$SOC_LOGON
                          :usuario,
                          :clave,
                          :instancia
        returning_values :rela_usuario_ok;

    
        INSERT INTO SOCSYST90_MOV_LOGS(SOCSYST90_MOV_LOGS.socsyst90_usuario,
                                       SOCSYST90_MOV_LOGS.socsyst90_accion,
                                       SOCSYST90_MOV_LOGS.socsyst90_tabla,
                                       SOCSYST90_MOV_LOGS.socsyst90_ultid)
        VALUES(current_user,
               'W',
               'SOCUSUA01',
               :id_socusua01);

        /* Esto deberia ir en otro lado. Por ahora lo pongo aqui. Solo verifico que si no tiene inventario agrego la cabecera de stock */
        select pymalma01_cab_stock.id_pymalma01
        from pymalma01_cab_stock
        where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
        and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
        into :id_pymalma01;

        if (id_pymalma01 is null) then
        begin
            insert into pymalma01_cab_stock(pymalma01_cab_stock.rela_socmain01,
                                            pymalma01_cab_stock.rela_socmain21,
                                            pymalma01_cab_stock.rela_socusua01)
            values(:rela_socmain01,
                   :rela_socmain21,
                   1);
        end

        SELECT cbo_socsyst10_stk01.id_socsyst10
        FROM cbo_socsyst10_stk01
        WHERE cbo_socsyst10_stk01.socsyst10_codigo = 'STK-MANUAL-INVENTARIO'
        into :id_socsyst10_stk01;
    
        if (id_socsyst10_stk01 is null) then
        begin
            SELECT first 1 socsyst09_cab_entradas.id_socsyst09
            FROM socsyst09_cab_entradas
            INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.rela_socsyst09 = socsyst09_cab_entradas.id_socsyst09)
            WHERE socsyst09_cab_entradas.socsyst09_codigo = 'STK01'
            INTO :ID_SOCSYST09;

            insert into socsyst10_det_entradas(socsyst10_det_entradas.rela_socsyst09,
                                               socsyst10_det_entradas.socsyst10_codigo,
                                               socsyst10_det_entradas.socsyst10_descripcion,
                                               socsyst10_det_entradas.socsyst10_grupo)
            values(:ID_SOCSYST09,
                   'STK-MANUAL-INVENTARIO',
                   'Movimmiento manual',
                   'NONE'
            );
        end


        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_PYMALMA04_INSERT (
    ID_PYMALMA01 BIGINT,
    ID_PYMALMA02 BIGINT,
    ID_SICINGR95 BIGINT)
AS
declare variable ALMACEN varchar(50);
declare variable RACK varchar(50);
declare variable COLUMNA varchar(50);
declare variable FILA varchar(50);
begin
    almacen = null;

    select first 1
    pymalma04_mov_locaciones.pymalma04_almacen,
    pymalma04_mov_locaciones.pymalma04_rack,
    pymalma04_mov_locaciones.pymalma04_columna,
    pymalma04_mov_locaciones.pymalma04_fila
    from pymalma02_det_stock
    inner join pymalma04_mov_locaciones on (pymalma04_mov_locaciones.rela_pymalma02 = pymalma02_det_stock.id_pymalma02)
    where pymalma02_det_stock.rela_pymalma01 = :id_pymalma01
    and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
    group by
    pymalma04_mov_locaciones.pymalma04_almacen,
    pymalma04_mov_locaciones.pymalma04_rack,
    pymalma04_mov_locaciones.pymalma04_columna,
    pymalma04_mov_locaciones.pymalma04_fila
    having sum(pymalma02_det_stock.pymalma02_cantidad) > 0
    order by sum(pymalma02_det_stock.pymalma02_cantidad) asc
    into :almacen,
         :rack,
         :columna,
         :fila;

    if (almacen is not null) then
    begin
        if (rack is null) then rack = '';
        if (columna is null) then columna = '';
        if (fila is null) then fila = '';

        insert into pymalma04_mov_locaciones( pymalma04_mov_locaciones.rela_pymalma02,
                                              pymalma04_mov_locaciones.pymalma04_almacen,
                                              pymalma04_mov_locaciones.pymalma04_rack,
                                              pymalma04_mov_locaciones.pymalma04_columna,
                                              pymalma04_mov_locaciones.pymalma04_fila )
        values( :id_pymalma02,
                :almacen,
                :rack,
                :columna,
                :fila );

    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMALMA04_VALIDACION (
    ALMACEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RACK VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COLUMNA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FILA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    VALIDA VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SIN_INVENTARIO INTEGER,
    BUSQUEDA VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable PATRON_01 varchar(5);
declare variable PATRON_02 varchar(5);
declare variable PATRON_03 varchar(5);
declare variable PATRON_04 varchar(5);
declare variable PATRON_VALIDA varchar(5);
begin
    patron_01 = 'XZZZ';
    patron_02 = 'XXZZ';
    patron_03 = 'XXXZ';
    patron_04 = 'XXXX';

    valida = '';
    sin_inventario = 1;
    busqueda = '';

    if (almacen is null) then almacen = '';
    if (rack is null) then rack = '';
    if (columna is null) then columna = '';
    if (fila is null) then fila = '';

    almacen = upper(trim(almacen));
    rack = upper(trim(rack));
    columna = upper(trim(columna));
    fila = upper(trim(fila));

    if (almacen <> '') then
    begin
        sin_inventario = 0;
        patron_valida = 'X';

        if (rack <> '') then
            patron_valida = patron_valida || 'X';
        else
        begin
            patron_valida = patron_valida || 'Z';
            valida = 'RACK';
        end

        if (columna <> '') then
            patron_valida = patron_valida || 'X';
        else
        begin
            patron_valida = patron_valida || 'Z';   
            valida = valida || ' COLUMNA';
        end

        if (fila <> '') then
            patron_valida = patron_valida || 'X';
        else
        begin
            patron_valida = patron_valida || 'Z';
            valida = valida || ' FILA';
        end

        if (patron_valida = patron_01 or patron_valida = patron_02 or
            patron_valida = patron_03 or patron_valida = patron_04) then
        begin
            valida = 'OK';
            busqueda = trim(almacen || rack || columna || fila);
        end
    end
    else
    begin
       valida = 'ALMACEN';

       if (rack = '') then
           valida = valida || ' RACK';

       if (columna = '') then
           valida = valida || ' COLUMNA';

       if (fila = '') then
           valida = valida || ' FILA';

       valida = trim(valida);
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMALMA10 (
    P_RELA_SOCMAIN01 BIGINT,
    P_RELA_SOCMAIN21 BIGINT,
    P_RELA_SICEGRE80 BIGINT,
    P_PYMALMA10 BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICEGRE01 BIGINT,
    RELA_SICEGRE80 BIGINT,
    ID_PYMALMA10 BIGINT,
    PYMALMA10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA10_ORDPROVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA10_FECHA_SOL DATE,
    PYMALMA10_FECHA_REC DATE,
    PYMALMA10_NROFACT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA10_FFACT DATE,
    PYMALMA10_IMPFACT DOUBLE PRECISION,
    PYMALMA10_FAPL TIMESTAMP,
    ENTIDAD VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable STR_SQL varchar(4000);
begin

  str_sql = 'select
        pymalma10_cab_recepcion.rela_socmain01,
        pymalma10_cab_recepcion.rela_socmain21,
        pymalma10_cab_recepcion.rela_sicegre01,
        pymalma10_cab_recepcion.rela_sicegre80,
        pymalma10_cab_recepcion.id_pymalma10,
        pymalma10_cab_recepcion.pymalma10_docnro,
        pymalma10_cab_recepcion.pymalma10_ordprove,
        pymalma10_cab_recepcion.pymalma10_fecha_sol,
        pymalma10_cab_recepcion.pymalma10_fecha_rec,
        pymalma10_cab_recepcion.pymalma10_nrofact,
        pymalma10_cab_recepcion.pymalma10_ffact,
        pymalma10_cab_recepcion.pymalma10_impfact,
        pymalma10_cab_recepcion.pymalma10_fapl,
        CBO_SICEGRE01_ID.entidad,
        CBO_SICEGRE01_ID.rfc
        from pymalma10_cab_recepcion
        inner join CBO_SICEGRE01_ID on ( CBO_SICEGRE01_ID.id_sicegre01 = pymalma10_cab_recepcion.rela_sicegre01 )
        where pymalma10_cab_recepcion.rela_socmain01 = ' || p_rela_socmain01;

  if (p_rela_sicegre80 = -1 and P_PYMALMA10 = -1) then  --Trae todas las solicitudes sin productos
  begin
     str_sql = str_sql || ' and pymalma10_cab_recepcion.rela_socmain21 = ' || p_rela_socmain21 ||
     ' and not exists ( select first 1 *
                             from pymalma11_det_productos
                             where pymalma11_det_productos.rela_pymalma10 = pymalma10_cab_recepcion.id_pymalma10  )';
  end
  else if (P_PYMALMA10 <> -1) then  --Trae una Solicitud en particular
       str_sql = str_sql || ' and pymalma10_cab_recepcion.id_pymalma10 = ' || P_PYMALMA10;
  else  --Trae una Orden en particular
    str_sql = str_sql || ' and pymalma10_cab_recepcion.rela_socmain21 = ' || p_rela_socmain21 ||
    ' and pymalma10_cab_recepcion.rela_sicegre80 = ' || p_rela_sicegre80;


  for execute statement :str_sql
  into RELA_SOCMAIN01,
    RELA_SOCMAIN21,
    RELA_SICEGRE01,
    rela_sicegre80,
    ID_PYMALMA10,
    PYMALMA10_DOCNRO,
    PYMALMA10_ORDPROVE,
    PYMALMA10_FECHA_SOL,
    PYMALMA10_FECHA_REC,
    pymalma10_nrofact,
    pymalma10_ffact,
    pymalma10_impfact,
    pymalma10_fapl,
    ENTIDAD,
    RFC
  do begin
     suspend;
  end 

end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT11 (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCSYST10_LPR01 BIGINT,
    RELA_SICINGR95 BIGINT)
RETURNS (
    ID_PYMREGL01 INTEGER,
    REGLA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION)
AS
begin
    ID_PYMREGL01 = 1;

    regla = 'Sin Reglas';

    Select SICINGR95_IMPORTE
    from SICINGR95_CAB_CONCEPTOS
    where ID_SICINGR95 = :rela_sicingr95
    into :importe;

    suspend;

    importe = null;

    select
    pymvent11_det_xproductos.pymvent11_importe
    from pymvent11_det_xproductos
    inner join pymvent10_cab_listaprecios on (pymvent10_cab_listaprecios.id_pymvent10 = pymvent11_det_xproductos.rela_pymvent10)
    where pymvent10_cab_listaprecios.rela_socmain01 = :rela_socmain01
    and pymvent10_cab_listaprecios.rela_socsyst10_lpr01 = :rela_socsyst10_lpr01
    and pymvent11_det_xproductos.rela_sicingr95 = :rela_sicingr95
    into :importe;
    
    if (importe is not null) then
    begin
        ID_PYMREGL01 = 2;
        regla = 'X Producto';
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT15_SEMANA (
    CADENA VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    VALIDA INTEGER)
AS
declare variable INT_DIA_SEMANA integer;
declare variable STR_DIA_SEMANA varchar(1);
begin
    int_dia_semana = extract(weekday from current_date);

    if (int_dia_semana = 0) then
        str_dia_semana = 'D';
    else if (int_dia_semana = 1) then
        str_dia_semana = 'L';
    else if (int_dia_semana = 2) then
        str_dia_semana = 'M';
    else if (int_dia_semana = 3) then
        str_dia_semana = 'I';
    else if (int_dia_semana = 4) then
        str_dia_semana = 'J';
    else if (int_dia_semana = 5) then
        str_dia_semana = 'V';
    else if (int_dia_semana = 6) then
        str_dia_semana = 'S';

    valida = position (str_dia_semana in cadena);

    if (valida <> 0) then
        valida = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT50_APART_CANC (
    RELA_PYMVENT50 BIGINT)
RETURNS (
    OK INTEGER)
AS
declare variable ID_PYMVENT70 bigint;
declare variable ID_PYMVENT71 bigint;
declare variable ID_PYMALMA01 bigint;
declare variable ID_SOCSYST10_STK_MAS bigint;
declare variable ID_SOCSYST10_STK_MENOS bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SICINGR95 bigint;
declare variable PYMVENT71_CANTIDAD double precision;
declare variable RELA_SOCMAIN21_APARTADO bigint;
declare variable ID_PYMALMA01_APARTADO bigint;
declare variable ID_PYMALMA02 bigint;
begin
    ok = 1;

    select
    pymvent01_cab_cajas.rela_socmain21_apartado,
    pymvent50_cab_apertura.rela_socmain01,
    pymvent50_cab_apertura.rela_socmain21
    from pymvent50_cab_apertura
    inner join pymvent01_cab_cajas on ( pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01 )
    where pymvent50_cab_apertura.id_pymvent50 = :rela_pymvent50
    into :rela_socmain21_apartado,
         :rela_socmain01,
         :rela_socmain21;

    select pymalma01_cab_stock.id_pymalma01
    from pymalma01_cab_stock
    where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
    and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
    into :id_pymalma01;

    select pymalma01_cab_stock.id_pymalma01
    from pymalma01_cab_stock
    where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
    and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21_apartado
    into :id_pymalma01_apartado;

    select CBO_SOCSYST10_STK01.id_socsyst10
    from CBO_SOCSYST10_STK01
    where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK_AUTO-APARTADO-MAS'
    into :id_socsyst10_stk_mas;

    select CBO_SOCSYST10_STK01.id_socsyst10
    from CBO_SOCSYST10_STK01
    where CBO_SOCSYST10_STK01.socsyst10_codigo = 'STK_AUTO-APARTADO-MENOS'
    into :id_socsyst10_stk_menos;

    for select
    REP_PYMVENT50_APARTADOS.id_pymvent70
    from REP_PYMVENT50_APARTADOS( :rela_pymvent50 )
    where REP_PYMVENT50_APARTADOS.pymvent51_diasapartado < 0
    into :id_pymvent70
    do
    begin
        update pymvent51_det_ventas set pymvent51_det_ventas.pymvent51_fcerrado = current_timestamp,
                                        pymvent51_det_ventas.pymvent51_diasapartado = 99
        where pymvent51_det_ventas.rela_pymvent70 = :id_pymvent70;

        /* =================================================================================== */
        /* =================================================================================== */

        for select
        pymvent71_det_ticket.rela_sicingr95,
        pymvent71_det_ticket.id_pymvent71,
        pymvent71_det_ticket.pymvent71_cantidad
        from pymvent71_det_ticket
        where pymvent71_det_ticket.rela_pymvent70 = :id_pymvent70
        into :rela_sicingr95,
             :id_pymvent71,
             :pymvent71_cantidad
        do
        begin
            /* =================================================================================== */
            /* =================================================================================== */

            insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                             pymalma02_det_stock.rela_sicingr95,
                                             pymalma02_det_stock.rela_socsyst10_stk01,
                                             pymalma02_det_stock.pymalma02_cantidad )
            values( :id_pymalma01_apartado,
                    :rela_sicingr95,
                    :id_socsyst10_stk_menos,
                    :pymvent71_cantidad * -1 );

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
            INTO :id_pymalma02;

            /* =================================================================================== */

            insert into pymalma03_dep_referencia( pymalma03_dep_referencia.rela_pymalma02,
                                                  pymalma03_dep_referencia.rela_pymvent71 )
            values( :id_pymalma02,
                    :id_pymvent71 );

            /* =================================================================================== */

            execute procedure PRD_PYMALMA04_INSERT :id_pymalma01_apartado, :id_pymalma02,  :rela_sicingr95;

            /* =================================================================================== */
            /* =================================================================================== */

            insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                             pymalma02_det_stock.rela_sicingr95,
                                             pymalma02_det_stock.rela_socsyst10_stk01,
                                             pymalma02_det_stock.pymalma02_cantidad )
            values( :id_pymalma01,
                    :rela_sicingr95,
                    :id_socsyst10_stk_mas,
                    :pymvent71_cantidad );

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
            INTO :id_pymalma02;

            /* =================================================================================== */

            insert into pymalma03_dep_referencia( pymalma03_dep_referencia.rela_pymalma02,
                                                  pymalma03_dep_referencia.rela_pymvent71 )
            values( :id_pymalma02,
                    :id_pymvent71 );

            /* =================================================================================== */

            execute procedure PRD_PYMALMA04_INSERT :id_pymalma01, :id_pymalma02,  :rela_sicingr95;

            /* =================================================================================== */
            /* =================================================================================== */
        end
    end
    
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT50_FACTFIND (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT)
RETURNS (
    ID_PYMVENT50 BIGINT,
    PATH_WORK VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IS_TESTING INTEGER)
AS
declare variable RELA_PYMVENT01 bigint;
begin
    SELECT
    MAX(PYMVENT50_CAB_APERTURA.rela_pymvent01),
    MAX(PYMVENT50_CAB_APERTURA.id_pymvent50)
    FROM PYMVENT50_CAB_APERTURA
    INNER JOIN pymvent01_cab_cajas ON (pymvent01_cab_cajas.id_pymvent01 = PYMVENT50_CAB_APERTURA.rela_pymvent01)
    WHERE PYMVENT50_CAB_APERTURA.rela_socmain01 = :rela_socmain01
    AND PYMVENT50_CAB_APERTURA.rela_socmain21 = :rela_socmain21
    AND pymvent01_cab_cajas.pymvent01_factura = 1
    AND PYMVENT50_CAB_APERTURA.pymvent50_fcierre IS NULL
    INTO :rela_pymvent01,
         :id_pymvent50;

    if (id_pymvent50 is not null) then
    begin
        select
        pymvent01_cab_cajas.pymvent01_pathwork,
        pymvent01_cab_cajas.pymvent01_test
        from pymvent01_cab_cajas
        where pymvent01_cab_cajas.id_pymvent01 = :rela_pymvent01
        into :path_work,
             :is_testing;

        suspend;
   end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT50_PRESU_CANC (
    RELA_PYMVENT50 BIGINT)
RETURNS (
    OK INTEGER)
AS
declare variable ID_PYMVENT51 bigint;
begin
    for select pymvent51_det_ventas.id_pymvent51
    from pymvent51_det_ventas
    where pymvent51_det_ventas.rela_pymvent50 = :rela_pymvent50
    and pymvent51_det_ventas.pymvent51_fcerrado is null
    and pymvent51_det_ventas.pymvent51_fvencido is not null
    and pymvent51_det_ventas.pymvent51_cancelado <> 9
    and cast(pymvent51_det_ventas.pymvent51_fvencido as date) < current_date
    and not exists ( select first 1 pymvent57_det_presupuesto.id_pymvent57
                     from pymvent57_det_presupuesto
                     where pymvent57_det_presupuesto.rela_pymvent70_presu = pymvent51_det_ventas.rela_pymvent70
                    )
    into :id_pymvent51
    do
    begin
        update pymvent51_det_ventas set pymvent51_det_ventas.pymvent51_cancelado = 9
        where pymvent51_det_ventas.id_pymvent51 = :id_pymvent51;
    end

    ok = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT60_SALDOS_CLIENTES (
    ID_SICINGR01X BIGINT)
RETURNS (
    ID_SICINGR01 BIGINT,
    SALDO DOUBLE PRECISION)
AS
begin
    /*$$IBEC$$ id_sicingr01 = id_sicingr01x;

    SELECT sicingr01_cab_clientes.rela_socusua30
    FROM sicingr01_cab_clientes
    where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
    into :rela_socusua30;

    select sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
    from PYMVENT55_MOV_MOVENTSAL
    where PYMVENT55_MOV_MOVENTSAL.rela_socusua30 = :rela_socusua30
    and PYMVENT55_MOV_MOVENTSAL.pymvent55_pagoticket = 4
    into :saldo; $$IBEC$$*/

    id_sicingr01 = id_sicingr01x;

    SELECT SUM(grd_pymvent55_monedero.pymvent55_importe)
    FROM  grd_pymvent55_monedero(:id_sicingr01x)
    into :saldo;

    if (saldo is null) then
        saldo = 0.00;
    else
        saldo = saldo * (-1);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT62 (
    RELA_PYMVENT70 BIGINT)
RETURNS (
    ID_PYMVENT62 BIGINT,
    ES_FACTURADO INTEGER,
    PYMVENT62_CANCELADO INTEGER,
    RELA_SICINGR70 BIGINT)
AS
begin
    select
    pymvent62_dep_facturacion.rela_sicingr70,
    pymvent62_dep_facturacion.id_pymvent62,
    pymvent62_dep_facturacion.pymvent62_cancelado,
    ( select sicingr74_dep_cfdis.id_sicingr74
      from sicingr74_dep_cfdis
      where sicingr74_dep_cfdis.rela_sicingr70 = pymvent62_dep_facturacion.rela_sicingr70
    )
    FROM pymvent62_dep_facturacion
    where pymvent62_dep_facturacion.rela_pymvent70 = :rela_pymvent70
    into :rela_sicingr70,
         :id_pymvent62,
         :pymvent62_cancelado,
         :es_facturado;

    if (es_facturado is null) then
        es_facturado = 0;
    else
        es_facturado = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_APARTADO (
    ID_PYMVENT70 BIGINT)
RETURNS (
    ID_PYMVENT51 BIGINT,
    PYMVENT51_FCERRADO TIMESTAMP,
    PYMVENT51_DIASAPARTADO INTEGER,
    SALDO_APARTADO DECIMAL(15,2))
AS
declare variable FECHA_VTO date;
declare variable PYMVENT70_FECHA timestamp;
begin
    select
    pymvent51_det_ventas.id_pymvent51,
    pymvent51_det_ventas.pymvent51_diasapartado,
    pymvent51_det_ventas.pymvent51_fcerrado,
    pymvent70_cab_ticket.pymvent70_fecha
    from pymvent51_det_ventas
    inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    where pymvent51_det_ventas.rela_pymvent70 = :id_pymvent70
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent51_det_ventas.rela_socmain21_apartados is not null
    and pymvent51_det_ventas.pymvent51_diasapartado > 0
    into :id_pymvent51,
         :pymvent51_diasapartado,
         :pymvent51_fcerrado,
         :pymvent70_fecha;

    fecha_vto = dateadd (pymvent51_diasapartado day to cast(pymvent70_fecha as date));

    select sum(pymvent55_mov_moventsal.pymvent55_importe)
    from pymvent55_mov_moventsal
    where pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70
    and pymvent55_mov_moventsal.pymvent55_pagoticket = 5
    into :saldo_apartado;

    if (saldo_apartado is null) then
        saldo_apartado = 0;
    else
        saldo_apartado = saldo_apartado * (-1);

    if (pymvent51_diasapartado <> 99) then
        pymvent51_diasapartado = datediff (day from current_date to fecha_vto);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_CANCELAR (
    ID_PYMVENT70X BIGINT)
RETURNS (
    ID_PYMVENT62 BIGINT,
    RELA_SICINGR70 BIGINT,
    SICINGR74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_EMISOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_RECEPTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_NETO DOUBLE PRECISION)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SICINGR01 bigint;
begin
    id_pymvent62 = null;

    select
    pymvent62_dep_facturacion.id_pymvent62,
    pymvent62_dep_facturacion.rela_sicingr70
    from pymvent62_dep_facturacion
    where pymvent62_dep_facturacion.rela_pymvent70 = :ID_PYMVENT70X
    into :id_pymvent62, 
         :rela_sicingr70;

    if (id_pymvent62 is null) then
        EXCEPTION ex_pymvent70_sicingr70_cancela;

    select
    sicingr70_cab_facturacion.rela_socmain01,
    sicingr70_cab_facturacion.rela_sicingr01,
    sicingr70_cab_facturacion.sicingr70_neto,
    sicingr74_dep_cfdis.sicingr74_uuid
    from sicingr74_dep_cfdis
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70)
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :rela_socmain01,
         :rela_sicingr01,
         :sicingr70_neto,
         :sicingr74_uuid;

    select cbo_socmain01_all.rfc
    FROM cbo_socmain01_all
    where cbo_socmain01_all.id_socmain01 = :rela_socmain01
    into :rfc_emisor;

    select cbo_sicingr01_id.rfc
    FROM cbo_sicingr01_id
    where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
    into :rfc_receptor;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_CFDI40 (
    MODALIDAD INTEGER,
    ID_SICINGR01 BIGINT,
    RELA_REGFISCAL BIGINT,
    CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RSOCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID INTEGER,
    R_CODPOSTAL VARCHAR(5) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_REGFISCAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    R_RSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SOCMAIN80 bigint;
declare variable SOCSYST10_CODIGO_PERSONA varchar(50);
declare variable NOMBRE_RAZSOCIAL varchar(400);
declare variable APE_PAT varchar(400);
declare variable APE_MAT varchar(400);
declare variable RESULTADO varchar(255);
declare variable ID_POS integer;
declare variable EXISTE_DOMICILIO bigint;
declare variable RELA_SOCSYST10 bigint;
begin
    select cbo_socsyst10_tdd01.id_socsyst10
    from cbo_socsyst10_tdd01
    where cbo_socsyst10_tdd01.socsyst10_codigo = 'PARTICULAR'
    into :rela_socsyst10;

    if(modalidad = 0) then
    begin
        select sicingr01_cab_clientes.rela_socusua30,
        sicingr01_cab_clientes.rela_socsyst10_sat01
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        into :rela_socusua30,
             :r_regfiscal;

        select first 1 socusua36_det_domicilios.socusua36_codpostal
        from socusua36_det_domicilios
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
        into :R_CODPOSTAL;

        select cbo_sicingr01.entidad
        from cbo_sicingr01
        where cbo_sicingr01.rela_sicingr01 = :id_sicingr01
        into :r_rsocial;
    end
    else
    begin
        select sicingr01_cab_clientes.rela_socusua30,
        socsyst10_det_entradas.socsyst10_codigo
        from sicingr01_cab_clientes
        inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = sicingr01_cab_clientes.rela_socusua30)
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        into :rela_socusua30,
             :SOCSYST10_CODIGO_PERSONA;
    
        update sicingr01_cab_clientes set sicingr01_cab_clientes.rela_socsyst10_sat01 = :rela_regfiscal
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01;
    
        select first 1 cbo_socmain80.id_socmain80
        from cbo_socmain80(:codpostal)
        into :rela_socmain80;

        select first 1 socusua36_det_domicilios.id_socusua36
        from socusua36_det_domicilios
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socusua36_det_domicilios.rela_socmain80 = :rela_socmain80
        and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
        into :existe_domicilio;

        if (existe_domicilio is null) then
        begin
            insert into socusua36_det_domicilios(socusua36_det_domicilios.rela_socusua30,
                                                 socusua36_det_domicilios.rela_socsyst10_tdd01,
                                                 socusua36_det_domicilios.rela_socmain80,
                                                 socusua36_det_domicilios.socusua36_codpostal,
                                                 socusua36_det_domicilios.socusua36_calle,
                                                 socusua36_det_domicilios.socusua36_nro,
                                                 socusua36_det_domicilios.socusua36_ciudad,
                                                 socusua36_det_domicilios.socusua36_colonia)
            values( :rela_socusua30,
                    :rela_socsyst10,
                    :rela_socmain80,
                    :codpostal,
                    'calle',
                    'no',
                    '',
                    ''
            );
        end

        ape_pat = '';
        ape_mat = '';
        nombre_razsocial = null;
    
        for select
        SMX$UTIL_STRTOKENIZE1.id,
        SMX$UTIL_STRTOKENIZE1.result
        from SMX$UTIL_STRTOKENIZE1(:RSOCIAL, ';')
        into :id_pos,
             :resultado
        do
        begin
            if (id_pos = 1) then
                nombre_razsocial = :resultado;
            else if (id_pos = 2) then
                ape_pat = :resultado;
            else if (id_pos = 3) then
                ape_mat = :resultado;
        end
    
        if (nombre_razsocial is not null) then
        begin
            update socusua30_cab_entidades set socusua30_cab_entidades.socusua30_apellido_pat = :ape_pat,
                                               socusua30_cab_entidades.socusua30_apellido_mat = :ape_mat,
                                               socusua30_cab_entidades.socusua30_nombre_razsoc = :nombre_razsocial
            where socusua30_cab_entidades.id_socusua30 = :rela_socusua30;
        end
    end

    id = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_CLONE_TICKET (
    RELA_PYMVENT70 BIGINT,
    RELA_PYMVENT51X BIGINT)
RETURNS (
    RELA_PYMVENT51 BIGINT)
AS
declare variable ID_PYMVENT70_NEW bigint;
declare variable ID_PYMVENT71_NEW bigint;
declare variable ID_PYMVENT71 bigint;
declare variable RELA_SICINGR95 bigint;
declare variable PYMVENT71_ORDEN integer;
declare variable PYMVENT71_CODIGO varchar(50);
declare variable PYMVENT71_CONCEPTO varchar(8000);
declare variable PYMVENT71_CANTIDAD double precision;
declare variable PYMVENT71_IMPORTE_UNIDAD double precision;
declare variable PYMVENT71_IMPORTE_UNIDADR double precision;
declare variable PYMVENT71_IMPORTE_SUBTOTAL double precision;
declare variable PYMVENT71_IMPORTE_DESCUENTO double precision;
declare variable PYMVENT71_IMPORTE_COSTO double precision;
declare variable PYMVENT71_IMPORTE_TOTAL double precision;
declare variable PYMVENT71_IMPORTE_IMPUESTOS double precision;
declare variable PYMVENT71_IMPORTE_RETENIDO double precision;
declare variable PYMVENT71_IMPORTE_TRASLADO double precision;
declare variable PYMVENT71_IMPORTE_LOCALES double precision;
declare variable PYMVENT71_IMPORTE_NETO double precision;
declare variable PYMVENT71_STATUS_PRECIO varchar(400);
declare variable PYMVENT71_CANCELADO integer;
begin
    insert into pymvent70_cab_ticket(
        pymvent70_cab_ticket.rela_socmain01,
        pymvent70_cab_ticket.rela_socmain21,
        pymvent70_cab_ticket.rela_socusua01,
        pymvent70_cab_ticket.rela_sicingr01,
        pymvent70_cab_ticket.pymvent70_serie,
        pymvent70_cab_ticket.pymvent70_docnro,
        pymvent70_cab_ticket.pymvent70_fecha,
        pymvent70_cab_ticket.pymvent70_subtotal,
        pymvent70_cab_ticket.pymvent70_descuento,
        pymvent70_cab_ticket.pymvent70_total,
        pymvent70_cab_ticket.pymvent70_totimp_retenidos,
        pymvent70_cab_ticket.pymvent70_totimp_traslados,
        pymvent70_cab_ticket.pymvent70_totimp_locales,
        pymvent70_cab_ticket.pymvent70_neto
    )
    select
        pymvent70_cab_ticket.rela_socmain01,
        pymvent70_cab_ticket.rela_socmain21,
        pymvent70_cab_ticket.rela_socusua01,
        pymvent70_cab_ticket.rela_sicingr01,
        pymvent70_cab_ticket.pymvent70_serie,
        pymvent70_cab_ticket.pymvent70_docnro,
        pymvent70_cab_ticket.pymvent70_fecha,
        pymvent70_cab_ticket.pymvent70_subtotal,
        pymvent70_cab_ticket.pymvent70_descuento,
        pymvent70_cab_ticket.pymvent70_total,
        pymvent70_cab_ticket.pymvent70_totimp_retenidos,
        pymvent70_cab_ticket.pymvent70_totimp_traslados,
        pymvent70_cab_ticket.pymvent70_totimp_locales,
        pymvent70_cab_ticket.pymvent70_neto
    from pymvent70_cab_ticket
    where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMVENT70'
    INTO :id_pymvent70_new;

    for select
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_orden,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_unidadr,
    pymvent71_det_ticket.pymvent71_importe_subtotal,
    pymvent71_det_ticket.pymvent71_importe_descuento,
    pymvent71_det_ticket.pymvent71_importe_costo,
    pymvent71_det_ticket.pymvent71_importe_total,
    pymvent71_det_ticket.pymvent71_importe_impuestos,
    pymvent71_det_ticket.pymvent71_importe_retenido,
    pymvent71_det_ticket.pymvent71_importe_traslado,
    pymvent71_det_ticket.pymvent71_importe_locales,
    pymvent71_det_ticket.pymvent71_importe_neto,
    pymvent71_det_ticket.pymvent71_status_precio,
    pymvent71_det_ticket.pymvent71_cancelado
    from pymvent71_det_ticket
    where pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
    into :rela_sicingr95,
         :id_pymvent71,
         :pymvent71_orden,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_cantidad,
         :pymvent71_importe_unidad,
         :pymvent71_importe_unidadr,
         :pymvent71_importe_subtotal,
         :pymvent71_importe_descuento,
         :pymvent71_importe_costo,
         :pymvent71_importe_total,
         :pymvent71_importe_impuestos,
         :pymvent71_importe_retenido,
         :pymvent71_importe_traslado,
         :pymvent71_importe_locales,
         :pymvent71_importe_neto,
         :pymvent71_status_precio,
         :pymvent71_cancelado
    do
    begin
        insert into pymvent71_det_ticket(
        pymvent71_det_ticket.rela_pymvent70,
        pymvent71_det_ticket.rela_sicingr95,
        pymvent71_det_ticket.pymvent71_orden,
        pymvent71_det_ticket.pymvent71_codigo,
        pymvent71_det_ticket.pymvent71_concepto,
        pymvent71_det_ticket.pymvent71_cantidad,
        pymvent71_det_ticket.pymvent71_importe_unidad,
        pymvent71_det_ticket.pymvent71_importe_unidadr,
        pymvent71_det_ticket.pymvent71_importe_subtotal,
        pymvent71_det_ticket.pymvent71_importe_descuento,
        pymvent71_det_ticket.pymvent71_importe_costo,
        pymvent71_det_ticket.pymvent71_importe_total,
        pymvent71_det_ticket.pymvent71_importe_impuestos,
        pymvent71_det_ticket.pymvent71_importe_retenido,
        pymvent71_det_ticket.pymvent71_importe_traslado,
        pymvent71_det_ticket.pymvent71_importe_locales,
        pymvent71_det_ticket.pymvent71_importe_neto,
        pymvent71_det_ticket.pymvent71_status_precio,
        pymvent71_det_ticket.pymvent71_cancelado)
        values(:id_pymvent70_new,
               :rela_sicingr95,
               :pymvent71_orden,
               :pymvent71_codigo,
               :pymvent71_concepto,
               :pymvent71_cantidad,
               :pymvent71_importe_unidad,
               :pymvent71_importe_unidadr,
               :pymvent71_importe_subtotal,
               :pymvent71_importe_descuento,
               :pymvent71_importe_costo,
               :pymvent71_importe_total,
               :pymvent71_importe_impuestos,
               :pymvent71_importe_retenido,
               :pymvent71_importe_traslado,
               :pymvent71_importe_locales,
               :pymvent71_importe_neto,
               :pymvent71_status_precio,
               :pymvent71_cancelado);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMVENT71'
        INTO :id_pymvent71_new;

        insert into pymvent72_det_impuestos(
            pymvent72_det_impuestos.rela_pymvent71,
            pymvent72_det_impuestos.rela_sicxmls02,
            pymvent72_det_impuestos.pymvent72_tipozona,
            pymvent72_det_impuestos.pymvent72_tipo,
            pymvent72_det_impuestos.pymvent72_impuesto,
            pymvent72_det_impuestos.pymvent72_importe,
            pymvent72_det_impuestos.pymvent72_base,
            pymvent72_det_impuestos.pymvent72_tasaocuota,
            pymvent72_det_impuestos.pymvent72_factor)
        select
        :id_pymvent71_new,
        pymvent72_det_impuestos.rela_sicxmls02,
        pymvent72_det_impuestos.pymvent72_tipozona,
        pymvent72_det_impuestos.pymvent72_tipo,
        pymvent72_det_impuestos.pymvent72_impuesto,
        pymvent72_det_impuestos.pymvent72_importe,
        pymvent72_det_impuestos.pymvent72_base,
        pymvent72_det_impuestos.pymvent72_tasaocuota,
        pymvent72_det_impuestos.pymvent72_factor
        from pymvent72_det_impuestos
        where pymvent72_det_impuestos.rela_pymvent71 = :id_pymvent71;
    end

    insert into pymvent51_det_ventas(
        pymvent51_det_ventas.rela_pymvent50,
        pymvent51_det_ventas.rela_pymvent70,
        pymvent51_det_ventas.rela_socusua01_vend,
        pymvent51_det_ventas.pymvent51_fcerrado,
        pymvent51_det_ventas.pymvent51_diasapartado
        )
        select
        pymvent51_det_ventas.rela_pymvent50,
        :id_pymvent70_new,
        pymvent51_det_ventas.rela_socusua01_vend,
        pymvent51_det_ventas.pymvent51_fcerrado,
        0
        from pymvent51_det_ventas
        where pymvent51_det_ventas.id_pymvent51 = :rela_pymvent51x;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMVENT51'
    INTO :rela_pymvent51;

    insert into PYMVENT57_DET_PRESUPUESTO(
        PYMVENT57_DET_PRESUPUESTO.rela_pymvent70_presu,
        PYMVENT57_DET_PRESUPUESTO.rela_pymvent70_cobo)
    values(
        :rela_pymvent70,
        :id_pymvent70_new);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_FIND (
    RELA_SOCMAIN01 BIGINT,
    VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SICINGR01 BIGINT,
    RELA_PYMVENT60 BIGINT,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_NETO DOUBLE PRECISION,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BLOQUEADO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_PYMVENT81 bigint;
begin
    valor = trim(upper(valor));

    FOR SELECT
    prd_pymvent70_view.rela_sicingr01,
    prd_pymvent70_view.id_pymvent70,
    prd_pymvent70_view.pymvent70_docnro,
    prd_pymvent70_view.pymvent70_fecha,
    prd_pymvent70_view.pymvent70_neto,
    prd_pymvent70_view.cliente,
    prd_pymvent70_view.rfc
    FROM prd_pymvent70_view(:rela_socmain01)
    WHERE prd_pymvent70_view.busqueda like '%' || :Valor || '%'
    into :rela_sicingr01,
         :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto,
         :cliente,
         :rfc
    do
    begin
        rela_pymvent60 = null;

        select pymvent60_cab_cobro.id_pymvent60
        from pymvent60_cab_cobro
        inner join pymvent51_det_ventas on ( pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51 )
        where pymvent51_det_ventas.rela_pymvent70 = :id_pymvent70
        into :rela_pymvent60;

        if (rfc is null or trim(rfc) = '' ) then
            rfc = 'XAXX010101000';

        id_pymvent81 = null;
        bloqueado = 'No';

        select pymvent81_det_factglobal.id_pymvent81
        from pymvent81_det_factglobal
        where pymvent81_det_factglobal.rela_pymvent70 = :id_pymvent70
        into :id_pymvent81;

        if (id_pymvent81 is not null) then
            bloqueado = 'Si';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_LOADCFDI (
    ID_SICINGR70 BIGINT)
RETURNS (
    RELA_SICINGR01 BIGINT,
    ID_SICINGR74 BIGINT,
    SICINGR74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_SMX_QRCODE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    select
    sicingr74_dep_cfdis.id_sicingr74,
    sicingr74_dep_cfdis.sicingr74_uuid,
    sicingr74_dep_cfdis.sicingr74_uuid_smx,
    sicingr74_dep_cfdis.sicingr74_uuid_smx_qrcode,
    sicingr70_cab_facturacion.rela_sicingr01,
    sicingr70_cab_facturacion.sicingr70_docnro
    from pymvent62_dep_facturacion
    inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = pymvent62_dep_facturacion.rela_sicingr70 )
    inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
    where pymvent62_dep_facturacion.rela_sicingr70 = :id_sicingr70
    into :id_sicingr74,
         :sicingr74_uuid,
         :sicingr74_uuid_smx,
         :sicingr74_uuid_smx_qrcode,
         :rela_sicingr01,
         :folio;
    
    if (id_sicingr74 is not null) then
    begin
        select
        cbo_sicingr01_id.entidad,
        cbo_sicingr01_id.rfc
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :entidad,
             :rfc;
        
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_SICINGR01 (
    RELA_SICINGR01 BIGINT)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    ID_SICINGR01 BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_PARTICULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_CELULAR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_LABORAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BUSQUEDA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCUSUA31_LADA varchar(50);
declare variable SOCUSUA31_NRO varchar(50);
declare variable TELEFONO varchar(50);
begin
    FOR SELECT
    sicingr01_cab_clientes.id_sicingr01,
    sicingr01_cab_clientes.rela_socusua30
    FROM sicingr01_cab_clientes
    WHERE sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
    INTO :id_sicingr01,
         :rela_socusua30
    do
    begin
        SELECT
        cbo_socusua30.entidad,
        cbo_socusua30.tipo,
        cbo_socusua30.rfc
        FROM cbo_socusua30(:rela_socusua30)
        into :entidad,
             :tipo,
             :rfc;

        if (rfc is null) then
            rfc = '';

        for select
        socsyst10_det_entradas.socsyst10_codigo,
        socusua31_det_telefonos.socusua31_lada,
        socusua31_det_telefonos.socusua31_nro
        from socusua31_det_telefonos
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua31_det_telefonos.rela_socsyst10_tt001 )
        where socusua31_det_telefonos.rela_socusua30 = :rela_socusua30
        into :socsyst10_codigo,
             :socusua31_lada,
             :socusua31_nro
        do
        begin
            telefono = '(' || :socusua31_lada || ') ' || :socusua31_nro;

            if (socsyst10_codigo = 'TELCEL') then
                tel_celular = telefono;
            else if (socsyst10_codigo = 'TELPAR') then
                tel_particular = telefono;
            else if (socsyst10_codigo = 'TELLAB') then
                tel_laboral = telefono;
        end

        if (tel_celular is null) then tel_celular = '';
        if (tel_particular is null) then tel_particular = '';
        if (tel_laboral is null) then tel_laboral = '';

        busqueda = :entidad || :rfc || tel_celular || tel_particular || tel_laboral;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_SICINGR70 (
    ID_PYMVENT62 BIGINT,
    VERCFDI VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable PARAM_PYMVENT60 bigint;
declare variable PARAM_PYMVENT70 bigint;
declare variable PARAM_SOCSYST10_MET01 bigint;
declare variable PARAM_SOCSYST10_UCF01 bigint;
declare variable PARAM_SOCMAIN01 bigint;
declare variable PARAM_SOCMAIN21 bigint;
declare variable PARAM_SOCUSUA01 bigint;
declare variable PARAM_SICINGR01 bigint;
declare variable PARAM_SOCSYST10 bigint;
declare variable PARAM_SOCSYST10_CTM01 bigint;
declare variable PARAM_SOCSYST10_TCP01 bigint;
declare variable PARAM_SOCSYST10_FDP01 bigint;
declare variable PARAM_SUBTOTAL double precision;
declare variable PARAM_DESCUENTO double precision;
declare variable PARAM_TOTAL double precision;
declare variable PARAM_TOTIMP_RETENIDOS double precision;
declare variable PARAM_TOTIMP_TRASLADOS double precision;
declare variable PARAM_TOTIMP_LOCALES double precision;
declare variable PARAM_NETO double precision;
declare variable ID_SICINGR71 bigint;
declare variable ID_SICINGR70 bigint;
declare variable PARAM_SICINGR95 bigint;
declare variable PARAM_PYMVENT71 bigint;
declare variable PARAM_CODIGO varchar(50);
declare variable PARAM_CONCEPTO varchar(8000);
declare variable PARAM_CANTIDAD double precision;
declare variable PARAM_IMPORTE_UNIDAD double precision;
declare variable PARAM_IMPORTE_SUBTOTAL double precision;
declare variable PARAM_IMPORTE_DESCUENTO double precision;
declare variable PARAM_IMPORTE_TOTAL double precision;
declare variable PARAM_IMPORTE_IMPUESTOS double precision;
declare variable PARAM_IMPORTE_RETENIDO double precision;
declare variable PARAM_IMPORTE_TRASLADO double precision;
declare variable PARAM_IMPORTE_LOCALES double precision;
declare variable PARAM_IMPORTE_NETO double precision;
declare variable PARAM_SICXMLS02 bigint;
declare variable PARAM_TIPOZONA varchar(50);
declare variable PARAM_TIPO varchar(50);
declare variable PARAM_IMPUESTO varchar(400);
declare variable PARAM_IMPORTE double precision;
declare variable PARAM_BASE double precision;
declare variable PARAM_TASAOCUOTA double precision;
declare variable PARAM_FACTOR varchar(50);
declare variable PARAM_IMPORTE_COSTO integer;
begin
    select
    pymvent62_dep_facturacion.rela_pymvent60,
    pymvent62_dep_facturacion.rela_pymvent70,
    pymvent62_dep_facturacion.rela_socsyst10_met01,
    pymvent62_dep_facturacion.rela_socsyst10_ucf01
    from pymvent62_dep_facturacion
    where pymvent62_dep_facturacion.id_pymvent62 = :id_pymvent62
    into :param_pymvent60,
         :param_pymvent70,
         :param_socsyst10_met01,
         :param_socsyst10_ucf01;

    param_sicingr01 = null;

    select
    pymvent70_cab_ticket.rela_socmain01,
    pymvent70_cab_ticket.rela_socmain21,
    pymvent70_cab_ticket.rela_socusua01,
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent70_cab_ticket.pymvent70_subtotal,
    pymvent70_cab_ticket.pymvent70_descuento,
    pymvent70_cab_ticket.pymvent70_total,
    pymvent70_cab_ticket.pymvent70_totimp_retenidos,
    pymvent70_cab_ticket.pymvent70_totimp_traslados,
    pymvent70_cab_ticket.pymvent70_totimp_locales,
    pymvent70_cab_ticket.pymvent70_neto
    from pymvent70_cab_ticket
    where pymvent70_cab_ticket.id_pymvent70 = :param_pymvent70
    and pymvent70_cab_ticket.rela_sicingr01 is not null
    into :param_socmain01,
         :param_socmain21,
         :param_socusua01,
         :param_sicingr01,
         :param_subtotal,
         :param_descuento,
         :param_total,
         :param_totimp_retenidos,
         :param_totimp_traslados,
         :param_totimp_locales,
         :param_neto;

    if (param_sicingr01 is null) then
        exception EX_PYMVENT70_SICINGR70;

    select
    CBO_SOCSYST10_FFS01.id_socsyst10
    from CBO_SOCSYST10_FFS01
    where CBO_SOCSYST10_FFS01.socsyst10_codigo = 'SICINGR70'
    into :param_socsyst10;

    select
    CBO_SOCSYST10_CTM01W.id_socsyst10
    from CBO_SOCSYST10_CTM01W
    where CBO_SOCSYST10_CTM01W.socsyst10_codigo = 'MXN'
    into :param_socsyst10_ctm01;

    select
    CBO_SOCSYST10_TCP01.id_socsyst10
    from CBO_SOCSYST10_TCP01
    where CBO_SOCSYST10_TCP01.socsyst10_codigo = 'I'
    into :param_socsyst10_tcp01;

    select first 1
    PYMVENT61_DET_COBRO.rela_socsyst10_fdp01
    from PYMVENT61_DET_COBRO
    where PYMVENT61_DET_COBRO.rela_pymvent60 = :param_pymvent60
    order by PYMVENT61_DET_COBRO.pymvent61_valor desc
    into :param_socsyst10_fdp01;

    /* ==================================================================================================================== */

    insert into sicingr70_cab_facturacion( sicingr70_cab_facturacion.rela_socmain01,
                                           sicingr70_cab_facturacion.rela_socmain21,
                                           sicingr70_cab_facturacion.rela_socusua01,
                                           sicingr70_cab_facturacion.rela_socsyst10,
                                           sicingr70_cab_facturacion.rela_sicingr01,
                                           sicingr70_cab_facturacion.rela_socsyst10_ctm01,
                                           sicingr70_cab_facturacion.rela_socsyst10_fdp01,
                                           sicingr70_cab_facturacion.rela_socsyst10_tcp01,
                                           sicingr70_cab_facturacion.rela_socsyst10_met01,
                                           sicingr70_cab_facturacion.rela_socsyst10_ucf01,
                                           sicingr70_cab_facturacion.sicingr70_docnro,
                                           sicingr70_cab_facturacion.sicingr70_fecha,
                                           sicingr70_cab_facturacion.sicingr70_subtotal,
                                           sicingr70_cab_facturacion.sicingr70_descuento,
                                           sicingr70_cab_facturacion.sicingr70_total,
                                           sicingr70_cab_facturacion.sicingr70_totimp_retenidos,
                                           sicingr70_cab_facturacion.sicingr70_totimp_traslados,
                                           sicingr70_cab_facturacion.sicingr70_totimp_locales,
                                           sicingr70_cab_facturacion.sicingr70_neto,
                                           sicingr70_cab_facturacion.sicingr70_cambio,
                                           sicingr70_cab_facturacion.sicingr70_vercfdi )
    values( :param_socmain01,
            :param_socmain21,
            :param_socusua01,
            :param_socsyst10,
            :param_sicingr01,
            :param_socsyst10_ctm01,
            :param_socsyst10_fdp01,
            :param_socsyst10_tcp01,
            :param_socsyst10_met01,
            :param_socsyst10_ucf01,
            '',
            current_date,
            :param_subtotal,
            :param_descuento,
            :param_total,
            :param_totimp_retenidos,
            :param_totimp_traslados,
            :param_totimp_locales,
            :param_neto,
            1.00,
            :vercfdi );

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR70'
    INTO :id_sicingr70;

    /* ==================================================================================================================== */

    for select
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_subtotal,
    pymvent71_det_ticket.pymvent71_importe_descuento,
    pymvent71_det_ticket.pymvent71_importe_total,
    pymvent71_det_ticket.pymvent71_importe_impuestos,
    pymvent71_det_ticket.pymvent71_importe_retenido,
    pymvent71_det_ticket.pymvent71_importe_traslado,
    pymvent71_det_ticket.pymvent71_importe_locales,
    pymvent71_det_ticket.pymvent71_importe_neto,
    pymvent71_det_ticket.pymvent71_importe_costo
    from pymvent71_det_ticket
    where pymvent71_det_ticket.rela_pymvent70 = :param_pymvent70
    and pymvent71_det_ticket.pymvent71_cancelado = 0
    into :param_sicingr95,
         :param_pymvent71,
         :param_codigo,
         :param_concepto,
         :param_cantidad,
         :param_importe_unidad,
         :param_importe_subtotal,
         :param_importe_descuento,
         :param_importe_total,
         :param_importe_impuestos,
         :param_importe_retenido,
         :param_importe_traslado,
         :param_importe_locales,
         :param_importe_neto,
         :param_importe_costo
    do
    begin
        insert into sicingr71_det_facturacion( sicingr71_det_facturacion.rela_sicingr70,
                                               sicingr71_det_facturacion.rela_sicingr95,
                                               sicingr71_det_facturacion.sicingr71_codigo,
                                               sicingr71_det_facturacion.sicingr71_concepto,
                                               sicingr71_det_facturacion.sicingr71_cantidad,
                                               sicingr71_det_facturacion.sicingr71_importe_unidad,
                                               sicingr71_det_facturacion.sicingr71_importe_subtotal,
                                               sicingr71_det_facturacion.sicingr71_importe_descuento,
                                               sicingr71_det_facturacion.sicingr71_importe_total,
                                               sicingr71_det_facturacion.sicingr71_importe_impuestos,
                                               sicingr71_det_facturacion.sicingr71_importe_retenido,
                                               sicingr71_det_facturacion.sicingr71_importe_traslado,
                                               sicingr71_det_facturacion.sicingr71_importe_locales,
                                               sicingr71_det_facturacion.sicingr71_importe_neto,
                                               sicingr71_det_facturacion.sicingr71_importe_costo )
        values( :id_sicingr70,
                :param_sicingr95,
                :param_codigo,
                :param_concepto,
                :param_cantidad,
                :param_importe_unidad,
                :param_importe_subtotal,
                :param_importe_descuento,
                :param_importe_total,
                :param_importe_impuestos,
                :param_importe_retenido,
                :param_importe_traslado,
                :param_importe_locales,
                :param_importe_neto,
                :param_importe_costo );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR71'
        INTO :id_sicingr71;

        for select
        pymvent72_det_impuestos.rela_sicxmls02,
        pymvent72_det_impuestos.pymvent72_tipozona,
        pymvent72_det_impuestos.pymvent72_tipo,
        pymvent72_det_impuestos.pymvent72_impuesto,
        pymvent72_det_impuestos.pymvent72_importe,
        pymvent72_det_impuestos.pymvent72_base,
        pymvent72_det_impuestos.pymvent72_tasaocuota,
        pymvent72_det_impuestos.pymvent72_factor
        from pymvent72_det_impuestos
        where pymvent72_det_impuestos.rela_pymvent71 = :param_pymvent71
        into :param_sicxmls02,
             :param_tipozona,
             :param_tipo,
             :param_impuesto,
             :param_importe,
             :param_base,
             :param_tasaocuota,
             :param_factor
       do
       begin
           insert into sicingr72_det_impuestos( sicingr72_det_impuestos.rela_sicingr71,
                                                sicingr72_det_impuestos.rela_sicxmls02,
                                                sicingr72_det_impuestos.sicingr72_tipozona,
                                                sicingr72_det_impuestos.sicingr72_tipo,
                                                sicingr72_det_impuestos.sicingr72_impuesto,
                                                sicingr72_det_impuestos.sicingr72_importe,
                                                sicingr72_det_impuestos.sicingr72_base,
                                                sicingr72_det_impuestos.sicingr72_tasaocuota,
                                                sicingr72_det_impuestos.sicingr72_factor )
           values( :id_sicingr71,
                   :param_sicxmls02,
                   :param_tipozona,
                   :param_tipo,
                   :param_impuesto,
                   :param_importe,
                   :param_base,
                   :param_tasaocuota,
                   :param_factor );
       end
    end

    /* ==================================================================================================================== */

    update pymvent62_dep_facturacion set pymvent62_dep_facturacion.rela_sicingr70 = :id_sicingr70
    where pymvent62_dep_facturacion.id_pymvent62 = :id_pymvent62;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_TICKET (
    RELA_PYMVENT70 BIGINT)
RETURNS (
    ID_PYMVENT70 BIGINT,
    TICKET VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA TIMESTAMP,
    CAJA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJERO VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    RECIBIDO DOUBLE PRECISION,
    CAMBIO DOUBLE PRECISION)
AS
declare variable RELA_PYMVENT50 bigint;
declare variable RELA_SOCUSUA01_VEND bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_PYMVENT51 bigint;
begin
    id_pymvent70 = :rela_pymvent70;

    select
    pymvent51_det_ventas.rela_pymvent50,
    pymvent51_det_ventas.rela_socusua01_vend,
    pymvent51_det_ventas.id_pymvent51
    from pymvent51_det_ventas
    where pymvent51_det_ventas.rela_pymvent70 = :rela_pymvent70
    into :rela_pymvent50,
         :rela_socusua01_vend,
         :id_pymvent51;

    select
    socsyst10_det_entradas.socsyst10_descripcion
    from pymvent50_cab_apertura
    inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = pymvent01_cab_cajas.rela_socsyst10_pvc01)
    where pymvent50_cab_apertura.id_pymvent50 = :rela_pymvent50
    into :caja;

    select socusua01_cab_usuarios.rela_socusua30
    from socusua01_cab_usuarios
    where socusua01_cab_usuarios.id_socusua01 = :rela_socusua01_vend
    into :rela_socusua30;

    select cbo_socusua30.entidad
    from cbo_socusua30(:rela_socusua30)
    into :cajero;

    select
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha
    from pymvent70_cab_ticket
    where pymvent70_cab_ticket.id_pymvent70 = :id_pymvent70
    into :ticket, 
         :fecha;

    select
    PYMVENT60_CAB_COBRO.pymvent60_tot_pago,
    PYMVENT60_CAB_COBRO.pymvent60_imp_recibido,
    PYMVENT60_CAB_COBRO.pymvent60_imp_cambio
    from PYMVENT60_CAB_COBRO
    where PYMVENT60_CAB_COBRO.rela_pymvent51 = :id_pymvent51
    into :importe,
         :recibido,
         :cambio;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_VIEW (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SICINGR01 BIGINT,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_NETO DOUBLE PRECISION,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    BUSQUEDA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable BUSQUEDA_FIND varchar(2000);
begin
    busqueda = '';

    FOR select
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_neto
    from pymvent70_cab_ticket
    inner join pymvent51_det_ventas on ( pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70 )
    where pymvent70_cab_ticket.rela_socmain01 = :rela_socmain01
    and pymvent51_det_ventas.pymvent51_fcerrado is not null
    into :rela_sicingr01,
         :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto
    do
    begin
        if (rela_sicingr01 is null) then
        begin
            cliente = 'Venta Consumidor Final';
            rfc = 'XAXX010101000';
            busqueda_find = :cliente;
        end
        else
        begin
            select
            PRD_PYMVENT70_SICINGR01.entidad,
            PRD_PYMVENT70_SICINGR01.rfc,
            PRD_PYMVENT70_SICINGR01.busqueda
            from PRD_PYMVENT70_SICINGR01(:rela_sicingr01)

            into :cliente,
                 :rfc,
                 :busqueda_find;
        end

        busqueda = trim(pymvent70_docnro) || :pymvent70_fecha || :pymvent70_neto || :busqueda_find;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT70_XCLIENTE (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT)
RETURNS (
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA DATE,
    PYMVENT70_NETO DOUBLE PRECISION,
    CANCELADO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PENDIENTE VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable PYMVENT51_CANCELADO integer;
declare variable PYMVENT51_FCERRADO timestamp;
begin
    for select
    PYMVENT70_CAB_TICKET.id_pymvent70,
    PYMVENT70_CAB_TICKET.pymvent70_docnro,
    PYMVENT70_CAB_TICKET.pymvent70_fecha,
    PYMVENT70_CAB_TICKET.pymvent70_neto,
    pymvent51_det_ventas.pymvent51_fcerrado,
    pymvent51_det_ventas.pymvent51_cancelado
    from PYMVENT70_CAB_TICKET
    inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = PYMVENT70_CAB_TICKET.id_pymvent70)
    where PYMVENT70_CAB_TICKET.rela_socmain01 = :rela_socmain01
    and PYMVENT70_CAB_TICKET.rela_sicingr01 = :rela_sicingr01
    into :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto,
         :pymvent51_fcerrado,
         :pymvent51_cancelado
    do
    begin
        cancelado = 'No';
        pendiente = 'No';

        if (pymvent51_cancelado = 1) then
            cancelado = 'Si';

        if (pymvent51_fcerrado is null) then
           pendiente = 'Si';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT73_DEVOLUCIONES (
    RELA_PYMVENT50 BIGINT,
    RELA_PYMVENT70 BIGINT,
    RELA_PYMVENT71 BIGINT,
    PYMVENT73_CANTIDAD DOUBLE PRECISION,
    PYMVENT73_IMPORTE DOUBLE PRECISION)
AS
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable ID_PYMALMA01 bigint;
declare variable RELA_SICINGR95 bigint;
declare variable ID_SOCSYST10 bigint;
declare variable ID_PYMALMA02 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_PYMVENT51 bigint;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable PYMVENT55_PAGOTICKET integer;
begin
    select
    pymvent70_cab_ticket.rela_socmain01,
    pymvent70_cab_ticket.rela_socmain21,
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent51_det_ventas.id_pymvent51
    from pymvent70_cab_ticket
    inner join pymvent51_det_ventas on ( pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70 )
    where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
    into :rela_socmain01,
         :rela_socmain21,
         :rela_sicingr01,
         :id_pymvent51;

    update pymvent51_det_ventas set pymvent51_det_ventas.pymvent51_cancelado = 1
    where pymvent51_det_ventas.id_pymvent51 = :id_pymvent51
    and pymvent51_det_ventas.pymvent51_cancelado = 0;

    select
    sicingr01_cab_clientes.rela_socusua30
    from sicingr01_cab_clientes
    where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
    into :rela_socusua30;

    select
    pymvent71_det_ticket.rela_sicingr95
    from pymvent71_det_ticket
    where pymvent71_det_ticket.id_pymvent71 = :rela_pymvent71
    into :rela_sicingr95;

    select
    pymalma01_cab_stock.id_pymalma01
    from pymalma01_cab_stock
    where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
    and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
    into :id_pymalma01;

    select
    cbo_socsyst10_stk01.id_socsyst10
    from cbo_socsyst10_stk01
    where cbo_socsyst10_stk01.socsyst10_codigo = 'STK-PTOVTA-DEVOLUCION'
    into :id_socsyst10;

    if (id_pymalma01 is not null) then
    begin
        insert into PYMALMA02_DET_STOCK( PYMALMA02_DET_STOCK.rela_pymalma01,
                                         PYMALMA02_DET_STOCK.rela_sicingr95,
                                         PYMALMA02_DET_STOCK.rela_socsyst10_stk01,
                                         PYMALMA02_DET_STOCK.pymalma02_cantidad )
        values(:id_pymalma01,
               :rela_sicingr95,
               :id_socsyst10,
               :pymvent73_cantidad );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
        INTO :id_pymalma02;

        insert into pymalma03_dep_referencia( pymalma03_dep_referencia.rela_pymalma02,
                                              pymalma03_dep_referencia.rela_pymvent71 )
        values( :id_pymalma02,
                :rela_pymvent71 );
    end

    select 
       socsyst10_det_remoto.socsyst10_codigo
    from socsyst10_det_remoto
       inner join pymvent61_det_cobro on (socsyst10_det_remoto.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01)
       inner join pymvent60_cab_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
       inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
    where     pymvent51_det_ventas.rela_pymvent70 = :rela_pymvent70
    into :socsyst10_codigo;

    if (socsyst10_codigo = '99') then
        pymvent55_pagoticket = 6;
    else
        pymvent55_pagoticket = 4;


    insert into PYMVENT55_MOV_MOVENTSAL( PYMVENT55_MOV_MOVENTSAL.rela_pymvent50,
                                             PYMVENT55_MOV_MOVENTSAL.rela_socusua30,
                                             PYMVENT55_MOV_MOVENTSAL.rela_pymvent70,
                                             PYMVENT55_MOV_MOVENTSAL.pymvent55_importe,
                                             PYMVENT55_MOV_MOVENTSAL.pymvent55_pagoticket )
        values( :rela_pymvent50,
                :rela_socusua30,
                :rela_pymvent70,
                :pymvent73_importe * (-1),
                :pymvent55_pagoticket );
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT73_DEVOVENT (
    RELA_PYMVENT70 BIGINT)
RETURNS (
    OK INTEGER)
AS
declare variable ID_PYMVENT71 bigint;
declare variable ID_PYMVENT51 bigint;
begin
    select
    PYMVENT51_DET_VENTAS.id_pymvent51
    from PYMVENT51_DET_VENTAS
    where PYMVENT51_DET_VENTAS.rela_pymvent70 = :rela_pymvent70
    into :id_pymvent51;

    delete from pymvent60_cab_cobro where pymvent60_cab_cobro.rela_pymvent51 = :id_pymvent51;

    for select
    pymvent71_det_ticket.id_pymvent71
    from pymvent71_det_ticket
    where pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
    into :id_pymvent71
    do
    begin
        delete from pymalma03_dep_referencia where pymalma03_dep_referencia.rela_pymvent71 = :id_pymvent71;
    end

    ok = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT80_FACTGLOBAL (
    ID_PYMVENT80 BIGINT)
RETURNS (
    OK INTEGER,
    SUMA_PTOVTA DOUBLE PRECISION,
    SUMA_FACTURA DOUBLE PRECISION,
    SUMA_DIFERENCIA DOUBLE PRECISION)
AS
declare variable ID_SICINGR70 bigint;
declare variable ID_PYMVENT81 bigint;
declare variable ID_SICINGR95 bigint;
declare variable ID_SICINGR95_ORIG bigint;
declare variable ID_SICINGR71_NEW bigint;
declare variable RELA_PYMVENT70 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable PYMVENT70_DOCNRO varchar(50);
declare variable RELA_SICXMLS02 bigint;
declare variable PYMVENT72_TIPOZONA varchar(50);
declare variable PYMVENT72_IMPUESTO varchar(400);
declare variable PYMVENT72_TASAOCUOTA double precision;
declare variable PYMVENT72_FACTOR varchar(50);
declare variable PYMVENT72_IMPORTE double precision;
declare variable PYMVENT72_BASE double precision;
declare variable SICINGR70_SUBTOTAL_SUM double precision;
declare variable SICINGR70_DESCUENTO_SUM double precision;
declare variable SICINGR70_TOTAL_SUM double precision;
declare variable SICINGR70_TOTIMP_RETENIDOS_SUM double precision;
declare variable SICINGR70_TOTIMP_TRASLADOS_SUM double precision;
declare variable SICINGR70_TOTIMP_LOCALES_SUM double precision;
declare variable SICINGR70_NETO_SUM double precision;
declare variable IMPORTE_IMPUESTO_FEDERAL double precision;
declare variable IMPORTE_IMPUESTO_LOCAL double precision;
declare variable PYMVENT70_NETO double precision;
begin
    suma_ptovta = 0;
    suma_factura = 0;
    suma_diferencia = 0;

    if (id_pymvent80 is null) then
    begin
        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMVENT80'
        INTO :id_pymvent80;
    end

    select pymvent80_cab_factglobal.rela_sicingr70
    from pymvent80_cab_factglobal
    where pymvent80_cab_factglobal.id_pymvent80 = :id_pymvent80
    into :id_sicingr70;


    /* ---------------------------------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------------------------------- */

    for select
    PYMVENT81_DET_FACTGLOBAL.id_pymvent81,
    PYMVENT81_DET_FACTGLOBAL.rela_pymvent70
    from PYMVENT81_DET_FACTGLOBAL
    where PYMVENT81_DET_FACTGLOBAL.rela_pymvent80 = :id_pymvent80
    and PYMVENT81_DET_FACTGLOBAL.pymvent81_procesado = 0
    into :id_pymvent81,
         :rela_pymvent70
    do
    begin
        select
        pymvent70_cab_ticket.rela_socmain01,
        pymvent70_cab_ticket.pymvent70_docnro,
        pymvent70_cab_ticket.pymvent70_neto
        from pymvent70_cab_ticket
        where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
        into :rela_socmain01,
             :pymvent70_docnro,
             :pymvent70_neto;

         suma_ptovta = suma_ptovta + pymvent70_neto;

        /* ---------------------------------------------------------------------------------------------------------------------------- */
        /* ---------------------------------------------------------------------------------------------------------------------------- */

        for select
        pymvent71_det_ticket.rela_sicingr95,
        pymvent72_det_impuestos.rela_sicxmls02,
        pymvent72_det_impuestos.pymvent72_tipozona,
        pymvent72_det_impuestos.pymvent72_impuesto,
        pymvent72_det_impuestos.pymvent72_tasaocuota,
        pymvent72_det_impuestos.pymvent72_factor,
        cast(sum(pymvent72_det_impuestos.pymvent72_base) as decimal(18, 2))
        from pymvent71_det_ticket
        inner join pymvent72_det_impuestos on (pymvent71_det_ticket.id_pymvent71 = pymvent72_det_impuestos.rela_pymvent71)
        where pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
        and pymvent71_det_ticket.pymvent71_cancelado = 0
        and upper(trim(pymvent72_det_impuestos.pymvent72_tipo)) = 'TRASLADADO'
        group by pymvent71_det_ticket.rela_sicingr95,
                 pymvent72_det_impuestos.rela_sicxmls02,
                 pymvent72_det_impuestos.pymvent72_tipozona,
                 pymvent72_det_impuestos.pymvent72_impuesto,
                 pymvent72_det_impuestos.pymvent72_tasaocuota,
                 pymvent72_det_impuestos.pymvent72_factor
        into :id_sicingr95_orig,
             :rela_sicxmls02,
             :pymvent72_tipozona,
             :pymvent72_impuesto,
             :pymvent72_tasaocuota,
             :pymvent72_factor,
             :pymvent72_base
        do
        begin
            if (pymvent72_base <> 0) then
            begin
                select
                prd_pymvent80_factglobal_imp.id_sicingr95,
                prd_pymvent80_factglobal_imp.importe_calculo
                from prd_pymvent80_factglobal_imp(:rela_socmain01,
                                                  :pymvent72_impuesto,
                                                  :pymvent72_tasaocuota,
                                                  :pymvent72_factor,
                                                  :pymvent72_base)
                into :id_sicingr95,
                     :pymvent72_importe;
    
                importe_impuesto_federal = 0;
                importe_impuesto_local = 0;
    
                if (upper(trim(pymvent72_tipozona)) = 'FEDERAL') then
                    importe_impuesto_federal = :pymvent72_importe;
                else
                    importe_impuesto_local = :pymvent72_importe;
    
                suma_factura = suma_factura + (:pymvent72_base + :pymvent72_importe);

                insert into sicingr71_det_facturacion( sicingr71_det_facturacion.rela_sicingr70,
                                                       sicingr71_det_facturacion.rela_sicingr95,
                                                       sicingr71_det_facturacion.sicingr71_codigo,
                                                       sicingr71_det_facturacion.sicingr71_concepto,
                                                       sicingr71_det_facturacion.sicingr71_cantidad,
    
                                                       sicingr71_det_facturacion.sicingr71_importe_unidad,
                                                       sicingr71_det_facturacion.sicingr71_importe_subtotal,
                                                       sicingr71_det_facturacion.sicingr71_importe_descuento,
                                                       sicingr71_det_facturacion.sicingr71_importe_total,
                                                       sicingr71_det_facturacion.sicingr71_importe_impuestos,
                                                       sicingr71_det_facturacion.sicingr71_importe_retenido,
    
                                                       sicingr71_det_facturacion.sicingr71_importe_traslado,
                                                       sicingr71_det_facturacion.sicingr71_importe_locales,
                                                       sicingr71_det_facturacion.sicingr71_importe_neto,
                                                       sicingr71_det_facturacion.sicingr71_factglobal )
                values( :id_sicingr70,
                        :id_sicingr95,
                        :pymvent70_docnro,
                        'VENTA',
                        1,
    
                        :pymvent72_base,
                        :pymvent72_base,
                        0.00,
                        :pymvent72_base,
                        :pymvent72_importe,
                        0.00,
    
                        :importe_impuesto_federal,
                        :importe_impuesto_local,
                        (:pymvent72_base + :pymvent72_importe),
                        1 );
    
                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR71'
                INTO :id_sicingr71_new;
    
                insert into sicingr72_det_impuestos( sicingr72_det_impuestos.rela_sicingr71,
                                                     sicingr72_det_impuestos.rela_sicxmls02,
                                                     sicingr72_det_impuestos.sicingr72_tipozona,
                                                     sicingr72_det_impuestos.sicingr72_tipo,
                                                     sicingr72_det_impuestos.sicingr72_impuesto,
                                                     sicingr72_det_impuestos.sicingr72_importe,
                                                     sicingr72_det_impuestos.sicingr72_base,
                                                     sicingr72_det_impuestos.sicingr72_tasaocuota,
                                                     sicingr72_det_impuestos.sicingr72_factor )
    
                values( :id_sicingr71_new,
                            :rela_sicxmls02,
                            :pymvent72_tipozona,
                            'Trasladado',
                            :pymvent72_impuesto,
                            :pymvent72_importe,
                            :pymvent72_base,
                            :pymvent72_tasaocuota,
                            :pymvent72_factor );
            end
            else
            begin
                suma_factura = suma_factura + :pymvent70_neto;

                insert into sicingr71_det_facturacion( sicingr71_det_facturacion.rela_sicingr70,
                                                       sicingr71_det_facturacion.rela_sicingr95,
                                                       sicingr71_det_facturacion.sicingr71_codigo,
                                                       sicingr71_det_facturacion.sicingr71_concepto,
                                                       sicingr71_det_facturacion.sicingr71_cantidad,
        
                                                       sicingr71_det_facturacion.sicingr71_importe_unidad,
                                                       sicingr71_det_facturacion.sicingr71_importe_subtotal,
                                                       sicingr71_det_facturacion.sicingr71_importe_descuento,
                                                       sicingr71_det_facturacion.sicingr71_importe_total,
                                                       sicingr71_det_facturacion.sicingr71_importe_impuestos,
                                                       sicingr71_det_facturacion.sicingr71_importe_retenido,
        
                                                       sicingr71_det_facturacion.sicingr71_importe_traslado,
                                                       sicingr71_det_facturacion.sicingr71_importe_locales,
                                                       sicingr71_det_facturacion.sicingr71_importe_neto,
                                                       sicingr71_det_facturacion.sicingr71_factglobal )
                values( :id_sicingr70,
                        :id_sicingr95_orig,
                        :pymvent70_docnro,
                        'VENTA',
                        1,
        
                        :pymvent70_neto,
                        :pymvent70_neto,
                        0.00,
                        :pymvent70_neto,
                        0.00,
                        0.00,
        
                        0.00,
                        0.00,
                        :pymvent70_neto,
                        1 );
            end
        end

        /* ---------------------------------------------------------------------------------------------------------------------------- */
        /* ---------------------------------------------------------------------------------------------------------------------------- */

        update pymvent81_det_factglobal set pymvent81_det_factglobal.pymvent81_procesado = 1
        where pymvent81_det_factglobal.id_pymvent81 = :id_pymvent81;
    end

    suma_diferencia = suma_ptovta - suma_factura;

    /* ---------------------------------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------------------------------- */

    sicingr70_subtotal_sum = 0;
    sicingr70_descuento_sum = 0;
    sicingr70_total_sum = 0;
    sicingr70_totimp_retenidos_sum = 0;
    sicingr70_totimp_traslados_sum = 0;
    sicingr70_totimp_locales_sum = 0;
    sicingr70_neto_sum = 0;

    select
    cast(sum(sicingr71_det_facturacion.sicingr71_importe_subtotal) as decimal(18, 2)),
    cast(sum(sicingr71_det_facturacion.sicingr71_importe_descuento) as decimal(18, 2)),
    cast(sum(sicingr71_det_facturacion.sicingr71_importe_total) as decimal(18, 2)),
    cast(sum(sicingr71_det_facturacion.sicingr71_importe_retenido) as decimal(18, 2)),
    cast(sum(sicingr71_det_facturacion.sicingr71_importe_traslado) as decimal(18, 2)),
    cast(sum(sicingr71_det_facturacion.sicingr71_importe_locales) as decimal(18, 2))
    from sicingr71_det_facturacion
    where sicingr71_det_facturacion.rela_sicingr70 = :id_sicingr70
    into :sicingr70_subtotal_sum,
         :sicingr70_descuento_sum,
         :sicingr70_total_sum,
         :sicingr70_totimp_retenidos_sum,
         :sicingr70_totimp_traslados_sum,
         :sicingr70_totimp_locales_sum;

    if(sicingr70_total_sum is not null and sicingr70_total_sum <> 0) then
    begin
        sicingr70_neto_sum = ((sicingr70_total_sum + sicingr70_totimp_traslados_sum) - sicingr70_totimp_retenidos_sum) + sicingr70_totimp_locales_sum;
    
        update sicingr70_cab_facturacion set sicingr70_cab_facturacion.sicingr70_subtotal = :sicingr70_subtotal_sum,
                                             sicingr70_cab_facturacion.sicingr70_descuento = :sicingr70_descuento_sum,
                                             sicingr70_cab_facturacion.sicingr70_total = :sicingr70_total_sum,
                                             sicingr70_cab_facturacion.sicingr70_totimp_retenidos = :sicingr70_totimp_retenidos_sum,
                                             sicingr70_cab_facturacion.sicingr70_totimp_traslados = :sicingr70_totimp_traslados_sum,
                                             sicingr70_cab_facturacion.sicingr70_totimp_locales = :sicingr70_totimp_locales_sum,
                                             sicingr70_cab_facturacion.sicingr70_neto = :sicingr70_neto_sum
        where sicingr70_cab_facturacion.id_sicingr70 = :id_sicingr70;
    
        ok = 1;
    end
    else
    begin
        ok = 0;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT80_FACTGLOBAL_IMP (
    RELA_SOCMAIN01 BIGINT,
    IMPUESTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TASAOCUOTA DOUBLE PRECISION,
    FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_BASE DOUBLE PRECISION)
RETURNS (
    ID_SICINGR95 BIGINT,
    IMPORTE_CALCULO DOUBLE PRECISION)
AS
declare variable FIND_CONCEPTO_FACTOR integer;
begin
    impuesto = upper(trim(impuesto));
    importe_calculo = 0;

    if (tasaocuota <> 0) then
    begin
        find_concepto_factor = 2;
        importe_calculo = cast((importe_base * tasaocuota / 100) as decimal(18,2));
    end
    else if (upper(trim(factor)) = 'EXENTO') then
        find_concepto_factor = 1;
    else
        find_concepto_factor = 0;

    select first 1 prd_pymvent81_cabconcep.id_sicingr95
    from prd_pymvent81_cabconcep(:rela_socmain01)
    where prd_pymvent81_cabconcep.factor = :find_concepto_factor
    into :id_sicingr95;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_PYMVENT81_CABCONCEP (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    ID_SICINGR95 BIGINT,
    FACTOR INTEGER)
AS
begin
    for select
    sicingr95_cab_conceptos.id_sicingr95,
    sicxmls04_det_conceptos.sicxmls04_excento
    from sicingr95_cab_conceptos
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and sicingr95_cab_conceptos.sicingr95_codigo like 'FACTGLOBAL-%'
    and sicxmls04_det_conceptos.sicxmls04_tipo = 'I'
    into :id_sicingr95,
         :factor
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT01_COPIA (
    RELA_SOCMAIN01_SOURCE BIGINT,
    RELA_SOCMAIN01_TARJET BIGINT)
RETURNS (
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICCONT01_SOURCE bigint;
declare variable ID_SICCONT02_NEW bigint;
declare variable SICCONT01_DESCRIPCION_SOURCE varchar(400);
declare variable EXISTE_TARJET bigint;
declare variable RELA_SICCONT01 bigint;
declare variable RELA_SOCSYST06 bigint;
declare variable RELA_SICCONT02 bigint;
declare variable ID_SICCONT02 bigint;
declare variable SICCONT02_CODIGO_EXT varchar(50);
declare variable SICCONT02_DESCRIPCION varchar(400);
declare variable SICCONT02_TIPO varchar(1);
declare variable SICCONT02_CODAGRUP varchar(50);
begin
    DELETE from tmp_siccont01_siccont02 where tmp_siccont01_siccont02.usuario = current_user;

    select
    siccont01_cab_planctas.id_siccont01,
    siccont01_cab_planctas.siccont01_descripcion
    from siccont01_cab_planctas
    where siccont01_cab_planctas.rela_socmain01 = :RELA_SOCMAIN01_SOURCE
    into :id_siccont01_source,
         :siccont01_descripcion_source;

    if (id_siccont01_source is not null) then
    begin
        existe_tarjet = null;

        select socmain01_cab_empresas.id_socmain01
        from socmain01_cab_empresas
        where socmain01_cab_empresas.id_socmain01 = :rela_socmain01_tarjet
        into :existe_tarjet;

        if (existe_tarjet is not null) then
        begin
            existe_tarjet = null;

            select siccont01_cab_planctas.rela_socmain01
            from siccont01_cab_planctas
            where siccont01_cab_planctas.rela_socmain01 = :rela_socmain01_tarjet
            into :existe_tarjet; 
            
            if (existe_tarjet is null) then
            begin
                insert into siccont01_cab_planctas( siccont01_cab_planctas.rela_socmain01,
                                                    siccont01_cab_planctas.siccont01_descripcion)
                values(:rela_socmain01_tarjet, :siccont01_descripcion_source);

                select
                socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT01'
                INTO :rela_siccont01;

                /* ------------------------------------------------------------------------------------- */

                for select
                siccont02_arb_planctas.rela_socsyst06,
                siccont02_arb_planctas.rela_siccont02,
                siccont02_arb_planctas.id_siccont02,
                siccont02_arb_planctas.siccont02_codigo_ext,
                siccont02_arb_planctas.siccont02_descripcion,
                siccont02_arb_planctas.siccont02_tipo,
                siccont02_arb_planctas.siccont02_codagrup
                from siccont02_arb_planctas
                where siccont02_arb_planctas.rela_siccont01 = :id_siccont01_source
                order by siccont02_arb_planctas.siccont02_codigo
                into :rela_socsyst06,
                     :rela_siccont02,
                     :id_siccont02,
                     :siccont02_codigo_ext,
                     :siccont02_descripcion,
                     :siccont02_tipo,
                     :siccont02_codagrup
                do
                begin
                    if (rela_siccont02 is not null) then
                    begin
                       select tmp_siccont01_siccont02.id_siccont02_tarjet
                       from tmp_siccont01_siccont02
                       where tmp_siccont01_siccont02.usuario = current_user
                       and tmp_siccont01_siccont02.id_siccont02_source = :rela_siccont02
                       into :rela_siccont02;
                    end

                    insert into siccont02_arb_planctas( siccont02_arb_planctas.rela_siccont01,
                                                        siccont02_arb_planctas.rela_socsyst06,
                                                        siccont02_arb_planctas.rela_siccont02,
                                                        siccont02_arb_planctas.siccont02_codigo,
                                                        siccont02_arb_planctas.siccont02_codigo_ext,
                                                        siccont02_arb_planctas.siccont02_descripcion,
                                                        siccont02_arb_planctas.siccont02_tipo,
                                                        siccont02_arb_planctas.siccont02_codagrup)
                    values( :rela_siccont01,
                            :rela_socsyst06,
                            :rela_siccont02,
                            'xxxx',
                            :siccont02_codigo_ext,
                            :siccont02_descripcion,
                            :siccont02_tipo,
                            :siccont02_codagrup);

                    select socsyst91_tbl_ultids.socsyst91_ultid
                    from socsyst91_tbl_ultids
                    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT02'
                    INTO :id_siccont02_new;

                    insert into tmp_siccont01_siccont02( tmp_siccont01_siccont02.usuario,
                                                         tmp_siccont01_siccont02.id_siccont02_source,
                                                         tmp_siccont01_siccont02.id_siccont02_tarjet)
                    values(current_user, :id_siccont02, :id_siccont02_new);

                    id_siccont02 = :id_siccont02_new;
                end

                status = 'Ok';
                suspend;
            end
            else
            begin
                status = 'La Empresa Destino ya tiene Catálogo de Cuentas';
                suspend;
            end
        end
        else
        begin
            status = 'No existe la Empresa Destino';
            suspend;
        end
    end
    else
    begin
        status = 'No Existe la Empresa Origen';
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT02_SICCONT11 (
