CREATE OR ALTER PROCEDURE PRD_SICCONT10_TRASPASO_BANCOS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCMAIN05_BANCO_ORIGEN BIGINT,
    RELA_SOCMAIN05_BANCO_DESTINO BIGINT,
    IMPORTE DOUBLE PRECISION,
    FECHA DATE,
    COTIZA DOUBLE PRECISION)
RETURNS (
    STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICCONT02_TRASPASO bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01_ORIGEN bigint;
declare variable ID_SOCSYST10_CTM01_DESTINO bigint;
declare variable ID_SICCONT10_NEW bigint;
declare variable ID_SICXMLS01 bigint;
declare variable RELA_SICCONT02_BANCO_ORIGEN bigint;
declare variable RELA_SICCONT02_BANCO_DESTINO bigint;
begin
    status = 'OK';

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    select GRD_SICXMLS03.rela_siccont02
    from GRD_SICXMLS03(:id_sicxmls01)
    where  GRD_SICXMLS03.socsyst10_codigo = 'TRASPASO'
    and GRD_SICXMLS03.rela_siccont02 is not null
    into :rela_siccont02_traspaso;

    if (rela_siccont02_traspaso is null) then
        status = 'No se ha parametrizado la Cuenta de Traspaso';

    if (status = 'OK') then
    begin
        select cbo_socsyst10_ctp01.id_socsyst10
        from cbo_socsyst10_ctp01
        where cbo_socsyst10_ctp01.socsyst10_codigo = 'TRASPASO'
        into :id_socsyst10_ctp01;

        select cbo_socsyst10_ctp02.id_socsyst10
        from cbo_socsyst10_ctp02
        where cbo_socsyst10_ctp02.socsyst10_codigo = 'PO-3-DIA'
        into :id_socsyst10_ctp02;

        select
        GRD_SOCMAIN05.rela_siccont02,
        GRD_SOCMAIN05.rela_socsyst10_ctm01
        from GRD_SOCMAIN05
        where GRD_SOCMAIN05.id_socmain05 = :rela_socmain05_banco_origen
        into :rela_siccont02_banco_origen,
             :id_socsyst10_ctm01_origen;

        select
        GRD_SOCMAIN05.rela_siccont02,
        GRD_SOCMAIN05.rela_socsyst10_ctm01
        from GRD_SOCMAIN05
        where GRD_SOCMAIN05.id_socmain05 = :rela_socmain05_banco_destino
        into :rela_siccont02_banco_destino,
             :id_socsyst10_ctm01_destino;

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        insert into siccont10_cab_polizas( siccont10_cab_polizas.rela_socmain01,
                                           siccont10_cab_polizas.rela_socmain21,
                                           siccont10_cab_polizas.rela_socusua01,
                                           siccont10_cab_polizas.rela_socsyst10_ctp01,
                                           siccont10_cab_polizas.rela_socsyst10_ctp02,
                                           siccont10_cab_polizas.rela_socsyst10_ctm01,
                                           siccont10_cab_polizas.siccont10_tipo_entidad,
                                           siccont10_cab_polizas.siccont10_descripcion,
                                           siccont10_cab_polizas.siccont10_docnro,
                                           siccont10_cab_polizas.siccont10_fcta,
                                           siccont10_cab_polizas.siccont10_cotiza,
                                           siccont10_cab_polizas.siccont10_origen )
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01_origen,
                'S',
                'TRASPASO ENTRE CTAS DE BANCO ORIGEN',
                'XXX',
                :fecha,
                :cotiza,
                'X' );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes )
        values( :id_siccont10_new,
                :rela_siccont02_banco_origen,
                'S',
                0,
                :importe,
                extract(year from :fecha),
                extract(month from  :fecha) );

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes )
        values( :id_siccont10_new,
                :rela_siccont02_traspaso,
                'S',
                :importe,
                0,
                extract(year from :fecha),
                extract(month from  :fecha) );

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        insert into siccont10_cab_polizas( siccont10_cab_polizas.rela_socmain01,
                                           siccont10_cab_polizas.rela_socmain21,
                                           siccont10_cab_polizas.rela_socusua01,
                                           siccont10_cab_polizas.rela_socsyst10_ctp01,
                                           siccont10_cab_polizas.rela_socsyst10_ctp02,
                                           siccont10_cab_polizas.rela_socsyst10_ctm01,
                                           siccont10_cab_polizas.siccont10_tipo_entidad,
                                           siccont10_cab_polizas.siccont10_descripcion,
                                           siccont10_cab_polizas.siccont10_docnro,
                                           siccont10_cab_polizas.siccont10_fcta,
                                           siccont10_cab_polizas.siccont10_cotiza,
                                           siccont10_cab_polizas.siccont10_origen )
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01_destino,
                'S',
                'TRASPASO ENTRE CTAS DE BANCO DESTINO',
                'XXX',
                :fecha,
                :cotiza,
                'X' );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes )
        values( :id_siccont10_new,
                :rela_siccont02_traspaso,
                'S',
                0,
                :importe,
                extract(year from :fecha),
                extract(month from  :fecha) );

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes )
        values( :id_siccont10_new,
                :rela_siccont02_banco_destino,
                'S',
                :importe,
                0,
                extract(year from :fecha),
                extract(month from  :fecha) );

    end
    
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_AUDITORIA (
    ACCION INTEGER)
RETURNS (
    ID_SOCMAIN01 BIGINT,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    RELA_SICCONT02 BIGINT,
    ID_SICCONT11 BIGINT,
    ERROR VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICCONT02_UPDATE BIGINT)
AS
declare variable ID_EXISTE_COMO_PADRE bigint;
declare variable RELA_SICCONT02_TMP bigint;
begin
    for select
    CBO_SOCMAIN01.id_socmain01,
    CBO_SOCMAIN01.socmain01_nomcomercial
    from CBO_SOCMAIN01
    into :id_socmain01,
         :socmain01_nomcomercial
    do
    begin
        for select
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont11_det_polizas.rela_siccont02,
        siccont11_det_polizas.id_siccont11
        from siccont10_cab_polizas
        inner join siccont11_det_polizas  on (siccont11_det_polizas.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
        where siccont10_cab_polizas.rela_socmain01 = :id_socmain01
        into :siccont10_docnro,
             :siccont10_fcta,
             :rela_siccont02,
             :id_siccont11
        do
        begin
            error = 'N';
            id_existe_como_padre = null;
    
            select first 1
            siccont02_arb_planctas.id_siccont02
            from siccont01_cab_planctas
            inner join siccont02_arb_planctas on (siccont02_arb_planctas.rela_siccont01 = siccont01_cab_planctas.id_siccont01)
            where siccont01_cab_planctas.rela_socmain01 = :id_socmain01
            and siccont02_arb_planctas.rela_siccont02 = :rela_siccont02
            into :id_existe_como_padre;
    
            if (id_existe_como_padre is not null) then
            begin
                rela_siccont02_tmp = :rela_siccont02;
    
                while( rela_siccont02_tmp is not null  ) do
                begin
                    select first 1
                    siccont02_arb_planctas.id_siccont02
                    from siccont01_cab_planctas
                    inner join siccont02_arb_planctas on (siccont02_arb_planctas.rela_siccont01 = siccont01_cab_planctas.id_siccont01)
                    where siccont01_cab_planctas.rela_socmain01 = :id_socmain01
                    and siccont02_arb_planctas.rela_siccont02 = :rela_siccont02_tmp
                    into :rela_siccont02_update;
    
                    if (rela_siccont02_update is null) then
                    begin
                        rela_siccont02_update = :rela_siccont02_tmp;
    
                        if (accion is not null and accion = 10) then
                            update siccont11_det_polizas set siccont11_det_polizas.rela_siccont02 = :rela_siccont02_update
                            where siccont11_det_polizas.id_siccont11 = :id_siccont11;
    
                        break;
                    end
                    else
                    begin
                        rela_siccont02_tmp = :rela_siccont02_update;
                        rela_siccont02_update = null;
                    end
                end
    
                error = 'S';
                suspend;
            end
    
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_AUXILIAR (
    ID_SOCMAIN01 BIGINT,
    CUENTA_DESDE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CUENTA_HASTA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE,
    MODALIDAD INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORIGEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_POLIZA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT11_DEBE DOUBLE PRECISION,
    SICCONT11_HABER DOUBLE PRECISION,
    SALDO_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO DOUBLE PRECISION,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SALDO_INI double precision;
declare variable SALDO_FIN double precision;
declare variable CODIGO_CTA varchar(50);
declare variable ANO_FILTRO integer;
declare variable ENTRO integer;
begin
    DELETE FROM tmp_siccont11_auxiliar where tmp_siccont11_auxiliar.usuario = current_user;

    INSERT INTO tmp_siccont11_auxiliar(
    tmp_siccont11_auxiliar.usuario,
    tmp_siccont11_auxiliar.rela_socmain01,
    tmp_siccont11_auxiliar.id_siccont02,
    tmp_siccont11_auxiliar.siccont02_tipo,
    tmp_siccont11_auxiliar.saldo,
    tmp_siccont11_auxiliar.suma_debe,
    tmp_siccont11_auxiliar.suma_haber,
    tmp_siccont11_auxiliar.siccont10_fcta,
    tmp_siccont11_auxiliar.movimientos)
    
    select
    current_user,
    QRY_SICCONT11_AUXILIAR.rela_socmain01,
    QRY_SICCONT11_AUXILIAR.id_siccont02,
    QRY_SICCONT11_AUXILIAR.siccont02_tipo,
    QRY_SICCONT11_AUXILIAR.saldo,
    QRY_SICCONT11_AUXILIAR.suma_debe,
    QRY_SICCONT11_AUXILIAR.suma_haber,
    QRY_SICCONT11_AUXILIAR.siccont10_fcta,
    QRY_SICCONT11_AUXILIAR.movimientos
    from QRY_SICCONT11_AUXILIAR
    where QRY_SICCONT11_AUXILIAR.rela_socmain01 = :id_socmain01;

    for select
    siccont02_arb_planctas.id_siccont02,
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    siccont02_arb_planctas.siccont02_tipo
    from siccont01_cab_planctas
    inner join siccont02_arb_planctas on (siccont02_arb_planctas.rela_siccont01 = siccont01_cab_planctas.id_siccont01)
    where siccont01_cab_planctas.rela_socmain01 =  :id_socmain01
    and siccont02_arb_planctas.siccont02_codigo_ext between :cuenta_desde and :cuenta_hasta
    and not EXISTS (SELECT siccont02_arb_planctas.id_siccont02
                      FROM siccont02_arb_planctas siccont02
                      WHERE siccont02.rela_siccont02 = siccont02_arb_planctas.id_siccont02)
    order by siccont02_arb_planctas.siccont02_codigo_ext
    into :id_siccont02,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_tipo
    do
    begin
        saldo_ini = null;
        saldo_fin = null;
        saldo = null;

        saldo_tipo = null;
        origen = null;
        tipo_poliza = null;
        siccont10_docnro = null;
        siccont10_descripcion = null;
        siccont10_fcta = null;
        siccont11_debe = 0;
        siccont11_haber = 0;

        tipo = 'Cta.Balance';
        ano_filtro = extract(YEAR from :fecha_hasta);
        codigo_cta = substring(siccont02_codigo_ext FROM 1 FOR 1);

        if (codigo_cta >= '4') then
        BEGIN
            tipo = 'Cta.Resultado';

            SELECT
            sum(tmp_siccont11_auxiliar.saldo)
            FROM tmp_siccont11_auxiliar
            WHERE tmp_siccont11_auxiliar.id_siccont02 = :id_siccont02
            and extract(YEAR from tmp_siccont11_auxiliar.siccont10_fcta) = :ano_filtro
            and tmp_siccont11_auxiliar.siccont10_fcta < :fecha_desde
            into :saldo_ini;
        END
        ELSE
        BEGIN
            SELECT
            sum(tmp_siccont11_auxiliar.saldo)
            FROM tmp_siccont11_auxiliar
            WHERE tmp_siccont11_auxiliar.id_siccont02 = :id_siccont02
            and tmp_siccont11_auxiliar.siccont10_fcta < :fecha_desde
            into :saldo_ini;
        END


        saldo_tipo = 'Inicial';
        if (saldo_ini is null) then
            saldo = 0;
        else
            saldo = saldo_ini;

        suspend;

        for select
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_descripcion,
        siccont10_cab_polizas.siccont10_fcta,
        ctp01.socsyst10_descripcion,
        ctp02.socsyst10_descripcion,
        siccont11_det_polizas.siccont11_debe,
        siccont11_det_polizas.siccont11_haber
        from siccont10_cab_polizas
        inner join siccont11_det_polizas on (siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10)
        inner join socsyst10_det_entradas ctp01 on (ctp01.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
        inner join socsyst10_det_entradas ctp02 on (ctp02.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp02)
        where siccont10_cab_polizas.rela_socmain01 = :id_socmain01
        and siccont10_cab_polizas.siccont10_fcta between :fecha_desde and :fecha_hasta
        and siccont11_det_polizas.rela_siccont02 = :id_siccont02
        order by siccont10_cab_polizas.siccont10_fcta, siccont10_cab_polizas.siccont10_docnro
        into :siccont10_docnro,
             :siccont10_descripcion,
             :siccont10_fcta,
             :origen,
             :tipo_poliza,
             :siccont11_debe,
             :siccont11_haber
        do
        begin
            saldo = 0;
            entro = 0;
            saldo_tipo = 'Póliza';

            if (tipo = 'Cta.Balance') then
                entro = 1;
            else if (extract(YEAR from :siccont10_fcta) =  :ano_filtro) then
                entro = 1;

            if (entro = 1) then
            begin
                if (siccont02_tipo = 'D') then
                    saldo = siccont11_debe - siccont11_haber;
                else
                    saldo = siccont11_haber - siccont11_debe;

                suspend;    
            end
        end

        if (modalidad = 1) then
        begin
            saldo_tipo = null;
            origen = null;
            tipo_poliza = null;
            siccont10_docnro = null;
            siccont10_descripcion = null;
            siccont10_fcta = null;
            siccont11_debe = 0;
            siccont11_haber = 0;

            if (saldo_ini is null) then
                saldo_ini = 0;

            if (codigo_cta >= '4') then
                SELECT
                sum(tmp_siccont11_auxiliar.suma_debe),
                sum(tmp_siccont11_auxiliar.suma_haber),
                sum(tmp_siccont11_auxiliar.saldo)
                FROM tmp_siccont11_auxiliar
                WHERE tmp_siccont11_auxiliar.id_siccont02 = :id_siccont02
                and extract(YEAR from tmp_siccont11_auxiliar.siccont10_fcta) = :ano_filtro
                and tmp_siccont11_auxiliar.siccont10_fcta between :fecha_desde and :fecha_hasta
                into :siccont11_debe,
                     :siccont11_haber,
                     :saldo_fin;
            else
                SELECT
                sum(tmp_siccont11_auxiliar.suma_debe),
                sum(tmp_siccont11_auxiliar.suma_haber),
                sum(tmp_siccont11_auxiliar.saldo)
                FROM tmp_siccont11_auxiliar
                WHERE tmp_siccont11_auxiliar.id_siccont02 = :id_siccont02
                and tmp_siccont11_auxiliar.siccont10_fcta between :fecha_desde and :fecha_hasta
                into :siccont11_debe,
                     :siccont11_haber,
                     :saldo_fin;

            saldo_tipo = 'Final';
            if (saldo_fin is null) then
            begin
                siccont11_debe = 0;
                siccont11_haber = 0;
                saldo = saldo_ini;
            end
            else
                saldo = saldo_ini + saldo_fin;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANCE (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    RESULTADO_ACTUAL DOUBLE PRECISION,
    RESULTADO_HISTORICO DOUBLE PRECISION)
AS
declare variable INGRESOS_ACTUAL double precision;
declare variable EGRESOS_ACTUAL double precision;
declare variable INGRESOS_HISTO double precision;
declare variable EGRESOS_HISTO double precision;
begin
    delete from TMP_SICCONT11_BALANZA_BALANCE where TMP_SICCONT11_BALANZA_BALANCE.usuario = current_user;

    insert into TMP_SICCONT11_BALANZA_BALANCE
    select
    current_user,
    1,
    prd_siccont11_balanza.id_siccont02,
    prd_siccont11_balanza.siccont02_tipo,
    prd_siccont11_balanza.socsyst06_nivel,
    prd_siccont11_balanza.siccont02_codagrup,
    prd_siccont11_balanza.siccont02_codigo_ext,
    prd_siccont11_balanza.siccont02_descripcion,
    prd_siccont11_balanza.saldo_inicial,
    prd_siccont11_balanza.saldo_final
    from prd_siccont11_balanza(:id_socmain01, (:ano), :mes, 0)
    where prd_siccont11_balanza.siccont02_codigo_ext < '8';

    insert into TMP_SICCONT11_BALANZA_BALANCE
    select
    current_user,
    0,
    prd_siccont11_balanza.id_siccont02,
    prd_siccont11_balanza.siccont02_tipo,
    prd_siccont11_balanza.socsyst06_nivel,
    prd_siccont11_balanza.siccont02_codagrup,
    prd_siccont11_balanza.siccont02_codigo_ext,
    prd_siccont11_balanza.siccont02_descripcion,
    prd_siccont11_balanza.saldo_inicial,
    prd_siccont11_balanza.saldo_final
    from prd_siccont11_balanza(:id_socmain01, (:ano-1), :mes, 0)
    where prd_siccont11_balanza.siccont02_codigo_ext < '8';

    /* --------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------- */

    select sum(tmp_siccont11_balanza_balance.saldo_final)
    from tmp_siccont11_balanza_balance
    where tmp_siccont11_balanza_balance.usuario = current_user
    and tmp_siccont11_balanza_balance.actual = 1
    and tmp_siccont11_balanza_balance.socsyst06_nivel = 1
    and tmp_siccont11_balanza_balance.siccont02_codigo_ext = '4'
    into :ingresos_actual;

    select sum(tmp_siccont11_balanza_balance.saldo_final)
    from tmp_siccont11_balanza_balance
    where tmp_siccont11_balanza_balance.usuario = current_user
    and tmp_siccont11_balanza_balance.actual = 1
    and tmp_siccont11_balanza_balance.socsyst06_nivel = 1
    and tmp_siccont11_balanza_balance.siccont02_codigo_ext > '4'
    into :egresos_actual;

    resultado_actual = ingresos_actual - egresos_actual;

    /* --------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------- */

    select sum(tmp_siccont11_balanza_balance.saldo_final)
    from tmp_siccont11_balanza_balance
    where tmp_siccont11_balanza_balance.usuario = current_user
    and tmp_siccont11_balanza_balance.actual = 0
    and tmp_siccont11_balanza_balance.socsyst06_nivel = 1
    and tmp_siccont11_balanza_balance.siccont02_codigo_ext = '4'
    into :ingresos_histo;

    select sum(tmp_siccont11_balanza_balance.saldo_final)
    from tmp_siccont11_balanza_balance
    where tmp_siccont11_balanza_balance.usuario = current_user
    and tmp_siccont11_balanza_balance.actual = 0
    and tmp_siccont11_balanza_balance.socsyst06_nivel = 1
    and tmp_siccont11_balanza_balance.siccont02_codigo_ext > '4'
    into :egresos_histo;
    
    resultado_historico = ingresos_histo - egresos_histo;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANCE_TOTALES
RETURNS (
    ID_TMPSICONT99 BIGINT,
    ACTIVO_CIRCULANTE INTEGER,
    ACTIVO_NOCIRCULANTE DOUBLE PRECISION,
    ACTIVO_TOTAL DOUBLE PRECISION,
    ACTIVO_TOTAL_INICIAL DOUBLE PRECISION,
    ACTIVO_TOTAL_MES DOUBLE PRECISION,
    PASIVO_CIRCULANTE DOUBLE PRECISION,
    PASIVO_NOCIRCULANTE DOUBLE PRECISION,
    PASIVO_TOTAL DOUBLE PRECISION,
    PASIVO_TOTAL_INICIAL DOUBLE PRECISION,
    PASIVO_TOTAL_MES DOUBLE PRECISION,
    CAPITAL DOUBLE PRECISION,
    CAPITAL_INICIAL DOUBLE PRECISION,
    CAPITAL_MES DOUBLE PRECISION,
    UTILIDAD DOUBLE PRECISION,
    UTILIDAD_INICIAL DOUBLE PRECISION,
    UTILIDAD_MES DOUBLE PRECISION,
    PASIVO_MAS_CAPITAL DOUBLE PRECISION,
    PASIVO_MAS_CAPITAL_INICIAL DOUBLE PRECISION,
    PASIVO_MAS_CAPITAL_MES DOUBLE PRECISION)
AS
begin
    id_tmpsicont99 = 1;

    select
    sum(tmp_siccont11_balance.saldo_historico),
    sum(tmp_siccont11_balance.saldo_actual),
    sum(tmp_siccont11_balance.saldo_mes)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '1%'
    into :activo_total_inicial,
         :activo_total,
         :activo_total_mes;

    activo_total = round(activo_total, 2);

    select
    sum(tmp_siccont11_balance.saldo_actual)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '11%'
    into :activo_circulante;

    select
    sum(tmp_siccont11_balance.saldo_actual)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '12%'
    into :activo_nocirculante;

    select
    sum(tmp_siccont11_balance.saldo_historico),
    sum(tmp_siccont11_balance.saldo_actual),
    sum(tmp_siccont11_balance.saldo_mes)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '2%'
    into :pasivo_total_inicial,
         :pasivo_total,
         :pasivo_total_mes;

    select sum(tmp_siccont11_balance.saldo_actual)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '21%'
    into :pasivo_circulante;

    select sum(tmp_siccont11_balance.saldo_actual)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '22%'
    into :pasivo_nocirculante;

    select
    sum(tmp_siccont11_balance.saldo_historico),
    sum(tmp_siccont11_balance.saldo_actual),
    sum(tmp_siccont11_balance.saldo_mes)
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like '3%'
    into :capital_inicial,
         :capital,
         :capital_mes;

    select
    prd_siccont11_resultado_totales.utilidad,
    prd_siccont11_resultado_totales.utilidad_inicial
    from prd_siccont11_resultado_totales
    into :utilidad,
         :utilidad_inicial;

    utilidad_mes = utilidad - utilidad_inicial;

    pasivo_mas_capital = round(pasivo_total + capital, 2);
    pasivo_mas_capital_inicial = pasivo_total_inicial + capital_inicial;
    pasivo_mas_capital_mes = pasivo_total_mes + capital_mes;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER,
    SINMOVI INTEGER)
RETURNS (
    SOCSYST06_NIVEL INTEGER,
    ID_SICCONT02 INTEGER,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_INICIAL DOUBLE PRECISION,
    SUMA_DEBE DOUBLE PRECISION,
    SUMA_HABER DOUBLE PRECISION,
    SALDO_FINAL DOUBLE PRECISION,
    AFECTACION INTEGER)
AS
declare variable MES_INI integer;
declare variable ANO_INI integer;
declare variable SUMA_DEBE_INI double precision;
declare variable SUMA_HABER_INI double precision;
declare variable SALDO_CTA double precision;
declare variable LIKE_CODIGO varchar(50);
declare variable ANO_C varchar(4);
declare variable MES_C varchar(2);
declare variable ANOMES integer;
declare variable SICCONT02_CODIGO varchar(50);
declare variable IS_CUENTA_FINAL integer;
begin
    DELETE FROM TMP_SICCONT11_BALANZA WHERE TMP_SICCONT11_BALANZA.tmpcont11_user = current_user;

    INSERT INTO tmp_siccont11_balanza
    SELECT
    current_user,
    qry_siccont11_balanza.rela_siccont02,
    qry_siccont11_balanza.siccont02_tipo,
    qry_siccont11_balanza.siccont02_codigo_ext,
    qry_siccont11_balanza.siccont02_codigo,
    qry_siccont11_balanza.suma_debe,
    qry_siccont11_balanza.suma_haber,
    qry_siccont11_balanza.siccont11_ano,
    qry_siccont11_balanza.siccont11_mes,
    0,
    0
    FROM qry_siccont11_balanza
    WHERE qry_siccont11_balanza.rela_socmain01 = :id_socmain01;

    for select
    siccont02_arb_planctas.siccont02_codagrup,
    socsyst06_det_niveles.socsyst06_nivel,
    siccont02_arb_planctas.id_siccont02,
    siccont02_arb_planctas.siccont02_tipo,
    trim(siccont02_arb_planctas.siccont02_codigo_ext),
    trim(siccont02_arb_planctas.siccont02_codigo),
    siccont02_arb_planctas.siccont02_descripcion
    from siccont01_cab_planctas
    inner join siccont02_arb_planctas on (siccont02_arb_planctas.rela_siccont01 = siccont01_cab_planctas.id_siccont01)
    inner join socsyst06_det_niveles on (socsyst06_det_niveles.id_socsyst06 = siccont02_arb_planctas.rela_socsyst06)
    where siccont01_cab_planctas.rela_socmain01 = :id_socmain01
    order by siccont02_arb_planctas.siccont02_codigo
    into :siccont02_codagrup,
         :socsyst06_nivel,
         :id_siccont02,
         :siccont02_tipo,
         :siccont02_codigo_ext,
         :siccont02_codigo,
         :siccont02_descripcion
    do
    begin
        suma_debe = 0.00;
        suma_haber = 0.00;
        saldo_final = 0.00;
        like_codigo = siccont02_codigo || '%';
        is_cuenta_final = null;
        afectacion = 0;

        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */

        if (mes = 1) then
        begin
            mes_ini = 12;
            ano_ini = ano - 1;
        end
        else
        begin
            mes_ini = mes -1;
            ano_ini = ano;
        end

        ano_c = cast(ano_ini as varchar(4));
        mes_c = cast(mes_ini as varchar(2));

        if (char_length(mes_c) = 1) then
            mes_c = '0' || :mes_c;

        anomes = cast((ano_c || mes_c) as integer);

        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */

        select first 1 tmp_siccont11_balanza.rela_siccont02
        from tmp_siccont11_balanza
        where tmp_siccont11_balanza.tmpcont11_user = current_user
        and tmp_siccont11_balanza.rela_siccont02 = :id_siccont02
        into :is_cuenta_final;

        if (is_cuenta_final is not null) then
        begin
            select
            tmp_siccont11_balanza.suma_debe,
            tmp_siccont11_balanza.suma_haber
            from tmp_siccont11_balanza
            where tmp_siccont11_balanza.tmpcont11_user = current_user
            and tmp_siccont11_balanza.rela_siccont02 = :id_siccont02
            and tmp_siccont11_balanza.siccont11_ano = :ano
            and tmp_siccont11_balanza.siccont11_mes = :mes
            into :suma_debe,
                 :suma_haber;

            AFECTACION = 1;
        end
        else
        begin
            select
            sum(tmp_siccont11_balanza.suma_debe),
            sum(tmp_siccont11_balanza.suma_haber)
            from tmp_siccont11_balanza
            where tmp_siccont11_balanza.tmpcont11_user = current_user
            and tmp_siccont11_balanza.siccont11_ano = :ano
            and tmp_siccont11_balanza.siccont11_mes = :mes
            and tmp_siccont11_balanza.siccont02_codigo like :like_codigo
            into :suma_debe,
                 :suma_haber;
        end

        if (suma_debe is null) then
            suma_debe = 0.00;

        if (suma_haber is null) then
            suma_haber = 0.00;

        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */

        if ((SUBSTRING(trim(siccont02_codigo_ext) FROM 1 FOR 1) = '1') or
            (SUBSTRING(trim(siccont02_codigo_ext) FROM 1 FOR 1) = '2') or
            (SUBSTRING(trim(siccont02_codigo_ext) FROM 1 FOR 1) = '3') ) then
        begin
            select
            sum(tmp_siccont11_balanza.suma_debe),
            sum(tmp_siccont11_balanza.suma_haber)
            from tmp_siccont11_balanza
            where tmp_siccont11_balanza.tmpcont11_user = current_user
            and tmp_siccont11_balanza.anomes <= :anomes
            and tmp_siccont11_balanza.siccont02_codigo like :like_codigo
            into :suma_debe_ini,
                 :suma_haber_ini;
        end
        else
        begin
            select
            sum(tmp_siccont11_balanza.suma_debe),
            sum(tmp_siccont11_balanza.suma_haber)
            from tmp_siccont11_balanza
            where tmp_siccont11_balanza.tmpcont11_user = current_user
            and (tmp_siccont11_balanza.siccont11_ano = :ano
            and tmp_siccont11_balanza.siccont11_mes < :mes)
            and tmp_siccont11_balanza.siccont02_codigo like :like_codigo
            into :suma_debe_ini,
                 :suma_haber_ini;
        end

        if (suma_debe_ini is null) then
            suma_debe_ini = 0;

        if (suma_haber_ini is null) then
            suma_haber_ini = 0;

        if (siccont02_tipo = 'D') then
            saldo_inicial = :suma_debe_ini - :suma_haber_ini;
        else if (siccont02_tipo = 'H') then
            saldo_inicial = :suma_haber_ini - :suma_debe_ini;

        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */

        if (siccont02_tipo = 'D') then
            saldo_cta =  :suma_debe - :suma_haber;
        else if (siccont02_tipo = 'H') then
            saldo_cta = :suma_haber - :suma_debe;

        saldo_final = :saldo_inicial + :saldo_cta;

        /* --------------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------------- */

        if (sinmovi = 1) then
        begin
            /* if (not (suma_debe = 0 and suma_haber = 0)) then */
            if ((cast((suma_debe + suma_haber) as numeric(15,2)) <> 0) or saldo_final <> 0) then
                suspend;
        end
        else if (sinmovi = 0) then
        begin
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA_BALANCE (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER,
    CREA_TEMPORARIO INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST06_NIVEL INTEGER,
    CATALOGO_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_HISTORICO DOUBLE PRECISION,
    SALDO_ACTUAL DOUBLE PRECISION,
    SALDO_MES DOUBLE PRECISION)
AS
declare variable RESULTADO_ACTUAL double precision;
declare variable RESULTADO_HISTORICO double precision;
declare variable SALDO_INICIAL double precision;
begin
    if (crea_temporario = 1) then
        execute procedure prd_siccont11_balance :id_socmain01, :ano, :mes
        returning_values :resultado_actual, :resultado_historico;

    /* ======================================================================================================================= */

    for select
    TMP_SICCONT11_BALANZA_BALANCE.id_siccont02,
    TMP_SICCONT11_BALANZA_BALANCE.socsyst06_nivel,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_descripcion,
    TMP_SICCONT11_BALANZA_BALANCE.saldo_inicial,
    TMP_SICCONT11_BALANZA_BALANCE.saldo_final,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_codagrup,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_tipo
    from TMP_SICCONT11_BALANZA_BALANCE
    where TMP_SICCONT11_BALANZA_BALANCE.usuario = current_user
    and TMP_SICCONT11_BALANZA_BALANCE.actual = 1
    and (TMP_SICCONT11_BALANZA_BALANCE.socsyst06_nivel > 1
    and TMP_SICCONT11_BALANZA_BALANCE.socsyst06_nivel < 5)
    and TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext < '4'

    order by TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext
    into :id_siccont02,
         :socsyst06_nivel,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :saldo_inicial,
         :saldo_actual,
         :catalogo_sat,
         :siccont02_tipo
    do
    begin
        select
        TMP_SICCONT11_BALANZA_BALANCE.saldo_final
        from TMP_SICCONT11_BALANZA_BALANCE
        where TMP_SICCONT11_BALANZA_BALANCE.usuario = current_user
        and TMP_SICCONT11_BALANZA_BALANCE.actual = 0
        and TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext = :siccont02_codigo_ext
        into :saldo_historico;

        if (saldo_historico is null) then
            saldo_historico = 0;

        /* utilidad */
        if (siccont02_codigo_ext = '32515') then
        begin
            if (resultado_actual > 0) then
                saldo_actual = :resultado_actual;
            else
                saldo_actual = 0;

            if (resultado_historico > 0) then
               saldo_historico = :resultado_historico;
            else
                saldo_historico = 0;
        end
        /* perdida */
        else if (siccont02_codigo_ext = '32530') then
        begin
            if (resultado_actual < 0) then
                saldo_actual = :resultado_actual;
            else
                saldo_actual = 0;

            if (resultado_historico < 0) then
               saldo_historico = :resultado_historico;
            else
                saldo_historico = 0;
        end

        if (socsyst06_nivel <> 4) then
        begin
            saldo_mes = null;
            saldo_actual = null;
            saldo_historico = null;
        end
        else
        begin
            saldo_mes = saldo_actual - saldo_inicial;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA_FIANT (
