            siccont11_det_polizas.siccont11_haber * :porcentaje / 100
            from siccont11_det_polizas
            inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10 )
            inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
