declare variable RELA_SICCONT10_CB_AJUSTE bigint;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SICCONT50 bigint;
begin
    delete from tmp_siccont11_balanza_fiscal where tmp_siccont11_balanza_fiscal.usuario = current_user;

    execute procedure PRD_SICCONT11_BALANZA_FIANT :id_socmain01, :ano, :mes;
    execute procedure PRD_SICCONT11_BALANZA_FIREE :id_socmain01, :ano, :mes;

    for select
    siccont50_cab_bancos.id_siccont50,
    siccont50_cab_bancos.rela_siccont10_poliza
    from siccont50_cab_bancos
    where siccont50_cab_bancos.rela_socmain01 = :id_socmain01
    and siccont50_cab_bancos.siccont50_ano = :ano
    and siccont50_cab_bancos.siccont50_mes = :mes
    into :id_siccont50,
         :rela_siccont10_cb_ajuste
    do
    begin
        if (rela_siccont10_cb_ajuste is not null) then
        begin
            insert into tmp_siccont11_balanza_fiscal ( tmp_siccont11_balanza_fiscal.usuario,
                                                       tmp_siccont11_balanza_fiscal.origen,
                                                       tmp_siccont11_balanza_fiscal.poliza,
                                                       tmp_siccont11_balanza_fiscal.fecha,
                                                       tmp_siccont11_balanza_fiscal.id_siccont02,
                                                       tmp_siccont11_balanza_fiscal.siccont02_tipo,
                                                       tmp_siccont11_balanza_fiscal.siccont02_codigo_ext,
                                                       tmp_siccont11_balanza_fiscal.siccont02_codagrup,
                                                       tmp_siccont11_balanza_fiscal.suma_debe,
