            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta,
            siccont02_arb_planctas.id_siccont02,
            siccont02_arb_planctas.siccont02_tipo,
            siccont02_arb_planctas.siccont02_codigo_ext,
            siccont02_arb_planctas.siccont02_codagrup,
            siccont11_det_polizas.siccont11_debe,
            siccont11_det_polizas.siccont11_haber
            from siccont10_cab_polizas
            inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
            inner join siccont11_det_polizas on ( siccont11_det_polizas.rela_siccont10 = siccont10_cab_polizas.id_siccont10 )
            inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
            where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_cb_ajuste;
        end

        for select distinct
        siccont51_det_bancos.rela_siccont10,
        socsyst10_det_entradas.socsyst10_codigo
        from siccont51_det_bancos
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = siccont51_det_bancos.rela_siccont10)
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
        where siccont51_det_bancos.rela_siccont50 = :id_siccont50
        order by socsyst10_det_entradas.socsyst10_codigo,
                 siccont10_cab_polizas.siccont10_docnro
        into :id_siccont10,
             :socsyst10_codigo
        do
        begin
            insert into tmp_siccont11_balanza_fiscal ( tmp_siccont11_balanza_fiscal.usuario,
                                                       tmp_siccont11_balanza_fiscal.origen,
