            inner join siccont11_det_polizas on ( siccont11_det_polizas.rela_siccont10 = siccont10_cab_polizas.id_siccont10 )
            inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
            where siccont10_cab_polizas.id_siccont10 = :id_siccont10;

            if (socsyst10_codigo = 'DROPZONE-BANCOS') then
            begin
                execute procedure PRD_SICCONT11_BALANZA_FIPRO :id_siccont10;
            end

            else if (socsyst10_codigo = 'DROPZONE-BANCOS-CLIENTE') then
            begin
                execute procedure PRD_SICCONT11_BALANZA_FICLI :id_siccont10;
            end

            else if (socsyst10_codigo = 'DROPZONE-BANCOS-NOMI') then
            begin
                execute procedure PRD_SICCONT11_BALANZA_FINOM :id_siccont10;
            end

            else if (socsyst10_codigo = 'DROPZONE-DEPOSITOS') then
            begin
               execute procedure PRD_SICCONT11_BALANZA_FIDEP :id_siccont10;
            end

            else if (socsyst10_codigo = 'DROPZONE-PERIODO-NOMI') then
            begin
                execute procedure PRD_SICCONT11_BALANZA_FIPER :id_siccont10;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA_FIREE (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER)
AS
declare variable RELA_SICCONT10_AJUSTE bigint;
declare variable RELA_SICCONT10_XML bigint;
declare variable RELA_SICCONT10 bigint;
declare variable RELA_SICEGRE50 bigint;
begin
    for select distinct
    sicegre60_cab_rendicion.rela_siccont10_ajuste
    from sicegre60_cab_rendicion
    inner join siccont10_cab_polizas on ( sicegre60_cab_rendicion.rela_siccont10_ajuste = siccont10_cab_polizas.id_siccont10 )
    where sicegre60_cab_rendicion.rela_socmain01 = :id_socmain01
    and Extract(year FROM siccont10_cab_polizas.siccont10_fcta) = :ano
    and Extract(month FROM siccont10_cab_polizas.siccont10_fcta) = :mes
    into :rela_siccont10_ajuste
    do
    begin
        insert into tmp_siccont11_balanza_fiscal ( tmp_siccont11_balanza_fiscal.usuario,
                                                   tmp_siccont11_balanza_fiscal.origen,
                                                   tmp_siccont11_balanza_fiscal.poliza,
                                                   tmp_siccont11_balanza_fiscal.fecha,
                                                   tmp_siccont11_balanza_fiscal.id_siccont02,
                                                   tmp_siccont11_balanza_fiscal.siccont02_tipo,
                                                   tmp_siccont11_balanza_fiscal.siccont02_codigo_ext,
                                                   tmp_siccont11_balanza_fiscal.siccont02_codagrup,
                                                   tmp_siccont11_balanza_fiscal.suma_debe,
                                                   tmp_siccont11_balanza_fiscal.suma_haber )
        select
        current_user,
        'DROPZONE-REEMBOLSO-AJUSTE',
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont02_arb_planctas.id_siccont02,
        siccont02_arb_planctas.siccont02_tipo,
        siccont02_arb_planctas.siccont02_codigo_ext,
        siccont02_arb_planctas.siccont02_codagrup,
        siccont11_det_polizas.siccont11_debe,
        siccont11_det_polizas.siccont11_haber
        from siccont11_det_polizas
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10 )
        inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_ajuste;
    end

    for select distinct
    sicegre61_det_rendicion.rela_sicegre50,
    sicegre61_det_rendicion.rela_siccont10
    from sicegre61_det_rendicion
    inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre61_det_rendicion.rela_siccont10 )
    where siccont10_cab_polizas.rela_socmain01 = :id_socmain01
    and Extract(year FROM siccont10_cab_polizas.siccont10_fcta) = :ano
    and Extract(month FROM siccont10_cab_polizas.siccont10_fcta) = :mes
    into :rela_sicegre50,
         :rela_siccont10
    do
    begin
        insert into tmp_siccont11_balanza_fiscal ( tmp_siccont11_balanza_fiscal.usuario,
                                                   tmp_siccont11_balanza_fiscal.origen,
                                                   tmp_siccont11_balanza_fiscal.poliza,
                                                   tmp_siccont11_balanza_fiscal.fecha,
                                                   tmp_siccont11_balanza_fiscal.id_siccont02,
                                                   tmp_siccont11_balanza_fiscal.siccont02_tipo,
                                                   tmp_siccont11_balanza_fiscal.siccont02_codigo_ext,
                                                   tmp_siccont11_balanza_fiscal.siccont02_codagrup,
                                                   tmp_siccont11_balanza_fiscal.suma_debe,
                                                   tmp_siccont11_balanza_fiscal.suma_haber )
        select
        current_user,
        'DROPZONE-REEMBOLSO',
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont02_arb_planctas.id_siccont02,
        siccont02_arb_planctas.siccont02_tipo,
        siccont02_arb_planctas.siccont02_codigo_ext,
        siccont02_arb_planctas.siccont02_codagrup,
        siccont11_det_polizas.siccont11_debe,
        siccont11_det_polizas.siccont11_haber
        from siccont11_det_polizas
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10 )
        inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10;

        select sicegre50_det_ctacte.rela_siccont10
        from sicegre50_det_ctacte
        where sicegre50_det_ctacte.id_sicegre50 = :rela_sicegre50
        into :rela_siccont10_xml;

        insert into tmp_siccont11_balanza_fiscal ( tmp_siccont11_balanza_fiscal.usuario,
                                                   tmp_siccont11_balanza_fiscal.origen,
                                                   tmp_siccont11_balanza_fiscal.poliza,
                                                   tmp_siccont11_balanza_fiscal.fecha,
                                                   tmp_siccont11_balanza_fiscal.id_siccont02,
                                                   tmp_siccont11_balanza_fiscal.siccont02_tipo,
                                                   tmp_siccont11_balanza_fiscal.siccont02_codigo_ext,
                                                   tmp_siccont11_balanza_fiscal.siccont02_codagrup,
                                                   tmp_siccont11_balanza_fiscal.suma_debe,
                                                   tmp_siccont11_balanza_fiscal.suma_haber )
        select
        current_user,
        'DROPZONE-REEMBOLSO-CFDI',
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        siccont02_arb_planctas.id_siccont02,
        siccont02_arb_planctas.siccont02_tipo,
        siccont02_arb_planctas.siccont02_codigo_ext,
        siccont02_arb_planctas.siccont02_codagrup,
        siccont11_det_polizas.siccont11_debe,
        siccont11_det_polizas.siccont11_haber
        from siccont11_det_polizas
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10 )
        inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_xml;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA_FISCAL (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    SOCSYST06_NIVEL INTEGER,
    ID_SICCONT02 INTEGER,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SUMA_DEBE NUMERIC(18,4),
    SUMA_HABER NUMERIC(18,4),
    SALDO_FINAL NUMERIC(18,4),
    AFECTACION INTEGER)
AS
declare variable LIKE_CODIGO varchar(50);
declare variable CTA_FINAL bigint;
begin
    execute procedure prd_siccont11_balanza_fiqry :id_socmain01, :ano, :mes;

    DELETE FROM TMP_SICCONT11_BALANZA WHERE TMP_SICCONT11_BALANZA.tmpcont11_user = current_user;

    INSERT INTO tmp_siccont11_balanza
    SELECT
    current_user,
    qry_siccont11_balanza_fiscal.id_siccont02,
    qry_siccont11_balanza_fiscal.siccont02_tipo,
    qry_siccont11_balanza_fiscal.siccont02_codigo_ext,
    '',
    qry_siccont11_balanza_fiscal.suma_debe,
    qry_siccont11_balanza_fiscal.suma_haber,
    :ano,
    :mes,
    0,
    0
    FROM qry_siccont11_balanza_fiscal
    where qry_siccont11_balanza_fiscal.usuario = current_user;

    /* ------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------ */

    for select
    siccont02_arb_planctas.siccont02_codagrup,
    socsyst06_det_niveles.socsyst06_nivel,
    siccont02_arb_planctas.id_siccont02,
    siccont02_arb_planctas.siccont02_tipo,
    trim(siccont02_arb_planctas.siccont02_codigo_ext),
    siccont02_arb_planctas.siccont02_descripcion
    from siccont01_cab_planctas
    inner join siccont02_arb_planctas on (siccont02_arb_planctas.rela_siccont01 = siccont01_cab_planctas.id_siccont01)
    inner join socsyst06_det_niveles on (socsyst06_det_niveles.id_socsyst06 = siccont02_arb_planctas.rela_socsyst06)
    where siccont01_cab_planctas.rela_socmain01 = :id_socmain01
    order by siccont02_arb_planctas.siccont02_codigo_ext
    into :siccont02_codagrup,
         :socsyst06_nivel,
         :id_siccont02,
         :siccont02_tipo,
         :siccont02_codigo_ext,
         :siccont02_descripcion
    do
    begin
        suma_debe = null;
        suma_haber = null;
        saldo_final = 0;

        /* ============================================================================================================ */

        like_codigo = :siccont02_codigo_ext || '%';

        select
        sum(tmp_siccont11_balanza.suma_debe),
        sum(tmp_siccont11_balanza.suma_haber)
        from tmp_siccont11_balanza
        where tmp_siccont11_balanza.tmpcont11_user = current_user
        and tmp_siccont11_balanza.siccont02_codigo_ext like :like_codigo
        into :suma_debe,
             :suma_haber;

        if (suma_debe is null) then
            suma_debe = 0;

        if (suma_haber is null) then
            suma_haber = 0;

        if (siccont02_tipo = 'D') then
            saldo_final = :suma_debe - :suma_haber;
        else if (siccont02_tipo = 'H') then
            saldo_final = :suma_haber - :suma_debe;

        cta_final = null;

        select tmp_siccont11_balanza.rela_siccont02
        from tmp_siccont11_balanza
        where tmp_siccont11_balanza.tmpcont11_user = current_user
        and tmp_siccont11_balanza.rela_siccont02 = :id_siccont02
        into :cta_final;

        if (cta_final is not null) then
            afectacion = 1;
        else
            afectacion = 0;

        if ((suma_debe + suma_haber) <> 0) then
            suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA_RESULTADO (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER,
    CREA_TEMPORARIO INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST06_NIVEL INTEGER,
    CATALOGO_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_HISTORICO DOUBLE PRECISION,
    SALDO_ACTUAL DOUBLE PRECISION,
    SALDO_MES DOUBLE PRECISION)
AS
declare variable SALDO_INICIAL double precision;
declare variable TMP_RETO1 double precision;
declare variable TMP_RETO2 double precision;
begin
    if (crea_temporario = 1) then
        execute procedure prd_siccont11_balance :id_socmain01, :ano, :mes
        returning_values :tmp_reto1, :tmp_reto2;

     /* ======================================================================================================================= */

    for select
    TMP_SICCONT11_BALANZA_BALANCE.id_siccont02,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_tipo,
    TMP_SICCONT11_BALANZA_BALANCE.socsyst06_nivel,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_descripcion,
    TMP_SICCONT11_BALANZA_BALANCE.saldo_inicial,
    TMP_SICCONT11_BALANZA_BALANCE.saldo_final,
    TMP_SICCONT11_BALANZA_BALANCE.siccont02_codagrup
    from TMP_SICCONT11_BALANZA_BALANCE
    where TMP_SICCONT11_BALANZA_BALANCE.usuario = current_user
    and TMP_SICCONT11_BALANZA_BALANCE.actual = 1
    and (TMP_SICCONT11_BALANZA_BALANCE.socsyst06_nivel > 1
    and TMP_SICCONT11_BALANZA_BALANCE.socsyst06_nivel < 5)
    and (TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext > '4')
    into :id_siccont02,
         :siccont02_tipo,
         :socsyst06_nivel,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :saldo_inicial,
         :saldo_actual,
         :catalogo_sat
    do
    begin
        select
        TMP_SICCONT11_BALANZA_BALANCE.saldo_final
        from TMP_SICCONT11_BALANZA_BALANCE
        where TMP_SICCONT11_BALANZA_BALANCE.usuario = current_user
        and TMP_SICCONT11_BALANZA_BALANCE.actual = 0
        and TMP_SICCONT11_BALANZA_BALANCE.siccont02_codigo_ext = :siccont02_codigo_ext
        into :saldo_historico;

        if (saldo_historico is null) then
            saldo_historico = 0;

        if (socsyst06_nivel <> 4) then
        begin
            saldo_mes = null;
            saldo_actual = null;
            saldo_historico = null;
        end
        else
        begin
            saldo_mes = saldo_actual - saldo_inicial;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_BALANZA_XCUENTA (
    ID_SOCMAIN01 BIGINT,
    ID_SICCONT02X BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    ID_SICCONT02 INTEGER,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_INICIAL DOUBLE PRECISION,
    SUMA_DEBE DOUBLE PRECISION,
    SUMA_HABER DOUBLE PRECISION,
    SALDO_FINAL DOUBLE PRECISION,
    AFECTACION INTEGER)
AS
begin
    for select
    prd_siccont11_balanza.id_siccont02,
    prd_siccont11_balanza.siccont02_codigo_ext,
    prd_siccont11_balanza.siccont02_descripcion,
    prd_siccont11_balanza.siccont02_codagrup,
    prd_siccont11_balanza.siccont02_tipo,
    prd_siccont11_balanza.saldo_inicial,
    prd_siccont11_balanza.suma_debe,
    prd_siccont11_balanza.suma_haber,
    prd_siccont11_balanza.saldo_final,
    prd_siccont11_balanza.afectacion
    from prd_siccont11_balanza(:id_socmain01, :ano, :mes, 0)
    where prd_siccont11_balanza.id_siccont02 = :id_siccont02x
    into :id_siccont02,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_codagrup,
         :siccont02_tipo,
         :saldo_inicial,
         :suma_debe,
         :suma_haber,
         :saldo_final,
         afectacion
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_CIERRE (
    RELA_SOCMAIN01 BIGINT,
    ANO INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_DEBE DOUBLE PRECISION,
    SICCONT11_HABER DOUBLE PRECISION)
AS
declare variable SICCONT11_DEBE_SUM double precision;
declare variable SICCONT11_HABER_SUM double precision;
begin
    DELETE FROM TMP_SICCONT11_CIERRE WHERE TMP_SICCONT11_CIERRE.usuario = current_user;

    INSERT INTO TMP_SICCONT11_CIERRE( TMP_SICCONT11_CIERRE.usuario,
                                      TMP_SICCONT11_CIERRE.id_siccont02,
                                      TMP_SICCONT11_CIERRE.siccont02_codigo_ext,
                                      TMP_SICCONT11_CIERRE.siccont02_descripcion,
                                      TMP_SICCONT11_CIERRE.siccont11_debe,
                                      TMP_SICCONT11_CIERRE.siccont11_haber )
    SELECT
    current_user,
    prd_siccont11_cierre_view.id_siccont02,
    prd_siccont11_cierre_view.siccont02_codigo_ext,
    prd_siccont11_cierre_view.siccont02_descripcion,
    prd_siccont11_cierre_view.siccont11_debe,
    prd_siccont11_cierre_view.siccont11_haber
    FROM prd_siccont11_cierre_view(:rela_socmain01, :ano);

    select
    sum(TMP_SICCONT11_CIERRE.siccont11_debe),
    sum(TMP_SICCONT11_CIERRE.siccont11_haber)
    from TMP_SICCONT11_CIERRE
    where TMP_SICCONT11_CIERRE.usuario = current_user
    into :siccont11_debe_sum,
         :siccont11_haber_sum;

    if (siccont11_debe_sum > siccont11_haber_sum) then /* es Pérdida */
    begin
        SELECT
        sicxmls03_det_cuentas.rela_siccont02,
        siccont02_arb_planctas.siccont02_codigo_ext,
        siccont02_arb_planctas.siccont02_descripcion
        FROM sicxmls03_det_cuentas
        INNER JOIN sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls03_det_cuentas.rela_sicxmls01)
        INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        INNER JOIN siccont02_arb_planctas ON (siccont02_arb_planctas.id_siccont02 = sicxmls03_det_cuentas.rela_siccont02)
        WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
        AND socsyst10_det_entradas.socsyst10_codigo = 'CIERRE_PERDIDA'
        INTO :id_siccont02,
             :siccont02_codigo_ext,
             :siccont02_descripcion;

        siccont11_debe = 0;
        siccont11_haber = (siccont11_debe_sum - siccont11_haber_sum);

        suspend;
    end
    else if (siccont11_haber_sum > siccont11_debe_sum) then /* es Utilidad */
    begin
        SELECT
        sicxmls03_det_cuentas.rela_siccont02,
        siccont02_arb_planctas.siccont02_codigo_ext,
        siccont02_arb_planctas.siccont02_descripcion
        FROM sicxmls03_det_cuentas
        INNER JOIN sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls03_det_cuentas.rela_sicxmls01)
        INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        INNER JOIN siccont02_arb_planctas ON (siccont02_arb_planctas.id_siccont02 = sicxmls03_det_cuentas.rela_siccont02)
        WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
        AND socsyst10_det_entradas.socsyst10_codigo = 'CIERRE_UTILIDAD'
        INTO :id_siccont02,
             :siccont02_codigo_ext,
             :siccont02_descripcion;

        siccont11_debe = (siccont11_haber_sum - siccont11_debe_sum);
        siccont11_haber = 0;

        suspend;
    end

    for select
    TMP_SICCONT11_CIERRE.id_siccont02,
    TMP_SICCONT11_CIERRE.siccont02_codigo_ext,
    TMP_SICCONT11_CIERRE.siccont02_descripcion,
    TMP_SICCONT11_CIERRE.siccont11_debe,
    TMP_SICCONT11_CIERRE.siccont11_haber
    from TMP_SICCONT11_CIERRE
    where TMP_SICCONT11_CIERRE.usuario = current_user
    into :id_siccont02,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont11_debe,
         :siccont11_haber
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_CIERRE_POLIZA (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    ANO INTEGER)
RETURNS (
    ERROR VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCSYST10_CTP01 bigint;
declare variable RELA_SOCSYST10_CTP02 bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable ID_SICCONT10_NEW bigint;
declare variable ID_SICCONT02 bigint;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
begin
    select PRD_SICCONT11_CIERRE_VALIDA.error
    from PRD_SICCONT11_CIERRE_VALIDA(:rela_socmain01, :ano)
    into :error;

    if (error is not null) then
        suspend;
    else
    begin
        select cbo_socsyst10_ctp01.id_socsyst10
        from cbo_socsyst10_ctp01
        where cbo_socsyst10_ctp01.socsyst10_codigo = 'MANUAL'
        into :rela_socsyst10_ctp01;

        select cbo_socsyst10_ctp02.id_socsyst10
        from cbo_socsyst10_ctp02
        where cbo_socsyst10_ctp02.socsyst10_codigo = 'PO-6-FIN'
        into :rela_socsyst10_ctp02;

        select cbo_socsyst10_ctm01.id_socsyst10
        from cbo_socsyst10_ctm01
        where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
        into :rela_socsyst10_ctm01;

        insert into siccont10_cab_polizas(siccont10_cab_polizas.rela_socmain01,
                                          siccont10_cab_polizas.rela_socmain21,
                                          siccont10_cab_polizas.rela_socusua01,
                                          siccont10_cab_polizas.rela_socsyst10_ctp01,
                                          siccont10_cab_polizas.rela_socsyst10_ctp02,
                                          siccont10_cab_polizas.rela_socsyst10_ctm01,
                                          siccont10_cab_polizas.siccont10_tipo_entidad,
                                          siccont10_cab_polizas.siccont10_descripcion,
                                          siccont10_cab_polizas.siccont10_docnro,
                                          siccont10_cab_polizas.siccont10_fcta,
                                          siccont10_cab_polizas.siccont10_cotiza)
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :rela_socsyst10_ctp01,
                :rela_socsyst10_ctp02,
                :rela_socsyst10_ctm01,
                'S',
                'POLIZA DE CIERRE EJERCICIO : ' || :ano,
                'xxx',
                cast('31.12.' || :ano as DATE),
                1 );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        for select
        prd_siccont11_cierre.id_siccont02,
        prd_siccont11_cierre.siccont11_debe,
        prd_siccont11_cierre.siccont11_haber
        from prd_siccont11_cierre(:rela_socmain01, :ano)
        into :id_siccont02,
             :siccont11_debe,
             :siccont11_haber
        do
        begin
            if (siccont11_debe <> 0) then
                insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                                   siccont11_det_polizas.rela_siccont02,
                                                   siccont11_det_polizas.siccont11_tipo_entidad,
                                                   siccont11_det_polizas.siccont11_debe,
                                                   siccont11_det_polizas.siccont11_haber,
                                                   siccont11_det_polizas.siccont11_ano,
                                                   siccont11_det_polizas.siccont11_mes)
                values(:id_siccont10_new,
                       :id_siccont02,
                       'S',
                       0,
                       :siccont11_debe,
                       :ano,
                       12);

           if (siccont11_haber <> 0) then
                insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                                   siccont11_det_polizas.rela_siccont02,
                                                   siccont11_det_polizas.siccont11_tipo_entidad,
                                                   siccont11_det_polizas.siccont11_debe,
                                                   siccont11_det_polizas.siccont11_haber,
                                                   siccont11_det_polizas.siccont11_ano,
                                                   siccont11_det_polizas.siccont11_mes)
                values(:id_siccont10_new,
                       :id_siccont02,
                       'S',
                       :siccont11_haber,
                       0,
                       :ano,
                       12);
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_CIERRE_VALIDA (
    RELA_SOCMAIN01 BIGINT,
    ANO INTEGER)
RETURNS (
    ERROR VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICCONT10_EXISTE bigint;
declare variable ANO_MINIMO integer;
declare variable ANO_CALCULA integer;
declare variable ID_SICCONT02_CIERRE bigint;
begin
    SELECT sicxmls03_det_cuentas.rela_siccont02
    FROM sicxmls03_det_cuentas
    INNER JOIN sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls03_det_cuentas.rela_sicxmls01)
    INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    INNER JOIN siccont02_arb_planctas ON (siccont02_arb_planctas.id_siccont02 = sicxmls03_det_cuentas.rela_siccont02)
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    AND socsyst10_det_entradas.socsyst10_codigo = 'CIERRE_UTILIDAD'
    INTO :id_siccont02_cierre;

    if (id_siccont02_cierre is null) then
    begin
        error = 'Falta parametrizar Cuenta de Ciere por Utilidad';
        suspend;
    end
    else
    begin
        id_siccont02_cierre = null;

        SELECT sicxmls03_det_cuentas.rela_siccont02
        FROM sicxmls03_det_cuentas
        INNER JOIN sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls03_det_cuentas.rela_sicxmls01)
        INNER JOIN socsyst10_det_entradas ON (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        INNER JOIN siccont02_arb_planctas ON (siccont02_arb_planctas.id_siccont02 = sicxmls03_det_cuentas.rela_siccont02)
        WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
        AND socsyst10_det_entradas.socsyst10_codigo = 'CIERRE_PERDIDA'
        INTO :id_siccont02_cierre;

        if (id_siccont02_cierre is null) then
        begin
            error = 'Falta parametrizar Cuenta de Ciere por Pérdida';
            suspend;
        end
    end

    if (id_siccont02_cierre is not null) then
    begin
        select first 1 min(Extract(year FROM siccont10_cab_polizas.siccont10_fcta))
        from siccont10_cab_polizas
        where siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
        into :ano_minimo;

        id_siccont10_existe = null;

        select first 1 siccont10_cab_polizas.id_siccont10
        from siccont10_cab_polizas
        inner join socsyst10_det_entradas ctp01 on (ctp01.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
        inner join socsyst10_det_entradas ctp02 on (ctp02.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp02)
        where siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
        and Extract(year FROM siccont10_cab_polizas.siccont10_fcta) = :ano
        and ctp01.socsyst10_codigo = 'MANUAL'
        and ctp02.socsyst10_codigo = 'PO-6-FIN'
        into :id_siccont10_existe;

        if (id_siccont10_existe is not null) then
        begin
            error = 'Poliza de Cierre ya Generada';
            suspend;
        end
        else
        begin
            ano_calcula = ano + 1;
    
            select first 1 siccont10_cab_polizas.id_siccont10
            from siccont10_cab_polizas
            inner join socsyst10_det_entradas ctp01 on (ctp01.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
            inner join socsyst10_det_entradas ctp02 on (ctp02.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp02)
            where siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
            and Extract(year FROM siccont10_cab_polizas.siccont10_fcta) = :ano_calcula
            and ctp01.socsyst10_codigo = 'MANUAL'
            and ctp02.socsyst10_codigo = 'PO-6-FIN'
            into :id_siccont10_existe;
    
            if (id_siccont10_existe is not null) then
            begin
                error = 'Poliza de Cierre Generada Año Posterior ' || :ano_calcula;
                suspend;
            end 
            else
            begin
                ano_calcula = ano - 1;
    
                if (ano_calcula >= ano_minimo) then
                begin
                    select first 1 siccont10_cab_polizas.id_siccont10
                    from siccont10_cab_polizas
                    inner join socsyst10_det_entradas ctp01 on (ctp01.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
                    inner join socsyst10_det_entradas ctp02 on (ctp02.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp02)
                    where siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
                    and Extract(year FROM siccont10_cab_polizas.siccont10_fcta) = :ano_calcula
                    and ctp01.socsyst10_codigo = 'MANUAL'
                    and ctp02.socsyst10_codigo = 'PO-6-FIN'
                    into :id_siccont10_existe;    
    
                    if (id_siccont10_existe is null) then
                    begin
                        error = 'No Existe una Póliza de Cierre Año Anterior ' || :ano_calcula;
                        suspend;    
                    end
                end
            end
        end 
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_CIERRE_VIEW (
    RELA_SOCMAIN01 BIGINT,
    ANO INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_DEBE DOUBLE PRECISION,
    SICCONT11_HABER DOUBLE PRECISION)
AS
begin
    FOR SELECT
    siccont11_det_polizas.rela_siccont02,
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    sum(siccont11_det_polizas.siccont11_debe),
    sum(siccont11_det_polizas.siccont11_haber)
    FROM siccont11_det_polizas
    INNER JOIN siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02)
    INNER JOIN siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10)
    where siccont10_cab_polizas.rela_socmain01 = :rela_socmain01
    and siccont11_det_polizas.siccont11_ano = :ano
    and (siccont02_arb_planctas.siccont02_codigo_ext like '4%' OR
         siccont02_arb_planctas.siccont02_codigo_ext like '5%' OR
         siccont02_arb_planctas.siccont02_codigo_ext like '6%' OR
         siccont02_arb_planctas.siccont02_codigo_ext like '7%')
    group by siccont11_det_polizas.rela_siccont02,
             siccont02_arb_planctas.siccont02_codigo_ext,
             siccont02_arb_planctas.siccont02_descripcion
    order by siccont02_arb_planctas.siccont02_codigo_ext
    into :id_siccont02,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont11_debe,
         :siccont11_haber
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_DIOT (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    ID_SOCUSUA30 BIGINT,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_PROVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_OPERACION VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IVA_BASE DOUBLE PRECISION,
    IVA_BASE_8 DOUBLE PRECISION,
    IVA_EXENTO DOUBLE PRECISION,
    IVA_CERO DOUBLE PRECISION,
    IVA_RETENIDO DOUBLE PRECISION,
    IVA_CREDITO DOUBLE PRECISION)
AS
declare variable FECHA_DESDE varchar(50);
declare variable FECHA_HASTA varchar(50);
declare variable DIAS integer;
declare variable ID_SICXMLS40_FIND bigint;
begin
    tipo_prove = '04';
    tipo_operacion = '85';
    
    select SMX$UTIL_FECHA_MAX_DIA.dias
    from SMX$UTIL_FECHA_MAX_DIA(:mes, :ano)
    into :dias;
    
    fecha_desde = :mes || '/01/' || :ano;
    fecha_hasta = :mes || '/' || :dias || '/' || :ano;

    for Select
    max(GRD_SICXMLS41_IMPUESTOS.rela_socusua30),
    max(GRD_SICXMLS41_IMPUESTOS.sicxmls41_entidad),
    GRD_SICXMLS41_IMPUESTOS.sicxmls41_rfc,
    sum(GRD_SICXMLS41_IMPUESTOS.base_imponible),
    sum(GRD_SICXMLS41_IMPUESTOS.base_imponible8),
    sum(GRD_SICXMLS41_IMPUESTOS.iva_exento),
    sum(GRD_SICXMLS41_IMPUESTOS.iva_cero),
    sum(GRD_SICXMLS41_IMPUESTOS.iva_rete + GRD_SICXMLS41_IMPUESTOS.iva_rete8)
    from GRD_SICXMLS41_IMPUESTOS(:id_socmain01, 5, :fecha_desde, :fecha_hasta)
    group by GRD_SICXMLS41_IMPUESTOS.sicxmls41_rfc
    into :id_socusua30,
         :entidad,
         :rfc,
         :iva_base,
         :iva_base_8,
         :iva_exento,
         :iva_cero,
         :iva_retenido
    do
    begin
        id_sicxmls40_find = null;
        iva_credito = null;

        select first 1 sicxmls40_cab_migracion.id_sicxmls40
        from sicxmls40_cab_migracion
        inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
        inner join socsyst10_det_entradas tct01 on ( tct01.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01 )
        where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
        and sicxmls41_det_migracion.rela_socusua30 = :id_socusua30
        and (tct01.socsyst10_codigo = 'CREADITOAFAVOR' or tct01.socsyst10_codigo = 'CREADITOAFAVORX')
        into :id_sicxmls40_find;

        if (id_sicxmls40_find is not null) then
            select sum(sicxmls43_det_impuestos.sicxmls43_importe)
            from sicxmls41_det_migracion
            inner join sicxmls40_cab_migracion on ( sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40 )
            inner join socsyst10_det_entradas tct01 on ( tct01.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01 )
            inner join sicxmls43_det_impuestos on ( sicxmls43_det_impuestos.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
            where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
            and sicxmls41_det_migracion.rela_socusua30 = :id_socusua30
            and (tct01.socsyst10_codigo = 'CREADITOAFAVOR' or tct01.socsyst10_codigo = 'CREADITOAFAVORX')
            and sicxmls41_det_migracion.sicxmls41_uuid_fecha between :fecha_desde and :fecha_hasta
            into :iva_credito;

        iva_credito = iif(iva_credito is null, 0, iva_credito);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT11_RESULTADO_TOTALES
RETURNS (
    ID_TMPSICONT99 BIGINT,
    INGRESOS DOUBLE PRECISION,
    INGRESOS_INI DOUBLE PRECISION,
    INGRESOS_MES DOUBLE PRECISION,
    EGRESOS_COSTOS_COMPRAS DOUBLE PRECISION,
    EGRESOS_COSTOS_COMPRAS_INI DOUBLE PRECISION,
    EGRESOS_COSTOS_COMPRAS_MES DOUBLE PRECISION,
    EGRESOS_GASTOS_OPERATIVOS DOUBLE PRECISION,
    EGRESOS_GASTOS_OPERATIVOS_INI DOUBLE PRECISION,
    EGRESOS_GASTOS_OPERATIVOS_MES DOUBLE PRECISION,
    EGRESOS_GASTOS_NOOPERATIVOS DOUBLE PRECISION,
    EGRESOS_GASTOS_NOOPERATIVOS_INI DOUBLE PRECISION,
    EGRESOS_GASTOS_NOOPERATIVOS_MES DOUBLE PRECISION,
    EGRESO_INI DOUBLE PRECISION,
    EGRESO_MES DOUBLE PRECISION,
    INGRESOS_TOTAL DOUBLE PRECISION,
    EGRESOS_TOTAL DOUBLE PRECISION,
    UTILIDAD DOUBLE PRECISION,
    UTILIDAD_INICIAL DOUBLE PRECISION,
    UTILIDAD_MES DOUBLE PRECISION)
AS
declare variable INGRESOS_TOTAL_TMP double precision;
declare variable EGRESOS_TOTAL_TMP double precision;
begin
    id_tmpsicont99 = 1;

    select
    sum(tmp_siccont11_resultado.saldo_actual),
    sum(tmp_siccont11_resultado.saldo_historico),
    sum(tmp_siccont11_resultado.saldo_mes)
    from tmp_siccont11_resultado
    where tmp_siccont11_resultado.usuario = current_user
    and tmp_siccont11_resultado.siccont02_codigo_ext like '4%'
    into :ingresos,
         :ingresos_ini,
         :ingresos_mes;

    select
    sum(tmp_siccont11_resultado.saldo_actual),
    sum(tmp_siccont11_resultado.saldo_historico),
    sum(tmp_siccont11_resultado.saldo_mes)
    from tmp_siccont11_resultado
    where tmp_siccont11_resultado.usuario = current_user
    and tmp_siccont11_resultado.siccont02_codigo_ext like '5%'
    into :egresos_costos_compras,
         :egresos_costos_compras_ini,
         :egresos_costos_compras_mes;

    select
    sum(tmp_siccont11_resultado.saldo_actual),
    sum(tmp_siccont11_resultado.saldo_historico),
    sum(tmp_siccont11_resultado.saldo_mes)
    from tmp_siccont11_resultado
    where tmp_siccont11_resultado.usuario = current_user
    and tmp_siccont11_resultado.siccont02_codigo_ext like '6%'
    into :egresos_gastos_operativos,
         :egresos_gastos_operativos_ini,
         :egresos_gastos_operativos_mes;

    select
    sum(tmp_siccont11_resultado.saldo_actual),
    sum(tmp_siccont11_resultado.saldo_historico),
    sum(tmp_siccont11_resultado.saldo_mes)
    from tmp_siccont11_resultado
    where tmp_siccont11_resultado.usuario = current_user
    and tmp_siccont11_resultado.siccont02_codigo_ext like '7%'
    into :egresos_gastos_nooperativos,
         :egresos_gastos_nooperativos_ini,
         :egresos_gastos_nooperativos_mes;

    ingresos_total = ingresos;
    egresos_total = egresos_costos_compras + egresos_gastos_operativos + egresos_gastos_nooperativos;
    utilidad = ingresos_total - egresos_total;

    egreso_ini = egresos_costos_compras_ini + egresos_gastos_operativos_ini + egresos_gastos_nooperativos_ini;
    egreso_mes = egresos_costos_compras_mes + egresos_gastos_operativos_mes + egresos_gastos_nooperativos_mes;

    ingresos_total_tmp = ingresos_ini;
    egresos_total_tmp = egresos_costos_compras_ini + egresos_gastos_operativos_ini + egresos_gastos_nooperativos_ini;
    utilidad_inicial = ingresos_total_tmp - egresos_total_tmp;

    ingresos_total_tmp = ingresos_mes;
    egresos_total_tmp = egresos_costos_compras_mes + egresos_gastos_operativos_mes + egresos_gastos_nooperativos_mes;
    utilidad_mes = ingresos_total_tmp - egresos_total_tmp;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT50_ANOMES (
    ID_SOCMAIN05 BIGINT)
RETURNS (
    ANOMES INTEGER)
AS
declare variable CANOMES varchar(50);
begin
    SELECT
    max( cast(siccont50_cab_bancos.siccont50_ano as integer) ||
    iif( char_length((cast(siccont50_cab_bancos.siccont50_mes as integer))) = 1,
         '0' || cast(siccont50_cab_bancos.siccont50_mes as integer),
         cast(siccont50_cab_bancos.siccont50_mes as integer)) )
    FROM siccont50_cab_bancos
    where siccont50_cab_bancos.rela_socmain05 = :id_socmain05
    into :canomes;

    if (canomes is null) then
        anomes = CAST('201001' AS INTEGER);
    else
        anomes = cast(canomes as integer);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT50_CREAPOLIZAS (
    ID BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    ID_SOCMAIN05 BIGINT,
    AJUSTE DOUBLE PRECISION,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    ID_SICCONT10 BIGINT)
AS
declare variable RELA_SICCONT02_BANCO bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable RELA_SOCSYST10_CTP01 bigint;
declare variable RELA_SOCSYST10_CTP02 bigint;
declare variable FECHA date;
declare variable RELA_SICCONT02_AJUSTE_E bigint;
declare variable RELA_SICCONT02_AJUSTE_I bigint;
declare variable CONCEPTO varchar(400);
begin
    select
    SOCMAIN05_DET_BANCOS.rela_siccont02,
    SOCMAIN05_DET_BANCOS.rela_socsyst10_ctm01
    from SOCMAIN05_DET_BANCOS
    where SOCMAIN05_DET_BANCOS.id_socmain05 = :id_socmain05
    into :rela_siccont02_banco,
         :rela_socsyst10_ctm01;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls03_det_cuentas.rela_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'AJUSTEE'
    into :rela_siccont02_ajuste_e;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls03_det_cuentas.rela_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'AJUSTEI'
    into :rela_siccont02_ajuste_i;

    select
    CBO_SOCSYST10_CTP01.id_socsyst10
    FROM CBO_SOCSYST10_CTP01
    WHERE CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-BANCOS-AJUSTE'
    INTO :rela_socsyst10_ctp01;

    select
    CBO_SOCSYST10_CTP02.id_socsyst10
    FROM CBO_SOCSYST10_CTP02
    WHERE CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-3-DIA'
    INTO :rela_socsyst10_ctp02;

    fecha = cast(mes || '/1/' || ano as date);

    if (ajuste > 0) then
        concepto = 'CONCILIACION BANCARIA SALDO A FAVOR # ' || :id || ' Año: ' || :ano || ' Mes: ' || :mes;
    else
        concepto = 'CONCILIACION BANCARIA SALDO NEGATIVO # ' || :id || ' Año: ' || :ano || ' Mes: ' || :mes;

    insert into siccont10_cab_polizas(siccont10_cab_polizas.rela_socmain01,
                                      siccont10_cab_polizas.rela_socmain21,
                                      siccont10_cab_polizas.rela_socusua01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp02,
                                      siccont10_cab_polizas.rela_socsyst10_ctm01,
                                      siccont10_cab_polizas.siccont10_tipo_entidad,
                                      siccont10_cab_polizas.siccont10_descripcion,
                                      siccont10_cab_polizas.siccont10_fcta,
                                      siccont10_cab_polizas.siccont10_cotiza)

    values(:rela_socmain01,
           :rela_socmain21,
           :rela_socusua01,
           :rela_socsyst10_ctp01,
           :rela_socsyst10_ctp02,
           :rela_socsyst10_ctm01,
           'S',
           :concepto,
           :fecha,
           1);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :id_siccont10;

    if (ajuste > 0) then
    begin
        insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

        values(:id_siccont10,
            :rela_siccont02_banco,
            'S',
            :ajuste,                            /* cargo */
            0,                                  /* abono */
            :ano,
            :mes);

       insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

        values(:id_siccont10,
            :rela_siccont02_ajuste_e,
            'S',
            0,                                  /* cargo */
            :ajuste,                            /* abono */
            :ano,
            :mes);
    end
    else
    begin
        insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

        values(:id_siccont10,
            :rela_siccont02_banco,
            'S',
            0,                                  /* cargo */
            :ajuste*(-1),                       /* abono */
            :ano,
            :mes);

       insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

        values(:id_siccont10,
            :rela_siccont02_ajuste_i,
            'S',
            :ajuste*(-1),                       /* cargo */
            0,                                  /* abono */
            :ano,
            :mes);
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT51 (
    ID_SOCMAIN05 BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    MARCA INTEGER,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICCONT10 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SUMA_DEBE DOUBLE PRECISION,
    SUMA_HABER DOUBLE PRECISION,
    IMPORTE DOUBLE PRECISION,
    IMPORTE_XCONCILIAR DOUBLE PRECISION)
AS
declare variable RELA_SICCONT02_BANCO bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable SICCONT10_TIPO_ENTIDAD varchar(1);
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SICCONT02_BANCO_TRANSPASO bigint;
declare variable CAD_ANOMES varchar(50);
begin
    MARCA = 1;
    importe_xconciliar = 0;

    ano = iif(ano = -1, 0, ano);
    mes = iif(mes = -1, 0, mes);

    cad_anomes = cast(:ano as varchar(4));
    cad_anomes = cad_anomes || iif(:mes < 10, '0' || cast(:mes as varchar(1)), cast(:mes as varchar(2)));

    select
    SOCMAIN05_DET_BANCOS.rela_socmain01,
    SOCMAIN05_DET_BANCOS.rela_siccont02
    from SOCMAIN05_DET_BANCOS
    where SOCMAIN05_DET_BANCOS.id_socmain05 = :id_socmain05
    into :rela_socmain01, :rela_siccont02_banco;

    for select
    siccont10_cab_polizas.rela_socusua30,
    siccont10_cab_polizas.siccont10_tipo_entidad,
    siccont10_cab_polizas.siccont10_descripcion,   --HV
    socsyst10_det_entradas.socsyst10_descripcion,
    siccont10_cab_polizas.id_siccont10,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    sum(siccont11_det_polizas.siccont11_debe),
    sum(siccont11_det_polizas.siccont11_haber)
    from siccont10_cab_polizas
    inner join siccont11_det_polizas on (siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    where (siccont11_det_polizas.rela_siccont02 = :rela_siccont02_banco
    and socsyst10_det_entradas.socsyst10_codigo <> 'DROPZONE-BANCOS-AJUSTE')
    and (cast(siccont11_det_polizas.siccont11_ano as varchar(4)) ||
        iif(siccont11_det_polizas.siccont11_mes < 10,
            '0' || cast(siccont11_det_polizas.siccont11_mes as varchar(1)),
            cast(siccont11_det_polizas.siccont11_mes as varchar(2)))) <= :cad_anomes


    and not exists ( Select first 1 siccont51_det_bancos.id_siccont51
                     from siccont51_det_bancos
                     where siccont51_det_bancos.rela_siccont10 = siccont10_cab_polizas.id_siccont10
                   )
    group by
    siccont10_cab_polizas.rela_socusua30,
    siccont10_cab_polizas.siccont10_descripcion,
    socsyst10_det_entradas.socsyst10_descripcion,
    siccont10_cab_polizas.id_siccont10,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    siccont10_cab_polizas.siccont10_tipo_entidad
    into :rela_socusua30,
         :siccont10_tipo_entidad,
         :siccont10_descripcion,
         :socsyst10_descripcion,
         :id_siccont10,
         :siccont10_docnro,
         :siccont10_fcta,
         :suma_debe,
         :suma_haber
    do
    begin



        importe = suma_debe - suma_haber;
        importe_xconciliar = importe;
        entidad = '';

        if (siccont10_tipo_entidad = 'P') then
            select cbo_sicegre01.entidad
            from cbo_sicegre01
            where cbo_sicegre01.rela_socmain01 = :rela_socmain01
            and cbo_sicegre01.id_socusua30 = :rela_socusua30

            into :entidad;
        else if (siccont10_tipo_entidad = 'C') then
            select cbo_sicingr01.entidad
            from cbo_sicingr01
            where cbo_sicingr01.rela_socmain01 = :rela_socmain01
            and cbo_sicingr01.id_socusua30 = :rela_socusua30
            into :entidad;
        else if (siccont10_tipo_entidad = 'E') then
            select cbo_sicnomi01.entidad
            from cbo_sicnomi01
            where cbo_sicnomi01.rela_sicnomi01 = :rela_socmain01
            and cbo_sicnomi01.id_socusua30 = :rela_socusua30
            into :entidad;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT51_ACUMULADO (
    ID_SOCMAIN05 BIGINT)
RETURNS (
    IMPORTE_ACUMULADO DOUBLE PRECISION)
AS
declare variable ID_SICCONT50_MAX bigint;
begin
    importe_acumulado = 0;

    select
    max(siccont50_cab_bancos.id_siccont50)
    from siccont50_cab_bancos
    where siccont50_cab_bancos.rela_socmain05 = :id_socmain05
    into :id_siccont50_max;

    select
    siccont50_cab_bancos.siccont50_saldo_banco
    from siccont50_cab_bancos
    where siccont50_cab_bancos.id_siccont50 = :id_siccont50_max
    into :importe_acumulado;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICCONT51_VIEW (
    ID_SICCONT50 BIGINT)
RETURNS (
    MARCA INTEGER,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICCONT10 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SUMA_DEBE DOUBLE PRECISION,
    SUMA_HABER DOUBLE PRECISION,
    IMPORTE DOUBLE PRECISION,
    IMPORTE_XCONCILIAR DOUBLE PRECISION)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable SICCONT10_TIPO_ENTIDAD varchar(1);
declare variable RELA_SOCMAIN01 bigint;
begin
    MARCA = 1;
    importe_xconciliar = 0;

    for select
    siccont10_cab_polizas.rela_socmain01,
    siccont10_cab_polizas.rela_socusua30,
    siccont10_cab_polizas.siccont10_tipo_entidad,
    siccont10_cab_polizas.siccont10_descripcion, --HV
    socsyst10_det_entradas.socsyst10_descripcion,
    siccont10_cab_polizas.id_siccont10,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta,
    siccont51_det_bancos.siccont51_importe,
    siccont51_det_bancos.siccont51_debe,
    siccont51_det_bancos.siccont51_haber
    from socsyst10_det_entradas
    inner join siccont10_cab_polizas on (socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01)
    inner join siccont51_det_bancos on (siccont10_cab_polizas.id_siccont10 = siccont51_det_bancos.rela_siccont10)
    where siccont51_det_bancos.rela_siccont50 = :id_siccont50
    into :rela_socmain01,
         :rela_socusua30,
         :siccont10_tipo_entidad,
         :siccont10_descripcion,
         :socsyst10_descripcion,
         :id_siccont10,
         :siccont10_docnro,
         :siccont10_fcta,
         :IMPORTE,
         :suma_debe,
         :suma_haber
    do
    begin
        importe_xconciliar = importe;
        entidad = '';

        if (siccont10_tipo_entidad = 'P') then
            select cbo_sicegre01.entidad
            from cbo_sicegre01
            where cbo_sicegre01.rela_socmain01 = :rela_socmain01
            and cbo_sicegre01.id_socusua30 = :rela_socusua30

            into :entidad;
        else if (siccont10_tipo_entidad = 'C') then
            select cbo_sicingr01.entidad
            from cbo_sicingr01
            where cbo_sicingr01.rela_socmain01 = :rela_socmain01
            and cbo_sicingr01.id_socusua30 = :rela_socusua30
            into :entidad;
        else if (siccont10_tipo_entidad = 'E') then
            select cbo_sicnomi01.entidad
            from cbo_sicnomi01
            where cbo_sicnomi01.rela_sicnomi01 = :rela_socmain01
            and cbo_sicnomi01.id_socusua30 = :rela_socusua30
            into :entidad;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE50_ANTICIPO (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICEGRE01 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    COTIZA DOUBLE PRECISION,
    FECHA DATE)
RETURNS (
    OK INTEGER)
AS
declare variable RELA_SOCSYST10_CTP01 bigint;
declare variable RELA_SOCSYST10_CTP02 bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable RELA_SICCONT02_DEBE bigint;
declare variable RELA_SICCONT02_HABER bigint;
declare variable ID_SOCUSUA30 bigint;
declare variable ID_SICCONT10 bigint;
begin
    select cbo_socsyst10_ctp01.id_socsyst10
    from cbo_socsyst10_ctp01
    where cbo_socsyst10_ctp01.socsyst10_codigo = 'DROPZONE-ANTI'
    into :rela_socsyst10_ctp01;

    select cbo_socsyst10_ctp02.id_socsyst10
    from cbo_socsyst10_ctp02
    where cbo_socsyst10_ctp02.socsyst10_codigo = 'PO-2-EGR'
    into :rela_socsyst10_ctp02;

    select cbo_sicegre01.id_socusua30
    from cbo_sicegre01
    where cbo_sicegre01.rela_sicegre01 = :rela_sicegre01
    into :id_socusua30;

    select
    socmain05_det_bancos.rela_siccont02,
    socmain05_det_bancos.rela_socsyst10_ctm01
    from socmain05_det_bancos
    where socmain05_det_bancos.id_socmain05 = :rela_socmain05
    into :rela_siccont02_haber,
         :rela_socsyst10_ctm01;

    select SICXMLS03_DET_CUENTAS.rela_siccont02
    from sicxmls01_cab_parametros
    inner join SICXMLS03_DET_CUENTAS on (SICXMLS03_DET_CUENTAS.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICXMLS03_DET_CUENTAS.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'PROVE-ANTIC'
    into :rela_siccont02_debe;

    INSERT INTO siccont10_cab_polizas(siccont10_cab_polizas.rela_socmain01,
                                      siccont10_cab_polizas.rela_socmain21,
                                      siccont10_cab_polizas.rela_socusua01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp02,
                                      siccont10_cab_polizas.rela_socsyst10_ctm01,
                                      siccont10_cab_polizas.rela_socusua30,
                                      siccont10_cab_polizas.siccont10_tipo_entidad,
                                      siccont10_cab_polizas.siccont10_descripcion,
                                      siccont10_cab_polizas.siccont10_docnro,
                                      siccont10_cab_polizas.siccont10_fcta,
                                      siccont10_cab_polizas.siccont10_cotiza)
    VALUES(:rela_socmain01,
           :rela_socmain21,
           :rela_socusua01,
           :rela_socsyst10_ctp01,
           :rela_socsyst10_ctp02,
           :rela_socsyst10_ctm01,
           :id_socusua30,
           'P',
           :CONCEPTO,
           'XXXX',
           :fecha,
           :cotiza);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :ID_SICCONT10;

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)
    values(:id_siccont10,
           :rela_siccont02_debe,
           'S',
           '',
           :importe,
           0,
           -1,
           -1);

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)
    values(:id_siccont10,
           :rela_siccont02_haber,
           'S',
           '',
           0,
           :importe,
           -1,
           -1);

     insert into sicegre50_det_ctacte(sicegre50_det_ctacte.rela_sicegre01,
                                      sicegre50_det_ctacte.rela_socmain01,
                                      sicegre50_det_ctacte.rela_siccont10,
                                      sicegre50_det_ctacte.sicegre50_importe)
     values(:rela_sicegre01,
            :rela_socmain01,
            :id_siccont10,
            :importe * (-1));


    ok = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE50_CREDITO (
    ID_SICEGRE50 BIGINT,
    ID_SICCONT10 BIGINT)
RETURNS (
    ID_SICEGRE51 BIGINT,
    FECHA DATE,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    POLIZA_FECHA DATE,
    IMPORTE DOUBLE PRECISION)
AS
begin
    for select SICEGRE52_DET_BANCOS.rela_sicegre51
    from SICEGRE52_DET_BANCOS
    inner join sicegre50_det_ctacte on ( sicegre50_det_ctacte.id_sicegre50 = SICEGRE52_DET_BANCOS.rela_sicegre50 )
    where SICEGRE52_DET_BANCOS.rela_sicegre50 = :id_sicegre50
    and sicegre50_det_ctacte.rela_siccont10 = :id_siccont10
    into :id_sicegre51
    do
    begin
        for select
        sicegre51_cab_bancos.id_sicegre51,
        sicegre51_cab_bancos.sicegre51_fecha,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        sicegre52_det_bancos.sicegre52_importe
        from sicegre52_det_bancos
        inner join sicegre51_cab_bancos on ( sicegre51_cab_bancos.id_sicegre51 = sicegre52_det_bancos.rela_sicegre51 )
        inner join sicegre50_det_ctacte on ( sicegre50_det_ctacte.id_sicegre50 = sicegre52_det_bancos.rela_sicegre50 )
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10 )
        where sicegre52_det_bancos.rela_sicegre51 = :id_sicegre51
        into :id_sicegre51,
             :fecha,
             :poliza,
             :poliza_fecha,
             :importe
       do
       begin
          suspend;
       end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE51_CREAPOLIZAS
RETURNS (
    OK INTEGER)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SICCONT10_NEW bigint;
declare variable ID_SICCONT10_OLD bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable PORCENTAJE double precision;
declare variable RELA_SICCONT02 bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable RELA_SICCONT02_BANCO bigint;
declare variable RELA_SICCONT02_PROVE bigint;
declare variable PM_RELA_SOCMAIN01 bigint;
declare variable PM_RELA_SOCMAIN21 bigint;
declare variable PM_RELA_SOCUSUA01 bigint;
declare variable PM_RELA_SICEGRE01 bigint;
declare variable PM_RELA_SOCMAIN05 bigint;
declare variable PM_ID_SICEGRE51 bigint;
declare variable PM_SICEGRE51_REFERENCIA varchar(400);
declare variable PM_SICEGRE51_FECHA date;
declare variable PM_SICEGRE51_COTIZA double precision;
declare variable PM_SICEGRE51_IMPORTE double precision;
declare variable PM_SICEGRE51_MONNAC bigint;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
declare variable RELA_SICCONT02_ANTICIPO bigint;
declare variable SICEGRE50_IMPORTE_ANTICIPO double precision;
declare variable SICCONT10_UUID_SAT varchar(50);
declare variable SICEGRE52_IMPORTE double precision;
begin
    ok = 0;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICEGRE51'
    INTO :pm_id_sicegre51;

    Select
    sicegre51_cab_bancos.rela_socmain01,
    sicegre51_cab_bancos.rela_socmain21,
    sicegre51_cab_bancos.rela_socusua01,
    sicegre51_cab_bancos.rela_sicegre01,
    sicegre51_cab_bancos.rela_socmain05,
    sicegre51_cab_bancos.sicegre51_referencia,
    sicegre51_cab_bancos.sicegre51_fecha,
    sicegre51_cab_bancos.sicegre51_cotiza,
    sicegre51_cab_bancos.sicegre51_importe,
    sicegre51_cab_bancos.sicegre51_monnac
    from sicegre51_cab_bancos
    where sicegre51_cab_bancos.id_sicegre51 = :pm_id_sicegre51
    into :pm_rela_socmain01,
         :pm_rela_socmain21,
         :pm_rela_socusua01,
         :pm_rela_sicegre01,
         :pm_rela_socmain05,
         :pm_sicegre51_referencia,
         :pm_sicegre51_fecha,
         :pm_sicegre51_cotiza,
         :pm_sicegre51_importe,
         :pm_sicegre51_monnac;

    pm_sicegre51_cotiza = iif(pm_sicegre51_cotiza is null, 1, :pm_sicegre51_cotiza);
    pm_sicegre51_importe = iif(:pm_sicegre51_importe is null, 0, :pm_sicegre51_importe);
    pm_sicegre51_monnac = iif(:pm_sicegre51_monnac is null, 0, :pm_sicegre51_monnac);

    select
    sum(sicegre50_det_ctacte.sicegre50_importe)
    from sicegre52_det_bancos
    inner join sicegre50_det_ctacte on (sicegre52_det_bancos.rela_sicegre50 = sicegre50_det_ctacte.id_sicegre50)
    inner join siccont10_cab_polizas on (sicegre50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
    inner join socsyst10_det_entradas on (siccont10_cab_polizas.rela_socsyst10_ctp01 = socsyst10_det_entradas.id_socsyst10)
    where sicegre52_det_bancos.rela_sicegre51 = :pm_id_sicegre51
    and socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-ANTI'
    into :sicegre50_importe_anticipo;

    if (sicegre50_importe_anticipo IS NULL) then
        sicegre50_importe_anticipo = 0;
    else
        sicegre50_importe_anticipo = sicegre50_importe_anticipo * (-1);

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if ((pm_sicegre51_importe <> 0) or (sicegre50_importe_anticipo <> 0))then
    begin
        select sicegre01_cab_proveedores.rela_socusua30
        from sicegre01_cab_proveedores
        where sicegre01_cab_proveedores.id_sicegre01 = :pm_rela_sicegre01
        into :rela_socusua30;

        select CBO_SOCSYST10_CTP01.id_socsyst10
        from CBO_SOCSYST10_CTP01
        where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-BANCOS'
        into :id_socsyst10_ctp01;

        select CBO_SOCSYST10_CTP02.id_socsyst10
        from CBO_SOCSYST10_CTP02
        where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-2-EGR'
        into :id_socsyst10_ctp02;

        select socmain05_det_bancos.rela_siccont02,
        socmain05_det_bancos.rela_socsyst10_ctm01
        from socmain05_det_bancos
        where socmain05_det_bancos.id_socmain05 = :pm_rela_socmain05
        into :rela_siccont02_banco,
             :id_socsyst10_ctm01;

        select sicxmls01_cab_parametros.id_sicxmls01
        from sicxmls01_cab_parametros
        where sicxmls01_cab_parametros.rela_socmain01 = :pm_rela_socmain01
        into :id_sicxmls01;

        select sicxmls03_det_cuentas.rela_siccont02
        from sicxmls03_det_cuentas
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
        and socsyst10_det_entradas.socsyst10_codigo = 'PROVE'
        into :rela_siccont02_prove;    

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* aqui debo ver despues, para proveedor extranjero, tengo que saber como tomar si es o no proveedor extranjero */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                          SICCONT10_CAB_POLIZAS.rela_socmain21,
                                          SICCONT10_CAB_POLIZAS.rela_socusua01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                          SICCONT10_CAB_POLIZAS.rela_socusua30,
                                          SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                          SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                          SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                          SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                          SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :pm_rela_socmain01,
                :pm_rela_socmain21,
                :pm_rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                :rela_socusua30,
                'P',
                :pm_sicegre51_referencia,
                'xxxx',
                :pm_sicegre51_fecha,
                :pm_sicegre51_cotiza);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */
        
        if (sicegre50_importe_anticipo <> 0) then
        begin
            select sicxmls03_det_cuentas.rela_siccont02
            from sicxmls03_det_cuentas
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
            where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
            and socsyst10_det_entradas.socsyst10_codigo = 'PROVE-ANTIC'
            into :rela_siccont02_anticipo;

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                               siccont11_det_polizas.rela_siccont02,
                                               siccont11_det_polizas.siccont11_tipo_entidad,
                                               siccont11_det_polizas.siccont11_debe,
                                               siccont11_det_polizas.siccont11_haber,
                                               siccont11_det_polizas.siccont11_ano,
                                               siccont11_det_polizas.siccont11_mes,
                                               siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_prove,
                   'S',
                   :sicegre50_importe_anticipo,
                   0,
                   -1,
                   -1,
                   1);

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes,
                                              siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_anticipo,
                   'S',
                   0,
                   :sicegre50_importe_anticipo,
                   -1,
                   -1,
                   1);

            pm_sicegre51_importe = sicegre50_importe_anticipo;
        end
        else if (pm_sicegre51_cotiza = 1) then
        begin
            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes,
                                              siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_prove,
                   'S',
                   :pm_sicegre51_importe,
                   0,
                   -1,
                   -1,
                   1);

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes,
                                              siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_banco,
                   'S',
                   0,
                   :pm_sicegre51_importe,
                   -1,
                   -1,
                   1);
        end
    end

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if (pm_sicegre51_importe <> 0)  then
    begin
        for select
        sicegre50_det_ctacte.rela_siccont10,
        sicegre52_det_bancos.sicegre52_importe / sicegre50_det_ctacte.sicegre50_importe * 100,
        siccont10_cab_polizas.siccont10_uuid_sat,
        sicegre52_det_bancos.sicegre52_importe
        from sicegre50_det_ctacte
        inner join sicegre52_det_bancos on (sicegre50_det_ctacte.id_sicegre50 = sicegre52_det_bancos.rela_sicegre50)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicegre50_det_ctacte.rela_siccont10)
        where  sicegre52_det_bancos.rela_sicegre51 = :pm_id_sicegre51
        and sicegre52_det_bancos.sicegre52_importe > 0
        into :id_siccont10_old,
             :porcentaje,
             :siccont10_uuid_sat,
             :sicegre52_importe
        do
        begin
            if (pm_sicegre51_cotiza <> 1) then
                execute procedure prd_sicegre51_creapolizas_tc :id_sicxmls01,
                                                               :id_siccont10_old,
                                                               :id_siccont10_new,
                                                               :rela_siccont02_prove,
                                                               :rela_siccont02_banco,
                                                               :pm_sicegre51_monnac,
                                                               :porcentaje,
                                                               :pm_sicegre51_cotiza,
                                                               :sicegre52_importe;
            for select
            sicxmls02_det_impuestos.rela_siccont02,
            sicxmls02_det_impuestos.rela_siccont02_ctracta,
            siccont11_det_polizas.siccont11_debe,
            siccont11_det_polizas.siccont11_haber
            from sicxmls02_det_impuestos
            inner join siccont12_mov_dropzone on (sicxmls02_det_impuestos.id_sicxmls02 = siccont12_mov_dropzone.rela_sicxmls02)
            inner join siccont11_det_polizas on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)    
            where siccont11_det_polizas.rela_siccont10 = :id_siccont10_old
            into :rela_siccont02,
                 :rela_siccont02_ctracta,
                 :siccont11_debe,
                 :siccont11_haber
            do
            begin
                if (siccont11_debe <> 0) then
                   siccont11_debe = siccont11_debe * porcentaje / 100;
                else
                   siccont11_haber = siccont11_haber * porcentaje / 100;
                    
                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_referencia,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes,
                                                  siccont11_det_polizas.siccont11_nocotiza)

                values(:id_siccont10_new,
                       :rela_siccont02_ctracta,
                       'S',
                       :siccont10_uuid_sat,
                       :siccont11_debe,
                       :siccont11_haber,
                       -1,
                       -1,
                       1);

                /* --------------------------------------------------------------------------------------------------------------------------- */
                /* --------------------------------------------------------------------------------------------------------------------------- */

                if (siccont11_debe <> 0) then
                begin
                    siccont11_haber = siccont11_debe;
                    siccont11_debe = 0;
                end
                else
                begin
                    siccont11_debe = siccont11_haber;
                    siccont11_haber = 0;
                end

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes,
                                      siccont11_det_polizas.siccont11_nocotiza)

                values(:id_siccont10_new,
                   :rela_siccont02,
                   'S',
                   :siccont10_uuid_sat,
                   :siccont11_debe,
                   :siccont11_haber,
                    -1,
                    -1,
                    1);
            end    
        end

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        if (sicegre50_importe_anticipo = 0) then
           pm_sicegre51_importe = :pm_sicegre51_importe * (-1);
        else
           pm_sicegre51_importe = 0;

        insert into sicegre50_det_ctacte(sicegre50_det_ctacte.rela_sicegre01,
                                         sicegre50_det_ctacte.rela_socmain01,
                                         sicegre50_det_ctacte.rela_siccont10,
                                         sicegre50_det_ctacte.rela_sicegre51,
                                         sicegre50_det_ctacte.sicegre50_importe)

        values( :pm_rela_sicegre01,
                :pm_rela_socmain01,
                :id_siccont10_new,
                :pm_id_sicegre51,
                :pm_sicegre51_importe);

        ok = 1;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE51_CREAPOLIZAS_TC (
    ID_SICXMLS01 BIGINT,
    ID_SICCONT10_OLD BIGINT,
    ID_SICCONT10_NEW BIGINT,
    RELA_SICCONT02_PROVE BIGINT,
    RELA_SICCONT02_BANCO BIGINT,
    PM_SICINGR51_MONNAC BIGINT,
    PORCENTAJE DOUBLE PRECISION,
    PM_SICINGR51_COTIZA DOUBLE PRECISION,
    SICINGR52_IMPORTE DOUBLE PRECISION)
AS
declare variable RELA_SICCONT02_COTIZA_COMP bigint;
declare variable RELA_SICCONT02_COTIZA_MAS bigint;
declare variable RELA_SICCONT02_COTIZA_MENOS bigint;
declare variable RELA_SICCONT02_COTIZA_TARIA bigint;
declare variable SUMA_COTIZA_XML double precision;
declare variable SICCONT10_COTIZA_OLD double precision;
declare variable RESULTADO_COTIZA double precision;
begin
    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-COMP'
    into :rela_siccont02_cotiza_comp;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-MAS'
    into :rela_siccont02_cotiza_mas;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-MENOS'
    into :rela_siccont02_cotiza_menos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-TARIA-PROVE'
    into :rela_siccont02_cotiza_taria;

    select sum(siccont11_det_polizas.siccont11_debe)
    from siccont11_det_polizas
    where siccont11_det_polizas.rela_siccont10 = :id_siccont10_old
    into :suma_cotiza_xml;

    select siccont10_cab_polizas.siccont10_cotiza
    from siccont10_cab_polizas
    where siccont10_cab_polizas.id_siccont10 = :id_siccont10_old
    into :siccont10_cotiza_old;

    suma_cotiza_xml = suma_cotiza_xml * porcentaje / 100;

    sicingr52_importe = sicingr52_importe * pm_sicingr51_cotiza;
    sicingr52_importe = sicingr52_importe * porcentaje / 100;

    resultado_cotiza = suma_cotiza_xml - sicingr52_importe;

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes,
                                                  siccont11_det_polizas.siccont11_nocotiza)

    values( :id_siccont10_new,
            :rela_siccont02_prove,
            'S',
            :suma_cotiza_xml / :siccont10_cotiza_old,
            0,
            -1,
            -1,
            1 );
    
    insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                       siccont11_det_polizas.rela_siccont02,
                                       siccont11_det_polizas.siccont11_tipo_entidad,
                                       siccont11_det_polizas.siccont11_debe,
                                       siccont11_det_polizas.siccont11_haber,
                                       siccont11_det_polizas.siccont11_ano,
                                       siccont11_det_polizas.siccont11_mes,
                                       siccont11_det_polizas.siccont11_nocotiza )
            
    values( :id_siccont10_new,
            :rela_siccont02_cotiza_taria,
            'S',
            :suma_cotiza_xml - (:suma_cotiza_xml / :siccont10_cotiza_old),
            0,
            -1,
            -1,
            1 );


    if (pm_sicingr51_monnac <> 0) then
    begin
        select socmain05_det_bancos.rela_siccont02
        from socmain05_det_bancos
        where socmain05_det_bancos.id_socmain05 = :pm_sicingr51_monnac
        into :rela_siccont02_banco;

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                       siccont11_det_polizas.rela_siccont02,
                                       siccont11_det_polizas.siccont11_tipo_entidad,
                                       siccont11_det_polizas.siccont11_debe,
                                       siccont11_det_polizas.siccont11_haber,
                                       siccont11_det_polizas.siccont11_ano,
                                       siccont11_det_polizas.siccont11_mes,
                                       siccont11_det_polizas.siccont11_nocotiza )

        values( :id_siccont10_new,
                :rela_siccont02_banco,
                'S',
                0,
                :sicingr52_importe,
                -1,
                -1,
                1 );
    end
    else
    begin
        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
    
        values( :id_siccont10_new,
                :rela_siccont02_banco,
                'S',
                0,
                :suma_cotiza_xml / :siccont10_cotiza_old,
                -1,
                -1,
                1 );
    
        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
    
        values( :id_siccont10_new,
                :rela_siccont02_cotiza_comp,
                'S',
                0,
                :sicingr52_importe - (:suma_cotiza_xml / :siccont10_cotiza_old),
                -1,
                -1,
                1 );
    end

    if (resultado_cotiza < 0) then
    begin
        resultado_cotiza = resultado_cotiza * (-1);

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
        
        values( :id_siccont10_new,
                :rela_siccont02_cotiza_menos,
                'S',
                :resultado_cotiza,
                0,
                -1,
                -1,
                1 );
    end
    else if (resultado_cotiza > 0) then
    begin
        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
        
        values( :id_siccont10_new,
                :rela_siccont02_cotiza_mas,
                'S',
                0,
                :resultado_cotiza,
                -1,
                -1,
                1 );
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE51_VALIDA (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    ID INTEGER,
    MENSAJE VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CADENA_MENSAJE varchar(100);
declare variable ID_SICXMLS02 bigint;
begin
    id = 0;
    id_sicxmls02 = null;
    CADENA_MENSAJE = 'Debe parametrizar ';

    SELECT FIRST 1 sicxmls02_det_impuestos.id_sicxmls02
    FROM sicxmls02_det_impuestos
    inner join sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls02_det_impuestoS.rela_sicxmls01)
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    AND (sicxmls02_det_impuestos.rela_siccont02 is null
    or sicxmls02_det_impuestos.rela_siccont02_ctracta is null)
    into :id_sicxmls02;

    if (id_sicxmls02 is not null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || ' los Impuestos y ctas de traslados.';
        suspend; 
    end

    if (id = 0) then
    BEGIN
        ID = ID + 1;
        mensaje = 'OK';
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE60_CREAPOLIZAS (
    ID_SOCMAIN01 BIGINT,
    ID_SOCMAIN21 BIGINT,
    ID_SOCUSUA01 BIGINT,
    ID_SOCMAIN05 BIGINT,
    ID_SICNOMI01 BIGINT,
    IMPORTE DOUBLE PRECISION,
    DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE)
RETURNS (
    RELA_SICCONT10 BIGINT)
AS
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SOCUSUA30 bigint;
declare variable RELA_SICCONT02_BANCOS bigint;
declare variable RELA_SICCONT02_DEUDORES bigint;
begin
    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-REEMBOLSO'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-2-EGR'
    into :id_socsyst10_ctp02;

    select cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :id_socsyst10_ctm01;

    select cbo_sicnomi01_id.rela_socusua30
    from cbo_sicnomi01_id
    where cbo_sicnomi01_id.id_sicnomi01 = :id_sicnomi01
    into :id_socusua30;

    select socmain05_det_bancos.rela_siccont02
    from socmain05_det_bancos
    where socmain05_det_bancos.id_socmain05 = :id_socmain05
    into :rela_siccont02_bancos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'PROVE-DEUDORES'
    into :rela_siccont02_deudores;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.rela_socusua30,
                                      SICCONT10_CAB_POLIZAS.siccont10_notas,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :ID_SOCMAIN01,
                :ID_SOCMAIN21,
                :ID_SOCUSUA01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                :id_socusua30,
                :descripcion,
                'E',
                'APERTURA DE RENDICION',
                'xxxx',
                :fecha,
                1);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :rela_siccont10;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10,
                   :rela_siccont02_deudores,
                   'S',
                   :importe,
                   0,
                   -1,
                   -1);

        insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                          siccont11_det_polizas.rela_siccont02,
                                          siccont11_det_polizas.siccont11_tipo_entidad,
                                          siccont11_det_polizas.siccont11_debe,
                                          siccont11_det_polizas.siccont11_haber,
                                          siccont11_det_polizas.siccont11_ano,
                                          siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10,
                   :rela_siccont02_bancos,
                   'S',
                   0,
                   :importe,
                   -1,
                   -1);

    suspend;

end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE60_EMPLEADO (
    APELLIDO_PATERNO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    APELLIDO_MATERNO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SOCMAIN01 BIGINT)
RETURNS (
    ID_SICNOMI01 BIGINT)
AS
declare variable ID_SOCSYST10 bigint;
declare variable ID_SOCUSUA30 bigint;
begin
    SELECT CBO_SOCSYST10_TP001.id_socsyst10
    FROM CBO_SOCSYST10_TP001
    WHERE CBO_SOCSYST10_TP001.socsyst10_codigo = 'FISICO'
    INTO :id_socsyst10;

    INSERT into socusua30_cab_entidades(socusua30_cab_entidades.rela_socsyst10,
                                        socusua30_cab_entidades.socusua30_apellido_pat,
                                        socusua30_cab_entidades.socusua30_apellido_mat,
                                        socusua30_cab_entidades.socusua30_nombre_razsoc,
                                        socusua30_cab_entidades.socusua30_fnac_const,
                                        socusua30_cab_entidades.socusua30_extranjero)
    VALUES(:id_socsyst10, :APELLIDO_PATERNO, :APELLIDO_MATERNO, :NOMBRES, current_date, 0);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA30'
    INTO :ID_SOCUSUA30;

    INSERT INTO sicnomi01_cab_empleados(sicnomi01_cab_empleados.rela_socusua30,
                                        sicnomi01_cab_empleados.rela_socmain01,
                                        sicnomi01_cab_empleados.sicnomi01_diascredito)
    VALUES(:ID_SOCUSUA30, :ID_SOCMAIN01, 0);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICNOMI01'
    INTO :ID_SICNOMI01;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICEGRE61_CREAPOLIZAS
RETURNS (
    OK INTEGER)
AS
declare variable ID_SICEGRE60 bigint;
declare variable ID_SICEGRE61_FIND bigint;
declare variable RELA_SICCONT10_ORIGEN bigint;
declare variable SICEGRE50_IMPORTE double precision;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SOCMAIN01 bigint;
declare variable ID_SOCMAIN21 bigint;
declare variable ID_SOCUSUA01 bigint;
declare variable RELA_SICCONT10_NEW bigint;
declare variable ID_SOCUSUA30 bigint;
declare variable ID_SICEGRE61 bigint;
declare variable IMPORTE_JUSTE double precision;
declare variable SICEGRE60_IMPORTE double precision;
declare variable IMPORTE_RENDICION double precision;
declare variable FOLIO_APERTURA varchar(50);
declare variable RELA_SICCONT02_PROVEEDORES bigint;
declare variable RELA_SICCONT02_AJUSTE bigint;
declare variable RELA_SICCONT02_DEUDORES bigint;
declare variable RELA_SICCONT02_IMPUESTOS bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
declare variable RELA_SICCONT10_AJUSTE bigint;
declare variable RELA_SICEGRE01 bigint;
declare variable SICEGRE60_FCTA_REND date;
declare variable SICCONT10_UUID_SAT varchar(50);
declare variable SICCONT10_UUID_SMX varchar(50);
begin
    ok = 0;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICEGRE61'
    INTO :id_sicegre61_find;

    select sicegre61_det_rendicion.rela_sicegre60
    from sicegre61_det_rendicion
    where sicegre61_det_rendicion.id_sicegre61 = :id_sicegre61_find
    into :id_sicegre60;

    select
    sicegre60_cab_rendicion.rela_socmain01,
    sicegre60_cab_rendicion.rela_socmain21,
    sicegre60_cab_rendicion.rela_socusua01,
    sicegre60_cab_rendicion.sicegre60_importe,
    siccont10_cab_polizas.siccont10_docnro,
    sicegre60_cab_rendicion.sicegre60_fcta_rend
    from sicegre60_cab_rendicion
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicegre60_cab_rendicion.rela_siccont10)
    where sicegre60_cab_rendicion.id_sicegre60 = :id_sicegre60
    into :id_socmain01,
         :id_socmain21,
         :id_socusua01,
         :sicegre60_importe,
         :folio_apertura,
         :sicegre60_fcta_rend;

    SELECT sum(sicegre50_det_ctacte.sicegre50_importe)
    FROM sicegre61_det_rendicion
    INNER join sicegre50_det_ctacte ON (sicegre50_det_ctacte.id_sicegre50 = sicegre61_det_rendicion.rela_sicegre50)
    WHERE sicegre61_det_rendicion.rela_sicegre60 = :id_sicegre60
    into :importe_rendicion;

    importe_juste = sicegre60_importe - importe_rendicion;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-REEMBOLSO'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-3-DIA'
    into :id_socsyst10_ctp02;

    select cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :id_socsyst10_ctm01;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'PROVE'
    into :rela_siccont02_proveedores;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'PROVE-AJUSTE-REEMBOLSO'
    into :rela_siccont02_ajuste;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'PROVE-DEUDORES'
    into :rela_siccont02_deudores;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    for select
    sicegre61_det_rendicion.id_sicegre61,
    sicegre50_det_ctacte.rela_siccont10,
    sicegre50_det_ctacte.sicegre50_importe
    from sicegre61_det_rendicion
    inner join sicegre50_det_ctacte on (sicegre50_det_ctacte.id_sicegre50 = sicegre61_det_rendicion.rela_sicegre50)
    where sicegre61_det_rendicion.rela_sicegre60 = :id_sicegre60
    into :id_sicegre61,
         :rela_siccont10_origen,
         :sicegre50_importe
    do
    begin
        select
        siccont10_cab_polizas.rela_socusua30,
        siccont10_cab_polizas.siccont10_uuid_sat,
        siccont10_cab_polizas.siccont10_uuid_smx
        from siccont10_cab_polizas
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_origen
        into :id_socusua30,
             :siccont10_uuid_sat,
             :siccont10_uuid_smx;

        select cbo_sicegre01.rela_sicegre01
        from cbo_sicegre01
        where cbo_sicegre01.rela_socmain01 = :id_socmain01
        and cbo_sicegre01.id_socusua30 = :id_socusua30
        into :rela_sicegre01;

        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                          SICCONT10_CAB_POLIZAS.rela_socmain21,
                                          SICCONT10_CAB_POLIZAS.rela_socusua01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                          SICCONT10_CAB_POLIZAS.rela_socusua30,
                                          SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                          SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                          SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                          SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                          SICCONT10_CAB_POLIZAS.siccont10_cotiza,
                                          SICCONT10_CAB_POLIZAS.siccont10_uuid_sat,
                                          SICCONT10_CAB_POLIZAS.siccont10_uuid_smx)
        values( :ID_SOCMAIN01,
                :ID_SOCMAIN21,
                :ID_SOCUSUA01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                :id_socusua30,
                'P',
                'RENDICION DE GASTOS - APERTURA POLIZA NO. ' || :folio_apertura,
                'xxxx',
                :sicegre60_fcta_rend,
                1,
                :siccont10_uuid_sat,
                :siccont10_uuid_smx);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :rela_siccont10_new;

        update sicegre61_det_rendicion set sicegre61_det_rendicion.rela_siccont10 = :rela_siccont10_new
        where sicegre61_det_rendicion.id_sicegre61 = :id_sicegre61;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        insert into sicegre50_det_ctacte(sicegre50_det_ctacte.rela_sicegre01,
                                             sicegre50_det_ctacte.rela_socmain01,
                                             sicegre50_det_ctacte.rela_siccont10,
                                             sicegre50_det_ctacte.sicegre50_importe)

        values(:rela_sicegre01, :id_socmain01, :rela_siccont10_new, :sicegre50_importe * -1);

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_new,
                   :rela_siccont02_proveedores,
                   'S',
                   :sicegre50_importe,
                   0,
                   -1,
                   -1);

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_new,
                   :rela_siccont02_deudores,
                   'S',
                   0,
                   :sicegre50_importe,
                   -1,
                   -1);

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        for select
        sicxmls02_det_impuestos.rela_siccont02,
        sicxmls02_det_impuestos.rela_siccont02_ctracta,
        sum(siccont11_det_polizas.siccont11_debe),
        sum(siccont11_det_polizas.siccont11_haber)
        from sicxmls02_det_impuestos
        inner join siccont12_mov_dropzone on (sicxmls02_det_impuestos.id_sicxmls02 = siccont12_mov_dropzone.rela_sicxmls02)
        inner join siccont11_det_polizas on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10_origen
        group by sicxmls02_det_impuestos.rela_siccont02,
                 sicxmls02_det_impuestos.rela_siccont02_ctracta
        having (sum(siccont11_det_polizas.siccont11_debe) + sum(siccont11_det_polizas.siccont11_haber)) <> 0
        into :rela_siccont02_impuestos,
             :rela_siccont02_ctracta,
             :siccont11_debe,
             :siccont11_haber
        do
        begin
            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_new,
                   :rela_siccont02_ctracta,
                   'S',
                   :siccont11_debe,
                   :siccont11_haber,
                   -1,
                   -1);

            /* --------------------------------------------------------------------------------------------------------------------------- */
            /* --------------------------------------------------------------------------------------------------------------------------- */

            if (siccont11_debe <> 0) then
            begin
                siccont11_haber = siccont11_debe;
                siccont11_debe = 0;
            end
            else
            begin
                siccont11_debe = siccont11_haber;
                siccont11_haber = 0;
            end

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes)

                values(:rela_siccont10_new,
                   :rela_siccont02_impuestos,
                   'S',
                   :siccont11_debe,
                   :siccont11_haber,
                    -1,
                    -1);    
        end
    end

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if (importe_juste <> 0) then
    begin
        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                          SICCONT10_CAB_POLIZAS.rela_socmain21,
                                          SICCONT10_CAB_POLIZAS.rela_socusua01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                          SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                          SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                          SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                          SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                          SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :ID_SOCMAIN01,
                :ID_SOCMAIN21,
                :ID_SOCUSUA01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                'S',
                'AJUSTE DE GASTOS - APERTURA POLIZA NO. ' || :folio_apertura,
                'xxxx',
                :sicegre60_fcta_rend,
                1);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :rela_siccont10_ajuste;

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                               siccont11_det_polizas.rela_siccont02,
                                               siccont11_det_polizas.siccont11_tipo_entidad,
                                               siccont11_det_polizas.siccont11_debe,
                                               siccont11_det_polizas.siccont11_haber,
                                               siccont11_det_polizas.siccont11_ano,
                                               siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_ajuste,
                   :rela_siccont02_ajuste,
                   'S',
                   :importe_juste,
                   0,
                   -1,
                   -1);

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                               siccont11_det_polizas.rela_siccont02,
                                               siccont11_det_polizas.siccont11_tipo_entidad,
                                               siccont11_det_polizas.siccont11_debe,
                                               siccont11_det_polizas.siccont11_haber,
                                               siccont11_det_polizas.siccont11_ano,
                                               siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_ajuste,
                   :rela_siccont02_deudores,
                   'S',
                   0,
                   :importe_juste,
                   -1,
                   -1);

        update sicegre60_cab_rendicion set sicegre60_cab_rendicion.rela_siccont10_ajuste = :rela_siccont10_ajuste
        where sicegre60_cab_rendicion.id_sicegre60 = :id_sicegre60;
    end

    ok = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR01_MODI (
    RELA_SICINGR01 BIGINT,
    PARAM_MODALIDAD INTEGER,
    PARAM_DIAS_CREDITO INTEGER,
    PARAM_IMPORTE_CREDITO DOUBLE PRECISION,
    PARAM_RFC VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PARAM_CODPOSTAL INTEGER,
    PARAM_CODPOSTAL_ID BIGINT,
    PARAM_TEL_PAR VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PARAM_TEL_CEL VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PARAM_TEL_TRA VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PARAM_CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICINGR01 BIGINT,
    DIAS_CREDITO INTEGER,
    IMPORTE_CREDITO DOUBLE PRECISION,
    RFC VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOSTAL_ID BIGINT,
    TEL_PAR VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_CEL VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TEL_TRA VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable CODPOSTAL_TMP integer;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCUSUA31_LADA varchar(10);
declare variable SOCUSUA31_NRO varchar(20);
declare variable ID_SOCSYST10_RFC bigint;
declare variable ID_SOCSYST10_DOMICILIO bigint;
declare variable ID_SOCSYST10_CORREO bigint;
declare variable ID_SOCSYST10_TELEFONO bigint;
declare variable EXISTE bigint;
declare variable LADA_TMP varchar(10);
declare variable TELE_TMP varchar(10);
begin
  id_sicingr01 = :rela_sicingr01;

  /* Busca la información */
  if (param_modalidad = 0) then
  begin
        tel_cel = '';
        tel_par = '';
        tel_tra = '';
    
        select
        sicingr01_cab_clientes.rela_socusua30,
        sicingr01_cab_clientes.sicingr01_diascredito,
        sicingr01_cab_clientes.sicingr01_credito
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
        into :rela_socusua30,
             :dias_credito,
             :importe_credito;
    
        if (dias_credito is null) then
            dias_credito = 0;
    
        if (importe_credito is null) then
            importe_credito = 0.00;

        select
        cbo_sicingr01_id.rfc
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :rfc;

        if (rfc = 'null') then
            rfc = '';
    
        select first 1
        socusua36_det_domicilios.rela_socmain80,
        socusua36_det_domicilios.socusua36_codpostal
        from socusua36_det_domicilios
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
        into :codpostal_id,
             :codpostal_tmp;
    
        codpostal = cast(codpostal_tmp as varchar(10));

        if (char_length(codpostal) < 5) then
            codpostal = '0' || codpostal;
    
        select first 1
        socusua35_det_internet.socusua35_internet
        from socusua35_det_internet
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01 )
        where socusua35_det_internet.rela_socusua30 = :rela_socusua30
        and socsyst10_det_entradas.socsyst10_codigo = 'CORREO'
        into :correo;
    
        for select
        socsyst10_det_entradas.socsyst10_codigo,
        socusua31_det_telefonos.socusua31_lada,
        socusua31_det_telefonos.socusua31_nro
        from socusua31_det_telefonos
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua31_det_telefonos.rela_socsyst10_tt001 )
        where socusua31_det_telefonos.rela_socusua30 = :rela_socusua30
        into :socsyst10_codigo,
             :socusua31_lada,
             :socusua31_nro
        do
        begin
            if (socusua31_lada is null) then
                socusua31_lada = '';
    
            if (socusua31_nro is null) then
                socusua31_nro = '';
    
            if (socsyst10_codigo = 'TELCEL') then
                tel_cel = '(' || socusua31_lada || ') ' || socusua31_nro;
            else if (socsyst10_codigo = 'TELPAR') then
                tel_par = '(' || socusua31_lada || ') ' || socusua31_nro;
            else if (socsyst10_codigo = 'TELLAB') then
                tel_tra = '(' || socusua31_lada || ') ' || socusua31_nro;
        end
  end
  /* Actualiza Datos */
  else
  begin
        select
        sicingr01_cab_clientes.rela_socusua30
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
        into :rela_socusua30;
    
        select
        cbo_socsyst10_td001.id_socsyst10
        from cbo_socsyst10_td001
        where cbo_socsyst10_td001.socsyst10_codigo = 'RFC'
        into :id_socsyst10_rfc;
    
        select
        cbo_socsyst10_tdd01.id_socsyst10
        from cbo_socsyst10_tdd01
        where cbo_socsyst10_tdd01.socsyst10_codigo = 'PARTICULAR'
        into :id_socsyst10_domicilio;
    
        select
        cbo_socsyst10_tdi01.id_socsyst10
        from cbo_socsyst10_tdi01
        where cbo_socsyst10_tdi01.socsyst10_codigo = 'CORREO'
        into :id_socsyst10_correo;
    
        update sicingr01_cab_clientes set sicingr01_cab_clientes.sicingr01_diascredito = :param_dias_credito,
                                          sicingr01_cab_clientes.sicingr01_credito = :param_importe_credito
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01;
    
        /* ================================================================================================================ */
        /* DOCUMENTO */
        /* ================================================================================================================ */
        
        if (param_rfc is not null) then
        begin
            existe = null;
        
            select
            socusua32_det_documentos.id_socusua32
            from socusua32_det_documentos
            where socusua32_det_documentos.rela_socusua30 = :rela_socusua30
            and socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_rfc
            into :existe;
        
            if (existe is null) then
                insert into socusua32_det_documentos(socusua32_det_documentos.rela_socusua30,
                                                     socusua32_det_documentos.rela_socsyst10_td001,
                                                     socusua32_det_documentos.socusua32_documento,
                                                     socusua32_det_documentos.socusua32_principal )
                values( :rela_socusua30,
                        :id_socsyst10_rfc,
                        :param_rfc,
                        1);
            else
                update socusua32_det_documentos set socusua32_det_documentos.socusua32_documento = :param_rfc
                where socusua32_det_documentos.id_socusua32 = :existe;
        end
        else
        begin
            delete from socusua32_det_documentos where socusua32_det_documentos.rela_socusua30 = :rela_socusua30
            and socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_rfc;
        end

        /* ================================================================================================================ */
        /* DOMICILIO */
        /* ================================================================================================================ */

        existe = null;
    
        select
        socusua36_det_domicilios.id_socusua36
        from socusua36_det_domicilios
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socusua36_det_domicilios.rela_socsyst10_tdd01 = :id_socsyst10_domicilio
        into :existe;
    
        if (existe is null) then
            insert into socusua36_det_domicilios( socusua36_det_domicilios.rela_socusua30,
                                                  socusua36_det_domicilios.rela_socsyst10_tdd01,
                                                  socusua36_det_domicilios.rela_socmain80,
                                                  socusua36_det_domicilios.socusua36_codpostal,
                                                  socusua36_det_domicilios.socusua36_calle,
                                                  socusua36_det_domicilios.socusua36_nro,
                                                  socusua36_det_domicilios.socusua36_nrointerior,
                                                  socusua36_det_domicilios.socusua36_ciudad,
                                                  socusua36_det_domicilios.socusua36_colonia,
                                                  socusua36_det_domicilios.socusua36_referencia )
            values( :rela_socusua30,
                    :id_socsyst10_domicilio,
                    :param_codpostal_id,
                    :param_codpostal,
                    '',
                    '',
                    '',
                    '',
                    '',
                    '');
        else
            update socusua36_det_domicilios set  socusua36_det_domicilios.rela_socmain80 = :param_codpostal_id,
                                                 socusua36_det_domicilios.socusua36_codpostal = :param_codpostal
            where  socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
            and  socusua36_det_domicilios.rela_socsyst10_tdd01 = :id_socsyst10_domicilio;
    
       /* ================================================================================================================ */
       /* CORREO */
       /* ================================================================================================================ */

       existe = null;
    
       select
       socusua35_det_internet.id_socusua35
       from socusua35_det_internet
       where socusua35_det_internet.rela_socusua30 = :rela_socusua30
       and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10_correo
       into :existe;
    
       if (existe is null) then
           insert into socusua35_det_internet( socusua35_det_internet.rela_socusua30,
                                               socusua35_det_internet.rela_socsyst10_tdi01,
                                               socusua35_det_internet.socusua35_internet )
           values( :rela_socusua30,
                   :id_socsyst10_correo,
                   :param_correo );
            
        else
           update socusua35_det_internet set socusua35_det_internet.socusua35_internet = :param_correo
           where socusua35_det_internet.rela_socusua30 = :rela_socusua30
           and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10_correo;


       /* ================================================================================================================ */
       /* TELEFONOS */
       /* ================================================================================================================ */

       FOR SELECT
       cbo_socsyst10_tt001.id_socsyst10,
       cbo_socsyst10_tt001.socsyst10_codigo
       from cbo_socsyst10_tt001
       into :id_socsyst10_telefono,
            :socsyst10_codigo
       do
       begin
          lada_tmp = null;
          tele_tmp = null;

          if (socsyst10_codigo = 'TELCEL' and char_length(param_tel_cel) = 13) then
          begin
             lada_tmp = trim(substring(param_tel_cel from 2 for 3));
             tele_tmp = trim(substring(param_tel_cel from 6));
          end
          else if (socsyst10_codigo = 'TELPAR' and char_length(param_tel_par) = 13) then
          begin
             lada_tmp = trim(substring(param_tel_par from 2 for 3));
             tele_tmp = trim(substring(param_tel_par from 6));
          end
          else if (socsyst10_codigo = 'TELLAB' and char_length(param_tel_tra) = 13) then
          begin
             lada_tmp = trim(substring(param_tel_tra from 2 for 3));
             tele_tmp = trim(substring(param_tel_tra from 6));
          end

          if (lada_tmp is not null and tele_tmp is not null) then
          begin
              existe = null;
    
              select
              socusua31_det_telefonos.id_socusua31
              from socusua31_det_telefonos
              where socusua31_det_telefonos.rela_socusua30 = :rela_socusua30
              and socusua31_det_telefonos.rela_socsyst10_tt001 = :id_socsyst10_telefono
              into :existe;
    
              if (existe is null) then
                  insert into socusua31_det_telefonos( socusua31_det_telefonos.rela_socusua30,
                                                       socusua31_det_telefonos.rela_socsyst10_tt001,
                                                       socusua31_det_telefonos.socusua31_lada,
                                                       socusua31_det_telefonos.socusua31_nro)
                  values( :rela_socusua30,
                          :id_socsyst10_telefono,
                          :lada_tmp,
                          :tele_tmp );
               else
                  update socusua31_det_telefonos set socusua31_det_telefonos.socusua31_lada = :lada_tmp,
                                                     socusua31_det_telefonos.socusua31_nro = :tele_tmp
                  where socusua31_det_telefonos.rela_socusua30 = :rela_socusua30
                  and socusua31_det_telefonos.rela_socsyst10_tt001 = :id_socsyst10_telefono;
          end
       end
  end

  suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION (
    ID_SICINGR30 BIGINT,
    MODALIDAD INTEGER)
AS
declare variable ID_SICINGR31 bigint;
declare variable RELA_SOCMAIN01 bigint;
begin
    for select
    sicingr30_cab_migracion.rela_socmain01,
    sicingr31_det_migracion.id_sicingr31
    from sicingr31_det_migracion
    inner join sicingr30_cab_migracion on (sicingr30_cab_migracion.id_sicingr30 = sicingr31_det_migracion.rela_sicingr30)
    where sicingr31_det_migracion.rela_sicingr30 = :id_sicingr30
    into :rela_socmain01,
         :id_sicingr31
    do
    begin
        if (modalidad = 0) then
            execute procedure prd_sicingr30_migracion_add :id_sicingr31, :rela_socmain01;
        else
            execute procedure prd_sicingr30_migracion_update :id_sicingr31, :rela_socmain01;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_ADD (
    ID_SICINGR31 BIGINT,
    RELA_SOCMAIN01 BIGINT)
AS
declare variable SICINGR31_CODIGO varchar(50);
declare variable SICINGR31_PRODUCTO varchar(400);
declare variable SICINGR31_IMPORTE double precision;
declare variable SICINGR31_IMPORTE_COSTO double precision;
declare variable SICINGR31_IVA double precision;
declare variable SICINGR31_FACTOR varchar(50);
declare variable SICINGR31_IEPS double precision;
declare variable SICINGR31_CODSAT varchar(50);
declare variable SICINGR31_UNISAT varchar(50);
declare variable SICINGR31_CTACTE varchar(50);
declare variable SICINGR31_CATEGORIA varchar(400);
declare variable SICINGR31_FAMILIA varchar(400);
declare variable SICINGR31_MARCA varchar(400);
declare variable SICINGR31_MODELO varchar(400);
declare variable SICINGR31_TALLA varchar(400);
declare variable SICINGR31_COLOR varchar(400);
declare variable ID_SICXMLS04 bigint;
declare variable ID_SICINGR95 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable ID_SOCSYST10_TCT01 bigint;
declare variable ID_SICCONT02 bigint;
declare variable IVA integer;
declare variable ID_SOCSYST10_CUM01 bigint;
declare variable ID_SOCSYST10_CPO01 bigint;
declare variable STATUS varchar(400);
declare variable ID_SOCSYST10_MLI01_COSTO bigint;
declare variable ID_SICINGR90_IVA bigint;
declare variable ID_SICINGR90_IEPS bigint;
begin
    select
    sicingr31_det_migracion.sicingr31_codigo,
    sicingr31_det_migracion.sicingr31_producto,
    sicingr31_det_migracion.sicingr31_importe,
    sicingr31_det_migracion.sicingr31_importe_costo,
    sicingr31_det_migracion.sicingr31_iva,
    sicingr31_det_migracion.sicingr31_factor,
    sicingr31_det_migracion.sicingr31_ieps,
    sicingr31_det_migracion.sicingr31_codsat,
    sicingr31_det_migracion.sicingr31_unisat,
    sicingr31_det_migracion.sicingr31_ctacte,
    sicingr31_det_migracion.sicingr31_categoria,
    sicingr31_det_migracion.sicingr31_familia,
    sicingr31_det_migracion.sicingr31_marca,
    sicingr31_det_migracion.sicingr31_modelo,
    sicingr31_det_migracion.sicingr31_talla,
    sicingr31_det_migracion.sicingr31_color
    from sicingr31_det_migracion
    where sicingr31_det_migracion.id_sicingr31 = :id_sicingr31
    into :sicingr31_codigo,
         :sicingr31_producto,
         :sicingr31_importe,
         :sicingr31_importe_costo,
         :sicingr31_iva,
         :sicingr31_factor,
         :sicingr31_ieps,
         :sicingr31_codsat,
         :sicingr31_unisat,
         :sicingr31_ctacte,
         :sicingr31_categoria,
         :sicingr31_familia,
         :sicingr31_marca,
         :sicingr31_modelo,
         :sicingr31_talla,
         :sicingr31_color;

    select
    prd_sicingr30_migracion_valida.id_sicxmls01,
    prd_sicingr30_migracion_valida.id_sicxmls04,
    prd_sicingr30_migracion_valida.id_sicingr95,
    prd_sicingr30_migracion_valida.id_siccont02,
    prd_sicingr30_migracion_valida.id_socsyst10_tct01,
    prd_sicingr30_migracion_valida.id_socsyst10_cum01,
    prd_sicingr30_migracion_valida.id_socsyst10_cpo01,
    prd_sicingr30_migracion_valida.iva,
    prd_sicingr30_migracion_valida.status,
    prd_sicingr30_migracion_valida.id_socsyst10_mli01_costo,
    prd_sicingr30_migracion_valida.id_sicingr90_iva,
    prd_sicingr30_migracion_valida.id_sicingr90_ieps
    from prd_sicingr30_migracion_valida(0, /* modalidad add */
                                        :rela_socmain01,
                                        :sicingr31_codigo,
                                        :sicingr31_producto,
                                        :sicingr31_codsat,
                                        :sicingr31_unisat,
                                        :sicingr31_ctacte,
                                        :sicingr31_iva,
                                        :sicingr31_factor,
                                        :sicingr31_ieps)
    into :id_sicxmls01,
         :id_sicxmls04,
         :id_sicingr95,
         :id_siccont02,
         :id_socsyst10_tct01,
         :id_socsyst10_cum01,
         :id_socsyst10_cpo01,
         :iva,
         :status,
         :id_socsyst10_mli01_costo,
         :id_sicingr90_iva,
         :id_sicingr90_ieps;

    if (status = 'Ok.') then
    begin
        execute procedure PRD_SICXMLS04_INSERT :id_sicxmls01,
                                               :id_socsyst10_tct01,
                                               :id_siccont02,
                                               'I',
                                               :sicingr31_producto,
                                               :iva,
                                               0,
                                               :sicingr31_codsat,
                                               :sicingr31_unisat
        returning_values :id_sicxmls04;

        /* ================================================================================================================== */

        insert into sicingr95_cab_conceptos( sicingr95_cab_conceptos.rela_sicxmls01,
                                             sicingr95_cab_conceptos.rela_sicxmls04,
                                             sicingr95_cab_conceptos.rela_socsyst10_cum01,
                                             sicingr95_cab_conceptos.rela_socsyst10_cpo01,
                                             sicingr95_cab_conceptos.sicingr95_codigo,
                                             sicingr95_cab_conceptos.sicingr95_descripcion,
                                             sicingr95_cab_conceptos.sicingr95_importe )
        values( :id_sicxmls01,
                :id_sicxmls04,
                :id_socsyst10_cum01,
                :id_socsyst10_cpo01,
                :sicingr31_codigo,
                :sicingr31_producto,
                :sicingr31_importe );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
        INTO :id_sicingr95;

        /* ================================================================================================================== */

        insert into sicingr98_det_importes( sicingr98_det_importes.rela_sicingr95,
                                            sicingr98_det_importes.rela_socsyst10_mli01,
                                            sicingr98_det_importes.sicingr98_importe,
                                            sicingr98_det_importes.sicingr98_fecha_aplicacion,
                                            sicingr98_det_importes.sicingr98_fecha_vencimiento,
                                            sicingr98_det_importes.sicingr98_modalidad)
        values( :id_sicingr95,
                :id_socsyst10_mli01_costo,
                :sicingr31_importe_costo,
                current_timestamp,
                current_timestamp,
                0);

        /* ================================================================================================================== */

        insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                             sicingr96_det_impuestos.rela_sicingr90 )
        values( :id_sicingr95,
                :id_sicingr90_iva );

        /* ================================================================================================================== */

        if (id_sicingr90_ieps <> 0) then
            insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                                 sicingr96_det_impuestos.rela_sicingr90 )
            values( :id_sicingr95,
                    :id_sicingr90_ieps );

        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'FAMILIA', :sicingr31_familia, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'CATEGORIA', :sicingr31_categoria, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'MARCA', :sicingr31_marca, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'MODELO', :sicingr31_modelo, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'TALLA-MEDIDA', :sicingr31_talla, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'COLOR-PRESENTACION', :sicingr31_color, :id_sicingr95;
    end

    update sicingr31_det_migracion set sicingr31_det_migracion.sicingr31_status = :status
    where sicingr31_det_migracion.id_sicingr31 = :id_sicingr31;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_CLAS (
    MODALIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLASIFICACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR95 BIGINT)
AS
declare variable ID_SOCSYST10 bigint;
declare variable ID_SOCSYST12 bigint;
begin
    clasificacion = trim(upper(clasificacion));

    if (clasificacion != '') then
    begin
        select CBO_SOCSYST10_CDP01.id_socsyst10
        from CBO_SOCSYST10_CDP01
        where CBO_SOCSYST10_CDP01.socsyst10_codigo = :modalidad
        into :id_socsyst10;

        id_socsyst12 = null;

        select first 1
        SOCSYST12_DET_CLA.id_socsyst12
        from SOCSYST12_DET_CLA
        where SOCSYST12_DET_CLA.RELA_SOCSYST10 = :id_socsyst10
        and trim(upper(SOCSYST12_DET_CLA.socsyst12_descripcion)) = :clasificacion
        into :id_socsyst12;

        if (id_socsyst12 is null) then
        begin
            insert into socsyst12_det_cla( socsyst12_det_cla.rela_socsyst10,
                                           socsyst12_det_cla.socsyst12_codigo,
                                           socsyst12_det_cla.socsyst12_descripcion,
                                           socsyst12_det_cla.socsyst12_codagr)
            values( :id_socsyst10,
                    'SMXAUTO',
                    :clasificacion,
                    'SMXAUTO');

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCSYST12'
            INTO :id_socsyst12;
        end

        delete from sicingr97_det_clasificacion
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and sicingr97_det_clasificacion.rela_socsyst12 = :id_socsyst12;

        insert into sicingr97_det_clasificacion( sicingr97_det_clasificacion.rela_sicingr95,
                                                 sicingr97_det_clasificacion.rela_socsyst12,
                                                 sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
        values( :id_sicingr95,
                :id_socsyst12,
                :id_socsyst10 );
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_INVE (
    ID_SICINGR30 BIGINT)
AS
declare variable ID_SICINGR32 bigint;
declare variable SICINGR32_CODIGO varchar(50);
declare variable SICINGR32_ALMACEN varchar(50);
declare variable SICINGR32_RACK varchar(50);
declare variable SICINGR32_COLUMNA varchar(50);
declare variable SICINGR32_FILA varchar(50);
declare variable SICINGR32_INVENTARIO double precision;
declare variable ID_SOCSYST10_STK01 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01 bigint;
declare variable ID_PYMALMA01 bigint;
declare variable ID_SICINGR95 bigint;
declare variable SUMA_CANTIDAD double precision;
declare variable ID_PYMALMA02 bigint;
declare variable SIN_INVENTARIO integer;
declare variable VALIDA varchar(200);
declare variable STATUS varchar(400);
declare variable ID_SICXMLS01 bigint;
begin
    select
    cbo_socsyst10_stk01.id_socsyst10
    from cbo_socsyst10_stk01
    where cbo_socsyst10_stk01.socsyst10_codigo = 'STK-UPDATE'
    into :id_socsyst10_stk01;

    select
    sicingr30_cab_migracion.rela_socmain01,
    sicingr30_cab_migracion.rela_socmain21,
    sicingr30_cab_migracion.rela_socusua01
    from sicingr30_cab_migracion
    where sicingr30_cab_migracion.id_sicingr30 = :id_sicingr30
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01;

    select
    sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    id_pymalma01 = null;

    select
    pymalma01_cab_stock.id_pymalma01
    from pymalma01_cab_stock
    where pymalma01_cab_stock.rela_socmain01 = :rela_socmain01
    and pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
    into :id_pymalma01;

    /* ======================================================================================================================================== */

    if (id_pymalma01 is null) then
    begin
        insert into pymalma01_cab_stock( pymalma01_cab_stock.rela_socmain01,
                                         pymalma01_cab_stock.rela_socmain21,
                                         pymalma01_cab_stock.rela_socusua01 )
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01 );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA01'
        INTO :id_pymalma01;
    end

    /* ======================================================================================================================================== */

    for select
    sicingr32_det_inventario.id_sicingr32,
    sicingr32_det_inventario.sicingr32_codigo,
    sicingr32_det_inventario.sicingr32_almacen,
    sicingr32_det_inventario.sicingr32_rack,
    sicingr32_det_inventario.sicingr32_columna,
    sicingr32_det_inventario.sicingr32_fila,
    sicingr32_det_inventario.sicingr32_inventario
    from sicingr32_det_inventario
    where sicingr32_det_inventario.rela_sicingr30 = :id_sicingr30
    into :id_sicingr32,
         :sicingr32_codigo,
         :sicingr32_almacen,
         :sicingr32_rack,
         :sicingr32_columna,
         :sicingr32_fila,
         :sicingr32_inventario
    do
    begin
        status = 'Ok.';
        sicingr32_codigo = trim(upper(sicingr32_codigo));

        if (sicingr32_almacen is null) then
            sicingr32_almacen = '';
        else
            sicingr32_almacen = upper(trim(sicingr32_almacen));

        if (sicingr32_rack is null) then
            sicingr32_rack = '';
        else
            sicingr32_rack = upper(trim(sicingr32_rack));

        if (sicingr32_columna is null) then
            sicingr32_columna = '';
        else
            sicingr32_columna = upper(trim(sicingr32_columna));

        if (sicingr32_fila is null) then
            sicingr32_fila = '';
        else
            sicingr32_fila = upper(trim(sicingr32_fila));

        /* ======================================================================================================================================== */

        id_sicingr95 = null;

        select
        sicingr95_cab_conceptos.id_sicingr95
        from sicingr95_cab_conceptos
        where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01
        and trim(upper(sicingr95_cab_conceptos.sicingr95_codigo)) = :sicingr32_codigo
        into :id_sicingr95;

        /* ======================================================================================================================================== */

        if (id_sicingr95 is null) then
            status = 'Producto No Encontrado en Conceptos por Facturar' || ASCII_CHAR(13) || ASCII_CHAR(10);
        else if (sicingr32_inventario < 0) then
            status = 'La Cantidad Importada es Negativa' || ASCII_CHAR(13) || ASCII_CHAR(10);
        else
        begin
            select
            sum(pymalma02_det_stock.pymalma02_cantidad)
            from pymalma02_det_stock
            where pymalma02_det_stock.rela_pymalma01 = :id_pymalma01
            and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
            into :suma_cantidad;

            if (suma_cantidad is null) then
                suma_cantidad = 0;

            if (suma_cantidad <> 0) then
                insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                                 pymalma02_det_stock.rela_sicingr95,
                                                 pymalma02_det_stock.rela_socsyst10_stk01,
                                                 pymalma02_det_stock.pymalma02_cantidad )
                values( :id_pymalma01,
                        :id_sicingr95,
                        :id_socsyst10_stk01,
                        :suma_cantidad * (-1) );

            /* ======================================================================================================================================== */

            insert into pymalma02_det_stock( pymalma02_det_stock.rela_pymalma01,
                                             pymalma02_det_stock.rela_sicingr95,
                                             pymalma02_det_stock.rela_socsyst10_stk01,
                                             pymalma02_det_stock.pymalma02_cantidad )
            values( :id_pymalma01,
                    :id_sicingr95,
                    :id_socsyst10_stk01,
                    :sicingr32_inventario );

            /* ======================================================================================================================================== */

            select
            prd_pymalma04_validacion.sin_inventario,
            prd_pymalma04_validacion.valida
            from prd_pymalma04_validacion( :sicingr32_almacen,
                                           :sicingr32_rack,
                                           :sicingr32_columna,
                                           :sicingr32_fila )
            into :sin_inventario,
                 :valida;

            /* ======================================================================================================================================== */

            if (sin_inventario = 0) then
            begin
                if (valida = 'OK') then
                begin
                    select socsyst91_tbl_ultids.socsyst91_ultid
                    from socsyst91_tbl_ultids
                    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMALMA02'
                    INTO :id_pymalma02;
    
                    insert into pymalma04_mov_locaciones( pymalma04_mov_locaciones.rela_pymalma02,
                                                          pymalma04_mov_locaciones.pymalma04_almacen,
                                                          pymalma04_mov_locaciones.pymalma04_rack,
                                                          pymalma04_mov_locaciones.pymalma04_columna,
                                                          pymalma04_mov_locaciones.pymalma04_fila )
                    values( :id_pymalma02,
                            :sicingr32_almacen,
                            :sicingr32_rack,
                            :sicingr32_columna,
                            :sicingr32_fila );

                    end
                else
                    status = 'La Secuencia de Inventario no coincide.' || ASCII_CHAR(13) || ASCII_CHAR(10) ||
                             'Falta/n : ' || :valida || ASCII_CHAR(13) || ASCII_CHAR(10);
            end
        end

        update sicingr32_det_inventario set sicingr32_det_inventario.sicingr32_status = :status
        where sicingr32_det_inventario.id_sicingr32 = :id_sicingr32;

    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_RUN (
    ID_SICINGR30 BIGINT,
    MODALIDAD INTEGER)
RETURNS (
    OK VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (modalidad = 0 or modalidad = 2) then
        execute procedure prd_sicingr30_migracion :id_sicingr30, :modalidad;
    else  if (modalidad = 3) then
        execute procedure prd_sicingr30_migracion_inve :id_sicingr30;

    ok = 'ok';

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_SUBE (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR30 BIGINT)
RETURNS (
    RELA_SICINGR30 BIGINT,
    ID_SICINGR31 BIGINT,
    SICINGR31_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_PRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_DESCRIPCION VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_IMPORTE DOUBLE PRECISION,
    SICINGR31_IMPORTE_COSTO DOUBLE PRECISION,
    SICINGR31_MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_COTIZA DOUBLE PRECISION,
    SICINGR31_IVA DOUBLE PRECISION,
    SICINGR31_FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_IEPS DOUBLE PRECISION,
    SICINGR31_CODSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_UNISAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_CTACTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_CATEGORIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_FAMILIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_MARCA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_MODELO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_TALLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_COLOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_FAPL TIMESTAMP)
AS
declare variable ID_SICXMLS01 bigint;
declare variable ID_SICINGR95 bigint;
declare variable ROWS_IMPORTE integer;
declare variable SUMA_IMPORTE double precision;
declare variable RELA_SOCSYST10_CTM01 bigint;
begin
    rela_sicingr30 = id_sicingr30;
    id_sicingr31 = 0;

    select
    sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    into :id_sicxmls01;

    for select
    cum01.socsyst10_codigo,
    cpo01.socsyst10_codigo,
    siccont02_arb_planctas.siccont02_codigo_ext,
    sicingr95_cab_conceptos.id_sicingr95,
    sicingr95_cab_conceptos.sicingr95_codigo,
    sicingr95_cab_conceptos.sicingr95_descripcion,
    sicingr95_cab_conceptos.sicingr95_importe,
    sicingr95_cab_conceptos.sicingr95_notas,
    sicingr95_cab_conceptos.rela_socsyst10_ctm01
    from sicxmls04_det_conceptos
    inner join sicingr95_cab_conceptos on (sicingr95_cab_conceptos.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04)
    inner join socsyst10_det_remoto cum01 on (cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01)
    inner join socsyst10_det_remoto cpo01 on (cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01)
    inner join siccont02_arb_planctas on (siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02)
    where sicxmls04_det_conceptos.rela_sicxmls01 = :id_sicxmls01
    order by sicingr95_cab_conceptos.sicingr95_codigo
    into :sicingr31_unisat,
         :sicingr31_codsat,
         :sicingr31_ctacte,
         :id_sicingr95,
         :sicingr31_codigo,
         :sicingr31_producto,
         :sicingr31_importe,
         :sicingr31_descripcion,
         :rela_socsyst10_ctm01
    do
    begin
        id_sicingr31 = id_sicingr31 - 1;
        sicingr31_moneda = 'MXN';
        sicingr31_cotiza = 1.0;

        if (sicingr31_descripcion is null) then
            sicingr31_descripcion = '';

        if (rela_socsyst10_ctm01 is not null) then
        begin
            select
            cbo_socsyst10_ctm01_cotiza.socsyst10_codigo,
            cbo_socsyst10_ctm01_cotiza.socsyst10_cotiza
            from cbo_socsyst10_ctm01_cotiza
            where cbo_socsyst10_ctm01_cotiza.id_socsyst10 = :rela_socsyst10_ctm01
            into :sicingr31_moneda,
                 :sicingr31_cotiza;
        end

        select
        count(sicingr98_det_importes.id_sicingr98),
        sum(sicingr98_det_importes.sicingr98_importe)
        from sicingr98_det_importes
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01)
        where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'CONCEP-XMARGEN'
        into :rows_importe,
             :suma_importe;

        sicingr31_importe_costo = suma_importe / rows_importe;

        if (sicingr31_importe_costo is null) then
            sicingr31_importe_costo = 0.00;

        select first 1
        sicingr90_cab_impuestos.sicingr90_tasa,
        sicingr90_cab_impuestos.sicingr90_modo
        from sicingr96_det_impuestos
        inner join sicingr90_cab_impuestos on (sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90)
        inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = sicingr90_cab_impuestos.rela_socsyst10_imp02)
        where sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_remoto.socsyst10_codigo = '002'
        into :sicingr31_iva,
             :sicingr31_factor;

        if (sicingr31_iva is null) then
            sicingr31_iva = 0.00;

        select
        max(sicingr90_cab_impuestos.sicingr90_tasa)
        from sicingr96_det_impuestos
        inner join sicingr90_cab_impuestos on (sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90)
        inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = sicingr90_cab_impuestos.rela_socsyst10_imp02)
        where sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_remoto.socsyst10_codigo = '003'
        into :sicingr31_ieps;

        if (sicingr31_ieps is null) then
            sicingr31_ieps = 0.00;

        select first 1
        socsyst12_det_cla.socsyst12_descripcion
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'CATEGORIA'
        order by sicingr97_det_clasificacion.id_sicingr97 desc
        into :sicingr31_categoria;

        select first 1
        socsyst12_det_cla.socsyst12_descripcion
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'FAMILIA'
        order by sicingr97_det_clasificacion.id_sicingr97 desc
        into :sicingr31_familia;

        select first 1
        socsyst12_det_cla.socsyst12_descripcion
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'MARCA'
        order by sicingr97_det_clasificacion.id_sicingr97 desc
        into :sicingr31_marca;

        select first 1
        socsyst12_det_cla.socsyst12_descripcion
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'MODELO'
        order by sicingr97_det_clasificacion.id_sicingr97 desc
        into :sicingr31_modelo;

        select first 1
        socsyst12_det_cla.socsyst12_descripcion
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'TALLA-MEDIDA'
        order by sicingr97_det_clasificacion.id_sicingr97 desc
        into :sicingr31_talla;

        select first 1
        socsyst12_det_cla.socsyst12_descripcion
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'COLOR-PRESENTACION'
        order by sicingr97_det_clasificacion.id_sicingr97 desc
        into :sicingr31_color;

        if (sicingr31_categoria is null) then
            sicingr31_categoria = '';

        if (sicingr31_familia is null) then
            sicingr31_familia = '';

        if (sicingr31_marca is null) then
            sicingr31_marca = '';

        if (sicingr31_modelo is null) then
            sicingr31_modelo = '';

        if (sicingr31_talla is null) then
            sicingr31_talla = '';

        if (sicingr31_color is null) then
            sicingr31_color = '';

        sicingr31_status = 'Por Procesar...';
        sicingr31_fapl = current_timestamp;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_UPDATE (
    ID_SICINGR31 BIGINT,
    RELA_SOCMAIN01 BIGINT)
AS
declare variable SICINGR31_CODIGO varchar(50);
declare variable SICINGR31_PRODUCTO varchar(400);
declare variable SICINGR31_IMPORTE double precision;
declare variable SICINGR31_IMPORTE_COSTO double precision;
declare variable SICINGR31_IVA double precision;
declare variable SICINGR31_FACTOR varchar(50);
declare variable SICINGR31_IEPS double precision;
declare variable SICINGR31_CODSAT varchar(50);
declare variable SICINGR31_UNISAT varchar(50);
declare variable SICINGR31_CTACTE varchar(50);
declare variable SICINGR31_CATEGORIA varchar(400);
declare variable SICINGR31_FAMILIA varchar(400);
declare variable SICINGR31_MARCA varchar(400);
declare variable SICINGR31_MODELO varchar(400);
declare variable SICINGR31_TALLA varchar(400);
declare variable SICINGR31_COLOR varchar(400);
declare variable ID_SICXMLS04 bigint;
declare variable ID_SICINGR95 bigint;
declare variable ID_SICCONT02 bigint;
declare variable ID_SOCSYST10_CUM01 bigint;
declare variable ID_SOCSYST10_CPO01 bigint;
declare variable STATUS varchar(400);
declare variable ID_SOCSYST10_MLI01_COSTO bigint;
declare variable ID_SICINGR90_IVA bigint;
declare variable ID_SOCSYST10_IVA bigint;
declare variable ID_SICINGR90_IEPS bigint;
declare variable ID_SOCSYST10_IEPS bigint;
begin
    select
    sicingr31_det_migracion.sicingr31_codigo,
    sicingr31_det_migracion.sicingr31_producto,
    sicingr31_det_migracion.sicingr31_importe,
    sicingr31_det_migracion.sicingr31_importe_costo,
    sicingr31_det_migracion.sicingr31_iva,
    sicingr31_det_migracion.sicingr31_factor,
    sicingr31_det_migracion.sicingr31_ieps,
    sicingr31_det_migracion.sicingr31_codsat,
    sicingr31_det_migracion.sicingr31_unisat,
    sicingr31_det_migracion.sicingr31_ctacte,
    sicingr31_det_migracion.sicingr31_categoria,
    sicingr31_det_migracion.sicingr31_familia,
    sicingr31_det_migracion.sicingr31_marca,
    sicingr31_det_migracion.sicingr31_modelo,
    sicingr31_det_migracion.sicingr31_talla,
    sicingr31_det_migracion.sicingr31_color
    from sicingr31_det_migracion
    where sicingr31_det_migracion.id_sicingr31 = :id_sicingr31
    into :sicingr31_codigo,
         :sicingr31_producto,
         :sicingr31_importe,
         :sicingr31_importe_costo,
         :sicingr31_iva,
         :sicingr31_factor,
         :sicingr31_ieps,
         :sicingr31_codsat,
         :sicingr31_unisat,
         :sicingr31_ctacte,
         :sicingr31_categoria,
         :sicingr31_familia,
         :sicingr31_marca,
         :sicingr31_modelo,
         :sicingr31_talla,
         :sicingr31_color;

    select
    prd_sicingr30_migracion_valida.id_sicxmls04,
    prd_sicingr30_migracion_valida.id_sicingr95,
    prd_sicingr30_migracion_valida.id_siccont02,
    prd_sicingr30_migracion_valida.id_socsyst10_cum01,
    prd_sicingr30_migracion_valida.id_socsyst10_cpo01,
    prd_sicingr30_migracion_valida.status,
    prd_sicingr30_migracion_valida.id_socsyst10_mli01_costo,
    prd_sicingr30_migracion_valida.id_sicingr90_iva,
    prd_sicingr30_migracion_valida.id_socsyst10_iva,
    prd_sicingr30_migracion_valida.id_sicingr90_ieps,
    prd_sicingr30_migracion_valida.id_socsyst10_ieps
    from prd_sicingr30_migracion_valida(2, /* modalidad update */
                                        :rela_socmain01,
                                        :sicingr31_codigo,
                                        :sicingr31_producto,
                                        :sicingr31_codsat,
                                        :sicingr31_unisat,
                                        :sicingr31_ctacte,
                                        :sicingr31_iva,
                                        :sicingr31_factor,
                                        :sicingr31_ieps)
    into :id_sicxmls04,
         :id_sicingr95,
         :id_siccont02,
         :id_socsyst10_cum01,
         :id_socsyst10_cpo01,
         :status,
         :id_socsyst10_mli01_costo,
         :id_sicingr90_iva,
         :id_socsyst10_iva,
         :id_sicingr90_ieps,
         :id_socsyst10_ieps;

    if (status = 'Ok.') then
    begin
        update sicxmls04_det_conceptos set sicxmls04_det_conceptos.rela_siccont02 = :id_siccont02
        where sicxmls04_det_conceptos.id_sicxmls04 = :id_sicxmls04;

        /* ================================================================================================================== */

        update sicingr95_cab_conceptos set sicingr95_cab_conceptos.rela_socsyst10_cum01 = :id_socsyst10_cum01,
                                           sicingr95_cab_conceptos.rela_socsyst10_cpo01 = :id_socsyst10_cpo01,
                                           sicingr95_cab_conceptos.sicingr95_importe = :sicingr31_importe
        where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95;

        /* ================================================================================================================== */

        update sicingr98_det_importes set sicingr98_det_importes.sicingr98_importe = :sicingr31_importe_costo
        where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95
        and sicingr98_det_importes.rela_socsyst10_mli01 = :id_socsyst10_mli01_costo;

        /* ================================================================================================================== */

        delete from sicingr96_det_impuestos
        where sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
        and exists (select first 1 sicingr90_cab_impuestos.id_sicingr90
                    from sicingr90_cab_impuestos
                    where sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90
                    and sicingr90_cab_impuestos.rela_socsyst10_imp02 = :id_socsyst10_iva);

        insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                             sicingr96_det_impuestos.rela_sicingr90 )
        values( :id_sicingr95,
                :id_sicingr90_iva );

        /* ================================================================================================================== */

        if (id_sicingr90_ieps <> 0) then
        begin
            delete from sicingr96_det_impuestos
            where sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
            and exists (select first 1 sicingr90_cab_impuestos.id_sicingr90
                        from sicingr90_cab_impuestos
                        where sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90
                        and sicingr90_cab_impuestos.rela_socsyst10_imp02 = :id_socsyst10_ieps);

            insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                                 sicingr96_det_impuestos.rela_sicingr90 )
            values( :id_sicingr95,
                    :id_sicingr90_ieps );
        end

        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'FAMILIA', :sicingr31_familia, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'CATEGORIA', :sicingr31_categoria, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'MARCA', :sicingr31_marca, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'MODELO', :sicingr31_modelo, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'TALLA-MEDIDA', :sicingr31_talla, :id_sicingr95;
        execute procedure PRD_SICINGR30_MIGRACION_CLAS 'COLOR-PRESENTACION', :sicingr31_color, :id_sicingr95;
    end

    update sicingr31_det_migracion set sicingr31_det_migracion.sicingr31_status = :status
    where sicingr31_det_migracion.id_sicingr31 = :id_sicingr31;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_VALIDA (
    MODALIDAD INTEGER,
    RELA_SOCMAIN01 BIGINT,
    SICINGR31_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_PRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_CODSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_UNISAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_CTACTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_IVA DOUBLE PRECISION,
    SICINGR31_FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR31_IEPS DOUBLE PRECISION)
RETURNS (
    STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IVA INTEGER,
    ID_SICXMLS01 BIGINT,
    ID_SICXMLS04 BIGINT,
    ID_SICINGR95 BIGINT,
    ID_SICCONT02 BIGINT,
    ID_SOCSYST10_TCT01 BIGINT,
    ID_SOCSYST10_CUM01 BIGINT,
    ID_SOCSYST10_CPO01 BIGINT,
    ID_SOCSYST10_MLI01_COSTO BIGINT,
    ID_SICINGR90_IVA BIGINT,
    ID_SOCSYST10_IVA BIGINT,
    ID_SICINGR90_IEPS BIGINT,
    ID_SOCSYST10_IEPS BIGINT)
AS
begin
    /*
        MODALIDAD = 0 (ADD)
        MODALIDAD = 2 (UPDATE)
    */
    status = '';
    id_sicxmls01 = null;

    /* ============================================================================================================ */
    /* ============================================================================================================ */
    /* ============================================================================================================ */

    select
    sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    id_socsyst10_cum01 = null;

    select
    cbo_socsyst10_cum01.id_socsyst10
    from cbo_socsyst10_cum01
    where cbo_socsyst10_cum01.socsyst10_codigo = upper(trim(:sicingr31_unisat))
    into :id_socsyst10_cum01;

    if (id_socsyst10_cum01 is null) then
        status = 'Unidad de Medida del Catalogo del SAT no se encontró.' || ASCII_CHAR(13) || ASCII_CHAR(10);

    /* ============================================================================================================ */
    
    id_socsyst10_cpo01 = null;
    
    select
    cbo_socsyst10_cpo01_find.id_socsyst10
    from cbo_socsyst10_cpo01_find(upper(trim(:sicingr31_codsat)))
    into :id_socsyst10_cpo01;
    
    if (id_socsyst10_cpo01 is null) then
        status = status || 'Código del SAT para el Producto no se encontró' || ASCII_CHAR(13) || ASCII_CHAR(10);
    
    /* ============================================================================================================ */

    id_sicxmls04 = null;

    select first 1
    sicxmls04_det_conceptos.id_sicxmls04
    from sicxmls04_det_conceptos
    where sicxmls04_det_conceptos.rela_sicxmls01 = :id_sicxmls01
    and sicxmls04_det_conceptos.sicxmls04_tipo = 'I'
    and upper(trim(sicxmls04_det_conceptos.sicxmls04_concepto)) = upper(trim(:sicingr31_producto))
    into :id_sicxmls04;

    if (id_sicxmls04 is null) then
    begin
        select first 1
        sicingr95_cab_conceptos.rela_sicxmls04
        from sicingr95_cab_conceptos
        where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01
        and upper(trim(sicingr95_cab_conceptos.sicingr95_descripcion)) = upper(trim(:sicingr31_producto))
        into : id_sicxmls04;
    end
                
    if (id_sicxmls04 is not null and modalidad = 0) then
        status = status || 'Producto Existente en Parametrizacion Contable' || ASCII_CHAR(13) || ASCII_CHAR(10);
    else if (id_sicxmls04 is null and modalidad = 2) then
        status = status || 'Producto No Encontrado en Parametrizacion Contable' || ASCII_CHAR(13) || ASCII_CHAR(10);

    /* ============================================================================================================ */

    id_sicingr95 = null;
    
    select first 1
    sicingr95_cab_conceptos.id_sicingr95
    from sicingr95_cab_conceptos
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and trim(upper(sicingr95_cab_conceptos.sicingr95_codigo)) = trim(upper(:sicingr31_codigo))
    into :id_sicingr95;
                
    if (id_sicingr95 is not null and modalidad = 0) then
        status = status || 'Producto Existente en Conceptos por Facturar' || ASCII_CHAR(13) || ASCII_CHAR(10);
    else if (id_sicingr95 is null and modalidad = 2) then
        status = status || 'Producto No Encontrado en Conceptos por Facturar' || ASCII_CHAR(13) || ASCII_CHAR(10);

    /* ============================================================================================================ */

    id_siccont02 = null;
    
    select first 1
    siccont02_arb_planctas.id_siccont02
    from siccont02_arb_planctas
    inner join siccont01_cab_planctas on (siccont01_cab_planctas.id_siccont01 = siccont02_arb_planctas.rela_siccont01)
    where siccont01_cab_planctas.rela_socmain01 = :rela_socmain01
    and trim(siccont02_arb_planctas.siccont02_codigo_ext) = trim(:sicingr31_ctacte)
    into :id_siccont02;
    
    if (id_siccont02 is null) then
        status = status || 'Cuenta Contable No encontrada' || ASCII_CHAR(13) || ASCII_CHAR(10);
    
    /* ============================================================================================================ */

    id_sicingr90_iva = null;
    
    select first 1
    SICINGR90_CAB_IMPUESTOS.rela_socsyst10_imp02,
    SICINGR90_CAB_IMPUESTOS.id_sicingr90
    from SICINGR90_CAB_IMPUESTOS
    inner join SOCSYST10_DET_REMOTO on (SOCSYST10_DET_REMOTO.id_socsyst10 = SICINGR90_CAB_IMPUESTOS.rela_socsyst10_imp02)
    where SICINGR90_CAB_IMPUESTOS.rela_sicxmls01 = :id_sicxmls01
    and SOCSYST10_DET_REMOTO.socsyst10_codigo = '002'
    and upper(trim(SICINGR90_CAB_IMPUESTOS.sicingr90_modo)) = upper(trim(:sicingr31_factor))
    and SICINGR90_CAB_IMPUESTOS.sicingr90_tasa = :sicingr31_iva
    into :id_socsyst10_iva, 
         :id_sicingr90_iva;
    
    if (id_sicingr90_iva is null) then
        status = status || 'Impuesto IVA no configurado en Impuestos Facturacion a tasa ' ||
                           :sicingr31_iva || ' factor ' || :sicingr31_factor || ASCII_CHAR(13) || ASCII_CHAR(10);
    
    /* ============================================================================================================ */

    if (sicingr31_ieps <> 0) then
    begin
        id_sicingr90_ieps = null;
    
        select first 1
        SICINGR90_CAB_IMPUESTOS.rela_socsyst10_imp02,
        SICINGR90_CAB_IMPUESTOS.id_sicingr90
        from SICINGR90_CAB_IMPUESTOS
        inner join SOCSYST10_DET_REMOTO on (SOCSYST10_DET_REMOTO.id_socsyst10 = SICINGR90_CAB_IMPUESTOS.rela_socsyst10_imp02)
        where SICINGR90_CAB_IMPUESTOS.rela_sicxmls01 = :id_sicxmls01
        and SOCSYST10_DET_REMOTO.socsyst10_codigo = '003'
        and SICINGR90_CAB_IMPUESTOS.sicingr90_tasa = :sicingr31_ieps
        into :id_socsyst10_ieps,
             :id_sicingr90_ieps;
    
        if (id_sicingr90_ieps is null) then
            status = status || 'Impuesto IEPS no configurado en Impuestos Facturacion a tasa ' || :sicingr31_ieps || ASCII_CHAR(13) || ASCII_CHAR(10);
    end

    /* ============================================================================================================ */
    /* ============================================================================================================ */
    /* ============================================================================================================ */

    if (status = '') then
    begin
        iva = 2;
        if (sicingr31_iva = 0) then
            iva = 1;

        select
        cbo_socsyst10_tct01.id_socsyst10
        from cbo_socsyst10_tct01
        where cbo_socsyst10_tct01.socsyst10_codigo = 'CLIENTE'
        into :id_socsyst10_tct01;

        select
        CBO_SOCSYST10_MLI01.id_socsyst10
        from CBO_SOCSYST10_MLI01
        where CBO_SOCSYST10_MLI01.socsyst10_codigo = 'CONCEP-XMARGEN'
        into :id_socsyst10_mli01_costo;
        
        status = 'Ok.';
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR30_MIGRACION_XML (
    RELA_SICXMLS01 BIGINT,
    TIPO INTEGER)
RETURNS (
    OK VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICXMLS04 bigint;
declare variable SICINGR31_CODIGO varchar(50);
declare variable SICINGR31_PRODUCTO varchar(400);
declare variable SICINGR31_DESCRIPCION varchar(8000);
declare variable SICINGR31_IMPORTE double precision;
declare variable SICINGR31_CODSAT varchar(50);
declare variable SICINGR31_UNISAT varchar(50);
declare variable ID_SICINGR95_FIND bigint;
declare variable ID_SOCSYST10_CUM01 bigint;
declare variable ID_SOCSYST10_CPO01 bigint;
declare variable ID_SICINGR90 bigint;
declare variable ID_SICINGR95_NEW bigint;
declare variable RELA_SOCSYST12 bigint;
declare variable RELA_SOCSYST10_CDP01 bigint;
begin
    OK = 1;
    id_sicingr90 = null;

    SELECT SICINGR90_CAB_IMPUESTOS.id_sicingr90
    FROM SICINGR90_CAB_IMPUESTOS
    INNER JOIN sicxmls02_det_impuestos ON (sicxmls02_det_impuestos.id_sicxmls02 = SICINGR90_CAB_IMPUESTOS.rela_sicxmls02)
    WHERE SICINGR90_CAB_IMPUESTOS.rela_sicxmls01 = :rela_sicxmls01
    AND sicxmls02_det_impuestos.sicxmls02_impuesto = '002'
    INTO :id_sicingr90;

    for select tmpingr30_tbl_migracion.rela_sicxmls04
    from tmpingr30_tbl_migracion
    where tmpingr30_tbl_migracion.tmpingr30_usuario =  current_user --'JAM$_ADMIN' --
    into :rela_sicxmls04
    do
    begin
        select first 1
        sicxmls42_det_conceptos.sicxmls42_noidentificacion,
        sicxmls04_det_conceptos.sicxmls04_concepto,
        sicxmls42_det_conceptos.sicxmls42_concepto,
        sicxmls42_det_conceptos.sicxmls42_unidad_valor,
        sicxmls42_det_conceptos.sicxmls42_claveprodserv,
        sicxmls42_det_conceptos.sicxmls42_unidad
        from sicxmls04_det_conceptos
        inner join sicxmls42_det_conceptos on ( sicxmls42_det_conceptos.rela_sicxmls04 = sicxmls04_det_conceptos.id_sicxmls04 )
        inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicxmls42_det_conceptos.rela_sicxmls41 )
        inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02 )
        where sicxmls04_det_conceptos.id_sicxmls04 = :rela_sicxmls04
        into :sicingr31_codigo,
             :sicingr31_producto,
             :sicingr31_descripcion,
             :sicingr31_importe,
             :sicingr31_codsat,
             :sicingr31_unisat;

        id_sicingr95_find = null;

        if (sicingr31_codigo is null or trim(sicingr31_codigo) = '' ) then
            sicingr31_codigo = 'AUT' || :rela_sicxmls04;

        select sicingr95_cab_conceptos.id_sicingr95
        from sicingr95_cab_conceptos
        where sicingr95_cab_conceptos.rela_sicxmls01 = :rela_sicxmls01
        and sicingr95_cab_conceptos.rela_sicxmls04 = :rela_sicxmls04
        into :id_sicingr95_find;

        if (id_sicingr95_find is null) then
        begin
            id_sicingr95_find = null;

            select sicingr95_cab_conceptos.id_sicingr95
            from sicingr95_cab_conceptos
            where sicingr95_cab_conceptos.rela_sicxmls01 = :rela_sicxmls01
            and sicingr95_cab_conceptos.sicingr95_codigo = :sicingr31_codigo
            into :id_sicingr95_find;

            if (id_sicingr95_find is not null) then
                sicingr31_codigo = :sicingr31_codigo || :rela_sicxmls04;

            id_socsyst10_cum01 = null;
            id_socsyst10_cpo01 = null;

            select first 1 cbo_socsyst10_cum01.id_socsyst10
            from cbo_socsyst10_cum01
            where trim(cbo_socsyst10_cum01.socsyst10_codigo) = trim(:sicingr31_unisat)
            into :id_socsyst10_cum01;

            if (id_socsyst10_cum01 is null) then
                select first 1 cbo_socsyst10_cum01.id_socsyst10
                from cbo_socsyst10_cum01
                where trim(cbo_socsyst10_cum01.socsyst10_codigo) = 'H87'
                into :id_socsyst10_cum01;

            select first 1 cbo_socsyst10_cpo01.id_socsyst10
            from cbo_socsyst10_cpo01
            where cbo_socsyst10_cpo01.socsyst10_codigo = :sicingr31_codsat
            into :id_socsyst10_cpo01;

            if (id_socsyst10_cpo01 is null) then
                select first 1 cbo_socsyst10_cpo01.id_socsyst10
                from cbo_socsyst10_cpo01
                where trim(cbo_socsyst10_cpo01.socsyst10_codigo) = '01010101'
                into :id_socsyst10_cpo01;

            insert into sicingr95_cab_conceptos( sicingr95_cab_conceptos.rela_sicxmls01,
                                                 sicingr95_cab_conceptos.rela_sicxmls04,
                                                 sicingr95_cab_conceptos.rela_socsyst10_cum01,
                                                 sicingr95_cab_conceptos.rela_socsyst10_cpo01,
                                                 sicingr95_cab_conceptos.sicingr95_codigo,
                                                 sicingr95_cab_conceptos.sicingr95_descripcion,
                                                 sicingr95_cab_conceptos.sicingr95_importe,
                                                 sicingr95_cab_conceptos.sicingr95_inactivo,
                                                 sicingr95_cab_conceptos.sicingr95_tipo,
                                                 sicingr95_cab_conceptos.sicingr95_notas )
            values(:rela_sicxmls01,
                   :rela_sicxmls04,
                   :id_socsyst10_cum01,
                   :id_socsyst10_cpo01,
                   :sicingr31_codigo,
                   :sicingr31_producto,
                   :sicingr31_importe,
                   0,
                   :tipo,
                   :sicingr31_descripcion);

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
            INTO :id_sicingr95_new;

            for select
            tmpingr31_tbl_clasificacion.rela_socsyst12,
            tmpingr31_tbl_clasificacion.rela_socsyst10_cdp01
            from tmpingr31_tbl_clasificacion
            where tmpingr31_tbl_clasificacion.tmpingr31_usuario = current_user
            into :rela_socsyst12,
                 :rela_socsyst10_cdp01
            do
            begin
                insert into sicingr97_det_clasificacion( sicingr97_det_clasificacion.rela_sicingr95,
                                                         sicingr97_det_clasificacion.rela_socsyst12,
                                                         sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
                values( :id_sicingr95_new,
                        :rela_socsyst12,
                        :rela_socsyst10_cdp01 );
            end

            if (id_sicingr90 is not null) then
            begin
                insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                                     sicingr96_det_impuestos.rela_sicingr90 )
                values( :id_sicingr95_new,
                        :id_sicingr90 );
            end
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR50_ANTICIPO (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    COTIZA DOUBLE PRECISION,
    FECHA DATE)
RETURNS (
    ID_SICCONT10 BIGINT)
AS
declare variable RELA_SOCSYST10_CTP01 bigint;
declare variable RELA_SOCSYST10_CTP02 bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable RELA_SICCONT02_DEBE bigint;
declare variable RELA_SICCONT02_HABER bigint;
declare variable ID_SOCUSUA30 bigint;
begin
    select cbo_socsyst10_ctp01.id_socsyst10
    from cbo_socsyst10_ctp01
    where cbo_socsyst10_ctp01.socsyst10_codigo = 'DROPZONE-ANTI-CLIENTE'
    into :rela_socsyst10_ctp01;

    select cbo_socsyst10_ctp02.id_socsyst10
    from cbo_socsyst10_ctp02
    where cbo_socsyst10_ctp02.socsyst10_codigo = 'PO-1-ING'
    into :rela_socsyst10_ctp02;

    select sicingr01_cab_clientes.rela_socusua30
    from sicingr01_cab_clientes
    where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
    into :ID_SOCUSUA30;

    select
    socmain05_det_bancos.rela_siccont02,
    socmain05_det_bancos.rela_socsyst10_ctm01
    from socmain05_det_bancos
    where socmain05_det_bancos.id_socmain05 = :rela_socmain05
    into :rela_siccont02_haber,
         :rela_socsyst10_ctm01;

    select SICXMLS03_DET_CUENTAS.rela_siccont02
    from sicxmls01_cab_parametros
    inner join SICXMLS03_DET_CUENTAS on (SICXMLS03_DET_CUENTAS.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICXMLS03_DET_CUENTAS.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE-ANTIC'
    into :rela_siccont02_debe;

    INSERT INTO siccont10_cab_polizas(siccont10_cab_polizas.rela_socmain01,
                                      siccont10_cab_polizas.rela_socmain21,
                                      siccont10_cab_polizas.rela_socusua01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp02,
                                      siccont10_cab_polizas.rela_socsyst10_ctm01,
                                      siccont10_cab_polizas.rela_socusua30,
                                      siccont10_cab_polizas.siccont10_tipo_entidad,
                                      siccont10_cab_polizas.siccont10_descripcion,
                                      siccont10_cab_polizas.siccont10_docnro,
                                      siccont10_cab_polizas.siccont10_fcta,
                                      siccont10_cab_polizas.siccont10_cotiza)
    VALUES(:rela_socmain01,
           :rela_socmain21,
           :rela_socusua01,
           :rela_socsyst10_ctp01,
           :rela_socsyst10_ctp02,
           :rela_socsyst10_ctm01,
           :id_socusua30,
           'C',
           :CONCEPTO,
           'XXXX',
           :fecha,
           :cotiza);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :ID_SICCONT10;

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)
    values(:id_siccont10,
           :rela_siccont02_debe,
           'S',
           '',
           0,
           :importe * :cotiza,
           -1,
           -1);

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)
    values(:id_siccont10,
           :rela_siccont02_haber,
           'S',
           '',
           :importe * :cotiza,
           0,
           -1,
           -1);

    insert into sicingr50_det_ctacte(sicingr50_det_ctacte.rela_sicingr01,
                                      sicingr50_det_ctacte.rela_socmain01,
                                      sicingr50_det_ctacte.rela_siccont10,
                                      sicingr50_det_ctacte.sicingr50_importe)
    values(:rela_sicingr01,
            :rela_socmain01,
            :id_siccont10,
            :importe * -1);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR50_ANTICIPOS (
    RELA_SICINGR50 BIGINT)
RETURNS (
    ID_SICINGR52 BIGINT,
    SICINGR52_IMPORTE DOUBLE PRECISION)
AS
declare variable SOCSYST10_CODIGO_FIND varchar(50);
declare variable RELA_SICINGR51 bigint;
begin
    FOR SELECT
    sicingr52_det_bancos.rela_sicingr51,
    sicingr52_det_bancos.id_sicingr52,
    sicingr52_det_bancos.sicingr52_importe
    FROM sicingr52_det_bancos
    INNER JOIN sicingr51_cab_bancos ON ( sicingr51_cab_bancos.id_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
    INNER JOIN sicingr50_det_ctacte ON ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
    INNER JOIN siccont10_cab_polizas ON ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
    INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
    WHERE sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
    INTO :rela_sicingr51,
         :id_sicingr52,
         :sicingr52_importe
    DO
    BEGIN
        socsyst10_codigo_find = NULL;

        select
        socsyst10_det_entradas.socsyst10_codigo
        FROM sicingr52_det_bancos
        INNER JOIN sicingr51_cab_bancos ON ( sicingr51_cab_bancos.id_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
        INNER JOIN sicingr50_det_ctacte ON ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
        INNER JOIN siccont10_cab_polizas ON ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
        INNER JOIN socsyst10_det_entradas ON ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
        WHERE sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
        AND sicingr52_det_bancos.sicingr52_importe = (:sicingr52_importe * (-1))
        AND socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-ANTI-CLIENTE'
        INTO socsyst10_codigo_find;

        if (socsyst10_codigo_find is not null) then
            suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR50_CREDITO (
    ID_SICINGR50 BIGINT,
    ID_SICCONT10 BIGINT)
RETURNS (
    ID_SICINGR51 BIGINT,
    FECHA DATE,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    POLIZA_FECHA DATE,
    IMPORTE DOUBLE PRECISION)
AS
begin
    for select SICINGR52_DET_BANCOS.rela_sicingr51
    from SICINGR52_DET_BANCOS
    inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = SICINGR52_DET_BANCOS.rela_sicingr50 )
    where SICINGR52_DET_BANCOS.rela_sicingr50 = :id_sicingr50
    and sicingr50_det_ctacte.rela_siccont10 = :id_siccont10
    into :id_sicingr51
    do
    begin
        for select
        sicingr51_cab_bancos.id_sicingr51,
        sicingr51_cab_bancos.sicingr51_fecha,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta,
        SICINGR52_DET_BANCOS.sicingr52_importe
        from SICINGR52_DET_BANCOS
        inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = SICINGR52_DET_BANCOS.rela_sicingr51 )
        inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = SICINGR52_DET_BANCOS.rela_sicingr50 )
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
        where SICINGR52_DET_BANCOS.rela_sicingr51 = :id_sicingr51
        into :id_sicingr51,
             :fecha,
             :poliza,
             :poliza_fecha,
             :importe
       do
       begin
          suspend;
       end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR50_MONEDAS
RETURNS (
    ID_SOCSYST10 BIGINT,
    MONEDA_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    FOR SELECT DISTINCT
    qry_sicingr50.rela_socsyst10_ctm01,
    qry_sicingr50.moneda_codigo,
    qry_sicingr50.moneda_descripcion
    FROM qry_sicingr50
    INTO :ID_SOCSYST10,
         :moneda_codigo,
         :moneda_descripcion
    DO
    BEGIN
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR50_SALDOS (
    RELA_SICINGR01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT)
RETURNS (
    ID_TMPINGR50 BIGINT,
    SALDO DOUBLE PRECISION)
AS
begin
    ID_TMPINGR50 = 1;

    SELECT sum(qry_sicingr50.sicingr50_importe)
    FROM qry_sicingr50
    WHERE qry_sicingr50.rela_sicingr01 = :rela_sicingr01
    AND qry_sicingr50.rela_socsyst10_ctm01 = :rela_socsyst10_ctm01
    INTO :saldo;

    if (saldo is null) then
        saldo = 0.00;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR51_CREAPOLIZAS
RETURNS (
    OK INTEGER)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SICCONT10_NEW bigint;
declare variable ID_SICCONT10_OLD bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable PORCENTAJE double precision;
declare variable RELA_SICCONT02 bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable RELA_SICCONT02_BANCO bigint;
declare variable RELA_SICCONT02_CLIENTE bigint;
declare variable PM_RELA_SOCMAIN01 bigint;
declare variable PM_RELA_SOCMAIN21 bigint;
declare variable PM_RELA_SOCUSUA01 bigint;
declare variable PM_RELA_SICINGR01 bigint;
declare variable PM_RELA_SOCMAIN05 bigint;
declare variable PM_ID_SICINGR51 bigint;
declare variable PM_SICINGR51_REFERENCIA varchar(400);
declare variable PM_SICINGR51_FECHA date;
declare variable PM_SICINGR51_COTIZA double precision;
declare variable PM_SICINGR51_IMPORTE double precision;
declare variable PM_SICINGR51_MONNAC bigint;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
declare variable RELA_SICCONT02_ANTICIPO bigint;
declare variable SICINGR50_IMPORTE_ANTICIPO double precision;
declare variable SICCONT10_UUID_SAT varchar(50);
declare variable SOCUSUA30_EXTRANJERO bigint;
declare variable SICINGR52_IMPORTE double precision;
begin
    ok = 0;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR51'
    INTO :pm_id_sicingr51;

    Select
    sicingr51_cab_bancos.rela_socmain01,
    sicingr51_cab_bancos.rela_socmain21,
    sicingr51_cab_bancos.rela_socusua01,
    sicingr51_cab_bancos.rela_sicingr01,
    sicingr51_cab_bancos.rela_socmain05,
    sicingr51_cab_bancos.sicingr51_referencia,
    sicingr51_cab_bancos.sicingr51_fecha,
    sicingr51_cab_bancos.sicingr51_cotiza,
    sicingr51_cab_bancos.sicingr51_importe,
    sicingr51_cab_bancos.sicingr51_monnac
    from sicingr51_cab_bancos
    where sicingr51_cab_bancos.id_sicingr51 = :pm_id_sicingr51
    into :pm_rela_socmain01,
         :pm_rela_socmain21,
         :pm_rela_socusua01,
         :pm_rela_sicingr01,
         :pm_rela_socmain05,
         :pm_sicingr51_referencia,
         :pm_sicingr51_fecha,
         :pm_sicingr51_cotiza,
         :pm_sicingr51_importe,
         :pm_sicingr51_monnac;

    pm_sicingr51_cotiza = iif(pm_sicingr51_cotiza is null, 1, :pm_sicingr51_cotiza);
    pm_sicingr51_monnac = iif(:pm_sicingr51_monnac is null, 0, :pm_sicingr51_monnac);

    select socusua30_cab_entidades.socusua30_extranjero
    from sicingr01_cab_clientes
    inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = sicingr01_cab_clientes.rela_socusua30 )
    where sicingr01_cab_clientes.id_sicingr01 = :pm_rela_sicingr01
    into :socusua30_extranjero;

    if (pm_sicingr51_importe IS NULL) then
        pm_sicingr51_importe = 0;

    select
    sum(sicingr50_det_ctacte.sicingr50_importe)
    from sicingr52_det_bancos
    inner join sicingr50_det_ctacte on (sicingr52_det_bancos.rela_sicingr50 = sicingr50_det_ctacte.id_sicingr50)
    inner join siccont10_cab_polizas on (sicingr50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
    inner join socsyst10_det_entradas on (siccont10_cab_polizas.rela_socsyst10_ctp01 = socsyst10_det_entradas.id_socsyst10)
    where sicingr52_det_bancos.rela_sicingr51 = :pm_id_sicingr51
    and socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-ANTI-CLIENTE'
    into :sicingr50_importe_anticipo;

    if (sicingr50_importe_anticipo IS NULL) then
        sicingr50_importe_anticipo = 0;
    else
        sicingr50_importe_anticipo = sicingr50_importe_anticipo * (-1);

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if ((pm_sicingr51_importe <> 0) or (sicingr50_importe_anticipo <> 0))then
    begin
        select sicingr01_cab_clientes.rela_socusua30
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :pm_rela_sicingr01
        into :rela_socusua30;

        select CBO_SOCSYST10_CTP01.id_socsyst10
        from CBO_SOCSYST10_CTP01
        where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-BANCOS-CLIENTE'
        into :id_socsyst10_ctp01;

        select CBO_SOCSYST10_CTP02.id_socsyst10
        from CBO_SOCSYST10_CTP02
        where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-1-ING'
        into :id_socsyst10_ctp02;

        select socmain05_det_bancos.rela_siccont02,
        socmain05_det_bancos.rela_socsyst10_ctm01
        from socmain05_det_bancos
        where socmain05_det_bancos.id_socmain05 = :pm_rela_socmain05
        into :rela_siccont02_banco,
             :id_socsyst10_ctm01;

        select sicxmls01_cab_parametros.id_sicxmls01
        from sicxmls01_cab_parametros
        where sicxmls01_cab_parametros.rela_socmain01 = :pm_rela_socmain01
        into :id_sicxmls01;

        if (socusua30_extranjero = 0) then
            select sicxmls03_det_cuentas.rela_siccont02
            from sicxmls03_det_cuentas
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
            where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
            and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE'
            into :rela_siccont02_cliente;
        else
            select sicxmls03_det_cuentas.rela_siccont02
            from sicxmls03_det_cuentas
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
            where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
            and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTEX'
            into :rela_siccont02_cliente;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                          SICCONT10_CAB_POLIZAS.rela_socmain21,
                                          SICCONT10_CAB_POLIZAS.rela_socusua01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                          SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                          SICCONT10_CAB_POLIZAS.rela_socusua30,
                                          SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                          SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                          SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                          SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                          SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :pm_rela_socmain01,
                :pm_rela_socmain21,
                :pm_rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                :rela_socusua30,
                'C',
                :pm_sicingr51_referencia,
                'xxxx',
                :pm_sicingr51_fecha,
                :pm_sicingr51_cotiza );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */
        
        if (sicingr50_importe_anticipo <> 0) then
        begin
            select sicxmls03_det_cuentas.rela_siccont02
            from sicxmls03_det_cuentas
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
            where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
            and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE-ANTIC'
            into :rela_siccont02_anticipo;

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                               siccont11_det_polizas.rela_siccont02,
                                               siccont11_det_polizas.siccont11_tipo_entidad,
                                               siccont11_det_polizas.siccont11_debe,
                                               siccont11_det_polizas.siccont11_haber,
                                               siccont11_det_polizas.siccont11_ano,
                                               siccont11_det_polizas.siccont11_mes,
                                               siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_cliente,
                   'S',
                   0,
                   :sicingr50_importe_anticipo,
                   -1,
                   -1,
                   1);

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes,
                                               siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_anticipo,
                   'S',
                   :sicingr50_importe_anticipo,
                   0,
                   -1,
                   -1,
                   1);

            pm_sicingr51_importe = sicingr50_importe_anticipo;
        end
        else if (pm_sicingr51_cotiza = 1) then
        begin
            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes,
                                              siccont11_det_polizas.siccont11_nocotiza)

            values(:id_siccont10_new,
                   :rela_siccont02_cliente,
                   'S',
                   0,
                   :pm_sicingr51_importe,
                   -1,
                   -1,
                   1);

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                      siccont11_det_polizas.rela_siccont02,
                                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                                      siccont11_det_polizas.siccont11_debe,
                                                      siccont11_det_polizas.siccont11_haber,
                                                      siccont11_det_polizas.siccont11_ano,
                                                      siccont11_det_polizas.siccont11_mes,
                                                      siccont11_det_polizas.siccont11_nocotiza)
        
                values(:id_siccont10_new,
                       :rela_siccont02_banco,
                       'S',
                       :pm_sicingr51_importe,
                       0,
                       -1,
                       -1,
                       1);
        end
    end

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if (pm_sicingr51_importe <> 0)  then
    begin
        for select
        sicingr50_det_ctacte.rela_siccont10,
        sicingr52_det_bancos.sicingr52_importe / sicingr50_det_ctacte.sicingr50_importe * 100,
        siccont10_cab_polizas.siccont10_uuid_sat,
        sicingr52_det_bancos.sicingr52_importe
        from sicingr50_det_ctacte
        inner join sicingr52_det_bancos on (sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
        where  sicingr52_det_bancos.rela_sicingr51 = :pm_id_sicingr51
        and sicingr52_det_bancos.sicingr52_importe > 0
        into :id_siccont10_old,
             :porcentaje,
             :siccont10_uuid_sat,
             :sicingr52_importe
        do
        begin
            if (pm_sicingr51_cotiza <> 1) then
                execute procedure prd_sicingr51_creapolizas_tc :id_sicxmls01,
                                                               :id_siccont10_old,
                                                               :id_siccont10_new,
                                                               :rela_siccont02_cliente,
                                                               :rela_siccont02_banco,
                                                               :pm_sicingr51_monnac,
                                                               :porcentaje,
                                                               :pm_sicingr51_cotiza,
                                                               :sicingr52_importe;

            for select
            sicxmls02_det_impuestos.rela_siccont02,
            sicxmls02_det_impuestos.rela_siccont02_ctracta,
            siccont11_det_polizas.siccont11_debe,
            siccont11_det_polizas.siccont11_haber
            from sicxmls02_det_impuestos
            inner join siccont12_mov_dropzone on (sicxmls02_det_impuestos.id_sicxmls02 = siccont12_mov_dropzone.rela_sicxmls02)
            inner join siccont11_det_polizas on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)    
            where siccont11_det_polizas.rela_siccont10 = :id_siccont10_old
            into :rela_siccont02,
                 :rela_siccont02_ctracta,
                 :siccont11_debe,
                 :siccont11_haber
            do
            begin
                if (siccont11_debe <> 0) then
                begin
                    siccont11_debe = siccont11_debe * porcentaje / 100;
                end
                else
                begin
                    siccont11_haber = siccont11_haber * porcentaje / 100;
                end

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_referencia,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes,
                                                  siccont11_det_polizas.siccont11_nocotiza)

                values(:id_siccont10_new,
                       :rela_siccont02_ctracta,
                       'S',
                       :siccont10_uuid_sat,
                       :siccont11_debe,
                       :siccont11_haber,
                       -1,
                       -1,
                       1);

                /* --------------------------------------------------------------------------------------------------------------------------- */
                /* --------------------------------------------------------------------------------------------------------------------------- */

                if (siccont11_debe <> 0) then
                begin
                    siccont11_haber = siccont11_debe;
                    siccont11_debe = 0;
                end
                else
                begin
                    siccont11_debe = siccont11_haber;
                    siccont11_haber = 0;
                end

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_referencia,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes,
                                                  siccont11_det_polizas.siccont11_nocotiza)

                values(:id_siccont10_new,
                       :rela_siccont02,
                       'S',
                       :siccont10_uuid_sat,
                       :siccont11_debe,
                       :siccont11_haber,
                       -1,
                       -1,
                       1);
            end
        end

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        if (sicingr50_importe_anticipo = 0) then
           pm_sicingr51_importe = :pm_sicingr51_importe * (-1);
        else
           pm_sicingr51_importe = 0;

        insert into sicingr50_det_ctacte(sicingr50_det_ctacte.rela_sicingr01,
                                         sicingr50_det_ctacte.rela_socmain01,
                                         sicingr50_det_ctacte.rela_siccont10,
                                         sicingr50_det_ctacte.rela_sicingr51,
                                         sicingr50_det_ctacte.sicingr50_importe)

        values( :pm_rela_sicingr01,
                :pm_rela_socmain01,
                :id_siccont10_new,
                :pm_id_sicingr51,
                :pm_sicingr51_importe);

        ok = 1;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR51_CREAPOLIZAS_TC (
    ID_SICXMLS01 BIGINT,
    ID_SICCONT10_OLD BIGINT,
    ID_SICCONT10_NEW BIGINT,
    RELA_SICCONT02_CLIENTE BIGINT,
    RELA_SICCONT02_BANCO BIGINT,
    PM_SICINGR51_MONNAC BIGINT,
    PORCENTAJE DOUBLE PRECISION,
    PM_SICINGR51_COTIZA DOUBLE PRECISION,
    SICINGR52_IMPORTE DOUBLE PRECISION)
AS
declare variable RELA_SICCONT02_COTIZA_COMP bigint;
declare variable RELA_SICCONT02_COTIZA_MAS bigint;
declare variable RELA_SICCONT02_COTIZA_MENOS bigint;
declare variable RELA_SICCONT02_COTIZA_TARIA bigint;
declare variable SUMA_COTIZA_XML double precision;
declare variable SICCONT10_COTIZA_OLD double precision;
declare variable RESULTADO_COTIZA double precision;
begin
    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-COMP'
    into :rela_siccont02_cotiza_comp;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-MAS'
    into :rela_siccont02_cotiza_mas;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-MENOS'
    into :rela_siccont02_cotiza_menos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-TARIA-CLIENTE'
    into :rela_siccont02_cotiza_taria;

    select sum(siccont11_det_polizas.siccont11_debe)
    from siccont11_det_polizas
    where siccont11_det_polizas.rela_siccont10 = :id_siccont10_old
    into :suma_cotiza_xml;

    select siccont10_cab_polizas.siccont10_cotiza
    from siccont10_cab_polizas
    where siccont10_cab_polizas.id_siccont10 = :id_siccont10_old
    into :siccont10_cotiza_old;

    suma_cotiza_xml = suma_cotiza_xml * porcentaje / 100;

    sicingr52_importe = sicingr52_importe * pm_sicingr51_cotiza;
    sicingr52_importe = sicingr52_importe * porcentaje / 100;

    resultado_cotiza = suma_cotiza_xml - sicingr52_importe;

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes,
                                                  siccont11_det_polizas.siccont11_nocotiza)

    values( :id_siccont10_new,
            :rela_siccont02_cliente,
            'S',
            0,
            :suma_cotiza_xml / :siccont10_cotiza_old,
            -1,
            -1,
            1 );
    
    insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                       siccont11_det_polizas.rela_siccont02,
                                       siccont11_det_polizas.siccont11_tipo_entidad,
                                       siccont11_det_polizas.siccont11_debe,
                                       siccont11_det_polizas.siccont11_haber,
                                       siccont11_det_polizas.siccont11_ano,
                                       siccont11_det_polizas.siccont11_mes,
                                       siccont11_det_polizas.siccont11_nocotiza )
            
    values( :id_siccont10_new,
            :rela_siccont02_cotiza_taria,
            'S',
            0,
            :suma_cotiza_xml - (:suma_cotiza_xml / :siccont10_cotiza_old),
            -1,
            -1,
            1 );


    if (pm_sicingr51_monnac <> 0) then
    begin
        select socmain05_det_bancos.rela_siccont02
        from socmain05_det_bancos
        where socmain05_det_bancos.id_socmain05 = :pm_sicingr51_monnac
        into :rela_siccont02_banco;

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                       siccont11_det_polizas.rela_siccont02,
                                       siccont11_det_polizas.siccont11_tipo_entidad,
                                       siccont11_det_polizas.siccont11_debe,
                                       siccont11_det_polizas.siccont11_haber,
                                       siccont11_det_polizas.siccont11_ano,
                                       siccont11_det_polizas.siccont11_mes,
                                       siccont11_det_polizas.siccont11_nocotiza )

        values( :id_siccont10_new,
                :rela_siccont02_banco,
                'S',
                :sicingr52_importe,
                0,
                -1,
                -1,
                1 );
    end
    else
    begin
        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
    
        values( :id_siccont10_new,
                :rela_siccont02_banco,
                'S',
                :suma_cotiza_xml / :siccont10_cotiza_old,
                0,
                -1,
                -1,
                1 );
    
        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
    
        values( :id_siccont10_new,
                :rela_siccont02_cotiza_comp,
                'S',
                :sicingr52_importe - (:suma_cotiza_xml / :siccont10_cotiza_old),
                0,
                -1,
                -1,
                1 );
    end

    if (resultado_cotiza > 0) then
    begin
        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
        
        values( :id_siccont10_new,
                :rela_siccont02_cotiza_menos,
                'S',
                :resultado_cotiza,
                0,
                -1,
                -1,
                1 );
    end
    else if (resultado_cotiza < 0) then
    begin
        resultado_cotiza = resultado_cotiza * (-1);

        insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes,
                                           siccont11_det_polizas.siccont11_nocotiza )
        
        values( :id_siccont10_new,
                :rela_siccont02_cotiza_mas,
                'S',
                0,
                :resultado_cotiza,
                -1,
                -1,
                1 );
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR51_GTOSCLIENTE (
    RELA_SICINGR50 BIGINT,
    IMPORTE DOUBLE PRECISION)
RETURNS (
    OK INTEGER)
AS
declare variable RELA_SOCMAIN01 integer;
declare variable RELA_SOCMAIN21 integer;
declare variable RELA_SOCUSUA01 integer;
declare variable ID_SICINGR50_NEW bigint;
declare variable ID_SICCONT10_NEW bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SICINGR52 bigint;
declare variable RELA_SICINGR51 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable SICCONT10_COTIZA double precision;
declare variable RELA_SICCONT02_CLIENTE bigint;
declare variable SOCUSUA30_EXTRANJERO integer;
declare variable ID_SICXMLS01 bigint;
declare variable RELA_SICINGR01 bigint;
begin
    SELECT first 1
    GRD_SICINGR50_MOV_DET.id_sicingr52
    FROM GRD_SICINGR50_MOV_DET(null,:rela_sicingr50, 0)
    where GRD_SICINGR50_MOV_DET.status = 'Cobro'
    into :id_sicingr52;

    select first 1
    sicingr52_det_bancos.rela_sicingr51,
    sicingr51_cab_bancos.rela_sicingr01
    from sicingr52_det_bancos
    inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
    where sicingr52_det_bancos.id_sicingr52 = :id_sicingr52
    into :rela_sicingr51,
         :rela_sicingr01;

    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'BANCOS-GASTOS3ROS'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-3-DIA'
    into :id_socsyst10_ctp02;

    select
    siccont10_cab_polizas.rela_socmain01,
    siccont10_cab_polizas.rela_socmain21,
    siccont10_cab_polizas.rela_socusua01,
    siccont10_cab_polizas.rela_socusua30,
    siccont10_cab_polizas.rela_socsyst10_ctm01,
    siccont10_cab_polizas.siccont10_cotiza,
    socusua30_cab_entidades.socusua30_extranjero
    from sicingr50_det_ctacte
    inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10 )
    inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = siccont10_cab_polizas.rela_socusua30 )
    where sicingr50_det_ctacte.id_sicingr50 = :rela_sicingr50
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :rela_socusua30,
         :id_socsyst10_ctm01,
         :siccont10_cotiza,
         :socusua30_extranjero;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    if (socusua30_extranjero = 0) then
        select sicxmls03_det_cuentas.rela_siccont02
        from sicxmls03_det_cuentas
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
        and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE'
        into :rela_siccont02_cliente;
    else
        select sicxmls03_det_cuentas.rela_siccont02
        from sicxmls03_det_cuentas
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
        and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTEX'
        into :rela_siccont02_cliente;

    insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.rela_socusua30,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza)
    values( :rela_socmain01,
            :rela_socmain21,
            :rela_socusua01,
            :id_socsyst10_ctp01,
            :id_socsyst10_ctp02,
            :id_socsyst10_ctm01,
            :rela_socusua30,
            'C',
            'PAGO POR CUENTA DEL CLIENTE (CAMBIAR)',
            'xxxx',
            current_date,
            :siccont10_cotiza );

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :id_siccont10_new;

    insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                       siccont11_det_polizas.rela_siccont02,
                                       siccont11_det_polizas.siccont11_tipo_entidad,
                                       siccont11_det_polizas.siccont11_referencia,
                                       siccont11_det_polizas.siccont11_debe,
                                       siccont11_det_polizas.siccont11_haber,
                                       siccont11_det_polizas.siccont11_ano,
                                       siccont11_det_polizas.siccont11_mes,
                                       siccont11_det_polizas.siccont11_nocotiza)

    values( :id_siccont10_new,
            :rela_siccont02_cliente,
            'S',
            '',
            :importe,
            0,
            -1,
            -1,
            1 );

    insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                       siccont11_det_polizas.rela_siccont02,
                                       siccont11_det_polizas.siccont11_tipo_entidad,
                                       siccont11_det_polizas.siccont11_referencia,
                                       siccont11_det_polizas.siccont11_debe,
                                       siccont11_det_polizas.siccont11_haber,
                                       siccont11_det_polizas.siccont11_ano,
                                       siccont11_det_polizas.siccont11_mes,
                                       siccont11_det_polizas.siccont11_nocotiza )

    values( :id_siccont10_new,
            :rela_siccont02_cliente,
            'S',
            '',
            0,
            :importe,
            -1,
            -1,
            1 );

    /* ------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------ */

    insert into sicingr50_det_ctacte( sicingr50_det_ctacte.rela_sicingr01,
                                      sicingr50_det_ctacte.rela_socmain01,
                                      sicingr50_det_ctacte.rela_siccont10,
                                      sicingr50_det_ctacte.sicingr50_importe )
    values( :rela_sicingr01,
            :rela_socmain01,
            :id_siccont10_new,
            :importe * (-1) );

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR50'
    INTO :id_sicingr50_new;

    insert into SICINGR52_DET_BANCOS( SICINGR52_DET_BANCOS.rela_sicingr51,
                                      SICINGR52_DET_BANCOS.rela_sicingr50,
                                      SICINGR52_DET_BANCOS.sicingr52_importe )
    values( :rela_sicingr51,
            :rela_sicingr50,
            :importe );

    insert into SICINGR52_DET_BANCOS( SICINGR52_DET_BANCOS.rela_sicingr51,
                                      SICINGR52_DET_BANCOS.rela_sicingr50,
                                      SICINGR52_DET_BANCOS.sicingr52_importe )
    values( :rela_sicingr51,
            :id_sicingr50_new,
            :importe * (-1) );

    OK = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR51_SICINGR70 (
    RELA_SICINGR70 INTEGER)
RETURNS (
    ID_SICCONT10 BIGINT,
    IMPORTE_FACTURA DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_ANTICIPOS DOUBLE PRECISION,
    IMPORTE_CTAGASTOS DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    DIFF_DIAS_BANCO INTEGER,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICINGR50 bigint;
declare variable RELA_SICINGR85 bigint;
declare variable MAXFECHA_BANCO date;
declare variable SICINGR70_FECHA date;
begin
    SELECT
    sicxmls41_det_migracion.rela_siccont10,
    sicingr70_cab_facturacion.sicingr70_fecha
    FROM sicingr70_cab_facturacion
    INNER JOIN sicingr74_dep_cfdis ON ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
    INNER JOIN sicxmls41_det_migracion ON ( sicxmls41_det_migracion.id_sicxmls41 = sicingr74_dep_cfdis.rela_sicxmls41 )
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :id_siccont10,
         :sicingr70_fecha;

    select sicingr50_det_ctacte.id_sicingr50, sicingr50_det_ctacte.sicingr50_importe
    from sicingr50_det_ctacte
    where sicingr50_det_ctacte.rela_siccont10 = :id_siccont10
    into :rela_sicingr50, importe_factura;

    select
    sum(sicingr52_det_bancos.sicingr52_importe),
    max(sicingr51_cab_bancos.sicingr51_fapl)
    from sicingr52_det_bancos
    inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
    where sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
    into :importe_banco,
         :maxfecha_banco;

    select
    sicingr88_det_gastos3ros.rela_sicingr85,
    sicingr85_cab_gastos3ros.sicingr85_referencia
    from sicingr88_det_gastos3ros
    inner join sicingr85_cab_gastos3ros on ( sicingr85_cab_gastos3ros.id_sicingr85 = sicingr88_det_gastos3ros.rela_sicingr85 )
    where sicingr88_det_gastos3ros.rela_sicingr70 = :rela_sicingr70
    into :rela_sicingr85,
         sicingr85_referencia;

    select sum(sicingr53_det_refanticipos.sicingr53_importe)
    from sicingr53_det_refanticipos
    where sicingr53_det_refanticipos.rela_sicingr85 = :rela_sicingr85
    into :importe_anticipos;

    select SUM(sicingr86_det_gastos3ros.sicingr86_importe)
    from sicingr86_det_gastos3ros
    where sicingr86_det_gastos3ros.rela_sicingr85 = :rela_sicingr85
    into :importe_ctagastos;

    if (importe_banco is null) then importe_banco = 0.00;
    if (importe_anticipos is null) then importe_anticipos = 0.00;
    if (importe_ctagastos is null) then importe_ctagastos = 0.00;

    importe_saldo = importe_anticipos - (importe_banco + importe_ctagastos);

    if (importe_banco = 0) then
        diff_dias_banco = DATEDIFF(DAY FROM sicingr70_fecha TO CURRENT_DATE);
    else
        diff_dias_banco = DATEDIFF(DAY FROM sicingr70_fecha TO maxfecha_banco);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR51_VALIDA (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    ID INTEGER,
    MENSAJE VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CADENA_MENSAJE varchar(100);
declare variable ID_SICXMLS02 bigint;
begin
    id = 0;
    id_sicxmls02 = null;
    CADENA_MENSAJE = 'Debe parametrizar ';

    SELECT FIRST 1 sicxmls02_det_impuestos.id_sicxmls02
    FROM sicxmls02_det_impuestos
    inner join sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls02_det_impuestoS.rela_sicxmls01)
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    AND (sicxmls02_det_impuestos.rela_siccont02 is null
    or sicxmls02_det_impuestos.rela_siccont02_ctracta is null)
    into :id_sicxmls02;

    if (id_sicxmls02 is not null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || ' los Impuestos y ctas de traslados.';
        suspend; 
    end

    if (id = 0) then
    BEGIN
        ID = ID + 1;
        mensaje = 'OK';
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR52_SICINGR70 (
    RELA_SICINGR70 BIGINT)
RETURNS (
    RELA_SICCONT10 BIGINT,
    ID_SICINGR70 BIGINT,
    IMPORTE_BANCOS DOUBLE PRECISION,
    IMPORTE_PAGADO DOUBLE PRECISION,
    IMPORTE_FACTURA DOUBLE PRECISION,
    IMPORTE_CTAGASTO DOUBLE PRECISION,
    IMPORTE_ANTICIPOS DOUBLE PRECISION,
    IMPORTE_ANTICIPOS_AA DOUBLE PRECISION,
    SALDO_FACTURA DOUBLE PRECISION,
    SALDO_PAGADO DOUBLE PRECISION,
    SALDO_ANTICIPOS DOUBLE PRECISION,
    SALDO_ANTICIPOS_AA DOUBLE PRECISION,
    NO_CANCELAR INTEGER)
AS
declare variable RELA_SICINGR50 bigint;
declare variable RELA_SICINGR01 bigint;
begin
    id_sicingr70 = :rela_sicingr70;
    no_cancelar = 0;
    saldo_anticipos = 0;

    select
    sicingr70_cab_facturacion.rela_sicingr01
    from sicingr70_cab_facturacion
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :rela_sicingr01;

    select
    sicxmls41_det_migracion.rela_siccont10,
    sicxmls41_det_migracion.sicxmls41_uuid_importe
    from sicingr74_dep_cfdis
    inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.id_sicxmls41 = sicingr74_dep_cfdis.rela_sicxmls41 )
    where sicingr74_dep_cfdis.rela_sicingr70 = :rela_sicingr70
    into :rela_siccont10,
         :importe_factura;

    if (rela_siccont10 is not null) then
        select
        sicingr52_det_bancos.rela_sicingr50,
        sum(sicingr52_det_bancos.sicingr52_importe)
        from sicingr52_det_bancos
        inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
        where sicingr50_det_ctacte.rela_siccont10 = :rela_siccont10
        group by sicingr50_det_ctacte.rela_sicingr01,
                 sicingr52_det_bancos.rela_sicingr50
        into :rela_sicingr50,
             :importe_bancos;

    select
    sum(sicingr52_det_bancos.sicingr52_importe)
    from sicingr52_det_bancos
    where exists ( select first 1 sicpago70_cab_pago.id_sicpago70
             from sicpago70_cab_pago
             where sicpago70_cab_pago.rela_sicingr51 = sicingr52_det_bancos.rela_sicingr51 )
    and sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
    into :importe_pagado;

    select
    sum(sicingr86_det_gastos3ros.sicingr86_importe)
    from sicingr88_det_gastos3ros
    inner join sicingr85_cab_gastos3ros on ( sicingr85_cab_gastos3ros.id_sicingr85 =  sicingr88_det_gastos3ros.rela_sicingr85 )
    inner join sicingr86_det_gastos3ros on ( sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85 )
    where sicingr88_det_gastos3ros.rela_sicingr70 = :rela_sicingr70
    group by sicingr86_det_gastos3ros.rela_sicingr85
    into :importe_ctagasto;

    select
    sum(SICINGR53_DET_REFANTICIPOS.sicingr53_importe)
    from SICINGR53_DET_REFANTICIPOS
    inner join sicingr85_cab_gastos3ros on ( sicingr85_cab_gastos3ros.id_sicingr85 = SICINGR53_DET_REFANTICIPOS.rela_sicingr85 )
    inner join sicingr88_det_gastos3ros on ( sicingr88_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85 )
    where sicingr88_det_gastos3ros.rela_sicingr70 = :rela_sicingr70
    into :importe_anticipos_aa;

    select
    sum(QRY_SICINGR52_ANTICIPOS_NO_AA.importe)
    from QRY_SICINGR52_ANTICIPOS_NO_AA
    where QRY_SICINGR52_ANTICIPOS_NO_AA.rela_sicingr01 = :rela_sicingr01
    into :importe_anticipos;

    importe_bancos = iif(importe_bancos is null, 0.00, importe_bancos);
    importe_pagado = iif(importe_pagado is null, 0.00, importe_pagado);
    importe_ctagasto = iif(importe_ctagasto is null, 0.00, importe_ctagasto);
    importe_anticipos = iif(importe_anticipos is null, 0.00, importe_anticipos);
    importe_anticipos_aa = iif(importe_anticipos_aa is null, 0.00, importe_anticipos_aa);

    saldo_factura = importe_factura - importe_bancos;
    saldo_pagado = importe_bancos - importe_pagado;

    if (importe_ctagasto <> 0 or importe_anticipos_aa <> 0) then
    begin
        saldo_anticipos_aa = (importe_factura + importe_ctagasto) - importe_anticipos_aa;
        saldo_anticipos = saldo_anticipos_aa + saldo_anticipos_aa;
    end

    if (importe_bancos != 0 or importe_pagado != 0) then
        no_cancelar = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR60_CREAPOLIZAS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    SICINGR60_IMPORTE DOUBLE PRECISION,
    SICINGR60_AJUSTE DOUBLE PRECISION,
    SICINGR60_FCTA DATE)
RETURNS (
    RELA_SICCONT10_NEW BIGINT)
AS
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable RELA_SICCONT02_BANCOS bigint;
declare variable RELA_SICCONT02_CLIENTE bigint;
declare variable RELA_SICCONT02_AJUSTE bigint;
begin
    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-DEPOSITOS'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-1-ING'
    into :id_socsyst10_ctp02;

    select cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :id_socsyst10_ctm01;

    select socmain05_det_bancos.rela_siccont02
    from socmain05_det_bancos
    where socmain05_det_bancos.id_socmain05 = :rela_socmain05
    into :rela_siccont02_bancos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE'
    into :rela_siccont02_cliente;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE-AJUSTE-DEPOSITO'
    into :rela_siccont02_ajuste;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                'S',
                'DEPOSITOS GLOBALES',
                'xxxx',
                :sicingr60_fcta,
                1);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :rela_siccont10_new;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes)

    values(:rela_siccont10_new,
           :rela_siccont02_bancos,
           'S',
           :sicingr60_importe + :sicingr60_ajuste,
           0,
           -1,
           -1);

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                          siccont11_det_polizas.rela_siccont02,
                                          siccont11_det_polizas.siccont11_tipo_entidad,
                                          siccont11_det_polizas.siccont11_debe,
                                          siccont11_det_polizas.siccont11_haber,
                                          siccont11_det_polizas.siccont11_ano,
                                          siccont11_det_polizas.siccont11_mes)

    values(:rela_siccont10_new,
           :rela_siccont02_cliente,
           'S',
           0,
           :sicingr60_importe,
           -1,
           -1);

    if (sicingr60_ajuste <> 0) then
    begin
        insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                          siccont11_det_polizas.rela_siccont02,
                                          siccont11_det_polizas.siccont11_tipo_entidad,
                                          siccont11_det_polizas.siccont11_debe,
                                          siccont11_det_polizas.siccont11_haber,
                                          siccont11_det_polizas.siccont11_ano,
                                          siccont11_det_polizas.siccont11_mes)

        values(:rela_siccont10_new,
               :rela_siccont02_ajuste,
               'S',
               0,
               :sicingr60_ajuste,
               -1,
               -1);
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR61_CREAPOLIZAS
RETURNS (
    OK INTEGER)
AS
declare variable ID_SICINGR60 bigint;
declare variable ID_SICINGR61 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SICCONT10_ORIGEN bigint;
declare variable SICCONT10_DOCNRO_ORIGINAL varchar(50);
declare variable SICINGR50_IMPORTE double precision;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable SICINGR60_FCTA date;
declare variable RELA_SICCONT10_IMPUESTOS bigint;
declare variable RELA_SICCONT02_IMPUESTOS bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
declare variable RELA_SOCMAIN01 integer;
declare variable RELA_SOCMAIN21 integer;
declare variable RELA_SOCUSUA01 integer;
declare variable SICCONT10_DOCNRO varchar(50);
declare variable SICCONT10_UUID_SMX varchar(50);
declare variable SICCONT10_UUID_SAT varchar(50);
begin
    ok = 0;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR60'
    INTO :ID_SICINGR60;

    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-DEPOSITOS'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-1-ING'
    into :id_socsyst10_ctp02;

    select cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :id_socsyst10_ctm01;

    select
    sicingr60_cab_depositos.rela_socmain01,
    sicingr60_cab_depositos.rela_socmain21,
    sicingr60_cab_depositos.rela_socusua01,
    sicingr60_cab_depositos.sicingr60_fcta,
    siccont10_cab_polizas.siccont10_docnro
    from sicingr60_cab_depositos
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr60_cab_depositos.rela_siccont10)
    where sicingr60_cab_depositos.id_sicingr60 = :id_sicingr60
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :sicingr60_fcta,
         :siccont10_docnro;

    for select
    sicingr61_det_depositos.id_sicingr61,
    sicingr50_det_ctacte.rela_sicingr01,
    sicingr50_det_ctacte.rela_siccont10,
    sicingr50_det_ctacte.sicingr50_importe,
    siccont10_cab_polizas.siccont10_docnro
    from sicingr61_det_depositos
    inner join sicingr50_det_ctacte on (sicingr50_det_ctacte.id_sicingr50 = sicingr61_det_depositos.rela_sicingr50)
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
    where sicingr61_det_depositos.rela_sicingr60 = :id_sicingr60
    into :id_sicingr61,
         :rela_sicingr01,
         :rela_siccont10_origen,
         :sicingr50_importe,
         :siccont10_docnro_original
    do
    begin
        Select siccont10_cab_polizas.rela_socusua30,
        siccont10_cab_polizas.siccont10_uuid_smx,
        siccont10_cab_polizas.siccont10_uuid_sat
        from siccont10_cab_polizas
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_origen
        into :rela_socusua30,
             :siccont10_uuid_smx,
             :siccont10_uuid_sat;

        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.rela_socusua30,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza,
                                      SICCONT10_CAB_POLIZAS.siccont10_uuid_smx,
                                      SICCONT10_CAB_POLIZAS.siccont10_uuid_sat)
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                :rela_socusua30,
                'C',
                'CRUCE DE IMPUESTOS - POLIZA NO. ' || :siccont10_docnro || ' POLIZA ORIG. NO. '|| :siccont10_docnro_original,
                'xxxx',
                :sicingr60_fcta,
                1,
                :siccont10_uuid_smx,
                :siccont10_uuid_sat);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :rela_siccont10_impuestos;

        update sicingr61_det_depositos set sicingr61_det_depositos.rela_siccont10 = :rela_siccont10_impuestos
        where sicingr61_det_depositos.id_sicingr61 = :id_sicingr61;

        insert into sicingr50_det_ctacte(sicingr50_det_ctacte.rela_sicingr01,
                                         sicingr50_det_ctacte.rela_socmain01,
                                         sicingr50_det_ctacte.rela_siccont10,
                                         sicingr50_det_ctacte.sicingr50_importe)
        values(:rela_sicingr01,
               :rela_socmain01,
               :rela_siccont10_impuestos,
               :sicingr50_importe * -1);

        for select
        sicxmls02_det_impuestos.rela_siccont02,
        sicxmls02_det_impuestos.rela_siccont02_ctracta,
        sum(siccont11_det_polizas.siccont11_debe),
        sum(siccont11_det_polizas.siccont11_haber)
        from sicxmls02_det_impuestos
        inner join siccont12_mov_dropzone on (sicxmls02_det_impuestos.id_sicxmls02 = siccont12_mov_dropzone.rela_sicxmls02)
        inner join siccont11_det_polizas on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10_origen
        group by sicxmls02_det_impuestos.rela_siccont02,
                 sicxmls02_det_impuestos.rela_siccont02_ctracta
        having (sum(siccont11_det_polizas.siccont11_debe) + sum(siccont11_det_polizas.siccont11_haber)) <> 0
        into :rela_siccont02_impuestos,
             :rela_siccont02_ctracta,
             :siccont11_debe,
             :siccont11_haber
        do
        begin
            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_impuestos,
                   :rela_siccont02_ctracta,
                   'S',
                   :siccont11_debe,
                   :siccont11_haber,
                   -1,
                   -1);


            if (siccont11_debe <> 0) then
            begin
                siccont11_haber = siccont11_debe;
                siccont11_debe = 0;
            end
            else
            begin
                siccont11_debe = siccont11_haber;
                siccont11_haber = 0;
            end

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes)

            values(:rela_siccont10_impuestos,
                   :rela_siccont02_impuestos,
                   'S',
                   :siccont11_debe,
                   :siccont11_haber,
                   -1,
                   -1);
        end
    end

    ok = 1;

    suspend;

end^


CREATE OR ALTER PROCEDURE PRD_SICINGR70_UPDATE_FECHAS (
    RELA_SICINGR70 BIGINT,
    FECHA_SICINGR70 TIMESTAMP,
    FECHA_SICINGR74 TIMESTAMP)
RETURNS (
    OK INTEGER)
AS
begin
    update sicingr70_cab_facturacion set sicingr70_cab_facturacion.sicingr70_fecha = :fecha_sicingr70
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70;

    update sicingr74_dep_cfdis set sicingr74_dep_cfdis.sicingr74_uuid_fecha = :fecha_sicingr74
    where sicingr74_dep_cfdis.rela_sicingr70 = :rela_sicingr70;

    ok = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR70_WEB (
    RELA_SICINGR70 BIGINT)
AS
declare variable RELA_SICINGR71 bigint;
declare variable ID_SICINGR72 bigint;
declare variable SICINGR72_IMPUESTO varchar(50);
declare variable SICINGR72_IMPORTE double precision;
declare variable SICINGR72_TASAOCUOTA double precision;
declare variable RESULTADO varchar(50);
declare variable ID_SOCSYST10 bigint;
declare variable ID_SICINGR75 bigint;
begin
    for select
    sicingr72_det_impuestos.rela_sicingr71,
    sicingr72_det_impuestos.id_sicingr72,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_importe,
    sicingr72_det_impuestos.sicingr72_tasaocuota
    from sicingr72_det_impuestos
    inner join sicingr71_det_facturacion on (sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    into :rela_sicingr71,
         :id_sicingr72,
         :sicingr72_impuesto,
         :sicingr72_importe,
         :sicingr72_tasaocuota
    do
    begin
        resultado = sicingr72_impuesto || '-' || CAST( cast(sicingr72_tasaocuota as integer) as varchar(6));
        id_socsyst10 = null;

        if (resultado = 'IVA-0') then
            resultado = 'IVA-00';

        select cbo_socsyst10_sat10.id_socsyst10
        from cbo_socsyst10_sat10
        where cbo_socsyst10_sat10.socsyst10_codigo = :resultado
        into :id_socsyst10;

        if (id_socsyst10 is not null) then
        begin
            id_sicingr75 = null;

            select distinct sicingr75_det_impuestos_web.id_sicingr75
            from sicingr75_det_impuestos_web
            where sicingr75_det_impuestos_web.rela_sicingr72 = :id_sicingr72
            into :id_sicingr75;

            if (id_sicingr75 is null) then
            begin
                insert into sicingr75_det_impuestos_web(sicingr75_det_impuestos_web.rela_sicingr71,
                                                        sicingr75_det_impuestos_web.rela_sicingr72,
                                                        sicingr75_det_impuestos_web.rela_socsyst10_sat10,
                                                        sicingr75_det_impuestos_web.sicingr75_porcentaje,
                                                        sicingr75_det_impuestos_web.sicingr75_total)
                values(:rela_sicingr71,
                       :id_sicingr72,
                       :id_socsyst10,
                       :sicingr72_tasaocuota,
                       :sicingr72_importe);
            end
            else
            begin
                update sicingr75_det_impuestos_web set sicingr75_det_impuestos_web.rela_socsyst10_sat10 = :id_socsyst10,
                                                       sicingr75_det_impuestos_web.sicingr75_porcentaje = :sicingr72_tasaocuota,
                                                       sicingr75_det_impuestos_web.sicingr75_total = :sicingr72_importe
                where sicingr75_det_impuestos_web.id_sicingr75 = :id_sicingr75;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR72_IMPUESTOS (
    PARAM_ID BIGINT)
RETURNS (
    IVA DOUBLE PRECISION,
    OTROS DOUBLE PRECISION,
    RETIVA DOUBLE PRECISION,
    RETISR DOUBLE PRECISION)
AS
declare variable ID_SICINGR71 bigint;
declare variable IVA1 integer;
declare variable OTROS1 integer;
declare variable RETIVA1 integer;
declare variable RETISR1 integer;
BEGIN
    IVA = 0;
    OTROS = 0;
    RETIVA = 0;
    RETISR = 0;

    for select sicingr71_det_facturacion.id_sicingr71
    FROM sicingr71_det_facturacion
    where sicingr71_det_facturacion.rela_sicingr70 = :param_id
    into :id_sicingr71
    do
    begin
        select sum(sicingr72_det_impuestos.sicingr72_importe)
        from sicingr72_det_impuestos
        where sicingr72_det_impuestos.rela_sicingr71 = :id_sicingr71
        and SICINGR72_DET_IMPUESTOS.SICINGR72_TIPO = 'Trasladado'
        and SICINGR72_DET_IMPUESTOS.SICINGR72_IMPUESTO = 'IVA'
        into :IVA1;

        IVA1 = IIF(IVA1 IS NULL, 0, IVA1);

        select sum(sicingr72_det_impuestos.sicingr72_importe)
        from sicingr72_det_impuestos
        where sicingr72_det_impuestos.rela_sicingr71 = :id_sicingr71
        and SICINGR72_DET_IMPUESTOS.SICINGR72_TIPO = 'Trasladado'
        and SICINGR72_DET_IMPUESTOS.SICINGR72_IMPUESTO <> 'IVA'
        into :OTROS1;
        
        OTROS1 = IIF(OTROS1 IS NULL, 0, OTROS1);

        select sum(sicingr72_det_impuestos.sicingr72_importe)
        from sicingr72_det_impuestos
        where sicingr72_det_impuestos.rela_sicingr71 = :id_sicingr71
        and SICINGR72_DET_IMPUESTOS.SICINGR72_TIPO = 'Retenido'
        and SICINGR72_DET_IMPUESTOS.SICINGR72_IMPUESTO = 'IVA'
        into :RETIVA1;

        RETIVA1 = IIF(RETIVA1 IS NULL, 0, RETIVA1);

        select sum(sicingr72_det_impuestos.sicingr72_importe)
        from sicingr72_det_impuestos
        where sicingr72_det_impuestos.rela_sicingr71 = :id_sicingr71
        and SICINGR72_DET_IMPUESTOS.SICINGR72_TIPO = 'Retenido'
        and SICINGR72_DET_IMPUESTOS.SICINGR72_IMPUESTO = 'ISR'
        into :RETISR1;

        RETISR1 = IIF(RETISR1 IS NULL, 0, RETISR1);

        IVA = IVA + IVA1;
        OTROS = OTROS + OTROS1;
        RETIVA = RETIVA + RETIVA1;
        RETISR = RETISR + RETISR1;

    end              



    SUSPEND;
END^


CREATE OR ALTER PROCEDURE PRD_SICINGR74 (
    RELA_SICINGR70 BIGINT,
    SICINGR74_VERSION_CFDI VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_FECHA TIMESTAMP)
RETURNS (
    ID_SICXMLS41 BIGINT)
AS
declare variable ENTIDAD varchar(1000);
declare variable RFC varchar(50);
declare variable ID_SICXMLS40 bigint;
declare variable ID_SOCSYST10_XML01 bigint;
declare variable ID_SOCSYST10_TCT01 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SICXMLS04 bigint;
declare variable RELA_SICXMLS02 bigint;
declare variable SICINGR70_SERIE varchar(50);
declare variable SICINGR70_DOCNRO varchar(50);
declare variable SICINGR70_SUBTOTAL double precision;
declare variable SICINGR70_DESCUENTO double precision;
declare variable SICINGR70_NETO double precision;
declare variable SICINGR70_CAMBIO double precision;
declare variable MONEDA varchar(50);
declare variable TCOMPR varchar(50);
declare variable MDPAGO varchar(50);
declare variable FDPAGO varchar(50);
declare variable UNIDAD varchar(400);
declare variable SICINGR71_CODIGO varchar(50);
declare variable SICINGR71_CONCEPTO varchar(8000);
declare variable SICINGR71_CANTIDAD double precision;
declare variable SICINGR71_IMPORTE_UNIDAD double precision;
declare variable SICINGR71_IMPORTE_SUBTOTAL double precision;
declare variable SICINGR72_TIPOZONA varchar(50);
declare variable SICINGR72_TIPO varchar(50);
declare variable SICINGR72_IMPUESTO varchar(50);
declare variable SICINGR72_IMPORTE double precision;
declare variable SICINGR72_TASAOCUOTA double precision;
declare variable RETENIDO integer;
declare variable LOCAL integer;
declare variable SICXMLS04_CONCEPTO varchar(400);
declare variable CONCEPTO_TMP varchar(8000);
declare variable RELA_SICXMLS01 bigint;
declare variable RELA_SOCSYST10_TCT01 bigint;
declare variable SICXMLS04_TIPO varchar(1);
declare variable RELA_SOCUSUA30_EMISOR integer;
declare variable CODPOSTAL integer;
declare variable CODPOSTAL_C varchar(50);
declare variable CLAVEPRODSERV varchar(50);
declare variable EXCENTO integer;
declare variable RELA_SICCONT02 bigint;
declare variable SICXMLS04_DEDUCIBLE integer;
declare variable SICXMLS04_UNIDAD varchar(50);
begin
    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS40'
    INTO :ID_SICXMLS40;

    select cbo_socsyst10_xml01.id_socsyst10
    from cbo_socsyst10_xml01
    where cbo_socsyst10_xml01.socsyst10_codigo = 'CLIENTE'
    INTO :id_socsyst10_xml01;

    select cbo_socsyst10_tct01.id_socsyst10
    from cbo_socsyst10_tct01
    where cbo_socsyst10_tct01.socsyst10_codigo = 'CLIENTE'
    INTO :id_socsyst10_tct01;

    select
    sicingr70_cab_facturacion.rela_sicingr01,
    sicingr70_cab_facturacion.sicingr70_serie,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_subtotal,
    sicingr70_cab_facturacion.sicingr70_descuento,
    sicingr70_cab_facturacion.sicingr70_neto,
    sicingr70_cab_facturacion.sicingr70_cambio,
    moneda.socsyst10_codigo,
    tcompr.socsyst10_codigo,
    mdpago.socsyst10_codigo,
    fdpago.socsyst10_codigo
    from sicingr70_cab_facturacion
    inner join socsyst10_det_remoto moneda on (moneda.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01 )
    inner join socsyst10_det_remoto tcompr on (tcompr.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01 )
    inner join socsyst10_det_remoto mdpago on (mdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
    inner join socsyst10_det_remoto fdpago on (fdpago.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_fdp01 )
    where sicingr70_cab_facturacion.id_sicingr70 = :rela_sicingr70
    into :rela_sicingr01,
         :sicingr70_serie,
         :sicingr70_docnro,
         :sicingr70_subtotal,
         :sicingr70_descuento,
         :sicingr70_neto,
         :sicingr70_cambio,
         :moneda,
         :tcompr,
         :mdpago,
         :fdpago;

    if (sicingr70_serie is null) then
        sicingr70_serie = '';

    select
    cbo_sicingr01_id.rela_socusua30,
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc
    from cbo_sicingr01_id
    where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
    into :rela_socusua30,
         :entidad,
         :rfc;

    if (upper(trim(rfc)) = 'XEXX010101000') then
    BEGIN
        if (tcompr = 'I') then
        BEGIN
            select cbo_socsyst10_tct01.id_socsyst10
            from cbo_socsyst10_tct01
            where cbo_socsyst10_tct01.socsyst10_codigo = 'CLIENTEX'
            INTO :id_socsyst10_tct01; 
        END
        else if (tcompr = 'E') then
        BEGIN
            select cbo_socsyst10_tct01.id_socsyst10
            from cbo_socsyst10_tct01
            where cbo_socsyst10_tct01.socsyst10_codigo = 'CREDITOENCONTRAX'
            INTO :id_socsyst10_tct01; 
        END
    END
    ELSE
    BEGIN
        if (tcompr = 'E') then
        BEGIN
            select cbo_socsyst10_tct01.id_socsyst10
            from cbo_socsyst10_tct01
            where cbo_socsyst10_tct01.socsyst10_codigo = 'CREDITOENCONTRA'
            INTO :id_socsyst10_tct01;
        END    
    END

    select socmain01_cab_empresas.rela_socusua30
    from sicxmls40_cab_migracion
    inner join socmain01_cab_empresas on ( socmain01_cab_empresas.id_socmain01 =  sicxmls40_cab_migracion.rela_socmain01 )
    where sicxmls40_cab_migracion.id_sicxmls40 = :id_sicxmls40
    into :rela_socusua30_emisor;

    codpostal = null;

    select first 1 socusua36_det_domicilios.socusua36_codpostal
    from socusua36_det_domicilios
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
    where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_emisor
    and socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
    into :codpostal;

    codpostal_c = '';

    if (codpostal is not null) then
    begin
        codpostal_c = cast(codpostal as varchar(50));
        if (char_length(codpostal_c) < 5) then
            codpostal_c = lpad(codpostal, 5, '0');
    end

    insert into sicxmls41_det_migracion(sicxmls41_det_migracion.rela_sicxmls40,
                                        sicxmls41_det_migracion.rela_socsyst10_xml01,
                                        sicxmls41_det_migracion.rela_socsyst10_tct01,
                                        sicxmls41_det_migracion.rela_socusua30,
                                        sicxmls41_det_migracion.sicxmls41_version,
                                        sicxmls41_det_migracion.sicxmls41_entidad,
                                        sicxmls41_det_migracion.sicxmls41_rfc,
                                        sicxmls41_det_migracion.sicxmls41_folio,
                                        sicxmls41_det_migracion.sicxmls41_uuid,
                                        sicxmls41_det_migracion.sicxmls41_uuid_importe,
                                        sicxmls41_det_migracion.sicxmls41_uuid_fecha,
                                        sicxmls41_det_migracion.sicxmls41_uuid_smx,
                                        sicxmls41_det_migracion.sicxmls41_tipocomprobante,
                                        sicxmls41_det_migracion.sicxmls41_metododepago,
                                        sicxmls41_det_migracion.sicxmls41_formapago,
                                        sicxmls41_det_migracion.sicxmls41_moneda,
                                        sicxmls41_det_migracion.sicxmls41_cambio,
                                        sicxmls41_det_migracion.sicxmls41_subtotal,
                                        sicxmls41_det_migracion.sicxmls41_descuento,
                                        sicxmls41_det_migracion.sicxmls41_extranjero,
                                        sicxmls41_det_migracion.sicxmls41_diferencia,
                                        sicxmls41_det_migracion.sicxmls41_fecha_pago,
                                        sicxmls41_det_migracion.sicxmls41_curp,
                                        sicxmls41_det_migracion.sicxmls41_origen,
                                        sicxmls41_det_migracion.sicxmls41_lugarexpedicion)
    values(:id_sicxmls40,
           :id_socsyst10_xml01,
           :id_socsyst10_tct01,
           :rela_socusua30,
           :sicingr74_version_cfdi,
           :entidad,
           :rfc,
           trim(:sicingr70_docnro),
           trim(upper(:sicingr74_uuid)),
           :sicingr70_neto,
           :sicingr74_uuid_fecha,
           :sicingr74_uuid_smx,
           :tcompr,
           :mdpago,
           :fdpago,
           :moneda,
           :sicingr70_cambio,
           :sicingr70_subtotal,
           :sicingr70_descuento,
           0,
           0,
           null,
           null,
           'F',
           :codpostal_c);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS41'
    INTO :ID_SICXMLS41;

    for select
    sicingr95_cab_conceptos.rela_sicxmls04,
    sicxmls04_det_conceptos.rela_sicxmls01,
    sicxmls04_det_conceptos.rela_socsyst10_tct01,
    sicxmls04_det_conceptos.sicxmls04_tipo,
    sicxmls04_det_conceptos.sicxmls04_concepto,
    cum01.socsyst10_descripcion,
    sicingr71_det_facturacion.sicingr71_codigo,
    sicingr71_det_facturacion.sicingr71_concepto,
    sicingr71_det_facturacion.sicingr71_cantidad,
    sicingr71_det_facturacion.sicingr71_importe_unidad,
    sicingr71_det_facturacion.sicingr71_importe_subtotal,
    cpo01.socsyst10_codigo,
    sicxmls04_det_conceptos.sicxmls04_excento
    from sicingr71_det_facturacion
    inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = sicingr71_det_facturacion.rela_sicingr95 )
    inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
    inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    into :rela_sicxmls04,
         :rela_sicxmls01,
         :rela_socsyst10_tct01,
         :sicxmls04_tipo,
         :sicxmls04_concepto,
         :unidad,
         :sicingr71_codigo,
         :sicingr71_concepto,
         :sicingr71_cantidad,
         :sicingr71_importe_unidad,
         :sicingr71_importe_subtotal,
         :CLAVEPRODSERV,
         :excento
    do
    begin
        concepto_tmp = trim(upper(sicingr71_concepto));
        claveprodserv = iif(:claveprodserv is null, '01010101', :claveprodserv);

        if (CHAR_LENGTH(concepto_tmp) > 400) then
            concepto_tmp = SUBSTRING (concepto_tmp FROM 1 FOR 400);

        if (concepto_tmp <> sicxmls04_concepto) then
        begin
            select
            sicxmls04_det_conceptos.rela_siccont02,
            sicxmls04_det_conceptos.sicxmls04_deducible,
            iif(sicxmls04_det_conceptos.sicxmls04_unidad is null, 'H87', sicxmls04_det_conceptos.sicxmls04_unidad)
            from sicxmls04_det_conceptos
            where sicxmls04_det_conceptos.id_sicxmls04 = :rela_sicxmls04
            into :rela_siccont02,
                 :sicxmls04_deducible,
                 :sicxmls04_unidad;

            execute procedure PRD_SICXMLS04_INSERT :rela_sicxmls01,
                                                   :rela_socsyst10_tct01,
                                                   :rela_siccont02,
                                                   :sicxmls04_tipo,
                                                   :concepto_tmp,
                                                   :excento,
                                                   :sicxmls04_deducible,
                                                   :claveprodserv,
                                                   :sicxmls04_unidad

            returning_values :RELA_SICXMLS04;
        end

        insert into sicxmls42_det_conceptos ( sicxmls42_det_conceptos.rela_sicxmls41,
                                              sicxmls42_det_conceptos.rela_sicxmls04,
                                              sicxmls42_det_conceptos.sicxmls42_concepto,
                                              sicxmls42_det_conceptos.sicxmls42_cantidad,
                                              sicxmls42_det_conceptos.sicxmls42_importe,
                                              sicxmls42_det_conceptos.sicxmls42_unidad,
                                              sicxmls42_det_conceptos.sicxmls42_unidad_valor,
                                              sicxmls42_det_conceptos.sicxmls42_noidentificacion,
                                              sicxmls42_det_conceptos.sicxmls42_claveprodserv,
                                              sicxmls42_det_conceptos.sicxmls42_excento )
        values( :id_sicxmls41,
                :rela_sicxmls04,
                :sicingr71_concepto,
                :sicingr71_cantidad,
                :sicingr71_importe_subtotal,
                :unidad,
                :sicingr71_importe_unidad,
                :sicingr71_codigo,
                :claveprodserv,
                :excento ) ;
    end

    for select
    sicingr72_det_impuestos.rela_sicxmls02,
    sicingr72_det_impuestos.sicingr72_tipozona,
    sicingr72_det_impuestos.sicingr72_tipo,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_importe,
    sicingr72_det_impuestos.sicingr72_tasaocuota
    from sicingr72_det_impuestos
    inner join sicingr71_det_facturacion on ( sicingr71_det_facturacion.id_sicingr71 = sicingr72_det_impuestos.rela_sicingr71 )
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    into :rela_sicxmls02,
         :sicingr72_tipozona,
         :sicingr72_tipo,
         :sicingr72_impuesto,
         :sicingr72_importe,
         :sicingr72_tasaocuota
    do
    begin
        retenido = 0;
        if (upper(substring( sicingr72_tipo from 1 for 1)) = 'R') then
            retenido = 1;

        local = 0;
        if (upper(substring( sicingr72_tipozona from 1 for 1)) <> 'F') then
            local = 1;

        insert into sicxmls43_det_impuestos ( sicxmls43_det_impuestos.rela_sicxmls41,
                                                 sicxmls43_det_impuestos.rela_sicxmls02,
                                                 sicxmls43_det_impuestos.sicxmls43_impuesto,
                                                 sicxmls43_det_impuestos.sicxmls43_excluir,
                                                 sicxmls43_det_impuestos.sicxmls43_importe,
                                                 sicxmls43_det_impuestos.sicxmls43_tasa,
                                                 sicxmls43_det_impuestos.sicxmls43_retenido,
                                                 sicxmls43_det_impuestos.sicxmls43_local )
         values ( :id_sicxmls41,
                  :rela_sicxmls02,
                  :sicingr72_impuesto,
                  'N',
                  :sicingr72_importe,
                  :sicingr72_tasaocuota,
                  :retenido,
                  :local );

    end
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR75_SICINGR72 (
    ACCION VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICINGR71 BIGINT,
    RELA_SICINGR72 BIGINT,
    RELA_SOCSYST10_SAT10 BIGINT,
    SICINGR75_PORCENTAJE DOUBLE PRECISION,
    SICINGR75_IMPLOCAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR75_TOTAL DOUBLE PRECISION)
RETURNS (
    ID_SICINGR72 BIGINT)
AS
declare variable RELA_SICXMLS02 bigint;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCSYST10_VALOR01 varchar(50);
declare variable SICINGR72_TIPOZONA varchar(50);
declare variable SICINGR72_TIPO varchar(50);
declare variable SICINGR72_IMPUESTO varchar(50);
declare variable SICINGR72_IMPORTE double precision;
declare variable SICINGR72_BASE double precision;
declare variable SICINGR72_TASAOCUOTA double precision;
declare variable SICINGR72_FACTOR varchar(50);
declare variable ID_SICINGR72_FIND bigint;
begin
    id_sicingr72 = :rela_sicingr72;

    select first 1 sicxmls02_det_impuestos.id_sicxmls02
    from sicxmls02_det_impuestos
    into :rela_sicxmls02;

    select 
    cbo_socsyst10_sat10.socsyst10_codigo,
    cbo_socsyst10_sat10.socsyst10_valor01
    from cbo_socsyst10_sat10
    where cbo_socsyst10_sat10.id_socsyst10 = :rela_socsyst10_sat10
    into :socsyst10_codigo,
         :socsyst10_valor01;

    /* ============================================================================================================ */

    if (position('LOCAL' in :socsyst10_codigo) = 0) then
        sicingr72_tipozona = 'Federal';
    else
        sicingr72_tipozona = 'Estatal';

    /* ============================================================================================================ */

    if (position('T' in :socsyst10_valor01) != 0) then
        sicingr72_tipo = 'Trasladado';
    else
        sicingr72_tipo = 'Retenido';

    /* ============================================================================================================ */

    if (position('LOCAL' in :socsyst10_codigo) != 0) then
    begin
        sicingr72_impuesto = sicingr75_implocal;
    end
    else
    begin
        if (position('IVA' in :socsyst10_codigo) != 0) then
            sicingr72_impuesto = 'IVA';
        else
            sicingr72_impuesto = :socsyst10_codigo;
    end

    /* ============================================================================================================ */

    sicingr72_importe = :sicingr75_total;
    sicingr72_tasaocuota = :sicingr75_porcentaje;

    select sicingr71_det_facturacion.sicingr71_importe_total
    from sicingr71_det_facturacion
    where sicingr71_det_facturacion.id_sicingr71 = :rela_sicingr71
    into :sicingr72_base;

    /* ============================================================================================================ */

    if (position('IVA-EX' in :socsyst10_codigo) != 0) then
        sicingr72_factor = 'Exento';
    else
        sicingr72_factor = 'Tasa';

    /* ============================================================================================================ */

    if (rela_sicingr72 <= 0 or rela_sicingr72 is null) then
    begin
        select sicingr72_det_impuestos.id_sicingr72
        from sicingr72_det_impuestos
        where sicingr72_det_impuestos.rela_sicingr71 = :rela_sicingr71
        and sicingr72_det_impuestos.sicingr72_tipozona = :sicingr72_tipozona
        and sicingr72_det_impuestos.sicingr72_tipo = :sicingr72_tipo
        and sicingr72_det_impuestos.sicingr72_impuesto = :sicingr72_impuesto
        and sicingr72_det_impuestos.sicingr72_importe = :sicingr72_importe
        and sicingr72_det_impuestos.sicingr72_base = :sicingr72_base
        and sicingr72_det_impuestos.sicingr72_tasaocuota = :sicingr72_tasaocuota
        and sicingr72_det_impuestos.sicingr72_factor = :sicingr72_factor
        into :id_sicingr72_find;
    
        if (id_sicingr72_find is null) then
        begin
            insert into sicingr72_det_impuestos(
                        sicingr72_det_impuestos.rela_sicingr71,
                        sicingr72_det_impuestos.rela_sicxmls02,
                        sicingr72_det_impuestos.sicingr72_tipozona,
                        sicingr72_det_impuestos.sicingr72_tipo,
                        sicingr72_det_impuestos.sicingr72_impuesto,
                        sicingr72_det_impuestos.sicingr72_importe,
                        sicingr72_det_impuestos.sicingr72_base,
                        sicingr72_det_impuestos.sicingr72_tasaocuota,
                        sicingr72_det_impuestos.sicingr72_factor)
                        values(
                            :rela_sicingr71,
                            :rela_sicxmls02,
                            :sicingr72_tipozona,
                            :sicingr72_tipo,
                            :sicingr72_impuesto,
                            :sicingr72_importe,
                            :sicingr72_base,
                            :sicingr72_tasaocuota,
                            :sicingr72_factor
                        );
        
            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR72'
            INTO :ID_SICINGR72;
        end
        else
        begin
            id_sicingr72 = :id_sicingr72_find;

            update sicingr72_det_impuestos
            set sicingr72_det_impuestos.sicingr72_tipozona = :sicingr72_tipozona,
                sicingr72_det_impuestos.sicingr72_tipo = :sicingr72_tipo,
                sicingr72_det_impuestos.sicingr72_impuesto = :sicingr72_impuesto,
                sicingr72_det_impuestos.sicingr72_importe = :sicingr72_importe,
                sicingr72_det_impuestos.sicingr72_base = :sicingr72_base,
                sicingr72_det_impuestos.sicingr72_tasaocuota = :sicingr72_tasaocuota,
                sicingr72_det_impuestos.sicingr72_factor = :sicingr72_factor
            where sicingr72_det_impuestos.id_sicingr72 = :id_sicingr72_find;
        end
    end
    else
    begin
       id_sicingr72 = :rela_sicingr72;
        
       if (accion = 'M') then
       begin
           update sicingr72_det_impuestos
           set sicingr72_det_impuestos.sicingr72_tipozona = :sicingr72_tipozona,
               sicingr72_det_impuestos.sicingr72_tipo = :sicingr72_tipo,
               sicingr72_det_impuestos.sicingr72_impuesto = :sicingr72_impuesto,
               sicingr72_det_impuestos.sicingr72_importe = :sicingr72_importe,
               sicingr72_det_impuestos.sicingr72_base = :sicingr72_base,
               sicingr72_det_impuestos.sicingr72_tasaocuota = :sicingr72_tasaocuota,
               sicingr72_det_impuestos.sicingr72_factor = :sicingr72_factor
           where sicingr72_det_impuestos.id_sicingr72 = :rela_sicingr72;
       end
       else if (accion = 'B') then
       begin
           delete from sicingr72_det_impuestos
           where sicingr72_det_impuestos.id_sicingr72 = :rela_sicingr72;
       end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR88_CREAPOLIZAS (
    ID_SICINGR70 BIGINT,
    MODO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable RELA_SICCONT02_BANCO_EMPRESA bigint;
declare variable RELA_SICCONT02_ANTICIPO bigint;
declare variable RELA_SICCONT02_GASTOS3EROS bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable SICINGR70_FECHA date;
declare variable SICINGR70_DOCNRO varchar(50);
declare variable ID_SICCONT10 bigint;
declare variable SICCONT10_DOCNRO varchar(50);
declare variable RELA_SICINGR85_PARAM bigint;
declare variable RELA_SOCMAIN05_PARAM bigint;
declare variable IMPORTE_ANTICIPOS_PARAM double precision;
declare variable IMPORTE_GASTOS_PARAM double precision;
declare variable ID_SICINGR88_PARAM bigint;
declare variable SICCONT10_COTIZA_PARAM double precision;
begin
   /* modo = 'A' CREA POLIZAS */
   /* modo = 'D' BORRA POLIZAS */

    id_sicingr88_param = null;
    importe_gastos_param = null;

    if (MODO = 'A') then
    BEGIN
        select
        sicingr88_det_gastos3ros.id_sicingr88,
        sicingr88_det_gastos3ros.rela_sicingr85,
        sicingr88_det_gastos3ros.rela_socmain05,
        sicingr88_det_gastos3ros.sicingr88_importe_cta
        from sicingr88_det_gastos3ros
        where sicingr88_det_gastos3ros.rela_sicingr70 = :id_sicingr70
        into :id_sicingr88_param,
             :rela_sicingr85_param,
             :rela_socmain05_param,
             :importe_anticipos_param;
    
        if (id_sicingr88_param is not null) then
            select sum(sicingr86_det_gastos3ros.sicingr86_importe)
            from sicingr88_det_gastos3ros
            inner join sicingr85_cab_gastos3ros on ( sicingr85_cab_gastos3ros.id_sicingr85 = sicingr88_det_gastos3ros.rela_sicingr85 )
            inner join sicingr86_det_gastos3ros on ( sicingr86_det_gastos3ros.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85 )
            where sicingr88_det_gastos3ros.rela_sicingr85 = :rela_sicingr85_param
            into :importe_gastos_param;
    
        if ((id_sicingr88_param is not null) and (importe_gastos_param is not null) and (importe_gastos_param <> 0)) then
        begin
            Select
            sicingr70_cab_facturacion.rela_socmain01,
            sicingr70_cab_facturacion.rela_socmain21,
            sicingr70_cab_facturacion.rela_socusua01,
            sicingr70_cab_facturacion.rela_sicingr01,
            sicingr70_cab_facturacion.sicingr70_fecha,
            sicingr70_cab_facturacion.sicingr70_docnro,
            sicingr70_cab_facturacion.sicingr70_cambio
            from sicingr70_cab_facturacion
            where sicingr70_cab_facturacion.id_sicingr70 = :id_sicingr70
            into :rela_socmain01,
                 :rela_socmain21,
                 :rela_socusua01,
                 :rela_sicingr01,
                 :sicingr70_fecha,
                 :sicingr70_docnro,
                 :siccont10_cotiza_param;

            /* ---------------------------------------------------------------------------------------------------------------------- */
            /* ---------------------------------------------------------------------------------------------------------------------- */
            /* ---------------------------------------------------------------------------------------------------------------------- */
        
            select sicingr01_cab_clientes.rela_socusua30
            from sicingr01_cab_clientes
            where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
            into :rela_socusua30;
        
            select CBO_SOCSYST10_CTP01.id_socsyst10
            from CBO_SOCSYST10_CTP01
            where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'BANCOS-GASTOS3ROS'
            into :id_socsyst10_ctp01;
        
            select cbo_socsyst10_ctp02.id_socsyst10
            from cbo_socsyst10_ctp02
            where cbo_socsyst10_ctp02.socsyst10_codigo = 'PO-2-EGR'
            into :id_socsyst10_ctp02;
        
            select ADUCTAG01_CAB_CTAGASTOS.rela_socsyst10_ctm01
            FROM ADUCTAG01_CAB_CTAGASTOS
            WHERE ADUCTAG01_CAB_CTAGASTOS.rela_sicingr85 = :rela_sicingr85_param
            into :id_socsyst10_ctm01;
        
            select SICXMLS03_DET_CUENTAS.rela_siccont02
            from sicxmls01_cab_parametros
            inner join SICXMLS03_DET_CUENTAS on (SICXMLS03_DET_CUENTAS.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICXMLS03_DET_CUENTAS.rela_socsyst10_tct01)
            where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
            and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE-ANTIC'
            into :rela_siccont02_anticipo;
        
            select SICXMLS03_DET_CUENTAS.rela_siccont02
            from sicxmls01_cab_parametros
            inner join SICXMLS03_DET_CUENTAS on (SICXMLS03_DET_CUENTAS.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICXMLS03_DET_CUENTAS.rela_socsyst10_tct01)
            where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
            and socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE-CTA-3RO'
            into :rela_siccont02_gastos3eros;
        
            select socmain05_det_bancos.rela_siccont02
            from socmain05_det_bancos
            where socmain05_det_bancos.id_socmain05 = :rela_socmain05_param
            into :rela_siccont02_banco_empresa;
        
            /* ---------------------------------------------------------------------------------------------------------------------- */
            /* ---------------------------------------------------------------------------------------------------------------------- */
            /* ---------------------------------------------------------------------------------------------------------------------- */
        
            insert into SICCONT10_cab_polizas( siccont10_cab_polizas.rela_socmain01,
                                               siccont10_cab_polizas.rela_socmain21,
                                               siccont10_cab_polizas.rela_socusua01,
                                               siccont10_cab_polizas.rela_socsyst10_ctp01,
                                               siccont10_cab_polizas.rela_socsyst10_ctp02,
                                               siccont10_cab_polizas.rela_socsyst10_ctm01,
                                               siccont10_cab_polizas.rela_socusua30,
                                               siccont10_cab_polizas.siccont10_tipo_entidad,
                                               siccont10_cab_polizas.siccont10_docnro,
                                               siccont10_cab_polizas.siccont10_fcta,
                                               siccont10_cab_polizas.siccont10_descripcion,
                                               siccont10_cab_polizas.siccont10_cotiza,
                                               siccont10_cab_polizas.siccont10_origen )
            values( :rela_socmain01,
                    :rela_socmain21,
                    :rela_socusua01,
                    :id_socsyst10_ctp01,
                    :id_socsyst10_ctp02,
                    :id_socsyst10_ctm01,
                    :rela_socusua30,
                    'C',
                    'XXX',
                    current_date,
                    'GASTOS POR CUENTA DEL CIENTE (REF.FACTURA:' || :sicingr70_docnro || ' FECHA:' || :sicingr70_fecha || ')',
                    :siccont10_cotiza_param,
                    'G' );
        
            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
            INTO :ID_SICCONT10;
        
            select siccont10_cab_polizas.siccont10_docnro
            from siccont10_cab_polizas
            where siccont10_cab_polizas.id_siccont10 = :id_siccont10
            into :siccont10_docnro;
        
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_gastos3eros,
                   'S',
                   :importe_gastos_param,
                   0,
                   -1,
                   -1);
        
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_banco_empresa,
                   'S',
                   0,
                   :importe_gastos_param,
                   -1,
                   -1);
        
            INSERT INTO sicingr50_det_ctacte( sicingr50_det_ctacte.rela_sicingr01,
                                              sicingr50_det_ctacte.rela_socmain01,
                                              sicingr50_det_ctacte.rela_siccont10,
                                              sicingr50_det_ctacte.sicingr50_importe)
            VALUES( :rela_sicingr01,
                    :rela_socmain01,
                    :id_siccont10,
                    :importe_gastos_param);
        
            insert into sicingr89_det_polizas( sicingr89_det_polizas.rela_sicingr88,
                                               sicingr89_det_polizas.rela_siccont10 )
            values ( :id_sicingr88_param, :id_siccont10 );
        
            /* ---------------------------------------------------------------------------------------------------------------------- */
            /* ---------------------------------------------------------------------------------------------------------------------- */
            /* ---------------------------------------------------------------------------------------------------------------------- */
        
            if (importe_anticipos_param <> 0) then
            begin
                insert into siccont10_cab_polizas( siccont10_cab_polizas.rela_socmain01,
                                                       siccont10_cab_polizas.rela_socmain21,
                                                       siccont10_cab_polizas.rela_socusua01,
                                                       siccont10_cab_polizas.rela_socsyst10_ctp01,
                                                       siccont10_cab_polizas.rela_socsyst10_ctp02,
                                                       siccont10_cab_polizas.rela_socsyst10_ctm01,
                                                       siccont10_cab_polizas.rela_socusua30,
                                                       siccont10_cab_polizas.siccont10_tipo_entidad,
                                                       siccont10_cab_polizas.siccont10_docnro,
                                                       siccont10_cab_polizas.siccont10_fcta,
                                                       siccont10_cab_polizas.siccont10_descripcion,
                                                       siccont10_cab_polizas.siccont10_cotiza,
                                                       siccont10_cab_polizas.siccont10_origen )
                    values( :rela_socmain01,
                            :rela_socmain21,
                            :rela_socusua01,
                            :id_socsyst10_ctp01,
                            :id_socsyst10_ctp02,
                            :id_socsyst10_ctm01,
                            :rela_socusua30,
                            'C',
                            'XXX',
                            current_date,
                            'HONORARIOS GASTOS POR CUENTA DEL CLIENTE REF. POLIZA : ' || :siccont10_docnro,
                            :siccont10_cotiza_param,
                            'G' );
                
                    select socsyst91_tbl_ultids.socsyst91_ultid
                    from socsyst91_tbl_ultids
                    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
                    INTO :ID_SICCONT10;
                
                    INSERT INTO siccont11_det_polizas(
                                siccont11_det_polizas.rela_siccont10,
                                siccont11_det_polizas.rela_siccont02,
                                siccont11_det_polizas.siccont11_tipo_entidad,
                                siccont11_det_polizas.siccont11_debe,
                                siccont11_det_polizas.siccont11_haber,
                                siccont11_det_polizas.siccont11_ano,
                                siccont11_det_polizas.siccont11_mes)
                    VALUES(:ID_SICCONT10,
                           :rela_siccont02_anticipo,
                           'S',
                           :importe_anticipos_param,
                           0,
                           -1,
                           -1);
                
                    INSERT INTO siccont11_det_polizas(
                                siccont11_det_polizas.rela_siccont10,
                                siccont11_det_polizas.rela_siccont02,
                                siccont11_det_polizas.siccont11_tipo_entidad,
                                siccont11_det_polizas.siccont11_debe,
                                siccont11_det_polizas.siccont11_haber,
                                siccont11_det_polizas.siccont11_ano,
                                siccont11_det_polizas.siccont11_mes)
                    VALUES(:ID_SICCONT10,
                           :rela_siccont02_gastos3eros,
                           'S',
                           0,
                           :importe_anticipos_param,
                           -1,
                           -1);
        
                    insert into sicingr89_det_polizas( sicingr89_det_polizas.rela_sicingr88,
                                                       sicingr89_det_polizas.rela_siccont10 )
                    values ( :id_sicingr88_param, :id_siccont10 );
            end
        end
    END
    elsE if (MODO = 'D') then
    BEGIN
        select
        sicingr88_det_gastos3ros.id_sicingr88
        from sicingr88_det_gastos3ros
        where sicingr88_det_gastos3ros.rela_sicingr70 = :id_sicingr70
        into :id_sicingr88_param;

        if (id_sicingr88_param is not null) then
            delete from sicingr89_det_polizas where sicingr89_det_polizas.rela_sicingr88 = :id_sicingr88_param;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_ADD (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCSYST10_CUM01 BIGINT,
    RELA_SOCSYST10_CPO01 BIGINT,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICINGR95 BIGINT,
    SICINGR95_FAPL TIMESTAMP)
AS
declare variable RELA_SICXMLS01 bigint;
declare variable RELA_SICXMLS04 bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
begin
    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :rela_sicxmls01;

    select first 1 sicxmls04_det_conceptos.id_sicxmls04
    from sicxmls04_det_conceptos
    into :rela_sicxmls04;

    select first 1 cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :rela_socsyst10_ctm01;


    insert into sicingr95_cab_conceptos(
        sicingr95_cab_conceptos.rela_sicxmls01,
        sicingr95_cab_conceptos.rela_sicxmls04,
        sicingr95_cab_conceptos.rela_socsyst10_cum01,
        sicingr95_cab_conceptos.rela_socsyst10_cpo01,
        sicingr95_cab_conceptos.rela_socsyst10_ctm01,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion,
        sicingr95_cab_conceptos.sicingr95_importe,
        sicingr95_cab_conceptos.sicingr95_tipo)
    values(:rela_sicxmls01,
           :rela_sicxmls04,
           :rela_socsyst10_cum01,
           :rela_socsyst10_cpo01,
           :rela_socsyst10_ctm01,
           'SMXAUTO',
           :concepto,
           1.0,
           0);

    select
    socsyst91_tbl_ultids.socsyst91_ultid,
    socsyst91_tbl_ultids.socsyst91_fapl
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
    INTO :id_sicingr95,
         :sicingr95_fapl;

  suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_FIND (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_PYMVENT10 BIGINT,
    RELA_PYMVENT50 BIGINT,
    VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICINGR95 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_IMPORTE DOUBLE PRECISION,
    STOCK DOUBLE PRECISION,
    REGLA_XPRODUCTO DOUBLE PRECISION,
    SERVICIOS INTEGER,
    MONEDA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_PYMVENT10 bigint;
declare variable ID_SOCSYST10_MONEDA bigint;
declare variable PYMVENT52_COTIZA double precision;
begin
    id_pymvent10 = null;

    select pymvent10_cab_listaprecios.id_pymvent10
    from pymvent10_cab_listaprecios
    where pymvent10_cab_listaprecios.id_pymvent10 = :rela_pymvent10
    into :id_pymvent10;

    valor = upper(trim(valor));

    for select
    SICINGR95_CAB_CONCEPTOS.ID_SICINGR95,
    SICINGR95_CAB_CONCEPTOS.sicingr95_codigo,
    SICINGR95_CAB_CONCEPTOS.sicingr95_descripcion,
    SICINGR95_CAB_CONCEPTOS.sicingr95_importe
    from SICINGR95_CAB_CONCEPTOS
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = SICINGR95_CAB_CONCEPTOS.rela_sicxmls01 )
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and (SICINGR95_CAB_CONCEPTOS.sicingr95_inactivo is null or SICINGR95_CAB_CONCEPTOS.sicingr95_inactivo = 0)
    and (UPPER(TRIM(SICINGR95_CAB_CONCEPTOS.sicingr95_codigo)) LIKE :valor || '%'
    OR UPPER(TRIM(SICINGR95_CAB_CONCEPTOS.sicingr95_descripcion)) LIKE '%' || :valor || '%')
    AND EXISTS (
         select first 1 socsyst12_det_cla.id_socsyst12
         from sicingr97_det_clasificacion
         inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
         inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
         where sicingr97_det_clasificacion.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95
         and socsyst10_det_entradas.socsyst10_codigo = 'FAMILIA'
         and socsyst12_det_cla.socsyst12_descripcion <> 'PROCESOS'
    )

    INTO :ID_SICINGR95,
         :sicingr95_codigo,
         :sicingr95_descripcion,
         :sicingr95_importe
    DO
    BEGIN
        stock = null;
        regla_xproducto = 0.00;
        id_socsyst10_moneda = null;
        moneda = 'MXN';

        if (rela_pymvent50 is not null and rela_pymvent50 <> -1) then
        begin
            select
            socsyst10_det_remoto.id_socsyst10,
            socsyst10_det_remoto.socsyst10_codigo
            from sicingr95_cab_conceptos
            inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_ctm01 )
            where sicingr95_cab_conceptos.id_sicingr95 = :ID_SICINGR95
            into :id_socsyst10_moneda,
                 :moneda;
        
            if (id_socsyst10_moneda is not null) then
            begin
                pymvent52_cotiza = null;

                SELECT pymvent52_det_cotizacion.pymvent52_cotiza
                FROM pymvent52_det_cotizacion
                WHERE pymvent52_det_cotizacion.rela_pymvent50 = :rela_pymvent50
                AND pymvent52_det_cotizacion.rela_socsyst10_ctm01 = :id_socsyst10_moneda
                INTO :pymvent52_cotiza;

                if (pymvent52_cotiza is null) then
                begin
                    pymvent52_cotiza = 1;
                end
                else
                begin
                    moneda = moneda || '-$ ' || cast(pymvent52_cotiza as numeric(6,2));
                end

                sicingr95_importe = sicingr95_importe * pymvent52_cotiza;
            end
            else
            begin
                moneda = 'MXN';
            end
        end

        select sum(pymalma02_det_stock.pymalma02_cantidad)
        from pymalma02_det_stock
        inner join pymalma01_cab_stock on (pymalma01_cab_stock.id_pymalma01 = pymalma02_det_stock.rela_pymalma01)
        where pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
        and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
        into :stock;

        if (stock is null) then
            stock = 0.00;

        if (id_pymvent10 is not null) then
        begin
            select pymvent11_det_xproductos.pymvent11_importe
            from pymvent11_det_xproductos
            where pymvent11_det_xproductos.rela_pymvent10 = :id_pymvent10
            and pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95
            into :regla_xproducto;

            if (regla_xproducto is null) then
                regla_xproducto = 0.00;
        end

        servicios = null;

        select first 1 sicingr97_det_clasificacion.id_sicingr97
        from sicingr97_det_clasificacion
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'SERVICIO'
        into :servicios;

        if (servicios is null) then
            servicios = 0;
        else
            servicios = 1;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_IEPS (
    RELA_SOCMAIN01 BIGINT,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE NUMERIC(18,4))
RETURNS (
    ID INTEGER,
    IMPORTE_SIN_IEPS NUMERIC(18,4),
    IMPORTE_SIN_IEPS_IVA NUMERIC(18,4),
    IMPORTE_CON_IEPS NUMERIC(18,4))
AS
declare variable DBLIEPS numeric(18,4);
begin
    id = 1;
    dblIeps = null;
    importe_sin_ieps = importe;
    importe_sin_ieps_iva = importe;
    importe_con_ieps = importe;

    select sicingr90_cab_impuestos.sicingr90_tasa
    from sicingr90_cab_impuestos
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicingr90_cab_impuestos.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and trim(upper(sicingr90_cab_impuestos.sicingr90_codigo)) = trim(upper(:sicingr95_codigo))
    into :dblIeps;

    if (dblIeps is not null) then
    begin
        importe_sin_ieps = importe - dblIeps;
        importe_sin_ieps_iva = importe_sin_ieps / 1.16;
    
        importe_con_ieps = importe_sin_ieps_iva + dblIeps;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_IMPUESTOS (
    ID_SICINGR95 BIGINT,
    IMPORTE DOUBLE PRECISION)
RETURNS (
    ID_SICXMLS02 BIGINT,
    SOCSYST10_CODIGO_IMPUESTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_CODIGO_CALCULO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR90_TIPOZONA VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR90_TASA DECIMAL(18,2),
    SICINGR95_IMPORTE DECIMAL(18,2),
    SICXMLS02_RETENIDO INTEGER,
    IMPORTE_CALCULADO DECIMAL(18,2))
AS
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable COTIZA double precision;
begin
    /*
        socsyst10_codigo_impuesto
        -------------------------
        001 = ISR
        002 = IVA
        003 = IEPS
        004 = ISH (LOCAL)
        005 = IMCD (LOCAL)

        socsyst10_codigo_calculo
        ------------------------
        SCONCEPTO = Se calcula sobre el Importe del Producto o Servicio
        SIVA      = Se calcula sobre el importe del IVA

        sicxmls04_excento
        -----------------
        0 = Exento
        1 = IVA 0%
        2 = IVA 16%
    */

    if (importe is null) then
    begin
        select
        sicingr95_cab_conceptos.rela_socsyst10_ctm01,
        sicingr95_cab_conceptos.sicingr95_importe
        from sicingr95_cab_conceptos
        inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
        where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95
        into :rela_socsyst10_ctm01,
             :sicingr95_importe;
    end
    else
    begin
        select
        sicingr95_cab_conceptos.rela_socsyst10_ctm01
        from sicingr95_cab_conceptos
        inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
        where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95
        into :rela_socsyst10_ctm01;

        sicingr95_importe = cast(importe as decimal(18,2));
    end

    cotiza = 1;

    if (rela_socsyst10_ctm01 is not null) then
    begin
        select first 1 pymvent52_det_cotizacion.pymvent52_cotiza
        from pymvent52_det_cotizacion
        where pymvent52_det_cotizacion.rela_socsyst10_ctm01 = :rela_socsyst10_ctm01
        order by pymvent52_det_cotizacion.id_pymvent52 desc
        into :cotiza;

        cotiza = iif(cotiza is null, 1, cotiza);
    end

    sicingr95_importe = sicingr95_importe * cotiza;

    for select
    sicxmls02_det_impuestos.id_sicxmls02,
    sicxmls02_det_impuestos.sicxmls02_retenido,
    imp02.socsyst10_codigo,
    mci01.socsyst10_codigo,
    sicingr90_cab_impuestos.sicingr90_tipozona,
    sicingr90_cab_impuestos.sicingr90_tasa
    from sicingr96_det_impuestos
    inner join sicingr90_cab_impuestos on ( sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90 )
    inner join socsyst10_det_remoto imp02 on ( imp02.id_socsyst10 = SICINGR90_CAB_IMPUESTOS.rela_socsyst10_imp02 )
    inner join socsyst10_det_entradas mci01 on ( mci01.id_socsyst10 = sicingr90_cab_impuestos.rela_socsyst10_mci01 )
    inner join sicxmls02_det_impuestos on ( sicxmls02_det_impuestos.id_sicxmls02 = sicingr90_cab_impuestos.rela_sicxmls02 )
    where sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95
    into :id_sicxmls02,
         :sicxmls02_retenido,
         :socsyst10_codigo_impuesto,
         :socsyst10_codigo_calculo,
         :sicingr90_tipozona,
         :sicingr90_tasa
    do
    begin
        importe_calculado = 0;
        if (socsyst10_codigo_calculo = 'SCONCEPTO' and (sicingr95_importe <> 0 and sicingr90_tasa <> 0)) then
        begin
            importe_calculado = cast((sicingr95_importe * sicingr90_tasa / 100) as decimal(18,2));
        end

        suspend;
    end

    if (id_sicxmls02 is null) then
    begin
        id_sicxmls02 = -1;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_IMPUESTOS_CALCULO (
    ID_SICINGR95X BIGINT,
    IMPORTE DOUBLE PRECISION)
RETURNS (
    ID_SICINGR95 BIGINT,
    IMPORTE_IMPUESTOS DECIMAL(18,2),
    IMPORTE_PRODUCTO DECIMAL(18,2),
    IMPORTE_NETO DECIMAL(18,2))
AS
declare variable IMPORTE_IEPS decimal(18,2);
declare variable IMPORTE_CALCULADO decimal(18,2);
declare variable SOCSYST10_CODIGO_IMPUESTO varchar(50);
declare variable SOCSYST10_CODIGO_CALCULO varchar(50);
declare variable SICXMLS02_RETENIDO integer;
declare variable SICINGR90_TASA decimal(15,4);
begin
    /*
        socsyst10_codigo_impuesto
        -------------------------
        001 = ISR
        002 = IVA
        003 = IEPS
        004 = ISH (LOCAL)
        005 = IMCD (LOCAL)

        socsyst10_codigo_calculo
        ------------------------
        SCONCEPTO = Se calcula sobre el Importe del Producto o Servicio
        SIVA      = Se calcula sobre el importe del IVA

        sicxmls04_excento
        -----------------
        0 = Exento
        1 = IVA 0%
        2 = IVA 16%
    */
    id_sicingr95 = id_sicingr95x;
    importe_impuestos = 0;

    select
    sum(prd_sicingr95_impuestos.importe_calculado)
    from prd_sicingr95_impuestos(:id_sicingr95x, :importe)
    where prd_sicingr95_impuestos.socsyst10_codigo_impuesto = '003'
    into :importe_ieps;

    if (importe_ieps is null) then
        importe_ieps = 0.00;

    for select
    prd_sicingr95_impuestos.socsyst10_codigo_impuesto,
    prd_sicingr95_impuestos.socsyst10_codigo_calculo,
    prd_sicingr95_impuestos.importe_calculado,
    prd_sicingr95_impuestos.sicxmls02_retenido,
    prd_sicingr95_impuestos.sicingr90_tasa,
    prd_sicingr95_impuestos.sicingr95_importe
    from prd_sicingr95_impuestos(:id_sicingr95x, :importe)
    where prd_sicingr95_impuestos.socsyst10_codigo_impuesto <> '003'
    into :socsyst10_codigo_impuesto,
         :socsyst10_codigo_calculo,
         :importe_calculado,
         :sicxmls02_retenido,
         :sicingr90_tasa,
         :importe_producto
    do
    begin
        if ( (socsyst10_codigo_impuesto = '002' and socsyst10_codigo_calculo = 'SCONCEPTO') and
             (sicxmls02_retenido = 0 and sicingr90_tasa <> 0 and importe_ieps <> 0) ) then
        begin
            importe_calculado = cast( ((importe_producto + importe_ieps) * sicingr90_tasa / 100) as decimal(18,2) );
        end

        if (sicxmls02_retenido = 1) then
            importe_calculado = importe_calculado * (-1);

        importe_impuestos = importe_impuestos + importe_calculado;
    end

    if (importe_producto is null) then
        importe_producto = 0.00;

    if (importe_impuestos is null) then
        importe_impuestos = 0.00;

    importe_neto = importe_producto + importe_impuestos;

    if (importe_neto = 0) then
    begin
        select sicingr95_cab_conceptos.sicingr95_importe
        from sicingr95_cab_conceptos
        where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95x
        into :importe_producto;

        importe_neto = importe_producto;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_PARAMETRIZAR (
    ID_SOCMAIN01 BIGINT,
    ID_SOCSYST10_CPO01 BIGINT,
    ID_SOCSYST10_CUM01 BIGINT,
    FILTRO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    STATUS INTEGER)
AS
declare variable CON_SELECCION integer;
declare variable IMPORTE double precision;
declare variable ID_SICXMLS04 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable CONCEPTO varchar(800);
declare variable ID_SICINGR90 bigint;
declare variable ID_SICINGR95NEW bigint;
begin
    FILTRO = UPPER(trim(FILTRO));
    CON_SELECCION = null;

    select first 1 sicxmls10_tmp_sicxmls04.id_sicxmls10
    from sicxmls10_tmp_sicxmls04
    where sicxmls10_tmp_sicxmls04.sicxmls10_usuario = current_user
    into :con_seleccion;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    into :id_sicxmls01;

    if (CON_SELECCION IS NULL) then
    BEGIN
        for select
        GRD_SICINGR95_SICXMLS04.id_sicxmls04,
        GRD_SICINGR95_SICXMLS04.sicxmls04_concepto,
        GRD_SICINGR95_SICXMLS04.importe
        from GRD_SICINGR95_SICXMLS04
        where GRD_SICINGR95_SICXMLS04.rela_socmain01 = :id_socmain01
        and (GRD_SICINGR95_SICXMLS04.siccont02_codigo_ext || GRD_SICINGR95_SICXMLS04.siccont02_descripcion ||
             GRD_SICINGR95_SICXMLS04.siccont02_codagrup || GRD_SICINGR95_SICXMLS04.socsyst10_descripcion ||
             GRD_SICINGR95_SICXMLS04.sicxmls04_concepto || GRD_SICINGR95_SICXMLS04.tipo) like '%' || :FILTRO || '%'
        into :id_sicxmls04,
             :concepto,
             :importe
        do
        begin
            insert into sicingr95_cab_conceptos( sicingr95_cab_conceptos.rela_sicxmls01,
                                                 sicingr95_cab_conceptos.rela_sicxmls04,
                                                 sicingr95_cab_conceptos.rela_socsyst10_cum01,
                                                 sicingr95_cab_conceptos.rela_socsyst10_cpo01,
                                                 sicingr95_cab_conceptos.sicingr95_codigo,
                                                 sicingr95_cab_conceptos.sicingr95_descripcion,
                                                 sicingr95_cab_conceptos.sicingr95_importe)
            values( :id_sicxmls01,
                    :id_sicxmls04,
                    :id_socsyst10_cum01,
                    :id_socsyst10_cpo01,
                    'AUT' || :id_sicxmls04,
                    :concepto,
                    :importe);


            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
            INTO :id_sicingr95new;

            for select
            sicxmls11_tmp_sicingr90.sicxmls11_sicingr90
            from sicxmls11_tmp_sicingr90
            where sicxmls11_tmp_sicingr90.sicxmls11_usuario = current_user
            into :id_sicingr90
            do
            begin
                insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                                     sicingr96_det_impuestos.rela_sicingr90)
                values(:id_sicingr95new,
                       :id_sicingr90);
            end
        end

        status = 1;
        suspend;
    END
    ELSE
    BEGIN
        for select
        sicxmls10_tmp_sicxmls04.sicxmls10_sicxmls04,
        sicxmls10_tmp_sicxmls04.sicxmls10_concepto,
        sicxmls10_tmp_sicxmls04.sicxmls10_importe
        from sicxmls10_tmp_sicxmls04
        where sicxmls10_tmp_sicxmls04.sicxmls10_usuario = current_user
        into :id_sicxmls04,
             :concepto,
             :importe
        do
        begin
            insert into sicingr95_cab_conceptos( sicingr95_cab_conceptos.rela_sicxmls01,
                                                 sicingr95_cab_conceptos.rela_sicxmls04,
                                                 sicingr95_cab_conceptos.rela_socsyst10_cum01,
                                                 sicingr95_cab_conceptos.rela_socsyst10_cpo01,
                                                 sicingr95_cab_conceptos.sicingr95_codigo,
                                                 sicingr95_cab_conceptos.sicingr95_descripcion,
                                                 sicingr95_cab_conceptos.sicingr95_importe)
            values( :id_sicxmls01,
                    :id_sicxmls04,
                    :id_socsyst10_cum01,
                    :id_socsyst10_cpo01,
                    'AUT' || :id_sicxmls04,
                    :concepto,
                    :importe);


            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
            INTO :id_sicingr95new;

            for select
            sicxmls11_tmp_sicingr90.sicxmls11_sicingr90
            from sicxmls11_tmp_sicingr90
            where sicxmls11_tmp_sicingr90.sicxmls11_usuario = current_user
            into :id_sicingr90
            do
            begin
                insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                                     sicingr96_det_impuestos.rela_sicingr90)
                values(:id_sicingr95new,
                       :id_sicingr90);
            end
        end

        status = 1;
        suspend;
    END
    
    delete from sicxmls10_tmp_sicxmls04 where sicxmls10_tmp_sicxmls04.sicxmls10_usuario = current_user;
    delete from sicxmls11_tmp_sicingr90 where sicxmls11_tmp_sicingr90.sicxmls11_usuario = current_user;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_PYMVENT71 (
    RELA_SOCMAIN01 BIGINT,
    RELA_PYMVENT50 INTEGER,
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR95 BIGINT,
    CANTIDAD DOUBLE PRECISION)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    RELA_SICINGR95 BIGINT,
    ID_PYMVENT71 BIGINT,
    PYMVENT71_ORDEN INTEGER,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_COSTO NUMERIC(15,2),
    PYMVENT71_IMPORTE_UNIDAD NUMERIC(15,2),
    PYMVENT71_IMPORTE_UNIDADR NUMERIC(15,2),
    PYMVENT71_IMPORTE_SUBTOTAL NUMERIC(15,2),
    PYMVENT71_IMPORTE_DESCUENTO NUMERIC(15,2),
    PYMVENT71_IMPORTE_TOTAL NUMERIC(15,2),
    PYMVENT71_IMPORTE_IMPUESTOS NUMERIC(15,2),
    PYMVENT71_IMPORTE_RETENIDO NUMERIC(15,2),
    PYMVENT71_IMPORTE_TRASLADO NUMERIC(15,2),
    PYMVENT71_IMPORTE_LOCALES NUMERIC(15,2),
    PYMVENT71_IMPORTE_NETO NUMERIC(15,2),
    PYMVENT71_CANCELADO INTEGER,
    PYMVENT71_STATUS_PRECIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_FAPL TIMESTAMP)
AS
declare variable SQL_C varchar(1000);
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable PYMVENT52_COTIZA double precision;
declare variable RELA_SOCMAIN21 bigint;
declare variable IMPORTE_REGLASDENEGOCIO double precision;
declare variable PYMVENT01_REGLAS_NEGO integer;
begin
    id_pymvent71 = 0;

    if (id_sicingr95 is not null) then
        sql_c = 'select sicingr95_cab_conceptos.id_sicingr95, ' ||
                'sicingr95_cab_conceptos.rela_socsyst10_ctm01, ' ||
                'sicingr95_cab_conceptos.sicingr95_codigo, ' ||
                'sicingr95_cab_conceptos.sicingr95_descripcion,' ||
                'sicingr95_cab_conceptos.sicingr95_importe ' ||
                'from sicingr95_cab_conceptos ' ||
                'inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 ) ' ||
                'where sicxmls01_cab_parametros.rela_socmain01 = ' || :rela_socmain01 ||
                ' and sicingr95_cab_conceptos.id_sicingr95 = ' || :id_sicingr95;
    else if (codigo is not null) then
        sql_c = 'select sicingr95_cab_conceptos.id_sicingr95, ' ||
                'sicingr95_cab_conceptos.rela_socsyst10_ctm01, ' ||
                'sicingr95_cab_conceptos.sicingr95_codigo, ' ||
                'sicingr95_cab_conceptos.sicingr95_descripcion, ' ||
                'sicingr95_cab_conceptos.sicingr95_importe ' ||
                'from sicingr95_cab_conceptos ' ||
                'inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 ) ' ||
                'where sicxmls01_cab_parametros.rela_socmain01 = ' || :rela_socmain01 ||
                ' and upper(sicingr95_cab_conceptos.sicingr95_codigo) = ''' || upper(:codigo) || '''';

    execute statement :sql_c
    into :rela_sicingr95,
         :rela_socsyst10_ctm01,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_importe_unidad;

    /* ------------------------------------------------------------- */

    if (rela_sicingr95 is not null) then
    begin
        if (rela_socsyst10_ctm01 is not null) then
        begin
            pymvent52_cotiza = null;
    
            SELECT pymvent52_det_cotizacion.pymvent52_cotiza
            FROM pymvent52_det_cotizacion
            WHERE pymvent52_det_cotizacion.rela_pymvent50 = :rela_pymvent50
            AND pymvent52_det_cotizacion.rela_socsyst10_ctm01 = :rela_socsyst10_ctm01
            INTO :pymvent52_cotiza;
    
            if (pymvent52_cotiza is null) then
                pymvent52_cotiza = 1;
    
            pymvent71_importe_unidad = pymvent71_importe_unidad * pymvent52_cotiza;
        end
    
        /* ------------------------------------------------------------- */
    
        pymvent71_importe_descuento = 0.00;
        pymvent71_importe_unidadr = :pymvent71_importe_unidad;
        pymvent71_status_precio = 'Sin Modificación';
        importe_reglasdenegocio = null;

        /* ------------------------------------------------------------- */

        select first 1
        pymvent50_cab_apertura.rela_socmain21,
        pymvent01_cab_cajas.pymvent01_reglas_nego
        from pymvent50_cab_apertura
        inner join pymvent01_cab_cajas on ( pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01 )
        where pymvent50_cab_apertura.id_pymvent50 = :rela_pymvent50
        into :rela_socmain21,
             :pymvent01_reglas_nego;

        if (pymvent01_reglas_nego = 1) then
        begin
            select
            PRD_SICINGR95_REGLASDENEGOCIO.importe,
            PRD_SICINGR95_REGLASDENEGOCIO.status_regla
            from PRD_SICINGR95_REGLASDENEGOCIO(:rela_socmain01, :rela_socmain21, :rela_sicingr95)
            into :importe_reglasdenegocio,
                 :pymvent71_status_precio;
    
            if (importe_reglasdenegocio is not null) then
            begin
                pymvent71_importe_descuento = (pymvent71_importe_unidad - importe_reglasdenegocio) * cantidad;
            end
        end

        /* ------------------------------------------------------------- */
    
        rela_pymvent70 = -1;
        pymvent71_orden = 0;
        id_pymvent71 = id_pymvent71 - 1;
        pymvent71_importe_impuestos = 0;
        pymvent71_importe_retenido = 0;
        pymvent71_importe_traslado = 0;
        pymvent71_importe_locales = 0;
        pymvent71_importe_neto = 0;
        pymvent71_cancelado = 0;
        pymvent71_fapl = current_timestamp;
        pymvent71_importe_costo = null;
    
        pymvent71_cantidad = :cantidad;
        pymvent71_importe_subtotal = pymvent71_cantidad * pymvent71_importe_unidad;
        pymvent71_importe_total = pymvent71_importe_subtotal - pymvent71_importe_descuento;
    
        /* ------------------------------------------------------------- */
    
        select
        sum(sicingr98_det_importes.sicingr98_importe) / count(sicingr98_det_importes.id_sicingr98)
        from sicingr98_det_importes
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01 )
        where sicingr98_det_importes.rela_sicingr95 = :rela_sicingr95
        and socsyst10_det_entradas.socsyst10_codigo = 'CONCEP-XMARGEN'
        into :pymvent71_importe_costo;
    
        if (pymvent71_importe_costo is null) then
            pymvent71_importe_costo = :pymvent71_importe_unidadr;
    
        /* ------------------------------------------------------------- */
    
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_REGLASDENEGOCIO (
    RELA_SOCMAIN01X BIGINT,
    RELA_SOCMAIN21X INTEGER,
    RELA_SICINGR95X BIGINT)
RETURNS (
    IMPORTE NUMERIC(15,2),
    STATUS_REGLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PUNTOS DOUBLE PRECISION,
    REGLA1_CANTIDAD_STOCK INTEGER,
    REGLA1_CANTIDAD_VENTA INTEGER,
    REGLA2_SICINGR95 BIGINT,
    REGLA2_MINIMO INTEGER,
    REGLA2_REGALO INTEGER)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SICINGR95_REGALO bigint;
declare variable ID_PYMVENT16 bigint;
declare variable PYMVENT15_REGLA integer;
declare variable PYMVENT15_PORCENTAJE double precision;
declare variable PYMVENT15_VOL_STOCK double precision;
declare variable PYMVENT15_VOL_VENTA double precision;
declare variable PYMVENT15_STOCKCERO integer;
declare variable PYMVENT15_SEMANA varchar(50);
declare variable PYMVENT15_REGALO double precision;
declare variable PYMVENT15_PUNTOS double precision;
declare variable PYMVENT16_STOCK double precision;
declare variable PYMVENT16_STOCK_CONT double precision;
declare variable PYMVENT15_REGALO_MIN double precision;
declare variable VALIDA_SEMANA integer;
begin
    status_regla = 'Sin Modificación';

    select first 1
    pymvent15_cab_xreglas.rela_socmain21,
    pymvent15_cab_xreglas.rela_sicingr95,
    pymvent16_det_xreglas_p.id_pymvent16,
    pymvent16_det_xreglas_p.pymvent16_stock,
    pymvent16_det_xreglas_p.pymvent16_stock_cont,
    pymvent15_cab_xreglas.pymvent15_regla,
    pymvent15_cab_xreglas.pymvent15_porcentaje,
    pymvent15_cab_xreglas.pymvent15_vol_stock,
    pymvent15_cab_xreglas.pymvent15_vol_venta,
    pymvent15_cab_xreglas.pymvent15_stockcero,
    pymvent15_cab_xreglas.pymvent15_semana,
    pymvent15_cab_xreglas.pymvent15_regalo,
    pymvent15_cab_xreglas.pymvent15_puntos,
    pymvent15_cab_xreglas.pymvent15_regalo_min,
    sicingr95_cab_conceptos.sicingr95_importe
    from pymvent16_det_xreglas_p
    inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = pymvent16_det_xreglas_p.rela_sicingr95 )
    inner join pymvent15_cab_xreglas on ( pymvent15_cab_xreglas.id_pymvent15 = pymvent16_det_xreglas_p.rela_pymvent15 )
    where pymvent15_cab_xreglas.rela_socmain01 = :rela_socmain01x
    and pymvent16_det_xreglas_p.rela_sicingr95 = :rela_sicingr95x
    and pymvent15_cab_xreglas.pymvent15_fvto >= current_date
    order by pymvent16_det_xreglas_p.id_pymvent16 desc
    into :rela_socmain21,
         :rela_sicingr95_regalo,
         :id_pymvent16,
         :pymvent16_stock,
         :pymvent16_stock_cont,
         :pymvent15_regla,
         :pymvent15_porcentaje,
         :pymvent15_vol_stock,
         :pymvent15_vol_venta,
         :pymvent15_stockcero,
         :pymvent15_semana,
         :pymvent15_regalo,
         :pymvent15_puntos,
         :pymvent15_regalo_min,
         :importe;

    if (id_pymvent16 is not null) then
    begin
        puntos = pymvent15_puntos;

        SELECT prd_pymvent15_semana.valida
        FROM prd_pymvent15_semana(:pymvent15_semana)
        INTO :valida_semana;

        if (valida_semana = 1) then
        begin
            if (pymvent15_stockcero = 0 or ( pymvent15_stockcero = 1 and (pymvent16_stock_cont < pymvent16_stock)) ) then
            begin
                if (rela_socmain21 is null or (rela_socmain21 = rela_socmain21x) ) then
                begin
                    /* 0 = Por Porcentaje */
                    if (pymvent15_regla = 0) then
                    begin
                        status_regla = 'Regla #0 por Porcentaje ' || cast(:pymvent15_porcentaje as numeric(5,2));
                        importe = importe - (importe * pymvent15_porcentaje / 100);
                    end

                    /* 1 = Por Promoción Eje. 3x2 */
                    else if (pymvent15_regla = 1) then
                    begin
                        status_regla = 'Regla #1 por Promocion Lleva: ' || cast(:pymvent15_vol_stock as numeric(10,0)) ||
                                       ' Paga: ' || cast(:pymvent15_vol_venta as numeric(10,0));
                        regla1_cantidad_stock = pymvent15_vol_stock;
                        regla1_cantidad_venta = pymvent15_vol_venta;
                    end

                    /* 2 = Por Regalo */
                    else if (pymvent15_regla = 2) then
                    begin
                        select sicingr95_cab_conceptos.sicingr95_descripcion
                        from sicingr95_cab_conceptos
                        where sicingr95_cab_conceptos.id_sicingr95 = :rela_sicingr95_regalo
                        into :status_regla;

                        if (char_length(status_regla) > 50) then
                            status_regla = SUBSTRING (status_regla FROM 1 FOR 50);

                        regla2_sicingr95 = rela_sicingr95_regalo;
                        regla2_minimo =  pymvent15_regalo_min;
                        regla2_regalo = pymvent15_regalo;

                        status_regla = 'Regla #2 por Regalo Min: ' || regla2_minimo ||
                                       ' Cant: ' || regla2_regalo || ' ' ||   trim(status_regla);
                    end
                end
            end
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_REPLICACION (
    MODALIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    OK INTEGER)
AS
declare variable ID_SOCMAIN01 bigint;
declare variable ID_SICINGR95 bigint;
begin
    modalidad = upper(trim(modalidad));

    for select
    tmpingr95_tbl_replicacion.rela_socmain01,
    tmpingr95_tbl_replicacion.rela_sicingr95
    from tmpingr95_tbl_replicacion
    where tmpingr95_tbl_replicacion.tmpingr95_usuario = current_user
    into :id_socmain01,
         :id_sicingr95
    do
    begin
        if (modalidad = 'A') then
        begin
            execute procedure prd_sicingr95_replicacion_alta :id_sicingr95, id_socmain01;
        end
        else if (modalidad = 'M') then
        begin
            execute procedure prd_sicingr95_replicacion_modi :id_sicingr95, id_socmain01;
        end
    end

    ok = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_REPLICACION_ALTA (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SOCMAIN01_DESTINO BIGINT)
AS
declare variable SICINGR95_CODIGO_ORIGEN varchar(50);
declare variable SICCONT02_CODIGO_ORIGEN varchar(50);
declare variable ID_SICINGR95_DESTINO bigint;
declare variable ID_SICXMLS01_DESTINO bigint;
declare variable ID_SICXMLS01_ORIGEN integer;
declare variable ID_SICCONT02_DESTINO bigint;
declare variable ID_SICXMLS04_ORIGEN bigint;
declare variable ID_SICXMLS04_DESTINO bigint;
declare variable SICXMLS04_CONCEPTO_ORIGEN varchar(400);
declare variable ID_SOCMAIN01_ORIGEN bigint;
declare variable RELA_SOCSYST10_LPR01_ORIGEN bigint;
declare variable PYMVENT10_PORCENTAJE_ORIGEN double precision;
declare variable ID_PYMVENT10_DESTINO bigint;
declare variable ID_PYMVENT10_ORIGEN bigint;
declare variable ID_SICINGR90_DESTINO bigint;
declare variable SICXMLS02_IMPUESTO varchar(400);
declare variable SICXMLS02_TIPO varchar(1);
declare variable SICXMLS02_RETENIDO integer;
declare variable SICXMLS02_TASA double precision;
declare variable RELA_SOCSYST10_MLI01 bigint;
declare variable SICINGR98_IMPORTE double precision;
declare variable SICINGR98_FECHA_APLICACION timestamp;
declare variable SICINGR98_FECHA_VENCIMIENTO timestamp;
declare variable SICINGR98_MARGEN double precision;
declare variable SICINGR98_MODALIDAD integer;
declare variable CLAVEPRODSERV varchar(50);
declare variable UNIDAD varchar(50);
declare variable SICXMLS04_TIPO varchar(10);
declare variable SICXMLS04_EXCENTO integer;
declare variable SICXMLS04_DEDUCIBLE integer;
declare variable RELA_SOCSYST10_TCT01 bigint;
begin
    /* ----------------------------- */
    /* valores de la empresa origen  */
    /* ----------------------------- */

    select
    sicxmls04_det_conceptos.rela_socsyst10_tct01,
    sicxmls04_det_conceptos.id_sicxmls04,
    sicxmls04_det_conceptos.rela_sicxmls01,
    sicxmls01_cab_parametros.rela_socmain01,
    upper(trim(sicxmls04_det_conceptos.sicxmls04_concepto)),
    upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)),
    upper(trim(siccont02_arb_planctas.siccont02_codigo_ext)),
    cpo01.socsyst10_codigo,
    cum01.socsyst10_codigo,
    sicxmls04_det_conceptos.sicxmls04_tipo,
    sicxmls04_det_conceptos.sicxmls04_excento,
    sicxmls04_det_conceptos.sicxmls04_deducible
    from sicingr95_cab_conceptos
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls04_det_conceptos.rela_sicxmls01 )
    inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02 )
    inner join socsyst10_det_remoto cpo01 on ( cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
    inner join socsyst10_det_remoto cum01 on ( cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
    where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen
    into :rela_socsyst10_tct01,
         :id_sicxmls04_origen,
         :id_sicxmls01_origen,
         :id_socmain01_origen,
         :sicxmls04_concepto_origen,
         :sicingr95_codigo_origen,
         :siccont02_codigo_origen,
         :claveprodserv,
         :unidad,
         :sicxmls04_tipo,
         :sicxmls04_excento,
         :sicxmls04_deducible;

    /* ----------------------------------------------- */
    /* Producto Destino - debe no existir para seguir  */
    /* lo busco sólo por el código.                    */
    /* ----------------------------------------------- */

    select
    sicingr95_cab_conceptos.id_sicingr95
    from sicingr95_cab_conceptos
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04 )
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls04_det_conceptos.rela_sicxmls01 )
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    and upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)) = :sicingr95_codigo_origen
    into :id_sicingr95_destino;

    /* ----------------------------------------------- */
    /* Busco la Parametrización de la Empresa Destino  */
    /* ----------------------------------------------- */

    select
    sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    into :id_sicxmls01_destino;

    /* -------------------------------------------------- */
    /* Busco el Concepto Contable en la Empresa Destino   */
    /* a través de la Descripcion del Producto. Si existe */
    /* no debo agregar al producto porque existe ya       */
    /* -------------------------------------------------- */

    select
    sicxmls04_det_conceptos.id_sicxmls04
    from sicxmls01_cab_parametros
    inner join sicxmls04_det_conceptos on ( sicxmls04_det_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01 )
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    and upper(trim(sicxmls04_det_conceptos.sicxmls04_concepto)) = :sicxmls04_concepto_origen
    into :id_sicxmls04_destino;

    /* -------------------------------------------------- */
    /* Busco la cuenta Contable en la Empresa Destino     */
    /* comparandolo con el Codigo con la empresa Origen   */
    /* Si no existe no lo dejo pasar                      */
    /* -------------------------------------------------- */
    select first 1 siccont02_arb_planctas.id_siccont02
    from siccont02_arb_planctas
    inner join siccont01_cab_planctas on ( siccont01_cab_planctas.id_siccont01 = siccont02_arb_planctas.rela_siccont01)
    where siccont01_cab_planctas.rela_socmain01 = :id_socmain01_destino
    and trim(upper(siccont02_arb_planctas.siccont02_codigo_ext)) = :siccont02_codigo_origen
    into :id_siccont02_destino;

    /* --------------------------------------------------------------------------------------------------------------------- */

    if ((id_sicingr95_destino is null and id_sicxmls04_destino is null) and
        (id_siccont02_destino is not null and id_sicxmls01_destino is not null) ) then
    begin
        execute procedure PRD_SICXMLS04_INSERT :id_sicxmls01_destino,
                                               :rela_socsyst10_tct01,
                                               :id_siccont02_destino,
                                               :sicxmls04_tipo,
                                               :sicxmls04_concepto_origen,
                                               :sicxmls04_excento,
                                               :sicxmls04_deducible,
                                               :claveprodserv,
                                               :unidad
        returning_values :id_sicxmls04_destino;

        /* --------------------------------------------------------------------------------------------------------------------- */

        insert into sicingr95_cab_conceptos ( sicingr95_cab_conceptos.rela_sicxmls01,
                                              sicingr95_cab_conceptos.rela_sicxmls04,
                                              sicingr95_cab_conceptos.rela_socsyst10_cum01,
                                              sicingr95_cab_conceptos.rela_socsyst10_cpo01,
                                              sicingr95_cab_conceptos.sicingr95_codigo,
                                              sicingr95_cab_conceptos.sicingr95_descripcion,
                                              sicingr95_cab_conceptos.sicingr95_predial,
                                              sicingr95_cab_conceptos.sicingr95_importe,
                                              sicingr95_cab_conceptos.sicingr95_notas )
        select
        :id_sicxmls01_destino,
        :id_sicxmls04_destino,
        sicingr95_cab_conceptos.rela_socsyst10_cum01,
        sicingr95_cab_conceptos.rela_socsyst10_cpo01,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion,
        sicingr95_cab_conceptos.sicingr95_predial,
        sicingr95_cab_conceptos.sicingr95_importe,
        sicingr95_cab_conceptos.sicingr95_notas
        FROM sicingr95_cab_conceptos
        WHERE sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen;

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
        INTO :id_sicingr95_destino;

        /* --------------------------------------------------------------------------------------------------------------------- */

        insert into sicingr97_det_clasificacion( sicingr97_det_clasificacion.rela_sicingr95,
                                                 sicingr97_det_clasificacion.rela_socsyst12,
                                                 sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
        select
        :id_sicingr95_destino,
        sicingr97_det_clasificacion.rela_socsyst12,
        sicingr97_det_clasificacion.rela_socsyst10_cdp01
        from sicingr97_det_clasificacion
        where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95_origen;

        /* ---------------------------- */
        /* IMPORTES                     */
        /* ---------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------- */

        for select
        sicingr98_det_importes.rela_socsyst10_mli01,
        sicingr98_det_importes.sicingr98_importe,
        sicingr98_det_importes.sicingr98_fecha_aplicacion,
        sicingr98_det_importes.sicingr98_fecha_vencimiento,
        sicingr98_det_importes.sicingr98_margen,
        sicingr98_det_importes.sicingr98_modalidad
        from sicingr98_det_importes
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01 )
        where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95_origen
        and socsyst10_det_entradas.socsyst10_codigo <> 'CONCEP-REF'
        into :rela_socsyst10_mli01,
             :sicingr98_importe,
             :sicingr98_fecha_aplicacion,
             :sicingr98_fecha_vencimiento,
             :sicingr98_margen,
             :sicingr98_modalidad
        do
        begin
            insert into sicingr98_det_importes( sicingr98_det_importes.rela_sicingr95,
                                                sicingr98_det_importes.rela_socsyst10_mli01,
                                                sicingr98_det_importes.sicingr98_importe,
                                                sicingr98_det_importes.sicingr98_fecha_aplicacion,
                                                sicingr98_det_importes.sicingr98_fecha_vencimiento,
                                                sicingr98_det_importes.sicingr98_margen,
                                                sicingr98_det_importes.sicingr98_modalidad )
            values( :id_sicingr95_destino,
                    :rela_socsyst10_mli01,
                    :sicingr98_importe,
                    :sicingr98_fecha_aplicacion,
                    :sicingr98_fecha_vencimiento,
                    :sicingr98_margen,
                    :sicingr98_modalidad );

        end

        /* ---------------------------- */
        /* LISTA DE PRECIOS             */
        /* ---------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------- */

        for select
        pymvent10_cab_listaprecios.id_pymvent10,
        pymvent10_cab_listaprecios.rela_socsyst10_lpr01,
        pymvent10_cab_listaprecios.pymvent10_porcentaje
        from pymvent10_cab_listaprecios
        where pymvent10_cab_listaprecios.rela_socmain01 = :id_socmain01_origen
        and exists ( select first 1 pymvent11_det_xproductos.id_pymvent11
                     from pymvent11_det_xproductos
                     where pymvent11_det_xproductos.rela_pymvent10 = pymvent10_cab_listaprecios.id_pymvent10
                     and pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95_origen
                    )
        into :id_pymvent10_origen,
             :rela_socsyst10_lpr01_origen,
             :pymvent10_porcentaje_origen
        do
        begin
            id_pymvent10_destino = null;

            select
            pymvent10_cab_listaprecios.id_pymvent10
            from pymvent10_cab_listaprecios
            where pymvent10_cab_listaprecios.rela_socmain01 = :id_socmain01_destino
            and pymvent10_cab_listaprecios.rela_socsyst10_lpr01 = :rela_socsyst10_lpr01_origen
            into :id_pymvent10_destino;

            if (id_pymvent10_destino is null) then
            begin
                insert into pymvent10_cab_listaprecios( pymvent10_cab_listaprecios.rela_socmain01,
                                                        pymvent10_cab_listaprecios.rela_socsyst10_lpr01,
                                                        pymvent10_cab_listaprecios.pymvent10_porcentaje )
                values( :id_socmain01_destino,
                        :rela_socsyst10_lpr01_origen,
                        :pymvent10_porcentaje_origen );

                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMVENT10'
                INTO :id_pymvent10_destino;
            end

            insert into  pymvent11_det_xproductos( pymvent11_det_xproductos.rela_pymvent10,
                                                   pymvent11_det_xproductos.rela_sicingr95,
                                                   pymvent11_det_xproductos.pymvent11_importe )
            select
            :id_pymvent10_destino,
            :id_sicingr95_destino,
            pymvent11_det_xproductos.pymvent11_importe
            from pymvent11_det_xproductos
            where pymvent11_det_xproductos.rela_pymvent10 = :id_pymvent10_origen
            and pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95_origen;
        end

        /* ---------------------------- */
        /* IMPUESTOS                    */
        /* ---------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------- */

        for select
        upper(trim(sicxmls02_det_impuestos.sicxmls02_impuesto)),
        sicxmls02_det_impuestos.sicxmls02_tipo,
        sicxmls02_det_impuestos.sicxmls02_retenido,
        sicxmls02_det_impuestos.sicxmls02_tasa
        from sicingr96_det_impuestos
        inner join sicingr90_cab_impuestos on ( sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90 )
        inner join sicxmls02_det_impuestos on ( sicxmls02_det_impuestos.id_sicxmls02 = sicingr90_cab_impuestos.rela_sicxmls02 )
        where sicingr90_cab_impuestos.rela_sicxmls01 = :id_sicxmls01_origen
        and sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95_origen
        into :sicxmls02_impuesto,
             :sicxmls02_tipo,
             :sicxmls02_retenido,
             :sicxmls02_tasa
        do
        begin
            id_sicingr90_destino = null;

            select first 1 sicingr90_cab_impuestos.id_sicingr90
            from sicingr90_cab_impuestos
            inner join sicxmls02_det_impuestos on ( sicxmls02_det_impuestos.id_sicxmls02 = sicingr90_cab_impuestos.rela_sicxmls02 )
            where sicingr90_cab_impuestos.rela_sicxmls01 = :id_sicxmls01_destino
            and upper(trim(sicxmls02_det_impuestos.sicxmls02_impuesto)) = :sicxmls02_impuesto
            and sicxmls02_det_impuestos.sicxmls02_tipo = :sicxmls02_tipo
            and sicxmls02_det_impuestos.sicxmls02_retenido = :sicxmls02_retenido
            and sicxmls02_det_impuestos.sicxmls02_tasa = :sicxmls02_tasa
            into :id_sicingr90_destino;

            if (id_sicingr90_destino is not null) then
            begin
                insert into sicingr96_det_impuestos( sicingr96_det_impuestos.rela_sicingr95,
                                                     sicingr96_det_impuestos.rela_sicingr90 )
                values( :id_sicingr95_destino,
                        :id_sicingr90_destino );
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_REPLICACION_MODI (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SOCMAIN01_DESTINO BIGINT)
AS
declare variable SICINGR95_CODIGO varchar(50);
declare variable SICINGR95_DESCRIPCION varchar(400);
declare variable SICINGR95_PREDIAL varchar(50);
declare variable SICINGR95_IMPORTE double precision;
declare variable SICINGR95_NOTAS varchar(8000);
declare variable ID_SICXMLS01_DESTINO bigint;
declare variable ID_SICINGR95_DESTINO bigint;
declare variable RELA_SOCSYST10_MLI01 bigint;
declare variable SICINGR98_IMPORTE double precision;
declare variable SICINGR98_FECHA_APLICACION timestamp;
declare variable SICINGR98_FECHA_VENCIMIENTO timestamp;
declare variable SICINGR98_MARGEN double precision;
declare variable SICINGR98_MODALIDAD integer;
declare variable ID_SICINGR98 bigint;
declare variable ID_SOCMAIN01_ORIGEN bigint;
declare variable RELA_SOCSYST10_LPR01 bigint;
declare variable PYMVENT10_PORCENTAJE double precision;
declare variable PYMVENT11_IMPORTE double precision;
declare variable ID_PYMVENT11 bigint;
declare variable ID_PYMVENT10 bigint;
begin
    select
    sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    into :id_sicxmls01_destino;

    select
    sicxmls01_cab_parametros.rela_socmain01
    from sicingr95_cab_conceptos
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01 )
    where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen
    into :id_socmain01_origen;

    select
    upper(trim(sicingr95_cab_conceptos.sicingr95_codigo)),
    sicingr95_cab_conceptos.sicingr95_descripcion,
    sicingr95_cab_conceptos.sicingr95_predial,
    sicingr95_cab_conceptos.sicingr95_importe,
    sicingr95_cab_conceptos.sicingr95_notas
    from sicingr95_cab_conceptos
    where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen
    into :sicingr95_codigo,
         :sicingr95_descripcion,
         :sicingr95_predial,
         :sicingr95_importe,
         :sicingr95_notas;

    select
    sicingr95_cab_conceptos.id_sicingr95
    from sicingr95_cab_conceptos
    where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01_destino
    and sicingr95_cab_conceptos.sicingr95_codigo = :sicingr95_codigo
    into :id_sicingr95_destino;

    if (id_sicingr95_destino is null) then
    begin
        execute procedure PRD_SICINGR95_REPLICACION_ALTA :id_sicingr95_origen, :id_socmain01_destino;
    end
    else
    begin
        update sicingr95_cab_conceptos set sicingr95_cab_conceptos.sicingr95_descripcion = :sicingr95_descripcion,
                                           sicingr95_cab_conceptos.sicingr95_predial = :sicingr95_predial,
                                           sicingr95_cab_conceptos.sicingr95_importe = :sicingr95_importe,
                                           sicingr95_cab_conceptos.sicingr95_notas = :sicingr95_notas
        where sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_destino;

        /* --------------------------------------------------------------------------------------------------------- */

        for select
           sicingr98_det_importes.rela_socsyst10_mli01,
           sicingr98_det_importes.sicingr98_importe,
           sicingr98_det_importes.sicingr98_fecha_aplicacion,
           sicingr98_det_importes.sicingr98_fecha_vencimiento,
           sicingr98_det_importes.sicingr98_margen,
           sicingr98_det_importes.sicingr98_modalidad
           from sicingr98_det_importes
           inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01 )
           where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95_origen
           and socsyst10_det_entradas.socsyst10_codigo <> 'CONCEP-REF'
           into :rela_socsyst10_mli01,
                :sicingr98_importe,
                :sicingr98_fecha_aplicacion,
                :sicingr98_fecha_vencimiento,
                :sicingr98_margen,
                :sicingr98_modalidad
           do
           begin
            id_sicingr98 = null;

            select sicingr98_det_importes.id_sicingr98
            from sicingr98_det_importes
            where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95_destino
            and sicingr98_det_importes.rela_socsyst10_mli01 = :rela_socsyst10_mli01
            into :id_sicingr98;

            if (id_sicingr98 is not null) then
            begin
                update sicingr98_det_importes set sicingr98_det_importes.sicingr98_importe = :sicingr98_importe,
                                                  sicingr98_det_importes.sicingr98_fecha_aplicacion =  :sicingr98_fecha_aplicacion,
                                                  sicingr98_det_importes.sicingr98_fecha_vencimiento = :sicingr98_fecha_vencimiento,
                                                  sicingr98_det_importes.sicingr98_margen = :sicingr98_margen,
                                                  sicingr98_det_importes.SICINGR98_MODALIDAD = :SICINGR98_MODALIDAD
                where sicingr98_det_importes.id_sicingr98 = :id_sicingr98;
            end
            else
            begin
                insert into sicingr98_det_importes( sicingr98_det_importes.rela_sicingr95,
                                                    sicingr98_det_importes.rela_socsyst10_mli01,
                                                    sicingr98_det_importes.sicingr98_importe,
                                                    sicingr98_det_importes.sicingr98_fecha_aplicacion,
                                                    sicingr98_det_importes.sicingr98_fecha_vencimiento,
                                                    sicingr98_det_importes.sicingr98_margen,
                                                    sicingr98_det_importes.sicingr98_modalidad )
                values( :id_sicxmls01_destino,
                        :rela_socsyst10_mli01,
                        :sicingr98_importe,
                        :sicingr98_fecha_aplicacion,
                        :sicingr98_fecha_vencimiento,
                        :sicingr98_margen,
                        :sicingr98_modalidad );
            end
       end

       /* --------------------------------------------------------------------------------------------------------- */

       for select
       pymvent10_cab_listaprecios.rela_socsyst10_lpr01,
       pymvent10_cab_listaprecios.pymvent10_porcentaje,
       pymvent11_det_xproductos.pymvent11_importe
       from pymvent11_det_xproductos
       inner join pymvent10_cab_listaprecios on ( pymvent10_cab_listaprecios.id_pymvent10 = pymvent11_det_xproductos.rela_pymvent10 )
       where pymvent10_cab_listaprecios.rela_socmain01 = :id_socmain01_origen
       and pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95_origen
       into :rela_socsyst10_lpr01,
            :pymvent10_porcentaje,
            :pymvent11_importe
       do
       begin
           select
           pymvent10_cab_listaprecios.id_pymvent10,
           pymvent11_det_xproductos.id_pymvent11
           from pymvent11_det_xproductos
           inner join pymvent10_cab_listaprecios on ( pymvent10_cab_listaprecios.id_pymvent10 = pymvent11_det_xproductos.rela_pymvent10 )
           where pymvent10_cab_listaprecios.rela_socmain01 = :id_socmain01_destino
           and pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95_destino
           and pymvent10_cab_listaprecios.rela_socsyst10_lpr01 = :rela_socsyst10_lpr01
           into :id_pymvent10,
                :id_pymvent11;

           if (id_pymvent11 is not null) then
           begin
              update pymvent10_cab_listaprecios set pymvent10_cab_listaprecios.pymvent10_porcentaje = :pymvent10_porcentaje
              where pymvent10_cab_listaprecios.id_pymvent10 = :id_pymvent10;

              update pymvent11_det_xproductos set pymvent11_det_xproductos.pymvent11_importe = :pymvent11_importe
              where pymvent11_det_xproductos.id_pymvent11 = :id_pymvent11;
           end
           else
           begin
              select pymvent10_cab_listaprecios.id_pymvent10
              from pymvent10_cab_listaprecios
              where pymvent10_cab_listaprecios.rela_socmain01 = :id_socmain01_destino
              and pymvent10_cab_listaprecios.rela_socsyst10_lpr01 = :rela_socsyst10_lpr01
              into :id_pymvent10;

              if (id_pymvent10 is not null) then
              begin
                 update pymvent10_cab_listaprecios set pymvent10_cab_listaprecios.pymvent10_porcentaje = :pymvent10_porcentaje
                 where pymvent10_cab_listaprecios.id_pymvent10 = :id_pymvent10;
              end
              else
              begin
                insert into pymvent10_cab_listaprecios( pymvent10_cab_listaprecios.rela_socmain01,
                                                        pymvent10_cab_listaprecios.rela_socsyst10_lpr01,
                                                        pymvent10_cab_listaprecios.pymvent10_porcentaje )
                values( :id_socmain01_destino,
                        :rela_socsyst10_lpr01,
                        :pymvent10_porcentaje );

                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'PYMVENT10'
                INTO :id_pymvent10;
              end

              /* --------------------------------------------------------------------------------------------------------- */
              /* --------------------------------------------------------------------------------------------------------- */

              select pymvent11_det_xproductos.id_pymvent11
              from pymvent11_det_xproductos
              where pymvent11_det_xproductos.rela_pymvent10 = :id_pymvent10
              and pymvent11_det_xproductos.rela_sicingr95 = :id_sicingr95_destino
              into :id_pymvent11;

              if (id_pymvent11 is not null) then
              begin
                 update pymvent11_det_xproductos set pymvent11_det_xproductos.pymvent11_importe = :pymvent11_importe
                 where pymvent11_det_xproductos.id_pymvent11 = :id_pymvent11;
              end
              else
              begin
                 insert into pymvent11_det_xproductos( pymvent11_det_xproductos.rela_pymvent10,
                                                       pymvent11_det_xproductos.rela_sicingr95,
                                                       pymvent11_det_xproductos.pymvent11_importe )
                 values( :id_pymvent10,
                         :id_sicingr95_destino,
                         :pymvent11_importe );
              end
           end
       end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_TIPO (
    VALOR INTEGER)
RETURNS (
    DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (valor = 0) then
        descripcion = 'Producto para la Venta';
    else if (valor = 1) then
        descripcion = 'Producto Propio o Terminados';
    else if (valor = 2) then
        descripcion = 'Materia Prima o Material stockeable';
    else if (valor = 3) then
        descripcion = 'Materia Prima o Material consignado';
    else if (valor = 4) then
        descripcion = 'Subproductos para producción';
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_TRANSFERENCIA (
    RELA_SICINGR95_ORIGEN BIGINT,
    RELA_PYMALMA01_ORIGEN BIGINT,
    RELA_PYMALMA01_DESTINO BIGINT,
    CANTIDAD DOUBLE PRECISION)
AS
declare variable V_RELA_SICINGR95_DESTINO bigint;
declare variable V_ID_SICXMLS01 bigint;
declare variable V_RELA_SOCSYST10_STK01 bigint;
declare variable V_RELA_SOCMAIN01 bigint;
declare variable V_SICINGR95_CODIGO varchar(50);
begin
    SELECT cbo_socsyst10_stk01.id_socsyst10
    FROM cbo_socsyst10_stk01
    WHERE cbo_socsyst10_stk01.socsyst10_codigo = 'STK-MANUAL-TRANSFERENCIA'
    into :v_rela_socsyst10_stk01;

    select pymalma01_cab_stock.rela_socmain01
    from pymalma01_cab_stock
    where pymalma01_cab_stock.id_pymalma01 = :rela_pymalma01_destino
    into :v_rela_socmain01;

    v_id_sicxmls01 = null;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :v_rela_socmain01
    into :v_id_sicxmls01;

    if (v_id_sicxmls01 is null) then
    begin
        EXIT;
    end

    select
    sicingr95_cab_conceptos.sicingr95_codigo
    from sicingr95_cab_conceptos
    where sicingr95_cab_conceptos.id_sicingr95 = :rela_sicingr95_origen
    into :v_sicingr95_codigo;

    if (v_sicingr95_codigo is null) then
    begin
        EXIT;
    end

    select sicingr95_cab_conceptos.id_sicingr95
    from sicingr95_cab_conceptos
    where sicingr95_cab_conceptos.rela_sicxmls01 = :v_id_sicxmls01
    and sicingr95_cab_conceptos.sicingr95_codigo = :v_sicingr95_codigo
    into :v_rela_sicingr95_destino;

    insert into pymalma02_det_stock(pymalma02_det_stock.rela_pymalma01,
                                    pymalma02_det_stock.rela_pymalma01_transf,
                                    pymalma02_det_stock.rela_sicingr95,
                                    pymalma02_det_stock.rela_socsyst10_stk01,
                                    pymalma02_det_stock.pymalma02_cantidad)
    values(
        :rela_pymalma01_origen,
        :rela_pymalma01_destino,
        :rela_sicingr95_origen,
        :v_rela_socsyst10_stk01,
        :cantidad*(-1)
    );

    insert into pymalma02_det_stock(pymalma02_det_stock.rela_pymalma01,
                                    pymalma02_det_stock.rela_pymalma01_transf,
                                    pymalma02_det_stock.rela_sicingr95,
                                    pymalma02_det_stock.rela_socsyst10_stk01,
                                    pymalma02_det_stock.pymalma02_cantidad)
    values(
        :rela_pymalma01_destino,
        :rela_pymalma01_origen,
        :v_rela_sicingr95_destino,
        :v_rela_socsyst10_stk01,
        :cantidad
    );
end^


CREATE OR ALTER PROCEDURE PRD_SICINGR95_VALIDAR (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR95X BIGINT,
    ID_SICXMLS04 BIGINT,
    CODIGOX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICINGR95 BIGINT,
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRODUCTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICXMLS01 bigint;
begin
    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    into :id_sicxmls01;

    id_sicingr95 = null;

    if (:id_sicingr95x is null or :id_sicingr95x <= 0) then
    begin
        select
        sicingr95_cab_conceptos.id_sicingr95,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.SICINGR95_DESCRIPCION
        from sicingr95_cab_conceptos
        where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01
        and sicingr95_cab_conceptos.sicingr95_codigo = :codigox
        into :id_sicingr95, :codigo, :producto;

        if (id_sicingr95 is null) then
            select
            sicingr95_cab_conceptos.id_sicingr95,
            sicingr95_cab_conceptos.sicingr95_codigo,
            sicingr95_cab_conceptos.SICINGR95_DESCRIPCION
            from sicingr95_cab_conceptos
            where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01
            and sicingr95_cab_conceptos.rela_sicxmls04 = :id_sicxmls04
            into :id_sicingr95, :codigo, :producto;
    end
    else
    begin
        select
        sicingr95_cab_conceptos.id_sicingr95,
        sicingr95_cab_conceptos.SICINGR95_DESCRIPCION
        from sicingr95_cab_conceptos
        where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01
        and sicingr95_cab_conceptos.sicingr95_codigo = :codigox
        and sicingr95_cab_conceptos.id_sicingr95 <> :id_sicingr95x
        into :id_sicingr95, :producto;

        if (id_sicingr95 is null) then
            select
            sicingr95_cab_conceptos.id_sicingr95,
            sicingr95_cab_conceptos.sicingr95_codigo,
            sicingr95_cab_conceptos.SICINGR95_DESCRIPCION
            from sicingr95_cab_conceptos
            where sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01
            and sicingr95_cab_conceptos.rela_sicxmls04 = :id_sicxmls04
            and sicingr95_cab_conceptos.id_sicingr95 <> :id_sicingr95x
            into :id_sicingr95, :codigo, :producto;
    end

    if (id_sicingr95 is not null) then
        suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI05 (
    RELA_SICNOMI05 BIGINT,
    VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICNOMI05 BIGINT)
AS
begin
    update sicnomi05_det_nomina set sicnomi05_det_nomina.sicnomi05_valor = :valor,
                                    sicnomi05_det_nomina.sicnomi05_descripcion = :descripcion
    where sicnomi05_det_nomina.id_sicnomi05 = :rela_sicnomi05;

    id_sicnomi05 = :rela_sicnomi05;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI50_ANTICIPO (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SICNOMI01 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    COTIZA DOUBLE PRECISION,
    FECHA DATE)
RETURNS (
    OK INTEGER)
AS
declare variable RELA_SOCSYST10_CTP01 bigint;
declare variable RELA_SOCSYST10_CTP02 bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable RELA_SICCONT02_DEBE bigint;
declare variable RELA_SICCONT02_HABER bigint;
declare variable ID_SOCUSUA30 bigint;
declare variable ID_SICCONT10 bigint;
begin
    select cbo_socsyst10_ctp01.id_socsyst10
    from cbo_socsyst10_ctp01
    where cbo_socsyst10_ctp01.socsyst10_codigo = 'DROPZONE-ANTI-NOMI'
    into :rela_socsyst10_ctp01;

    select cbo_socsyst10_ctp02.id_socsyst10
    from cbo_socsyst10_ctp02
    where cbo_socsyst10_ctp02.socsyst10_codigo = 'PO-2-EGR'
    into :rela_socsyst10_ctp02;

    select cbo_SICNOMI01.id_socusua30
    from cbo_SICNOMI01
    where cbo_SICNOMI01.rela_SICNOMI01 = :rela_SICNOMI01
    into :id_socusua30;

    select
    socmain05_det_bancos.rela_siccont02,
    socmain05_det_bancos.rela_socsyst10_ctm01
    from socmain05_det_bancos
    where socmain05_det_bancos.id_socmain05 = :rela_socmain05
    into :rela_siccont02_haber,
         :rela_socsyst10_ctm01;

    select SICXMLS03_DET_CUENTAS.rela_siccont02
    from sicxmls01_cab_parametros
    inner join SICXMLS03_DET_CUENTAS on (SICXMLS03_DET_CUENTAS.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICXMLS03_DET_CUENTAS.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA-ANTIC'
    into :rela_siccont02_debe;

    INSERT INTO siccont10_cab_polizas(siccont10_cab_polizas.rela_socmain01,
                                      siccont10_cab_polizas.rela_socmain21,
                                      siccont10_cab_polizas.rela_socusua01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp01,
                                      siccont10_cab_polizas.rela_socsyst10_ctp02,
                                      siccont10_cab_polizas.rela_socsyst10_ctm01,
                                      siccont10_cab_polizas.rela_socusua30,
                                      siccont10_cab_polizas.siccont10_tipo_entidad,
                                      siccont10_cab_polizas.siccont10_descripcion,
                                      siccont10_cab_polizas.siccont10_docnro,
                                      siccont10_cab_polizas.siccont10_fcta,
                                      siccont10_cab_polizas.siccont10_cotiza)
    VALUES(:rela_socmain01,
           :rela_socmain21,
           :rela_socusua01,
           :rela_socsyst10_ctp01,
           :rela_socsyst10_ctp02,
           :rela_socsyst10_ctm01,
           :id_socusua30,
           'P',
           :CONCEPTO,
           'XXXX',
           :fecha,
           :cotiza);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :ID_SICCONT10;

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)
    values(:id_siccont10,
           :rela_siccont02_debe,
           'S',
           '',
           :importe,
           0,
           -1,
           -1);

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)
    values(:id_siccont10,
           :rela_siccont02_haber,
           'S',
           '',
           0,
           :importe,
           -1,
           -1);

     insert into SICNOMI50_det_ctacte(SICNOMI50_det_ctacte.rela_SICNOMI01,
                                      SICNOMI50_det_ctacte.rela_socmain01,
                                      SICNOMI50_det_ctacte.rela_siccont10,
                                      SICNOMI50_det_ctacte.SICNOMI50_importe)
     values(:rela_SICNOMI01,
            :rela_socmain01,
            :id_siccont10,
            :importe * (-1));


    ok = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI51_CREAPOLIZAS
RETURNS (
    OK INTEGER)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SICCONT10_NEW bigint;
declare variable ID_SICCONT10_OLD bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable PORCENTAJE double precision;
declare variable RELA_SICCONT02 bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable RELA_SICCONT02_BANCO bigint;
declare variable RELA_SICCONT02_NOMI bigint;
declare variable PM_RELA_SOCMAIN01 bigint;
declare variable PM_RELA_SOCMAIN21 bigint;
declare variable PM_RELA_SOCUSUA01 bigint;
declare variable PM_RELA_SICNOMI01 bigint;
declare variable PM_RELA_SOCMAIN05 bigint;
declare variable PM_ID_SICNOMI51 bigint;
declare variable PM_SICNOMI51_REFERENCIA varchar(400);
declare variable PM_SICNOMI51_FECHA date;
declare variable PM_SICNOMI51_COTIZA double precision;
declare variable PM_SICNOMI51_IMPORTE double precision;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
declare variable RELA_SICCONT02_ANTICIPO bigint;
declare variable SICNOMI50_IMPORTE_ANTICIPO double precision;
declare variable SICCONT10_UUID_SAT varchar(50);
begin
    ok = 0;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICNOMI51'
    INTO :pm_id_SICNOMI51;

    Select
    SICNOMI51_cab_bancos.rela_socmain01,
    SICNOMI51_cab_bancos.rela_socmain21,
    SICNOMI51_cab_bancos.rela_socusua01,
    SICNOMI51_cab_bancos.rela_SICNOMI01,
    SICNOMI51_cab_bancos.rela_socmain05,
    SICNOMI51_cab_bancos.SICNOMI51_referencia,
    SICNOMI51_cab_bancos.SICNOMI51_fecha,
    SICNOMI51_cab_bancos.SICNOMI51_cotiza,
    SICNOMI51_cab_bancos.SICNOMI51_importe
    from SICNOMI51_cab_bancos
    where SICNOMI51_cab_bancos.id_SICNOMI51 = :pm_id_SICNOMI51
    into :pm_rela_socmain01,
         :pm_rela_socmain21,
         :pm_rela_socusua01,
         :pm_rela_SICNOMI01,
         :pm_rela_socmain05,
         :pm_SICNOMI51_referencia,
         :pm_SICNOMI51_fecha,
         :pm_SICNOMI51_cotiza,
         :pm_SICNOMI51_importe;

    if (pm_SICNOMI51_importe IS NULL) then
        pm_SICNOMI51_importe = 0;

    select
    sum(SICNOMI50_det_ctacte.SICNOMI50_importe)
    from SICNOMI52_det_bancos
    inner join SICNOMI50_det_ctacte on (SICNOMI52_det_bancos.rela_SICNOMI50 = SICNOMI50_det_ctacte.id_SICNOMI50)
    inner join siccont10_cab_polizas on (SICNOMI50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
    inner join socsyst10_det_entradas on (siccont10_cab_polizas.rela_socsyst10_ctp01 = socsyst10_det_entradas.id_socsyst10)
    where SICNOMI52_det_bancos.rela_SICNOMI51 = :pm_id_SICNOMI51
    and socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-ANTI-NOMI'
    into :SICNOMI50_importe_anticipo;

    if (SICNOMI50_importe_anticipo IS NULL) then
        SICNOMI50_importe_anticipo = 0;
    else
        SICNOMI50_importe_anticipo = SICNOMI50_importe_anticipo * (-1);

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if ((pm_SICNOMI51_importe <> 0) or (SICNOMI50_importe_anticipo <> 0))then
    begin
        select sicnomi01_cab_empleados.rela_socusua30
        from sicnomi01_cab_empleados
        where sicnomi01_cab_empleados.id_SICNOMI01 = :pm_rela_SICNOMI01
        into :rela_socusua30;

        select CBO_SOCSYST10_CTP01.id_socsyst10
        from CBO_SOCSYST10_CTP01
        where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-BANCOS-NOMI'
        into :id_socsyst10_ctp01;

        select CBO_SOCSYST10_CTP02.id_socsyst10
        from CBO_SOCSYST10_CTP02
        where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-2-EGR'
        into :id_socsyst10_ctp02;

        select socmain05_det_bancos.rela_siccont02,
        socmain05_det_bancos.rela_socsyst10_ctm01
        from socmain05_det_bancos
        where socmain05_det_bancos.id_socmain05 = :pm_rela_socmain05
        into :rela_siccont02_banco,
             :id_socsyst10_ctm01;

        select sicxmls01_cab_parametros.id_sicxmls01
        from sicxmls01_cab_parametros
        where sicxmls01_cab_parametros.rela_socmain01 = :pm_rela_socmain01
        into :id_sicxmls01;

        select sicxmls03_det_cuentas.rela_siccont02
        from sicxmls03_det_cuentas
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
        and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA'
        into :rela_siccont02_nomi;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* aqui debo ver despues, para proveedor extranjero, tengo que saber como tomar si es o no proveedor extranjero */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.rela_socusua30,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :pm_rela_socmain01,
            :pm_rela_socmain21,
            :pm_rela_socusua01,
            :id_socsyst10_ctp01,
            :id_socsyst10_ctp02,
            :id_socsyst10_ctm01,
            :rela_socusua30,
            'P',
            :pm_SICNOMI51_referencia,
            'xxxx',
            :pm_SICNOMI51_fecha,
            :pm_SICNOMI51_cotiza);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */
        
        if (SICNOMI50_importe_anticipo <> 0) then
        begin
            select sicxmls03_det_cuentas.rela_siccont02
            from sicxmls03_det_cuentas
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
            where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
            and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA-ANTIC'
            into :rela_siccont02_anticipo;

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                               siccont11_det_polizas.rela_siccont02,
                                               siccont11_det_polizas.siccont11_tipo_entidad,
                                               siccont11_det_polizas.siccont11_debe,
                                               siccont11_det_polizas.siccont11_haber,
                                               siccont11_det_polizas.siccont11_ano,
                                               siccont11_det_polizas.siccont11_mes)

            values(:id_siccont10_new,
                   :rela_siccont02_nomi,
                   'S',
                   :SICNOMI50_importe_anticipo,
                   0,
                   -1,
                   -1);

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes)

            values(:id_siccont10_new,
                   :rela_siccont02_anticipo,
                   'S',
                   0,
                   :SICNOMI50_importe_anticipo,
                   -1,
                   -1);

            pm_SICNOMI51_importe = SICNOMI50_importe_anticipo;
        end
        else
        begin
            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes)

            values(:id_siccont10_new,
                   :rela_siccont02_nomi,
                   'S',
                   :pm_SICNOMI51_importe,
                   0,
                   -1,
                   -1);

            insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                              siccont11_det_polizas.rela_siccont02,
                                              siccont11_det_polizas.siccont11_tipo_entidad,
                                              siccont11_det_polizas.siccont11_debe,
                                              siccont11_det_polizas.siccont11_haber,
                                              siccont11_det_polizas.siccont11_ano,
                                              siccont11_det_polizas.siccont11_mes)

            values(:id_siccont10_new,
                   :rela_siccont02_banco,
                   'S',
                   0,
                   :pm_SICNOMI51_importe,
                   -1,
                   -1);

        end
    end

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    if (pm_SICNOMI51_importe <> 0)  then
    begin
        for select
        SICNOMI50_det_ctacte.rela_siccont10,
        SICNOMI52_det_bancos.SICNOMI52_importe / SICNOMI50_det_ctacte.SICNOMI50_importe * 100,
        siccont10_cab_polizas.siccont10_uuid_sat
        from SICNOMI50_det_ctacte
        inner join SICNOMI52_det_bancos on (SICNOMI50_det_ctacte.id_SICNOMI50 = SICNOMI52_det_bancos.rela_SICNOMI50)
        inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = SICNOMI50_det_ctacte.rela_siccont10)
        where  SICNOMI52_det_bancos.rela_SICNOMI51 = :pm_id_SICNOMI51
        and SICNOMI52_det_bancos.SICNOMI52_importe > 0
        into :id_siccont10_old,
             :porcentaje,
             :siccont10_uuid_sat
        do
        begin
            for select
            sicxmls05_det_nomina.rela_siccont02,
            sicxmls05_det_nomina.rela_siccont02_ctracta,
            siccont11_det_polizas.siccont11_debe,
            siccont11_det_polizas.siccont11_haber
            from sicxmls05_det_nomina
            inner join siccont12_mov_dropzone on (sicxmls05_det_nomina.id_sicxmls05 = siccont12_mov_dropzone.rela_sicxmls05)
            inner join siccont11_det_polizas on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)    
            where siccont11_det_polizas.rela_siccont10 = :id_siccont10_old
            and sicxmls05_det_nomina.rela_siccont02_ctracta is not null
            into :rela_siccont02,
                 :rela_siccont02_ctracta,
                 :siccont11_debe,
                 :siccont11_haber
            do
            begin
                if (siccont11_debe <> 0) then
                   siccont11_debe = siccont11_debe * porcentaje / 100;
                else
                   siccont11_haber = siccont11_haber * porcentaje / 100;

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

                values(:id_siccont10_new,
                   :rela_siccont02_ctracta,
                   'S',
                   :siccont10_uuid_sat,
                   :siccont11_debe,
                   :siccont11_haber,
                   -1,
                   -1);

                /* --------------------------------------------------------------------------------------------------------------------------- */
                /* --------------------------------------------------------------------------------------------------------------------------- */

                if (siccont11_debe <> 0) then
                begin
                    siccont11_haber = siccont11_debe;
                    siccont11_debe = 0;
                end
                else
                begin
                    siccont11_debe = siccont11_haber;
                    siccont11_haber = 0;
                end

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                      siccont11_det_polizas.rela_siccont02,
                                      siccont11_det_polizas.siccont11_tipo_entidad,
                                      siccont11_det_polizas.siccont11_referencia,
                                      siccont11_det_polizas.siccont11_debe,
                                      siccont11_det_polizas.siccont11_haber,
                                      siccont11_det_polizas.siccont11_ano,
                                      siccont11_det_polizas.siccont11_mes)

                values(:id_siccont10_new,
                   :rela_siccont02,
                   'S',
                   :siccont10_uuid_sat,
                   :siccont11_debe,
                   :siccont11_haber,
                    -1,
                    -1);    
            end    
        end

        /* --------------------------------------------------------------------------------------------------------------------------- */
        /* --------------------------------------------------------------------------------------------------------------------------- */

        if (SICNOMI50_importe_anticipo = 0) then
           pm_SICNOMI51_importe = :pm_SICNOMI51_importe * (-1);
        else
           pm_SICNOMI51_importe = 0;

        insert into SICNOMI50_det_ctacte(SICNOMI50_det_ctacte.rela_SICNOMI01,
                                         SICNOMI50_det_ctacte.rela_socmain01,
                                         SICNOMI50_det_ctacte.rela_siccont10,
                                         SICNOMI50_det_ctacte.rela_SICNOMI51,
                                         SICNOMI50_det_ctacte.SICNOMI50_importe)

        values( :pm_rela_SICNOMI01,
                :pm_rela_socmain01,
                :id_siccont10_new,
                :pm_id_SICNOMI51,
                :pm_SICNOMI51_importe);

        ok = 1;
    end
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI51_VALIDA (
    RELA_SOCMAIN01 BIGINT)
RETURNS (
    ID INTEGER,
    MENSAJE VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CADENA_MENSAJE varchar(100);
declare variable ID_SICXMLS02 bigint;
begin
    id = 0;
    id_sicxmls02 = null;
    CADENA_MENSAJE = 'Debe parametrizar ';

    SELECT FIRST 1 sicxmls02_det_impuestos.id_sicxmls02
    from sicxmls02_det_impuestos
    inner join sicxmls01_cab_parametros on (sicxmls02_det_impuestos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    AND (sicxmls02_det_impuestos.rela_siccont02 is null
    or sicxmls02_det_impuestos.rela_siccont02_ctracta is null)
    into :id_sicxmls02;

    if (id_sicxmls02 is not null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || ' los Impuestos y ctas de traslados.';
        suspend; 
    end

    if (id = 0) then
    BEGIN
        ID = ID + 1;
        mensaje = 'OK';
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI60_CREAPOLIZAS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCMAIN05 BIGINT,
    SICINGR60_IMPORTE DOUBLE PRECISION,
    SICINGR60_AJUSTE DOUBLE PRECISION,
    SICINGR60_FCTA DATE,
    SICINGR60_FCTA_PERIODO DATE)
RETURNS (
    RELA_SICCONT10_NEW BIGINT)
AS
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable RELA_SICCONT02_BANCOS bigint;
declare variable RELA_SICCONT02_NOMINA bigint;
declare variable RELA_SICCONT02_AJUSTE bigint;
begin
    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-PERIODO-NOMI'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-2-EGR'
    into :id_socsyst10_ctp02;

    select cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :id_socsyst10_ctm01;

    select socmain05_det_bancos.rela_siccont02
    from socmain05_det_bancos
    where socmain05_det_bancos.id_socmain05 = :rela_socmain05
    into :rela_siccont02_bancos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA'
    into :rela_siccont02_nomina;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls01_cab_parametros
    inner join sicxmls03_det_cuentas on (sicxmls03_det_cuentas.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'NOMINA-AJUSTE-PERIODO'
    into :rela_siccont02_ajuste;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza)
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                'S',
                'NOMINA POR PERIODO ' || :sicingr60_fcta_periodo,
                'xxxx',
                :sicingr60_fcta,
                1);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :rela_siccont10_new;

    /* --------------------------------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------------------------------- */

    insert into siccont11_det_polizas( siccont11_det_polizas.rela_siccont10,
                                           siccont11_det_polizas.rela_siccont02,
                                           siccont11_det_polizas.siccont11_tipo_entidad,
                                           siccont11_det_polizas.siccont11_debe,
                                           siccont11_det_polizas.siccont11_haber,
                                           siccont11_det_polizas.siccont11_ano,
                                           siccont11_det_polizas.siccont11_mes)

    values(:rela_siccont10_new,
           :rela_siccont02_bancos,
           'S',
           0,
           :sicingr60_importe + :sicingr60_ajuste,
           -1,
           -1);

    insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                          siccont11_det_polizas.rela_siccont02,
                                          siccont11_det_polizas.siccont11_tipo_entidad,
                                          siccont11_det_polizas.siccont11_debe,
                                          siccont11_det_polizas.siccont11_haber,
                                          siccont11_det_polizas.siccont11_ano,
                                          siccont11_det_polizas.siccont11_mes)

    values(:rela_siccont10_new,
           :rela_siccont02_nomina,
           'S',
           :sicingr60_importe,
           0,
           -1,
           -1);

    if (sicingr60_ajuste <> 0) then
    begin
        insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                          siccont11_det_polizas.rela_siccont02,
                                          siccont11_det_polizas.siccont11_tipo_entidad,
                                          siccont11_det_polizas.siccont11_debe,
                                          siccont11_det_polizas.siccont11_haber,
                                          siccont11_det_polizas.siccont11_ano,
                                          siccont11_det_polizas.siccont11_mes)

        values(:rela_siccont10_new,
               :rela_siccont02_ajuste,
               'S',
               :sicingr60_ajuste,
               0,
               -1,
               -1);
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI61_CREAPOLIZAS
RETURNS (
    OK INTEGER)
AS
declare variable ID_SICNOMI60 bigint;
declare variable ID_SICNOMI61 bigint;
declare variable RELA_SICNOMI01 bigint;
declare variable RELA_SICCONT10_ORIGEN bigint;
declare variable SICCONT10_DOCNRO_ORIGINAL varchar(50);
declare variable SICNOMI50_IMPORTE double precision;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable SICNOMI60_FCTA date;
declare variable ID_SICCONT10_NEW bigint;
declare variable RELA_SICCONT02 bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable SICCONT11_DEBE double precision;
declare variable SICCONT11_HABER double precision;
declare variable RELA_SOCMAIN01 integer;
declare variable RELA_SOCMAIN21 integer;
declare variable RELA_SOCUSUA01 integer;
declare variable SICCONT10_DOCNRO varchar(50);
declare variable SICCONT10_UUID_SMX varchar(50);
declare variable SICCONT10_UUID_SAT varchar(50);
begin
    ok = 0;

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICNOMI60'
    INTO :ID_SICNOMI60;

    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE-PERIODO-NOMI'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-2-EGR'
    into :id_socsyst10_ctp02;

    select cbo_socsyst10_ctm01.id_socsyst10
    from cbo_socsyst10_ctm01
    where cbo_socsyst10_ctm01.socsyst10_codigo = 'MXN'
    into :id_socsyst10_ctm01;

    select
    sicnomi60_cab_xperiodo.rela_socmain01,
    sicnomi60_cab_xperiodo.rela_socmain21,
    sicnomi60_cab_xperiodo.rela_socusua01,
    sicnomi60_cab_xperiodo.SICNOMI60_fcta,
    siccont10_cab_polizas.siccont10_docnro
    from sicnomi60_cab_xperiodo
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi60_cab_xperiodo.rela_siccont10)
    where sicnomi60_cab_xperiodo.id_SICNOMI60 = :id_SICNOMI60
    into :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :SICNOMI60_fcta,
         :siccont10_docnro;

    for select
    sicnomi61_det_xperiodo.id_sicnomi61,
    sicnomi50_det_ctacte.rela_sicnomi01,
    sicnomi50_det_ctacte.rela_siccont10,
    sicnomi50_det_ctacte.sicnomi50_importe,
    siccont10_cab_polizas.siccont10_docnro
    from sicnomi61_det_xperiodo
    inner join sicnomi50_det_ctacte on (sicnomi50_det_ctacte.id_sicnomi50 = sicnomi61_det_xperiodo.rela_sicnomi50)
    inner join siccont10_cab_polizas on (siccont10_cab_polizas.id_siccont10 = sicnomi50_det_ctacte.rela_siccont10)
    where sicnomi61_det_xperiodo.rela_sicnomi60 = :id_SICNOMI60
    into :id_sicnomi61,
         :rela_sicnomi01,
         :rela_siccont10_origen,
         :sicnomi50_importe,
         :siccont10_docnro_original
    do
    begin
        Select siccont10_cab_polizas.rela_socusua30,
        siccont10_cab_polizas.siccont10_uuid_smx,
        siccont10_cab_polizas.siccont10_uuid_sat
        from siccont10_cab_polizas
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10_origen
        into :rela_socusua30,
             :siccont10_uuid_smx,
             :siccont10_uuid_sat;

        insert into SICCONT10_CAB_POLIZAS(SICCONT10_CAB_POLIZAS.rela_socmain01,
                                      SICCONT10_CAB_POLIZAS.rela_socmain21,
                                      SICCONT10_CAB_POLIZAS.rela_socusua01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp01,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctp02,
                                      SICCONT10_CAB_POLIZAS.rela_socsyst10_ctm01,
                                      SICCONT10_CAB_POLIZAS.rela_socusua30,
                                      SICCONT10_CAB_POLIZAS.siccont10_tipo_entidad,
                                      SICCONT10_CAB_POLIZAS.siccont10_descripcion,
                                      SICCONT10_CAB_POLIZAS.siccont10_docnro,
                                      SICCONT10_CAB_POLIZAS.siccont10_fcta,
                                      SICCONT10_CAB_POLIZAS.siccont10_cotiza,
                                      SICCONT10_CAB_POLIZAS.siccont10_uuid_smx,
                                      SICCONT10_CAB_POLIZAS.siccont10_uuid_sat)
        values( :rela_socmain01,
                :rela_socmain21,
                :rela_socusua01,
                :id_socsyst10_ctp01,
                :id_socsyst10_ctp02,
                :id_socsyst10_ctm01,
                :rela_socusua30,
                'C',
                'CRUCE DE IMPUESTOS - POLIZA NO. ' || :siccont10_docnro || ' POLIZA ORIG. NO. '|| :siccont10_docnro_original,
                'xxxx',
                :SICNOMI60_fcta,
                1,
                :siccont10_uuid_smx,
                :siccont10_uuid_sat);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
        INTO :id_siccont10_new;

        update sicnomi61_det_xperiodo set sicnomi61_det_xperiodo.rela_siccont10 = :id_siccont10_new
        where sicnomi61_det_xperiodo.id_sicnomi61 = :id_sicnomi61;

        insert into sicnomi50_det_ctacte(sicnomi50_det_ctacte.rela_sicnomi01,
                                         sicnomi50_det_ctacte.rela_socmain01,
                                         sicnomi50_det_ctacte.rela_siccont10,
                                         sicnomi50_det_ctacte.sicnomi50_importe)
        values(:rela_sicnomi01,
               :rela_socmain01,
               :id_siccont10_new,
               :sicnomi50_importe * -1);


        for select
        sicxmls05_det_nomina.rela_siccont02,
        sicxmls05_det_nomina.rela_siccont02_ctracta,
        sum(siccont11_det_polizas.siccont11_debe),
        sum(siccont11_det_polizas.siccont11_haber)
        from sicxmls05_det_nomina
        inner join siccont12_mov_dropzone on (sicxmls05_det_nomina.id_sicxmls05 = siccont12_mov_dropzone.rela_sicxmls05)
        inner join siccont11_det_polizas on (siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11)
        where siccont11_det_polizas.rela_siccont10 = :rela_siccont10_origen
        and sicxmls05_det_nomina.rela_siccont02_ctracta is not null
        group by sicxmls05_det_nomina.rela_siccont02,
                 sicxmls05_det_nomina.rela_siccont02_ctracta
        having (sum(siccont11_det_polizas.siccont11_debe) + sum(siccont11_det_polizas.siccont11_haber)) <> 0
        into :rela_siccont02,
             :rela_siccont02_ctracta,
             :siccont11_debe,
             :siccont11_haber
        do
        begin
            if (siccont11_debe <> 0) then
            begin
                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes)
    
                values(:id_siccont10_new,
                       :rela_siccont02_ctracta,
                       'S',
                       :siccont11_debe,
                       0,
                       -1,
                       -1);

                siccont11_haber = siccont11_debe;
                siccont11_debe = 0;

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes)
    
                values(:id_siccont10_new,
                       :rela_siccont02,
                       'S',
                       :siccont11_debe,
                       :siccont11_haber,
                       -1,
                       -1);
            end

            if (siccont11_haber <> 0) then
            begin
                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes)
    
                values(:id_siccont10_new,
                       :rela_siccont02_ctracta,
                       'S',
                       0,
                       :siccont11_haber,
                       -1,
                       -1);

                siccont11_debe = siccont11_haber;
                siccont11_haber = 0;

                insert into siccont11_det_polizas(siccont11_det_polizas.rela_siccont10,
                                                  siccont11_det_polizas.rela_siccont02,
                                                  siccont11_det_polizas.siccont11_tipo_entidad,
                                                  siccont11_det_polizas.siccont11_debe,
                                                  siccont11_det_polizas.siccont11_haber,
                                                  siccont11_det_polizas.siccont11_ano,
                                                  siccont11_det_polizas.siccont11_mes)
    
                values(:id_siccont10_new,
                       :rela_siccont02,
                       'S',
                       :siccont11_debe,
                       :siccont11_haber,
                       -1,
                       -1);
            end
        end
    end

    ok = 1;

    suspend;

end^


