CREATE OR ALTER PROCEDURE PRD_SICNOMI70_ULTCANCELADO (
    RELA_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI70 BIGINT,
    FECHA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable FECHA_REC timestamp;
begin
    ID_SICNOMI70 = :rela_sicnomi70;

    select
    max(sicnomi77_det_cfdiscancelados.sicnomi77_uuid_fecha)
    from sicnomi77_det_cfdiscancelados
    where sicnomi77_det_cfdiscancelados.rela_sicnomi70 = :rela_sicnomi70
    into :fecha_rec;

    if (fecha_rec is null) then
        fecha = 'Sin Cancelados';
    else
    begin
        fecha = Extract(day FROM :fecha_rec) || '/' ||
                Extract(month FROM :fecha_rec) || '/' ||
                Extract(year FROM :fecha_rec) || ' ' ||
                Extract(hour FROM :fecha_rec) || ':' ||
                Extract(minute FROM :fecha_rec);
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI71_IMPORTES (
    SICXMLS05_GRAVADO INTEGER,
    ID_SOCMAIN01 BIGINT,
    ID_SICNOMI01 BIGINT,
    RELA_SICXMLS05 BIGINT)
RETURNS (
    IMPORTE DOUBLE PRECISION,
    GRAVADO VARCHAR(2) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable FECHA_MAX date;
begin
    importe = 0;

    if (sicxmls05_gravado = 0) then
    begin
        gravado = 'No';
        select
        max(sicxmls41_det_migracion.sicxmls41_uuid_fecha)
        from sicxmls40_cab_migracion
        inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
        inner join cbo_sicnomi01 on ( cbo_sicnomi01.id_socusua30 = sicxmls41_det_migracion.rela_socusua30 )
        inner join sicxmls46_det_nomina on ( sicxmls46_det_nomina.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
        where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
        and cbo_sicnomi01.rela_sicnomi01 = :ID_SICNOMI01
        and sicxmls46_det_nomina.rela_sicxmls05_excento = :rela_sicxmls05
        into :fecha_max;

        if (fecha_max is not null) then
        begin
            select
            sum(sicxmls46_det_nomina.sicxmls46_importe_exento)
            from sicxmls40_cab_migracion
            inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
            inner join cbo_sicnomi01 on ( cbo_sicnomi01.id_socusua30 = sicxmls41_det_migracion.rela_socusua30 )
            inner join sicxmls46_det_nomina on ( sicxmls46_det_nomina.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
            where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
            and cbo_sicnomi01.rela_sicnomi01 = :ID_SICNOMI01
            and sicxmls46_det_nomina.rela_sicxmls05_excento = :rela_sicxmls05
            and sicxmls41_det_migracion.sicxmls41_uuid_fecha = :fecha_max
            into :importe;
        end
    end
    else
    begin
        gravado = 'Si';

        select
        max(sicxmls41_det_migracion.sicxmls41_uuid_fecha)
        from sicxmls40_cab_migracion
        inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
        inner join cbo_sicnomi01 on ( cbo_sicnomi01.id_socusua30 = sicxmls41_det_migracion.rela_socusua30 )
        inner join sicxmls46_det_nomina on ( sicxmls46_det_nomina.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
        where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
        and cbo_sicnomi01.rela_sicnomi01 = :ID_SICNOMI01
        and sicxmls46_det_nomina.rela_sicxmls05_gravado = :rela_sicxmls05
        into :fecha_max;

        if (fecha_max is not null) then
        begin
            select
            sum(sicxmls46_det_nomina.sicxmls46_importe_gavado)
            from sicxmls40_cab_migracion
            inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
            inner join cbo_sicnomi01 on ( cbo_sicnomi01.id_socusua30 = sicxmls41_det_migracion.rela_socusua30 )
            inner join sicxmls46_det_nomina on ( sicxmls46_det_nomina.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
            where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
            and cbo_sicnomi01.rela_sicnomi01 = :ID_SICNOMI01
            and sicxmls46_det_nomina.rela_sicxmls05_gravado = :rela_sicxmls05
            and sicxmls41_det_migracion.sicxmls41_uuid_fecha = :fecha_max
            into :importe;
        end

    end

    if (importe is null) then
        importe = 0;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI73 (
    RELA_SICNOMI72 BIGINT,
    RELA_SICNOMI01 BIGINT,
    ANTIGUEDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SICNOMI70 BIGINT)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01 bigint;
declare variable SICNOMI72_TIPONOMINA varchar(1);
declare variable SICNOMI72_FECHA date;
declare variable SICNOMI72_FINI date;
declare variable SICNOMI72_FFIN date;
declare variable SICNOMI72_DIAS integer;
declare variable RELA_SICXMLS05_P bigint;
declare variable TIPO_P varchar(1);
declare variable IMPORTE_P double precision;
declare variable CANTIDAD_P double precision;
declare variable CLAVEOTROS_P varchar(400);
declare variable SUBSIDIO_P numeric(15,2);
declare variable ANO_P integer;
declare variable REMANENTE_P double precision;
declare variable SALDOFAVOR_P double precision;
declare variable ID_SICNOMI05 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable CLAVENTFED varchar(50);
declare variable RELA_SOCMAIN80 bigint;
declare variable ESTADO varchar(400);
begin
    RELA_SICNOMI70 = null;
    select
    sicnomi72_cab_xperiodo.rela_socmain01,
    sicnomi72_cab_xperiodo.rela_socmain21,
    sicnomi72_cab_xperiodo.rela_socusua01,
    sicnomi72_cab_xperiodo.sicnomi72_tiponomina,
    sicnomi72_cab_xperiodo.sicnomi72_fecha,
    sicnomi72_cab_xperiodo.sicnomi72_fini,
    sicnomi72_cab_xperiodo.sicnomi72_ffin,
    sicnomi72_cab_xperiodo.sicnomi72_dias
    from sicnomi72_cab_xperiodo
    where sicnomi72_cab_xperiodo.id_sicnomi72 = :rela_sicnomi72
    INTO :rela_socmain01,
         :rela_socmain21,
         :rela_socusua01,
         :sicnomi72_tiponomina,
         :sicnomi72_fecha,
         :sicnomi72_fini,
         :sicnomi72_ffin,
         :sicnomi72_dias;

    /* ------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------ */

    DELETE FROM TMP_SICNOMI73 WHERE TMP_SICNOMI73.usuario = current_user;

    INSERT INTO tmp_sicnomi73( tmp_sicnomi73.usuario,
                               tmp_sicnomi73.rela_sicxmls05,
                               tmp_sicnomi73.tipo,
                               tmp_sicnomi73.sicnomi73_cantidad,
                               tmp_sicnomi73.sicnomi71_importe,
                               tmp_sicnomi73.sicnomi71_claveotros,
                               tmp_sicnomi73.sicnomi71_subsidio,
                               tmp_sicnomi73.sicnomi71_ano,
                               tmp_sicnomi73.sicnomi71_remanente,
                               tmp_sicnomi73.sicnomi71_saldofavor)
    SELECT
    current_user,
    GRD_SICNOMI71_PERCEPCIONES.rela_sicxmls05,
    GRD_SICNOMI71_PERCEPCIONES.sicxmls05_tipo,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_cantidad,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_importe,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_claveotros,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_subsidio,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_ano,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_remanente,
    GRD_SICNOMI71_PERCEPCIONES.sicnomi71_saldofavor
    FROM GRD_SICNOMI71_PERCEPCIONES(:rela_socmain01, :rela_sicnomi01)
    WHERE  GRD_SICNOMI71_PERCEPCIONES.sicnomi71_importe <> 0

    UNION ALL

    SELECT
    current_user,
    GRD_SICNOMI71_DEDUCCIONES.rela_sicxmls05,
    GRD_SICNOMI71_DEDUCCIONES.sicxmls05_tipo,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_cantidad,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_importe,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_claveotros,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_subsidio,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_ano,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_remanente,
    GRD_SICNOMI71_DEDUCCIONES.sicnomi71_saldofavor
    FROM GRD_SICNOMI71_DEDUCCIONES(:rela_socmain01, :rela_sicnomi01)
    WHERE GRD_SICNOMI71_DEDUCCIONES.sicnomi71_importe <> 0;
    
    /* ------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------ */

    FOR select
    tmp_sicnomi73.rela_sicxmls05,
    tmp_sicnomi73.tipo,
    tmp_sicnomi73.sicnomi73_cantidad,
    tmp_sicnomi73.sicnomi71_importe,
    tmp_sicnomi73.sicnomi71_claveotros,
    tmp_sicnomi73.sicnomi71_subsidio,
    tmp_sicnomi73.sicnomi71_ano,
    tmp_sicnomi73.sicnomi71_remanente,
    tmp_sicnomi73.sicnomi71_saldofavor

    FROM tmp_sicnomi73
    WHERE tmp_sicnomi73.usuario = current_user
    into :rela_sicxmls05_p,
         :tipo_p,
         :cantidad_p,
         :importe_p,
         :claveotros_p,
         :subsidio_p,
         :ano_p,
         :remanente_p,
         :saldofavor_p
    do
    begin
        if (RELA_SICNOMI70 is null) then
        begin
            insert into sicnomi70_cab_nomina( sicnomi70_cab_nomina.rela_socmain01,
                                      sicnomi70_cab_nomina.rela_socmain21,
                                      sicnomi70_cab_nomina.rela_socusua01,
                                      sicnomi70_cab_nomina.rela_sicnomi01,
                                      sicnomi70_cab_nomina.sicnomi70_tiponomina,
                                      sicnomi70_cab_nomina.sicnomi70_fecha,
                                      sicnomi70_cab_nomina.sicnomi70_fini,
                                      sicnomi70_cab_nomina.sicnomi70_ffin,
                                      sicnomi70_cab_nomina.sicnomi70_dias )
            values( :rela_socmain01,
                    :rela_socmain21,
                    :rela_socusua01,
                    :rela_sicnomi01,
                    :sicnomi72_tiponomina,
                    :sicnomi72_fecha,
                    :sicnomi72_fini,
                    :sicnomi72_ffin,
                    :sicnomi72_dias );

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICNOMI70'
            INTO :rela_sicnomi70;
        end


        insert into sicnomi71_det_nomina( sicnomi71_det_nomina.rela_sicnomi70,
                                          sicnomi71_det_nomina.rela_sicxmls05,
                                          sicnomi71_det_nomina.sicnomi71_tipo,
                                          sicnomi71_det_nomina.sicnomi71_importe,
                                          sicnomi71_det_nomina.sicnomi71_cantidad,
                                          sicnomi71_det_nomina.sicnomi71_claveotros,
                                          sicnomi71_det_nomina.sicnomi71_subsidio,
                                          sicnomi71_det_nomina.sicnomi71_ano,
                                          sicnomi71_det_nomina.sicnomi71_remanente,
                                          sicnomi71_det_nomina.sicnomi71_saldofavor )
        values( :rela_sicnomi70,
                :rela_sicxmls05_p,
                :tipo_p,
                :importe_p,
                :cantidad_p,
                :claveotros_p,
                :subsidio_p,
                :ano_p,
                :remanente_p,
                :saldofavor_p );

    end

    clavEntFed = null;
    id_sicnomi05 = null;

    select sicnomi05_det_nomina.id_sicnomi05
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'ANTIGUEDAD'
    into :id_sicnomi05;

    if (id_sicnomi05 is not null) then
        update sicnomi05_det_nomina set sicnomi05_det_nomina.sicnomi05_valor = :antiguedad,
                                        sicnomi05_det_nomina.sicnomi05_descripcion = 'N/A'
        where sicnomi05_det_nomina.id_sicnomi05 = :id_sicnomi05;



    select
    sicnomi05_det_nomina.id_sicnomi05,
    sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'CLAVEENTFED'
    into :id_sicnomi05,
         :clavEntFed;

    if (clavEntFed is null) then
        clavEntFed = '';

    clavEntFed = trim(clavEntFed);

    if (id_sicnomi05 is not null and clavEntFed = '' ) then
    begin
        Select socmain01_cab_empresas.rela_socusua30
        from socmain01_cab_empresas
        where socmain01_cab_empresas.id_socmain01 = :rela_socmain01
        into :rela_socusua30;

        Select socusua36_det_domicilios.rela_socmain80
        from socusua36_det_domicilios
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
        INTO :rela_socmain80;

        Select socmain80_cab_codpostales.socmain80_d_estado
        from socmain80_cab_codpostales
        where socmain80_cab_codpostales.id_socmain80 = :rela_socmain80
        into :estado;

        estado = TRIM(UPPER(estado));
        clavEntFed = null;

        select socsyst11_det_sat.socsyst11_codigo
        from socsyst11_det_sat
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socsyst11_det_sat.rela_socsyst10 )
        where socsyst10_det_entradas.socsyst10_codigo = 'CLAVEENTFED'
        and TRIM(UPPER(socsyst11_det_sat.socsyst11_descripcion)) like '%' || :estado || '%'
        INTO :clavEntFed;

        if (clavEntFed is not null) then
            update sicnomi05_det_nomina set sicnomi05_det_nomina.sicnomi05_valor = :clavEntFed,
                                            sicnomi05_det_nomina.sicnomi05_descripcion = 'N/A'
            where sicnomi05_det_nomina.id_sicnomi05 = :id_sicnomi05; 
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICNOMI74 (
    RELA_SICNOMI70 BIGINT,
    SICNOMI74_VERSION_CFDI VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID_FECHA TIMESTAMP)
RETURNS (
    ID_SICXMLS41 BIGINT)
AS
declare variable ID_SICXMLS40 bigint;
declare variable ID_SOCSYST10_XML01 bigint;
declare variable ID_SOCSYST10_TCT01 bigint;
declare variable RELA_SICNOMI01 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable SICNOMI70_SERIE varchar(50);
declare variable SICNOMI70_DOCNRO varchar(50);
declare variable SICNOMI70_FECHA date;
declare variable ENTIDAD varchar(1000);
declare variable CURP varchar(50);
declare variable RFC varchar(50);
declare variable TOT_PERCEPCIONES double precision;
declare variable TOT_DEDUCCIONES double precision;
declare variable ID_SICXMLS04 bigint;
declare variable SICXMLS04_CONCEPTO varchar(400);
declare variable ID_SICXMLS05 bigint;
declare variable SICXMLS05_TIPO varchar(1);
declare variable SICXMLS05_TIPOSAT varchar(50);
declare variable SICXMLS05_GRAVADO integer;
declare variable SICXMLS05_CONCEPTO varchar(400);
declare variable RELA_SICXMLS05_GRAVADO bigint;
declare variable RELA_SICXMLS05_EXCENTO bigint;
declare variable SICNOMI71_CANTIDAD double precision;
declare variable SICNOMI71_IMPORTE double precision;
declare variable SICNOMI71_IMPORTE_GRAVADO double precision;
declare variable SICNOMI71_IMPORTE_EXENTO double precision;
declare variable RELA_SOCUSUA30_EMISOR bigint;
declare variable CODPOSTAL integer;
declare variable CODPOSTAL_C varchar(50);
declare variable RELA_SICXMLS01 bigint;
begin
    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS40'
    INTO :ID_SICXMLS40;

    select cbo_socsyst10_xml01.id_socsyst10
    from cbo_socsyst10_xml01
    where cbo_socsyst10_xml01.socsyst10_codigo = 'NOMINA'
    INTO :id_socsyst10_xml01;

    select cbo_socsyst10_tct01.id_socsyst10
    from cbo_socsyst10_tct01
    where cbo_socsyst10_tct01.socsyst10_codigo = 'NOMINA'
    INTO :id_socsyst10_tct01;

    select
    sicnomi70_cab_nomina.rela_sicnomi01,
    sicnomi70_cab_nomina.rela_socmain01,
    sicnomi70_cab_nomina.sicnomi70_serie,
    sicnomi70_cab_nomina.sicnomi70_docnro,
    sicnomi70_cab_nomina.sicnomi70_fecha
    from sicnomi70_cab_nomina
    where sicnomi70_cab_nomina.id_sicnomi70 = :rela_sicnomi70
    into :rela_sicnomi01,
         :rela_socmain01,
         :sicnomi70_serie,
         :sicnomi70_docnro,
         :sicnomi70_fecha;

    if (sicnomi70_serie is null) then
        sicnomi70_serie = '';

    select sum(sicnomi71_det_nomina.sicnomi71_importe)
    from sicnomi71_det_nomina
    where sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
    and (sicnomi71_det_nomina.sicnomi71_tipo = 'P' or
         sicnomi71_det_nomina.sicnomi71_tipo = 'O' or
         sicnomi71_det_nomina.sicnomi71_tipo = 'H')
    into :tot_percepciones;

    select sum(sicnomi71_det_nomina.sicnomi71_importe)
    from sicnomi71_det_nomina
    where sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
    and (sicnomi71_det_nomina.sicnomi71_tipo = 'D' or
         sicnomi71_det_nomina.sicnomi71_tipo = 'I')
    into :tot_deducciones;

    if (tot_deducciones is null) then
        tot_deducciones = 0.00;

    if (tot_deducciones is null) then
        tot_deducciones = 0.00;

    select
    cbo_sicnomi01_curp.rela_socusua30,
    cbo_sicnomi01_curp.entidad,
    cbo_sicnomi01_curp.curp,
    cbo_sicnomi01_curp.rfc
    from cbo_sicnomi01_curp
    where cbo_sicnomi01_curp.id_sicnomi01 = :rela_sicnomi01
    into :rela_socusua30,
         :entidad,
         :curp,
         :rfc;

    select socmain01_cab_empresas.rela_socusua30
    from sicxmls40_cab_migracion
    inner join socmain01_cab_empresas on ( socmain01_cab_empresas.id_socmain01 =  sicxmls40_cab_migracion.rela_socmain01 )
    where sicxmls40_cab_migracion.id_sicxmls40 = :id_sicxmls40
    into :rela_socusua30_emisor;

    codpostal = null;

    select first 1 socusua36_det_domicilios.socusua36_codpostal
    from socusua36_det_domicilios
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01 )
    where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_emisor
    and socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
    into :codpostal;

    codpostal_c = '';

    if (codpostal is not null) then
    begin
        codpostal_c = cast(codpostal as varchar(50));
        if (char_length(codpostal_c) < 5) then
            codpostal_c = lpad(codpostal, 5, '0');
    end

    id_sicxmls04 = null;

    select first 1
    sicxmls04_det_conceptos.id_sicxmls04,
    sicxmls04_det_conceptos.sicxmls04_concepto
    from sicxmls04_det_conceptos
    inner join sicxmls01_cab_parametros on ( sicxmls01_cab_parametros.id_sicxmls01 = sicxmls04_det_conceptos.rela_sicxmls01 )
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    and (upper(sicxmls04_det_conceptos.sicxmls04_concepto) like '%NÓMINA%' OR
         upper(sicxmls04_det_conceptos.sicxmls04_concepto) like '%NOMINA%')
    into :id_sicxmls04,
         :sicxmls04_concepto;

    if (id_sicxmls04 is null) then
    begin
        sicxmls04_concepto = 'PAGO DE NOMINA';

        select sicxmls01_cab_parametros.id_sicxmls01
        from sicxmls01_cab_parametros
        where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
        into :rela_sicxmls01;

        insert into sicxmls04_det_conceptos(sicxmls04_det_conceptos.rela_sicxmls01,
                                            sicxmls04_det_conceptos.rela_socsyst10_tct01,
                                            sicxmls04_det_conceptos.sicxmls04_tipo,
                                            sicxmls04_det_conceptos.sicxmls04_concepto,
                                            sicxmls04_det_conceptos.sicxmls04_excento,
                                            sicxmls04_det_conceptos.sicxmls04_deducible,
                                            sicxmls04_det_conceptos.sicxmls04_claveprodserv,
                                            sicxmls04_det_conceptos.sicxmls04_unidad )
        values(:rela_sicxmls01,
               :id_socsyst10_tct01,
               'E',
               :sicxmls04_concepto,
               0,
               1,
               '84111505',
               'ACT' );



        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS04'
        INTO :id_sicxmls04;
    end

    insert into sicxmls41_det_migracion(sicxmls41_det_migracion.rela_sicxmls40,
                                        sicxmls41_det_migracion.rela_socsyst10_xml01,
                                        sicxmls41_det_migracion.rela_socsyst10_tct01,
                                        sicxmls41_det_migracion.rela_socusua30,
                                        sicxmls41_det_migracion.sicxmls41_version,
                                        sicxmls41_det_migracion.sicxmls41_entidad,
                                        sicxmls41_det_migracion.sicxmls41_rfc,
                                        sicxmls41_det_migracion.sicxmls41_folio,
                                        sicxmls41_det_migracion.sicxmls41_uuid,
                                        sicxmls41_det_migracion.sicxmls41_uuid_importe,
                                        sicxmls41_det_migracion.sicxmls41_uuid_fecha,
                                        sicxmls41_det_migracion.sicxmls41_uuid_smx,
                                        sicxmls41_det_migracion.sicxmls41_tipocomprobante,
                                        sicxmls41_det_migracion.sicxmls41_metododepago,
                                        sicxmls41_det_migracion.sicxmls41_formapago,
                                        sicxmls41_det_migracion.sicxmls41_moneda,
                                        sicxmls41_det_migracion.sicxmls41_cambio,
                                        sicxmls41_det_migracion.sicxmls41_subtotal,
                                        sicxmls41_det_migracion.sicxmls41_descuento,
                                        sicxmls41_det_migracion.sicxmls41_extranjero,
                                        sicxmls41_det_migracion.sicxmls41_diferencia,
                                        sicxmls41_det_migracion.sicxmls41_fecha_pago,
                                        sicxmls41_det_migracion.sicxmls41_curp,
                                        sicxmls41_det_migracion.sicxmls41_origen,
                                        sicxmls41_det_migracion.SICXMLS41_LUGAREXPEDICION)
    values(:id_sicxmls40,
           :id_socsyst10_xml01,
           :id_socsyst10_tct01,
           :rela_socusua30,
           :sicnomi74_version_cfdi,
           :entidad,
           :rfc,
           trim(:sicnomi70_docnro),
           trim(upper(:sicnomi74_uuid)),
           :tot_percepciones - :tot_deducciones,
           :sicnomi74_uuid_fecha,
           :sicnomi74_uuid_smx,
           'egreso',
           'PUE',
           'NA',
           'MXN',
           1,
           :tot_percepciones,
           :tot_deducciones,
           0,
           0,
           :sicnomi70_fecha,
           :curp,
           'N',
           :codpostal_c);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS41'
    INTO :ID_SICXMLS41;

    insert into sicxmls42_det_conceptos( sicxmls42_det_conceptos.rela_sicxmls41,
                                         sicxmls42_det_conceptos.rela_sicxmls04,
                                         sicxmls42_det_conceptos.sicxmls42_concepto,
                                         sicxmls42_det_conceptos.sicxmls42_cantidad,
                                         sicxmls42_det_conceptos.sicxmls42_importe,
                                         sicxmls42_det_conceptos.sicxmls42_unidad,
                                         sicxmls42_det_conceptos.sicxmls42_unidad_valor,
                                         sicxmls42_det_conceptos.sicxmls42_noidentificacion,
                                         sicxmls42_det_conceptos.sicxmls42_claveprodserv)
    values(:id_sicxmls41,
           :id_sicxmls04,
           :sicxmls04_concepto,
           1,
           :tot_percepciones - :tot_deducciones,
           'ACT',
           :tot_percepciones - :tot_deducciones,
           '',
           '84111505');


    for select
    sicxmls05_det_nomina.id_sicxmls05,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicxmls05_det_nomina.sicxmls05_gravado,
    sicxmls05_det_nomina.sicxmls05_concepto,
    sicnomi71_det_nomina.sicnomi71_cantidad,
    sicnomi71_det_nomina.sicnomi71_importe
    from sicnomi71_det_nomina
    inner join sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :rela_sicnomi70
    into :id_sicxmls05,
         :sicxmls05_tipo,
         :sicxmls05_tiposat,
         :sicxmls05_gravado,
         :sicxmls05_concepto,
         :sicnomi71_cantidad,
         :sicnomi71_importe
    do
    begin
        rela_sicxmls05_gravado = null;
        rela_sicxmls05_excento = null;
        sicnomi71_importe_gravado = 0;
        sicnomi71_importe_exento = 0;

        if (sicxmls05_gravado = 0) then
        begin
           rela_sicxmls05_excento = :id_sicxmls05;
           sicnomi71_importe_exento = :sicnomi71_importe;
        end
        else
        begin
           rela_sicxmls05_gravado = :id_sicxmls05;
           sicnomi71_importe_gravado = :sicnomi71_importe;
        end

        insert into sicxmls46_det_nomina( sicxmls46_det_nomina.rela_sicxmls41,
                                      sicxmls46_det_nomina.rela_sicxmls05_gravado,
                                      sicxmls46_det_nomina.rela_sicxmls05_excento,
                                      sicxmls46_det_nomina.sicxmls46_tipo,
                                      sicxmls46_det_nomina.sicxmls46_tipo_sat,
                                      sicxmls46_det_nomina.sicxmls46_cantidad,
                                      sicxmls46_det_nomina.sicxmls46_concepto,
                                      sicxmls46_det_nomina.sicxmls46_importe_gavado,
                                      sicxmls46_det_nomina.sicxmls46_importe_exento)

        values(:id_sicxmls41,
               :rela_sicxmls05_gravado,
               :rela_sicxmls05_excento,
               :sicxmls05_tipo,
               :sicxmls05_tiposat,
               :sicnomi71_cantidad,
               :sicxmls05_concepto,
               :sicnomi71_importe_gravado,
               :sicnomi71_importe_exento);
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICPAGO70 (
    ID_SOCMAIN01 BIGINT,
    ID_SOCMAIN21 BIGINT,
    ID_SOCUSUA01 BIGINT,
    ID_SICINGR51 SMALLINT)
AS
begin
    insert into sicpago70_cab_pago ( sicpago70_cab_pago.rela_socmain01,
                                     sicpago70_cab_pago.rela_socmain21,
                                     sicpago70_cab_pago.rela_socusua01,
                                     sicpago70_cab_pago.rela_sicingr51)
    values( :id_socmain01,
            :id_socmain21,
            :id_socusua01,
            :id_sicingr51);
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS01_UPDATE_CTAS (
    ID BIGINT,
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OLD_RELA_SICCONT02 BIGINT,
    NEW_RELA_SICCONT02 BIGINT)
AS
begin
    if (old_rela_siccont02 <> new_rela_siccont02) then
    begin
        if (TIPO = 'I') then
        BEGIN
            UPDATE siccont11_det_polizas SET siccont11_det_polizas.rela_siccont02 = :new_rela_siccont02
            WHERE siccont11_det_polizas.rela_siccont02 = :old_rela_siccont02
            and not exists ( select first 1 siccont20_cab_cierre.id_siccont20
                             from siccont20_cab_cierre
                             where siccont20_cab_cierre.siccont20_ano = siccont11_det_polizas.siccont11_ano
                           )
            and exists ( select first 1 siccont12_mov_dropzone.id_siccont12
                         from siccont12_mov_dropzone
                         where siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11
                         and siccont12_mov_dropzone.rela_sicxmls02 = :id
                        );
        END
        ELSE if (TIPO = 'T') then
        BEGIN
           /*
           SON IMPUESTOS TRASLADADOS... QUE SE APLICA EN BANCOS NO EN EL DROPZONE
           */
        END
        ELSE if (TIPO = 'C') then
        BEGIN
            UPDATE siccont11_det_polizas SET siccont11_det_polizas.rela_siccont02 = :new_rela_siccont02
            WHERE siccont11_det_polizas.rela_siccont02 = :old_rela_siccont02
            and not exists ( select first 1 siccont20_cab_cierre.id_siccont20
                             from siccont20_cab_cierre
                             where siccont20_cab_cierre.siccont20_ano = siccont11_det_polizas.siccont11_ano
                           )
            and exists ( select first 1 siccont12_mov_dropzone.id_siccont12
                         from siccont12_mov_dropzone
                         where siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11
                         and siccont12_mov_dropzone.rela_sicxmls04 = :id
                        );
        END
        ELSE if (TIPO = 'N') then
        BEGIN
            UPDATE siccont11_det_polizas SET siccont11_det_polizas.rela_siccont02 = :new_rela_siccont02
            WHERE siccont11_det_polizas.rela_siccont02 = :old_rela_siccont02
            and not exists ( select first 1 siccont20_cab_cierre.id_siccont20
                             from siccont20_cab_cierre
                             where siccont20_cab_cierre.siccont20_ano = siccont11_det_polizas.siccont11_ano
                           )
            and exists ( select first 1 siccont12_mov_dropzone.id_siccont12
                         from siccont12_mov_dropzone
                         where siccont12_mov_dropzone.rela_siccont11 = siccont11_det_polizas.id_siccont11
                         and siccont12_mov_dropzone.rela_sicxmls05 = :id
                        );
        END
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS04_FIND (
    ID_SICXMLS01 BIGINT,
    ID_SOCSYST10_TCT01 BIGINT,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICXMLS04 BIGINT)
AS
begin
    id_sicxmls04 = null;
    concepto = upper(trim(concepto));
    tipo = trim(upper(tipo));

    select sicxmls04_det_conceptos.id_sicxmls04
    from sicxmls04_det_conceptos
    where sicxmls04_det_conceptos.rela_sicxmls01 = :id_sicxmls01
    and sicxmls04_det_conceptos.rela_socsyst10_tct01 = :id_socsyst10_tct01
    and sicxmls04_det_conceptos.sicxmls04_concepto = :concepto
    and sicxmls04_det_conceptos.sicxmls04_tipo = :tipo
    into :id_sicxmls04;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS04_INSERT (
    ID_SICXMLS01 BIGINT,
    ID_SOCSYST10_TCT01 BIGINT,
    ID_SICCONT02 BIGINT,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXENTO INTEGER,
    DEDUCIBLE INTEGER,
    CLAVEPRODSERV VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICXMLS04 BIGINT)
AS
begin
    select PRD_SICXMLS04_FIND.id_sicxmls04
    from PRD_SICXMLS04_FIND(:id_sicxmls01, :id_socsyst10_tct01, :concepto, :tipo)
    into :id_sicxmls04;

    if (id_sicxmls04 is null) then
    begin
        claveprodserv = iif(claveprodserv is null, '01010101', claveprodserv);
        unidad = iif(unidad is null, 'H87', unidad);

        insert into sicxmls04_det_conceptos( sicxmls04_det_conceptos.rela_sicxmls01,
                                             sicxmls04_det_conceptos.rela_socsyst10_tct01,
                                             sicxmls04_det_conceptos.rela_siccont02,
                                             sicxmls04_det_conceptos.sicxmls04_tipo,
                                             sicxmls04_det_conceptos.sicxmls04_concepto,
                                             sicxmls04_det_conceptos.sicxmls04_excento,
                                             sicxmls04_det_conceptos.sicxmls04_deducible,
                                             sicxmls04_det_conceptos.sicxmls04_claveprodserv,
                                             sicxmls04_det_conceptos.sicxmls04_unidad )
        values( :id_sicxmls01,
                :id_socsyst10_tct01,
                :id_siccont02,
                :tipo,
                :concepto,
                :exento,
                :deducible,
                :claveprodserv,
                :unidad );

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS04'
        INTO :id_sicxmls04;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS04_PARAMETRIZAR (
    RELA_SICXMLS01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    RELA_SOCSYST10_TCT01 BIGINT,
    RELA_SICCONT02 BIGINT,
    FILTRO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_IVA INTEGER,
    DEDUCIBLE INTEGER)
RETURNS (
    STATUS INTEGER)
AS
declare variable ID_SICXMLS04 bigint;
declare variable CON_SELECCION bigint;
begin
    FILTRO = UPPER(trim(FILTRO));
    CON_SELECCION = null;

    select first 1 sicxmls10_tmp_sicxmls04.id_sicxmls10
    from sicxmls10_tmp_sicxmls04
    where sicxmls10_tmp_sicxmls04.sicxmls10_usuario = current_user
    into :con_seleccion;

    if (CON_SELECCION IS NULL) then
    BEGIN
        if (RELA_SOCUSUA30 <> -1) then
        begin
            for select
            grd_sicxmls04_sinpara_xprove.id_sicxmls04
            from grd_sicxmls04_sinpara_xprove
            where grd_sicxmls04_sinpara_xprove.RELA_SICXMLS01 = :rela_sicxmls01
            and grd_sicxmls04_sinpara_xprove.rela_socusua30 = :rela_socusua30
            and grd_sicxmls04_sinpara_xprove.RELA_SOCSYST10_TCT01 = :RELA_SOCSYST10_TCT01
            and grd_sicxmls04_sinpara_xprove.sicxmls04_concepto like '%' || :FILTRO || '%'
            into :id_sicxmls04
            do
            begin
                update sicxmls04_det_conceptos set sicxmls04_det_conceptos.rela_siccont02 = :rela_siccont02,
                                                   sicxmls04_det_conceptos.sicxmls04_deducible = :deducible,
                                                   sicxmls04_det_conceptos.sicxmls04_excento = :tipo_iva
                where sicxmls04_det_conceptos.id_sicxmls04 = :id_sicxmls04;
            end

            status = 1;
            suspend;
        end
        else
        begin
            for select
            grd_sicxmls04_sinpara_xfiltro.id_sicxmls04
            from grd_sicxmls04_sinpara_xfiltro
            where grd_sicxmls04_sinpara_xfiltro.RELA_SICXMLS01 = :rela_sicxmls01
            and grd_sicxmls04_sinpara_xfiltro.RELA_SOCSYST10_TCT01 = :RELA_SOCSYST10_TCT01
            and grd_sicxmls04_sinpara_xfiltro.sicxmls04_concepto like '%' || :FILTRO || '%'
            into :id_sicxmls04
            do
            begin
                update sicxmls04_det_conceptos set sicxmls04_det_conceptos.rela_siccont02 = :rela_siccont02,
                                                   sicxmls04_det_conceptos.sicxmls04_deducible = :deducible,
                                                   sicxmls04_det_conceptos.sicxmls04_excento = :tipo_iva
                where sicxmls04_det_conceptos.id_sicxmls04 = :id_sicxmls04;
            end

            status = 1;
            suspend;
        end    
    END
    ELSE
    BEGIN
        for select sicxmls10_tmp_sicxmls04.sicxmls10_sicxmls04
        from sicxmls10_tmp_sicxmls04
        where sicxmls10_tmp_sicxmls04.sicxmls10_usuario = current_user
        into :id_sicxmls04
        do
        begin
            update sicxmls04_det_conceptos set sicxmls04_det_conceptos.rela_siccont02 = :rela_siccont02,
                                               sicxmls04_det_conceptos.sicxmls04_deducible = :deducible,
                                               sicxmls04_det_conceptos.sicxmls04_excento = :tipo_iva
            where sicxmls04_det_conceptos.id_sicxmls04 = :id_sicxmls04;
        end
    END

    delete from sicxmls10_tmp_sicxmls04 where sicxmls10_tmp_sicxmls04.sicxmls10_usuario = current_user;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS40_VALIDA (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    ID INTEGER,
    MENSAJE VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    AJUSTE DOUBLE PRECISION)
AS
declare variable ID_SOCMAIN01X bigint;
declare variable ID_SOCMAIN10 bigint;
declare variable ID_SOCSYST20 bigint;
declare variable ID_SOCSYST21 bigint;
declare variable ID_SICCONT01 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable ID_SICXMLS03 bigint;
declare variable ID_SOCUSUA32 bigint;
declare variable ID_SOCMAIN05 bigint;
declare variable CADENA_MENSAJE varchar(100);
begin
    ID = 0;
    ID_SOCMAIN01X = null;
    ID_SOCMAIN10 = null;
    ID_SOCSYST20 = null;
    ID_SOCSYST21 = null;
    ID_SICCONT01 = null;
    id_socusua32 = null;
    CADENA_MENSAJE = 'Debe Crear Empresa y ';

    select socmain01_cab_empresas.id_socmain01
    from socmain01_cab_empresas
    where socmain01_cab_empresas.id_socmain01 = :id_socmain01
    into :ID_SOCMAIN01X;

    if (ID_SOCMAIN01X is null) then
    begin
        ID = ID + 1;
        mensaje = 'No tiene creada la Empresa';
        suspend;
    end
    else
    begin
        CADENA_MENSAJE = 'La empresa no tiene ';
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select first 1 socusua32_det_documentos.id_socusua32
    from socsyst10_det_entradas
    inner join socusua32_det_documentos on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
    inner join socusua30_cab_entidades on (socusua32_det_documentos.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
    inner join socmain01_cab_empresas on (socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30)
    where socmain01_cab_empresas.id_socmain01 = :ID_SOCMAIN01X
    and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
    into :id_socusua32;

    if (id_socusua32 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'registrado el RFC';
        suspend; 
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select first 1 socmain05_det_bancos.id_socmain05
    from socmain05_det_bancos
    inner join socmain01_cab_empresas on (socmain05_det_bancos.rela_socmain01 = socmain01_cab_empresas.id_socmain01)
    where socmain01_cab_empresas.id_socmain01 = :ID_SOCMAIN01X
    into :id_socmain05;

    if (id_socmain05 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'Cuentas de Bancos';
        suspend; 
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    SELECT socmain10_det_contadores.id_socmain10
    FROM socmain10_det_contadores
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socmain10_det_contadores.rela_socsyst10_co001)
    WHERE socmain10_det_contadores.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'SICCONT10'
    INTO :id_socmain10;

    if (id_socmain10 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'creada la Modalidad de los Contadores';
        suspend;
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select socsyst20_cab_contaempr.id_socsyst20
    from socsyst20_cab_contaempr
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socsyst20_cab_contaempr.rela_socsyst10_co001)
    WHERE socsyst20_cab_contaempr.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'SICCONT10'
    into :id_socsyst20;

    select socsyst21_cab_contaorga.id_socsyst21
    from socsyst21_cab_contaorga
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socsyst21_cab_contaorga.rela_socsyst10_co001)
    WHERE socsyst21_cab_contaorga.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = 'SICCONT10'
    into :id_socsyst21;

    if (id_socsyst20 is null and id_socsyst21 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'Creado los Contadores de Pólizas';
        suspend;
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select siccont01_cab_planctas.id_siccont01
    from siccont01_cab_planctas
    where siccont01_cab_planctas.rela_socmain01 = :id_socmain01
    into :id_siccont01;

    if (id_siccont01 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'Creado el Catálogo de Cuentas';
        suspend;
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    into :id_sicxmls01;

    if (id_sicxmls01 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'Creada la Configuración del Drop Zone';
        suspend;
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select first 1 SICXMLS03_DET_CUENTAS.id_sicxmls03
    from SICXMLS03_DET_CUENTAS
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = SICXMLS03_DET_CUENTAS.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    into :id_sicxmls03;

    if (id_sicxmls03 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'Cuentas Anclas del Drop Zone';
        suspend;
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    select first 1 SICXMLS03_DET_CUENTAS.id_sicxmls03
    from SICXMLS03_DET_CUENTAS
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = SICXMLS03_DET_CUENTAS.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and SICXMLS03_DET_CUENTAS.rela_siccont02 is null
    into :id_sicxmls03;

    if (id_sicxmls03 is null) then
    begin
        ID = ID + 1;
        mensaje = CADENA_MENSAJE || 'Cuentas Anclas del Drop Zone no todas estan configuradas';
        suspend;
    end

    /* --------------------------------------------------------------------------------------------------------------------- */

    if (id = 0) then
    BEGIN
        ID = ID + 1;
        mensaje = 'OK';
        select sicxmls01_cab_parametros.sicxmls01_ajuste_monto
        from sicxmls01_cab_parametros
        where sicxmls01_cab_parametros.id_sicxmls01 = :ID_SOCMAIN01
        into :ajuste;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CREAPOLIZAS (
    ID_SOCMAIN01 BIGINT,
    ID_SOCMAIN21 BIGINT,
    ID_SOCUSUA01 BIGINT)
RETURNS (
    ID_TMPXMLS41 BIGINT,
    XMLS_PROCESADAS INTEGER,
    XMLS_POLIZAS_CREADAS INTEGER,
    XMLS_SIN_POLIZAS INTEGER,
    SINSETUP_CONCEPTOS INTEGER,
    SINSETUP_NOMINA INTEGER,
    SINSETUP_IMPUESTOS INTEGER,
    IMPORTE_PROVE DOUBLE PRECISION,
    IMPORTE_CLIENTE DOUBLE PRECISION,
    IMPORTE_NOMINA DOUBLE PRECISION,
    TMPXMLS41_FAPL TIMESTAMP)
AS
declare variable ID_SICXMLS41 bigint;
declare variable EXISTE_CONCEPTOS_SINSETUP integer;
declare variable EXISTE_IMPUESTOS_SINSETUP integer;
declare variable EXISTE_NOMINA_SINSETUP integer;
declare variable ID_SOCSYST10_CTP01 bigint;
declare variable ID_SOCSYST10_CTP02 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable RELA_SICCONT02_DESCUE_INGRESOS bigint;
declare variable RELA_SICCONT02_DESCUE_EGRESOS bigint;
declare variable RELA_SICCONT02_AJUSTE_INGRESOS bigint;
declare variable RELA_SICCONT02_AJUSTE_EGRESOS bigint;
declare variable SICXMLS41_UUID_IMPORTE double precision;
declare variable SOCSYST10_CODIGO_XML varchar(50);
begin
    xmls_procesadas = 0;
    xmls_polizas_creadas = 0;
    id_tmpxmls41 = 1;
    tmpxmls41_fapl = current_timestamp;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    into :id_sicxmls01;

    select CBO_SOCSYST10_CTP01.id_socsyst10
    from CBO_SOCSYST10_CTP01
    where CBO_SOCSYST10_CTP01.socsyst10_codigo = 'DROPZONE'
    into :id_socsyst10_ctp01;

    select CBO_SOCSYST10_CTP02.id_socsyst10
    from CBO_SOCSYST10_CTP02
    where CBO_SOCSYST10_CTP02.socsyst10_codigo = 'PO-3-DIA'
    into :id_socsyst10_ctp02;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'DESCUEI'
    into :rela_siccont02_descue_ingresos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'DESCUEE'
    into :rela_siccont02_descue_egresos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'AJUSTEI'
    into :rela_siccont02_ajuste_ingresos;

    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and socsyst10_det_entradas.socsyst10_codigo = 'AJUSTEE'
    into :rela_siccont02_ajuste_egresos;

    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */

    importe_prove = 0;
    importe_cliente = 0;
    importe_nomina = 0;

    for select
    socsyst10_det_entradas.socsyst10_codigo,
    sum(sicxmls41_det_migracion.sicxmls41_uuid_importe)
    from sicxmls41_det_migracion
    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01)
    where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo <> 'ERROR'
    and sicxmls41_det_migracion.rela_siccont10 is null
    group by socsyst10_det_entradas.socsyst10_codigo
    into :socsyst10_codigo_xml,
         :sicxmls41_uuid_importe
    do
    begin
        if (socsyst10_codigo_xml = 'PROVE') then
            importe_prove = sicxmls41_uuid_importe;
        else if (socsyst10_codigo_xml = 'CLIENTE') then
            importe_cliente = sicxmls41_uuid_importe;
        else if (socsyst10_codigo_xml = 'NOMINA') then
            importe_nomina = sicxmls41_uuid_importe;
    end

    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */

    for select
    sicxmls41_det_migracion.id_sicxmls41
    from sicxmls41_det_migracion
    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_xml01)
    where sicxmls40_cab_migracion.rela_socmain01 = :id_socmain01
    and socsyst10_det_entradas.socsyst10_codigo <> 'ERROR'
    and sicxmls41_det_migracion.rela_siccont10 is null
    into :id_sicxmls41
    do
    begin
        xmls_procesadas = xmls_procesadas + 1;

        existe_conceptos_sinsetup = 0;
        select first 1 sicxmls04_det_conceptos.id_sicxmls04
        from sicxmls42_det_conceptos
        inner join sicxmls04_det_conceptos on (sicxmls04_det_conceptos.id_sicxmls04 = sicxmls42_det_conceptos.rela_sicxmls04)
        where sicxmls42_det_conceptos.rela_sicxmls41 = :id_sicxmls41
        and sicxmls04_det_conceptos.rela_siccont02 is null
        into :existe_conceptos_sinsetup;

        if (existe_conceptos_sinsetup <> 0) then
            existe_conceptos_sinsetup = existe_conceptos_sinsetup + 1;

        existe_impuestos_sinsetup = 0;
        select first 1 sicxmls02_det_impuestos.id_sicxmls02
        from sicxmls43_det_impuestos
        inner join sicxmls02_det_impuestos on (sicxmls02_det_impuestos.id_sicxmls02 = sicxmls43_det_impuestos.rela_sicxmls02)
        where sicxmls43_det_impuestos.rela_sicxmls41 = :id_sicxmls41
        and sicxmls02_det_impuestos.rela_siccont02 is null
        into :existe_impuestos_sinsetup;

        if (existe_impuestos_sinsetup <> 0) then
            existe_impuestos_sinsetup = existe_impuestos_sinsetup + 1;

        existe_nomina_sinsetup = 0;
        select first 1 sicxmls05_det_nomina.id_sicxmls05
        from sicxmls46_det_nomina
        inner join sicxmls05_det_nomina on (sicxmls05_det_nomina.id_sicxmls05 = sicxmls46_det_nomina.rela_sicxmls05_gravado)
        where sicxmls46_det_nomina.rela_sicxmls41 = :id_sicxmls41
        and sicxmls05_det_nomina.rela_siccont02 is null
        into :existe_nomina_sinsetup;

        if (existe_nomina_sinsetup <> 0) then
            existe_nomina_sinsetup = existe_nomina_sinsetup + 1;
        else 
        begin
            select first 1 sicxmls05_det_nomina.id_sicxmls05
            from sicxmls46_det_nomina
            inner join sicxmls05_det_nomina on (sicxmls05_det_nomina.id_sicxmls05 = sicxmls46_det_nomina.rela_sicxmls05_excento)
            where sicxmls46_det_nomina.rela_sicxmls41 = :id_sicxmls41
            and sicxmls05_det_nomina.rela_siccont02 is null
            into :existe_nomina_sinsetup;

            if (existe_nomina_sinsetup <> 0) then
                existe_nomina_sinsetup = existe_nomina_sinsetup + 1;
        end

        if (existe_conceptos_sinsetup = 0 and existe_nomina_sinsetup = 0 and existe_impuestos_sinsetup = 0) then
        begin
            xmls_polizas_creadas = xmls_polizas_creadas + 1;
            
            execute procedure prd_sicxmls41_creapolizas_cab
                                                            :id_sicxmls41,
                                                            :id_socmain01,
                                                            :id_socmain21,
                                                            :id_socusua01,
                                                            :id_socsyst10_ctp01,
                                                            :id_socsyst10_ctp02,
                                                            :id_sicxmls01,
                                                            :rela_siccont02_descue_ingresos,
                                                            :rela_siccont02_descue_egresos,
                                                            :rela_siccont02_ajuste_ingresos,
                                                            :rela_siccont02_ajuste_egresos;
        end
    end

    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */

    xmls_sin_polizas = xmls_procesadas - xmls_polizas_creadas;

    select count(sicxmls04_det_conceptos.id_sicxmls04)
    from sicxmls04_det_conceptos
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls04_det_conceptos.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and sicxmls04_det_conceptos.rela_siccont02 is null
    into :sinsetup_conceptos;

    select count(sicxmls02_det_impuestos.id_sicxmls02)
    from sicxmls02_det_impuestos
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls02_det_impuestos.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and sicxmls02_det_impuestos.rela_siccont02 is null
    into :sinsetup_impuestos;

    select count(sicxmls05_det_nomina.id_sicxmls05)
    from sicxmls05_det_nomina
    inner join sicxmls01_cab_parametros on (sicxmls01_cab_parametros.id_sicxmls01 = sicxmls05_det_nomina.rela_sicxmls01)
    where sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01
    and sicxmls05_det_nomina.rela_siccont02 is null
    into :sinsetup_nomina;

    delete from sicxmls40_cab_migracion
    where not exists (Select first 1 sicxmls41_det_migracion.id_sicxmls41
                      from sicxmls41_det_migracion
                      where sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40);

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_CAB (
    ID_SICXMLS41 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCSYST10_CTP01 BIGINT,
    RELA_SOCSYST10_CTP02 BIGINT,
    ID_SICXMLS01 BIGINT,
    RELA_SICCONT02_DESCUE_INGRESOS BIGINT,
    RELA_SICCONT02_DESCUE_EGRESOS BIGINT,
    RELA_SICCONT02_AJUSTE_INGRESOS BIGINT,
    RELA_SICCONT02_AJUSTE_EGRESOS BIGINT)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable DESCRIPCION varchar(1200);
declare variable SICXMLS41_VERSION varchar(50);
declare variable SICXMLS41_FORMAPAGO varchar(400);
declare variable SICXMLS41_ENTIDAD varchar(800);
declare variable SICXMLS41_UUID varchar(50);
declare variable SICXMLS41_UUID_FECHA date;
declare variable SICXMLS41_FOLIO varchar(100);
declare variable SICXMLS41_CAMBIO double precision;
declare variable SICXMLS41_MONEDA varchar(400);
declare variable SICXMLS41_UUID_SMX varchar(50);
declare variable SICXMLS41_DESCUENTO double precision;
declare variable SICXMLS41_DIFERENCIA double precision;
declare variable SICXMLS41_UUID_IMPORTE double precision;
declare variable RELA_SOCSYST10_TCT01 bigint;
declare variable SOCSYST10_DESCRIPCION varchar(400);
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SICCONT10 bigint;
declare variable ID_SICEGRE01 bigint;
declare variable ID_SICINGR01 bigint;
declare variable ID_SICNOMI01 bigint;
declare variable TIPO_ENTIDAD varchar(1);
declare variable TIPO_MOVIMIENTO varchar(1);
declare variable ERROR_COTIZA integer;
declare variable SICXMLS41_ORIGEN varchar(1);
begin
    select
    SICXMLS41_DET_MIGRACION.sicxmls41_version,
    SICXMLS41_DET_MIGRACION.sicxmls41_formapago,
    SICXMLS41_DET_MIGRACION.rela_socsyst10_tct01,
    socsyst10_det_entradas.socsyst10_codigo,
    socsyst10_det_entradas.socsyst10_descripcion,
    SICXMLS41_DET_MIGRACION.rela_socusua30,
    SICXMLS41_DET_MIGRACION.sicxmls41_entidad,
    SICXMLS41_DET_MIGRACION.SICXMLS41_FOLIO,
    SICXMLS41_DET_MIGRACION.SICXMLS41_UUID_FECHA,
    SICXMLS41_DET_MIGRACION.SICXMLS41_CAMBIO,
    SICXMLS41_DET_MIGRACION.sicxmls41_moneda,
    SICXMLS41_DET_MIGRACION.sicxmls41_uuid,
    SICXMLS41_DET_MIGRACION.sicxmls41_uuid_smx,
    SICXMLS41_DET_MIGRACION.sicxmls41_uuid_importe,
    SICXMLS41_DET_MIGRACION.sicxmls41_descuento,
    SICXMLS41_DET_MIGRACION.sicxmls41_diferencia,
    SICXMLS41_DET_MIGRACION.sicxmls41_origen
    from SICXMLS41_DET_MIGRACION
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICXMLS41_DET_MIGRACION.rela_socsyst10_tct01)
    where SICXMLS41_DET_MIGRACION.ID_SICXMLS41 = :ID_SICXMLS41
    INTO :sicxmls41_version,
         :sicxmls41_formapago,
         :rela_socsyst10_tct01,
         :socsyst10_codigo,
         :socsyst10_descripcion,
         :rela_socusua30,
         :sicxmls41_entidad,
         :SICXMLS41_FOLIO,
         :SICXMLS41_UUID_FECHA,
         :SICXMLS41_CAMBIO,
         :sicxmls41_moneda,
         :sicxmls41_uuid,
         :sicxmls41_uuid_smx,
         :sicxmls41_uuid_importe,
         :sicxmls41_descuento,
         :sicxmls41_diferencia,
         :sicxmls41_origen;

    sicxmls41_version = iif(sicxmls41_version is null, '3.2', sicxmls41_version);
    sicxmls41_formapago = iif(sicxmls41_formapago is null, '99', sicxmls41_formapago);

    SICXMLS41_FOLIO = IIF(SICXMLS41_FOLIO IS null, '', UPPER(TRIM(SICXMLS41_FOLIO)));
    socsyst10_descripcion = upper(trim(socsyst10_descripcion));
    sicxmls41_entidad = upper(trim(sicxmls41_entidad));
    sicxmls41_moneda = upper(trim(sicxmls41_moneda));
    sicxmls41_cambio = iif(sicxmls41_cambio = 0, 1, sicxmls41_cambio);

    if (SICXMLS41_FOLIO = '') then
        DESCRIPCION  = socsyst10_descripcion || ' : ' || sicxmls41_entidad;
    else
        DESCRIPCION  = socsyst10_descripcion || ' : ' || SICXMLS41_FOLIO || ' ' || sicxmls41_entidad;

    if (char_length(DESCRIPCION) > 1200) then
       DESCRIPCION = SUBSTRING (DESCRIPCION FROM 1 FOR 1200);

    SELECT prd_sicxmls41_moneda.id_socsyst10, prd_sicxmls41_moneda.error
    FROM prd_sicxmls41_moneda(:sicxmls41_moneda, :sicxmls41_cambio)
    INTO :id_socsyst10_ctm01, error_cotiza;

    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */

    if ((socsyst10_codigo = 'CLIENTE') or (socsyst10_codigo = 'CLIENTEX')) then
    BEGIN
        tipo_entidad = 'C';                         /* CLIENTE */
        tipo_movimiento = 'I';                      /* INGRESO */

        select sicingr01_cab_clientes.id_sicingr01
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.rela_socmain01 = :rela_socmain01
        and sicingr01_cab_clientes.rela_socusua30 = :rela_socusua30
        into :id_sicingr01;
    END
    ELSE if ((socsyst10_codigo = 'PROVE') or (socsyst10_codigo = 'PROVEX')) then
    BEGIN
        tipo_entidad = 'P';                         /* PROVEEDOR */
        tipo_movimiento = 'E';                      /* EGRESO */

        select sicegre01_cab_proveedores.id_sicegre01
        from sicegre01_cab_proveedores
        where sicegre01_cab_proveedores.rela_socmain01 = :rela_socmain01
        and sicegre01_cab_proveedores.rela_socusua30 = :rela_socusua30
        into :id_sicegre01;
    END
    ELSE if ((socsyst10_codigo = 'NOMINA')) then
    BEGIN
        tipo_entidad = 'E';                         /* EMPLEADO */
        tipo_movimiento = 'N';                      /* NOMINA */

        select sicnomi01_cab_empleados.id_sicnomi01
        from sicnomi01_cab_empleados
        where sicnomi01_cab_empleados.rela_socmain01 = :rela_socmain01
        and sicnomi01_cab_empleados.rela_socusua30 = :rela_socusua30
        into :id_sicnomi01;
    END
    ELSE if ((socsyst10_codigo = 'CREADITOAFAVOR') or (socsyst10_codigo = 'CREADITOAFAVORX')) then
    BEGIN
        tipo_entidad = 'P';                         /* PROVEEDOR */
        tipo_movimiento = 'I';                      /* INGRESO */

        select sicegre01_cab_proveedores.id_sicegre01
        from sicegre01_cab_proveedores
        where sicegre01_cab_proveedores.rela_socmain01 = :rela_socmain01
        and sicegre01_cab_proveedores.rela_socusua30 = :rela_socusua30
        into :id_sicegre01;
    END
    ELSE if ((socsyst10_codigo = 'CREDITOENCONTRA') or (socsyst10_codigo = 'CREDITOENCONTRAX')) then
    BEGIN
        tipo_entidad = 'C';                         /* CLIENTE */
        tipo_movimiento = 'E';                      /* EGRESO */

        select sicingr01_cab_clientes.id_sicingr01
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.rela_socmain01 = :rela_socmain01
        and sicingr01_cab_clientes.rela_socusua30 = :rela_socusua30
        into :id_sicingr01;
    END

    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */

    insert into siccont10_cab_polizas(
    siccont10_cab_polizas.rela_socmain01,
    siccont10_cab_polizas.rela_socmain21,
    siccont10_cab_polizas.rela_socusua01,
    siccont10_cab_polizas.rela_socsyst10_ctp01,
    siccont10_cab_polizas.rela_socsyst10_ctp02,
    siccont10_cab_polizas.rela_socsyst10_ctm01,
    siccont10_cab_polizas.rela_socusua30,
    siccont10_cab_polizas.siccont10_tipo_entidad,
    siccont10_cab_polizas.siccont10_descripcion,
    siccont10_cab_polizas.siccont10_fcta,
    siccont10_cab_polizas.siccont10_cotiza,
    siccont10_cab_polizas.siccont10_uuid_smx,
    siccont10_cab_polizas.siccont10_uuid_sat,
    siccont10_cab_polizas.siccont10_origen)
    values(:rela_socmain01,
           :rela_socmain21,
           :rela_socusua01,
           :RELA_SOCSYST10_CTP01,
           :RELA_SOCSYST10_CTP02,
           :id_socsyst10_ctm01,
           :rela_socusua30,
           :tipo_entidad,
           :DESCRIPCION,
           :SICXMLS41_UUID_FECHA,
           :SICXMLS41_CAMBIO,
           :SICXMLS41_UUID_SMX,
           :sicxmls41_uuid,
           :sicxmls41_origen);

    select socsyst91_tbl_ultids.socsyst91_ultid
    from socsyst91_tbl_ultids
    WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
    AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT10'
    INTO :ID_SICCONT10;

     /* ---------------------------------------------------------------------------------------------------- */

    if (tipo_movimiento = 'I') then
    BEGIN
        if ((socsyst10_codigo = 'CLIENTE' or socsyst10_codigo = 'CLIENTEX') and id_sicingr01 is not null) then
        begin
            insert into sicingr50_det_ctacte(sicingr50_det_ctacte.rela_sicingr01,
                                             sicingr50_det_ctacte.rela_socmain01,
                                             sicingr50_det_ctacte.rela_siccont10,
                                             sicingr50_det_ctacte.sicingr50_importe)
            values(:id_sicingr01, :rela_socmain01, :id_siccont10, :sicxmls41_uuid_importe);
        end
        else if ((socsyst10_codigo = 'CREADITOAFAVOR' or socsyst10_codigo = 'CREADITOAFAVORX') and id_sicegre01 is not null) then
        begin
            insert into sicegre50_det_ctacte(sicegre50_det_ctacte.rela_sicegre01,
                                             sicegre50_det_ctacte.rela_socmain01,
                                             sicegre50_det_ctacte.rela_siccont10,
                                             sicegre50_det_ctacte.sicegre50_importe)
            values(:id_sicegre01, :rela_socmain01, :id_siccont10, (:sicxmls41_uuid_importe * -1) );

            if (sicxmls41_descuento is not null and sicxmls41_descuento <> 0) then
            begin
                rela_siccont02_descue_ingresos = rela_siccont02_descue_egresos;
                rela_siccont02_ajuste_ingresos = rela_siccont02_ajuste_egresos;
            end
        end

        execute procedure PRD_SICXMLS41_CREAPOLIZAS_ING
                  :id_siccont10,
                  :id_sicxmls01,
                  :id_sicxmls41,
                  :rela_socsyst10_tct01,
                  :rela_siccont02_descue_ingresos,
                  :rela_siccont02_ajuste_ingresos,
                  :sicxmls41_uuid_importe,
                  :sicxmls41_descuento,
                  :sicxmls41_diferencia,
                  :SICXMLS41_CAMBIO;

        EXECUTE PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_ERROR :id_siccont10, :rela_siccont02_ajuste_ingresos, :sicxmls41_cambio, :error_cotiza;
    END
    ELSE  if (tipo_movimiento = 'N' and id_sicnomi01 is not null) then
    BEGIN
        insert into sicnomi50_det_ctacte(sicnomi50_det_ctacte.rela_sicnomi01,
                                             sicnomi50_det_ctacte.rela_socmain01,
                                             sicnomi50_det_ctacte.rela_siccont10,
                                             sicnomi50_det_ctacte.sicnomi50_importe)
        values(:id_sicnomi01, :rela_socmain01, :id_siccont10, :sicxmls41_uuid_importe);

        execute procedure PRD_SICXMLS41_CREAPOLIZAS_NOM
                  :id_siccont10,
                  :id_sicxmls01,
                  :id_sicxmls41,
                  :rela_socsyst10_tct01,
                  :rela_siccont02_descue_egresos,
                  :rela_siccont02_ajuste_egresos,
                  :sicxmls41_uuid_importe,
                  :sicxmls41_descuento,
                  :sicxmls41_diferencia,
                  :SICXMLS41_CAMBIO;

        EXECUTE PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_ERROR :id_siccont10, :rela_siccont02_ajuste_egresos, :sicxmls41_cambio, :error_cotiza;
    END
    ELSE  if (tipo_movimiento = 'E') then
    BEGIN
        if ((socsyst10_codigo = 'PROVE' or socsyst10_codigo = 'PROVEX') and id_sicegre01 is not null) then
        begin
            insert into sicegre50_det_ctacte(sicegre50_det_ctacte.rela_sicegre01,
                                             sicegre50_det_ctacte.rela_socmain01,
                                             sicegre50_det_ctacte.rela_siccont10,
                                             sicegre50_det_ctacte.sicegre50_importe)
            values(:id_sicegre01, :rela_socmain01, :id_siccont10, :sicxmls41_uuid_importe);
        end
        else if ((socsyst10_codigo = 'CREDITOENCONTRA' or socsyst10_codigo = 'CREDITOENCONTRAX') and id_sicingr01 is not null) then
        begin
            insert into sicingr50_det_ctacte(sicingr50_det_ctacte.rela_sicingr01,
                                             sicingr50_det_ctacte.rela_socmain01,
                                             sicingr50_det_ctacte.rela_siccont10,
                                             sicingr50_det_ctacte.sicingr50_importe)
            values(:id_sicingr01, :rela_socmain01, :id_siccont10, (:sicxmls41_uuid_importe * -1) );

            if (sicxmls41_descuento is not null and sicxmls41_descuento <> 0) then
            begin
                rela_siccont02_descue_egresos = rela_siccont02_descue_ingresos;
                rela_siccont02_ajuste_egresos = rela_siccont02_ajuste_ingresos;
            end
        end

        execute procedure PRD_SICXMLS41_CREAPOLIZAS_EGR
                  :id_siccont10,
                  :id_sicxmls01,
                  :id_sicxmls41,
                  :rela_socsyst10_tct01,
                  :rela_siccont02_descue_egresos,
                  :rela_siccont02_ajuste_egresos,
                  :sicxmls41_uuid_importe,
                  :sicxmls41_descuento,
                  :sicxmls41_diferencia,
                  :SICXMLS41_CAMBIO;

        EXECUTE PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_ERROR :id_siccont10, :rela_siccont02_ajuste_egresos, :sicxmls41_cambio, :error_cotiza;
    END

    update sicxmls41_det_migracion set sicxmls41_det_migracion.rela_siccont10 = :id_siccont10,
                                       sicxmls41_det_migracion.sicxmls41_version = :sicxmls41_version,
                                       sicxmls41_det_migracion.sicxmls41_formapago = :sicxmls41_formapago
    where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41;

end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_EGR (
    ID_SICCONT10 BIGINT,
    ID_SICXMLS01 BIGINT,
    ID_SICXMLS41 BIGINT,
    RELA_SOCSYST10_TCT01 BIGINT,
    RELA_SICCONT02_DESCUENTOS BIGINT,
    RELA_SICCONT02_AJUSTES BIGINT,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_DESCUENTO DOUBLE PRECISION,
    SICXMLS41_DIFERENCIA DOUBLE PRECISION,
    SICXMLS41_CAMBIO DOUBLE PRECISION)
AS
declare variable RELA_SICCONT02_CTA bigint;
declare variable RELA_SICCONT02_CONCEPTOS bigint;
declare variable SICXMLS42_IMPORTE double precision;
declare variable RELA_SICCONT02_IMPUESTOS bigint;
declare variable SICXMLS02_RETENIDO integer;
declare variable SICXMLS43_IMPORTE double precision;
declare variable SICXMLS42_CONCEPTO varchar(8000);
declare variable ID_SICCONT11 bigint;
declare variable ID_SICXMLS04 bigint;
declare variable SICXMLS43_IMPUESTO varchar(400);
declare variable ID_SICXMLS02 bigint;
declare variable IMPORTE_CARGO double precision;
declare variable IMPORTE_ABONO double precision;
declare variable RELA_SICCONT02_COTIZA bigint;
begin
    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and sicxmls03_det_cuentas.rela_socsyst10_tct01 = :rela_socsyst10_tct01
    into :rela_siccont02_cta;

    if (sicxmls41_cambio > 1) then
    begin
        select sicxmls03_det_cuentas.rela_siccont02
        from sicxmls03_det_cuentas
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls03_det_cuentas.rela_socsyst10_tct01)
        where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
        and socsyst10_det_entradas.socsyst10_codigo = 'COTIZA-TARIA-PROVE'
        into :rela_siccont02_cotiza;

        INSERT INTO siccont11_det_polizas(
                    siccont11_det_polizas.rela_siccont10,
                    siccont11_det_polizas.rela_siccont02,
                    siccont11_det_polizas.siccont11_tipo_entidad,
                    siccont11_det_polizas.siccont11_debe,
                    siccont11_det_polizas.siccont11_haber,
                    siccont11_det_polizas.siccont11_ano,
                    siccont11_det_polizas.siccont11_mes,
                    siccont11_det_polizas.siccont11_nocotiza)

        VALUES(:ID_SICCONT10,
               :rela_siccont02_cta,
               'S',
               0,
               :sicxmls41_uuid_importe,
               -1,
               -1,
               1);

        INSERT INTO siccont11_det_polizas(
                    siccont11_det_polizas.rela_siccont10,
                    siccont11_det_polizas.rela_siccont02,
                    siccont11_det_polizas.siccont11_tipo_entidad,
                    siccont11_det_polizas.siccont11_debe,
                    siccont11_det_polizas.siccont11_haber,
                    siccont11_det_polizas.siccont11_ano,
                    siccont11_det_polizas.siccont11_mes,
                    siccont11_det_polizas.siccont11_nocotiza)

        VALUES(:ID_SICCONT10,
               :rela_siccont02_cotiza,
               'S',
               0,
               (:sicxmls41_uuid_importe * :sicxmls41_cambio) - :sicxmls41_uuid_importe,
               -1,
               -1,
               1);
    end
    else
    begin
        INSERT INTO siccont11_det_polizas(
                    siccont11_det_polizas.rela_siccont10,
                    siccont11_det_polizas.rela_siccont02,
                    siccont11_det_polizas.siccont11_tipo_entidad,
                    siccont11_det_polizas.siccont11_debe,
                    siccont11_det_polizas.siccont11_haber,
