CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_ERROR (
    ID_SICCONT10 BIGINT,
    RELA_SICCONT02_AJUSTES BIGINT,
    SICXMLS41_CAMBIO DOUBLE PRECISION,
    ERROR_COTIZA INTEGER)
AS
declare variable SUMA_DEBE_VERIFICA double precision;
declare variable SUMA_HABER_VERIFICA double precision;
declare variable SUMA_DIFER_VERIFICA double precision;
begin
    select
    sum(siccont11_det_polizas.siccont11_debe),
    sum(siccont11_det_polizas.siccont11_haber)
    from siccont11_det_polizas
    where siccont11_det_polizas.rela_siccont10 = :ID_SICCONT10
    into :suma_debe_verifica, :suma_haber_verifica;

    suma_debe_verifica = cast(suma_debe_verifica as numeric(15,4));
    suma_haber_verifica = cast(suma_haber_verifica as numeric(15,4));

    if (suma_debe_verifica <> suma_haber_verifica) then
    BEGIN
        suma_difer_verifica = suma_debe_verifica - suma_haber_verifica;

        if (suma_difer_verifica < 0) then
        begin
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_ajustes,
                   'S',
                   (:suma_difer_verifica*(-1)) * :sicxmls41_cambio,
                   0,
                   -1,
                   -1);
        end
        else
        begin
           INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_ajustes,
                   'S',
                   0,
                   :suma_difer_verifica * :sicxmls41_cambio,
                   -1,
                   -1);
        end

        update siccont10_cab_polizas set siccont10_cab_polizas.siccont10_error_ajuste = 'E'
        WHERE siccont10_cab_polizas.id_siccont10 = :id_siccont10;
    END
    ELSE
    BEGIN
        if (error_cotiza = 1) then
            update siccont10_cab_polizas set siccont10_cab_polizas.siccont10_error_ajuste = 'E'
            WHERE siccont10_cab_polizas.id_siccont10 = :id_siccont10; 
    END
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_ING (
