    SICXMLS41_DESCUENTO DOUBLE PRECISION,
    SICXMLS41_DIFERENCIA DOUBLE PRECISION,
    SICXMLS41_CAMBIO DOUBLE PRECISION)
AS
declare variable RELA_SICCONT02_CTA bigint;
declare variable RELA_SICCONT02_CONCEPTOS bigint;
declare variable SICXMLS42_IMPORTE double precision;
declare variable RELA_SICCONT02_IMPUESTOS bigint;
declare variable SICXMLS02_RETENIDO integer;
declare variable SICXMLS43_IMPORTE double precision;
declare variable SICXMLS42_CONCEPTO varchar(8000);
declare variable ID_SICXMLS04 bigint;
declare variable ID_SICCONT11 bigint;
declare variable ID_SICXMLS02 bigint;
declare variable SICXMLS43_IMPUESTO varchar(400);
declare variable IMPORTE_CARGO double precision;
declare variable IMPORTE_ABONO double precision;
declare variable RELA_SICCONT02_COTIZA double precision;
begin
    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
