CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CREAPOLIZAS_NOM (
    ID_SICCONT10 BIGINT,
    ID_SICXMLS01 BIGINT,
    ID_SICXMLS41 BIGINT,
    RELA_SOCSYST10_TCT01 BIGINT,
    RELA_SICCONT02_DESCUENTOS BIGINT,
    RELA_SICCONT02_AJUSTES BIGINT,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_DESCUENTO DOUBLE PRECISION,
    SICXMLS41_DIFERENCIA DOUBLE PRECISION,
    SICXMLS41_CAMBIO DOUBLE PRECISION)
AS
declare variable RELA_SICCONT02_CTA bigint;
declare variable RELA_SICCONT02_NOMINA bigint;
declare variable SICXMLS46_IMPORTE_GAVADO double precision;
declare variable SICXMLS46_IMPORTE_EXENTO double precision;
declare variable SICXMLS05_TIPO varchar(1);
declare variable ID_SICXMLS05 bigint;
declare variable SICXMLS46_CONCEPTO varchar(400);
declare variable ID_SICCONT11 bigint;
begin
    select sicxmls03_det_cuentas.rela_siccont02
    from sicxmls03_det_cuentas
    where sicxmls03_det_cuentas.rela_sicxmls01 = :id_sicxmls01
    and sicxmls03_det_cuentas.rela_socsyst10_tct01 = :rela_socsyst10_tct01
    into :rela_siccont02_cta;

    INSERT INTO siccont11_det_polizas(
                siccont11_det_polizas.rela_siccont10,
                siccont11_det_polizas.rela_siccont02,
                siccont11_det_polizas.siccont11_tipo_entidad,
                siccont11_det_polizas.siccont11_debe,
                siccont11_det_polizas.siccont11_haber,
                siccont11_det_polizas.siccont11_ano,
                siccont11_det_polizas.siccont11_mes)
    VALUES(:ID_SICCONT10,
           :rela_siccont02_cta,
           'S',
           0,
           :sicxmls41_uuid_importe,
           -1,
           -1);
    /*
    if (sicxmls41_descuento <> 0) then
    begin
        INSERT INTO siccont11_det_polizas(
                    siccont11_det_polizas.rela_siccont10,
                    siccont11_det_polizas.rela_siccont02,
                    siccont11_det_polizas.siccont11_debe,
                    siccont11_det_polizas.siccont11_haber,
                    siccont11_det_polizas.siccont11_ano,
                    siccont11_det_polizas.siccont11_mes)
        VALUES(:ID_SICCONT10,
               :rela_siccont02_descuentos,
               :sicxmls41_descuento * :sicxmls41_cambio,
               0,
               -1,
               -1);

    end
    */

    if (sicxmls41_diferencia <> 0) then
    begin
        if (sicxmls41_diferencia > 0) then
        begin
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_ajustes,
                   'S',
                   :sicxmls41_diferencia,
                   0,
                   -1,
                   -1);
        end
        else
        begin
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_ajustes,
                   'S',
                   0,
                   :sicxmls41_diferencia*-1,
                   -1,
                   -1);
        end
    end

    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */
    /* ---------------------------------------------------------------------------------------------------- */

    for select
    sicxmls05_det_nomina.id_sicxmls05,
    sicxmls05_det_nomina.rela_siccont02,
    sicxmls46_det_nomina.sicxmls46_importe_gavado,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls46_det_nomina.sicxmls46_concepto
    from sicxmls46_det_nomina
    inner join sicxmls05_det_nomina on (sicxmls05_det_nomina.id_sicxmls05 = sicxmls46_det_nomina.rela_sicxmls05_gravado)
    where sicxmls46_det_nomina.rela_sicxmls41 = :id_sicxmls41
    into :id_sicxmls05,
         :rela_siccont02_nomina,
         :sicxmls46_importe_gavado,
         :sicxmls05_tipo,
         :sicxmls46_concepto
    do
    begin
        if (sicxmls05_tipo = 'D' or sicxmls05_tipo = 'I') then
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes,
                        siccont11_det_polizas.siccont11_referencia)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_nomina,
                   'S',
                   0,
                   :sicxmls46_importe_gavado,
                   -1,
                   -1,
                   :sicxmls46_concepto);
        else
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes,
                        siccont11_det_polizas.siccont11_referencia)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_nomina,
                   'S',
                   :sicxmls46_importe_gavado,
                   0,
                   -1,
                   -1,
                   :sicxmls46_concepto);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT11'
        INTO :ID_SICCONT11;

        INSERT INTO siccont12_mov_dropzone(siccont12_mov_dropzone.rela_siccont11,
                                           siccont12_mov_dropzone.rela_sicxmls05)
        VALUES(:id_siccont11, :id_sicxmls05);
    end

    /* ---------------------------------------------------------------------------------------------------- */

    for select
    sicxmls05_det_nomina.id_sicxmls05,
    sicxmls05_det_nomina.rela_siccont02,
    sicxmls46_det_nomina.sicxmls46_importe_exento,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls46_det_nomina.sicxmls46_concepto
    from sicxmls46_det_nomina
    inner join sicxmls05_det_nomina on (sicxmls05_det_nomina.id_sicxmls05 = sicxmls46_det_nomina.rela_sicxmls05_excento)
    where sicxmls46_det_nomina.rela_sicxmls41 = :id_sicxmls41
    into :id_sicxmls05,
         :rela_siccont02_nomina,
         :sicxmls46_importe_exento,
         :sicxmls05_tipo,
         :sicxmls46_concepto
    do
    begin
       if (sicxmls05_tipo = 'D' or sicxmls05_tipo = 'I') then
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes,
                        siccont11_det_polizas.siccont11_referencia)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_nomina,
                   'S',
                   0,
                   :sicxmls46_importe_exento,
                   -1,
                   -1,
                   :sicxmls46_concepto);
        else
            INSERT INTO siccont11_det_polizas(
                        siccont11_det_polizas.rela_siccont10,
                        siccont11_det_polizas.rela_siccont02,
                        siccont11_det_polizas.siccont11_tipo_entidad,
                        siccont11_det_polizas.siccont11_debe,
                        siccont11_det_polizas.siccont11_haber,
                        siccont11_det_polizas.siccont11_ano,
                        siccont11_det_polizas.siccont11_mes,
                        siccont11_det_polizas.siccont11_referencia)
            VALUES(:ID_SICCONT10,
                   :rela_siccont02_nomina,
                   'S',
                   :sicxmls46_importe_exento,
                   0,
                   -1,
                   -1,
                   :sicxmls46_concepto);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICCONT11'
        INTO :ID_SICCONT11;

        INSERT INTO siccont12_mov_dropzone(siccont12_mov_dropzone.rela_siccont11,
                                           siccont12_mov_dropzone.rela_sicxmls05)
        VALUES(:id_siccont11, :id_sicxmls05);
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_CURP (
    RELA_SOCUSUA30 BIGINT,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCSYST10_CURP bigint;
declare variable EXISTE_CURP bigint;
begin
    if (curp is not null) then
    begin
        select CBO_SOCSYST10_TD001.id_socsyst10
        from CBO_SOCSYST10_TD001
        where CBO_SOCSYST10_TD001.socsyst10_codigo = 'CURP'
        into :rela_socsyst10_curp;

        select
        socusua32_det_documentos.id_socusua32
        from socusua32_det_documentos
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
        where socsyst10_det_entradas.socsyst10_codigo = 'CURP'
        and socusua32_det_documentos.socusua32_documento = :curp
        into :existe_curp;

        if (existe_curp is null) then
        begin
            select
            socusua32_det_documentos.id_socusua32
            from socusua32_det_documentos
            inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
            where socusua32_det_documentos.rela_socusua30 = :rela_socusua30
            and socsyst10_det_entradas.socsyst10_codigo = 'CURP'
            into :existe_curp;

            if (existe_curp is null) then
                insert into socusua32_det_documentos(socusua32_det_documentos.rela_socusua30,
                                                     socusua32_det_documentos.rela_socsyst10_td001,
                                                     socusua32_det_documentos.socusua32_documento,
                                                     socusua32_det_documentos.socusua32_principal)
                values(:rela_socusua30,
                       :rela_socsyst10_curp,
                       :curp,
                       1);
             else
                update socusua32_det_documentos set socusua32_det_documentos.socusua32_documento = :curp
                where socusua32_det_documentos.id_socusua32 = :existe_curp;
         end
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_ENTIDAD (
    XML_MODO BIGINT,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01 BIGINT,
    CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SOCUSUA30 BIGINT)
AS
declare variable TIPO_PERSONA char(1);
declare variable APELL_MAT varchar(400);
declare variable APELL_PAT varchar(400);
declare variable RAZSOCNOMBRE varchar(400);
declare variable CON_1 integer;
declare variable CON_2 integer;
declare variable TMP_1 varchar(400);
declare variable TMP_2 varchar(400);
declare variable RELA_SOCSYST10 bigint;
declare variable RELA_SOCSYST10_RFC bigint;
declare variable XML_TIPO_ENTIDAD_SISTEMA varchar(50);
declare variable ID_SICEGRE01 bigint;
declare variable ID_SICINGR01 bigint;
declare variable ID_SICNOMI01 bigint;
declare variable ID_SOCSYST10_TDD01 bigint;
declare variable ID_SOCMAIN80 bigint;
declare variable SOCMAIN80_D_ASENTA varchar(400);
declare variable SOCMAIN80_D_CIUDAD varchar(400);
declare variable ID_SOCUSUA36 bigint;
declare variable RELA_SOCSYST10_SAT bigint;
begin
    RFC = UPPER(TRIM(RFC));
    if (CURP is not null) then
        CURP = UPPER(TRIM(CURP));

    select cbo_socsyst10_xml01.socsyst10_codigo
    from cbo_socsyst10_xml01
    where cbo_socsyst10_xml01.id_socsyst10 = :xml_modo
    into :xml_tipo_entidad_sistema;

    select CBO_SOCSYST10_TD001.id_socsyst10
    from CBO_SOCSYST10_TD001
    where CBO_SOCSYST10_TD001.socsyst10_codigo = 'RFC'
    into :rela_socsyst10_rfc;

    select max(socusua32_det_documentos.rela_socusua30)
    from socusua32_det_documentos
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
    where socsyst10_det_entradas.socsyst10_codigo = 'RFC'
    and socusua32_det_documentos.socusua32_documento = :rfc
    into :rela_socusua30;

    if (rela_socusua30 is null) then
    begin
        APELL_PAT = '';
        APELL_MAT = '';
        razsocnombre = '';

        if (CHAR_LENGTH(trim(RFC)) = 12 ) then
        begin
            TIPO_PERSONA = 'M';
            select CBO_SOCSYST10_TP001.ID_SOCSYST10
            from CBO_SOCSYST10_TP001
            where CBO_SOCSYST10_TP001.socsyst10_codigo = 'MORAL'
            into :RELA_SOCSYST10;

            razsocnombre = upper(trim(:entidad));
        end
        else
        begin
            TIPO_PERSONA = 'F';
            select CBO_SOCSYST10_TP001.ID_SOCSYST10
            from CBO_SOCSYST10_TP001
            where CBO_SOCSYST10_TP001.socsyst10_codigo = 'FISICO'
            into :RELA_SOCSYST10;
        end

        CON_1 = 0;
        if (tipo_persona = 'F') then
        BEGIN
            for select smx$util_strtokenize.result
            from smx$util_strtokenize(:entidad, ',')
            into :tmp_1
            do
            begin
                CON_1 = CON_1 + 1;
                if (CON_1 = 1) then
                begin
                    CON_2 = 0;
                    for select smx$util_strtokenize.result
                    from smx$util_strtokenize(:tmp_1, ' ')
                    into :tmp_2
                    do
                    begin
                        CON_2 = CON_2 + 1;
                        if (CON_2 = 1) then
                           APELL_PAT = tmp_2;
                        else
                           APELL_MAT = APELL_MAT || ' ' || tmp_2;

                    end
                end
                else
                    razsocnombre = razsocnombre || ' ' || tmp_1;
            end

            /* ---------------------------------------------------------------------------------------------------- */

            if (CON_1 = 0) then
            begin
                for select smx$util_strtokenize.result
                from smx$util_strtokenize(:entidad, ' ')
                into :tmp_1
                do
                begin
                    CON_1 = CON_1 + 1;

                    if (CON_1 = 1) then
                        APELL_PAT = APELL_PAT || tmp_1 || ' ';
                    else if (CON_1 = 2) then
                        APELL_MAT = APELL_MAT || tmp_1 || ' ';
                    else
                        razsocnombre = razsocnombre || tmp_1 || ' ';
                end
            end
        END

        /* ------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------ */

        insert into socusua30_cab_entidades(socusua30_cab_entidades.rela_socsyst10,
                                   socusua30_cab_entidades.socusua30_apellido_pat,
                                   socusua30_cab_entidades.socusua30_apellido_mat,
                                   socusua30_cab_entidades.socusua30_nombre_razsoc,
                                   socusua30_cab_entidades.socusua30_fnac_const,
                                   socusua30_cab_entidades.socusua30_extranjero)
        values(:rela_socsyst10,
               upper(trim(:apell_pat)),
               upper(trim(:apell_mat)),
               upper(trim(:razsocnombre)),
               current_date,
               0);

        select
        socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA30'
        INTO :rela_socusua30;

        insert into socusua32_det_documentos(socusua32_det_documentos.rela_socusua30,
                                             socusua32_det_documentos.rela_socsyst10_td001,
                                             socusua32_det_documentos.socusua32_documento,
                                             socusua32_det_documentos.socusua32_principal)
        values(:rela_socusua30,
               :rela_socsyst10_rfc,
               :rfc,
               1);

        execute procedure prd_sicxmls41_curp :rela_socusua30, :curp;
    end
    else
    begin
        execute procedure prd_sicxmls41_curp :rela_socusua30, :curp;
    end

    /* --------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------- */

    if (xml_tipo_entidad_sistema = 'PROVE') then
    begin
        select sicegre01_cab_proveedores.id_sicegre01
        from sicegre01_cab_proveedores
        where sicegre01_cab_proveedores.rela_socmain01 = :rela_socmain01
        and sicegre01_cab_proveedores.rela_socusua30 = :rela_socusua30
        into :id_sicegre01;

        if (id_sicegre01 is null) then
            insert into sicegre01_cab_proveedores(sicegre01_cab_proveedores.rela_socmain01,
                                                  sicegre01_cab_proveedores.rela_socusua30,
                                                  sicegre01_cab_proveedores.sicegre01_diascredito)
            values(:rela_socmain01, :rela_socusua30, 0);

    end
    else if (xml_tipo_entidad_sistema = 'CLIENTE') then
    begin
        select sicingr01_cab_clientes.id_sicingr01
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.rela_socmain01 = :rela_socmain01
        and sicingr01_cab_clientes.rela_socusua30 = :rela_socusua30
        into :id_sicingr01;

        if (id_sicingr01 is null) then
        BEGIN
            select cbo_socsyst10_sat01.id_socsyst10
            from cbo_socsyst10_sat01
            where cbo_socsyst10_sat01.socsyst10_codigo = '616'
            into :rela_socsyst10_sat;

            insert into sicingr01_cab_clientes( sicingr01_cab_clientes.rela_socmain01,
                                                sicingr01_cab_clientes.rela_socusua30,
                                                sicingr01_cab_clientes.sicingr01_diascredito,
                                                sicingr01_cab_clientes.rela_socsyst10_sat01)
            values(:rela_socmain01, :rela_socusua30, 0, :rela_socsyst10_sat);
        END
    end
    else if (xml_tipo_entidad_sistema = 'NOMINA') then
    begin
        select sicnomi01_cab_empleados.id_sicnomi01
        from sicnomi01_cab_empleados
        where sicnomi01_cab_empleados.rela_socmain01 = :rela_socmain01
        and sicnomi01_cab_empleados.rela_socusua30 = :rela_socusua30
        into :id_sicnomi01;

        if (id_sicnomi01 is null) then
            insert into sicnomi01_cab_empleados( sicnomi01_cab_empleados.rela_socmain01,
                                                 sicnomi01_cab_empleados.rela_socusua30,
                                                 sicnomi01_cab_empleados.sicnomi01_diascredito)
            values(:rela_socmain01, :rela_socusua30, 0);
    end

    /* --------------------------------------------------------------------------------------------------- */
    /* --------------------------------------------------------------------------------------------------- */

    if (codpostal <> '') then
    begin
        select cbo_socsyst10_tdd01.id_socsyst10
        from cbo_socsyst10_tdd01
        where cbo_socsyst10_tdd01.socsyst10_codigo = 'PARTICULAR'
        INTO :id_socsyst10_tdd01;

        select first 1 socusua36_det_domicilios.id_socusua36
        from socusua36_det_domicilios
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socusua36_det_domicilios.rela_socsyst10_tdd01 = :id_socsyst10_tdd01
        into :id_socusua36;

        if (id_socusua36 is null) then
        begin
            id_socmain80 = null;

            if (char_length(codpostal) < 5) then
                codpostal = lpad(codpostal, 5, '0');
    
            select first 1
            cbo_socmain80.id_socmain80,
            cbo_socmain80.socmain80_d_asenta,
            cbo_socmain80.socmain80_d_ciudad
            from cbo_socmain80(:codpostal)
            into :id_socmain80,
                 :socmain80_d_asenta,
                 :socmain80_d_ciudad;
    
            if (id_socmain80 is not null) then
            begin
                insert into socusua36_det_domicilios( socusua36_det_domicilios.rela_socusua30,
                                                      socusua36_det_domicilios.rela_socsyst10_tdd01,
                                                      socusua36_det_domicilios.rela_socmain80,
                                                      socusua36_det_domicilios.socusua36_codpostal,
                                                      socusua36_det_domicilios.socusua36_calle,
                                                      socusua36_det_domicilios.socusua36_nro,
                                                      socusua36_det_domicilios.socusua36_ciudad,
                                                      socusua36_det_domicilios.socusua36_colonia)
                values( :rela_socusua30,
                        :id_socsyst10_tdd01,
                        :id_socmain80,
                        :codpostal,
                        '',
                        '',
                        iif(:socmain80_d_ciudad is null, '', :socmain80_d_ciudad),
                        :socmain80_d_asenta);
            end
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_MONEDA (
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION)
RETURNS (
    ID_SOCSYST10 BIGINT,
    ERROR INTEGER)
AS
declare variable POSI integer;
declare variable TIPO_MONEDA varchar(1);
begin
    id_socsyst10 = null;
    moneda = iif(moneda is null, 'MXN', upper(trim(MONEDA)));
    error = 0;

    if (moneda = 'MXN' and cotiza <> 1) then
        error = 1;

    select cbo_socsyst10_ctm01w.id_socsyst10
    from cbo_socsyst10_ctm01w
    where cbo_socsyst10_ctm01w.socsyst10_codigo = :moneda
    into :id_socsyst10;

    if (id_socsyst10 is null) then
    begin
        tipo_moneda = 'X';
        posi = POSITION('MX' IN moneda);

        if (posi = 0) then
            posi = POSITION('PESO' IN moneda);

        if (posi = 0) then
            posi = POSITION('Mexico' IN moneda);

        if (posi = 0) then
            posi = POSITION('México' IN moneda);

        if (posi = 0) then
        BEGIN
            tipo_moneda = 'D';
            posi = POSITION('USA' IN moneda);

            if (posi = 0) then
                posi = POSITION('DOLAR' IN moneda);

            if (posi = 0) then
                posi = POSITION('DÓLAR' IN moneda);

        END

        if (posi = 0 or tipo_moneda = 'X') then
        begin
            select cbo_socsyst10_ctm01w.id_socsyst10
            from cbo_socsyst10_ctm01w
            where cbo_socsyst10_ctm01w.socsyst10_codigo = 'MXN'
            into :id_socsyst10;

            if (cotiza <> 1) then
                error = 1;
        end
        else
        begin
            select cbo_socsyst10_ctm01w.id_socsyst10
            from cbo_socsyst10_ctm01w
            where cbo_socsyst10_ctm01w.socsyst10_codigo = 'USD'
            into :id_socsyst10;    

            if (cotiza <> 1) then
                error = 1;
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS41_VALIDA_UUID (
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICXMLS40 BIGINT,
    FECHA DATE,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCSYST10_XML bigint;
begin
    uuid = upper(trim(uuid));

    select cbo_socsyst10_xml01.id_socsyst10
    from cbo_socsyst10_xml01
    where cbo_socsyst10_xml01.socsyst10_codigo = :tipo
    into :id_socsyst10_xml;

    Select
    sicxmls40_cab_migracion.id_sicxmls40,
    sicxmls40_cab_migracion.sicxmls40_fecha_proceso,
    socmain01_cab_empresas.socmain01_nomcomercial
    from sicxmls40_cab_migracion
    inner join socmain01_cab_empresas on (sicxmls40_cab_migracion.rela_socmain01 = socmain01_cab_empresas.id_socmain01)
    inner join sicxmls41_det_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    where sicxmls41_det_migracion.rela_socsyst10_xml01 = :id_socsyst10_xml
    and SICXMLS41_DET_MIGRACION.SICXMLS41_UUID = :uuid
    into :id_sicxmls40,
         :fecha,
         :empresa;

    if (id_sicxmls40 is not null) then
        suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS42_CONCEPTOS (
    RELA_SICXMLS41 BIGINT,
    CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXCENTO INTEGER,
    UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVEPRODSERV VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SICXMLS04 BIGINT)
AS
declare variable RELA_SOCSYST10_TCT01 bigint;
declare variable RELA_SICXMLS40 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable TIPO varchar(50);
declare variable RELA_SOCMAIN01 bigint;
begin
    concepto = upper(trim(concepto));

    if (char_length(concepto) > 400) then
        concepto = substring(concepto FROM 1 FOR 400);

    select
    sicxmls41_det_migracion.rela_sicxmls40,
    sicxmls41_det_migracion.rela_socsyst10_tct01,
    socsyst10_det_entradas.socsyst10_grupo
    from sicxmls41_det_migracion
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01)
    where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
    into :rela_sicxmls40,
         :rela_socsyst10_tct01,
         :TIPO;

    tipo = substring(:TIPO from position ('(' in :TIPO)+1 for 1);

    select
    sicxmls40_cab_migracion.rela_socmain01
    from sicxmls40_cab_migracion
    where sicxmls40_cab_migracion.id_sicxmls40 = :rela_sicxmls40
    into :rela_socmain01;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    execute procedure PRD_SICXMLS04_INSERT :id_sicxmls01,
                                           :rela_socsyst10_tct01,
                                           null,
                                           :tipo,
                                           :concepto,
                                           :excento,
                                           1,
                                           :claveprodserv,
                                           :unidad

    returning_values :RELA_SICXMLS04;

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS43_IMPUESTOS (
    RELA_SICXMLS41 BIGINT,
    IMPUESTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TASA DOUBLE PRECISION,
    RETENIDO INTEGER)
RETURNS (
    RELA_SICXMLS02 BIGINT)
AS
declare variable TIPO varchar(50);
declare variable RELA_SICXMLS40 bigint;
declare variable RELA_SOCSYST10_TCT01 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable ID_SICXMLS01 bigint;
begin
    impuesto = upper(trim(impuesto));

    select
    sicxmls41_det_migracion.rela_sicxmls40,
    sicxmls41_det_migracion.rela_socsyst10_tct01,
    socsyst10_det_entradas.socsyst10_grupo
    from sicxmls41_det_migracion
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01)
    where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
    into :rela_sicxmls40, :rela_socsyst10_tct01, :TIPO;

    tipo = substring(:TIPO from position ('(' in :TIPO)+1 for 1);

    select
    sicxmls40_cab_migracion.rela_socmain01
    from sicxmls40_cab_migracion
    where sicxmls40_cab_migracion.id_sicxmls40 = :rela_sicxmls40
    into :rela_socmain01;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    select sicxmls02_det_impuestos.id_sicxmls02
    from sicxmls02_det_impuestos
    where sicxmls02_det_impuestos.rela_sicxmls01 = :id_sicxmls01
    and sicxmls02_det_impuestos.rela_socsyst10_tct01 = :rela_socsyst10_tct01
    and sicxmls02_det_impuestos.sicxmls02_impuesto = :impuesto
    and sicxmls02_det_impuestos.sicxmls02_tasa = :tasa
    and sicxmls02_det_impuestos.sicxmls02_retenido = :retenido
    and sicxmls02_det_impuestos.sicxmls02_tipo = :tipo
    into :rela_sicxmls02;

    if (rela_sicxmls02 is null) then
    begin
        insert into sicxmls02_det_impuestos(sicxmls02_det_impuestos.rela_sicxmls01,
                                            sicxmls02_det_impuestos.rela_socsyst10_tct01,
                                            sicxmls02_det_impuestos.rela_siccont02,
                                            sicxmls02_det_impuestos.sicxmls02_impuesto,
                                            sicxmls02_det_impuestos.sicxmls02_tipo,
                                            sicxmls02_det_impuestos.sicxmls02_retenido,
                                            sicxmls02_det_impuestos.sicxmls02_tasa)
        values(:id_sicxmls01,
               :rela_socsyst10_tct01,
               null,
               :impuesto,
               :tipo,
               :retenido,
               :tasa);

        select
        socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS02'
        INTO :RELA_SICXMLS02;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS46_NOMINA (
    RELA_SICXMLS41 BIGINT,
    SICXMLS46_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS46_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS46_TIPOSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS46_IMPORTE_GAVADO DOUBLE PRECISION,
    SICXMLS46_IMPORTE_EXENTO DOUBLE PRECISION)
RETURNS (
    RELA_SICXMLS05_GRAVADO BIGINT,
    RELA_SICXMLS05_EXCENTO BIGINT)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable ID_SICXMLS01 bigint;
declare variable GRAVADO integer;
declare variable EXCENTO integer;
begin
    SICXMLS46_CONCEPTO = upper(trim(SICXMLS46_CONCEPTO));
    gravado = 0;
    excento = 0;

    if (SICXMLS46_IMPORTE_GAVADO <> 0) then
        gravado = 1;

    if (SICXMLS46_IMPORTE_EXENTO <> 0) then
        excento = 1;


    if (gravado = 0 and excento = 0) then
    begin
       gravado = 1;
       excento = 1;
    end

    select
    sicxmls40_cab_migracion.rela_socmain01
    from sicxmls41_det_migracion
    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
    into :rela_socmain01;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01
    into :id_sicxmls01;

    if (gravado = 1) then
    begin
        select sicxmls05_det_nomina.id_sicxmls05
        from sicxmls05_det_nomina
        where sicxmls05_det_nomina.rela_sicxmls01 = :id_sicxmls01
        and sicxmls05_det_nomina.sicxmls05_tipo = :SICXMLS46_TIPO
        and sicxmls05_det_nomina.sicxmls05_tiposat = :sicxmls46_tiposat
        and sicxmls05_det_nomina.sicxmls05_gravado = 1
        and sicxmls05_det_nomina.sicxmls05_concepto = :SICXMLS46_CONCEPTO
        into :rela_sicxmls05_gravado;

        if (rela_sicxmls05_gravado is null) then
        begin
            insert into sicxmls05_det_nomina(sicxmls05_det_nomina.rela_sicxmls01,
                                             sicxmls05_det_nomina.sicxmls05_tipo,
                                             sicxmls05_det_nomina.sicxmls05_tiposat,
                                             sicxmls05_det_nomina.sicxmls05_gravado,
                                             sicxmls05_det_nomina.sicxmls05_concepto)
            values(:id_sicxmls01,
                   :sicxmls46_tipo,
                   :sicxmls46_tiposat,
                   1,
                   :sicxmls46_concepto);

            select
            socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS05'
            INTO :rela_sicxmls05_gravado;
        end
    end

    if (excento = 1) then
    begin
        select sicxmls05_det_nomina.id_sicxmls05
        from sicxmls05_det_nomina
        where sicxmls05_det_nomina.rela_sicxmls01 = :id_sicxmls01
        and sicxmls05_det_nomina.sicxmls05_tipo = :SICXMLS46_TIPO
        and sicxmls05_det_nomina.sicxmls05_tiposat = :sicxmls46_tiposat
        and sicxmls05_det_nomina.sicxmls05_gravado = 0
        and sicxmls05_det_nomina.sicxmls05_concepto = :SICXMLS46_CONCEPTO
        into :rela_sicxmls05_excento;

        if (rela_sicxmls05_excento is null) then
        begin
            insert into sicxmls05_det_nomina(sicxmls05_det_nomina.rela_sicxmls01,
                                             sicxmls05_det_nomina.sicxmls05_tipo,
                                             sicxmls05_det_nomina.sicxmls05_tiposat,
                                             sicxmls05_det_nomina.sicxmls05_gravado,
                                             sicxmls05_det_nomina.sicxmls05_concepto)
            values(:id_sicxmls01,
                   :sicxmls46_tipo,
                   :sicxmls46_tiposat,
                   0,
                   :sicxmls46_concepto);

            select
            socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS05'
            INTO :rela_sicxmls05_excento;
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS47_NOMINADATOS (
    ID_SICXMLS47 BIGINT)
AS
declare variable RELA_SICXMLS41 bigint;
declare variable RELA_SOCUSUA30_EMPLEADO bigint;
declare variable RELA_SOCUSUA30_EMPRESA bigint;
declare variable RELA_SOCSYST10_REGISTROPATRONAL bigint;
declare variable ID_SICNOMI01 bigint;
declare variable ID_SOCMAIN01 bigint;
declare variable ID_SOCUSUA32 bigint;
declare variable SICXMLS47_REGISTROPATRONAL varchar(400);
declare variable SICXMLS47_NUMEMPLEADO varchar(400);
declare variable SICXMLS47_NUMSEGURIDADSOCIAL varchar(400);
declare variable SICXMLS47_FECHAINICIORELLABORAL varchar(400);
declare variable SICXMLS47_ANTIGUEDAD varchar(400);
declare variable SICXMLS47_TIPOCONTRATO varchar(400);
declare variable SICXMLS47_SINDICALIZADO varchar(400);
declare variable SICXMLS47_TIPOJORNADA varchar(400);
declare variable SICXMLS47_TIPOREGIMEN varchar(400);
declare variable SICXMLS47_DEPARTAMENTO varchar(400);
declare variable SICXMLS47_PUESTO varchar(400);
declare variable SICXMLS47_RIESGOPUESTO varchar(400);
declare variable SICXMLS47_PERIODICIDADPAGO varchar(400);
declare variable SICXMLS47_SALARIOBASECOTAPOR varchar(400);
declare variable SICXMLS47_SALARIODIARIOINTEGRAD varchar(400);
declare variable SICXMLS47_CLAVEENTFED varchar(400);
begin
    select
    sicxmls47_det_nominadatos.rela_sicxmls41,
    sicxmls47_det_nominadatos.sicxmls47_registropatronal,
    sicxmls47_det_nominadatos.sicxmls47_numempleado,
    sicxmls47_det_nominadatos.sicxmls47_numseguridadsocial,
    sicxmls47_det_nominadatos.sicxmls47_fechainiciorellaboral,
    sicxmls47_det_nominadatos.sicxmls47_antiguedad,
    sicxmls47_det_nominadatos.sicxmls47_tipocontrato,
    sicxmls47_det_nominadatos.sicxmls47_sindicalizado,
    sicxmls47_det_nominadatos.sicxmls47_tipojornada,
    sicxmls47_det_nominadatos.sicxmls47_tiporegimen,
    sicxmls47_det_nominadatos.sicxmls47_departamento,
    sicxmls47_det_nominadatos.sicxmls47_puesto,
    sicxmls47_det_nominadatos.sicxmls47_riesgopuesto,
    sicxmls47_det_nominadatos.sicxmls47_periodicidadpago,
    sicxmls47_det_nominadatos.sicxmls47_salariobasecotapor,
    sicxmls47_det_nominadatos.sicxmls47_salariodiariointegrad,
    sicxmls47_det_nominadatos.sicxmls47_claveentfed
    from sicxmls47_det_nominadatos
    where sicxmls47_det_nominadatos.id_sicxmls47 = :id_sicxmls47
    into :rela_sicxmls41,
         :sicxmls47_registropatronal,
         :sicxmls47_numempleado,
         :sicxmls47_numseguridadsocial,
         :sicxmls47_fechainiciorellaboral,
         :sicxmls47_antiguedad,
         :sicxmls47_tipocontrato,
         :sicxmls47_sindicalizado,
         :sicxmls47_tipojornada,
         :sicxmls47_tiporegimen,
         :sicxmls47_departamento,
         :sicxmls47_puesto,
         :sicxmls47_riesgopuesto,
         :sicxmls47_periodicidadpago,
         :sicxmls47_salariobasecotapor,
         :sicxmls47_salariodiariointegrad,
         :sicxmls47_claveentfed;

    select
    socmain01_cab_empresas.id_socmain01,
    socmain01_cab_empresas.rela_socusua30,
    sicxmls41_det_migracion.rela_socusua30
    from sicxmls41_det_migracion
    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = sicxmls40_cab_migracion.rela_socmain01)
    where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
    into :id_socmain01,
         :rela_socusua30_empresa,
         :rela_socusua30_empleado;

    select sicnomi01_cab_empleados.id_sicnomi01
    from sicnomi01_cab_empleados
    where sicnomi01_cab_empleados.rela_socmain01 = :id_socmain01
    and sicnomi01_cab_empleados.rela_socusua30 = :rela_socusua30_empleado
    into :id_sicnomi01;

    select cbo_socsyst10_td001.id_socsyst10
    from cbo_socsyst10_td001
    where cbo_socsyst10_td001.socsyst10_codigo = 'REGISTROPATRONAL'
    into :rela_socsyst10_registropatronal;

    id_socusua32 = null;
    select socusua32_det_documentos.id_socusua32
    from socusua32_det_documentos
    where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_empresa
    and socusua32_det_documentos.socusua32_principal = 1
    and socusua32_det_documentos.rela_socsyst10_td001 = :rela_socsyst10_registropatronal
    into :id_socusua32;

    if (id_socusua32 is null) then
    begin
        insert into socusua32_det_documentos(socusua32_det_documentos.rela_socusua30,
                                             socusua32_det_documentos.rela_socsyst10_td001,
                                             socusua32_det_documentos.socusua32_documento,
                                             socusua32_det_documentos.socusua32_principal)
        values(:rela_socusua30_empresa,
               :rela_socsyst10_registropatronal,
               :sicxmls47_registropatronal,
               1);
    end

    /* ------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------ */

    if (upper(sicxmls47_periodicidadpago) = 'DIARIO') then
        sicxmls47_periodicidadpago = '01';
    if (upper(sicxmls47_periodicidadpago) = 'SEMANAL') then
        sicxmls47_periodicidadpago = '02';
    if (upper(sicxmls47_periodicidadpago) = 'CATORCENAL') then
        sicxmls47_periodicidadpago = '03';
    if (upper(sicxmls47_periodicidadpago) = 'QUINCENAL') then
        sicxmls47_periodicidadpago = '04';
    if (upper(sicxmls47_periodicidadpago) = 'MENSUAL') then
        sicxmls47_periodicidadpago = '05';
    if (upper(sicxmls47_periodicidadpago) = 'BIMESTRAL') then
        sicxmls47_periodicidadpago = '06';

    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'NUMEMPLEADO', :sicxmls47_numempleado;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'NUMSEGURIDADSOCIAL', :sicxmls47_numseguridadsocial;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'FECHAINICIORELLABORAL', :sicxmls47_fechainiciorellaboral;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'ANTIGUEDAD', :sicxmls47_antiguedad;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'TIPOCONTRATO', :sicxmls47_tipocontrato;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'SINDICALIZADO', :sicxmls47_sindicalizado;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'TIPOJORNADA', :sicxmls47_tipojornada;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'TIPOREGIMEN', :sicxmls47_tiporegimen;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'DEPARTAMENTO', :sicxmls47_departamento;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'PUESTO', :sicxmls47_puesto;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'RIESGOPUESTO', :sicxmls47_riesgopuesto;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'PERIODICIDADPAGO', :sicxmls47_periodicidadpago;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'SALARIOBASECOTAPOR', :sicxmls47_salariobasecotapor;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'SALARIODIARIOINTEGRADO', :sicxmls47_salariodiariointegrad;
    execute procedure prd_sicxmls47_socsyst10 :id_sicnomi01, 'CLAVEENTFED', :sicxmls47_claveentfed;

    /* ------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------ */
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS47_SOCSYST10 (
    ID_SICNOMI01 BIGINT,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable EXISTE_ID_SOCSYST10_CNO01 bigint;
declare variable ID_SICNOMI05 bigint;
begin
    existe_id_socsyst10_cno01 = null;
    select cbo_socsyst10_CNO01.id_socsyst10
    from cbo_socsyst10_CNO01
    where cbo_socsyst10_CNO01.socsyst10_codigo = :clave
    into :existe_id_socsyst10_cno01;

    if (existe_id_socsyst10_cno01 is not null) then
    begin
        id_sicnomi05 = null;
        select sicnomi05_det_nomina.id_sicnomi05
        from sicnomi05_det_nomina
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
        where sicnomi05_det_nomina.rela_sicnomi01 = :id_sicnomi01
        and socsyst10_det_entradas.socsyst10_codigo = :clave
        into :id_sicnomi05;

        if (id_sicnomi05 is null) then
            insert into sicnomi05_det_nomina(sicnomi05_det_nomina.rela_sicnomi01,
                                             sicnomi05_det_nomina.rela_socsyst10_cno01,
                                             sicnomi05_det_nomina.sicnomi05_valor,
                                             sicnomi05_det_nomina.sicnomi05_descripcion)
            values(:id_sicnomi01,
                   :existe_id_socsyst10_cno01,
                   :valor,
                   'Pendiente por Actualizar');
        else
            update sicnomi05_det_nomina set sicnomi05_det_nomina.sicnomi05_valor = :valor,
                                            sicnomi05_det_nomina.sicnomi05_descripcion = 'N/A'
            where sicnomi05_det_nomina.id_sicnomi05 = :id_sicnomi05;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SICXMLS51 (
    P_STATUS INTEGER,
    P_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_IDENTIFICADOR INTEGER,
    P_MODALIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_FINI DATE,
    P_FFIN DATE,
    P_CFDIS INTEGER)
RETURNS (
    ID_SICXMLS51 BIGINT,
    IDENTIFICADOR INTEGER,
    MODALIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FINI DATE,
    FFIN DATE,
    FAPL TIMESTAMP,
    MENSAJE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS INTEGER)
AS
declare variable ENTRO integer;
declare variable STATUS_FILTRO integer;
begin
    entro = 0;
    status_filtro = 0;

    begin
        for select
        sicxmls51_mov_descargasat.id_sicxmls51,
        sicxmls51_mov_descargasat.sicxmls51_identificador,
        sicxmls51_mov_descargasat.sicxmls51_modalidad,
        sicxmls51_mov_descargasat.sicxmls51_fini,
        sicxmls51_mov_descargasat.sicxmls51_ffin,
        sicxmls51_mov_descargasat.sicxmls51_fapl
        from sicxmls51_mov_descargasat
        where sicxmls51_mov_descargasat.sicxmls51_rfc = :p_rfc
        and sicxmls51_mov_descargasat.sicxmls51_status = :status_filtro
        into :id_sicxmls51,
             :identificador,
             :modalidad,
             :fini,
             :ffin,
             :fapl
        do
        begin
            entro = 1;
            mensaje = 'Pendiente';
            status = 0;

            if (p_status = 10) then
                suspend;
        end
    end

    if (entro = 0 and p_status = 0) then
    begin
        insert into sicxmls51_mov_descargasat(sicxmls51_mov_descargasat.sicxmls51_rfc,
                                                  sicxmls51_mov_descargasat.sicxmls51_identificador,
                                                  sicxmls51_mov_descargasat.sicxmls51_status,
                                                  sicxmls51_mov_descargasat.sicxmls51_modalidad,
                                                  sicxmls51_mov_descargasat.sicxmls51_fini,
                                                  sicxmls51_mov_descargasat.sicxmls51_ffin,
                                                  sicxmls51_mov_descargasat.sicxmls51_cfdis)
        values(:p_rfc,
                   :p_identificador,
                   :p_status,
                   :p_modalidad,
                   :p_fini,
                   :p_ffin,
                   :p_cfdis);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICXMLS51'
        INTO :id_sicxmls51;

        identificador = p_identificador;
        modalidad = p_modalidad;
        fini = p_fini;
        ffin = p_ffin;
        fapl = current_timestamp;
        mensaje = 'Nva.Solicitud';
        status = -1;

        suspend;
    end


    if (entro = 1 and p_status = 1) then
    begin
        update sicxmls51_mov_descargasat set sicxmls51_mov_descargasat.sicxmls51_status = 1,
                                             sicxmls51_mov_descargasat.sicxmls51_cfdis = :p_cfdis
        where sicxmls51_mov_descargasat.id_sicxmls51 = :id_sicxmls51;

        delete from sicxmls51_mov_descargasat
        where sicxmls51_mov_descargasat.id_sicxmls51 <> :id_sicxmls51
        and sicxmls51_mov_descargasat.sicxmls51_rfc = :p_rfc
        and not exists(select first 1 sicxmls50_det_descargasat.id_sicxmls50
                       from sicxmls50_det_descargasat
                       where sicxmls50_det_descargasat.rela_sicxmls51 = sicxmls51_mov_descargasat.id_sicxmls51);
    end

    if (entro = 1 and p_status = 2) then
    begin
       delete from sicxmls51_mov_descargasat
       where sicxmls51_mov_descargasat.id_sicxmls51 = :id_sicxmls51;
    end
end^


