CREATE OR ALTER PROCEDURE PRD_SOCMAIN01_DATOS (
    PARAM_EMPRESA BIGINT)
RETURNS (
    RELA_SOCUSUA30 BIGINT,
    EMPRESA_NOMCOMERCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_ENTIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRONAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_DIRECCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_LOCALIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_TELEFONOS VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_DOMICILIO VARCHAR(3000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable TIPO_RAZONSOCIAL varchar(400);
declare variable CALLE varchar(400);
declare variable NROEXTERIOR varchar(400);
declare variable NROINTERIOR varchar(400);
declare variable COLONIA varchar(400);
declare variable LOCALIDAD varchar(400);
declare variable MUNICIPIO varchar(400);
declare variable ESTADO varchar(400);
declare variable REFERENCIA varchar(400);
declare variable PAIS varchar(400);
declare variable RELA_SOCSYST10_TS001 bigint;
declare variable TELEFONO varchar(1200);
declare variable SOCUSUA31_LADA varchar(50);
declare variable SOCUSUA31_NRO varchar(50);
BEGIN
  SELECT
      SOCMAIN01_CAB_EMPRESAS.RELA_SOCSYST10_TS001,
      SOCMAIN01_CAB_EMPRESAS.RELA_SOCUSUA30,
      SOCMAIN01_CAB_EMPRESAS.SOCMAIN01_NOMCOMERCIAL
  FROM SOCMAIN01_CAB_EMPRESAS
  WHERE SOCMAIN01_CAB_EMPRESAS.ID_SOCMAIN01 = :PARAM_EMPRESA
  INTO
      :RELA_SOCSYST10_TS001,
      :RELA_SOCUSUA30,
      :EMPRESA_NOMCOMERCIAL;

  SELECT
      CBO_SOCUSUA30.TIPO,
      CBO_SOCUSUA30.ENTIDAD,
      CBO_SOCUSUA30.RFC,
      CBO_SOCUSUA30.CURP
  FROM CBO_SOCUSUA30(:RELA_SOCUSUA30)
  INTO
      :TIPO_ENTIDAD,
      :EMPRESA,
      :EMPRESA_RFC,
      :EMPRESA_CURP;

  IF (:TIPO_ENTIDAD = 'M') THEN
    BEGIN
      SELECT UPPER(SOCSYST10_DET_ENTRADAS.SOCSYST10_DESCRIPCION)
      FROM SOCSYST10_DET_ENTRADAS
      WHERE SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = :RELA_SOCSYST10_TS001
      INTO :TIPO_RAZONSOCIAL;

      EMPRESA_RAZSOCIAL = :EMPRESA_RAZSOCIAL || ' ' || :TIPO_RAZONSOCIAL;
    END

  SELECT SOCUSUA32_DET_DOCUMENTOS.SOCUSUA32_DOCUMENTO
  FROM SOCUSUA32_DET_DOCUMENTOS
  INNER JOIN SOCSYST10_DET_ENTRADAS ON (SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = SOCUSUA32_DET_DOCUMENTOS.RELA_SOCSYST10_TD001 )
  WHERE SOCUSUA32_DET_DOCUMENTOS.RELA_SOCUSUA30 = :RELA_SOCUSUA30
    AND SOCSYST10_DET_ENTRADAS.SOCSYST10_CODIGO = 'REGISTROPATRONAL'
  INTO :EMPRESA_REGPATRONAL;

  SELECT
      SOCMAIN80_CAB_CODPOSTALES.SOCMAIN80_D_CODIGO,
      SOCUSUA36_DET_DOMICILIOS.SOCUSUA36_CALLE,
      SOCUSUA36_DET_DOMICILIOS.SOCUSUA36_NRO,
      SOCUSUA36_DET_DOMICILIOS.SOCUSUA36_NROINTERIOR,
      SOCUSUA36_DET_DOMICILIOS.SOCUSUA36_COLONIA,
      SOCUSUA36_DET_DOMICILIOS.SOCUSUA36_CIUDAD,
      SOCMAIN80_CAB_CODPOSTALES.SOCMAIN80_D_MNPIO,
      SOCMAIN80_CAB_CODPOSTALES.SOCMAIN80_D_ESTADO,
      SOCUSUA36_DET_DOMICILIOS.SOCUSUA36_REFERENCIA
  FROM SOCUSUA36_DET_DOMICILIOS
  INNER JOIN SOCSYST10_DET_ENTRADAS ON (SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = SOCUSUA36_DET_DOMICILIOS.RELA_SOCSYST10_TDD01)
  INNER JOIN SOCMAIN80_CAB_CODPOSTALES ON (SOCMAIN80_CAB_CODPOSTALES.ID_SOCMAIN80 = SOCUSUA36_DET_DOMICILIOS.RELA_SOCMAIN80)
  WHERE SOCUSUA36_DET_DOMICILIOS.RELA_SOCUSUA30 = :RELA_SOCUSUA30
    AND SOCSYST10_DET_ENTRADAS.SOCSYST10_CODIGO = 'EMPRESA'
  INTO
      :CODPOSTAL,
      :CALLE,
      :NROEXTERIOR,
      :NROINTERIOR,
      :COLONIA,
      :LOCALIDAD,
      :MUNICIPIO,
      :ESTADO,
      :REFERENCIA;

  PAIS = 'Mexico';


  EMPRESA_DIRECCION = :CALLE || ' ' || :NROEXTERIOR;

  IF (NROINTERIOR IS NOT NULL) THEN
    EMPRESA_DIRECCION = :EMPRESA_DIRECCION || ' ' || :NROINTERIOR;

  EMPRESA_LOCALIDAD = :LOCALIDAD || ', ' || :MUNICIPIO || ', ' || :ESTADO || ', ' || :PAIS;

  telefono = '';

  for select
  socusua31_det_telefonos.socusua31_lada,
  socusua31_det_telefonos.socusua31_nro
  from socusua31_det_telefonos
  where socusua31_det_telefonos.rela_socusua30 = :rela_socusua30
  into :socusua31_lada,
       :socusua31_nro
  do
  begin
     telefono  = telefono || '(' || trim(socusua31_lada) || ') ' || trim(socusua31_nro) || ' ';
  end

  empresa_telefonos = trim(telefono);

  empresa_domicilio = empresa_direccion || ' CP: ' || codpostal || ' ' || empresa_localidad;

  SUSPEND;
END^


CREATE OR ALTER PROCEDURE PRD_SOCMAIN11 (
    RELA_SOCMAIN01 BIGINT,
    ALIAS_CONTADOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODO INTEGER)
RETURNS (
    ID_SICFOLI01 BIGINT,
    FOLIOS_RESTANTES INTEGER,
    AVISO INTEGER,
    SICFOLI01_FAPL TIMESTAMP)
AS
declare variable ID_SOCMAIN10 bigint;
declare variable ID_SOCMAIN11 bigint;
declare variable SUMA_COMPRADOS double precision;
declare variable SUMA_CONSUMIDOS double precision;
declare variable SOCMAIN01_AVISOFOLIOS integer;
declare variable PORCENTAJE double precision;
begin
    aviso = 0;
    id_sicfoli01 = 1;
    sicfoli01_fapl = current_timestamp;

    select socmain01_cab_empresas.socmain01_avisofolios
    from socmain01_cab_empresas
    where socmain01_cab_empresas.id_socmain01 = :rela_socmain01
    into :socmain01_avisofolios;

    select first 1 socmain10_det_contadores.id_socmain10
    from socmain10_det_contadores
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain10_det_contadores.rela_socsyst10_co001 )
    inner join socmain11_mov_folios on ( socmain10_det_contadores.id_socmain10 = socmain11_mov_folios.rela_socmain10 )
    where socmain10_det_contadores.rela_socmain01 = :rela_socmain01
    and socsyst10_det_entradas.socsyst10_codigo = :alias_contador
    into :id_socmain10;

    if (id_socmain10 is not null) then
    begin
        select
        sum(socmain11_mov_folios.socmain11_folios_comprados),
        sum(socmain11_mov_folios.socmain11_folios_consumidos)
        from socmain11_mov_folios
        where socmain11_mov_folios.rela_socmain10 = :id_socmain10
        into :suma_comprados,
             :suma_consumidos;

        folios_restantes = :suma_comprados - :suma_consumidos;

        porcentaje = 100 - (suma_consumidos / suma_comprados * 100);

        if (socmain01_avisofolios > 0 and porcentaje <= socmain01_avisofolios) then
            aviso = 1;

        if (modo = 1) then
        begin
            if (folios_restantes > 0) then
            begin
                select min(socmain11_mov_folios.id_socmain11)
                from socmain11_mov_folios
                where socmain11_mov_folios.rela_socmain10 = :id_socmain10
                and socmain11_mov_folios.socmain11_folios_comprados > socmain11_mov_folios.socmain11_folios_consumidos
                into :id_socmain11;
            end
            else
            begin
                select max(socmain11_mov_folios.id_socmain11)
                from socmain11_mov_folios
                where socmain11_mov_folios.rela_socmain10 = :id_socmain10
                and socmain11_mov_folios.socmain11_folios_comprados <= socmain11_mov_folios.socmain11_folios_consumidos
                into :id_socmain11;
            end

            update socmain11_mov_folios
            set socmain11_mov_folios.socmain11_folios_consumidos = (socmain11_mov_folios.socmain11_folios_consumidos + 1)
            where socmain11_mov_folios.id_socmain11 = :id_socmain11;

            folios_restantes = folios_restantes - 1;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SOCMAIN80_ADD (
    SOCMAIN80_X_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_CODIGO VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_ASENTA VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_TIPO_ASENTA VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_CIUDAD VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_MNPIO VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_ESTADO VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_CP VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCMAIN80 BIGINT,
    SOCMAIN80_D_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CODIGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_ASENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_TIPO_ASENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CIUDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_MNPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DAR_ALTA INTEGER)
AS
declare variable C_SQL varchar(8000);
declare variable ID_SOCMAIN80FIND bigint;
begin
    dar_alta = 0;

    c_sql = 'INSERT INTO SOCMAIN80_CAB_CODPOSTALES(SOCMAIN80_D_PAIS, SOCMAIN80_D_CODIGO,SOCMAIN80_D_ASENTA,SOCMAIN80_D_TIPO_ASENTA,
            SOCMAIN80_D_CIUDAD, SOCMAIN80_D_MNPIO,SOCMAIN80_D_ESTADO,SOCMAIN80_D_CP) VALUES('''
                                                                            || :SOCMAIN80_X_PAIS || ''','''
                                                                            || :SOCMAIN80_X_CODIGO || ''','''
                                                                            || :SOCMAIN80_X_ASENTA || ''','''
                                                                            || :SOCMAIN80_X_TIPO_ASENTA || ''','''
                                                                            || :SOCMAIN80_X_CIUDAD || ''','''
                                                                            || :SOCMAIN80_X_MNPIO || ''','''
                                                                            || :SOCMAIN80_X_ESTADO || ''','''
                                                                            || :SOCMAIN80_X_CP || ''')';
    execute statement :c_sql
    on external 'SMXSEG'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey';

    FOR SELECT
    cbo_socmain80.id_socmain80,
    cbo_socmain80.socmain80_d_pais,
    cbo_socmain80.socmain80_d_codigo,
    cbo_socmain80.socmain80_d_asenta,
    cbo_socmain80.socmain80_d_tipo_asenta,
    cbo_socmain80.socmain80_d_ciudad,
    cbo_socmain80.socmain80_d_mnpio,
    cbo_socmain80.socmain80_d_estado,
    cbo_socmain80.socmain80_d_cp
    FROM cbo_socmain80(:SOCMAIN80_X_CODIGO)
    INTO :ID_SOCMAIN80,
         :socmain80_d_pais,
         :SOCMAIN80_D_CODIGO,
         :SOCMAIN80_D_ASENTA,
         :SOCMAIN80_D_TIPO_ASENTA,
         :SOCMAIN80_D_CIUDAD,
         :SOCMAIN80_D_MNPIO,
         :SOCMAIN80_D_ESTADO,
         :SOCMAIN80_D_CP
    DO
    BEGIN
        id_socmain80Find = null;

        select socmain80_cab_codpostales.id_socmain80
        from socmain80_cab_codpostales
        where socmain80_cab_codpostales.id_socmain80 = :ID_SOCMAIN80
        into :id_socmain80Find;

        if (id_socmain80Find is null) then
            insert into socmain80_cab_codpostales( socmain80_cab_codpostales.id_socmain80,
                                                   socmain80_cab_codpostales.socmain80_d_pais,
                                                   socmain80_cab_codpostales.socmain80_d_codigo,
                                                   socmain80_cab_codpostales.socmain80_d_asenta,
                                                   socmain80_cab_codpostales.socmain80_d_tipo_asenta,
                                                   socmain80_cab_codpostales.socmain80_d_ciudad,
                                                   socmain80_cab_codpostales.socmain80_d_mnpio,
                                                   socmain80_cab_codpostales.socmain80_d_estado,
                                                   socmain80_cab_codpostales.socmain80_d_cp )
            values(  :ID_SOCMAIN80,
                     :socmain80_d_pais,
                     :SOCMAIN80_D_CODIGO,
                     :SOCMAIN80_D_ASENTA,
                     :SOCMAIN80_D_TIPO_ASENTA,
                     :SOCMAIN80_D_CIUDAD,
                     :SOCMAIN80_D_MNPIO,
                     :SOCMAIN80_D_ESTADO,
                     :SOCMAIN80_D_CP );
        else
            update socmain80_cab_codpostales set socmain80_cab_codpostales.socmain80_d_pais = :socmain80_d_pais,
                                                  socmain80_cab_codpostales.socmain80_d_codigo = :SOCMAIN80_D_CODIGO,
                                                   socmain80_cab_codpostales.socmain80_d_asenta = :SOCMAIN80_D_ASENTA,
                                                   socmain80_cab_codpostales.socmain80_d_tipo_asenta = :SOCMAIN80_D_TIPO_ASENTA,
                                                   socmain80_cab_codpostales.socmain80_d_ciudad = :SOCMAIN80_D_CIUDAD,
                                                   socmain80_cab_codpostales.socmain80_d_mnpio = :SOCMAIN80_D_MNPIO,
                                                   socmain80_cab_codpostales.socmain80_d_estado = :SOCMAIN80_D_ESTADO,
                                                   socmain80_cab_codpostales.socmain80_d_cp = :SOCMAIN80_D_CP
            where socmain80_cab_codpostales.id_socmain80 = :ID_SOCMAIN80;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SOCMAIN80_UPDATE (
    ID_SOCMAIN80X BIGINT,
    SOCMAIN80_X_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_CODIGO VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_ASENTA VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_TIPO_ASENTA VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_CIUDAD VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_MNPIO VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_ESTADO VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_X_CP VARCHAR(300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCMAIN80 BIGINT,
    SOCMAIN80_D_PAIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CODIGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_ASENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_TIPO_ASENTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CIUDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_MNPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN80_D_CP VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DAR_ALTA INTEGER)
AS
declare variable C_SQL varchar(8000);
declare variable ID_SOCMAIN80FIND bigint;
begin
    dar_alta = 0;

    c_sql = 'UPDATE SOCMAIN80_CAB_CODPOSTALES SET SOCMAIN80_D_PAIS = ''' || :SOCMAIN80_X_PAIS || ''','
                                             || ' SOCMAIN80_D_CODIGO = ''' || :SOCMAIN80_X_CODIGO || ''','
                                             || ' SOCMAIN80_D_ASENTA = ''' || :SOCMAIN80_X_ASENTA || ''','
                                             || ' SOCMAIN80_D_TIPO_ASENTA = ''' || :SOCMAIN80_X_TIPO_ASENTA || ''','
                                             || ' SOCMAIN80_D_CIUDAD = ''' || :SOCMAIN80_X_CIUDAD || ''','
                                             || ' SOCMAIN80_D_MNPIO = ''' || :SOCMAIN80_X_MNPIO || ''','
                                             || ' SOCMAIN80_D_ESTADO = ''' || :SOCMAIN80_X_ESTADO || ''','
                                             || ' SOCMAIN80_D_CP = ''' || :SOCMAIN80_X_CP || ''''
                                             || ' WHERE ID_SOCMAIN80 = ' || :id_socmain80x;
    execute statement :c_sql
    on external 'SMXSEG'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey';

    FOR SELECT
    cbo_socmain80.id_socmain80,
    cbo_socmain80.socmain80_d_pais,
    cbo_socmain80.socmain80_d_codigo,
    cbo_socmain80.socmain80_d_asenta,
    cbo_socmain80.socmain80_d_tipo_asenta,
    cbo_socmain80.socmain80_d_ciudad,
    cbo_socmain80.socmain80_d_mnpio,
    cbo_socmain80.socmain80_d_estado,
    cbo_socmain80.socmain80_d_cp
    FROM cbo_socmain80(:SOCMAIN80_X_CODIGO) where cbo_socmain80.id_socmain80 = :id_socmain80x
    INTO :ID_SOCMAIN80,
         :SOCMAIN80_D_PAIS,
         :SOCMAIN80_D_CODIGO,
         :SOCMAIN80_D_ASENTA,
         :SOCMAIN80_D_TIPO_ASENTA,
         :SOCMAIN80_D_CIUDAD,
         :SOCMAIN80_D_MNPIO,
         :SOCMAIN80_D_ESTADO,
         :SOCMAIN80_D_CP
    DO
    BEGIN
        id_socmain80Find = null;

        select socmain80_cab_codpostales.id_socmain80
        from socmain80_cab_codpostales
        where socmain80_cab_codpostales.id_socmain80 = :ID_SOCMAIN80
        into :id_socmain80Find;

        if (id_socmain80Find is null) then
            insert into socmain80_cab_codpostales( socmain80_cab_codpostales.id_socmain80,
                                                   socmain80_cab_codpostales.socmain80_d_pais,
                                                   socmain80_cab_codpostales.socmain80_d_codigo,
                                                   socmain80_cab_codpostales.socmain80_d_asenta,
                                                   socmain80_cab_codpostales.socmain80_d_tipo_asenta,
                                                   socmain80_cab_codpostales.socmain80_d_ciudad,
                                                   socmain80_cab_codpostales.socmain80_d_mnpio,
                                                   socmain80_cab_codpostales.socmain80_d_estado,
                                                   socmain80_cab_codpostales.socmain80_d_cp )
            values(  :ID_SOCMAIN80,
                     :socmain80_d_pais,
                     :SOCMAIN80_D_CODIGO,
                     :SOCMAIN80_D_ASENTA,
                     :SOCMAIN80_D_TIPO_ASENTA,
                     :SOCMAIN80_D_CIUDAD,
                     :SOCMAIN80_D_MNPIO,
                     :SOCMAIN80_D_ESTADO,
                     :SOCMAIN80_D_CP );
        else
            update socmain80_cab_codpostales set socmain80_cab_codpostales.socmain80_d_pais = :socmain80_d_pais,
                                                  socmain80_cab_codpostales.socmain80_d_codigo = :SOCMAIN80_D_CODIGO,
                                                   socmain80_cab_codpostales.socmain80_d_asenta = :SOCMAIN80_D_ASENTA,
                                                   socmain80_cab_codpostales.socmain80_d_tipo_asenta = :SOCMAIN80_D_TIPO_ASENTA,
                                                   socmain80_cab_codpostales.socmain80_d_ciudad = :SOCMAIN80_D_CIUDAD,
                                                   socmain80_cab_codpostales.socmain80_d_mnpio = :SOCMAIN80_D_MNPIO,
                                                   socmain80_cab_codpostales.socmain80_d_estado = :SOCMAIN80_D_ESTADO,
                                                   socmain80_cab_codpostales.socmain80_d_cp = :SOCMAIN80_D_CP
            where socmain80_cab_codpostales.id_socmain80 = :ID_SOCMAIN80;

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE PRD_SOCMAIN90_VALIDAR (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGPATRONAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    MENSAJE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCUSUA32 bigint;
declare variable USUARIO_FIND varchar(50);
begin
    id_socusua32 = null;

    select first 1
    socusua32_det_documentos.id_socusua32
    from socsyst10_det_entradas
    inner join socusua32_det_documentos on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
    inner join socusua30_cab_entidades on (socusua32_det_documentos.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
    inner join socmain01_cab_empresas on (socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30)
    where socusua32_det_documentos.socusua32_documento = :RFC
    INTO :id_socusua32;

    if (id_socusua32 is not null) then
    begin
        mensaje = 'El RFC ingresado ya Existe en Documentos de Entidades como Empresa';
        suspend;
    end

    select first 1
    socusua32_det_documentos.id_socusua32
    from socsyst10_det_entradas
    inner join socusua32_det_documentos on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
    inner join socusua30_cab_entidades on (socusua32_det_documentos.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
    inner join socmain01_cab_empresas on (socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30)
    where socusua32_det_documentos.socusua32_documento = :REGPATRONAL
    INTO :id_socusua32;

    if (id_socusua32 is not null) then
    begin
        mensaje = 'El REGISTRO PATRONAL ingresado ya Existe en Documentos de Entidades como Empresa';
        suspend;
    end

    usuario_find = null;
    select smx$soc_seguridad.usuario_existe
    from smx$soc_seguridad('EXISTE', :usuario, null)
    into :usuario_find;

    if (usuario_find is not null) then
    begin
        mensaje = 'El USUARIO ingresado ya ha sido Usado, escriba otro Nombre de Usuario';
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SOCSYST10_ADD (
    CODIGO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCSYST10 BIGINT,
    SOCSYST10_FAPL TIMESTAMP)
AS
declare variable ID_SOCSYST09 bigint;
begin
    codigo = upper(trim(codigo));

    SELECT socsyst09_cab_entradas.id_socsyst09
    FROM socsyst09_cab_entradas
    WHERE socsyst09_cab_entradas.socsyst09_codigo = :codigo
    into :id_socsyst09;

    if(id_socsyst09 is not null) then
    begin
        insert into socsyst10_det_entradas(socsyst10_det_entradas.rela_socsyst09,
                                           socsyst10_det_entradas.socsyst10_codigo,
                                           socsyst10_det_entradas.socsyst10_descripcion,
                                           socsyst10_det_entradas.socsyst10_grupo)
        values(:id_socsyst09,
               'SMXAUTO',
               :descripcion,
               'NONE');

        select
        socsyst91_tbl_ultids.socsyst91_ultid,
        socsyst91_tbl_ultids.socsyst91_fapl
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCSYST10'
        INTO :id_socsyst10,
             :socsyst10_fapl;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SOCSYST13_ENTRADAS (
    PRM_ID_SOCSYST01 BIGINT,
    PRM_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_COD01 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_DES01 VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_COD02 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_DES02 VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_COD03 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_DES03 VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_COD04 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PRM_SOCSYST14_DES04 VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RESULTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCSYST13 bigint;
begin
    select socsyst13_cab_reportes.id_socsyst13
      from socsyst13_cab_reportes
     where socsyst13_cab_reportes.socsyst13_codigo = :PRM_CODIGO
      into :id_socsyst13;

    if (id_socsyst13 is null) then
        begin
            INSERT INTO SOCSYST13_CAB_REPORTES (RELA_SOCSYST01, SOCSYST13_CODIGO, SOCSYST13_DESCRIPCION, SOCSYST13_REPORTE, SOCSYST13_FXML, SOCSYST13_TIPO, SOCSYST13_ACTIVO)
                 VALUES (:PRM_ID_SOCSYST01, upper(:PRM_CODIGO), :PRM_DESCRIPCION, lower(:PRM_CODIGO), lower(:PRM_CODIGO), 'L', 1);
            
            select socsyst13_cab_reportes.id_socsyst13
              from socsyst13_cab_reportes
             where socsyst13_cab_reportes.socsyst13_codigo = :PRM_CODIGO
              into :id_socsyst13;
        end

    if (id_socsyst13 is null) then
        resultado = 'ERROR: No se inserto el id_socsyst13';
    else
       begin
         if (PRM_SOCSYST14_COD01 is not null and PRM_SOCSYST14_DES01 is not null) then
             INSERT INTO SOCSYST14_DET_PARAMETROS (RELA_SOCSYST13, SOCSYST14_DESCRIPCION, SOCSYST14_PARAMETRO, SOCSYST14_VALOR)
             VALUES (:id_socsyst13, :PRM_SOCSYST14_DES01, upper(:PRM_SOCSYST14_COD01), NULL);

         if (PRM_SOCSYST14_COD02 is not null and PRM_SOCSYST14_DES02 is not null) then
             INSERT INTO SOCSYST14_DET_PARAMETROS (RELA_SOCSYST13, SOCSYST14_DESCRIPCION, SOCSYST14_PARAMETRO, SOCSYST14_VALOR)
             VALUES (:id_socsyst13, :PRM_SOCSYST14_DES02, upper(:PRM_SOCSYST14_COD02), NULL);

         if (PRM_SOCSYST14_COD03 is not null and PRM_SOCSYST14_DES03 is not null) then
             INSERT INTO SOCSYST14_DET_PARAMETROS (RELA_SOCSYST13, SOCSYST14_DESCRIPCION, SOCSYST14_PARAMETRO, SOCSYST14_VALOR)
             VALUES (:id_socsyst13, :PRM_SOCSYST14_DES03, upper(:PRM_SOCSYST14_COD03), NULL);

         if (PRM_SOCSYST14_COD04 is not null and PRM_SOCSYST14_DES04 is not null) then
             INSERT INTO SOCSYST14_DET_PARAMETROS (RELA_SOCSYST13, SOCSYST14_DESCRIPCION, SOCSYST14_PARAMETRO, SOCSYST14_VALOR)
             VALUES (:id_socsyst13, :PRM_SOCSYST14_DES04, upper(:PRM_SOCSYST14_COD04), NULL);

            resultado = 'ok: Parametros Insertados.';
        end
  suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SOCSYST51 (
    RELA_SOCUSUA01 BIGINT,
    ALIAS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VALOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCSYST51 BIGINT)
AS
declare variable SQL varchar(1000);
begin
    id_socsyst51 = null;

    Select first 1 socsyst51_tbl_users.id_socsyst51
    from socsyst51_tbl_users
    where socsyst51_tbl_users.rela_socusua01 = :rela_socusua01
    into :id_socsyst51;

    if (id_socsyst51 is null) then
    begin
        sql = 'INSERT INTO socsyst51_tbl_users(rela_socusua01, SOCSYST51_' || :alias || ') VALUES(' ||
              :rela_socusua01 || ',' || :valor || ')';
    end
    else
    begin
        sql = 'UPDATE socsyst51_tbl_users set socsyst51_' || :alias || ' = ' || :valor ||
              ' where rela_socusua01 = ' || :rela_socusua01;
    end

    execute statement :sql;

    suspend;
end^


