CREATE OR ALTER PROCEDURE PRD_SOCUSUA32_VALIDA (
    ID_SOCSYST10_TD001 BIGINT,
    DOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID BIGINT,
    TIPODOCU VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CATEGORIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SOCUSUA30_EMPRESA bigint;
begin
    id = 1;
    documento = trim(upper(documento));

    SELECT socusua32_det_documentos.rela_socusua30
    FROM socusua32_det_documentos
    where socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_td001
    and trim(upper(socusua32_det_documentos.socusua32_documento)) = :documento
    into :rela_socusua30;

    if (rela_socusua30 is not null) then
    begin
        select socsyst10_det_entradas.socsyst10_descripcion
        from socsyst10_det_entradas
        where socsyst10_det_entradas.id_socsyst10 = :id_socsyst10_td001
        into :tipodocu;

        docnro = :documento;

        select cbo_socusua30.entidad,
        cbo_socusua30.tipo
        from cbo_socusua30(:rela_socusua30)
        into :entidad,
             :entidad_tipo;

        empresa = 'Entidad sin asignar a Empresa, Proveedor, Cliente y/o Empleado';
        categoria = 'Sin Categoria';

        select socmain01_cab_empresas.rela_socusua30
        from socmain01_cab_empresas
        where socmain01_cab_empresas.rela_socusua30 = :rela_socusua30
        into :rela_socusua30_empresa;

        if (rela_socusua30_empresa is not null) then
        begin
            categoria = 'Empresa';

            select cbo_socusua30.entidad
            from cbo_socusua30(:rela_socusua30_empresa)
            into :empresa;
        end

        /* ================================================================================================================ */
        /* ================================================================================================================ */
        /* ================================================================================================================ */

        if (rela_socusua30_empresa is null) then
        begin
            select max(socmain01_cab_empresas.rela_socusua30)
            from sicnomi01_cab_empleados
            inner join socmain01_cab_empresas on ( socmain01_cab_empresas.id_socmain01 = sicnomi01_cab_empleados.rela_socmain01 )
            where sicnomi01_cab_empleados.rela_socusua30 = :rela_socusua30
            into :rela_socusua30_empresa;

            if (rela_socusua30_empresa is not null) then
            begin
                categoria = 'Empleado';

                select cbo_socusua30.entidad
                from cbo_socusua30(:rela_socusua30_empresa)
                into :empresa;
            end
        end

        /* ================================================================================================================ */
        /* ================================================================================================================ */
        /* ================================================================================================================ */

        if (rela_socusua30_empresa is null) then
        begin
            select max(socmain01_cab_empresas.rela_socusua30)
            from sicegre01_cab_proveedores
            inner join socmain01_cab_empresas on ( socmain01_cab_empresas.id_socmain01 = sicegre01_cab_proveedores.rela_socmain01 )
            where sicegre01_cab_proveedores.rela_socusua30 = :rela_socusua30
            into :rela_socusua30_empresa;

            if (rela_socusua30_empresa is not null) then
            begin
                categoria = 'Proveedor';

                select cbo_socusua30.entidad
                from cbo_socusua30(:rela_socusua30_empresa)
                into :empresa;
            end
        end

        /* ================================================================================================================ */
        /* ================================================================================================================ */
        /* ================================================================================================================ */

        if (rela_socusua30_empresa is null) then
        begin
            select max(socmain01_cab_empresas.rela_socusua30)
            from sicingr01_cab_clientes
            inner join socmain01_cab_empresas on ( socmain01_cab_empresas.id_socmain01 = sicingr01_cab_clientes.rela_socmain01 )
            where sicingr01_cab_clientes.rela_socusua30 = :rela_socusua30
            into :rela_socusua30_empresa;

            if (rela_socusua30_empresa is not null) then
            begin
                categoria = 'Cliente';

                select cbo_socusua30.entidad
                from cbo_socusua30(:rela_socusua30_empresa)
                into :empresa;
            end
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE PRD_SOCUSUA35_SICINGR01_CORREO (
    ID_USER BIGINT,
    CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODALIDAD INTEGER)
RETURNS (
    ID_SOCUSUA35 BIGINT,
    CORREO_USER VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCSYST10 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SICINGR01 bigint;
begin
    if (modalidad = 0) then
    begin
       id_sicingr01 = id_user;
    end
    if (modalidad = 1) then
    begin
        select sicingr70_cab_facturacion.rela_sicingr01
        from sicingr70_cab_facturacion
        where sicingr70_cab_facturacion.id_sicingr70 = :id_user
        into :id_sicingr01;
    end

    id_socusua35 = -1;
    correo_user = '';

    if (correo is null) then
    begin
        select first 1
        socusua35_det_internet.id_socusua35,
        socusua35_det_internet.socusua35_internet
        from sicingr01_cab_clientes
        inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = sicingr01_cab_clientes.rela_socusua30)
        inner join socusua35_det_internet on (socusua30_cab_entidades.id_socusua30 = socusua35_det_internet.rela_socusua30)
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01)
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        and socsyst10_det_entradas.socsyst10_codigo = 'CORREO'
        into :id_socusua35,
             :correo_user;
    end
    else
    begin
        select CBO_SOCSYST10_TDI01.id_socsyst10
        from CBO_SOCSYST10_TDI01
        where CBO_SOCSYST10_TDI01.socsyst10_codigo = 'CORREO'
        into :id_socsyst10;

        select sicingr01_cab_clientes.rela_socusua30
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        into :rela_socusua30;

        select socusua35_det_internet.id_socusua35
        from socusua35_det_internet
        where socusua35_det_internet.rela_socusua30 = :rela_socusua30
        and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10
        into :id_socusua35;

        if (id_socusua35 = -1) then
        begin
            insert into socusua35_det_internet ( socusua35_det_internet.rela_socusua30,
                                                 socusua35_det_internet.rela_socsyst10_tdi01,
                                                 socusua35_det_internet.socusua35_internet )
            values( :rela_socusua30,
                    :id_socsyst10,
                    :correo );

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA35'
            INTO :id_socusua35;
        end
        else
        begin
            update socusua35_det_internet set socusua35_det_internet.socusua35_internet = :correo
            where socusua35_det_internet.rela_socusua30 = :rela_socusua30
            and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10;
        end

        correo_user = :correo;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SOCUSUA35_SICINGR01P_CORREO (
    ID_USER BIGINT,
    CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODALIDAD INTEGER)
RETURNS (
    ID_SOCUSUA35 BIGINT,
    CORREO_USER VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCSYST10 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SICINGR01 bigint;
begin
    if (modalidad = 0) then
    begin
       id_sicingr01 = id_user;
    end
    if (modalidad = 1) then
    begin
        select sicingr51_cab_bancos.rela_sicingr01
        from sicpago70_cab_pago
        inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51 )
        where sicpago70_cab_pago.id_sicpago70 = :id_user
        into :id_sicingr01;
    end

    id_socusua35 = -1;
    correo_user = '';

    if (correo is null) then
    begin
        select first 1
        socusua35_det_internet.id_socusua35,
        socusua35_det_internet.socusua35_internet
        from sicingr01_cab_clientes
        inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = sicingr01_cab_clientes.rela_socusua30)
        inner join socusua35_det_internet on (socusua30_cab_entidades.id_socusua30 = socusua35_det_internet.rela_socusua30)
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01)
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        and socsyst10_det_entradas.socsyst10_codigo = 'CORREO'
        into :id_socusua35,
             :correo_user;
    end
    else
    begin
        select CBO_SOCSYST10_TDI01.id_socsyst10
        from CBO_SOCSYST10_TDI01
        where CBO_SOCSYST10_TDI01.socsyst10_codigo = 'CORREO'
        into :id_socsyst10;

        select sicingr01_cab_clientes.rela_socusua30
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01
        into :rela_socusua30;

        select socusua35_det_internet.id_socusua35
        from socusua35_det_internet
        where socusua35_det_internet.rela_socusua30 = :rela_socusua30
        and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10
        into :id_socusua35;

        if (id_socusua35 = -1) then
        begin
            insert into socusua35_det_internet ( socusua35_det_internet.rela_socusua30,
                                                 socusua35_det_internet.rela_socsyst10_tdi01,
                                                 socusua35_det_internet.socusua35_internet )
            values( :rela_socusua30,
                    :id_socsyst10,
                    :correo );

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA35'
            INTO :id_socusua35;
        end
        else
        begin
            update socusua35_det_internet set socusua35_det_internet.socusua35_internet = :correo
            where socusua35_det_internet.rela_socusua30 = :rela_socusua30
            and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10;
        end

        correo_user = :correo;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SOCUSUA35_SICNOMI01_CORREO (
    ID_USER BIGINT,
    CORREO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MODALIDAD INTEGER)
RETURNS (
    ID_SOCUSUA35 BIGINT,
    CORREO_USER VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCSYST10 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable ID_SICNOMI01 bigint;
begin
    if (modalidad = 0) then
    begin
       id_sicnomi01 = id_user;
    end
    if (modalidad = 1) then
    begin
        select sicnomi70_cab_nomina.rela_sicnomi01
        from sicnomi70_cab_nomina
        where sicnomi70_cab_nomina.id_sicnomi70 = :id_user
        into :id_sicnomi01;
    end

    id_socusua35 = -1;
    correo_user = '';

    if (correo is null) then
    begin
        select first 1
        socusua35_det_internet.id_socusua35,
        socusua35_det_internet.socusua35_internet
        from sicnomi01_cab_empleados
        inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = sicnomi01_cab_empleados.rela_socusua30)
        inner join socusua35_det_internet on (socusua30_cab_entidades.id_socusua30 = socusua35_det_internet.rela_socusua30)
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01)
        where sicnomi01_cab_empleados.id_sicnomi01 = :id_sicnomi01
        and socsyst10_det_entradas.socsyst10_codigo = 'CORREO'
        into :id_socusua35,
             :correo_user;
    end
    else
    begin
        select CBO_SOCSYST10_TDI01.id_socsyst10
        from CBO_SOCSYST10_TDI01
        where CBO_SOCSYST10_TDI01.socsyst10_codigo = 'CORREO'
        into :id_socsyst10;

        select sicnomi01_cab_empleados.rela_socusua30
        from sicnomi01_cab_empleados
        where sicnomi01_cab_empleados.id_sicnomi01 = :id_sicnomi01
        into :rela_socusua30;

        select socusua35_det_internet.id_socusua35
        from socusua35_det_internet
        where socusua35_det_internet.rela_socusua30 = :rela_socusua30
        and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10
        into :id_socusua35;

        if (id_socusua35 = -1) then
        begin
            insert into socusua35_det_internet ( socusua35_det_internet.rela_socusua30,
                                                 socusua35_det_internet.rela_socsyst10_tdi01,
                                                 socusua35_det_internet.socusua35_internet )
            values( :rela_socusua30,
                    :id_socsyst10,
                    :correo );

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA35'
            INTO :id_socusua35;
        end
        else
        begin
            update socusua35_det_internet set socusua35_det_internet.socusua35_internet = :correo
            where socusua35_det_internet.rela_socusua30 = :rela_socusua30
            and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10;
        end

        correo_user = :correo;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE PRD_SYSUSER11 (
    MODO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VALOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID BIGINT)
RETURNS (
    ID_SYSUSER11 BIGINT,
    SYSUSER11_OK INTEGER,
    SYSUSER11_FAPL TIMESTAMP)
AS
declare variable ID_SYSUSER10 bigint;
declare variable ID_SYSUSER11X bigint;
begin
    id_sysuser11 = 1;
    sysuser11_ok = 0;
    sysuser11_fapl = current_timestamp;

    id_sysuser10 = -1;

    if (modo = 'C') then
        select sysuser10_cab_movil.id_sysuser10
        from sysuser10_cab_movil
        where sysuser10_cab_movil.sysuser10_correo = :valor
        or sysuser10_cab_movil.sysuser10_correo_01 = :valor
        into :id_sysuser10;

    else if (modo = 'T') then
        select sysuser10_cab_movil.id_sysuser10
        from sysuser10_cab_movil
        where sysuser10_cab_movil.sysuser10_telefono = :valor
        into :id_sysuser10;

    if (id_sysuser10 = -1) then
    begin
        sysuser11_ok = 0;
        suspend;
    end
    else
    begin
        id_sysuser11x = -1;

        select sysuser11_det_contactos.id_sysuser11
        from sysuser11_det_contactos
        where sysuser11_det_contactos.rela_sysuser10 = :id
        and sysuser11_det_contactos.rela_sysuser10_invitado = :id_sysuser10
        into :id_sysuser11x;

        if (id_sysuser11x <> -1) then
        begin
            sysuser11_ok = 1;
            suspend;
        end
        else
        begin
            insert into sysuser11_det_contactos(
            sysuser11_det_contactos.rela_sysuser10,
            sysuser11_det_contactos.rela_sysuser10_invitado,
            sysuser11_det_contactos.sysuser11_relacion,
            sysuser11_det_contactos.sysuser11_aceptado)
            values (:id, :id_sysuser10, 'invitado', 0);

            sysuser11_ok = 2;
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE PRD_TID_SICINGR01_WEB (
    MODALIDAD VARCHAR(2) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    AVISOFOLIOS INTEGER,
    RELA_SOCMAIN01_OLD BIGINT,
    RELA_SOCMAIN01_NEW BIGINT,
    RELA_SOCMAIN80_OLD BIGINT,
    RELA_SOCMAIN80_NEW BIGINT,
    ENTIDAD_OLD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_NEW VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCUSUA30_OLD BIGINT,
    RELA_SOCUSUA30_NEW BIGINT,
    RFC_OLD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_NEW VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MAIL_OLD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MAIL_NEW VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SOCMAIN80 BIGINT,
    RELA_SOCUSUA30 BIGINT)
AS
declare variable ID_SOCSYST10_TP001 bigint;
declare variable ID_SOCSYST10_RFC bigint;
declare variable ID_SOCSYST10_DOMI bigint;
declare variable ID_SOCSYST10_CORREO bigint;
declare variable ID_SOCMAIN10_FACT bigint;
declare variable ID_SOCMAIN10_PAGO bigint;
declare variable ID_SOCSYST10_PCT01 bigint;
declare variable ID_SOCSYST10_CO001_FACT bigint;
declare variable ID_SOCSYST10_CO001_PAGO bigint;
declare variable RELA_SOCMAIN20 bigint;
declare variable RELA_SOCSYST06 bigint;
declare variable CODPOSTAL varchar(10);
declare variable EXISTE integer;
declare variable STR_USUARIO varchar(50);
declare variable INT_USUARIO bigint;
begin
    rela_socmain80 = :rela_socmain80_old;
    rela_socusua30 = :rela_socusua30_old;

    if (modalidad = 'A') then
    BEGIN
        select
        smx$soc_socmain80_update_remoto.id_socmain80_reto,
        smx$soc_socmain80_update_remoto.codpostal
        from smx$soc_socmain80_update_remoto(:rela_socmain80_new)
        into :rela_socmain80,
             :codpostal;
    
        select cbo_socsyst10_tp001.id_socsyst10
        from cbo_socsyst10_tp001
        where cbo_socsyst10_tp001.socsyst10_codigo = 'MORAL'
        into :id_socsyst10_tp001;
            
        insert into socusua30_cab_entidades(socusua30_cab_entidades.rela_socsyst10,
                                            socusua30_cab_entidades.socusua30_nombre_razsoc,
                                            socusua30_cab_entidades.socusua30_fnac_const,
                                            socusua30_cab_entidades.socusua30_extranjero)
        values(:id_socsyst10_tp001,
               :entidad_new,
               current_date,
               0);
    
        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA30'
        INTO :rela_socusua30;
    
        select cbo_socsyst10_td001.id_socsyst10
        from cbo_socsyst10_td001
        where cbo_socsyst10_td001.socsyst10_codigo = 'RFC'
        into :id_socsyst10_rfc;
        
        select cbo_socsyst10_tdd01.id_socsyst10
        from cbo_socsyst10_tdd01
        where cbo_socsyst10_tdd01.socsyst10_codigo = 'PARTICULAR'
        into :id_socsyst10_domi;
    
        select cbo_socsyst10_tdi01.id_socsyst10
        from cbo_socsyst10_tdi01
        where cbo_socsyst10_tdi01.socsyst10_codigo = 'CORREO'
        into :id_socsyst10_correo;
    
        insert into SOCUSUA32_DET_DOCUMENTOS(SOCUSUA32_DET_DOCUMENTOS.rela_socusua30,
                                             SOCUSUA32_DET_DOCUMENTOS.rela_socsyst10_td001,
                                             SOCUSUA32_DET_DOCUMENTOS.socusua32_documento,
                                             SOCUSUA32_DET_DOCUMENTOS.socusua32_principal)
        values(:rela_socusua30,
               :id_socsyst10_rfc,
               :rfc_new,
               1);
    
        insert into socusua35_det_internet(socusua35_det_internet.rela_socusua30,
                                           socusua35_det_internet.rela_socsyst10_tdi01,
                                           socusua35_det_internet.socusua35_internet)
        values(:rela_socusua30,
               :id_socsyst10_correo,
               :mail_new);
        
        insert into socusua36_det_domicilios(socusua36_det_domicilios.rela_socusua30,
                                             socusua36_det_domicilios.rela_socsyst10_tdd01,
                                             socusua36_det_domicilios.rela_socmain80,
                                             socusua36_det_domicilios.socusua36_codpostal,
                                             socusua36_det_domicilios.socusua36_calle,
                                             socusua36_det_domicilios.socusua36_nro,
                                             socusua36_det_domicilios.socusua36_nrointerior,
                                             socusua36_det_domicilios.socusua36_ciudad,
                                             socusua36_det_domicilios.socusua36_colonia,
                                             socusua36_det_domicilios.socusua36_referencia)
        values(:rela_socusua30,
               :id_socsyst10_domi,
               :rela_socmain80,
               :codpostal,
               '',
               '',
               '',
               '',
               '',
               '');
    END
    ELSE if (modalidad = 'AA') then
    BEGIN
        insert into SOCMAIN20_CAB_ORGANIZACION(SOCMAIN20_CAB_ORGANIZACION.rela_socmain01,
                                               SOCMAIN20_CAB_ORGANIZACION.socmain20_codigo,
                                               SOCMAIN20_CAB_ORGANIZACION.socmain20_descripcion)
        values(:rela_socmain01_new,
               'AUT00' || CAST(:rela_socmain01_new AS VARCHAR(10)),
               :entidad_new);

        select socsyst91_tbl_ultids.socsyst91_ultid
        from socsyst91_tbl_ultids
        where socsyst91_tbl_ultids.socsyst91_usuario = current_user
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCMAIN20'
        into :rela_socmain20;

        select first 1
        socmain21_arb_organizacion.rela_socsyst06
        from socmain21_arb_organizacion
        where socmain21_arb_organizacion.rela_socmain21 is null
        into :rela_socsyst06;

        insert into socmain21_arb_organizacion(socmain21_arb_organizacion.rela_socmain20,
                                               socmain21_arb_organizacion.rela_socsyst06,
                                               socmain21_arb_organizacion.socmain21_codigo,
                                               SOCMAIN21_ARB_ORGANIZACION.socmain21_codigo_ext,
                                               SOCMAIN21_ARB_ORGANIZACION.socmain21_descripcion)
        values(:rela_socmain20,
               :rela_socsyst06,
               'AUT00' || CAST(:rela_socmain20 AS VARCHAR(10)),
               'AUT01' || CAST(:rela_socmain20 AS VARCHAR(10)),
               :entidad_new);

        /* ================================================================================================================== */
                

        select CBO_SOCSYST10_PCT01.id_socsyst10
        from CBO_SOCSYST10_PCT01
        where CBO_SOCSYST10_PCT01.socsyst10_codigo = 'CTAGRAL'
        into :id_socsyst10_pct01;
    
        insert into sicxmls01_cab_parametros(sicxmls01_cab_parametros.rela_socmain01,
                                             sicxmls01_cab_parametros.rela_socsyst10_pct01,
                                             sicxmls01_cab_parametros.sicxmls01_ajuste_monto)
        values(:rela_socmain01_new,
               :id_socsyst10_pct01,
               1);

        /* ================================================================================================================== */

        select cbo_socsyst10_co001.id_socsyst10
        from cbo_socsyst10_co001
        where cbo_socsyst10_co001.socsyst10_codigo = 'SICINGR70'
        into :id_socsyst10_co001_fact;

        insert into socmain10_det_contadores(socmain10_det_contadores.rela_socmain01,
                                                 socmain10_det_contadores.rela_socsyst10_co001,
                                                 socmain10_det_contadores.socmain10_modo)
        values( :rela_socmain01_new,
                :id_socsyst10_co001_fact,
                0 );

        /* ================================================================================================================== */

        select cbo_socsyst10_co001.id_socsyst10
        from cbo_socsyst10_co001
        where cbo_socsyst10_co001.socsyst10_codigo = 'SICPAGO70'
        into :id_socsyst10_co001_pago;

        insert into socmain10_det_contadores(socmain10_det_contadores.rela_socmain01,
                                                 socmain10_det_contadores.rela_socsyst10_co001,
                                                 socmain10_det_contadores.socmain10_modo)
        values( :rela_socmain01_new,
                :id_socsyst10_co001_pago,
                0 );

        /* ================================================================================================================== */

        if (position ('JAM$_' in current_user) != -1) then
        begin
            str_usuario = trim(substring(current_user from 6));
    
            select socusua01_cab_usuarios.id_socusua01
            from socusua01_cab_usuarios
            where socusua01_cab_usuarios.socusua01_usuario = :str_usuario
            into :int_usuario;
    
            insert into socusua04_det_empresas(socusua04_det_empresas.rela_socusua01,
                                               socusua04_det_empresas.rela_socmain01)
            values(:int_usuario, :rela_socmain01_new);
        end
    END
    ELSE if (modalidad = 'M') then
    BEGIN
        if (avisofolios IS NOT NULL AND avisofolios != 0) then
        BEGIN
            select first 1 socmain10_det_contadores.id_socmain10
            from socmain10_det_contadores
            inner join cbo_socsyst10_co001 on (cbo_socsyst10_co001.id_socsyst10 = socmain10_det_contadores.rela_socsyst10_co001)
            where socmain10_det_contadores.rela_socmain01 = :rela_socmain01_old
            and cbo_socsyst10_co001.socsyst10_codigo = 'SICINGR70'
            into :id_socmain10_fact;
    
            insert into socmain11_mov_folios(socmain11_mov_folios.rela_socmain10,
                                             socmain11_mov_folios.socmain11_pac,
                                             socmain11_mov_folios.socmain11_folios_comprados,
                                             socmain11_mov_folios.socmain11_folios_consumidos,
                                             socmain11_mov_folios.socmain11_importe,
                                             socmain11_mov_folios.socmain11_fecha)
            values( :id_socmain10_fact,
                    'CLF',
                    :avisofolios/2,
                    0,
                    0.10,
                    current_date );
    
            select first 1 socmain10_det_contadores.id_socmain10
            from socmain10_det_contadores
            inner join cbo_socsyst10_co001 on (cbo_socsyst10_co001.id_socsyst10 = socmain10_det_contadores.rela_socsyst10_co001)
            where socmain10_det_contadores.rela_socmain01 = :rela_socmain01_old
            and cbo_socsyst10_co001.socsyst10_codigo = 'SICPAGO70'
            into :id_socmain10_pago;
    
            insert into socmain11_mov_folios(socmain11_mov_folios.rela_socmain10,
                                             socmain11_mov_folios.socmain11_pac,
                                             socmain11_mov_folios.socmain11_folios_comprados,
                                             socmain11_mov_folios.socmain11_folios_consumidos,
                                             socmain11_mov_folios.socmain11_importe,
                                             socmain11_mov_folios.socmain11_fecha)
            values( :id_socmain10_pago,
                    'CLF',
                    :avisofolios/2,
                    0,
                    0.10,
                    current_date );
        END


        if ((:rela_socmain80_old <> :rela_socmain80_new) or (:rela_socmain80_old is null)) then
        begin
            select
            smx$soc_socmain80_update_remoto.id_socmain80_reto,
            smx$soc_socmain80_update_remoto.codpostal
            from smx$soc_socmain80_update_remoto(:rela_socmain80_new)
            into :rela_socmain80,
                 :codpostal;
    
            select cbo_socsyst10_tdd01.id_socsyst10
            from cbo_socsyst10_tdd01
            where cbo_socsyst10_tdd01.socsyst10_codigo = 'PARTICULAR'
            into :id_socsyst10_domi;
    
            select count(*)
            from socusua36_det_domicilios
            where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_old
            and socusua36_det_domicilios.rela_socsyst10_tdd01 = :id_socsyst10_domi
            into :existe;

            if (existe = 0) then
                insert into socusua36_det_domicilios(socusua36_det_domicilios.rela_socusua30,
                                                     socusua36_det_domicilios.rela_socsyst10_tdd01,
                                                     socusua36_det_domicilios.rela_socmain80,
                                                     socusua36_det_domicilios.socusua36_codpostal,
                                                     socusua36_det_domicilios.socusua36_calle,
                                                     socusua36_det_domicilios.socusua36_nro,
                                                     socusua36_det_domicilios.socusua36_nrointerior,
                                                     socusua36_det_domicilios.socusua36_ciudad,
                                                     socusua36_det_domicilios.socusua36_colonia,
                                                     socusua36_det_domicilios.socusua36_referencia)
                values(:rela_socusua30_old,
                       :id_socsyst10_domi,
                       :rela_socmain80,
                       :codpostal, 
                       '',
                       '',
                       '',
                       '',
                       '',
                       '');
            else
                update socusua36_det_domicilios
                set socusua36_det_domicilios.rela_socmain80 = rela_socmain80,
                    socusua36_det_domicilios.socusua36_codpostal = :codpostal
                where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_old
                and socusua36_det_domicilios.rela_socsyst10_tdd01 = :id_socsyst10_domi;
        end

        /* ------------------------------------------------------------------------------------------- */
    
        if (:rfc_old != :rfc_new) then
        begin
            select cbo_socsyst10_td001.id_socsyst10
            from cbo_socsyst10_td001
            where cbo_socsyst10_td001.socsyst10_codigo = 'RFC'
            into :id_socsyst10_rfc;

            select count(*)
            from socusua32_det_documentos
            where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_old
            and socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_rfc
            into :existe;

            if (existe = 0) then
                insert into SOCUSUA32_DET_DOCUMENTOS(SOCUSUA32_DET_DOCUMENTOS.rela_socusua30,
                                                     SOCUSUA32_DET_DOCUMENTOS.rela_socsyst10_td001,
                                                     SOCUSUA32_DET_DOCUMENTOS.socusua32_documento,
                                                     SOCUSUA32_DET_DOCUMENTOS.socusua32_principal)
                values(:rela_socusua30_old,
                       :id_socsyst10_rfc,
                       :rfc_new,
                       1);    
            else
                update socusua32_det_documentos
                set socusua32_det_documentos.socusua32_documento = :rfc_new
                where socusua32_det_documentos.rela_socusua30 = :rela_socusua30_old
                and socusua32_det_documentos.rela_socsyst10_td001 = :id_socsyst10_rfc;
        end

        /* ------------------------------------------------------------------------------------------- */
    
        if (:entidad_old != :entidad_new) then
        begin
            update socusua30_cab_entidades
            set socusua30_cab_entidades.socusua30_nombre_razsoc = :entidad_new
            where socusua30_cab_entidades.id_socusua30 = :rela_socusua30_old;
        end

        /* ------------------------------------------------------------------------------------------- */

        if (:mail_old != mail_new) then
        begin
            select cbo_socsyst10_tdi01.id_socsyst10
            from cbo_socsyst10_tdi01
            where cbo_socsyst10_tdi01.socsyst10_codigo = 'CORREO'
            into :id_socsyst10_correo;

            select count(*)
            from socusua35_det_internet
            where socusua35_det_internet.rela_socusua30 = :rela_socusua30_old
            and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10_correo
            into :existe;

            if (existe = 0) then
                insert into socusua35_det_internet(socusua35_det_internet.rela_socusua30,
                                                   socusua35_det_internet.rela_socsyst10_tdi01,
                                                   socusua35_det_internet.socusua35_internet)
                values(:rela_socusua30_old,
                       :id_socsyst10_correo,
                       :mail_new);
            else
                update socusua35_det_internet
                set socusua35_det_internet.socusua35_internet = :mail_new
                where socusua35_det_internet.rela_socusua30 = :rela_socusua30_old
                and socusua35_det_internet.rela_socsyst10_tdi01 = :id_socsyst10_correo;
        end
    END
    ELSE if (modalidad = 'B') then
    BEGIN
        delete from socusua30_cab_entidades where socusua30_cab_entidades.id_socusua30 = :rela_socusua30;
    END
end^


CREATE OR ALTER PROCEDURE REP_ENTIDADES (
    RELA_SOCUSUA30 BIGINT)
RETURNS (
    ID_SOCUSUA30 BIGINT,
    CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMICILIO VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCUMENTO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TELEFONO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CORREO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
declare variable SOCUSUA36_CODPOSTAL integer;
declare variable SOCUSUA36_CALLE varchar(400);
declare variable SOCUSUA36_NRO varchar(400);
declare variable SOCUSUA36_CIUDAD varchar(400);
declare variable SOCUSUA36_COLONIA varchar(400);
declare variable SOCSYST10_DESCRIPCION varchar(400);
declare variable SOCUSUA32_DOCUMENTO varchar(400);
declare variable SOCSYST10_DESCRIPCIONT varchar(400);
declare variable SOCUSUA31_LADA varchar(10);
declare variable SOCUSUA31_NRO varchar(10);
begin
    id_socusua30 = :rela_socusua30;

    /* armo los datos del nombre del cliente */
    select
    GRD_SOCUSUA30.socusua30_apellido_pat,
    GRD_SOCUSUA30.socusua30_apellido_mat,
    GRD_SOCUSUA30.socusua30_nombre_razsoc
    from GRD_SOCUSUA30
    where GRD_SOCUSUA30.id_socusua30 = :rela_socusua30
    into :socusua30_apellido_pat,
         :socusua30_apellido_mat,
         :socusua30_nombre_razsoc;

    cliente = trim(COALESCE(socusua30_apellido_pat, '')) || ' ' ||
              trim(COALESCE(socusua30_apellido_mat, '')) || ', ' ||
              trim(COALESCE(socusua30_nombre_razsoc, ''));

    /* tomo la direccion del cliente */
    select first 1
    grd_socusua36.socusua36_codpostal,
    grd_socusua36.socusua36_calle,
    grd_socusua36.socusua36_nro,
    grd_socusua36.socusua36_ciudad,
    grd_socusua36.socusua36_colonia
    from grd_socusua36
    where grd_socusua36.rela_socusua30 = :rela_socusua30
    into :socusua36_codpostal,
         :socusua36_calle,
         :socusua36_nro,
         :socusua36_ciudad,
         :socusua36_colonia;

    if (socusua36_codpostal is not null) then
        domicilio = trim(COALESCE(socusua36_calle, '')) || ' ' ||
                    trim(COALESCE(socusua36_nro, '')) || ' (' ||
                    trim(COALESCE(socusua36_ciudad, '')) || '-' ||
                    trim(COALESCE(socusua36_colonia, '')) || ') ' ||
                    ' CP: ' || socusua36_codpostal;

    /* documentacion del cliente */

    select first 1
    GRD_SOCUSUA32.socsyst10_descripcion,
    GRD_SOCUSUA32.socusua32_documento
    from GRD_SOCUSUA32
    where GRD_SOCUSUA32.rela_socusua30 = :rela_socusua30
    and GRD_SOCUSUA32.socusua32_principal = 1
    into :socsyst10_descripcion,
         :socusua32_documento;

    if (socsyst10_descripcion is not null) then
        documento = trim(COALESCE(socsyst10_descripcion, '')) || ': ' ||
                    trim(COALESCE(socusua32_documento, ''));

    /* telefono del cliente */

    select first 1
    grd_socusua31.socsyst10_descripcion,
    grd_socusua31.socusua31_lada,
    grd_socusua31.socusua31_nro
    from grd_socusua31
    where grd_socusua31.rela_socusua30 = :rela_socusua30
    into :socsyst10_descripcionT,
         :socusua31_lada,
         :socusua31_nro;

    if (socusua31_lada is not null) then
        telefono = '(' || trim(COALESCE(socusua31_lada, '')) || ') ' ||
                          trim(COALESCE(socusua31_nro, ''));

    /*
    telefono = trim(COALESCE(socsyst10_descripcionT, '')) || ': (' ||
               trim(COALESCE(socusua31_lada, '')) || ') ' ||
               trim(COALESCE(socusua31_nro, ''));
    */
    /* busco el correo del cliente */

    select first 1
    GRD_SOCUSUA35.socusua35_internet
    from GRD_SOCUSUA35
    where GRD_SOCUSUA35.rela_socusua30 = :rela_socusua30
    and GRD_SOCUSUA35.socsyst10_codigo = 'CORREO'
    INTO :correo;

    if (socusua30_apellido_pat is not null) then
        suspend;
end^


CREATE OR ALTER PROCEDURE REP_INTAUTO01 (
    RELA_PYMVENT70_PARAM BIGINT)
RETURNS (
    ID_INTAUTO01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    RELA_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_SERVICIO_FECHA DATE,
    INTAUTO01_UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_PLACA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_HORAS_SERV INTEGER,
    INTAUTO01_KILO_SERV INTEGER,
    INTAUTO01_NROCHASIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_NROMOTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_TIPO_SERVICIOS INTEGER,
    INTAUTO01_SERVICIO_DESDE INTEGER,
    INTAUTO01_SERVICIO_HASTA INTEGER,
    INTAUTO01_LOCALIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_OBSER_CLIENTE VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_OBSER_MECANICO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MECANICO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_SERVICIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
     for SELECT
        intauto01_cab_servicios.id_intauto01,
        intauto01_cab_servicios.rela_socusua30,
        intauto01_cab_servicios.rela_pymvent70,
        intauto01_cab_servicios.intauto01_servicio_fecha,
        intauto01_cab_servicios.intauto01_unidad,
        intauto01_cab_servicios.intauto01_placa,
        intauto01_cab_servicios.intauto01_horas_serv,
        intauto01_cab_servicios.intauto01_kilo_serv,
        intauto01_cab_servicios.intauto01_nrochasis,
        intauto01_cab_servicios.intauto01_nromotor,
        intauto01_cab_servicios.intauto01_tipo_servicios,
        intauto01_cab_servicios.intauto01_servicio_desde,
        intauto01_cab_servicios.intauto01_servicio_hasta,
        intauto01_cab_servicios.intauto01_localizacion,
        intauto01_cab_servicios.intauto01_obser_cliente,
        intauto01_cab_servicios.intauto01_obser_mecanico
        FROM intauto01_cab_servicios
        WHERE   intauto01_cab_servicios.rela_pymvent70 = :rela_pymvent70_param      
    into :id_intauto01,
        :rela_socusua30,
        :rela_pymvent70,
        :intauto01_servicio_fecha,
        :intauto01_unidad,
        :intauto01_placa,
        :intauto01_horas_serv,
        :intauto01_kilo_serv,
        :intauto01_nrochasis,
        :intauto01_nromotor,
        :intauto01_tipo_servicios,
        :intauto01_servicio_desde,
        :intauto01_servicio_hasta,
        :intauto01_localizacion,
        :intauto01_obser_cliente,
        :intauto01_obser_mecanico
    do
    begin

        /* Se obtiene el nombre del mecánico */
        SELECT ENTIDAD FROM CBO_SOCUSUA30(:rela_socusua30)
        into :mecanico;

        /* Se obtiene el nombre del cliente */
        select /*$$IBEC$$ cbo_sicingr01.id_socusua30, $$IBEC$$*/
               cbo_sicingr01.entidad
        from cbo_sicingr01
        where cbo_sicingr01.rela_sicingr01 IN (Select  pymvent70_cab_ticket.rela_sicingr01
            from pymvent70_cab_ticket where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70)
        into /*$$IBEC$$ :id_socusua30, $$IBEC$$*/
             :cliente;

       /* Ahora se obtiene el nombre *//*$$IBEC$$ 
        SELECT ENTIDAD FROM CBO_SOCUSUA30(:id_socusua30)
        into :cliente; $$IBEC$$*/

        /* Se obtiene el folio del ticket */
        SELECT pymvent70_cab_ticket.pymvent70_docnro
        FROM pymvent70_cab_ticket
        WHERE pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
        into :pymvent70_docnro;

        /* Se determina el tipo de servicio */
        if (intauto01_tipo_servicios = 0) then
            tipo_servicio = 'Kilómetros';
        else
            tipo_servicio = 'Horas';

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_INTAUTO01_PYMVENT71 (
    RELA_PYMVENT70_PARAM BIGINT)
RETURNS (
    ID_PYMVENT71 BIGINT,
    RELA_PYMVENT70 BIGINT,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_NETO DOUBLE PRECISION,
    NUM INTEGER)
AS
begin
    num = 0;
    for select
        pymvent71_det_ticket.id_pymvent71,
        pymvent71_det_ticket.pymvent71_codigo,
        pymvent71_det_ticket.pymvent71_concepto,
        pymvent71_det_ticket.pymvent71_cantidad,
        pymvent71_det_ticket.pymvent71_importe_neto,
        pymvent71_det_ticket.rela_pymvent70
    from pymvent71_det_ticket
    where  rela_pymvent70 = :rela_pymvent70_param
    into id_pymvent71,
        :pymvent71_codigo,
        :pymvent71_concepto,
        :pymvent71_cantidad,
        :pymvent71_importe_neto,
        :rela_pymvent70
      do
      begin 
          num = num + 1;
          suspend;
      end
end^


CREATE OR ALTER PROCEDURE REP_INTAUTO01_RESUMEN (
    FECHA_INI DATE,
    FECHA_FIN DATE,
    SOCMAIN01 BIGINT)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT,
    ID_INTAUTO01 BIGINT,
    INTAUTO01_UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_PLACA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_NROCHASIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_SERVICIO_FECHA DATE,
    INTAUTO01_FAPL TIMESTAMP,
    MECANICO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_NETO DOUBLE PRECISION,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DEUDA DOUBLE PRECISION,
    INTAUTO01_HORAS_SERV INTEGER,
    INTAUTO01_KILO_SERV INTEGER,
    SUM_REFACCIONES DOUBLE PRECISION,
    SUM_SERVICIOS DOUBLE PRECISION,
    SUM_OTROS DOUBLE PRECISION)
AS
declare variable STR varchar(3000);
declare variable TOTAL_ENTRADAS double precision;
declare variable STR1 varchar(1500);
declare variable STR2 varchar(1500);
begin
    str1 =   'select
            intauto01_cab_servicios.rela_pymvent70,
            intauto01_cab_servicios.rela_socusua30,
             pymvent70_cab_ticket.rela_socmain01,
             pymvent70_cab_ticket.rela_sicingr01,
            intauto01_cab_servicios.id_intauto01,
            intauto01_cab_servicios.intauto01_unidad,
            intauto01_cab_servicios.intauto01_placa,
            intauto01_cab_servicios.intauto01_nrochasis,
            intauto01_cab_servicios.intauto01_servicio_fecha,
            intauto01_cab_servicios.intauto01_horas_serv,
            intauto01_cab_servicios.intauto01_kilo_serv,
            intauto01_cab_servicios.intauto01_fapl
        from intauto01_cab_servicios
        inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = intauto01_cab_servicios.rela_pymvent70)
        inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where pymvent70_cab_ticket.rela_socmain01  =  ' || :socmain01 ||
        ' and not exists (select pymvent60_cab_cobro.id_pymvent60 from pymvent60_cab_cobro where pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51 )';

    str2 = 'select
            intauto01_cab_servicios.rela_pymvent70,
            intauto01_cab_servicios.rela_socusua30,
             pymvent70_cab_ticket.rela_socmain01,
             pymvent70_cab_ticket.rela_sicingr01,
            intauto01_cab_servicios.id_intauto01,
            intauto01_cab_servicios.intauto01_unidad,
            intauto01_cab_servicios.intauto01_placa,
            intauto01_cab_servicios.intauto01_nrochasis,
            intauto01_cab_servicios.intauto01_servicio_fecha,
            intauto01_cab_servicios.intauto01_horas_serv,
            intauto01_cab_servicios.intauto01_kilo_serv,
            intauto01_cab_servicios.intauto01_fapl
        from intauto01_cab_servicios
        inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = intauto01_cab_servicios.rela_pymvent70)
        inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        inner join pymvent60_cab_cobro on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
        inner join pymvent61_det_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
        where pymvent70_cab_ticket.rela_socmain01  = ' || :socmain01 ||' and pymvent61_det_cobro.rela_socsyst10_fdp01 <> 54661';

    if ((:fecha_ini is not null) and (:fecha_fin is not null)) then
    begin
        str1 = :str1 || ' and cast(intauto01_fapl as date) between ''' || :FECHA_INI ||
        ''' and ''' || :FECHA_FIN || '''';

        str2 = :str2 || ' and cast(intauto01_fapl as date) between ''' || :FECHA_INI ||
        ''' and ''' || :FECHA_FIN || '''';
    end

    str = 'Select * from (' || :str1 || ' union ' || :str2 || ') order by rela_sicingr01, rela_pymvent70';

  for execute statement :str
        into :rela_pymvent70,
             :rela_socusua30,
             :rela_socmain01,
             :rela_sicingr01,
             :id_intauto01,
             :intauto01_unidad,
             :intauto01_placa,
             :intauto01_nrochasis,
             :intauto01_servicio_fecha,
             :intauto01_horas_serv,
             :intauto01_kilo_serv,
             :intauto01_fapl
   do begin
      /* Por cada hoja de servicio */

      /* Inicializamos las variables */
      Deuda = null;
      Total_entradas = null;


       /* Monto por pagar del ticket (caso pago 99) */
        /* Primero se obtiene la deuda original del ticket */
        select pymvent70_cab_ticket.pymvent70_neto
        from pymvent70_cab_ticket
        where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
        into :Deuda;

        select
        REP_INTAUTO01_RESUMEN_SUM.sum_refacciones,
        REP_INTAUTO01_RESUMEN_SUM.sum_servicios
        from REP_INTAUTO01_RESUMEN_SUM(:rela_pymvent70)
        into :sum_refacciones,
             :sum_servicios;

        sum_otros = Deuda - (sum_refacciones + sum_servicios);

        /* Ahora se obtiene el total de pagos realizados a dicho ticket */
        select pymvent60_cab_cobro.pymvent60_tot_pago
            from pymvent60_cab_cobro
            inner join pymvent51_det_ventas on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
            where pymvent51_det_ventas.rela_pymvent70 =  :rela_pymvent70
            into :Total_entradas;

        Total_entradas = iif(Total_entradas is null, 0.00, Total_entradas);

        /* Finalmente se deduce los pagos a la deuda */
        Deuda = Deuda - Total_entradas;

        if (((:fecha_ini is null) and (:fecha_fin is null) and (Deuda > 0))
            or ((:fecha_ini is not null) and (:fecha_fin is not null)))  then
        begin
             /* inicializacion de las variables */
               mecanico = null;
              -- id_socusua30 = null;
               cliente = null;
               pymvent70_docnro = null;
               pymvent70_neto = null;
               sicingr70_docnro = null;

             /* Se obtine el nombre del mecánico */
                SELECT ENTIDAD FROM CBO_SOCUSUA30(:rela_socusua30)
                into :mecanico;
        
                /* Se obtiene el nombre del cliente */
                select cbo_sicingr01.entidad
                from cbo_sicingr01
                where cbo_sicingr01.rela_sicingr01 = :rela_sicingr01 /*$$IBEC$$ IN (Select  pymvent70_cab_ticket.rela_sicingr01
                    from pymvent70_cab_ticket where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70) $$IBEC$$*/
                into :cliente;
        
                /* Ahora se obtiene el nombre *//*$$IBEC$$ 
                SELECT ENTIDAD FROM CBO_SOCUSUA30(:id_socusua30)
                into :cliente; $$IBEC$$*/
        
                /* Recopilacion de datos del ticket por cada servicio */
                /* Se obtiene el folio del ticket */
                SELECT pymvent70_cab_ticket.pymvent70_docnro,
                       pymvent70_cab_ticket.pymvent70_neto
                FROM pymvent70_cab_ticket
                WHERE pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
                into :pymvent70_docnro,
                     :pymvent70_neto;

                select sicingr70_cab_facturacion.sicingr70_docnro
                    from sicingr70_cab_facturacion
                       inner join pymvent62_dep_facturacion on (pymvent62_dep_facturacion.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
                    where pymvent62_dep_facturacion.rela_pymvent70 = :rela_pymvent70
                       and sicingr70_cab_facturacion.rela_socmain01 = :socmain01
                into  :sicingr70_docnro;
        
             suspend;
         end
   end
end^


CREATE OR ALTER PROCEDURE REP_INTAUTO01_RESUMEN_99 (
    FECHA_INI DATE,
    FECHA_FIN DATE,
    SOCMAIN01 BIGINT)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT,
    ID_INTAUTO01 BIGINT,
    INTAUTO01_UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_PLACA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_NROCHASIS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTAUTO01_SERVICIO_FECHA DATE,
    INTAUTO01_FAPL TIMESTAMP,
    MECANICO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_NETO DOUBLE PRECISION,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DEUDA DOUBLE PRECISION,
    INTAUTO01_HORAS_SERV INTEGER,
    INTAUTO01_KILO_SERV INTEGER,
    SUM_REFACCIONES DOUBLE PRECISION,
    SUM_SERVICIOS DOUBLE PRECISION,
    SUM_OTROS DOUBLE PRECISION)
AS
declare variable STR varchar(3000);
declare variable TOTAL_ENTRADAS double precision;
begin
   str = 'select
            intauto01_cab_servicios.rela_pymvent70,
            intauto01_cab_servicios.rela_socusua30,
             pymvent70_cab_ticket.rela_socmain01,
             pymvent70_cab_ticket.rela_sicingr01,
            intauto01_cab_servicios.id_intauto01,
            intauto01_cab_servicios.intauto01_unidad,
            intauto01_cab_servicios.intauto01_placa,
            intauto01_cab_servicios.intauto01_nrochasis,
            intauto01_cab_servicios.intauto01_servicio_fecha,
            intauto01_cab_servicios.intauto01_horas_serv,
            intauto01_cab_servicios.intauto01_kilo_serv,
            intauto01_cab_servicios.intauto01_fapl
        from intauto01_cab_servicios
        inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = intauto01_cab_servicios.rela_pymvent70)
        inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        inner join pymvent60_cab_cobro on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
        inner join pymvent61_det_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
        where pymvent70_cab_ticket.rela_socmain01  = ' || :socmain01 ||' and pymvent61_det_cobro.rela_socsyst10_fdp01 = 54661';

   if ((:fecha_ini is not null) and (:fecha_fin is not null)) then
        str = :str || ' and cast(intauto01_fapl as date) between ''' || :FECHA_INI ||
        ''' and ''' || :FECHA_FIN || '''
        order by rela_sicingr01, rela_pymvent70';
    else
        str = :str || 'order by rela_sicingr01, rela_pymvent70';

  for execute statement :str
        into :rela_pymvent70,
             :rela_socusua30,
             :rela_socmain01,
             :rela_sicingr01,
             :id_intauto01,
             :intauto01_unidad,
             :intauto01_placa,
             :intauto01_nrochasis,
             :intauto01_servicio_fecha,
             :intauto01_horas_serv,
             :intauto01_kilo_serv,
             :intauto01_fapl
   do begin
      /* Por cada hoja de servicio */

      /* Inicializamos las variables */
      Deuda = null;
      Total_entradas = null;


       /* Monto por pagar del ticket (caso pago 99) */
        /* Primero se obtiene la deuda original del ticket */
        select pymvent70_cab_ticket.pymvent70_neto
        from pymvent70_cab_ticket
        where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
        into :Deuda;

        select
        REP_INTAUTO01_RESUMEN_SUM.sum_refacciones,
        REP_INTAUTO01_RESUMEN_SUM.sum_servicios
        from REP_INTAUTO01_RESUMEN_SUM(:rela_pymvent70)
        into :sum_refacciones,
             :sum_servicios;

        sum_otros = Deuda - (sum_refacciones + sum_servicios);

        /* Ahora se obtiene el total de pagos realizados a dicho ticket */
        select sum(pymvent55_mov_moventsal.pymvent55_importe)
        from pymvent55_mov_moventsal
        where pymvent55_mov_moventsal.rela_pymvent70 = :rela_pymvent70
        and pymvent55_mov_moventsal.pymvent55_importe > 0
        and pymvent55_mov_moventsal.pymvent55_pagoticket = 3

        into :Total_entradas;

        Total_entradas = iif(Total_entradas is null, 0.00, Total_entradas);

        /* Finalmente se deduce los pagos a la deuda */
        Deuda = Deuda - Total_entradas;

        if ((:fecha_ini is null and :fecha_fin is null and Deuda > 0) or
            (:fecha_ini is not null and :fecha_fin is not null))  then
        begin
             /* inicializacion de las variables */
               mecanico = null;
               cliente = null;
               pymvent70_docnro = null;
               pymvent70_neto = null;
               sicingr70_docnro = null;

             /* Se obtine el nombre del mecánico */
                SELECT ENTIDAD FROM CBO_SOCUSUA30(:rela_socusua30)
                into :mecanico;
        
                /* Se obtiene el nombre del cliente */
                select cbo_sicingr01.entidad
                from cbo_sicingr01
                where cbo_sicingr01.rela_sicingr01 = :rela_sicingr01 /*$$IBEC$$ IN (Select  pymvent70_cab_ticket.rela_sicingr01
                    from pymvent70_cab_ticket where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70) $$IBEC$$*/
                into :cliente;
        
                /* Ahora se obtiene el nombre *//*$$IBEC$$ 
                SELECT ENTIDAD FROM CBO_SOCUSUA30(:id_socusua30)
                into :cliente; $$IBEC$$*/
        
                /* Recopilacion de datos del ticket por cada servicio */
                /* Se obtiene el folio del ticket */
                SELECT pymvent70_cab_ticket.pymvent70_docnro,
                       pymvent70_cab_ticket.pymvent70_neto
                FROM pymvent70_cab_ticket
                WHERE pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70
                into :pymvent70_docnro,
                     :pymvent70_neto;

                select sicingr70_cab_facturacion.sicingr70_docnro
                    from sicingr70_cab_facturacion
                       inner join pymvent62_dep_facturacion on (pymvent62_dep_facturacion.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
                    where pymvent62_dep_facturacion.rela_pymvent70 = :rela_pymvent70
                       and sicingr70_cab_facturacion.rela_socmain01 = :socmain01
                into  :sicingr70_docnro;
        
             suspend;
         end
   end
end^


CREATE OR ALTER PROCEDURE REP_INTAUTO01_RESUMEN_DET (
    RELA_PYMVENT70 BIGINT)
RETURNS (
    COLOR INTEGER,
    ID_PYMVENT71 BIGINT,
    PYMVENT71_ORDEN INTEGER,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_TOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_IMPUESTOS DOUBLE PRECISION,
    PYMVENT71_IMPORTE_NETO DOUBLE PRECISION)
AS
declare variable ID_SICINGR97 bigint;
declare variable RELA_SICINGR95 integer;
begin
    FOR SELECT
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_orden,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_subtotal,
    pymvent71_det_ticket.pymvent71_importe_descuento,
    pymvent71_det_ticket.pymvent71_importe_total,
    pymvent71_det_ticket.pymvent71_importe_impuestos,
    pymvent71_det_ticket.pymvent71_importe_neto
    FROM pymvent71_det_ticket
    INNER JOIN sicingr95_cab_conceptos ON (sicingr95_cab_conceptos.id_sicingr95 = pymvent71_det_ticket.rela_sicingr95)
    WHERE pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
    and pymvent71_det_ticket.pymvent71_cancelado = 0
    order by pymvent71_det_ticket.pymvent71_orden
    into :rela_sicingr95,
         :id_pymvent71,
         :pymvent71_orden,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_cantidad,
         :pymvent71_importe_unidad,
         :pymvent71_importe_subtotal,
         :pymvent71_importe_descuento,
         :pymvent71_importe_total,
         :pymvent71_importe_impuestos,
         :pymvent71_importe_neto
    do
    begin
        color = 0;
        id_sicingr97 = null;

        select first 1 sicingr97_det_clasificacion.id_sicingr97
        from sicingr97_det_clasificacion
        inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
        where sicingr97_det_clasificacion.rela_sicingr95 = :rela_sicingr95
        and UPPER(socsyst12_det_cla.socsyst12_descripcion) like '%SERVICIO%'
        into :id_sicingr97;

        if (id_sicingr97 is not null) then
           color = 1;
        else
        begin
           select first 1 sicingr97_det_clasificacion.id_sicingr97
           from sicingr97_det_clasificacion
           inner join socsyst12_det_cla on (socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12)
           where sicingr97_det_clasificacion.rela_sicingr95 = :rela_sicingr95
           and UPPER(socsyst12_det_cla.socsyst12_descripcion) like '%REFACCION%'
           into :id_sicingr97;

           if (id_sicingr97 is not null) then
              color = 2;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_INTAUTO01_RESUMEN_SUM (
    ID_PYMVENT70 BIGINT)
RETURNS (
    SUM_REFACCIONES DOUBLE PRECISION,
    SUM_SERVICIOS DOUBLE PRECISION)
AS
begin
    select sum(pymvent71_det_ticket.pymvent71_importe_neto)
    from pymvent71_det_ticket
    where pymvent71_det_ticket.rela_pymvent70 = :id_pymvent70
    and exists ( select first 1 sicingr97_det_clasificacion.id_sicingr97
                 from sicingr97_det_clasificacion
                 inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
                 where sicingr97_det_clasificacion.rela_sicingr95 = pymvent71_det_ticket.rela_sicingr95
                 and UPPER(socsyst12_det_cla.socsyst12_descripcion) like '%REFACCION%'
                )
    into :sum_refacciones;

    select sum(pymvent71_det_ticket.pymvent71_importe_neto)
    from pymvent71_det_ticket
    where pymvent71_det_ticket.rela_pymvent70 = :id_pymvent70
    and exists ( select first 1 sicingr97_det_clasificacion.id_sicingr97
                 from sicingr97_det_clasificacion
                 inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
                 where sicingr97_det_clasificacion.rela_sicingr95 = pymvent71_det_ticket.rela_sicingr95
                 and UPPER(socsyst12_det_cla.socsyst12_descripcion) like '%SERVICIO%'
                 /* and (socsyst10_det_entradas.socsyst10_codigo = 'CATEGORIA' and socsyst12_det_cla.socsyst12_codigo = 'SERVICIOS') */
                 /*or (socsyst10_det_entradas.socsyst10_codigo = 'SERVICIO') */
                )
    into :sum_servicios;

    sum_refacciones = iif(sum_refacciones is null, 0.00, sum_refacciones);
    sum_servicios = iif(sum_servicios is null, 0.00, sum_servicios);

    suspend;
end^


