CREATE OR ALTER PROCEDURE REP_PYMALMA02 (
    P_ID_PYMALMA10 BIGINT,
    P_SOCMAIN01 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOEXTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOINTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_LOCALIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_MUNICIPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_PAIS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REG_FISCAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN21 BIGINT,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_PYMALMA01 BIGINT,
    RELA_PYMALMA01_TRANSF BIGINT,
    RELA_SICINGR95 BIGINT,
    RELA_SOCSYST10_STK01 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    ID_PYMALMA02 BIGINT,
    PYMALMA02_CANTIDAD DOUBLE PRECISION,
    PYMALMA02_FAPL TIMESTAMP,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_MODELO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_TALLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_COLOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_VENCIMIENTO TIMESTAMP,
    PYMALMA20_SERIE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_SERIE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STOCK DOUBLE PRECISION,
    DETALLE VARCHAR(4000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_TRANSF_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin

    /* Se obtiene los datos de la Empresa*/
   select CFDI_EMPRESA.RAZSOCIAL,
    CFDI_EMPRESA.rfc,
    CFDI_EMPRESA.domf_calle,
    CFDI_EMPRESA.domf_noexterior,
    CFDI_EMPRESA.domf_nointerior,
    CFDI_EMPRESA.domf_colonia,
    CFDI_EMPRESA.domf_localidad,
    CFDI_EMPRESA.domf_municipio,
    CFDI_EMPRESA.domf_estado,
    CFDI_EMPRESA.domf_pais,
    CFDI_EMPRESA.domf_codpostal
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC,
        :rfc,
        :domf_calle,
        :domf_noexterior,
        :domf_nointerior,
        :domf_colonia,
        :domf_localidad,
        :domf_municipio,
        :domf_estado,
        :domf_pais,
        :domf_codpostal;

   /* Se obtiene el regimen fiscal de la empresa */
    SELECT SOCSYST10_DESCRIPCION
     FROM SOCSYST10_DET_ENTRADAS
     inner join SOCMAIN01_CAB_EMPRESAS on (SOCMAIN01_CAB_EMPRESAS.RELA_SOCSYST10_SAT01 = SOCSYST10_DET_ENTRADAS.id_socsyst10)
     where SOCMAIN01_CAB_EMPRESAS.id_socmain01 = :p_socmain01
     into :reg_fiscal;

    --Se obtiene el id de sucursal y del usuario
     select pymalma10_cab_recepcion.rela_socmain21,
            pymalma10_cab_recepcion.rela_socusua01
     from pymalma10_cab_recepcion
     where pymalma10_cab_recepcion.id_pymalma10 = :p_id_pymalma10
     into :rela_socmain21,
          :rela_socusua01;

   /* Se obtiene la descripcion de la Sucursal/Organizacion */
      select socmain21_arb_organizacion.socmain21_descripcion
        from socmain21_arb_organizacion
        where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
        into :socmain21_descripcion;

     --Nombre del usuario que realizó la provision
     select cbo_socusua01.entidad from cbo_socusua01(:p_socmain01, :rela_socmain21, :rela_socusua01)
     into :usuario;



     for select pymalma11_det_productos.rela_pymalma02
        from pymalma11_det_productos
        where pymalma11_det_productos.rela_pymalma10 = :p_id_pymalma10
     into :id_pymalma02
     do begin

        /* Se obtienen los datos de los productos recibidos */
        select
            pymalma02_det_stock.rela_pymalma01,
            pymalma02_det_stock.rela_pymalma01_transf,
            pymalma02_det_stock.rela_sicingr95,
            pymalma02_det_stock.rela_socsyst10_stk01,
            pymalma02_det_stock.pymalma02_cantidad,
            pymalma02_det_stock.pymalma02_fapl,
            sicingr95_cab_conceptos.sicingr95_codigo,
            sicingr95_cab_conceptos.sicingr95_descripcion,
            socsyst10_det_entradas.socsyst10_descripcion,
            pymalma20_dep_mtclvs.pymalma20_modelo,
            pymalma20_dep_mtclvs.pymalma20_talla,
            pymalma20_dep_mtclvs.pymalma20_color,
            pymalma20_dep_mtclvs.pymalma20_lote_desde,
            pymalma20_dep_mtclvs.pymalma20_lote_hasta,
            pymalma20_dep_mtclvs.pymalma20_vencimiento,
            pymalma20_dep_mtclvs.pymalma20_serie_desde,
            pymalma20_dep_mtclvs.pymalma20_serie_hasta
        from sicingr95_cab_conceptos
           inner join pymalma02_det_stock on (sicingr95_cab_conceptos.id_sicingr95 = pymalma02_det_stock.rela_sicingr95)
           inner join pymalma01_cab_stock on (pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01)
           inner join socsyst10_det_entradas on (pymalma02_det_stock.rela_socsyst10_stk01 = socsyst10_det_entradas.id_socsyst10)
           left outer join pymalma20_dep_mtclvs on (pymalma02_det_stock.id_pymalma02 = pymalma20_dep_mtclvs.rela_pymalma02)
        where pymalma02_det_stock.id_pymalma02 = :id_pymalma02
        into
            :rela_pymalma01,
            :rela_pymalma01_transf,
            :rela_sicingr95,
            :rela_socsyst10_stk01,
            :pymalma02_cantidad,
            :pymalma02_fapl,
            :sicingr95_codigo,
            :sicingr95_descripcion,
            :socsyst10_descripcion,
            :pymalma20_modelo,
            :pymalma20_talla,
            :pymalma20_color,
            :pymalma20_lote_desde,
            :pymalma20_lote_hasta,
            :pymalma20_vencimiento,
            :pymalma20_serie_desde,
            :pymalma20_serie_hasta;

            select sum(pymalma02_det_stock.pymalma02_cantidad)
                from pymalma02_det_stock
                inner join pymalma01_cab_stock on (pymalma01_cab_stock.id_pymalma01 = pymalma02_det_stock.rela_pymalma01)
                where pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
                and pymalma02_det_stock.rela_sicingr95 = :rela_sicingr95
                into :stock;

            detalle = iif(pymalma20_modelo is null, '', 'Modelo: '|| pymalma20_modelo || ', ') ||
                      iif(pymalma20_talla is null, '', 'Talla: '|| pymalma20_talla|| ', ') ||
                      iif(pymalma20_color is null, '', 'Color: '|| pymalma20_color|| ', ') ||
                      iif(pymalma20_lote_desde is null, '', 'Lote Des.: '|| pymalma20_lote_desde|| ', ') ||
                      iif(pymalma20_lote_hasta is null, '', 'Lote Has.: '|| pymalma20_lote_hasta|| ', ') ||
                      iif(pymalma20_vencimiento is null, '', 'Fec. Ven.: '||
                                        SUBSTRING(100 + EXTRACT(DAY FROM pymalma20_vencimiento) FROM 2 FOR 2) || '/' ||
                                        SUBSTRING(100 + EXTRACT(MONTH FROM pymalma20_vencimiento) FROM 2 FOR 2) || '/' ||
                                        EXTRACT(YEAR FROM pymalma20_vencimiento)   || ', ') ||
                     -- cast(cast(pymalma20_vencimiento as date) as varchar(10))|| ', ') ||
                      iif(pymalma20_serie_desde is null, '', 'Serie Des.: '|| pymalma20_serie_desde|| ', ') ||
                      iif(pymalma20_serie_hasta is null, '', 'Serie Has.: '|| pymalma20_serie_hasta);

            /*$$IBEC$$ if (rela_pymalma01_transf is not null) then
            begin
                select 
                    socmain21_arb_organizacion.socmain21_descripcion
                from socmain21_arb_organizacion
                   inner join pymalma01_cab_stock on (pymalma01_cab_stock.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
                where  pymalma01_cab_stock.id_pymalma01 = :rela_pymalma01_transf
                into :socmain21_transf_descripcion;
            end
            else
                socmain21_transf_descripcion = ''; $$IBEC$$*/

         SUSPEND;
     end
end^


CREATE OR ALTER PROCEDURE REP_PYMALMA02_TRANSFERENCIA (
    P_ID_PYMALMA15 BIGINT,
    P_SOCMAIN01 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOEXTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOINTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_LOCALIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_MUNICIPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_PAIS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REG_FISCAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN21 BIGINT,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_PYMALMA01 BIGINT,
    RELA_PYMALMA01_TRANSF BIGINT,
    RELA_SICINGR95 BIGINT,
    RELA_SOCSYST10_STK01 BIGINT,
    RELA_SOCUSUA01 BIGINT,
    ID_PYMALMA02 BIGINT,
    PYMALMA02_CANTIDAD DOUBLE PRECISION,
    PYMALMA02_FAPL TIMESTAMP,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_MODELO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_TALLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_COLOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_LOTE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_VENCIMIENTO TIMESTAMP,
    PYMALMA20_SERIE_DESDE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMALMA20_SERIE_HASTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STOCK DOUBLE PRECISION,
    DETALLE VARCHAR(4000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_TRANSF_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin

    /* Se obtiene los datos de la Empresa*/
   select CFDI_EMPRESA.RAZSOCIAL,
    CFDI_EMPRESA.rfc,
    CFDI_EMPRESA.domf_calle,
    CFDI_EMPRESA.domf_noexterior,
    CFDI_EMPRESA.domf_nointerior,
    CFDI_EMPRESA.domf_colonia,
    CFDI_EMPRESA.domf_localidad,
    CFDI_EMPRESA.domf_municipio,
    CFDI_EMPRESA.domf_estado,
    CFDI_EMPRESA.domf_pais,
    CFDI_EMPRESA.domf_codpostal
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC,
        :rfc,
        :domf_calle,
        :domf_noexterior,
        :domf_nointerior,
        :domf_colonia,
        :domf_localidad,
        :domf_municipio,
        :domf_estado,
        :domf_pais,
        :domf_codpostal;

   /* Se obtiene el regimen fiscal de la empresa */
    SELECT SOCSYST10_DESCRIPCION
     FROM SOCSYST10_DET_ENTRADAS
     inner join SOCMAIN01_CAB_EMPRESAS on (SOCMAIN01_CAB_EMPRESAS.RELA_SOCSYST10_SAT01 = SOCSYST10_DET_ENTRADAS.id_socsyst10)
     where SOCMAIN01_CAB_EMPRESAS.id_socmain01 = :p_socmain01
     into :reg_fiscal;

    --Se obtiene el id de sucursal y del usuario
     select PYMALMA15_CAB_TRANSFERENCIA.rela_socmain21,
            PYMALMA15_CAB_TRANSFERENCIA.rela_socusua01
     from PYMALMA15_CAB_TRANSFERENCIA
     where PYMALMA15_CAB_TRANSFERENCIA.id_pymalma15 = :p_id_pymalma15
     into :rela_socmain21,
          :rela_socusua01;

   /* Se obtiene la descripcion de la Sucursal/Organizacion */
      select socmain21_arb_organizacion.socmain21_descripcion
        from socmain21_arb_organizacion
        where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
        into :socmain21_descripcion;

     --Nombre del usuario que realizó la provision
     select cbo_socusua01.entidad from cbo_socusua01(:p_socmain01, :rela_socmain21, :rela_socusua01)
     into :usuario;

     for select PYMALMA16_DET_TRANSFERENCIA.rela_pymalma02
        from PYMALMA16_DET_TRANSFERENCIA
        where PYMALMA16_DET_TRANSFERENCIA.rela_pymalma15 = :p_id_pymalma15
     into :id_pymalma02
     do begin

        /* Se obtienen los datos de los productos recibidos */
        select
            pymalma02_det_stock.rela_pymalma01,
            pymalma02_det_stock.rela_pymalma01_transf,
            pymalma02_det_stock.rela_sicingr95,
            pymalma02_det_stock.rela_socsyst10_stk01,
            pymalma02_det_stock.pymalma02_cantidad*(-1),
            pymalma02_det_stock.pymalma02_fapl,
            sicingr95_cab_conceptos.sicingr95_codigo,
            sicingr95_cab_conceptos.sicingr95_descripcion,
            socsyst10_det_entradas.socsyst10_descripcion,
            pymalma20_dep_mtclvs.pymalma20_modelo,
            pymalma20_dep_mtclvs.pymalma20_talla,
            pymalma20_dep_mtclvs.pymalma20_color,
            pymalma20_dep_mtclvs.pymalma20_lote_desde,
            pymalma20_dep_mtclvs.pymalma20_lote_hasta,
            pymalma20_dep_mtclvs.pymalma20_vencimiento,
            pymalma20_dep_mtclvs.pymalma20_serie_desde,
            pymalma20_dep_mtclvs.pymalma20_serie_hasta
        from sicingr95_cab_conceptos
           inner join pymalma02_det_stock on (sicingr95_cab_conceptos.id_sicingr95 = pymalma02_det_stock.rela_sicingr95)
           inner join pymalma01_cab_stock on (pymalma02_det_stock.rela_pymalma01 = pymalma01_cab_stock.id_pymalma01)
           inner join socsyst10_det_entradas on (pymalma02_det_stock.rela_socsyst10_stk01 = socsyst10_det_entradas.id_socsyst10)
           left outer join pymalma20_dep_mtclvs on (pymalma02_det_stock.id_pymalma02 = pymalma20_dep_mtclvs.rela_pymalma02)
        where pymalma02_det_stock.id_pymalma02 = :id_pymalma02
        into
            :rela_pymalma01,
            :rela_pymalma01_transf,
            :rela_sicingr95,
            :rela_socsyst10_stk01,
            :pymalma02_cantidad,
            :pymalma02_fapl,
            :sicingr95_codigo,
            :sicingr95_descripcion,
            :socsyst10_descripcion,
            :pymalma20_modelo,
            :pymalma20_talla,
            :pymalma20_color,
            :pymalma20_lote_desde,
            :pymalma20_lote_hasta,
            :pymalma20_vencimiento,
            :pymalma20_serie_desde,
            :pymalma20_serie_hasta;

            select sum(pymalma02_det_stock.pymalma02_cantidad)
                from pymalma02_det_stock
                inner join pymalma01_cab_stock on (pymalma01_cab_stock.id_pymalma01 = pymalma02_det_stock.rela_pymalma01)
                where pymalma01_cab_stock.rela_socmain21 = :rela_socmain21
                and pymalma02_det_stock.rela_sicingr95 = :rela_sicingr95
                into :stock;

            detalle = iif(pymalma20_modelo is null, '', 'Modelo: '|| pymalma20_modelo || ', ') ||
                      iif(pymalma20_talla is null, '', 'Talla: '|| pymalma20_talla|| ', ') ||
                      iif(pymalma20_color is null, '', 'Color: '|| pymalma20_color|| ', ') ||
                      iif(pymalma20_lote_desde is null, '', 'Lote Des.: '|| pymalma20_lote_desde|| ', ') ||
                      iif(pymalma20_lote_hasta is null, '', 'Lote Has.: '|| pymalma20_lote_hasta|| ', ') ||
                      iif(pymalma20_vencimiento is null, '', 'Fec. Ven.: '||
                                        SUBSTRING(100 + EXTRACT(DAY FROM pymalma20_vencimiento) FROM 2 FOR 2) || '/' ||
                                        SUBSTRING(100 + EXTRACT(MONTH FROM pymalma20_vencimiento) FROM 2 FOR 2) || '/' ||
                                        EXTRACT(YEAR FROM pymalma20_vencimiento)   || ', ') ||
                      iif(pymalma20_serie_desde is null, '', 'Serie Des.: '|| pymalma20_serie_desde|| ', ') ||
                      iif(pymalma20_serie_hasta is null, '', 'Serie Has.: '|| pymalma20_serie_hasta);

            if (rela_pymalma01_transf is not null) then
            begin
                select 
                    socmain21_arb_organizacion.socmain21_descripcion
                from socmain21_arb_organizacion
                   inner join pymalma01_cab_stock on (pymalma01_cab_stock.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
                where  pymalma01_cab_stock.id_pymalma01 = :rela_pymalma01_transf
                into :socmain21_transf_descripcion;
            end
            else
                socmain21_transf_descripcion = '';

         SUSPEND;
     end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT01 (
    FECHA_INI DATE,
    FECHA_FIN DATE,
    RELA_SOCMAIN21_PARAM BIGINT,
    P_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    ID_PYMVENT01 BIGINT,
    RELA_SOCSYST10_PVC01 BIGINT,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SUM_PYMVENT70_SUBTOTAL DOUBLE PRECISION,
    SUM_PYMVENT70_DESCUENTO DOUBLE PRECISION,
    TOTAL_IMPUESTOS DOUBLE PRECISION,
    SUM_PYMVENT70_NETO DOUBLE PRECISION,
    CANT_TICKETS INTEGER,
    TOTAL_ENTRADAS DOUBLE PRECISION,
    TOTAL_SALIDAS DOUBLE PRECISION)
AS
declare variable STR varchar(1000);
declare variable SUM_PYMVENT70_TOTIMP_RETENIDOS double precision;
declare variable SUM_PYMVENT70_TOTIMP_TRASLADOS double precision;
declare variable SUM_PYMVENT70_TOTIMP_LOCALES double precision;
declare variable SALIDAS_MON double precision;
declare variable ID_PYMVENT50 bigint;
declare variable SUM_PYMVENT70_SUBTOTAL2 double precision;
declare variable SUM_PYMVENT70_DESCUENTO2 double precision;
declare variable SUM_PYMVENT70_TOTIMP_RETENIDOS2 double precision;
declare variable SUM_PYMVENT70_TOTIMP_TRASLADOS2 double precision;
declare variable SUM_PYMVENT70_TOTIMP_LOCALES2 double precision;
declare variable SUM_PYMVENT70_NETO2 double precision;
declare variable CANT_TICKETS2 double precision;
begin
    if (rela_socmain21_param is null) then
      str = 'select ' ||
            'pymvent50_cab_apertura.rela_socmain21,
            pymvent50_cab_apertura.id_pymvent50,
            pymvent01_cab_cajas.rela_socmain01, ' ||
            'pymvent01_cab_cajas.id_pymvent01, ' ||
            'pymvent01_cab_cajas.rela_socsyst10_pvc01 ' ||
        'from pymvent01_cab_cajas ' ||
           'inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01) ' ||
        'where not (cast(pymvent50_fcierre as date) < ''' || :FECHA_INI || ''' ) and '||
         'not (cast(pymvent50_cab_apertura.pymvent50_fapertura as date) > ''' || :FECHA_FIN || ''' ) and
         pymvent50_cab_apertura.rela_socmain01 = ' || :p_socmain01 ||
         'group by pymvent50_cab_apertura.rela_socmain21, pymvent01_cab_cajas.rela_socmain01,
         pymvent01_cab_cajas.id_pymvent01, pymvent50_cab_apertura.id_pymvent50, pymvent01_cab_cajas.rela_socsyst10_pvc01 ';
    else
        str = 'select ' ||
            :rela_socmain21_param || ',
             pymvent50_cab_apertura.id_pymvent50,
            pymvent01_cab_cajas.rela_socmain01,
            pymvent01_cab_cajas.id_pymvent01,
            pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent01_cab_cajas
           inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where not (cast(pymvent50_fcierre as date) < ''' || :FECHA_INI || ''') and
         not (cast(pymvent50_cab_apertura.pymvent50_fapertura as date) > ''' || :FECHA_FIN || ''') and
         pymvent50_cab_apertura.rela_socmain01 = ' || :p_socmain01 ||
         'and pymvent50_cab_apertura.rela_socmain21 =' || :RELA_SOCMAIN21_PARAM  ||
         'group by pymvent01_cab_cajas.rela_socmain01, pymvent01_cab_cajas.id_pymvent01, pymvent50_cab_apertura.id_pymvent50, pymvent01_cab_cajas.rela_socsyst10_pvc01';

  for execute statement :str
    into :rela_socmain21,
         :id_pymvent50,
         :rela_socmain01,
         :id_pymvent01,
         :rela_socsyst10_pvc01
    do begin
        /* Por cada sucursal (rela_socmain21) y caja (id_pymvent01) */

        /* Incializamos las variables */
        socmain01_nomcomercial = null;
        socmain21_descripcion = null;
        socsyst10_descripcion = null;
        total_impuestos = null;
        sum_pymvent70_subtotal = null;
        sum_pymvent70_descuento = null;
        sum_pymvent70_totimp_retenidos = null;
        sum_pymvent70_totimp_traslados = null;
        sum_pymvent70_totimp_locales =  null;
        sum_pymvent70_neto = null;
        cant_tickets = null;
        Total_entradas = null;
        Total_salidas = null;

           /* Se obtiene el nombre de la organización */
        select CBO_SOCMAIN01.socmain01_nomcomercial
          from CBO_SOCMAIN01
          where CBO_SOCMAIN01.id_socmain01 = :rela_socmain01
          into :socmain01_nomcomercial;

          /* Obtenemos el nombre de la Sucursal */
          select socmain21_arb_organizacion.socmain21_descripcion
            from socmain21_arb_organizacion
            where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
            into :socmain21_descripcion;

            /* obtenemos la descripcion de la caja */
          select CBO_SOCSYST10_PVC01.socsyst10_descripcion
              from CBO_SOCSYST10_PVC01
              where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
              into :socsyst10_descripcion;

          /* Obtenemos los totales de los tickets que esten dentro del rango de fechas
          por ventas normales (no creditos o apartados)*/
          select 
                sum( pymvent70_cab_ticket.pymvent70_subtotal ) sum_of_pymvent70_subtotal,
                sum( pymvent70_cab_ticket.pymvent70_descuento ) sum_of_pymvent70_descuento,
                sum( pymvent70_cab_ticket.pymvent70_totimp_retenidos ) sum_of_pymvent70_totimp_retenidos,
                sum( pymvent70_cab_ticket.pymvent70_totimp_traslados ) sum_of_pymvent70_totimp_traslados,
                sum( pymvent70_cab_ticket.pymvent70_totimp_locales ) sum_of_pymvent70_totimp_locales,
                sum( pymvent70_cab_ticket.pymvent70_neto ) sum_of_pymvent70_neto,
                count( pymvent70_cab_ticket.id_pymvent70 ) count_of_id_pymvent70
            from pymvent70_cab_ticket
               inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
               inner join pymvent50_cab_apertura on (pymvent51_det_ventas.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
               inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
            where pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21
               and pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
               and cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
            into :sum_pymvent70_subtotal,
                 :sum_pymvent70_descuento,
                 :sum_pymvent70_totimp_retenidos,
                 :sum_pymvent70_totimp_traslados,
                 :sum_pymvent70_totimp_locales,
                 :sum_pymvent70_neto,
                 :cant_tickets;
          sum_pymvent70_subtotal = iif(sum_pymvent70_subtotal is null, 0.00, sum_pymvent70_subtotal);
          sum_pymvent70_descuento = iif(sum_pymvent70_descuento is null, 0.00, sum_pymvent70_descuento);
          sum_pymvent70_neto = iif(sum_pymvent70_neto is null, 0.00, sum_pymvent70_neto);
          cant_tickets = iif(cant_tickets is null, 0.00, cant_tickets);

          /* Obtenemos las sumas de aportes a abonos por creditos o apartados */
          select
                sum( pymvent70_cab_ticket.pymvent70_subtotal ) sum_of_pymvent70_subtotal,
                sum( pymvent70_cab_ticket.pymvent70_descuento ) sum_of_pymvent70_descuento,
                sum( pymvent70_cab_ticket.pymvent70_totimp_retenidos ) sum_of_pymvent70_totimp_retenidos,
                sum( pymvent70_cab_ticket.pymvent70_totimp_traslados ) sum_of_pymvent70_totimp_traslados,
                sum( pymvent70_cab_ticket.pymvent70_totimp_locales ) sum_of_pymvent70_totimp_locales,
                sum( pymvent70_cab_ticket.pymvent70_neto ) sum_of_pymvent70_neto,
                count( pymvent70_cab_ticket.id_pymvent70 ) count_of_id_pymvent70
            from pymvent70_cab_ticket
               inner join pymvent55_mov_moventsal on (pymvent70_cab_ticket.id_pymvent70 = pymvent55_mov_moventsal.rela_pymvent70)
               inner join pymvent50_cab_apertura on (pymvent55_mov_moventsal.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
               inner join pymvent56_det_cobro on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
            where pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21
               and pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
               and cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
            into :sum_pymvent70_subtotal2,
                 :sum_pymvent70_descuento2,
                 :sum_pymvent70_totimp_retenidos2,
                 :sum_pymvent70_totimp_traslados2,
                 :sum_pymvent70_totimp_locales2,
                 :sum_pymvent70_neto2,
                 :cant_tickets2;
          sum_pymvent70_subtotal2 = iif(sum_pymvent70_subtotal2 is null, 0.00, sum_pymvent70_subtotal2);
          sum_pymvent70_descuento2 = iif(sum_pymvent70_descuento2 is null, 0.00, sum_pymvent70_descuento2);
          sum_pymvent70_neto2 = iif(sum_pymvent70_neto2 is null, 0.00, sum_pymvent70_neto2);
          cant_tickets2 = iif(cant_tickets is null, 0.00, cant_tickets2);

          sum_pymvent70_subtotal = sum_pymvent70_subtotal + sum_pymvent70_subtotal2;
          sum_pymvent70_descuento = sum_pymvent70_descuento + sum_pymvent70_descuento2;
          sum_pymvent70_neto = sum_pymvent70_neto + sum_pymvent70_neto2;

          total_impuestos = sum_pymvent70_totimp_retenidos +
          sum_pymvent70_totimp_traslados + sum_pymvent70_totimp_locales +
          sum_pymvent70_totimp_retenidos2 +
          sum_pymvent70_totimp_traslados2 + sum_pymvent70_totimp_locales2;
          total_impuestos = iif(total_impuestos is null, 0.00, total_impuestos);



          /* Calculo de entradas de dinero */
         select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where pymvent55_mov_moventsal.pymvent55_importe > 0 and (pymvent55_mov_moventsal.pymvent55_pagoticket = 0 or
            pymvent55_mov_moventsal.pymvent55_pagoticket = 3 or ( pymvent55_mov_moventsal.pymvent55_pagoticket = 5) )
            and pymvent50_cab_apertura.rela_pymvent01 = :id_pymvent01 and
            pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21 and
                cast(pymvent55_mov_moventsal.pymvent55_fapl as date) between :fecha_ini and :fecha_fin
            into :Total_entradas;

          Total_entradas = iif(Total_entradas is null, 0.00, Total_entradas);

          /* Calculo de salidas de dinero
          Se consideran salidas de dinero los prestamos a personal y las devoluciones
          de dinero a clientes por Monedero Electónico*/
          /* Como los montos de monedero electronico son positivos, se obtienen
          primero los mismos por separado */
         select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe > 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and
            pymvent55_mov_moventsal.rela_pymvent70 is null) and
                pymvent50_cab_apertura.rela_pymvent01 = :id_pymvent01 and pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21 and
                cast(pymvent55_mov_moventsal.pymvent55_fapl as date) between :fecha_ini and :fecha_fin
         into :Salidas_mon;

            /* Se cambia a negativo para sumarlo con le siguiente monto */
         Salidas_mon = iif(Salidas_mon is null, 0.00, (-1)*Salidas_mon);

         /* Se obtienen los montos de prestamos a personal, los cuales son negativos */
         select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe < 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 0) and
                pymvent50_cab_apertura.rela_pymvent01 = :id_pymvent01 and pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21 and
                cast(pymvent55_mov_moventsal.pymvent55_fapl as date) between :fecha_ini and :fecha_fin
            into :Total_salidas;

            Total_salidas = iif(Total_salidas is null, 0.00, Total_salidas);

            /* Fnalmente, se suman mabos montos */
            Total_salidas =  Total_salidas + Salidas_mon;

          suspend;
    end 

end^


CREATE OR ALTER PROCEDURE REP_PYMVENT01_DET (
    FECHA_INI DATE,
    FECHA_FIN DATE,
    P_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21_PARAM BIGINT,
    P_ID_PYMVENT01 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT50 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_PYMVENT01 BIGINT,
    RELA_SOCSYST10_PVC01 BIGINT,
    ID_PYMVENT70 BIGINT,
    RELA_SICINGR01 BIGINT,
    CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    FORMADEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_SUBTOTAL DOUBLE PRECISION,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION,
    TOTAL_IMPUESTOS DOUBLE PRECISION)
AS
declare variable STR varchar(1000);
declare variable PYMVENT70_TOTIMP_RETENIDOS double precision;
declare variable PYMVENT70_TOTIMP_TRASLADOS double precision;
declare variable PYMVENT70_TOTIMP_LOCALES double precision;
declare variable MONTO double precision;
declare variable RELA_SOCSYST10_FDP01 bigint;
declare variable PAGOS double precision;
begin

    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    if (rela_socmain21_param is null and P_ID_PYMVENT01 is null) then
      str = 'select
            pymvent50_cab_apertura.id_pymvent50,
            pymvent50_cab_apertura.rela_socmain21,
            pymvent01_cab_cajas.id_pymvent01,
            pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent01_cab_cajas
           inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where not (cast(pymvent50_fcierre as date) < ''' || :FECHA_INI || ''' ) and
         not (cast(pymvent50_cab_apertura.pymvent50_fapertura as date) > ''' || :FECHA_FIN || ''' )';

    else if (rela_socmain21_param is not null and P_ID_PYMVENT01 is null) then

        str = 'select
            pymvent50_cab_apertura.id_pymvent50, ' ||
            :rela_socmain21_param || ',
            pymvent01_cab_cajas.id_pymvent01,
            pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent01_cab_cajas
           inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where not (cast(pymvent50_fcierre as date) < ''' || :FECHA_INI || ''') and
         not (cast(pymvent50_cab_apertura.pymvent50_fapertura as date) > ''' || :FECHA_FIN || ''') and
         pymvent50_cab_apertura.rela_socmain21 = ' || :RELA_SOCMAIN21_PARAM;

    else if (rela_socmain21_param is not null and P_ID_PYMVENT01 is not null) then

        str = 'select
            pymvent50_cab_apertura.id_pymvent50, ' ||
            :rela_socmain21_param || ', ' ||
            :P_ID_PYMVENT01 || ', '||
           ' pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent01_cab_cajas
           inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where not (cast(pymvent50_fcierre as date) < ''' || :FECHA_INI || ''') and
         not (cast(pymvent50_cab_apertura.pymvent50_fapertura as date) > ''' || :FECHA_FIN || ''') and
         pymvent50_cab_apertura.rela_socmain21 = ' || :RELA_SOCMAIN21_PARAM || ' and
         pymvent50_cab_apertura.rela_pymvent01 = '|| :p_id_pymvent01;

  for execute statement :str
    into :id_pymvent50,
         :rela_socmain21,
         :rela_pymvent01,
         :rela_socsyst10_pvc01
    do begin
          /* Inicializamos las variables */
          socmain21_descripcion = null;
          socsyst10_descripcion = null;

           /* Obtenemos el nombre de la Sucursal */
          select socmain21_arb_organizacion.socmain21_descripcion
            from socmain21_arb_organizacion
            where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
            into :socmain21_descripcion;

            /* obtenemos la descripcion de la caja */
          select CBO_SOCSYST10_PVC01.socsyst10_descripcion
              from CBO_SOCSYST10_PVC01
              where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
              into :socsyst10_descripcion;

          /* Obtenemos los tickets que esten dentro del rango de fechas */
          for select
            pymvent70_cab_ticket.id_pymvent70,
            pymvent70_cab_ticket.rela_sicingr01,  --HV, el 15/04/2019
            pymvent70_cab_ticket.pymvent70_docnro,
            pymvent70_cab_ticket.pymvent70_fecha,
            pymvent70_cab_ticket.pymvent70_subtotal,
            pymvent70_cab_ticket.pymvent70_descuento,
            pymvent70_cab_ticket.pymvent70_totimp_retenidos,
            pymvent70_cab_ticket.pymvent70_totimp_traslados,
            pymvent70_cab_ticket.pymvent70_totimp_locales,
            pymvent70_cab_ticket.pymvent70_neto
           from pymvent70_cab_ticket
            inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
            inner join pymvent50_cab_apertura on (pymvent51_det_ventas.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
            inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
                where pymvent50_cab_apertura.rela_socmain21= :rela_socmain21 and pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
                and cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
          union
            select distinct
                pymvent70_cab_ticket.id_pymvent70,
                pymvent70_cab_ticket.rela_sicingr01,  --HV, el 15/04/2019
                pymvent70_cab_ticket.pymvent70_docnro,
                pymvent70_cab_ticket.pymvent70_fecha,
                pymvent70_cab_ticket.pymvent70_subtotal,
                pymvent70_cab_ticket.pymvent70_descuento,
                pymvent70_cab_ticket.pymvent70_totimp_retenidos,
                pymvent70_cab_ticket.pymvent70_totimp_traslados,
                pymvent70_cab_ticket.pymvent70_totimp_locales,
                pymvent70_cab_ticket.pymvent70_neto
            from pymvent70_cab_ticket
               inner join pymvent55_mov_moventsal on (pymvent70_cab_ticket.id_pymvent70 = pymvent55_mov_moventsal.rela_pymvent70)
               inner join pymvent50_cab_apertura on (pymvent55_mov_moventsal.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
               inner join pymvent56_det_cobro on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
                where pymvent50_cab_apertura.rela_socmain21= :rela_socmain21 and pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
                and cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
            into :id_pymvent70,
                 :rela_sicingr01,
                 :pymvent70_docnro,
                 :pymvent70_fecha,
                 :pymvent70_subtotal,
                 :pymvent70_descuento,
                 :pymvent70_totimp_retenidos,
                 :pymvent70_totimp_traslados,
                 :pymvent70_totimp_locales,
                 :pymvent70_neto
          do begin
                /* Se inicializan las variables */
                total_impuestos = null;
                monto = null;
                pagos = 0;
                saldo = 0;
                rela_socsyst10_fdp01 = null;
                FormaDePago = null;

                --Se busca el nombre del cliente
                --HV, el 15/04/2019
                select cbo_sicingr01_id.entidad
                    from cbo_sicingr01_id
                where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
                into :cliente;

                /* Se obtiene la suma de los impuestos */
                total_impuestos = pymvent70_totimp_retenidos +
                pymvent70_totimp_traslados + pymvent70_totimp_locales;
                total_impuestos = iif(total_impuestos is null, 0.00, total_impuestos);

                /*Se calculan los pagos recibidos en todas las modalidades, menos abonos de credito
                    Añadido por HV el 15/04/2019*/
                select sum(pymvent60_cab_cobro.pymvent60_tot_pago)
                from pymvent51_det_ventas
                   inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
                   inner join pymvent61_det_cobro on (pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
                   inner join socsyst10_det_remoto fdp on (fdp.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01)
                where   pymvent51_det_ventas.rela_pymvent70 = :id_pymvent70 and
                        fdp.socsyst10_codigo <> '99'
                into :pagos;

                if (pagos is not null) then  --Existen pagos en el punto de venta
                    saldo = pymvent70_neto - pagos;

                --Se calcula los abonos a credito
                select 
                   sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe) as pagos
                from PYMVENT55_MOV_MOVENTSAL
                where PYMVENT55_MOV_MOVENTSAL.rela_pymvent70 = :id_pymvent70
                into :pagos;  --En realidad obtengo el saldo, dado que ya se calcula los abonos junto con el monto inicial de la fatura

                pagos = iif(pagos is null, 0.00, pagos);

                saldo = saldo + pagos;   --se suma porque pagos es un saldo en realidad

                /* Se obtiene la forma del pago. Se selecciona aquella con el mayor monto que se pagó
                Se busca tanto en los pagos normales en la tabla 61, o en aportes de abonos o credito en
                la tabla 56*/
                select first 1
                    pymvent61_det_cobro.pymvent61_valor,
                    pymvent61_det_cobro.rela_socsyst10_fdp01
                from  pymvent61_det_cobro
                   inner join pymvent60_cab_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
                   inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
                   --inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70 )
                        WHERE pymvent51_det_ventas.rela_pymvent70 = :id_pymvent70
                group by pymvent61_det_cobro.pymvent61_valor, pymvent61_det_cobro.rela_socsyst10_fdp01
                order by pymvent61_det_cobro.pymvent61_valor Desc
                into :monto,
                     :rela_socsyst10_fdp01;

                if (:rela_socsyst10_fdp01 is null) then
                begin
                   select first 1
                        pymvent56_det_cobro.pymvent56_valor,
                        pymvent56_det_cobro.rela_socsyst10_fdp01
                    from pymvent56_det_cobro
                       inner join pymvent55_mov_moventsal on (pymvent56_det_cobro.rela_pymvent55 = pymvent55_mov_moventsal.id_pymvent55)
                       inner join pymvent50_cab_apertura on (pymvent55_mov_moventsal.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
                     WHERE pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70
                        group by pymvent56_det_cobro.pymvent56_valor,  pymvent56_det_cobro.rela_socsyst10_fdp01
                        order by pymvent56_det_cobro.pymvent56_valor Desc
                     into :monto,
                        :rela_socsyst10_fdp01;
                end

                monto = iif(monto is null, 0.00, monto);

                select CBO_SOCSYST10_FDP01.socsyst10_descripcion
                    from CBO_SOCSYST10_FDP01
                    where CBO_SOCSYST10_FDP01.id_socsyst10 = :rela_socsyst10_fdp01
                    into :FormaDePago;

                suspend;
          end
    end 

end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_APARTADOS (
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_PYMVENT70 INTEGER,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT51_DIASAPARTADO INTEGER,
    SALDO_APARTADO DOUBLE PRECISION)
AS
declare variable FECHA_VTO date;
declare variable RELA_PYMVENT01 bigint;
begin
    select pymvent50_cab_apertura.rela_pymvent01
    from pymvent50_cab_apertura
    where pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
    into :rela_pymvent01;

    for select
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_neto,
    pymvent51_det_ventas.pymvent51_diasapartado
    from pymvent51_det_ventas
    inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    inner join pymvent50_cab_apertura on (pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50)
    where pymvent50_cab_apertura.rela_pymvent01 = :rela_pymvent01
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent51_det_ventas.pymvent51_fcerrado is null
    and pymvent51_det_ventas.rela_socmain21_apartados is not null
    and pymvent51_det_ventas.pymvent51_diasapartado > 0
    into :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto,
         :pymvent51_diasapartado
    do
    begin
        fecha_vto = dateadd (pymvent51_diasapartado day to cast(pymvent70_fecha as date));

        select sum(pymvent55_mov_moventsal.pymvent55_importe)
        from pymvent55_mov_moventsal
        where pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70
        and pymvent55_mov_moventsal.pymvent55_pagoticket = 5
        into :saldo_apartado;

        if (saldo_apartado is null) then
            saldo_apartado = 0;
        else
            saldo_apartado = saldo_apartado * (-1);

        pymvent51_diasapartado = datediff (day from current_date to fecha_vto);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_COBROS (
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_SOCSYST10_FDP01 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTALES DOUBLE PRECISION)
AS
declare variable EFECTIVO double precision;
declare variable APERTURA double precision;
declare variable REDONDEO double precision;
declare variable ENTRO integer;
declare variable IMPORTE_DEVOLUCIONES double precision;
declare variable PRESTAMOS double precision;
declare variable MONEDERO double precision;
begin
    entro = 0;

    FOR SELECT
    pymvent61_det_cobro.rela_socsyst10_fdp01,
    socsyst10_det_remoto.socsyst10_codigo,
    socsyst10_det_remoto.socsyst10_descripcion,
    SUM(pymvent61_det_cobro.pymvent61_valor)
    FROM pymvent61_det_cobro
    INNER JOIN socsyst10_det_remoto ON ( socsyst10_det_remoto.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01 )
    inner join pymvent60_cab_cobro on ( pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60 )
    inner join pymvent51_det_ventas on ( pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51 )
    where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
    and pymvent51_det_ventas.pymvent51_fvencido is null
    GROUP by pymvent61_det_cobro.rela_socsyst10_fdp01,
             socsyst10_det_remoto.socsyst10_codigo,
             socsyst10_det_remoto.socsyst10_descripcion
    INTO :ID_SOCSYST10_FDP01,
         :socsyst10_codigo,
         :socsyst10_descripcion,
         :totales
    do
    begin
        entro = 1;

        if (socsyst10_codigo = '01') then
            efectivo = iif(totales is null, 0.00, totales);
        else if (socsyst10_codigo = '64') then
            redondeo = iif(totales is null, 0.00, totales);

        suspend;
    end

    efectivo = iif(efectivo is null, 0.00, efectivo);
    redondeo = iif(redondeo is null, 0.00, redondeo);

    /*if (entro = 1) then
    begin */
        select sum(pymvent73_mov_cancelados.pymvent73_importe)
        from pymvent73_mov_cancelados
        where pymvent73_mov_cancelados.rela_pymvent50 = :id_pymvent50
        into :importe_devoluciones;

        importe_devoluciones = iif(importe_devoluciones is null, 0.00, importe_devoluciones);
        totales = importe_devoluciones;

        ID_SOCSYST10_FDP01 = 19640923;
        socsyst10_codigo = 'Z0';
        socsyst10_descripcion = 'Total Devoluciones';

        suspend;

        select
        sum(rep_pymvent50_detalles.total)
        from rep_pymvent50_detalles(:id_pymvent50)
        into :totales;
        totales = iif(totales is null, 0.00, totales) - importe_devoluciones;
    
        ID_SOCSYST10_FDP01 = 19640924;
        socsyst10_codigo = 'Z1';
        socsyst10_descripcion = 'Total Ventas';
    
        suspend;
    
        select pymvent50_cab_apertura.pymvent50_importe_apertura
        from pymvent50_cab_apertura
        where pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
        into :apertura;
        apertura = iif(apertura is null, 0.00, apertura);
    
        ID_SOCSYST10_FDP01 = 19640925;
        socsyst10_codigo = 'Z2';
        socsyst10_descripcion = 'Efectivo Apert.';
        totales = apertura;
    
        suspend;
    
        ID_SOCSYST10_FDP01 = 19640926;
        socsyst10_codigo = 'Z3';
        socsyst10_descripcion = 'Efectivo Venta Caja';
        totales = efectivo + apertura + redondeo;
    
        suspend;

        select sum(pymvent56_det_cobro.pymvent56_valor)
        from pymvent56_det_cobro
        inner join cbo_socsyst10_fdp01 on (cbo_socsyst10_fdp01.id_socsyst10 = pymvent56_det_cobro.rela_socsyst10_fdp01)
        inner join pymvent55_mov_moventsal on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
        where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
        and cbo_socsyst10_fdp01.socsyst10_codigo = '01'
        into :totales;

        if (totales is null) then
            totales = 0.00;

        select sum(pymvent55_mov_moventsal.pymvent55_importe)*(-1)
        from pymvent55_mov_moventsal
        where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50 and
        pymvent55_mov_moventsal.pymvent55_pagoticket = 0 and pymvent55_mov_moventsal.pymvent55_importe < 0
        into :prestamos;

        if (prestamos is null) then
            prestamos = 0.00;

        select sum(pymvent55_mov_moventsal.pymvent55_importe)
        from pymvent55_mov_moventsal
        where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50 and
        pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and pymvent55_mov_moventsal.pymvent55_importe > 0
        and pymvent55_mov_moventsal.rela_pymvent70 is null
        into :monedero;

        if (monedero is null) then
            monedero = 0.00;

        ID_SOCSYST10_FDP01 = 19640927;
        socsyst10_codigo = 'Z4';
        socsyst10_descripcion = 'Entradas y Salidas de Efectivo';
        totales = totales - prestamos - monedero;

        suspend;

        ID_SOCSYST10_FDP01 = 19640928;
        socsyst10_codigo = 'Z5';
        socsyst10_descripcion = 'Super Total Caja';
        totales = efectivo + apertura + redondeo + totales;
    
        suspend;
   /* end  */
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_CORTE_CAJA (
    PARAM_ID BIGINT)
RETURNS (
    EMPRESA_RAZSOCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION_NOMBRE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJA_NOMBRE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_DOCNRO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT50_CAJERO VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT50_IMPORTE_APERTURA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_CIERRE DOUBLE PRECISION,
    PYMVENT50_FAPERTURA TIMESTAMP,
    PYMVENT50_FCIERRE TIMESTAMP,
    PYMVENT50_SUBTOTAL DOUBLE PRECISION,
    PYMVENT50_DESCUENTO DOUBLE PRECISION,
    PYMVENT50_TOTAL_IMPUESTOS DOUBLE PRECISION,
    PYMVENT50_TOTAL DOUBLE PRECISION,
    PYMVENT50_ENTRADA DOUBLE PRECISION,
    PYMVENT50_SALIDA DOUBLE PRECISION,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_TICKET_ORDEN INTEGER,
    PYMVENT70_TICKET_TIPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT70_FORMAPAGO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_CLIENTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_VENDEDOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_PRODUCTOS INTEGER,
    PYMVENT70_CANCELADO INTEGER,
    PYMVENT50_ENTRADA_CONT INTEGER,
    PYMVENT50_SALIDA_CONT INTEGER,
    NUMERO_TICKETS_TOTALES INTEGER)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable ID_SOCMAIN21 bigint;
declare variable ID_PYMVENT60 bigint;
declare variable ID_PYMVENT73 bigint;
declare variable PYMVENT51_CANCELADO integer;
declare variable PYMVENT51_FCERRADO date;
declare variable PYMVENT51_FVENCIDO date;
declare variable CANT_ENTRADAS_APART integer;
declare variable TOTAL_ENTRADAS_APART double precision;
declare variable CANT_SALIDAS integer;
declare variable TOTAL_SALIDAS double precision;
begin

     select  socmain21_arb_organizacion.id_socmain21,
             socmain21_arb_organizacion.socmain21_descripcion,
             socsyst10_det_entradas.socsyst10_descripcion,
             pymvent01_cab_cajas.rela_socusua01_caje,
             pymvent50_cab_apertura.rela_socmain01,
             pymvent50_cab_apertura.id_pymvent50,
             pymvent50_cab_apertura.pymvent50_docnro,
             pymvent50_cab_apertura.pymvent50_importe_apertura,
             pymvent50_cab_apertura.pymvent50_fapertura,
             pymvent50_cab_apertura.pymvent50_fcierre
        from socmain21_arb_organizacion
  inner join pymvent50_cab_apertura on (pymvent50_cab_apertura.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
  inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
  inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = pymvent01_cab_cajas.rela_socsyst10_pvc01)
       where pymvent50_cab_apertura.id_pymvent50 = :param_id
        into :id_socmain21,
             :organizacion_nombre,
             :caja_nombre,
             :rela_socusua01_caje,
             :rela_socmain01,
             :id_pymvent50,
             :pymvent50_docnro,
             :pymvent50_importe_apertura,
             :pymvent50_fapertura,
             :pymvent50_fcierre;

     SELECT CFDI_EMPRESA.RAZSOCIAL,
            CFDI_EMPRESA.RFC,
            CFDI_EMPRESA.CURP,
            CFDI_EMPRESA.REGISTROPATRONAL
       FROM CFDI_EMPRESA(:rela_socmain01)
       INTO :EMPRESA_RAZSOCIAL,
            :EMPRESA_RFC,
            :EMPRESA_CURP,
            :EMPRESA_REGPATRON;

    SELECT CBO_SOCUSUA01.ENTIDAD
      from CBO_SOCUSUA01(:rela_socmain01, :id_socmain21, :rela_socusua01_caje)
      into :pymvent50_cajero;

  /*$$IBEC$$   select count(pymvent55_mov_moventsal.id_pymvent55),
           sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
      from pymvent55_mov_moventsal
     where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
       and pymvent55_mov_moventsal.pymvent55_importe > 0
      into :pymvent50_entrada_cont,
           :pymvent50_entrada;

        if (pymvent50_entrada is null) then
            pymvent50_entrada = 0; $$IBEC$$*/

     /* Calculo de entradas de dinero */
        select count(pymvent55_mov_moventsal.id_pymvent55),
                sum(pymvent56_det_cobro.pymvent56_valor)
            from pymvent56_det_cobro
               inner join pymvent55_mov_moventsal on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
            where pymvent56_det_cobro.rela_socsyst10_fdp01 = 54642 and
                pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and
                pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
            into :pymvent50_entrada_cont,
                 :pymvent50_entrada;

         pymvent50_entrada = iif(pymvent50_entrada is null, 0.00, pymvent50_entrada);
         pymvent50_entrada_cont = iif(pymvent50_entrada_cont is null, 0.00, pymvent50_entrada_cont);

         --HV: 08/05/2019. Se agrega los pagos iniciales de apartados y
         --entrada de dinero de personal
         select count(pymvent55_mov_moventsal.id_pymvent55),
                sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent55_mov_moventsal
            where (pymvent55_mov_moventsal.pymvent55_pagoticket = 5 or pymvent55_mov_moventsal.pymvent55_pagoticket = 0)
             and pymvent55_mov_moventsal.pymvent55_importe > 0 and
                pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
            into :Cant_entradas_apart,
                 :Total_entradas_apart;

         Total_entradas_apart = iif(Total_entradas_apart is null, 0.00, Total_entradas_apart);
         Cant_entradas_apart = iif(Cant_entradas_apart is null, 0.00, Cant_entradas_apart);

         pymvent50_entrada = pymvent50_entrada +  Total_entradas_apart;
         pymvent50_entrada_cont = pymvent50_entrada_cont +  Cant_entradas_apart;

    /*$$IBEC$$  select count(pymvent55_mov_moventsal.id_pymvent55),
            sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
       from pymvent55_mov_moventsal
      where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
        and pymvent55_mov_moventsal.pymvent55_importe < 0
       into :pymvent50_salida_cont,
            :pymvent50_salida;

         if (pymvent50_salida is null) then
            pymvent50_salida = 0;
         else
            pymvent50_salida = (pymvent50_salida * -1); $$IBEC$$*/

         /* Calculo de salidas de dinero
          Se consideran salidas de dinero los prestamos a personal y las devoluciones
          de dinero a clientes por Monedero Electónico*/
          /* Como los montos de monedero electronico son positivos, se obtienen
          primero los mismos por separado */
         select count(pymvent55_mov_moventsal.id_pymvent55),
            sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe > 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and
            pymvent55_mov_moventsal.rela_pymvent70 is null) and
                pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50 and pymvent50_cab_apertura.rela_socmain21 = :id_socmain21
         into   :pymvent50_salida_cont,
                :pymvent50_salida;

         pymvent50_salida_cont = iif(pymvent50_salida_cont is null, 0.00, pymvent50_salida_cont);
         pymvent50_salida = iif(pymvent50_salida is null, 0.00, pymvent50_salida);

         /* Se obtienen los montos de prestamos a personal, los cuales son negativos */
         select count(pymvent55_mov_moventsal.id_pymvent55),
            sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe < 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 0) and
                pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50 and pymvent50_cab_apertura.rela_socmain21 = :id_socmain21
            into    :cant_salidas,
                    :Total_salidas;

          cant_salidas = iif(cant_salidas is null, 0.00, cant_salidas);
          Total_salidas = iif(Total_salidas is null, 0.00, (-1)*Total_salidas);

          pymvent50_salida_cont = pymvent50_salida_cont + cant_salidas;
          pymvent50_salida = pymvent50_salida + Total_salidas;

          numero_tickets_totales = 0;

          /* Obtenemos los tickets de la apertura / cierre */
          for select pymvent70_cab_ticket.rela_sicingr01,
                     pymvent70_cab_ticket.id_pymvent70,
                     pymvent70_cab_ticket.pymvent70_docnro,
                     pymvent70_cab_ticket.pymvent70_neto,
                     pymvent51_det_ventas.pymvent51_fcerrado,
                     pymvent51_det_ventas.pymvent51_fvencido,
                     pymvent51_det_ventas.pymvent51_cancelado,
                     socusua01_cab_usuarios.rela_socusua30,
                     pymvent60_cab_cobro.id_pymvent60,
                     pymvent73_mov_cancelados.id_pymvent73
                from pymvent70_cab_ticket
          inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
          inner join socusua01_cab_usuarios on (socusua01_cab_usuarios.id_socusua01 = pymvent51_det_ventas.rela_socusua01_vend)
         left outer join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
         left outer join pymvent73_mov_cancelados on (pymvent70_cab_ticket.id_pymvent70 = pymvent73_mov_cancelados.rela_pymvent70)
               where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
                into :rela_sicingr01,
                     :id_pymvent70,
                     :pymvent70_docnro,
                     :pymvent70_neto,
                     :pymvent51_fcerrado,
                     :pymvent51_fvencido,
                     :pymvent51_cancelado,
                     :rela_socusua30,
                     :id_pymvent60,
                     :id_pymvent73
           do begin
                numero_tickets_totales = numero_tickets_totales + 1;

                select cbo_socusua30.entidad
                  from cbo_socusua30(:rela_socusua30)
                  into :pymvent70_vendedor;

                select count(pymvent71_det_ticket.id_pymvent71),
                       sum(pymvent71_det_ticket.pymvent71_cancelado)
                  from pymvent71_det_ticket
                 where pymvent71_det_ticket.rela_pymvent70 = :id_pymvent70
                  into :pymvent70_productos,
                       :pymvent70_cancelado;

                if (id_pymvent60 > 0) then
                    begin
                        pymvent70_ticket_orden = 1;
                        pymvent70_ticket_tipo = 'Cobrados';

                        select first 1 socsyst10_det_remoto.socsyst10_descripcion
                          from pymvent61_det_cobro
                    inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01)
                         where pymvent61_det_cobro.rela_pymvent60 = :id_pymvent60
                          into :pymvent70_formapago;

                        select cbo_sicingr01_id.entidad
                          from cbo_sicingr01_id
                         where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
                          into :pymvent70_cliente;

                    end
                else
                    begin
                       pymvent70_ticket_orden = 4;
                       pymvent70_ticket_tipo = 'Pendientes';
                       pymvent70_formapago = null;
                       pymvent70_cliente = null;
                    end

                if (pymvent70_cancelado > 0) then
                    begin
                        pymvent70_ticket_orden = 2;
                        pymvent70_ticket_tipo = 'Cancelados';
                    end

                if (id_pymvent73 is not null) then
                    begin
                        pymvent70_ticket_orden = 3;
                        pymvent70_ticket_tipo = 'Devoluciones';
                    end

                if (pymvent70_neto is null) then
                    pymvent70_neto = 0;

                suspend;

           end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_CORTE_CAJA_EXT (
    ID_PYMVENT50_PARAM BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_PYMVENT01 BIGINT,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_DOCNRO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT50_IMPORTE_APERTURA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_VENTA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_EFECTIVO DOUBLE PRECISION,
    PYMVENT50_FAPERTURA TIMESTAMP,
    PYMVENT50_FCIERRE TIMESTAMP,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCUSUA01_CAJE BIGINT,
    RELA_SOCSYST10_PVC01 BIGINT,
    NOMBRE_CAJ VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CANT_ART_VENDIDOS DOUBLE PRECISION,
    NUM_TICKETS INTEGER,
    CANT_ENTRADAS INTEGER,
    TOTAL_ENTRADAS DOUBLE PRECISION,
    CANT_SALIDAS INTEGER,
    TOTAL_SALIDAS DOUBLE PRECISION)
AS
declare variable SALIDAS_MON double precision;
declare variable CANT_SALIDAS_MON integer;
declare variable TOTAL_ENTRADAS_APART double precision;
declare variable CANT_ENTRADAS_APART integer;
BEGIN
    for select
         pymvent50_cab_apertura.rela_socmain01,
         pymvent50_cab_apertura.rela_socmain21,
         pymvent50_cab_apertura.rela_pymvent01,
         pymvent50_cab_apertura.id_pymvent50,
         pymvent50_cab_apertura.pymvent50_docnro,
         pymvent50_cab_apertura.pymvent50_importe_apertura,
         pymvent50_cab_apertura.pymvent50_importe_venta,
         pymvent50_cab_apertura.pymvent50_importe_efectivo,
         pymvent50_cab_apertura.pymvent50_fapertura,
         pymvent50_cab_apertura.pymvent50_fcierre,
         socmain21_arb_organizacion.socmain21_descripcion,
         pymvent01_cab_cajas.rela_socusua01_caje,
         pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent50_cab_apertura
        inner join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = pymvent50_cab_apertura.rela_socmain21)
        inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where pymvent50_cab_apertura.id_pymvent50 = :ID_PYMVENT50_PARAM
        into :rela_socmain01,
             :rela_socmain21,
             :rela_pymvent01,
             :id_pymvent50,
             :pymvent50_docnro,
             :pymvent50_importe_apertura,
             :pymvent50_importe_venta,
             :pymvent50_importe_efectivo,
             :pymvent50_fapertura,
             :pymvent50_fcierre,
             :socmain21_descripcion,
             :rela_socusua01_caje,
             :rela_socsyst10_pvc01
    do begin

        /* Se obtiene el nombre de la organización */
        select CBO_SOCMAIN01.socmain01_nomcomercial
          from CBO_SOCMAIN01
          where CBO_SOCMAIN01.id_socmain01 = :rela_socmain01
          into :socmain01_nomcomercial;

          /* obtenemos la descripcion de la caja */
          select CBO_SOCSYST10_PVC01.socsyst10_descripcion
              from CBO_SOCSYST10_PVC01
              where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
              into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
        SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:rela_socmain01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;
    
         /* Se obtienen la cantidad de articulos vendidos */
        select sum( pymvent71_det_ticket.pymvent71_cantidad)
            from pymvent71_det_ticket
               inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
               inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
               inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
            where pymvent51_det_ventas.rela_pymvent50 = :ID_PYMVENT50_PARAM  and
                pymvent71_det_ticket.pymvent71_cancelado = 0
            into :cant_art_vendidos;
        cant_art_vendidos = iif(cant_art_vendidos is null, 0.00, cant_art_vendidos);

        /* Se obtiene la cantidad de tickets generados */
        select count(pymvent51_det_ventas.id_pymvent51)
            from pymvent51_det_ventas
            where pymvent51_det_ventas.rela_pymvent50 = :ID_PYMVENT50_PARAM and
            pymvent51_det_ventas.pymvent51_fcerrado is not null
            into :num_tickets;
        num_tickets = iif(num_tickets is null, 0.00, num_tickets);

        /* Calculo de entradas de dinero por abono a creditos 99*/
        select count(pymvent55_mov_moventsal.id_pymvent55),
                sum(pymvent56_det_cobro.pymvent56_valor)
            from pymvent56_det_cobro
               inner join pymvent55_mov_moventsal on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
            where pymvent56_det_cobro.rela_socsyst10_fdp01 = 54642 and
                 pymvent55_mov_moventsal.pymvent55_pagoticket = 3 AND
                pymvent55_mov_moventsal.rela_pymvent50 = :ID_PYMVENT50_PARAM
            into :Cant_entradas,
                 :Total_entradas;

         Total_entradas = iif(Total_entradas is null, 0.00, Total_entradas);
         Cant_entradas = iif(Cant_entradas is null, 0.00, Cant_entradas);

         --HV: 08/05/2019. Se agrega los pagos iniciales de apartados y
         --entrada de dinero de personal
         select count(pymvent55_mov_moventsal.id_pymvent55),
                sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent55_mov_moventsal
            where (pymvent55_mov_moventsal.pymvent55_pagoticket = 5 or pymvent55_mov_moventsal.pymvent55_pagoticket = 0)
             and pymvent55_mov_moventsal.pymvent55_importe > 0 and
                pymvent55_mov_moventsal.rela_pymvent50 = :ID_PYMVENT50_PARAM
            into :Cant_entradas_apart,
                 :Total_entradas_apart;

         Total_entradas_apart = iif(Total_entradas_apart is null, 0.00, Total_entradas_apart);
         Cant_entradas_apart = iif(Cant_entradas_apart is null, 0.00, Cant_entradas_apart);

         Total_entradas = Total_entradas +  Total_entradas_apart;
         Cant_entradas = Cant_entradas +  Cant_entradas_apart;

         /* Calculo de salidas de dinero
          Se consideran salidas de dinero los prestamos a personal y las devoluciones
          de dinero a clientes por Monedero Electónico*/
          /* Como los montos de monedero electronico son positivos, se obtienen
          primero los mismos por separado */
         select count(pymvent55_mov_moventsal.id_pymvent55),
            sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe > 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and
            pymvent55_mov_moventsal.rela_pymvent70 is null) and
                pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50_param and pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21
         into   :cant_salidas_mon,
                :Salidas_mon;

         cant_salidas_mon = iif(cant_salidas_mon is null, 0.00, cant_salidas_mon);
         Salidas_mon = iif(Salidas_mon is null, 0.00, Salidas_mon);

         /* Se obtienen los montos de prestamos a personal, los cuales son negativos */
         select count(pymvent55_mov_moventsal.id_pymvent55),
            sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe < 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 0) and
                pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50_param and pymvent50_cab_apertura.rela_socmain21 = :rela_socmain21
            into    :cant_salidas,
                    :Total_salidas;

            cant_salidas = iif(cant_salidas is null, 0.00, cant_salidas);
            Total_salidas = iif(Total_salidas is null, 0.00, (-1)*Total_salidas);

            /* Finalmente, se suman ambos montos y cantidades*/
            cant_salidas = cant_salidas + cant_salidas_mon;
            Total_salidas =  Total_salidas + Salidas_mon;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_CORTE_DETALLE (
    PARAM_EMPRESA BIGINT,
    PARAM_FECHA_DESDE DATE,
    PARAM_FECHA_HASTA DATE)
RETURNS (
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION_NOMBRE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAJA_NOMBRE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_DOCNRO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT50_FAPERTURA DATE,
    PYMVENT50_FCIERRE DATE,
    NUMERO_TICKETS INTEGER,
    PYMVENT50_SUBTOTAL DOUBLE PRECISION,
    PYMVENT50_DESCUENTO DOUBLE PRECISION,
    PYMVENT50_TOTAL_IMPUESTOS DOUBLE PRECISION,
    PYMVENT50_TOTAL DOUBLE PRECISION,
    PYMVENT50_NETO DOUBLE PRECISION,
    PYMVENT50_ENTRADA DOUBLE PRECISION,
    PYMVENT50_SALIDA DOUBLE PRECISION)
AS
declare variable TOTAL_ENTRADAS_APART double precision;
declare variable TOTAL_SALIDAS double precision;
BEGIN
  SELECT
      CFDI_EMPRESA.RAZSOCIAL,
      CFDI_EMPRESA.RFC,
      CFDI_EMPRESA.CURP,
      CFDI_EMPRESA.REGISTROPATRONAL
  FROM CFDI_EMPRESA(:PARAM_EMPRESA)
  INTO
      :EMPRESA_RAZSOCIAL,
      :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;

  for select socmain21_arb_organizacion.socmain21_descripcion,
             socsyst10_det_entradas.socsyst10_descripcion,
             pymvent50_cab_apertura.id_pymvent50,
             pymvent50_cab_apertura.pymvent50_docnro,
             pymvent50_cab_apertura.pymvent50_fapertura,
             pymvent50_cab_apertura.pymvent50_fcierre
        from socmain21_arb_organizacion
  inner join pymvent50_cab_apertura on (pymvent50_cab_apertura.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
  inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.rela_socmain21 = socmain21_arb_organizacion.id_socmain21)
  inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = pymvent01_cab_cajas.rela_socsyst10_pvc01)
       where CAST (pymvent50_cab_apertura.pymvent50_fapertura AS date) between :PARAM_FECHA_DESDE and :PARAM_FECHA_HASTA
        into :organizacion_nombre,
             :caja_nombre,
             :id_pymvent50,
             :pymvent50_docnro,
             :pymvent50_fapertura,
             :pymvent50_fcierre
           do
           begin

              numero_tickets = 0;
              pymvent50_subtotal = 0;
              pymvent50_descuento = 0;
              pymvent50_total_impuestos = 0;
              pymvent50_total = 0;
              pymvent50_neto = 0;
              pymvent50_entrada = 0;
              pymvent50_salida = 0;

              caja_nombre = organizacion_nombre || ' - ' || caja_nombre;

              select count(REP_PYMVENT50_TICKETS.id_pymvent70),
                     sum(REP_PYMVENT50_TICKETS.pymvent70_subtotal),
                     sum(rep_pymvent50_tickets.pymvent70_descuento),
                     sum(rep_pymvent50_tickets.pymvent70_total_impuestos),
                     sum(rep_pymvent50_tickets.pymvent70_total),
                     sum(REP_PYMVENT50_TICKETS.pymvent70_neto)
                from REP_PYMVENT50_TICKETS(:id_pymvent50)
                into :numero_tickets,
                     :pymvent50_subtotal,
                     :pymvent50_descuento,
                     :pymvent50_total_impuestos,
                     :pymvent50_total,
                     :pymvent50_neto;

              if (numero_tickets is null) then
                numero_tickets = 0;

              if (pymvent50_subtotal is null) then
                 pymvent50_subtotal = 0;

              if (pymvent50_descuento is null) then
                  pymvent50_descuento = 0;

              if (pymvent50_total_impuestos is null) then
                  pymvent50_total_impuestos = 0;

              if (pymvent50_total is null) then
                  pymvent50_total = 0;

              if (pymvent50_neto is null) then
                  pymvent50_neto = 0;

             /*$$IBEC$$  select sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
                from pymvent55_mov_moventsal
               where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
                 and pymvent55_mov_moventsal.pymvent55_importe > 0
                into :pymvent50_entrada;

               if (pymvent50_entrada is null) then
                   pymvent50_entrada = 0;

              select sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
                from pymvent55_mov_moventsal
               where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
                 and pymvent55_mov_moventsal.pymvent55_importe < 0
               into :pymvent50_salida;

               if (pymvent50_salida is null) then
                   pymvent50_salida = 0;
               else
                   pymvent50_salida = (pymvent50_salida * -1); $$IBEC$$*/

              /* Calculo de entradas de dinero */
         select count(pymvent55_mov_moventsal.id_pymvent55)
            from pymvent56_det_cobro
               inner join pymvent55_mov_moventsal on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
            where pymvent56_det_cobro.rela_socsyst10_fdp01 = 54642 and
                pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and
                pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
            into :pymvent50_entrada;

         pymvent50_entrada = iif(pymvent50_entrada is null, 0.00, pymvent50_entrada);

         --HV: 08/05/2019. Se agrega los pagos iniciales de apartados y
         --entrada de dinero de personal
         select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent55_mov_moventsal
            where (pymvent55_mov_moventsal.pymvent55_pagoticket = 5 or pymvent55_mov_moventsal.pymvent55_pagoticket = 0)
             and pymvent55_mov_moventsal.pymvent55_importe > 0 and
                pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50
            into :Total_entradas_apart;

         Total_entradas_apart = iif(Total_entradas_apart is null, 0.00, Total_entradas_apart);

         pymvent50_entrada = pymvent50_entrada +  Total_entradas_apart;

          /* Calculo de salidas de dinero
          Se consideran salidas de dinero los prestamos a personal y las devoluciones
          de dinero a clientes por Monedero Electónico*/
          /* Como los montos de monedero electronico son positivos, se obtienen
          primero los mismos por separado */
         select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe > 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and
            pymvent55_mov_moventsal.rela_pymvent70 is null) and
                pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
         into  :pymvent50_salida;

         pymvent50_salida = iif(pymvent50_salida is null, 0.00, pymvent50_salida);

         /* Se obtienen los montos de prestamos a personal, los cuales son negativos */
         select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent50_cab_apertura
               inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
            where (pymvent55_mov_moventsal.pymvent55_importe < 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 0) and
                pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50
            into :Total_salidas;

          Total_salidas = iif(Total_salidas is null, 0.00, (-1)*Total_salidas);

          pymvent50_salida = pymvent50_salida + Total_salidas;
              suspend;

           end
END^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_DETALLES (
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_SICINGR95 BIGINT,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    TOT_CANTIDAD DOUBLE PRECISION,
    TOT_DESCUENTOS DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TOT_CANTIDAD_VENTA INTEGER)
AS
begin
    FOR select 
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    min(pymvent71_det_ticket.pymvent71_importe_unidad),
    sum(pymvent71_det_ticket.pymvent71_cantidad),
    sum(pymvent71_det_ticket.pymvent71_importe_descuento),
    sum(pymvent71_det_ticket.pymvent71_importe_neto),
    count(pymvent71_det_ticket.rela_sicingr95)
    from pymvent71_det_ticket
    inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    inner join pymvent60_cab_cobro on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
    where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent71_det_ticket.pymvent71_cancelado = 0
    group by pymvent71_det_ticket.rela_sicingr95,
             pymvent71_det_ticket.pymvent71_codigo,
             pymvent71_det_ticket.pymvent71_concepto
    into :id_sicingr95,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_importe_unidad,
         :tot_cantidad,
         :tot_descuentos,
         :total,
         :tot_cantidad_venta
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_DETALLES_CANC (
    ID_PYMVENT50 BIGINT)
RETURNS (
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    ID_SICINGR95 BIGINT,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    TOT_CANTIDAD DOUBLE PRECISION,
    TOT_DESCUENTOS DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TOT_CANTIDAD_VENTA INTEGER)
AS
begin
    FOR select 
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    min(pymvent71_det_ticket.pymvent71_importe_unidad),
    sum(pymvent71_det_ticket.pymvent71_cantidad),
    sum(pymvent71_det_ticket.pymvent71_importe_descuento),
    sum(pymvent71_det_ticket.pymvent71_importe_neto),
    count(pymvent71_det_ticket.rela_sicingr95)
    from pymvent71_det_ticket
    inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent71_det_ticket.pymvent71_cancelado = 1
    group by pymvent70_cab_ticket.pymvent70_docnro,
             pymvent70_cab_ticket.pymvent70_fecha,
             pymvent71_det_ticket.rela_sicingr95,
             pymvent71_det_ticket.pymvent71_codigo,
             pymvent71_det_ticket.pymvent71_concepto
    into :pymvent70_docnro,
         :pymvent70_fecha,
         :id_sicingr95,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_importe_unidad,
         :tot_cantidad,
         :tot_descuentos,
         :total,
         :tot_cantidad_venta
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_DETALLES_DEVO (
    ID_PYMVENT50 BIGINT)
RETURNS (
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    ID_SICINGR95 BIGINT,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_NETO DOUBLE PRECISION,
    PYMVENT73_CANTIDAD DOUBLE PRECISION,
    PYMVENT73_IMPORTE DOUBLE PRECISION,
    SALDO_CANTIDAD DOUBLE PRECISION,
    SALDO_IMPORTE DOUBLE PRECISION)
AS
declare variable RELA_SICINGR01 bigint;
begin
    FOR select 
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.pymvent71_codigo,
    pymvent71_det_ticket.pymvent71_concepto,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_neto,
    pymvent73_mov_cancelados.pymvent73_cantidad,
    pymvent73_mov_cancelados.pymvent73_importe
    from pymvent71_det_ticket
    inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    inner join pymvent73_mov_cancelados on (pymvent71_det_ticket.id_pymvent71 = pymvent73_mov_cancelados.rela_pymvent71)
    where pymvent73_mov_cancelados.rela_pymvent50 = :id_pymvent50
    into :rela_sicingr01,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :id_sicingr95,
         :pymvent71_codigo,
         :pymvent71_concepto,
         :pymvent71_cantidad,
         :pymvent71_importe_neto,
         :pymvent73_cantidad,
         :pymvent73_importe
    do
    begin
        select cbo_sicingr01_id.entidad
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :cliente;

        saldo_cantidad = pymvent71_cantidad - pymvent73_cantidad;
        saldo_importe = pymvent71_importe_neto - pymvent73_importe;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_ENT (
    ID_PYMVENT50_PARAM BIGINT,
    P_SOCMAIN01 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_IMPORTE_APERTURA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_VENTA DOUBLE PRECISION,
    PYMVENT50_FAPERTURA TIMESTAMP,
    PYMVENT50_FCIERRE TIMESTAMP,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE_CAJ VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_PYMVENT70 BIGINT,
    PYMVENT55_IMPORTE DOUBLE PRECISION,
    PYMVENT55_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCSYST10_PVC01 bigint;
declare variable RELA_SOCUSUA30 bigint;
begin
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    /* Se obtiene los datos del encabezado */
    for select
         pymvent50_cab_apertura.rela_socmain21,
         pymvent50_cab_apertura.id_pymvent50,
         pymvent50_cab_apertura.pymvent50_importe_apertura,
         pymvent50_cab_apertura.pymvent50_importe_venta,
         pymvent50_cab_apertura.pymvent50_fapertura,
         pymvent50_cab_apertura.pymvent50_fcierre,
         socmain21_arb_organizacion.socmain21_descripcion,
         pymvent01_cab_cajas.rela_socusua01_caje,
         pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent50_cab_apertura
        inner join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = pymvent50_cab_apertura.rela_socmain21)
        inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where pymvent50_cab_apertura.id_pymvent50 = :ID_PYMVENT50_PARAM and pymvent50_cab_apertura.rela_socmain01 = :P_SOCMAIN01
        into :rela_socmain21,
             :id_pymvent50,
             :pymvent50_importe_apertura,
             :pymvent50_importe_venta,
             :pymvent50_fapertura,
             :pymvent50_fcierre,
             :socmain21_descripcion,
             :rela_socusua01_caje,
             :rela_socsyst10_pvc01
        do begin
            /* Se inicializan las variables */
            socsyst10_descripcion = null;
            NOMBRE_CAJ = null;

          /* obtenemos la descripcion de la caja */
          select CBO_SOCSYST10_PVC01.socsyst10_descripcion
              from CBO_SOCSYST10_PVC01
              where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
              into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
         SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:P_SOCMAIN01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;

          --Entradas de dinero por abonos a credito en efectivo o por personal
          for select pymvent55_mov_moventsal.rela_socusua30,
                pymvent55_mov_moventsal.rela_pymvent70,
               pymvent56_det_cobro.pymvent56_valor,
               pymvent55_mov_moventsal.pymvent55_notas
            from pymvent56_det_cobro
               inner join pymvent55_mov_moventsal on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
            where pymvent56_det_cobro.rela_socsyst10_fdp01 = 54642 and
                pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50_param
            into :RELA_SOCUSUA30,
                :RELA_PYMVENT70,
                :PYMVENT55_IMPORTE,
                :PYMVENT55_NOTAS
            do begin
                /* Se inicializan las variables */
                pymvent70_docnro = null;
                cliente = null;

                /* se obtiene el numero de ticket completo, sólo para
                entradas de dinero con 99*/
                if (RELA_PYMVENT70 is not null) then
                    select pymvent70_cab_ticket.pymvent70_docnro
                    from pymvent70_cab_ticket
                    where pymvent70_cab_ticket.id_pymvent70 = :RELA_PYMVENT70
                    into :pymvent70_docnro;
                else
                    pymvent70_docnro = ' ';
        
                /* Se obtiene el nombre del cliente */
                select ENTIDAD from CBO_SOCUSUA30_ALL where ID_SOCUSUA30 = :RELA_SOCUSUA30
                into :cliente;
              suspend;
            end

           --Entradas de dinero por inicial de apartados (No aparecen en el pymvent56_det_cobro)
          for select pymvent55_mov_moventsal.rela_socusua30,
                pymvent55_mov_moventsal.rela_pymvent70,
                 pymvent55_mov_moventsal.pymvent55_importe,
               pymvent55_mov_moventsal.pymvent55_notas
            from pymvent55_mov_moventsal
               --inner join pymvent55_mov_moventsal on (pymvent55_mov_moventsal.id_pymvent55 = pymvent56_det_cobro.rela_pymvent55)
            where pymvent55_mov_moventsal.pymvent55_pagoticket = 5 and
                pymvent55_mov_moventsal.pymvent55_importe > 0 and
                pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50_param
            into :RELA_SOCUSUA30,
                :RELA_PYMVENT70,
                :PYMVENT55_IMPORTE,
                :PYMVENT55_NOTAS
            do begin
                /* Se inicializan las variables */
                pymvent70_docnro = null;
                cliente = null;

                /* se obtiene el numero de ticket completo */
                --if (RELA_PYMVENT70 is not null) then
                select pymvent70_cab_ticket.pymvent70_docnro
                from pymvent70_cab_ticket
                where pymvent70_cab_ticket.id_pymvent70 = :RELA_PYMVENT70
                into :pymvent70_docnro;

        
                /* Se obtiene el nombre del cliente */
                select ENTIDAD from CBO_SOCUSUA30_ALL where ID_SOCUSUA30 = :RELA_SOCUSUA30
                into :cliente;
                 suspend;
            end
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_ENT_SAL (
    ID_PYMVENT50_PARAM BIGINT,
    P_SOCMAIN01 BIGINT,
    P_ENT_SAL INTEGER)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_IMPORTE_APERTURA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_VENTA DOUBLE PRECISION,
    PYMVENT50_FAPERTURA TIMESTAMP,
    PYMVENT50_FCIERRE TIMESTAMP,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE_CAJ VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_PYMVENT70 BIGINT,
    PYMVENT55_IMPORTE DOUBLE PRECISION,
    PYMVENT55_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCSYST10_PVC01 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable STR varchar(2000);
begin
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    /* Se obtiene los datos del encabezado */
    for select
         pymvent50_cab_apertura.rela_socmain21,
         pymvent50_cab_apertura.id_pymvent50,
         pymvent50_cab_apertura.pymvent50_importe_apertura,
         pymvent50_cab_apertura.pymvent50_importe_venta,
         pymvent50_cab_apertura.pymvent50_fapertura,
         pymvent50_cab_apertura.pymvent50_fcierre,
         socmain21_arb_organizacion.socmain21_descripcion,
         pymvent01_cab_cajas.rela_socusua01_caje,
         pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent50_cab_apertura
        inner join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = pymvent50_cab_apertura.rela_socmain21)
        inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where pymvent50_cab_apertura.id_pymvent50 = :ID_PYMVENT50_PARAM and pymvent50_cab_apertura.rela_socmain01 = :P_SOCMAIN01
        into :rela_socmain21,
             :id_pymvent50,
             :pymvent50_importe_apertura,
             :pymvent50_importe_venta,
             :pymvent50_fapertura,
             :pymvent50_fcierre,
             :socmain21_descripcion,
             :rela_socusua01_caje,
             :rela_socsyst10_pvc01
        do begin
            /* Se inicializan las variables */
            socsyst10_descripcion = null;
            NOMBRE_CAJ = null;

          /* obtenemos la descripcion de la caja */
          select CBO_SOCSYST10_PVC01.socsyst10_descripcion
              from CBO_SOCSYST10_PVC01
              where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
              into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
         SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:P_SOCMAIN01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;



         /*$$IBEC$$  str = 'select RELA_SOCUSUA30,
                        RELA_PYMVENT70,
                        PYMVENT55_IMPORTE,
                        PYMVENT55_NOTAS
                from PYMVENT55_MOV_MOVENTSAL
                where RELA_PYMVENT50 =' || :ID_PYMVENT50_PARAM || ' and
                    (pymvent55_pagoticket = 0 '; $$IBEC$$*/

          /* Si p_ent_sal = 0 se quiere solo los moviemientos de entrada,
          si es 1, se quiere los moviemientos de salida */
          if (:p_ent_sal = 0) then /* Se requiere sólo las entradas de dinero */
          begin
              /* Se obtienen los pagos a tickets con compra 99 o entrada de
              efectivo por un empleado*/
            /*$$IBEC$$  str = :str ||  'or pymvent55_pagoticket = 3) and PYMVENT55_IMPORTE > 0 '; $$IBEC$$*/

             --HV: 09/05/2019, Se cambia para usar los procedimientos que estan correguidos
             str = 'select
                        CLIENTE,
                        RELA_PYMVENT70,
                        pymvent70_docnro,
                        PYMVENT55_IMPORTE,
                        PYMVENT55_NOTAS
                from REP_PYMVENT50_ENT('||:id_pymvent50_param||','||:p_socmain01||')';

          end
          else
          begin

               /* Se obtienen las salidas de dinero, las cuales no tienen ticket
               relacionado */
               /*$$IBEC$$  str = :str ||  ' and PYMVENT55_IMPORTE < 0) or
                (pymvent55_mov_moventsal.pymvent55_importe > 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and
                pymvent55_mov_moventsal.rela_pymvent70 is null)'; $$IBEC$$*/

                --HV: 09/05/2019, Se cambia para usar los procedimientos que estan correguidos
             str = 'select
                        CLIENTE,
                        -1,
                        '''',
                        PYMVENT55_IMPORTE,
                        PYMVENT55_NOTAS
                from REP_PYMVENT50_SAL('||:id_pymvent50_param||','||:p_socmain01||')';

          end
          for execute statement str
            into
                 :cliente,
                :RELA_PYMVENT70,
                :pymvent70_docnro,
                :PYMVENT55_IMPORTE,
                :PYMVENT55_NOTAS
            do begin
               /* Se inicializan las variables *//*$$IBEC$$ 
                pymvent70_docnro = null;
                cliente = null;

                if (:p_ent_sal = 0) then
                     $$IBEC$$*//* se obtiene el numero de ticket completo, sólo para
                    entradas de dinero con 99*//*$$IBEC$$ 
                    if (RELA_PYMVENT70 is not null) then
                        select pymvent70_cab_ticket.pymvent70_docnro
                        from pymvent70_cab_ticket
                        where pymvent70_cab_ticket.id_pymvent70 = :RELA_PYMVENT70
                        into :pymvent70_docnro;
                    else
                        pymvent70_docnro = ' ';
                else
                     $$IBEC$$*//* En el caso de salidas de dinero, el importe es negativo *//*$$IBEC$$ 
                    PYMVENT55_IMPORTE = (-1)*PYMVENT55_IMPORTE;
        
                 $$IBEC$$*//* Se obtiene el nombre del cliente *//*$$IBEC$$ 
                select ENTIDAD from CBO_SOCUSUA30_ALL where ID_SOCUSUA30 = :RELA_SOCUSUA30
                into :cliente; $$IBEC$$*/
              suspend;
            end
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_PENDIENTES (
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_PYMVENT70 INTEGER,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_SUBTOTAL INTEGER,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_LOCALES DOUBLE PRECISION,
    PYMVENT70_TOTAL_IMPUESTOS DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION)
AS
begin
    for select
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_subtotal,
    pymvent70_cab_ticket.pymvent70_descuento,
    pymvent70_cab_ticket.pymvent70_total,
    pymvent70_cab_ticket.pymvent70_totimp_retenidos,
    pymvent70_cab_ticket.pymvent70_totimp_traslados,
    pymvent70_cab_ticket.pymvent70_totimp_locales,
    pymvent70_cab_ticket.pymvent70_neto
    from pymvent51_det_ventas
    inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent51_det_ventas.pymvent51_fcerrado is null
    and not exists ( select pymvent60_cab_cobro.id_pymvent60
                     from pymvent60_cab_cobro
                     where pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51
                    )
    into :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_subtotal,
         :pymvent70_descuento,
         :pymvent70_total,
         :pymvent70_totimp_retenidos,
         :pymvent70_totimp_traslados,
         :pymvent70_totimp_locales,
         :pymvent70_neto
    do
    begin
        pymvent70_total_impuestos =  pymvent70_totimp_retenidos +
                                     pymvent70_totimp_traslados +
                                     pymvent70_totimp_locales;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_PRESUPUESTOS (
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_PYMVENT70 INTEGER,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_SUBTOTAL INTEGER,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_LOCALES DOUBLE PRECISION,
    PYMVENT70_TOTAL_IMPUESTOS DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT51_FVENCIDO TIMESTAMP,
    PYMVENT70_DOCNRO_VENTA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA_VENTA TIMESTAMP,
    PYMVENT70_NETO_VENTA DOUBLE PRECISION)
AS
begin
    for select
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_subtotal,
    pymvent70_cab_ticket.pymvent70_descuento,
    pymvent70_cab_ticket.pymvent70_total,
    pymvent70_cab_ticket.pymvent70_totimp_retenidos,
    pymvent70_cab_ticket.pymvent70_totimp_traslados,
    pymvent70_cab_ticket.pymvent70_totimp_locales,
    pymvent70_cab_ticket.pymvent70_neto,
    pymvent51_det_ventas.pymvent51_fvencido
    from pymvent51_det_ventas
    inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
    and pymvent51_det_ventas.pymvent51_fvencido is not null
    and pymvent51_det_ventas.pymvent51_fcerrado is null
    and pymvent51_det_ventas.pymvent51_cancelado <> 9
    into :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_subtotal,
         :pymvent70_descuento,
         :pymvent70_total,
         :pymvent70_totimp_retenidos,
         :pymvent70_totimp_traslados,
         :pymvent70_totimp_locales,
         :pymvent70_neto,
         :pymvent51_fvencido
    do
    begin
        pymvent70_docnro_venta = null;
        pymvent70_fecha_venta = null;
        pymvent70_neto_venta = null;

        pymvent70_total_impuestos =  pymvent70_totimp_retenidos +
                                     pymvent70_totimp_traslados +
                                     pymvent70_totimp_locales;

        select
        pymvent70_cab_ticket.pymvent70_docnro,
        pymvent70_cab_ticket.pymvent70_fecha,
        pymvent70_cab_ticket.pymvent70_neto
        from pymvent57_det_presupuesto
        inner join pymvent70_cab_ticket on ( pymvent70_cab_ticket.id_pymvent70 = pymvent57_det_presupuesto.rela_pymvent70_cobo )
        where pymvent57_det_presupuesto.rela_pymvent70_presu = :id_pymvent70
        into :pymvent70_docnro_venta,
             :pymvent70_fecha_venta,
             :pymvent70_neto_venta;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_PYMVENT70 (
    ID_PYMVENT50_PARAM BIGINT)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    ID_PYMVENT51 BIGINT,
    ID_PYMVENT60 BIGINT,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CANTIDAD DOUBLE PRECISION,
    OCURRENCIA INTEGER,
    FORMADEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_VENDEDOR VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA01_VEND bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable PYMVENT51_CANCELADO integer;
declare variable RELA_SICINGR01 bigint;
declare variable CANT_CANCE double precision;
declare variable IMPORTE_CANCE double precision;
declare variable OCURREN_CANCE double precision;
declare variable RELA_SOCSYST10_FDP01 bigint;
declare variable MONTO double precision;
begin
  for select
            pymvent51_det_ventas.rela_pymvent70,
            pymvent51_det_ventas.rela_socusua01_vend,
            pymvent51_det_ventas.id_pymvent51,
            pymvent60_cab_cobro.id_pymvent60,
            pymvent51_det_ventas.pymvent51_cancelado,
            pymvent70_cab_ticket.rela_sicingr01,
            pymvent70_cab_ticket.pymvent70_docnro,
            pymvent70_cab_ticket.pymvent70_neto
        from pymvent51_det_ventas
           inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
           inner join pymvent60_cab_cobro on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
        where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50_param
       into
        :rela_pymvent70,
        :rela_socusua01_vend,
        :id_pymvent51,
        :id_pymvent60,
        :pymvent51_cancelado,
        :rela_sicingr01,
        :pymvent70_docnro,
        :pymvent70_total
       do begin      /* por cada ticket (rela_pymvent70)*/

           /* Se inicializa las variables */
           cantidad = null;
           ocurrencia = null;
           cant_cance = null;
           importe_cance = null;
           cantidad = null;
           ocurren_cance = null;
           rela_socsyst10_fdp01 = null;
           FormaDePago = null;
           pymvent70_cliente = null;
           rela_socmain01 = null;
           rela_socmain21 = null;
           pymvent51_vendedor = null;

             /* se obtiene la cantidad y ocurrencias de todos los productos */
           select
            sum(pymvent71_det_ticket.pymvent71_cantidad),
            count(pymvent71_det_ticket.id_pymvent71)
            from pymvent71_det_ticket
            where pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
            and pymvent71_det_ticket.pymvent71_cancelado = 0
            into
                :cantidad,
                :ocurrencia;

             /* se obtiene la cantidad e importe de los productos devueltos*/
            if (pymvent51_cancelado = 1) then
            begin
                select
                    sum(pymvent73_mov_cancelados.pymvent73_cantidad),
                    sum(pymvent73_mov_cancelados.pymvent73_importe)
                    from pymvent71_det_ticket
                       inner join pymvent73_mov_cancelados on ( pymvent71_det_ticket.id_pymvent71 = pymvent73_mov_cancelados.rela_pymvent71)
                    where pymvent73_mov_cancelados.rela_pymvent70 = :rela_pymvent70
                    into
                        :cant_cance,
                        :importe_cance;
    
                if (cant_cance is not null) then
                begin
                   cantidad = cantidad - cant_cance;
                   pymvent70_total = pymvent70_total - importe_cance;
                end
    
                 /* se obtiene las ocurrencias de los productos cancelados*/
                select
                    count(pymvent73_mov_cancelados.pymvent73_cantidad)
                    from pymvent71_det_ticket
                       inner join pymvent73_mov_cancelados on ( pymvent71_det_ticket.id_pymvent71 = pymvent73_mov_cancelados.rela_pymvent71)
                    where pymvent73_mov_cancelados.rela_pymvent70 = :rela_pymvent70
                    and pymvent73_mov_cancelados.pymvent73_cantidad = pymvent71_det_ticket.pymvent71_cantidad
                    into
                        :ocurren_cance;
                 ocurrencia = ocurrencia - ocurren_cance;
            end

            /* Se obtiene la forma de la pago. Se selecciona aquella con el mayor monto que se pagó */
           select first 1
                    pymvent61_det_cobro.rela_socsyst10_fdp01
                from  pymvent61_det_cobro
                   inner join pymvent60_cab_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
                   inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
                   inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70 )
                        WHERE pymvent51_det_ventas.rela_pymvent70 = :rela_pymvent70
                group by pymvent61_det_cobro.pymvent61_valor, pymvent61_det_cobro.rela_socsyst10_fdp01
                order by pymvent61_det_cobro.pymvent61_valor Desc
            into
                :rela_socsyst10_fdp01;

          select CBO_SOCSYST10_FDP01.socsyst10_codigo
            from CBO_SOCSYST10_FDP01
            where CBO_SOCSYST10_FDP01.id_socsyst10 = :rela_socsyst10_fdp01
            into
                :FormaDePago;

           /* Se obtiene el cliente (entidad) y el vendedor*/
           select cbo_sicingr01_id.entidad
             from cbo_sicingr01_id
             where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
             into :pymvent70_cliente;
            pymvent70_cliente = iif(pymvent70_cliente is null, 'Venta Consumidor Final', pymvent70_cliente);


            select pymvent50_cab_apertura.rela_socmain01,
                pymvent50_cab_apertura.rela_socmain21
                from pymvent50_cab_apertura
                where pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50_param
                into
                    :rela_socmain01,
                    :rela_socmain21;

            select CBO_SOCUSUA01.entidad
              from CBO_SOCUSUA01(:rela_socmain01, :rela_socmain21, :rela_socusua01_vend)
              into :pymvent51_vendedor;

            suspend;
       end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_PYMVENT72 (
    ID_PYMVENT50_PARAM BIGINT)
RETURNS (
    TOTAL_IMPORTE DOUBLE PRECISION,
    PYMVENT72_IMPUESTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT72_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT72_TASAOCUOTA DOUBLE PRECISION,
    PYMVENT72_FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
   for select 
        sum( pymvent72_det_impuestos.pymvent72_importe ) sum_of_pymvent72_importe,
        pymvent72_det_impuestos.pymvent72_tipo,
        pymvent72_det_impuestos.pymvent72_impuesto,
        pymvent72_det_impuestos.pymvent72_tasaocuota,
        pymvent72_det_impuestos.pymvent72_factor
    from pymvent51_det_ventas
       inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
       inner join pymvent71_det_ticket on (pymvent70_cab_ticket.id_pymvent70 = pymvent71_det_ticket.rela_pymvent70)
       inner join pymvent72_det_impuestos on (pymvent71_det_ticket.id_pymvent71 = pymvent72_det_impuestos.rela_pymvent71)
    where   pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50_param
    group by pymvent72_det_impuestos.pymvent72_tipo, pymvent72_det_impuestos.pymvent72_impuesto, pymvent72_det_impuestos.pymvent72_tasaocuota, pymvent72_det_impuestos.pymvent72_factor, pymvent51_det_ventas.rela_pymvent50
    into :total_importe,
         :pymvent72_tipo,
         :pymvent72_impuesto,
         :pymvent72_tasaocuota,
         :pymvent72_factor
     do begin

       suspend;
     end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_PYMVENT73 (
    ID_PYMVENT50_PARAM BIGINT)
RETURNS (
    RELA_PYMVENT70 BIGINT,
    RELA_PYMVENT50 BIGINT,
    ID_PYMVENT51 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT73_CANTIDAD DOUBLE PRECISION,
    OCURRENCIA INTEGER,
    PYMVENT73_IMPORTE_TOTAL DOUBLE PRECISION,
    FORMADEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_VENDEDOR VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCUSUA01_VEND bigint;
declare variable RELA_SICINGR01 bigint;
declare variable MONTO double precision;
declare variable RELA_SOCSYST10_FDP01 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN21 bigint;
begin
    for select 
            pymvent51_det_ventas.rela_pymvent70,
            pymvent51_det_ventas.rela_pymvent50,
            pymvent51_det_ventas.rela_socusua01_vend,
            pymvent51_det_ventas.id_pymvent51,
            pymvent70_cab_ticket.rela_sicingr01,
            pymvent70_cab_ticket.pymvent70_docnro
        from pymvent51_det_ventas
           inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
           inner join pymvent50_cab_apertura on (pymvent51_det_ventas.rela_pymvent50 = pymvent50_cab_apertura.id_pymvent50)
        where pymvent50_cab_apertura.id_pymvent50 = :ID_PYMVENT50_PARAM and
            pymvent51_det_ventas.pymvent51_cancelado = 1
        into
            :rela_pymvent70,
            :rela_pymvent50,
            :rela_socusua01_vend,
            :id_pymvent51,
            :rela_sicingr01,
            :pymvent70_docnro
        do begin
            /* Se obtiene la cantidad, ocurrencia y total de productos cancelados */
            select
                sum(pymvent73_mov_cancelados.pymvent73_cantidad),
                count(pymvent73_mov_cancelados.id_pymvent73),
                sum(pymvent73_mov_cancelados.pymvent73_importe)
            from pymvent73_mov_cancelados
            where pymvent73_mov_cancelados.rela_pymvent70 = :rela_pymvent70
            into
                :pymvent73_cantidad,
                :ocurrencia,
                :pymvent73_importe_total;

            /* Se obtiene la forma de la pago. Se selecciona aquella con el mayor monto que se pagó */
            select
                MAX(pymvent61_det_cobro.pymvent61_valor) AS MONTO,
                pymvent61_det_cobro.rela_socsyst10_fdp01
            from  pymvent61_det_cobro
               inner join pymvent60_cab_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
            WHERE pymvent61_det_cobro.rela_pymvent60 IN
                (select 
                        pymvent60_cab_cobro.id_pymvent60
                    from pymvent60_cab_cobro
                       inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
                    WHERE pymvent51_det_ventas.rela_pymvent70 = :rela_pymvent70)
            group by pymvent61_det_cobro.rela_socsyst10_fdp01
            order by MONTO desc
            rows 1
            into :monto,
                 :rela_socsyst10_fdp01;

            select CBO_SOCSYST10_FDP01.socsyst10_codigo
            from CBO_SOCSYST10_FDP01
            where CBO_SOCSYST10_FDP01.id_socsyst10 = :rela_socsyst10_fdp01
            into  :FormaDePago;
    
            /* Se obtiene el cliente (entidad) y el vendedor*/
            select cbo_sicingr01_id.entidad
            from cbo_sicingr01_id
            where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
            into :pymvent70_cliente;
    
            select pymvent50_cab_apertura.rela_socmain01,
                pymvent50_cab_apertura.rela_socmain21
            from pymvent50_cab_apertura
            where pymvent50_cab_apertura.id_pymvent50 = :id_pymvent50_param
            into :rela_socmain01,
                 :rela_socmain21;
    
            select CBO_SOCUSUA01.entidad
            from CBO_SOCUSUA01(:rela_socmain01, :rela_socmain21, :rela_socusua01_vend)
            into :pymvent51_vendedor;

            suspend;
        end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_SAL (
    ID_PYMVENT50_PARAM BIGINT,
    P_SOCMAIN01 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT50 BIGINT,
    PYMVENT50_IMPORTE_APERTURA DOUBLE PRECISION,
    PYMVENT50_IMPORTE_VENTA DOUBLE PRECISION,
    PYMVENT50_FAPERTURA TIMESTAMP,
    PYMVENT50_FCIERRE TIMESTAMP,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE_CAJ VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT55_IMPORTE DOUBLE PRECISION,
    PYMVENT55_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCSYST10_PVC01 bigint;
declare variable RELA_SOCUSUA30 bigint;
begin
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    /* Se obtiene los datos del encabezado */
    for select
         pymvent50_cab_apertura.rela_socmain21,
         pymvent50_cab_apertura.id_pymvent50,
         pymvent50_cab_apertura.pymvent50_importe_apertura,
         pymvent50_cab_apertura.pymvent50_importe_venta,
         pymvent50_cab_apertura.pymvent50_fapertura,
         pymvent50_cab_apertura.pymvent50_fcierre,
         socmain21_arb_organizacion.socmain21_descripcion,
         pymvent01_cab_cajas.rela_socusua01_caje,
         pymvent01_cab_cajas.rela_socsyst10_pvc01
        from pymvent50_cab_apertura
        inner join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = pymvent50_cab_apertura.rela_socmain21)
        inner join pymvent01_cab_cajas on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
        where pymvent50_cab_apertura.id_pymvent50 = :ID_PYMVENT50_PARAM
        into :rela_socmain21,
             :id_pymvent50,
             :pymvent50_importe_apertura,
             :pymvent50_importe_venta,
             :pymvent50_fapertura,
             :pymvent50_fcierre,
             :socmain21_descripcion,
             :rela_socusua01_caje,
             :rela_socsyst10_pvc01
        do begin
            /* Se inicializan las variables */
            socsyst10_descripcion = null;
            NOMBRE_CAJ = null;

          /* obtenemos la descripcion de la caja */
          select CBO_SOCSYST10_PVC01.socsyst10_descripcion
              from CBO_SOCSYST10_PVC01
              where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
              into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
         SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:P_SOCMAIN01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;



          for select pymvent55_mov_moventsal.rela_socusua30,
              pymvent55_mov_moventsal.pymvent55_importe,
              pymvent55_mov_moventsal.pymvent55_notas
            from pymvent55_mov_moventsal
            where pymvent55_mov_moventsal.rela_pymvent50 = :id_pymvent50_param and ((pymvent55_mov_moventsal.pymvent55_importe > 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 4 and
            pymvent55_mov_moventsal.rela_pymvent70 is null)  or
            (pymvent55_mov_moventsal.pymvent55_importe < 0 and  pymvent55_mov_moventsal.pymvent55_pagoticket = 0))

            into :RELA_SOCUSUA30,
                :PYMVENT55_IMPORTE,
                :PYMVENT55_NOTAS
            do begin
                /* Se inicializan las variables */
                cliente = null;

                PYMVENT55_IMPORTE = iif(PYMVENT55_IMPORTE < 0, (-1)*PYMVENT55_IMPORTE, PYMVENT55_IMPORTE);

                /* Se obtiene el nombre del cliente */
                select ENTIDAD from CBO_SOCUSUA30_ALL where ID_SOCUSUA30 = :RELA_SOCUSUA30
                into :cliente;
              suspend;
            end
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_SOCSYST10_FDP (
    ID_PYMVENT50_PARAM BIGINT)
RETURNS (
    FORMADEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL_VENTA DOUBLE PRECISION)
AS
declare variable RELA_SOCSYST10_FDP01 bigint;
begin
  for select
        sum(pymvent61_det_cobro.pymvent61_valor),
        pymvent61_det_cobro.rela_socsyst10_fdp01
    from pymvent61_det_cobro
       inner join pymvent60_cab_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
       inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
    WHERE     pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50_param
    group by  pymvent61_det_cobro.rela_socsyst10_fdp01
    into
        :total_venta,
        :rela_socsyst10_fdp01
    do begin
       select CBO_SOCSYST10_FDP01.socsyst10_descripcion
            from CBO_SOCSYST10_FDP01
            where CBO_SOCSYST10_FDP01.id_socsyst10 = :rela_socsyst10_fdp01
            into  :FormaDePago;
       suspend;
       end 
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT50_TICKETS (
    ID_PYMVENT50 BIGINT)
RETURNS (
    ID_PYMVENT70 INTEGER,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_SUBTOTAL DOUBLE PRECISION,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_LOCALES DOUBLE PRECISION,
    PYMVENT70_TOTAL_IMPUESTOS DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA TIMESTAMP,
    FACTURA_CANCELADA VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FACTURA_GLOBAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_PYMVENT62 bigint;
declare variable PYMVENT62_CANCELADO integer;
declare variable IMPORTE_DEVOLUCION double precision;
begin
    for select
    pymvent70_cab_ticket.id_pymvent70,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_subtotal,
    pymvent70_cab_ticket.pymvent70_descuento,
    pymvent70_cab_ticket.pymvent70_total,
    pymvent70_cab_ticket.pymvent70_totimp_retenidos,
    pymvent70_cab_ticket.pymvent70_totimp_traslados,
    pymvent70_cab_ticket.pymvent70_totimp_locales,
    pymvent70_cab_ticket.pymvent70_neto
    from pymvent51_det_ventas
    inner join pymvent70_cab_ticket on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
    inner join pymvent60_cab_cobro on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
    where pymvent51_det_ventas.rela_pymvent50 = :id_pymvent50
    and pymvent51_det_ventas.pymvent51_fvencido is null
    and pymvent51_det_ventas.pymvent51_fcerrado is not null
    into :id_pymvent70,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_subtotal,
         :pymvent70_descuento,
         :pymvent70_total,
         :pymvent70_totimp_retenidos,
         :pymvent70_totimp_traslados,
         :pymvent70_totimp_locales,
         :pymvent70_neto
    do
    begin
        factura_global = 'No';
        factura_cancelada = 'No';
        sicingr70_docnro = null;
        sicingr70_fecha = null;
        pymvent62_cancelado = null;

        pymvent70_total_impuestos =  pymvent70_totimp_retenidos +
                                     pymvent70_totimp_traslados +
                                     pymvent70_totimp_locales;

        select
        max(pymvent62_dep_facturacion.id_pymvent62)
        from pymvent62_dep_facturacion
        where pymvent62_dep_facturacion.rela_pymvent70 = :id_pymvent70
        into :id_pymvent62;

        if (id_pymvent62 is not null) then
        begin
            select
            sicingr70_cab_facturacion.sicingr70_docnro,
            sicingr70_cab_facturacion.sicingr70_fecha,
            pymvent62_dep_facturacion.pymvent62_cancelado
            from pymvent62_dep_facturacion
            inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = pymvent62_dep_facturacion.rela_sicingr70)
            where pymvent62_dep_facturacion.id_pymvent62 = :id_pymvent62
            into :sicingr70_docnro,
                 :sicingr70_fecha,
                 :pymvent62_cancelado;
    
            if (pymvent62_cancelado = 1) then
                factura_cancelada = 'Si';

        end
        else
        begin
            select
            sicingr70_cab_facturacion.sicingr70_docnro,
            sicingr70_cab_facturacion.sicingr70_fecha
            from pymvent81_det_factglobal
            inner join pymvent80_cab_factglobal on ( pymvent80_cab_factglobal.id_pymvent80 = pymvent81_det_factglobal.rela_pymvent80 )
            inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = pymvent80_cab_factglobal.rela_sicingr70 )
            where pymvent81_det_factglobal.rela_pymvent70 = :id_pymvent70
            into :sicingr70_docnro,
                 :sicingr70_fecha;

            if (sicingr70_docnro is not null) then
                factura_global = 'Si';
        end

        select sum(pymvent73_mov_cancelados.pymvent73_importe)
        from pymvent73_mov_cancelados
        where pymvent73_mov_cancelados.rela_pymvent70 = :id_pymvent70
        into :importe_devolucion;
        importe_devolucion = iif(importe_devolucion is null, 0.00, importe_devolucion);

        if (importe_devolucion <> 0) then
            pymvent70_neto = pymvent70_neto - importe_devolucion;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT55 (
    P_SOCMAIN01 BIGINT,
    P_SALDO INTEGER)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR01 BIGINT,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CREDITO DOUBLE PRECISION,
    MON_ELECTRO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION)
AS
declare variable DEVUELTO double precision;
begin
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    /* Obtenemos los clientes de la empresa que hayan realizado alguna compra
    con pago 99*/
  FOR select distinct(pymvent70_cab_ticket.rela_sicingr01)
        from pymvent51_det_ventas
           inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
           inner join pymvent61_det_cobro on (pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
           inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent61_det_cobro.rela_socsyst10_fdp01 = 54661) and
        pymvent70_cab_ticket.rela_socmain01 = :p_socmain01
  into :id_sicingr01
  do begin
        /* Se inicializan las variables */
         entidad = null;
         rfc = null;
         credito = null;
         mon_electro = null;
         saldo = null;

        /* Por cada Cliente */
         /* Obtenemos el nombre/razon social y RFC del cliente */
        SELECT
            CBO_SICINGR01_ID.entidad,
            CBO_SICINGR01_ID.rfc
          FROM CBO_SICINGR01_ID
          WHERE CBO_SICINGR01_ID.id_sicingr01 = :id_sicingr01
          into :entidad,
               :rfc;

        /* Obtenemos el credito que posee el cliente */
        select sum(pymvent55_mov_moventsal.pymvent55_importe)
        from pymvent55_mov_moventsal
           inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and
              pymvent70_cab_ticket.rela_sicingr01 = :id_sicingr01)
        into :credito;

        credito = iif(credito is null, 0.00, (-1)*credito);

        --HV: 08/05/2019, se calcula los montos de productos cancelados de creditos
        select sum(pymvent55_mov_moventsal.pymvent55_importe)*(-1)
        from pymvent55_mov_moventsal
           inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent55_mov_moventsal.pymvent55_pagoticket = 6 and
              pymvent70_cab_ticket.rela_sicingr01 = :id_sicingr01)
        into :devuelto;

        credito = credito - devuelto;


        /* Obetenemos el monto en monedero electrónico */
        SELECT PRD_PYMVENT60_SALDOS_CLIENTES.saldo
           FROM PRD_PYMVENT60_SALDOS_CLIENTES(:id_sicingr01)
        into :mon_electro;

        /* Calculamos el saldo del cliente */
        saldo =  credito -  mon_electro;

        /* Se pregunta si se filtra por saldo ceros, positivos o negativos */
        if ((:p_saldo = -1)  or (:p_saldo = 0 and saldo = 0)
            or (:p_saldo = 1 and saldo > 0)
            or (:p_saldo = 2 and saldo < 0) ) then
        begin
              suspend;
        end

  end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT55_CLIENTE (
    P_SOCMAIN01 BIGINT,
    P_ID_SICINGR01 BIGINT,
    P_SALDO INTEGER,
    TIPO INTEGER)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SICINGR01 BIGINT,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MON_ELECTRO DOUBLE PRECISION,
    ID_PYMVENT70 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT61_VALOR DOUBLE PRECISION,
    PAGO_TICKET DOUBLE PRECISION,
    SALDO_TICKET DOUBLE PRECISION,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    if (P_ID_SICINGR01 = -1) then /* Se requiere todos los clientes */
    begin
        /* Obtenemos los clientes de la empresa que hayan realizado alguna compra
        con pago 99*/
      FOR select distinct(pymvent70_cab_ticket.rela_sicingr01)
        from pymvent51_det_ventas
           inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
           inner join pymvent61_det_cobro on (pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
           inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent61_det_cobro.rela_socsyst10_fdp01 = 54661) and
        pymvent70_cab_ticket.rela_socmain01 = :p_socmain01
          into :rela_sicingr01
          do begin
            /* Por cada cliente, se obtiene sus detalles, junto con sus tickets */

            /* Se condiciona el tipo de reporte que se desea: 0 es cartera detallada
            de clientes, 1 es Kardex de los clientes */
            if (tipo = 0) then
            begin
               for select * from REP_PYMVENT55_CLIENTE_DETALLE(:rela_sicingr01,:p_saldo)
               into :mon_electro,
                 :entidad,
                 :rfc,
                 :id_pymvent70,
                 :pymvent70_docnro,
                 :pymvent70_fecha,
                 :pymvent61_valor,
                 :pago_ticket,
                 :saldo_ticket
                 do begin
                    suspend;
                 end
            end
            else
            begin
              for select * from REP_PYMVENT55_CLIENTE_KARDEX(:rela_sicingr01,:p_saldo)
              into :mon_electro,
                 :entidad,
                 :rfc,
                 :id_pymvent70,
                 :RELA_SOCMAIN21,
                 :pymvent70_docnro,
                 :pymvent70_fecha,
                 :pymvent61_valor,
                 :PAGO_TICKET,
                 :saldo_ticket,
                 :SOCMAIN21_DESCRIPCION
                 do begin
                    suspend;
                 end
             end
          end
    end
    else
    begin
        /* Como se quiere un sólo cliente, se obtiene los datos del mismo.*/
        rela_sicingr01 = :p_id_sicingr01;

        /* Se condiciona el tipo de reporte que se desea: 0 es cartera detallada
            de clientes, 1 es Kardex de los clientes */
            if (tipo = 0) then
            begin
               for select * from REP_PYMVENT55_CLIENTE_DETALLE(:rela_sicingr01,:p_saldo)
               into :mon_electro,
                 :entidad,
                 :rfc,
                 :id_pymvent70,
                 :pymvent70_docnro,
                 :pymvent70_fecha,
                 :pymvent61_valor,
                 :pago_ticket,
                 :saldo_ticket
                 do begin
                    suspend;
                 end
            end
            else
            begin
              for select * from REP_PYMVENT55_CLIENTE_KARDEX(:rela_sicingr01,:p_saldo)
              into :mon_electro,
                 :entidad,
                 :rfc,
                 :id_pymvent70,
                 :RELA_SOCMAIN21,
                 :pymvent70_docnro,
                 :pymvent70_fecha,
                 :pymvent61_valor,
                 :PAGO_TICKET,
                 :saldo_ticket,
                 :SOCMAIN21_DESCRIPCION
                 do begin
                    suspend;
                 end
             end
    end
 end^


CREATE OR ALTER PROCEDURE REP_PYMVENT55_CLIENTE_DETALLE (
    P_ID_SICINGR01 BIGINT,
    P_SALDO INTEGER)
RETURNS (
    MON_ELECTRO DOUBLE PRECISION,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT61_VALOR DOUBLE PRECISION,
    PAGO_TICKET DOUBLE PRECISION,
    SALDO_TICKET DOUBLE PRECISION)
AS
declare variable CREDITO double precision;
declare variable SALDO double precision;
declare variable DEVUELTO double precision;
begin

     /* Obtenemos el monto en monedero electrónico, dado que esto siempre se
     hace sin importar el filtro de saldo*/
     SELECT PRD_PYMVENT60_SALDOS_CLIENTES.saldo
       FROM PRD_PYMVENT60_SALDOS_CLIENTES(:p_id_sicingr01)
     into :mon_electro;
    
     mon_electro = iif(mon_electro is null, 0.00, mon_electro);

     /* Si se quiere filtrar por saldo (p_saldo != -1), se procede a calcular el saldo del cliente) */

     if (:p_saldo != -1) then
     begin

        /* Obtenemos el credito que posee el cliente */
        select sum(pymvent55_mov_moventsal.pymvent55_importe)
        from pymvent55_mov_moventsal
           inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and
              pymvent70_cab_ticket.rela_sicingr01 = :P_ID_SICINGR01)
        into :credito;

        credito = iif(credito is null, 0.00, (-1)*credito);

        --HV: 08/05/2019, se calcula los montos de productos cancelados de creditos
        select sum(pymvent55_mov_moventsal.pymvent55_importe)*(-1)
        from pymvent55_mov_moventsal
           inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent55_mov_moventsal.pymvent55_pagoticket = 6 and
              pymvent70_cab_ticket.rela_sicingr01 = :P_ID_SICINGR01)
        into :devuelto;

        credito = credito - devuelto;


        /* Calculamos el saldo del cliente */
        saldo =  credito - mon_electro;
    end

    /* Se pregunta si se filtra por saldo ceros, positivos o negativos,
    o sin filtro (p_saldo = -1) */
    if ((:p_saldo = -1)  or (:p_saldo = 0 and saldo = 0)
        or (:p_saldo = 1 and saldo > 0)
        or (:p_saldo = 2 and saldo < 0) ) then
    begin
        /* Obtenemos el nombre/Razon social y RFC del cliente */
        SELECT
            CBO_SICINGR01_ID.entidad,
            CBO_SICINGR01_ID.rfc
         FROM CBO_SICINGR01_ID
         WHERE CBO_SICINGR01_ID.id_sicingr01 = :p_id_sicingr01
         into :entidad,
              :rfc;

         /* Obtenemos los tickets pagados con forma de pago 99 (credito) */
        for select pymvent70_cab_ticket.id_pymvent70,
            pymvent70_cab_ticket.pymvent70_docnro,
            pymvent70_cab_ticket.pymvent70_fecha,
            pymvent61_det_cobro.pymvent61_valor
        from pymvent70_cab_ticket
           inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
           inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
           inner join pymvent61_det_cobro on (pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
        where (pymvent61_det_cobro.rela_socsyst10_fdp01 = 54661) and
                (pymvent70_cab_ticket.rela_sicingr01 = :p_id_sicingr01)
        into  :id_pymvent70,
              :pymvent70_docnro,
              :pymvent70_fecha,
              :pymvent61_valor
        do begin
            /* Obtenemos los pagos abonados a cada ticket */
            select sum(pymvent55_mov_moventsal.pymvent55_importe)
            from pymvent55_mov_moventsal
               inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
            where (pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and
                  pymvent55_mov_moventsal.pymvent55_importe > 0 and
                  pymvent70_cab_ticket.id_pymvent70 = :id_pymvent70)
            into :pago_ticket;
    
            pago_ticket = iif(pago_ticket is null, 0.00, pago_ticket);
    
            /* Calculamos el saldo del ticket */
            saldo_ticket = :pymvent61_valor - :pago_ticket;
    
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT55_CLIENTE_KARDE_PAG (
    P_ID_SICINGR01 BIGINT,
    P_ID_PYMVENT70 BIGINT)
RETURNS (
    ID_PYMVENT55 BIGINT,
    PYMVENT55_FAPL TIMESTAMP,
    PYMVENT55_IMPORTE DOUBLE PRECISION,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN21 bigint;
begin
  for select 
        pymvent55_mov_moventsal.id_pymvent55,
        pymvent55_mov_moventsal.pymvent55_fapl,
        pymvent55_mov_moventsal.pymvent55_importe,
        pymvent50_cab_apertura.rela_socmain21
    from pymvent50_cab_apertura
       inner join pymvent55_mov_moventsal on (pymvent50_cab_apertura.id_pymvent50 = pymvent55_mov_moventsal.rela_pymvent50)
       inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    where pymvent55_mov_moventsal.pymvent55_pagoticket = 3  and pymvent55_mov_moventsal.pymvent55_importe > 0 and
          pymvent70_cab_ticket.id_pymvent70 = :p_id_pymvent70 and pymvent70_cab_ticket.rela_sicingr01 = :p_id_sicingr01
    into :id_pymvent55,
        :pymvent55_fapl,
        :pymvent55_importe,
        :rela_socmain21
    do begin
        /* Obtenemos la descripcion de la organizacion*/
        select SOCMAIN21_ARB_ORGANIZACION.socmain21_descripcion
        from SOCMAIN21_ARB_ORGANIZACION
        where SOCMAIN21_ARB_ORGANIZACION.id_socmain21 = :rela_socmain21
        into :SOCMAIN21_DESCRIPCION;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT55_CLIENTE_KARDEX (
    P_ID_SICINGR01 BIGINT,
    P_SALDO INTEGER)
RETURNS (
    MON_ELECTRO DOUBLE PRECISION,
    ENTIDAD VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT70 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT61_VALOR DOUBLE PRECISION,
    PAGO_TICKET DOUBLE PRECISION,
    SALDO_TICKET DOUBLE PRECISION,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable DEVUELTO double precision;
begin
       /* Obtenemos el monto en monedero electrónico */
    SELECT PRD_PYMVENT60_SALDOS_CLIENTES.saldo
       FROM PRD_PYMVENT60_SALDOS_CLIENTES(:p_id_sicingr01)
    into :mon_electro;

    /* Obtenemos el nombre/Razon social del cliente */
    SELECT
        CBO_SICINGR01_ID.entidad,
        CBO_SICINGR01_ID.rfc
     FROM CBO_SICINGR01_ID
     WHERE CBO_SICINGR01_ID.id_sicingr01 = :p_id_sicingr01
     into :entidad,
          :rfc;

     /* Obtenemos los tickets pagados con forma de pago 99 (credito) */
    for select pymvent70_cab_ticket.id_pymvent70,
        pymvent70_cab_ticket.rela_socmain21,
        pymvent70_cab_ticket.pymvent70_docnro,
        pymvent70_cab_ticket.pymvent70_fecha,
        pymvent61_det_cobro.pymvent61_valor
    from pymvent70_cab_ticket
       inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
       inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
       inner join pymvent61_det_cobro on (pymvent60_cab_cobro.id_pymvent60 = pymvent61_det_cobro.rela_pymvent60)
    where (pymvent61_det_cobro.rela_socsyst10_fdp01 = 54661 and
            pymvent70_cab_ticket.rela_sicingr01 = :p_id_sicingr01)
    into :id_pymvent70,
          :rela_socmain21,
          :pymvent70_docnro,
          :pymvent70_fecha,
          :pymvent61_valor
    do begin
        /* Se inicializan las variables */
        pago_ticket = null;
        saldo_ticket = null;

        /* Obtenemos los pagos abonados a cada ticket */
        select sum(pymvent55_mov_moventsal.pymvent55_importe)
        from pymvent55_mov_moventsal
           inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent55_mov_moventsal.pymvent55_pagoticket = 3 and
              pymvent55_mov_moventsal.pymvent55_importe > 0 and
              pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70)
        into :pago_ticket;

        pago_ticket = iif(pago_ticket is null, 0.00, pago_ticket);

        /* Calculamos el saldo del ticket */
        saldo_ticket = :pymvent61_valor - :pago_ticket;

        --HV: 08/05/2019, se calcula los montos de productos cancelados de creditos
        select sum(pymvent55_mov_moventsal.pymvent55_importe)*(-1)
        from pymvent55_mov_moventsal
           inner join pymvent70_cab_ticket on (pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
        where (pymvent55_mov_moventsal.pymvent55_pagoticket = 6 and
              pymvent70_cab_ticket.rela_sicingr01 = :p_id_sicingr01)
        into :devuelto;

        saldo_ticket = saldo_ticket - devuelto;

         /* Se pregunta si se filtra por saldo ceros, positivos o negativos,
        o sin filtro (p_saldo = -1) */
        if ((:p_saldo = -1)  or (:p_saldo = 0 and saldo_ticket > 0)
            or (:p_saldo = 1 and saldo_ticket = 0)) then
        begin
             /* Obtenemos la descripcion de la organizacion*/
            select SOCMAIN21_ARB_ORGANIZACION.socmain21_descripcion
            from SOCMAIN21_ARB_ORGANIZACION
            where SOCMAIN21_ARB_ORGANIZACION.id_socmain21 = :rela_socmain21
            into :SOCMAIN21_DESCRIPCION;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT70 (
    P_PYMVENT70 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOEXTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOINTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_LOCALIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_MUNICIPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_PAIS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REG_FISCAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE_CAJ VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA TIMESTAMP,
    PYMVENT70_SUBTOTAL DOUBLE PRECISION,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_LOCALES DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT70_CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_FVENCIDO TIMESTAMP,
    RFC_CLIENTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_VENDEDOR VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_TOTAL DOUBLE PRECISION)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCSYST10_PVC01 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCUSUA01_VEND bigint;
declare variable P_SOCMAIN01 bigint;
begin
    select 
        pymvent01_cab_cajas.rela_socmain01
    from pymvent01_cab_cajas
       inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
       inner join pymvent51_det_ventas on (pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50)
       inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70
    into :p_socmain01;


    /* Se obtiene los datos de la Empresa*/
   select CFDI_EMPRESA.RAZSOCIAL,
    CFDI_EMPRESA.rfc,
    CFDI_EMPRESA.domf_calle,
    CFDI_EMPRESA.domf_noexterior,
    CFDI_EMPRESA.domf_nointerior,
    CFDI_EMPRESA.domf_colonia,
    CFDI_EMPRESA.domf_localidad,
    CFDI_EMPRESA.domf_municipio,
    CFDI_EMPRESA.domf_estado,
    CFDI_EMPRESA.domf_pais,
    CFDI_EMPRESA.domf_codpostal
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC,
        :rfc,
        :domf_calle,
        :domf_noexterior,
        :domf_nointerior,
        :domf_colonia,
        :domf_localidad,
        :domf_municipio,
        :domf_estado,
        :domf_pais,
        :domf_codpostal;

       /* Se obtiene el regimen fiscal de la empresa */
        SELECT SOCSYST10_DESCRIPCION
         FROM SOCSYST10_DET_ENTRADAS
         inner join SOCMAIN01_CAB_EMPRESAS on (SOCMAIN01_CAB_EMPRESAS.RELA_SOCSYST10_SAT01 = SOCSYST10_DET_ENTRADAS.id_socsyst10)
         where SOCMAIN01_CAB_EMPRESAS.id_socmain01 = :p_socmain01
         into Reg_Fiscal;

    /* Se obtienen datos de la caja */
    for select 
        pymvent01_cab_cajas.rela_socmain21,
        pymvent01_cab_cajas.rela_socusua01_caje,
        pymvent01_cab_cajas.rela_socsyst10_pvc01
    from pymvent01_cab_cajas
       inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
       inner join pymvent51_det_ventas on (pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50)
       inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70/*$$IBEC$$  and pymvent70_cab_ticket.rela_socmain01 = :p_socmain01 $$IBEC$$*/
    into :rela_socmain21,
         :rela_socusua01_caje,
         :rela_socsyst10_pvc01
    do begin
        /* Inicializacion de variables */
        socmain21_descripcion = null;
        socsyst10_descripcion = null;
        NOMBRE_CAJ = null;
        id_pymvent70 = null;
        rela_sicingr01 = null;
        pymvent70_docnro = null;
        rela_socusua01_vend = null;
        pymvent70_cliente = null;
        pymvent51_vendedor = null;

        /* Se obtiene la descripcion de la Sucursal/Organizacion */
          select socmain21_arb_organizacion.socmain21_descripcion
            from socmain21_arb_organizacion
            where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
            into :socmain21_descripcion;

        /* obtenemos la descripcion de la caja */
        select CBO_SOCSYST10_PVC01.socsyst10_descripcion
          from CBO_SOCSYST10_PVC01
          where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
          into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
        SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:p_socmain01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;

      /* Obtenemos los detalles del ticket y productos*/
      for select  pymvent70_cab_ticket.id_pymvent70,
          pymvent70_cab_ticket.rela_sicingr01,
          pymvent70_cab_ticket.pymvent70_docnro,
          pymvent70_cab_ticket.pymvent70_fecha,
          pymvent70_cab_ticket.pymvent70_subtotal,
          pymvent70_cab_ticket.pymvent70_descuento,
          pymvent70_cab_ticket.pymvent70_total,
          pymvent70_cab_ticket.pymvent70_totimp_retenidos,
          pymvent70_cab_ticket.pymvent70_totimp_traslados,
          pymvent70_cab_ticket.pymvent70_totimp_locales,
          pymvent70_cab_ticket.pymvent70_neto,
          pymvent51_det_ventas.rela_socusua01_vend,
          pymvent51_det_ventas.pymvent51_fvencido
      from pymvent70_cab_ticket
      inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
      where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70 and pymvent70_cab_ticket.rela_socmain01 = :p_socmain01
      into :id_pymvent70,
           :rela_sicingr01,
           :pymvent70_docnro,
           pymvent70_fecha,
           :pymvent70_subtotal,
           :pymvent70_descuento,
           :pymvent70_total,
           :pymvent70_totimp_retenidos,
           :pymvent70_totimp_traslados,
           :pymvent70_totimp_locales,
           :pymvent70_neto,
           :rela_socusua01_vend,
           :pymvent51_fvencido
      do begin
    
           pymvent70_descuento = iif(pymvent70_descuento is null, 0.00, pymvent70_descuento);
           pymvent70_totimp_retenidos = iif(pymvent70_totimp_retenidos is null, 0.00, pymvent70_totimp_retenidos);
           pymvent70_totimp_traslados = iif(pymvent70_totimp_traslados is null, 0.00, pymvent70_totimp_traslados);
           pymvent70_totimp_locales = iif(pymvent70_totimp_locales is null, 0.00, pymvent70_totimp_locales);

          /* Se obtiene el cliente (entidad) y el vendedor*/
           if (rela_sicingr01 is not null) then
               select cbo_sicingr01_id.entidad,
                    cbo_sicingr01_id.rfc
                 from cbo_sicingr01_id
                 where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
                 into :pymvent70_cliente,
                      :rfc_cliente;
           else
           begin
                pymvent70_cliente = 'Venta Consumidor Final';
                rfc_cliente = 'XAXX010101000';
           end

    
            select CBO_SOCUSUA01.entidad
              from CBO_SOCUSUA01(:p_socmain01, :rela_socmain21, :rela_socusua01_vend)
              into :pymvent51_vendedor;

            /* Detalles de los productos */
            for select pymvent71_det_ticket.pymvent71_codigo,
                pymvent71_det_ticket.pymvent71_concepto,
                pymvent71_det_ticket.pymvent71_cantidad,
                pymvent71_det_ticket.pymvent71_importe_unidad,
                pymvent71_det_ticket.pymvent71_importe_subtotal,
                pymvent71_det_ticket.pymvent71_importe_descuento,
                pymvent71_det_ticket.pymvent71_importe_total
             from pymvent71_det_ticket
             where pymvent71_det_ticket.rela_pymvent70 = :p_pymvent70
             and pymvent71_det_ticket.pymvent71_cancelado = 0
             into  :pymvent71_codigo,
                :pymvent71_concepto,
                :pymvent71_cantidad,
                :pymvent71_importe_unidad,
                :pymvent71_importe_subtotal,
                :pymvent71_importe_descuento,
                :pymvent71_importe_total
             do begin
                suspend;
             end
    end

  end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT70_FDP (
    P_PYMVENT70 BIGINT)
RETURNS (
    PYMVENT61_VALOR DOUBLE PRECISION,
    FORMADEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
  for select
        pymvent61_det_cobro.pymvent61_valor,
        (select CBO_SOCSYST10_FDP01.socsyst10_descripcion
            from CBO_SOCSYST10_FDP01
            where CBO_SOCSYST10_FDP01.id_socsyst10 = pymvent61_det_cobro.rela_socsyst10_fdp01)
    from pymvent61_det_cobro
       inner join pymvent60_cab_cobro on (pymvent61_det_cobro.rela_pymvent60 = pymvent60_cab_cobro.id_pymvent60)
       inner join pymvent51_det_ventas on (pymvent60_cab_cobro.rela_pymvent51 = pymvent51_det_ventas.id_pymvent51)
    WHERE     pymvent51_det_ventas.rela_pymvent70 = :p_pymvent70
    into :pymvent61_valor,
         :FormaDePago
    do begin
      suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT70_VENTAS (
    RELA_SOCMAIN01 BIGINT,
    MODALIDAD INTEGER)
RETURNS (
    RELA_SICINGR01 BIGINT,
    ID_PYMVENT70 BIGINT,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_FECHA DATE,
    PYMVENT70_NETO NUMERIC(15,2),
    DEUDA_TOTAL NUMERIC(15,2),
    DEUDA_MONEDERO NUMERIC(15,2),
    DEUDA_APARTADO NUMERIC(15,2),
    DEUDA_SALDO NUMERIC(15,2),
    ORIGEN VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COSTO NUMERIC(15,2),
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE)
AS
declare variable ID_SICINGR95 bigint;
declare variable TEMP_CATEGO varchar(400);
declare variable TEMP_CATEGO_IMPORTE numeric(15,2);
declare variable SQL_INSERT varchar(4000);
declare variable SQL_SELECT varchar(4000);
declare variable SQL_UPDATE varchar(4000);
declare variable CAMPOS_OTROS varchar(1000);
declare variable SUMA_IMPORTE_CATEGO numeric(15,2);
declare variable ID_INTAUTO01 bigint;
declare variable IMPORTE_AJUSTE numeric(15,2);
declare variable IMPORTE_COSTO numeric(15,2);
declare variable PYMVENT71_CANTIDAD numeric(15,2);
declare variable SUMA_COSTO_CATEGO numeric(15,2);
begin
    for select
    pymvent70_cab_ticket.rela_sicingr01,
    pymvent70_cab_ticket.id_pymvent70,
    cbo_sicingr01_id.entidad,
    pymvent70_cab_ticket.pymvent70_docnro,
    pymvent70_cab_ticket.pymvent70_fecha,
    pymvent70_cab_ticket.pymvent70_neto
    from pymvent70_cab_ticket
    inner join cbo_sicingr01_id on (cbo_sicingr01_id.id_sicingr01 = pymvent70_cab_ticket.rela_sicingr01)
    where pymvent70_cab_ticket.rela_socmain01 = :rela_socmain01
    and exists (select first 1 pymvent55_mov_moventsal.id_pymvent55
                from pymvent55_mov_moventsal
                where pymvent55_mov_moventsal.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    order by pymvent70_cab_ticket.id_pymvent70
    into :rela_sicingr01,
         :id_pymvent70,
         :entidad,
         :pymvent70_docnro,
         :pymvent70_fecha,
         :pymvent70_neto
    do
    begin
        sicingr70_docnro = null;
        sicingr70_fecha = null;

        select first 1
        sicingr70_cab_facturacion.sicingr70_docnro,
        sicingr70_cab_facturacion.sicingr70_fecha
        from PYMVENT62_DEP_FACTURACION
        inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = PYMVENT62_DEP_FACTURACION.rela_sicingr70 )
        where PYMVENT62_DEP_FACTURACION.rela_pymvent70 = :id_pymvent70
        into :sicingr70_docnro,
             :sicingr70_fecha;

        id_intauto01 = null;
        origen = 'PVTA';

        select intauto01_cab_servicios.id_intauto01
        from intauto01_cab_servicios
        where intauto01_cab_servicios.rela_pymvent70 = :id_pymvent70
        into :id_intauto01;

        if (id_intauto01 is not null) then
            origen = 'SERV';

        deuda_saldo = 0;
        deuda_total = 0;

        select
        CBO_PYMVENT70_ACREDITO.abono,
        CBO_PYMVENT70_ACREDITO.saldo
        from CBO_PYMVENT70_ACREDITO(:rela_socmain01, :rela_sicingr01)
        where CBO_PYMVENT70_ACREDITO.id_pymvent70 = :id_pymvent70
        into :deuda_total,
             :deuda_saldo;

        if (deuda_total is null) then deuda_total = 0.00;
        if (deuda_saldo is null) then deuda_saldo = 0.00;

        select sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
        from PYMVENT55_MOV_MOVENTSAL
        where PYMVENT55_MOV_MOVENTSAL.rela_pymvent70 = :id_pymvent70
        and PYMVENT55_MOV_MOVENTSAL.pymvent55_pagoticket = 4
        into :deuda_monedero;

        if (deuda_monedero is null) then deuda_monedero = 0.00;

        select sum(PYMVENT55_MOV_MOVENTSAL.pymvent55_importe)
        from PYMVENT55_MOV_MOVENTSAL
        where PYMVENT55_MOV_MOVENTSAL.rela_pymvent70 = :id_pymvent70
        and PYMVENT55_MOV_MOVENTSAL.pymvent55_pagoticket = 5
        into :deuda_apartado;

        if (deuda_apartado is null) then deuda_apartado = 0.00;

        if (deuda_total = 0 and deuda_saldo = 0) then
            deuda_total = :pymvent70_neto;

        /* ===================================================================================================================== */
        /* ===================================================================================================================== */
        /* ===================================================================================================================== */

        if (modalidad = 1) then
        begin
            if (sicingr70_docnro is not null) then
            begin
                campos_otros = 'RELA_SICINGR01,
                                ID_PYMVENT70,
                                ENTIDAD,
                                PYMVENT70_DOCNRO,
                                PYMVENT70_FECHA,
                                PYMVENT70_NETO,
                                DEUDA_TOTAL,
                                DEUDA_MONEDERO,
                                DEUDA_APARTADO,
                                DEUDA_SALDO,
                                ORIGEN,
                                AJUSTE,
                                COSTO,
                                SICINGR70_DOCNRO,
                                SICINGR70_FECHA';

                sql_insert = 'INSERT INTO ' || 'TMP_CROSSTAB_' || current_user || '(' || campos_otros || ') VALUES(' ||
                             rela_sicingr01 || ',' || id_pymvent70 || ',''' || entidad || ''',''' ||
                             pymvent70_docnro || ''',''' || pymvent70_fecha || ''',' ||
                             pymvent70_neto || ',' || deuda_total || ',' || deuda_monedero || ',' ||
                             deuda_apartado || ',' || deuda_saldo || ',''' || origen || ''', 0, 0,''' ||
                             sicingr70_docnro || ''',''' || sicingr70_fecha || ''')';
            end
            else
            begin
                campos_otros = 'RELA_SICINGR01,
                                ID_PYMVENT70,
                                ENTIDAD,
                                PYMVENT70_DOCNRO,
                                PYMVENT70_FECHA,
                                PYMVENT70_NETO,
                                DEUDA_TOTAL,
                                DEUDA_MONEDERO,
                                DEUDA_APARTADO,
                                DEUDA_SALDO,
                                ORIGEN,
                                AJUSTE,
                                COSTO';

                sql_insert = 'INSERT INTO ' || 'TMP_CROSSTAB_' || current_user || '(' || campos_otros || ') VALUES(' ||
                             rela_sicingr01 || ',' || id_pymvent70 || ',''' || entidad || ''',''' ||
                             pymvent70_docnro || ''',''' || pymvent70_fecha || ''',' ||
                             pymvent70_neto || ',' || deuda_total || ',' || deuda_monedero || ',' ||
                             deuda_apartado || ',' || deuda_saldo || ',''' || origen || ''', 0, 0)';
            end

            execute statement :sql_insert;

            importe_ajuste = 0;
            costo = 0;
    
            for select
            sicingr95_cab_conceptos.id_sicingr95,
            pymvent71_det_ticket.pymvent71_importe_neto,
            pymvent71_det_ticket.pymvent71_cantidad
            from pymvent71_det_ticket
            inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = pymvent71_det_ticket.rela_sicingr95 )
            where pymvent71_det_ticket.rela_pymvent70 = :id_pymvent70
            and pymvent71_det_ticket.pymvent71_cancelado = 0
            into :id_sicingr95,
                 :temp_catego_importe,
                 :pymvent71_cantidad
            do
            begin
                importe_costo = null;
    
                select first 1 sicingr98_det_importes.sicingr98_importe
                from sicingr98_det_importes
                inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01 )
                where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95
                and socsyst10_det_entradas.socsyst10_codigo = 'CONCEP-XMARGEN'
                order by sicingr98_det_importes.id_sicingr98 desc
                into :importe_costo;
    
                if (importe_costo is null) then
                    importe_costo = 0;
    
                costo = costo + (importe_costo * pymvent71_cantidad);
    
                importe_ajuste = importe_ajuste + temp_catego_importe;
    
                select first 1 socsyst12_det_cla.socsyst12_descripcion
                from sicingr97_det_clasificacion
                inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
                inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
                where sicingr97_det_clasificacion.rela_sicingr95 = :id_sicingr95
                and socsyst10_det_entradas.socsyst10_codigo = 'CATEGORIA'
                ORDER by sicingr97_det_clasificacion.id_sicingr97 desc
                into :temp_catego;
    
                sql_select = 'select ' || temp_catego || ', ' || temp_catego || '_C from TMP_CROSSTAB_' || current_user ||
                             ' where id_pymvent70 = ' || :id_pymvent70;
    
                execute statement :sql_select into :suma_importe_catego, :suma_costo_catego;
    
                if (suma_importe_catego is null) then suma_importe_catego = 0.00;
                if (suma_costo_catego is null) then suma_costo_catego = 0.00;
    
                suma_importe_catego = suma_importe_catego + temp_catego_importe;
                suma_costo_catego = suma_costo_catego + (importe_costo * pymvent71_cantidad);
    
                sql_update = 'update ' || 'TMP_CROSSTAB_' || current_user || ' set ' || temp_catego || ' = ' || :suma_importe_catego ||
                             ',' || temp_catego || '_C = ' || :suma_costo_catego ||
                             ' where id_pymvent70 = ' || :id_pymvent70;
    
                execute statement :sql_update;
            end
    
            importe_ajuste = pymvent70_neto - importe_ajuste;
    
            sql_update = 'update ' || 'TMP_CROSSTAB_' || current_user || ' set AJUSTE  = ' || :importe_ajuste ||
                         ', costo = ' || :costo || ' where id_pymvent70 = ' || :id_pymvent70;
    
            execute statement :sql_update;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT70_VENTAS_CROSS
RETURNS (
    OK INTEGER)
AS
declare variable CAMPOS varchar(400);
declare variable CAMPOS_LISTA varchar(2000);
declare variable SQL_CREATE varchar(4000);
declare variable FIND_TABLE varchar(1000);
declare variable CAMPOS_OTROS varchar(4000);
begin
    campos_lista = '';

    for select distinct socsyst12_det_cla.socsyst12_descripcion
    from sicingr97_det_clasificacion
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01 )
    inner join socsyst12_det_cla on ( socsyst12_det_cla.id_socsyst12 = sicingr97_det_clasificacion.rela_socsyst12 )
    where socsyst10_det_entradas.socsyst10_codigo = 'CATEGORIA'
    order by socsyst12_det_cla.socsyst12_descripcion desc
    into :campos
    do
    begin
        campos_lista = campos_lista || :campos || ' numeric(15,2) DEFAULT 0,';
        campos_lista = campos_lista || :campos || '_C numeric(15,2) DEFAULT 0,';
    end

    campos_lista = SUBSTRING (campos_lista FROM 1 FOR CHAR_LENGTH (campos_lista) - 1);

    find_table = null;

    SELECT 1 FROM RDB$RELATIONS
    WHERE RDB$RELATION_NAME = 'TMP_CROSSTAB_' || current_user
    INTO :find_table;

    if (find_table is not null) then
    begin
        sql_create = 'DROP TABLE ' || 'TMP_CROSSTAB_' || current_user;
        execute statement :sql_create;
    end

    campos_otros = 'RELA_SICINGR01 bigint,
                    ID_PYMVENT70 bigint NOT NULL,
                    ENTIDAD varchar(1200),
                    PYMVENT70_DOCNRO varchar(50),
                    PYMVENT70_FECHA date,
                    PYMVENT70_NETO numeric(15,2),
                    DEUDA_TOTAL numeric(15,2),
                    DEUDA_MONEDERO numeric(15,2),
                    DEUDA_APARTADO numeric(15,2),
                    DEUDA_SALDO numeric(15,2),
                    ORIGEN varchar(10),
                    AJUSTE numeric(15,2),
                    COSTO numeric(15,2),
                    SICINGR70_DOCNRO varchar(50),
                    SICINGR70_FECHA date,';

    sql_create = 'CREATE TABLE ' || 'TMP_CROSSTAB_' || current_user || ' ('  || campos_otros || campos_lista || ')';
    execute statement :sql_create;

    sql_create = 'ALTER TABLE ' || 'TMP_CROSSTAB_' || current_user || ' ADD CONSTRAINT PKY_' || 'TMP_CROSSTAB_' || current_user || ' PRIMARY KEY (ID_PYMVENT70)';
    execute statement :sql_create;

    ok = 1;
    suspend;
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT70A (
    P_SOCMAIN01 BIGINT,
    P_PYMVENT70 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOEXTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOINTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_LOCALIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_MUNICIPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_PAIS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REG_FISCAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE_CAJ VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_SUBTOTAL DOUBLE PRECISION,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_LOCALES DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT70_CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_CLIENTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_VENDEDOR VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_VENC DATE,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_TOTAL DOUBLE PRECISION,
    PAGOS DOUBLE PRECISION,
    SALDO DOUBLE PRECISION)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCSYST10_PVC01 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCUSUA01_VEND bigint;
declare variable PYMVENT51_DIASAPARTADO integer;
declare variable PYMVENT70_FECHA timestamp;
begin
    /* Se obtiene los datos de la Empresa*/
   select CFDI_EMPRESA.RAZSOCIAL,
    CFDI_EMPRESA.rfc,
    CFDI_EMPRESA.domf_calle,
    CFDI_EMPRESA.domf_noexterior,
    CFDI_EMPRESA.domf_nointerior,
    CFDI_EMPRESA.domf_colonia,
    CFDI_EMPRESA.domf_localidad,
    CFDI_EMPRESA.domf_municipio,
    CFDI_EMPRESA.domf_estado,
    CFDI_EMPRESA.domf_pais,
    CFDI_EMPRESA.domf_codpostal
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC,
        :rfc,
        :domf_calle,
        :domf_noexterior,
        :domf_nointerior,
        :domf_colonia,
        :domf_localidad,
        :domf_municipio,
        :domf_estado,
        :domf_pais,
        :domf_codpostal;

    /* Se obtiene el regimen fiscal de la empresa */
        SELECT SOCSYST10_DESCRIPCION
         FROM SOCSYST10_DET_ENTRADAS
         inner join SOCMAIN01_CAB_EMPRESAS on (SOCMAIN01_CAB_EMPRESAS.RELA_SOCSYST10_SAT01 = SOCSYST10_DET_ENTRADAS.id_socsyst10)
         where SOCMAIN01_CAB_EMPRESAS.id_socmain01 = :p_socmain01
         into Reg_Fiscal;

    /* Se obtienen datos de la caja */
    for select 
        pymvent01_cab_cajas.rela_socmain21,
        pymvent01_cab_cajas.rela_socusua01_caje,
        pymvent01_cab_cajas.rela_socsyst10_pvc01
    from pymvent01_cab_cajas
       inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
       inner join pymvent51_det_ventas on (pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50)
       inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70 and pymvent70_cab_ticket.rela_socmain01 = :p_socmain01
    into :rela_socmain21,
         :rela_socusua01_caje,
         :rela_socsyst10_pvc01
    do begin
        /* Inicializacion de variables */
        socmain21_descripcion = null;
        socsyst10_descripcion = null;
        NOMBRE_CAJ = null;
        id_pymvent70 = null;
        rela_sicingr01 = null;
        pymvent70_docnro = null;
        rela_socusua01_vend = null;
        pymvent70_cliente = null;
        pymvent51_vendedor = null;

        /* Se obtiene la descripcion de la Sucursal/Organizacion */
          select socmain21_arb_organizacion.socmain21_descripcion
            from socmain21_arb_organizacion
            where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
            into :socmain21_descripcion;

        /* obtenemos la descripcion de la caja */
        select CBO_SOCSYST10_PVC01.socsyst10_descripcion
          from CBO_SOCSYST10_PVC01
          where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
          into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
        SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:p_socmain01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;

      /* Obtenemos los detalles del ticket y productos*/
      for select  pymvent70_cab_ticket.id_pymvent70,
          pymvent70_cab_ticket.rela_sicingr01,
          pymvent70_cab_ticket.pymvent70_docnro,
          pymvent70_cab_ticket.pymvent70_subtotal,
          pymvent70_cab_ticket.pymvent70_descuento,
          pymvent70_cab_ticket.pymvent70_total,
          pymvent70_cab_ticket.pymvent70_totimp_retenidos,
          pymvent70_cab_ticket.pymvent70_totimp_traslados,
          pymvent70_cab_ticket.pymvent70_totimp_locales,
          pymvent70_cab_ticket.pymvent70_neto,
          pymvent70_cab_ticket.pymvent70_fecha,
          pymvent51_det_ventas.rela_socusua01_vend,
          pymvent51_det_ventas.pymvent51_diasapartado
      from pymvent70_cab_ticket
      inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
      where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70
      into :id_pymvent70,
           :rela_sicingr01,
           :pymvent70_docnro,
           :pymvent70_subtotal,
           :pymvent70_descuento,
           :pymvent70_total,
           :pymvent70_totimp_retenidos,
           :pymvent70_totimp_traslados,
           :pymvent70_totimp_locales,
           :pymvent70_neto,
           :pymvent70_fecha,
           :rela_socusua01_vend,
           :pymvent51_diasapartado
      do begin
    
           pymvent70_descuento = iif(pymvent70_descuento is null, 0.00, pymvent70_descuento);
           pymvent70_totimp_retenidos = iif(pymvent70_totimp_retenidos is null, 0.00, pymvent70_totimp_retenidos);
           pymvent70_totimp_traslados = iif(pymvent70_totimp_traslados is null, 0.00, pymvent70_totimp_traslados);
           pymvent70_totimp_locales = iif(pymvent70_totimp_locales is null, 0.00, pymvent70_totimp_locales);
           fecha_venc = dateadd (:pymvent51_diasapartado day to :pymvent70_fecha);

           pagos = null;
           saldo = null;

          /* Se obtiene el cliente (entidad) y el vendedor*/
           select cbo_sicingr01_id.entidad,
                cbo_sicingr01_id.rfc
             from cbo_sicingr01_id
             where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
             into :pymvent70_cliente,
                  :rfc_cliente;
    
            select CBO_SOCUSUA01.entidad
              from CBO_SOCUSUA01(:p_socmain01, :rela_socmain21, :rela_socusua01_vend)
              into :pymvent51_vendedor;

            select sum(pymvent55_mov_moventsal.pymvent55_importe)
                FROM pymvent55_mov_moventsal
                where pymvent55_mov_moventsal.rela_pymvent70 = :id_pymvent70 and
                pymvent55_mov_moventsal.pymvent55_pagoticket = 5 and
                pymvent55_mov_moventsal.pymvent55_importe > 0
                into :pagos;

           pagos = iif(pagos is null, 0.00, pagos);
           saldo = :pymvent70_neto - pagos;


            /* Detalles de los productos */
            for select pymvent71_det_ticket.pymvent71_codigo,
                pymvent71_det_ticket.pymvent71_concepto,
                pymvent71_det_ticket.pymvent71_cantidad,
                pymvent71_det_ticket.pymvent71_importe_unidad,
                pymvent71_det_ticket.pymvent71_importe_subtotal,
                pymvent71_det_ticket.pymvent71_importe_descuento,
                pymvent71_det_ticket.pymvent71_importe_total
             from pymvent71_det_ticket
             where pymvent71_det_ticket.rela_pymvent70 = :p_pymvent70
              and pymvent71_det_ticket.pymvent71_cancelado = 0
             into  :pymvent71_codigo,
                :pymvent71_concepto,
                :pymvent71_cantidad,
                :pymvent71_importe_unidad,
                :pymvent71_importe_subtotal,
                :pymvent71_importe_descuento,
                :pymvent71_importe_total
             do begin
                suspend;
             end
    end

  end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT70P (
    P_SOCMAIN01 BIGINT,
    P_PYMVENT70 BIGINT)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOEXTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_NOINTERIOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_LOCALIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_MUNICIPIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_PAIS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOMF_CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REG_FISCAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMBRE_CAJ VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_PYMVENT70 BIGINT,
    PYMVENT70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT70_SUBTOTAL DOUBLE PRECISION,
    PYMVENT70_DESCUENTO DOUBLE PRECISION,
    PYMVENT70_TOTAL DOUBLE PRECISION,
    PYMVENT70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    PYMVENT70_TOTIMP_LOCALES DOUBLE PRECISION,
    PYMVENT70_NETO DOUBLE PRECISION,
    PYMVENT51_FVENCIDO TIMESTAMP,
    PYMVENT70_CLIENTE VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_CLIENTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT51_VENDEDOR VARCHAR(1300) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_TOTAL DOUBLE PRECISION)
AS
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA01_CAJE bigint;
declare variable RELA_SOCSYST10_PVC01 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCUSUA01_VEND bigint;
begin
    /* Se obtiene los datos de la Empresa*/
   select CFDI_EMPRESA.RAZSOCIAL,
    CFDI_EMPRESA.rfc,
    CFDI_EMPRESA.domf_calle,
    CFDI_EMPRESA.domf_noexterior,
    CFDI_EMPRESA.domf_nointerior,
    CFDI_EMPRESA.domf_colonia,
    CFDI_EMPRESA.domf_localidad,
    CFDI_EMPRESA.domf_municipio,
    CFDI_EMPRESA.domf_estado,
    CFDI_EMPRESA.domf_pais,
    CFDI_EMPRESA.domf_codpostal
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC,
        :rfc,
        :domf_calle,
        :domf_noexterior,
        :domf_nointerior,
        :domf_colonia,
        :domf_localidad,
        :domf_municipio,
        :domf_estado,
        :domf_pais,
        :domf_codpostal;

        /* Se obtiene el regimen fiscal de la empresa */
        SELECT SOCSYST10_DESCRIPCION
         FROM SOCSYST10_DET_ENTRADAS
         inner join SOCMAIN01_CAB_EMPRESAS on (SOCMAIN01_CAB_EMPRESAS.RELA_SOCSYST10_SAT01 = SOCSYST10_DET_ENTRADAS.id_socsyst10)
         where SOCMAIN01_CAB_EMPRESAS.id_socmain01 = :p_socmain01
         into Reg_Fiscal;

    /* Se obtienen datos de la caja */
    for select 
        pymvent01_cab_cajas.rela_socmain21,
        pymvent01_cab_cajas.rela_socusua01_caje,
        pymvent01_cab_cajas.rela_socsyst10_pvc01
    from pymvent01_cab_cajas
       inner join pymvent50_cab_apertura on (pymvent01_cab_cajas.id_pymvent01 = pymvent50_cab_apertura.rela_pymvent01)
       inner join pymvent51_det_ventas on (pymvent50_cab_apertura.id_pymvent50 = pymvent51_det_ventas.rela_pymvent50)
       inner join pymvent70_cab_ticket on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
    where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70 and pymvent70_cab_ticket.rela_socmain01 = :p_socmain01
    into :rela_socmain21,
         :rela_socusua01_caje,
         :rela_socsyst10_pvc01
    do begin
        /* Inicializacion de variables */
        socmain21_descripcion = null;
        socsyst10_descripcion = null;
        NOMBRE_CAJ = null;
        id_pymvent70 = null;
        rela_sicingr01 = null;
        pymvent70_docnro = null;
        rela_socusua01_vend = null;
        pymvent70_cliente = null;
        pymvent51_vendedor = null;

        /* Se obtiene la descripcion de la Sucursal/Organizacion */
          select socmain21_arb_organizacion.socmain21_descripcion
            from socmain21_arb_organizacion
            where socmain21_arb_organizacion.id_socmain21 = :rela_socmain21
            into :socmain21_descripcion;

        /* obtenemos la descripcion de la caja */
        select CBO_SOCSYST10_PVC01.socsyst10_descripcion
          from CBO_SOCSYST10_PVC01
          where CBO_SOCSYST10_PVC01.id_socsyst10 = :rela_socsyst10_pvc01
          into :socsyst10_descripcion;

         /* Se busca el nombre y apellidos del cajero */
        SELECT CBO_SOCUSUA01.ENTIDAD
          from CBO_SOCUSUA01(:p_socmain01, :rela_socmain21, :rela_socusua01_caje)
          into :NOMBRE_CAJ;

      /* Obtenemos los detalles del ticket y productos*/
      for select  pymvent70_cab_ticket.id_pymvent70,
          pymvent70_cab_ticket.rela_sicingr01,
          pymvent70_cab_ticket.pymvent70_docnro,
          pymvent70_cab_ticket.pymvent70_subtotal,
          pymvent70_cab_ticket.pymvent70_descuento,
          pymvent70_cab_ticket.pymvent70_total,
          pymvent70_cab_ticket.pymvent70_totimp_retenidos,
          pymvent70_cab_ticket.pymvent70_totimp_traslados,
          pymvent70_cab_ticket.pymvent70_totimp_locales,
          pymvent70_cab_ticket.pymvent70_neto,
          pymvent51_det_ventas.rela_socusua01_vend,
          pymvent51_det_ventas.pymvent51_fvencido
      from pymvent70_cab_ticket
      inner join pymvent51_det_ventas on (pymvent51_det_ventas.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
      where pymvent70_cab_ticket.id_pymvent70 = :p_pymvent70
      into :id_pymvent70,
           :rela_sicingr01,
           :pymvent70_docnro,
           :pymvent70_subtotal,
           :pymvent70_descuento,
           :pymvent70_total,
           :pymvent70_totimp_retenidos,
           :pymvent70_totimp_traslados,
           :pymvent70_totimp_locales,
           :pymvent70_neto,
           :rela_socusua01_vend,
           :pymvent51_fvencido
      do begin
    
           pymvent70_descuento = iif(pymvent70_descuento is null, 0.00, pymvent70_descuento);
           pymvent70_totimp_retenidos = iif(pymvent70_totimp_retenidos is null, 0.00, pymvent70_totimp_retenidos);
           pymvent70_totimp_traslados = iif(pymvent70_totimp_traslados is null, 0.00, pymvent70_totimp_traslados);
           pymvent70_totimp_locales = iif(pymvent70_totimp_locales is null, 0.00, pymvent70_totimp_locales);

          /* Se obtiene el cliente (entidad) y el vendedor*/
           select cbo_sicingr01_id.entidad,
                cbo_sicingr01_id.rfc
             from cbo_sicingr01_id
             where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
             into :pymvent70_cliente,
                  :rfc_cliente;
    
            select CBO_SOCUSUA01.entidad
              from CBO_SOCUSUA01(:p_socmain01, :rela_socmain21, :rela_socusua01_vend)
              into :pymvent51_vendedor;

            /* Detalles de los productos */
            for select pymvent71_det_ticket.pymvent71_codigo,
                pymvent71_det_ticket.pymvent71_concepto,
                pymvent71_det_ticket.pymvent71_cantidad,
                pymvent71_det_ticket.pymvent71_importe_unidad,
                pymvent71_det_ticket.pymvent71_importe_subtotal,
                pymvent71_det_ticket.pymvent71_importe_descuento,
                pymvent71_det_ticket.pymvent71_importe_total
             from pymvent71_det_ticket
             where pymvent71_det_ticket.rela_pymvent70 = :p_pymvent70
             and pymvent71_det_ticket.pymvent71_cancelado = 0
             into  :pymvent71_codigo,
                :pymvent71_concepto,
                :pymvent71_cantidad,
                :pymvent71_importe_unidad,
                :pymvent71_importe_subtotal,
                :pymvent71_importe_descuento,
                :pymvent71_importe_total
             do begin
                suspend;
             end
    end

  end
end^


CREATE OR ALTER PROCEDURE REP_PYMVENT71 (
    P_SOCMAIN01 BIGINT,
    FECHA_INI DATE,
    FECHA_FIN DATE)
RETURNS (
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR95 BIGINT,
    PYMVENT71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PYMVENT71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SUCURSAL0 DOUBLE PRECISION,
    SUCURSAL1 DOUBLE PRECISION,
    SUCURSAL2 DOUBLE PRECISION,
    SUCURSAL3 DOUBLE PRECISION,
    SUCURSAL4 DOUBLE PRECISION,
    SUCURSAL5 DOUBLE PRECISION,
    SUCURSAL6 DOUBLE PRECISION,
    SUCURSAL7 DOUBLE PRECISION,
    SUCURSAL8 DOUBLE PRECISION,
    SUCURSAL9 DOUBLE PRECISION)
AS
declare variable ID_SOCMAIN21 bigint;
declare variable CONT integer;
declare variable STR varchar(1000);
declare variable CANTIDAD double precision;
declare variable RELA_SICINGR95 bigint;
declare variable USUARIO varchar(50);
BEGIN
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    /* Se elimina datos en la tabla temporal solamente del usuario actual */
    DELETE FROM tmp_pymvent71 WHERE tmp_pymvent71.usuario = current_user;

    /* Se agregan datos de los productos vendidos, sin las cantidades por
    sucursales */
    INSERT INTO tmp_pymvent71( tmp_pymvent71.usuario,
                               tmp_pymvent71.rela_sicingr95,
                               tmp_pymvent71.pymvent71_codigo,
                               tmp_pymvent71.pymvent71_concepto)
    select
        current_user,
        pymvent71_det_ticket.rela_sicingr95,
        pymvent71_det_ticket.pymvent71_codigo,
        pymvent71_det_ticket.pymvent71_concepto
    from pymvent71_det_ticket
       inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
       inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
       inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
    where pymvent70_cab_ticket.rela_socmain01 = :p_socmain01 and
        pymvent71_det_ticket.pymvent71_cancelado = 0 and
        cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
    group by pymvent71_det_ticket.rela_sicingr95, pymvent71_det_ticket.pymvent71_codigo, pymvent71_det_ticket.pymvent71_concepto
    order by pymvent71_det_ticket.pymvent71_concepto;

  /* Obtenemos las organizaciones/sucursales que tenga la empresa, con alguna venta
  en el periodo especificado.
  Por cada una, obtenemos el total de ventas de cada producto y lo agregamos
  a la Tabla temporal */
  cont = 0;
  for select distinct pymvent70_cab_ticket.rela_socmain21
    from pymvent70_cab_ticket
       inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
       inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
    where pymvent70_cab_ticket.rela_socmain01 = :p_socmain01 and
    cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
  into :id_socmain21
  DO BEGIN
    /* Inicializamos las variables */
    rela_sicingr95 = null;
    cantidad = 0;

    /* Buscamos los productos y cantidades vendidas en cada sucursal */
    for select pymvent71_det_ticket.rela_sicingr95,
    sum( pymvent71_det_ticket.pymvent71_cantidad)
    from pymvent71_det_ticket
       inner join pymvent70_cab_ticket on (pymvent71_det_ticket.rela_pymvent70 = pymvent70_cab_ticket.id_pymvent70)
       inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
       inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
    where pymvent70_cab_ticket.rela_socmain01 = :p_socmain01  and
          pymvent70_cab_ticket.rela_socmain21 = :id_socmain21 and
          pymvent71_det_ticket.pymvent71_cancelado = 0 and
          cast(pymvent70_cab_ticket.pymvent70_fecha as date) between  :fecha_ini and :fecha_fin
    group by pymvent71_det_ticket.rela_sicingr95
    into :rela_sicingr95,
        :cantidad
    do begin
        /* Actualizamos en la tabla temporal las cantidades vendidas por producto
        para esta sucursal */
         str = 'UPDATE tmp_pymvent71 SET tmp_pymvent71.sucursal' || cont ||' = '
         || :cantidad || ' where tmp_pymvent71.rela_sicingr95 = ' || :rela_sicingr95
         || ' and tmp_pymvent71.usuario = ''' || current_user || '''';

         execute statement :str;
    end
    cont = :cont + 1;
  END

  for select *
  from tmp_pymvent71
  where tmp_pymvent71.usuario = current_user
  into :ID_SICINGR95,
       :PYMVENT71_CODIGO,
       :PYMVENT71_CONCEPTO,
       :SUCURSAL0,
       :SUCURSAL1,
       :SUCURSAL2,
       :SUCURSAL3,
       :SUCURSAL4,
       :SUCURSAL5,
       :SUCURSAL6,
       :SUCURSAL7,
       :SUCURSAL8,
       :SUCURSAL9,
       :usuario
  do begin
      suspend;
  end

END^


CREATE OR ALTER PROCEDURE REP_PYMVENT71_LEYENDA (
    P_SOCMAIN01 BIGINT,
    FECHA_INI DATE,
    FECHA_FIN DATE)
RETURNS (
    ID_SOCMAIN21 BIGINT,
    SOCMAIN21_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
  /* Obtenemos las organizaciones/sucursales que tenga la empresa, con alguna venta
  en el periodo especificado.
  Por cada una, obtenemos el codigo y descripcion de la misma */
  for select distinct pymvent70_cab_ticket.rela_socmain21
    from pymvent70_cab_ticket
       inner join pymvent51_det_ventas on (pymvent70_cab_ticket.id_pymvent70 = pymvent51_det_ventas.rela_pymvent70)
       inner join pymvent60_cab_cobro on (pymvent51_det_ventas.id_pymvent51 = pymvent60_cab_cobro.rela_pymvent51)
    where  pymvent70_cab_ticket.rela_socmain01 = :p_socmain01 and
    cast(pymvent70_cab_ticket.pymvent70_fecha as date) between :fecha_ini and :fecha_fin
  into :id_socmain21
  DO BEGIN
     SELECT ARB_SOCMAIN21_X_EMPRESA.socmain21_codigo_ext,
      ARB_SOCMAIN21_X_EMPRESA.socmain21_descripcion
      FROM ARB_SOCMAIN21_X_EMPRESA(:p_socmain01)
      where ARB_SOCMAIN21_X_EMPRESA.id_socmain21 = :id_socmain21
      into :socmain21_codigo,
           :socmain21_descripcion;
      suspend;
  end
end^


CREATE OR ALTER PROCEDURE REP_SICCONT10_CAB (
    ID_SICCONT10X BIGINT,
    ID_SOCMAIN01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE,
    TIPO_SISTEMA_ID BIGINT,
    TIPO_POLIZA_ID BIGINT,
    TIPO_ENTIDADX VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_ID BIGINT)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCSYST10_CTP01 BIGINT,
    RELA_SOCSYST10_CTP02 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    ID_SICCONT10 BIGINT,
    ORDEN INTEGER,
    SICCONT10_TIPO_ENTIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SMX VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT10_COTIZA DOUBLE PRECISION,
    SICCONT10_ORIGEN VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_ENTIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_POLIZA_SISTEMA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_POLIZA_CONTABLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION)
AS
declare variable SQLX varchar(4000);
declare variable FECHA_CORTE date;
begin
    fecha_corte = null;
    orden = 0;

    SQLX =  'Select ' ||
            'ctp01.socsyst10_descripcion, ' ||
            'ctp02.socsyst10_descripcion, ' ||
            'ctm01.socsyst10_descripcion, ' ||
            'siccont10_cab_polizas.rela_socmain01, ' ||
            'siccont10_cab_polizas.rela_socsyst10_ctp01, ' ||
            'siccont10_cab_polizas.rela_socsyst10_ctp02, ' ||
            'siccont10_cab_polizas.rela_socsyst10_ctm01, ' ||
            'siccont10_cab_polizas.rela_socusua30, ' ||
            'siccont10_cab_polizas.id_siccont10, ' ||
            'siccont10_cab_polizas.siccont10_tipo_entidad, ' ||
            'siccont10_cab_polizas.siccont10_uuid_smx, ' ||
            'siccont10_cab_polizas.siccont10_uuid_sat, ' ||
            'siccont10_cab_polizas.siccont10_docnro, ' ||
            'siccont10_cab_polizas.siccont10_descripcion, ' ||
            'siccont10_cab_polizas.siccont10_fcta, ' ||
            'siccont10_cab_polizas.siccont10_cotiza, ' ||
            'siccont10_cab_polizas.siccont10_origen ' ||
            'from siccont10_cab_polizas ' ||
            'inner join socsyst10_det_entradas ctp01 on ( ctp01.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 ) ' ||
            'inner join socsyst10_det_entradas ctp02 on ( ctp02.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp02 ) ' ||
            'inner join socsyst10_det_remoto ctm01 on ( ctm01.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctm01 ) ' ||
            'where siccont10_cab_polizas.rela_socmain01 = ' || :id_socmain01;

    if (ID_SICCONT10X is not null) then
        SQLX = SQLX || ' and siccont10_cab_polizas.id_siccont10 = ' || :id_siccont10x;
    else
    begin
        if (fecha_desde is not null and fecha_hasta is not null) then
            SQLX = SQLX || ' and siccont10_cab_polizas.siccont10_fcta between ''' || :fecha_desde || ''' and ''' || :fecha_hasta || '''';
        
        if (ENTIDAD_ID is not null) then
            SQLX = SQLX || 'and siccont10_cab_polizas.rela_socusua30 = ' || :entidad_id;

        if (TIPO_ENTIDADX is not null) then
            SQLX = SQLX || ' and siccont10_cab_polizas.siccont10_tipo_entidad = ''' || :tipo_entidadx || '''';

        if (tipo_sistema_id is not null) then
            SQLX = SQLX || ' and siccont10_cab_polizas.rela_socsyst10_ctp01 = ' || tipo_sistema_id;

        if (tipo_poliza_id is not null) then
            SQLX = SQLX || ' and siccont10_cab_polizas.rela_socsyst10_ctp02 = ' || tipo_poliza_id;

    end

    SQLX = SQLX || ' order by siccont10_cab_polizas.siccont10_docnro,  ' ||
                   '          siccont10_cab_polizas.siccont10_fcta';
    for execute statement :SQLX
    into :tipo_poliza_sistema,
         :tipo_poliza_contable,
         :tipo_moneda,
         :rela_socmain01,
         :rela_socsyst10_ctp01,
         :rela_socsyst10_ctp02,
         :rela_socsyst10_ctm01,
         :rela_socusua30,
         :id_siccont10,
         :siccont10_tipo_entidad,
         :siccont10_uuid_smx,
         :siccont10_uuid_sat,
         :siccont10_docnro,
         :siccont10_descripcion,
         :siccont10_fcta,
         :siccont10_cotiza,
         :siccont10_origen
    do
    begin
        if (fecha_corte is null) then
            fecha_corte = siccont10_fcta;
        else
        if (fecha_corte <> siccont10_fcta) then
        begin
            orden = 0;
            fecha_corte = siccont10_fcta;
        end
        orden = orden + 1;

        if (siccont10_uuid_smx is null) then
            siccont10_uuid_smx = '';

        if (siccont10_tipo_entidad = 'P') then
        begin
            tipo_entidad = 'Proveedor';

            select
            cbo_sicegre01_id.entidad,
            cbo_sicegre01_id.rfc
            from cbo_sicegre01_id
            where cbo_sicegre01_id.rela_socmain01 = :rela_socmain01
            and cbo_sicegre01_id.rela_socusua30 = :rela_socusua30
            into :entidad,
                 :rfc;
        end
        else if (siccont10_tipo_entidad = 'C') then
        begin
            tipo_entidad = 'Cliente';

            select
            cbo_sicingr01_id.entidad,
            cbo_sicingr01_id.rfc
            from cbo_sicingr01_id
            where cbo_sicingr01_id.rela_socmain01 = :rela_socmain01
            and cbo_sicingr01_id.rela_socusua30 = :rela_socusua30
            into :entidad,
                 :rfc;
        end
        else if (siccont10_tipo_entidad = 'E') then
        begin
            tipo_entidad = 'Empleado';

            select
            cbo_sicnomi01_id.entidad,
            cbo_sicnomi01_id.rfc
            from cbo_sicnomi01_id
            where cbo_sicnomi01_id.rela_socmain01 = :rela_socmain01
            and cbo_sicnomi01_id.rela_socusua30 = :rela_socusua30
            into :entidad,
                 :rfc;
        end
        else
        begin
            tipo_entidad = 'N/A';
            entidad = '';
            rfc = '';
        end

        select sum(siccont11_det_polizas.siccont11_debe)
        from siccont11_det_polizas
        where siccont11_det_polizas.rela_siccont10 = :id_siccont10
        into :importe;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICCONT10_DET (
    RELA_SICCONT10 BIGINT)
RETURNS (
    RELA_SICCONT02 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    ID_SICCONT11 BIGINT,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_TIPO_ENTIDAD VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_DEBE DOUBLE PRECISION,
    SICCONT11_HABER DOUBLE PRECISION,
    TIPO_ENTIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN01 bigint;
begin
    select siccont10_cab_polizas.rela_socmain01
    from siccont10_cab_polizas
    where siccont10_cab_polizas.id_siccont10 = :rela_siccont10
    into :rela_socmain01;

    for select
    siccont02_arb_planctas.siccont02_codagrup,
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    siccont11_det_polizas.rela_siccont02,
    siccont11_det_polizas.rela_socusua30,
    siccont11_det_polizas.id_siccont11,
    siccont11_det_polizas.siccont11_tipo_entidad,
    siccont11_det_polizas.siccont11_referencia,
    siccont11_det_polizas.siccont11_debe,
    siccont11_det_polizas.siccont11_haber
    from siccont11_det_polizas
    inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
    where siccont11_det_polizas.rela_siccont10 = :rela_siccont10
    into :siccont02_codagrup,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :rela_siccont02,
         :rela_socusua30,
         :id_siccont11,
         :siccont11_tipo_entidad,
         :siccont11_referencia,
         :siccont11_debe,
         :siccont11_haber
    do
    begin
        if (siccont11_tipo_entidad = 'P') then
        begin
            tipo_entidad = 'Proveedor';

            select
            cbo_sicegre01_id.entidad,
            cbo_sicegre01_id.rfc
            from cbo_sicegre01_id
            where cbo_sicegre01_id.rela_socmain01 = :rela_socmain01
            and cbo_sicegre01_id.rela_socusua30 = :rela_socusua30
            into :entidad,
                 :rfc;
        end
        else if (siccont11_tipo_entidad = 'C') then
        begin
            tipo_entidad = 'Cliente';

            select
            cbo_sicingr01_id.entidad,
            cbo_sicingr01_id.rfc
            from cbo_sicingr01_id
            where cbo_sicingr01_id.rela_socmain01 = :rela_socmain01
            and cbo_sicingr01_id.rela_socusua30 = :rela_socusua30
            into :entidad,
                 :rfc;
        end
        else if (siccont11_tipo_entidad = 'E') then
        begin
            tipo_entidad = 'Empleado';

            select
            cbo_sicnomi01_id.entidad,
            cbo_sicnomi01_id.rfc
            from cbo_sicnomi01_id
            where cbo_sicnomi01_id.rela_socmain01 = :rela_socmain01
            and cbo_sicnomi01_id.rela_socusua30 = :rela_socusua30
            into :entidad,
                 :rfc;
        end
        else
        begin
            tipo_entidad = 'N/A';
            entidad = '';
            rfc = '';
        end

        suspend;
    end
end^


