CREATE OR ALTER PROCEDURE REP_SICCONT11_BALANCE (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER,
    CREA_TEMPORARIO INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SOCSYST06_NIVEL INTEGER,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CATALOGO_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_HISTORICO DOUBLE PRECISION,
    SALDO_ACTUAL DOUBLE PRECISION,
    SALDO_MES DOUBLE PRECISION)
AS
declare variable TMP_RETO integer;
declare variable NATURALEZ_CUENTA_PRINCIPAL varchar(1);
begin
    delete from tmp_siccont11_balance where tmp_siccont11_balance.usuario = current_user;

    insert into tmp_siccont11_balance(  tmp_siccont11_balance.usuario,
                                        tmp_siccont11_balance.id_siccont02,
                                        tmp_siccont11_balance.socsyst06_nivel,
                                        tmp_siccont11_balance.siccont02_tipo,
                                        tmp_siccont11_balance.catalogo_sat,
                                        tmp_siccont11_balance.siccont02_codigo_ext,
                                        tmp_siccont11_balance.siccont02_descripcion,
                                        tmp_siccont11_balance.saldo_historico,
                                        tmp_siccont11_balance.saldo_actual,
                                        tmp_siccont11_balance.saldo_mes  )
    select
    current_user,
    prd_siccont11_balanza_balance.id_siccont02,
    prd_siccont11_balanza_balance.socsyst06_nivel,
    prd_siccont11_balanza_balance.siccont02_tipo,
    prd_siccont11_balanza_balance.catalogo_sat,
    prd_siccont11_balanza_balance.siccont02_codigo_ext,
    prd_siccont11_balanza_balance.siccont02_descripcion,
    iif(prd_siccont11_balanza_balance.saldo_historico is null, 0, prd_siccont11_balanza_balance.saldo_historico) ,
    iif(prd_siccont11_balanza_balance.saldo_actual is null, 0, prd_siccont11_balanza_balance.saldo_actual) ,
    iif(prd_siccont11_balanza_balance.saldo_mes is null, 0, prd_siccont11_balanza_balance.saldo_mes )
    FROM prd_siccont11_balanza_balance(:id_socmain01, :ano, :mes, :crea_temporario);

    select count(rep_siccont11_resultado.id_siccont02)
    from rep_siccont11_resultado(:id_socmain01, :ano, :mes, 0)
    into :tmp_reto;

    for select
    tmp_siccont11_balance.id_siccont02,
    tmp_siccont11_balance.socsyst06_nivel,
    tmp_siccont11_balance.siccont02_tipo,
    tmp_siccont11_balance.catalogo_sat,
    tmp_siccont11_balance.siccont02_codigo_ext,
    tmp_siccont11_balance.siccont02_descripcion,
    tmp_siccont11_balance.saldo_historico,
    tmp_siccont11_balance.saldo_actual,
    tmp_siccont11_balance.saldo_mes
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    order by tmp_siccont11_balance.siccont02_codigo_ext
    into :id_siccont02,
         :socsyst06_nivel,
         :siccont02_tipo,
         :catalogo_sat,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :saldo_historico,
         :saldo_actual,
         :saldo_mes
    do
    begin
        if (socsyst06_nivel = 2) then
            naturalez_cuenta_principal = :siccont02_tipo;

        if (siccont02_tipo != naturalez_cuenta_principal) then
        begin
            if (saldo_historico > 0) then
                update tmp_siccont11_balance set tmp_siccont11_balance.saldo_historico = tmp_siccont11_balance.saldo_historico * (-1)
                where tmp_siccont11_balance.usuario = current_user
                and tmp_siccont11_balance.id_siccont02 = :id_siccont02;

            if (saldo_actual > 0) then
                update tmp_siccont11_balance set tmp_siccont11_balance.saldo_actual = tmp_siccont11_balance.saldo_actual * (-1)
                where tmp_siccont11_balance.usuario = current_user
                and tmp_siccont11_balance.id_siccont02 = :id_siccont02;

            if (saldo_mes > 0) then
                update tmp_siccont11_balance set tmp_siccont11_balance.saldo_mes = tmp_siccont11_balance.saldo_mes * (-1)
                where tmp_siccont11_balance.usuario = current_user
                and tmp_siccont11_balance.id_siccont02 = :id_siccont02;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICCONT11_BALANCE_CAB (
    ID_SOCMAIN01X BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    ID_SOCMAIN01 BIGINT,
    EMPRESA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ACTIVO_CIRCULANTE DOUBLE PRECISION,
    ACTIVO_NOCIRCULANTE DOUBLE PRECISION,
    ACTIVO_TOTAL DOUBLE PRECISION,
    ACTIVO_TOTAL_INICIAL DOUBLE PRECISION,
    ACTIVO_TOTAL_MES DOUBLE PRECISION,
    PASIVO_CIRCULANTE DOUBLE PRECISION,
    PASIVO_NOCIRCULANTE DOUBLE PRECISION,
    PASIVO_TOTAL DOUBLE PRECISION,
    PASIVO_TOTAL_INICIAL DOUBLE PRECISION,
    PASIVO_TOTAL_MES DOUBLE PRECISION,
    CAPITAL DOUBLE PRECISION,
    CAPITAL_INICIAL DOUBLE PRECISION,
    CAPITAL_MES DOUBLE PRECISION,
    UTILIDAD DOUBLE PRECISION,
    UTILIDAD_INICIAL DOUBLE PRECISION,
    UTILIDAD_MES DOUBLE PRECISION,
    PASIVO_MAS_CAPITAL DOUBLE PRECISION,
    PASIVO_MAS_CAPITAL_INICIAL DOUBLE PRECISION,
    PASIVO_MAS_CAPITAL_MES DOUBLE PRECISION)
AS
declare variable TMP_RETO integer;
begin
    id_socmain01 = id_socmain01x;

    select count(rep_siccont11_balance.id_siccont02)
    from rep_siccont11_balance(:id_socmain01, :ano, :mes, 1)
    into :tmp_reto;

    Select
    PRD_SICCONT11_BALANCE_TOTALES.activo_circulante,
    PRD_SICCONT11_BALANCE_TOTALES.activo_nocirculante,
    PRD_SICCONT11_BALANCE_TOTALES.activo_total,
    PRD_SICCONT11_BALANCE_TOTALES.activo_total_inicial,
    PRD_SICCONT11_BALANCE_TOTALES.activo_total_mes,

    PRD_SICCONT11_BALANCE_TOTALES.pasivo_circulante,
    PRD_SICCONT11_BALANCE_TOTALES.pasivo_nocirculante,
    PRD_SICCONT11_BALANCE_TOTALES.pasivo_total,
    PRD_SICCONT11_BALANCE_TOTALES.pasivo_total_inicial,
    PRD_SICCONT11_BALANCE_TOTALES.pasivo_total_mes,

    PRD_SICCONT11_BALANCE_TOTALES.capital,
    PRD_SICCONT11_BALANCE_TOTALES.capital_inicial,
    PRD_SICCONT11_BALANCE_TOTALES.capital_mes,

    PRD_SICCONT11_BALANCE_TOTALES.utilidad,
    PRD_SICCONT11_BALANCE_TOTALES.utilidad_inicial,
    PRD_SICCONT11_BALANCE_TOTALES.utilidad_mes,

    PRD_SICCONT11_BALANCE_TOTALES.pasivo_mas_capital,
    PRD_SICCONT11_BALANCE_TOTALES.pasivo_mas_capital_inicial,
    PRD_SICCONT11_BALANCE_TOTALES.pasivo_mas_capital_mes

    from PRD_SICCONT11_BALANCE_TOTALES
    into :activo_circulante,
         :activo_nocirculante,
         :activo_total,
         :activo_total_inicial,
         :activo_total_mes,

         :pasivo_circulante,
         :pasivo_nocirculante,
         :pasivo_total,
         :pasivo_total_inicial,
         :pasivo_total_mes,

         :capital,
         :capital_inicial,
         :capital_mes,

         :utilidad,
         :utilidad_inicial,
         :utilidad_mes,

         :pasivo_mas_capital,
         :pasivo_mas_capital_inicial,
         :pasivo_mas_capital_mes;

    select
    cbo_socmain01_cfdi.socmain01_nomcomercial,
    cbo_socmain01_cfdi.rfc
    from cbo_socmain01_cfdi
    where cbo_socmain01_cfdi.id_socmain01 = :id_socmain01
    into :empresa,
         :rfc;


    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICCONT11_BALANCE_FILTRO (
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICCONT02 BIGINT,
    SOCSYST06_NIVEL INTEGER,
    CATALOGO_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_HISTORICO DOUBLE PRECISION,
    SALDO_ACTUAL DOUBLE PRECISION,
    SALDO_MES DOUBLE PRECISION)
AS
declare variable SUMA double precision;
declare variable ENTRO integer;
begin
    entro = 0;

    for select
    tmp_siccont11_balance.id_siccont02,
    tmp_siccont11_balance.socsyst06_nivel,
    tmp_siccont11_balance.catalogo_sat,
    tmp_siccont11_balance.siccont02_codigo_ext,
    tmp_siccont11_balance.siccont02_descripcion,
    tmp_siccont11_balance.saldo_historico,
    tmp_siccont11_balance.saldo_actual,
    tmp_siccont11_balance.saldo_mes
    from tmp_siccont11_balance
    where tmp_siccont11_balance.usuario = current_user
    and tmp_siccont11_balance.siccont02_codigo_ext like :codigo || '%'
    and tmp_siccont11_balance.siccont02_codigo_ext <> :codigo
    order by tmp_siccont11_balance.siccont02_codigo_ext
    into :id_siccont02,
         :socsyst06_nivel,
         :catalogo_sat,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :saldo_historico,
         :saldo_actual,
         :saldo_mes
    do
    begin
        suma = saldo_historico + saldo_actual + saldo_mes;

        if (suma <> 0) then
        begin
            entro = 1;
            suspend;
        end
    end

    if (entro = 0) then
    begin
        siccont02_descripcion = 'Sin movimiento';
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICCONT11_BALANZA (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER,
    SINMOVI INTEGER)
RETURNS (
    SOCSYST06_NIVEL INTEGER,
