CREATE OR ALTER PROCEDURE REP_SICCONT11_BALANZA_FISANUAL (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER)
RETURNS (
    SOCSYST06_NIVEL INTEGER,
    ID_SICCONT02 BIGINT,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODAGRUP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_01 NUMERIC(18,4),
    SALDO_02 NUMERIC(18,4),
    SALDO_03 NUMERIC(18,4),
    SALDO_04 NUMERIC(18,4),
    SALDO_05 NUMERIC(18,4),
    SALDO_06 NUMERIC(18,4),
    SALDO_07 NUMERIC(18,4),
    SALDO_08 NUMERIC(18,4),
    SALDO_09 NUMERIC(18,4),
    SALDO_10 NUMERIC(18,4),
    SALDO_11 NUMERIC(18,4),
    SALDO_12 NUMERIC(18,4),
    SALDO_TOTAL NUMERIC(18,4),
    AFECTACION INTEGER)
AS
declare variable MES integer;
declare variable SALDO_FINAL numeric(18,4);
declare variable SMXSQL varchar(2000);
declare variable MESSTR varchar(2);
declare variable MES_FILTRO integer;
begin
    delete from TMP_SICCONT11_BALANZA_FISANUAL where TMP_SICCONT11_BALANZA_FISANUAL.usuario = current_user;

    insert into TMP_SICCONT11_BALANZA_FISANUAL( TMP_SICCONT11_BALANZA_FISANUAL.usuario,
                                                TMP_SICCONT11_BALANZA_FISANUAL.id_siccont02,
                                                TMP_SICCONT11_BALANZA_FISANUAL.socsyst06_nivel,
                                                TMP_SICCONT11_BALANZA_FISANUAL.siccont02_codigo_ext,
                                                TMP_SICCONT11_BALANZA_FISANUAL.siccont02_descripcion,
                                                TMP_SICCONT11_BALANZA_FISANUAL.siccont02_codagrup,
                                                TMP_SICCONT11_BALANZA_FISANUAL.siccont02_tipo,
                                                TMP_SICCONT11_BALANZA_FISANUAL.afectacion)
    select
    current_user,
    siccont02_arb_planctas.id_siccont02,
    socsyst06_det_niveles.socsyst06_nivel,
    trim(siccont02_arb_planctas.siccont02_codigo_ext),
    siccont02_arb_planctas.siccont02_descripcion,
    siccont02_arb_planctas.siccont02_codagrup,
    siccont02_arb_planctas.siccont02_tipo,
    iif( ( select first 1 ctafinal.id_siccont02
           from siccont02_arb_planctas ctafinal
           where ctafinal.rela_siccont02 = siccont02_arb_planctas.id_siccont02) is null, 1, 0)
    from siccont01_cab_planctas
    inner join siccont02_arb_planctas on (siccont02_arb_planctas.rela_siccont01 = siccont01_cab_planctas.id_siccont01)
    inner join socsyst06_det_niveles on (socsyst06_det_niveles.id_socsyst06 = siccont02_arb_planctas.rela_socsyst06)
    where siccont01_cab_planctas.rela_socmain01 = :id_socmain01
    order by siccont02_arb_planctas.siccont02_codigo_ext;

    mes = 1;
    if (ano = extract(year FROM current_date)) then
        mes_filtro = extract(month FROM current_date);
    else
        mes_filtro = 12;

    while (mes <= mes_filtro) do
    begin
        for select
        rep_siccont11_balanza_fiscal.id_siccont02,
        rep_siccont11_balanza_fiscal.saldo_final
        from rep_siccont11_balanza_fiscal(:id_socmain01, :ano, :mes)
        into :id_siccont02,
             :saldo_final
        do
        begin
            messtr = trim(cast(mes as varchar(2)));
            messtr = iif(char_length(messtr) = 1, '0' || messtr, messtr);

            SMXSQL = 'update tmp_siccont11_balanza_fisanual set tmp_siccont11_balanza_fisanual.saldo_' || messtr ||
                     ' = ' || :saldo_final || ' where tmp_siccont11_balanza_fisanual.usuario = current_user' ||
                     ' and tmp_siccont11_balanza_fisanual.id_siccont02 = ' || :id_siccont02;

            EXECUTE STATEMENT :SMXSQL;
        end

        mes = mes + 1;
    end

    for select
    tmp_siccont11_balanza_fisanual.socsyst06_nivel,
    tmp_siccont11_balanza_fisanual.id_siccont02,
    tmp_siccont11_balanza_fisanual.siccont02_codigo_ext,
    tmp_siccont11_balanza_fisanual.siccont02_descripcion,
    tmp_siccont11_balanza_fisanual.siccont02_codagrup,
    tmp_siccont11_balanza_fisanual.siccont02_tipo,
    tmp_siccont11_balanza_fisanual.saldo_01,
    tmp_siccont11_balanza_fisanual.saldo_02,
    tmp_siccont11_balanza_fisanual.saldo_03,
    tmp_siccont11_balanza_fisanual.saldo_04,
    tmp_siccont11_balanza_fisanual.saldo_05,
    tmp_siccont11_balanza_fisanual.saldo_06,
    tmp_siccont11_balanza_fisanual.saldo_07,
    tmp_siccont11_balanza_fisanual.saldo_08,
    tmp_siccont11_balanza_fisanual.saldo_09,
    tmp_siccont11_balanza_fisanual.saldo_10,
    tmp_siccont11_balanza_fisanual.saldo_11,
    tmp_siccont11_balanza_fisanual.saldo_12,
    tmp_siccont11_balanza_fisanual.afectacion
    from tmp_siccont11_balanza_fisanual
    where tmp_siccont11_balanza_fisanual.usuario = current_user
    into :socsyst06_nivel,
         :id_siccont02,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_codagrup,
         :siccont02_tipo,
         :saldo_01,
         :saldo_02,
         :saldo_03,
         :saldo_04,
         :saldo_05,
         :saldo_06,
         :saldo_07,
         :saldo_08,
         :saldo_09,
         :saldo_10,
         :saldo_11,
         :saldo_12,
         :afectacion
    do
    begin
        saldo_total = saldo_01 + saldo_02 + saldo_03 + saldo_04 + saldo_05 + saldo_06 +
                      saldo_07 + saldo_08 + saldo_09 + saldo_10 + saldo_11 + saldo_12;

        if (saldo_total <> 0) then
            suspend;
    end
end^


