CREATE OR ALTER PROCEDURE REP_SICCONT11_MAYOR_DET (
    ID_SICCONT02 BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    ID_SICCONT10 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT11_DEBE DOUBLE PRECISION,
    SICCONT11_HABER DOUBLE PRECISION,
    ACUMULADO DOUBLE PRECISION,
    SICCONT11_REFERENCIA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    acumulado = 0;

    for select
    siccont10_cab_polizas.id_siccont10,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_descripcion,
    siccont10_cab_polizas.siccont10_fcta,
    siccont02_arb_planctas.siccont02_codigo_ext,
    siccont02_arb_planctas.siccont02_descripcion,
    siccont02_arb_planctas.siccont02_tipo,
    siccont11_det_polizas.siccont11_debe,
    siccont11_det_polizas.siccont11_haber,
    siccont11_det_polizas.siccont11_referencia
    from siccont11_det_polizas
    inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10 )
    inner join siccont02_arb_planctas on ( siccont02_arb_planctas.id_siccont02 = siccont11_det_polizas.rela_siccont02 )
    where siccont11_det_polizas.rela_siccont02 = :id_siccont02
    and siccont11_det_polizas.siccont11_ano = :ano
    and siccont11_det_polizas.siccont11_mes = :mes
    order by siccont10_cab_polizas.siccont10_fcta, siccont10_cab_polizas.siccont10_docnro
    into :id_siccont10,
         :siccont10_docnro,
         :siccont10_descripcion,
         :siccont10_fcta,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :siccont02_tipo,
         :siccont11_debe,
         :siccont11_haber,
         :siccont11_referencia
    do
    begin
        if (siccont11_debe <> 0) then
            acumulado = acumulado + siccont11_debe;
        else  if (siccont11_haber <> 0) then
            acumulado = acumulado - siccont11_haber;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICCONT11_RESULTADO (
    ID_SOCMAIN01 BIGINT,
    ANO INTEGER,
    MES INTEGER,
    CREA_TEMPORARIO INTEGER)
RETURNS (
    ID_SICCONT02 BIGINT,
    SOCSYST06_NIVEL INTEGER,
    SICCONT02_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CATALOGO_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_HISTORICO DOUBLE PRECISION,
    SALDO_ACTUAL DOUBLE PRECISION,
    SALDO_MES DOUBLE PRECISION)
AS
declare variable NATURALEZ_CUENTA_PRINCIPAL varchar(1);
begin
    delete from tmp_siccont11_resultado where tmp_siccont11_resultado.usuario = current_user;

    insert into tmp_siccont11_resultado(  tmp_siccont11_resultado.usuario,
                                          tmp_siccont11_resultado.id_siccont02,
                                          tmp_siccont11_resultado.socsyst06_nivel,
                                          tmp_siccont11_resultado.siccont02_tipo,
                                          tmp_siccont11_resultado.catalogo_sat,
                                          tmp_siccont11_resultado.siccont02_codigo_ext,
                                          tmp_siccont11_resultado.siccont02_descripcion,
                                          tmp_siccont11_resultado.saldo_historico,
                                          tmp_siccont11_resultado.saldo_actual,
                                          tmp_siccont11_resultado.saldo_mes  )
    SELECT
    current_user,
    prd_siccont11_balanza_resultado.id_siccont02,
    prd_siccont11_balanza_resultado.socsyst06_nivel,
    prd_siccont11_balanza_resultado.siccont02_tipo,
    prd_siccont11_balanza_resultado.catalogo_sat,
    prd_siccont11_balanza_resultado.siccont02_codigo_ext,
    prd_siccont11_balanza_resultado.siccont02_descripcion,
    iif(prd_siccont11_balanza_resultado.saldo_historico is null, 0, prd_siccont11_balanza_resultado.saldo_historico) ,
    iif(prd_siccont11_balanza_resultado.saldo_actual is null, 0, prd_siccont11_balanza_resultado.saldo_actual) ,
    iif(prd_siccont11_balanza_resultado.saldo_mes is null, 0, prd_siccont11_balanza_resultado.saldo_mes )
    FROM prd_siccont11_balanza_resultado(:id_socmain01, :ano, :mes, :crea_temporario);

    for select
    tmp_siccont11_resultado.id_siccont02,
    tmp_siccont11_resultado.socsyst06_nivel,
    tmp_siccont11_resultado.siccont02_tipo,
    tmp_siccont11_resultado.catalogo_sat,
    tmp_siccont11_resultado.siccont02_codigo_ext,
    tmp_siccont11_resultado.siccont02_descripcion,
    tmp_siccont11_resultado.saldo_historico,
    tmp_siccont11_resultado.saldo_actual,
    tmp_siccont11_resultado.saldo_mes
    from tmp_siccont11_resultado
    where tmp_siccont11_resultado.usuario = current_user
    order by tmp_siccont11_resultado.siccont02_codigo_ext
    into :id_siccont02,
         :socsyst06_nivel,
         :siccont02_tipo,
         :catalogo_sat,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :saldo_historico,
         :saldo_actual,
         :saldo_mes
    do
    begin
        if (socsyst06_nivel = 2) then
            naturalez_cuenta_principal = :siccont02_tipo;

        if (siccont02_tipo != naturalez_cuenta_principal) then
        begin
            if (saldo_historico > 0) then
                update tmp_siccont11_resultado set tmp_siccont11_resultado.saldo_historico = tmp_siccont11_resultado.saldo_historico * (-1)
                where tmp_siccont11_resultado.usuario = current_user
                and tmp_siccont11_resultado.id_siccont02 = :id_siccont02;

            if (saldo_actual > 0) then
                update tmp_siccont11_resultado set tmp_siccont11_resultado.saldo_actual = tmp_siccont11_resultado.saldo_actual * (-1)
                where tmp_siccont11_resultado.usuario = current_user
                and tmp_siccont11_resultado.id_siccont02 = :id_siccont02;

            if (saldo_mes > 0) then
                update tmp_siccont11_resultado set tmp_siccont11_resultado.saldo_mes = tmp_siccont11_resultado.saldo_mes * (-1)
                where tmp_siccont11_resultado.usuario = current_user
                and tmp_siccont11_resultado.id_siccont02 = :id_siccont02;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICCONT11_RESULTADO_CAB (
    ID_SOCMAIN01X BIGINT,
    ANO INTEGER,
    MES INTEGER)
RETURNS (
    ID_SOCMAIN01 BIGINT,
    EMPRESA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INGRESOS DOUBLE PRECISION,
    INGRESOS_INI DOUBLE PRECISION,
    INGRESOS_MES DOUBLE PRECISION,
    INGRESOS_TOTAL DOUBLE PRECISION,
    EGRESOS_COSTOS_COMPRAS DOUBLE PRECISION,
    EGRESOS_COSTOS_COMPRAS_INI DOUBLE PRECISION,
    EGRESOS_COSTOS_COMPRAS_MES DOUBLE PRECISION,
    EGRESOS_GASTOS_OPERATIVOS DOUBLE PRECISION,
    EGRESOS_GASTOS_OPERATIVOS_INI DOUBLE PRECISION,
    EGRESOS_GASTOS_OPERATIVOS_MES DOUBLE PRECISION,
    EGRESOS_GASTOS_NOOPERATIVOS DOUBLE PRECISION,
    EGRESOS_GASTOS_NOOPERATIVOS_INI DOUBLE PRECISION,
    EGRESOS_GASTOS_NOOPERATIVOS_MES DOUBLE PRECISION,
    EGRESOS_TOTAL DOUBLE PRECISION,
    EGRESOS_INI DOUBLE PRECISION,
    EGRESOS_MES DOUBLE PRECISION,
    UTILIDAD DOUBLE PRECISION,
    UTILIDAD_INICIAL DOUBLE PRECISION,
    UTILIDAD_MES DOUBLE PRECISION)
AS
declare variable TMP_RETO integer;
begin
    id_socmain01 = id_socmain01x;

    select count(rep_siccont11_resultado.id_siccont02)
    from rep_siccont11_resultado(:id_socmain01, :ano, :mes, 1)
    into :tmp_reto;

    Select
    prd_siccont11_resultado_totales.ingresos,
    prd_siccont11_resultado_totales.ingresos_ini,
    prd_siccont11_resultado_totales.ingresos_mes,
    prd_siccont11_resultado_totales.ingresos_total,

    prd_siccont11_resultado_totales.egresos_costos_compras,
    prd_siccont11_resultado_totales.egresos_costos_compras_ini,
    prd_siccont11_resultado_totales.egresos_costos_compras_mes,

    prd_siccont11_resultado_totales.egresos_gastos_operativos,
    prd_siccont11_resultado_totales.egresos_gastos_operativos_ini,
    prd_siccont11_resultado_totales.egresos_gastos_operativos_mes,

    prd_siccont11_resultado_totales.egresos_gastos_nooperativos,
    prd_siccont11_resultado_totales.egresos_gastos_nooperativos_ini,
    prd_siccont11_resultado_totales.egresos_gastos_nooperativos_mes,

    prd_siccont11_resultado_totales.egresos_total,
    prd_siccont11_resultado_totales.egreso_ini,
    prd_siccont11_resultado_totales.egreso_mes,

    prd_siccont11_resultado_totales.utilidad,
    prd_siccont11_resultado_totales.utilidad_inicial,
    prd_siccont11_resultado_totales.utilidad_mes

    from prd_siccont11_resultado_totales
    into :ingresos,
         :ingresos_ini,
         :ingresos_mes,
         :ingresos_total,

         :egresos_costos_compras,
         :egresos_costos_compras_ini,
         :egresos_costos_compras_mes,

         :egresos_gastos_operativos,
         :egresos_gastos_operativos_ini,
         :egresos_gastos_operativos_mes,

         :egresos_gastos_nooperativos,
         :egresos_gastos_nooperativos_ini,
         :egresos_gastos_nooperativos_mes,

         :egresos_total,
         :egresos_ini,
         :egresos_mes,

         :utilidad,
         :utilidad_inicial,
         :utilidad_mes;

    select
    cbo_socmain01_cfdi.socmain01_nomcomercial,
    cbo_socmain01_cfdi.rfc
    from cbo_socmain01_cfdi
    where cbo_socmain01_cfdi.id_socmain01 = :id_socmain01
    into :empresa,
         :rfc;


    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICCONT11_RESULTADO_FILTRO (
    CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SICCONT02 BIGINT,
    SOCSYST06_NIVEL INTEGER,
    CATALOGO_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_HISTORICO DOUBLE PRECISION,
    SALDO_ACTUAL DOUBLE PRECISION,
    SALDO_MES DOUBLE PRECISION)
AS
declare variable SUMA double precision;
declare variable ENTRO integer;
begin
    entro = 0;

    for select
    tmp_siccont11_resultado.id_siccont02,
    tmp_siccont11_resultado.socsyst06_nivel,
    tmp_siccont11_resultado.catalogo_sat,
    tmp_siccont11_resultado.siccont02_codigo_ext,
    tmp_siccont11_resultado.siccont02_descripcion,
    tmp_siccont11_resultado.saldo_historico,
    tmp_siccont11_resultado.saldo_actual,
    tmp_siccont11_resultado.saldo_mes
    from tmp_siccont11_resultado
    where tmp_siccont11_resultado.usuario = current_user
    and tmp_siccont11_resultado.siccont02_codigo_ext like :codigo || '%'
    and tmp_siccont11_resultado.siccont02_codigo_ext <> :codigo
    order by tmp_siccont11_resultado.siccont02_codigo_ext
    into :id_siccont02,
         :socsyst06_nivel,
         :catalogo_sat,
         :siccont02_codigo_ext,
         :siccont02_descripcion,
         :saldo_historico,
         :saldo_actual,
         :saldo_mes
    do
    begin
        suma = saldo_historico + saldo_actual + saldo_mes;

        if (suma <> 0) then
        begin
            entro = 1;
            suspend;
        end
    end

    if (entro = 0) then
    begin
        siccont02_descripcion = 'Sin movimiento';
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICEGRE50 (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    ID_SICEGRE01 BIGINT,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL DOUBLE PRECISION,
    PORCENTAJE DOUBLE PRECISION)
AS
declare variable TOTAL_CTAS double precision;
begin
    select sum(sicegre50_det_ctacte.sicegre50_importe)
    from sicegre50_det_ctacte
    where sicegre50_det_ctacte.rela_socmain01 = :id_socmain01
    into :total_ctas;
    
    for Select
    cbo_sicegre01_id.id_sicegre01,
    cbo_sicegre01_id.rfc,
    cbo_sicegre01_id.entidad,
    sum(sicegre50_det_ctacte.sicegre50_importe)
    FROM sicegre50_det_ctacte
    INNER JOIN cbo_sicegre01_id ON ( cbo_sicegre01_id.id_sicegre01 = sicegre50_det_ctacte.rela_sicegre01 )
    where sicegre50_det_ctacte.rela_socmain01 = :id_socmain01
    group by cbo_sicegre01_id.id_sicegre01,
             cbo_sicegre01_id.rfc,
             cbo_sicegre01_id.entidad,
             sicegre50_det_ctacte.rela_socmain01
    having sum(sicegre50_det_ctacte.sicegre50_importe) <> 0
    into :id_sicegre01,
         :rfc,
         :entidad,
         :total
    do
    begin
        porcentaje = total / total_ctas * 100;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICEGRE50_CAB (
    ID_SOCMAIN01 BIGINT,
    ID_SICEGRE01X BIGINT)
RETURNS (
    ID_SICEGRE01 BIGINT,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL_INGRESOS DOUBLE PRECISION)
AS
begin
    id_sicegre01 = :id_sicegre01x;

    select
    cbo_sicegre01_id.entidad,
    cbo_sicegre01_id.rfc
    from cbo_sicegre01_id
    where cbo_sicegre01_id.id_sicegre01 = :id_sicegre01
    into :entidad,
         :rfc;

    select sum( rep_sicingr50.total )
    from rep_sicingr50(:id_socmain01)
    into :total_ingresos;

    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICEGRE50_PAGADAS (
    RELA_SOCMAIN01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SICCONT10 BIGINT,
    RELA_SICEGRE50 BIGINT,
    ID_SICXMLS41 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICXMLS41_ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID_FECHA DATE,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO_FACTURA DOUBLE PRECISION,
    FECHA DATE,
    EJECUTADO DOUBLE PRECISION,
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS INTEGER,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SICEGRE60_FCTA date;
begin
    for select
    (
      select sicegre50_det_ctacte.id_sicegre50
      from sicegre50_det_ctacte
      where sicegre50_det_ctacte.rela_siccont10 = sicxmls41_det_migracion.rela_siccont10
    ),
    sicxmls41_det_migracion.rela_siccont10,
    sicxmls41_det_migracion.id_sicxmls41,
    sicxmls41_det_migracion.sicxmls41_entidad,
    sicxmls41_det_migracion.sicxmls41_rfc,
    sicxmls41_det_migracion.sicxmls41_folio,
    sicxmls41_det_migracion.sicxmls41_uuid,
    sicxmls41_det_migracion.sicxmls41_uuid_importe,
    sicxmls41_det_migracion.sicxmls41_metododepago,
    sicxmls41_det_migracion.sicxmls41_formapago,
    sicxmls41_det_migracion.sicxmls41_uuid_fecha
    from sicxmls41_det_migracion
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01 )
    inner join sicxmls40_cab_migracion on ( sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40 )
    where sicxmls40_cab_migracion.rela_socmain01 = :rela_socmain01
    and (socsyst10_det_entradas.socsyst10_codigo = 'PROVE' OR socsyst10_det_entradas.socsyst10_codigo = 'PROVEX')
    and sicxmls41_det_migracion.sicxmls41_uuid_fecha between :fecha_desde and :fecha_hasta
    into :rela_sicegre50,
         :rela_siccont10,
         :id_sicxmls41,
         :sicxmls41_entidad,
         :sicxmls41_rfc,
         :sicxmls41_folio,
         :sicxmls41_uuid,
         :sicxmls41_uuid_importe,
         :sicxmls41_metododepago,
         :sicxmls41_formapago,
         :sicxmls41_uuid_fecha
    do
    begin
        origen = 'Bancos';
        importe_pago = null;
        siccont10_docnro = null;
        siccont10_fcta = null;
        ejecutado = 0.00;
        fecha = null;
        CRP = '';

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
        else
           CRP = 'No';

        if (rela_siccont10 is null) then
            origen = 'Sin Contabilidad';
        else
        begin
            select
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta
            from siccont10_cab_polizas
            where siccont10_cab_polizas.id_siccont10 = :rela_siccont10
            into :siccont10_docnro,
                 :siccont10_fcta;

            select
            max(sicegre51_cab_bancos.sicegre51_fecha),
            sum(SICEGRE52_det_bancos.SICEGRE52_importe)
            from sicegre51_cab_bancos
            inner join sicegre52_det_bancos on ( sicegre52_det_bancos.rela_sicegre51 = sicegre51_cab_bancos.id_sicegre51 )
            and sicegre52_det_bancos.rela_sicegre50 = :rela_sicegre50
            into :fecha,
                 :importe_pago;
    
            if (importe_pago is null) then
            begin
                importe_pago = 0.00;
                sicegre60_fcta = null;
    
                select sicegre60_cab_rendicion.sicegre60_fcta
                from sicegre60_cab_rendicion
                inner join sicegre61_det_rendicion on ( sicegre61_det_rendicion.rela_sicegre60 = sicegre60_cab_rendicion.id_sicegre60 )
                inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre61_det_rendicion.rela_siccont10 )
                where sicegre61_det_rendicion.rela_sicegre50 = :rela_sicegre50
                into :sicegre60_fcta;
    
                if (sicegre60_fcta is not null) then
                begin
                   origen = 'Rendición';
                   fecha = sicegre60_fcta;
                   ejecutado = 100.00;
                   importe_pago = sicxmls41_uuid_importe;
                end
    
            end
            else
            begin
                ejecutado =  importe_pago / sicxmls41_uuid_importe * 100;
            end
        end

        importe_pago = iif(importe_pago is null, 0, importe_pago);

        saldo_factura = sicxmls41_uuid_importe - importe_pago;

        if (ejecutado = 0) then
            dias = DATEDIFF(day, :sicxmls41_uuid_fecha, current_date);
        else
            dias = DATEDIFF(day, :sicxmls41_uuid_fecha, fecha);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICEGRE50_PROVEEDOR (
    ID_SOCMAIN01 BIGINT,
    ID_SICEGRE01 BIGINT,
    MODO INTEGER)
RETURNS (
    ID_SICEGRE50 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EJECUTADO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REF_POLIZA VARCHAR(5000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REF_DIAS INTEGER,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    FECHA DATE,
    UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS INTEGER)
AS
begin
    FOR SELECT
    GRD_SICEGRE50_MOV.id_sicegre50,
    GRD_SICEGRE50_MOV.status,
    GRD_SICEGRE50_MOV.ejecutado,
    GRD_SICEGRE50_MOV.poliza,
    GRD_SICEGRE50_MOV.folio,
    GRD_SICEGRE50_MOV.importe_xml,
    GRD_SICEGRE50_MOV.importe_banco,
    GRD_SICEGRE50_MOV.importe_saldo,
    GRD_SICEGRE50_MOV.fecha,
    GRD_SICEGRE50_MOV.uuid_sat,
    GRD_SICEGRE50_MOV.cotiza,
    GRD_SICEGRE50_MOV.moneda,
    GRD_SICEGRE50_MOV.siccont10_docnro_ref,
    GRD_SICEGRE50_MOV.dias_ref
    FROM GRD_SICEGRE50_MOV(:id_socmain01, :id_sicegre01, '01-01-2010', '01-01-2064')
    order by GRD_SICEGRE50_MOV.poliza
    into :id_sicegre50,
         :status,
         :ejecutado,
         :poliza,
         :folio,
         :importe_xml,
         :importe_banco,
         :importe_saldo,
         :fecha,
         :uuid_sat,
         :cotiza,
         :moneda,
         :ref_poliza,
         :ref_dias
    do
    begin
        dias = datediff(DAY FROM :fecha TO current_date);

        if (MODO = 0) then
            suspend;
        else if (MODO = 1) then
        begin
            if (importe_saldo <> 0) then
                suspend;
        end
        else if (MODO = 2) then
        begin
            if (status = 'Factura Recibida' and importe_saldo = 0) then
                suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE REP_SICEGRE50_SUM (
    ID_SICXMLS41 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ULTFECHA DATE,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO_FACTURA DOUBLE PRECISION,
    EJECUTADO DOUBLE PRECISION,
    DIAS INTEGER)
AS
declare variable SICEGRE60_FCTA date;
declare variable SICXMLS41_UUID_IMPORTE double precision;
declare variable SICXMLS41_UUID_FECHA date;
declare variable RELA_SICEGRE50 bigint;
declare variable STR_SQL_BANCOS varchar(1000);
declare variable STR_SQL_RENDICION varchar(1000);
begin
    select
    (
      select sicegre50_det_ctacte.id_sicegre50
      from sicegre50_det_ctacte
      where sicegre50_det_ctacte.rela_siccont10 = sicxmls41_det_migracion.rela_siccont10
    ),
    sicxmls41_det_migracion.sicxmls41_uuid_importe,
    sicxmls41_det_migracion.sicxmls41_uuid_fecha
    from sicxmls41_det_migracion
    where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41
    into :rela_sicegre50,
         :sicxmls41_uuid_importe,
         :sicxmls41_uuid_fecha;

    origen = 'Bancos';
    importe_pago = null;
    ejecutado = 0.00;
    ultfecha = null;

    if (fecha_desde is null and fecha_hasta is null) then
    begin
        str_sql_bancos = 'select
                          max(sicegre51_cab_bancos.sicegre51_fecha),
                          sum(SICEGRE52_det_bancos.SICEGRE52_importe)
                          from sicegre51_cab_bancos
                          inner join SICEGRE52_det_bancos on ( SICEGRE52_det_bancos.rela_sicegre51 = sicegre51_cab_bancos.id_sicegre51 )
                          and SICEGRE52_det_bancos.rela_sicegre50 = ' || :rela_sicegre50;

        str_sql_rendicion = 'select SICEGRE60_CAB_RENDICION.sicegre60_fcta_rend
                             from SICEGRE60_CAB_RENDICION
                             inner join sicegre61_det_rendicion on ( sicegre61_det_rendicion.rela_sicegre60 = sicegre60_cab_rendicion.id_sicegre60 )
                             inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre61_det_rendicion.rela_siccont10 )
                             where sicegre61_det_rendicion.rela_sicegre50 = ' || :rela_sicegre50 ||
                            ' and SICEGRE60_CAB_RENDICION.sicegre60_fcta_rend is not null';

    end
    else
    begin
        str_sql_bancos = 'select
                          max(sicegre51_cab_bancos.sicegre51_fecha),
                          sum(SICEGRE52_det_bancos.SICEGRE52_importe)
                          from sicegre51_cab_bancos
                          inner join SICEGRE52_det_bancos on ( SICEGRE52_det_bancos.rela_sicegre51 = sicegre51_cab_bancos.id_sicegre51 )
                          and SICEGRE52_det_bancos.rela_sicegre50 = ' || :rela_sicegre50 ||
                          ' and sicegre51_cab_bancos.sicegre51_importe <> 0 ' ||
                          ' and sicegre51_cab_bancos.sicegre51_fecha between ''' || :fecha_desde || ''' and ''' || :fecha_hasta || '''';

        str_sql_rendicion = 'select SICEGRE60_CAB_RENDICION.sicegre60_fcta_rend
                             from SICEGRE60_CAB_RENDICION
                             inner join sicegre61_det_rendicion on ( sicegre61_det_rendicion.rela_sicegre60 = sicegre60_cab_rendicion.id_sicegre60 )
                             inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicegre61_det_rendicion.rela_siccont10 )
                             where sicegre61_det_rendicion.rela_sicegre50 = ' || :rela_sicegre50 ||
                             ' and SICEGRE60_CAB_RENDICION.sicegre60_fcta_rend is not null' ||
                             ' and SICEGRE60_CAB_RENDICION.sicegre60_fcta_rend between ''' || :fecha_desde || ''' and ''' || :fecha_hasta || '''';
    end

    execute statement :str_sql_bancos
    into :ultfecha,
         :importe_pago;

    if (importe_pago is not null and importe_pago < 0) then
        importe_pago = importe_pago * (-1);

    if (importe_pago is null) then
    begin
        importe_pago = 0.00;
        sicegre60_fcta = null;
    
        execute statement :str_sql_rendicion
        into :sicegre60_fcta;
    
        if (sicegre60_fcta is not null) then
        begin
            origen = 'Depósitos';
            ultfecha = sicegre60_fcta;
            ejecutado = 100.00;
            importe_pago = sicxmls41_uuid_importe;
        end
    end
    else
    begin
        ejecutado =  importe_pago / sicxmls41_uuid_importe * 100;
    end

    importe_pago = iif(importe_pago is null, 0, importe_pago);

    saldo_factura = sicxmls41_uuid_importe - importe_pago;

    if (ejecutado = 0) then
        dias = DATEDIFF(day, :sicxmls41_uuid_fecha, current_date);
    else
        dias = DATEDIFF(day, :sicxmls41_uuid_fecha, ultfecha);

    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICINGR50 (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    ID_SICINGR01 BIGINT,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL DOUBLE PRECISION,
    PORCENTAJE DOUBLE PRECISION)
AS
declare variable TOTAL_CTAS double precision;
begin
    select sum(sicingr50_det_ctacte.sicingr50_importe)
    from sicingr50_det_ctacte
    where sicingr50_det_ctacte.rela_socmain01 = :id_socmain01
    into :total_ctas;
    
    for Select
    cbo_sicingr01_id.id_sicingr01,
    cbo_sicingr01_id.rfc,
    cbo_sicingr01_id.entidad,
    sum(sicingr50_det_ctacte.sicingr50_importe)
    FROM sicingr50_det_ctacte
    INNER JOIN cbo_sicingr01_id ON ( cbo_sicingr01_id.id_sicingr01 = sicingr50_det_ctacte.rela_sicingr01 )
    where sicingr50_det_ctacte.rela_socmain01 = :id_socmain01
    group by cbo_sicingr01_id.id_sicingr01,
             cbo_sicingr01_id.rfc,
             cbo_sicingr01_id.entidad,
             sicingr50_det_ctacte.rela_socmain01
    having sum(sicingr50_det_ctacte.sicingr50_importe) <> 0
    into :id_sicingr01,
         :rfc,
         :entidad,
         :total
    do
    begin
        porcentaje = total / total_ctas * 100;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR50_CAB (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01X BIGINT)
RETURNS (
    ID_SICINGR01 BIGINT,
    ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOTAL_EGRESOS DOUBLE PRECISION)
AS
begin
    id_sicingr01 = :id_sicingr01x;

    select
    cbo_sicingr01_id.entidad,
    cbo_sicingr01_id.rfc
    from cbo_sicingr01_id
    where cbo_sicingr01_id.id_sicingr01 = :id_sicingr01
    into :entidad,
         :rfc;

    select sum( rep_sicegre50.total )
    from rep_sicegre50(:id_socmain01)
    into :total_egresos;

    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICINGR50_CLIENTE (
    ID_SOCMAIN01 BIGINT,
    ID_SICINGR01 BIGINT,
    MODO INTEGER)
RETURNS (
    ID_SICINGR50 BIGINT,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EJECUTADO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REF_POLIZA VARCHAR(5000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REF_DIAS INTEGER,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_XML DOUBLE PRECISION,
    IMPORTE_BANCO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    FECHA DATE,
    UUID_SAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COTIZA DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS INTEGER)
AS
begin
    FOR SELECT
    GRD_SICINGR50_MOV.id_sicingr50,
    GRD_SICINGR50_MOV.status,
    GRD_SICINGR50_MOV.ejecutado,
    GRD_SICINGR50_MOV.poliza,
    GRD_SICINGR50_MOV.folio,
    GRD_SICINGR50_MOV.importe_xml,
    GRD_SICINGR50_MOV.importe_banco,
    GRD_SICINGR50_MOV.importe_saldo,
    GRD_SICINGR50_MOV.fecha,
    GRD_SICINGR50_MOV.uuid_sat,
    GRD_SICINGR50_MOV.cotiza,
    GRD_SICINGR50_MOV.moneda,
    GRD_SICINGR50_MOV.siccont10_docnro_ref,
    GRD_SICINGR50_MOV.dias_ref
    FROM GRD_SICINGR50_MOV(:id_socmain01, :id_sicingr01, '01-01-2010', '01-01-2064')
    order by GRD_SICINGR50_MOV.poliza
    into :id_sicingr50,
         :status,
         :ejecutado,
         :poliza,
         :folio,
         :importe_xml,
         :importe_banco,
         :importe_saldo,
         :fecha,
         :uuid_sat,
         :cotiza,
         :moneda,
         :ref_poliza,
         :ref_dias
    do
    begin
        dias = datediff(DAY FROM :fecha TO current_date);

        if (MODO = 0) then
            suspend;
        else if (MODO = 1) then
        begin
            if (importe_saldo <> 0) then
                suspend;
        end
        else if (MODO = 2) then
        begin
            if (status = 'Factura Emitida' and importe_saldo = 0) then
                suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR50_COBRADAS (
    RELA_SOCMAIN01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    ID_SICXMLS41 BIGINT,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SICXMLS41_ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_METODODEPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_FORMAPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CRP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION,
    SICXMLS41_UUID_FECHA DATE,
    SICXMLS41_MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_CAMBIO INTEGER,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO_FACTURA DOUBLE PRECISION,
    FECHA DATE,
    EJECUTADO DOUBLE PRECISION,
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS INTEGER)
AS
declare variable RELA_SICCONT10 bigint;
begin
    for select
    sicxmls41_det_migracion.rela_siccont10,
    sicxmls41_det_migracion.id_sicxmls41,
    sicxmls41_det_migracion.sicxmls41_entidad,
    sicxmls41_det_migracion.sicxmls41_rfc,
    sicxmls41_det_migracion.sicxmls41_folio,
    sicxmls41_det_migracion.sicxmls41_uuid,
    sicxmls41_det_migracion.sicxmls41_metododepago,
    sicxmls41_det_migracion.sicxmls41_formapago,
    sicxmls41_det_migracion.sicxmls41_uuid_importe * sicxmls41_det_migracion.sicxmls41_cambio,
    sicxmls41_det_migracion.sicxmls41_uuid_fecha,
    sicxmls41_det_migracion.sicxmls41_moneda,
    sicxmls41_det_migracion.sicxmls41_cambio
    from sicxmls41_det_migracion
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = sicxmls41_det_migracion.rela_socsyst10_tct01 )
    inner join sicxmls40_cab_migracion on ( sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40 )
    where sicxmls40_cab_migracion.rela_socmain01 = :rela_socmain01
    and (socsyst10_det_entradas.socsyst10_codigo = 'CLIENTE' OR socsyst10_det_entradas.socsyst10_codigo = 'CLIENTEX')
    and sicxmls41_det_migracion.sicxmls41_uuid_fecha between :fecha_desde and :fecha_hasta
    into :rela_siccont10,
         :id_sicxmls41,
         :sicxmls41_entidad,
         :sicxmls41_rfc,
         :sicxmls41_folio,
         :sicxmls41_uuid,
         :sicxmls41_metododepago,
         :sicxmls41_formapago,
         :sicxmls41_uuid_importe,
         :sicxmls41_uuid_fecha,
         :sicxmls41_moneda,
         :sicxmls41_cambio
    do
    begin
        origen = 'Bancos';
        importe_pago = 0.00;
        siccont10_docnro = null;
        siccont10_fcta = null;
        ejecutado = 0.00;
        fecha = null;
        saldo_factura = :sicxmls41_uuid_importe;
        dias = 0;

        if (sicxmls41_formapago = '99' and sicxmls41_metododepago = 'PPD') then
           CRP = 'Si';
        else
           CRP = 'No';

        if (rela_siccont10 is null) then
        begin
            origen = 'Sin Contabilidad';
        end
        else
        begin
            select
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.siccont10_fcta
            from siccont10_cab_polizas
            where siccont10_cab_polizas.id_siccont10 = :rela_siccont10
            into :siccont10_docnro,
                 :siccont10_fcta;

            select
            rep_sicingr50_sum.origen,
            rep_sicingr50_sum.importe_pago,
            rep_sicingr50_sum.ultfecha,
            rep_sicingr50_sum.ejecutado,
            rep_sicingr50_sum.saldo_factura,
            rep_sicingr50_sum.dias
            from rep_sicingr50_sum(:id_sicxmls41, null, null)
            into :origen,
                 :importe_pago,
                 :fecha,
                 :ejecutado,
                 :saldo_factura,
                 :dias;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR50_SUM (
    ID_SICXMLS41 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    ORIGEN VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ULTFECHA DATE,
    IMPORTE_PAGO DOUBLE PRECISION,
    SALDO_FACTURA DOUBLE PRECISION,
    EJECUTADO DOUBLE PRECISION,
    DIAS INTEGER)
AS
declare variable SICINGR60_FCTA date;
declare variable SICXMLS41_UUID_IMPORTE double precision;
declare variable SICXMLS41_UUID_FECHA date;
declare variable RELA_SICINGR50 bigint;
declare variable STR_SQL_BANCOS varchar(1000);
declare variable STR_SQL_DEPOSITOS varchar(1000);
begin
    select
    (
      select sicingr50_det_ctacte.id_sicingr50
      from sicingr50_det_ctacte
      where sicingr50_det_ctacte.rela_siccont10 = sicxmls41_det_migracion.rela_siccont10
    ),
    sicxmls41_det_migracion.sicxmls41_uuid_importe,
    sicxmls41_det_migracion.sicxmls41_uuid_fecha
    from sicxmls41_det_migracion
    where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41
    into :rela_sicingr50,
         :sicxmls41_uuid_importe,
         :sicxmls41_uuid_fecha;

    origen = 'Bancos';
    importe_pago = null;
    ejecutado = 0.00;
    ultfecha = null;

    if (fecha_desde is null and fecha_hasta is null) then
    begin
        str_sql_bancos = 'select
                          max(sicingr51_cab_bancos.sicingr51_fecha),
                          sum(SICINGR52_det_bancos.SICINGR52_importe)
                          from sicingr51_cab_bancos
                          inner join sicingr52_det_bancos on ( sicingr52_det_bancos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51 )
                          where sicingr51_cab_bancos.sicingr51_anticipo = 0
                          and sicingr52_det_bancos.rela_sicingr50 = ' || :rela_sicingr50;

        str_sql_depositos = 'select sicingr60_cab_depositos.sicingr60_fcta
                             from sicingr60_cab_depositos
                             inner join sicingr61_det_depositos on ( sicingr61_det_depositos.rela_sicingr60 = sicingr60_cab_depositos.id_sicingr60 )
                             inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr61_det_depositos.rela_siccont10 )
                             where sicingr61_det_depositos.rela_sicingr50 = ' || :rela_sicingr50;
    end
    else
    begin
        str_sql_bancos = 'select
                          max(sicingr51_cab_bancos.sicingr51_fecha),
                          sum(SICINGR52_det_bancos.SICINGR52_importe)
                          from sicingr51_cab_bancos
                          inner join sicingr52_det_bancos on ( sicingr52_det_bancos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51 )
                          where sicingr51_cab_bancos.sicingr51_anticipo = 0
                          and sicingr52_det_bancos.rela_sicingr50 = ' || :rela_sicingr50 ||
                          ' and sicingr51_cab_bancos.sicingr51_fecha between ''' || :fecha_desde || ''' and ''' || :fecha_hasta || '''';

        str_sql_depositos = 'select sicingr60_cab_depositos.sicingr60_fcta
                             from sicingr60_cab_depositos
                             inner join sicingr61_det_depositos on ( sicingr61_det_depositos.rela_sicingr60 = sicingr60_cab_depositos.id_sicingr60 )
                             inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = sicingr61_det_depositos.rela_siccont10 )
                             where sicingr61_det_depositos.rela_sicingr50 = ' || :rela_sicingr50 ||
                             ' and sicingr60_cab_depositos.sicingr60_fcta between ''' || :fecha_desde || ''' and ''' || :fecha_hasta || '''';
    end

    execute statement :str_sql_bancos
    into :ultfecha,
         :importe_pago;

    if (importe_pago is not null and importe_pago < 0) then
        importe_pago = importe_pago * (-1);

    if (importe_pago is null) then
    begin
        importe_pago = 0.00;
        sicingr60_fcta = null;
    
        execute statement :str_sql_depositos
        into :sicingr60_fcta;
    
        if (sicingr60_fcta is not null) then
        begin
            origen = 'Depósitos';
            ultfecha = sicingr60_fcta;
            ejecutado = 100.00;
            importe_pago = sicxmls41_uuid_importe;
        end
    end
    else
    begin
        ejecutado =  importe_pago / sicxmls41_uuid_importe * 100;
    end

    importe_pago = iif(importe_pago is null, 0, importe_pago);

    saldo_factura = sicxmls41_uuid_importe - importe_pago;

    if (ejecutado = 0) then
        dias = DATEDIFF(day, :sicxmls41_uuid_fecha, current_date);
    else
        dias = DATEDIFF(day, :sicxmls41_uuid_fecha, ultfecha);

    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICINGR70 (
    ID_SICINGR70X BIGINT)
RETURNS (
    ID_SICINGR70 BIGINT,
    EMPRESA_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_NOCERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CODPOSTAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA TIMESTAMP,
    SICINGR70_SUBTOTAL DOUBLE PRECISION,
    SICINGR70_DESCUENTO DOUBLE PRECISION,
    SICINGR70_TOTAL DOUBLE PRECISION,
    SICINGR70_TOTIMP_RETENIDOS DOUBLE PRECISION,
    SICINGR70_TOTIMP_TRASLADOS DOUBLE PRECISION,
    SICINGR70_TOTIMP_LOCALES DOUBLE PRECISION,
    SICINGR70_NETO DOUBLE PRECISION,
    SICINGR70_CAMBIO DOUBLE PRECISION,
    CAT_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAT_FDPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAT_TCOMPR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAT_MDPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAT_USOCFD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_FECHA TIMESTAMP,
    SICINGR74_SELLO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_SELLOSAT VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_CADENA VARCHAR(30000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_CERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE_LETRA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CON_CFDIS_RELACIONADOS INTEGER,
    REGIMEN VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGIMEN_RECEPTOR VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR74_UUID_PAGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_ANTICIPO DOUBLE PRECISION,
    SICINGR70_GASTOS DOUBLE PRECISION,
    RELA_SOCSYST10_FF INTEGER,
    TIPORELACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_CONDPAGOS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODPOSTAL_RECEPTOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SICINGR01 bigint;
declare variable COD_MONEDA varchar(50);
declare variable COD_FDPAGO varchar(50);
declare variable COD_TCOMPR varchar(50);
declare variable COD_MDPAGO varchar(50);
declare variable COD_USOCFD varchar(50);
declare variable FORMATO_FACTURA varchar(50);
declare variable IMPORTE_SAL double precision;
declare variable IMPORTE_NUMERO double precision;
declare variable RELA_SOCSYST10_SAT01 bigint;
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SOCUSUA30_EMPRESA bigint;
begin
    con_cfdis_relacionados = 0;

    select
    MONEDA.socsyst10_codigo,
    MONEDA.socsyst10_descripcion,
    FDPAGO.socsyst10_codigo,
    FDPAGO.socsyst10_descripcion,
    TCOMPR.socsyst10_codigo,
    TCOMPR.socsyst10_descripcion,
    MDPAGO.socsyst10_codigo,
    MDPAGO.socsyst10_descripcion,
    USOCFD.socsyst10_codigo,
    USOCFD.socsyst10_descripcion,
    sicingr70_cab_facturacion.rela_socsyst10,
    sicingr70_cab_facturacion.rela_socmain01,
    sicingr70_cab_facturacion.rela_sicingr01,
    sicingr70_cab_facturacion.id_sicingr70,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_fecha,
    sicingr70_cab_facturacion.sicingr70_subtotal,
    sicingr70_cab_facturacion.sicingr70_descuento,
    sicingr70_cab_facturacion.sicingr70_total,
    sicingr70_cab_facturacion.sicingr70_totimp_retenidos,
    sicingr70_cab_facturacion.sicingr70_totimp_traslados,
    sicingr70_cab_facturacion.sicingr70_totimp_locales,
    sicingr70_cab_facturacion.sicingr70_neto,
    sicingr70_cab_facturacion.sicingr70_cambio,
    sicingr70_cab_facturacion.sicingr70_condpagos,
    sicingr70_cab_facturacion.sicingr70_notas,
    sicingr70_cab_facturacion.rela_socsyst10_sat01
    FROM sicingr70_cab_facturacion
    inner join socsyst10_det_remoto MONEDA on ( MONEDA.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ctm01 )
    inner join socsyst10_det_remoto FDPAGO on ( FDPAGO.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_fdp01 )
    inner join socsyst10_det_remoto TCOMPR on ( TCOMPR.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_tcp01 )
    inner join socsyst10_det_remoto MDPAGO on ( MDPAGO.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
    inner join socsyst10_det_remoto USOCFD on ( USOCFD.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_ucf01 )
    WHERE sicingr70_cab_facturacion.id_sicingr70 = :id_sicingr70x
    into :cod_moneda,
         :cat_moneda,
         :cod_fdpago,
         :cat_fdpago,
         :cod_tcompr,
         :cat_tcompr,
         :cod_mdpago,
         :cat_mdpago,
         :cod_usocfd,
         :cat_usocfd,
         :rela_socsyst10_ff,
         :rela_socmain01,
         :rela_sicingr01,
         :id_sicingr70,
         :sicingr70_docnro,
         :sicingr70_fecha,
         :sicingr70_subtotal,
         :sicingr70_descuento,
         :sicingr70_total,
         :sicingr70_totimp_retenidos,
         :sicingr70_totimp_traslados,
         :sicingr70_totimp_locales,
         :sicingr70_neto,
         :sicingr70_cambio,
         :sicingr70_condpagos,
         :sicingr70_notas,
         :rela_socsyst10_sat01;

    if (id_sicingr70 is not null) then
    begin
        Select
        cbo_sicingr01_id.rela_socusua30,
        cbo_sicingr01_id.entidad,
        cbo_sicingr01_id.rfc
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :rela_socusua30,
             :cliente,
             :cliente_rfc;

        select '(' || CBO_SOCSYST10_SAT01.socsyst10_codigo || ') ' || CBO_SOCSYST10_SAT01.socsyst10_descripcion
        from sicingr01_cab_clientes
        join CBO_SOCSYST10_SAT01 on (CBO_SOCSYST10_SAT01.id_socsyst10 = sicingr01_cab_clientes.rela_socsyst10_sat01)
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
        into :regimen_receptor;

        if (regimen_receptor is null) then
            regimen_receptor = '';

        select
        '(' || trim(socusua36_det_domicilios.socusua36_codpostal) || ') ' ||
        trim(socusua36_det_domicilios.socusua36_calle) || ' ' || trim(socusua36_det_domicilios.socusua36_nro) || ', ' ||
        trim(socmain80_cab_codpostales.socmain80_d_estado) || ' ' || trim(socmain80_cab_codpostales.socmain80_d_mnpio) || ', ' ||
        trim(socmain80_cab_codpostales.socmain80_d_asenta)
        from socusua36_det_domicilios
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
        inner join socmain80_cab_codpostales on ( socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80)
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        and socsyst10_det_entradas.socsyst10_codigo = 'PARTICULAR'
        into :codpostal_receptor;

        Select
        cfdi_empresa.rela_socusua30,
        cfdi_empresa.socmain01_nomcomercial,
        cfdi_empresa.socmain01_nocertificado,
        cfdi_empresa.rfc,
        cfdi_empresa.curp,
        cfdi_empresa.razsocial,
        cfdi_empresa.domf_codpostal
        from cfdi_empresa(:rela_socmain01)
        into :rela_socusua30_empresa,
             :empresa_nomcomercial,
             :empresa_nocertificado,
             :empresa_rfc,
             :empresa_curp,
             :empresa_razsocial,
             :empresa_codpostal;

        select
        '(' || trim(socusua36_det_domicilios.socusua36_codpostal) || ') ' ||
        trim(socusua36_det_domicilios.socusua36_calle) || ' ' || trim(socusua36_det_domicilios.socusua36_nro) || ', ' ||
        trim(socmain80_cab_codpostales.socmain80_d_estado) || ' ' || trim(socmain80_cab_codpostales.socmain80_d_mnpio) || ', ' ||
        trim(socmain80_cab_codpostales.socmain80_d_asenta)
        from socusua36_det_domicilios
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
        inner join socmain80_cab_codpostales on ( socmain80_cab_codpostales.id_socmain80 = socusua36_det_domicilios.rela_socmain80)
        where socusua36_det_domicilios.rela_socusua30 = :rela_socusua30_empresa
        and socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
        into :empresa_codpostal;
    
        select
        sicingr74_dep_cfdis.sicingr74_uuid,
        sicingr74_dep_cfdis.sicingr74_uuid_fecha,
        sicingr74_dep_cfdis.sicingr74_sello,
        sicingr74_dep_cfdis.sicingr74_sellosat,
        sicingr74_dep_cfdis.sicingr74_cadena,
        sicingr74_dep_cfdis.sicingr74_certificado,
        sicingr74_dep_cfdis.sicingr74_uuid_pago
        from sicingr74_dep_cfdis
        where sicingr74_dep_cfdis.rela_sicingr70 = :id_sicingr70x
        into :sicingr74_uuid,
             :sicingr74_uuid_fecha,
             :sicingr74_sello,
             :sicingr74_sellosat,
             :sicingr74_cadena,
             :sicingr74_certificado,
             :sicingr74_uuid_pago;

        sicingr70_fecha = iif(sicingr74_uuid_fecha is null, sicingr70_fecha, sicingr74_uuid_fecha);
    
        select socsyst10_det_entradas.socsyst10_codigo
           from socsyst10_det_entradas
          where socsyst10_det_entradas.id_socsyst10 = :rela_socsyst10_ff
           into :formato_factura;

        if (formato_factura = 'SICINGR70-GASTOS3ROS') then
            begin
              select sum(REP_SICINGR85.SICINGR86_IMPORTE)
                from REP_SICINGR85(:ID_SICINGR70)
                into :sicingr70_gastos;

              select sicingr88_det_gastos3ros.sicingr88_importe_cta,
                     sicingr88_det_gastos3ros.sicingr88_importe_sal
                from sicingr88_det_gastos3ros
               where sicingr88_det_gastos3ros.rela_sicingr70 = :ID_SICINGR70
                into :sicingr70_anticipo,
                     :importe_sal;

                if (:importe_sal < 0) then
                   sicingr70_anticipo = :sicingr70_anticipo + (:importe_sal * -1);
             end

        if (:sicingr70_gastos is null) then
           sicingr70_gastos = 0.00;

        if (:sicingr70_anticipo is null) then
           sicingr70_anticipo = 0.00;

        importe_numero = :sicingr70_neto + :sicingr70_gastos - :sicingr70_anticipo;

        if (:importe_numero < 0 ) then
             importe_numero = (:importe_numero * -1);

        select SMX$UTIL_NUM_MEXICO.cnumero
          from SMX$UTIL_NUM_MEXICO(:importe_numero, :cod_moneda)
          into :importe_letra;

        cat_moneda = '(' || cod_moneda || ') ' || cat_moneda;
        cat_fdpago = '(' || cod_fdpago || ') ' || cat_fdpago;
        cat_tcompr = '(' || cod_tcompr || ') ' || cat_tcompr;
        cat_mdpago = '(' || cod_mdpago || ') ' || cat_mdpago;
        cat_usocfd = '(' || cod_usocfd || ') ' || cat_usocfd;

        tiporelacion = null;
        con_cfdis_relacionados = null;

        select first 1
        sicingr73_det_relacionados.id_sicingr73
        from sicingr73_det_relacionados
        where sicingr73_det_relacionados.rela_sicingr70 = :id_sicingr70
        into :con_cfdis_relacionados;

        if (con_cfdis_relacionados is null) then
            con_cfdis_relacionados = 0;
        else
        begin
            tiporelacion = 'Cfdi/s Relacionados';
            con_cfdis_relacionados = 1;
        end

        if (rela_socsyst10_sat01 is null) then
            select
            '(' || socsyst10_det_entradas.socsyst10_codigo || ') ' || socsyst10_det_entradas.socsyst10_descripcion
            from socmain01_cab_empresas
            inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01 )
            where socmain01_cab_empresas.id_socmain01 = :rela_socmain01
            into :regimen;
        else
            select
            '(' || cbo_socsyst10_sat01.socsyst10_codigo || ') ' || cbo_socsyst10_sat01.socsyst10_descripcion
            from cbo_socsyst10_sat01
            where cbo_socsyst10_sat01.id_socsyst10 = :rela_socsyst10_sat01
            into :regimen;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR70_CARTERA (
    PARAM_EMPRESA BIGINT,
    PARAM_ORGANIGRAMA BIGINT,
    PARAM_CLIENTE BIGINT,
    PARAM_MONEDA BIGINT,
    PARAM_TIPO INTEGER)
RETURNS (
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SICXMLS41 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICINGR70 BIGINT,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE,
    TOTAL DOUBLE PRECISION,
    TIPOCAMBIO DOUBLE PRECISION,
    IMPORTE DOUBLE PRECISION,
    DIASCREDITO INTEGER,
    MENOS30 DOUBLE PRECISION,
    MENOS60 DOUBLE PRECISION,
    MENOS90 DOUBLE PRECISION,
    MAS90 DOUBLE PRECISION,
    DIAS INTEGER,
    FECHAPAGO DATE,
    IMPORTE_PARCIAL DOUBLE PRECISION,
    ALCORRIENTE DOUBLE PRECISION,
    TLF_CLIENTE VARCHAR(60) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INTERNET_CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SQLUSER varchar(5000);
declare variable SQLWHERE varchar(1000);
declare variable IMPORTE_TMP double precision;
declare variable TLF_CLIENTE_TMP varchar(11);
declare variable INTERNET_CLIENTE_TMP varchar(400);
BEGIN
  SELECT
      CFDI_EMPRESA.RAZSOCIAL,
      CFDI_EMPRESA.RFC,
      CFDI_EMPRESA.CURP,
      CFDI_EMPRESA.REGISTROPATRONAL
  FROM CFDI_EMPRESA(:PARAM_EMPRESA)
  INTO
      :EMPRESA_RAZSOCIAL,
     :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;



  SQLUSER = 'SELECT
                 SICINGR70_CAB_FACTURACION.RELA_SOCMAIN01,
                 SICINGR70_CAB_FACTURACION.RELA_SOCMAIN21,
                 SICINGR70_CAB_FACTURACION.RELA_SICINGR01,
                 SICXMLS41_DET_MIGRACION.RELA_SICCONT10,
                 SICXMLS41_DET_MIGRACION.id_sicxmls41,
                 SICINGR70_CAB_FACTURACION.RELA_SOCSYST10_CTM01,
                 SICINGR70_CAB_FACTURACION.ID_SICINGR70,
                 SOCMAIN01_CAB_EMPRESAS.SOCMAIN01_NOMCOMERCIAL,
                 SOCMAIN21_ARB_ORGANIZACION.SOCMAIN21_DESCRIPCION,
                 TRIM(SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_APELLIDO_PAT  ||  '' '' ||  SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_APELLIDO_MAT  ||  '' '' ||  SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_NOMBRE_RAZSOC),
                 SOCSYST10_DET_REMOTO.SOCSYST10_CODIGO,
                 SICINGR70_CAB_FACTURACION.SICINGR70_DOCNRO,
                 SICINGR70_CAB_FACTURACION.SICINGR70_FECHA,
                 SICINGR70_CAB_FACTURACION.SICINGR70_NETO,
                 SICINGR70_CAB_FACTURACION.SICINGR70_CAMBIO,
                 SICINGR01_CAB_CLIENTES.SICINGR01_DIASCREDITO
            FROM SICINGR70_CAB_FACTURACION
            INNER JOIN SOCMAIN01_CAB_EMPRESAS ON (SICINGR70_CAB_FACTURACION.RELA_SOCMAIN01 = SOCMAIN01_CAB_EMPRESAS.ID_SOCMAIN01)
            INNER JOIN SOCMAIN21_ARB_ORGANIZACION ON (SICINGR70_CAB_FACTURACION.RELA_SOCMAIN21 = SOCMAIN21_ARB_ORGANIZACION.ID_SOCMAIN21)
            INNER JOIN SOCSYST10_DET_REMOTO ON (SICINGR70_CAB_FACTURACION.RELA_SOCSYST10_CTM01 = SOCSYST10_DET_REMOTO.ID_SOCSYST10)
            INNER JOIN SICINGR01_CAB_CLIENTES ON (SICINGR70_CAB_FACTURACION.RELA_SICINGR01 = SICINGR01_CAB_CLIENTES.ID_SICINGR01)
            INNER JOIN SICINGR74_DEP_CFDIS ON (SICINGR70_CAB_FACTURACION.ID_SICINGR70 = SICINGR74_DEP_CFDIS.RELA_SICINGR70)
            INNER JOIN SICXMLS41_DET_MIGRACION ON (SICINGR74_DEP_CFDIS.RELA_SICXMLS41 = SICXMLS41_DET_MIGRACION.ID_SICXMLS41)
            INNER JOIN SOCUSUA30_CAB_ENTIDADES ON (SICINGR01_CAB_CLIENTES.RELA_SOCUSUA30 = SOCUSUA30_CAB_ENTIDADES.ID_SOCUSUA30)
            WHERE SICINGR70_CAB_FACTURACION.RELA_SOCMAIN01 = ' || :PARAM_EMPRESA ||
            ' AND SICINGR70_CAB_FACTURACION.RELA_SOCMAIN21 = ' || :PARAM_ORGANIGRAMA ||
            ' AND SICINGR70_CAB_FACTURACION.RELA_SOCSYST10_CTM01 = ' || :PARAM_MONEDA;

  SQLWHERE = '';
  IF (:PARAM_CLIENTE != -1) THEN
    SQLWHERE = ' AND SICINGR70_CAB_FACTURACION.RELA_SICINGR01 = ' || :PARAM_CLIENTE;

  FOR EXECUTE STATEMENT :SQLUSER || :SQLWHERE
  INTO
      :RELA_SOCMAIN01,
      :RELA_SOCMAIN21,
      :RELA_SICINGR01,
      :RELA_SICCONT10,
      :RELA_SICXMLS41,
      :RELA_SOCSYST10_CTM01,      
      :ID_SICINGR70,
      :EMPRESA,
      :ORGANIZACION,
      :CLIENTE,
      :MONEDA,
      :DOCNRO,
      :FECHA,
      :TOTAL,
      :TIPOCAMBIO,
      :DIASCREDITO
  DO
  BEGIN
    FECHAPAGO = NULL;
    IMPORTE = 0;
    IMPORTE_TMP = 0;
    IMPORTE_PARCIAL = 0;
    ALCORRIENTE = 0;
    MENOS30 = 0;
    MENOS60 = 0;
    MENOS90 = 0;
    MAS90 = 0;
    tlf_cliente = '';
    internet_cliente = '';

    --Datos del cliente
    for select socusua31_det_telefonos.socusua31_lada || ' ' || socusua31_det_telefonos.socusua31_nro
        FROM socusua31_det_telefonos 
        inner join socusua30_cab_entidades on (socusua31_det_telefonos.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
        inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
    into :tlf_cliente_tmp
    do begin
        tlf_cliente = tlf_cliente || ' , ' || tlf_cliente_tmp;
    end

    for select socusua35_det_internet.socusua35_internet
        FROM socusua35_det_internet
        inner join socusua30_cab_entidades on (socusua35_det_internet.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
        inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.rela_socusua30 = socusua30_cab_entidades.id_socusua30)
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
    into :internet_cliente_tmp
    do begin
         internet_cliente = internet_cliente || ' , ' || internet_cliente_tmp;
    end


    IF (:PARAM_TIPO = 0) THEN
      BEGIN
      --Se obtiene los anticipos y pagos aplicados a esta factura (desde Bancos)
        select SUM(SICINGR52_DET_BANCOS.SICINGR52_IMPORTE) AS IMPORTE
          from SICINGR52_DET_BANCOS
          inner join SICINGR50_DET_CTACTE on (SICINGR52_DET_BANCOS.RELA_SICINGR50 = SICINGR50_DET_CTACTE.ID_SICINGR50)
          inner join SICCONT10_CAB_POLIZAS on (SICINGR50_DET_CTACTE.RELA_SICCONT10 = SICCONT10_CAB_POLIZAS.ID_SICCONT10)
          inner join SICXMLS41_DET_MIGRACION on (SICCONT10_CAB_POLIZAS.ID_SICCONT10 = SICXMLS41_DET_MIGRACION.RELA_SICCONT10)
          inner join SICINGR51_CAB_BANCOS on (SICINGR52_DET_BANCOS.RELA_SICINGR51 = SICINGR51_CAB_BANCOS.ID_SICINGR51)
          where SICXMLS41_DET_MIGRACION.ID_SICXMLS41 = :RELA_SICXMLS41 and
                exists(select SICINGR50_DET_CTACTE.RELA_SICINGR51
                      from SICINGR50_DET_CTACTE
                      where SICINGR50_DET_CTACTE.RELA_SICINGR01 = :RELA_SICINGR01 and
                            SICINGR50_DET_CTACTE.RELA_SICINGR51 is not null)
        INTO :IMPORTE_TMP;

        IMPORTE_TMP = iif(IMPORTE_TMP IS NULL, 0, IMPORTE_TMP);

        --Se obtienen los depositos globales a esta factura
        select sicingr50_det_ctacte.sicingr50_importe
        from sicxmls41_det_migracion
           inner join siccont10_cab_polizas on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
           inner join sicingr50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
           inner join sicingr61_det_depositos on (sicingr50_det_ctacte.id_sicingr50 = sicingr61_det_depositos.rela_sicingr50)
        where sicxmls41_det_migracion.id_sicxmls41 = :RELA_SICXMLS41 and
              sicingr50_det_ctacte.rela_sicingr01 = :RELA_SICINGR01
        into :IMPORTE;

        IMPORTE = iif(IMPORTE IS NULL, 0, IMPORTE);

        IMPORTE = IMPORTE + IMPORTE_TMP;

        IF (:TOTAL > IMPORTE) THEN
          BEGIN
            DIAS = (CAST('NOW' AS DATE) - :FECHA) - DIASCREDITO;

            IF (:DIAS <= 0) THEN
              ALCORRIENTE = TOTAL;
            ELSE
              IF (:DIAS < 30) THEN
                MENOS30 = TOTAL;
              ELSE
                IF (:DIAS >= 30 AND :DIAS < 60) THEN
                  MENOS60 = TOTAL;
                ELSE
                  IF (:DIAS >= 60 AND :DIAS < 90) THEN
                    MENOS90 = TOTAL;
                  ELSE
                    MAS90 = TOTAL;

            SUSPEND;
          END
      END
    ELSE     --Tipo 1
      BEGIN
        FOR select    SICINGR51_CAB_BANCOS.sicingr51_fecha,
              SICINGR52_DET_BANCOS.SICINGR52_IMPORTE
              from SICINGR52_DET_BANCOS
              inner join SICINGR50_DET_CTACTE on (SICINGR52_DET_BANCOS.RELA_SICINGR50 = SICINGR50_DET_CTACTE.ID_SICINGR50)
              inner join SICCONT10_CAB_POLIZAS on (SICINGR50_DET_CTACTE.RELA_SICCONT10 = SICCONT10_CAB_POLIZAS.ID_SICCONT10)
              inner join SICXMLS41_DET_MIGRACION on (SICCONT10_CAB_POLIZAS.ID_SICCONT10 = SICXMLS41_DET_MIGRACION.RELA_SICCONT10)
              inner join SICINGR51_CAB_BANCOS on (SICINGR52_DET_BANCOS.RELA_SICINGR51 = SICINGR51_CAB_BANCOS.ID_SICINGR51)
              where SICXMLS41_DET_MIGRACION.ID_SICXMLS41 = :RELA_SICXMLS41 and
                exists(select SICINGR50_DET_CTACTE.RELA_SICINGR51
                          from SICINGR50_DET_CTACTE
                          where SICINGR50_DET_CTACTE.RELA_SICINGR01 = :RELA_SICINGR01 and
                                SICINGR50_DET_CTACTE.RELA_SICINGR51 is not null)
        UNION ALL
        
            select  siccont10_cab_polizas.siccont10_fcta,
                sicingr50_det_ctacte.sicingr50_importe
            from sicxmls41_det_migracion
               inner join siccont10_cab_polizas on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
               inner join sicingr50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
               inner join sicingr61_det_depositos on (sicingr50_det_ctacte.id_sicingr50 = sicingr61_det_depositos.rela_sicingr50)
            where sicxmls41_det_migracion.id_sicxmls41 = :RELA_SICXMLS41 and
                  sicingr50_det_ctacte.rela_sicingr01 = :RELA_SICINGR01
        INTO
              :FECHAPAGO,
              :IMPORTE_PARCIAL
        DO
        BEGIN
          IMPORTE = IMPORTE + IMPORTE_PARCIAL;
          DIAS = (:FECHAPAGO - :FECHA) - DIASCREDITO;

          IF (:DIAS <= 0) THEN
            ALCORRIENTE = IMPORTE_PARCIAL;
          ELSE
            IF (:DIAS < 30) THEN
              MENOS30 = IMPORTE_PARCIAL;
            ELSE
              IF (:DIAS >= 30 AND :DIAS < 60) THEN
                MENOS60 = IMPORTE_PARCIAL;
              ELSE
                IF (:DIAS >= 60 AND :DIAS < 90) THEN
                  MENOS90 = IMPORTE_PARCIAL;
                ELSE
                  MAS90 = IMPORTE_PARCIAL;
        END

        IF (:FECHAPAGO IS NULL) THEN
          BEGIN
            DIAS = (CAST('NOW' AS DATE) - :FECHA) - DIASCREDITO;

            IF (:DIAS <= 0) THEN
              ALCORRIENTE = TOTAL;
            ELSE
              IF (:DIAS < 30) THEN
                MENOS30 = TOTAL;
              ELSE
                IF (:DIAS >= 30 AND :DIAS < 60) THEN
                  MENOS60 = TOTAL;
                ELSE
                  IF (:DIAS >= 60 AND :DIAS < 90) THEN
                    MENOS90 = TOTAL;
                  ELSE
                    MAS90 = TOTAL;
          END

        IF (:TOTAL > IMPORTE) THEN
          SUSPEND;
      END
  END
END^


CREATE OR ALTER PROCEDURE REP_SICINGR70_CFDIS_RELACION (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID BIGINT,
    TIPO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    ID = 0;
    FOR

    SELECT
    '(' || trim(socsyst10_det_remoto.socsyst10_codigo) || ') ' || socsyst10_det_remoto.socsyst10_descripcion,
    sicxmls41_det_migracion.sicxmls41_uuid
    FROM sicingr73_det_relacionados
    inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = sicingr73_det_relacionados.rela_socsyst10_tre01)
    INNER JOIN sicxmls41_det_migracion ON ( sicxmls41_det_migracion.id_sicxmls41 = sicingr73_det_relacionados.rela_sicxmls41 )
    WHERE sicingr73_det_relacionados.rela_sicingr70 = :rela_sicingr70

    UNION ALL

    SELECT
    '(' || trim(socsyst10_det_remoto.socsyst10_codigo) || ') ' || socsyst10_det_remoto.socsyst10_descripcion,
    sicingr77_det_cfdiscancelados.sicingr77_uuid
    FROM sicingr73_det_relacionados
    inner join socsyst10_det_remoto on (socsyst10_det_remoto.id_socsyst10 = sicingr73_det_relacionados.rela_socsyst10_tre01)
    INNER JOIN sicingr77_det_cfdiscancelados ON (sicingr77_det_cfdiscancelados.id_sicingr77 = sicingr73_det_relacionados.rela_sicingr77)
    WHERE sicingr73_det_relacionados.rela_sicingr70 = :rela_sicingr70


    INTO :tipo,
         :UUID
    do
    begin
        ID = ID + 1;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR70_COBRADAS (
    PARAM_EMPRESA BIGINT,
    PARAM_CLIENTE BIGINT,
    PARAM_FECHADESDE DATE,
    PARAM_FECHAHASTA DATE,
    PARAM_MONEDA BIGINT)
RETURNS (
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    RELA_SICCONT10 BIGINT,
    ID_SICINGR70 BIGINT,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE,
    SUBTOTAL DOUBLE PRECISION,
    DESCUENTO DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TIPOCAMBIO DOUBLE PRECISION,
    IVA DOUBLE PRECISION,
    OTROS DOUBLE PRECISION,
    RETIVA DOUBLE PRECISION,
    RETISR DOUBLE PRECISION,
    IMPORTE DOUBLE PRECISION,
    FECHA_DEPOSITO DATE,
    T_SUBTOTAL DOUBLE PRECISION,
    T_DESCUENTO DOUBLE PRECISION,
    T_IVA DOUBLE PRECISION,
    T_OTROS DOUBLE PRECISION,
    T_RETIVA DOUBLE PRECISION,
    T_RETISR DOUBLE PRECISION,
    T_TOTAL DOUBLE PRECISION,
    C_SUBTOTAL DOUBLE PRECISION,
    C_DESCUENTO DOUBLE PRECISION,
    C_IVA DOUBLE PRECISION,
    C_OTROS DOUBLE PRECISION,
    C_RETIVA DOUBLE PRECISION,
    C_RETISR DOUBLE PRECISION,
    C_TOTAL DOUBLE PRECISION)
AS
declare variable SQLUSER varchar(5000);
declare variable SQLWHERE varchar(1000);
BEGIN
  SELECT
      CFDI_EMPRESA.RAZSOCIAL,
      CFDI_EMPRESA.RFC,
      CFDI_EMPRESA.CURP,
      CFDI_EMPRESA.REGISTROPATRONAL
  FROM CFDI_EMPRESA(:PARAM_EMPRESA)
  INTO
      :EMPRESA_RAZSOCIAL,
      :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;

    IMPORTE = 0;
    FECHA_DEPOSITO = NULL;

    FOR SELECT SICINGR51_CAB_BANCOS.RELA_SOCMAIN01,
               SICINGR51_CAB_BANCOS.RELA_SICINGR01,
               SICINGR50_DET_CTACTE.RELA_SICCONT10,
               CAST(SICINGR52_DET_BANCOS.SICINGR52_FAPL AS DATE) AS FECHA_DEPOSITO,
               SICINGR52_DET_BANCOS.SICINGR52_IMPORTE
          FROM SICINGR50_DET_CTACTE
    INNER JOIN SICINGR52_DET_BANCOS ON (SICINGR50_DET_CTACTE.ID_SICINGR50 = SICINGR52_DET_BANCOS.RELA_SICINGR50)
    INNER JOIN SICINGR51_CAB_BANCOS ON (SICINGR52_DET_BANCOS.RELA_SICINGR51 = SICINGR51_CAB_BANCOS.ID_SICINGR51)
         WHERE SICINGR51_CAB_BANCOS.RELA_SOCMAIN01 = :PARAM_EMPRESA
           AND CAST(SICINGR52_DET_BANCOS.SICINGR52_FAPL AS DATE) BETWEEN :PARAM_FECHADESDE AND :PARAM_FECHAHASTA
    INTO :RELA_SOCMAIN01,
         :RELA_SICINGR01,
         :RELA_SICCONT10,
         :FECHA_DEPOSITO,
         :IMPORTE
    DO BEGIN
      if (IMPORTE > 0) then
        BEGIN

            SQLUSER = 'SELECT SICINGR70_CAB_FACTURACION.RELA_SOCMAIN01,
                       SICINGR70_CAB_FACTURACION.RELA_SOCMAIN21,
                       SICINGR70_CAB_FACTURACION.RELA_SICINGR01,
                       SICINGR70_CAB_FACTURACION.RELA_SOCSYST10_CTM01,
                       SICINGR70_CAB_FACTURACION.ID_SICINGR70,
                       SOCMAIN01_CAB_EMPRESAS.SOCMAIN01_NOMCOMERCIAL,
                       SOCMAIN21_ARB_ORGANIZACION.SOCMAIN21_DESCRIPCION,
                       TRIM(SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_APELLIDO_PAT || '' '' || SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_APELLIDO_MAT || '' '' || SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_NOMBRE_RAZSOC),
                       SOCSYST10_DET_REMOTO.SOCSYST10_CODIGO,
                       SICINGR70_CAB_FACTURACION.SICINGR70_DOCNRO,
                       SICINGR70_CAB_FACTURACION.SICINGR70_FECHA,
                       SICINGR70_CAB_FACTURACION.SICINGR70_SUBTOTAL,
                       SICINGR70_CAB_FACTURACION.SICINGR70_DESCUENTO,
                       SICINGR70_CAB_FACTURACION.SICINGR70_NETO,
                       SICINGR70_CAB_FACTURACION.SICINGR70_CAMBIO
                  FROM SICINGR70_CAB_FACTURACION
            INNER JOIN SOCMAIN01_CAB_EMPRESAS ON (SICINGR70_CAB_FACTURACION.RELA_SOCMAIN01 = SOCMAIN01_CAB_EMPRESAS.ID_SOCMAIN01)
            INNER JOIN SOCMAIN21_ARB_ORGANIZACION ON (SICINGR70_CAB_FACTURACION.RELA_SOCMAIN21 = SOCMAIN21_ARB_ORGANIZACION.ID_SOCMAIN21)
            INNER JOIN SOCSYST10_DET_REMOTO ON (SICINGR70_CAB_FACTURACION.RELA_SOCSYST10_CTM01 = SOCSYST10_DET_REMOTO.ID_SOCSYST10)
            INNER JOIN SICINGR01_CAB_CLIENTES ON (SICINGR70_CAB_FACTURACION.RELA_SICINGR01 = SICINGR01_CAB_CLIENTES.ID_SICINGR01)
            INNER JOIN SICINGR74_DEP_CFDIS ON (SICINGR70_CAB_FACTURACION.ID_SICINGR70 = SICINGR74_DEP_CFDIS.RELA_SICINGR70)
            INNER JOIN SICXMLS41_DET_MIGRACION ON (SICINGR74_DEP_CFDIS.RELA_SICXMLS41 = SICXMLS41_DET_MIGRACION.ID_SICXMLS41)
            INNER JOIN SOCUSUA30_CAB_ENTIDADES ON (SICINGR01_CAB_CLIENTES.RELA_SOCUSUA30 = SOCUSUA30_CAB_ENTIDADES.ID_SOCUSUA30)
                 WHERE SICXMLS41_DET_MIGRACION.RELA_SICCONT10 = ' || :RELA_SICCONT10 ||
                  'AND SICINGR70_CAB_FACTURACION.RELA_SOCSYST10_CTM01 = ' || :PARAM_MONEDA ;

            SQLWHERE = '';

            IF (:PARAM_CLIENTE != -1) THEN
                SQLWHERE = ' AND SICINGR70_CAB_FACTURACION.RELA_SICINGR01 = ' || :PARAM_CLIENTE;

            FOR EXECUTE STATEMENT :SQLUSER || :SQLWHERE
                INTO :RELA_SOCMAIN01,
                     :RELA_SOCMAIN21,
                     :RELA_SICINGR01,
                     :RELA_SOCSYST10_CTM01,
                     :ID_SICINGR70,
                     :EMPRESA,
                     :ORGANIZACION,
                     :CLIENTE,
                     :MONEDA,
                     :DOCNRO,
                     :FECHA,
                     :SUBTOTAL,
                     :DESCUENTO,
                     :TOTAL,
                     :TIPOCAMBIO
            DO BEGIN
                SELECT PRD_SICINGR72_IMPUESTOS.IVA,
                       PRD_SICINGR72_IMPUESTOS.OTROS,
                       PRD_SICINGR72_IMPUESTOS.RETIVA,
                       PRD_SICINGR72_IMPUESTOS.RETISR
                  FROM PRD_SICINGR72_IMPUESTOS(:ID_SICINGR70)
                  INTO :IVA,
                       :OTROS,
                       :RETIVA,
                       :RETISR;

                    SUSPEND;
            END
        END
    END
END^


CREATE OR ALTER PROCEDURE REP_SICINGR70_CONCEPTOS (
    RELA_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR71 BIGINT,
    CANTIDAD DOUBLE PRECISION,
    DESCRIPCION VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOIDENTIFICACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UNIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    VALORUNITARIO DOUBLE PRECISION,
    CLAVEPRODSERV VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVEPRODSERV_DES VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVEUNIDAD VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DESCUENTO DOUBLE PRECISION,
    TRASLADOS DOUBLE PRECISION,
    RETENIDOS DOUBLE PRECISION,
    LOCALES DOUBLE PRECISION,
    PREDIAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    for select
    sicingr71_det_facturacion.id_sicingr71,
    sicingr71_det_facturacion.sicingr71_codigo,
    sicingr71_det_facturacion.sicingr71_concepto,
    sicingr71_det_facturacion.sicingr71_cantidad,
    sicingr71_det_facturacion.sicingr71_importe_unidad,
    sicingr71_det_facturacion.SICINGR71_IMPORTE_TOTAL,
    COD_MEDIDA.socsyst10_codigo,
    COD_MEDIDA.socsyst10_descripcion,
    COD_SERVPRD.socsyst10_codigo,
    COD_SERVPRD.socsyst10_descripcion,
    sicingr71_det_facturacion.sicingr71_importe_descuento,
    sicingr71_det_facturacion.sicingr71_importe_retenido,
    sicingr71_det_facturacion.sicingr71_importe_traslado,
    sicingr71_det_facturacion.sicingr71_importe_locales,
    sicingr71_det_facturacion.sicingr71_predial
    from sicingr71_det_facturacion
    inner join sicingr95_cab_conceptos on ( sicingr95_cab_conceptos.id_sicingr95 = sicingr71_det_facturacion.rela_sicingr95 )
    inner join socsyst10_det_remoto COD_SERVPRD ON ( COD_SERVPRD.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01 )
    inner join socsyst10_det_remoto COD_MEDIDA ON ( COD_MEDIDA.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01 )
    where sicingr71_det_facturacion.rela_sicingr70 = :rela_sicingr70
    into :id_sicingr71,
         :noidentificacion,
         :descripcion,
         :cantidad,
         :valorunitario,
         :importe,
         :claveunidad,
         :unidad,
         :claveprodserv,
         :claveprodserv_des, 
         :descuento,
         :retenidos,
         :traslados,
         :locales,
         :predial
   DO
   BEGIN
        suspend;
   END
end^


CREATE OR ALTER PROCEDURE REP_SICINGR70_EDOCUENTA (
    PARAM_EMPRESA BIGINT,
    PARAM_ORGANIGRAMA BIGINT,
    PARAM_CLIENTE BIGINT,
    PARAM_MONEDA BIGINT,
    PARAM_FECHA_DESDE DATE,
    PARAM_FECHA_HASTA DATE,
    PARAM_SALDO INTEGER)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    RELA_SICCONT10 BIGINT,
    ID_SICXMLS41 BIGINT,
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE,
    TOTAL DOUBLE PRECISION,
    TIPOCAMBIO DOUBLE PRECISION,
    IMPORTETOTAL DOUBLE PRECISION,
    SALDO DOUBLE PRECISION,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DIAS INTEGER,
    MENOS30 DOUBLE PRECISION,
    MENOS60 DOUBLE PRECISION,
    MENOS90 DOUBLE PRECISION,
    MAS90 DOUBLE PRECISION,
    TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SQLUSER varchar(5000);
declare variable SQLWHERE varchar(1000);
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_MONEDA_ANTICIPO bigint;
declare variable TIPOCAMBIO_ANTICIPO double precision;
declare variable IMPORTE double precision;
declare variable TIPOCOMPROBANTE varchar(400);
begin
  select CFDI_EMPRESA.ID_SOCMAIN01, CFDI_EMPRESA.RAZSOCIAL, CFDI_EMPRESA.RFC, CFDI_EMPRESA.CURP,
         CFDI_EMPRESA.REGISTROPATRONAL
  from CFDI_EMPRESA(:PARAM_EMPRESA)
  into :RELA_SOCMAIN01,
      :EMPRESA_RAZSOCIAL,
      :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;

    select CBO_SOCSYST10_CTM01_REMOTO.SOCSYST10_DESCRIPCION
        from CBO_SOCSYST10_CTM01_REMOTO
        where CBO_SOCSYST10_CTM01_REMOTO.ID_SOCSYST10 = :PARAM_MONEDA
        into :MONEDA;

  --Se selecciona el o los clientes de la empresa
  SQLUSER = 'select distinct sicingr50_det_ctacte.rela_sicingr01,
    sicingr01_cab_clientes.rela_socusua30
    from sicingr50_det_ctacte
    inner join sicingr01_cab_clientes on (sicingr01_cab_clientes.id_sicingr01 = sicingr50_det_ctacte.rela_sicingr01)
    where  sicingr50_det_ctacte.rela_socmain01 = ' || :PARAM_EMPRESA || ' and cast(sicingr50_det_ctacte.sicingr50_fapl as date) between ''' || :PARAM_FECHA_DESDE || ''' AND ''' || :PARAM_FECHA_HASTA || '''';

  SQLWHERE = '';
  if (:PARAM_CLIENTE != - 1) then
    SQLWHERE = ' and sicingr50_det_ctacte.rela_sicingr01 = ' || :PARAM_CLIENTE;

  for execute statement :SQLUSER || :SQLWHERE
          into :RELA_SICINGR01, :RELA_SOCUSUA30
  do
  begin
    --Nombre del cliente

    select CBO_SOCUSUA30.ENTIDAD
    from CBO_SOCUSUA30(:RELA_SOCUSUA30)
    into :CLIENTE;

    --Anticipos sin aplicar a ninguna factura o Credito en contra para este cliente
    --Sacando los que corresponda a depositos globaLes
    SQLUSER = 'select
            sicingr50_det_ctacte.sicingr50_importe,
            sicingr50_det_ctacte.sicingr50_fapl,
            siccont10_cab_polizas.rela_socmain21,
            siccont10_cab_polizas.siccont10_docnro,
            siccont10_cab_polizas.id_siccont10,
            siccont10_cab_polizas.rela_socsyst10_ctm01,
            siccont10_cab_polizas.siccont10_cotiza
        from sicingr50_det_ctacte
            inner join siccont10_cab_polizas on (sicingr50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
        where sicingr50_det_ctacte.rela_sicingr01 = ' || :RELA_SICINGR01 || ' and
            sicingr50_det_ctacte.sicingr50_importe < 0 and
            sicingr50_det_ctacte.rela_sicingr51 is null and
            siccont10_cab_polizas.rela_socsyst10_ctm01 = ' || :PARAM_MONEDA ||
            ' and cast(sicingr50_det_ctacte.sicingr50_fapl as date) between ''' || :PARAM_FECHA_DESDE || ''' and ''' || :PARAM_FECHA_HASTA ||
            ''' and sicingr50_det_ctacte.id_sicingr50 <> all (
                select sicingr52_det_bancos.rela_sicingr50
                from sicingr52_det_bancos
                inner join sicingr51_cab_bancos on (sicingr51_cab_bancos.id_sicingr51 = sicingr52_det_bancos.rela_sicingr51)
                where sicingr51_cab_bancos.rela_sicingr01 = ' || :RELA_SICINGR01;

    if (PARAM_ORGANIGRAMA != - 1) then
      SQLUSER = SQLUSER || ' and
            sicingr51_cab_bancos.rela_socmain21 = ' || :PARAM_ORGANIGRAMA;

    SQLUSER = SQLUSER || ') and
        sicingr50_det_ctacte.rela_siccont10 <> all (select
            sicingr61_det_depositos.rela_siccont10
        from sicingr61_det_depositos
           inner join sicingr50_det_ctacte on (sicingr61_det_depositos.rela_sicingr50 = sicingr50_det_ctacte.id_sicingr50)
        where sicingr50_det_ctacte.rela_sicingr01 = ' || :RELA_SICINGR01 || ')';

    for execute statement :SQLUSER
            into :TOTAL,
                :FECHA,
                :RELA_SOCMAIN21,
                :DOCNRO,
                :RELA_SICCONT10,
                :RELA_SOCSYST10_CTM01,
                :TIPOCAMBIO
    do
    begin
      IMPORTETOTAL = 0;
      IMPORTE = 0;
      SALDO = 0;
      MENOS30 = 0;
      MENOS60 = 0;
      MENOS90 = 0;
      MAS90 = 0;

      TIPO = 'Anticipo/Cre. Contra';

      select SOCMAIN21_ARB_ORGANIZACION.SOCMAIN21_DESCRIPCION
      from SOCMAIN21_ARB_ORGANIZACION
      where SOCMAIN21_ARB_ORGANIZACION.ID_SOCMAIN21 = :RELA_SOCMAIN21
      into :ORGANIZACION;

      DIAS = cast('NOW' as date) - :FECHA;

      if ((param_saldo = 1) or (param_saldo = 3)) then  --Saldo negativo o todos
      begin
            suspend;
      end


    end

    --Facturas para este cliente, que no sean credito en contra
    SQLUSER = 'select 
            sicxmls41_det_migracion.rela_siccont10,
            sicingr70_cab_facturacion.rela_socsyst10_ctm01,
            sicxmls40_cab_migracion.rela_socmain21,
            sicxmls41_det_migracion.id_sicxmls41,
            sicxmls41_det_migracion.sicxmls41_folio,
            sicxmls41_det_migracion.sicxmls41_cambio,
            sicxmls40_cab_migracion.sicxmls40_fecha_proceso,
            sicxmls41_det_migracion.sicxmls41_tipocomprobante,
            sicxmls41_det_migracion.sicxmls41_uuid_importe
        from sicingr70_cab_facturacion
           inner join sicingr74_dep_cfdis on (sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70)
           right outer join sicxmls41_det_migracion on (sicingr74_dep_cfdis.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41)
           inner join sicxmls40_cab_migracion on (sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40)
        WHERE sicxmls41_det_migracion.sicxmls41_tipocomprobante = ''I'' and
            sicxmls41_det_migracion.rela_socusua30 = ' || :RELA_SOCUSUA30 || ' AND  sicxmls40_cab_migracion.rela_socmain01 = '
            || :PARAM_EMPRESA || ' AND  sicingr70_cab_facturacion.rela_socsyst10_ctm01 = ' || :PARAM_MONEDA ||
            ' AND  cast(sicxmls41_det_migracion.sicxmls41_uuid_fecha as date) BETWEEN ''' || :PARAM_FECHA_DESDE || ''' AND ''' || :PARAM_FECHA_HASTA || '''';

    if (PARAM_ORGANIGRAMA != - 1) then
      SQLUSER = SQLUSER || ' AND sicxmls40_cab_migracion.rela_socmain21 = ' || :PARAM_ORGANIGRAMA;

    for execute statement :SQLUSER
            into :RELA_SICCONT10,
                :RELA_SOCSYST10_CTM01,
                :RELA_SOCMAIN21,
                :ID_SICXMLS41,
                :DOCNRO,
                :TIPOCAMBIO,
                :FECHA,
                :TIPOCOMPROBANTE,
                :TOTAL
    do
    begin
      IMPORTE = 0;
      SALDO = 0;
      MENOS30 = 0;
      MENOS60 = 0;
      MENOS90 = 0;
      MAS90 = 0;

      select SOCMAIN21_ARB_ORGANIZACION.SOCMAIN21_DESCRIPCION
      from SOCMAIN21_ARB_ORGANIZACION
      where SOCMAIN21_ARB_ORGANIZACION.ID_SOCMAIN21 = :RELA_SOCMAIN21
      into :ORGANIZACION;

      DIAS = cast('NOW' as date) - :FECHA;

      TIPO = 'CFDI';

      IMPORTETOTAL = 0;
      --Se obtiene los anticipos y pagos aplicados a esta factura (desde Bancos)
      for select SICINGR51_CAB_BANCOS.RELA_SOCSYST10_CTM01,
                 SICINGR51_CAB_BANCOS.SICINGR51_COTIZA,
                 SICINGR52_DET_BANCOS.SICINGR52_IMPORTE
          from SICINGR52_DET_BANCOS
          inner join SICINGR50_DET_CTACTE on (SICINGR52_DET_BANCOS.RELA_SICINGR50 = SICINGR50_DET_CTACTE.ID_SICINGR50)
          inner join SICCONT10_CAB_POLIZAS on (SICINGR50_DET_CTACTE.RELA_SICCONT10 = SICCONT10_CAB_POLIZAS.ID_SICCONT10)
          inner join SICXMLS41_DET_MIGRACION on (SICCONT10_CAB_POLIZAS.ID_SICCONT10 = SICXMLS41_DET_MIGRACION.RELA_SICCONT10)
          inner join SICINGR51_CAB_BANCOS on (SICINGR52_DET_BANCOS.RELA_SICINGR51 = SICINGR51_CAB_BANCOS.ID_SICINGR51)
          where SICXMLS41_DET_MIGRACION.ID_SICXMLS41 = :ID_SICXMLS41 and
                exists(select SICINGR50_DET_CTACTE.RELA_SICINGR51
                                                          from SICINGR50_DET_CTACTE
                                                          where SICINGR50_DET_CTACTE.RELA_SICINGR01 = :RELA_SICINGR01 and
                                                                SICINGR50_DET_CTACTE.RELA_SICINGR51 is not null)
          into :RELA_MONEDA_ANTICIPO,
                :TIPOCAMBIO_ANTICIPO,
                :IMPORTE
      do
      begin

        --Se verifica si la moneda de este anticipo coincide con la del CFDI
        if (RELA_SOCSYST10_CTM01 != RELA_MONEDA_ANTICIPO) then
          IMPORTE = IMPORTE / TIPOCAMBIO;--Se convierte el monto del anticipo a la tasa de la factura

        IMPORTETOTAL = IMPORTETOTAL + IMPORTE;
      end

      RELA_MONEDA_ANTICIPO = NULL;
      TIPOCAMBIO_ANTICIPO = 0.0;
      IMPORTE = 0.0;
      --Se obtienen los depositos globales a esta factura
      select  siccont10_cab_polizas.rela_socsyst10_ctm01,
            siccont10_cab_polizas.siccont10_cotiza,
            sicingr50_det_ctacte.sicingr50_importe
        from sicxmls41_det_migracion
           inner join siccont10_cab_polizas on (sicxmls41_det_migracion.rela_siccont10 = siccont10_cab_polizas.id_siccont10)
           inner join sicingr50_det_ctacte on (siccont10_cab_polizas.id_siccont10 = sicingr50_det_ctacte.rela_siccont10)
           inner join sicingr61_det_depositos on (sicingr50_det_ctacte.id_sicingr50 = sicingr61_det_depositos.rela_sicingr50)
        where sicxmls41_det_migracion.id_sicxmls41 = :ID_SICXMLS41 and
              sicingr50_det_ctacte.rela_sicingr01 = :RELA_SICINGR01
        into  :RELA_MONEDA_ANTICIPO,
                :TIPOCAMBIO_ANTICIPO,
                :IMPORTE;

      if (RELA_MONEDA_ANTICIPO  IS NOT NULL) then
      begin
          --Se verifica si la moneda de este anticipo coincide con la del CFDI
          if (RELA_SOCSYST10_CTM01 != RELA_MONEDA_ANTICIPO) then
              IMPORTE = IMPORTE / TIPOCAMBIO;--Se convierte el monto del anticipo a la tasa de la factura
    
          IMPORTETOTAL = IMPORTETOTAL + IMPORTE;
      end

      SALDO = TOTAL - IMPORTETOTAL;

      if (:DIAS < 30) then
        MENOS30 = SALDO;
      else
      if (:DIAS >= 30 and
          :DIAS < 60) then
        MENOS60 = SALDO;
      else
      if (:DIAS >= 60 and
          :DIAS < 90) then
        MENOS90 = SALDO;
      else
        MAS90 = SALDO;

      --SALDO = cast(SALDO as numeric(10,2));

      if ((param_saldo = 0) and (saldo > 0)) then  --Saldo positivo
      begin
            suspend;
      end
      else if ((param_saldo = 1) and (saldo < 0)) then  --Saldo Negativo
      begin
        suspend;
      end
      else if ((param_saldo = 2) and (saldo = 0)) then   --Saldo cero
      begin
        suspend;
      end
      else if (param_saldo = 3) then   --Todos
      begin
        suspend;
      end

    end

  end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR70_EDOCUENTA_AA (
    PARAM_EMPRESA BIGINT,
    PARAM_ORGANIGRAMA BIGINT,
    PARAM_CLIENTE BIGINT,
    PARAM_MONEDA BIGINT,
    PARAM_FECHA_DESDE DATE,
    PARAM_FECHA_HASTA DATE)
RETURNS (
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SICCONT10 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICINGR70 BIGINT,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE,
    SUBTOTAL DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TIPOCAMBIO DOUBLE PRECISION,
    HONORARIOS DOUBLE PRECISION,
    EROGACIONES DOUBLE PRECISION,
    TOTIMP_TRASLADADOS DOUBLE PRECISION,
    TOTIMP_LOCALES DOUBLE PRECISION,
    TOTIMP_RETENIDOS DOUBLE PRECISION,
    IMPUESTOS DOUBLE PRECISION,
    ANTICIPO DOUBLE PRECISION,
    IMPORTE_SAL DOUBLE PRECISION,
    GASTOS DOUBLE PRECISION,
    TOTAL_CTAGASTO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION,
    MENOS30 DOUBLE PRECISION,
    MENOS60 DOUBLE PRECISION,
    MENOS90 DOUBLE PRECISION,
    MAS90 DOUBLE PRECISION,
    DIAS INTEGER,
    PEDIMENTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTETOTAL DOUBLE PRECISION)
AS
declare variable ID_SICINGR85 bigint;
declare variable RELA_SICXMLS41 bigint;
declare variable IMPORTE_PAGO double precision;
declare variable ID_MONEDA_PAGO bigint;
declare variable TIPOCAMBIO_PAGO double precision;
declare variable IMPORTEANTICIPOS double precision;
BEGIN
  SELECT
      CFDI_EMPRESA.RAZSOCIAL,
      CFDI_EMPRESA.RFC,
      CFDI_EMPRESA.CURP,
      CFDI_EMPRESA.REGISTROPATRONAL
  FROM CFDI_EMPRESA(:PARAM_EMPRESA)
  INTO
      :EMPRESA_RAZSOCIAL,
      :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;

  FOR SELECT
    F.RELA_SOCMAIN01,
    F.RELA_SOCMAIN21,
    F.RELA_SICINGR01,
    M.RELA_SICCONT10,
    M.ID_SICXMLS41,
    F.RELA_SOCSYST10_CTM01,
    F.ID_SICINGR70,
    E.SOCMAIN01_NOMCOMERCIAL,
    O.SOCMAIN21_DESCRIPCION,
    TRIM(C.SOCUSUA30_APELLIDO_PAT || ' ' || C.SOCUSUA30_APELLIDO_MAT || ' ' || C.SOCUSUA30_NOMBRE_RAZSOC) AS NOMBRE_CLIENTE,
    R.SOCSYST10_CODIGO,
    F.SICINGR70_DOCNRO,
    F.SICINGR70_FECHA,
    F.SICINGR70_SUBTOTAL,
    F.SICINGR70_TOTIMP_TRASLADOS,
    F.SICINGR70_TOTIMP_LOCALES,
    F.SICINGR70_TOTIMP_RETENIDOS,
    F.SICINGR70_TOTAL,
    F.SICINGR70_CAMBIO
    FROM SICINGR70_CAB_FACTURACION F
    INNER JOIN SOCMAIN01_CAB_EMPRESAS E ON F.RELA_SOCMAIN01 = E.ID_SOCMAIN01
    INNER JOIN SOCMAIN21_ARB_ORGANIZACION O ON F.RELA_SOCMAIN21 = O.ID_SOCMAIN21
    INNER JOIN SOCSYST10_DET_REMOTO R ON F.RELA_SOCSYST10_CTM01 = R.ID_SOCSYST10
    INNER JOIN SICINGR01_CAB_CLIENTES CL ON F.RELA_SICINGR01 = CL.ID_SICINGR01
    INNER JOIN SICINGR74_DEP_CFDIS D ON F.ID_SICINGR70 = D.RELA_SICINGR70
    INNER JOIN SICXMLS41_DET_MIGRACION M ON D.RELA_SICXMLS41 = M.ID_SICXMLS41
    INNER JOIN SOCUSUA30_CAB_ENTIDADES C ON CL.RELA_SOCUSUA30 = C.ID_SOCUSUA30
    WHERE
        F.RELA_SOCMAIN01 = :PARAM_EMPRESA
        AND F.RELA_SOCSYST10_CTM01 = :PARAM_MONEDA
        AND F.SICINGR70_FECHA BETWEEN :PARAM_FECHA_DESDE AND :PARAM_FECHA_HASTA
        AND (:PARAM_ORGANIGRAMA = -1 OR F.RELA_SOCMAIN21 = :PARAM_ORGANIGRAMA)
        AND (:PARAM_CLIENTE = -1 OR F.RELA_SICINGR01 = :PARAM_CLIENTE)
        --AND SICINGR70_DOCNRO = 'F012139' OR SICINGR70_DOCNRO = 'F011965'

  INTO
      :RELA_SOCMAIN01,
      :RELA_SOCMAIN21,
      :RELA_SICINGR01,
      :RELA_SICCONT10,
      :rela_sicxmls41,
      :RELA_SOCSYST10_CTM01,
      :ID_SICINGR70,
      :EMPRESA,
      :ORGANIZACION,
      :CLIENTE,
      :MONEDA,
      :DOCNRO,
      :FECHA,
      :SUBTOTAL,
      :TOTIMP_TRASLADADOS,
      :TOTIMP_LOCALES,
      :TOTIMP_RETENIDOS,
      :TOTAL,
      :TIPOCAMBIO
  DO
  BEGIN
    REFERENCIA = '';
    PEDIMENTO = '';
    ID_SICINGR85 = NULL;
    EROGACIONES = 0;
    HONORARIOS = 0;
    IMPUESTOS = 0;
    GASTOS = 0;
    ANTICIPO = 0;
    TOTAL_CTAGASTO = 0;
    SALDO = 0;
    MENOS30 = 0;
    MENOS60 = 0;
    MENOS90 = 0;
    MAS90 = 0;

    if (CLIENTE is null) then
    begin
        select sicingr01_cab_clientes.sicingr01_entidad
        from sicingr01_cab_clientes
        where sicingr01_cab_clientes.id_sicingr01 = :rela_sicingr01
        into :cliente;
    end

    SELECT SICINGR71_DET_FACTURACION.SICINGR71_IMPORTE_TOTAL
    FROM SICINGR71_DET_FACTURACION
    INNER JOIN SICINGR95_CAB_CONCEPTOS ON
        (SICINGR71_DET_FACTURACION.RELA_SICINGR95 =
        SICINGR95_CAB_CONCEPTOS.ID_SICINGR95)
    WHERE SICINGR71_DET_FACTURACION.RELA_SICINGR70 = :ID_SICINGR70
      AND SICINGR95_CAB_CONCEPTOS.SICINGR95_CODIGO LIKE 'HONO%'
    INTO :HONORARIOS;

    IF (:HONORARIOS IS NULL) THEN
      HONORARIOS = 0;

    select
    sicingr88_det_gastos3ros.rela_sicingr85
    from sicingr88_det_gastos3ros
    where sicingr88_det_gastos3ros.rela_sicingr70 = :id_sicingr70
    into :id_sicingr85;

    select first 1
    SICINGR85_CAB_GASTOS3ROS.SICINGR85_REFERENCIA,
    ADUPEDI01_CAB_PEDIMENTO.adupedi01_pedimento
    from SICINGR85_CAB_GASTOS3ROS
    left outer join ADUPEDI01_CAB_PEDIMENTO  ON (SICINGR85_CAB_GASTOS3ROS.ID_SICINGR85 = ADUPEDI01_CAB_PEDIMENTO.rela_sicingr85)
    where SICINGR85_CAB_GASTOS3ROS.id_sicingr85 = :id_sicingr85
    into :REFERENCIA,
         :PEDIMENTO;

    IF (:REFERENCIA IS NULL) THEN
      REFERENCIA = '';


    IF (:PEDIMENTO IS NULL) THEN
      PEDIMENTO = '';

    Select
    SICINGR51_CAB_BANCOS.RELA_SOCSYST10_CTM01,
    iif(SICINGR51_CAB_BANCOS.SICINGR51_COTIZA is null, 1, SICINGR51_CAB_BANCOS.SICINGR51_COTIZA),
    sum(sicingr55_det_facturas.sicingr55_importe)
    from sicingr55_det_facturas
    inner join sicingr51_cab_bancos on (sicingr51_cab_bancos.id_sicingr51 = sicingr55_det_facturas.rela_sicingr51)
    where sicingr55_det_facturas.rela_sicingr70 = :id_sicingr70
    group by SICINGR51_CAB_BANCOS.RELA_SOCSYST10_CTM01,
             SICINGR51_CAB_BANCOS.SICINGR51_COTIZA
    into :ID_MONEDA_PAGO,
         :TIPOCAMBIO_PAGO,
         :IMPORTE_PAGO;

    IMPORTE_PAGO = IMPORTE_PAGO / TIPOCAMBIO_PAGO;

    select sum(aductag02_det_anticipos.aductag02_importe)
    from sicingr88_det_gastos3ros
    inner join sicingr85_cab_gastos3ros on (sicingr85_cab_gastos3ros.id_sicingr85 = sicingr88_det_gastos3ros.rela_sicingr85)
    inner join aductag02_det_anticipos on (aductag02_det_anticipos.rela_sicingr85 = sicingr85_cab_gastos3ros.id_sicingr85)
    where sicingr88_det_gastos3ros.rela_sicingr70 = :ID_SICINGR70
    into :anticipo;

    anticipo = IIF(anticipo IS NULL, 0, anticipo);
    importeanticipos = :anticipo;

    SELECT SUM(SICINGR86_DET_GASTOS3ROS.SICINGR86_IMPORTE)
    FROM SICINGR86_DET_GASTOS3ROS
    WHERE SICINGR86_DET_GASTOS3ROS.RELA_SICINGR85 = :ID_SICINGR85
    INTO :GASTOS;

    GASTOS = iif(GASTOS is null, 0.00, GASTOS);

    /* ================================================================================================================================== */

    IMPUESTOS = (TOTIMP_TRASLADADOS + TOTIMP_LOCALES) - TOTIMP_RETENIDOS;
    EROGACIONES = SUBTOTAL + IMPUESTOS;

    TOTAL_CTAGASTO = TOTAL + GASTOS + IMPUESTOS;
    IMPORTETOTAL = TOTAL_CTAGASTO - IMPORTE_PAGO;
    IMPORTE_SAL = importetotal - anticipo;
    SALDO = TOTAL_CTAGASTO - anticipo;

    DIAS = CAST('NOW' AS DATE) - :FECHA;

    IF (:DIAS < 30) THEN
      MENOS30 = SALDO;
    ELSE
      IF (:DIAS >= 30 AND :DIAS < 60) THEN
        MENOS60 = SALDO;
      ELSE
        IF (:DIAS >= 60 AND :DIAS < 90) THEN
          MENOS90 = SALDO;
        ELSE
          MAS90 = SALDO;

    SUSPEND;
  END
END^


CREATE OR ALTER PROCEDURE REP_SICINGR70_FACTURAS (
    PARAM_EMPRESA BIGINT,
    PARAM_CLIENTE BIGINT,
    PARAM_FECHADESDE DATE,
    PARAM_FECHAHASTA DATE,
    PARAM_MONEDA BIGINT)
RETURNS (
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICINGR01 BIGINT,
    RELA_SOCSYST10_CTM01 BIGINT,
    ID_SICINGR70 BIGINT,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA DATE,
    SUBTOTAL DOUBLE PRECISION,
    DESCUENTO DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TIPOCAMBIO DOUBLE PRECISION,
    IVA DOUBLE PRECISION,
    OTROS DOUBLE PRECISION,
    RETIVA DOUBLE PRECISION,
    RETISR DOUBLE PRECISION,
    TIPO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_CANCELADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    UUID_FECHA_CANCEL DATE)
AS
declare variable SQLUSER varchar(5000);
declare variable ID_SICINGR74 bigint;
declare variable CANCELADO integer;
declare variable PASO integer;
BEGIN
  SELECT
      E.RAZSOCIAL,
      E.RFC,
      E.CURP,
      E.REGISTROPATRONAL
  FROM CFDI_EMPRESA(:PARAM_EMPRESA) E
  INTO
      :EMPRESA_RAZSOCIAL,
      :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;

  FOR
    SELECT
        0 AS CANCELADO,
        F.RELA_SOCMAIN01,
        F.RELA_SOCMAIN21,
        F.RELA_SICINGR01,
        F.RELA_SOCSYST10_CTM01,
        F.ID_SICINGR70,
        E.SOCMAIN01_NOMCOMERCIAL,
        O.SOCMAIN21_DESCRIPCION,
        TRIM(C.SOCUSUA30_APELLIDO_PAT || ' ' || C.SOCUSUA30_APELLIDO_MAT || ' ' || C.SOCUSUA30_NOMBRE_RAZSOC),
        M.SOCSYST10_CODIGO,
        F.SICINGR70_DOCNRO,
        F.SICINGR70_FECHA,
        F.SICINGR70_SUBTOTAL,
        F.SICINGR70_DESCUENTO,
        F.SICINGR70_NETO,
        F.SICINGR70_CAMBIO
    FROM SICINGR70_CAB_FACTURACION F
    INNER JOIN SOCMAIN01_CAB_EMPRESAS E ON F.RELA_SOCMAIN01 = E.ID_SOCMAIN01
    INNER JOIN SOCMAIN21_ARB_ORGANIZACION O ON F.RELA_SOCMAIN21 = O.ID_SOCMAIN21
    INNER JOIN SOCSYST10_DET_REMOTO M ON F.RELA_SOCSYST10_CTM01 = M.ID_SOCSYST10
    INNER JOIN SICINGR01_CAB_CLIENTES CL ON F.RELA_SICINGR01 = CL.ID_SICINGR01
    INNER JOIN SOCUSUA30_CAB_ENTIDADES C ON CL.RELA_SOCUSUA30 = C.ID_SOCUSUA30
    WHERE F.RELA_SOCMAIN01 = :PARAM_EMPRESA
      AND F.RELA_SOCSYST10_CTM01 = :PARAM_MONEDA
      AND F.SICINGR70_FECHA BETWEEN :PARAM_FECHADESDE AND :PARAM_FECHAHASTA

    UNION ALL

    SELECT
        1 AS CANCELADO,
        F.RELA_SOCMAIN01,
        F.RELA_SOCMAIN21,
        F.RELA_SICINGR01,
        F.RELA_SOCSYST10_CTM01,
        F.ID_SICINGR70,
        E.SOCMAIN01_NOMCOMERCIAL,
        O.SOCMAIN21_DESCRIPCION,
        TRIM(C.SOCUSUA30_APELLIDO_PAT || ' ' || C.SOCUSUA30_APELLIDO_MAT || ' ' || C.SOCUSUA30_NOMBRE_RAZSOC),
        M.SOCSYST10_CODIGO,
        C77.SICINGR77_FOLIO,
        CAST(C77.SICINGR77_UUID_FECHA AS DATE),
        F.SICINGR70_SUBTOTAL,
        F.SICINGR70_DESCUENTO,
        C77.SICINGR77_UUID_IMPORTE,
        F.SICINGR70_CAMBIO
    FROM SICINGR70_CAB_FACTURACION F
    INNER JOIN SOCMAIN01_CAB_EMPRESAS E ON F.RELA_SOCMAIN01 = E.ID_SOCMAIN01
    INNER JOIN SOCMAIN21_ARB_ORGANIZACION O ON F.RELA_SOCMAIN21 = O.ID_SOCMAIN21
    INNER JOIN SOCSYST10_DET_REMOTO M ON F.RELA_SOCSYST10_CTM01 = M.ID_SOCSYST10
    INNER JOIN SICINGR01_CAB_CLIENTES CL ON F.RELA_SICINGR01 = CL.ID_SICINGR01
    INNER JOIN SOCUSUA30_CAB_ENTIDADES C ON CL.RELA_SOCUSUA30 = C.ID_SOCUSUA30
    INNER JOIN SICINGR77_DET_CFDISCANCELADOS C77 ON C77.RELA_SICINGR70 = F.ID_SICINGR70
    WHERE F.RELA_SOCMAIN01 = :PARAM_EMPRESA
      AND F.RELA_SOCSYST10_CTM01 = :PARAM_MONEDA
      AND F.SICINGR70_FECHA BETWEEN :PARAM_FECHADESDE AND :PARAM_FECHAHASTA

  INTO
      :CANCELADO, 
      :RELA_SOCMAIN01,
      :RELA_SOCMAIN21,
      :RELA_SICINGR01,
      :RELA_SOCSYST10_CTM01,
      :ID_SICINGR70,
      :EMPRESA,
      :ORGANIZACION,
      :CLIENTE,
      :MONEDA,
      :DOCNRO,
      :FECHA,
      :SUBTOTAL,
      :DESCUENTO,
      :TOTAL,
      :TIPOCAMBIO
  DO
  BEGIN
    PASO = 0;

    IF (PARAM_CLIENTE IS NULL OR PARAM_CLIENTE <= 0 OR PARAM_CLIENTE = RELA_SICINGR01) THEN
    BEGIN
        PASO = 1;
    END

    IF (PASO = 1) THEN
    BEGIN
        SELECT
            I.IVA,
            I.OTROS,
            I.RETIVA,
            I.RETISR
        FROM PRD_SICINGR72_IMPUESTOS(:ID_SICINGR70) I
        INTO :IVA, :OTROS, :RETIVA, :RETISR;

        TIPO = 'Pendiente';

        IF (CANCELADO = 0) THEN
        BEGIN
            SELECT FIRST 1 D.ID_SICINGR74
            FROM SICINGR74_DEP_CFDIS D
            WHERE D.RELA_SICINGR70 = :ID_SICINGR70
            INTO :ID_SICINGR74;

            IF (:ID_SICINGR74 IS NOT NULL) THEN
                TIPO = 'Timbrado';
        END
        ELSE
        BEGIN
            TIPO = 'Cancelado';

            SELECT FIRST 1
                C77.SICINGR77_UUID,
                C77.SICINGR77_UUID_FECHA
            FROM SICINGR77_DET_CFDISCANCELADOS C77
            WHERE C77.RELA_SICINGR70 = :ID_SICINGR70
            ORDER BY C77.SICINGR77_UUID_FECHA DESC
            INTO :UUID_CANCELADO, :UUID_FECHA_CANCEL;
        END

        SUSPEND;
    END
  END
END^


CREATE OR ALTER PROCEDURE REP_SICINGR70_IMPUESTOS (
    ID_SICINGR70 BIGINT)
RETURNS (
    ID_SICINGR72MAX BIGINT,
    SICINGR72_TIPOZONA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR72_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR72_IMPUESTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR72_IMPORTE DOUBLE PRECISION,
    SICINGR72_TASAOCUOTA DOUBLE PRECISION,
    SICINGR72_FACTOR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    
    for select distinct
    max(sicingr72_det_impuestos.id_sicingr72),
    sicingr72_det_impuestos.sicingr72_tipozona,
    sicingr72_det_impuestos.sicingr72_tipo,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sum(sicingr72_det_impuestos.sicingr72_importe),
    sicingr72_det_impuestos.sicingr72_tasaocuota,
    sicingr72_det_impuestos.sicingr72_factor
    from sicingr72_det_impuestos
    inner join sicingr71_det_facturacion on (sicingr72_det_impuestos.rela_sicingr71 = sicingr71_det_facturacion.id_sicingr71)
    where sicingr71_det_facturacion.rela_sicingr70 = :id_sicingr70
    group by
    sicingr72_det_impuestos.sicingr72_tipozona,
    sicingr72_det_impuestos.sicingr72_tipo,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_tasaocuota,
    sicingr72_det_impuestos.sicingr72_factor
    into :id_sicingr72max,
         :sicingr72_tipozona,
         :sicingr72_tipo,
         :sicingr72_impuesto,
         :sicingr72_importe,
         :sicingr72_tasaocuota,
         :sicingr72_factor
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR70_SICINGR88 (
    RELA_SOCMAIN01 BIGINT,
    RELA_SICINGR01 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    ID_SICINGR70 BIGINT,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_FECHA DATE,
    SICINGR70_NETO DOUBLE PRECISION,
    DIAS INTEGER,
    DIAS_BANCOS INTEGER,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_D01 DOUBLE PRECISION,
    SICINGR71_D02 DOUBLE PRECISION,
    SICINGR71_D03 DOUBLE PRECISION,
    SICINGR71_D04 DOUBLE PRECISION,
    SICINGR71_D05 DOUBLE PRECISION,
    SICINGR71_D06 DOUBLE PRECISION,
    SICINGR71_D07 DOUBLE PRECISION,
    SICINGR71_D08 DOUBLE PRECISION,
    SICINGR71_D09 DOUBLE PRECISION,
    SICINGR71_D10 DOUBLE PRECISION,
    SICINGR71_D11 DOUBLE PRECISION,
    SICINGR71_D12 DOUBLE PRECISION,
    SICINGR71_D13 DOUBLE PRECISION,
    SICINGR71_D14 DOUBLE PRECISION,
    SICINGR71_D15 DOUBLE PRECISION,
    SICINGR71_D16 DOUBLE PRECISION,
    SICINGR71_D17 DOUBLE PRECISION,
    SICINGR71_D18 DOUBLE PRECISION,
    SICINGR71_D19 DOUBLE PRECISION,
    SICINGR71_D20 DOUBLE PRECISION,
    SICINGR71_D21 DOUBLE PRECISION,
    SICINGR71_D22 DOUBLE PRECISION,
    SICINGR71_D23 DOUBLE PRECISION,
    SICINGR71_D24 DOUBLE PRECISION,
    SICINGR71_D25 DOUBLE PRECISION,
    SICINGR71_D26 DOUBLE PRECISION,
    SICINGR71_D27 DOUBLE PRECISION,
    SICINGR71_D28 DOUBLE PRECISION,
    SICINGR71_D29 DOUBLE PRECISION,
    SICINGR71_D30 DOUBLE PRECISION,
    SICINGR88_G01 DOUBLE PRECISION,
