    SICINGR88_G30 DOUBLE PRECISION,
    TOTAL_CTAGASTOS DOUBLE PRECISION,
    TOTAL_ANTICIPOS DOUBLE PRECISION,
    TOTAL_BANCOS DOUBLE PRECISION,
    TOTAL_SALDO DOUBLE PRECISION)
AS
declare variable CONTA_DET_SICINGR71 integer;
declare variable CONTA_DET_SICINGR88 integer;
declare variable CROSSTAB01_CODIGO varchar(50);
declare variable SICINGR71_CONCEPTO varchar(1200);
declare variable SICINGR71_IMPORTE_NETO double precision;
declare variable RELA_SICINGR85 bigint;
declare variable SOCSYST10_DESCRIPCION varchar(400);
declare variable SICINGR86_IMPORTE double precision;
begin
    conta_det_sicingr71 = 1;
    conta_det_sicingr88 = 1;

    delete from tmp_crosstab01 where tmp_crosstab01.crosstab01_usuario = current_user;

    FOR SELECT
    sicingr70_cab_facturacion.rela_sicingr01,
    sicingr70_cab_facturacion.id_sicingr70,
    sicingr70_cab_facturacion.sicingr70_docnro,
    sicingr70_cab_facturacion.sicingr70_fecha,
