    FROM sicingr70_cab_facturacion
    inner join cbo_sicingr01_id on ( cbo_sicingr01_id.id_sicingr01 = sicingr70_cab_facturacion.rela_sicingr01 )
    WHERE sicingr70_cab_facturacion.rela_socmain01 = :rela_socmain01
    AND sicingr70_cab_facturacion.rela_sicingr01 = :rela_sicingr01
    AND sicingr70_cab_facturacion.sicingr70_fecha between :fecha_desde and :fecha_hasta
    order by sicingr70_cab_facturacion.sicingr70_fecha desc
    INTO :rela_sicingr01,
         :id_sicingr70,
         :sicingr70_docnro,
         :sicingr70_fecha,
         :sicingr70_neto
    DO
    BEGIN
        SICINGR71_D01 = 0;
        SICINGR71_D02 = 0;
        SICINGR71_D03 = 0;
        SICINGR71_D04 = 0;
