            else if (crosstab01_codigo = 'D09') then
                SICINGR71_D09 = SICINGR71_D09 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D10') then
                SICINGR71_D10 = SICINGR71_D10 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D11') then
                SICINGR71_D11 = SICINGR71_D11 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D12') then
                SICINGR71_D12 = SICINGR71_D12 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D13') then
                SICINGR71_D13 = SICINGR71_D13 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D14') then
                SICINGR71_D14 = SICINGR71_D14 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D15') then
                SICINGR71_D15 = SICINGR71_D15 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D16') then
