            else if (crosstab01_codigo = 'D17') then
                SICINGR71_D17 = SICINGR71_D17 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D18') then
                SICINGR71_D18 = SICINGR71_D18 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D19') then
