            else if (crosstab01_codigo = 'D29') then
                SICINGR71_D29 = SICINGR71_D29 + sicingr71_importe_neto;
            else if (crosstab01_codigo = 'D30') then
                SICINGR71_D30 = SICINGR71_D30 + sicingr71_importe_neto;
        END

        /* ------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------ */

        select
        PRD_SICINGR51_SICINGR70.importe_banco,
        PRD_SICINGR51_SICINGR70.importe_anticipos,
        PRD_SICINGR51_SICINGR70.importe_ctagastos,
