             :sicingr85_referencia;

        SELECT sicingr88_det_gastos3ros.rela_sicingr85
        FROM sicingr88_det_gastos3ros
        WHERE sicingr88_det_gastos3ros.rela_sicingr70 = :id_sicingr70
        INTO :rela_sicingr85;

        SICINGR88_G01 = 0;
        SICINGR88_G02 = 0;
