            WHERE tmp_crosstab01.crosstab01_usuario = current_user
            and SUBSTRING(tmp_crosstab01.crosstab01_codigo FROM 1 FOR 1) = 'G'
            and tmp_crosstab01.crosstab01_descr_original = UPPER(TRIM(:socsyst10_descripcion))
            into :crosstab01_codigo;

            if (crosstab01_codigo is null) then
