                                           tmp_crosstab01.crosstab01_descr_original,
                                           tmp_crosstab01.crosstab01_descr_usuario)
                values(current_user,
                       :crosstab01_codigo,
                       UPPER(TRIM(:socsyst10_descripcion)),
                       '');

                conta_det_sicingr88 = conta_det_sicingr88 + 1;
           end

           if (crosstab01_codigo = 'G01') then
                SICINGR88_G01 = SICINGR88_G01 + sicingr86_importe;
            else if (crosstab01_codigo = 'G02') then
                SICINGR88_G02 = SICINGR88_G02 + sicingr86_importe;
            else if (crosstab01_codigo = 'G03') then
                SICINGR88_G03 = SICINGR88_G03 + sicingr86_importe;
            else if (crosstab01_codigo = 'G04') then
                SICINGR88_G04 = SICINGR88_G04 + sicingr86_importe;
            else if (crosstab01_codigo = 'G05') then
