CREATE OR ALTER PROCEDURE REP_SICINGR71_CAB_CONCEPTOS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    ID_SICINGR71 BIGINT,
    SICINGR71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OCURRENCIA INTEGER,
    CANTIDAD DOUBLE PRECISION,
    IMPORTE DOUBLE PRECISION,
    FECHA_MIN DATE,
    FECHA_MAX DATE)
AS
begin
    for select
    max(sicingr71_det_facturacion.id_sicingr71),
    sicingr71_det_facturacion.sicingr71_codigo,
    sicingr71_det_facturacion.sicingr71_concepto,
    count(sicingr71_det_facturacion.id_sicingr71),
    sum(sicingr71_det_facturacion.sicingr71_cantidad),
    sum(sicingr71_det_facturacion.sicingr71_importe_neto),
    cast(min(sicingr74_dep_cfdis.sicingr74_uuid_fecha) as date),
    cast(max(sicingr74_dep_cfdis.sicingr74_uuid_fecha) as date)
    from sicingr70_cab_facturacion
    inner join sicingr71_det_facturacion on ( sicingr71_det_facturacion.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
    inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70 )
    where sicingr70_cab_facturacion.rela_socmain01 = :rela_socmain01
    and sicingr70_cab_facturacion.rela_socmain21 = :rela_socmain21
    and cast(sicingr74_dep_cfdis.sicingr74_uuid_fecha as date) between :fecha_desde and :fecha_hasta
    group by sicingr71_det_facturacion.sicingr71_codigo,
             sicingr71_det_facturacion.sicingr71_concepto
    into :id_sicingr71,
         :sicingr71_codigo,
         :sicingr71_concepto,
         :ocurrencia,
         :cantidad,
         :importe,
         :fecha_min,
         :fecha_max
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR71_DET_CFDIS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    ID_SICINGR70 BIGINT,
    SICINGR70_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR70_NETO DOUBLE PRECISION,
    SICINGR70_FECHA DATE,
    SICXMLS41_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_CANTIDAD DOUBLE PRECISION,
    IMPORTE_CONCEPTO DOUBLE PRECISION,
    POLIZA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLIENTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SICXMLS41 bigint;
declare variable RELA_SICCONT10 bigint;
begin
    for
    select distinct sicxmls42_det_conceptos.rela_sicxmls41
    from sicxmls40_cab_migracion
    inner join sicxmls41_det_migracion on ( sicxmls41_det_migracion.rela_sicxmls40 = sicxmls40_cab_migracion.id_sicxmls40 )
    inner join sicxmls42_det_conceptos on ( sicxmls42_det_conceptos.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
    where sicxmls40_cab_migracion.rela_socmain01 = :rela_socmain01
    and sicxmls40_cab_migracion.rela_socmain21 = :rela_socmain21
    and sicxmls42_det_conceptos.sicxmls42_concepto = :concepto
    and exists( select first 1 sicingr74_dep_cfdis.id_sicingr74
                from sicingr74_dep_cfdis
                where sicingr74_dep_cfdis.rela_sicxmls41 = sicxmls42_det_conceptos.rela_sicxmls41
                and cast(sicingr74_dep_cfdis.sicingr74_uuid_fecha as date) between :fecha_desde and :fecha_hasta
                )
    into :rela_sicxmls41
    do
    begin
        select
        sicxmls41_det_migracion.rela_siccont10,
        sicingr70_cab_facturacion.id_sicingr70,
        sicingr70_cab_facturacion.sicingr70_docnro,
        sicingr70_cab_facturacion.sicingr70_neto,
        sicingr70_cab_facturacion.sicingr70_fecha,
        sicxmls41_det_migracion.sicxmls41_uuid,
        sicxmls41_det_migracion.sicxmls41_entidad
        from sicxmls41_det_migracion
        inner join sicingr74_dep_cfdis on ( sicingr74_dep_cfdis.rela_sicxmls41 = sicxmls41_det_migracion.id_sicxmls41 )
        inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
        where sicxmls41_det_migracion.id_sicxmls41 = :rela_sicxmls41
        into :rela_siccont10,
             :id_sicingr70,
             :sicingr70_docnro,
             :sicingr70_neto,
             :sicingr70_fecha,
             :sicxmls41_uuid,
             :cliente;

        select
        sum(sicingr71_det_facturacion.sicingr71_cantidad),
        sum(sicingr71_det_facturacion.sicingr71_importe_neto)
        from sicingr71_det_facturacion
        where sicingr71_det_facturacion.rela_sicingr70 = :id_sicingr70
        and sicingr71_det_facturacion.sicingr71_concepto = :concepto
        into :sicingr71_cantidad,
             :importe_concepto;

        select
        siccont10_cab_polizas.siccont10_docnro
        from siccont10_cab_polizas
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10
        into :poliza;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR81 (
    ID_SICINGR70 BIGINT)
RETURNS (
    RELA_SOCUSUA30_ORIGEN BIGINT,
    RELA_SOCUSUA30_DESTINO BIGINT,
    ID_SICINGR81 BIGINT,
    SICINGR81_DOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_RECOGE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_VALOR DOUBLE PRECISION,
    SICINGR81_SEENTREGAEN VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_FDEENTREGA DATE,
    SICINGR81_OPERADOR VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_PELIGROSO INTEGER,
    SICINGR81_PLACAS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_NOTAS VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCSYST10_UMT01 BIGINT,
    RELA_SOCSYST10_CUM01 BIGINT,
    RELA_SOCSYST10_UMB01 BIGINT,
    SICINGR82_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR82_CANTIDAD DOUBLE PRECISION,
    SICINGR82_VALOR DOUBLE PRECISION,
    SICINGR82_PESO DOUBLE PRECISION,
    SICINGR82_PELIGROSO INTEGER,
    SOCSYST10_MEDIDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_EMBALAJE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REMOLQUE_1 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REMOLQUE_2 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REMOLQUE_3 VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ANO_TIPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ASEGURADORA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    POLIZA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PERMISO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR81_LICENCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CONTA_REMOLQUE integer;
declare variable SICINGR83_PLACAS varchar(50);
declare variable SICINGR83_SUBTIPO varchar(50);
declare variable SICINGR81_CAMION_ANO integer;
declare variable SICINGR81_CAMION_TIPO varchar(10);
begin
    select
        RELA_SOCUSUA30_ORIGEN,
        RELA_SOCUSUA30_DESTINO,
        ID_SICINGR81,
        SICINGR81_DOCUMENTO,
        SICINGR81_RECOGE,
        SICINGR81_VALOR,
        SICINGR81_SEENTREGAEN,
        SICINGR81_FDEENTREGA,
        SICINGR81_PELIGROSO,
        SICINGR81_OPERADOR,
        SICINGR81_PLACAS,
        SICINGR81_NOTAS,
        sicingr81_camion_ano,
        sicingr81_camion_tipo,
        socsyst10_det_entradas.socsyst10_descripcion,
        SICINGR81_CAB_TRANSPORTE.sicingr81_poliza,
        SICINGR81_CAB_TRANSPORTE.sicingr81_permsct,
        SICINGR81_CAB_TRANSPORTE.sicingr81_licencia
    from SICINGR81_CAB_TRANSPORTE
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = SICINGR81_CAB_TRANSPORTE.rela_socsyst10_por05)
    where RELA_SICINGR70 = :ID_SICINGR70
    into
        :RELA_SOCUSUA30_ORIGEN,
        :RELA_SOCUSUA30_DESTINO,
        :ID_SICINGR81,
        :SICINGR81_DOCUMENTO,
        :SICINGR81_RECOGE,
        :SICINGR81_VALOR,
        :SICINGR81_SEENTREGAEN,
        :SICINGR81_FDEENTREGA,
        :SICINGR81_PELIGROSO,
        :SICINGR81_OPERADOR,
        :SICINGR81_PLACAS,
        :SICINGR81_NOTAS,
        :sicingr81_camion_ano,
        :sicingr81_camion_tipo,
        :aseguradora,
        :poliza,
        :permiso,
        :sicingr81_licencia;

    ano_tipo = cast(sicingr81_camion_ano as varchar(5)) || ' ' || :sicingr81_camion_tipo;

    conta_remolque = 0;
    for select
    SICINGR83_DET_REMOLQUES.sicingr83_placas,
    SICINGR83_DET_REMOLQUES.sicingr83_subtipo
    from SICINGR83_DET_REMOLQUES
    where SICINGR83_DET_REMOLQUES.rela_sicingr81 = :ID_SICINGR81
    into :sicingr83_placas,
         :sicingr83_subtipo
    do
    begin
        if (conta_remolque = 0) then
            remolque_1 = :sicingr83_placas || ' '  || :sicingr83_subtipo;
        else if (conta_remolque = 1) then
            remolque_2 = :sicingr83_placas || ' '  || :sicingr83_subtipo;
         else if (conta_remolque = 2) then
            remolque_3 = :sicingr83_placas || ' '  || :sicingr83_subtipo;

        conta_remolque = conta_remolque + 1;
    end

    for select
    SICINGR82_DET_TRANSPORTE.rela_socsyst10_cum01,
    SICINGR82_DET_TRANSPORTE.sicingr82_concepto,
    SICINGR82_DET_TRANSPORTE.sicingr82_cantidad,
    SICINGR82_DET_TRANSPORTE.sicingr82_valor,
    SICINGR82_DET_TRANSPORTE.sicingr82_peso,
    SICINGR82_DET_TRANSPORTE.sicingr82_peligroso
    from  SICINGR82_DET_TRANSPORTE
    where SICINGR82_DET_TRANSPORTE.RELA_SICINGR81 = :ID_SICINGR81
    into :RELA_SOCSYST10_cum01,
         :sicingr82_concepto,
         :sicingr82_cantidad,
         :sicingr82_valor,
         :sicingr82_peso,
         :sicingr82_peligroso
    do
    begin
        SELECT cbo_socsyst10_cum01.socsyst10_codigo
        FROM cbo_socsyst10_cum01
        WHERE cbo_socsyst10_cum01.id_socsyst10 = :RELA_SOCSYST10_cum01
        into :SOCSYST10_MEDIDA;


        /*
            select socsyst10_det_entradas.socsyst10_descripcion from socsyst10_det_entradas
             where socsyst10_det_entradas.id_socsyst10 = :rela_socsyst10_umt01
             into :SOCSYST10_MEDIDA;

             /*
            select socsyst10_det_entradas.socsyst10_descripcion from socsyst10_det_entradas
             where socsyst10_det_entradas.id_socsyst10 = :rela_socsyst10_umb01
             into :SOCSYST10_EMBALAJE;
               */
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR85 (
    ID_SICINGR70 BIGINT)
RETURNS (
    RELA_SOCSYST10_CCG01 BIGINT,
    ID_SICINGR85 BIGINT,
    SICINGR85_REFERENCIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ADUCTAG01_CONTROL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ADUCTAG01_VALORADUANA DOUBLE PRECISION,
    ADUCTAG01_VALORCOMERC DOUBLE PRECISION,
    ADUCTAG01_BULTOS INTEGER,
    ADUCTAG01_PESO DOUBLE PRECISION,
    ADUCTAG01_TERMPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ADUCTAG01_FVTO DATE,
    ADUCTAG01_FCRUCE DATE,
    ADUCTAG01_BASEHONO DOUBLE PRECISION,
    ADUCTAG01_DOCTRANS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ADUCTAG01_NUMCAJA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR86_GASTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR86_IMPORTE DOUBLE PRECISION)
AS
begin

    select ID_SICINGR85,
           SICINGR85_REFERENCIA,
           ADUCTAG01_CONTROL,
           ADUCTAG01_VALORADUANA,
           ADUCTAG01_VALORCOMERC,
           ADUCTAG01_BULTOS,
           ADUCTAG01_PESO,
           ADUCTAG01_TERMPAGO,
           ADUCTAG01_FVTO,
           ADUCTAG01_FCRUCE,
           ADUCTAG01_BASEHONO,
           ADUCTAG01_DOCTRANS,
           ADUCTAG01_NUMCAJA
    from SICINGR85_CAB_GASTOS3ROS
   inner join SICINGR88_DET_GASTOS3ROS ON (SICINGR85_CAB_GASTOS3ROS.ID_SICINGR85 = SICINGR88_DET_GASTOS3ROS.RELA_SICINGR85)
   left outer join ADUCTAG01_CAB_CTAGASTOS  ON (ADUCTAG01_CAB_CTAGASTOS.RELA_SICINGR85 = SICINGR85_CAB_GASTOS3ROS.ID_SICINGR85)
   where SICINGR88_DET_GASTOS3ROS.RELA_SICINGR70 = :ID_SICINGR70
    into
        :ID_SICINGR85,
        :SICINGR85_REFERENCIA,
        :ADUCTAG01_CONTROL,
        :ADUCTAG01_VALORADUANA,
        :ADUCTAG01_VALORCOMERC,
        :ADUCTAG01_BULTOS,
        :ADUCTAG01_PESO,
        :ADUCTAG01_TERMPAGO,
        :ADUCTAG01_FVTO,
        :ADUCTAG01_FCRUCE,
        :ADUCTAG01_BASEHONO,
        :ADUCTAG01_DOCTRANS,
        :ADUCTAG01_NUMCAJA;

    for select
        RELA_SOCSYST10_CCG01,
        SICINGR86_IMPORTE
   from SICINGR86_DET_GASTOS3ROS
  where RELA_SICINGR85 = :ID_SICINGR85
   into
        RELA_SOCSYST10_CCG01,
        SICINGR86_IMPORTE
    do
        begin
            select socsyst10_det_entradas.socsyst10_descripcion from socsyst10_det_entradas
             where socsyst10_det_entradas.id_socsyst10 = :rela_socsyst10_ccg01
             into :SICINGR86_GASTO;

            suspend;
        end

        if (:RELA_SOCSYST10_CCG01 is null) then
            suspend;
end^


