CREATE OR ALTER PROCEDURE REP_SICINGR85_EDOCUENTA (
    RELA_SICINGR85 BIGINT)
RETURNS (
    ID_SICINGR85 BIGINT,
    TOTAL DOUBLE PRECISION,
    HONORARIOS DOUBLE PRECISION,
    OTROS DOUBLE PRECISION,
    IMPUESTOS DOUBLE PRECISION,
    EROGACIONES DOUBLE PRECISION,
    GASTOS DOUBLE PRECISION,
    TOTAL_CTAGASTOS DOUBLE PRECISION,
    ANTICIPO DOUBLE PRECISION,
    SALDO DOUBLE PRECISION,
    IMPORTE_PAGO DOUBLE PRECISION,
    IMPORTE_SALDO DOUBLE PRECISION,
    APLICACIONES DOUBLE PRECISION,
    SALDO_FINAL DOUBLE PRECISION)
AS
declare variable APLICACIONES_FACTURAS double precision;
BEGIN
    id_sicingr85 = :rela_sicingr85;

    select
    coalesce(sum(sicingr70_cab_facturacion.sicingr70_total), 0),
    (coalesce(sum(sicingr70_cab_facturacion.sicingr70_totimp_traslados), 0) +
     coalesce(sum(sicingr70_cab_facturacion.sicingr70_totimp_locales), 0)
    ) - coalesce(sum(sicingr70_cab_facturacion.sicingr70_totimp_retenidos), 0),
    coalesce(sum(sicingr70_cab_facturacion.sicingr70_neto), 0)
    from sicingr88_det_gastos3ros
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
    where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
    into :total,
         :impuestos,
         :erogaciones;

    select
    coalesce(sum(sicingr71_det_facturacion.sicingr71_importe_total), 0)
    from sicingr88_det_gastos3ros
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
    inner join sicingr71_det_facturacion on (sicingr71_det_facturacion.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
    inner join sicingr95_cab_conceptos on (sicingr95_cab_conceptos.id_sicingr95 = sicingr71_det_facturacion.rela_sicingr95)
    where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
    and sicingr95_cab_conceptos.sicingr95_codigo like 'HONO%'
    into :honorarios;

    select
    coalesce(sum(sicingr71_det_facturacion.sicingr71_importe_total), 0)
    from sicingr88_det_gastos3ros
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
    inner join sicingr71_det_facturacion on (sicingr71_det_facturacion.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
    inner join sicingr95_cab_conceptos on (sicingr95_cab_conceptos.id_sicingr95 = sicingr71_det_facturacion.rela_sicingr95)
    where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
    and sicingr95_cab_conceptos.sicingr95_codigo not like 'HONO%'
    into :otros;

    SELECT
    coalesce(SUM(sicingr86_det_gastos3ros.sicingr86_importe), 0)
    FROM sicingr86_det_gastos3ros
    WHERE sicingr86_det_gastos3ros.rela_sicingr85 = :id_sicingr85
    INTO :gastos;

    total_ctagastos = erogaciones + gastos;

    select
    coalesce(sum(aductag02_det_anticipos.aductag02_importe), 0)
    from aductag02_det_anticipos
    where aductag02_det_anticipos.rela_sicingr85 = :id_sicingr85
    into :anticipo;

    saldo = total_ctagastos - anticipo;

    select 
    coalesce(sum(sicingr55_det_facturas.sicingr55_importe), 0)
    from sicingr55_det_facturas
    inner join sicingr70_cab_facturacion on (sicingr55_det_facturas.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
    inner join sicingr88_det_gastos3ros on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
    where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
    into :importe_pago;

    importe_saldo = total_ctagastos - importe_pago;

    select 
    coalesce(sum(aductag03_det_aplicaciones.aductag03_importe), 0)
    from aductag03_det_aplicaciones
    where aductag03_det_aplicaciones.rela_sicingr85 = :id_sicingr85
    into :aplicaciones;

    select coalesce(sum(sicingr70_cab_facturacion.sicingr70_neto), 0)
    from sicingr88_det_gastos3ros
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr88_det_gastos3ros.rela_sicingr70)
    where sicingr88_det_gastos3ros.rela_sicingr85 = :id_sicingr85
    into :aplicaciones_facturas;

    aplicaciones = aplicaciones + aplicaciones_facturas;
    saldo_final = importe_saldo - aplicaciones;

    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICINGR95 (
    P_SOCMAIN01 BIGINT,
    P_SOCMAIN021 BIGINT,
    P_SOCSYST10 BIGINT,
    P_SOCSYST12 BIGINT,
    P_CANTIDAD INTEGER)
RETURNS (
    RELA_SOCMAIN21 BIGINT,
    SOCMAIN21_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RAZSOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR95 BIGINT,
    CANTIDAD DOUBLE PRECISION,
    SICINGR95_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_IMPORTE DOUBLE PRECISION,
    SICINGR98_IMPORTE DOUBLE PRECISION,
    SOCSYST10_PATH VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST12_PATH VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VALORINVENTARIO DOUBLE PRECISION)
AS
declare variable STR varchar(2000);
declare variable SOCSYST10_DESCRIPCION varchar(400);
declare variable SOCSYST12_DESCRIPCION varchar(400);
declare variable STRWHERE varchar(1000);
begin
    select CFDI_EMPRESA.RAZSOCIAL
    from CFDI_EMPRESA(:p_socmain01)
    into :EMPRESA_RAZSOC;

    if (:p_socmain021 = -1) then
        str = 'select 
                sicingr95_cab_conceptos.id_sicingr95,
                null as cantidad,
                sicingr95_cab_conceptos.sicingr95_codigo,
                sicingr95_cab_conceptos.sicingr95_descripcion,
                sicingr95_cab_conceptos.sicingr95_importe
            from sicingr95_cab_conceptos
               inner join sicxmls01_cab_parametros on (sicingr95_cab_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
            where sicxmls01_cab_parametros.rela_socmain01 = '|| :p_socmain01;
    else
    begin
       str = 'select
                sicingr95_cab_conceptos.id_sicingr95,
                sum( pymalma02_det_stock.pymalma02_cantidad ) cantidad,
                sicingr95_cab_conceptos.sicingr95_codigo,
                sicingr95_cab_conceptos.sicingr95_descripcion,
                sicingr95_cab_conceptos.sicingr95_importe
            from pymalma01_cab_stock
               inner join pymalma02_det_stock on (pymalma01_cab_stock.id_pymalma01 = pymalma02_det_stock.rela_pymalma01)
               inner join sicingr95_cab_conceptos on (pymalma02_det_stock.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95)
               inner join sicxmls01_cab_parametros on (sicingr95_cab_conceptos.rela_sicxmls01 = sicxmls01_cab_parametros.id_sicxmls01)
           where sicxmls01_cab_parametros.rela_socmain01 = ' || :p_socmain01 ||
            ' and  pymalma01_cab_stock.rela_socmain21 = ' || :p_socmain021 ||
            ' group by sicxmls01_cab_parametros.rela_socmain01, sicingr95_cab_conceptos.id_sicingr95,
              sicingr95_cab_conceptos.sicingr95_codigo, sicingr95_cab_conceptos.sicingr95_descripcion,
              sicingr95_cab_conceptos.sicingr95_importe ' ;

        /* Obtenemos la descripcion de la organizacion por única vez*/
            select SOCMAIN21_ARB_ORGANIZACION.socmain21_descripcion
            from SOCMAIN21_ARB_ORGANIZACION
            where SOCMAIN21_ARB_ORGANIZACION.id_socmain21 = :p_socmain021
            into :SOCMAIN21_DESCRIPCION;

            RELA_SOCMAIN21 = :p_socmain021;
        end

  for execute statement :str
    into :id_sicingr95,
         :cantidad,
         :sicingr95_codigo,
         :sicingr95_descripcion,
         :sicingr95_importe
    do begin
       -- Obtenemos el precio de compra del producto
        select
        sum(sicingr98_det_importes.sicingr98_importe) / count(sicingr98_det_importes.id_sicingr98)
        from sicingr98_det_importes
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicingr98_det_importes.rela_socsyst10_mli01)
        where sicingr98_det_importes.rela_sicingr95 = :id_sicingr95
               and socsyst10_det_entradas.socsyst10_codigo = 'CONCEP-XMARGEN'
        into :sicingr98_importe;

        if (:p_socmain021 = -1) then
        begin
          /* Obtenemos la cantidad del producto cuando no se escoge organización */
            select sum(pymalma02_det_stock.pymalma02_cantidad) as cantidad
            from pymalma02_det_stock
            where  pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
            into :cantidad;

          /* Se calcula el Valor Inventario */
          valorInventario = :cantidad * :sicingr98_importe;

          /* Obtenemos la descripción de la organización para dicho producto*/
            select first 1
            socmain21_arb_organizacion.id_socmain21
            from pymalma01_cab_stock
            inner join socmain21_arb_organizacion on ( socmain21_arb_organizacion.id_socmain21 = pymalma01_cab_stock.rela_socmain21 )
            inner join pymalma02_det_stock on (pymalma01_cab_stock.id_pymalma01 = pymalma02_det_stock.rela_pymalma01 )
            where pymalma01_cab_stock.rela_socmain01 = :p_socmain01
            and pymalma02_det_stock.rela_sicingr95 = :id_sicingr95
            into :RELA_SOCMAIN21;

            SOCMAIN21_DESCRIPCION = iif(RELA_SOCMAIN21 is null, '-S/A-', 'En Sucursales');
        end


        if ((:p_cantidad = -1) or (:p_cantidad = 1 and :cantidad > 0) or
        (:p_cantidad = 2 and :cantidad < 0) or (:p_cantidad = 3 and :cantidad = 0)) then
        begin
            /* Obtenemos la clasificación y su valor, y filtramos por la misma */

            str = 'select
                    socsyst10_det_entradas.socsyst10_descripcion,
                    socsyst12_det_cla.socsyst12_descripcion
                from socsyst10_det_entradas
                   inner join sicingr97_det_clasificacion on (socsyst10_det_entradas.id_socsyst10 = sicingr97_det_clasificacion.rela_socsyst10_cdp01)
                   inner join socsyst12_det_cla on (sicingr97_det_clasificacion.rela_socsyst12 = socsyst12_det_cla.id_socsyst12)
                where sicingr97_det_clasificacion.rela_sicingr95 = ' || :id_sicingr95;

            socsyst10_path = '';
            socsyst12_path = '';
            if (:p_socsyst10 != -1 and :p_socsyst12 = -1) then
            begin
                strWhere = ' and sicingr97_det_clasificacion.rela_socsyst10_cdp01 = ' || :p_socsyst10;
                for execute statement :str || :strWhere
                into :socsyst10_path,
                     :socsyst12_path
                do begin
                    suspend;
                end
            end
            else if (:p_socsyst10 != -1 and :p_socsyst12 != -1) then
            begin
               strWhere = ' and sicingr97_det_clasificacion.rela_socsyst10_cdp01 = ' || :p_socsyst10 ||
                   'and sicingr97_det_clasificacion.rela_socsyst12 = ' || :p_socsyst12;
               for execute statement :str || :strWhere
                into :socsyst10_path,
                     :socsyst12_path
                do begin
                    suspend;
                end 
            end
            else
            begin
                for execute statement :str
                into :socsyst10_descripcion,
                     :socsyst12_descripcion
                do begin
                    socsyst10_path = :socsyst10_path || '/' || :socsyst10_descripcion;
                    socsyst12_path = :socsyst12_path || '/' || :socsyst12_descripcion;
                end
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE REP_SICINGR95_WEB (
    RELA_SOCMAIN01_IN BIGINT,
    FECHA_DESDE DATE,
    FECHA_HASTA DATE)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    ID_VIDINGR11 BIGINT,
    FAMILIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_CODIGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR95_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VIDINGR11_CANTIDAD DOUBLE PRECISION,
    VIDINGR11_IMPORTE DOUBLE PRECISION,
    VIDINGR11_TOTAL DOUBLE PRECISION,
    VIDINGR11_FAPL DATE)
AS
begin
    for select
        sicingr70_cab_facturacion.rela_socmain01,
        max(sicingr71_det_facturacion.id_sicingr71),
        coalesce((
            select first 1 grd_sicingr95_familia.socsyst12_descripcion
            from grd_sicingr95_familia
            where grd_sicingr95_familia.rela_sicingr95 = sicingr95_cab_conceptos.id_sicingr95
        ), cast('SIN FAMILIA' as varchar(50))),
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion,
        sum(sicingr71_det_facturacion.sicingr71_cantidad),
        sum(sicingr71_det_facturacion.sicingr71_importe_neto) / nullif(sum(sicingr71_det_facturacion.sicingr71_cantidad), 0),
        sum(sicingr71_det_facturacion.sicingr71_importe_neto),
        cast(max(sicingr71_det_facturacion.sicingr71_fapl) as date)
    from sicingr70_cab_facturacion
    inner join sicingr71_det_facturacion on (
        sicingr71_det_facturacion.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70
    )
    inner join sicingr95_cab_conceptos on (
        sicingr95_cab_conceptos.id_sicingr95 = sicingr71_det_facturacion.rela_sicingr95
    )
    where sicingr70_cab_facturacion.rela_socmain01 = :rela_socmain01_in
    and cast(sicingr71_det_facturacion.sicingr71_fapl as date)
        between :fecha_desde and :fecha_hasta
    group by
        sicingr70_cab_facturacion.rela_socmain01,
        sicingr95_cab_conceptos.id_sicingr95,
        sicingr95_cab_conceptos.sicingr95_codigo,
        sicingr95_cab_conceptos.sicingr95_descripcion
    order by
        sum(sicingr71_det_facturacion.sicingr71_cantidad) desc
    into
        :rela_socmain01,
        :id_vidingr11,
        :familia,
        :sicingr95_codigo,
        :sicingr95_descripcion,
        :vidingr11_cantidad,
        :vidingr11_importe,
        :vidingr11_total,
        :vidingr11_fapl
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICNOMI70 (
    ID_SICNOMI70X BIGINT)
RETURNS (
    ID_SICNOMI70 BIGINT,
    EMPLEADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO_NUMERO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO_SEGUROSOCIAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO_PUESTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO_DEPARTAMENTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_SALARIODIARIO DOUBLE PRECISION,
    NOMINA_SALARIONOMINAL DOUBLE PRECISION,
    NOMINA_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_FECHA_PAGO DATE,
    NOMINA_FECHA_INI DATE,
    NOMINA_FECHA_FIN DATE,
    NOMINA_FECHA_INILABOR DATE,
    NOMINA_DIAS INTEGER,
    NOMINA_TIPONOMINA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_PERIODO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_CONTRATO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_JORNADA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_REGIMEN VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOMINA_FECHA TIMESTAMP,
    SICNOMI74_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID_FECHA TIMESTAMP,
    SICNOMI74_UUID_IMPORTE DOUBLE PRECISION,
    SICNOMI74_SELLO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_SELLOSAT VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_CADENA VARCHAR(30000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_CERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_TOTAL_PERCEPCIONES DOUBLE PRECISION,
    SICNOMI74_TOTAL_DEDUCCIONES DOUBLE PRECISION,
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGIMEN_FISCAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI74_UUID_IMPORTE_LETRA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SICNOMI01 bigint;
declare variable SICNOMI70_TIPONOMINA varchar(10);
declare variable ID_SOCSYST10 bigint;
declare variable PERIODO_DES varchar(400);
declare variable DESCRIPCION_SAT varchar(400);
begin
    id_sicnomi70 = :id_sicnomi70x;

    Select
    sicnomi70_cab_nomina.rela_socmain01,
    sicnomi70_cab_nomina.rela_sicnomi01,
    sicnomi70_cab_nomina.sicnomi70_docnro,
    sicnomi70_cab_nomina.sicnomi70_tiponomina,
    sicnomi70_cab_nomina.sicnomi70_fecha,
    sicnomi70_cab_nomina.sicnomi70_fini,
    sicnomi70_cab_nomina.sicnomi70_ffin,
    sicnomi70_cab_nomina.sicnomi70_dias,
    sicnomi70_cab_nomina.sicnomi70_fapl
    from sicnomi70_cab_nomina
    where sicnomi70_cab_nomina.id_sicnomi70 = :id_sicnomi70
    into :rela_socmain01,
         :rela_sicnomi01,
         :nomina_folio,
         :sicnomi70_tiponomina,
         :nomina_fecha_pago,
         :nomina_fecha_ini,
         :nomina_fecha_fin,
         :nomina_dias,
         :nomina_fecha;

    Select
    cbo_sicnomi01_curp.entidad,
    cbo_sicnomi01_curp.curp,
    cbo_sicnomi01_curp.rfc
    from cbo_sicnomi01_curp
    where cbo_sicnomi01_curp.id_sicnomi01 = :rela_sicnomi01
    into :empleado,
         :empleado_curp,
         :empleado_rfc;

    nomina_tiponomina = null;

    if (UPPER(sicnomi70_tiponomina) = 'O') then
        nomina_tiponomina = 'Ordinaria';
    else if (UPPER(sicnomi70_tiponomina) = 'E') then
        nomina_tiponomina = 'Extraordinaria';

    select cast(sicnomi05_det_nomina.sicnomi05_valor as date)
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'FECHAINICIORELLABORAL'
    into :nomina_fecha_inilabor;

    select sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'PUESTO'
    into :empleado_puesto;

    
    select sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'DEPARTAMENTO'
    into :empleado_departamento;

    select sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'NUMEMPLEADO'
    into :empleado_numero;

    select sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'NUMSEGURIDADSOCIAL'
    into :empleado_segurosocial;

    select cast(sicnomi05_det_nomina.sicnomi05_valor as double precision)
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'SALARIODIARIOINTEGRADO'
    into :nomina_salariodiario;

    select cast(sicnomi05_det_nomina.sicnomi05_valor as double precision)
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'SALARIOBASECOTAPOR'
    into :nomina_salarionominal;

    /* ------------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------------ */

    select
    sicnomi05_det_nomina.rela_socsyst10_cno01,
    sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'PERIODICIDADPAGO'
    into :id_socsyst10, :nomina_periodo;

    select SOCSYST11_DET_SAT.socsyst11_descripcion
    from SOCSYST11_DET_SAT
    where SOCSYST11_DET_SAT.rela_socsyst10 = :id_socsyst10
    and SOCSYST11_DET_SAT.socsyst11_codigo = :nomina_periodo
    into :periodo_des;

    nomina_periodo = nomina_periodo || ' ' || periodo_des;


    select
    sicnomi05_det_nomina.rela_socsyst10_cno01,
    sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'TIPOCONTRATO'
    into :id_socsyst10, :nomina_contrato;

    select SOCSYST11_DET_SAT.socsyst11_descripcion
    from SOCSYST11_DET_SAT
    where SOCSYST11_DET_SAT.rela_socsyst10 = :id_socsyst10
    and SOCSYST11_DET_SAT.socsyst11_codigo = :nomina_contrato
    into :periodo_des;

    nomina_contrato = nomina_contrato || ' ' || periodo_des;

    select
    sicnomi05_det_nomina.rela_socsyst10_cno01,
    sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'TIPOJORNADA'
    into :id_socsyst10, :nomina_jornada;

    select SOCSYST11_DET_SAT.socsyst11_descripcion
    from SOCSYST11_DET_SAT
    where SOCSYST11_DET_SAT.rela_socsyst10 = :id_socsyst10
    and SOCSYST11_DET_SAT.socsyst11_codigo = :nomina_jornada
    into :periodo_des;

    nomina_jornada = nomina_jornada || ' ' || periodo_des;

    select
    sicnomi05_det_nomina.rela_socsyst10_cno01,
    sicnomi05_det_nomina.sicnomi05_valor
    from sicnomi05_det_nomina
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = sicnomi05_det_nomina.rela_socsyst10_cno01)
    where sicnomi05_det_nomina.rela_sicnomi01 = :rela_sicnomi01
    and socsyst10_det_entradas.socsyst10_codigo = 'TIPOREGIMEN'
    into :id_socsyst10, :nomina_regimen;

    select SOCSYST11_DET_SAT.socsyst11_descripcion
    from SOCSYST11_DET_SAT
    where SOCSYST11_DET_SAT.rela_socsyst10 = :id_socsyst10
    and SOCSYST11_DET_SAT.socsyst11_codigo = :nomina_regimen
    into :periodo_des;

    nomina_regimen = nomina_regimen || ' ' || periodo_des;

    select
    sicnomi74_dep_cfdis.sicnomi74_uuid,
    sicnomi74_dep_cfdis.sicnomi74_uuid_fecha,
    sicnomi74_dep_cfdis.sicnomi74_uuid_importe,
    sicnomi74_dep_cfdis.sicnomi74_sello,
    sicnomi74_dep_cfdis.sicnomi74_sellosat,
    sicnomi74_dep_cfdis.sicnomi74_cadena,
    sicnomi74_dep_cfdis.sicnomi74_certificado
    from sicnomi74_dep_cfdis
    where sicnomi74_dep_cfdis.rela_sicnomi70 = :id_sicnomi70
    into :sicnomi74_uuid,
         :sicnomi74_uuid_fecha,
         :sicnomi74_uuid_importe,
         :sicnomi74_sello,
         :sicnomi74_sellosat,
         :sicnomi74_cadena,
         :sicnomi74_certificado;

    select
    cfdi_empresa.razsocial,
    cfdi_empresa.rfc,
    cfdi_empresa.curp,
    cfdi_empresa.registropatronal,
    cfdi_empresa.socmain01_nocertificado
    from cfdi_empresa(:rela_socmain01)
    into :empresa_razsocial,
         :empresa_rfc,
         :empresa_curp,
         :empresa_regpatron,
         :empresa_certificado;

    select
    cfdi_empresa_regfiscal.rela_socsyst10_sat01,
    cfdi_empresa_regfiscal.regimen
    from cfdi_empresa_regfiscal(:rela_socmain01)
    into :id_socsyst10,
         :empresa_regimen_fiscal;

     select
     socsyst10_det_entradas.socsyst10_descripcion
     from socsyst10_det_entradas
     where socsyst10_det_entradas.id_socsyst10 = :id_socsyst10
     into :descripcion_sat;

    empresa_regimen_fiscal = empresa_regimen_fiscal || ' ' || descripcion_sat;

    /* ------------------------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------------------------ */

    SELECT CNUMERO FROM SMX$UTIL_NUM_MEXICO(:SICNOMI74_UUID_IMPORTE, 'MXN') INTO :SICNOMI74_UUID_IMPORTE_LETRA;

    select SUM(SICNOMI71_IMPORTE) from REP_SICNOMI70_PERCEPCIONES(:ID_SICNOMI70X) into :SICNOMI74_TOTAL_PERCEPCIONES;

    select SUM(SICNOMI71_IMPORTE) from REP_SICNOMI70_DEDUCCIONES(:ID_SICNOMI70X) into :SICNOMI74_TOTAL_DEDUCCIONES;

    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICNOMI70_DEDUCCIONES (
    ID_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI71 BIGINT,
    SICXMLS05_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS05_TIPOSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS05_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_IMPORTE DOUBLE PRECISION)
AS
begin
    for select
    sicnomi71_det_nomina.id_sicnomi71,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicxmls05_det_nomina.sicxmls05_concepto,
    sicnomi71_det_nomina.sicnomi71_importe
    from sicnomi71_det_nomina
    inner join sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'D' OR sicxmls05_det_nomina.sicxmls05_tipo = 'I')
    into :id_sicnomi71,
         :sicxmls05_tipo,
         :sicxmls05_tiposat,
         :sicxmls05_concepto,
         :sicnomi71_importe
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICNOMI70_NOMINAS (
    PARAM_EMPRESA BIGINT,
    PARAM_EMPLEADO BIGINT,
    PARAM_FECHADESDE DATE,
    PARAM_FECHAHASTA DATE,
    PARAM_TIPO INTEGER)
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SICNOMI01 BIGINT,
    ID_SICNOMI70 BIGINT,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPLEADO VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPONOMINA CHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO_NOMINA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FECHA_NOMINA DATE,
    FECHA_INICIO DATE,
    FECHA_FIN DATE,
    NRO_EMPLEADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NSS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALARIO_DIA DOUBLE PRECISION,
    SALARIO_BASE DOUBLE PRECISION,
    TOTAL_PERCEPCIONES DOUBLE PRECISION,
    TOTAL_DEDUCCIONES DOUBLE PRECISION,
    TIPO CHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IMPORTE DOUBLE PRECISION,
    PERCEPCIONES DOUBLE PRECISION,
    DEDUCCIONES DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    EMPRESA_RAZSOCIAL VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA_REGPATRON VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SQLUSER varchar(5000);
declare variable SQLWHERE varchar(1000);
BEGIN
  SELECT
      CFDI_EMPRESA.RAZSOCIAL,
      CFDI_EMPRESA.RFC,
      CFDI_EMPRESA.CURP,
      CFDI_EMPRESA.REGISTROPATRONAL
  FROM CFDI_EMPRESA(:PARAM_EMPRESA)
  INTO
      :EMPRESA_RAZSOCIAL,
      :EMPRESA_RFC,
      :EMPRESA_CURP,
      :EMPRESA_REGPATRON;

  SELECT SUM(SICNOMI71_DET_NOMINA.SICNOMI71_IMPORTE)
  FROM SICNOMI70_CAB_NOMINA
  INNER JOIN SICNOMI71_DET_NOMINA ON (SICNOMI70_CAB_NOMINA.ID_SICNOMI70 = SICNOMI71_DET_NOMINA.RELA_SICNOMI70)
  INNER JOIN SICXMLS05_DET_NOMINA ON (SICNOMI71_DET_NOMINA.RELA_SICXMLS05 = SICXMLS05_DET_NOMINA.ID_SICXMLS05)
  WHERE SICNOMI70_CAB_NOMINA.RELA_SOCMAIN01 = :PARAM_EMPRESA
    AND SICNOMI70_CAB_NOMINA.SICNOMI70_FECHA BETWEEN :PARAM_FECHADESDE AND :PARAM_FECHAHASTA
    AND (SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'P' OR
         SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'H' OR
         SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'O')
  INTO :TOTAL_PERCEPCIONES;

  SELECT SUM(SICNOMI71_DET_NOMINA.SICNOMI71_IMPORTE)
  FROM SICNOMI70_CAB_NOMINA
  INNER JOIN SICNOMI71_DET_NOMINA ON (SICNOMI70_CAB_NOMINA.ID_SICNOMI70 = SICNOMI71_DET_NOMINA.RELA_SICNOMI70)
  INNER JOIN SICXMLS05_DET_NOMINA ON (SICNOMI71_DET_NOMINA.RELA_SICXMLS05 = SICXMLS05_DET_NOMINA.ID_SICXMLS05)
  WHERE SICNOMI70_CAB_NOMINA.RELA_SOCMAIN01 = :PARAM_EMPRESA
    AND SICNOMI70_CAB_NOMINA.SICNOMI70_FECHA BETWEEN :PARAM_FECHADESDE AND :PARAM_FECHAHASTA
    AND (SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'D' OR
         SICXMLS05_DET_NOMINA.sicxmls05_tipo = 'I')
  INTO :TOTAL_DEDUCCIONES;

  SQLUSER = 'SELECT
                 SICNOMI70_CAB_NOMINA.RELA_SOCMAIN01,
                 SICNOMI70_CAB_NOMINA.RELA_SOCMAIN21,
                 SICNOMI70_CAB_NOMINA.RELA_SICNOMI01,
                 SICNOMI70_CAB_NOMINA.ID_SICNOMI70,
                 SOCMAIN01_CAB_EMPRESAS.SOCMAIN01_NOMCOMERCIAL,
                 SOCMAIN21_ARB_ORGANIZACION.SOCMAIN21_DESCRIPCION,
                 SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_APELLIDO_PAT || '' '' || SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_APELLIDO_MAT || '' '' || SOCUSUA30_CAB_ENTIDADES.SOCUSUA30_NOMBRE_RAZSOC,
                 SICNOMI70_CAB_NOMINA.SICNOMI70_TIPONOMINA,
                 SICNOMI70_CAB_NOMINA.SICNOMI70_DOCNRO,
                 SICNOMI70_CAB_NOMINA.SICNOMI70_FECHA,
                 SICNOMI70_CAB_NOMINA.SICNOMI70_FINI,
                 SICNOMI70_CAB_NOMINA.SICNOMI70_FFIN
             FROM SICNOMI70_CAB_NOMINA
             INNER JOIN SOCMAIN01_CAB_EMPRESAS ON (SICNOMI70_CAB_NOMINA.RELA_SOCMAIN01 = SOCMAIN01_CAB_EMPRESAS.ID_SOCMAIN01)
             INNER JOIN SOCMAIN21_ARB_ORGANIZACION ON (SICNOMI70_CAB_NOMINA.RELA_SOCMAIN21 = SOCMAIN21_ARB_ORGANIZACION.ID_SOCMAIN21)
             INNER JOIN SICNOMI01_CAB_EMPLEADOS ON (SICNOMI70_CAB_NOMINA.RELA_SICNOMI01 = SICNOMI01_CAB_EMPLEADOS.ID_SICNOMI01)
             INNER JOIN SOCUSUA30_CAB_ENTIDADES ON (SICNOMI01_CAB_EMPLEADOS.RELA_SOCUSUA30 = SOCUSUA30_CAB_ENTIDADES.ID_SOCUSUA30)
             WHERE SICNOMI70_CAB_NOMINA.RELA_SOCMAIN01 = ' || :PARAM_EMPRESA ||
             ' AND SICNOMI70_CAB_NOMINA.SICNOMI70_FECHA BETWEEN ''' || :PARAM_FECHADESDE || ''' AND ''' || :PARAM_FECHAHASTA || '''';

  SQLWHERE = '';
  IF (:PARAM_EMPLEADO != -1) THEN
    SQLWHERE = ' AND SICNOMI01_CAB_EMPLEADOS.ID_SICNOMI01 = ' || :PARAM_EMPLEADO;

  FOR EXECUTE STATEMENT :SQLUSER || :SQLWHERE
  INTO
      :RELA_SOCMAIN01,
      :RELA_SOCMAIN21,
      :RELA_SICNOMI01,
      :ID_SICNOMI70,
      :EMPRESA,
      :ORGANIZACION,
      :EMPLEADO,
      :TIPONOMINA,
      :FOLIO_NOMINA,
      :FECHA_NOMINA,
      :FECHA_INICIO,
      :FECHA_FIN
  DO
  BEGIN
    NRO_EMPLEADO = '';
    NSS = '';
    SALARIO_DIA = 0;
    SALARIO_BASE = 0;

    SELECT SICNOMI05_DET_NOMINA.SICNOMI05_VALOR
    FROM SICNOMI05_DET_NOMINA
    INNER JOIN SOCSYST10_DET_ENTRADAS on (SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = SICNOMI05_DET_NOMINA.RELA_SOCSYST10_CNO01)
    WHERE SICNOMI05_DET_NOMINA.RELA_SICNOMI01 = :RELA_SICNOMI01
      AND SOCSYST10_DET_ENTRADAS.SOCSYST10_CODIGO = 'NUMEMPLEADO'
    INTO :NRO_EMPLEADO;

    SELECT SICNOMI05_DET_NOMINA.SICNOMI05_VALOR
    FROM SICNOMI05_DET_NOMINA
    INNER JOIN SOCSYST10_DET_ENTRADAS on (SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = SICNOMI05_DET_NOMINA.RELA_SOCSYST10_CNO01)
    WHERE SICNOMI05_DET_NOMINA.RELA_SICNOMI01 = :RELA_SICNOMI01
      AND SOCSYST10_DET_ENTRADAS.SOCSYST10_CODIGO = 'NUMSEGURIDADSOCIAL'
    INTO :NSS;

    SELECT CAST(SICNOMI05_DET_NOMINA.SICNOMI05_VALOR AS DOUBLE PRECISION)
    FROM SICNOMI05_DET_NOMINA
    INNER JOIN SOCSYST10_DET_ENTRADAS on (SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = SICNOMI05_DET_NOMINA.RELA_SOCSYST10_CNO01)
    WHERE SICNOMI05_DET_NOMINA.RELA_SICNOMI01 = :RELA_SICNOMI01
      AND SOCSYST10_DET_ENTRADAS.SOCSYST10_CODIGO = 'SALARIODIARIOINTEGRADO'
    INTO :SALARIO_DIA;

    SELECT CAST(SICNOMI05_DET_NOMINA.SICNOMI05_VALOR AS DOUBLE PRECISION)
    FROM SICNOMI05_DET_NOMINA
    INNER JOIN SOCSYST10_DET_ENTRADAS on (SOCSYST10_DET_ENTRADAS.ID_SOCSYST10 = SICNOMI05_DET_NOMINA.RELA_SOCSYST10_CNO01)
    WHERE SICNOMI05_DET_NOMINA.RELA_SICNOMI01 = :RELA_SICNOMI01
      AND SOCSYST10_DET_ENTRADAS.SOCSYST10_CODIGO = 'SALARIOBASECOTAPOR'
    INTO :SALARIO_BASE;

    IF (:PARAM_TIPO = 0) THEN
      BEGIN
        PERCEPCIONES = 0;
        DEDUCCIONES = 0;
        TOTAL = 0;

        SELECT SUM(REP_SICNOMI70_PERCEPCIONES.SICNOMI71_IMPORTE)
        FROM REP_SICNOMI70_PERCEPCIONES(:ID_SICNOMI70)
        INTO :PERCEPCIONES;

        IF (:PERCEPCIONES IS NULL) THEN
          PERCEPCIONES = 0;

        SELECT SUM(REP_SICNOMI70_DEDUCCIONES.SICNOMI71_IMPORTE)
        FROM REP_SICNOMI70_DEDUCCIONES(:ID_SICNOMI70)
        INTO :DEDUCCIONES;

        IF (:DEDUCCIONES IS NULL) THEN
          DEDUCCIONES = 0;

        TOTAL = PERCEPCIONES - DEDUCCIONES;

        SUSPEND;
      END
    ELSE
      BEGIN
        FOR
          SELECT
              'P',
              REP_SICNOMI70_PERCEPCIONES.SICXMLS05_CONCEPTO,
              REP_SICNOMI70_PERCEPCIONES.SICNOMI71_IMPORTE
          FROM REP_SICNOMI70_PERCEPCIONES(:ID_SICNOMI70)
          INTO
              :TIPO,
              :CONCEPTO,
              :IMPORTE
        DO
        BEGIN
          SUSPEND;
        END

        FOR
          SELECT
              'D',
              REP_SICNOMI70_DEDUCCIONES.SICXMLS05_CONCEPTO,
              REP_SICNOMI70_DEDUCCIONES.SICNOMI71_IMPORTE
          FROM REP_SICNOMI70_DEDUCCIONES(:ID_SICNOMI70)
          INTO
              :TIPO,
              :CONCEPTO,
              :IMPORTE
        DO
        BEGIN
          SUSPEND;
        END
      END
  END
END^


CREATE OR ALTER PROCEDURE REP_SICNOMI70_PERCEPCIONES (
    ID_SICNOMI70 BIGINT)
RETURNS (
    ID_SICNOMI71 BIGINT,
    SICXMLS05_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS05_TIPOSAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS05_CONCEPTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICNOMI71_IMPORTE DOUBLE PRECISION)
AS
begin
    for select
    sicnomi71_det_nomina.id_sicnomi71,
    sicxmls05_det_nomina.sicxmls05_tipo,
    sicxmls05_det_nomina.sicxmls05_tiposat,
    sicxmls05_det_nomina.sicxmls05_concepto,
    sicnomi71_det_nomina.sicnomi71_importe
    from sicnomi71_det_nomina
    inner join sicxmls05_det_nomina on ( sicxmls05_det_nomina.id_sicxmls05 = sicnomi71_det_nomina.rela_sicxmls05 )
    where sicnomi71_det_nomina.rela_sicnomi70 = :id_sicnomi70
    and (sicxmls05_det_nomina.sicxmls05_tipo = 'P' or
         sicxmls05_det_nomina.sicxmls05_tipo = 'H' or
         sicxmls05_det_nomina.sicxmls05_tipo = 'O')
    into :id_sicnomi71,
         :sicxmls05_tipo,
         :sicxmls05_tiposat,
         :sicxmls05_concepto,
         :sicnomi71_importe
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICPAGO70 (
    ID_SICPAGO70X BIGINT,
    ENTRADA INTEGER)
RETURNS (
    RELA_SICINGR51 BIGINT,
    ID_SICPAGO70 BIGINT,
    EMISOR_NOMBRECOMERCIAL VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_NOMBRE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_REGIMENFISCAL VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CERTIFICADO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RECEPTOR_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RECEPTOR_NOMBRE VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_FECHA DATE,
    PAGO_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_TIPOCAMBIO DOUBLE PRECISION,
    PAGO_MONTO DOUBLE PRECISION,
    PAGO_FORMA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_NUMOPERACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_CTAORDENANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_NOMBREORDENANTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_RFCORDENANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_CTABENEFICIARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_NOMBREBENEFICIARIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_RFCBENEFICIARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_FECHA TIMESTAMP,
    TIMBRE_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_SELLOSAT VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_SELLOCFD VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_CERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_CADENA VARCHAR(30000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_SERIEFOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_TIPOCAMBIO DOUBLE PRECISION,
    DOCREL_METODOPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_NUMPARCIALIDAD INTEGER,
    DOCREL_SALDOANTERIOR DOUBLE PRECISION,
    DOCREL_IMPORTEPAGADO DOUBLE PRECISION,
    DOCREL_SALDOACT DOUBLE PRECISION,
    SICINGR51_CTAORD INTEGER)
AS
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SICINGR50 bigint;
declare variable RELA_SICCONT10 bigint;
declare variable ID_SICXMLS41 bigint;
declare variable ID_SICINGR52 bigint;
declare variable IMPORTE_XML double precision;
declare variable SUMAPAGOS double precision;
declare variable SICXMLS41_ORIGEN varchar(20);
declare variable DOCREL_METODOPAGO_TMP varchar(400);
begin
  select sicpago70_cab_pago.rela_socmain01,
         sicingr51_cab_bancos.rela_sicingr01,
         sicingr51_cab_bancos.id_sicingr51,
         sicpago70_cab_pago.id_sicpago70,
         sicpago70_cab_pago.sicpago70_serie,
         sicpago70_cab_pago.sicpago70_docnro,
         'XXX',
         '(' || FORMAPAGO.socsyst10_grupo || ') ' || FORMAPAGO.socsyst10_descripcion,
         sicingr51_cab_bancos.sicingr51_fecha,
         sicingr51_cab_bancos.sicingr51_cotiza,
         sicingr51_cab_bancos.sicingr51_importe,
         sicingr51_cab_bancos.sicingr51_referencia,
         BANORD.socsyst10_valor01,
         BANORD.socsyst10_descripcion,
         sicingr51_cab_bancos.sicingr51_cuenta,
         BANBEN.socsyst10_valor01,
         BANBEN.socsyst10_descripcion,
         socmain05_det_bancos.socmain05_cuenta,
         sicingr51_cab_bancos.sicingr51_ctaord
    from sicpago70_cab_pago
   inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51 )
   inner join socsyst10_det_entradas FORMAPAGO on ( sicingr51_cab_bancos.rela_socsyst10_mdp01 = FORMAPAGO.id_socsyst10 )
   inner join socsyst10_det_entradas BANORD on ( sicingr51_cab_bancos.rela_socsyst10_ban01 = BANORD.id_socsyst10 )
   inner join socmain05_det_bancos on ( sicingr51_cab_bancos.rela_socmain05 = socmain05_det_bancos.id_socmain05)
   inner join socsyst10_det_entradas BANBEN on (socmain05_det_bancos.rela_socsyst10_ban01 =  BANBEN.id_socsyst10 )
   where sicpago70_cab_pago.id_sicpago70 = :id_sicpago70x
    into :rela_socmain01,
         :rela_sicingr01,
         :rela_sicingr51,
         :id_sicpago70,
         :pago_serie,
         :pago_folio,
         :pago_moneda,
         :pago_forma, 
         :pago_fecha,
         :pago_tipocambio,
         :pago_monto,
         :pago_numoperacion,
         :pago_rfcordenante,
         :pago_nombreordenante,
         :pago_ctaordenante,
         :pago_rfcbeneficiario,
         :pago_nombrebeneficiario,
         :pago_ctabeneficiario,
         :sicingr51_ctaord;


  Select cfdi_empresa.socmain01_nomcomercial,
         cfdi_empresa.socmain01_nocertificado,
         cfdi_empresa.rfc,
         cfdi_empresa.curp,
         cfdi_empresa.razsocial,
         cfdi_empresa.domf_codpostal,
         '(' || socsyst10_det_entradas.socsyst10_codigo || ') ' || socsyst10_det_entradas.socsyst10_descripcion
    from cfdi_empresa(:rela_socmain01)
   inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = :rela_socmain01)
   inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01 )
    into :emisor_nombrecomercial,
         :emisor_certificado,
         :emisor_rfc,
         :emisor_curp,
         :emisor_nombre,
         :emisor_codpostal,
         :emisor_regimenfiscal;

  Select cbo_sicingr01_id.entidad,
         cbo_sicingr01_id.rfc
    from cbo_sicingr01_id
   where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
    into :receptor_nombre,
         :receptor_rfc;

  select sicpago74_dep_cfdis.sicpago74_uuid,
         sicpago74_dep_cfdis.sicpago74_uuid_fecha,
         sicpago74_dep_cfdis.sicpago74_sello,
         sicpago74_dep_cfdis.sicpago74_sellosat,
         sicpago74_dep_cfdis.sicpago74_cadena,
         sicpago74_dep_cfdis.sicpago74_certificado
    from sicpago74_dep_cfdis
   where sicpago74_dep_cfdis.rela_sicpago70 = :id_sicpago70x
    into :timbre_uuid,
         :timbre_fecha,
         :timbre_sellocfd,
         :timbre_sellosat,
         :timbre_cadena,
         :timbre_certificado;

    /* Seccion de Documentos Relacionados */

    for select sicingr52_det_bancos.id_sicingr52,
               sicingr52_det_bancos.rela_sicingr50,
               sicingr52_det_bancos.sicingr52_importe,
               sicingr50_det_ctacte.sicingr50_importe,
               sicingr50_det_ctacte.rela_siccont10
          from sicingr52_det_bancos
         inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
         where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51
          into :id_sicingr52,
               :rela_sicingr50,
               :docrel_importepagado,
               :importe_xml,
               :rela_siccont10
    do
       begin
          docrel_numparcialidad = 0;
          docrel_saldoanterior = importe_xml;
          docrel_saldoact = 0;

          select sicxmls41_det_migracion.id_sicxmls41,
                 sicxmls41_det_migracion.sicxmls41_uuid,
                 sicxmls41_det_migracion.sicxmls41_folio,
                 sicxmls41_det_migracion.sicxmls41_moneda,
                 sicxmls41_det_migracion.sicxmls41_cambio,
                 sicxmls41_det_migracion.sicxmls41_origen
            from sicxmls41_det_migracion
           where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
           into :id_sicxmls41,
                :docrel_uuid,
                :docrel_seriefolio,
                :docrel_moneda,
                :docrel_tipocambio,
                :sicxmls41_origen;

        if (docrel_moneda = 'MXN') then
            docrel_tipocambio = null;
        else
        begin
            if (entrada = 0) then
            begin
                entrada = 1;

                select sum(rep_sicpago70.docrel_importepagado)
                from rep_sicpago70(:id_sicpago70x, :entrada)
                into :pago_monto;
            end
        end

        if (sicxmls41_origen = 'F') then
           begin
              select ' ( ' || socsyst10_det_remoto.socsyst10_codigo || ' ) ' || socsyst10_det_remoto.socsyst10_descripcion,
                  socsyst10_det_remoto.socsyst10_codigo
                from sicingr74_dep_cfdis
               inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
               inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
               where sicingr74_dep_cfdis.rela_sicxmls41 = :id_sicxmls41
                into :docrel_metodopago,
                     :docrel_metodopago_tmp;    --HV el 24/04/2019
            end
        else
            begin
                select sicxmls41_det_migracion.sicxmls41_metododepago
                  from sicxmls41_det_migracion
                 where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41
                  into :docrel_metodopago;
            end

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (docrel_importepagado <> importe_xml) then
            begin
                select count(sicingr52_det_bancos.id_sicingr52),
                       sum(sicingr52_det_bancos.sicingr52_importe)
                  from sicingr52_det_bancos
                 where sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
                   and sicingr52_det_bancos.id_sicingr52 < :id_sicingr52
                  into :docrel_numparcialidad,
                       :sumapagos;

                docrel_numparcialidad = docrel_numparcialidad + 1;

                if (sumapagos is null) then
                    sumapagos = 0;

                docrel_saldoact = importe_xml - (docrel_importepagado + sumapagos);

                if (sumapagos = 0) then
                    docrel_saldoanterior = importe_xml;
                else
                    docrel_saldoanterior = importe_xml - sumapagos;
            end

--        porcentaje = docrel_importepagado / importe_xml * 100;

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        -- HV se agregó el codigo temporal con el ORs
        if ((docrel_metodopago = 'PPD' or docrel_metodopago_tmp = 'PPD')  and docrel_numparcialidad = 0) then
            docrel_numparcialidad = 1;

        if (docrel_moneda <> 'MXN') then
        begin
            if (docrel_saldoact <> 0) then
                docrel_saldoact = docrel_saldoact;

            if (docrel_saldoanterior <> 0) then
                docrel_saldoanterior = docrel_saldoanterior;

            if (docrel_importepagado <> 0) then
                docrel_importepagado = docrel_importepagado;
        end
        
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICPAGO70_CAB (
    ID_SICPAGO70X BIGINT)
RETURNS (
    RELA_SICINGR51 BIGINT,
    ID_SICPAGO70 BIGINT,
    EMISOR_NOMBRECOMERCIAL VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CURP VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CODPOSTAL VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_NOMBRE VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_REGIMENFISCAL VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CERTIFICADO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RECEPTOR_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RECEPTOR_NOMBRE VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_FECHA DATE,
    PAGO_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_TIPOCAMBIO DOUBLE PRECISION,
    PAGO_MONTO DOUBLE PRECISION,
    PAGO_FORMA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_NUMOPERACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_CTAORDENANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_NOMBREORDENANTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_RFCORDENANTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_CTABENEFICIARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_NOMBREBENEFICIARIO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_RFCBENEFICIARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_FECHA TIMESTAMP,
    TIMBRE_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_SELLOSAT VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_SELLOCFD VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_CERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_CADENA VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR51_CTAORD INTEGER)
AS
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCMAIN01 bigint;
begin
  select sicpago70_cab_pago.rela_socmain01,
         sicingr51_cab_bancos.rela_sicingr01,
         sicingr51_cab_bancos.id_sicingr51,
         sicpago70_cab_pago.id_sicpago70,
         sicpago70_cab_pago.sicpago70_serie,
         sicpago70_cab_pago.sicpago70_docnro,
         'XXX',
         '(' || FORMAPAGO.socsyst10_grupo || ') ' || FORMAPAGO.socsyst10_descripcion,
         sicingr51_cab_bancos.sicingr51_fecha,
         sicingr51_cab_bancos.sicingr51_cotiza,
         sicingr51_cab_bancos.sicingr51_importe,
         sicingr51_cab_bancos.sicingr51_referencia,
         BANORD.socsyst10_valor01,
         BANORD.socsyst10_descripcion,
         sicingr51_cab_bancos.sicingr51_cuenta,
         BANBEN.socsyst10_valor01,
         BANBEN.socsyst10_descripcion,
         socmain05_det_bancos.socmain05_cuenta,
         sicingr51_cab_bancos.sicingr51_ctaord
    from sicpago70_cab_pago
   inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51 )
   inner join socsyst10_det_entradas FORMAPAGO on ( sicingr51_cab_bancos.rela_socsyst10_mdp01 = FORMAPAGO.id_socsyst10 )
   inner join socsyst10_det_entradas BANORD on ( sicingr51_cab_bancos.rela_socsyst10_ban01 = BANORD.id_socsyst10 )
   inner join socmain05_det_bancos on ( sicingr51_cab_bancos.rela_socmain05 = socmain05_det_bancos.id_socmain05)
   inner join socsyst10_det_entradas BANBEN on (socmain05_det_bancos.rela_socsyst10_ban01 =  BANBEN.id_socsyst10 )
   where sicpago70_cab_pago.id_sicpago70 = :id_sicpago70x
    into :rela_socmain01,
         :rela_sicingr01,
         :rela_sicingr51,
         :id_sicpago70,
         :pago_serie,
         :pago_folio,
         :pago_moneda,
         :pago_forma, 
         :pago_fecha,
         :pago_tipocambio,
         :pago_monto,
         :pago_numoperacion,
         :pago_rfcordenante,
         :pago_nombreordenante,
         :pago_ctaordenante,
         :pago_rfcbeneficiario,
         :pago_nombrebeneficiario,
         :pago_ctabeneficiario,
         :sicingr51_ctaord;


  Select cfdi_empresa.socmain01_nomcomercial,
         cfdi_empresa.socmain01_nocertificado,
         cfdi_empresa.rfc,
         cfdi_empresa.curp,
         cfdi_empresa.razsocial,
         cfdi_empresa.domf_codpostal,
         '(' || socsyst10_det_entradas.socsyst10_codigo || ') ' || socsyst10_det_entradas.socsyst10_descripcion
    from cfdi_empresa(:rela_socmain01)
   inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = :rela_socmain01)
   inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01 )
    into :emisor_nombrecomercial,
         :emisor_certificado,
         :emisor_rfc,
         :emisor_curp,
         :emisor_nombre,
         :emisor_codpostal,
         :emisor_regimenfiscal;

  receptor_nombre = NULL;

  SELECT
  sicxmls41_det_migracion.sicxmls41_entidad,
  sicxmls41_det_migracion.sicxmls41_rfc
  FROM sicpago50_cab_factoraje
  INNER join sicxmls41_det_migracion ON (sicxmls41_det_migracion.id_sicxmls41 = sicpago50_cab_factoraje.rela_sicxmls41_comi)
  WHERE sicpago50_cab_factoraje.rela_sicingr51 = :rela_sicingr51
  into :receptor_nombre,
       :receptor_rfc;

  if (receptor_nombre IS NULL) then
  BEGIN
        Select cbo_sicingr01_id.entidad,
             cbo_sicingr01_id.rfc
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :receptor_nombre,
             :receptor_rfc;
  END

  select sicpago74_dep_cfdis.sicpago74_uuid,
         sicpago74_dep_cfdis.sicpago74_uuid_fecha,
         sicpago74_dep_cfdis.sicpago74_sello,
         sicpago74_dep_cfdis.sicpago74_sellosat,
         sicpago74_dep_cfdis.sicpago74_cadena,
         sicpago74_dep_cfdis.sicpago74_certificado
    from sicpago74_dep_cfdis
   where sicpago74_dep_cfdis.rela_sicpago70 = :id_sicpago70x
    into :timbre_uuid,
         :timbre_fecha,
         :timbre_sellocfd,
         :timbre_sellosat,
         :timbre_cadena,
         :timbre_certificado;

    select sum(rep_sicpago70_det.docrel_importepagado)
    from rep_sicpago70_det(:rela_sicingr51)
    into :pago_monto;
    
    suspend;
end^


CREATE OR ALTER PROCEDURE REP_SICPAGO70_DET (
    RELA_SICINGR51X BIGINT)
RETURNS (
    DOCREL_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SICINGR52 BIGINT,
    DOCREL_SERIEFOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_TIPOCAMBIO DOUBLE PRECISION,
    DOCREL_METODOPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_NUMPARCIALIDAD INTEGER,
    DOCREL_SALDOANTERIOR DOUBLE PRECISION,
    DOCREL_IMPORTEPAGADO DOUBLE PRECISION,
    DOCREL_SALDOACT DOUBLE PRECISION)
AS
declare variable RELA_SICINGR50 bigint;
declare variable RELA_SICCONT10 bigint;
declare variable ID_SICXMLS41 bigint;
declare variable IMPORTE_XML double precision;
declare variable SUMAPAGOS double precision;
declare variable SICXMLS41_ORIGEN varchar(20);
begin
    for select sicingr52_det_bancos.id_sicingr52,
               sicingr52_det_bancos.rela_sicingr50,
               sicingr52_det_bancos.sicingr52_importe,
               sicingr50_det_ctacte.sicingr50_importe,
               sicingr50_det_ctacte.rela_siccont10
          from sicingr52_det_bancos
    inner join sicingr50_det_ctacte on ( sicingr50_det_ctacte.id_sicingr50 = sicingr52_det_bancos.rela_sicingr50 )
         where sicingr52_det_bancos.rela_sicingr51 = :rela_sicingr51X
          into :id_sicingr52,
               :rela_sicingr50,
               :docrel_importepagado,
               :importe_xml,
               :rela_siccont10
    do
       begin
          docrel_numparcialidad = 0;
          docrel_saldoanterior = importe_xml;
          docrel_saldoact = 0;

          select sicxmls41_det_migracion.id_sicxmls41,
                 sicxmls41_det_migracion.sicxmls41_uuid,
                 sicxmls41_det_migracion.sicxmls41_folio,
                 sicxmls41_det_migracion.sicxmls41_moneda,
                 sicxmls41_det_migracion.sicxmls41_cambio,
                 sicxmls41_det_migracion.sicxmls41_origen
            from sicxmls41_det_migracion
           where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
           into :id_sicxmls41,
                :docrel_uuid,
                :docrel_seriefolio,
                :docrel_moneda,
                :docrel_tipocambio,
                :sicxmls41_origen;

        if (docrel_moneda = 'MXN') then
            docrel_tipocambio = null;

        if (sicxmls41_origen = 'F') then
           begin
              select ' ( ' || socsyst10_det_remoto.socsyst10_codigo || ' ) ' || socsyst10_det_remoto.socsyst10_descripcion
                from sicingr74_dep_cfdis
               inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
               inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr70_cab_facturacion.rela_socsyst10_met01 )
               where sicingr74_dep_cfdis.rela_sicxmls41 = :id_sicxmls41
                into :docrel_metodopago;
            end
        else
            begin
                select sicxmls41_det_migracion.sicxmls41_metododepago
                  from sicxmls41_det_migracion
                 where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41
                  into :docrel_metodopago;
            end

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (docrel_importepagado <> importe_xml) then
            begin
                select count(sicingr52_det_bancos.id_sicingr52),
                       sum(sicingr52_det_bancos.sicingr52_importe)
                  from sicingr52_det_bancos
                 where sicingr52_det_bancos.rela_sicingr50 = :rela_sicingr50
                   and sicingr52_det_bancos.id_sicingr52 < :id_sicingr52
                  into :docrel_numparcialidad,
                       :sumapagos;

                docrel_numparcialidad = docrel_numparcialidad + 1;

                if (sumapagos is null) then
                    sumapagos = 0;

                docrel_saldoact = importe_xml - (docrel_importepagado + sumapagos);

                if (sumapagos = 0) then
                    docrel_saldoanterior = importe_xml;
                else
                    docrel_saldoanterior = importe_xml - sumapagos;
            end

--        porcentaje = docrel_importepagado / importe_xml * 100;

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (docrel_metodopago = 'PPD' and docrel_numparcialidad = 0) then
            docrel_numparcialidad = 1;

        if (docrel_moneda <> 'MXN') then
        begin
            if (docrel_saldoact <> 0) then
                docrel_saldoact = docrel_saldoact;

            if (docrel_saldoanterior <> 0) then
                docrel_saldoanterior = docrel_saldoanterior;

            if (docrel_importepagado <> 0) then
                docrel_importepagado = docrel_importepagado;
        end
        
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SICPAGO70_FACTORAJE (
    ID_SICPAGO70 BIGINT)
RETURNS (
    IDDOCUMENTO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MONEDADR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    METODODEPAGODR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICPAGO50_COMISION DOUBLE PRECISION,
    IMPSALDOANT_FAC DOUBLE PRECISION,
    IMPSALDOANT_COM DOUBLE PRECISION,
    IMPPAGADO_FAC DOUBLE PRECISION,
    IMPPAGADO_COM DOUBLE PRECISION,
    IMPSALDOINSOLUTO_FAC DOUBLE PRECISION)
AS
declare variable RELA_SICINGR51 bigint;
declare variable SICXMLS41_UUID_IMPORTE double precision;
begin
    SELECT sicpago70_cab_pago.rela_sicingr51
    FROM sicpago70_cab_pago
    WHERE sicpago70_cab_pago.id_sicpago70 = :id_sicpago70
    into :rela_sicingr51;

    select
    sicpago50_cab_factoraje.sicpago50_comision
    from sicpago50_cab_factoraje
    where sicpago50_cab_factoraje.rela_sicingr51 = :rela_sicingr51
    into :sicpago50_comision;

    for select
    GRD_SICINGR52_SICPAGO70.sicxmls41_uuid,
    GRD_SICINGR52_SICPAGO70.sicxmls41_folio,
    GRD_SICINGR52_SICPAGO70.sicxmls41_metododepago,
    GRD_SICINGR52_SICPAGO70.sicxmls41_moneda,
    GRD_SICINGR52_SICPAGO70.sicxmls41_uuid_importe
    from GRD_SICINGR52_SICPAGO70
    where GRD_SICINGR52_SICPAGO70.rela_sicingr51 = :rela_sicingr51
    into :iddocumento,
         :folio,
         :metododepagodr,
         :monedadr,
         :sicxmls41_uuid_importe
    do
    begin
        impsaldoant_fac = sicxmls41_uuid_importe;
        impsaldoinsoluto_fac = impsaldoant_fac * sicpago50_comision / 100;
        imppagado_fac = impsaldoant_fac - impsaldoinsoluto_fac;

        imppagado_com = impsaldoinsoluto_fac;
        impsaldoant_com = impsaldoinsoluto_fac;
        suspend;
    end
end^


