    EMISOR_REGIMENFISCAL VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMISOR_CERTIFICADO VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RECEPTOR_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RECEPTOR_NOMBRE VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_FOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_FECHA DATE,
    PAGO_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PAGO_TIPOCAMBIO DOUBLE PRECISION,
