    TIMBRE_FECHA TIMESTAMP,
    TIMBRE_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_SELLOSAT VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_SELLOCFD VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_CERTIFICADO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIMBRE_CADENA VARCHAR(30000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_SERIEFOLIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_MONEDA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_TIPOCAMBIO DOUBLE PRECISION,
    DOCREL_METODOPAGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DOCREL_NUMPARCIALIDAD INTEGER,
    DOCREL_SALDOANTERIOR DOUBLE PRECISION,
    DOCREL_IMPORTEPAGADO DOUBLE PRECISION,
    DOCREL_SALDOACT DOUBLE PRECISION,
    SICINGR51_CTAORD INTEGER)
AS
declare variable RELA_SICINGR01 bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable IMPORTE_XML double precision;
declare variable SUMAPAGOS double precision;
declare variable ID_SICINGR70 bigint;
begin
  select sicpago70_cab_pago.rela_socmain01,
         sicingr51_cab_bancos.rela_sicingr01,
         sicingr51_cab_bancos.id_sicingr51,
         sicpago70_cab_pago.id_sicpago70,
         sicpago70_cab_pago.sicpago70_serie,
         sicpago70_cab_pago.sicpago70_docnro,
         'XXX',
         '(' || FORMAPAGO.socsyst10_grupo || ') ' || FORMAPAGO.socsyst10_descripcion,
         sicingr51_cab_bancos.sicingr51_fecha,
         sicingr51_cab_bancos.sicingr51_cotiza,
         sicingr51_cab_bancos.sicingr51_importe,
         sicingr51_cab_bancos.sicingr51_referencia,
         BANORD.socsyst10_valor01,
         BANORD.socsyst10_descripcion,
         sicingr51_cab_bancos.sicingr51_cuenta,
         BANBEN.socsyst10_valor01,
         BANBEN.socsyst10_descripcion,
         socmain05_det_bancos.socmain05_cuenta,
         sicingr51_cab_bancos.sicingr51_ctaord
    from sicpago70_cab_pago
   inner join sicingr51_cab_bancos on ( sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51 )
   inner join socsyst10_det_entradas FORMAPAGO on ( sicingr51_cab_bancos.rela_socsyst10_mdp01 = FORMAPAGO.id_socsyst10 )
   inner join socsyst10_det_entradas BANORD on ( sicingr51_cab_bancos.rela_socsyst10_ban01 = BANORD.id_socsyst10 )
   inner join socmain05_det_bancos on ( sicingr51_cab_bancos.rela_socmain05 = socmain05_det_bancos.id_socmain05)
   inner join socsyst10_det_entradas BANBEN on (socmain05_det_bancos.rela_socsyst10_ban01 =  BANBEN.id_socsyst10 )
   where sicpago70_cab_pago.id_sicpago70 = :id_sicpago70x
    into :rela_socmain01,
         :rela_sicingr01,
         :rela_sicingr51,
         :id_sicpago70,
         :pago_serie,
         :pago_folio,
         :pago_moneda,
         :pago_forma, 
         :pago_fecha,
         :pago_tipocambio,
         :pago_monto,
         :pago_numoperacion,
         :pago_rfcordenante,
         :pago_nombreordenante,
         :pago_ctaordenante,
         :pago_rfcbeneficiario,
         :pago_nombrebeneficiario,
         :pago_ctabeneficiario,
         :sicingr51_ctaord;


  Select cfdi_empresa.socmain01_nomcomercial,
         cfdi_empresa.socmain01_nocertificado,
         cfdi_empresa.rfc,
         cfdi_empresa.curp,
         cfdi_empresa.razsocial,
         cfdi_empresa.domf_codpostal,
         '(' || socsyst10_det_entradas.socsyst10_codigo || ') ' || socsyst10_det_entradas.socsyst10_descripcion
    from cfdi_empresa(:rela_socmain01)
   inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = :rela_socmain01)
   inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01 )
    into :emisor_nombrecomercial,
         :emisor_certificado,
         :emisor_rfc,
         :emisor_curp,
         :emisor_nombre,
         :emisor_codpostal,
         :emisor_regimenfiscal;

  Select cbo_sicingr01_id.entidad,
         cbo_sicingr01_id.rfc
    from cbo_sicingr01_id
   where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
    into :receptor_nombre,
         :receptor_rfc;

  select sicpago74_dep_cfdis.sicpago74_uuid,
         sicpago74_dep_cfdis.sicpago74_uuid_fecha,
         sicpago74_dep_cfdis.sicpago74_sello,
         sicpago74_dep_cfdis.sicpago74_sellosat,
         sicpago74_dep_cfdis.sicpago74_cadena,
         sicpago74_dep_cfdis.sicpago74_certificado
    from sicpago74_dep_cfdis
   where sicpago74_dep_cfdis.rela_sicpago70 = :id_sicpago70x
    into :timbre_uuid,
         :timbre_fecha,
         :timbre_sellocfd,
         :timbre_sellosat,
         :timbre_cadena,
         :timbre_certificado;

    /* Seccion de Documentos Relacionados */

    for select
    SICINGR55_DET_FACTURAS.rela_sicingr51,
    SICINGR55_DET_FACTURAS.rela_sicingr70,
    SICINGR55_DET_FACTURAS.sicingr55_importe,
    sicingr70_cab_facturacion.sicingr70_neto,
    (select sicingr74_dep_cfdis.sicingr74_uuid
     from sicingr74_dep_cfdis
     where sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70
    ),
    sicingr70_cab_facturacion.sicingr70_docnro,
    cbo_socsyst10_ctm01.socsyst10_codigo,
    sicingr70_cab_facturacion.sicingr70_cambio,
    cbo_socsyst10_met01.socsyst10_descripcion
    from sicingr70_cab_facturacion
    inner join sicingr55_det_facturas on (sicingr70_cab_facturacion.id_sicingr70 = sicingr55_det_facturas.rela_sicingr70)
    inner join sicingr51_cab_bancos on (sicingr55_det_facturas.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51)
    inner join sicpago70_cab_pago on (sicingr51_cab_bancos.id_sicingr51 = sicpago70_cab_pago.rela_sicingr51)
    inner join cbo_socsyst10_ctm01 on (sicingr70_cab_facturacion.rela_socsyst10_ctm01 = cbo_socsyst10_ctm01.id_socsyst10)
    inner join cbo_socsyst10_met01 on (sicingr70_cab_facturacion.rela_socsyst10_met01 = cbo_socsyst10_met01.id_socsyst10)
    where sicpago70_cab_pago.id_sicpago70 = :id_sicpago70x
    into :rela_sicingr51,
         :id_sicingr70,
         :docrel_importepagado,
         :importe_xml,
         :docrel_uuid,
         :docrel_seriefolio,
         :docrel_moneda,
         :docrel_tipocambio,
         :docrel_metodopago
    do
    begin
        docrel_numparcialidad = 0;
        docrel_saldoanterior = importe_xml;
        docrel_saldoact = 0;

        if (docrel_moneda = 'MXN') then
            docrel_tipocambio = 1.00;
        else
        begin
            if (entrada = 0) then
            begin
                entrada = 1;

                select sum(rep_sicpago70_web.docrel_importepagado)
                from rep_sicpago70_web(:id_sicpago70x, :entrada)
                into :pago_monto;
            end
        end

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (docrel_importepagado <> importe_xml) then
        begin
            select
            count(sicingr55_det_facturas.id_sicingr55),
            sum(sicingr55_det_facturas.sicingr55_importe)
            from sicingr55_det_facturas
            where sicingr55_det_facturas.rela_sicingr70 = :id_sicingr70
            and sicingr55_det_facturas.rela_sicingr51 <> :rela_sicingr51
            into :docrel_numparcialidad,
                 :sumapagos;

            docrel_numparcialidad = docrel_numparcialidad + 1;

            if (sumapagos is null) then
                sumapagos = 0;

            docrel_saldoact = importe_xml - (docrel_importepagado + sumapagos);

            if (sumapagos = 0) then
                docrel_saldoanterior = importe_xml;
            else
                docrel_saldoanterior = importe_xml - sumapagos;
        end

        /* ------------------------------------------------------------------------------------------------------------------------ */
        /* ------------------------------------------------------------------------------------------------------------------------ */

        if (docrel_numparcialidad = 0) then
            docrel_numparcialidad = 1;
        
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE REP_SOCMAIN01_LOGO (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    ID_SOCMAIN03 BIGINT,
    FILE_TIPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FILE_LOGO VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FILE_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    FILE_TIPO_IMAGE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable POSI integer;
declare variable SOCMAIN03_ARCHIVO varchar(400);
declare variable SOCSYST50_WEB integer;
begin
    select socsyst50_cab_config.socsyst50_web
    from socsyst50_cab_config
    into :socsyst50_web;

    if (socsyst50_web = 0) then
    begin
        FOR select
        socmain03_det_upload.id_socmain03,
        socsyst10_det_entradas.socsyst10_codigo,
        socmain03_det_upload.socmain03_uuid ,
        socmain03_det_upload.socmain03_archivo
        from socmain02_det_logos
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain02_det_logos.rela_socsyst10_tdl01 )
        inner join socmain03_det_upload on ( socmain03_det_upload.rela_socmain02 = socmain02_det_logos.id_socmain02 )
        where socmain02_det_logos.rela_socmain01 = :id_socmain01
        into :id_socmain03,
             :file_tipo,
             :file_uuid,
             :socmain03_archivo
        do
        begin
            posi = position('.' in :socmain03_archivo);
            file_tipo_image = trim(upper(SUBSTRING(:socmain03_archivo FROM posi + 1 FOR CHAR_LENGTH (:socmain03_archivo) - posi + 1)));
            FILE_LOGO = 'SOCMAIN03'  || :file_uuid || '.' || :file_tipo_image;
            suspend;
        end
    end
    else
    begin
       for select
       socmain02_det_logos.id_socmain02,
       socsyst10_det_entradas.socsyst10_codigo,
       sysjson02_tbl_files.sysjson02_uuid,
       sysjson02_tbl_files.sysjson02_tipo
       from socmain02_det_logos
       inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socmain02_det_logos.rela_socsyst10_tdl01 )
       inner join sysjson02_tbl_files on ( sysjson02_tbl_files.id_sysjson02 = socmain02_det_logos.rela_sysjson02 )
       where socmain02_det_logos.rela_socmain01 = :id_socmain01
       into :id_socmain03,
            :file_tipo,
            :file_uuid,
            :socmain03_archivo
        do
        begin
            FILE_LOGO = 'SOCMAIN02'  || :file_uuid || '.' || :socmain03_archivo;
            suspend;
        end

    end
end^


CREATE OR ALTER PROCEDURE REP_SOCUSUA30 (
    PARAM_ID INTEGER)
RETURNS (
    SOCSYST10_CODIGO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SOCUSUA30 BIGINT,
    SOCUSUA30_APELLIDO_PAT VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCUSUA30_APELLIDO_MAT VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCUSUA30_NOMBRE_RAZSOC VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_CP VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_CALLE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_NUMEXT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_NUMINT VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_CIUDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_ESTADO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_COLONIA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_RAZONSOCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_RFC VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_DIRECCION VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCSYST10_TDD01 bigint;
declare variable RELA_SOCMAIN80 bigint;
begin

    select first 1
        SOCSYST10_CODIGO,
        ID_SOCUSUA30,
        SOCUSUA30_APELLIDO_PAT,
        SOCUSUA30_APELLIDO_MAT,
        SOCUSUA30_NOMBRE_RAZSOC
    from SOCUSUA30_CAB_ENTIDADES
    inner join socsyst10_det_entradas ON (RELA_SOCSYST10 = ID_SOCSYST10)
    where ID_SOCUSUA30 = :PARAM_ID
    into
        :SOCSYST10_CODIGO,
        :ID_SOCUSUA30,
        :SOCUSUA30_APELLIDO_PAT,
        :SOCUSUA30_APELLIDO_MAT,
        :SOCUSUA30_NOMBRE_RAZSOC;

    if (:SOCSYST10_CODIGO = 'FISICO') then
       ENTIDAD_RAZONSOCIAL = :SOCUSUA30_NOMBRE_RAZSOC || ' ' || :SOCUSUA30_APELLIDO_PAT || ' ' || :SOCUSUA30_APELLIDO_MAT;
    else
       ENTIDAD_RAZONSOCIAL = :SOCUSUA30_NOMBRE_RAZSOC;

    select first 1
           socusua32_det_documentos.socusua32_documento
      from socusua32_det_documentos
     inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
     where socusua32_det_documentos.rela_socusua30 = :PARAM_ID
       and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
      into :ENTIDAD_RFC;

    select first 1
           RELA_SOCSYST10_TDD01,
           RELA_SOCMAIN80,
           TRIM(CAST(SOCUSUA36_CODPOSTAL AS VARCHAR(10))),
           TRIM(SOCUSUA36_CALLE),
           TRIM(SOCUSUA36_NRO),
           TRIM(SOCUSUA36_NROINTERIOR),
           TRIM(SOCUSUA36_CIUDAD),
           TRIM(SOCUSUA36_COLONIA)
      from socusua36_det_domicilios
     where socusua36_det_domicilios.rela_socusua30 = :PARAM_ID
      into :RELA_SOCSYST10_TDD01,
           :RELA_SOCMAIN80,
           :ENTIDAD_CP,
           :ENTIDAD_CALLE,
           :ENTIDAD_NUMEXT,
           :ENTIDAD_NUMINT,
           :ENTIDAD_CIUDAD,
           :ENTIDAD_COLONIA;

    select first 1
            TRIM(SOCMAIN80_D_ASENTA),
            TRIM(SOCMAIN80_D_CIUDAD),
            TRIM(SOCMAIN80_D_ESTADO)
     from socmain80_cab_codpostales
    where socmain80_cab_codpostales.id_socmain80 = :RELA_SOCMAIN80
     into :ENTIDAD_COLONIA,
          :ENTIDAD_CIUDAD,
          :ENTIDAD_ESTADO;

    if (entidad_cp != '' and CHAR_LENGTH (entidad_cp) < 5) then
        entidad_cp = '0' || entidad_cp;

    ENTIDAD_DIRECCION = iif(:entidad_calle is null or :entidad_calle = '' ,'',:entidad_calle || ' ') ||
                        iif(:entidad_numext is null or :entidad_numext = '' ,'','#' || :entidad_numext|| ' ') ||
                        iif(:entidad_numint is null or :entidad_numint = '' ,'',:entidad_numint || ' ') ||
                        iif(:entidad_cp is null or (:entidad_cp = '') ,'','C.P. ' || :entidad_cp || ',') || ' ' ||
                        iif(:entidad_colonia is null or :entidad_colonia = '' ,'',:entidad_colonia || ',') || ' ' ||
                        iif(:entidad_ciudad is null or :entidad_ciudad = '' ,'',:entidad_ciudad || ',') || ' ' ||
                        iif(:entidad_estado is null or :entidad_estado  = '' ,'',:entidad_estado || '.');


    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$_UTIL_FECHA_ADD_HABILES (
    DATE_INI DATE,
    DIAS INTEGER)
RETURNS (
    DIA DATE)
AS
declare variable DATE_ACTUAL date;
declare variable WEEK_DATES integer;
begin
    week_dates = 0;
    date_actual = date_ini;

    while(week_dates < dias) do
    begin
        date_actual = date_actual + 1;

        if (extract(weekday from date_actual) between 1 and 5) then
            week_dates = week_dates + 1;
    end

    dia = date_actual;

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$_UTIL_FECHA_BISIESTO (
    ANO INTEGER)
RETURNS (
    BISIESTO INTEGER,
    DIAS INTEGER)
AS
begin
    bisiesto = 0;
    dias = 28;

    IF ((MOD(ano, 4) = 0 AND MOD(ano, 100) <> 0) OR MOD(ano, 400) = 0) THEN
    begin
        bisiesto = 1;
        dias = 29;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$_UTIL_FECHA_DIFF_HABILES (
    DATE_INI DATE,
    DATE_FIN DATE)
RETURNS (
    DIAS INTEGER)
AS
declare variable DATE_ACTUAL date;
declare variable WEEK_DATE integer;
begin
    date_actual = date_ini;
    week_date = 0;

    while(date_actual < date_fin) DO
    BEGIN
        if (extract(weekday from date_actual) between 1 and 5) then
            week_date = week_date + 1;

        date_actual = date_actual + 1;
    END

    while(date_actual > date_fin) DO
    BEGIN
        if (extract(weekday from date_actual) between 1 and 5) then
            week_date = week_date - 1;

        date_actual = date_actual - 1;
    END

    dias = week_date;

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$DB_CREAR_FKYS (
    EJECUTAR INTEGER)
RETURNS (
    ALIAS VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXISTE_FKY VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SMXSQL_CREAR varchar(8000);
declare variable SMXSQL_BORRAR varchar(8000);
declare variable EXISTE_ID varchar(1000);
declare variable CAMPO_RELA varchar(1000);
declare variable TABLA_RELA varchar(1000);
declare variable ALIAS_RELA varchar(1000);
declare variable VALOR_FIND varchar(1000);
begin
    for select
    trim(smx$db_dicc_tablas_y_campos.alias),
    trim(smx$db_dicc_tablas_y_campos.tablas),
    trim(smx$db_dicc_tablas_y_campos.campos)
    from smx$db_dicc_tablas_y_campos
    where upper(substring(smx$db_dicc_tablas_y_campos.campos from 1 for 5)) = 'RELA_'
    and smx$db_dicc_tablas_y_campos.tablas not like 'TMP_%'
    and smx$db_dicc_tablas_y_campos.tablas <> 'SOCSYST10_DET_REMOTO'
    into :alias,
         :tabla,
         :campo
    do
    begin
        EXISTE_FKY = 'N';
        existe_id = null;
        CAMPO_RELA = trim(substring(campo from 6 for char_length(campo)-5));
        ALIAS_RELA = trim(substring(campo from 6 for 9));

        valor_find = 'FKY_' || :alias || '_' || :CAMPO_RELA;

        if (char_length(valor_find) > 31) then
            valor_find = SUBSTRING (valor_find FROM 1 FOR 31);

        select RDB$INDICES.rdb$index_name
        from RDB$INDICES
        where RDB$INDICES.rdb$index_name = :valor_find
        into :existe_id;

        if (existe_id is not null) then
            EXISTE_FKY = 'S';

        if (EJECUTAR is not null and EXISTE_FKY = 'N') then
        begin
            /*
            if (EXISTE_FKY = 'S') then
            begin
                SMXSQL_BORRAR = 'ALTER TABLE ' || :tabla || ' DROP CONSTRAINT FKY_' || :alias || '_' || :CAMPO_RELA;
                EXECUTE STATEMENT :SMXSQL_BORRAR;
            end
            */

            TABLA_RELA = NULL;
            select first 1 trim(SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas)
            from SMX$DB_DICC_TABLAS_Y_CAMPOS
            where SMX$DB_DICC_TABLAS_Y_CAMPOS.alias = :ALIAS_RELA
            and SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas <> 'SOCSYST10_DET_REMOTO'
            into :TABLA_RELA;

            if (TABLA_RELA IS NOT NULL) then
            BEGIN
                SMXSQL_CREAR = 'ALTER TABLE ' || trim(:tabla) || ' ADD CONSTRAINT FKY_' || trim(:alias) ||
                                '_' || :CAMPO_RELA ||
                                ' FOREIGN KEY (' || trim(:campo) || ')' ||
                                ' REFERENCES ' || :TABLA_RELA || '(ID_' || :ALIAS_RELA || ')';

                EXECUTE STATEMENT :SMXSQL_CREAR;
            END
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_CREAR_PKYS (
    EJECUTAR INTEGER)
RETURNS (
    ALIAS VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXISTE_PKY VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SMXSQL_CREAR varchar(8000);
declare variable SMXSQL_BORRAR varchar(8000);
declare variable EXISTE_ID varchar(1000);
begin
    for select
    smx$db_dicc_tablas_y_campos.alias,
    smx$db_dicc_tablas_y_campos.tablas,
    smx$db_dicc_tablas_y_campos.campos
    from smx$db_dicc_tablas_y_campos
    where upper(substring(smx$db_dicc_tablas_y_campos.campos from 1 for 3)) = 'ID_'
    and smx$db_dicc_tablas_y_campos.tablas not like 'TMP_%'
    and smx$db_dicc_tablas_y_campos.tablas not like 'SOCSYST10_DET_REMOTO%'
    into :alias,
         :tabla,
         :campo
    do
    begin
        existe_pky = 'N';
        existe_id = null;

        select RDB$INDICES.rdb$index_name
        from RDB$INDICES
        where RDB$INDICES.rdb$index_name = 'PKY_' || :alias
        into :existe_id;

        if (existe_id is not null) then
            existe_pky = 'S';
        else
            existe_pky = 'N';

        if (EJECUTAR is not null) then
        begin
            /*
            if (existe_pky = 'S') then
            begin
                SMXSQL_BORRAR = 'ALTER TABLE ' || :tabla || ' DROP CONSTRAINT PKY_' || alias;
                EXECUTE STATEMENT :SMXSQL_BORRAR;
            end
            */
            if (existe_pky = 'N') then
            begin
                SMXSQL_CREAR = 'ALTER TABLE ' || :tabla ||
                           ' ADD CONSTRAINT PKY_' || :alias ||
                           ' PRIMARY KEY (ID_' || :alias || ')';


                EXECUTE STATEMENT :SMXSQL_CREAR;
            end
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_CREAR_SEQS (
    EJECUTAR INTEGER)
RETURNS (
    ALIAS VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXISTE_SID VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    IDACTUAL INTEGER,
    IDMAX INTEGER)
AS
declare variable SMXSQL_CREAR varchar(8000);
declare variable SMXSQL_RECREAR varchar(8000);
declare variable EXISTE_ID varchar(1000);
declare variable SMXSQL_MAXIDS varchar(8000);
begin
    for select
    smx$db_dicc_tablas_y_campos.alias,
    smx$db_dicc_tablas_y_campos.tablas,
    smx$db_dicc_tablas_y_campos.campos
    from smx$db_dicc_tablas_y_campos
    where smx$db_dicc_tablas_y_campos.tablas != 'SOCSYST10_DET_REMOTO'
    and smx$db_dicc_tablas_y_campos.campos LIKE 'ID_%'
    and smx$db_dicc_tablas_y_campos.tablas not LIKE 'TMP%'
    into :alias,
         :tabla,
         :campo
    do
    begin
        idmax = 0;
        idactual = 0;
        existe_id = null;
        existe_sid = '';

        select rdb$generator_name
        from rdb$generators
        where rdb$generators.rdb$generator_name = 'S' || :campo
        into :existe_id;

        if (existe_id is not null) then
        BEGIN
            existe_sid = 'S';

            SMXSQL_MAXIDS = 'Select max(' || :campo || ') from ' || :tabla;
            EXECUTE STATEMENT :SMXSQL_MAXIDS into :idmax;
    
            idmax = iif(idmax is null, 0, idmax);
    
            SMXSQL_MAXIDS = 'SELECT GEN_ID(S' || :campo || ', 0) AS valor_actual FROM rdb$database';
            EXECUTE STATEMENT :SMXSQL_MAXIDS into :idactual;

            if (idactual < idmax and EJECUTAR = 1) then
            begin
                SMXSQL_RECREAR = 'SET GENERATOR S' || :campo || ' TO ' || (idmax+1);
                EXECUTE STATEMENT :SMXSQL_RECREAR;
            end
        END
        else
        begin
            existe_sid = 'N';

            if (EJECUTAR = 1) then
            BEGIN
                SMXSQL_CREAR = 'CREATE SEQUENCE S' || :campo;
                EXECUTE STATEMENT :SMXSQL_CREAR;
            END
        end

        if (idactual < idmax or existe_sid = 'N') then
            suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_CREAR_TRGS (
    EJECUTAR INTEGER)
RETURNS (
    ALIAS VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXISTE_TRG VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SMXSQL_CREAR varchar(8000);
declare variable SMXSQL_BORRAR varchar(8000);
declare variable EXISTE_ID varchar(1000);
declare variable SOURCE blob sub_type 1 segment size 80;
begin
    for select
    trim(smx$db_dicc_tablas_y_campos.alias),
    trim(smx$db_dicc_tablas_y_campos.tablas),
    trim(smx$db_dicc_tablas_y_campos.campos)
    from smx$db_dicc_tablas_y_campos
    where upper(substring(smx$db_dicc_tablas_y_campos.campos from 1 for 3)) = 'ID_'
    and smx$db_dicc_tablas_y_campos.tablas not like 'TMP_%'
    and smx$db_dicc_tablas_y_campos.tablas not like 'SOCSYST10_DET_REMOTO%'
    into :alias,
         :tabla,
         :campo
    do
    begin
        EXISTE_TRG = 'N';
        existe_id = null;

        select RDB$TRIGGERS.rdb$trigger_name, RDB$TRIGGERS.rdb$trigger_source
        from RDB$TRIGGERS
        where RDB$TRIGGERS.rdb$trigger_name = 'TID_' || :alias
        INTO :existe_id, :SOURCE;

        if (existe_id is not null) then
            EXISTE_TRG = 'S';

        if (EJECUTAR is not null) then
        begin
           if (EXISTE_TRG = 'S') then
           begin
           /*
              SMXSQL_BORRAR = 'DROP TRIGGER TID_' || :ALIAS;
              EXECUTE STATEMENT :SMXSQL_BORRAR;

              SMXSQL_CREAR = 'CREATE TRIGGER TID_' || :alias || ' for ' || :tabla ||
                             ' active before insert or update or delete position 0 ' || :SOURCE;
              EXECUTE STATEMENT :SMXSQL_CREAR;
           */
           end
           else
           begin
              SMXSQL_CREAR = 'CREATE TRIGGER TID_' || :alias || ' for ' || :tabla ||
                             ' active before insert or update or delete position 0 ' ||
                             'AS ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
                             'DECLARE VARIABLE cTipo CHAR(1); ' || ASCII_CHAR(13) ||
                             'DECLARE VARIABLE nID BIGINT; ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
                             'BEGIN ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'IF (INSERTING) THEN ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'BEGIN ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || 'NEW.ID_' || :alias || ' = GEN_ID(SID_' || :alias || ',1); ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || 'cTipo = ''A''; ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) ||  'nID = NEW.ID_' || :alias || '; ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'END ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'ELSE IF (UPDATING) THEN ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'BEGIN ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || 'cTipo = ''M''; ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) ||  'nID = OLD.ID_' || :alias || '; ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'END ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'ELSE ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) ||  'BEGIN ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || 'cTipo = ''B''; ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || 'nID = OLD.ID_' || :alias || '; ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'END ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || 'EXECUTE PROCEDURE smx$db_util_logs ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || ASCII_CHAR(9) || 'CURRENT_USER, ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || ASCII_CHAR(9) || ':cTipo, ' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || ASCII_CHAR(9) ||  '''' || :alias || ''',' || ASCII_CHAR(13) ||
                             ASCII_CHAR(9) || ASCII_CHAR(9) || ASCII_CHAR(9) || ':nID; ' || ASCII_CHAR(13) ||
                             'END ';

           EXECUTE STATEMENT :SMXSQL_CREAR;
           end
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_DELETE_FKYS (
    EJECUTAR INTEGER)
RETURNS (
    ALIAS VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(100) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EXISTE_FKY VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable EXISTE_ID varchar(500);
declare variable CAMPO_RELA varchar(100);
declare variable SMXSQL_BORRAR varchar(8000);
begin
    for select
    trim(smx$db_dicc_tablas_y_campos.alias),
    trim(smx$db_dicc_tablas_y_campos.tablas),
    trim(smx$db_dicc_tablas_y_campos.campos)
    from smx$db_dicc_tablas_y_campos
    where upper(substring(smx$db_dicc_tablas_y_campos.campos from 1 for 5)) = 'RELA_'
    into :alias,
         :tabla,
         :campo
    do
    begin
        EXISTE_FKY = 'N';
        existe_id = null;
        CAMPO_RELA = trim(substring(campo from 6 for char_length(campo)-5));

        select RDB$INDICES.rdb$index_name
        from RDB$INDICES
        where RDB$INDICES.rdb$index_name = 'FKY_' || :alias || '_' || :CAMPO_RELA
        into :existe_id;

        if (existe_id is not null) then
            EXISTE_FKY = 'S';

        if (EJECUTAR is not null AND EXISTE_FKY = 'S') then
        begin
            if (EXISTE_FKY = 'S') then
            begin
                SMXSQL_BORRAR = 'ALTER TABLE ' || :tabla || ' DROP CONSTRAINT FKY_' || :alias || '_' || :CAMPO_RELA;
                EXECUTE STATEMENT :SMXSQL_BORRAR;
            end
        end

        suspend;
    end
end^


