CREATE OR ALTER PROCEDURE SMX$DB_FECHA_ALTA_DIFF (
    ALIAS_DESDE VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ALIAS_HASTA VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_DESDE BIGINT,
    ID_HASTA BIGINT)
RETURNS (
    DIAS INTEGER,
    FECHA_DESDE TIMESTAMP,
    FECHA_HASTA TIMESTAMP,
    USUARIO_DESDE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO_HASTA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    select
    max(socsyst90_mov_logs.socsyst90_fapl),
    max(socsyst90_mov_logs.socsyst90_usuario)
    from socsyst90_mov_logs
    where socsyst90_mov_logs.socsyst90_tabla = :alias_desde
    and socsyst90_mov_logs.socsyst90_accion = 'A'
    and socsyst90_mov_logs.socsyst90_ultid = :id_desde
    into :fecha_desde,
         :usuario_desde;

    usuario_desde = substring(usuario_desde from 6);

    select
    max(socsyst90_mov_logs.socsyst90_fapl),
    max(socsyst90_mov_logs.socsyst90_usuario)
    from socsyst90_mov_logs
    where socsyst90_mov_logs.socsyst90_tabla = :alias_hasta
    and socsyst90_mov_logs.socsyst90_accion = 'A'
    and socsyst90_mov_logs.socsyst90_ultid = :id_hasta
    into :fecha_hasta,
         :usuario_hasta;

    usuario_hasta = substring(usuario_hasta from 6);

    dias = DATEDIFF(day, :fecha_desde, :fecha_hasta);
    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$DB_LOGS_ESTADISTICAS
RETURNS (
    SOCSYST90_USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOT_ACCIONES INTEGER,
    TOT_ALTAS INTEGER,
    TOT_BAJAS INTEGER,
    TOT_MODI INTEGER,
    TOT_LOGON INTEGER,
    TOT_PRINTER INTEGER,
    MAX_FECHA DATE)
AS
begin
    FOR SELECT
    socsyst90_mov_logs.socsyst90_usuario,
    count(socsyst90_mov_logs.id_socsyst90),
    max(socsyst90_mov_logs.socsyst90_fapl)
    FROM socsyst90_mov_logs
    group by socsyst90_mov_logs.socsyst90_usuario
    into :socsyst90_usuario,
         :tot_acciones,
         :max_fecha
    do
    begin
        select
        count(socsyst90_mov_logs.id_socsyst90)
        from socsyst90_mov_logs
        where socsyst90_mov_logs.socsyst90_usuario = :socsyst90_usuario
        and socsyst90_mov_logs.socsyst90_accion = 'A'
        INTO :TOT_ALTAS;

        select
        count(socsyst90_mov_logs.id_socsyst90)
        from socsyst90_mov_logs
        where socsyst90_mov_logs.socsyst90_usuario = :socsyst90_usuario
        and socsyst90_mov_logs.socsyst90_accion = 'B'
        INTO :TOT_BAJAS;

        select
        count(socsyst90_mov_logs.id_socsyst90)
        from socsyst90_mov_logs
        where socsyst90_mov_logs.socsyst90_usuario = :socsyst90_usuario
        and socsyst90_mov_logs.socsyst90_accion = 'M'
        INTO :TOT_MODI;

        select
        count(socsyst90_mov_logs.id_socsyst90)
        from socsyst90_mov_logs
        where socsyst90_mov_logs.socsyst90_usuario = :socsyst90_usuario
        and socsyst90_mov_logs.socsyst90_accion = 'L'
        INTO :TOT_LOGON;

        select
        count(socsyst90_mov_logs.id_socsyst90)
        from socsyst90_mov_logs
        where socsyst90_mov_logs.socsyst90_usuario = :socsyst90_usuario
        and socsyst90_mov_logs.socsyst90_accion = 'P'
        INTO :TOT_PRINTER;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_RECREA_SEQS
RETURNS (
    ALIAS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    "SEQUENCE" VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MAX_SEQS INTEGER,
    MAX_SEQS_VACIOS INTEGER)
AS
declare variable SMXSQL varchar(400);
begin
    for select
    smx$db_dicc_tablas_y_campos.alias,
    smx$db_dicc_tablas_y_campos.tablas,
    smx$db_dicc_tablas_y_campos.campos
    from smx$db_dicc_tablas_y_campos
    where upper(substring(smx$db_dicc_tablas_y_campos.campos from 1 for 3)) = 'ID_'
    AND upper(substring(smx$db_dicc_tablas_y_campos.alias from 1 for 4)) <> 'TMP_'
    into :alias,
         :tabla,
         :campo
    do
    begin
        select rdb$generator_name
        from rdb$generators
        where rdb$generators.rdb$generator_name = 'SID_' || :alias
        into :sequence;

        max_seqs = 0;
        execute statement
        'SELECT max(' || 'ID_' || :alias || ') FROM ' || :tabla
        into :max_seqs;

        if (max_seqs IS NULL) then
            max_seqs = 0;

        max_seqs_vacios = 0;
        execute statement
        'SELECT count(' || 'ID_' || :alias || ') FROM ' || :tabla
        into :max_seqs_vacios;

        if (max_seqs_vacios IS NULL) then
            max_seqs = 0;

        SMXSQL = 'ALTER SEQUENCE ' || :sequence || ' RESTART WITH ' || max_seqs;
        EXECUTE STATEMENT :SMXSQL;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_SOCSYST10_UNIVERSAL (
    VISTA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCSYST10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VE VARCHAR(460) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST09 varchar(400);
declare variable ID_SOCSYST09 bigint;
declare variable SOCSYST10 varchar(400);
begin
    vista = trim(upper(:vista));
    ID_SOCSYST09 = 0;
    SOCSYST09 = 'SELECT ID_SOCSYST09 FROM SOCSYST09_CAB_ENTRADAS WHERE TRIM(UPPER(SOCSYST09_CODIGO)) = ''' || :vista || '''';

    execute statement :SOCSYST09
    on external 'SMXSEG'
    AS USER 'SYSDBA' PASSWORD 'masterkey'
    into :ID_SOCSYST09;

    if (id_socsyst09 <> 0) then
    begin
        socsyst10 = 'SELECT * FROM ' || :VISTA;
        for execute statement :socsyst10
        on external 'SMXSEG'
        AS USER 'SYSDBA' PASSWORD 'masterkey'
        into :ID_SOCSYST10,
             :SOCSYST10_CODIGO,
             :SOCSYST10_DESCRIPCION,
             :ve
        DO
        BEGIN
            suspend;
        END
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_TABLE_FIND (
    TABLE_NAME VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ENCONTRO INTEGER)
AS
declare variable TABLE_FIND varchar(40);
begin
    SELECT
    RDB$RELATION_NAME FROM RDB$RELATIONS
    WHERE (RDB$SYSTEM_FLAG <> 1 OR RDB$SYSTEM_FLAG IS NULL) AND RDB$VIEW_BLR IS NULL
    and UPPER(RDB$RELATION_NAME) = UPPER(:table_name)
    INTO :table_find;

    if (table_find is null) then
        encontro = 0;
    else
        encontro = 1;

    SUSPEND;
end^


CREATE OR ALTER PROCEDURE SMX$DB_TABLE_FIND_ALIAS (
    ALIAS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SMXDATA01 BIGINT,
    TABLAS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CAMPO_ID varchar(400);
begin
    id_smxdata01 = 0;
    campo_id = 'ID_' || upper(trim(alias));

    for Select
    SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas
    from SMX$DB_DICC_TABLAS_Y_CAMPOS
    where ALIAS = :alias and CAMPOS = :campo_id and not SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas LIKE '%REMOTO%'
    into :tablas
    do
    begin
        id_smxdata01 = id_smxdata01 + 1;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$DB_TRIGGERS (
    FLAG INTEGER)
RETURNS (
    TRIGGER_NAME VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SMXTRIGGER varchar(400);
begin
    FOR select RDB$TRIGGERS.rdb$trigger_name
    from RDB$TRIGGERS
    where RDB$TRIGGERS.rdb$trigger_name like 'TID_%'
    INTO :TRIGGER_NAME
    DO
    BEGIN
        if (FLAG = 0) then
            SMXTRIGGER = 'alter trigger ' || :TRIGGER_NAME  || 'inactive';
        else
            SMXTRIGGER = 'alter trigger ' || :TRIGGER_NAME  || 'active';
        EXECUTE STATEMENT :SMXTRIGGER;
        suspend;
     END
end^


CREATE OR ALTER PROCEDURE SMX$DB_UTIL_LOGS (
    CUSUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CTIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CTABLA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NULTID BIGINT)
AS
declare variable NEXISTE bigint;
begin
    INSERT INTO socsyst90_mov_logs
    (socsyst90_USUARIO,
    socsyst90_ACCION,
    SOCSYST90_TABLA,
    socsyst90_ULTID)
    VALUES(:CUSUARIO, :CTIPO, :CTABLA, :NULTID);

    SELECT count(*) FROM SOCSYST91_TBL_ULTIDS
    WHERE SOCSYST91_TBL_ULTIDS.SOCSYST91_USUARIO =:CUSUARIO
    AND SOCSYST91_TBL_ULTIDS.socsyst91_ulttbl = :CTABLA
    INTO :NEXISTE;

    if (NEXISTE =0) then
      begin
        INSERT INTO SOCSYST91_TBL_ULTIDS
        (SOCSYST91_USUARIO, SOCSYST91_ULTID, SOCSYST91_ULTTBL)
        VALUES(:CUSUARIO, :NULTID, :CTABLA);
      end
    else
      begin
        UPDATE SOCSYST91_TBL_ULTIDS
        SET SOCSYST91_ULTID = :NULTID,
            socsyst91_ulttbl = :CTABLA,
            SOCSYST91_FAPL = current_timestamp
        WHERE SOCSYST91_USUARIO=:CUSUARIO
        AND socsyst91_ulttbl = :CTABLA;
      end
end^


CREATE OR ALTER PROCEDURE SMX$SICCONT11_CORRECCION (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    RELA_SICCONT11 BIGINT,
    ID_SICCONT10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_DOCNRO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICCONT10_FCTA DATE,
    SUMA_DEBE DOUBLE PRECISION,
    SUMA_HABER DOUBLE PRECISION,
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ISENTRO integer;
begin
    isEntro = 0;

    for select
    siccont11_det_polizas.id_siccont11,
    siccont10_cab_polizas.id_siccont10,
    socsyst10_det_entradas.socsyst10_codigo,
    siccont10_cab_polizas.siccont10_docnro,
    siccont10_cab_polizas.siccont10_fcta
    from siccont10_cab_polizas
    inner join siccont11_det_polizas on ( siccont11_det_polizas.rela_siccont10 = siccont10_cab_polizas.id_siccont10 )
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
    where siccont11_det_polizas.siccont11_debe <> 0 and siccont11_det_polizas.siccont11_haber <> 0
    and siccont10_cab_polizas.rela_socmain01 = :id_socmain01
    group by siccont11_det_polizas.id_siccont11,
             siccont10_cab_polizas.id_siccont10,
             socsyst10_det_entradas.socsyst10_codigo,
             siccont10_cab_polizas.siccont10_docnro,
             siccont10_cab_polizas.siccont10_fcta
    into :rela_siccont11,
         :id_siccont10,
         :socsyst10_codigo,
         :siccont10_docnro,
         :siccont10_fcta
    do
    begin
        isEntro = 1;

        select
        sum(siccont11_det_polizas.siccont11_debe),
        sum(siccont11_det_polizas.siccont11_haber)
        from siccont11_det_polizas
        where siccont11_det_polizas.rela_siccont10 = :id_siccont10
        into :suma_debe,
             :suma_haber;

        if (suma_debe > suma_haber) then
            update siccont11_det_polizas set siccont11_det_polizas.siccont11_debe = 0
            where siccont11_det_polizas.id_siccont11 = :rela_siccont11;
        else
            update siccont11_det_polizas set siccont11_det_polizas.siccont11_haber = 0
            where siccont11_det_polizas.id_siccont11 = :rela_siccont11;

        select
        sum(siccont11_det_polizas.siccont11_debe),
        sum(siccont11_det_polizas.siccont11_haber)
        from siccont11_det_polizas
        where siccont11_det_polizas.rela_siccont10 = :id_siccont10
        into :suma_debe,
             :suma_haber;

        if (cast(suma_debe as numeric(18,4)) = cast(suma_haber as numeric(18,4))) then
            status = 'OK';
        else
            status = 'Diferencia : ' || cast( cast(suma_debe as numeric(18,4)) -
                                              cast(suma_haber as numeric(18,4)) as Varchar(50));
        suspend;
    end

    if (isEntro = 0) then
    begin
        for select
        siccont10_cab_polizas.id_siccont10,
        socsyst10_det_entradas.socsyst10_codigo,
        siccont10_cab_polizas.siccont10_docnro,
        siccont10_cab_polizas.siccont10_fcta
        from siccont11_det_polizas
        inner join siccont10_cab_polizas on ( siccont10_cab_polizas.id_siccont10 = siccont11_det_polizas.rela_siccont10 )
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
        where siccont10_cab_polizas.rela_socmain01 = :id_socmain01
        group by siccont10_cab_polizas.id_siccont10,
                 socsyst10_det_entradas.socsyst10_codigo,
                 siccont10_cab_polizas.siccont10_docnro,
                 siccont10_cab_polizas.siccont10_fcta
        having cast(sum(siccont11_det_polizas.siccont11_debe) as numeric(18,3)) <>
               cast(sum(siccont11_det_polizas.siccont11_haber) as numeric(18,3))
        into :id_siccont10,
             :socsyst10_codigo,
             :siccont10_docnro,
             :siccont10_fcta
        do
        begin
             status = 'Correccion a Mano';
             suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_ACTUALIZA_INSTANCIA (
    INSTANCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable NADA integer;
declare variable ID_SOCSYST10_CTM01 bigint;
declare variable ID_SOCSYST50 bigint;
declare variable ID_SICEGRE51 bigint;
declare variable ID_SICINGR51 bigint;
declare variable RELA_SICCONT10 bigint;
begin
    delete from SOCSYST90_MOV_LOGS;
    EXECUTE STATEMENT 'ALTER SEQUENCE SID_SOCSYST90 RESTART WITH 0';

    /* ------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------ */

    FOR SELECT sicegre51_cab_bancos.id_sicegre51
    FROM sicegre51_cab_bancos
    WHERE sicegre51_cab_bancos.sicegre51_importe <> 0
    AND NOT EXISTS ( SELECT FIRST 1 sicegre50_det_ctacte.id_sicegre50
                       FROM sicegre50_det_ctacte
                       WHERE sicegre50_det_ctacte.rela_sicegre51 =  sicegre51_cab_bancos.id_sicegre51)
    INTO :id_sicegre51
    DO
    BEGIN
        DELETE FROM sicegre51_cab_bancos WHERE sicegre51_cab_bancos.id_sicegre51 = :id_sicegre51;
    END

    /* ------------------------------------------------------------------------------------------------------------ */

    FOR SELECT sicegre51_cab_bancos.id_sicegre51
    FROM sicegre51_cab_bancos
    WHERE NOT EXISTS ( select first 1 sicegre52_det_bancos.id_sicegre52
                       from sicegre52_det_bancos
                       where sicegre52_det_bancos.rela_sicegre51 = sicegre51_cab_bancos.id_sicegre51
                      )
    INTO :id_sicegre51
    do
    BEGIN
        rela_siccont10 = null;

        select sicegre50_det_ctacte.rela_siccont10
        from sicegre50_det_ctacte
        where sicegre50_det_ctacte.rela_sicegre51 = :id_sicegre51
        into :rela_siccont10;

        if (rela_siccont10 is not null) then
            delete from siccont10_cab_polizas where siccont10_cab_polizas.id_siccont10 = :rela_siccont10;

        delete from sicegre51_cab_bancos where sicegre51_cab_bancos.id_sicegre51 = :id_sicegre51;
    END

    /* ------------------------------------------------------------------------------------------------------------ */

    FOR SELECT sicingr51_cab_bancos.id_sicingr51
    FROM sicingr51_cab_bancos
    WHERE sicingr51_cab_bancos.sicingr51_importe <> 0
    and sicingr51_cab_bancos.sicingr51_anticipo = 0
    AND NOT EXISTS ( SELECT FIRST 1 sicingr50_det_ctacte.id_sicingr50
                       FROM sicingr50_det_ctacte
                       WHERE sicingr50_det_ctacte.rela_sicingr51 =  sicingr51_cab_bancos.id_sicingr51)
    INTO :id_sicingr51
    DO
    BEGIN
        DELETE FROM sicingr51_cab_bancos WHERE sicingr51_cab_bancos.id_sicingr51 = :id_sicingr51;
    END

    /* ------------------------------------------------------------------------------------------------------------ */

    FOR SELECT
    sicingr51_cab_bancos.id_sicingr51
    FROM sicingr51_cab_bancos
    where CAST(sicingr51_cab_bancos.sicingr51_importe AS NUMERIC(15,3)) <>
    CAST((SELECT SUM(sicingr52_det_bancos.sicingr52_importe)
     FROM sicingr52_det_bancos
     WHERE sicingr52_det_bancos.rela_sicingr51 = sicingr51_cab_bancos.id_sicingr51
    ) AS NUMERIC(15,3))
    INTO :id_sicegre51
    DO
    BEGIN
        for select sicingr50_det_ctacte.rela_siccont10
        from sicingr50_det_ctacte
        where sicingr50_det_ctacte.rela_sicingr51 = :id_sicegre51
        into :rela_siccont10
        do
        begin
            delete from siccont10_cab_polizas where siccont10_cab_polizas.id_siccont10 = :rela_siccont10;
        end

        delete from sicingr51_cab_bancos where sicingr51_cab_bancos.id_sicingr51 = :id_sicegre51;
    END

    /*
    SELECT siccont10_cab_polizas.*
    FROM siccont10_cab_polizas
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
    where socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-BANCOS'
    and not exists (select sicegre50_det_ctacte.id_sicegre50
                    from sicegre50_det_ctacte
                    where sicegre50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10 )
    
    
    SELECT siccont10_cab_polizas.*
    FROM siccont10_cab_polizas
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
    where socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-BANCOS-CLIENTE'
    and not exists (select sicingr50_det_ctacte.id_sicingr50
                    from  sicingr50_det_ctacte
                    where  sicingr50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10 )
    
    SELECT siccont10_cab_polizas.*
    FROM siccont10_cab_polizas
    inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = siccont10_cab_polizas.rela_socsyst10_ctp01 )
    where socsyst10_det_entradas.socsyst10_codigo = 'DROPZONE-BANCOS-NOMI'
    and not exists (select sicnomi50_det_ctacte.id_sicnomi50
                    from  sicnomi50_det_ctacte
                    where  sicnomi50_det_ctacte.rela_siccont10 = siccont10_cab_polizas.id_siccont10 )

    */

    /* ------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------ */
    /* ------------------------------------------------------------------------------------------------------------ */

    id_socsyst50 = null;

    select first 1 socsyst50_cab_config.id_socsyst50
    from socsyst50_cab_config
    into :id_socsyst50;

    if (id_socsyst50 is null) then
    begin
        insert into socsyst50_cab_config( socsyst50_cab_config.socsyst50_pymvent71,
                                          socsyst50_cab_config.socsyst50_instancia,
                                          socsyst50_cab_config.socsyst50_sicingr89,
                                          socsyst50_cab_config.socsyst50_monedas )
                                          values( 0,
                                                  :instancia,
                                                  0,
                                                  0 );
    end

    /* ---------------------------------------------------------------------- */

    /*
    SELECT COUNT(smx$soc_corrige_sicxmls41_1.id_sicxmls41)
    FROM smx$soc_corrige_sicxmls41_1
    INTO :nada;

    SELECT COUNT(smx$soc_corrige_sicxmls41_2.id_sicxmls41)
    FROM smx$soc_corrige_sicxmls41_2
    INTO :nada;
    */

    /* ---------------------------------------------------------------------- */

    SELECT CBO_SOCSYST10_CTM01W.id_socsyst10
    FROM CBO_SOCSYST10_CTM01W
    WHERE CBO_SOCSYST10_CTM01W.socsyst10_codigo = 'MXN'
    INTO :id_socsyst10_ctm01;

    update aductag01_cab_ctagastos set aductag01_cab_ctagastos.rela_socsyst10_ctm01 = :id_socsyst10_ctm01
    where aductag01_cab_ctagastos.rela_socsyst10_ctm01 is null;

    /* ---------------------------------------------------------------------- */

    delete from tmp_siccont01_siccont02;

    delete from TMP_SICCONT11_BALANCE;
    
    delete from tmp_siccont11_balanza;
    
    delete from tmp_siccont11_balanza_balance;
    
    delete from tmp_siccont11_balanza_fisanual;
    
    delete from tmp_siccont11_balanza_fiscal;
    
    delete from tmp_siccont11_resultado;

    delete from tmp_sicnomi73;

    delete from tmp_socusua30_sicxmls41;

    /* ---------------------------------------------------------------------- */

    delete from tmpingr95_tbl_replicacion;
    EXECUTE STATEMENT 'ALTER SEQUENCE SID_TMPINGR95 RESTART WITH 0';

    /* ---------------------------------------------------------------------- */

    select count(*) from smx$soc_copia_socsyst10 into :nada;

    select count(*) from smx$soc_copia_socsyst01 into :nada;

    select count(*) from smx$soc_copia_socsyst02 into :nada;

    select count(*) from smx$soc_copia_socsyst13 into :nada;

    /* ---------------------------------------------------------------------- */

    delete from SOCSYST90_MOV_LOGS;
    EXECUTE STATEMENT 'ALTER SEQUENCE SID_SOCSYST90 RESTART WITH 0';

    /* --------------------------------------------------------------------------------------------------------------*/
end^


CREATE OR ALTER PROCEDURE SMX$SOC_ARBOLES (
    RELA_CAB BIGINT,
    ALIAS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_ARB BIGINT)
RETURNS (
    RELA_SOCSYST06 BIGINT,
    CODIGO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable LOGNIVEL integer;
declare variable RELAPADRE bigint;
declare variable LEN_MASCARA integer;
begin
    if (rela_arb is null) then
    begin
        select
        socsyst06_det_niveles.id_socsyst06,
        CHAR_LENGTH(socsyst06_det_niveles.socsyst06_mascara)
        FROM socsyst05_cab_arboles
        inner join socsyst06_det_niveles on (socsyst06_det_niveles.rela_socsyst05 = socsyst05_cab_arboles.id_socsyst05)
        WHERE socsyst05_cab_arboles.socsyst05_codigo = :alias
        and socsyst06_det_niveles.socsyst06_nivel = 1
        into :rela_socsyst06,
             :LEN_MASCARA;
    end
    else
    begin
        logNivel = 1;
        relaPadre = :rela_arb;
        while((:relaPadre is not null) or (logNivel > 20) ) do
        begin
            logNivel = logNivel + 1;

            if (alias = 'SICCONT02') then
                SELECT siccont02_arb_planctas.rela_siccont02
                FROM siccont02_arb_planctas
                WHERE siccont02_arb_planctas.id_siccont02 = :relaPadre
                INTO :relaPadre;

            else if (alias = 'SOCMAIN21') then
                SELECT socmain21_arb_organizacion.rela_socmain21
                FROM socmain21_arb_organizacion
                WHERE socmain21_arb_organizacion.id_socmain21 = :relaPadre
                INTO :relaPadre;

           else if (alias = 'SOCUSUA11') then
                SELECT socusua11_arb_menu.rela_socusua11
                FROM socusua11_arb_menu
                WHERE socusua11_arb_menu.id_socusua11 = :relaPadre
                INTO :relaPadre;
        end

        select
        socsyst06_det_niveles.id_socsyst06,
        CHAR_LENGTH(socsyst06_det_niveles.socsyst06_mascara)
        FROM socsyst05_cab_arboles
        inner join socsyst06_det_niveles on (socsyst06_det_niveles.rela_socsyst05 = socsyst05_cab_arboles.id_socsyst05)
        WHERE socsyst05_cab_arboles.socsyst05_codigo = :alias
        and socsyst06_det_niveles.socsyst06_nivel = :logNivel
        into rela_socsyst06,
             :LEN_MASCARA;
    end

    if (alias = 'SICCONT02') then
        execute procedure smx$soc_arboles_siccont02 :rela_cab,
                                                    :rela_arb,
                                                    :LEN_MASCARA
        returning_values codigo;
    else if (alias = 'SOCMAIN21') then
        execute procedure smx$soc_arboles_socmain21 :rela_cab,
                                                    :rela_arb,
                                                    :LEN_MASCARA
        returning_values codigo;

    else if (alias = 'SOCUSUA11') then
        execute procedure smx$soc_arboles_socusua11 :rela_cab,
                                                    :rela_arb,
                                                    :LEN_MASCARA
        returning_values codigo;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_ARBOLES_SICCONT02 (
    RELA_CAB BIGINT,
    RELA_ARB BIGINT,
    LEN_MASCARA INTEGER)
RETURNS (
    CODIGO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CODIGO_TMP varchar(1000);
declare variable CODIGO_NUM integer;
declare variable CODIGO_PADRE varchar(1000);
begin
    CODIGO_TMP = null;

    if (rela_arb is null) then
    begin
        select max(siccont02_arb_planctas.siccont02_codigo)
        from siccont02_arb_planctas
        where siccont02_arb_planctas.rela_siccont01 = :rela_cab
        and siccont02_arb_planctas.rela_siccont02 is null
        into :CODIGO_TMP;

        if (CODIGO_TMP is null) then
            CODIGO_TMP = '0';

        CODIGO_NUM = CAST(CODIGO_TMP AS INTEGER);
        CODIGO_NUM = CODIGO_NUM + 10;
        CODIGO_TMP = CAST(CODIGO_NUM AS VARCHAR(1000));
        CODIGO = lpad (CODIGO_TMP, :LEN_MASCARA, '0');
    end
    else
    begin
        select siccont02_arb_planctas.siccont02_codigo
        from siccont02_arb_planctas
        where siccont02_arb_planctas.rela_siccont01 = :rela_cab
        and siccont02_arb_planctas.id_siccont02 = :rela_arb
        into :CODIGO_PADRE;

        select max(siccont02_arb_planctas.siccont02_codigo)
        from siccont02_arb_planctas
        where siccont02_arb_planctas.rela_siccont01 = :rela_cab
        and siccont02_arb_planctas.rela_siccont02 = :rela_arb
        into :CODIGO_TMP;

        if (CODIGO_TMP is null) then
            CODIGO_TMP = '0';
        else
            CODIGO_TMP = right(CODIGO_TMP, LEN_MASCARA);

        CODIGO_NUM = CAST(CODIGO_TMP AS INTEGER);
        CODIGO_NUM = CODIGO_NUM + 10;
        CODIGO_TMP = CAST(CODIGO_NUM AS VARCHAR(1000));
        CODIGO = lpad (CODIGO_TMP, :LEN_MASCARA, '0');
        CODIGO = codigo_padre || '.' || CODIGO;
    end
end^


