CREATE OR ALTER PROCEDURE SMX$SOC_BORRACONTABILIDAD (
    RELA_SOCMAIN01 BIGINT,
    TODOS_MENOS INTEGER)
AS
begin
    if (todos_menos = 0) then
    begin
        delete from SICCONT50_CAB_BANCOS where SICCONT50_CAB_BANCOS.rela_socmain01 = :rela_socmain01;
    
        delete from sicegre51_cab_bancos where sicegre51_cab_bancos.rela_socmain01 = :rela_socmain01;
        delete from sicegre60_cab_rendicion where sicegre60_cab_rendicion.rela_socmain01 = :rela_socmain01;
    
        delete from sicingr51_cab_bancos where sicingr51_cab_bancos.rela_socmain01 = :rela_socmain01;
        delete from sicingr60_cab_depositos where sicingr60_cab_depositos.rela_socmain01 = :rela_socmain01;
    
        delete from sicnomi51_cab_bancos where sicnomi51_cab_bancos.rela_socmain01 = :rela_socmain01;
        delete from sicnomi60_cab_xperiodo where sicnomi60_cab_xperiodo.rela_socmain01 = :rela_socmain01;
    
        delete from sicpago70_cab_pago where sicpago70_cab_pago.rela_socmain01 = :rela_socmain01;
        delete from sicingr70_cab_facturacion where sicingr70_cab_facturacion.rela_socmain01 = :rela_socmain01;
        delete from sicnomi70_cab_nomina where sicnomi70_cab_nomina.rela_socmain01 = :rela_socmain01;
    
        delete from siccont10_cab_polizas where siccont10_cab_polizas.rela_socmain01 = :rela_socmain01;
    
        delete from SICXMLS40_CAB_MIGRACION where SICXMLS40_CAB_MIGRACION.rela_socmain01 = :rela_socmain01;
    
        delete from pymvent70_cab_ticket where pymvent70_cab_ticket.rela_socmain01 = :rela_socmain01;
    
        delete from sicingr85_cab_gastos3ros where sicingr85_cab_gastos3ros.rela_socmain01 = :rela_socmain01;
        delete from sicxmls01_cab_parametros where sicxmls01_cab_parametros.rela_socmain01 = :rela_socmain01;
    
        delete from sicxmls10_tmp_sicxmls04;
    
        delete from SICINGR30_CAB_MIGRACION where SICINGR30_CAB_MIGRACION.rela_socusua01 = :rela_socmain01;
    
        delete from sicegre01_cab_proveedores where sicegre01_cab_proveedores.rela_socmain01 = :rela_socmain01;
        delete from sicingr01_cab_clientes where sicingr01_cab_clientes.rela_socmain01 = :rela_socmain01;
        delete from sicnomi01_cab_empleados where sicnomi01_cab_empleados.rela_socmain01 = :rela_socmain01;
    
        delete from TMP_SOCUSUA30_SICXMLS41;
        delete from tmp_siccont11_balanza;
        delete from tmp_siccont11_balanza_balance;
        delete from tmp_siccont01_siccont02;
        delete from tmp_sicnomi73;
        delete from tmp_socusua30_sicxmls41;
    
        delete from siccont30_cab_reportes where siccont30_cab_reportes.rela_socmain01 = :rela_socmain01;

        delete from pymvent50_cab_apertura where pymvent50_cab_apertura.rela_socmain01 = :rela_socmain01;
        delete from PYMVENT01_CAB_CAJAS where PYMVENT01_CAB_CAJAS.rela_socmain01 = :rela_socmain01;
    
        delete from socmain01_cab_empresas where socmain01_cab_empresas.id_socmain01 = :rela_socmain01;
    end
    else
    begin
        for select socmain01_cab_empresas.id_socmain01
        from socmain01_cab_empresas
        where socmain01_cab_empresas.id_socmain01 <> 22
        and socmain01_cab_empresas.id_socmain01 <> :rela_socmain01
        into :rela_socmain01
        do
        begin
            execute procedure SMX$SOC_BORRACONTABILIDAD :rela_socmain01, 0;
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CONTADORES (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    IDX INTEGER,
    ALIAS VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    NRODOC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SERIE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCMAIN10_MODO integer;
declare variable ID_SOCSYST10 bigint;
declare variable PREFIJO varchar(10);
declare variable SUBFIJO varchar(10);
declare variable LONGITUD integer;
declare variable CONTADOR integer;
declare variable ID_CONTA bigint;
begin
    alias = upper(alias);

    Select
    socsyst10_det_entradas.id_socsyst10,
    socmain10_det_contadores.socmain10_modo
    from socmain10_det_contadores
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socmain10_det_contadores.rela_socsyst10_co001)
    where socmain10_det_contadores.rela_socmain01 = :RELA_SOCMAIN01
    and socsyst10_det_entradas.socsyst10_codigo = :alias
    into :id_socsyst10, :socmain10_modo;

    if (id_socsyst10 is null) then
    begin
     select smx$util_strrepeat.resultado
        from smx$util_strrepeat(:idx, '0', 6, 0)
        into :NRODOC;

        SERIE = 'AUT';
        NRODOC = SERIE || NRODOC;
    end
    else
    begin
        if (socmain10_modo = 0) then
        begin
            select
            socsyst20_cab_contaempr.id_socsyst20,
            socsyst20_cab_contaempr.socsyst20_prefijo,
            socsyst20_cab_contaempr.socsyst20_subfijo,
            socsyst20_cab_contaempr.socsyst20_longitud,
            socsyst20_cab_contaempr.socsyst20_contador
            from socsyst20_cab_contaempr
            where socsyst20_cab_contaempr.rela_socmain01 = :RELA_SOCMAIN01
            and socsyst20_cab_contaempr.rela_socsyst10_co001 = :id_socsyst10
            into :id_conta,
                 :prefijo,
                 :subfijo,
                 :longitud,
                 :contador;

            contador = contador + 1;
            if (prefijo is null) then prefijo = '';
            if (subfijo is null) then subfijo = '';

            update socsyst20_cab_contaempr set socsyst20_cab_contaempr.socsyst20_contador = :contador
            where socsyst20_cab_contaempr.rela_socmain01 = :RELA_SOCMAIN01
            and socsyst20_cab_contaempr.rela_socsyst10_co001 = :id_socsyst10;
        end
        else
        begin
            select
            socsyst21_cab_contaorga.id_socsyst21,
            socsyst21_cab_contaorga.socsyst21_prefijo,
            socsyst21_cab_contaorga.socsyst21_subfijo,
            socsyst21_cab_contaorga.socsyst21_longitud,
            socsyst21_cab_contaorga.socsyst21_contador
            from socsyst21_cab_contaorga
            where socsyst21_cab_contaorga.rela_socmain01 = :RELA_SOCMAIN01
            and socsyst21_cab_contaorga.rela_socmain21 = :rela_socmain21
            and socsyst21_cab_contaorga.rela_socsyst10_co001 = :id_socsyst10
            into :id_conta,
                 :prefijo,
                 :subfijo,
                 :longitud,
                 :contador;

            contador = contador + 1;
            if (prefijo is null) then prefijo = '';
            if (subfijo is null) then subfijo = '';

            update socsyst21_cab_contaorga set socsyst21_cab_contaorga.socsyst21_contador = :contador
            where socsyst21_cab_contaorga.rela_socmain01 = :RELA_SOCMAIN01
            and socsyst21_cab_contaorga.rela_socmain21 = :rela_socmain21
            and socsyst21_cab_contaorga.rela_socsyst10_co001 = :id_socsyst10;
        end

        if (id_conta is null) then
        begin
            select smx$util_strrepeat.resultado
            from smx$util_strrepeat(:idx, '0', 6, 0)
            into :NRODOC;


        end
        else
        begin
            select smx$util_strrepeat.resultado
            from smx$util_strrepeat(:contador, '0', :longitud, 0)
            into :NRODOC;

            NRODOC = trim(prefijo) || NRODOC || trim(subfijo);
            serie = trim(prefijo);
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_COPIA_SOCSYST01
RETURNS (
    RELA_SOCSYST10_SX001 BIGINT,
    RELA_SOCSYST10_SX002 BIGINT,
    ID_SOCSYST01 BIGINT,
    SOCSYST01_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST01_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST01_ACTIVO INTEGER,
    SOCSYST01_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST01_URL_CLASE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST01_FAPL TIMESTAMP)
AS
declare variable SOCSYST01 varchar(400);
declare variable ID_SOCSYST01_LOCAL bigint;
declare variable URL_LOCAL varchar(400);
declare variable SX001 varchar(50);
declare variable SX002 varchar(50);
begin
    SOCSYST01 = 'select sx001.socsyst10_codigo sx001, sx002.socsyst10_codigo sx002, ' ||
                'socsyst01_cab_funciones.* from socsyst01_cab_funciones ' ||
                'inner join socsyst10_det_entradas sx001 on ( sx001.id_socsyst10 = socsyst01_cab_funciones.rela_socsyst10_sx001 ) ' ||
                'inner join socsyst10_det_entradas sx002 on ( sx002.id_socsyst10 = socsyst01_cab_funciones.rela_socsyst10_sx002 )';
    for execute statement :SOCSYST01
    on external 'SMXVAC'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :sx001,
         :sx002,
         :rela_socsyst10_sx001,
         :rela_socsyst10_sx002,
         :id_socsyst01,
         :SOCSYST01_CODIGO,
         :socsyst01_descripcion,
         :socsyst01_activo,
         :socsyst01_tipo,
         :socsyst01_url_clase,
         :SOCSYST01_FAPL
    do
    BEGIN    
        id_socsyst01_local = null;

        select
        socsyst01_cab_funciones.id_socsyst01,
        socsyst01_cab_funciones.socsyst01_url_clase
        from socsyst01_cab_funciones
        where socsyst01_cab_funciones.socsyst01_codigo = :socsyst01_codigo
        into :id_socsyst01_local,
             :url_local;

        select cbo_socsyst10_sx001.id_socsyst10
        from cbo_socsyst10_sx001
        where cbo_socsyst10_sx001.socsyst10_codigo_sx001 = :sx001
        into :rela_socsyst10_sx001;

        select cbo_socsyst10_sx002.id_socsyst10
        from cbo_socsyst10_sx002
        where cbo_socsyst10_sx002.socsyst10_codigo_sx002 = :sx002
        into :rela_socsyst10_sx002;

        if (id_socsyst01_local is null) then
            insert into socsyst01_cab_funciones( socsyst01_cab_funciones.rela_socsyst10_sx001,
                                                 socsyst01_cab_funciones.rela_socsyst10_sx002,
                                                 socsyst01_cab_funciones.socsyst01_codigo,
                                                 socsyst01_cab_funciones.socsyst01_descripcion,
                                                 socsyst01_cab_funciones.socsyst01_activo,
                                                 socsyst01_cab_funciones.socsyst01_tipo,
                                                 socsyst01_cab_funciones.socsyst01_url_clase)
            values(:rela_socsyst10_sx001,
                   :rela_socsyst10_sx002,
                   :socsyst01_codigo,
                   :socsyst01_descripcion,
                   :socsyst01_activo,
                   :socsyst01_tipo,
                   :socsyst01_url_clase);

        else if (upper(trim(socsyst01_url_clase)) <> upper(trim(:url_local))) then
            update socsyst01_cab_funciones set socsyst01_cab_funciones.socsyst01_url_clase = :socsyst01_url_clase
            where socsyst01_cab_funciones.id_socsyst01 = :id_socsyst01_local;

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_COPIA_SOCSYST02
RETURNS (
    RELA_SOCSYST01 BIGINT,
    ID_SOCSYST02 BIGINT,
    SOCSYST02_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST02_PARAMETRO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST02_FAPL TIMESTAMP)
AS
declare variable SOCSYST02 varchar(1000);
declare variable ID_SOCSYST02_LOCAL bigint;
begin
    socsyst02 = 'Select socsyst02_det_parametros.rela_socsyst01, socsyst02_det_parametros.id_socsyst02,
                 socsyst02_det_parametros.socsyst02_descripcion, socsyst02_det_parametros.socsyst02_parametro,
                 socsyst02_det_parametros.socsyst02_fapl from socsyst02_det_parametros';

    for execute statement :socsyst02
    on external 'SMXVAC'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :rela_socsyst01,
         :id_socsyst02,
         :socsyst02_descripcion,
         :socsyst02_parametro,
         :socsyst02_fapl
    do
    begin
        select socsyst02_det_parametros.id_socsyst02
        from socsyst02_det_parametros
        where socsyst02_det_parametros.rela_socsyst01 = :rela_socsyst01
        and socsyst02_det_parametros.socsyst02_parametro = :socsyst02_parametro
        into :id_socsyst02_local;

        if (id_socsyst02_local is null) then
        begin
            insert into socsyst02_det_parametros( socsyst02_det_parametros.rela_socsyst01,
                                                  socsyst02_det_parametros.socsyst02_descripcion,
                                                  socsyst02_det_parametros.socsyst02_parametro )
            values( :rela_socsyst01,
                    :socsyst02_descripcion,
                    :socsyst02_parametro );
        end
        else
        begin
            update socsyst02_det_parametros set socsyst02_det_parametros.socsyst02_descripcion = :socsyst02_descripcion,
                                                socsyst02_det_parametros.socsyst02_parametro = :socsyst02_parametro
            where socsyst02_det_parametros.id_socsyst02 = :id_socsyst02_local;
        end

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_COPIA_SOCSYST10
RETURNS (
    STATUS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_SOCSYST09 BIGINT,
    SOCSYST09_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST09_DESCIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST09_REMOTO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST09_FAPL TIMESTAMP,
    RELA_SOCSYST09 BIGINT,
    ID_SOCSYST10 BIGINT,
    SOCSYST10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_GRUPO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_VALOR01 VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST10_FAPL TIMESTAMP,
    RELA_SOCSYST10 BIGINT,
    ID_SOCSYST11 BIGINT,
    SOCSYST11_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST11_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST11_CODAGR VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST11_FAPL TIMESTAMP,
    ID_SOCSYST15 BIGINT,
    SOCSYST15_REPORTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST15_FXML VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST15_FAPL TIMESTAMP)
AS
declare variable SOCSYST09 varchar(8000);
declare variable SOCSYST10 varchar(8000);
declare variable SOCSYST11 varchar(8000);
declare variable ID_SOCSYST09_LOCAL bigint;
declare variable ID_SOCSYST10_LOCAL bigint;
declare variable ID_SOCSYST11_LOCAL bigint;
declare variable ID_SOCSYST15_LOCAL bigint;
begin
    delete from socsyst10_det_entradas where socsyst10_det_entradas.id_socsyst10 = 582;

    SOCSYST09 = 'SELECT * FROM SOCSYST09_CAB_ENTRADAS';
    for execute statement :SOCSYST09
    on external 'SMXVAC'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :ID_SOCSYST09,
         :SOCSYST09_CODIGO,
         :socsyst09_descipcion,
         :SOCSYST09_REMOTO,
         :SOCSYST09_FAPL
    do
    BEGIN
        STATUS = 'S/N';

        id_socsyst09_local = null;

        Select socsyst09_cab_entradas.id_socsyst09
        from socsyst09_cab_entradas
        where socsyst09_cab_entradas.socsyst09_codigo = :SOCSYST09_CODIGO
        into :id_socsyst09_local;

        if (id_socsyst09_local is null) then
        begin
            insert into socsyst09_cab_entradas( socsyst09_cab_entradas.socsyst09_codigo,
                                                socsyst09_cab_entradas.socsyst09_descipcion,
                                                socsyst09_cab_entradas.socsyst09_remoto)
            values(:SOCSYST09_CODIGO, :socsyst09_descipcion, :socsyst09_remoto);

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCSYST09'
            INTO :id_socsyst09_local;
        end
        else
        begin
            update socsyst09_cab_entradas set socsyst09_cab_entradas.socsyst09_descipcion = :socsyst09_descipcion,
                                              socsyst09_cab_entradas.socsyst09_remoto = :socsyst09_remoto
            where socsyst09_cab_entradas.id_socsyst09 = :id_socsyst09_local;
        end

        SOCSYST10 = 'SELECT * FROM SOCSYST10_DET_ENTRADAS WHERE RELA_SOCSYST09 = ' || :ID_SOCSYST09;
        for execute statement :SOCSYST10
        on external 'SMXVAC'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :RELA_SOCSYST09,
             :ID_SOCSYST10,
             :SOCSYST10_CODIGO,
             :SOCSYST10_DESCRIPCION,
             :SOCSYST10_GRUPO,
             :SOCSYST10_VALOR01,
             :SOCSYST10_FAPL
        do
        BEGIN
            id_socsyst10_local = null;

            select socsyst10_det_entradas.id_socsyst10
            from socsyst10_det_entradas
            where socsyst10_det_entradas.rela_socsyst09 = :id_socsyst09_local
            and socsyst10_det_entradas.socsyst10_codigo = :SOCSYST10_CODIGO
            into :id_socsyst10_local;

            if (id_socsyst10_local is null) then
            begin
                STATUS = 'ALTA';

                insert into socsyst10_det_entradas( socsyst10_det_entradas.rela_socsyst09,
                                                    socsyst10_det_entradas.socsyst10_codigo,
                                                    socsyst10_det_entradas.socsyst10_descripcion,
                                                    socsyst10_det_entradas.socsyst10_grupo,
                                                    socsyst10_det_entradas.socsyst10_valor01)
                values( :id_socsyst09_local,
                        :SOCSYST10_CODIGO,
                        :socsyst10_descripcion,
                        :socsyst10_grupo,
                        :socsyst10_valor01);

                select socsyst91_tbl_ultids.socsyst91_ultid
                from socsyst91_tbl_ultids
                WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
                AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCSYST10'
                INTO :id_socsyst10_local;
            end
            else
            begin
                STATUS = 'MODI';

                update socsyst10_det_entradas set socsyst10_det_entradas.socsyst10_descripcion = socsyst10_descripcion,
                                                  socsyst10_det_entradas.socsyst10_grupo = :socsyst10_grupo,
                                                  socsyst10_det_entradas.socsyst10_valor01 = :socsyst10_valor01
                where socsyst10_det_entradas.id_socsyst10 = :id_socsyst10_local;
            end

            if (SOCSYST09_CODIGO = 'CNO01') then
            BEGIN
                SOCSYST11 = 'SELECT * FROM SOCSYST11_DET_SAT WHERE RELA_SOCSYST10 = ' || :ID_SOCSYST10;
                for execute statement :SOCSYST11
                on external 'SMXVAC'
                AS
                USER 'SYSDBA' PASSWORD 'masterkey'
                    into :RELA_SOCSYST10,
                         :ID_SOCSYST11,
                         :SOCSYST11_CODIGO,
                         :SOCSYST11_DESCRIPCION,
                         :SOCSYST11_CODAGR,
                         :SOCSYST11_FAPL
                do
                BEGIN
                    id_socsyst11_local = NULL;

                    select socsyst11_det_sat.id_socsyst11
                    from socsyst11_det_sat
                    where socsyst11_det_sat.rela_socsyst10 = :id_socsyst10_local
                    AND socsyst11_det_sat.socsyst11_codigo = :SOCSYST11_CODIGO
                    into :id_socsyst11_local;

                    if (id_socsyst11_local IS NULL) then
                    BEGIN
                         STATUS = 'ALTA-SAT';
                        INSERT INTO socsyst11_det_sat( socsyst11_det_sat.rela_socsyst10,
                                                       socsyst11_det_sat.socsyst11_codigo,
                                                       socsyst11_det_sat.socsyst11_descripcion,
                                                       socsyst11_det_sat.socsyst11_codagr)
                        VALUES(:id_socsyst10_local,
                           :SOCSYST11_CODIGO,
                           :SOCSYST11_DESCRIPCION,
                           :SOCSYST11_CODAGR);
                    END
                    else
                    begin
                        update socsyst11_det_sat set socsyst11_det_sat.socsyst11_descripcion = :SOCSYST11_DESCRIPCION,
                                                     socsyst11_det_sat.socsyst11_codagr = :SOCSYST11_CODAGR
                        where socsyst11_det_sat.id_socsyst11 = :id_socsyst11_local;
                    end
                END
            END

            if (SOCSYST09_CODIGO = 'FFS01') then
            BEGIN
                SOCSYST11 = 'SELECT * FROM SOCSYST15_DEP_CFDI WHERE RELA_SOCSYST10 = ' || :ID_SOCSYST10;
                for execute statement :SOCSYST11
                on external 'SMXVAC'
                AS
                USER 'SYSDBA' PASSWORD 'masterkey'
                    into :RELA_SOCSYST10,
                         :ID_SOCSYST15,
                         :SOCSYST15_REPORTE,
                         :SOCSYST15_FXML,
                         :SOCSYST15_FAPL
                do
                BEGIN
                    id_socsyst15_local = NULL;

                    select socsyst15_dep_cfdi.id_socsyst15
                    from socsyst15_dep_cfdi
                    where socsyst15_dep_cfdi.rela_socsyst10 = :id_socsyst10_local
                    into :id_socsyst15_local;

                    if (id_socsyst15_local IS NULL) then
                    BEGIN
                        STATUS = 'ALTA-CFDI';
                        INSERT INTO socsyst15_dep_cfdi( socsyst15_dep_cfdi.rela_socsyst10,
                                                        socsyst15_dep_cfdi.socsyst15_reporte,
                                                        socsyst15_dep_cfdi.socsyst15_fxml)
                        VALUES(:id_socsyst10_local,
                               :SOCSYST15_REPORTE,
                               :SOCSYST15_FXML);
                    END
                    else
                    begin
                        update socsyst15_dep_cfdi set socsyst15_dep_cfdi.socsyst15_reporte = :SOCSYST15_REPORTE,
                                                      socsyst15_dep_cfdi.socsyst15_fxml = :SOCSYST15_FXML
                        where socsyst15_dep_cfdi.id_socsyst15 = :id_socsyst15_local;
                    end
                END
            END
        end

        suspend;

    END
end^


CREATE OR ALTER PROCEDURE SMX$SOC_COPIA_SOCSYST13
RETURNS (
    RELA_SOCSYST01 BIGINT,
    ID_SOCSYST13 BIGINT,
    SOCSYST13_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_REPORTE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_FXML VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST13_ACTIVO INTEGER,
    SOCSYST13_FAPL TIMESTAMP)
AS
declare variable SMXSQL varchar(8000);
declare variable ID_SOCSYST13_LOCAL bigint;
declare variable SMXSQL_DET varchar(8000);
declare variable RELA_SOCSYST13 integer;
declare variable ID_SOCSYST14 bigint;
declare variable SOCSYST14_DESCRIPCION varchar(400);
declare variable SOCSYST14_PARAMETRO varchar(50);
declare variable SOCSYST14_VALOR varchar(400);
declare variable SOCSYST14_FAPL timestamp;
begin
    UPDATE sicxmls41_det_migracion SET sicxmls41_det_migracion.sicxmls41_origen = 'Z'
    WHERE sicxmls41_det_migracion.sicxmls41_origen is null;

    SMXSQL = 'SELECT * FROM SOCSYST13_CAB_REPORTES';
    for execute statement :SMXSQL
    on external 'SMXVAC'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :RELA_SOCSYST01,
         :ID_SOCSYST13,
         :SOCSYST13_CODIGO,
         :SOCSYST13_DESCRIPCION,
         :SOCSYST13_REPORTE,
         :SOCSYST13_FXML,
         :SOCSYST13_TIPO,
         :SOCSYST13_ACTIVO,
         :SOCSYST13_FAPL
    do
    BEGIN
        id_socsyst13_local = null;

        select socsyst13_cab_reportes.id_socsyst13
        from socsyst13_cab_reportes
        where socsyst13_cab_reportes.socsyst13_codigo = :SOCSYST13_CODIGO
        into :id_socsyst13_local;

        if (id_socsyst13_local is null) then
        begin
            insert into socsyst13_cab_reportes( socsyst13_cab_reportes.rela_socsyst01,
                                                socsyst13_cab_reportes.socsyst13_codigo,
                                                socsyst13_cab_reportes.socsyst13_descripcion,
                                                socsyst13_cab_reportes.socsyst13_reporte,
                                                socsyst13_cab_reportes.socsyst13_fxml,
                                                socsyst13_cab_reportes.socsyst13_tipo,
                                                socsyst13_cab_reportes.socsyst13_activo)
            values( :RELA_SOCSYST01,
                    :socsyst13_codigo,
                    :socsyst13_descripcion,
                    :socsyst13_reporte,
                    :socsyst13_fxml,
                    :socsyst13_tipo,
                    :socsyst13_activo);


            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCSYST13'
            INTO :id_socsyst13_local;
        end
        else
        begin
            update socsyst13_cab_reportes set socsyst13_cab_reportes.socsyst13_descripcion = :socsyst13_descripcion,
                                              socsyst13_cab_reportes.socsyst13_reporte = :socsyst13_reporte,
                                              socsyst13_cab_reportes.socsyst13_fxml = :socsyst13_fxml,
                                              socsyst13_cab_reportes.socsyst13_tipo = :socsyst13_tipo
            where socsyst13_cab_reportes.id_socsyst13 = :id_socsyst13_local;
        end

        delete from socsyst14_det_parametros where socsyst14_det_parametros.rela_socsyst13 = :id_socsyst13_local;

        SMXSQL_DET = 'SELECT * FROM SOCSYST14_DET_PARAMETROS where RELA_SOCSYST13 = ' || :id_socsyst13;
        for execute statement :SMXSQL_DET
        on external 'SMXVAC'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :RELA_SOCSYST13,
             :ID_SOCSYST14,
             :SOCSYST14_DESCRIPCION,
             :SOCSYST14_PARAMETRO,
             :SOCSYST14_VALOR,
             :SOCSYST14_FAPL
        do
        BEGIN
            insert into socsyst14_det_parametros( socsyst14_det_parametros.rela_socsyst13,
                                                  socsyst14_det_parametros.socsyst14_descripcion,
                                                  socsyst14_det_parametros.socsyst14_parametro,
                                                  socsyst14_det_parametros.socsyst14_valor)
            values( :id_socsyst13_local,
                    :SOCSYST14_DESCRIPCION,
                    :SOCSYST14_PARAMETRO,
                    :SOCSYST14_VALOR);
        END

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE SMX$SOC_COPIAEMPRESAS (
    RELA_SOCMAIN01_SOURCE BIGINT,
    RELA_SOCMAIN01_TARGET BIGINT)
RETURNS (
    OK INTEGER)
AS
declare variable EXISTE integer;
begin
    ok = 0;
    existe = null;

    select sicxmls01_cab_parametros.id_sicxmls01
    from sicxmls01_cab_parametros
    where sicxmls01_cab_parametros.rela_socmain01 = :RELA_SOCMAIN01_TARGET
    into :existe;

    if (existe is null) then
    begin
        INSERT INTO sicxmls01_cab_parametros(sicxmls01_cab_parametros.rela_socmain01,
                                             sicxmls01_cab_parametros.rela_socsyst10_pct01,
                                             sicxmls01_cab_parametros.sicxmls01_ajuste_monto)
        select
        source.rela_socmain01,
        source.rela_socsyst10_pct01,
        source.sicxmls01_ajuste_monto
        from sicxmls01_cab_parametros source
        where source.rela_socmain01 = :RELA_SOCMAIN01_SOURCE;

        ok = 1;
        suspend;
    end
end^


