CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_MONEDA (
    MODALIDAD INTEGER)
RETURNS (
    TABLA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ALIAS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CAMPO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CON_DATOS INTEGER)
AS
declare variable CAMPO_RELA varchar(100);
declare variable SMXSQL varchar(1000);
declare variable ID_SOCSYST10_REMOTO bigint;
declare variable ID_TMP_REMOTO_USA bigint;
declare variable SOCSYST10_CODIGO varchar(50);
declare variable ID bigint;
declare variable RELA_SOCSYST10_CTM01 bigint;
declare variable ID_TMP_REMOTO bigint;
declare variable CKEY varchar(50);
begin
    select CBO_SOCSYST10_CTM01W.id_socsyst10
    from CBO_SOCSYST10_CTM01W
    where CBO_SOCSYST10_CTM01W.socsyst10_codigo = 'MXN'
    INTO :id_tmp_remoto;

    select CBO_SOCSYST10_CTM01W.id_socsyst10
    from CBO_SOCSYST10_CTM01W
    where CBO_SOCSYST10_CTM01W.socsyst10_codigo = 'USD'
    INTO :id_tmp_remoto_usa;

    FOR SELECT
    smx$db_dicc_tablas_y_campos.tablas,
    smx$db_dicc_tablas_y_campos.alias,
    smx$db_dicc_tablas_y_campos.campos
    FROM smx$db_dicc_tablas_y_campos
    WHERE smx$db_dicc_tablas_y_campos.campos = 'RELA_SOCSYST10_CTM01'
    INTO :tabla,
         :alias,
         :campo
    DO
    BEGIN
        if (MODALIDAD = 1) then
        BEGIN
            CAMPO_RELA = trim(substring(campo from 6 for char_length(campo)-5));
            ckey = null;

            select RDB$RELATION_CONSTRAINTS.RDB$DB_KEY
            from RDB$RELATION_CONSTRAINTS
            where RDB$RELATION_CONSTRAINTS.rdb$index_name = 'FKY_' || :alias || '_' || :CAMPO_RELA
            into :ckey;

            if (ckey is not null) then
            begin
                SMXSQL = 'ALTER TABLE ' || :tabla || ' DROP CONSTRAINT FKY_' || :alias || '_' || :CAMPO_RELA;
                EXECUTE STATEMENT :SMXSQL;
            end
        END
        ELSE if (MODALIDAD = 2) then
        BEGIN
            SMXSQL = 'select count(*) from ' || :tabla;
            EXECUTE STATEMENT :SMXSQL
            into :con_datos;

            if (con_datos <> 0) then
            begin
                SMXSQL = 'select rela_socsyst10_ctm01, ID_' || :alias || ' from ' || :tabla || ' where rela_socsyst10_ctm01 < 54665';
                for EXECUTE STATEMENT :SMXSQL
                into :rela_socsyst10_ctm01,
                     :id
                do
                begin
                    socsyst10_codigo = null;
                    id_socsyst10_remoto = null;
    
                    select socsyst10_det_entradas.socsyst10_codigo
                    from socsyst10_det_entradas
                    inner join socsyst09_cab_entradas on ( socsyst09_cab_entradas.id_socsyst09 = socsyst10_det_entradas.rela_socsyst09)
                    where socsyst09_cab_entradas.socsyst09_codigo = 'CTM01'
                    and socsyst10_det_entradas.id_socsyst10 = :rela_socsyst10_ctm01
                    INTO :socsyst10_codigo;
    
                    socsyst10_codigo = iif(socsyst10_codigo is null, 'MXN', socsyst10_codigo);
    
                    select cbo_socsyst10_ctm01w.id_socsyst10
                    from cbo_socsyst10_ctm01w
                    where cbo_socsyst10_ctm01w.socsyst10_codigo = :socsyst10_codigo
                    into :id_socsyst10_remoto;
    
                    if (id_socsyst10_remoto IS NULL and socsyst10_codigo = 'USA') then
                        id_socsyst10_remoto = id_tmp_remoto_usa;
                    else if (id_socsyst10_remoto IS NULL and socsyst10_codigo <> 'USA') then
                        id_socsyst10_remoto = id_tmp_remoto;
    
                    SMXSQL = 'update ' || :tabla || ' set rela_socsyst10_ctm01 = ' || :id_socsyst10_remoto ||
                             ' where id_' || :alias || ' = ' || :id;
    
                    EXECUTE STATEMENT :SMXSQL;
                end
            END
        END
        ELSE if (MODALIDAD = 3) then
        BEGIN
            SMXSQL = 'ALTER TABLE ' || :tabla || ' ADD CONSTRAINT FKY_' || :alias || '_SOCSYST10_CTM01 FOREIGN KEY (RELA_SOCSYST10_CTM01)
                     REFERENCES SOCSYST10_DET_REMOTO(ID_SOCSYST10) ';

            EXECUTE STATEMENT :SMXSQL;
        END

        suspend;
    END
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_PYMVENT71
RETURNS (
    RELA_SICINGR95 BIGINT,
    RELA_PYMVENT70 BIGINT,
    ID_PYMVENT71 BIGINT,
    PYMVENT71_CANTIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_UNIDAD DOUBLE PRECISION,
    PYMVENT71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_DESCUENTO DOUBLE PRECISION,
    PYMVENT71_IMPORTE_TOTAL DOUBLE PRECISION,
    PYMVENT71_IMPORTE_IMPUESTOS NUMERIC(15,2),
    PYMVENT71_IMPORTE_RETENIDO NUMERIC(15,2),
    PYMVENT71_IMPORTE_TRASLADO NUMERIC(15,2),
    PYMVENT71_IMPORTE_LOCALES NUMERIC(15,2),
    PYMVENT71_IMPORTE_NETO NUMERIC(15,2),
    IMPUESTOS_X_PRODUCTO INTEGER,
    IMPUESTOS_IMPORTE NUMERIC(15,2),
    STATUS INTEGER)
AS
declare variable RELA_SICXMLS02 bigint;
declare variable SICINGR90_TIPOZONA varchar(1);
declare variable IMPUESTO varchar(50);
declare variable FACTOR varchar(50);
declare variable TASA double precision;
declare variable RETENIDO integer;
declare variable SUM_SUBTOTAL numeric(15,2);
declare variable SUM_DESCUENTOS numeric(15,2);
declare variable SUM_TOTAL numeric(15,2);
declare variable SUM_RETENIDO numeric(15,2);
declare variable SUM_TRASLADO numeric(15,2);
declare variable SUM_LOCAL numeric(15,2);
declare variable SUM_NETO numeric(15,2);
begin
    update socsyst50_cab_config set socsyst50_cab_config.socsyst50_pymvent71 = 1;

    /*
        busco los ticket que tengan importe neto y no tenga impuestos
        VALOR = 0;
    */

    for select
    0,
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.rela_pymvent70,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_subtotal,
    pymvent71_det_ticket.pymvent71_importe_descuento,
    pymvent71_det_ticket.pymvent71_importe_total,
    pymvent71_det_ticket.pymvent71_importe_impuestos,
    pymvent71_det_ticket.pymvent71_importe_retenido,
    pymvent71_det_ticket.pymvent71_importe_traslado,
    pymvent71_det_ticket.pymvent71_importe_locales,
    pymvent71_det_ticket.pymvent71_importe_neto
    from pymvent71_det_ticket
    where pymvent71_det_ticket.pymvent71_cancelado = 0
    and pymvent71_det_ticket.pymvent71_importe_neto <> 0
    and not exists (select pymvent72_det_impuestos.id_pymvent72
                    from pymvent72_det_impuestos
                    where pymvent72_det_impuestos.rela_pymvent71 = pymvent71_det_ticket.id_pymvent71)

    union all

    /*
        busco los ticket que NO tengan o sea CERO importe neto no importa si tiene impuestos
        VALOR = 1;
    */

    select
    1,
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.rela_pymvent70,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_subtotal,
    pymvent71_det_ticket.pymvent71_importe_descuento,
    pymvent71_det_ticket.pymvent71_importe_total,
    pymvent71_det_ticket.pymvent71_importe_impuestos,
    pymvent71_det_ticket.pymvent71_importe_retenido,
    pymvent71_det_ticket.pymvent71_importe_traslado,
    pymvent71_det_ticket.pymvent71_importe_locales,
    pymvent71_det_ticket.pymvent71_importe_neto
    from pymvent71_det_ticket
    where pymvent71_det_ticket.pymvent71_cancelado = 0
    and pymvent71_det_ticket.pymvent71_importe_neto = 0

    union all

    /*
        busco los ticket que el TOTAL sea diferente a la Base o que el total de impuestos sea diferente a la cabecera de detalle
        VALOR = 2;
    */

    select
    2,
    pymvent71_det_ticket.rela_sicingr95,
    pymvent71_det_ticket.rela_pymvent70,
    pymvent71_det_ticket.id_pymvent71,
    pymvent71_det_ticket.pymvent71_cantidad,
    pymvent71_det_ticket.pymvent71_importe_unidad,
    pymvent71_det_ticket.pymvent71_importe_subtotal,
    pymvent71_det_ticket.pymvent71_importe_descuento,
    pymvent71_det_ticket.pymvent71_importe_total,
    pymvent71_det_ticket.pymvent71_importe_impuestos,
    pymvent71_det_ticket.pymvent71_importe_retenido,
    pymvent71_det_ticket.pymvent71_importe_traslado,
    pymvent71_det_ticket.pymvent71_importe_locales,
    pymvent71_det_ticket.pymvent71_importe_neto
    from pymvent71_det_ticket
    where pymvent71_det_ticket.pymvent71_cancelado = 0
    and exists ( select first 1 pymvent72_det_impuestos.id_pymvent72
                 from pymvent72_det_impuestos
                 where pymvent72_det_impuestos.rela_pymvent71 = pymvent71_det_ticket.id_pymvent71
                 and cast(pymvent71_det_ticket.pymvent71_importe_total as Numeric(15,2)) <>
                     cast(pymvent72_det_impuestos.pymvent72_base as Numeric(15,2))
                )
    or ( select sum(cast(pymvent72_det_impuestos.pymvent72_importe as Numeric(15,2)) )
         from pymvent72_det_impuestos
         where pymvent72_det_impuestos.rela_pymvent71 = pymvent71_det_ticket.id_pymvent71
        ) <> cast(pymvent71_det_ticket.pymvent71_importe_impuestos as Numeric(15,2))

    into :status,
         :rela_sicingr95,
         :rela_pymvent70,
         :id_pymvent71,
         :pymvent71_cantidad,
         :pymvent71_importe_unidad,
         :pymvent71_importe_subtotal,
         :pymvent71_importe_descuento,
         :pymvent71_importe_total,
         :pymvent71_importe_impuestos,
         :pymvent71_importe_retenido,
         :pymvent71_importe_traslado,
         :pymvent71_importe_locales,
         :pymvent71_importe_neto
    do
    begin
        impuestos_x_producto = 0;

        /* ------------------------------------------------------------------------------------v */

        for select
        sicingr90_cab_impuestos.rela_sicxmls02,
        sicingr90_cab_impuestos.sicingr90_tipozona,
        socsyst10_det_remoto.socsyst10_descripcion,
        sicingr90_cab_impuestos.sicingr90_modo,
        sicingr90_cab_impuestos.sicingr90_tasa,
        sicxmls02_det_impuestos.sicxmls02_retenido
        from sicingr96_det_impuestos
        inner join sicingr90_cab_impuestos on ( sicingr96_det_impuestos.rela_sicingr90 = sicingr90_cab_impuestos.id_sicingr90 )
        inner join socsyst10_det_remoto on ( socsyst10_det_remoto.id_socsyst10 = sicingr90_cab_impuestos.rela_socsyst10_imp02 )
        inner join sicxmls02_det_impuestos on ( sicxmls02_det_impuestos.id_sicxmls02 = sicingr90_cab_impuestos.rela_sicxmls02 )
        where sicingr96_det_impuestos.rela_sicingr95 = :rela_sicingr95
        into :rela_sicxmls02,
             :sicingr90_tipozona,
             :impuesto,
             :factor,
             :tasa,
             :retenido
        do
        begin
            if (impuestos_x_producto = 0) then
            begin
                pymvent71_importe_impuestos = 0;
                pymvent71_importe_retenido = 0;
                pymvent71_importe_traslado = 0;
                pymvent71_importe_locales = 0;
                pymvent71_importe_neto = 0;

                delete from pymvent72_det_impuestos where pymvent72_det_impuestos.rela_pymvent71 = :id_pymvent71;
            end

            impuestos_x_producto = impuestos_x_producto + 1;
            impuestos_importe = 0.00;

            /* ======================================================== */

            if (tasa <> 0) then
            begin
                impuestos_importe = pymvent71_importe_total * tasa / 100;

                if (retenido = 1) then
                    impuestos_importe = impuestos_importe * (-1);
            end

            /* ======================================================== */

            if (retenido = 0) then
                pymvent71_importe_traslado = pymvent71_importe_traslado + impuestos_importe;
            else
                pymvent71_importe_retenido = pymvent71_importe_retenido + (impuestos_importe * (-1));

            /* ======================================================== */

            if (sicingr90_tipozona <> 'F' and retenido = 0) then
                pymvent71_importe_locales = pymvent71_importe_locales + impuestos_importe;
            else if (sicingr90_tipozona <> 'F' and retenido = 1) then
                pymvent71_importe_locales = pymvent71_importe_locales + (impuestos_importe * (-1));

            /* ======================================================== */

            pymvent71_importe_impuestos = pymvent71_importe_impuestos + impuestos_importe;

            /* ======================================================== */

            insert into pymvent72_det_impuestos( pymvent72_det_impuestos.rela_pymvent71,
                                                 pymvent72_det_impuestos.rela_sicxmls02,
                                                 pymvent72_det_impuestos.pymvent72_tipozona,
                                                 pymvent72_det_impuestos.pymvent72_tipo,
                                                 pymvent72_det_impuestos.pymvent72_impuesto,
                                                 pymvent72_det_impuestos.pymvent72_importe,
                                                 pymvent72_det_impuestos.pymvent72_base,
                                                 pymvent72_det_impuestos.pymvent72_tasaocuota,
                                                 pymvent72_det_impuestos.pymvent72_factor )
            values( :id_pymvent71,
                    :rela_sicxmls02,
                    iif(:sicingr90_tipozona = 'F', 'Federal', iif(:sicingr90_tipozona = 'E', 'Estatal', 'Municipal')),
                    iif(:retenido = 0, 'Trasladado','Retenido'),
                    :impuesto,
                    :impuestos_importe,
                    :pymvent71_importe_total,
                    :tasa,
                    :factor);
        end

        /* ------------------------------------------------------------------------------------v */

        if (impuestos_x_producto <> 0) then
        begin
            pymvent71_importe_neto = (pymvent71_importe_total + :pymvent71_importe_impuestos);

            update pymvent71_det_ticket set pymvent71_det_ticket.pymvent71_importe_impuestos = :pymvent71_importe_impuestos,
                                            pymvent71_det_ticket.pymvent71_importe_retenido = :pymvent71_importe_retenido,
                                            pymvent71_det_ticket.pymvent71_importe_traslado = :pymvent71_importe_traslado,
                                            pymvent71_det_ticket.pymvent71_importe_locales = :pymvent71_importe_locales,
                                            pymvent71_det_ticket.pymvent71_importe_neto = :pymvent71_importe_neto
            where pymvent71_det_ticket.id_pymvent71 = :id_pymvent71;

            select
            sum(pymvent71_det_ticket.pymvent71_importe_subtotal),
            sum(pymvent71_det_ticket.pymvent71_importe_descuento),
            sum(pymvent71_det_ticket.pymvent71_importe_total),
            sum(pymvent71_det_ticket.pymvent71_importe_retenido),
            sum(pymvent71_det_ticket.pymvent71_importe_traslado),
            sum(pymvent71_det_ticket.pymvent71_importe_locales),
            sum(pymvent71_det_ticket.pymvent71_importe_neto)
            from pymvent71_det_ticket
            where pymvent71_det_ticket.rela_pymvent70 = :rela_pymvent70
            and pymvent71_det_ticket.pymvent71_cancelado = 0
            into :sum_subtotal,
                 :sum_descuentos,
                 :sum_total,
                 :sum_retenido,
                 :sum_traslado,
                 :sum_local,
                 :sum_neto;

            update pymvent70_cab_ticket set pymvent70_cab_ticket.pymvent70_subtotal = :sum_subtotal,
                                            pymvent70_cab_ticket.pymvent70_descuento = :sum_descuentos,
                                            pymvent70_cab_ticket.pymvent70_total = :sum_total,
                                            pymvent70_cab_ticket.pymvent70_totimp_retenidos = :sum_retenido,
                                            pymvent70_cab_ticket.pymvent70_totimp_traslados = :sum_traslado,
                                            pymvent70_cab_ticket.pymvent70_totimp_locales = :sum_local,
                                            pymvent70_cab_ticket.pymvent70_neto = :sum_neto
            where pymvent70_cab_ticket.id_pymvent70 = :rela_pymvent70;

            suspend;
        end
    end

    update socsyst50_cab_config set socsyst50_cab_config.socsyst50_pymvent71 = 0;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_PYMVENT71_IMP
RETURNS (
    EMPRESA INTEGER,
    STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOT_IMPUESTOS DOUBLE PRECISION,
    SICINGR71_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_CONCEPTO VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICINGR71_IMPORTE_SUBTOTAL DOUBLE PRECISION,
    SICINGR71_IMPORTE_TOTAL DOUBLE PRECISION,
    SICINGR71_IMPORTE_NETO DOUBLE PRECISION)
AS
begin
    FOR SELECT
    socmain01_cab_empresas.socmain01_nomcomercial,
    sicingr70_cab_facturacion.sicingr70_status,
    ( select sum(sicingr72_det_impuestos.sicingr72_importe)
      from sicingr72_det_impuestos
      where sicingr72_det_impuestos.rela_sicingr71 = sicingr71_det_facturacion.id_sicingr71
    ),
    sicingr71_det_facturacion.sicingr71_codigo,
    sicingr71_det_facturacion.sicingr71_concepto,
    sicingr71_det_facturacion.sicingr71_importe_subtotal,
    sicingr71_det_facturacion.sicingr71_importe_total,
    sicingr71_det_facturacion.sicingr71_importe_neto
    FROM sicingr71_det_facturacion
    inner join sicingr70_cab_facturacion on (sicingr70_cab_facturacion.id_sicingr70 = sicingr71_det_facturacion.rela_sicingr70)
    inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = sicingr70_cab_facturacion.rela_socmain01)
    WHERE cast(sicingr71_det_facturacion.sicingr71_importe_impuestos as numeric(15,2)) <> cast( (select sum(sicingr72_det_impuestos.sicingr72_importe)
                                                                                                 from sicingr72_det_impuestos
                                                                                                 where sicingr72_det_impuestos.rela_sicingr71 = sicingr71_det_facturacion.id_sicingr71)
                                                                                            as numeric(15,2))
    into :empresa,
         :status,
         :tot_impuestos,
         :sicingr71_codigo,
         :sicingr71_concepto,
         :sicingr71_importe_subtotal,
         :sicingr71_importe_total,
         :sicingr71_importe_neto
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICEGRE50_1
RETURNS (
    ID_SICEGRE51 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICEGRE01 BIGINT,
    SICEGRE51_IMPORTE NUMERIC(18,2),
    SUMA_IMPORTE_DETALLE NUMERIC(18,2),
    SIN_DETALLE INTEGER,
    SUMA_CTACTE NUMERIC(18,2),
    RELA_SICCONT50 BIGINT)
AS
declare variable SICEGRE50_IMPORTE numeric(18,2);
declare variable RELA_SICCONT10 bigint;
begin
    for select
    SICEGRE51_CAB_BANCOS.id_sicegre51,
    SICEGRE51_CAB_BANCOS.rela_socmain01,
    SICEGRE51_CAB_BANCOS.rela_sicegre01,
    SICEGRE51_CAB_BANCOS.sicegre51_importe,
    ( select sum(sicegre52_det_bancos.sicegre52_importe)
      from sicegre52_det_bancos
      where sicegre52_det_bancos.rela_sicegre51 = SICEGRE51_CAB_BANCOS.id_sicegre51
    )
    from SICEGRE51_CAB_BANCOS
    into :id_sicegre51,
         :rela_socmain01,
         :rela_sicegre01,
         :sicegre51_importe,
         :suma_importe_detalle
    do
    begin
        sin_detalle = 0;
        if (suma_importe_detalle is null) then
        begin
            suma_importe_detalle = 0.00;
            sin_detalle = 1;

            delete from sicegre51_cab_bancos where sicegre51_cab_bancos.id_sicegre51 = :id_sicegre51;

            suspend;
        end
        else if (sicegre51_importe <> suma_importe_detalle or (suma_importe_detalle > sicegre51_importe) ) then
        begin
            SICEGRE50_IMPORTE = 0;

            select sicegre50_det_ctacte.rela_siccont10, sicegre50_det_ctacte.sicegre50_importe
            from sicegre50_det_ctacte
            where sicegre50_det_ctacte.rela_sicegre51 = :id_sicegre51
            into :rela_siccont10,
                 :sicegre50_importe;

            if (rela_siccont10 is not null) then
            begin
                suma_ctacte = suma_ctacte + SICEGRE50_IMPORTE;
                rela_siccont50 = null;
    
                select siccont51_det_bancos.rela_siccont50
                from siccont51_det_bancos
                where siccont51_det_bancos.rela_siccont10 = :rela_siccont10
                into :rela_siccont50;
    
                if (rela_siccont50 is not null) then
                    delete from siccont50_cab_bancos where siccont50_cab_bancos.id_siccont50 = :rela_siccont50;
    
                delete from siccont10_cab_polizas where siccont10_cab_polizas.id_siccont10 = :rela_siccont10;
            end
            else
            begin
                delete from sicegre51_cab_bancos where sicegre51_cab_bancos.id_sicegre51 = :id_sicegre51;
            end

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICINGR50_1
RETURNS (
    RELA_SICINGR01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SICCONT10 BIGINT,
    ID_SICINGR50 BIGINT,
    RELA_SICINGR01_SICXMLS41 BIGINT,
    RELA_SOCUSUA30 BIGINT)
AS
declare variable RELA_SOCUSUA30_CTACONTABLE bigint;
begin
    for select
    sicingr50_det_ctacte.rela_sicingr01,
    sicingr50_det_ctacte.rela_socmain01,
    sicingr50_det_ctacte.rela_siccont10,
    sicingr50_det_ctacte.id_sicingr50
    from sicingr50_det_ctacte
    where sicingr50_det_ctacte.rela_sicingr51 is null
    and exists ( select sicxmls41_det_migracion.id_sicxmls41
                 from sicxmls41_det_migracion
                 where sicxmls41_det_migracion.rela_siccont10 = sicingr50_det_ctacte.rela_siccont10
                )
    into :rela_sicingr01,
         :rela_socmain01,
         :rela_siccont10,
         :id_sicingr50
    do
    begin
        select sicxmls41_det_migracion.rela_socusua30
        from sicxmls41_det_migracion
        where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
        into :rela_socusua30;

        rela_sicingr01_sicxmls41 = null;

        select cbo_sicingr01.rela_sicingr01
        from cbo_sicingr01
        where cbo_sicingr01.id_socusua30 = :rela_socusua30
        and cbo_sicingr01.rela_socmain01 = :rela_socmain01
        into :rela_sicingr01_sicxmls41;

        if (rela_sicingr01_sicxmls41 is not null and rela_sicingr01 <> rela_sicingr01_sicxmls41) then
        begin
            update sicingr50_det_ctacte set sicingr50_det_ctacte.rela_sicingr01 = :rela_sicingr01_sicxmls41
            where sicingr50_det_ctacte.id_sicingr50 = :id_sicingr50;
    
            suspend;
        end
        else if (rela_sicingr01_sicxmls41 is null) then
        begin
            insert into sicingr01_cab_clientes( sicingr01_cab_clientes.rela_socmain01,
                                                sicingr01_cab_clientes.rela_socusua30,
                                                sicingr01_cab_clientes.sicingr01_diascredito,
                                                sicingr01_cab_clientes.sicingr01_credito )
            values( :rela_socmain01,
                    :rela_socusua30,
                    0,
                    0 );

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICINGR50_2
RETURNS (
    RELA_SICINGR01 BIGINT,
    RELA_SICINGR01_POLIZA BIGINT,
    RELA_SICCONT10 BIGINT,
    ID_SICINGR50 BIGINT,
    STATUS VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN01_CLIENTE bigint;
declare variable RELA_SOCUSUA30_POLIZA bigint;
declare variable RELA_SOCUSUA30_CLIENTE bigint;
declare variable RELA_SOCMAIN01_POLIZA bigint;
begin
    for select
    sicingr50_det_ctacte.rela_sicingr01,
    sicingr50_det_ctacte.rela_socmain01,
    sicingr50_det_ctacte.rela_siccont10,
    sicingr50_det_ctacte.id_sicingr50
    from sicingr50_det_ctacte
    where sicingr50_det_ctacte.rela_sicingr51 is null
    and not exists ( select sicxmls41_det_migracion.id_sicxmls41
                     from sicxmls41_det_migracion
                     where sicxmls41_det_migracion.rela_siccont10 = sicingr50_det_ctacte.rela_siccont10
                    )
    into :rela_sicingr01,
         :rela_socmain01,
         :rela_siccont10,
         :id_sicingr50
    do
    begin
        select
        siccont10_cab_polizas.rela_socusua30,
        siccont10_cab_polizas.rela_socmain01
        from siccont10_cab_polizas
        where siccont10_cab_polizas.id_siccont10 = :rela_siccont10
        into :rela_socusua30_poliza,
             :rela_socmain01_poliza;

        select
        cbo_sicingr01_id.rela_socusua30,
        cbo_sicingr01_id.rela_socmain01
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :rela_socusua30_cliente,
             :rela_socmain01_cliente;

        if (rela_socmain01_cliente = rela_socmain01 and rela_socusua30_poliza <> rela_socusua30_cliente) then
        begin
            rela_sicingr01_poliza =  null;

            select cbo_sicingr01.rela_sicingr01
            from cbo_sicingr01
            where cbo_sicingr01.rela_socmain01 = :rela_socmain01
            and cbo_sicingr01.id_socusua30 = :rela_socusua30_poliza
            into :rela_sicingr01_poliza;

            if(rela_sicingr01_poliza is not null) then
            begin
                status = 'Cambia el Id de Cliente';

                update sicingr50_det_ctacte set sicingr50_det_ctacte.rela_sicingr01 = :rela_sicingr01_poliza
                where sicingr50_det_ctacte.id_sicingr50 = :id_sicingr50;

            end
            else
            begin
                status = 'No se encontro Id de Cliente';
            end

            suspend;

        end
        else
        begin
            if (rela_socmain01_cliente <> rela_socmain01) then
            begin
                if (rela_socmain01 <> rela_socmain01_poliza) then
                    status = 'Diferente empresa poliza';
                else
                begin
                    status = 'Cambia el Id de Cliente con Misma Empresa';
                    rela_sicingr01_poliza = null;

                    select cbo_sicingr01.rela_sicingr01
                    from cbo_sicingr01
                    where cbo_sicingr01.rela_socmain01 = :rela_socmain01
                    and cbo_sicingr01.id_socusua30 = :rela_socusua30_poliza
                    into :rela_sicingr01_poliza;
    
                    if (rela_sicingr01_poliza is null) then
                        status = 'No se Encontro el Cliente';
                    else
                        update sicingr50_det_ctacte set sicingr50_det_ctacte.rela_sicingr01 = :rela_sicingr01_poliza
                        where sicingr50_det_ctacte.id_sicingr50 = :id_sicingr50;
                end
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICINGR50_3
RETURNS (
    ID_SICINGR52 BIGINT,
    RELA_SICINGR50 BIGINT,
    SICINGR52_IMPORTE DOUBLE PRECISION,
    ID_SICEGRE52 BIGINT,
    RELA_SICEGRE50 BIGINT,
    SICEGRE52_IMPORTE DOUBLE PRECISION)
AS
declare variable ID_SICINGR51 bigint;
begin
    for select
    max(SICINGR52_DET_BANCOS.id_sicingr52),
    SICINGR52_DET_BANCOS.rela_sicingr50,
    SICINGR52_DET_BANCOS.sicingr52_importe
    from SICINGR52_DET_BANCOS
    group by
    SICINGR52_DET_BANCOS.rela_sicingr50,
    SICINGR52_DET_BANCOS.sicingr52_importe,
    SICINGR52_DET_BANCOS.sicingr52_fapl
    having count(SICINGR52_DET_BANCOS.id_sicingr52) <> 1
    into :id_sicingr52,
         :rela_sicingr50,
         :sicingr52_importe
    do
    begin
        delete from SICINGR52_DET_BANCOS
        where SICINGR52_DET_BANCOS.rela_sicingr50 = :rela_sicingr50
        and SICINGR52_DET_BANCOS.id_sicingr52 <> :id_sicingr52;

        suspend;
    end

    /* -------------------------------------------------------------------------------- */

    for select
    max(SICEGRE52_DET_BANCOS.id_sicegre52),
    SICEGRE52_DET_BANCOS.rela_sicegre50,
    SICEGRE52_DET_BANCOS.sicegre52_importe
    from SICEGRE52_DET_BANCOS
    group by
    SICEGRE52_DET_BANCOS.rela_sicegre50,
    SICEGRE52_DET_BANCOS.sicegre52_importe,
    SICEGRE52_DET_BANCOS.sicegre52_fapl
    having count(SICEGRE52_DET_BANCOS.id_sicegre52) <> 1
    into :id_sicegre52,
         :rela_sicegre50,
         :sicegre52_importe
    do
    begin
        delete from SICEGRE52_DET_BANCOS
        where SICEGRE52_DET_BANCOS.rela_sicegre50 = :rela_sicegre50
        and SICEGRE52_DET_BANCOS.id_sicegre52 <> :id_sicegre52;

        suspend;
    end

    /* -------------------------------------------------------------------------------- */

    for select
    SICINGR51_CAB_BANCOS.id_sicingr51
    from SICINGR51_CAB_BANCOS
    where SICINGR51_CAB_BANCOS.sicingr51_anticipo = 0
    and not exists ( select sicingr50_det_ctacte.id_sicingr50
                   from sicingr50_det_ctacte
                   where sicingr50_det_ctacte.rela_sicingr51 = SICINGR51_CAB_BANCOS.id_sicingr51)
    into :id_sicingr51
    do
    begin
        delete from sicingr51_cab_bancos where sicingr51_cab_bancos.id_sicingr51 = :id_sicingr51;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICINGR88
RETURNS (
    OK INTEGER)
AS
declare variable ID_SICINGR88 bigint;
declare variable ID_SICINGR89 bigint;
declare variable RELA_SICINGR88 bigint;
declare variable RELA_SICCONT10 bigint;
begin
    OK = 1;

    /* ---------------------------------------------------------------------- */
    /*     CORREJIR CUENTAS DE GASTOS DEL CLIENTE PARA AGENCIAS ADUANALES     */
    /* ---------------------------------------------------------------------- */

    for SELECT sicingr88_det_gastos3ros.id_sicingr88
    FROM sicingr70_cab_facturacion
    inner join sicingr88_det_gastos3ros on ( sicingr88_det_gastos3ros.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70)
    where EXISTS ( select *
                   from sicingr77_det_cfdiscancelados
                   where sicingr77_det_cfdiscancelados.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70
                 )
    and not exists ( select *
                     from sicingr74_dep_cfdis
                     where sicingr74_dep_cfdis.rela_sicingr70 = sicingr70_cab_facturacion.id_sicingr70
                    )
    into :id_sicingr88
    do
    begin
        delete from sicingr88_det_gastos3ros where sicingr88_det_gastos3ros.id_sicingr88 = :id_sicingr88;
    end

    update socsyst50_cab_config set socsyst50_cab_config.socsyst50_sicingr89 = 1;

    for select
    max(SICINGR89_DET_POLIZAS.id_sicingr89),
    sicingr89_det_polizas.rela_sicingr88,
    SICINGR89_DET_POLIZAS.rela_siccont10
    from SICINGR89_DET_POLIZAS
    group by sicingr89_det_polizas.rela_sicingr88,
             SICINGR89_DET_POLIZAS.rela_siccont10
    having count(SICINGR89_DET_POLIZAS.id_sicingr89) > 1
    into :id_sicingr89,
         :rela_sicingr88,
         :rela_siccont10
    do
    begin
        delete from sicingr89_det_polizas
        where sicingr89_det_polizas.rela_sicingr88 = :rela_sicingr88
        and SICINGR89_DET_POLIZAS.rela_siccont10 = :rela_siccont10
        and sicingr89_det_polizas.id_sicingr89 <> :id_sicingr89;
    end

    update socsyst50_cab_config set socsyst50_cab_config.socsyst50_sicingr89 = 0;

    /* ---------------------------------------------------------------------- */

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICINGR90
RETURNS (
    ID_COUNT BIGINT,
    ID_MAX BIGINT,
    RELA_SICXMLS01 BIGINT,
    RELA_SICXMLS02 BIGINT)
AS
declare variable ENTRO integer;
declare variable RECURSIVO integer;
begin
    entro = 0;

    for select
    count(sicingr90_cab_impuestos.id_sicingr90),
    max(sicingr90_cab_impuestos.id_sicingr90),
    sicingr90_cab_impuestos.rela_sicxmls01,
    sicingr90_cab_impuestos.rela_sicxmls02
    FROM sicingr90_cab_impuestos
    group BY sicingr90_cab_impuestos.rela_sicxmls01, sicingr90_cab_impuestos.rela_sicxmls02
    having count(sicingr90_cab_impuestos.id_sicingr90) <> 1
    into :id_count,
         :id_max,
         :rela_sicxmls01,
         :rela_sicxmls02
    do
    begin
        delete from sicingr90_cab_impuestos where sicingr90_cab_impuestos.id_sicingr90 = :id_max;
        entro = 1;
        suspend;
    end

    if (entro = 1) then
        select first 1 smx$soc_corrige_sicingr90.id_max
        from smx$soc_corrige_sicingr90
        into :recursivo;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICXMLS41_1
RETURNS (
    RELA_SICINGR01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    RELA_SICXMLS40 BIGINT,
    ID_SICXMLS41 BIGINT,
    SICXMLS41_ENTIDAD VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RELA_SOCMAIN01_SICINGR70 BIGINT,
    RELA_SOCMAIN01_SICINGR01 BIGINT,
    RELA_SOCMAIN01_SICXMLS41 BIGINT)
AS
declare variable RELA_SOCUSUA30_SICINGR70 bigint;
begin
    delete from socusua32_det_documentos where socusua32_det_documentos.socusua32_documento = 'XAXX010101000';
    delete from socusua32_det_documentos where socusua32_det_documentos.socusua32_documento = 'XEXX010101000';

    for select
    sicxmls40_cab_migracion.rela_socmain01,
    sicxmls40_cab_migracion.id_sicxmls40,
    sicxmls41_det_migracion.id_sicxmls41,
    sicxmls41_det_migracion.rela_socusua30,
    sicxmls41_det_migracion.sicxmls41_entidad,
    sicxmls41_det_migracion.sicxmls41_rfc,
    sicxmls41_det_migracion.sicxmls41_uuid
    from sicxmls41_det_migracion
    inner join sicxmls40_cab_migracion on ( sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40 )
    where sicxmls41_det_migracion.sicxmls41_origen = 'F'
    into :rela_socmain01_sicxmls41,
         :rela_sicxmls40,
         :id_sicxmls41,
         :rela_socusua30,
         :sicxmls41_entidad,
         :sicxmls41_rfc,
         :sicxmls41_uuid
    do
    begin
        select
        sicingr70_cab_facturacion.rela_socmain01,
        sicingr70_cab_facturacion.rela_sicingr01
        from sicingr74_dep_cfdis
        inner join sicingr70_cab_facturacion on ( sicingr70_cab_facturacion.id_sicingr70 = sicingr74_dep_cfdis.rela_sicingr70 )
        where sicingr74_dep_cfdis.rela_sicxmls41 = :id_sicxmls41
        into :rela_socmain01_sicingr70,
             :rela_sicingr01;

        select
        cbo_sicingr01_id.rela_socusua30,
        cbo_sicingr01_id.rela_socmain01
        from cbo_sicingr01_id
        where cbo_sicingr01_id.id_sicingr01 = :rela_sicingr01
        into :rela_socusua30_sicingr70,
             :rela_socmain01_sicingr01;

        if (rela_socusua30 <> rela_socusua30_sicingr70) then
        begin
            update sicxmls41_det_migracion set sicxmls41_det_migracion.rela_socusua30 = :rela_socusua30_sicingr70
            where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41;

            suspend;
        end
        else
        begin
            if (not (rela_socmain01_sicxmls41 = rela_socmain01_sicingr70 and rela_socmain01_sicxmls41 = rela_socmain01_sicingr01) ) then
            begin
                update sicxmls40_cab_migracion set sicxmls40_cab_migracion.rela_socmain01 = :rela_socmain01_sicingr70
                where sicxmls40_cab_migracion.id_sicxmls40 = :rela_sicxmls40;
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICXMLS41_2
RETURNS (
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCUSUA30 BIGINT,
    ID_SICXMLS41 BIGINT,
    SICXMLS41_ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SICXMLS41_RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD_SOC VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC_SOC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
begin
    for select
    sicxmls40_cab_migracion.rela_socmain01,
    socusua30_cab_entidades.id_socusua30,
    sicxmls41_det_migracion.id_sicxmls41,
    sicxmls41_det_migracion.sicxmls41_entidad,
    socsyst10_det_entradas.socsyst10_codigo,
    socusua30_cab_entidades.socusua30_apellido_pat,
    socusua30_cab_entidades.socusua30_apellido_mat,
    socusua30_cab_entidades.socusua30_nombre_razsoc,
    sicxmls41_det_migracion.sicxmls41_rfc
    from sicxmls41_det_migracion
    inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = sicxmls41_det_migracion.rela_socusua30)
    inner join sicxmls40_cab_migracion on (sicxmls40_cab_migracion.id_sicxmls40 = sicxmls41_det_migracion.rela_sicxmls40)
    inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = sicxmls40_cab_migracion.rela_socmain01)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10)
    where sicxmls41_det_migracion.sicxmls41_origen = 'F'
    into :rela_socmain01,
         :rela_socusua30,
         :id_sicxmls41,
         :sicxmls41_entidad,
         :socsyst10_codigo,
         :socusua30_apellido_pat,
         :socusua30_apellido_mat,
         :socusua30_nombre_razsoc,
         :sicxmls41_rfc
    do
    begin
        sicxmls41_rfc = trim(upper(sicxmls41_rfc));

        if (socsyst10_codigo = 'FISICO') then
            entidad_soc = trim(:socusua30_apellido_pat) || ' ' ||  trim(:socusua30_apellido_mat) || ', ' || trim(:socusua30_nombre_razsoc);
        else
            entidad_soc = trim(:socusua30_nombre_razsoc);

        entidad_soc = trim(upper(entidad_soc));

        if (CHAR_LENGTH(entidad_soc) > 400) then
            entidad_soc = SUBSTRING (entidad_soc FROM 1 FOR 400);

        rfc_soc = null;

        select socusua32_det_documentos.socusua32_documento
        from socusua32_det_documentos
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua32_det_documentos.rela_socsyst10_td001)
        where socusua32_det_documentos.rela_socusua30 = :rela_socusua30
        and socsyst10_det_entradas.socsyst10_codigo = 'RFC'
        into :rfc_soc;

        rfc_soc = iif(rfc_soc is null, '', trim(upper(rfc_soc)));

        if (rfc_soc <> '' and rfc_soc <> sicxmls41_rfc) then
        BEGIN
            if (sicxmls41_rfc <> 'XAXX010101000' and sicxmls41_rfc <> 'XEXX010101000') then
            BEGIN
                update sicxmls41_det_migracion set sicxmls41_det_migracion.sicxmls41_entidad = :entidad_soc,
                                                   sicxmls41_det_migracion.sicxmls41_rfc = :rfc_soc
                where sicxmls41_det_migracion.id_sicxmls41 = :id_sicxmls41;

                suspend;
            END
        END
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_CORRIGE_SICXMLS41_3
RETURNS (
    TIPO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ID_UPDATE BIGINT,
    RELA_SICCONT10 BIGINT,
    SICINGR50_IMPORTE DOUBLE PRECISION,
    SICXMLS41_UUID_IMPORTE DOUBLE PRECISION)
AS
begin
    for

    select
    'C',
    sicingr50_det_ctacte.id_sicingr50,
    sicingr50_det_ctacte.rela_siccont10,
    sicingr50_det_ctacte.sicingr50_importe
    from sicingr50_det_ctacte
    where sicingr50_det_ctacte.rela_sicingr51 is null

    union all

    SELECT
    'P',
    sicegre50_det_ctacte.id_sicegre50,
    sicegre50_det_ctacte.rela_siccont10,
    sicegre50_det_ctacte.sicegre50_importe
    from sicegre50_det_ctacte
    where sicegre50_det_ctacte.rela_sicegre51 is null

    into :tipo,
         :id_update,
         :rela_siccont10,
         :sicingr50_importe
    do
    begin
        sicxmls41_uuid_importe = null;

        select
        sicxmls41_det_migracion.sicxmls41_uuid_importe
        from sicxmls41_det_migracion
        where sicxmls41_det_migracion.rela_siccont10 = :rela_siccont10
        and sicxmls41_det_migracion.sicxmls41_cambio > 1
        into :sicxmls41_uuid_importe;

        if (sicxmls41_uuid_importe is not null and sicingr50_importe <> sicxmls41_uuid_importe) then
        begin
            if (tipo = 'C') then
                UPDATE sicingr50_det_ctacte set sicingr50_det_ctacte.sicingr50_importe = :sicxmls41_uuid_importe
                where sicingr50_det_ctacte.id_sicingr50 = :id_update;
            else if (tipo = 'P') then
                UPDATE sicegre50_det_ctacte set sicegre50_det_ctacte.sicegre50_importe = :sicxmls41_uuid_importe
                where sicegre50_det_ctacte.id_sicegre50 = :id_update;

            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_EMPRESA_BORRA (
    ID_SOCMAIN01 BIGINT)
RETURNS (
    MENSAJE VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SICCONT10 bigint;
declare variable ID_SOCUSUA30 bigint;
begin
    id_siccont10 = null;

    select first 1
    siccont10_cab_polizas.id_siccont10
    from siccont10_cab_polizas
    where siccont10_cab_polizas.rela_socmain01 = :id_socmain01
    into :id_siccont10;

    select socmain01_cab_empresas.rela_socusua30
    from socmain01_cab_empresas
    where socmain01_cab_empresas.id_socmain01 = :id_socmain01
    into :id_socusua30;

    if (id_siccont10 is not null) then
    begin
        mensaje = 'No puede Eliminar la Empresa. Tiene pólizas generadas';
        suspend;
    end
    else
    begin
        delete from socmain01_cab_empresas where socmain01_cab_empresas.id_socmain01 = :id_socmain01;

        delete from socusua01_cab_usuarios where socusua01_cab_usuarios.rela_socusua30 = :id_socusua30;

        delete from socusua30_cab_entidades where socusua30_cab_entidades.id_socusua30 = :id_socusua30;
    end

end^


CREATE OR ALTER PROCEDURE SMX$SOC_EMPRESAS (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCMAIN01 BIGINT,
    TIPO_PERSONA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_NOMCOMERCIAL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_SATUSER VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCMAIN01_SATPASS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    REGIMEN_FISCAL VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CORREOS VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SALDO_FOLIOS INTEGER)
AS
declare variable ID_SOCUSUA01 integer;
declare variable SOCUSUA35_INTERNET varchar(400);
begin
    id_socusua01 = null;

    for select
    cbo_socmain01_all.id_socmain01,
    cbo_socmain01_all.socmain01_nomcomercial,
    cbo_socmain01_all.socmain01_satuser,
    cbo_socmain01_all.socmain01_satpass,
    cbo_socmain01_all.rfc
    from cbo_socmain01_all
    inner join socusua04_det_empresas on (cbo_socmain01_all.id_socmain01 = socusua04_det_empresas.rela_socmain01)
    inner join socusua01_cab_usuarios on (socusua04_det_empresas.rela_socusua01 = socusua01_cab_usuarios.id_socusua01)
    WHERE socusua01_cab_usuarios.socusua01_usuario = :usuario
    into :id_socmain01,
         :socmain01_nomcomercial,
         :socmain01_satuser,
         :socmain01_satpass,
         :rfc
    do
    begin
        id_socusua01 = 1;
        correos = '';

        SELECT
        SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_comprados) -
        SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_consumidos)
        FROM SOCMAIN11_MOV_FOLIOS
        INNER JOIN socmain10_det_contadores ON (socmain10_det_contadores.id_socmain10 = SOCMAIN11_MOV_FOLIOS.rela_socmain10)
        WHERE socmain10_det_contadores.rela_socmain01 = :id_socmain01
        INTO :saldo_folios;

        for select trim(socusua35_det_internet.socusua35_internet)
        from socmain01_cab_empresas
        inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30 )
        inner join socusua35_det_internet on ( socusua35_det_internet.rela_socusua30 = socusua30_cab_entidades.id_socusua30 )
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01 )
        where socmain01_cab_empresas.id_socmain01 = :id_socmain01
        and socsyst10_det_entradas.socsyst10_codigo = 'CORREO'
        and socusua35_det_internet.socusua35_internet is not null
        into :socusua35_internet
        do
        begin
            correos = correos || :socusua35_internet || ';';
        end

        select socsyst10_det_entradas.socsyst10_descripcion
        from socmain01_cab_empresas
        inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30 )
        inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10 )
        where socmain01_cab_empresas.id_socmain01 = :id_socmain01
        into :tipo_persona;

        select
        '(' || trim(socsyst10_det_entradas.socsyst10_codigo) || ') ' || trim(socsyst10_det_entradas.socsyst10_descripcion)
        from socmain01_cab_empresas
        inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01)
        where socmain01_cab_empresas.id_socmain01 = :id_socmain01
        into regimen_fiscal;

        suspend;
    end

    if (id_socusua01 is null) then
    begin
        select socusua01_cab_usuarios.id_socusua01
        from socusua01_cab_usuarios
        where socusua01_cab_usuarios.socusua01_usuario = :usuario
        into :id_socusua01;

        if (id_socusua01 is not null) then
        begin
            for select
            cbo_socmain01.id_socmain01,
            cbo_socmain01.socmain01_nomcomercial,
            cbo_socmain01.socmain01_satuser,
            cbo_socmain01.socmain01_satpass,
            cbo_socmain01.rfc
            from cbo_socmain01
            into :id_socmain01,
                 :socmain01_nomcomercial,
                 :socmain01_satuser,
                 :socmain01_satpass,
                 :rfc
            do
            begin
                correos = '';

                SELECT
                SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_comprados) -
                SUM(SOCMAIN11_MOV_FOLIOS.socmain11_folios_consumidos)
                FROM SOCMAIN11_MOV_FOLIOS
                INNER JOIN socmain10_det_contadores ON (socmain10_det_contadores.id_socmain10 = SOCMAIN11_MOV_FOLIOS.rela_socmain10)
                WHERE socmain10_det_contadores.rela_socmain01 = :id_socmain01
                INTO :saldo_folios;

                for select trim(socusua35_det_internet.socusua35_internet)
                from socmain01_cab_empresas
                inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30 )
                inner join socusua35_det_internet on ( socusua35_det_internet.rela_socusua30 = socusua30_cab_entidades.id_socusua30 )
                inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01 )
                where socmain01_cab_empresas.id_socmain01 = :id_socmain01
                and socsyst10_det_entradas.socsyst10_codigo = 'CORREO'
                and socusua35_det_internet.socusua35_internet is not null
                into :socusua35_internet
                do
                begin
                    correos = correos || :socusua35_internet || ';';
                end

                select socsyst10_det_entradas.socsyst10_descripcion
                from socmain01_cab_empresas
                inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socmain01_cab_empresas.rela_socusua30 )
                inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua30_cab_entidades.rela_socsyst10 )
                where socmain01_cab_empresas.id_socmain01 = :id_socmain01
                into :tipo_persona;

                select
                '(' || trim(socsyst10_det_entradas.socsyst10_codigo) || ') ' || trim(socsyst10_det_entradas.socsyst10_descripcion)
                from socmain01_cab_empresas
                inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socmain01_cab_empresas.rela_socsyst10_sat01)
                where socmain01_cab_empresas.id_socmain01 = :id_socmain01
                into regimen_fiscal;
                suspend;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_EMPRESAS_CREA (
    ID_SOCMAIN90 BIGINT)
AS
declare variable SOCMAIN90_SOCUSUA10 bigint;
declare variable SOCMAIN90_SOCSYST10_BAN01 bigint;
declare variable SOCMAIN90_SOCSYST10_CTM01 bigint;
declare variable SOCMAIN90_SOCSYST10_TS001 bigint;
declare variable SOCMAIN90_SOCSYST10_SAT01 bigint;
declare variable SOCMAIN90_SOCMAIN80 bigint;
declare variable SOCMAIN90_SOCMAIN01 bigint;
declare variable SOCMAIN90_SOCUSUA01 bigint;
declare variable SOCMAIN90_TPERSONA varchar(1);
declare variable SOCMAIN90_RAZNOMBRE varchar(400);
declare variable SOCMAIN90_APELLIDO_PAT varchar(400);
declare variable SOCMAIN90_APELLIDO_MAT varchar(400);
declare variable SOCMAIN90_USER_SYS varchar(50);
declare variable SOCMAIN90_PASS_SYS varchar(50);
declare variable SOCMAIN90_USER_SAT varchar(50);
declare variable SOCMAIN90_PASS_SAT varchar(50);
declare variable SOCMAIN90_NOMCOMERCIAL varchar(400);
declare variable SOCMAIN90_CORREO varchar(400);
declare variable SOCMAIN90_RFC varchar(50);
declare variable SOCMAIN90_CUENTA varchar(400);
declare variable SOCMAIN90_TIPO_FOLIO varchar(1);
declare variable SOCMAIN90_CONACCESO varchar(1);
declare variable RELA_SOCSYST10_TP001 bigint;
declare variable RELA_SOCSYST10_TD001 bigint;
declare variable RELA_SOCSYST10_TD001_REGPAT bigint;
declare variable RELA_SOCSYST10_TDI01 bigint;
declare variable RELA_SOCSYST10_PCT01 integer;
declare variable RELA_SOCSYST10_CA001 bigint;
declare variable RELA_SOCSYST10_CO001_POLIZAS bigint;
declare variable RELA_SOCSYST10_CO001_NOMI_EMP bigint;
declare variable RELA_SOCSYST10_CO001_NOMI_PER bigint;
declare variable RELA_SOCSYST10_CO001_FACTURA bigint;
declare variable RELA_SOCSYST10_CO001_PAGO bigint;
declare variable RELA_SOCSYST10_TCT01 bigint;
declare variable RELA_SOCSYST10_TDD01 bigint;
declare variable ID_SOCUSUA30_NEW bigint;
declare variable ID_SOCMAIN01_NEW bigint;
declare variable ID_SOCUSUA01_NEW bigint;
declare variable ID_SOCMAIN20_NEW bigint;
declare variable ID_SOCMAIN21_NEW bigint;
declare variable ID_SICXMLS01_NEW bigint;
declare variable CONACCESO integer;
declare variable STATUS_CREA_CATCTA varchar(50);
declare variable ID_SICCONT02_BANCO_DEFAULT bigint;
declare variable ID_SOCSYST06_NIVEL bigint;
declare variable TIPO_FOLIO integer;
declare variable RELA_SICCONT02 bigint;
declare variable ID_SICCONT02_TARJET bigint;
declare variable RELA_SICCONT02_CTRACTA bigint;
declare variable ID_SICCONT02_TARJET_CTRACTA bigint;
declare variable SICXMLS02_IMPUESTO varchar(400);
declare variable SICXMLS02_TIPO varchar(1);
declare variable SICXMLS02_RETENIDO integer;
declare variable SICXMLS02_TASA double precision;
declare variable SOCMAIN90_USER_CFDI varchar(50);
declare variable SOCMAIN90_PASS_CFDI varchar(50);
declare variable SOCMAIN90_USER_PAC varchar(50);
declare variable SOCMAIN90_PASS_PAC varchar(50);
declare variable SOCMAIN90_NOCERTIFICADO varchar(50);
declare variable SOCMAIN90_PAC varchar(50);
declare variable SOCMAIN90_PCSD_SAT varchar(50);
declare variable SOCMAIN90_UUID_SMX_KEY varchar(50);
declare variable SOCMAIN90_UUID_SMX_CER varchar(50);
declare variable SOCMAIN90_CODPOSTAL varchar(10);
declare variable SOCMAIN90_REGPATRONAL varchar(400);
begin
    select
    socmain90_tmp_socmain01.socmain90_socusua10,
    socmain90_tmp_socmain01.socmain90_socsyst10_ban01,
    socmain90_tmp_socmain01.socmain90_socsyst10_ctm01,
    socmain90_tmp_socmain01.socmain90_socsyst10_ts001,
    socmain90_tmp_socmain01.socmain90_socmain80,
    socmain90_tmp_socmain01.socmain90_socmain01,
    socmain90_tmp_socmain01.socmain90_socusua01,
    socmain90_tmp_socmain01.socmain90_tpersona,
    socmain90_tmp_socmain01.socmain90_raznombre,
    socmain90_tmp_socmain01.socmain90_apellido_pat,
    socmain90_tmp_socmain01.socmain90_apellido_mat,
    socmain90_tmp_socmain01.socmain90_user_sys,
    socmain90_tmp_socmain01.socmain90_pass_sys,
    socmain90_tmp_socmain01.socmain90_user_sat,
    socmain90_tmp_socmain01.socmain90_pass_sat,
    socmain90_tmp_socmain01.socmain90_nomcomercial,
    socmain90_tmp_socmain01.socmain90_correo,
    socmain90_tmp_socmain01.socmain90_rfc,
    socmain90_tmp_socmain01.socmain90_cuenta,
    socmain90_tmp_socmain01.socmain90_tipo_folio,
    socmain90_tmp_socmain01.socmain90_conacceso,
    socmain90_tmp_socmain01.socmain90_user_cfdi,
    socmain90_tmp_socmain01.socmain90_pass_cfdi,
    socmain90_tmp_socmain01.socmain90_user_pac,
    socmain90_tmp_socmain01.socmain90_pass_pac,
    socmain90_tmp_socmain01.socmain90_nocertificdo,
    socmain90_tmp_socmain01.socmain90_pac,
    socmain90_tmp_socmain01.socmain90_pcsd_sat,
    socmain90_tmp_socmain01.socmain90_uuid_smx_key,
    socmain90_tmp_socmain01.socmain90_uuid_smx_cer,
    socmain90_tmp_socmain01.socmain90_codpostal,
    socmain90_tmp_socmain01.socmain90_socsyst10_sat01,
    socmain90_tmp_socmain01.socmain90_regpatronal
    from socmain90_tmp_socmain01
    where socmain90_tmp_socmain01.id_socmain90 = :id_socmain90
    into :socmain90_socusua10,
         :socmain90_socsyst10_ban01,
         :socmain90_socsyst10_ctm01,
         :socmain90_socsyst10_ts001,
         :socmain90_socmain80,
         :socmain90_socmain01,
         :socmain90_socusua01,
         :socmain90_tpersona,
         :socmain90_raznombre,
         :socmain90_apellido_pat,
         :socmain90_apellido_mat,
         :socmain90_user_sys,
         :socmain90_pass_sys,
         :socmain90_user_sat,
         :socmain90_pass_sat,
         :socmain90_nomcomercial,
         :socmain90_correo,
         :socmain90_rfc,
         :socmain90_cuenta,
         :socmain90_tipo_folio,
         :socmain90_conacceso,
         :socmain90_user_cfdi,
         :socmain90_pass_cfdi,
         :socmain90_user_pac,
         :socmain90_pass_pac,
         :socmain90_nocertificado,
         :socmain90_pac,
         :socmain90_pcsd_sat,
         :socmain90_uuid_smx_key,
         :socmain90_uuid_smx_cer,
         :socmain90_codpostal,
         :socmain90_socsyst10_sat01,
         :socmain90_regpatronal;

    if (socmain90_tpersona = 'F') then
        select CBO_SOCSYST10_TP001.id_socsyst10
        from CBO_SOCSYST10_TP001
        where CBO_SOCSYST10_TP001.socsyst10_codigo = 'FISICO'
        into :rela_socsyst10_tp001;
    else
        select CBO_SOCSYST10_TP001.id_socsyst10
        from CBO_SOCSYST10_TP001
        where CBO_SOCSYST10_TP001.socsyst10_codigo = 'MORAL'
        into :rela_socsyst10_tp001;

    select cbo_socsyst10_td001.id_socsyst10
    from cbo_socsyst10_td001
    where cbo_socsyst10_td001.socsyst10_codigo = 'RFC'
    into :rela_socsyst10_td001;

    select cbo_socsyst10_td001.id_socsyst10
    from cbo_socsyst10_td001
    where cbo_socsyst10_td001.socsyst10_codigo = 'REGISTROPATRONAL'
    into :rela_socsyst10_td001_regpat;

    if (socmain90_conacceso = 'S') then
        conacceso = 1;
    else
        conacceso = 0;

    select cbo_socsyst10_tdi01.id_socsyst10
    from cbo_socsyst10_tdi01
    where cbo_socsyst10_tdi01.socsyst10_codigo = 'CORREO'
    into :rela_socsyst10_tdi01;

    select socsyst06_det_niveles.id_socsyst06
    from SOCSYST05_CAB_ARBOLES
    inner join socsyst06_det_niveles on (socsyst06_det_niveles.rela_socsyst05 = SOCSYST05_CAB_ARBOLES.id_socsyst05)
    where SOCSYST05_CAB_ARBOLES.socsyst05_codigo = 'SOCMAIN21'
    and socsyst06_det_niveles.socsyst06_nivel = 1
    into :id_socsyst06_nivel;

    SELECT first 1
    socusua15_det_perfiles.rela_socsyst10_ca001
    FROM SOCUSUA10_CAB_MENU
    INNER JOIN socusua15_det_perfiles ON ( socusua15_det_perfiles.rela_socusua10 = SOCUSUA10_CAB_MENU.id_socusua10 )
    INNER JOIN socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = socusua15_det_perfiles.rela_socsyst10_ca001 )
    WHERE SOCUSUA10_CAB_MENU.id_socusua10 = :socmain90_socusua10
    and socsyst10_det_entradas.socsyst10_codigo <> 'ADMIN'
    into :rela_socsyst10_ca001;

    select CBO_SOCSYST10_CO001.ID_SOCSYST10
    from CBO_SOCSYST10_CO001
    where CBO_SOCSYST10_CO001.SOCSYST10_CODIGO = 'SICCONT10'
    into :rela_socsyst10_co001_polizas;

    select CBO_SOCSYST10_CO001.ID_SOCSYST10
    from CBO_SOCSYST10_CO001
    where CBO_SOCSYST10_CO001.SOCSYST10_CODIGO = 'SICNOMI70'
    into :rela_socsyst10_co001_nomi_emp;

    select CBO_SOCSYST10_CO001.ID_SOCSYST10
    from CBO_SOCSYST10_CO001
    where CBO_SOCSYST10_CO001.SOCSYST10_CODIGO = 'SICNOMI72'
    into :rela_socsyst10_co001_nomi_per;

    select CBO_SOCSYST10_CO001.ID_SOCSYST10
    from CBO_SOCSYST10_CO001
    where CBO_SOCSYST10_CO001.SOCSYST10_CODIGO = 'SICINGR70'
    into :rela_socsyst10_co001_factura;

    select CBO_SOCSYST10_CO001.ID_SOCSYST10
    from CBO_SOCSYST10_CO001
    where CBO_SOCSYST10_CO001.SOCSYST10_CODIGO = 'SICPAGO70'
    into :rela_socsyst10_co001_pago;

    if (socmain90_tipo_folio = 'E') then
        tipo_folio = 0;
