    where sicxmls01_cab_parametros.rela_socmain01 = :socmain90_socmain01
    into :rela_socsyst10_tct01,
         :rela_siccont02,
         :rela_siccont02_ctracta,
         :sicxmls02_impuesto,
         :sicxmls02_tipo,
         :sicxmls02_retenido,
         :sicxmls02_tasa
    do
    begin
        select tmp_siccont01_siccont02.id_siccont02_tarjet
        from tmp_siccont01_siccont02
        where tmp_siccont01_siccont02.usuario = current_user
        and tmp_siccont01_siccont02.id_siccont02_source = :rela_siccont02
        into :id_siccont02_tarjet;

        select tmp_siccont01_siccont02.id_siccont02_tarjet
        from tmp_siccont01_siccont02
        where tmp_siccont01_siccont02.usuario = current_user
        and tmp_siccont01_siccont02.id_siccont02_source = :rela_siccont02_ctracta
        into :id_siccont02_tarjet_ctracta;

        insert into sicxmls02_det_impuestos(sicxmls02_det_impuestos.rela_sicxmls01,
                                            sicxmls02_det_impuestos.rela_socsyst10_tct01,
                                            sicxmls02_det_impuestos.rela_siccont02,
                                            sicxmls02_det_impuestos.rela_siccont02_ctracta,
                                            sicxmls02_det_impuestos.sicxmls02_impuesto,
                                            sicxmls02_det_impuestos.sicxmls02_tipo,
                                            sicxmls02_det_impuestos.sicxmls02_retenido,
                                            sicxmls02_det_impuestos.sicxmls02_tasa)
        values(:id_sicxmls01_new,
               :rela_socsyst10_tct01,
               :id_siccont02_tarjet,
               :id_siccont02_tarjet_ctracta,
               :sicxmls02_impuesto,
               :sicxmls02_tipo,
               :sicxmls02_retenido,
               :sicxmls02_tasa);
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_EMPRESAS_LOG (
    INSTANCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LOGON INTEGER)
RETURNS (
    ID_SOCMAIN01 BIGINT)
AS
begin
  ID_SOCMAIN01 = 1;
  execute procedure smx$soc_empresas_seg trim(upper(:instancia)),
                                         trim(upper(:empresa)),
                                         trim(upper(:rfc)),
                                         trim(upper(:usuario)),
                                         :logon;
  suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_EMPRESAS_SEG (
    INSTANCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA VARCHAR(1200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    RFC VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LOGON INTEGER)
AS
declare variable SQL varchar(1000);
declare variable SMX_RFC varchar(50);
declare variable SMX_LOGON integer;
begin
    usuario = 'JAM$_' || trim(upper(:usuario));
    rfc = trim(upper(rfc));

    SMX_RFC = NULL;
    SMX_LOGON = NULL;

    SQL = 'SELECT SMX_RFC,SMX_LOGON FROM SMX_EMPRESAS WHERE SMX_INSTANCIA = ''' ||
          :INSTANCIA || ''' AND SMX_USUARIO = ''' || :usuario || ''' AND SMX_RFC = ''' ||:RFC || '''';

    execute statement :SQL
    on external 'SMXSEG'
    AS
    USER 'SYSDBA' PASSWORD 'masterkey'
    into :SMX_RFC,
         :SMX_LOGON;

    SMX_LOGON = IIF(SMX_LOGON IS NULL, 0, SMX_LOGON);

    if (:SMX_RFC IS NOT NULL) then
    BEGIN
        SQL =  'UPDATE SMX_EMPRESAS set SMX_FECHA = ''' || current_timestamp || ''' WHERE SMX_INSTANCIA = '''
                                                        || :INSTANCIA
                                                        || ''' AND SMX_USUARIO = ''' ||:usuario
                                                        || ''' AND SMX_RFC = ''' ||:RFC || '''';
        EXECUTE STATEMENT :SQL
        on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

        if (logon = 1 and SMX_LOGON = 0) then
        begin
            SQL =  'UPDATE SMX_EMPRESAS set SMX_LOGON = 1 WHERE SMX_INSTANCIA = '''
                                                        || :INSTANCIA
                                                        || ''' AND SMX_USUARIO = ''' ||:usuario
                                                        || ''' AND SMX_RFC = ''' ||:RFC || '''';
            EXECUTE STATEMENT :SQL
            on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';    
        end
    END
    ELSE
    BEGIN
        SQL = 'INSERT INTO SMX_EMPRESAS(SMX_INSTANCIA,SMX_RFC,SMX_EMPRESA,SMX_FECHA,SMX_USUARIO,SMX_LOGON) VALUES(''' ||
              :instancia || ''',''' || :rfc || ''',''' || :empresa || ''',''' || current_timestamp || ''',''' ||
              :usuario || ''',' || :logon || ')';

        EXECUTE STATEMENT :SQL
        on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

    END
end^


CREATE OR ALTER PROCEDURE SMX$SOC_FUNCION_DEVELOPER (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CODMENU VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    URLFUNCION VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCUSUA11 BIGINT,
    SOCUSUA11_DESCRIPCION VARCHAR(800) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCUSUA12_BTO_ALTA INTEGER,
    SOCUSUA12_BTO_BAJA INTEGER,
    SOCUSUA12_BTO_MODI INTEGER,
    SOCUSUA12_BTO_REPO INTEGER,
    SOCUSUA12_BTO_CONS INTEGER,
    SOCUSUA12_BTO_INFO INTEGER)
AS
begin
    select first 1
    socusua12_dep_funciones.rela_socusua11,
    socusua11_arb_menu.socusua11_descripcion,
    socusua12_dep_funciones.socusua12_bto_alta,
    socusua12_dep_funciones.socusua12_bto_baja,
    socusua12_dep_funciones.socusua12_bto_modi,
    socusua12_dep_funciones.socusua12_bto_repo,
    socusua12_dep_funciones.socusua12_bto_cons,
    socusua12_dep_funciones.socusua12_bto_info
    from socusua01_cab_usuarios
    inner join socusua02_det_organizacion on (socusua01_cab_usuarios.id_socusua01 = socusua02_det_organizacion.rela_socusua01)
    inner join socusua15_det_perfiles on (socusua02_det_organizacion.rela_socmain01 = socusua15_det_perfiles.rela_socmain01) and (socusua02_det_organizacion.rela_socmain20 = socusua15_det_perfiles.rela_socmain20) and (socusua02_det_organizacion.rela_socmain21 = socusua15_det_perfiles.rela_socmain21) and (socusua02_det_organizacion.rela_socsyst10_ca001 = socusua15_det_perfiles.rela_socsyst10_ca001)
    inner join socusua10_cab_menu on (socusua15_det_perfiles.rela_socusua10 = socusua10_cab_menu.id_socusua10)
    inner join socusua11_arb_menu on (socusua10_cab_menu.id_socusua10 = socusua11_arb_menu.rela_socusua10)
    inner join socusua12_dep_funciones on (socusua11_arb_menu.id_socusua11 = socusua12_dep_funciones.rela_socusua11)
    inner join socsyst01_cab_funciones on (socusua12_dep_funciones.rela_socsyst01 = socsyst01_cab_funciones.id_socsyst01)
    where socusua01_cab_usuarios.socusua01_usuario = :usuario
    and socusua10_cab_menu.socusua10_codigo = :codmenu
    and socsyst01_cab_funciones.socsyst01_url_clase = :urlfuncion
    into :id_socusua11,
         :socusua11_descripcion,
         :socusua12_bto_alta,
         :socusua12_bto_baja,
         :socusua12_bto_modi,
         :socusua12_bto_repo,
         :socusua12_bto_cons,
         :socusua12_bto_info;
    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_INSTANCIA
RETURNS (
    DATABASE_NAME VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    DATABASE_PATH VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INSTANCIA_NAME VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable PATH_NAME_DB varchar(1000);
declare variable RESULT varchar(50);
begin
  select MON$DATABASE.mon$database_name
  from MON$DATABASE INTO :PATH_NAME_DB;

  for select SMX$UTIL_STRTOKENIZE.result
  from SMX$UTIL_STRTOKENIZE(:path_name_db, '\')
  into :result
  do
  begin
    database_name = result;
  end

  database_path = replace(path_name_db, database_name, '');

  instancia_name = replace(database_name, '.KIT', '');

  suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_LOGON (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    INSTANCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCUSUA01 BIGINT)
AS
declare variable SMXSQL varchar(400);
declare variable USUARIO_EXISTE varchar(50);
declare variable FECHA timestamp;
declare variable ID_SOCUSUA01_LOCAL bigint;
begin
    usuario = trim(UPPER(:usuario));
    instancia = trim(UPPER(:instancia));

    select smx$soc_logon_addsoporte.id_socusua01
    from smx$soc_logon_addsoporte(:usuario, :clave)
    into :id_socusua01;

    /* si es nulo no es soporte... si es soporte no registra log en SMX_USERS_LOGON_LOGS */

    id_socusua01_local = null;

    select socusua01_cab_usuarios.id_socusua01
    from socusua01_cab_usuarios
    where socusua01_cab_usuarios.socusua01_usuario = :usuario
    and socusua01_cab_usuarios.socusua01_clave = :clave
    into :id_socusua01_local;
    
    usuario_existe = null;
    Select smx$soc_seguridad.usuario_existe
    from smx$soc_seguridad( 'EXISTE', :usuario, null)
    into :usuario_existe;
    
    if (id_socusua01_local is not null and usuario_existe is not null) then
    begin
        if (id_socusua01 is not null) then
            SMXSQL = 'update SMX_USERS set SMX_SOPORTE = 1 where trim(upper(SMX_USUARIO)) = ''JAM$_' || :usuario || '''';
        else
            SMXSQL = 'update SMX_USERS set SMX_SOPORTE = 0 where trim(upper(SMX_USUARIO)) = ''JAM$_' || :usuario || '''';
    
        execute statement :SMXSQL
        on external 'SMXSEG'
        AS USER 'SYSDBA' PASSWORD 'masterkey';

        /* ------------------------------------------------------------------------------------------------------------ */

        fecha = null;
        usuario_existe = null;

        SMXSQL = 'SELECT FIRST 1 SMX_USUARIO FROM SMX_USERS_LOGON_LOGS WHERE SMX_USUARIO = ''JAM$_' || :usuario || ''' and SMX_INSTANCIA = ''' || :instancia || '''';
        execute statement :SMXSQL
        on external 'SMXSEG'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :usuario_existe;

        fecha = current_timestamp;

        if (usuario_existe is not null) then
        begin
            SMXSQL =  'UPDATE SMX_USERS_LOGON_LOGS set SMX_FECHA = ''' || :fecha || '''' ||
                      ' WHERE SMX_INSTANCIA = ''' || :instancia || ''' AND smx_usuario = ''JAM$_' || :usuario || '''';
            EXECUTE STATEMENT :SMXSQL
            on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';
        end
        else
        begin
            SMXSQL =  'INSERT INTO smx_users_logon_logs(smx_usuario, smx_instancia, SMX_FECHA) VALUES(''JAM$_' || :usuario || ''',''' || :instancia || ''',''' || :fecha || ''')';
            EXECUTE STATEMENT :SMXSQL
            on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';
        end

        id_socusua01 = :id_socusua01_local;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_LOGON_ADDSOPORTE (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCUSUA01 BIGINT)
AS
declare variable SMXSQL varchar(2000);
declare variable ID_SOCUSUA01_SOVIVEMX bigint;
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
declare variable SOCUSUA01_CLAVE varchar(50);
declare variable SOCUSUA01_CLAVE_LOCAL varchar(50);
declare variable ID_SOCUSUA30 bigint;
declare variable ID_SOCSYST10 bigint;
declare variable ID_SOCSYST10_CARGO bigint;
declare variable RELA_SOCMAIN01 bigint;
declare variable RELA_SOCMAIN20 bigint;
declare variable RELA_SOCMAIN21 bigint;
declare variable RELA_SOCUSUA10_MENU bigint;
begin
    id_socusua01 = null;
    id_socusua01_sovivemx = null;

    SMXSQL = 'select id_socusua01, ' ||
             'socusua30_apellido_pat, ' ||
             'socusua30_apellido_mat, ' ||
             'socusua30_nombre_razsoc, ' ||
             'socusua01_clave ' ||
             'from socusua01_cab_usuarios ' ||
             'inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socusua01_cab_usuarios.rela_socusua30 ) ' ||
             'where socusua01_cab_usuarios.socusua01_usuario = ''' || :usuario || '''' ||
             ' and socusua01_cab_usuarios.socusua01_acceso = 1';

    execute statement :SMXSQL
    on external 'SOVIMEX'
    AS USER 'SYSDBA' PASSWORD 'masterkey'
    into :id_socusua01_sovivemx,
         :socusua30_apellido_pat,
         :socusua30_apellido_mat,
         :socusua30_nombre_razsoc,
         :socusua01_clave;

    if (id_socusua01_sovivemx is not null) then
    begin
        select
        socusua01_cab_usuarios.id_socusua01,
        socusua01_cab_usuarios.socusua01_clave
        from socusua01_cab_usuarios
        where socusua01_cab_usuarios.socusua01_usuario = :usuario
        into :id_socusua01,
             :socusua01_clave_local;

        if (id_socusua01 is not null and socusua01_clave <> socusua01_clave_local) then
        begin
            update socusua01_cab_usuarios set socusua01_cab_usuarios.socusua01_clave = :socusua01_clave
            where socusua01_cab_usuarios.id_socusua01 = :id_socusua01;
        end

        if (id_socusua01 is null) then
        begin
            select cbo_socsyst10_tp001.id_socsyst10
            from cbo_socsyst10_tp001
            where cbo_socsyst10_tp001.socsyst10_codigo = 'FISICO'
            into :id_socsyst10;

            select cbo_socsyst10_CA001.id_socsyst10
            from cbo_socsyst10_CA001
            where cbo_socsyst10_CA001.socsyst10_codigo = 'SMXSOPORTE'
            into :id_socsyst10_cargo;

            insert into socusua30_cab_entidades(socusua30_cab_entidades.rela_socsyst10,
                                                    socusua30_cab_entidades.socusua30_apellido_pat,
                                                    socusua30_cab_entidades.socusua30_apellido_mat,
                                                    socusua30_cab_entidades.socusua30_nombre_razsoc,
                                                    socusua30_cab_entidades.socusua30_fnac_const,
                                                    socusua30_cab_entidades.socusua30_extranjero)
            values(:id_socsyst10,
                       :socusua30_apellido_pat,
                       :socusua30_apellido_mat,
                       :socusua30_nombre_razsoc,
                       current_date,
                       0);

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA30'
            INTO :ID_SOCUSUA30;

            insert into socusua01_cab_usuarios(socusua01_cab_usuarios.rela_socusua30,
                                                   socusua01_cab_usuarios.socusua02_codigo,
                                                   socusua01_cab_usuarios.socusua01_usuario,
                                                   socusua01_cab_usuarios.socusua01_clave,
                                                   socusua01_cab_usuarios.socusua01_activo,
                                                   socusua01_cab_usuarios.socusua01_acceso)
            VALUES(:id_socusua30,
                       'SOPORTE' || :ID_SOCUSUA30,
                       :usuario,
                       :clave,
                       1,
                       1);

            select socsyst91_tbl_ultids.socsyst91_ultid
            from socsyst91_tbl_ultids
            WHERE socsyst91_tbl_ultids.socsyst91_usuario = current_user
            AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SOCUSUA01'
            INTO :id_socusua01;

            select first 1
            SOCUSUA02_DET_ORGANIZACION.rela_socmain01,
            SOCUSUA02_DET_ORGANIZACION.rela_socmain20,
            SOCUSUA02_DET_ORGANIZACION.rela_socmain21
            from SOCUSUA02_DET_ORGANIZACION
            inner join socusua01_cab_usuarios on ( socusua01_cab_usuarios.id_socusua01 = SOCUSUA02_DET_ORGANIZACION.rela_socusua01 )
            inner join socsyst10_det_entradas on ( socsyst10_det_entradas.id_socsyst10 = SOCUSUA02_DET_ORGANIZACION.rela_socsyst10_ca001 )
            where socusua01_cab_usuarios.socusua01_usuario = 'ADMIN'
            and socsyst10_det_entradas.socsyst10_codigo = 'ADMIN'
            into :rela_socmain01,
                 :rela_socmain20,
                 :rela_socmain21;

            insert into socusua02_det_organizacion( socusua02_det_organizacion.rela_socusua01,
                                                        socusua02_det_organizacion.rela_socmain01,
                                                        socusua02_det_organizacion.rela_socmain20,
                                                        socusua02_det_organizacion.rela_socmain21,
                                                        socusua02_det_organizacion.rela_socsyst10_ca001 )
            values( :id_socusua01,
                        :rela_socmain01,
                        :rela_socmain20,
                        :rela_socmain21,
                        :id_socsyst10_cargo );

            select first 1
            SOCUSUA15_DET_PERFILES.rela_socusua10
            from SOCUSUA15_DET_PERFILES
            where SOCUSUA15_DET_PERFILES.rela_socmain01 = :rela_socmain01
            and SOCUSUA15_DET_PERFILES.rela_socmain20 = :rela_socmain20
            and SOCUSUA15_DET_PERFILES.rela_socmain21 = :rela_socmain21
            and SOCUSUA15_DET_PERFILES.rela_socsyst10_ca001 = :id_socsyst10_cargo
            into :rela_socusua10_menu;

            if (rela_socusua10_menu is null) then
            begin
                select socusua10_cab_menu.id_socusua10
                from socusua10_cab_menu
                where socusua10_cab_menu.socusua10_codigo = 'SMXMENU'
                INTO :rela_socusua10_menu;

                insert into socusua15_det_perfiles( socusua15_det_perfiles.rela_socusua10,
                                                    socusua15_det_perfiles.rela_socmain01,
                                                    socusua15_det_perfiles.rela_socmain20,
                                                    socusua15_det_perfiles.rela_socmain21,
                                                    socusua15_det_perfiles.rela_socsyst10_ca001 )
                values( :rela_socusua10_menu,
                        :rela_socmain01,
                        :rela_socmain20,
                        :rela_socmain21,
                        :id_socsyst10_cargo );
            end
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_LOGON_MODI (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NEWPASS VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    OK INTEGER)
AS
declare variable USUARIO_EXISTE varchar(50);
begin
    usuario_existe = null;
    Select smx$soc_seguridad.usuario_existe
    from smx$soc_seguridad( 'EXISTE', :usuario, null)
    into :usuario_existe;

    if (usuario_existe is not null) then
    BEGIN
        Select smx$soc_seguridad.usuario_existe
        from smx$soc_seguridad( 'MODI', :usuario, :newpass)
        into :usuario_existe;

        update socusua01_cab_usuarios set socusua01_cab_usuarios.socusua01_clave = :newpass
        where socusua01_cab_usuarios.socusua01_usuario = :usuario;

        ok = 0;
    END
    else
        ok = 1;

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_LOGON_SOVIMEX (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCUSUA01 BIGINT)
AS
declare variable SMXSQL varchar(400);
begin
    id_socusua01 = null;
    usuario = upper(trim(usuario));

    SMXSQL = 'select SOCUSUA01_CAB_USUARIOS.id_socusua01 ' ||
             'from SOCUSUA01_CAB_USUARIOS ' ||
             'where trim(upper(SOCUSUA01_CAB_USUARIOS.socusua01_usuario)) = ''' || :usuario || '''';

    execute statement :SMXSQL
    on external 'SOVIMEX'
    AS USER 'SYSDBA' PASSWORD 'masterkey'
    into :id_socusua01;

    if (id_socusua01 is not null) then
        suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_MENU (
    RELA_SOCUSUA10 BIGINT)
RETURNS (
    RELA_SOCSYST06 BIGINT,
    RELA_SOCUSUA11 BIGINT,
    SOCSYST06_NIVEL BIGINT,
    ID_SOCUSUA11 BIGINT,
    SOCUSUA11_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCUSUA11_CODIGO_EXT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCUSUA11_DESCRIPCION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    for Select
    socusua11_arb_menu.rela_socsyst06,
    socusua11_arb_menu.rela_socusua11,
    socsyst06_det_niveles.socsyst06_nivel,
    socusua11_arb_menu.id_socusua11,
    socusua11_arb_menu.socusua11_codigo,
    socusua11_arb_menu.socusua11_codigo_ext,
    socusua11_arb_menu.socusua11_descripcion
    from socusua11_arb_menu
    inner join socsyst06_det_niveles on (socsyst06_det_niveles.id_socsyst06 = socusua11_arb_menu.rela_socsyst06)
    where socusua11_arb_menu.rela_socusua10 = :RELA_SOCUSUA10
    order by socusua11_codigo
    into :rela_socsyst06,
         :rela_socusua11,
         :socsyst06_nivel,
         :id_socusua11,
         :socusua11_codigo,
         :socusua11_codigo_ext,
         :socusua11_descripcion
    do
    begin
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_PERFILES (
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RELA_SOCUSUA01 BIGINT,
    RELA_SOCMAIN01 BIGINT,
    RELA_SOCMAIN20 BIGINT,
    RELA_SOCMAIN21 BIGINT,
    RELA_SOCSYST10_CA001 BIGINT,
    RELA_SOCUSUA02 BIGINT,
    RELA_SOCUSUA10 BIGINT,
    ID_SOCUSUA15 BIGINT,
    SOCUSUA10_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    MENU VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    EMPRESA VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ENTIDAD VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    PERFIL VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ORGANIZACION VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CARGO VARCHAR(400) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CARGO_CODIGO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID_SOCUSUA01 bigint;
declare variable SOCUSUA30_APELLIDO_PAT varchar(400);
declare variable SOCUSUA30_APELLIDO_MAT varchar(400);
declare variable SOCUSUA30_NOMBRE_RAZSOC varchar(400);
begin
    Select
    socusua01_cab_usuarios.id_socusua01,
    socusua30_cab_entidades.socusua30_apellido_pat,
    socusua30_cab_entidades.socusua30_apellido_mat,
    socusua30_cab_entidades.socusua30_nombre_razsoc
    from socusua01_cab_usuarios
    inner join socusua30_cab_entidades on (socusua30_cab_entidades.id_socusua30 = socusua01_cab_usuarios.rela_socusua30)
    where socusua01_cab_usuarios.socusua01_usuario = :USUARIO
    into :id_socusua01,
         :socusua30_apellido_pat,
         :socusua30_apellido_mat,
         :socusua30_nombre_razsoc;

    if (socusua30_apellido_mat is null) then
        socusua30_apellido_mat = '';
    else
        socusua30_apellido_mat = ' ' || socusua30_apellido_mat;

    if ((socusua30_apellido_mat <> '') or (socusua30_apellido_pat <> '') ) then
        entidad = :socusua30_apellido_pat || :socusua30_apellido_mat || ', ' || :socusua30_nombre_razsoc;
    else
        entidad = :socusua30_nombre_razsoc;

    for select
    socusua02_det_organizacion.rela_socusua01,
    socusua02_det_organizacion.rela_socmain01,
    socusua02_det_organizacion.rela_socmain20,
    socusua02_det_organizacion.rela_socmain21,
    socusua02_det_organizacion.rela_socsyst10_ca001,
    socusua02_det_organizacion.id_socusua02,
    socmain01_cab_empresas.socmain01_nomcomercial,
    socmain20_cab_organizacion.socmain20_descripcion,
    socmain21_arb_organizacion.socmain21_descripcion,
    socsyst10_det_entradas.socsyst10_descripcion,
    socsyst10_det_entradas.socsyst10_codigo
    from socusua02_det_organizacion
    inner join socmain01_cab_empresas on (socmain01_cab_empresas.id_socmain01 = socusua02_det_organizacion.rela_socmain01)
    inner join socmain20_cab_organizacion on (socmain20_cab_organizacion.id_socmain20 = socusua02_det_organizacion.rela_socmain20)
    inner join socmain21_arb_organizacion on (socmain21_arb_organizacion.id_socmain21 = socusua02_det_organizacion.rela_socmain21)
    inner join socsyst10_det_entradas on (socsyst10_det_entradas.id_socsyst10 = socusua02_det_organizacion.rela_socsyst10_ca001)
    where socusua02_det_organizacion.rela_socusua01 = :id_socusua01
    into :rela_socusua01,
         :rela_socmain01,
         :rela_socmain20,
         :rela_socmain21,
         :rela_socsyst10_ca001,
         :rela_socusua02,
         :empresa,
         :perfil,
         :organizacion,
         :cargo,
         :cargo_codigo
    do
    begin
        for select
        socusua15_det_perfiles.id_socusua15,
        socusua10_cab_menu.id_socusua10,
        socusua10_cab_menu.socusua10_codigo,
        socusua10_cab_menu.socusua10_descripcion
        from socusua10_cab_menu
        inner join socusua15_det_perfiles on (socusua10_cab_menu.id_socusua10 = socusua15_det_perfiles.rela_socusua10)
        where socusua15_det_perfiles.rela_socmain01 = :rela_socmain01
        and socusua15_det_perfiles.rela_socmain20 = :rela_socmain20
        and socusua15_det_perfiles.rela_socmain21 = :rela_socmain21
        and socusua15_det_perfiles.rela_socsyst10_ca001 = :rela_socsyst10_ca001
        into :ID_SOCUSUA15,
             :rela_socusua10,
             :socusua10_codigo,
             :MENU
        do
        begin
            suspend;
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_RESET_SOCSYST90
AS
begin
    delete from socsyst90_mov_logs;
    execute statement 'ALTER SEQUENCE SID_SOCSYST90 RESTART WITH 0';
end^


CREATE OR ALTER PROCEDURE SMX$SOC_SEGURIDAD (
    MODO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    USUARIO_EXISTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SMXSQL varchar(3000);
declare variable EXISTE varchar(50);
declare variable USUARIO_SIN varchar(50);
declare variable ID_SOCUSUA01_SOVIVEMX bigint;
declare variable SOPORTE integer;
begin
    modo = UPPER(:modo);
    usuario_sin = UPPER(:usuario);
    usuario = 'JAM$_' || UPPER(:usuario);
    usuario_existe = UPPER(:usuario);
    soporte = 0;
    id_socusua01_sovivemx = null;

    SMXSQL = 'select id_socusua01 ' ||
             'from socusua01_cab_usuarios ' ||
             'inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socusua01_cab_usuarios.rela_socusua30 ) ' ||
             'where socusua01_cab_usuarios.socusua01_usuario = ''' || :usuario_sin || '''' ||
             ' and socusua01_cab_usuarios.socusua01_acceso = 1';

    execute statement :SMXSQL
    on external 'SOVIMEX'
    AS USER 'SYSDBA' PASSWORD 'masterkey'
    into :id_socusua01_sovivemx;

    if (id_socusua01_sovivemx is not null) then
        soporte = 1;

    if (MODO = 'ALTA') then
    BEGIN
        existe = null;
        select smx$soc_seguridad.usuario_existe
        from smx$soc_seguridad('EXISTE', :usuario_sin, null)
        into :existe;

        if (existe is not null) then
            execute procedure smx$soc_seguridad 'BAJA', :usuario_sin, null
            returning_values existe;

        SMXSQL = 'CREATE USER ' || :usuario || '' || ' PASSWORD ' || '''' || :clave || '''';
        EXECUTE STATEMENT :SMXSQL;

        SMXSQL = 'grant SMX_ROLE to ' || '' || :usuario || '' || '' || ' with ADMIN OPTION';
        EXECUTE STATEMENT :SMXSQL;

        SMXSQL =  'INSERT into smx_users(smx_usuario, smx_clave, smx_soporte, smx_fecha) VALUES(''' ||
                  :usuario || ''',''' || :clave || ''',' || :soporte || ',''' || current_timestamp ||  ''')';
        EXECUTE STATEMENT :SMXSQL
        on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

        suspend;
    END
    else if (MODO = 'BAJA') then
    BEGIN
        existe = null;
        select smx$soc_seguridad.usuario_existe
        from smx$soc_seguridad('EXISTE', :usuario_sin, null)
        into :existe;

        if (existe is not null) then
        begin
            SMXSQL = 'DROP USER ' || '' || :usuario || '';
            EXECUTE STATEMENT :SMXSQL;

            delete from RDB$USER_PRIVILEGES where RDB$USER_PRIVILEGES.rdb$user = :usuario;

            SMXSQL =  'DELETE FROM smx_users WHERE smx_usuario = ''' || :usuario || '''';
            EXECUTE STATEMENT :SMXSQL
            on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

            suspend;
        end
    END
    else if (MODO = 'MODI') then
    BEGIN
        SMXSQL = 'ALTER USER ' || '' || :usuario || '' || ' PASSWORD ' || '''' || :clave || '''';
        EXECUTE STATEMENT :SMXSQL;

        SMXSQL =  'UPDATE smx_users set SMX_CLAVE = ''' || :clave || '''' ||
                  ', SMX_FECHA = ''' || current_timestamp || '''' ||
                  ', SMX_SOPORTE = ' || :soporte ||
                  ' WHERE smx_usuario = ''' || :usuario || '''';
        EXECUTE STATEMENT :SMXSQL
        on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

        suspend;
    END
    else if (MODO = 'EXISTE') then
    BEGIN
        for execute statement
         'SELECT SMX_USUARIO FROM SMX_USERS WHERE SMX_USUARIO = ''' || :usuario || ''''
        on external 'SMXSEG'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :usuario_existe
        do
        BEGIN
            suspend;
        END
    END
end^


CREATE OR ALTER PROCEDURE SMX$SOC_SEGURIDAD_REFRESH
RETURNS (
    ID_SOCUSUA01 BIGINT,
    SOCUSUA01_USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCUSUA01_CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_SEGURIDAD_BAJA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS_SEGURIDAD_ALTA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    FOR SELECT
    socusua01_cab_usuarios.id_socusua01,
    socusua01_cab_usuarios.socusua01_usuario,
    socusua01_cab_usuarios.socusua01_clave
    FROM socusua01_cab_usuarios
    WHERE socusua01_cab_usuarios.socusua01_acceso = 1
    AND socusua01_cab_usuarios.socusua01_usuario <> 'ADMIN'
    INTO :id_socusua01,
         :socusua01_usuario,
         :socusua01_clave
    DO
    BEGIN
        execute procedure smx$soc_seguridad 'BAJA', :socusua01_usuario, :socusua01_clave
        returning_values status_seguridad_baja;

        execute procedure smx$soc_seguridad 'ALTA', :socusua01_usuario, :socusua01_clave
        returning_values status_seguridad_alta;
        suspend;
    END
end^


CREATE OR ALTER PROCEDURE SMX$SOC_SOCMAIN80_UPDATE_REMOTO (
    ID_SOCMAIN80 BIGINT)
RETURNS (
    ID_SOCMAIN80_RETO BIGINT,
    CODPOSTAL VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SOCMAIN80 varchar(400);
declare variable SOCMAIN80_D_PAIS varchar(50);
declare variable SOCMAIN80_D_CODIGO varchar(400);
declare variable SOCMAIN80_D_CP varchar(400);
declare variable SOCMAIN80_D_ASENTA varchar(400);
declare variable SOCMAIN80_D_TIPO_ASENTA varchar(400);
declare variable SOCMAIN80_D_CIUDAD varchar(400);
declare variable SOCMAIN80_D_MNPIO varchar(400);
declare variable SOCMAIN80_D_ESTADO varchar(400);
begin
    ID_SOCMAIN80_RETO = null;

    select
    socmain80_cab_codpostales.id_socmain80,
    socmain80_cab_codpostales.socmain80_d_codigo
    from socmain80_cab_codpostales
    where socmain80_cab_codpostales.id_socmain80 = :id_socmain80
    into :id_socmain80_reto,
         :codpostal;

    if (id_socmain80_reto is null) then
    begin
        SOCMAIN80 = 'SELECT *  FROM C_CODIGOPOSTAL WHERE ID_SOCMAIN80 = ' || :id_socmain80;

        execute statement :SOCMAIN80
        on external 'SMXSEG'
        AS USER 'SYSDBA' PASSWORD 'masterkey'
        into :ID_SOCMAIN80,
             :SOCMAIN80_D_PAIS,
             :SOCMAIN80_D_CODIGO,
             :SOCMAIN80_D_ASENTA,
             :SOCMAIN80_D_TIPO_ASENTA,
             :SOCMAIN80_D_CIUDAD,
             :SOCMAIN80_D_MNPIO,
             :SOCMAIN80_D_ESTADO,
             :SOCMAIN80_D_CP;

        insert into socmain80_cab_codpostales ( socmain80_cab_codpostales.id_socmain80,
                                                socmain80_cab_codpostales.SOCMAIN80_D_PAIS,
                                                socmain80_cab_codpostales.SOCMAIN80_D_CODIGO,
                                                socmain80_cab_codpostales.SOCMAIN80_D_ASENTA,
                                                socmain80_cab_codpostales.SOCMAIN80_D_TIPO_ASENTA,
                                                socmain80_cab_codpostales.SOCMAIN80_D_CIUDAD,
                                                socmain80_cab_codpostales.SOCMAIN80_D_MNPIO,
                                                socmain80_cab_codpostales.SOCMAIN80_D_ESTADO,
                                                socmain80_cab_codpostales.SOCMAIN80_D_CP )

        values( :ID_SOCMAIN80,
                :SOCMAIN80_D_PAIS,
                :SOCMAIN80_D_CODIGO,
                :SOCMAIN80_D_ASENTA,
                :SOCMAIN80_D_TIPO_ASENTA,
                :SOCMAIN80_D_CIUDAD,
                :SOCMAIN80_D_MNPIO,
                :SOCMAIN80_D_ESTADO,
                :SOCMAIN80_D_CP );

        id_socmain80_reto = id_socmain80;
        codpostal = :SOCMAIN80_D_CODIGO;
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_SOCSYST10_UPDATE_REMOTO (
    ID_SOCSYST10 BIGINT,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCSYST10_RETO BIGINT)
AS
declare variable TABLA_REMOTA varchar(400);
declare variable SOCSYST10 varchar(400);
declare variable SOCSYST10_CODIGO varchar(50);
declare variable SOCSYST10_DESCRIPCION varchar(400);
declare variable ID_SOCSYST09 bigint;
begin
    id_socsyst10_reto = null;

    select socsyst10_det_remoto.id_socsyst10
    from socsyst10_det_remoto
    where socsyst10_det_remoto.id_socsyst10 = :id_socsyst10
    into :id_socsyst10_reto;

    if (id_socsyst10_reto is null) then
    begin
        select
        socsyst09_cab_entradas.id_socsyst09,
        socsyst09_cab_entradas.socsyst09_remoto
        from socsyst09_cab_entradas
        where socsyst09_cab_entradas.socsyst09_codigo = :clave
        into :id_socsyst09,
             :tabla_remota;

        SOCSYST10 = 'SELECT socsyst10_codigo, socsyst10_descripcion  FROM ' || :tabla_remota ||
                    ' WHERE id_socsyst10 = ' || :id_socsyst10;

        execute statement :SOCSYST10
        on external 'SMXSEG'
        AS USER 'SYSDBA' PASSWORD 'masterkey'
        into :socsyst10_codigo,
             :socsyst10_descripcion;

        if (socsyst10_descripcion is not null) then
        begin
            insert into socsyst10_det_remoto( socsyst10_det_remoto.rela_socsyst09,
                                              socsyst10_det_remoto.id_socsyst10,
                                              socsyst10_det_remoto.socsyst10_codigo,
                                              socsyst10_det_remoto.socsyst10_descripcion)
            values( :id_socsyst09,
                    :id_socsyst10,
                    :socsyst10_codigo,
                    :socsyst10_descripcion );

            id_socsyst10_reto = :id_socsyst10;
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_SOCSYST90_LOGS (
    INSTANCIA VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SOCSYST90 BIGINT,
    SOCSYST90_ACCION VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST90_TABLA VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SOCSYST90_ULTID BIGINT,
    SOCSYST90_FAPL TIME)
AS
declare variable SQL_C varchar(8000);
declare variable FAPL timestamp;
begin
    ID_SOCSYST90 = 0;
    instancia = UPPER(TRIM(instancia));
    usuario = UPPER(TRIM(usuario));

    if (usuario <> 'SYSDBA') then
        usuario = 'JAM$_' || :usuario;

    sql_c = 'SELECT SOCSYST90_ACCION, SOCSYST90_TABLA, MAX(SOCSYST90_ULTID), MAX(SOCSYST90_FAPL) ' ||
            'FROM SOCSYST90_MOV_LOGS ' ||
            'WHERE SOCSYST90_MOV_LOGS.socsyst90_usuario = '''|| :usuario || ''' ' ||
            'AND CAST(SOCSYST90_MOV_LOGS.socsyst90_fapl AS DATE) = CURRENT_DATE ' ||
            'GROUP BY SOCSYST90_ACCION, SOCSYST90_TABLA ' ||
            'ORDER BY MAX(SOCSYST90_FAPL)';
            

    for execute statement :sql_c
    on external :instancia
    AS USER 'SYSDBA' PASSWORD 'masterkey'
    into :SOCSYST90_ACCION,
         :SOCSYST90_TABLA,
         :SOCSYST90_ULTID,
         :FAPL
    do
    begin
        ID_SOCSYST90 = ID_SOCSYST90 + 1;

        select first 1 SMX$DB_DICC_TABLAS_Y_CAMPOS.tablas
        from SMX$DB_DICC_TABLAS_Y_CAMPOS
        where SMX$DB_DICC_TABLAS_Y_CAMPOS.alias = :SOCSYST90_TABLA
        into :socsyst90_tabla;

        socsyst90_fapl = cast(:fapl as time);

        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$SOC_USUARIOS_ACTIVA (
    ACTIVO INTEGER,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    OK VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable C_SQL varchar(1000);
begin
    usuario = upper(trim(:usuario));

    if (:usuario <> 'ADMIN') then
    begin
        C_SQL = 'update smx_users set smx_activo = ' || :activo || ' where upper(trim(smx_usuario)) like ''JAM$_' || :usuario || '''';
        execute statement :C_SQL
        on external 'SMXSEG'
        AS USER 'SYSDBA' PASSWORD 'masterkey';
    end

    OK = 'OK';
    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$SOC_UUIDS_JSON (
    UUID VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_SYSJSON01 BIGINT)
AS
declare variable SQL_C varchar(2000);
begin
    if (usuario is null) then
    begin
        id_sysjson01 = 1;
        sql_c = 'insert into sysjson01_tbl_uuids(sysjson01_tbl_uuids.sysjson01_uuid, sysjson01_tbl_uuids.sysjson01_usuario)
                 values(''' || :uuid || ''','''')';
    
        execute statement :sql_c;
    end
    else
    begin
        sql_c = 'Select ID_SYSJSON01 from sysjson01_tbl_uuids where sysjson01_tbl_uuids.sysjson01_uuid = ''' || :uuid || '''';
    
        id_sysjson01 = null;
        execute statement :sql_c into :id_sysjson01;

        if (id_sysjson01 is null) then
        begin
            id_sysjson01 = 2;
        end
        else
        begin
            sql_c = 'update sysjson01_tbl_uuids set sysjson01_usuario = ''' || :usuario || ''' where id_sysjson01 = ' || :id_sysjson01;
            execute statement :sql_c;

            id_sysjson01 = 1;
        end
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_FECHA_CADENA (
    FECHA DATE,
    MODO INTEGER)
RETURNS (
    CADENA VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
begin
    if (:modo = 0) then
    begin
        if (EXTRACT(MONTH FROM :FECHA) = 1) then
           CADENA = 'Enero';
        else if (EXTRACT(MONTH FROM :FECHA) = 2) then
           CADENA = 'Febrero';
        else if (EXTRACT(MONTH FROM :FECHA) = 3) then
           CADENA = 'Marzo';
        else if (EXTRACT(MONTH FROM :FECHA) = 4) then
           CADENA = 'Abril';
        else if (EXTRACT(MONTH FROM :FECHA) = 5) then
           CADENA = 'Mayo';
        else if (EXTRACT(MONTH FROM :FECHA) = 6) then
           CADENA = 'Junio';
        else if (EXTRACT(MONTH FROM :FECHA) = 7) then
           CADENA = 'Julio';
        else if (EXTRACT(MONTH FROM :FECHA) = 8) then
           CADENA = 'Agosto';
        else if (EXTRACT(MONTH FROM :FECHA) = 9) then
           CADENA = 'Septiembre';
        else if (EXTRACT(MONTH FROM :FECHA) = 10) then
           CADENA = 'Octubre';
        else if (EXTRACT(MONTH FROM :FECHA) = 11) then
           CADENA = 'Noviembre';
        else if (EXTRACT(MONTH FROM :FECHA) = 12) then
           CADENA = 'Diciembre';
    end
    else if (:modo = 1) then
    begin
        if (EXTRACT(MONTH FROM :FECHA) = 1) then
           CADENA = 'Ene';
        else if (EXTRACT(MONTH FROM :FECHA) = 2) then
           CADENA = 'Feb';
        else if (EXTRACT(MONTH FROM :FECHA) = 3) then
           CADENA = 'Mar';
        else if (EXTRACT(MONTH FROM :FECHA) = 4) then
           CADENA = 'Abr';
        else if (EXTRACT(MONTH FROM :FECHA) = 5) then
           CADENA = 'May';
        else if (EXTRACT(MONTH FROM :FECHA) = 6) then
           CADENA = 'Jun';
        else if (EXTRACT(MONTH FROM :FECHA) = 7) then
           CADENA = 'Jul';
        else if (EXTRACT(MONTH FROM :FECHA) = 8) then
           CADENA = 'Ago';
        else if (EXTRACT(MONTH FROM :FECHA) = 9) then
           CADENA = 'Sep';
        else if (EXTRACT(MONTH FROM :FECHA) = 10) then
           CADENA = 'Oct';
        else if (EXTRACT(MONTH FROM :FECHA) = 11) then
           CADENA = 'Nov';
        else if (EXTRACT(MONTH FROM :FECHA) = 12) then
           CADENA = 'Dic';
    end
    
    if (:modo = 0) then
        CADENA = EXTRACT(DAY FROM :FECHA) || ' de '
                 || CADENA || ' del ' || EXTRACT(YEAR FROM :FECHA);
    else
        CADENA = EXTRACT(DAY FROM :FECHA) || '/'
                 || CADENA || '/' || EXTRACT(YEAR FROM :FECHA);
  suspend;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_FECHA_MAX_DIA (
    MES INTEGER,
    ANO INTEGER)
RETURNS (
    DIAS INTEGER)
AS
begin
    if (mes = 1 or mes = 3 or mes = 5 or mes = 7 or mes = 8 or mes = 10 or mes = 10 or mes = 12) then
        dias = 31;
    else if (mes = 4 or mes = 6 or mes = 9 or mes = 11) then
        dias = 30;
    else if (mes = 2) then
        select SMX$_UTIL_FECHA_BISIESTO.dias
        from SMX$_UTIL_FECHA_BISIESTO(:ano)
        into :dias;

    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_NRO_WEEK (
    D DATE)
RETURNS (
    WEEK_NO INTEGER)
AS
DECLARE VARIABLE W INTEGER; /* week number */
DECLARE VARIABLE Y INTEGER; /* year the week belongs to */
BEGIN
  D = D - EXTRACT(WEEKDAY FROM D-1) + 3;  /* move to thursday */

  W = (EXTRACT(YEARDAY FROM D) - EXTRACT(WEEKDAY FROM D-1) + 7) / 7e0;
  Y = EXTRACT(YEAR FROM D);

  /* This is just formatting; you may prefer to make W and Y return parameters instead. */
  /*
  IF (W<10) THEN
    WEEK_NO = '0';
  ELSE
    WEEK_NO = '';
   WEEK_NO = Y || '/' || WEEK_NO || W; */

  /* PARA MEXICO HAY QUE AGREGAR UNA SEMANA MAS */
  /* PARA ESTADOS UNIDOS HAY QUE SACARLO */
  WEEK_NO = W + 1;

  SUSPEND;
END^


