CREATE OR ALTER PROCEDURE SMX$UTIL_NUM_000D (
    NUMERO NUMERIC(3,0),
    FLAG SMALLINT)
RETURNS (
    CNUMERO_000D VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE CNUM_RETO VARCHAR(200);
DECLARE VARIABLE CNUM_RETO_000 VARCHAR(200);
DECLARE VARIABLE CNUM_SEND NUMERIC(2,0);
begin
    if (NUMERO <= 99) then
        begin
            Select CNUMERO_00D FROM smx$util_num_00D(:NUMERO, :FLAG) INTO :CNUM_RETO;
        end        
    else if (NUMERO = 100) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(:NUMERO, 1) INTO :CNUM_RETO;
        end
    else if ((NUMERO-100) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(100, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 100;
        end
    else if ((NUMERO-200) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(200, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 200;
        end
    else if ((NUMERO-300) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(300, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 300;
        end
    else if ((NUMERO-400) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(400, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 400;
        end
    else if ((NUMERO-500) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(500, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 500;
        end
    else if ((NUMERO-600) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(600, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 600;
        end
    else if ((NUMERO-700) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(700, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 700;
        end
    else if ((NUMERO-800) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(800, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 800;
        end
    else if ((NUMERO-900) <= 99) then
        begin
            Select CNUMERO_000 FROM smx$util_num_000(900, 0) INTO :CNUM_RETO_000;
            CNUM_SEND = NUMERO - 900;
        end

    if ((CNUM_SEND<>0) and (NUMERO > 100)) then
        begin
            Select CNUMERO_00D FROM smx$util_num_00D(:CNUM_SEND, :FLAG) INTO :CNUM_RETO;
            CNUM_RETO = CNUM_RETO_000 || ' ' || :CNUM_RETO;
        end
    else if (NUMERO > 100) then
        begin
            CNUM_RETO = CNUM_RETO_000;
        end
    cnumero_000d = CNUM_RETO;
    SUSPEND;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_NUM_00D (
    NUMERO NUMERIC(2,0),
    FLAG SMALLINT)
RETURNS (
    CNUMERO_00D VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE CNUM_RETO VARCHAR(200);
DECLARE VARIABLE CNUM_RETO_0 VARCHAR(200);
DECLARE VARIABLE CNUM_SEND NUMERIC(1,0);
begin
    if (NUMERO <= 9) then
        begin
            Select CNUMERO_0 FROM smx$util_num_0(:NUMERO, :FLAG) INTO :CNUM_RETO;
        end
    else if ((NUMERO >= 10) and (NUMERO <= 20)) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(:NUMERO, 0) INTO :CNUM_RETO;
        end

    else if ((NUMERO >= 21) and (NUMERO <= 29)) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(20, 1) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 20;
            Select CNUMERO_0 FROM smx$util_num_0(:CNUM_SEND, :FLAG) INTO :CNUM_RETO_0;
            CNUM_RETO = CNUM_RETO || CNUM_RETO_0;
        end

    else if ((NUMERO-30) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(30, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 30;
        end

    else if ((NUMERO-40) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(40, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 40;
        end

    else if ((NUMERO-50) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(50, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 50;
        end

    else if ((NUMERO-60) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(60, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 60;
        end

    else if ((NUMERO-70) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(70, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 70;
        end

    else if ((NUMERO-80) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(80, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 80;
        end

    else if ((NUMERO-90) <= 9) then
        begin
            Select CNUMERO_00 FROM smx$util_num_00(90, 0) INTO :CNUM_RETO;
            CNUM_SEND = NUMERO - 90;
        end

    if ((CNUM_SEND<>0) and (NUMERO >= 30)) then
        begin
            Select CNUMERO_0 FROM smx$util_num_0(:CNUM_SEND, :FLAG) INTO :CNUM_RETO_0;
            CNUM_RETO = CNUM_RETO || ' y ' || CNUM_RETO_0;
        end

    CNUMERO_00D = CNUM_RETO;
    SUSPEND;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_NUM_JAM (
    NUMERO NUMERIC(12,0))
RETURNS (
    CNUMERO_JAM VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CNUM_RETO varchar(1000);
declare variable CNUM_RETO_MILES varchar(1000);
declare variable CNUM_RETO_MILLON varchar(1000);
declare variable CNUMERO_TMP varchar(12);
declare variable NLEN integer;
declare variable FLAG integer;
declare variable CNUMERO_MILES varchar(12);
declare variable NNUMERO_MILES numeric(6,0);
begin
    if (NUMERO <=999999) then
        begin
            Select CNUMERO_MILES FROM smx$util_num_miles(:NUMERO,0) INTO :CNUM_RETO;
        end
    else
        begin
            FLAG = 0;
            CNUMERO_TMP = NUMERO;
            NLEN = CHAR_LENGTH(CNUMERO_TMP);
            begin
                CNUMERO_MILES = SUBSTRING(cnumero_tmp from (NLEN-6)+1 for NLEN);
                NNUMERO_MILES = CNUMERO_MILES;
                Select CNUMERO_MILES FROM smx$util_num_miles(:NNUMERO_MILES,0) INTO :CNUM_RETO_MILES;

                CNUMERO_MILES = SUBSTRING(cnumero_tmp from 1 for NLEN-6);
                NNUMERO_MILES = CNUMERO_MILES;

                CNUMERO_MILES = SUBSTRING(CNUMERO_MILES from CHAR_LENGTH(CNUMERO_MILES) for CHAR_LENGTH(CNUMERO_MILES));
                if (CNUMERO_MILES = '1') then
                    FLAG = 1;

                Select CNUMERO_MILES FROM smx$util_num_miles(:NNUMERO_MILES, :FLAG) INTO :CNUM_RETO_MILLON;

                if (CNUM_RETO_MILES is null) then
                    CNUM_RETO = CNUM_RETO_MILLON || ' millones ';
                else
                    if (CNUM_RETO_MILLON='un') then
                        CNUM_RETO = trim(CNUM_RETO_MILLON) || ' millon ' || CNUM_RETO_MILES;
                    else
                        CNUM_RETO = trim(CNUM_RETO_MILLON) || ' millones ' || CNUM_RETO_MILES;
            end
        end
    CNUMERO_JAM = CNUM_RETO;
    SUSPEND;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_NUM_MEXICO (
    NUMERO DECIMAL(15,2),
    PARAM_MONEDA VARCHAR(3) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    CNUMERO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CENTERO varchar(50);
declare variable CDECIMAL varchar(50);
declare variable CNUMERO_TMP varchar(50);
declare variable NENTERO numeric(12,0);
declare variable CNUM_RETO_ENTERO varchar(1000);
begin
    cnumero_tmp = NUMERO;
    CENTERO = SUBSTRING(CNUMERO_TMP FROM 1 FOR position('.' IN cnumero_tmp)-1);

    CDECIMAL = SUBSTRING(CNUMERO_TMP FROM position('.' IN cnumero_tmp)+1 FOR CHAR_LENGTH(cnumero_tmp));
    CDECIMAL = SUBSTRING(CDECIMAL FROM 1 FOR 2);

    NENTERO = CENTERO;

    Select CNUMERO_JAM FROM SMX$UTIL_NUM_JAM(:NENTERO) INTO CNUM_RETO_ENTERO;

    if (CNUM_RETO_ENTERO IS NULL) then CNUM_RETO_ENTERO = 'Cero';

    if (CDECIMAL='') then
        CDECIMAL='00';

    if (CHAR_LENGTH(CDECIMAL)=1) then
        CDECIMAL='0' || CDECIMAL;

    if (PARAM_MONEDA='MXN') then
        cnumero = CNUM_RETO_ENTERO || ' pesos con ' || CDECIMAL || '/100 M.N.';

    else if (PARAM_MONEDA='USD') then
        cnumero = CNUM_RETO_ENTERO || ' dolares con ' || CDECIMAL || '/100 DLLS.';

    else if (PARAM_MONEDA='EUR') then
        cnumero = CNUM_RETO_ENTERO || ' euros con ' || CDECIMAL || '/100 EUR';

    else if (PARAM_MONEDA='JPY') then
        cnumero = CNUM_RETO_ENTERO || ' yenes con ' || CDECIMAL || '/100 JPY';

    else
        cnumero = CNUM_RETO_ENTERO || ' moneda con ' || CDECIMAL || '/100 MND';

    SUSPEND;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_NUM_MILES (
    NUMERO NUMERIC(12,0),
    FLAG INTEGER)
RETURNS (
    CNUMERO_MILES VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CNUM_RETO varchar(1000);
declare variable CNUM_RETO_000 varchar(1000);
declare variable CNUM_RETO_0000 varchar(1000);
declare variable CNUMERO_TMP varchar(12);
declare variable NLEN integer;
declare variable CNUMERO_000 varchar(12);
declare variable NNUMERO_000 numeric(3,0);
declare variable XFLAG smallint;
begin
    if (NUMERO <=999) then
        begin
            Select CNUMERO_000D FROM smx$util_num_000D(:NUMERO, :FLAG) INTO :CNUM_RETO;
        end
    else
        begin
            XFLAG = 0;
            CNUMERO_TMP = NUMERO;
            NLEN = CHAR_LENGTH(CNUMERO_TMP);
            begin
                CNUMERO_000 = SUBSTRING(cnumero_tmp from (NLEN-3)+1 for NLEN);
                NNUMERO_000 = CNUMERO_000;
                Select CNUMERO_000D FROM smx$util_num_000D(:NNUMERO_000, :FLAG) INTO :CNUM_RETO_000;

                CNUMERO_000 = SUBSTRING (cnumero_tmp FROM 1 FOR NLEN-3);
                NNUMERO_000 = CNUMERO_000;

                CNUMERO_000 = SUBSTRING(CNUMERO_000 from CHAR_LENGTH(CNUMERO_000) for CHAR_LENGTH(CNUMERO_000));
                if (CNUMERO_000 = '1') then
                    XFLAG = 1;

                Select CNUMERO_000D FROM smx$util_num_000D(:NNUMERO_000, :XFLAG) INTO :CNUM_RETO_0000;

                if (CNUM_RETO_000 is null) then
                    CNUM_RETO = CNUM_RETO_0000 || ' mil ';
                else
                    CNUM_RETO = CNUM_RETO_0000 || ' mil ' || CNUM_RETO_000;
            end
        end
    CNUMERO_MILES = CNUM_RETO;
    SUSPEND;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_POSITION (
    CADENA_FIND VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CADENA_ORIG VARCHAR(8000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CADENA_TOKEN VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    LUGAR INTEGER,
    VALOR VARCHAR(200) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable ID integer;
declare variable RESULT varchar(255);
begin
    lugar = 0;

    for select
    smx$util_strtokenize1.id,
    smx$util_strtokenize1.result
    from smx$util_strtokenize1(:cadena_orig, :cadena_token)
    into :id,
         :result
    do
    begin
        if (upper(result) = upper(cadena_find)) then
        begin
            lugar = :id;
            valor = :result;
            break;
        end
    end
    
    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_STRREPEAT (
    CADENA VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    VALOR VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    LONGITUD INTEGER,
    MODO INTEGER)
RETURNS (
    RESULTADO VARCHAR(1000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable CONT integer;
declare variable RELLENO varchar(1000);
declare variable LENCAD integer;
begin
    resultado = trim(CADENA);

    cont = 0;
    RELLENO = '';
    lencad = char_length(resultado);

    if (lencad < longitud) then
    begin
        lencad = longitud - lencad;
        while (cont < lencad) do
        begin
            RELLENO = RELLENO || VALOR;
            cont = cont + 1;
        end

        if (MODO = 0) then
            resultado =  RELLENO || resultado;
        else
            resultado =  resultado || RELLENO;
        end


    suspend;
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_STRTOKENIZE (
    "INPUT" VARCHAR(1024) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOKEN CHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    RESULT VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable NEWPOS integer;
declare variable OLDPOS integer;
begin
    if (position(token, input, 1) <> 0) then
    begin
        oldpos = 1;
        newpos = 1;
        while (1 = 1) do
        begin
            newpos = position(token, input, oldpos);
            if (newpos > 0) then
            begin
                result = trim(substring(input from oldpos for newpos - oldpos));
                suspend;
                oldpos = newpos + 1;
            end
            else if (oldpos - 1 < char_length(input)) then
            begin
                result = trim(substring(input from oldpos));
                suspend;
                break;
            end
            else
            begin
                break;
            end
        end
    end
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_STRTOKENIZE1 (
    INPUTX VARCHAR(1024) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TOKEN CHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID INTEGER,
    RESULT VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable NEWPOS integer;
declare variable OLDPOS integer;
begin
    id = 0;
    if (position(token, inputx, 1) <> 0) then
    begin
        oldpos = 1;
        newpos = 1;
        while (1 = 1) do
        begin
            newpos = position(token, inputx, oldpos);
            if (newpos > 0) then
            begin
                id = id + 1;
                result = trim(substring(inputx from oldpos for newpos - oldpos));
                suspend;
                oldpos = newpos + 1;
            end
            else if (oldpos - 1 < char_length(inputx)) then
            begin
                id = id + 1;
                result = trim(substring(inputx from oldpos));
                suspend;
                break;
            end
            else
            begin
                break;
            end
        end
    end
    else
    begin
        result = inputx;
        suspend;
    end
end^


CREATE OR ALTER PROCEDURE SMX$UTIL_TEL_FORMAT (
    TELEFONO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    TELEF_FORMAT VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable TEL_TEMP varchar(50);
begin
    telefono = trim(telefono);

    tel_temp = REPLACE(telefono, '(', '');
    tel_temp = REPLACE(tel_temp, ')', '');
    tel_temp = REPLACE(tel_temp, '-', '');
    tel_temp = REPLACE(tel_temp, ' ', '');
    tel_temp = REPLACE(tel_temp, '.', '');
    tel_temp = REPLACE(tel_temp, '/', '');

    telefono = trim(tel_temp);

    if (CHAR_LENGTH (telefono) = 10) then
    begin
        tel_temp = SUBSTRING (telefono FROM 1 FOR 3);
        tel_temp = '(' || tel_temp || ') ';
        tel_temp = tel_temp || SUBSTRING (telefono FROM 4 FOR 3) || '-';
        tel_temp = tel_temp || SUBSTRING (telefono FROM 7 FOR 4);

        telef_format = trim(tel_temp);
    end
    else
    begin
        telef_format = '';
    end

    suspend;
end^


CREATE OR ALTER PROCEDURE SMXSOC_SEGURIDAD (
    MODO VARCHAR(10) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    USUARIO VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    CLAVE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_USUARIO BIGINT,
    USUARIO_EXISTE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable SMXSQL varchar(3000);
declare variable EXISTE varchar(50);
declare variable USUARIO_SIN varchar(50);
declare variable ID_SOCUSUA01_SOVIVEMX bigint;
declare variable SOPORTE integer;
begin
    id_usuario = 1;
    modo = UPPER(:modo);
    usuario_sin = UPPER(:usuario);
    usuario = 'JAM$_' || UPPER(:usuario);
    usuario_existe = UPPER(:usuario);
    soporte = 0;
    id_socusua01_sovivemx = null;

    SMXSQL = 'select id_socusua01 ' ||
             'from socusua01_cab_usuarios ' ||
             'inner join socusua30_cab_entidades on ( socusua30_cab_entidades.id_socusua30 = socusua01_cab_usuarios.rela_socusua30 ) ' ||
             'where socusua01_cab_usuarios.socusua01_usuario = ''' || :usuario_sin || '''' ||
             ' and socusua01_cab_usuarios.socusua01_acceso = 1';

    execute statement :SMXSQL
    on external 'SOVIMEX'
    AS USER 'SYSDBA' PASSWORD 'masterkey'
    into :id_socusua01_sovivemx;

    if (id_socusua01_sovivemx is not null) then
        soporte = 1;

    if (MODO = 'ALTA') then
    BEGIN
        existe = null;
        select smx$soc_seguridad.usuario_existe
        from smx$soc_seguridad('EXISTE', :usuario_sin, null)
        into :existe;

        if (existe is not null) then
            execute procedure smx$soc_seguridad 'BAJA', :usuario_sin, null
            returning_values existe;

        SMXSQL = 'CREATE USER ' || :usuario || '' || ' PASSWORD ' || '''' || :clave || '''';
        EXECUTE STATEMENT :SMXSQL;

        SMXSQL = 'grant SMX_ROLE to ' || '' || :usuario || '' || '' || ' with ADMIN OPTION';
        EXECUTE STATEMENT :SMXSQL;

        SMXSQL =  'INSERT into smx_users(smx_usuario, smx_clave, smx_soporte, smx_fecha) VALUES(''' ||
                  :usuario || ''',''' || :clave || ''',' || :soporte || ',''' || current_timestamp ||  ''')';
        EXECUTE STATEMENT :SMXSQL
        on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

        suspend;
    END
    else if (MODO = 'BAJA') then
    BEGIN
        existe = null;
        select smx$soc_seguridad.usuario_existe
        from smx$soc_seguridad('EXISTE', :usuario_sin, null)
        into :existe;

        if (existe is not null) then
        begin
            SMXSQL = 'DROP USER ' || '' || :usuario || '';
            EXECUTE STATEMENT :SMXSQL;

            delete from RDB$USER_PRIVILEGES where RDB$USER_PRIVILEGES.rdb$user = :usuario;

            SMXSQL =  'DELETE FROM smx_users WHERE smx_usuario = ''' || :usuario || '''';
            EXECUTE STATEMENT :SMXSQL
            on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

            suspend;
        end
    END
    else if (MODO = 'MODI') then
    BEGIN
        SMXSQL = 'ALTER USER ' || '' || :usuario || '' || ' PASSWORD ' || '''' || :clave || '''';
        EXECUTE STATEMENT :SMXSQL;

        SMXSQL =  'UPDATE smx_users set SMX_CLAVE = ''' || :clave || '''' ||
                  ', SMX_FECHA = ''' || current_timestamp || '''' ||
                  ', SMX_SOPORTE = ' || :soporte ||
                  ' WHERE smx_usuario = ''' || :usuario || '''';
        EXECUTE STATEMENT :SMXSQL
        on external 'SMXSEG' AS USER 'SYSDBA' PASSWORD 'masterkey';

        suspend;
    END
    else if (MODO = 'EXISTE') then
    BEGIN
        for execute statement
         'SELECT SMX_USUARIO FROM SMX_USERS WHERE SMX_USUARIO = ''' || :usuario || ''''
        on external 'SMXSEG'
        AS
        USER 'SYSDBA' PASSWORD 'masterkey'
        into :usuario_existe
        do
        BEGIN
            suspend;
        END
    END
end^


