        rela_socsyst10_lpr01 = null;

        FOR SELECT
            sicingr98_det_importes.id_sicingr98
        FROM sicingr98_det_importes
        inner join sicingr95_cab_conceptos on (
            sicingr95_cab_conceptos.id_sicingr95 = sicingr98_det_importes.rela_sicingr95
        )
        where sicingr98_det_importes.rela_socsyst10_mli01 = :id_socsyst10_mli01
        and sicingr95_cab_conceptos.id_sicingr95 != :id_sicingr95
        and sicingr95_cab_conceptos.sicingr95_codigo = :cod_producto
        into :id_sicingr98
        do
        begin
            UPDATE sicingr98_det_importes
            SET sicingr98_det_importes.sicingr98_importe = :imp_sicingr98
            WHERE sicingr98_det_importes.id_sicingr98 = :id_sicingr98;

            suspend;
        end
    end
    */

    if (modalidad = 3) then
    begin
        id_sicingr95_for = null;
        sicingr95_importe = null;

        FOR SELECT
            sicingr98_det_importes.rela_socsyst10_lpr01,
            sicingr98_det_importes.id_sicingr98
        FROM sicingr98_det_importes
        inner join sicingr95_cab_conceptos on (
            sicingr95_cab_conceptos.id_sicingr95 = sicingr98_det_importes.rela_sicingr95
        )
        where sicingr98_det_importes.rela_socsyst10_lpr01 = :id_socsyst10_lpr01
        and sicingr95_cab_conceptos.id_sicingr95 != :id_sicingr95
        and sicingr95_cab_conceptos.sicingr95_codigo = :cod_producto
        into :rela_socsyst10_lpr01,
             :id_sicingr98
        do
        begin
            --UPDATE sicingr98_det_importes
            --SET sicingr98_det_importes.sicingr98_importe = :imp_sicingr98
            --WHERE sicingr98_det_importes.id_sicingr98 = :id_sicingr98;

            FOR SELECT
                pymvent11_det_xproductos.id_pymvent11
            FROM pymvent10_cab_listaprecios
            inner join pymvent11_det_xproductos on (
                pymvent11_det_xproductos.rela_pymvent10 = pymvent10_cab_listaprecios.id_pymvent10
            )
            inner join sicingr95_cab_conceptos on (
