CREATE OR ALTER PROCEDURE SP_COLECTAR_DEPENDENCIAS (
    P_OBJETO VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_NIVEL INTEGER,
    P_PREFIX VARCHAR(3) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_DEP_NOMBRE varchar(31);
declare variable V_BUSQUEDA_OBJETO varchar(35);
BEGIN
    -- 1. Preparamos la cadena de búsqueda (Case Insensitive)
    V_BUSQUEDA_OBJETO = '%' || UPPER(TRIM(:P_OBJETO)) || '%';

    --- -------------------------------------------------------
    --- BLOQUE 1: PROCEDIMIENTOS (SPs)
    --- Buscamos en TODOS los SPs del usuario si el texto existe dentro
    --- -------------------------------------------------------
    FOR SELECT DISTINCT TRIM(RDB$PROCEDURE_NAME)
        FROM RDB$PROCEDURES
        WHERE RDB$SYSTEM_FLAG = 0 
          AND RDB$PROCEDURE_NAME <> UPPER(:P_OBJETO)
    INTO :V_DEP_NOMBRE DO
    BEGIN
        -- Verificamos el contenido del BLOB en mayúsculas
        IF (EXISTS(SELECT 1 FROM RDB$PROCEDURES 
                   WHERE RDB$PROCEDURE_NAME = :V_DEP_NOMBRE 
                   AND UPPER(RDB$PROCEDURE_SOURCE) LIKE :V_BUSQUEDA_OBJETO)) THEN
        BEGIN
            IF (NOT EXISTS(SELECT 1 FROM tmp_gttdrop_cascada WHERE OBJETO_NOMBRE = :V_DEP_NOMBRE)) THEN
            BEGIN
                INSERT INTO tmp_gttdrop_cascada (OBJETO_NOMBRE, OBJETO_TIPO, NIVEL)
                VALUES (:V_DEP_NOMBRE, 5, :P_NIVEL);
                
                -- RECURSIVIDAD: Buscamos quién usa este SP (sin importar el prefijo)
                EXECUTE PROCEDURE SP_COLECTAR_DEPENDENCIAS(:V_DEP_NOMBRE, :P_NIVEL + 1, :P_PREFIX);
            END
        END
    END

    --- -------------------------------------------------------
    --- BLOQUE 2: VISTAS
    --- -------------------------------------------------------
    FOR SELECT DISTINCT TRIM(RDB$RELATION_NAME)
        FROM RDB$RELATIONS
        WHERE RDB$VIEW_SOURCE IS NOT NULL
          AND RDB$SYSTEM_FLAG = 0
          AND RDB$RELATION_NAME <> UPPER(:P_OBJETO)
    INTO :V_DEP_NOMBRE DO
    BEGIN
        IF (EXISTS(SELECT 1 FROM RDB$RELATIONS 
                   WHERE RDB$RELATION_NAME = :V_DEP_NOMBRE 
                   AND UPPER(RDB$VIEW_SOURCE) LIKE :V_BUSQUEDA_OBJETO)) THEN
        BEGIN
            IF (NOT EXISTS(SELECT 1 FROM tmp_gttdrop_cascada WHERE OBJETO_NOMBRE = :V_DEP_NOMBRE)) THEN
            BEGIN
                INSERT INTO tmp_gttdrop_cascada (OBJETO_NOMBRE, OBJETO_TIPO, NIVEL)
                VALUES (:V_DEP_NOMBRE, 1, :P_NIVEL);
                
                EXECUTE PROCEDURE SP_COLECTAR_DEPENDENCIAS(:V_DEP_NOMBRE, :P_NIVEL + 1, :P_PREFIX);
            END
        END
    END

    --- -------------------------------------------------------
    --- BLOQUE 3: TRIGGERS
    --- -------------------------------------------------------
    FOR SELECT DISTINCT TRIM(RDB$TRIGGER_NAME)
        FROM RDB$TRIGGERS
        WHERE RDB$TRIGGER_SOURCE IS NOT NULL
          AND RDB$SYSTEM_FLAG = 0
          AND RDB$TRIGGER_NAME <> UPPER(:P_OBJETO)
    INTO :V_DEP_NOMBRE DO
    BEGIN
        IF (EXISTS(SELECT 1 FROM RDB$TRIGGERS 
                   WHERE RDB$TRIGGER_NAME = :V_DEP_NOMBRE 
                   AND UPPER(RDB$TRIGGER_SOURCE) LIKE :V_BUSQUEDA_OBJETO)) THEN
        BEGIN
            IF (NOT EXISTS(SELECT 1 FROM tmp_gttdrop_cascada WHERE OBJETO_NOMBRE = :V_DEP_NOMBRE)) THEN
            BEGIN
                INSERT INTO tmp_gttdrop_cascada (OBJETO_NOMBRE, OBJETO_TIPO, NIVEL)
                VALUES (:V_DEP_NOMBRE, 2, :P_NIVEL);
                
                EXECUTE PROCEDURE SP_COLECTAR_DEPENDENCIAS(:V_DEP_NOMBRE, :P_NIVEL + 1, :P_PREFIX);
            END
        END
    END

    --- -------------------------------------------------------
    --- BLOQUE 4: TABLAS (RELACIONES POR COLUMNA RELA_)
    --- Aquí si mantenemos el prefijo para no borrar tablas ajenas
    --- -------------------------------------------------------
    FOR SELECT DISTINCT TRIM(r.RDB$RELATION_NAME)
        FROM RDB$RELATION_FIELDS rf
        JOIN RDB$RELATIONS r ON rf.RDB$RELATION_NAME = r.RDB$RELATION_NAME
        WHERE rf.RDB$FIELD_NAME = 'RELA_' || SUBSTRING(UPPER(:P_OBJETO) FROM 1 FOR 9)
          AND r.RDB$RELATION_NAME STARTING WITH :P_PREFIX
          AND r.RDB$RELATION_NAME <> UPPER(:P_OBJETO)
    INTO :V_DEP_NOMBRE DO
    BEGIN
        IF (NOT EXISTS(SELECT 1 FROM tmp_gttdrop_cascada WHERE OBJETO_NOMBRE = :V_DEP_NOMBRE)) THEN
        BEGIN
            INSERT INTO tmp_gttdrop_cascada (OBJETO_NOMBRE, OBJETO_TIPO, NIVEL)
            VALUES (:V_DEP_NOMBRE, 0, :P_NIVEL);
            
            EXECUTE PROCEDURE SP_COLECTAR_DEPENDENCIAS(:V_DEP_NOMBRE, :P_NIVEL + 1, :P_PREFIX);
        END
    END
END^


CREATE OR ALTER PROCEDURE SP_CONSULTAR_CASCADA (
    P_TABLA_RAIZ VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    NIVEL INTEGER,
    OBJETO_NOMBRE VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TIPO_DESC VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_PREFIX varchar(3);
declare variable V_TIPO_ID integer;
BEGIN
    -- 1. Limpiamos y preparamos el prefijo
    V_PREFIX = TRIM(SUBSTRING(UPPER(:P_TABLA_RAIZ) FROM 1 FOR 3));
    
    DELETE FROM tmp_gttdrop_cascada;

    -- 2. Ejecutamos la recolección basada en tu lógica de 9 caracteres
    EXECUTE PROCEDURE SP_COLECTAR_DEPENDENCIAS(UPPER(:P_TABLA_RAIZ), 1, :V_PREFIX);

    -- 3. Devolvemos los resultados para verlos en el browser
    FOR SELECT NIVEL, OBJETO_NOMBRE, OBJETO_TIPO
        FROM tmp_gttdrop_cascada
        ORDER BY NIVEL ASC, OBJETO_TIPO ASC
    INTO :NIVEL, :OBJETO_NOMBRE, :V_TIPO_ID
    DO BEGIN
        TIPO_DESC = CASE :V_TIPO_ID
            WHEN 0 THEN 'TABLA'
            WHEN 1 THEN 'VISTA'
            WHEN 2 THEN 'TRIGGER'
            WHEN 5 THEN 'PROCEDIMIENTO'
            ELSE 'OTRO'
        END;
        SUSPEND;
    END
END^


CREATE OR ALTER PROCEDURE SP_CREATE_TABLE_KERNEL_OBJECTS (
    P_TABLE_NAME VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_EXECUTE INTEGER)
RETURNS (
    ORDEN INTEGER,
    FASE VARCHAR(40) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE V_TABLE VARCHAR(31);
DECLARE VARIABLE V_ALIAS VARCHAR(31);
DECLARE VARIABLE V_ID_FIELD VARCHAR(31);
DECLARE VARIABLE V_EXISTS INTEGER;
DECLARE VARIABLE V_MAX_ID BIGINT;
DECLARE VARIABLE V_FIELD VARCHAR(31);
DECLARE VARIABLE V_RELA_ALIAS VARCHAR(31);
DECLARE VARIABLE V_TARGET_TABLE VARCHAR(31);
DECLARE VARIABLE V_TARGET_ID VARCHAR(31);
DECLARE VARIABLE V_FK_NAME VARCHAR(31);
DECLARE VARIABLE V_SQL VARCHAR(8191);
DECLARE VARIABLE V_HAS_LOG_PROC INTEGER;
BEGIN
  ORDEN = 0;
  V_TABLE = UPPER(TRIM(P_TABLE_NAME));

  IF (P_EXECUTE IS NULL) THEN
    P_EXECUTE = 0;

  IF (POSITION('_' IN V_TABLE) <= 1) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    OBJETO = V_TABLE;
    ESTADO = 'ERROR';
    COMANDO_SQL = NULL;
    NOTA = 'La tabla debe tener alias antes del primer "_". Ej: SYSUSER11_DET_CONTACTOS.';
    SUSPEND;
    EXIT;
  END

  V_ALIAS = SUBSTRING(V_TABLE FROM 1 FOR POSITION('_' IN V_TABLE) - 1);
  V_ID_FIELD = 'ID_' || V_ALIAS;

  SELECT COUNT(*)
  FROM RDB$RELATIONS R
  WHERE R.RDB$RELATION_NAME = :V_TABLE
    AND R.RDB$VIEW_BLR IS NULL
  INTO :V_EXISTS;

  IF (V_EXISTS = 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    OBJETO = V_TABLE;
    ESTADO = 'ERROR';
    COMANDO_SQL = NULL;
    NOTA = 'No existe tabla real con ese nombre.';
    SUSPEND;
    EXIT;
  END

  SELECT COUNT(*)
  FROM RDB$RELATION_FIELDS RF
  WHERE RF.RDB$RELATION_NAME = :V_TABLE
    AND RF.RDB$FIELD_NAME = :V_ID_FIELD
  INTO :V_EXISTS;

  IF (V_EXISTS = 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    OBJETO = V_ID_FIELD;
    ESTADO = 'ERROR';
    COMANDO_SQL = NULL;
    NOTA = 'La tabla no tiene campo primary esperado ' || V_ID_FIELD || '.';
    SUSPEND;
    EXIT;
  END

  SELECT COUNT(*)
  FROM RDB$PROCEDURES P
  WHERE P.RDB$PROCEDURE_NAME = 'SMX$DB_UTIL_LOGS'
  INTO :V_HAS_LOG_PROC;

  /***************************************************************************
    1) Generator / sequence SID_ALIAS
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$GENERATORS G
  WHERE G.RDB$GENERATOR_NAME = ('SID_' || :V_ALIAS)
  INTO :V_EXISTS;

  V_SQL = 'CREATE GENERATOR SID_' || V_ALIAS;

  ORDEN = ORDEN + 1;
  FASE = 'GENERATOR';
  OBJETO = 'SID_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (V_EXISTS > 0) THEN
  BEGIN
    ESTADO = 'SKIP';
    NOTA = 'Ya existe generator.';
  END
  ELSE
  BEGIN
    IF (P_EXECUTE = 1) THEN
      EXECUTE STATEMENT :V_SQL;

    ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
    NOTA = 'Generator creado o listo para crear.';
  END
  SUSPEND;

  /***************************************************************************
    2) Ajustar generator a MAX(ID_ALIAS)
  ***************************************************************************/
  V_SQL = 'SELECT MAX(' || V_ID_FIELD || ') FROM ' || V_TABLE;
  EXECUTE STATEMENT :V_SQL INTO :V_MAX_ID;
  IF (V_MAX_ID IS NULL) THEN
    V_MAX_ID = 0;

  V_SQL = 'SET GENERATOR SID_' || V_ALIAS || ' TO ' || V_MAX_ID;

  ORDEN = ORDEN + 1;
  FASE = 'GENERATOR_SET';
  OBJETO = 'SID_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (P_EXECUTE = 1) THEN
    EXECUTE STATEMENT :V_SQL;

  ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
  NOTA = 'Generator ajustado al MAX(' || V_ID_FIELD || ') = ' || V_MAX_ID || '.';
  SUSPEND;

  /***************************************************************************
    3) Primary key PKY_ALIAS
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$RELATION_CONSTRAINTS RC
  WHERE RC.RDB$CONSTRAINT_NAME = ('PKY_' || :V_ALIAS)
  INTO :V_EXISTS;

  V_SQL = 'ALTER TABLE ' || V_TABLE ||
          ' ADD CONSTRAINT PKY_' || V_ALIAS ||
          ' PRIMARY KEY (' || V_ID_FIELD || ')';

  ORDEN = ORDEN + 1;
  FASE = 'PRIMARY_KEY';
  OBJETO = 'PKY_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (V_EXISTS > 0) THEN
  BEGIN
    ESTADO = 'SKIP';
    NOTA = 'Ya existe primary key con esa nomenclatura.';
  END
  ELSE
  BEGIN
    IF (P_EXECUTE = 1) THEN
      EXECUTE STATEMENT :V_SQL;

    ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
    NOTA = 'Primary key creada o lista para crear.';
  END
  SUSPEND;

  /***************************************************************************
    4) Trigger TID_ALIAS
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$TRIGGERS T
  WHERE T.RDB$TRIGGER_NAME = ('TID_' || :V_ALIAS)
  INTO :V_EXISTS;

  V_SQL =
    'CREATE OR ALTER TRIGGER TID_' || V_ALIAS || ' FOR ' || V_TABLE || ASCII_CHAR(13) ||
    'ACTIVE BEFORE INSERT OR UPDATE OR DELETE POSITION 0' || ASCII_CHAR(13) ||
    'AS ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
    'DECLARE VARIABLE cTipo CHAR(1); ' || ASCII_CHAR(13) ||
    'DECLARE VARIABLE nID BIGINT; ' || ASCII_CHAR(13) || ASCII_CHAR(13) ||
    'BEGIN ' || ASCII_CHAR(13) ||
    '    IF (INSERTING) THEN ' || ASCII_CHAR(13) ||
    '    BEGIN ' || ASCII_CHAR(13) ||
    '        NEW.' || V_ID_FIELD || ' = GEN_ID(SID_' || V_ALIAS || ',1); ' || ASCII_CHAR(13) ||
    '        cTipo = ''A''; ' || ASCII_CHAR(13) ||
    '        nID = NEW.' || V_ID_FIELD || '; ' || ASCII_CHAR(13) ||
    '    END ' || ASCII_CHAR(13) ||
    '    ELSE IF (UPDATING) THEN ' || ASCII_CHAR(13) ||
    '    BEGIN ' || ASCII_CHAR(13) ||
    '        cTipo = ''M''; ' || ASCII_CHAR(13) ||
    '        nID = OLD.' || V_ID_FIELD || '; ' || ASCII_CHAR(13) ||
    '    END ' || ASCII_CHAR(13) ||
    '    ELSE ' || ASCII_CHAR(13) ||
    '    BEGIN ' || ASCII_CHAR(13) ||
    '        cTipo = ''B''; ' || ASCII_CHAR(13) ||
    '        nID = OLD.' || V_ID_FIELD || '; ' || ASCII_CHAR(13) ||
    '    END ' || ASCII_CHAR(13) || ASCII_CHAR(13);

  IF (V_HAS_LOG_PROC > 0) THEN
    V_SQL = V_SQL ||
      '    EXECUTE PROCEDURE smx$db_util_logs ' || ASCII_CHAR(13) ||
      '            CURRENT_USER, ' || ASCII_CHAR(13) ||
      '            :cTipo, ' || ASCII_CHAR(13) ||
      '            ''' || V_ALIAS || ''',' || ASCII_CHAR(13) ||
      '            :nID; ' || ASCII_CHAR(13);

  V_SQL = V_SQL || 'END';

  ORDEN = ORDEN + 1;
  FASE = 'TRIGGER';
  OBJETO = 'TID_' || V_ALIAS;
  COMANDO_SQL = V_SQL || ';';

  IF (V_EXISTS > 0) THEN
  BEGIN
    ESTADO = 'SKIP';
    NOTA = 'Ya existe trigger con esa nomenclatura.';
  END
  ELSE
  BEGIN
    IF (P_EXECUTE = 1) THEN
      EXECUTE STATEMENT :V_SQL;

    ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
    NOTA = 'Trigger creado o listo para crear.';
  END
  SUSPEND;

  /***************************************************************************
    5) Foreign keys por cada campo RELA_ALIASDESTINO
  ***************************************************************************/
  FOR
    SELECT TRIM(RF.RDB$FIELD_NAME)
    FROM RDB$RELATION_FIELDS RF
    WHERE RF.RDB$RELATION_NAME = :V_TABLE
      AND RF.RDB$FIELD_NAME STARTING WITH 'RELA_'
    ORDER BY RF.RDB$FIELD_POSITION
    INTO :V_FIELD
  DO
  BEGIN
    V_RELA_ALIAS = SUBSTRING(V_FIELD FROM 6);
    V_TARGET_ID = 'ID_' || V_RELA_ALIAS;
    V_TARGET_TABLE = NULL;

    SELECT FIRST 1 TRIM(R.RDB$RELATION_NAME)
    FROM RDB$RELATIONS R
    JOIN RDB$RELATION_FIELDS RFID
      ON RFID.RDB$RELATION_NAME = R.RDB$RELATION_NAME
     AND RFID.RDB$FIELD_NAME = :V_TARGET_ID
    WHERE R.RDB$VIEW_BLR IS NULL
      AND COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
      AND R.RDB$RELATION_NAME STARTING WITH (:V_RELA_ALIAS || '_')
    ORDER BY R.RDB$RELATION_NAME
    INTO :V_TARGET_TABLE;

    V_FK_NAME = 'FKY_' || V_ALIAS || '_' || V_RELA_ALIAS;
    IF (CHAR_LENGTH(V_FK_NAME) > 31) THEN
      V_FK_NAME = SUBSTRING(V_FK_NAME FROM 1 FOR 31);

    ORDEN = ORDEN + 1;
    FASE = 'FOREIGN_KEY';
    OBJETO = V_FK_NAME;

    IF (V_TARGET_TABLE IS NULL) THEN
    BEGIN
      ESTADO = 'WARN';
      COMANDO_SQL = NULL;
      NOTA = 'No se encontro tabla destino para ' || V_FIELD || ' -> alias ' || V_RELA_ALIAS || '.';
      SUSPEND;
    END
    ELSE
    BEGIN
      SELECT COUNT(*)
      FROM RDB$RELATION_CONSTRAINTS RC
      WHERE RC.RDB$CONSTRAINT_NAME = :V_FK_NAME
      INTO :V_EXISTS;

      V_SQL = 'ALTER TABLE ' || V_TABLE ||
              ' ADD CONSTRAINT ' || V_FK_NAME ||
              ' FOREIGN KEY (' || V_FIELD || ')' ||
              ' REFERENCES ' || V_TARGET_TABLE || ' (' || V_TARGET_ID || ')';

      COMANDO_SQL = V_SQL || ';';

      IF (V_EXISTS > 0) THEN
      BEGIN
        ESTADO = 'SKIP';
        NOTA = 'Ya existe foreign key con esa nomenclatura.';
      END
      ELSE
      BEGIN
        IF (P_EXECUTE = 1) THEN
          EXECUTE STATEMENT :V_SQL;

        ESTADO = IIF(P_EXECUTE = 1, 'OK', 'PREVIEW');
        NOTA = 'FK hacia ' || V_TARGET_TABLE || '.';
      END
      SUSPEND;
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_DROP_BY_ALIAS (
    P_ALIAS VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_MAX_LEVEL INTEGER)
RETURNS (
    ORDEN INTEGER,
    FASE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NIVEL INTEGER,
    TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SQL_CODE INTEGER,
    GDS_CODE INTEGER,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_ORDEN integer;
declare variable V_FASE varchar(50);
declare variable V_NIVEL integer;
declare variable V_TIPO_OBJETO varchar(20);
declare variable V_OBJETO varchar(255);
declare variable V_COMANDO_SQL varchar(8191);
declare variable V_NOTA varchar(2000);
BEGIN
  FOR
    SELECT
      P.ORDEN,
      P.FASE,
      P.NIVEL,
      P.TIPO_OBJETO,
      P.OBJETO,
      P.COMANDO_SQL,
      P.NOTA
    FROM SP_PREVIEW_DROP_BY_ALIAS(:P_ALIAS, :P_MAX_LEVEL) P
    WHERE P.COMANDO_SQL IS NOT NULL
    ORDER BY P.ORDEN
    INTO
      :V_ORDEN,
      :V_FASE,
      :V_NIVEL,
      :V_TIPO_OBJETO,
      :V_OBJETO,
      :V_COMANDO_SQL,
      :V_NOTA
  DO
  BEGIN
    ORDEN = V_ORDEN;
    FASE = V_FASE;
    NIVEL = V_NIVEL;
    TIPO_OBJETO = V_TIPO_OBJETO;
    OBJETO = V_OBJETO;
    COMANDO_SQL = V_COMANDO_SQL;
    SQL_CODE = NULL;
    GDS_CODE = NULL;

    BEGIN
      EXECUTE STATEMENT :V_COMANDO_SQL;

      ESTADO = 'OK';
      NOTA = 'Ejecutado correctamente. Commit pendiente.';
      SUSPEND;

    WHEN ANY DO
      BEGIN
        ESTADO = 'ERROR';
        SQL_CODE = SQLCODE;
        GDS_CODE = GDSCODE;
        NOTA = 'Fallo este comando. El SP se detuvo aqui. Hacer ROLLBACK o corregir manualmente.';
        SUSPEND;
        EXIT;
      END
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_GENERAR_SCRIPT_DROP (
    P_TABLA_RAIZ VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ORDEN INTEGER,
    SENTENCIA VARCHAR(250) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    STATUS VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
declare variable V_PREFIX varchar(3);
declare variable V_NOMBRE varchar(31);
declare variable V_HIJA varchar(31);
declare variable V_TIPO smallint;
BEGIN
    V_PREFIX = TRIM(SUBSTRING(UPPER(:P_TABLA_RAIZ) FROM 1 FOR 3));
    
    -- 1. RECOLECCIÓN DE TODAS LAS DEPENDENCIAS (Tablas, SPs, Vistas, Triggers)
    DELETE FROM tmp_gttdrop_cascada;
    EXECUTE PROCEDURE SP_COLECTAR_DEPENDENCIAS(UPPER(:P_TABLA_RAIZ), 1, :V_PREFIX);

    --- -------------------------------------------------------
    --- PASO 1: ELIMINAR CONSTRAINTS (PK/FK)
    --- -------------------------------------------------------
    FOR SELECT DISTINCT TRIM(rc.RDB$RELATION_NAME), TRIM(rc.RDB$CONSTRAINT_NAME)
        FROM RDB$RELATION_CONSTRAINTS rc
        LEFT JOIN RDB$REF_CONSTRAINTS rfc ON rc.RDB$CONSTRAINT_NAME = rfc.RDB$CONSTRAINT_NAME
        LEFT JOIN RDB$RELATION_CONSTRAINTS rc2 ON rfc.RDB$CONST_NAME_UQ = rc2.RDB$CONSTRAINT_NAME
        WHERE TRIM(rc.RDB$RELATION_NAME) IN (SELECT OBJETO_NOMBRE FROM tmp_gttdrop_cascada WHERE OBJETO_TIPO = 0)
           OR TRIM(rc.RDB$RELATION_NAME) = TRIM(UPPER(:P_TABLA_RAIZ))
           OR TRIM(rc2.RDB$RELATION_NAME) IN (SELECT OBJETO_NOMBRE FROM tmp_gttdrop_cascada WHERE OBJETO_TIPO = 0)
           OR TRIM(rc2.RDB$RELATION_NAME) = TRIM(UPPER(:P_TABLA_RAIZ))
    INTO :V_HIJA, :V_NOMBRE DO
    BEGIN
        ORDEN = 10;
        SENTENCIA = 'ALTER TABLE ' || :V_HIJA || ' DROP CONSTRAINT ' || :V_NOMBRE;
        BEGIN
            IN AUTONOMOUS TRANSACTION DO EXECUTE STATEMENT :SENTENCIA;
            STATUS = 'BORRADO OK';
        WHEN ANY DO STATUS = 'ERROR/NO EXISTE';
        END
        SUSPEND;
    END

    --- -------------------------------------------------------
    --- PASO 2: VACIAR (STUBBING) DE SPs Y VISTAS
    --- Esto rompe las dependencias de código sin tocar el diccionario manual
    --- -------------------------------------------------------
    FOR SELECT TRIM(OBJETO_NOMBRE), OBJETO_TIPO 
        FROM tmp_gttdrop_cascada 
        WHERE OBJETO_TIPO IN (1, 5) 
        ORDER BY NIVEL DESC
    INTO :V_NOMBRE, :V_TIPO DO
    BEGIN
        ORDEN = 15;
        IF (V_TIPO = 1) THEN
            SENTENCIA = 'CREATE OR ALTER VIEW ' || :V_NOMBRE || ' AS SELECT 1 AS D FROM RDB$DATABASE';
        ELSE
            SENTENCIA = 'CREATE OR ALTER PROCEDURE ' || :V_NOMBRE || ' AS BEGIN END';
            
        BEGIN
            IN AUTONOMOUS TRANSACTION DO EXECUTE STATEMENT :SENTENCIA;
            STATUS = 'VACIADO OK';
        WHEN ANY DO STATUS = 'ERROR';
        END
        SUSPEND;
    END

    --- -------------------------------------------------------
    --- PASO 3: BORRADO DE OBJETOS LÓGICOS (Triggers, Vistas, SPs)
    --- -------------------------------------------------------
    FOR SELECT TRIM(OBJETO_NOMBRE), OBJETO_TIPO 
        FROM tmp_gttdrop_cascada 
        WHERE OBJETO_TIPO IN (1, 2, 5) 
        ORDER BY NIVEL DESC
    INTO :V_NOMBRE, :V_TIPO DO
    BEGIN
        ORDEN = 20;
        SENTENCIA = CASE :V_TIPO 
            WHEN 1 THEN 'DROP VIEW ' 
            WHEN 2 THEN 'DROP TRIGGER ' 
            WHEN 5 THEN 'DROP PROCEDURE ' 
        END || :V_NOMBRE;
        
        BEGIN
            IN AUTONOMOUS TRANSACTION DO EXECUTE STATEMENT :SENTENCIA;
            STATUS = 'BORRADO OK';
        WHEN ANY DO STATUS = 'ERROR';
        END
        SUSPEND;
    END

    --- -------------------------------------------------------
    --- PASO 4: BORRADO DE TABLAS (Hijas y Raíz)
    --- -------------------------------------------------------
    -- Primero las recolectadas (hijas)
    FOR SELECT TRIM(OBJETO_NOMBRE) 
        FROM tmp_gttdrop_cascada 
        WHERE OBJETO_TIPO = 0 
        ORDER BY NIVEL DESC
    INTO :V_NOMBRE DO
    BEGIN
        ORDEN = 30;
        SENTENCIA = 'DROP TABLE ' || :V_NOMBRE;
        BEGIN
            IN AUTONOMOUS TRANSACTION DO EXECUTE STATEMENT :SENTENCIA;
            STATUS = 'BORRADO OK';
        WHEN ANY DO STATUS = 'ERROR';
        END
        SUSPEND;
    END

    -- Y finalmente la tabla raíz
    ORDEN = 40;
    SENTENCIA = 'DROP TABLE ' || TRIM(UPPER(:P_TABLA_RAIZ));
    BEGIN
        IN AUTONOMOUS TRANSACTION DO EXECUTE STATEMENT :SENTENCIA;
        STATUS = 'BORRADO OK';
    WHEN ANY DO STATUS = 'ERROR';
    END
    SUSPEND;
END^


CREATE OR ALTER PROCEDURE SP_LIKE_DROP_BY_ALIAS (
    P_LIKE VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_MAX_LEVEL INTEGER)
RETURNS (
    TARGET_ALIAS VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TARGET_TABLE VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TABLA_ORDEN INTEGER,
    ORDEN INTEGER,
    FASE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NIVEL INTEGER,
    TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    ESTADO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    SQL_CODE INTEGER,
    GDS_CODE INTEGER,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE V_LIKE VARCHAR(31);
DECLARE VARIABLE V_ALIAS VARCHAR(31);
DECLARE VARIABLE V_TABLE VARCHAR(31);
DECLARE VARIABLE V_TABLE_ORDER INTEGER;
DECLARE VARIABLE V_ORDEN INTEGER;
DECLARE VARIABLE V_FASE VARCHAR(50);
DECLARE VARIABLE V_NIVEL INTEGER;
DECLARE VARIABLE V_TIPO_OBJETO VARCHAR(20);
DECLARE VARIABLE V_OBJETO VARCHAR(255);
DECLARE VARIABLE V_COMANDO_SQL VARCHAR(8191);
DECLARE VARIABLE V_ESTADO VARCHAR(20);
DECLARE VARIABLE V_SQL_CODE INTEGER;
DECLARE VARIABLE V_GDS_CODE INTEGER;
DECLARE VARIABLE V_NOTA VARCHAR(2000);
BEGIN
  DELETE FROM TMP_LIKE_DROP_BY_ALIAS;

  V_LIKE = UPPER(TRIM(P_LIKE));

  IF (P_MAX_LEVEL IS NULL OR P_MAX_LEVEL < 1) THEN
    P_MAX_LEVEL = 10;

  /* Si no trae comodin, se asume "empieza con". */
  IF (POSITION('%' IN V_LIKE) = 0 AND POSITION('_' IN V_LIKE) = 0) THEN
    V_LIKE = V_LIKE || '%';

  /***************************************************************************
    Snapshot de tablas candidatas.

    TARGET_ALIAS se toma como el prefijo antes del primer "_".
    Ejemplo:
      ADUCTAG02_DET_ANTICIPOS -> ADUCTAG02
  ***************************************************************************/
  INSERT INTO TMP_LIKE_DROP_BY_ALIAS (TARGET_ALIAS, TARGET_TABLE)
  SELECT
    SUBSTRING(TRIM(R.RDB$RELATION_NAME) FROM 1 FOR POSITION('_' IN TRIM(R.RDB$RELATION_NAME)) - 1),
    TRIM(R.RDB$RELATION_NAME)
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NULL
    AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE :V_LIKE
    AND POSITION('_' IN TRIM(R.RDB$RELATION_NAME)) > 1
  ORDER BY R.RDB$RELATION_NAME;

  V_TABLE_ORDER = 0;

  FOR
    SELECT TARGET_ALIAS, TARGET_TABLE
    FROM TMP_LIKE_DROP_BY_ALIAS
    ORDER BY TARGET_TABLE
    INTO :V_ALIAS, :V_TABLE
  DO
  BEGIN
    V_TABLE_ORDER = V_TABLE_ORDER + 1;

    TARGET_ALIAS = V_ALIAS;
    TARGET_TABLE = V_TABLE;
    TABLA_ORDEN = V_TABLE_ORDER;
    ORDEN = 0;
    FASE = 'INFO_TARGET_TABLE';
    NIVEL = NULL;
    TIPO_OBJETO = 'TABLE';
    OBJETO = V_TABLE;
    COMANDO_SQL = NULL;
    ESTADO = 'INFO';
    SQL_CODE = NULL;
    GDS_CODE = NULL;
    NOTA = 'Iniciando borrado para alias ' || V_ALIAS || ', tabla ' || V_TABLE || '.';
    SUSPEND;

    FOR
      SELECT
        D.ORDEN,
        D.FASE,
        D.NIVEL,
        D.TIPO_OBJETO,
        D.OBJETO,
        D.COMANDO_SQL,
        D.ESTADO,
        D.SQL_CODE,
        D.GDS_CODE,
        D.NOTA
      FROM SP_DROP_BY_ALIAS(:V_ALIAS, :P_MAX_LEVEL) D
      INTO
        :V_ORDEN,
        :V_FASE,
        :V_NIVEL,
        :V_TIPO_OBJETO,
        :V_OBJETO,
        :V_COMANDO_SQL,
        :V_ESTADO,
        :V_SQL_CODE,
        :V_GDS_CODE,
        :V_NOTA
    DO
    BEGIN
      TARGET_ALIAS = V_ALIAS;
      TARGET_TABLE = V_TABLE;
      TABLA_ORDEN = V_TABLE_ORDER;
      ORDEN = V_ORDEN;
      FASE = V_FASE;
      NIVEL = V_NIVEL;
      TIPO_OBJETO = V_TIPO_OBJETO;
      OBJETO = V_OBJETO;
      COMANDO_SQL = V_COMANDO_SQL;
      ESTADO = V_ESTADO;
      SQL_CODE = V_SQL_CODE;
      GDS_CODE = V_GDS_CODE;
      NOTA = V_NOTA;
      SUSPEND;

      IF (V_ESTADO = 'ERROR') THEN
        EXIT;
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_PLUGIN_DB_CACHE
RETURNS (
    TMPDICC01_NODE_ID VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_PARENT_ID VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_TIPO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_NOMBRE VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_OBJETO VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_ORDEN INTEGER,
    ID_TMPDICC01 INTEGER,
    TMPDICC01_FAPL TIMESTAMP)
AS
DECLARE VARIABLE V_ID INTEGER;
BEGIN
  DELETE FROM TMP_PLUGDB01
  WHERE TMPPLUGDB01_USUARIO = CURRENT_USER;

  V_ID = 0;

  V_ID = V_ID + 1;
  TMPDICC01_NODE_ID = 'ROOT_TABLES';
  TMPDICC01_PARENT_ID = '';
  TMPDICC01_TIPO = 'TABLE';
  TMPDICC01_NOMBRE = 'Tablas';
  TMPDICC01_OBJETO = '';
  TMPDICC01_ORDEN = 10;
  ID_TMPDICC01 = :V_ID;
  TMPDICC01_FAPL = CURRENT_TIMESTAMP;

  INSERT INTO TMP_PLUGDB01 (
      ID_TMPPLUGDB01,
      TMPPLUGDB01_NODE_ID,
      TMPPLUGDB01_PARENT_ID,
      TMPPLUGDB01_TIPO,
      TMPPLUGDB01_NOMBRE,
      TMPPLUGDB01_OBJETO,
      TMPPLUGDB01_ORDEN,
      TMPPLUGDB01_FAPL,
        TMPPLUGDB01_USUARIO
    ) VALUES (
      :ID_TMPDICC01,
      :TMPDICC01_NODE_ID,
      :TMPDICC01_PARENT_ID,
      :TMPDICC01_TIPO,
      :TMPDICC01_NOMBRE,
      :TMPDICC01_OBJETO,
      :TMPDICC01_ORDEN,
      CURRENT_TIMESTAMP,
        CURRENT_USER
    );
  SUSPEND;

  V_ID = V_ID + 1;
  TMPDICC01_NODE_ID = 'ROOT_VIEWS';
  TMPDICC01_PARENT_ID = '';
  TMPDICC01_TIPO = 'VIEW';
  TMPDICC01_NOMBRE = 'Vistas';
  TMPDICC01_OBJETO = '';
  TMPDICC01_ORDEN = 20;
  ID_TMPDICC01 = :V_ID;
  TMPDICC01_FAPL = CURRENT_TIMESTAMP;

  INSERT INTO TMP_PLUGDB01 (
      ID_TMPPLUGDB01,
      TMPPLUGDB01_NODE_ID,
      TMPPLUGDB01_PARENT_ID,
      TMPPLUGDB01_TIPO,
      TMPPLUGDB01_NOMBRE,
      TMPPLUGDB01_OBJETO,
      TMPPLUGDB01_ORDEN,
      TMPPLUGDB01_FAPL,
        TMPPLUGDB01_USUARIO
    ) VALUES (
      :ID_TMPDICC01,
      :TMPDICC01_NODE_ID,
      :TMPDICC01_PARENT_ID,
      :TMPDICC01_TIPO,
      :TMPDICC01_NOMBRE,
      :TMPDICC01_OBJETO,
      :TMPDICC01_ORDEN,
      CURRENT_TIMESTAMP,
        CURRENT_USER
    );
  SUSPEND;

  V_ID = V_ID + 1;
  TMPDICC01_NODE_ID = 'ROOT_PROCEDURES';
  TMPDICC01_PARENT_ID = '';
  TMPDICC01_TIPO = 'PROCEDURE';
  TMPDICC01_NOMBRE = 'Procedimientos';
  TMPDICC01_OBJETO = '';
  TMPDICC01_ORDEN = 30;
  ID_TMPDICC01 = :V_ID;
  TMPDICC01_FAPL = CURRENT_TIMESTAMP;

  INSERT INTO TMP_PLUGDB01 (
      ID_TMPPLUGDB01,
      TMPPLUGDB01_NODE_ID,
      TMPPLUGDB01_PARENT_ID,
      TMPPLUGDB01_TIPO,
      TMPPLUGDB01_NOMBRE,
      TMPPLUGDB01_OBJETO,
      TMPPLUGDB01_ORDEN,
      TMPPLUGDB01_FAPL,
        TMPPLUGDB01_USUARIO
    ) VALUES (
      :ID_TMPDICC01,
      :TMPDICC01_NODE_ID,
      :TMPDICC01_PARENT_ID,
      :TMPDICC01_TIPO,
      :TMPDICC01_NOMBRE,
      :TMPDICC01_OBJETO,
      :TMPDICC01_ORDEN,
      CURRENT_TIMESTAMP,
        CURRENT_USER
    );
  SUSPEND;

  FOR
    SELECT
        'TABLE_' || TRIM(R.RDB$RELATION_NAME),
        'ROOT_TABLES',
        'TABLE',
        TRIM(R.RDB$RELATION_NAME),
        TRIM(R.RDB$RELATION_NAME),
        11
    FROM RDB$RELATIONS R
    WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
      AND R.RDB$VIEW_BLR IS NULL
    ORDER BY TRIM(R.RDB$RELATION_NAME)
    INTO
        :TMPDICC01_NODE_ID,
        :TMPDICC01_PARENT_ID,
        :TMPDICC01_TIPO,
        :TMPDICC01_NOMBRE,
        :TMPDICC01_OBJETO,
        :TMPDICC01_ORDEN
  DO
  BEGIN
    V_ID = V_ID + 1;
    ID_TMPDICC01 = :V_ID;
    TMPDICC01_FAPL = CURRENT_TIMESTAMP;

    INSERT INTO TMP_PLUGDB01 (
        ID_TMPPLUGDB01,
        TMPPLUGDB01_NODE_ID,
        TMPPLUGDB01_PARENT_ID,
        TMPPLUGDB01_TIPO,
        TMPPLUGDB01_NOMBRE,
        TMPPLUGDB01_OBJETO,
        TMPPLUGDB01_ORDEN,
        TMPPLUGDB01_FAPL,
        TMPPLUGDB01_USUARIO
    ) VALUES (
        :ID_TMPDICC01,
        :TMPDICC01_NODE_ID,
        :TMPDICC01_PARENT_ID,
        :TMPDICC01_TIPO,
        :TMPDICC01_NOMBRE,
        :TMPDICC01_OBJETO,
        :TMPDICC01_ORDEN,
        CURRENT_TIMESTAMP,
        CURRENT_USER
    );

    SUSPEND;
  END

  FOR
    SELECT
        'VIEW_' || TRIM(R.RDB$RELATION_NAME),
        'ROOT_VIEWS',
        'VIEW',
        TRIM(R.RDB$RELATION_NAME),
        TRIM(R.RDB$RELATION_NAME),
        21
    FROM RDB$RELATIONS R
    WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
      AND R.RDB$VIEW_BLR IS NOT NULL
    ORDER BY TRIM(R.RDB$RELATION_NAME)
    INTO
        :TMPDICC01_NODE_ID,
        :TMPDICC01_PARENT_ID,
        :TMPDICC01_TIPO,
        :TMPDICC01_NOMBRE,
        :TMPDICC01_OBJETO,
        :TMPDICC01_ORDEN
  DO
  BEGIN
    V_ID = V_ID + 1;
    ID_TMPDICC01 = :V_ID;
    TMPDICC01_FAPL = CURRENT_TIMESTAMP;

    INSERT INTO TMP_PLUGDB01 (
        ID_TMPPLUGDB01,
        TMPPLUGDB01_NODE_ID,
        TMPPLUGDB01_PARENT_ID,
        TMPPLUGDB01_TIPO,
        TMPPLUGDB01_NOMBRE,
        TMPPLUGDB01_OBJETO,
        TMPPLUGDB01_ORDEN,
        TMPPLUGDB01_FAPL,
        TMPPLUGDB01_USUARIO
    ) VALUES (
        :ID_TMPDICC01,
        :TMPDICC01_NODE_ID,
        :TMPDICC01_PARENT_ID,
        :TMPDICC01_TIPO,
        :TMPDICC01_NOMBRE,
        :TMPDICC01_OBJETO,
        :TMPDICC01_ORDEN,
        CURRENT_TIMESTAMP,
        CURRENT_USER
    );

    SUSPEND;
  END

  FOR
    SELECT
        'PROCEDURE_' || TRIM(P.RDB$PROCEDURE_NAME),
        'ROOT_PROCEDURES',
        'PROCEDURE',
        TRIM(P.RDB$PROCEDURE_NAME),
        TRIM(P.RDB$PROCEDURE_NAME),
        31
    FROM RDB$PROCEDURES P
    WHERE COALESCE(P.RDB$SYSTEM_FLAG, 0) = 0
    ORDER BY TRIM(P.RDB$PROCEDURE_NAME)
    INTO
        :TMPDICC01_NODE_ID,
        :TMPDICC01_PARENT_ID,
        :TMPDICC01_TIPO,
        :TMPDICC01_NOMBRE,
        :TMPDICC01_OBJETO,
        :TMPDICC01_ORDEN
  DO
  BEGIN
    V_ID = V_ID + 1;
    ID_TMPDICC01 = :V_ID;
    TMPDICC01_FAPL = CURRENT_TIMESTAMP;

    INSERT INTO TMP_PLUGDB01 (
        ID_TMPPLUGDB01,
        TMPPLUGDB01_NODE_ID,
        TMPPLUGDB01_PARENT_ID,
        TMPPLUGDB01_TIPO,
        TMPPLUGDB01_NOMBRE,
        TMPPLUGDB01_OBJETO,
        TMPPLUGDB01_ORDEN,
        TMPPLUGDB01_FAPL,
        TMPPLUGDB01_USUARIO
    ) VALUES (
        :ID_TMPDICC01,
        :TMPDICC01_NODE_ID,
        :TMPDICC01_PARENT_ID,
        :TMPDICC01_TIPO,
        :TMPDICC01_NOMBRE,
        :TMPDICC01_OBJETO,
        :TMPDICC01_ORDEN,
        CURRENT_TIMESTAMP,
        CURRENT_USER
    );

    SUSPEND;
  END
END^


CREATE OR ALTER PROCEDURE SP_PLUGIN_DEPENDENCIES (
    P_TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_OBJETO VARCHAR(63) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    TMPDICC01_NODE_ID VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_PARENT_ID VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_TIPO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_NOMBRE VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_OBJETO VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPDICC01_ORDEN INTEGER,
    ID_TMPDICC01 INTEGER,
    TMPDICC01_FAPL TIMESTAMP)
AS
DECLARE VARIABLE V_TIPO_OBJETO VARCHAR(20);
DECLARE VARIABLE V_OBJETO VARCHAR(63);
DECLARE VARIABLE V_ALIAS VARCHAR(9);
DECLARE VARIABLE V_DEP_NAME VARCHAR(80);
DECLARE VARIABLE V_DEP_TYPE VARCHAR(20);
DECLARE VARIABLE V_PARENT_ID VARCHAR(80);
DECLARE VARIABLE V_OUT_ORDEN INTEGER;
BEGIN
  V_TIPO_OBJETO = UPPER(TRIM(:P_TIPO_OBJETO));
  V_OBJETO = UPPER(TRIM(:P_OBJETO));
  V_ALIAS = SUBSTRING(:V_OBJETO FROM 1 FOR 9);
  ID_TMPDICC01 = 0;

  TMPDICC01_NODE_ID = 'ROOT_TABLES';
  TMPDICC01_PARENT_ID = '';
  TMPDICC01_TIPO = 'TABLE';
  TMPDICC01_NOMBRE = 'Tablas';
  TMPDICC01_OBJETO = '';
  TMPDICC01_ORDEN = 10;
  TMPDICC01_FAPL = CURRENT_TIMESTAMP;
  SUSPEND;

  TMPDICC01_NODE_ID = 'ROOT_VIEWS';
  TMPDICC01_PARENT_ID = '';
  TMPDICC01_TIPO = 'VIEW';
  TMPDICC01_NOMBRE = 'Vistas';
  TMPDICC01_OBJETO = '';
  TMPDICC01_ORDEN = 20;
  TMPDICC01_FAPL = CURRENT_TIMESTAMP;
  SUSPEND;

  TMPDICC01_NODE_ID = 'ROOT_PROCEDURES';
  TMPDICC01_PARENT_ID = '';
  TMPDICC01_TIPO = 'PROCEDURE';
  TMPDICC01_NOMBRE = 'Procedimientos';
  TMPDICC01_OBJETO = '';
  TMPDICC01_ORDEN = 30;
  TMPDICC01_FAPL = CURRENT_TIMESTAMP;
  SUSPEND;

  FOR
    SELECT DISTINCT
        TRIM(DB.TMPPLUGDB01_OBJETO),
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO))
    FROM TMP_PLUGDB01 DB
    JOIN (
      /* Dependencias reales del motor: objetos que usa el objeto seleccionado. */
      SELECT
          TRIM(D.RDB$DEPENDED_ON_NAME) AS OBJETO
      FROM RDB$DEPENDENCIES D
      WHERE TRIM(D.RDB$DEPENDENT_NAME) = :V_OBJETO

      UNION

      /* Impacto directo: objetos que usan al objeto seleccionado. */
      SELECT
          TRIM(D.RDB$DEPENDENT_NAME) AS OBJETO
      FROM RDB$DEPENDENCIES D
      WHERE TRIM(D.RDB$DEPENDED_ON_NAME) = :V_OBJETO

      UNION

      /* Foreign keys salientes: tablas referenciadas por la tabla seleccionada. */
      SELECT
          TRIM(PK.RDB$RELATION_NAME) AS OBJETO
      FROM RDB$RELATION_CONSTRAINTS FK
      JOIN RDB$REF_CONSTRAINTS REF ON REF.RDB$CONSTRAINT_NAME = FK.RDB$CONSTRAINT_NAME
      JOIN RDB$RELATION_CONSTRAINTS PK ON PK.RDB$CONSTRAINT_NAME = REF.RDB$CONST_NAME_UQ
      WHERE FK.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
        AND TRIM(FK.RDB$RELATION_NAME) = :V_OBJETO

      UNION

      /* Foreign keys entrantes: tablas que referencian la tabla seleccionada. */
      SELECT
          TRIM(FK.RDB$RELATION_NAME) AS OBJETO
      FROM RDB$RELATION_CONSTRAINTS FK
      JOIN RDB$REF_CONSTRAINTS REF ON REF.RDB$CONSTRAINT_NAME = FK.RDB$CONSTRAINT_NAME
      JOIN RDB$RELATION_CONSTRAINTS PK ON PK.RDB$CONSTRAINT_NAME = REF.RDB$CONST_NAME_UQ
      WHERE FK.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
        AND TRIM(PK.RDB$RELATION_NAME) = :V_OBJETO

      UNION

      /*
       * RELA_ salientes usando SP_PLUGIN_FIELDS:
       * el objeto seleccionado declara RELA_ALIAS y se busca el objeto real
       * en SP_PLUGIN_DB por el alias Venture.
       */
      SELECT
          TRIM(DB_REL.TMPPLUGDB01_OBJETO) AS OBJETO
      FROM SP_PLUGIN_FIELDS(:V_TIPO_OBJETO, :V_OBJETO) FLD
      JOIN TMP_PLUGDB01 DB_REL
        ON DB_REL.TMPPLUGDB01_USUARIO = CURRENT_USER
       AND TRIM(DB_REL.TMPPLUGDB01_OBJETO) STARTING WITH SUBSTRING(TRIM(FLD.TMPFLD01_CAMPO) FROM 6 FOR 9)
      WHERE TRIM(FLD.TMPFLD01_CAMPO) STARTING WITH 'RELA_'
        AND NOT (TRIM(FLD.TMPFLD01_CAMPO) STARTING WITH 'RELA_SOCSYST10')
        AND COALESCE(TRIM(DB_REL.TMPPLUGDB01_OBJETO), '') <> ''

      UNION

      /*
       * RELA_SOCSYST10 usando la regla Venture encapsulada en
       * SP_PLUGIN_SOCSYST10.
       */
      SELECT
          TRIM(SS10.TMPSS10_OBJETO) AS OBJETO
      FROM SP_PLUGIN_FIELDS(:V_TIPO_OBJETO, :V_OBJETO) FLD
      JOIN SP_PLUGIN_SOCSYST10(TRIM(FLD.TMPFLD01_CAMPO)) SS10
        ON COALESCE(TRIM(SS10.TMPSS10_OBJETO), '') <> ''
      WHERE TRIM(FLD.TMPFLD01_CAMPO) STARTING WITH 'RELA_SOCSYST10'

      UNION

      /*
       * RELA_ entrantes:
       * objetos que tienen un campo RELA_ALIAS apuntando al alias del objeto
       * seleccionado. Esta parte usa metadata directa porque Firebird 2.5 no
       * permite invocar cÃ³modamente SP_PLUGIN_FIELDS por cada fila del
       * diccionario dentro de un SELECT correlacionado.
       */
      SELECT
          TRIM(RF.RDB$RELATION_NAME) AS OBJETO
      FROM RDB$RELATION_FIELDS RF
      JOIN RDB$RELATIONS R ON R.RDB$RELATION_NAME = RF.RDB$RELATION_NAME
      WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
        AND TRIM(RF.RDB$FIELD_NAME) STARTING WITH 'RELA_' || :V_ALIAS
    ) X ON TRIM(DB.TMPPLUGDB01_OBJETO) = X.OBJETO
    WHERE DB.TMPPLUGDB01_USUARIO = CURRENT_USER
      AND COALESCE(TRIM(DB.TMPPLUGDB01_OBJETO), '') <> ''
      AND TRIM(DB.TMPPLUGDB01_OBJETO) <> :V_OBJETO
      AND (
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO)) IN ('TABLE', 'VIEW', 'PROCEDURE') OR
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO)) IN ('TABLA', 'VISTA', 'PROCEDIMIENTO') OR
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO)) IN ('T', 'V', 'P', 'SP')
      )
    ORDER BY 2, 1
    INTO :V_DEP_NAME, :V_DEP_TYPE
  DO
  BEGIN
    V_PARENT_ID = NULL;
    V_OUT_ORDEN = 0;

    IF ((V_DEP_TYPE = 'TABLE') OR (V_DEP_TYPE = 'TABLA') OR (V_DEP_TYPE = 'T')) THEN
    BEGIN
      V_DEP_TYPE = 'TABLE';
      V_PARENT_ID = 'ROOT_TABLES';
      V_OUT_ORDEN = 11;
    END

    IF ((V_DEP_TYPE = 'VIEW') OR (V_DEP_TYPE = 'VISTA') OR (V_DEP_TYPE = 'V')) THEN
    BEGIN
      V_DEP_TYPE = 'VIEW';
      V_PARENT_ID = 'ROOT_VIEWS';
      V_OUT_ORDEN = 21;
    END

    IF ((V_DEP_TYPE = 'PROCEDURE') OR (V_DEP_TYPE = 'PROCEDIMIENTO') OR (V_DEP_TYPE = 'P') OR (V_DEP_TYPE = 'SP')) THEN
    BEGIN
      V_DEP_TYPE = 'PROCEDURE';
      V_PARENT_ID = 'ROOT_PROCEDURES';
      V_OUT_ORDEN = 31;
    END

    IF (V_PARENT_ID IS NOT NULL) THEN
    BEGIN
      ID_TMPDICC01 = ID_TMPDICC01 + 1;
      TMPDICC01_NODE_ID = V_DEP_TYPE || '_' || V_DEP_NAME;
      TMPDICC01_PARENT_ID = V_PARENT_ID;
      TMPDICC01_TIPO = V_DEP_TYPE;
      TMPDICC01_NOMBRE = V_DEP_NAME;
      TMPDICC01_OBJETO = V_DEP_NAME;
      TMPDICC01_ORDEN = V_OUT_ORDEN;
      TMPDICC01_FAPL = CURRENT_TIMESTAMP;
      SUSPEND;
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_PLUGIN_FIELDS (
    P_TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_OBJETO VARCHAR(63) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    ID_TMPFLD01 INTEGER,
    TMPFLD01_TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_OBJETO VARCHAR(63) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_SECCION VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_CAMPO VARCHAR(63) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_POSICION INTEGER,
    TMPFLD01_TIPO_DATO VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_LONGITUD INTEGER,
    TMPFLD01_ESCALA INTEGER,
    TMPFLD01_PRECISION INTEGER,
    TMPFLD01_REQUERIDO VARCHAR(1) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPFLD01_FAPL TIMESTAMP)
AS
DECLARE VARIABLE V_TIPO_OBJETO VARCHAR(20);
DECLARE VARIABLE V_OBJETO VARCHAR(63);
DECLARE VARIABLE V_FIELD_TYPE SMALLINT;
DECLARE VARIABLE V_FIELD_SUB_TYPE SMALLINT;
DECLARE VARIABLE V_FIELD_LENGTH SMALLINT;
DECLARE VARIABLE V_FIELD_SCALE SMALLINT;
DECLARE VARIABLE V_FIELD_PRECISION SMALLINT;
DECLARE VARIABLE V_NULL_FLAG SMALLINT;
BEGIN
  ID_TMPFLD01 = 0;
  V_TIPO_OBJETO = UPPER(TRIM(:P_TIPO_OBJETO));
  V_OBJETO = UPPER(TRIM(:P_OBJETO));

  IF ((V_TIPO_OBJETO = 'TABLE') OR (V_TIPO_OBJETO = 'VIEW')) THEN
  BEGIN
    FOR
      SELECT
          TRIM(RF.RDB$FIELD_NAME),
          RF.RDB$FIELD_POSITION,
          F.RDB$FIELD_TYPE,
          COALESCE(F.RDB$FIELD_SUB_TYPE, 0),
          COALESCE(F.RDB$FIELD_LENGTH, 0),
          COALESCE(F.RDB$FIELD_SCALE, 0),
          COALESCE(F.RDB$FIELD_PRECISION, 0),
          COALESCE(RF.RDB$NULL_FLAG, F.RDB$NULL_FLAG)
      FROM RDB$RELATION_FIELDS RF
      JOIN RDB$FIELDS F ON F.RDB$FIELD_NAME = RF.RDB$FIELD_SOURCE
      JOIN RDB$RELATIONS R ON R.RDB$RELATION_NAME = RF.RDB$RELATION_NAME
      WHERE RF.RDB$RELATION_NAME = :V_OBJETO
        AND COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
      ORDER BY RF.RDB$FIELD_POSITION
      INTO
          :TMPFLD01_CAMPO,
          :TMPFLD01_POSICION,
          :V_FIELD_TYPE,
          :V_FIELD_SUB_TYPE,
          :V_FIELD_LENGTH,
          :V_FIELD_SCALE,
          :V_FIELD_PRECISION,
          :V_NULL_FLAG
    DO
    BEGIN
      ID_TMPFLD01 = ID_TMPFLD01 + 1;
      TMPFLD01_TIPO_OBJETO = V_TIPO_OBJETO;
      TMPFLD01_OBJETO = V_OBJETO;
      TMPFLD01_SECCION = 'CAMPO';
      TMPFLD01_TIPO_DATO = 'UNKNOWN';
      TMPFLD01_LONGITUD = V_FIELD_LENGTH;
      TMPFLD01_ESCALA = V_FIELD_SCALE;
      TMPFLD01_PRECISION = V_FIELD_PRECISION;
      TMPFLD01_REQUERIDO = IIF(V_NULL_FLAG = 1, 'S', 'N');
      TMPFLD01_FAPL = CURRENT_TIMESTAMP;

      IF (V_FIELD_TYPE = 7) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'SMALLINT'));
      IF (V_FIELD_TYPE = 8) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'INTEGER'));
      IF (V_FIELD_TYPE = 10) THEN TMPFLD01_TIPO_DATO = 'FLOAT';
      IF (V_FIELD_TYPE = 12) THEN TMPFLD01_TIPO_DATO = 'DATE';
      IF (V_FIELD_TYPE = 13) THEN TMPFLD01_TIPO_DATO = 'TIME';
      IF (V_FIELD_TYPE = 14) THEN TMPFLD01_TIPO_DATO = 'CHAR';
      IF (V_FIELD_TYPE = 16) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'BIGINT'));
      IF (V_FIELD_TYPE = 27) THEN TMPFLD01_TIPO_DATO = 'DOUBLE PRECISION';
      IF (V_FIELD_TYPE = 35) THEN TMPFLD01_TIPO_DATO = 'TIMESTAMP';
      IF (V_FIELD_TYPE = 37) THEN TMPFLD01_TIPO_DATO = 'VARCHAR';
      IF (V_FIELD_TYPE = 261) THEN TMPFLD01_TIPO_DATO = 'BLOB';

      SUSPEND;
    END
  END

  IF (V_TIPO_OBJETO = 'PROCEDURE') THEN
  BEGIN
    FOR
      SELECT
          TRIM(P.RDB$PARAMETER_NAME),
          P.RDB$PARAMETER_NUMBER,
          F.RDB$FIELD_TYPE,
          COALESCE(F.RDB$FIELD_SUB_TYPE, 0),
          COALESCE(F.RDB$FIELD_LENGTH, 0),
          COALESCE(F.RDB$FIELD_SCALE, 0),
          COALESCE(F.RDB$FIELD_PRECISION, 0),
          COALESCE(P.RDB$NULL_FLAG, F.RDB$NULL_FLAG)
      FROM RDB$PROCEDURE_PARAMETERS P
      JOIN RDB$FIELDS F ON F.RDB$FIELD_NAME = P.RDB$FIELD_SOURCE
      WHERE P.RDB$PROCEDURE_NAME = :V_OBJETO
        AND P.RDB$PARAMETER_TYPE = 0
      ORDER BY P.RDB$PARAMETER_NUMBER
      INTO
          :TMPFLD01_CAMPO,
          :TMPFLD01_POSICION,
          :V_FIELD_TYPE,
          :V_FIELD_SUB_TYPE,
          :V_FIELD_LENGTH,
          :V_FIELD_SCALE,
          :V_FIELD_PRECISION,
          :V_NULL_FLAG
    DO
    BEGIN
      ID_TMPFLD01 = ID_TMPFLD01 + 1;
      TMPFLD01_TIPO_OBJETO = V_TIPO_OBJETO;
      TMPFLD01_OBJETO = V_OBJETO;
      TMPFLD01_SECCION = 'PARAMETRO';
      TMPFLD01_TIPO_DATO = 'UNKNOWN';
      TMPFLD01_LONGITUD = V_FIELD_LENGTH;
      TMPFLD01_ESCALA = V_FIELD_SCALE;
      TMPFLD01_PRECISION = V_FIELD_PRECISION;
      TMPFLD01_REQUERIDO = IIF(V_NULL_FLAG = 1, 'S', 'N');
      TMPFLD01_FAPL = CURRENT_TIMESTAMP;

      IF (V_FIELD_TYPE = 7) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'SMALLINT'));
      IF (V_FIELD_TYPE = 8) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'INTEGER'));
      IF (V_FIELD_TYPE = 10) THEN TMPFLD01_TIPO_DATO = 'FLOAT';
      IF (V_FIELD_TYPE = 12) THEN TMPFLD01_TIPO_DATO = 'DATE';
      IF (V_FIELD_TYPE = 13) THEN TMPFLD01_TIPO_DATO = 'TIME';
      IF (V_FIELD_TYPE = 14) THEN TMPFLD01_TIPO_DATO = 'CHAR';
      IF (V_FIELD_TYPE = 16) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'BIGINT'));
      IF (V_FIELD_TYPE = 27) THEN TMPFLD01_TIPO_DATO = 'DOUBLE PRECISION';
      IF (V_FIELD_TYPE = 35) THEN TMPFLD01_TIPO_DATO = 'TIMESTAMP';
      IF (V_FIELD_TYPE = 37) THEN TMPFLD01_TIPO_DATO = 'VARCHAR';
      IF (V_FIELD_TYPE = 261) THEN TMPFLD01_TIPO_DATO = 'BLOB';

      SUSPEND;
    END

    FOR
      SELECT
          TRIM(P.RDB$PARAMETER_NAME),
          P.RDB$PARAMETER_NUMBER,
          F.RDB$FIELD_TYPE,
          COALESCE(F.RDB$FIELD_SUB_TYPE, 0),
          COALESCE(F.RDB$FIELD_LENGTH, 0),
          COALESCE(F.RDB$FIELD_SCALE, 0),
          COALESCE(F.RDB$FIELD_PRECISION, 0),
          COALESCE(P.RDB$NULL_FLAG, F.RDB$NULL_FLAG)
      FROM RDB$PROCEDURE_PARAMETERS P
      JOIN RDB$FIELDS F ON F.RDB$FIELD_NAME = P.RDB$FIELD_SOURCE
      WHERE P.RDB$PROCEDURE_NAME = :V_OBJETO
        AND P.RDB$PARAMETER_TYPE = 1
      ORDER BY P.RDB$PARAMETER_NUMBER
      INTO
          :TMPFLD01_CAMPO,
          :TMPFLD01_POSICION,
          :V_FIELD_TYPE,
          :V_FIELD_SUB_TYPE,
          :V_FIELD_LENGTH,
          :V_FIELD_SCALE,
          :V_FIELD_PRECISION,
          :V_NULL_FLAG
    DO
    BEGIN
      ID_TMPFLD01 = ID_TMPFLD01 + 1;
      TMPFLD01_TIPO_OBJETO = V_TIPO_OBJETO;
      TMPFLD01_OBJETO = V_OBJETO;
      TMPFLD01_SECCION = 'SALIDA';
      TMPFLD01_TIPO_DATO = 'UNKNOWN';
      TMPFLD01_LONGITUD = V_FIELD_LENGTH;
      TMPFLD01_ESCALA = V_FIELD_SCALE;
      TMPFLD01_PRECISION = V_FIELD_PRECISION;
      TMPFLD01_REQUERIDO = IIF(V_NULL_FLAG = 1, 'S', 'N');
      TMPFLD01_FAPL = CURRENT_TIMESTAMP;

      IF (V_FIELD_TYPE = 7) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'SMALLINT'));
      IF (V_FIELD_TYPE = 8) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'INTEGER'));
      IF (V_FIELD_TYPE = 10) THEN TMPFLD01_TIPO_DATO = 'FLOAT';
      IF (V_FIELD_TYPE = 12) THEN TMPFLD01_TIPO_DATO = 'DATE';
      IF (V_FIELD_TYPE = 13) THEN TMPFLD01_TIPO_DATO = 'TIME';
      IF (V_FIELD_TYPE = 14) THEN TMPFLD01_TIPO_DATO = 'CHAR';
      IF (V_FIELD_TYPE = 16) THEN TMPFLD01_TIPO_DATO = IIF(V_FIELD_SUB_TYPE = 1, 'NUMERIC', IIF(V_FIELD_SUB_TYPE = 2, 'DECIMAL', 'BIGINT'));
      IF (V_FIELD_TYPE = 27) THEN TMPFLD01_TIPO_DATO = 'DOUBLE PRECISION';
      IF (V_FIELD_TYPE = 35) THEN TMPFLD01_TIPO_DATO = 'TIMESTAMP';
      IF (V_FIELD_TYPE = 37) THEN TMPFLD01_TIPO_DATO = 'VARCHAR';
      IF (V_FIELD_TYPE = 261) THEN TMPFLD01_TIPO_DATO = 'BLOB';

      SUSPEND;
    END
  END
END^


CREATE OR ALTER PROCEDURE SP_PLUGIN_SOCSYST10 (
    P_RELA VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
RETURNS (
    TMPSS10_OBJETO VARCHAR(80) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPSS10_TIPO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    TMPSS10_FAPL TIMESTAMP)
AS
DECLARE VARIABLE V_RELA VARCHAR(80);
DECLARE VARIABLE V_PAYLOAD VARCHAR(80);
DECLARE VARIABLE V_SUFFIX VARCHAR(80);
DECLARE VARIABLE V_CODIGO VARCHAR(5);
DECLARE VARIABLE V_MASK VARCHAR(80);
BEGIN
  V_RELA = UPPER(TRIM(:P_RELA));
  TMPSS10_FAPL = CURRENT_TIMESTAMP;

  IF (NOT (V_RELA STARTING WITH 'RELA_SOCSYST10')) THEN
    EXIT;

  V_PAYLOAD = SUBSTRING(:V_RELA FROM 15);
  V_PAYLOAD = TRIM(:V_PAYLOAD);

  IF ((V_PAYLOAD IS NULL) OR (V_PAYLOAD = '')) THEN
  BEGIN
    FOR
      SELECT FIRST 1
          TRIM(DB.TMPPLUGDB01_OBJETO),
          UPPER(TRIM(DB.TMPPLUGDB01_TIPO))
      FROM TMP_PLUGDB01 DB
      WHERE DB.TMPPLUGDB01_USUARIO = CURRENT_USER
        AND TRIM(DB.TMPPLUGDB01_OBJETO) STARTING WITH 'SOCSYST10'
        AND UPPER(TRIM(DB.TMPPLUGDB01_TIPO)) IN ('TABLE', 'TABLA', 'T')
      ORDER BY TRIM(DB.TMPPLUGDB01_OBJETO)
      INTO :TMPSS10_OBJETO, :TMPSS10_TIPO
    DO
    BEGIN
      TMPSS10_TIPO = 'TABLE';
      SUSPEND;
    END
    EXIT;
  END

  V_SUFFIX = :V_PAYLOAD;
  IF (V_SUFFIX STARTING WITH '_') THEN
    V_SUFFIX = SUBSTRING(:V_SUFFIX FROM 2);

  IF (CHAR_LENGTH(:V_SUFFIX) < 5) THEN
    EXIT;

  V_CODIGO = SUBSTRING(:V_SUFFIX FROM 1 FOR 3) || SUBSTRING(:V_SUFFIX FROM 4 FOR 2);
  V_MASK = 'CBO_SOCSYST10_' || :V_CODIGO;

  FOR
    SELECT DISTINCT
        TRIM(DB.TMPPLUGDB01_OBJETO),
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO))
    FROM TMP_PLUGDB01 DB
    WHERE DB.TMPPLUGDB01_USUARIO = CURRENT_USER
      AND TRIM(DB.TMPPLUGDB01_OBJETO) STARTING WITH :V_MASK
      AND (
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO)) IN ('VIEW', 'VISTA', 'V') OR
        UPPER(TRIM(DB.TMPPLUGDB01_TIPO)) IN ('PROCEDURE', 'PROCEDIMIENTO', 'P', 'SP')
      )
    ORDER BY 2, 1
    INTO :TMPSS10_OBJETO, :TMPSS10_TIPO
  DO
  BEGIN
    IF ((TMPSS10_TIPO = 'VISTA') OR (TMPSS10_TIPO = 'V')) THEN
      TMPSS10_TIPO = 'VIEW';

    IF ((TMPSS10_TIPO = 'PROCEDIMIENTO') OR (TMPSS10_TIPO = 'P') OR (TMPSS10_TIPO = 'SP')) THEN
      TMPSS10_TIPO = 'PROCEDURE';

    SUSPEND;
  END
END^


CREATE OR ALTER PROCEDURE SP_PREVIEW_DROP_BY_ALIAS (
    P_ALIAS VARCHAR(31) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    P_MAX_LEVEL INTEGER)
RETURNS (
    ORDEN INTEGER,
    FASE VARCHAR(50) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NIVEL INTEGER,
    TIPO_OBJETO VARCHAR(20) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    OBJETO VARCHAR(255) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    COMANDO_SQL VARCHAR(8191) CHARACTER SET ISO8859_1 COLLATE ISO8859_1,
    NOTA VARCHAR(2000) CHARACTER SET ISO8859_1 COLLATE ISO8859_1)
AS
DECLARE VARIABLE V_ALIAS VARCHAR(31);
DECLARE VARIABLE V_TARGET_TABLE VARCHAR(31);
DECLARE VARIABLE V_COUNT INTEGER;
DECLARE VARIABLE V_LEVEL INTEGER;
DECLARE VARIABLE V_BEFORE INTEGER;
DECLARE VARIABLE V_AFTER INTEGER;
DECLARE VARIABLE V_NAME VARCHAR(255);
DECLARE VARIABLE V_TYPE VARCHAR(20);
DECLARE VARIABLE V_SQL VARCHAR(8191);
BEGIN
  DELETE FROM TMP_DROP_BY_ALIAS_DEP;

  V_ALIAS = UPPER(TRIM(P_ALIAS));
  IF (P_MAX_LEVEL IS NULL OR P_MAX_LEVEL < 1) THEN
    P_MAX_LEVEL = 10;

  ORDEN = 0;

  /***************************************************************************
    Resolver alias -> tabla real.
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NULL
    AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE (:V_ALIAS || '\_%') ESCAPE '\'
  INTO :V_COUNT;

  IF (V_COUNT = 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR';
    NIVEL = NULL;
    TIPO_OBJETO = NULL;
    OBJETO = V_ALIAS;
    COMANDO_SQL = NULL;
    NOTA = 'No se encontro tabla real para el alias.';
    SUSPEND;
    EXIT;
  END

  IF (V_COUNT > 1) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'ERROR_ALIAS_AMBIGUO';
    NIVEL = NULL;
    TIPO_OBJETO = NULL;
    OBJETO = V_ALIAS;
    COMANDO_SQL = NULL;
    NOTA = 'El alias encontro mas de una tabla. Candidatos abajo.';
    SUSPEND;

    FOR
      SELECT TRIM(R.RDB$RELATION_NAME)
      FROM RDB$RELATIONS R
      WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
        AND R.RDB$VIEW_BLR IS NULL
        AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE (:V_ALIAS || '\_%') ESCAPE '\'
      ORDER BY R.RDB$RELATION_NAME
      INTO :V_NAME
    DO
    BEGIN
      ORDEN = ORDEN + 1;
      FASE = 'CANDIDATO_TABLA';
      NIVEL = NULL;
      TIPO_OBJETO = 'TABLE';
      OBJETO = V_NAME;
      COMANDO_SQL = NULL;
      NOTA = 'Candidato para el alias.';
      SUSPEND;
    END

    EXIT;
  END

  SELECT FIRST 1 TRIM(R.RDB$RELATION_NAME)
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NULL
    AND UPPER(TRIM(R.RDB$RELATION_NAME)) LIKE (:V_ALIAS || '\_%') ESCAPE '\'
  ORDER BY R.RDB$RELATION_NAME
  INTO :V_TARGET_TABLE;

  ORDEN = ORDEN + 1;
  FASE = 'INFO_TABLA';
  NIVEL = NULL;
  TIPO_OBJETO = 'TABLE';
  OBJETO = V_TARGET_TABLE;
  COMANDO_SQL = NULL;
  NOTA = 'Alias ' || V_ALIAS || ' resuelto a tabla real.';
  SUSPEND;

  /***************************************************************************
    Mostrar triggers propios de la tabla como INFO.
  ***************************************************************************/
  FOR
    SELECT TRIM(T.RDB$TRIGGER_NAME)
    FROM RDB$TRIGGERS T
    WHERE T.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
    ORDER BY T.RDB$TRIGGER_NAME
    INTO :V_NAME
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'INFO_TRIGGER_PROPIO';
    NIVEL = NULL;
    TIPO_OBJETO = 'TRIGGER';
    OBJETO = V_NAME;
    COMANDO_SQL = NULL;
    NOTA = 'Trigger propio de la tabla. No se genera DROP porque DROP TABLE debe borrarlo automaticamente.';
    SUSPEND;
  END

  /***************************************************************************
    Nivel 1: objetos que usan directamente la tabla.
    Excluimos triggers propios de la tabla objetivo.
  ***************************************************************************/
  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    D.RDB$DEPENDENT_NAME,
    CASE
      WHEN EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME) THEN 'PROCEDURE'
      WHEN EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL) THEN 'VIEW'
      ELSE 'TRIGGER'
    END,
    1
  FROM RDB$DEPENDENCIES D
  WHERE D.RDB$DEPENDED_ON_NAME = :V_TARGET_TABLE
    AND (
      EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME)
      OR EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL)
      OR EXISTS (
        SELECT 1
        FROM RDB$TRIGGERS T
        WHERE T.RDB$TRIGGER_NAME = D.RDB$DEPENDENT_NAME
          AND COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM RDB$TRIGGERS TP
      WHERE TP.RDB$TRIGGER_NAME = D.RDB$DEPENDENT_NAME
        AND TP.RDB$RELATION_NAME = :V_TARGET_TABLE
    );

  /***************************************************************************
    Nivel 1 respaldo por texto de source.

    Motivo:
      En esta base RDB$DEPENDENCIES no siempre reporta todo. Ejemplo real:
      GRD_SICINGR85_WEB usaba ADUCTAG02_DET_ANTICIPOS en una subconsulta, pero
      no salia como VIEW dependiente en la salida del SP solo por metadata.

    Este bloque busca menciones de la tabla real dentro de:
      - RDB$VIEW_SOURCE
      - RDB$PROCEDURE_SOURCE
      - RDB$TRIGGER_SOURCE

    No es perfecto semanticamente, pero como el SP solo genera PREVIEW, es una
    capa de seguridad muy util.
  ***************************************************************************/

  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    R.RDB$RELATION_NAME,
    'VIEW',
    1
  FROM RDB$RELATIONS R
  WHERE COALESCE(R.RDB$SYSTEM_FLAG, 0) = 0
    AND R.RDB$VIEW_BLR IS NOT NULL
    AND R.RDB$VIEW_SOURCE CONTAINING :V_TARGET_TABLE
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = R.RDB$RELATION_NAME
    );

  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    P.RDB$PROCEDURE_NAME,
    'PROCEDURE',
    1
  FROM RDB$PROCEDURES P
  WHERE P.RDB$PROCEDURE_SOURCE CONTAINING :V_TARGET_TABLE
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = P.RDB$PROCEDURE_NAME
    );

  INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
  SELECT DISTINCT
    T.RDB$TRIGGER_NAME,
    'TRIGGER',
    1
  FROM RDB$TRIGGERS T
  WHERE COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
    AND T.RDB$TRIGGER_SOURCE CONTAINING :V_TARGET_TABLE
    AND NOT EXISTS (
      SELECT 1
      FROM RDB$TRIGGERS TP
      WHERE TP.RDB$TRIGGER_NAME = T.RDB$TRIGGER_NAME
        AND TP.RDB$RELATION_NAME = :V_TARGET_TABLE
    )
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = T.RDB$TRIGGER_NAME
    );

  /***************************************************************************
    Niveles 2..P_MAX_LEVEL:
    objetos que usan los objetos del nivel anterior.
  ***************************************************************************/
  V_LEVEL = 2;
  WHILE (V_LEVEL <= P_MAX_LEVEL) DO
  BEGIN
    SELECT COUNT(*) FROM TMP_DROP_BY_ALIAS_DEP INTO :V_BEFORE;

    INSERT INTO TMP_DROP_BY_ALIAS_DEP (OBJ_NAME, OBJ_TYPE, NIVEL)
    SELECT DISTINCT
      D.RDB$DEPENDENT_NAME,
      CASE
        WHEN EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME) THEN 'PROCEDURE'
        WHEN EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL) THEN 'VIEW'
        ELSE 'TRIGGER'
      END,
      :V_LEVEL
    FROM RDB$DEPENDENCIES D
    JOIN TMP_DROP_BY_ALIAS_DEP L
      ON D.RDB$DEPENDED_ON_NAME = L.OBJ_NAME
     AND L.NIVEL = (:V_LEVEL - 1)
    WHERE (
      EXISTS (SELECT 1 FROM RDB$PROCEDURES P WHERE P.RDB$PROCEDURE_NAME = D.RDB$DEPENDENT_NAME)
      OR EXISTS (SELECT 1 FROM RDB$RELATIONS R WHERE R.RDB$RELATION_NAME = D.RDB$DEPENDENT_NAME AND R.RDB$VIEW_BLR IS NOT NULL)
      OR EXISTS (
        SELECT 1
        FROM RDB$TRIGGERS T
        WHERE T.RDB$TRIGGER_NAME = D.RDB$DEPENDENT_NAME
          AND COALESCE(T.RDB$SYSTEM_FLAG, 0) = 0
      )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM TMP_DROP_BY_ALIAS_DEP X
      WHERE X.OBJ_NAME = D.RDB$DEPENDENT_NAME
    );

    SELECT COUNT(*) FROM TMP_DROP_BY_ALIAS_DEP INTO :V_AFTER;

    IF (V_AFTER = V_BEFORE) THEN
      V_LEVEL = P_MAX_LEVEL + 1;
    ELSE
      V_LEVEL = V_LEVEL + 1;
  END

  /***************************************************************************
    Salida de cascada: niveles mas lejanos primero.
  ***************************************************************************/
  FOR
    SELECT
      D.NIVEL,
      D.OBJ_TYPE,
      TRIM(D.OBJ_NAME),
      CASE
        WHEN D.OBJ_TYPE = 'PROCEDURE' THEN 'DROP PROCEDURE ' || TRIM(D.OBJ_NAME) || ';'
        WHEN D.OBJ_TYPE = 'VIEW' THEN 'DROP VIEW ' || TRIM(D.OBJ_NAME) || ';'
        WHEN D.OBJ_TYPE = 'TRIGGER' THEN 'DROP TRIGGER ' || TRIM(D.OBJ_NAME) || ';'
        ELSE '/* Revisar manualmente: ' || TRIM(D.OBJ_NAME) || ' */'
      END
    FROM TMP_DROP_BY_ALIAS_DEP D
    ORDER BY D.NIVEL DESC, D.OBJ_TYPE, D.OBJ_NAME
    INTO :NIVEL, :V_TYPE, :V_NAME, :V_SQL
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_DEPENDIENTE';
    TIPO_OBJETO = V_TYPE;
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'Objeto que usa directa o indirectamente la tabla. Borrar consumidores primero.';
    SUSPEND;
  END

  /***************************************************************************
    FK entrantes: otras tablas apuntan a la tabla objetivo.
  ***************************************************************************/
  FOR
    SELECT
      'ALTER TABLE ' || TRIM(FK.RDB$RELATION_NAME) ||
      ' DROP CONSTRAINT ' || TRIM(FK.RDB$CONSTRAINT_NAME) || ';',
      TRIM(FK.RDB$RELATION_NAME) || '.' || TRIM(FK.RDB$CONSTRAINT_NAME)
    FROM RDB$RELATION_CONSTRAINTS PK
    JOIN RDB$REF_CONSTRAINTS RF
      ON RF.RDB$CONST_NAME_UQ = PK.RDB$CONSTRAINT_NAME
    JOIN RDB$RELATION_CONSTRAINTS FK
      ON FK.RDB$CONSTRAINT_NAME = RF.RDB$CONSTRAINT_NAME
    WHERE PK.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND FK.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
    ORDER BY FK.RDB$RELATION_NAME, FK.RDB$CONSTRAINT_NAME
    INTO :V_SQL, :V_NAME
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_FK_ENTRANTE';
    NIVEL = NULL;
    TIPO_OBJETO = 'CONSTRAINT';
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'FK de otra tabla hacia la tabla objetivo.';
    SUSPEND;
  END

  /***************************************************************************
    FK salientes: la tabla objetivo apunta a otras tablas.
  ***************************************************************************/
  FOR
    SELECT
      'ALTER TABLE ' || TRIM(RC.RDB$RELATION_NAME) ||
      ' DROP CONSTRAINT ' || TRIM(RC.RDB$CONSTRAINT_NAME) || ';',
      TRIM(RC.RDB$RELATION_NAME) || '.' || TRIM(RC.RDB$CONSTRAINT_NAME)
    FROM RDB$RELATION_CONSTRAINTS RC
    WHERE RC.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND RC.RDB$CONSTRAINT_TYPE = 'FOREIGN KEY'
    ORDER BY RC.RDB$CONSTRAINT_NAME
    INTO :V_SQL, :V_NAME
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_FK_SALIENTE';
    NIVEL = NULL;
    TIPO_OBJETO = 'CONSTRAINT';
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'FK propia de la tabla objetivo hacia otra tabla.';
    SUSPEND;
  END

  /***************************************************************************
    Constraints propias no-FK: UNIQUE, CHECK, PRIMARY KEY.
  ***************************************************************************/
  FOR
    SELECT
      'ALTER TABLE ' || TRIM(RC.RDB$RELATION_NAME) ||
      ' DROP CONSTRAINT ' || TRIM(RC.RDB$CONSTRAINT_NAME) || ';',
      TRIM(RC.RDB$RELATION_NAME) || '.' || TRIM(RC.RDB$CONSTRAINT_NAME),
      TRIM(RC.RDB$CONSTRAINT_TYPE)
    FROM RDB$RELATION_CONSTRAINTS RC
    WHERE RC.RDB$RELATION_NAME = :V_TARGET_TABLE
      AND RC.RDB$CONSTRAINT_TYPE <> 'FOREIGN KEY'
    ORDER BY
      CASE RC.RDB$CONSTRAINT_TYPE
        WHEN 'CHECK' THEN 1
        WHEN 'UNIQUE' THEN 2
        WHEN 'PRIMARY KEY' THEN 3
        ELSE 9
      END,
      RC.RDB$CONSTRAINT_NAME
    INTO :V_SQL, :V_NAME, :V_TYPE
  DO
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_CONSTRAINT_PROPIA';
    NIVEL = NULL;
    TIPO_OBJETO = V_TYPE;
    OBJETO = V_NAME;
    COMANDO_SQL = V_SQL;
    NOTA = 'Constraint propia de la tabla objetivo.';
    SUSPEND;
  END

  /***************************************************************************
    DROP TABLE.
  ***************************************************************************/
  ORDEN = ORDEN + 1;
  FASE = 'DROP_TABLE';
  NIVEL = NULL;
  TIPO_OBJETO = 'TABLE';
  OBJETO = V_TARGET_TABLE;
  COMANDO_SQL = 'DROP TABLE ' || V_TARGET_TABLE || ';';
  NOTA = 'Al borrar la tabla se borran sus triggers propios.';
  SUSPEND;

  /***************************************************************************
    DROP GENERATOR al final.
  ***************************************************************************/
  SELECT COUNT(*)
  FROM RDB$GENERATORS G
  WHERE COALESCE(G.RDB$SYSTEM_FLAG, 0) = 0
    AND TRIM(G.RDB$GENERATOR_NAME) = ('SID_' || :V_ALIAS)
  INTO :V_COUNT;

  IF (V_COUNT > 0) THEN
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'DROP_GENERATOR';
    NIVEL = NULL;
    TIPO_OBJETO = 'GENERATOR';
    OBJETO = 'SID_' || V_ALIAS;
    COMANDO_SQL = 'DROP GENERATOR SID_' || V_ALIAS || ';';
    NOTA = 'Generator por convencion. Va al final, despues del DROP TABLE.';
    SUSPEND;
  END
  ELSE
  BEGIN
    ORDEN = ORDEN + 1;
    FASE = 'INFO_GENERATOR';
    NIVEL = NULL;
    TIPO_OBJETO = 'GENERATOR';
    OBJETO = 'SID_' || V_ALIAS;
    COMANDO_SQL = NULL;
    NOTA = 'No existe generator exacto SID_' || V_ALIAS || '. Revisar manualmente si aplica.';
    SUSPEND;
  END
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICA_91 (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SICINGR95_DESTINO BIGINT)
AS
declare variable RELA_SYSJSON02 bigint;
declare variable ID_SICINGR91_DESTINO bigint;
BEGIN
    FOR SELECT origen.rela_sysjson02
    FROM sicingr91_det_imagenes origen
    WHERE origen.rela_sicingr95 = :id_sicingr95_origen
    INTO :rela_sysjson02
    DO
    BEGIN
        ID_SICINGR91_DESTINO = NULL;

        SELECT FIRST 1 destino.id_sicingr91
        FROM sicingr91_det_imagenes destino
        WHERE destino.rela_sicingr95 = :id_sicingr95_destino
        AND destino.rela_sysjson02 = :rela_sysjson02
        INTO :id_sicingr91_destino;

        IF (id_sicingr91_destino IS NULL) THEN
        BEGIN
            INSERT INTO sicingr91_det_imagenes (rela_sicingr95, rela_sysjson02)
            VALUES (:id_sicingr95_destino, :rela_sysjson02);
        END
    END
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICA_96 (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SICINGR95_DESTINO BIGINT,
    ID_SOCMAIN01_DESTINO BIGINT)
AS
DECLARE VARIABLE ID_SICXMLS01_ORIGEN BIGINT;
DECLARE VARIABLE ID_SICXMLS01_DESTINO BIGINT;
DECLARE VARIABLE ID_SICINGR90_DESTINO BIGINT;
DECLARE VARIABLE SICXMLS02_IMPUESTO VARCHAR(400);
DECLARE VARIABLE SICXMLS02_TIPO VARCHAR(1);
DECLARE VARIABLE SICXMLS02_RETENIDO INTEGER;
DECLARE VARIABLE SICXMLS02_TASA DOUBLE PRECISION;
BEGIN
    SELECT sicxmls01_cab_parametros.id_sicxmls01
    FROM sicingr95_cab_conceptos
    INNER JOIN sicxmls01_cab_parametros ON (sicxmls01_cab_parametros.id_sicxmls01 = sicingr95_cab_conceptos.rela_sicxmls01)
    WHERE sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen
    INTO :id_sicxmls01_origen;

    SELECT sicxmls01_cab_parametros.id_sicxmls01
    FROM sicxmls01_cab_parametros
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    INTO :id_sicxmls01_destino;

    FOR SELECT
        UPPER(TRIM(sicxmls02_det_impuestos.sicxmls02_impuesto)),
        sicxmls02_det_impuestos.sicxmls02_tipo,
        sicxmls02_det_impuestos.sicxmls02_retenido,
        sicxmls02_det_impuestos.sicxmls02_tasa
    FROM sicingr96_det_impuestos
    INNER JOIN sicingr90_cab_impuestos ON (sicingr90_cab_impuestos.id_sicingr90 = sicingr96_det_impuestos.rela_sicingr90)
    INNER JOIN sicxmls02_det_impuestos ON (sicxmls02_det_impuestos.id_sicxmls02 = sicingr90_cab_impuestos.rela_sicxmls02)
    WHERE sicingr90_cab_impuestos.rela_sicxmls01 = :id_sicxmls01_origen
    AND sicingr96_det_impuestos.rela_sicingr95 = :id_sicingr95_origen
    INTO :sicxmls02_impuesto,
         :sicxmls02_tipo,
         :sicxmls02_retenido,
         :sicxmls02_tasa
    DO
    BEGIN
        ID_SICINGR90_DESTINO = NULL;

        SELECT FIRST 1 sicingr90_cab_impuestos.id_sicingr90
        FROM sicingr90_cab_impuestos
        INNER JOIN sicxmls02_det_impuestos ON (sicxmls02_det_impuestos.id_sicxmls02 = sicingr90_cab_impuestos.rela_sicxmls02)
        WHERE sicingr90_cab_impuestos.rela_sicxmls01 = :id_sicxmls01_destino
        AND UPPER(TRIM(sicxmls02_det_impuestos.sicxmls02_impuesto)) = :sicxmls02_impuesto
        AND sicxmls02_det_impuestos.sicxmls02_tipo = :sicxmls02_tipo
        AND sicxmls02_det_impuestos.sicxmls02_retenido = :sicxmls02_retenido
        AND sicxmls02_det_impuestos.sicxmls02_tasa = :sicxmls02_tasa
        INTO :id_sicingr90_destino;

        IF (id_sicingr90_destino IS NOT NULL AND NOT EXISTS(
            SELECT FIRST 1 destino.id_sicingr96
            FROM sicingr96_det_impuestos destino
            WHERE destino.rela_sicingr95 = :id_sicingr95_destino
            AND destino.rela_sicingr90 = :id_sicingr90_destino
        )) THEN
        BEGIN
            INSERT INTO sicingr96_det_impuestos (rela_sicingr95, rela_sicingr90)
            VALUES (:id_sicingr95_destino, :id_sicingr90_destino);
        END
    END
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICA_97 (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SICINGR95_DESTINO BIGINT)
AS
DECLARE VARIABLE RELA_SOCSYST12 BIGINT;
DECLARE VARIABLE RELA_SOCSYST10_CDP01_ORIGEN BIGINT;
DECLARE VARIABLE RELA_SOCSYST10_CDP01_DESTINO BIGINT;
DECLARE VARIABLE SOCSYST10_CODIGO VARCHAR(50);
BEGIN
    FOR SELECT
        origen.rela_socsyst12,
        origen.rela_socsyst10_cdp01,
        cbo.socsyst10_codigo
    FROM sicingr97_det_clasificacion origen
    INNER JOIN cbo_socsyst10_cdp01 cbo ON (cbo.id_socsyst10 = origen.rela_socsyst10_cdp01)
    WHERE origen.rela_sicingr95 = :id_sicingr95_origen
    INTO :rela_socsyst12,
         :rela_socsyst10_cdp01_origen,
         :socsyst10_codigo
    DO
    BEGIN
        RELA_SOCSYST10_CDP01_DESTINO = NULL;

        SELECT cbo_socsyst10_cdp01.id_socsyst10
        FROM cbo_socsyst10_cdp01
        WHERE cbo_socsyst10_cdp01.socsyst10_codigo = :socsyst10_codigo
        INTO :rela_socsyst10_cdp01_destino;

        IF (rela_socsyst10_cdp01_destino IS NULL) THEN
            RELA_SOCSYST10_CDP01_DESTINO = :rela_socsyst10_cdp01_origen;

        IF (NOT EXISTS(
            SELECT FIRST 1 destino.id_sicingr97
            FROM sicingr97_det_clasificacion destino
            WHERE destino.rela_sicingr95 = :id_sicingr95_destino
            AND destino.rela_socsyst12 = :rela_socsyst12
            AND destino.rela_socsyst10_cdp01 = :rela_socsyst10_cdp01_destino
        )) THEN
        BEGIN
            INSERT INTO sicingr97_det_clasificacion (rela_sicingr95, rela_socsyst12, rela_socsyst10_cdp01)
            VALUES (:id_sicingr95_destino, :rela_socsyst12, :rela_socsyst10_cdp01_destino);
        END
    END
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICA_98 (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SICINGR95_DESTINO BIGINT)
AS
DECLARE VARIABLE ID_SICINGR98_DESTINO BIGINT;
DECLARE VARIABLE RELA_SOCSYST10_MLI01_ORIGEN BIGINT;
DECLARE VARIABLE RELA_SOCSYST10_LPR01_ORIGEN BIGINT;
DECLARE VARIABLE RELA_SOCSYST10_MLI01_DESTINO BIGINT;
DECLARE VARIABLE RELA_SOCSYST10_LPR01_DESTINO BIGINT;
DECLARE VARIABLE SOCSYST10_CODIGO VARCHAR(50);
DECLARE VARIABLE SICINGR98_IMPORTE DOUBLE PRECISION;
DECLARE VARIABLE SICINGR98_FECHA_APLICACION TIMESTAMP;
DECLARE VARIABLE SICINGR98_FECHA_VENCIMIENTO TIMESTAMP;
DECLARE VARIABLE SICINGR98_MARGEN DOUBLE PRECISION;
DECLARE VARIABLE SICINGR98_MODALIDAD INTEGER;
BEGIN
    FOR SELECT
        origen.rela_socsyst10_mli01,
        origen.rela_socsyst10_lpr01,
        origen.sicingr98_importe,
        origen.sicingr98_fecha_aplicacion,
        origen.sicingr98_fecha_vencimiento,
        origen.sicingr98_margen,
        origen.sicingr98_modalidad
    FROM sicingr98_det_importes origen
    WHERE origen.rela_sicingr95 = :id_sicingr95_origen
    INTO :rela_socsyst10_mli01_origen,
         :rela_socsyst10_lpr01_origen,
         :sicingr98_importe,
         :sicingr98_fecha_aplicacion,
         :sicingr98_fecha_vencimiento,
         :sicingr98_margen,
         :sicingr98_modalidad
    DO
    BEGIN
        ID_SICINGR98_DESTINO = NULL;
        RELA_SOCSYST10_MLI01_DESTINO = NULL;
        RELA_SOCSYST10_LPR01_DESTINO = NULL;
        SOCSYST10_CODIGO = NULL;

        IF (rela_socsyst10_mli01_origen IS NOT NULL) THEN
        BEGIN
            SELECT cbo_socsyst10_mli01.socsyst10_codigo
            FROM cbo_socsyst10_mli01
            WHERE cbo_socsyst10_mli01.id_socsyst10 = :rela_socsyst10_mli01_origen
            INTO :socsyst10_codigo;

            SELECT cbo_socsyst10_mli01.id_socsyst10
            FROM cbo_socsyst10_mli01
            WHERE cbo_socsyst10_mli01.socsyst10_codigo = :socsyst10_codigo
            INTO :rela_socsyst10_mli01_destino;

            IF (rela_socsyst10_mli01_destino IS NOT NULL) THEN
            BEGIN
                SELECT destino.id_sicingr98
                FROM sicingr98_det_importes destino
                WHERE destino.rela_sicingr95 = :id_sicingr95_destino
                AND destino.rela_socsyst10_mli01 = :rela_socsyst10_mli01_destino
                INTO :id_sicingr98_destino;
            END
        END
        ELSE IF (rela_socsyst10_lpr01_origen IS NOT NULL) THEN
        BEGIN
            SELECT cbo_socsyst10_lpr01.socsyst10_codigo
            FROM cbo_socsyst10_lpr01
            WHERE cbo_socsyst10_lpr01.id_socsyst10 = :rela_socsyst10_lpr01_origen
            INTO :socsyst10_codigo;

            SELECT cbo_socsyst10_lpr01.id_socsyst10
            FROM cbo_socsyst10_lpr01
            WHERE cbo_socsyst10_lpr01.socsyst10_codigo = :socsyst10_codigo
            INTO :rela_socsyst10_lpr01_destino;

            IF (rela_socsyst10_lpr01_destino IS NOT NULL) THEN
            BEGIN
                SELECT destino.id_sicingr98
                FROM sicingr98_det_importes destino
                WHERE destino.rela_sicingr95 = :id_sicingr95_destino
                AND destino.rela_socsyst10_lpr01 = :rela_socsyst10_lpr01_destino
                INTO :id_sicingr98_destino;
            END
        END

        IF (rela_socsyst10_mli01_destino IS NOT NULL OR rela_socsyst10_lpr01_destino IS NOT NULL) THEN
        BEGIN
            IF (id_sicingr98_destino IS NOT NULL) THEN
            BEGIN
                UPDATE sicingr98_det_importes SET
                    sicingr98_det_importes.sicingr98_importe = :sicingr98_importe,
                    sicingr98_det_importes.sicingr98_fecha_aplicacion = :sicingr98_fecha_aplicacion,
                    sicingr98_det_importes.sicingr98_fecha_vencimiento = :sicingr98_fecha_vencimiento,
                    sicingr98_det_importes.sicingr98_margen = :sicingr98_margen,
                    sicingr98_det_importes.sicingr98_modalidad = :sicingr98_modalidad
                WHERE sicingr98_det_importes.id_sicingr98 = :id_sicingr98_destino;
            END
            ELSE
            BEGIN
                INSERT INTO sicingr98_det_importes (
                    rela_sicingr95,
                    rela_socsyst10_mli01,
                    rela_socsyst10_lpr01,
                    sicingr98_importe,
                    sicingr98_fecha_aplicacion,
                    sicingr98_fecha_vencimiento,
                    sicingr98_margen,
                    sicingr98_modalidad)
                VALUES (
                    :id_sicingr95_destino,
                    :rela_socsyst10_mli01_destino,
                    :rela_socsyst10_lpr01_destino,
                    :sicingr98_importe,
                    :sicingr98_fecha_aplicacion,
                    :sicingr98_fecha_vencimiento,
                    :sicingr98_margen,
                    :sicingr98_modalidad);
            END
        END
    END
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICA_99 (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SICINGR95_DESTINO BIGINT,
    ID_SOCMAIN01_DESTINO BIGINT)
AS
DECLARE VARIABLE ID_SICINGR95_KIT_ORIGEN BIGINT;
DECLARE VARIABLE ID_SICINGR95_KIT_DESTINO BIGINT;
DECLARE VARIABLE ID_SICXMLS01_DESTINO BIGINT;
DECLARE VARIABLE ID_SICINGR99_DESTINO BIGINT;
DECLARE VARIABLE SICINGR95_CODIGO_KIT VARCHAR(50);
DECLARE VARIABLE SICINGR99_CANTIDAD DOUBLE PRECISION;
BEGIN
    SELECT sicxmls01_cab_parametros.id_sicxmls01
    FROM sicxmls01_cab_parametros
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    INTO :id_sicxmls01_destino;

    FOR SELECT
        origen.rela_sicingr95_kit,
        UPPER(TRIM(producto_kit.sicingr95_codigo)),
        origen.sicingr99_cantidad
    FROM sicingr99_det_kits origen
    INNER JOIN sicingr95_cab_conceptos producto_kit ON (producto_kit.id_sicingr95 = origen.rela_sicingr95_kit)
    WHERE origen.rela_sicingr95 = :id_sicingr95_origen
    INTO :id_sicingr95_kit_origen,
         :sicingr95_codigo_kit,
         :sicingr99_cantidad
    DO
    BEGIN
        ID_SICINGR95_KIT_DESTINO = NULL;

        IF (id_sicingr95_kit_origen = :id_sicingr95_origen) THEN
        BEGIN
            ID_SICINGR95_KIT_DESTINO = :id_sicingr95_destino;
        END
        ELSE
        BEGIN
            EXECUTE PROCEDURE SP_SICINGR95_REPLICACION(:id_sicingr95_kit_origen, :id_socmain01_destino)
            RETURNING_VALUES :id_sicingr95_kit_destino;
        END

        IF (id_sicingr95_kit_destino IS NULL) THEN
        BEGIN
            SELECT sicingr95_cab_conceptos.id_sicingr95
            FROM sicingr95_cab_conceptos
            WHERE sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01_destino
            AND UPPER(TRIM(sicingr95_cab_conceptos.sicingr95_codigo)) = :sicingr95_codigo_kit
            INTO :id_sicingr95_kit_destino;
        END

        IF (id_sicingr95_kit_destino IS NOT NULL) THEN
        BEGIN
            ID_SICINGR99_DESTINO = NULL;

            SELECT destino.id_sicingr99
            FROM sicingr99_det_kits destino
            WHERE destino.rela_sicingr95 = :id_sicingr95_destino
            AND destino.rela_sicingr95_kit = :id_sicingr95_kit_destino
            INTO :id_sicingr99_destino;

            IF (id_sicingr99_destino IS NOT NULL) THEN
            BEGIN
                UPDATE sicingr99_det_kits SET
                    sicingr99_det_kits.sicingr99_cantidad = :sicingr99_cantidad
                WHERE sicingr99_det_kits.id_sicingr99 = :id_sicingr99_destino;
            END
            ELSE
            BEGIN
                INSERT INTO sicingr99_det_kits (rela_sicingr95, rela_sicingr95_kit, sicingr99_cantidad)
                VALUES (:id_sicingr95_destino, :id_sicingr95_kit_destino, :sicingr99_cantidad);
            END
        END
    END
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICA_CAB (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SOCMAIN01_DESTINO BIGINT)
RETURNS (
    ID_SICINGR95_DESTINO BIGINT)
AS
declare variable SICINGR95_CODIGO_ORIGEN varchar(50);
declare variable ID_SICXMLS01_DESTINO bigint;
declare variable ID_SICCONT02_DESTINO bigint;
declare variable ID_SICXMLS04_DESTINO bigint;
declare variable ID_PYMALMA01_DESTINO bigint;
declare variable SICXMLS04_CONCEPTO_ORIGEN varchar(400);
declare variable RELA_SOCSYST10_TCT01 bigint;
declare variable CLAVEPRODSERV varchar(50);
declare variable UNIDAD varchar(50);
declare variable SICXMLS04_TIPO varchar(10);
declare variable SICXMLS04_EXCENTO integer;
declare variable SICXMLS04_DEDUCIBLE integer;
BEGIN
    SELECT
        sicxmls04_det_conceptos.rela_socsyst10_tct01,
        UPPER(TRIM(sicxmls04_det_conceptos.sicxmls04_concepto)),
        UPPER(TRIM(sicingr95_cab_conceptos.sicingr95_codigo)),
        cpo01.socsyst10_codigo,
        cum01.socsyst10_codigo,
        sicxmls04_det_conceptos.sicxmls04_tipo,
        sicxmls04_det_conceptos.sicxmls04_excento,
        sicxmls04_det_conceptos.sicxmls04_deducible
    FROM sicingr95_cab_conceptos
    INNER JOIN sicxmls04_det_conceptos ON (sicxmls04_det_conceptos.id_sicxmls04 = sicingr95_cab_conceptos.rela_sicxmls04)
    INNER JOIN siccont02_arb_planctas ON (siccont02_arb_planctas.id_siccont02 = sicxmls04_det_conceptos.rela_siccont02)
    INNER JOIN socsyst10_det_remoto cpo01 ON (cpo01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cpo01)
    INNER JOIN socsyst10_det_remoto cum01 ON (cum01.id_socsyst10 = sicingr95_cab_conceptos.rela_socsyst10_cum01)
    WHERE sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen
    INTO :rela_socsyst10_tct01,
         :sicxmls04_concepto_origen,
         :sicingr95_codigo_origen,
         :claveprodserv,
         :unidad,
         :sicxmls04_tipo,
         :sicxmls04_excento,
         :sicxmls04_deducible;

    SELECT sicxmls01_cab_parametros.id_sicxmls01
    FROM sicxmls01_cab_parametros
    WHERE sicxmls01_cab_parametros.rela_socmain01 = :id_socmain01_destino
    INTO :id_sicxmls01_destino;

    ID_SICINGR95_DESTINO = NULL;

    SELECT sicingr95_cab_conceptos.id_sicingr95
    FROM sicingr95_cab_conceptos
    WHERE sicingr95_cab_conceptos.rela_sicxmls01 = :id_sicxmls01_destino
    AND UPPER(TRIM(sicingr95_cab_conceptos.sicingr95_codigo)) = :sicingr95_codigo_origen
    INTO :id_sicingr95_destino;

    IF (id_sicxmls01_destino IS NULL) THEN
    BEGIN
        SUSPEND;
        EXIT;
    END

    IF (id_sicingr95_destino IS NULL) THEN
    BEGIN
        ID_PYMALMA01_DESTINO = NULL;

        SELECT FIRST 1 pymalma01_cab_stock.id_pymalma01
        FROM pymalma01_cab_stock
        WHERE pymalma01_cab_stock.rela_socmain01 = :id_socmain01_destino
        ORDER BY pymalma01_cab_stock.id_pymalma01
        INTO :id_pymalma01_destino;

        IF (id_pymalma01_destino IS NULL) THEN
        BEGIN
            SUSPEND;
            EXIT;
        END

        ID_SICCONT02_DESTINO = NULL;

        SELECT FIRST 1 siccont02_arb_planctas.id_siccont02
        FROM siccont02_arb_planctas
        INTO :id_siccont02_destino;

        IF (id_siccont02_destino IS NULL) THEN
        BEGIN
            SUSPEND;
            EXIT;
        END

        ID_SICXMLS04_DESTINO = NULL;

        SELECT sicxmls04_det_conceptos.id_sicxmls04
        FROM sicxmls04_det_conceptos
        WHERE sicxmls04_det_conceptos.rela_sicxmls01 = :id_sicxmls01_destino
        AND UPPER(TRIM(sicxmls04_det_conceptos.sicxmls04_concepto)) = :sicxmls04_concepto_origen
        INTO :id_sicxmls04_destino;

        IF (id_sicxmls04_destino IS NULL) THEN
        BEGIN
            EXECUTE PROCEDURE PRD_SICXMLS04_INSERT :id_sicxmls01_destino,
                                                   :rela_socsyst10_tct01,
                                                   :id_siccont02_destino,
                                                   :sicxmls04_tipo,
                                                   :sicxmls04_concepto_origen,
                                                   :sicxmls04_excento,
                                                   :sicxmls04_deducible,
                                                   :claveprodserv,
                                                   :unidad
            RETURNING_VALUES :id_sicxmls04_destino;
        END

        INSERT INTO sicingr95_cab_conceptos (
            rela_sicxmls01,
            rela_sicxmls04,
            rela_socsyst10_cum01,
            rela_socsyst10_cpo01,
            rela_socsyst10_ctm01,
            rela_pymalma01,
            sicingr95_codigo,
            sicingr95_descripcion,
            sicingr95_predial,
            sicingr95_fraccion,
            sicingr95_importe,
            sicingr95_notas,
            sicingr95_inactivo,
            sicingr95_tipo)
        SELECT
            :id_sicxmls01_destino,
            :id_sicxmls04_destino,
            sicingr95_cab_conceptos.rela_socsyst10_cum01,
            sicingr95_cab_conceptos.rela_socsyst10_cpo01,
            sicingr95_cab_conceptos.rela_socsyst10_ctm01,
            :id_pymalma01_destino,
            sicingr95_cab_conceptos.sicingr95_codigo,
            sicingr95_cab_conceptos.sicingr95_descripcion,
            sicingr95_cab_conceptos.sicingr95_predial,
            sicingr95_cab_conceptos.sicingr95_fraccion,
            sicingr95_cab_conceptos.sicingr95_importe,
            sicingr95_cab_conceptos.sicingr95_notas,
            sicingr95_cab_conceptos.sicingr95_inactivo,
            sicingr95_cab_conceptos.sicingr95_tipo
        FROM sicingr95_cab_conceptos
        WHERE sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_origen;

        SELECT socsyst91_tbl_ultids.socsyst91_ultid
        FROM socsyst91_tbl_ultids
        WHERE socsyst91_tbl_ultids.socsyst91_usuario = CURRENT_USER
        AND socsyst91_tbl_ultids.socsyst91_ulttbl = 'SICINGR95'
        INTO :id_sicingr95_destino;
    END
    ELSE
    BEGIN
        UPDATE sicingr95_cab_conceptos SET
            sicingr95_cab_conceptos.sicingr95_descripcion = (SELECT origen.sicingr95_descripcion FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen),
            sicingr95_cab_conceptos.sicingr95_predial = (SELECT origen.sicingr95_predial FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen),
            sicingr95_cab_conceptos.sicingr95_fraccion = (SELECT origen.sicingr95_fraccion FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen),
            sicingr95_cab_conceptos.sicingr95_importe = (SELECT origen.sicingr95_importe FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen),
            sicingr95_cab_conceptos.sicingr95_notas = (SELECT origen.sicingr95_notas FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen),
            sicingr95_cab_conceptos.sicingr95_inactivo = (SELECT origen.sicingr95_inactivo FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen),
            sicingr95_cab_conceptos.sicingr95_tipo = (SELECT origen.sicingr95_tipo FROM sicingr95_cab_conceptos origen WHERE origen.id_sicingr95 = :id_sicingr95_origen)
        WHERE sicingr95_cab_conceptos.id_sicingr95 = :id_sicingr95_destino;
    END

    SUSPEND;
END^


CREATE OR ALTER PROCEDURE SP_SICINGR95_REPLICACION (
    ID_SICINGR95_ORIGEN BIGINT,
    ID_SOCMAIN01_DESTINO BIGINT)
RETURNS (
    ID_SICINGR95_DESTINO BIGINT)
AS
declare variable CTX_KEY varchar(80);
declare variable CTX_VALUE varchar(10);
declare variable OK integer;
BEGIN
    CTX_KEY = 'SICINGR95_REPL_' || CAST(:id_sicingr95_origen AS VARCHAR(20)) || '_' || CAST(:id_socmain01_destino AS VARCHAR(20));
    CTX_VALUE = RDB$GET_CONTEXT('USER_TRANSACTION', :ctx_key);

    IF (ctx_value = '1') THEN
    BEGIN
        EXECUTE PROCEDURE SP_SICINGR95_REPLICA_CAB(:id_sicingr95_origen, :id_socmain01_destino)
        RETURNING_VALUES :id_sicingr95_destino;
        SUSPEND;
        EXIT;
    END

    OK = RDB$SET_CONTEXT('USER_TRANSACTION', :ctx_key, '1');

    EXECUTE PROCEDURE SP_SICINGR95_REPLICA_CAB(:id_sicingr95_origen, :id_socmain01_destino)
    RETURNING_VALUES :id_sicingr95_destino;

    IF (id_sicingr95_destino IS NOT NULL) THEN
    BEGIN
        EXECUTE PROCEDURE SP_SICINGR95_REPLICA_91(:id_sicingr95_origen, :id_sicingr95_destino);                         -- imagenes
        EXECUTE PROCEDURE SP_SICINGR95_REPLICA_96(:id_sicingr95_origen, :id_sicingr95_destino, :id_socmain01_destino);  -- impuestos
        EXECUTE PROCEDURE SP_SICINGR95_REPLICA_97(:id_sicingr95_origen, :id_sicingr95_destino);                         -- clasificacion
        EXECUTE PROCEDURE SP_SICINGR95_REPLICA_98(:id_sicingr95_origen, :id_sicingr95_destino);                         -- importes / precios
        EXECUTE PROCEDURE SP_SICINGR95_REPLICA_99(:id_sicingr95_origen, :id_sicingr95_destino, :id_socmain01_destino);  -- kits al final
    END

    OK = RDB$SET_CONTEXT('USER_TRANSACTION', :ctx_key, NULL);

    SUSPEND;
END^


