CREATE OR ALTER PROCEDURE ZZZ_IMPUESTOS_WEB
AS
declare variable RELA_SICINGR71 bigint;
declare variable ID_SICINGR72 bigint;
declare variable SICINGR72_IMPUESTO varchar(50);
declare variable SICINGR72_IMPORTE double precision;
declare variable SICINGR72_TASAOCUOTA double precision;
declare variable RESULTADO varchar(400);
declare variable ID_SOCSYST10 bigint;
declare variable ID_SICINGR75 bigint = 0;
begin
    update SOCSYST01_CAB_FUNCIONES set SOCSYST01_CAB_FUNCIONES.socsyst01_activo = 0
    where SOCSYST01_CAB_FUNCIONES.socsyst01_codigo = 'SOCSYST09';
    
    delete from sicingr75_det_impuestos_web;

    for select
    sicingr72_det_impuestos.rela_sicingr71,
    sicingr72_det_impuestos.id_sicingr72,
    sicingr72_det_impuestos.sicingr72_impuesto,
    sicingr72_det_impuestos.sicingr72_importe,
    sicingr72_det_impuestos.sicingr72_tasaocuota
    from sicingr72_det_impuestos
    WHERE extract(year FROM sicingr72_det_impuestos.sicingr72_fapl) >= 2024
    and extract(year FROM sicingr72_det_impuestos.sicingr72_fapl) <= 2099
    into :rela_sicingr71,
         :id_sicingr72,
         :sicingr72_impuesto,
         :sicingr72_importe,
         :sicingr72_tasaocuota
    do
    begin
        resultado = sicingr72_impuesto || '-' || CAST( cast(sicingr72_tasaocuota as integer) as varchar(6));
        id_socsyst10 = null;

        if (resultado = 'IVA-0') then
            resultado = 'IVA-00';

        select cbo_socsyst10_sat10.id_socsyst10
        from cbo_socsyst10_sat10
        where cbo_socsyst10_sat10.socsyst10_codigo = :resultado
        into :id_socsyst10;

        if (id_socsyst10 is not null) then
        begin
            id_sicingr75 = null;

            select distinct sicingr75_det_impuestos_web.id_sicingr75
            from sicingr75_det_impuestos_web
            where sicingr75_det_impuestos_web.rela_sicingr72 = :id_sicingr72
            into :id_sicingr75;

            if (id_sicingr75 is null) then
            begin
                insert into sicingr75_det_impuestos_web(sicingr75_det_impuestos_web.rela_sicingr71,
                                                        sicingr75_det_impuestos_web.rela_sicingr72,
                                                        sicingr75_det_impuestos_web.rela_socsyst10_sat10,
                                                        sicingr75_det_impuestos_web.sicingr75_porcentaje,
                                                        sicingr75_det_impuestos_web.sicingr75_total)
                values(:rela_sicingr71,
                       :id_sicingr72,
                       :id_socsyst10,
                       :sicingr72_tasaocuota,
                       :sicingr72_importe);
            end
        end
    end

    update SOCSYST01_CAB_FUNCIONES set SOCSYST01_CAB_FUNCIONES.socsyst01_activo = 1
    where SOCSYST01_CAB_FUNCIONES.socsyst01_codigo = 'SOCSYST09';

end^


CREATE OR ALTER PROCEDURE ZZZ_SICINGR01_WEB
AS
declare variable RELA_SOCMAIN80 bigint;
declare variable ID_SICINGR01 bigint;
declare variable ENTIDAD varchar(1000);
declare variable RFC varchar(20);
declare variable RELA_SOCSYST10_SAT01 bigint;
declare variable UUID_SMX_KEY varchar(50);
declare variable UUID_SMX_CER varchar(50);
declare variable UUID_EXISTS integer;
declare variable RELA_SOCUSUA30 bigint;
declare variable RELA_SOCMAIN80X bigint;
declare variable ID_SOCMAIN01 bigint;
declare variable MAIL varchar(400);
begin
    select cbo_socsyst10_sat01.id_socsyst10
    from cbo_socsyst10_sat01
    where cbo_socsyst10_sat01.socsyst10_codigo = '601'
    into :rela_socsyst10_sat01;

    for select
    socmain01_cab_empresas.rela_socusua30,
    socmain01_cab_empresas.id_socmain01,
    upper(socmain01_cab_empresas.socmain01_uuid_smx_key),
    upper(socmain01_cab_empresas.socmain01_uuid_smx_cer)
    from socmain01_cab_empresas
    where trim(socmain01_cab_empresas.socmain01_uuid_smx_key) != ''
    into :rela_socusua30,
         :id_socmain01,
         :uuid_smx_key,
         :uuid_smx_cer
    do
    begin
        select
        socusua36_det_domicilios.rela_socmain80
        from socsyst10_det_entradas
        inner join socusua36_det_domicilios on (socsyst10_det_entradas.id_socsyst10 = socusua36_det_domicilios.rela_socsyst10_tdd01)
        WHERE socusua36_det_domicilios.rela_socusua30 = :rela_socusua30
        AND socsyst10_det_entradas.socsyst10_codigo = 'EMPRESA'
        INTO :rela_socmain80X;

        if (rela_socmain80X IS NOT NULL) then
        UPDATE socmain01_cab_empresas SET rela_socmain80 = :rela_socmain80X,
                                          RELA_SOCSYST10_SAT01 = CASE
                                                                    WHEN RELA_SOCSYST10_SAT01 IS NULL THEN :rela_socsyst10_sat01
                                                                    ELSE RELA_SOCSYST10_SAT01
                                                                  END
        WHERE id_socmain01 = :id_socmain01;

        /* ============================================================================================================================= */

        select count(0)
        from sysjson02_tbl_files
        where sysjson02_tbl_files.sysjson02_uuid = :uuid_smx_key
        into :uuid_exists;

        if (uuid_exists = 0) then
        begin
            insert into sysjson02_tbl_files(sysjson02_tbl_files.sysjson02_alias,
                                            sysjson02_tbl_files.sysjson02_uuid,
                                            sysjson02_tbl_files.sysjson02_usuario,
                                            sysjson02_tbl_files.sysjson02_tipo,
                                            sysjson02_tbl_files.sysjson02_name)
            values('SOCMAIN01',
                   :uuid_smx_key,
                   'ADMIN',
                   'KEY',
                   'SAT.KEY');
        end   

        select count(0)
        from sysjson02_tbl_files
        where sysjson02_tbl_files.sysjson02_uuid = :uuid_smx_cer
        into :uuid_exists;

        if (uuid_exists = 0) then
        begin
            insert into sysjson02_tbl_files(sysjson02_tbl_files.sysjson02_alias,
                                            sysjson02_tbl_files.sysjson02_uuid,
                                            sysjson02_tbl_files.sysjson02_usuario,
                                            sysjson02_tbl_files.sysjson02_tipo,
                                            sysjson02_tbl_files.sysjson02_name)
            values('SOCMAIN01',
                   :uuid_smx_cer,
                   'ADMIN',
                   'CER',
                   'SAT.CER');
        end
    end

    /* ============================================================================================================================= */

    for select
    GRD_SICINGR01.rela_socusua30,
    GRD_SICINGR01.rela_socsyst10_sat01,
    GRD_SICINGR01.rela_socmain80,
    GRD_SICINGR01.id_sicingr01,
    GRD_SICINGR01.entidad,
    GRD_SICINGR01.rfc
    from GRD_SICINGR01
    into :rela_socusua30,
         :rela_socsyst10_sat01,
         :rela_socmain80,
         :id_sicingr01,
         :entidad,
         :rfc
    do
    begin
        if (rela_socmain80 IS NULL) then
            select first 1 cbo_socmain80.id_socmain80
            from cbo_socmain80(72777)
            into :rela_socmain80;

        if (rela_socsyst10_sat01 IS NULL) then
            select cbo_socsyst10_sat01.id_socsyst10
            from cbo_socsyst10_sat01
            where cbo_socsyst10_sat01.socsyst10_codigo = '601'
            into :rela_socsyst10_sat01;

        mail = null;

        select first 1 socusua35_det_internet.socusua35_internet
        from socusua35_det_internet
        inner join cbo_socsyst10_tdi01 on (cbo_socsyst10_tdi01.id_socsyst10 = socusua35_det_internet.rela_socsyst10_tdi01)
        where socusua35_det_internet.rela_socusua30 = :rela_socusua30
        and cbo_socsyst10_tdi01.socsyst10_codigo = 'CORREO'
        order by socusua35_det_internet.id_socusua35 desc
        into :mail;

        update sicingr01_cab_clientes
        set sicingr01_cab_clientes.rela_socmain80 = :rela_socmain80,
            sicingr01_cab_clientes.rela_socsyst10_sat01 = :rela_socsyst10_sat01,
            sicingr01_cab_clientes.sicingr01_entidad = :entidad,
            sicingr01_cab_clientes.sicingr01_rfc = :rfc,
            sicingr01_cab_clientes.sicingr01_mail = :mail
        where sicingr01_cab_clientes.id_sicingr01 = :id_sicingr01;
    end
end^



